${bundledXaml}[[System.IO.Path]::GetFullPath("${tebunkoRoot}\xaml\dialog_about.xaml")] = @'
<!-- 「バージョン情報」ダイアログ（ナビ下の「バージョン情報」）。gui.ps1（ui/about_dialog.ps1）が読み込む。
     版・コミットは中身を見るだけの表示で、確認や入力は無い（docs/design/gui/common.md「表示・アクセシビリティ」の例外）。
     色・文字・コントロールの形は scripts/shared/xaml/theme.xaml にまとめてある。 -->
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="バージョン情報" Width="460" SizeToContent="Height" ResizeMode="NoResize"
        WindowStartupLocation="CenterOwner" ShowInTaskbar="False"
        FontFamily="{DynamicResource Font.Body}" FontSize="13"
        TextOptions.TextFormattingMode="Display" TextOptions.TextRenderingMode="ClearType"
        Background="{DynamicResource Bg.Surface}" UseLayoutRounding="True" SnapsToDevicePixels="True">
  <Window.Resources>
    <ResourceDictionary>
      <ResourceDictionary.MergedDictionaries>
        <ResourceDictionary Source="../../shared/xaml/theme.xaml" />
      </ResourceDictionary.MergedDictionaries>
    </ResourceDictionary>
  </Window.Resources>

  <DockPanel Margin="28,24,28,20">
    <StackPanel DockPanel.Dock="Bottom" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,18,0,0">
      <Button x:Name="CloseButton" Content="OK" Style="{StaticResource Primary}" IsCancel="True" IsDefault="True" MinWidth="80" Height="32" />
    </StackPanel>

    <StackPanel>
      <Image x:Name="AppIcon" Width="64" Height="64" Stretch="Uniform" HorizontalAlignment="Center" />
      <TextBlock Text="tebunko" FontSize="20" FontWeight="SemiBold" Foreground="{StaticResource Ink.Strong}"
                 HorizontalAlignment="Center" Margin="0,12,0,0" />
      <TextBlock Style="{StaticResource Body}" Text="Office ファイル内テキスト検索ツール" Foreground="{StaticResource Ink.Muted}"
                 HorizontalAlignment="Center" Margin="0,8,0,0" />
      <StackPanel Orientation="Horizontal" HorizontalAlignment="Center" Margin="0,8,0,0">
        <TextBlock x:Name="VersionText" Style="{StaticResource Meta}" />
        <TextBlock x:Name="CommitText" Style="{StaticResource Meta}" Margin="12,0,0,0" />
      </StackPanel>
      <Separator Margin="0,16,0,16" Background="{StaticResource Border.Soft}" />
      <Border Background="{StaticResource Bg.Subtle}" BorderBrush="{StaticResource Border.Soft}" BorderThickness="1"
              CornerRadius="{StaticResource Radius.Control}" Padding="14,10">
        <Grid>
          <Grid.ColumnDefinitions>
            <ColumnDefinition Width="Auto" />
            <ColumnDefinition Width="*" />
          </Grid.ColumnDefinitions>
          <Grid.RowDefinitions>
            <RowDefinition Height="Auto" />
            <RowDefinition Height="Auto" />
          </Grid.RowDefinitions>
          <TextBlock Grid.Row="0" Grid.Column="0" Style="{StaticResource Meta}" FontWeight="SemiBold" Text="動作環境：" Margin="0,0,12,0" />
          <TextBlock Grid.Row="0" Grid.Column="1" Style="{StaticResource Meta}" Foreground="{StaticResource Ink.Body}" Text="Windows 10 / 11" />
          <TextBlock Grid.Row="1" Grid.Column="0" Style="{StaticResource Meta}" FontWeight="SemiBold" Text="ランタイム：" Margin="0,6,12,0" />
          <TextBlock Grid.Row="1" Grid.Column="1" Style="{StaticResource Meta}" Foreground="{StaticResource Ink.Body}" Text="PowerShell 5.1 + WPF" Margin="0,6,0,0" />
        </Grid>
      </Border>
      <StackPanel Orientation="Horizontal" HorizontalAlignment="Center" Margin="0,12,0,0">
        <Button x:Name="GitHubLink" Style="{StaticResource Link}" AutomationProperties.AutomationId="GitHubLink" AutomationProperties.Name="GitHub" />
        <Button x:Name="ReleasesLink" Style="{StaticResource Link}" AutomationProperties.AutomationId="ReleasesLink" AutomationProperties.Name="リリース" Margin="16,0,0,0" />
      </StackPanel>
      <TextBlock x:Name="LicenseText" Style="{StaticResource Micro}" HorizontalAlignment="Center" TextAlignment="Center" Margin="0,12,0,0" />
    </StackPanel>
  </DockPanel>
</Window>
@@'@
${bundledXaml}[[System.IO.Path]::GetFullPath("${tebunkoRoot}\xaml\dialog_export.xaml")] = @'
<!-- インデックスのエクスポートのダイアログ（［インデックス管理］タブの行のメニューの［エクスポート…］）。index_archive.ps1 が読み込む。
     色・文字・コントロールの形は scripts/shared/xaml/theme.xaml にまとめてある。 -->
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="インデックスのエクスポート" Width="620" Height="400" MinWidth="520" MinHeight="380"
        WindowStartupLocation="CenterOwner" ShowInTaskbar="False" ResizeMode="CanResize"
        FontFamily="{DynamicResource Font.Body}" FontSize="13"
        TextOptions.TextFormattingMode="Display" TextOptions.TextRenderingMode="ClearType"
        Background="{DynamicResource Bg.Surface}" UseLayoutRounding="True" SnapsToDevicePixels="True">
  <Window.Resources>
    <ResourceDictionary>
      <ResourceDictionary.MergedDictionaries>
        <ResourceDictionary Source="../../shared/xaml/theme.xaml" />
      </ResourceDictionary.MergedDictionaries>
    </ResourceDictionary>
  </Window.Resources>

  <DockPanel Margin="18,16,18,16">
    <StackPanel DockPanel.Dock="Bottom" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,14,0,0">
      <Button x:Name="CancelButton" Style="{StaticResource DialogButton}" Content="キャンセル" IsCancel="True" MinWidth="104" Height="32" Margin="0,0,8,0" />
      <Button x:Name="ExportButton" Style="{StaticResource Primary}" Content="エクスポート" IsDefault="True" MinWidth="104" Height="32" />
    </StackPanel>

    <!-- 取り扱いの注意（ボタンの上。橙の枠） -->
    <Border DockPanel.Dock="Bottom" Background="{StaticResource Warn.Soft}" BorderBrush="{StaticResource Warn}" BorderThickness="1" CornerRadius="6" Padding="12,10" Margin="0,14,0,0">
      <TextBlock x:Name="CautionText" Foreground="{StaticResource Banner.Warn.Text}" TextWrapping="Wrap" />
    </Border>

    <StackPanel>
      <!-- 見出しの代わりに、書き出す対象を枠で示す（名前・ファイル数） -->
      <Border Background="{StaticResource Bg.Summary}" BorderBrush="{StaticResource Border.Soft}" BorderThickness="1" CornerRadius="6" Padding="12,10">
        <StackPanel>
          <TextBlock x:Name="ExportTitleText" Style="{StaticResource Label.Strong}" TextTrimming="CharacterEllipsis" />
          <TextBlock x:Name="ExportSizeText" Style="{StaticResource Meta}" Margin="0,2,0,0" />
        </StackPanel>
      </Border>
      <TextBlock x:Name="IntroText" Style="{StaticResource Meta}" Margin="0,8,0,6" TextWrapping="Wrap" />

      <TextBlock Style="{StaticResource Label}" HorizontalAlignment="Left" Margin="0,12,0,6" Text="書き出し先のフォルダ" />
      <DockPanel>
        <Button x:Name="BrowseButton" DockPanel.Dock="Right" Content="参照…" MinWidth="80" Margin="8,0,0,0" />
        <TextBox x:Name="ExportPathBox" AllowDrop="True" />
      </DockPanel>
      <TextBlock x:Name="ExportFileText" Style="{StaticResource Meta}" Margin="2,6,0,0" TextWrapping="Wrap" />
      <TextBlock Style="{StaticResource Micro}" Margin="2,4,0,0"
                 Text="パスの入力・貼り付け・フォルダのドラッグ＆ドロップで指定できます。zip の名前は自動で付きます。" />

      <TextBlock x:Name="ErrorText" Style="{StaticResource ErrorText}" Margin="0,10,0,0" Visibility="Collapsed" />
    </StackPanel>
  </DockPanel>
</Window>
@@'@
${bundledXaml}[[System.IO.Path]::GetFullPath("${tebunkoRoot}\xaml\dialog_import.xaml")] = @'
<!-- インデックスのインポートのダイアログ（［インデックス管理］タブの［インポート…］）。gui_main.ps1 の側（index_archive.ps1）が読み込む。
     色・文字・コントロールの形は scripts/shared/xaml/theme.xaml にまとめてある。 -->
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="インデックスのインポート" Width="620" Height="520" MinWidth="520" MinHeight="480"
        WindowStartupLocation="CenterOwner" ShowInTaskbar="False" ResizeMode="CanResize"
        FontFamily="{DynamicResource Font.Body}" FontSize="13"
        TextOptions.TextFormattingMode="Display" TextOptions.TextRenderingMode="ClearType"
        Background="{DynamicResource Bg.Surface}" UseLayoutRounding="True" SnapsToDevicePixels="True">
  <Window.Resources>
    <ResourceDictionary>
      <ResourceDictionary.MergedDictionaries>
        <ResourceDictionary Source="../../shared/xaml/theme.xaml" />
      </ResourceDictionary.MergedDictionaries>
    </ResourceDictionary>
  </Window.Resources>

  <DockPanel Margin="18,16,18,16">
    <StackPanel DockPanel.Dock="Bottom" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,14,0,0">
      <Button x:Name="CancelButton" Style="{StaticResource DialogButton}" Content="キャンセル" IsCancel="True" MinWidth="104" Height="32" Margin="0,0,8,0" />
      <Button x:Name="ImportButton" Style="{StaticResource Primary}" Content="インポート" IsDefault="True" MinWidth="104" Height="32" />
    </StackPanel>

    <StackPanel>
      <!-- 見出しの代わりに、zip の中身を枠で示す（名前・エクスポートした日時・ファイル数と大きさと版） -->
      <Border Background="{StaticResource Bg.Summary}" BorderBrush="{StaticResource Border.Soft}" BorderThickness="1" CornerRadius="6" Padding="12,10">
        <StackPanel>
          <TextBlock x:Name="ImportTitleText" Style="{StaticResource Label.Strong}" TextTrimming="CharacterEllipsis" />
          <TextBlock x:Name="ImportExportedText" Style="{StaticResource Meta}" Margin="0,2,0,0" />
          <TextBlock x:Name="ImportSizeText" Style="{StaticResource Meta}" Margin="0,2,0,0" />
        </StackPanel>
      </Border>
      <!-- 同じ名前のインデックスが一覧にあるとき（getImportCollisionChoiceView）の選び方。名前の欄が一覧に無い名前になったら隠す -->
      <StackPanel x:Name="CollisionPanel" Margin="0,10,0,0" Visibility="Collapsed">
        <TextBlock x:Name="CollisionHeading" Style="{StaticResource WarnText}" TextWrapping="Wrap" />
        <StackPanel Orientation="Horizontal" Margin="0,6,0,0">
          <RadioButton x:Name="RenameRadio" GroupName="Collision" Margin="0,0,20,0" IsChecked="True" />
          <RadioButton x:Name="OverwriteRadio" GroupName="Collision" />
        </StackPanel>
        <TextBlock x:Name="CollisionNotice" Style="{StaticResource WarnText}" Margin="0,6,0,0" TextWrapping="Wrap" Visibility="Collapsed" />
      </StackPanel>
      <TextBlock x:Name="IntroText" Style="{StaticResource Meta}" Margin="0,8,0,6" TextWrapping="Wrap" />

      <TextBlock Style="{StaticResource Label}" HorizontalAlignment="Left" Margin="0,12,0,6"
                 Text="元のフォルダ（Office ファイルのある場所）" />
      <DockPanel>
        <Button x:Name="BrowseButton" DockPanel.Dock="Right" Content="参照…" MinWidth="80" Margin="8,0,0,0" />
        <TextBox x:Name="FolderBox" AllowDrop="True" />
      </DockPanel>
      <TextBlock x:Name="SourceCheckText" Style="{StaticResource Meta}" Margin="2,6,0,0" TextWrapping="Wrap" Visibility="Collapsed" />
      <TextBlock x:Name="FolderHint" Style="{StaticResource Micro}" Margin="2,4,0,0"
                 Text="パスの入力・貼り付け・フォルダのドラッグ＆ドロップで指定できます。" />

      <TextBlock Style="{StaticResource Label}" HorizontalAlignment="Left" Margin="0,14,0,6" Text="名前" />
      <TextBox x:Name="NameBox" />
      <TextBlock x:Name="NameHint" Style="{StaticResource Micro}" Margin="2,6,0,0"
                 Text="検索対象の一覧と検索結果に、この名前が出ます。\ / : * ? &quot; &lt; &gt; | は使えません。" />

      <TextBlock x:Name="ErrorText" Style="{StaticResource ErrorText}" Margin="0,10,0,0" Visibility="Collapsed" />
    </StackPanel>
  </DockPanel>
</Window>
@@'@
${bundledXaml}[[System.IO.Path]::GetFullPath("${tebunkoRoot}\xaml\dialog_indexing_confirm.xaml")] = @'
<!-- インデックス更新の確認ダイアログ（［すべて更新］を押した後、更新の対象を数え終えたときに開く）。gui.ps1 が読み込む。
     色・文字・コントロールの形は scripts/shared/xaml/theme.xaml にまとめてある。 -->
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="インデックス更新の確認" Width="720" Height="560" MinWidth="620" MinHeight="460"
        WindowStartupLocation="CenterOwner" ShowInTaskbar="False" ResizeMode="CanResize"
        FontFamily="{DynamicResource Font.Body}" FontSize="13"
        TextOptions.TextFormattingMode="Display" TextOptions.TextRenderingMode="ClearType"
        Background="{DynamicResource Bg.Surface}" UseLayoutRounding="True" SnapsToDevicePixels="True">
  <Window.Resources>
    <ResourceDictionary>
      <ResourceDictionary.MergedDictionaries>
        <ResourceDictionary Source="../../shared/xaml/theme.xaml" />
      </ResourceDictionary.MergedDictionaries>
    </ResourceDictionary>
  </Window.Resources>

  <DockPanel Margin="18,16,18,16">
    <StackPanel DockPanel.Dock="Bottom" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,14,0,0">
      <Button x:Name="CancelButton" Style="{StaticResource DialogButton}" Content="キャンセル" IsCancel="True" Height="34" Margin="0,0,8,0" />
      <Button x:Name="StartButton" Style="{StaticResource Primary}" Content="更新を開始" IsDefault="True" MinWidth="110" Height="34" />
    </StackPanel>

    <StackPanel DockPanel.Dock="Bottom" Margin="0,12,0,0">
      <CheckBox x:Name="RetryCheck" Visibility="Collapsed" Margin="0,0,0,10" />
      <!-- クラウドにだけあるファイル（OneDrive・SharePoint のオンデマンド）が 1 件でもあるときだけ出す -->
      <TextBlock x:Name="CloudWarnText" Foreground="{StaticResource Warn.Strong}" TextWrapping="Wrap" Visibility="Collapsed" Margin="0,0,0,6" />
      <CheckBox x:Name="CloudCheck" Visibility="Collapsed" Margin="0,0,0,4" />
      <CheckBox x:Name="CloudRememberCheck" Visibility="Collapsed" Margin="20,0,0,10" />
      <!-- 注意の枠（取り込むものが無いときの案内）。文字は NoteText に入れ、枠は NoteText の表示に合わせて出す -->
      <Border Margin="0,8,0,0" Padding="12,8" CornerRadius="6" Background="{StaticResource Warn.Note}"
              BorderBrush="{StaticResource Warn.Line}" BorderThickness="1"
              Visibility="{Binding Visibility, ElementName=NoteText}">
        <TextBlock x:Name="NoteText" Foreground="{StaticResource Warn.Strong}" TextWrapping="Wrap" Visibility="Collapsed" />
      </Border>
    </StackPanel>

    <StackPanel DockPanel.Dock="Top" Margin="0,0,0,12">
      <!-- 見出し。左のアイコンは、確認のメッセージ（dialog_confirm.xaml）と同じ「?」 -->
      <DockPanel>
        <Path DockPanel.Dock="Left" Data="{StaticResource Icon.CircleQuestionMark}" Width="20" Height="20" Stretch="Uniform" Margin="0,0,10,0"
              VerticalAlignment="Center" Stroke="{StaticResource Accent}" StrokeThickness="1.8"
              StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" />
        <TextBlock Style="{StaticResource DialogHeading}" Text="インデックス更新の確認" VerticalAlignment="Center" />
      </DockPanel>
      <!-- 削除予定のインデックスがあるときだけ出す一文（getIndexingConfirmIntro） -->
      <TextBlock x:Name="IntroText" Style="{StaticResource Meta}" Margin="0,6,0,0" TextWrapping="Wrap" Visibility="Collapsed" />
    </StackPanel>

    <!-- 表と、いちばん下の合計の行（更新するフォルダ数・ファイル数。薄い地）を 1 つの枠に入れる -->
    <Border BorderBrush="{StaticResource Border.Soft}" BorderThickness="1" CornerRadius="6" ClipToBounds="True">
      <DockPanel>
      <Border DockPanel.Dock="Bottom" Background="{StaticResource Bg.Summary}" BorderBrush="{StaticResource Border.Soft}" BorderThickness="0,1,0,0" Padding="12,8">
        <TextBlock x:Name="TotalText" Style="{StaticResource Label.Strong}" TextWrapping="Wrap" />
      </Border>
      <DataGrid x:Name="PlanGrid" MinHeight="120" BorderThickness="0" CanUserAddRows="False" SelectionMode="Single" CanUserSortColumns="False">
        <DataGrid.Columns>
          <DataGridTemplateColumn Header="フォルダ名" Width="*">
            <DataGridTemplateColumn.CellTemplate>
              <DataTemplate>
                <TextBlock Style="{StaticResource Cell.Key}" Text="{Binding Name}" ToolTip="{Binding Path}" />
              </DataTemplate>
            </DataGridTemplateColumn.CellTemplate>
          </DataGridTemplateColumn>
          <DataGridTemplateColumn Header="対象ファイル数" Width="120">
            <DataGridTemplateColumn.CellTemplate>
              <DataTemplate>
                <TextBlock Style="{StaticResource Cell.Number}" HorizontalAlignment="Stretch" Text="{Binding TotalText}" />
              </DataTemplate>
            </DataGridTemplateColumn.CellTemplate>
          </DataGridTemplateColumn>
          <DataGridTemplateColumn Header="ステータス" Width="130">
            <DataGridTemplateColumn.CellTemplate>
              <DataTemplate>
                <Border Style="{StaticResource LevelBadge}" Tag="{Binding Level}" ToolTip="{Binding DetailText}">
                  <TextBlock Style="{StaticResource LevelBadgeText}" Tag="{Binding Level}" Text="{Binding StatusText}" />
                </Border>
              </DataTemplate>
            </DataGridTemplateColumn.CellTemplate>
          </DataGridTemplateColumn>
        </DataGrid.Columns>
      </DataGrid>
      </DockPanel>
    </Border>
  </DockPanel>
</Window>
@@'@
${bundledXaml}[[System.IO.Path]::GetFullPath("${tebunkoRoot}\xaml\dialog_leftover.xaml")] = @'
<!-- 前回残った Office の終了の確認（起動時）。ui/leftover_dialog.ps1 が読み込む。
     形は確認ダイアログ（shared/xaml/dialog_confirm.xaml）と同じで、見出し・結果の欄・補足・ボタンに、詳細の一覧（開け閉めできる）を足したもの。
     色・文字・コントロールの形は scripts/shared/xaml/theme.xaml にまとめてある。 -->
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="Office の終了" Width="520" SizeToContent="Height" MaxHeight="620"
        WindowStartupLocation="CenterOwner" ShowInTaskbar="False" ResizeMode="NoResize"
        FontFamily="{DynamicResource Font.Body}" FontSize="13"
        TextOptions.TextFormattingMode="Display" TextOptions.TextRenderingMode="ClearType"
        Background="{DynamicResource Bg.Surface}" UseLayoutRounding="True" SnapsToDevicePixels="True">
  <Window.Resources>
    <ResourceDictionary>
      <ResourceDictionary.MergedDictionaries>
        <ResourceDictionary Source="../../shared/xaml/theme.xaml" />
      </ResourceDictionary.MergedDictionaries>
      <Style TargetType="Button" BasedOn="{StaticResource Button.Base}">
        <Setter Property="MinWidth" Value="80" />
        <Setter Property="Height" Value="32" />
        <Setter Property="Margin" Value="8,0,0,0" />
      </Style>
    </ResourceDictionary>
  </Window.Resources>

  <DockPanel Margin="20,16,20,20">
    <StackPanel x:Name="ButtonPanel" DockPanel.Dock="Bottom" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,20,0,0">
      <Button x:Name="LeftoverCancelButton" IsCancel="True" IsDefault="True" />
      <Button x:Name="LeftoverStopButton" Style="{StaticResource Primary}" />
    </StackPanel>

    <!-- ボタンの選び方の補足は、ボタンの真上に置く（本文の下に離して置くと、ボタンを選ぶときに目に入らない） -->
    <TextBlock x:Name="HintText" DockPanel.Dock="Bottom" Style="{StaticResource Meta}" TextWrapping="Wrap" Margin="0,12,0,0" />

    <StackPanel>
      <TextBlock x:Name="HeadingText" Style="{StaticResource Body}" TextWrapping="Wrap" />

      <!-- 結果：終了すると何が閉じて何が残るか -->
      <Border Margin="0,12,0,0" Background="{StaticResource Bg.Subtle}" BorderBrush="{StaticResource Border.Soft}" BorderThickness="1"
              CornerRadius="{StaticResource Radius.Card}" Padding="14,10">
        <ItemsControl x:Name="FactsList">
          <ItemsControl.ItemTemplate>
            <DataTemplate>
              <DockPanel Margin="0,5">
                <!-- 印（Mark）：Kept 残る・Gone 消える・Next 続けて起きること。dialog_confirm.xaml と同じ Lucide の形で出す（知らない値は注意の形） -->
                <Path x:Name="MarkIcon" DockPanel.Dock="Left" Width="14" Height="14" Margin="0,3,8,0" VerticalAlignment="Top" Stretch="Uniform"
                      Data="{StaticResource Icon.TriangleAlert}" Stroke="{Binding MarkBrush}" StrokeThickness="2"
                      StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" />
                <StackPanel>
                  <TextBlock Text="{Binding Title}" Foreground="{StaticResource Ink.Strong}" TextWrapping="Wrap" />
                  <TextBlock Style="{StaticResource Meta}" Text="{Binding Detail}" Margin="0,3,0,0" />
                </StackPanel>
              </DockPanel>
              <DataTemplate.Triggers>
                <DataTrigger Binding="{Binding Mark}" Value="Kept">
                  <Setter TargetName="MarkIcon" Property="Data" Value="{StaticResource Icon.Check}" />
                </DataTrigger>
                <DataTrigger Binding="{Binding Mark}" Value="Gone">
                  <Setter TargetName="MarkIcon" Property="Data" Value="{StaticResource Icon.Close}" />
                </DataTrigger>
                <DataTrigger Binding="{Binding Mark}" Value="Next">
                  <Setter TargetName="MarkIcon" Property="Data" Value="{StaticResource Icon.ArrowRight}" />
                </DataTrigger>
              </DataTemplate.Triggers>
            </DataTemplate>
          </ItemsControl.ItemTemplate>
        </ItemsControl>
      </Border>

      <!-- 詳細の開け閉め（既定は閉じている） -->
      <ToggleButton x:Name="DetailToggleButton" HorizontalAlignment="Left" Margin="0,10,0,0" MinWidth="0" Height="Auto" Padding="0,2"
              Cursor="Hand" Background="Transparent" BorderThickness="0"
              AutomationProperties.AutomationId="LeftoverDetailToggle">
        <ToggleButton.Template>
          <ControlTemplate TargetType="ToggleButton">
            <Border x:Name="Ring" CornerRadius="5" Padding="{TemplateBinding Padding}" Background="Transparent">
              <StackPanel Orientation="Horizontal">
                <Path x:Name="ToggleIcon" Data="{StaticResource Icon.ChevronRight}" Width="12" Height="12" Stretch="Uniform"
                      Stroke="{StaticResource Ink.Muted}" StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round"
                      StrokeLineJoin="Round" VerticalAlignment="Center" Margin="2,0,8,0" />
                <TextBlock Text="{Binding Content, RelativeSource={RelativeSource TemplatedParent}}" Style="{StaticResource Meta}"
                           Foreground="{StaticResource Ink.Muted}" VerticalAlignment="Center" />
              </StackPanel>
            </Border>
            <ControlTemplate.Triggers>
              <Trigger Property="IsKeyboardFocused" Value="True">
                <Setter TargetName="Ring" Property="Background" Value="{StaticResource Accent.Ring}" />
              </Trigger>
              <Trigger Property="IsChecked" Value="True">
                <Setter TargetName="ToggleIcon" Property="Data" Value="{StaticResource Icon.ChevronDown}" />
              </Trigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </ToggleButton.Template>
      </ToggleButton>

      <!-- 詳細：アプリ・PID・起動した時刻。数が多いときは一覧の中で動かす -->
      <Border x:Name="DetailBox" Visibility="Collapsed" Margin="0,8,0,0"
              BorderBrush="{StaticResource Border.Soft}" BorderThickness="1" CornerRadius="{StaticResource Radius.Control}">
        <DockPanel>
          <Border DockPanel.Dock="Top" Background="{StaticResource Bg.Subtle}" BorderBrush="{StaticResource Border.Soft}"
                  BorderThickness="0,0,0,1" CornerRadius="5,5,0,0" Padding="10,7">
            <Grid>
              <Grid.ColumnDefinitions>
                <ColumnDefinition Width="170" />
                <ColumnDefinition Width="110" />
                <ColumnDefinition Width="*" />
              </Grid.ColumnDefinitions>
              <TextBlock Grid.Column="0" Style="{StaticResource Meta}" FontWeight="SemiBold" Foreground="{StaticResource Ink.Strong}" Text="アプリ" />
              <TextBlock Grid.Column="1" Style="{StaticResource Meta}" FontWeight="SemiBold" Foreground="{StaticResource Ink.Strong}" Text="PID" />
              <TextBlock Grid.Column="2" Style="{StaticResource Meta}" FontWeight="SemiBold" Foreground="{StaticResource Ink.Strong}" Text="起動した時刻" />
            </Grid>
          </Border>
          <ScrollViewer MaxHeight="170" VerticalScrollBarVisibility="Auto" Focusable="False">
            <ItemsControl x:Name="DetailList">
              <ItemsControl.ItemTemplate>
                <DataTemplate>
                  <Border BorderBrush="{StaticResource Border.Soft}" BorderThickness="0,0,0,1" Padding="10,7">
                    <Grid>
                      <Grid.ColumnDefinitions>
                        <ColumnDefinition Width="170" />
                        <ColumnDefinition Width="110" />
                        <ColumnDefinition Width="*" />
                      </Grid.ColumnDefinitions>
                      <TextBlock Grid.Column="0" Foreground="{StaticResource Ink.Strong}" Text="{Binding AppName}" />
                      <TextBlock Grid.Column="1" Style="{StaticResource Meta}" Text="{Binding Id}" />
                      <TextBlock Grid.Column="2" Style="{StaticResource Meta}" Text="{Binding TimeText}" />
                    </Grid>
                  </Border>
                </DataTemplate>
              </ItemsControl.ItemTemplate>
            </ItemsControl>
          </ScrollViewer>
        </DockPanel>
      </Border>
    </StackPanel>
  </DockPanel>
</Window>
@@'@
${bundledXaml}[[System.IO.Path]::GetFullPath("${tebunkoRoot}\xaml\index\index.xaml")] = @'
<!-- インデックス管理の画面の枠。tebunko.xaml の ContentHost に入れる（gui_main.ps1）。いちばん上に更新の帯、その下にインデックスの一覧、下に詳細（状態・取り込みの進み具合・失敗の一覧）を差す口を並べる。
     一覧と詳細の高さは、間の GridSplitter のドラッグで変わる（詳細は最大 397・最小 240。窓を低くすると詳細が先に縮む）。 -->
<Grid xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
      xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml" Margin="-16,-12,-16,-12">
  <Grid.Resources>
    <ResourceDictionary>
      <ResourceDictionary.MergedDictionaries>
        <ResourceDictionary Source="../../../shared/xaml/theme.xaml" />
      </ResourceDictionary.MergedDictionaries>
    </ResourceDictionary>
  </Grid.Resources>
  <Grid.RowDefinitions>
    <RowDefinition Height="Auto" />
    <RowDefinition Height="*" />
  </Grid.RowDefinitions>

  <!-- 画面の上の帯。更新中・中断・終了を 1 行で知らせる（地・線・文字・アイコンの色と形は index_detail.ps1 の setIndexingBanner が状態で変える）。
       右の枠（ContentHost の余白）をはみ出して、右の領域の上端・左右いっぱいに置く（下の Grid.Margin）。
       更新中は、見本にない細い進みの棒と、いま見ているファイルを同じ 1 行に並べる -->
  <StackPanel Grid.Row="0">
  <Border x:Name="IndexingProgressPanel" Visibility="Collapsed" Style="{StaticResource Banner}"
          Background="{StaticResource Badge.Run.Bg}" BorderBrush="{StaticResource Accent}">
    <DockPanel>
      <!-- 帯の右の組。ボタンの間・見積もり時間とボタンの間は 10（ボタンの左の余白で取る。右の空き 12 は帯の余白） -->
      <StackPanel DockPanel.Dock="Right" Orientation="Horizontal" VerticalAlignment="Center" Margin="12,0,0,0">
        <TextBlock x:Name="IndexingProgressEta" Style="{StaticResource Meta}" VerticalAlignment="Center" />
        <Button x:Name="IndexingSearchButton" Style="{StaticResource Banner.Button}" Margin="10,0,0,0" Content="検索する" Visibility="Collapsed" />
        <Button x:Name="IndexingResumeButton" Style="{StaticResource Banner.Button}" Margin="10,0,0,0" Content="続きから再開" MinWidth="88" Visibility="Collapsed" />
        <Button x:Name="IndexingStopButton" Style="{StaticResource Banner.Button}" Margin="10,0,0,0" Content="中止" MinWidth="72" />
        <Button x:Name="IndexingBannerClose" Style="{StaticResource Banner.Close}" Margin="10,0,0,0" ToolTip="閉じる"
                AutomationProperties.Name="帯を閉じる" Visibility="Collapsed" />
      </StackPanel>
      <Grid VerticalAlignment="Center">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="Auto" />
          <ColumnDefinition Width="Auto" />
          <ColumnDefinition Width="Auto" />
          <ColumnDefinition Width="*" />
        </Grid.ColumnDefinitions>
        <Path x:Name="IndexingBannerIcon" Grid.Column="0" Data="{StaticResource Icon.Info}" Width="16" Height="16" Stretch="Uniform"
              Stroke="{StaticResource Accent}" StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round"
              Fill="Transparent" VerticalAlignment="Center" Margin="0,0,10,0" />
        <TextBlock x:Name="IndexingProgressText" Grid.Column="1" Style="{StaticResource Focal}" FontSize="12" FontWeight="Medium" Foreground="{StaticResource Banner.Info.Text}"
                   VerticalAlignment="Center" MaxWidth="560" TextTrimming="CharacterEllipsis" TextWrapping="NoWrap" />
        <ProgressBar x:Name="IndexingProgress" Grid.Column="2" Width="140" Height="4" Maximum="1" Margin="14,0,0,0" VerticalAlignment="Center" />
        <TextBlock x:Name="IndexingProgressDetail" Grid.Column="3" Style="{StaticResource Micro}" Foreground="{StaticResource Banner.Info.Text}"
                   VerticalAlignment="Center" Margin="14,0,0,0" TextTrimming="CharacterEllipsis" TextWrapping="NoWrap" />
      </Grid>
    </DockPanel>
  </Border>
  <!-- 削除・まとめてのエクスポート・削除に失敗があったときの知らせの帯（shell/notice_banner.xaml。notice_banner.ps1）。更新の帯の下に重ねて並べる -->
  <ContentControl x:Name="IndexNoticeHost" Focusable="False" IsTabStop="False"
                    HorizontalContentAlignment="Stretch" VerticalContentAlignment="Stretch" />
  </StackPanel>

  <!-- 帯の下。ContentHost の余白（16,12,16,12）を帯のために負の余白で打ち消した。一覧の表・仕切り・詳細は左右いっぱいに置き、一覧の頭の操作の行だけが左右 16 の余白を自分で持つ -->
  <Grid Grid.Row="1">
  <Grid.RowDefinitions>
    <RowDefinition Height="*" MinHeight="225" />
    <RowDefinition Height="Auto" />
    <RowDefinition x:Name="IndexDetailRow" Height="397" MinHeight="240" MaxHeight="397" />
  </Grid.RowDefinitions>

  <ContentControl x:Name="IndexListHost" Grid.Row="0" Margin="0,8,0,0" Focusable="False" IsTabStop="False"
                  HorizontalContentAlignment="Stretch" VerticalContentAlignment="Stretch" />

  <!-- 一覧と詳細の境目。上下にドラッグすると詳細の高さが変わる -->
  <GridSplitter x:Name="IndexSplitter" Grid.Row="1" Margin="0,6,0,0" HorizontalAlignment="Stretch" VerticalAlignment="Center"
                ResizeDirection="Rows" ResizeBehavior="PreviousAndNext" Style="{StaticResource Splitter.Rows}"
                ToolTip="上下にドラッグすると、詳細の高さを変えられます" />

  <ContentControl x:Name="IndexDetailHost" Grid.Row="2" Focusable="False" IsTabStop="False"
                  HorizontalContentAlignment="Stretch" VerticalContentAlignment="Stretch" />
  </Grid>
</Grid>
@@'@
${bundledXaml}[[System.IO.Path]::GetFullPath("${tebunkoRoot}\xaml\index\index_detail.xaml")] = @'
<!-- インデックスの詳細（選んだインデックスの基本設定・インデックスの情報・高速検索の状態、更新の進み具合、失敗の一覧）。
     index.xaml の IndexDetailHost に入れる（gui_main.ps1）。中身は縦にスクロールできる。
     更新中の帯は画面の上（index.xaml）にある。失敗の一覧（FailedPanel）は、いちばん下に置く。
     左右の部品のうち IndexDetail の名前の多くは shell\regions.ps1 の名前の一覧に無く、index_detail.ps1 が読み込んだ中身から取る。 -->
<Grid xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
      xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">
  <Grid.Resources>
    <ResourceDictionary>
      <ResourceDictionary.MergedDictionaries>
        <ResourceDictionary Source="../../../shared/xaml/theme.xaml" />
      </ResourceDictionary.MergedDictionaries>
      <!-- 左右の項目の名前 -->
      <Style x:Key="FieldName" TargetType="TextBlock" BasedOn="{StaticResource Label}">
        <Setter Property="Margin" Value="0,0,0,4" />
      </Style>
      <!-- 値を入れる枠（読むだけ） -->
      <Style x:Key="FieldBox" TargetType="Border">
        <Setter Property="Background" Value="{StaticResource Bg.Subtle}" />
        <Setter Property="BorderBrush" Value="{StaticResource Border.Soft}" />
        <Setter Property="BorderThickness" Value="1" />
        <Setter Property="CornerRadius" Value="4" />
        <Setter Property="Padding" Value="8,5" />
      </Style>
      <!-- 状態を入れる囲み -->
      <Style x:Key="InfoCard" TargetType="Border">
        <Setter Property="BorderBrush" Value="{StaticResource Border.Soft}" />
        <Setter Property="BorderThickness" Value="1" />
        <Setter Property="CornerRadius" Value="6" />
        <Setter Property="Padding" Value="10,8" />
        <Setter Property="Background" Value="{StaticResource Bg.Summary}" />
      </Style>
    </ResourceDictionary>
  </Grid.Resources>
  <!-- 平らな面。上に細い線、見出しの帯（薄い地）、その下に左右 2 列（間は線 1 本） -->
  <Border BorderBrush="{StaticResource Border.Soft}" BorderThickness="0,1,0,0">
    <DockPanel>
      <Border DockPanel.Dock="Top" Background="{StaticResource Bg.Window}" BorderBrush="{StaticResource Border.Soft}" BorderThickness="0,0,0,1" Padding="16,8">
        <StackPanel Orientation="Horizontal">
          <Path Data="{StaticResource Icon.Info}" Width="14" Height="14" Stretch="Uniform" Stroke="{StaticResource Ink.Muted}"
                StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" VerticalAlignment="Center" Margin="0,0,8,0" />
          <TextBlock x:Name="IndexDetailTitle" Style="{StaticResource Label.Strong}" VerticalAlignment="Center" Text="インデックスの状態" />
        </StackPanel>
      </Border>
      <ScrollViewer VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
        <StackPanel Margin="16,10,16,10">

          <!-- 2 件以上を選んだとき（見出しは「N 件を選択中」）の案内 -->
          <TextBlock x:Name="MultiSelectHintText" Style="{StaticResource Meta}" Visibility="Collapsed" />

          <!-- 1 つ選んだときの左右 2 列（左は基本設定・インデックスの状態・高速検索、右はインデックス情報の表）。何も選んでいないときは出さない -->
          <Grid x:Name="IndexDetailBody" Visibility="Collapsed">
            <Grid.ColumnDefinitions>
              <ColumnDefinition Width="*" />
              <ColumnDefinition Width="1" />
              <ColumnDefinition Width="*" />
            </Grid.ColumnDefinitions>
            <Border Grid.Column="1" Background="{StaticResource Border.Soft}" />

            <StackPanel Grid.Column="0" Margin="0,0,16,0">
              <TextBlock Style="{StaticResource Label.Strong}" Text="基本設定" Margin="0,0,0,8" />
              <Grid>
                <Grid.ColumnDefinitions>
                  <ColumnDefinition Width="98" />
                  <ColumnDefinition Width="*" />
                </Grid.ColumnDefinitions>
                <TextBlock Style="{StaticResource Label}" Text="名前" VerticalAlignment="Center" />
                <!-- 名前はその場で直す。Enter か欄から出たときに確定、Esc で取り消す（index_events.ps1・commitIndexDetailEdit） -->
                <TextBox x:Name="IndexDetailName" Grid.Column="1" AutomationProperties.AutomationId="IndexDetailName" AutomationProperties.Name="インデックスの名前" />
              </Grid>
              <Grid Margin="0,10,0,0" UseLayoutRounding="True">
                <Grid.ColumnDefinitions>
                  <ColumnDefinition Width="98" />
                  <ColumnDefinition Width="*" />
                  <ColumnDefinition Width="Auto" />
                </Grid.ColumnDefinitions>
                <TextBlock Style="{StaticResource Label}" Text="フォルダパス" VerticalAlignment="Center" />
                <TextBox x:Name="IndexDetailPath" Grid.Column="1" AutomationProperties.AutomationId="IndexDetailPath" AutomationProperties.Name="元のフォルダのパス" />
                <!-- フォルダの場所をその場で変える［変更…］（設定画面のワークスペースの［変更…］と同じ形）。欄の右に置く。押すとフォルダを選ぶ画面を出し、選んだ場所を欄に入れて、欄に入力したときと同じ道（changeIndexFolder → commitIndexDetailEdit）で変える -->
                <Button x:Name="IndexDetailPathButton" Grid.Column="2" Content="変更…" MinWidth="64" Margin="8,0,0,0"
                        AutomationProperties.AutomationId="IndexDetailPathButton" AutomationProperties.Name="フォルダの場所を変える"
                        ToolTip="元のフォルダの場所を変えます（インデックスはそのまま使います）" />
              </Grid>
              <!-- 名前・フォルダパスを確定できなかったときの理由（commitIndexDetailEdit） -->
              <TextBlock x:Name="IndexDetailEditError" Style="{StaticResource ErrorText}" Margin="98,4,0,0" TextWrapping="Wrap" Visibility="Collapsed" />
              <!-- 文字と左のアイコンの色は updateIndexDetailPanel が getIndexDetailView の FolderBrush で当て、アイコンの形は FolderIcon（Icon.Check・Icon.Close）で替える -->
              <StackPanel Orientation="Horizontal" Margin="98,4,0,0">
                <Path x:Name="IndexDetailFolderIcon" Width="12" Height="12" Margin="0,0,5,0" VerticalAlignment="Center" Stretch="Uniform"
                      Visibility="Collapsed" StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" />
                <TextBlock x:Name="IndexDetailFolderStatus" FontSize="11" VerticalAlignment="Center" />
              </StackPanel>
              <Border Style="{StaticResource InfoCard}" Margin="0,10,0,0">
                <StackPanel>
                  <StackPanel Orientation="Horizontal">
                    <TextBlock Style="{StaticResource Label.Strong}" Text="インデックス" VerticalAlignment="Center" />
                    <Border x:Name="IndexDetailBadge" Style="{StaticResource StatusBadge}" Margin="8,0,0,0" VerticalAlignment="Center">
                      <TextBlock x:Name="IndexDetailBadgeText" FontSize="11" FontWeight="SemiBold" />
                    </Border>
                    <TextBlock x:Name="IndexDetailBadgeSub" Style="{StaticResource Meta}" Margin="8,0,0,0" VerticalAlignment="Center" />
                  </StackPanel>
                  <!-- 元のフォルダが見つからないときの理由と直し方（バッジは「エラー」） -->
                  <TextBlock x:Name="IndexErrorText" Style="{StaticResource ErrorText}" Margin="0,8,0,0" Visibility="Collapsed" />
                  <TextBlock x:Name="IndexErrorHintText" Style="{StaticResource Meta}" Margin="0,2,0,0" TextWrapping="Wrap" Visibility="Collapsed" />
                  <!-- 更新中の行を選んでいるときの進み具合（全体の進みを出す。インデックスごとの件数は無い） -->
                  <StackPanel x:Name="IndexingDetailPanel" Margin="0,8,0,0" Visibility="Collapsed">
                    <ProgressBar x:Name="IndexingProgressBar" Maximum="1" Height="6" />
                    <TextBlock x:Name="IndexingCountText" Style="{StaticResource Meta}" Margin="0,6,0,0" TextTrimming="CharacterEllipsis" TextWrapping="NoWrap" />
                    <TextBlock x:Name="IndexingFileText" Style="{StaticResource Micro}" Margin="0,2,0,0" TextTrimming="CharacterEllipsis" TextWrapping="NoWrap" />
                  </StackPanel>
                  <TextBlock x:Name="IndexDetailUpdated" Style="{StaticResource Meta}" Margin="0,6,0,0" />
                  <TextBlock x:Name="IndexDetailCount" Style="{StaticResource Meta}" Margin="0,2,0,0" />
                </StackPanel>
              </Border>
              <Border Style="{StaticResource InfoCard}" Background="{DynamicResource Bg.Surface}" Margin="0,10,0,0">
                <StackPanel>
                  <StackPanel Orientation="Horizontal">
                    <TextBlock Style="{StaticResource Label.Strong}" Text="高速検索" VerticalAlignment="Center" />
                    <Border x:Name="IndexDetailFastBadge" Style="{StaticResource StatusBadge}" Margin="10,0,0,0" VerticalAlignment="Center">
                      <TextBlock x:Name="IndexDetailFastBadgeText" FontSize="11" FontWeight="SemiBold" />
                    </Border>
                  </StackPanel>
                  <TextBlock x:Name="IndexDetailFastReason" Style="{StaticResource WarnText}" Margin="0,6,0,0" TextWrapping="Wrap" />
                  <TextBlock x:Name="IndexDetailFastSteps" Style="{StaticResource Meta}" Margin="0,4,0,0" TextWrapping="Wrap" Visibility="Collapsed" />
                  <StackPanel x:Name="IndexDetailFastPanel" Margin="0,6,0,0" Visibility="Collapsed">
                    <TextBlock x:Name="IndexDetailFastText" Style="{StaticResource Meta}" />
                    <ProgressBar x:Name="IndexDetailFastBar" Margin="0,4,0,0" Maximum="1" Height="6" />
                  </StackPanel>
                  <TextBlock x:Name="IndexDetailFastChecked" Style="{StaticResource Meta}" Margin="0,6,0,0" />
                  <TextBlock x:Name="IndexDetailFastNote" Style="{StaticResource Micro}" Margin="0,6,0,0" TextWrapping="Wrap" />
                </StackPanel>
              </Border>
            </StackPanel>

            <StackPanel Grid.Column="2" Margin="16,0,0,0">
              <TextBlock Style="{StaticResource Label.Strong}" Text="インデックス情報" Margin="0,0,0,8" />
              <!-- 項目と値の表（見出しの行つき）。値は右に寄せ、1 行で、あふれたら「…」 -->
              <Border BorderBrush="{StaticResource Border.Soft}" BorderThickness="1" CornerRadius="6" ClipToBounds="True">
                <StackPanel>
                  <Border Background="{StaticResource Bg.Summary}" Padding="10,5">
                    <DockPanel>
                      <TextBlock DockPanel.Dock="Right" Style="{StaticResource Label.Strong}" Text="値" />
                      <TextBlock Style="{StaticResource Label.Strong}" Text="項目" />
                    </DockPanel>
                  </Border>
                  <ItemsControl x:Name="IndexDetailRows">
                    <ItemsControl.ItemTemplate>
                      <DataTemplate>
                        <Border BorderBrush="{StaticResource Border.Row}" BorderThickness="0,1,0,0" Padding="10,5">
                          <DockPanel>
                            <TextBlock DockPanel.Dock="Left" Style="{StaticResource Label}" Text="{Binding Label}" Width="130" />
                            <TextBlock Foreground="{StaticResource Ink.Value}" TextTrimming="CharacterEllipsis" TextWrapping="NoWrap" TextAlignment="Right"
                                       Text="{Binding Value}" ToolTip="{Binding Value}" />
                          </DockPanel>
                        </Border>
                      </DataTemplate>
                    </ItemsControl.ItemTemplate>
                  </ItemsControl>
                </StackPanel>
              </Border>
            </StackPanel>
          </Grid>

          <TextBlock Style="{StaticResource Meta}" Margin="0,14,0,0" Text="すべてのインデックスの合計" />
          <TextBlock x:Name="IndexSummaryText" Text="確認中…" Margin="0,4,0,0" />

          <StackPanel x:Name="FailedPanel" Visibility="Collapsed" Margin="0,8,0,0">
            <DockPanel>
              <TextBlock DockPanel.Dock="Right" Style="{StaticResource Micro}" VerticalAlignment="Bottom"
                         Text="ダブルクリックでファイルの場所を開きます" />
              <StackPanel Orientation="Horizontal">
                <Path Data="{StaticResource Icon.TriangleAlert}" Width="14" Height="14" Stretch="Uniform" Stroke="{StaticResource Badge.Ng.Text}"
                      StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" VerticalAlignment="Center" Margin="0,0,6,0" />
                <TextBlock x:Name="FailedHeading" Style="{StaticResource ErrorText}" />
              </StackPanel>
            </DockPanel>
            <DataGrid x:Name="FailedGrid" MaxHeight="130" Margin="0,6,0,0" SelectionMode="Single" CanUserSortColumns="False">
              <DataGrid.Columns>
                <DataGridTemplateColumn Header="ファイル" Width="280">
                  <DataGridTemplateColumn.CellTemplate>
                    <DataTemplate>
                      <TextBlock Style="{StaticResource Cell.Key}" Text="{Binding RelPath}" ToolTip="{Binding RelPath}" />
                    </DataTemplate>
                  </DataGridTemplateColumn.CellTemplate>
                </DataGridTemplateColumn>
                <DataGridTemplateColumn Header="失敗の原因" Width="*">
                  <DataGridTemplateColumn.CellTemplate>
                    <DataTemplate>
                      <TextBlock Style="{StaticResource Cell}" TextTrimming="None" TextWrapping="Wrap"
                                 Text="{Binding Reason}" ToolTip="{Binding Reason}" />
                    </DataTemplate>
                  </DataGridTemplateColumn.CellTemplate>
                </DataGridTemplateColumn>
                <DataGridTextColumn Header="日時" Binding="{Binding IngestedText}" Width="80"
                                    ElementStyle="{StaticResource Cell.Meta}" />
              </DataGrid.Columns>
            </DataGrid>
          </StackPanel>
        </StackPanel>
      </ScrollViewer>
    </DockPanel>
  </Border>
</Grid>
@@'@
${bundledXaml}[[System.IO.Path]::GetFullPath("${tebunkoRoot}\xaml\index\index_list.xaml")] = @'
<!-- インデックスの一覧（操作の行・［すべて更新］・［アクション ▼］・フォルダの追加・一覧の表・件数の帯）。index.xaml の IndexListHost に入れる（gui_main.ps1）。
     行の右端のボタンは［更新］［中止］だけ。エクスポート・削除・インポートは［アクション ▼］のメニュー（ActionExport・ActionDelete・ActionImport）。
     行の右クリックのメニュー（更新・元のフォルダを開く・エクスポート・削除）も残してある。名前と元のフォルダは、詳細欄で直接直す。 -->
<Grid xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
      xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">
  <Grid.Resources>
    <ResourceDictionary>
      <ResourceDictionary.MergedDictionaries>
        <ResourceDictionary Source="../../../shared/xaml/theme.xaml" />
      </ResourceDictionary.MergedDictionaries>
      <!-- ボタンの文字の左に線のアイコンを置く表示（文字は Content。アイコンの色はボタンの文字の色に合わせるので、無効・押し込み・主ボタンでも文字と同じ色になる） -->
      <DataTemplate x:Key="ButtonIcon.Refresh">
        <StackPanel Orientation="Horizontal">
          <Path Data="{StaticResource Icon.RefreshCw}" Width="13" Height="13" Stretch="Uniform" VerticalAlignment="Center" Margin="0,0,7,0"
                Stroke="{Binding Foreground, RelativeSource={RelativeSource AncestorType=Button}}" StrokeThickness="2"
                StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" />
          <TextBlock Text="{Binding}" VerticalAlignment="Center" />
        </StackPanel>
      </DataTemplate>
      <DataTemplate x:Key="ButtonIcon.Plus">
        <StackPanel Orientation="Horizontal">
          <Path Data="{StaticResource Icon.Plus}" Width="13" Height="13" Stretch="Uniform" VerticalAlignment="Center" Margin="0,0,7,0"
                Stroke="{Binding Foreground, RelativeSource={RelativeSource AncestorType=Button}}" StrokeThickness="2"
                StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" />
          <TextBlock Text="{Binding}" VerticalAlignment="Center" />
        </StackPanel>
      </DataTemplate>
      <!-- 選んだ行（詳細欄に出している行）の色 -->
      <Style x:Key="IndexRow" TargetType="DataGridRow" BasedOn="{StaticResource {x:Type DataGridRow}}">
        <Style.Triggers>
          <Trigger Property="IsSelected" Value="True">
            <Setter Property="Background" Value="{StaticResource Select.Soft}" />
          </Trigger>
        </Style.Triggers>
      </Style>
    </ResourceDictionary>
  </Grid.Resources>
  <Border>
    <Grid>
      <Grid.RowDefinitions>
        <RowDefinition Height="Auto" />
        <RowDefinition Height="*" MinHeight="90" />
      </Grid.RowDefinitions>

      <!-- 頭は高さ 48 の操作の行（上下 8・ボタン 32）。左に「N / M 件を選択中」、右に［すべて更新］・［アクション ▼］・［＋ フォルダを追加］ -->
      <StackPanel Grid.Row="0">
        <Grid Height="48" Margin="16,0">
          <Grid.ColumnDefinitions>
            <ColumnDefinition Width="*" />
            <ColumnDefinition Width="Auto" />
          </Grid.ColumnDefinitions>
          <TextBlock x:Name="SelectionCountText" Style="{StaticResource Meta}" VerticalAlignment="Center" HorizontalAlignment="Left"
                     TextTrimming="CharacterEllipsis" Margin="0,0,12,0" />
          <StackPanel Grid.Column="1" Orientation="Horizontal" HorizontalAlignment="Right" VerticalAlignment="Center">
            <Button x:Name="IndexingButton" Content="すべて更新" ContentTemplate="{StaticResource ButtonIcon.Refresh}" MinWidth="104" Height="32" Margin="0,0,8,0" />
            <!-- ［アクション ▼］: 押すと下にメニューを開く（index_events.ps1）。メニューの項目の可否は updateIndexingButton が決める -->
            <Button x:Name="ActionsButton" Height="32" Margin="0,0,8,0">
              <Button.Content>
                <StackPanel Orientation="Horizontal">
                  <TextBlock Text="アクション" VerticalAlignment="Center" />
                  <Path Data="{StaticResource Icon.ChevronDown}" Width="10" Height="10" Stretch="Uniform" Stroke="{StaticResource Ink.Muted}"
                        StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" VerticalAlignment="Center" Margin="6,0,0,0" />
                </StackPanel>
              </Button.Content>
              <Button.ContextMenu>
                <ContextMenu x:Name="ActionsMenu">
                  <MenuItem x:Name="ActionUpdate" Header="更新" />
                  <MenuItem x:Name="ActionExport" Header="エクスポート…" />
                  <MenuItem x:Name="ActionImport" Header="インポート…" />
                  <Separator />
                  <MenuItem x:Name="ActionDelete" Header="削除…" Style="{StaticResource MenuItemDanger}" />
                </ContextMenu>
              </Button.ContextMenu>
            </Button>
            <Button x:Name="NewIndexButton" Style="{StaticResource Primary}" Height="32" Content="フォルダを追加" ContentTemplate="{StaticResource ButtonIcon.Plus}" AutomationProperties.Name="＋ フォルダを追加" />
          </StackPanel>
        </Grid>
        <TextBlock x:Name="IndexingHint" Style="{StaticResource Meta}" Margin="16,0,16,0" TextWrapping="Wrap" TextAlignment="Right" />
      </StackPanel>

      <!-- 表は左右いっぱい。上辺だけ細い線を引く（左右と下の外枠は付けない。DataGrid 自身の枠は 0 のまま） -->
      <Border Grid.Row="1" Margin="0,4,0,0" BorderBrush="{StaticResource Border.Soft}" BorderThickness="0,1,0,0">
        <Grid>
        <DataGrid x:Name="IndexGrid" RowStyle="{StaticResource IndexRow}" SelectionMode="Single" CanUserSortColumns="False" AllowDrop="True" MinHeight="90">
          <DataGrid.ContextMenu>
            <ContextMenu x:Name="IndexRowMenu">
              <MenuItem x:Name="RowMenuUpdate" Header="更新" ToolTip="押したインデックスだけを更新します（行の［更新］と同じです）" />
              <MenuItem x:Name="RowMenuOpenFolder" Header="元のフォルダを開く" ToolTip="インデックスの元のフォルダを、エクスプローラーで開きます" />
              <MenuItem x:Name="ExportIndexButton" Header="エクスポート…" ToolTip="選んだインデックスを 1 つの zip に書き出します（別の PC・ワークスペースで使えます）" />
              <Separator />
              <MenuItem x:Name="RemoveIndexButton" Header="削除…" Style="{StaticResource MenuItemDanger}" ToolTip="選んだインデックスを一覧から消します（元のフォルダとファイルはそのまま残ります）" />
            </ContextMenu>
          </DataGrid.ContextMenu>
          <DataGrid.Columns>
            <DataGridTemplateColumn Width="52">
              <!-- 見出しの全選択（一部だけ選んでいるときは横棒）。押したときの動きは index_events.ps1 -->
              <DataGridTemplateColumn.Header>
                <CheckBox x:Name="SelectAllCheckBox" IsThreeState="True" HorizontalAlignment="Left" Margin="6,0,0,0"
                          AutomationProperties.Name="すべて選ぶ" />
              </DataGridTemplateColumn.Header>
              <DataGridTemplateColumn.CellTemplate>
                <DataTemplate>
                  <CheckBox IsChecked="{Binding Checked, Mode=TwoWay}" HorizontalAlignment="Left" Margin="6,0,0,0" />
                </DataTemplate>
              </DataGridTemplateColumn.CellTemplate>
            </DataGridTemplateColumn>
            <!-- 目で追う列を 1 本に絞るため、インデックス名だけ濃くする -->
            <DataGridTemplateColumn Header="名前" Width="170">
              <DataGridTemplateColumn.CellTemplate>
                <DataTemplate>
                  <Grid VerticalAlignment="Center">
                    <Grid.ColumnDefinitions>
                      <ColumnDefinition Width="Auto" />
                      <ColumnDefinition Width="*" />
                    </Grid.ColumnDefinitions>
                    <Path Data="{StaticResource Icon.Folder}" Width="16" Height="16" Stretch="Uniform" Stroke="{StaticResource File.Folder}"
                          StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round"
                          VerticalAlignment="Center" Margin="0,0,8,0" />
                    <TextBlock Style="{StaticResource Cell.Key}" Grid.Column="1" Text="{Binding Name}" Tag="TrimTip" />
                  </Grid>
                </DataTemplate>
              </DataGridTemplateColumn.CellTemplate>
            </DataGridTemplateColumn>
            <DataGridTemplateColumn Header="パス" Width="*">
              <DataGridTemplateColumn.CellTemplate>
                <DataTemplate>
                  <TextBlock Style="{StaticResource Cell.Meta}" Text="{Binding Path}" Tag="TrimTip" />
                </DataTemplate>
              </DataGridTemplateColumn.CellTemplate>
            </DataGridTemplateColumn>
            <DataGridTemplateColumn Header="ファイル数" Width="86">
              <DataGridTemplateColumn.CellTemplate>
                <DataTemplate>
                  <TextBlock Style="{StaticResource Cell.Number}" Text="{Binding FileCountText}" ToolTip="{Binding FileCountToolTip}" />
                </DataTemplate>
              </DataGridTemplateColumn.CellTemplate>
            </DataGridTemplateColumn>
            <DataGridTemplateColumn Header="最終更新" Width="110">
              <DataGridTemplateColumn.CellTemplate>
                <DataTemplate>
                  <TextBlock Style="{StaticResource Cell.Meta}" Text="{Binding LastIngestedText}" />
                </DataTemplate>
              </DataGridTemplateColumn.CellTemplate>
            </DataGridTemplateColumn>
            <DataGridTemplateColumn Width="170">
              <!-- 見出しの説明（StatusColumnHeader の ToolTip）は ui/index/index_list_view.ps1 の getIndexStatusHelpText が決める -->
              <DataGridTemplateColumn.Header>
                <TextBlock x:Name="StatusColumnHeader" Text="ステータス" />
              </DataGridTemplateColumn.Header>
              <DataGridTemplateColumn.CellTemplate>
                <DataTemplate>
                  <StackPanel VerticalAlignment="Center" ToolTip="{Binding IndexToolTip}">
                    <!-- バッジは状態の名前だけ。数字（更新中の「45%」・要更新の「残り N 件」）は右に小さく添える（無いときは場所を取らない） -->
                    <StackPanel Orientation="Horizontal">
                      <Border Style="{StaticResource LevelBadge}" Tag="{Binding IndexLevel}">
                        <TextBlock Style="{StaticResource LevelBadgeText}" Tag="{Binding IndexLevel}" Text="{Binding IndexText}" />
                      </Border>
                      <TextBlock AutomationProperties.AutomationId="IndexStatusSubText" Margin="8,0,0,0" VerticalAlignment="Center" FontSize="10" FontWeight="Normal"
                                 Foreground="{StaticResource Ink.Muted}" Text="{Binding IndexSub}">
                        <TextBlock.Style>
                          <Style TargetType="TextBlock">
                            <Style.Triggers>
                              <DataTrigger Binding="{Binding IndexSub}" Value="">
                                <Setter Property="Visibility" Value="Collapsed" />
                              </DataTrigger>
                            </Style.Triggers>
                          </Style>
                        </TextBlock.Style>
                      </TextBlock>
                    </StackPanel>
                    <!-- 更新中だけ、下に細い進み具合の棒（幅 120・高さ 4。Percent が負のときは出さない） -->
                    <ProgressBar Minimum="0" Maximum="100" Value="{Binding IndexPercent, Mode=OneWay}" Width="120" Height="4" HorizontalAlignment="Left" Margin="0,4,0,0"
                                 Foreground="{StaticResource File.Folder}" Background="{StaticResource Border.Soft}" BorderThickness="0">
                      <ProgressBar.Style>
                        <Style TargetType="ProgressBar">
                          <Setter Property="Visibility" Value="Collapsed" />
                          <Style.Triggers>
                            <DataTrigger Binding="{Binding IndexLevel}" Value="Run">
                              <Setter Property="Visibility" Value="Visible" />
                            </DataTrigger>
                          </Style.Triggers>
                        </Style>
                      </ProgressBar.Style>
                    </ProgressBar>
                  </StackPanel>
                </DataTemplate>
              </DataGridTemplateColumn.CellTemplate>
            </DataGridTemplateColumn>
            <DataGridTemplateColumn Header="高速検索" Width="118">
              <DataGridTemplateColumn.HeaderStyle>
                <Style TargetType="DataGridColumnHeader" BasedOn="{StaticResource {x:Type DataGridColumnHeader}}">
                  <Setter Property="ToolTip" Value="高速検索用のインデックスが、Windows Search にどこまで反映されたかを示します。" />
                </Style>
              </DataGridTemplateColumn.HeaderStyle>
              <DataGridTemplateColumn.CellTemplate>
                <DataTemplate>
                  <Border Style="{StaticResource LevelBadge}" Tag="{Binding FastLevel}" ToolTip="{Binding FastToolTip}">
                    <TextBlock Style="{StaticResource LevelBadgeText}" Tag="{Binding FastLevel}" Text="{Binding FastText}" />
                  </Border>
                </DataTemplate>
              </DataGridTemplateColumn.CellTemplate>
            </DataGridTemplateColumn>
            <!-- 行の操作は［更新］［中止］だけ（状態は RowAction。エラーの行はボタンを出さず、列の幅は変えない）。
                 押したときの動きは一覧（IndexGrid）の Click で受ける（index_events.ps1） -->
            <DataGridTemplateColumn Header="操作" Width="96">
              <DataGridTemplateColumn.CellTemplate>
                <DataTemplate>
                  <Grid HorizontalAlignment="Center" VerticalAlignment="Center">
                    <Button Tag="RowUpdate" Height="26" MinWidth="66" Padding="8,0" IsEnabled="{Binding RowUpdateEnabled}"
                            AutomationProperties.AutomationId="IndexRowUpdateButton" AutomationProperties.Name="更新">
                      <Button.Style>
                        <Style TargetType="Button" BasedOn="{StaticResource {x:Type Button}}">
                          <Setter Property="Visibility" Value="Collapsed" />
                          <Style.Triggers>
                            <DataTrigger Binding="{Binding RowAction}" Value="Update">
                              <Setter Property="Visibility" Value="Visible" />
                            </DataTrigger>
                          </Style.Triggers>
                        </Style>
                      </Button.Style>
                      <StackPanel Orientation="Horizontal">
                        <Path Data="{StaticResource Icon.RefreshCw}" Width="12" Height="12" Stretch="Uniform" Stroke="{StaticResource Ink.Muted}"
                              StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" VerticalAlignment="Center" />
                        <TextBlock Text="更新" Margin="5,0,0,0" VerticalAlignment="Center" />
                      </StackPanel>
                    </Button>
                    <Button Tag="RowStop" Height="26" MinWidth="66" Padding="8,0"
                            AutomationProperties.AutomationId="IndexRowStopButton" AutomationProperties.Name="中止">
                      <Button.Style>
                        <Style TargetType="Button" BasedOn="{StaticResource {x:Type Button}}">
                          <Setter Property="Visibility" Value="Collapsed" />
                          <Style.Triggers>
                            <DataTrigger Binding="{Binding RowAction}" Value="Stop">
                              <Setter Property="Visibility" Value="Visible" />
                            </DataTrigger>
                          </Style.Triggers>
                        </Style>
                      </Button.Style>
                      <StackPanel Orientation="Horizontal">
                        <Path Data="{StaticResource Icon.StopCircle}" Width="12" Height="12" Stretch="Uniform" Stroke="{StaticResource Ink.Muted}"
                              StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" VerticalAlignment="Center" />
                        <TextBlock Text="中止" Margin="5,0,0,0" VerticalAlignment="Center" />
                      </StackPanel>
                    </Button>
                  </Grid>
                </DataTemplate>
              </DataGridTemplateColumn.CellTemplate>
            </DataGridTemplateColumn>
          </DataGrid.Columns>
        </DataGrid>
        <!-- 1 件も無いときの案内。表の見出しは出したまま、その下に出す -->
        <StackPanel x:Name="IndexGridPlaceholder" VerticalAlignment="Center" HorizontalAlignment="Center" Margin="12,24,12,24">
          <Path Style="{StaticResource Illust.Path}" Data="{StaticResource Icon.FolderSearch}" HorizontalAlignment="Center" />
          <TextBlock Style="{StaticResource Label.Strong}" Margin="0,10,0,0" HorizontalAlignment="Center" Text="フォルダを追加してください" />
          <TextBlock Style="{StaticResource Meta}" Margin="0,4,0,0" HorizontalAlignment="Center" TextWrapping="Wrap"
                     Text="検索したいフォルダを追加すると、ここに表示されます。" />
          <!-- 上の［＋ フォルダを追加］と同じ動き（押せるかどうかも上のボタンに合わせる） -->
          <Button x:Name="IndexEmptyAddButton" Style="{StaticResource Primary}" Content="フォルダを追加" ContentTemplate="{StaticResource ButtonIcon.Plus}" AutomationProperties.Name="＋ フォルダを追加" Margin="0,14,0,0" HorizontalAlignment="Center" MinWidth="130" Height="32"
                  IsEnabled="{Binding IsEnabled, ElementName=NewIndexButton}" />
        </StackPanel>
        </Grid>
      </Border>
    </Grid>
  </Border>
</Grid>
@@'@
${bundledXaml}[[System.IO.Path]::GetFullPath("${tebunkoRoot}\xaml\search\preview.xaml")] = @'
<!-- プレビュー（選んだ行の前後の行と、元のファイルを開く操作）。search.xaml の PreviewHost に入れる（gui_main.ps1）。 -->
<Grid xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
      xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">
  <Grid.Resources>
    <ResourceDictionary>
      <ResourceDictionary.MergedDictionaries>
        <ResourceDictionary Source="../../../shared/xaml/theme.xaml" />
      </ResourceDictionary.MergedDictionaries>
    </ResourceDictionary>
  </Grid.Resources>
  <DockPanel>
      <!-- 選択行のプレビュー（前後の行をシートのように表示する。行番号の列の幅 44 は gui.ps1 の NumberWidth と合わせる）。
           行を選んでいなくても枠は出したままにする（高さが変わらず、次に選んだときもその場に出る） -->
      <DockPanel x:Name="DetailPanel" Margin="0">
        <!-- 見出しの帯（選んだ行の場所と、元のファイルを開く操作）。行を選ぶまでは押せない（プレビューの枠は行を選んでいなくても出したままにするため） -->
        <Border DockPanel.Dock="Top" Background="{StaticResource Bg.Window}" BorderBrush="{StaticResource Border.Soft}" BorderThickness="0,0,0,1" Padding="16,8">
          <DockPanel>
            <Button x:Name="OpenFolderButton" DockPanel.Dock="Right" Style="{StaticResource Link}" Content="フォルダを開く" Margin="14,0,0,0" IsEnabled="False"
                    VerticalAlignment="Center" />
            <!-- ［開く ▼］。［開く］は選んである開き方で開き、▼ から開き方を選ぶ（選んだ開き方は次からも使う。ダブルクリック・Enter も同じ） -->
            <Border DockPanel.Dock="Right" CornerRadius="6" BorderThickness="1"
                    Background="{StaticResource Bg.Surface}" VerticalAlignment="Center" Height="26">
              <!-- 使えないときは、枠・仕切り・文字・▼ をそろえて Ink.Disabled にする（枠だけ Accent のまま残さない） -->
              <Border.Style>
                <Style TargetType="Border">
                  <Setter Property="BorderBrush" Value="{StaticResource Accent}" />
                  <Style.Triggers>
                    <DataTrigger Binding="{Binding ElementName=OpenButton, Path=IsEnabled}" Value="False">
                      <Setter Property="BorderBrush" Value="{StaticResource Ink.Disabled}" />
                    </DataTrigger>
                  </Style.Triggers>
                </Style>
              </Border.Style>
              <StackPanel Orientation="Horizontal">
                <Button x:Name="OpenButton" Content="開く" IsEnabled="False" Cursor="Hand" FontSize="11" Padding="12,0" MinWidth="0" Height="Auto"
                        Foreground="{StaticResource Accent.Hover}" Background="Transparent" BorderThickness="0">
                  <Button.Template>
                    <ControlTemplate TargetType="Button">
                      <Border x:Name="Bg" Background="Transparent" CornerRadius="5,0,0,5" Padding="{TemplateBinding Padding}">
                        <TextBlock x:Name="Label" Text="{TemplateBinding Content}" Foreground="{TemplateBinding Foreground}" FontWeight="SemiBold"
                                   VerticalAlignment="Center" />
                      </Border>
                      <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bg" Property="Background" Value="{StaticResource Select.Soft}" /></Trigger>
                        <Trigger Property="IsEnabled" Value="False"><Setter TargetName="Label" Property="Foreground" Value="{StaticResource Ink.Disabled}" /></Trigger>
                      </ControlTemplate.Triggers>
                    </ControlTemplate>
                  </Button.Template>
                </Button>
                <Rectangle Width="1">
                  <Rectangle.Style>
                    <Style TargetType="Rectangle">
                      <Setter Property="Fill" Value="{StaticResource Accent}" />
                      <Style.Triggers>
                        <DataTrigger Binding="{Binding ElementName=OpenButton, Path=IsEnabled}" Value="False">
                          <Setter Property="Fill" Value="{StaticResource Ink.Disabled}" />
                        </DataTrigger>
                      </Style.Triggers>
                    </Style>
                  </Rectangle.Style>
                </Rectangle>
                <Button x:Name="OpenMenuButton" IsEnabled="False" Cursor="Hand" Padding="6,0" MinWidth="0" Height="Auto" Background="Transparent" BorderThickness="0"
                        AutomationProperties.Name="開き方を選ぶ" ToolTip="開き方を選びます">
                  <Button.Template>
                    <ControlTemplate TargetType="Button">
                      <Border x:Name="Bg" Background="Transparent" CornerRadius="0,5,5,0" Padding="{TemplateBinding Padding}">
                        <Path x:Name="Arrow" Data="{StaticResource Icon.ChevronDown}" Width="11" Height="11" Stretch="Uniform"
                              Stroke="{StaticResource Accent.Hover}" StrokeThickness="1.8" StrokeStartLineCap="Round" StrokeEndLineCap="Round"
                              StrokeLineJoin="Round" VerticalAlignment="Center" />
                      </Border>
                      <ControlTemplate.Triggers>
                        <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bg" Property="Background" Value="{StaticResource Select.Soft}" /></Trigger>
                        <Trigger Property="IsEnabled" Value="False"><Setter TargetName="Arrow" Property="Stroke" Value="{StaticResource Ink.Disabled}" /></Trigger>
                      </ControlTemplate.Triggers>
                    </ControlTemplate>
                  </Button.Template>
                  <Button.ContextMenu>
                    <ContextMenu>
                      <MenuItem x:Name="MenuOpenModeNormal" Header="開く" ToolTip="元のファイルをそのまま開きます。編集して上書き保存できます。" />
                      <MenuItem x:Name="MenuOpenModeNew" Header="新規で開く"
                                ToolTip="元のファイルを基にした新しい（無題の）ブック・文書として開きます。元のファイルを占有しないため、ほかの人が編集中でも開け、ほかの人の編集も妨げません。保存するときは名前を付けて保存します。" />
                      <MenuItem x:Name="MenuOpenModeReadOnly" Header="読み取り専用で開く"
                                ToolTip="元のファイルを読み取り専用で開きます。誤って上書き保存することがありません（編集するときは名前を付けて保存します）。" />
                    </ContextMenu>
                  </Button.ContextMenu>
                </Button>
              </StackPanel>
            </Border>
            <TextBlock x:Name="DetailTitle" FontSize="11" Foreground="{StaticResource Ink.Body}" VerticalAlignment="Center" Margin="0,0,12,0"
                       TextTrimming="CharacterEllipsis" TextWrapping="NoWrap" />
          </DockPanel>
        </Border>
        <!-- 枠は引かない（結果の表との境目は、見出しの帯の線と、窓の枠が示す） -->
        <Border Background="{StaticResource Bg.Surface}" ClipToBounds="True">
          <Grid>
            <DockPanel>
              <!-- 列見出しは、枠を低くしても隠れないよう、行とは別のスクロールに置く（横位置は gui.ps1 で PreviewScroll に合わせる） -->
              <ScrollViewer x:Name="PreviewHeaderScroll" DockPanel.Dock="Top" HorizontalScrollBarVisibility="Hidden" VerticalScrollBarVisibility="Disabled"
                            Focusable="False" Visibility="Collapsed">
                <StackPanel TextElement.FontSize="12">

                  <!-- 列見出し（右端をドラッグすると、その列の幅が変わる。幅は PreviewColumn を各行のセルと共有する）。
                       見えている列の見出しだけを作り、左右の空きは、見えていない列の幅の合計（DataContext は表の PreviewWindow） -->
                  <StackPanel x:Name="PreviewHeaderPanel" Orientation="Horizontal">
                    <!-- 行番号の列の分（幅 44 は gui.ps1 の NumberWidth と合わせる） -->
                    <Border Width="44" Background="{StaticResource Bg.Hover}" BorderBrush="{StaticResource Border.Soft}" BorderThickness="0,0,1,1" />
                    <Border Width="{Binding LeftSpace, FallbackValue=0}" />
                    <ItemsControl x:Name="PreviewHeader">
                      <ItemsControl.ItemsPanel>
                        <ItemsPanelTemplate>
                          <StackPanel Orientation="Horizontal" />
                        </ItemsPanelTemplate>
                      </ItemsControl.ItemsPanel>
                      <ItemsControl.ItemTemplate>
                        <DataTemplate>
                          <Border Width="{Binding Width}" Background="{StaticResource Bg.Subtle}" BorderBrush="{StaticResource Border.Soft}" BorderThickness="0,0,1,1">
                            <Grid>
                              <TextBlock Text="{Binding Label}" Padding="6,3" FontSize="11" TextAlignment="Left" FontWeight="SemiBold"
                                         Foreground="{StaticResource Ink.Muted}"
                                         TextTrimming="CharacterEllipsis" TextWrapping="NoWrap" />
                              <Thumb HorizontalAlignment="Right" Width="6" Cursor="SizeWE"
                                     ToolTip="ドラッグすると列の幅を変えられます">
                                <Thumb.Template>
                                  <ControlTemplate TargetType="Thumb">
                                    <Border Background="Transparent" />
                                  </ControlTemplate>
                                </Thumb.Template>
                              </Thumb>
                            </Grid>
                          </Border>
                        </DataTemplate>
                      </ItemsControl.ItemTemplate>
                    </ItemsControl>
                    <Border Width="{Binding RightSpace, FallbackValue=0}" />
                  </StackPanel>
                </StackPanel>
              </ScrollViewer>

              <!-- 行は仮想化して、見えている行（と前後の余白）だけ要素を作る（VirtualizingStackPanel・行の単位のスクロール）。
                   仮想化は、ItemsControl のテンプレートの中にスクロール（PreviewScroll）を置かないと効かない。
                   縦にも横にもスクロールでき、読み込んだ行は縦にスクロールして見られる。名前は shell\regions.ps1 でテンプレートから取る -->
                  <ItemsControl x:Name="PreviewRows" TextElement.FontSize="12" Focusable="False"
                                VirtualizingPanel.IsVirtualizing="True" VirtualizingPanel.VirtualizationMode="Recycling"
                                VirtualizingPanel.ScrollUnit="Item" ScrollViewer.CanContentScroll="True">
                    <ItemsControl.ContextMenu>
                      <!-- 項目の並び・文言・太字は、メニューを開くたびに判断層（getPreviewMenuItems）の結果で組み直す -->
                      <ContextMenu x:Name="PreviewMenu">
                        <MenuItem x:Name="MenuPreviewOpen" Header="元のファイルのこの場所を開く" />
                        <MenuItem x:Name="MenuPreviewCopy" Header="選んだセルをコピー" />
                        <MenuItem x:Name="MenuPreviewCopyRow" Header="この行をコピー" />
                      </ContextMenu>
                    </ItemsControl.ContextMenu>
                    <ItemsControl.Template>
                      <ControlTemplate TargetType="ItemsControl">
                        <ScrollViewer x:Name="PreviewScroll" AutomationProperties.AutomationId="PreviewScroll" HorizontalScrollBarVisibility="Auto" VerticalScrollBarVisibility="Auto"
                                      CanContentScroll="True" Focusable="True">
                          <ItemsPresenter />
                        </ScrollViewer>
                      </ControlTemplate>
                    </ItemsControl.Template>
                    <ItemsControl.ItemsPanel>
                      <ItemsPanelTemplate>
                        <VirtualizingStackPanel />
                      </ItemsPanelTemplate>
                    </ItemsControl.ItemsPanel>
                    <ItemsControl.ItemTemplate>
                      <DataTemplate>
                        <StackPanel x:Name="RowPanel" Orientation="Horizontal">
                          <Border Width="44" Background="{StaticResource Bg.Hover}" BorderBrush="{StaticResource Border.Soft}" BorderThickness="0,0,1,1">
                            <TextBlock x:Name="Num" Text="{Binding Number}" Padding="4,2,6,2" FontSize="11" TextAlignment="Right"
                                       Foreground="{StaticResource Ink.Faint}" />
                          </Border>
                          <!-- 見えていない左の列の分の空き。セルは見えている列の範囲の分だけ作る（Window は表の全部の行で同じもの） -->
                          <Border Width="{Binding Window.LeftSpace, FallbackValue=0}" />
                          <ItemsControl ItemsSource="{Binding Cells}">
                            <ItemsControl.ItemsPanel>
                              <ItemsPanelTemplate>
                                <StackPanel Orientation="Horizontal" />
                              </ItemsPanelTemplate>
                            </ItemsControl.ItemsPanel>
                            <ItemsControl.ItemTemplate>
                              <DataTemplate>
                                <!-- セル内改行のあるセルは折り返して複数行で表示する（高さの上限まで。全文はツールチップ） -->
                                <Border x:Name="CellBorder" Width="{Binding Column.Width}" BorderBrush="{StaticResource Border.Soft}" BorderThickness="0,0,1,1">
                                  <TextBlock x:Name="CellText" Text="{Binding Display}" ToolTip="{Binding ToolTip}" Padding="6,3"
                                             Foreground="{StaticResource Ink.Body}"
                                             TextTrimming="CharacterEllipsis" TextWrapping="Wrap" MaxHeight="58" />
                                </Border>
                                <DataTemplate.Triggers>
                                  <!-- コピーのために選んだセル（一致したセルは黄色のまま、枠だけを青にする） -->
                                  <DataTrigger Binding="{Binding IsSelected}" Value="True">
                                    <Setter TargetName="CellBorder" Property="Background" Value="{StaticResource Accent.Ring}" />
                                    <Setter TargetName="CellBorder" Property="BorderBrush" Value="{StaticResource Accent.Hover}" />
                                    <Setter TargetName="CellBorder" Property="BorderThickness" Value="1" />
                                  </DataTrigger>
                                  <DataTrigger Binding="{Binding IsHit}" Value="True">
                                    <Setter TargetName="CellBorder" Property="Background" Value="{StaticResource Hit.Cell}" />
                                    <Setter TargetName="CellText" Property="FontWeight" Value="SemiBold" />
                                    <Setter TargetName="CellText" Property="Foreground" Value="{StaticResource Ink.Strong}" />
                                  </DataTrigger>
                                  <MultiDataTrigger>
                                    <MultiDataTrigger.Conditions>
                                      <Condition Binding="{Binding IsHit}" Value="True" />
                                      <Condition Binding="{Binding IsSelected}" Value="True" />
                                    </MultiDataTrigger.Conditions>
                                    <Setter TargetName="CellBorder" Property="BorderBrush" Value="{StaticResource Accent.Hover}" />
                                    <Setter TargetName="CellBorder" Property="BorderThickness" Value="1" />
                                  </MultiDataTrigger>
                                </DataTemplate.Triggers>
                              </DataTemplate>
                            </ItemsControl.ItemTemplate>
                          </ItemsControl>
                          <Border Width="{Binding Window.RightSpace, FallbackValue=0}" />
                          <!-- 読み足しの「読み込み中…」「読めませんでした」の行（セルは持たない） -->
                          <TextBlock Text="{Binding Message}" Padding="10,3" FontSize="11" Foreground="{StaticResource Ink.Faint}" VerticalAlignment="Center">
                            <TextBlock.Style>
                              <Style TargetType="TextBlock">
                                <Setter Property="Visibility" Value="Collapsed" />
                                <Style.Triggers>
                                  <DataTrigger Binding="{Binding IsMessage}" Value="True">
                                    <Setter Property="Visibility" Value="Visible" />
                                  </DataTrigger>
                                </Style.Triggers>
                              </Style>
                            </TextBlock.Style>
                          </TextBlock>
                        </StackPanel>
                        <DataTemplate.Triggers>
                          <!-- 選択行は行全体を薄い青にし、行番号を目立たせる -->
                          <DataTrigger Binding="{Binding IsHitRow}" Value="True">
                            <Setter TargetName="RowPanel" Property="Background" Value="{StaticResource Select.Soft}" />
                            <Setter TargetName="Num" Property="FontWeight" Value="SemiBold" />
                            <Setter TargetName="Num" Property="Foreground" Value="{StaticResource Accent.Hover}" />
                          </DataTrigger>
                        </DataTemplate.Triggers>
                      </DataTemplate>
                    </ItemsControl.ItemTemplate>
                  </ItemsControl>
            </DockPanel>
            <!-- 行を選んでいないときの案内（プレビューの枠は出したままにする） -->
            <TextBlock x:Name="PreviewPlaceholder" Style="{StaticResource Placeholder}" Margin="12,10"
                       VerticalAlignment="Top" TextWrapping="Wrap"
                       Text="行を選ぶと、その前後を表示します。" />
          </Grid>
        </Border>
      </DockPanel>
  </DockPanel>
</Grid>
@@'@
${bundledXaml}[[System.IO.Path]::GetFullPath("${tebunkoRoot}\xaml\search\result_list.xaml")] = @'
<!-- 結果の一覧（件数・進捗・保存・絞り込みの行と、ファイルごとに畳める結果の表）。search.xaml の ResultListHost に入れる（gui_main.ps1）。
 -->
<Grid xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
      xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">
  <Grid.Resources>
    <ResourceDictionary>
      <ResourceDictionary.MergedDictionaries>
        <ResourceDictionary Source="../../../shared/xaml/theme.xaml" />
      </ResourceDictionary.MergedDictionaries>
    </ResourceDictionary>
  </Grid.Resources>
  <Grid.RowDefinitions>
    <RowDefinition Height="Auto" />
    <RowDefinition Height="*" />
  </Grid.RowDefinitions>

  <!-- 件数・すべて開く／閉じる・進捗・絞り込み・保存 -->
  <Border Grid.Row="0" Background="{StaticResource Bg.Subtle}" BorderBrush="{StaticResource Border.Soft}" BorderThickness="0,0,0,1">
    <DockPanel Margin="0">
      <Button x:Name="ExportButton" DockPanel.Dock="Right" Margin="10,0,0,0" Padding="10,0" MinWidth="0" Height="26" FontSize="11"
              ToolTip="結果をファイルに出力します">
        <StackPanel Orientation="Horizontal">
          <Path Data="{StaticResource Icon.Save}" Width="13" Height="13" Stretch="Uniform" Stroke="{StaticResource Ink.Body}"
                StrokeThickness="1.08" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" Margin="0,0,6,0" />
          <TextBlock Text="保存" VerticalAlignment="Center" />
        </StackPanel>
      </Button>
      <Grid DockPanel.Dock="Right" Width="220">
        <TextBox x:Name="FilterBox" FontSize="11" Height="26" />
        <TextBlock x:Name="FilterPlaceholder" Style="{StaticResource Placeholder}" FontSize="11" Text="ファイル名・場所・中身で絞り込む" />
      </Grid>
      <TextBlock DockPanel.Dock="Right" Text="結果を絞り込み" Style="{StaticResource Meta}" VerticalAlignment="Center" Margin="0,0,10,0" />
      <ProgressBar x:Name="SearchProgress" DockPanel.Dock="Right" Width="60" Margin="0,0,12,0" Maximum="1" Visibility="Collapsed" VerticalAlignment="Center" />
      <!-- 検索結果の件数は、この画面の主役 -->
      <TextBlock x:Name="SummaryText" DockPanel.Dock="Left" Style="{StaticResource Meta.Strong}"
                 Foreground="{StaticResource Ink.Strong}" VerticalAlignment="Center" TextTrimming="CharacterEllipsis" Margin="16,0,24,0" />
      <!-- 検索した直後は、ファイルごとの見出しだけを出す（ヒットした行は閉じておく）。ここで全部を開く・閉じる -->
      <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
        <Button x:Name="ExpandAllButton" Style="{StaticResource Link}" Content="すべて開く" FontSize="11" VerticalAlignment="Center"
                ToolTip="すべてのファイルを開いて、ヒットした行を表示します（ヒットが多いと時間がかかります）" />
        <Rectangle Width="1" Height="11" Fill="{StaticResource Border.Soft}" Margin="10,0" />
        <Button x:Name="CollapseAllButton" Style="{StaticResource Link}" Content="すべて折りたたむ" FontSize="11" VerticalAlignment="Center"
                ToolTip="すべてのファイルを閉じて、ファイルの見出しだけを表示します" />
      </StackPanel>
    </DockPanel>
  </Border>

      <!-- 結果の表。ファイルごとの見出しの行（FileGroup）と、開いているファイルの行（HitRow）を並べる（result_list.ps1）。
           見出しの行は、行の形（Template）を FileHeaderRow に替えて、列をまたいだ 1 行にする -->
      <DataGrid Grid.Row="1" x:Name="ResultGrid">
        <DataGrid.Resources>
          <ControlTemplate x:Key="FileHeaderRow" TargetType="DataGridRow">
            <!-- クリック（・Enter）で閉じる・開く。右端はヒットした場所（2 か所以上のときだけ）と件数（件数は絞り込み後の行の数） -->
            <Border x:Name="HeaderBg" Background="{StaticResource Bg.Window}" BorderBrush="{StaticResource Border.Soft}"
                    BorderThickness="0,0,0,1" MinHeight="36" Cursor="Hand" ToolTip="{Binding FullPath}">
              <Grid>
                <!-- 開いている見出しの左の青い線 -->
                <Rectangle x:Name="Bar" HorizontalAlignment="Left" Width="3" Margin="0,5" Fill="{StaticResource Accent}" Visibility="Collapsed" />
                <DockPanel Margin="14,0,16,0">
                  <TextBlock x:Name="Place" DockPanel.Dock="Right" Style="{StaticResource Meta}" FontSize="11" VerticalAlignment="Center"
                             TextTrimming="CharacterEllipsis" MaxWidth="360" Margin="12,0,0,0">
                    <TextBlock.Text>
                      <MultiBinding StringFormat="{}{0}{1:N0} 件">
                        <Binding Path="LocationPrefix" />
                        <Binding Path="ShownCount" />
                      </MultiBinding>
                    </TextBlock.Text>
                  </TextBlock>
                  <Path x:Name="Arrow" DockPanel.Dock="Left" Data="{StaticResource Icon.ChevronRight}" Width="12" Height="12" Stretch="Uniform"
                        Stroke="{StaticResource Ink.Muted}" StrokeThickness="1" StrokeStartLineCap="Round" StrokeEndLineCap="Round"
                        StrokeLineJoin="Round" VerticalAlignment="Center" Margin="0,0,8,0" />
                  <!-- ファイルの種類のアイコン（Excel・Word・PowerPoint の色） -->
                  <Path x:Name="KindIcon" DockPanel.Dock="Left" Data="{StaticResource Icon.File}" Width="16" Height="16" Stretch="Uniform"
                        Stroke="{StaticResource Ink.Body}" StrokeThickness="1.33" StrokeLineJoin="Round" VerticalAlignment="Center" Margin="0,0,8,0" />
                  <TextBlock DockPanel.Dock="Left" Text="{Binding Book}" FontWeight="SemiBold" Foreground="{StaticResource Ink.Strong}"
                             VerticalAlignment="Center" TextTrimming="CharacterEllipsis" />
                  <Border x:Name="RelDirChip" DockPanel.Dock="Left" Background="{StaticResource Bg.Hover}" CornerRadius="4" Padding="6,1" Margin="10,0,0,0" VerticalAlignment="Center"
                          HorizontalAlignment="Left">
                    <TextBlock Text="{Binding RelDir}" Style="{StaticResource Micro}" TextTrimming="CharacterEllipsis" />
                  </Border>
                </DockPanel>
              </Grid>
            </Border>
            <ControlTemplate.Triggers>
              <Trigger Property="IsMouseOver" Value="True">
                <Setter TargetName="HeaderBg" Property="Background" Value="{StaticResource Bg.Hover}" />
              </Trigger>
              <Trigger Property="IsSelected" Value="True">
                <Setter TargetName="HeaderBg" Property="Background" Value="{StaticResource Accent.Soft}" />
              </Trigger>
              <DataTrigger Binding="{Binding IsExpanded}" Value="True">
                <Setter TargetName="Arrow" Property="Data" Value="{StaticResource Icon.ChevronDown}" />
                <Setter TargetName="Bar" Property="Visibility" Value="Visible" />
                <Setter TargetName="Place" Property="Foreground" Value="{StaticResource Accent.Hover}" />
                <Setter TargetName="Place" Property="FontWeight" Value="SemiBold" />
              </DataTrigger>
              <!-- フォルダの印は、閉じた見出しにも出す。ルート直下のファイル（RelDir が空）には出さない -->
              <DataTrigger Binding="{Binding RelDir}" Value="">
                <Setter TargetName="RelDirChip" Property="Visibility" Value="Collapsed" />
              </DataTrigger>
              <DataTrigger Binding="{Binding AppKind}" Value="Excel">
                <Setter TargetName="KindIcon" Property="Data" Value="{StaticResource Icon.FileSpreadsheet}" />
                <Setter TargetName="KindIcon" Property="Stroke" Value="{StaticResource File.Excel}" />
              </DataTrigger>
              <DataTrigger Binding="{Binding AppKind}" Value="Word">
                <Setter TargetName="KindIcon" Property="Data" Value="{StaticResource Icon.FileText}" />
                <Setter TargetName="KindIcon" Property="Stroke" Value="{StaticResource File.Word}" />
              </DataTrigger>
              <DataTrigger Binding="{Binding AppKind}" Value="PowerPoint">
                <Setter TargetName="KindIcon" Property="Data" Value="{StaticResource Icon.Presentation}" />
                <Setter TargetName="KindIcon" Property="Stroke" Value="{StaticResource File.PowerPoint}" />
              </DataTrigger>
            </ControlTemplate.Triggers>
          </ControlTemplate>
        </DataGrid.Resources>
        <DataGrid.RowStyle>
          <Style TargetType="DataGridRow" BasedOn="{StaticResource {x:Type DataGridRow}}">
            <Style.Triggers>
              <!-- 読み上げに使われるのは行の名前。見出しの行はセルが無いため、ファイル名と、フォルダ・場所・件数を行に付ける -->
              <DataTrigger Binding="{Binding IsFileHeader}" Value="True">
                <Setter Property="Template" Value="{StaticResource FileHeaderRow}" />
                <Setter Property="AutomationProperties.Name" Value="{Binding Book}" />
                <Setter Property="AutomationProperties.HelpText">
                  <Setter.Value>
                    <MultiBinding StringFormat="{}{0}　{1}　{2:N0} 件">
                      <Binding Path="RelDir" />
                      <Binding Path="LocationText" />
                      <Binding Path="ShownCount" />
                    </MultiBinding>
                  </Setter.Value>
                </Setter>
              </DataTrigger>
              <DataTrigger Binding="{Binding IsFileHeader}" Value="False">
                <Setter Property="AutomationProperties.Name" Value="{Binding PlaceDisplay}" />
              </DataTrigger>
            </Style.Triggers>
          </Style>
        </DataGrid.RowStyle>
        <DataGrid.Columns>
          <!-- 場所は表示用の文字（[シート]売上!B12・3 ページ（目安） など）。並べ替えは元の名前（ページ003 など、桁をそろえてある）→ 行番号の順。
               幅より長いときはツールチップで全文を出す -->
          <DataGridTextColumn Header="場所" Binding="{Binding PlaceDisplay}" SortMemberPath="Location" Width="180">
            <DataGridTextColumn.ElementStyle>
              <Style TargetType="TextBlock" BasedOn="{StaticResource Cell.Meta}">
                <Setter Property="ToolTip" Value="{Binding PlaceDisplay}" />
              </Style>
            </DataGridTextColumn.ElementStyle>
          </DataGridTextColumn>
          <DataGridTextColumn Header="種別" Binding="{Binding Kind}" Width="48" ElementStyle="{StaticResource Cell.Meta}" />
          <DataGridTemplateColumn Header="該当行" Width="*" SortMemberPath="Line">
            <DataGridTemplateColumn.CellTemplate>
              <DataTemplate>
                <ItemsControl ItemsSource="{Binding Segments}" ToolTip="{Binding DisplayLine}" ClipToBounds="True">
                  <ItemsControl.ItemsPanel>
                    <ItemsPanelTemplate>
                      <StackPanel Orientation="Horizontal" />
                    </ItemsPanelTemplate>
                  </ItemsControl.ItemsPanel>
                  <ItemsControl.ItemTemplate>
                    <DataTemplate>
                      <TextBlock x:Name="Seg" Style="{StaticResource Cell}" TextTrimming="None" Text="{Binding Text}" />
                      <DataTemplate.Triggers>
                        <DataTrigger Binding="{Binding IsHit}" Value="True">
                          <Setter TargetName="Seg" Property="Background" Value="{StaticResource Hit}" />
                          <Setter TargetName="Seg" Property="FontWeight" Value="SemiBold" />
                          <Setter TargetName="Seg" Property="Foreground" Value="{StaticResource Ink.Strong}" />
                        </DataTrigger>
                      </DataTemplate.Triggers>
                    </DataTemplate>
                  </ItemsControl.ItemTemplate>
                </ItemsControl>
              </DataTemplate>
            </DataGridTemplateColumn.CellTemplate>
          </DataGridTemplateColumn>
        </DataGrid.Columns>
        <DataGrid.ContextMenu>
          <!-- 項目の並び・文言・太字は、メニューを開くたびに判断層（getResultMenuItems）の結果で組み直す -->
          <ContextMenu x:Name="ResultMenu">
            <MenuItem x:Name="MenuOpen" Header="開く" />
            <MenuItem x:Name="MenuOpenNew" Header="新規で開く" />
            <MenuItem x:Name="MenuOpenReadOnly" Header="読み取り専用で開く" />
            <MenuItem x:Name="MenuOpenFolder" Header="フォルダを開く" />
            <MenuItem x:Name="MenuCopy" Header="選んだ行をコピー" />
            <MenuItem x:Name="MenuCopyPath" Header="ファイルのパスをコピー" />
            <MenuItem x:Name="MenuToggleGroup" Header="この結果を折りたたむ" />
          </ContextMenu>
        </DataGrid.ContextMenu>
      </DataGrid>
      <!-- 検索が 0 件で終わったとき、結果の表の空いた所に出す文（search_session.ps1 が出し入れする） -->
      <TextBlock x:Name="NoHitText" Grid.Row="1" Style="{StaticResource Meta}" HorizontalAlignment="Center" VerticalAlignment="Top"
                 Margin="0,48,0,0" IsHitTestVisible="False" Visibility="Collapsed" />
</Grid>
@@'@
${bundledXaml}[[System.IO.Path]::GetFullPath("${tebunkoRoot}\xaml\search\search.xaml")] = @'
<!-- 検索の画面の枠。tebunko.xaml の ContentHost に入れる（gui_main.ps1）。上から検索バー・結果の一覧・プレビューを差す口を並べる。
     検索対象のツリーは左のナビ（NavPaneHost）に差す（target_tree.xaml）。
     結果の一覧とプレビューの高さは、間の GridSplitter のドラッグで変わる。結果が少ないときは、ドラッグするまで、
     結果の一覧を内容の高さまで縮めてプレビューを広げる（preview.ps1 の updateResultPaneHeight）。 -->
<Grid xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
      xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">
  <Grid.Resources>
    <ResourceDictionary>
      <ResourceDictionary.MergedDictionaries>
        <ResourceDictionary Source="../../../shared/xaml/theme.xaml" />
      </ResourceDictionary.MergedDictionaries>
    </ResourceDictionary>
  </Grid.Resources>
  <Grid.RowDefinitions>
    <RowDefinition Height="Auto" />
    <RowDefinition Height="Auto" />
    <RowDefinition Height="*" MinHeight="60" />
    <RowDefinition Height="Auto" />
    <!-- 下限は、列見出し＋1 行（一致した行）が見える高さ -->
    <RowDefinition x:Name="DetailRow" Height="180" MinHeight="120" />
  </Grid.RowDefinitions>

  <!-- 画面の上の知らせの帯（検索の結果を保存できなかったとき。shell/notice_banner.xaml。notice_banner.ps1）。窓の右の領域の余白をはみ出して、上端・左右いっぱいに置く（shell\regions.ps1 の領域の表の Margin） -->
  <ContentControl x:Name="SearchNoticeHost" Focusable="False" IsTabStop="False"
                    HorizontalContentAlignment="Stretch" VerticalContentAlignment="Stretch" />

  <!-- 検索バーは結果の一覧より前に出す（エラーの吹き出しが、検索バーの下へはみ出して結果の一覧に重なるため） -->
  <ContentControl x:Name="SearchBarHost" Grid.Row="1" Panel.ZIndex="1" Focusable="False" IsTabStop="False" HorizontalContentAlignment="Stretch" />
  <ContentControl x:Name="ResultListHost" Grid.Row="2" Focusable="False" IsTabStop="False"
                  HorizontalContentAlignment="Stretch" VerticalContentAlignment="Stretch" />

  <!-- 結果の一覧とプレビューの境目。上下にドラッグするとプレビューの高さが変わる -->
  <GridSplitter x:Name="PreviewSplitter" Grid.Row="3" Margin="0,3,0,0" HorizontalAlignment="Stretch" VerticalAlignment="Center"
                ResizeDirection="Rows" ResizeBehavior="PreviousAndNext" Style="{StaticResource Splitter.Rows}"
                ToolTip="上下にドラッグすると、プレビューの高さを変えられます" />

  <ContentControl x:Name="PreviewHost" Grid.Row="4" Focusable="False" IsTabStop="False"
                  HorizontalContentAlignment="Stretch" VerticalContentAlignment="Stretch" />

  <!-- 検索できるインデックスが無いときの空の状態。結果の一覧とプレビューの場所を、まるごと覆う -->
  <Grid x:Name="ResultEmptyState" Grid.Row="2" Grid.RowSpan="3" Background="{StaticResource Bg.Surface}" Visibility="Collapsed">
    <StackPanel HorizontalAlignment="Center" VerticalAlignment="Center" Margin="0,0,0,40">
      <Path Style="{StaticResource Illust.Path}" Data="{StaticResource Icon.FolderSearch}" HorizontalAlignment="Center" />
      <TextBlock Text="インデックスが作成されていません" Style="{StaticResource Heading}" HorizontalAlignment="Center" Margin="0,18,0,10" />
      <TextBlock Style="{StaticResource Meta}" HorizontalAlignment="Center" TextAlignment="Center" LineHeight="22"
                 Text="検索を行うには、まずインデックス管理からフォルダを登録し、&#10;インデックスを作成してください。" />
      <Button x:Name="GoIndexTabButton" Style="{StaticResource Primary}" Content="インデックス管理を開く" MinWidth="140" Height="32" Margin="0,18,0,0"
              HorizontalAlignment="Center" Padding="16,0" />
    </StackPanel>
  </Grid>
</Grid>
@@'@
${bundledXaml}[[System.IO.Path]::GetFullPath("${tebunkoRoot}\xaml\search\search_bar.xaml")] = @'
<!-- 検索バー（検索ワード・検索ボタン・種類のチップ・ファイル内の対象・検索条件・高速検索の状態）と、エラーの吹き出し。search.xaml の SearchBarHost に入れる（gui_main.ps1）。
     白い面にそのまま置き、下に 1px の線を引く（枠のあるカードにしない）。
     検索のエラーは吹き出しで重ねて出し、検索バーの高さは変えない（高さ 0 の Canvas の BalloonLayer に置く。位置は ui/search/search_bar.ps1 の placeSearchBalloon）。
     SearchKindBalloon は、種類を 1 つも選ばずに［検索］を押したときだけ、種類のチップの下に出す。
     RegexBalloon は、正規表現が正しくないとき、［正規表現］の下に出す（検索ワードの欄の枠も赤くする。WordErrorRing）。
     吹き出しは Popup・Adorner にせず、検索バーの中の Canvas に置く（親の Grid で SearchBarHost を前に出して結果の一覧に重ねる。Popup は別ウィンドウで、画面の読み上げ・テストの探索から外れやすい）。 -->
<StackPanel xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
            xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">
<StackPanel.Resources>
  <ResourceDictionary>
    <ResourceDictionary.MergedDictionaries>
      <ResourceDictionary Source="../../../shared/xaml/theme.xaml" />
    </ResourceDictionary.MergedDictionaries>
    <!-- エラーの吹き出し。白地・赤い線 1・角丸 4・影（黒 16%・下に 2・ぼかし 8）。中は 赤いアイコン＋赤い文字 -->
    <Style x:Key="Balloon" TargetType="Border">
      <Setter Property="Background" Value="{StaticResource Bg.Surface}" />
      <Setter Property="BorderBrush" Value="{StaticResource Danger.Text}" />
      <Setter Property="BorderThickness" Value="1" />
      <Setter Property="CornerRadius" Value="4" />
      <Setter Property="Padding" Value="8,5,10,5" />
      <Setter Property="IsHitTestVisible" Value="False" />
      <Setter Property="Visibility" Value="Collapsed" />
      <Setter Property="Effect">
        <Setter.Value>
          <DropShadowEffect Color="Black" Opacity="0.16" ShadowDepth="2" Direction="270" BlurRadius="8" />
        </Setter.Value>
      </Setter>
    </Style>
  </ResourceDictionary>
</StackPanel.Resources>
<Border Background="{DynamicResource Bg.Surface}" BorderBrush="{DynamicResource Border.Soft}" BorderThickness="0,0,0,1"
        Padding="16,12,16,10">
  <Border.Resources>
    <ResourceDictionary>
      <ResourceDictionary.MergedDictionaries>
        <ResourceDictionary Source="../../../shared/xaml/theme.xaml" />
      </ResourceDictionary.MergedDictionaries>
      <!-- 種類のチップ。押すたびに入り切りする（最後の 1 つは外せない。判断は ui/search/search_bar_view.ps1）。
           入りでも切りでも幅・太さを変えない（印は Hidden で場所を残し、文字は Regular のまま） -->
      <Style x:Key="KindChip" TargetType="ToggleButton">
        <Setter Property="Margin" Value="0,0,8,8" />
        <Setter Property="Cursor" Value="Hand" />
        <Setter Property="Focusable" Value="True" />
        <Setter Property="Template">
          <Setter.Value>
            <ControlTemplate TargetType="ToggleButton">
              <Border x:Name="Box" Style="{StaticResource Chip.Box}" Padding="5,4"
                      Background="{StaticResource Bg.Surface}" BorderBrush="{StaticResource Border.Input}">
                <StackPanel Orientation="Horizontal">
                  <Path x:Name="Mark" Data="{StaticResource Icon.Check}" Width="11" Height="11" Stretch="Uniform"
                        Stroke="{StaticResource Accent}" StrokeThickness="2" StrokeStartLineCap="Round"
                        StrokeEndLineCap="Round" StrokeLineJoin="Round" Margin="0,0,3,0" Visibility="Hidden" />
                  <TextBlock x:Name="Label" Text="{TemplateBinding Content}" FontSize="11"
                             Foreground="{StaticResource Ink.Muted}" VerticalAlignment="Center" />
                </StackPanel>
              </Border>
              <ControlTemplate.Triggers>
                <Trigger Property="IsChecked" Value="True">
                  <Setter TargetName="Box" Property="Background" Value="{StaticResource Select.Soft}" />
                  <Setter TargetName="Box" Property="BorderBrush" Value="{StaticResource Accent}" />
                  <Setter TargetName="Mark" Property="Visibility" Value="Visible" />
                  <Setter TargetName="Label" Property="Foreground" Value="{StaticResource Accent.Hover}" />
                </Trigger>
                <Trigger Property="IsMouseOver" Value="True">
                  <Setter TargetName="Box" Property="BorderBrush" Value="{StaticResource Accent}" />
                </Trigger>
                <Trigger Property="IsKeyboardFocused" Value="True">
                  <Setter TargetName="Box" Property="BorderBrush" Value="{StaticResource Accent}" />
                </Trigger>
              </ControlTemplate.Triggers>
            </ControlTemplate>
          </Setter.Value>
        </Setter>
      </Style>
      <!-- ［ファイル内の対象 ▼］。幅 176 で固定し（「・2 件変更」が付いても変わらない）、文字は左・▼ は右端。白地に灰色の線。触れたとき・既定から変えているとき（Tag = changed）は線を青にする -->
      <Style x:Key="ScopeButton" TargetType="Button">
        <Setter Property="Cursor" Value="Hand" />
        <Setter Property="FontSize" Value="11" />
        <Setter Property="Template">
          <Setter.Value>
            <ControlTemplate TargetType="Button">
              <Border x:Name="Box" CornerRadius="6" Padding="12,0" Height="24" Width="176" BorderThickness="1"
                      Background="{StaticResource Bg.Surface}" BorderBrush="{StaticResource Border.Input}">
                <DockPanel VerticalAlignment="Center" LastChildFill="True">
                  <Path DockPanel.Dock="Right" Data="{StaticResource Icon.ChevronDown}" Width="10" Height="10" Stretch="Uniform" Margin="6,1,0,0"
                        Stroke="{StaticResource Ink.Muted}" StrokeThickness="1.6" StrokeStartLineCap="Round"
                        StrokeEndLineCap="Round" StrokeLineJoin="Round" />
                  <TextBlock Text="{TemplateBinding Content}" FontSize="11" Foreground="{StaticResource Ink.Body}" VerticalAlignment="Center"
                             TextTrimming="CharacterEllipsis" TextWrapping="NoWrap" HorizontalAlignment="Left" />
                </DockPanel>
              </Border>
              <ControlTemplate.Triggers>
                <Trigger Property="Tag" Value="changed">
                  <Setter TargetName="Box" Property="BorderBrush" Value="{StaticResource Accent}" />
                </Trigger>
                <Trigger Property="IsMouseOver" Value="True">
                  <Setter TargetName="Box" Property="BorderBrush" Value="{StaticResource Accent}" />
                </Trigger>
                <Trigger Property="IsKeyboardFocused" Value="True">
                  <Setter TargetName="Box" Property="BorderBrush" Value="{StaticResource Accent}" />
                </Trigger>
              </ControlTemplate.Triggers>
            </ControlTemplate>
          </Setter.Value>
        </Setter>
      </Style>
      <!-- 高速検索の状態（Tag = ok の緑・off の灰色）。中の文字・アイコンの色も Tag で切り替える。
           印は幅 170 で固定し、使用可／不可でも変わらない（並びは左から 稲妻の印（zap）・文字・右端の 情報の印（info）。情報の印（info）は常に出す） -->
      <Style x:Key="FastBadgeText" TargetType="TextBlock">
        <Setter Property="Foreground" Value="{StaticResource Badge.None.Text}" />
        <Style.Triggers>
          <DataTrigger Binding="{Binding Tag, RelativeSource={RelativeSource AncestorType=Border}}" Value="ok">
            <Setter Property="Foreground" Value="{StaticResource Badge.Ok.Text}" />
          </DataTrigger>
        </Style.Triggers>
      </Style>
      <Style x:Key="FastBadgeIcon" TargetType="Path">
        <Setter Property="Stroke" Value="{StaticResource Badge.None.Text}" />
        <Style.Triggers>
          <DataTrigger Binding="{Binding Tag, RelativeSource={RelativeSource AncestorType=Border}}" Value="ok">
            <Setter Property="Stroke" Value="{StaticResource Badge.Ok.Text}" />
          </DataTrigger>
        </Style.Triggers>
      </Style>
      <Style x:Key="FastBadge" TargetType="Border">
        <Setter Property="CornerRadius" Value="{StaticResource Radius.Pill}" />
        <Setter Property="Width" Value="170" />
        <Setter Property="Padding" Value="9,3" />
        <Setter Property="Background" Value="{StaticResource Badge.None.Bg}" />
        <Style.Triggers>
          <Trigger Property="Tag" Value="ok">
            <Setter Property="Background" Value="{StaticResource Badge.Ok.Bg}" />
          </Trigger>
        </Style.Triggers>
      </Style>
    </ResourceDictionary>
  </Border.Resources>

  <StackPanel>
    <DockPanel>
      <TextBlock Text="検索ワード" FontSize="13" Foreground="{StaticResource Ink.Body}" VerticalAlignment="Center" Margin="0,0,12,0" />
      <Button x:Name="SearchButton" DockPanel.Dock="Right" Style="{StaticResource Primary}" Content="検索" Width="58" MinWidth="58" Height="32" Margin="12,0,0,0" />
      <Grid>
        <TextBox x:Name="WordBox" Height="32" />
        <TextBlock x:Name="WordPlaceholder" Style="{StaticResource Placeholder}" Text="検索ワードを入力" />
        <!-- 正規表現が正しくないときの赤い枠（入力欄に重ねる） -->
        <Border x:Name="WordErrorRing" BorderBrush="{StaticResource Danger.Text}" BorderThickness="1" Margin="1"
                CornerRadius="{StaticResource Radius.Control}" IsHitTestVisible="False" Visibility="Collapsed" />
      </Grid>
    </DockPanel>

    <!-- 種類のチップ・ファイル内の対象・検索条件・高速検索の状態。1 本の折り返す並び（項目の間 8・折り返した行の間 8）。
         入りきらないときは後ろの項目（高速検索の印から）が次の行の左端へ落ちる。
         ConditionsSpacer は［ファイル内の対象］と検索条件の間の「伸びる空き」で、広い幅では右の組（検索条件・高速検索の印）を右端に寄せる。
         幅は ui/search/search_bar.ps1 の updateConditionFlow が、折り返しの判断（search_bar_view.ps1 の getConditionFlow）で決める。
         各項目は右と下に間 8 を持ち、並びの右・下の余白を -8 にして間を外へはみ出させる -->
    <WrapPanel x:Name="ConditionsPanel" Orientation="Horizontal" Margin="0,8,-8,-8">
      <TextBlock Text="種類" FontSize="11" Foreground="{StaticResource Ink.Muted}" VerticalAlignment="Center" Margin="0,0,8,8" />
      <ToggleButton x:Name="KindChipExcel" Style="{StaticResource KindChip}" Tag="excel" Content="Excel" VerticalAlignment="Center" />
      <ToggleButton x:Name="KindChipWord" Style="{StaticResource KindChip}" Tag="word" Content="Word" VerticalAlignment="Center" />
      <ToggleButton x:Name="KindChipPowerPoint" Style="{StaticResource KindChip}" Tag="powerpoint" Content="PowerPoint" VerticalAlignment="Center" />
      <ToggleButton x:Name="KindChipText" Style="{StaticResource KindChip}" Tag="text" Content="テキスト" VerticalAlignment="Center" />
      <ToggleButton x:Name="KindChipPdf" Style="{StaticResource KindChip}" Tag="pdf" Content="PDF" VerticalAlignment="Center" />
      <Button x:Name="ScopeButton" Style="{StaticResource ScopeButton}" Content="ファイル内の対象" Margin="0,0,8,8" VerticalAlignment="Center"
              ToolTip="ファイルの中で検索する範囲を選びます" AutomationProperties.Name="ファイル内の対象">
        <Button.ContextMenu>
          <ContextMenu>
            <MenuItem Header="共通" IsEnabled="False" FontSize="11" />
            <MenuItem StaysOpenOnClick="True">
              <MenuItem.Header>
                <CheckBox Content="本文　（常に対象）" IsChecked="True" IsEnabled="False" Focusable="False" />
              </MenuItem.Header>
            </MenuItem>
            <MenuItem StaysOpenOnClick="True">
              <MenuItem.Header>
                <CheckBox x:Name="ShapeCheck" Content="図形"
                          ToolTip="オンにすると、図形・テキストボックス・SmartArt・グラフの文字も検索します（種別が「図形」の結果。PowerPoint のテキストボックスはスライドの本文）" />
              </MenuItem.Header>
            </MenuItem>
            <MenuItem StaysOpenOnClick="True">
              <MenuItem.Header>
                <CheckBox x:Name="CommentCheck" Content="コメント"
                          ToolTip="オンにすると、Excel・Word・PowerPoint のコメント（返信を含む）も検索します（種別が「コメント」の結果）" />
              </MenuItem.Header>
            </MenuItem>
          </ContextMenu>
        </Button.ContextMenu>
      </Button>
      <Border x:Name="ConditionsSpacer" Width="0" Height="1" />
      <CheckBox x:Name="CaseCheck" Content="大文字・小文字を区別" FontSize="11" Foreground="{StaticResource Ink.Muted}" VerticalAlignment="Center" Margin="0,0,8,8"
                ToolTip="オンにすると、英字の大文字と小文字を区別します（例: ID は id・Id に一致しない）" />
      <CheckBox x:Name="RegexCheck" Content="正規表現" ToolTip="正規表現を使う&#10;オンにすると高速検索は使えません" FontSize="11" VerticalAlignment="Center" Margin="0,0,8,8">
        <CheckBox.Style>
          <Style TargetType="CheckBox" BasedOn="{StaticResource {x:Type CheckBox}}">
            <Setter Property="Foreground" Value="{StaticResource Ink.Muted}" />
            <Style.Triggers>
              <Trigger Property="IsChecked" Value="True">
                <Setter Property="Foreground" Value="{StaticResource Accent}" />
              </Trigger>
            </Style.Triggers>
          </Style>
        </CheckBox.Style>
      </CheckBox>
      <!-- 高速検索の印。幅 170 で固定する。ツールチップ（ToolTip）は updateFastSearchView が常に付ける -->
      <Border x:Name="FastSearchSlot" Width="170" Margin="0,0,8,8" VerticalAlignment="Center">
        <Border x:Name="FastBadge" Style="{StaticResource FastBadge}" Tag="off" VerticalAlignment="Center">
          <DockPanel LastChildFill="True">
            <Path x:Name="FastBadgeIcon" DockPanel.Dock="Left" Style="{StaticResource FastBadgeIcon}" Data="{StaticResource Icon.Zap}" Width="12" Height="12" Stretch="Uniform" Margin="0,0,5,0"
                  StrokeThickness="1.8" StrokeLineJoin="Round" VerticalAlignment="Center" />
            <Path x:Name="FastBadgeInfo" DockPanel.Dock="Right" Style="{StaticResource FastBadgeIcon}" Data="{StaticResource Icon.Info}" Width="13" Height="13" Stretch="Uniform" Margin="5,0,0,0"
                  StrokeThickness="1.6" StrokeStartLineCap="Round" StrokeEndLineCap="Round" VerticalAlignment="Center" />
            <TextBlock x:Name="FastSearchText" Style="{StaticResource FastBadgeText}" FontSize="11" VerticalAlignment="Center"
                       TextTrimming="CharacterEllipsis" TextWrapping="NoWrap" />
          </DockPanel>
        </Border>
      </Border>
    </WrapPanel>

  </StackPanel>
</Border>
<!-- エラーの吹き出しの置き場。高さ 0 で、検索バーの高さを変えない。位置は placeSearchBalloon が決める -->
<Canvas x:Name="BalloonLayer" Height="0">
  <Border x:Name="SearchKindBalloon" Style="{StaticResource Balloon}">
    <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
      <Path Data="{StaticResource Icon.CircleAlert}" Width="14" Height="14" Stretch="Uniform" Stroke="{StaticResource Danger.Text}"
            StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" Fill="Transparent"
            VerticalAlignment="Center" Margin="0,0,6,0" />
      <TextBlock x:Name="SearchKindBalloonText" Style="{StaticResource ErrorText}" TextWrapping="NoWrap" VerticalAlignment="Center" />
    </StackPanel>
  </Border>
  <Border x:Name="RegexBalloon" Style="{StaticResource Balloon}">
    <StackPanel Orientation="Horizontal" VerticalAlignment="Center">
      <Path Data="{StaticResource Icon.CircleAlert}" Width="14" Height="14" Stretch="Uniform" Stroke="{StaticResource Danger.Text}"
            StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" Fill="Transparent"
            VerticalAlignment="Center" Margin="0,0,6,0" />
      <TextBlock x:Name="RegexBalloonText" Style="{StaticResource ErrorText}" TextWrapping="NoWrap" VerticalAlignment="Center" />
    </StackPanel>
  </Border>
</Canvas>
</StackPanel>
@@'@
${bundledXaml}[[System.IO.Path]::GetFullPath("${tebunkoRoot}\xaml\search\target_tree.xaml")] = @'
<!-- 検索対象のツリー。左のナビの NavPaneHost に入れる（gui_main.ps1。検索の画面のときだけ出す）。
     ［インデックス管理］で作ったインデックスを、チェックで検索対象にする。
     一番上の行は「検索対象 選んだ数 / 全部の数」と、［すべて］［解除］。インデックスが無いときは、結果の欄の空の状態（search.xaml の ResultEmptyState）が案内する。 -->
<Grid xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
      xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
      Background="{DynamicResource Bg.Pane}">
  <Grid.Resources>
    <ResourceDictionary>
      <ResourceDictionary.MergedDictionaries>
        <ResourceDictionary Source="../../../shared/xaml/theme.xaml" />
      </ResourceDictionary.MergedDictionaries>
    </ResourceDictionary>
  </Grid.Resources>
  <DockPanel Margin="12,12,8,10">
    <DockPanel DockPanel.Dock="Top" Margin="2,0,4,8">
      <StackPanel DockPanel.Dock="Right" Orientation="Horizontal" VerticalAlignment="Center">
        <Button x:Name="CheckAllIndexButton" Style="{StaticResource Link}" Content="すべて" FontSize="11"
                ToolTip="すべてのフォルダを検索の対象にします" />
        <Button x:Name="UncheckAllIndexButton" Style="{StaticResource Link}" Content="解除" FontSize="11" Margin="8,0,0,0"
                ToolTip="すべてのフォルダを検索の対象から外します" />
      </StackPanel>
      <TextBlock x:Name="TargetCountText" FontSize="12" FontWeight="SemiBold" Foreground="{StaticResource Ink.Strong}"
                 VerticalAlignment="Center" Text="検索対象" ToolTip="［インデックス管理］で作ったインデックスの一覧です" />
    </DockPanel>
    <TreeView x:Name="IndexTree" BorderThickness="0" Background="Transparent" Padding="0"
              ScrollViewer.HorizontalScrollBarVisibility="Disabled">
      <TreeView.ItemContainerStyle>
        <Style TargetType="TreeViewItem" BasedOn="{StaticResource TreeViewItem.Base}">
          <Setter Property="IsExpanded" Value="{Binding IsExpanded, Mode=TwoWay}" />
        </Style>
      </TreeView.ItemContainerStyle>
      <TreeView.ItemTemplate>
        <HierarchicalDataTemplate ItemsSource="{Binding Children}">
          <Grid ToolTip="{Binding ToolTip}" Margin="0,1">
            <Grid.ColumnDefinitions>
              <ColumnDefinition Width="Auto" />
              <ColumnDefinition Width="Auto" />
              <ColumnDefinition Width="*" />
              <ColumnDefinition Width="Auto" />
            </Grid.ColumnDefinitions>
            <CheckBox x:Name="Check" Grid.Column="0" IsChecked="{Binding IsChecked, Mode=OneWay}" IsThreeState="True" Focusable="False" VerticalAlignment="Center" Margin="0,0,4,0" />
            <Path x:Name="FolderIcon" Grid.Column="1" Data="{StaticResource Icon.Folder}" Width="14" Height="14" Stretch="Uniform"
                  VerticalAlignment="Center" Margin="0,0,6,0" Stroke="{StaticResource File.Folder}" StrokeThickness="1.6"
                  StrokeLineJoin="Round" />
            <Path x:Name="FileIcon" Grid.Column="1" Data="{StaticResource Icon.File}" Width="13" Height="13" Stretch="Uniform"
                  VerticalAlignment="Center" Margin="0,0,6,0" Stroke="{StaticResource Ink.Subtle}" StrokeThickness="1.5"
                  StrokeLineJoin="Round" Visibility="Collapsed" />
            <TextBlock x:Name="Label" Grid.Column="2" Text="{Binding Name}" VerticalAlignment="Center" TextTrimming="CharacterEllipsis" />
            <!-- 元のフォルダが見つからないインデックスの印（理由はツールチップ） -->
            <Ellipse x:Name="StatusDot" Grid.Column="3" Style="{StaticResource NavBadge.Dot}" Fill="{StaticResource Danger.Dot}"
                     Margin="6,0,4,0" VerticalAlignment="Center" Visibility="Collapsed" />
          </Grid>
          <HierarchicalDataTemplate.Triggers>
            <DataTrigger Binding="{Binding Exists}" Value="False">
              <Setter TargetName="StatusDot" Property="Visibility" Value="Visible" />
              <Setter TargetName="Label" Property="Foreground" Value="{StaticResource Ink.Muted}" />
            </DataTrigger>
            <DataTrigger Binding="{Binding IsFiles}" Value="True">
              <Setter TargetName="Label" Property="Foreground" Value="{StaticResource Ink.Muted}" />
              <Setter TargetName="Label" Property="FontSize" Value="12" />
              <Setter TargetName="FolderIcon" Property="Visibility" Value="Collapsed" />
              <Setter TargetName="FileIcon" Property="Visibility" Value="Visible" />
            </DataTrigger>
            <DataTrigger Binding="{Binding IsPlaceholder}" Value="True">
              <Setter TargetName="Check" Property="Visibility" Value="Collapsed" />
              <Setter TargetName="FolderIcon" Property="Visibility" Value="Collapsed" />
              <Setter TargetName="Label" Property="Foreground" Value="{StaticResource Ink.Faint}" />
            </DataTrigger>
          </HierarchicalDataTemplate.Triggers>
        </HierarchicalDataTemplate>
      </TreeView.ItemTemplate>
    </TreeView>
  </DockPanel>
</Grid>
@@'@
${bundledXaml}[[System.IO.Path]::GetFullPath("${tebunkoRoot}\xaml\settings\settings.xaml")] = @'
<!-- 設定の画面（ワークスペース・設定ファイルの場所）。tebunko.xaml の ContentHost に入れる（gui_main.ps1）。
     節は枠つきのカード（Section.Card）で、上に見出しの帯（Section.Header）、その下に行（Section.Row。左に名前と説明、右に値と操作）を縦に並べる。
     中身の幅は最大 880 で左に寄せ、カードの間は 16（2 つ目からのカードに Margin="0,16,0,0" を付ける）。縦にスクロールできる。 -->
<ScrollViewer xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
              xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
              VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled">
  <ScrollViewer.Resources>
    <ResourceDictionary>
      <ResourceDictionary.MergedDictionaries>
        <ResourceDictionary Source="../../../shared/xaml/theme.xaml" />
      </ResourceDictionary.MergedDictionaries>
      <!-- 見せるだけの場所の読み取り専用の文字。共通の入力欄の見た目（枠・高さ 30・マウスや選択での枠の色）を持たず、折り返しても全部見える -->
      <Style x:Key="ReadOnlyValueText" TargetType="TextBox">
        <Setter Property="IsReadOnly" Value="True" />
        <Setter Property="BorderThickness" Value="0" />
        <Setter Property="Background" Value="Transparent" />
        <Setter Property="Padding" Value="0" />
        <Setter Property="FontSize" Value="13" />
        <Setter Property="Foreground" Value="{StaticResource Ink.Strong}" />
        <Setter Property="SelectionBrush" Value="{StaticResource Select.Text}" />
        <Setter Property="SelectionOpacity" Value="0.4" />
        <Setter Property="TextWrapping" Value="Wrap" />
        <Setter Property="Template">
          <Setter.Value>
            <ControlTemplate TargetType="TextBox">
              <ScrollViewer x:Name="PART_ContentHost" Focusable="False" HorizontalScrollBarVisibility="Disabled" VerticalScrollBarVisibility="Disabled" />
            </ControlTemplate>
          </Setter.Value>
        </Setter>
      </Style>
    </ResourceDictionary>
  </ScrollViewer.Resources>
  <Grid Margin="0,16,0,24">
    <!-- 幅は最大 880 で左に寄せる（StackPanel を左寄せにすると中身の幅に縮むため、列の最大幅で抑える） -->
    <Grid.ColumnDefinitions>
      <ColumnDefinition Width="*" MaxWidth="880" />
    </Grid.ColumnDefinitions>
    <StackPanel>
      <!-- インデックス設定（ワークスペース。インデックス・取り込み一覧・ログを置くフォルダ。既定は work）。ツールのフォルダの外にも置ける -->
      <Border Style="{StaticResource Section.Card}">
        <StackPanel>
          <Border Style="{StaticResource Section.Header}">
            <TextBlock Style="{StaticResource Label.Strong}" VerticalAlignment="Center" Text="インデックス設定" />
          </Border>

          <Border Style="{StaticResource Section.Row}" BorderThickness="0">
            <StackPanel>
              <DockPanel>
                <StackPanel DockPanel.Dock="Right" Orientation="Horizontal" Margin="12,0,0,0" VerticalAlignment="Top">
                  <!-- パスは欄に直接入力して変えられる（Enter か欄から出たときに確定、Esc で取り消す）。［変更…］はフォルダを選ぶ画面から入れる -->
                  <TextBox x:Name="WorkspaceBox" Width="360" VerticalAlignment="Center"
                           AutomationProperties.AutomationId="WorkspaceBox" AutomationProperties.Name="ワークスペースのパス" />
                  <Button x:Name="ChangeWorkspaceButton" Content="変更…" MinWidth="64" Margin="8,0,0,0"
                          ToolTip="空のフォルダを選んで、ワークスペースにします（今のワークスペースの中身は新しいフォルダへ移します）" />
                  <Button x:Name="ResetWorkspaceButton" Content="既定に戻す" MinWidth="80" Margin="8,0,0,0" Visibility="Collapsed"
                          ToolTip="設定ファイルと同じフォルダの work に戻します" />
                </StackPanel>
                <StackPanel>
                  <TextBlock Style="{StaticResource Body}" FontWeight="SemiBold" Foreground="{StaticResource Ink.Strong}" Text="ワークスペース" />
                  <TextBlock Style="{StaticResource Meta}" Margin="0,2,0,0" Text="インデックスとログの保存先" />
                </StackPanel>
              </DockPanel>
              <TextBlock x:Name="WorkspaceInputError" Style="{StaticResource ErrorText}" Margin="0,8,0,0" TextWrapping="Wrap" Visibility="Collapsed"
                         AutomationProperties.AutomationId="WorkspaceInputError" />
              <TextBlock x:Name="WorkspaceNote" Style="{StaticResource Micro}" Margin="0,8,0,0" TextWrapping="Wrap" />
              <!-- 注意（文字がそのまま入る・更新中は変えられない）を先に、やり方をあとに置く（文言は getWorkspaceCautionTexts） -->
              <TextBlock x:Name="WorkspaceCaution" Style="{StaticResource Meta}" Margin="0,8,0,0" TextWrapping="Wrap" />
              <TextBlock x:Name="WorkspaceHowTo" Style="{StaticResource Meta}" Margin="0,6,0,0" TextWrapping="Wrap" />
            </StackPanel>
          </Border>

          <!-- 設定ファイルの場所（表示だけ。選んでコピーはできる） -->
          <Border Style="{StaticResource Section.Row}">
            <StackPanel>
              <DockPanel>
                <!-- 見せるだけの場所。押す欄に見えないよう枠を付けず、選んでコピーできる読み取り専用の TextBox にする -->
                <TextBox x:Name="SettingsFileText" Style="{StaticResource ReadOnlyValueText}" DockPanel.Dock="Right"
                         Margin="12,0,0,0" MaxWidth="360" VerticalAlignment="Top" TextAlignment="Right" />
                <StackPanel>
                  <TextBlock Style="{StaticResource Body}" FontWeight="SemiBold" Foreground="{StaticResource Ink.Strong}" Text="設定ファイル" />
                  <TextBlock Style="{StaticResource Meta}" Margin="0,2,0,0" Text="設定の保存先（変更不可）" />
                </StackPanel>
              </DockPanel>
              <TextBlock x:Name="SettingsFileNote" Style="{StaticResource Micro}" Margin="0,8,0,0" TextWrapping="Wrap" />
            </StackPanel>
          </Border>
        </StackPanel>
      </Border>
    </StackPanel>
  </Grid>
</ScrollViewer>
@@'@
${bundledXaml}[[System.IO.Path]::GetFullPath("${tebunkoRoot}\xaml\shell\nav.xaml")] = @'
<!-- ナビ（左の欄）。tebunko.xaml の NavHost に入れる（gui_main.ps1）。
     項目の名前（SearchTab・IndexTab・SettingsTab）は、画面の切り替えと tests/gui が使う。画面の切り替えは ui/shell/nav.ps1 の selectScreen を通す。
     NavPaneHost は、検索の画面のときに検索対象のツリーを差す口。 -->
<Grid xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
      xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
      Background="{DynamicResource Bg.Subtle}">
  <Grid.Resources>
    <ResourceDictionary>
      <ResourceDictionary.MergedDictionaries>
        <ResourceDictionary Source="../../../shared/xaml/theme.xaml" />
      </ResourceDictionary.MergedDictionaries>
    </ResourceDictionary>
  </Grid.Resources>
  <Grid.RowDefinitions>
    <RowDefinition Height="Auto" />
    <RowDefinition Height="1" />
    <RowDefinition Height="*" />
    <RowDefinition Height="1" />
    <RowDefinition Height="28" />
  </Grid.RowDefinitions>

  <ListBox x:Name="NavList" Grid.Row="0" Style="{StaticResource Nav.List}" Margin="0,8,0,0"
           AutomationProperties.Name="画面">
    <ListBoxItem x:Name="SearchTab" Style="{StaticResource NavItem}">
      <TextBlock Style="{x:Null}" Text="検索" />
    </ListBoxItem>
    <ListBoxItem x:Name="IndexTab" Style="{StaticResource NavItem}">
      <DockPanel>
        <!-- 更新中の割合・中断・失敗の印（文言と色は ui/index/index_list_view.ps1 の getIndexNavBadge） -->
        <TextBlock x:Name="IndexTabBadge" DockPanel.Dock="Right" Style="{x:Null}" Text="" Visibility="Collapsed" FontSize="10" Margin="6,0,0,0"
                   Foreground="{StaticResource Warn.Strong}" VerticalAlignment="Center" ToolTip="更新に失敗したファイルがあります" />
        <TextBlock Style="{x:Null}" Text="インデックス管理" />
      </DockPanel>
    </ListBoxItem>
    <ListBoxItem x:Name="SettingsTab" Style="{StaticResource NavItem}">
      <TextBlock Style="{x:Null}" Text="設定" />
    </ListBoxItem>
  </ListBox>

  <Rectangle Grid.Row="1" Fill="{StaticResource Border.Separator}" />

  <ContentControl x:Name="NavPaneHost" Grid.Row="2" Focusable="False" IsTabStop="False"
                  HorizontalContentAlignment="Stretch" VerticalContentAlignment="Stretch" />

  <Rectangle Grid.Row="3" Fill="{StaticResource Border.Separator}" />
  <!-- 情報の印（info） バージョン情報（押すとバージョン情報のダイアログを開く） -->
  <Button x:Name="AboutLink" Grid.Row="4" HorizontalAlignment="Left" VerticalAlignment="Center" Margin="13,0,12,0"
          Cursor="Hand" AutomationProperties.Name="バージョン情報">
    <Button.Template>
      <ControlTemplate TargetType="Button">
        <Border Background="Transparent" Padding="8,2">
          <StackPanel Orientation="Horizontal">
            <Path Data="{StaticResource Icon.Info}" Width="13" Height="13" Stretch="Uniform" VerticalAlignment="Center"
                  Stroke="{StaticResource Ink.Muted}" StrokeThickness="1.5" StrokeStartLineCap="Round" StrokeEndLineCap="Round" />
            <TextBlock x:Name="T" Text="バージョン情報" FontSize="12" Margin="6,0,0,0" VerticalAlignment="Center"
                       Foreground="{StaticResource Ink.Muted}" />
          </StackPanel>
        </Border>
        <ControlTemplate.Triggers>
          <Trigger Property="IsMouseOver" Value="True">
            <Setter TargetName="T" Property="Foreground" Value="{StaticResource Ink.Strong}" />
          </Trigger>
          <Trigger Property="IsKeyboardFocused" Value="True">
            <Setter TargetName="T" Property="TextDecorations" Value="Underline" />
          </Trigger>
        </ControlTemplate.Triggers>
      </ControlTemplate>
    </Button.Template>
  </Button>
</Grid>
@@'@
${bundledXaml}[[System.IO.Path]::GetFullPath("${tebunkoRoot}\xaml\shell\notice_banner.xaml")] = @'
<!-- 画面の上の知らせの帯 1 つ分。検索の画面・インデックス管理の画面・窓の上の 3 か所に差す（shell\regions.ps1 の領域の表。差す所ごとに Prefix を付けた名前で持つ）。
     文言・色・閉じられるか・ボタンは notice_banner.ps1 が、そのとき出す内容で決める -->
<Border xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        x:Name="NoticePanel" Visibility="Collapsed" Style="{DynamicResource Banner}"
        Background="{DynamicResource Warn.Soft}" BorderBrush="{DynamicResource Warn}">
  <Border.Resources>
    <ResourceDictionary>
      <ResourceDictionary.MergedDictionaries>
        <ResourceDictionary Source="../../../shared/xaml/theme.xaml" />
      </ResourceDictionary.MergedDictionaries>
    </ResourceDictionary>
  </Border.Resources>
  <DockPanel>
    <StackPanel DockPanel.Dock="Right" Orientation="Horizontal" VerticalAlignment="Center" Margin="12,0,0,0">
      <Button x:Name="NoticeButton" Style="{StaticResource Banner.Button}" Margin="10,0,0,0" Visibility="Collapsed" />
      <Button x:Name="NoticeClose" Style="{StaticResource Banner.Close}" Margin="10,0,0,0" ToolTip="閉じる"
              AutomationProperties.Name="帯を閉じる" />
    </StackPanel>
    <Path x:Name="NoticeIcon" DockPanel.Dock="Left" Data="{StaticResource Icon.CircleAlert}" Width="16" Height="16" Stretch="Uniform"
          Stroke="{StaticResource Warn}" StrokeThickness="2" StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round"
          Fill="Transparent" VerticalAlignment="Center" Margin="0,0,10,0" />
    <TextBlock x:Name="NoticeText" Style="{StaticResource Focal}" FontSize="12" FontWeight="Medium" Foreground="{StaticResource Banner.Warn.Text}"
               VerticalAlignment="Center" TextTrimming="CharacterEllipsis" TextWrapping="NoWrap" />
  </DockPanel>
</Border>
@@'@
${bundledXaml}[[System.IO.Path]::GetFullPath("${tebunkoRoot}\xaml\shell\status_bar.xaml")] = @'
<!-- ステータスバー（直前の操作の結果）。tebunko.xaml の StatusBarHost に入れる（gui_main.ps1）。
     常時は読まない情報なので、小さく薄くする -->
<Border xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Background="{DynamicResource Bg.Hover}" BorderBrush="{DynamicResource Border.Soft}" BorderThickness="0,1,0,0">
  <Border.Resources>
    <ResourceDictionary>
      <ResourceDictionary.MergedDictionaries>
        <ResourceDictionary Source="../../../shared/xaml/theme.xaml" />
      </ResourceDictionary.MergedDictionaries>
    </ResourceDictionary>
  </Border.Resources>
  <Grid>
    <Grid.ColumnDefinitions>
      <ColumnDefinition Width="Auto" />
      <ColumnDefinition Width="*" />
      <ColumnDefinition Width="Auto" />
    </Grid.ColumnDefinitions>
    <!-- インデックス管理の画面のときだけ出す、登録のフォルダ数（左）とファイルの合計（右）（ui/shell/nav.ps1 が出し入れ、ui/index/index_list.ps1 が文言を入れる） -->
    <TextBlock x:Name="IndexFooterFolders" Grid.Column="0" Style="{StaticResource Micro}" Foreground="{StaticResource Ink.Muted}" Margin="12,0,0,0"
               VerticalAlignment="Center" Visibility="Collapsed" Text="登録済み: 0 フォルダ" />
    <TextBlock x:Name="IndexFooterFiles" Grid.Column="2" Style="{StaticResource Micro}" Foreground="{StaticResource Ink.Muted}" Margin="12,0,12,0"
               VerticalAlignment="Center" Visibility="Collapsed" Text="合計: 0 ファイル" />
    <Grid Grid.Column="1">
      <TextBlock x:Name="StatusText" Style="{StaticResource Micro}" Foreground="{StaticResource Ink.Body}" Margin="12,0,12,0" VerticalAlignment="Center"
                 TextTrimming="CharacterEllipsis" TextWrapping="NoWrap" />
      <!-- 更新中だけ出す 1 行（ui/shell/status_bar.ps1）。出すときは StatusText を隠す。背景は変えない -->
      <TextBlock x:Name="IndexingStatusText" Style="{StaticResource Micro}" Foreground="{StaticResource Ink.Body}" Margin="12,0,12,0" VerticalAlignment="Center"
                 TextTrimming="CharacterEllipsis" TextWrapping="NoWrap" Visibility="Collapsed" />
    </Grid>
  </Grid>
</Border>
@@'@
${bundledXaml}[[System.IO.Path]::GetFullPath("${tebunkoRoot}\xaml\splash.xaml")] = @'
<!-- 起動中の表示。gui.ps1 がスクリプトを読み込む前に出し、画面（tebunko.xaml）が描き終わったら閉じる。
     早く出すため theme.xaml は読み込まず、色は theme.xaml と同じ値を直接書く
     （Bg.Window・Border.Normal・Ink.Strong・Ink.Muted・Accent・Border.Soft）。
     アイコン（xaml\app_icon.xaml のベクターの絵）は showSplash が読めたときだけ SplashIcon に入れる（読めなくても起動は続ける）。 -->
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="tebunko" Width="480" Height="300"
        WindowStyle="None" ResizeMode="NoResize" WindowStartupLocation="CenterScreen"
        FontFamily="Segoe UI, Yu Gothic UI, Meiryo UI" FontSize="13"
        TextOptions.TextFormattingMode="Display" TextOptions.TextRenderingMode="ClearType"
        Background="#FFFFFF" BorderBrush="#D7DBE0" BorderThickness="1,0,1,1"
        UseLayoutRounding="True" SnapsToDevicePixels="True">
  <DockPanel>
    <Border DockPanel.Dock="Top" Height="4" Background="#2563EB" />
    <StackPanel VerticalAlignment="Center" HorizontalAlignment="Center" Width="240">
      <Image x:Name="SplashIcon" Width="48" Height="48" HorizontalAlignment="Center" Margin="0,0,0,16" />
      <TextBlock Text="tebunko" FontSize="22" FontWeight="SemiBold" Foreground="#1F2937"
                 HorizontalAlignment="Center" Margin="0,0,0,18" />
      <ProgressBar x:Name="SplashProgress" Height="4" Minimum="0" Maximum="100" Value="0"
                   Foreground="#2563EB" Background="#E9ECF0" BorderThickness="0" />
      <TextBlock Text="起動中…" Margin="0,10,0,0" Foreground="#78828F" FontSize="12"
                 HorizontalAlignment="Center" />
    </StackPanel>
  </DockPanel>
</Window>
@@'@
${bundledXaml}[[System.IO.Path]::GetFullPath("${tebunkoRoot}\xaml\tebunko.xaml")] = @'
<!-- 画面の枠（ウィンドウ）。左にナビ、右に中身（ContentHost）とステータスバーを並べる。
     gui_main.ps1 が読み込み、ナビは shell/nav.xaml、ステータスバーは shell/status_bar.xaml、中身は画面ごとの XAML から入れる。
     タイトルバーは OS のものを使う（絵で描いた二重のタイトルバーは置かない）。
     色・文字・コントロールの形は scripts/shared/xaml/theme.xaml にまとめてある（loadWindow が読み込む）。 -->
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="tebunko" Width="1280" Height="820" MinWidth="1024" MinHeight="640"
        WindowStartupLocation="CenterScreen"
        FontFamily="{DynamicResource Font.Body}" FontSize="13"
        TextOptions.TextFormattingMode="Display" TextOptions.TextRenderingMode="ClearType"
        Background="{DynamicResource Bg.Surface}" UseLayoutRounding="True" SnapsToDevicePixels="True">

  <Window.TaskbarItemInfo>
    <TaskbarItemInfo />
  </Window.TaskbarItemInfo>

  <Window.Resources>
    <ResourceDictionary>
      <ResourceDictionary.MergedDictionaries>
        <ResourceDictionary Source="../../shared/xaml/theme.xaml" />
      </ResourceDictionary.MergedDictionaries>
    </ResourceDictionary>
  </Window.Resources>

  <Grid>
    <Grid.ColumnDefinitions>
      <!-- 左の欄は既定 220・最小 180・最大 360。右端の 1px の線をつまんで幅を変える -->
      <ColumnDefinition Width="220" MinWidth="180" MaxWidth="360" />
      <ColumnDefinition Width="1" />
      <ColumnDefinition Width="*" />
    </Grid.ColumnDefinitions>

    <!-- ナビ（shell/nav.xaml） -->
    <ContentControl x:Name="NavHost" Grid.Column="0" Focusable="False" IsTabStop="False"
                    HorizontalContentAlignment="Stretch" VerticalContentAlignment="Stretch" />

    <Rectangle Grid.Column="1" Fill="{StaticResource Border.Splitter}" />
    <GridSplitter Grid.Column="1" Width="5" HorizontalAlignment="Center" VerticalAlignment="Stretch"
                  Background="Transparent" ResizeBehavior="PreviousAndNext" ResizeDirection="Columns"
                  Focusable="False" AutomationProperties.Name="左の欄の幅" />

    <!-- 主な領域：中身（画面）とステータスバー。ステータスバーは左の欄の下には付かない -->
    <Grid Grid.Column="2">
      <Grid.RowDefinitions>
        <RowDefinition Height="Auto" />
        <RowDefinition Height="*" />
        <RowDefinition Height="24" />
      </Grid.RowDefinitions>
      <!-- 窓の上の知らせの帯（ワークスペースが使えないとき。shell/notice_banner.xaml。notice_banner.ps1）。画面を切り替えても残る -->
      <ContentControl x:Name="WorkspaceNoticeHost" Grid.Row="0" Focusable="False" IsTabStop="False"
                      HorizontalContentAlignment="Stretch" VerticalContentAlignment="Stretch" />
      <ContentControl x:Name="ContentHost" Grid.Row="1" Margin="16,12,16,12" Focusable="False" IsTabStop="False"
                      HorizontalContentAlignment="Stretch" VerticalContentAlignment="Stretch" />
      <ContentControl x:Name="StatusBarHost" Grid.Row="2" Focusable="False" IsTabStop="False"
                      HorizontalContentAlignment="Stretch" VerticalContentAlignment="Stretch" />
    </Grid>

    <!-- 暗幕。ダイアログを出している間だけ、窓いっぱいに掛ける（shell.ps1 の showOwnedDialog が出し入れする） -->
    <Border x:Name="ScrimOverlay" Grid.Column="0" Grid.ColumnSpan="3" Panel.ZIndex="100"
            Background="{DynamicResource Overlay.Scrim}" Visibility="Collapsed" />
  </Grid>
</Window>
@@'@
${bundledXaml}[[System.IO.Path]::GetFullPath("${tebunkoRoot}\..\shared\xaml\dialog_confirm.xaml")] = @'
<!-- 確認ダイアログ。「押すと何が起きるか」を見出し・結果・ボタンの文言で見せる。shell.ps1 の showConfirm が読み込む。
     題は OS のタイトルバーに出す（showConfirm の -title）。幅は形（normal・danger・choice）ごとに showConfirm が置く。
     色・文字・コントロールの形は scripts/shared/xaml/theme.xaml にまとめてある。 -->
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="確認" Width="520" SizeToContent="Height" MaxHeight="620"
        WindowStartupLocation="CenterOwner" ShowInTaskbar="False" ResizeMode="NoResize"
        FontFamily="{DynamicResource Font.Body}" FontSize="13"
        TextOptions.TextFormattingMode="Display" TextOptions.TextRenderingMode="ClearType"
        Background="{DynamicResource Bg.Surface}" UseLayoutRounding="True" SnapsToDevicePixels="True">
  <Window.Resources>
    <ResourceDictionary>
      <ResourceDictionary.MergedDictionaries>
        <ResourceDictionary Source="theme.xaml" />
      </ResourceDictionary.MergedDictionaries>
      <!-- 下部のボタンは shell.ps1 が並べるため、間隔はここで付ける -->
      <Style TargetType="Button" BasedOn="{StaticResource Button.Base}">
        <Setter Property="MinWidth" Value="80" />
        <Setter Property="Height" Value="32" />
        <Setter Property="Margin" Value="8,0,0,0" />
      </Style>
      <!-- 主なボタン・取り消せない操作のボタンも、ほかのボタンと同じ高さ・最小幅・間隔にそろえる（テーマのままだと高さ 30・最小幅 88 で、並べると 2 画素低く、間隔も無い） -->
      <Style x:Key="Primary" TargetType="Button" BasedOn="{StaticResource Primary}">
        <Setter Property="MinWidth" Value="80" />
        <Setter Property="Height" Value="32" />
        <Setter Property="Margin" Value="8,0,0,0" />
      </Style>
      <Style x:Key="Danger.Filled" TargetType="Button" BasedOn="{StaticResource Danger.Filled}">
        <Setter Property="MinWidth" Value="80" />
        <Setter Property="Height" Value="32" />
        <Setter Property="Margin" Value="8,0,0,0" />
      </Style>
    </ResourceDictionary>
  </Window.Resources>

  <DockPanel Margin="20,16,20,20">
    <!-- 下部：［キャンセル］の右に選択肢のボタンを並べる（最後の 1 つが主なボタン） -->
    <StackPanel x:Name="ButtonPanel" DockPanel.Dock="Bottom" Orientation="Horizontal" HorizontalAlignment="Right" Margin="0,20,0,0" />

    <StackPanel>
      <!-- 見出し：これから何をするか・知らせたいこと。左のアイコンは種類で変わる（shell.ps1 の setDialogLook。確認は「?」・取り消せない操作は赤い「!」・お知らせ・警告・誤りもここ） -->
      <DockPanel>
        <!-- アイコンは Label で包む（Path は UI オートメーションに出ず、読み上げの名前を付けられないため） -->
        <Label x:Name="HeadingIconHost" DockPanel.Dock="Left" Padding="0" Margin="0,0,10,0" VerticalAlignment="Top" Focusable="False"
               Visibility="Collapsed" AutomationProperties.AutomationId="HeadingIcon">
          <Path x:Name="HeadingIcon" Data="{StaticResource Icon.CircleAlert}" Width="20" Height="20" Stretch="Uniform"
                Stroke="{StaticResource Danger.Text}" StrokeThickness="1.8"
                StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" />
        </Label>
        <TextBlock x:Name="HeadingText" Style="{StaticResource Body}" TextWrapping="Wrap" VerticalAlignment="Center" />
      </DockPanel>

      <!-- 結果：実行すると何が消えて何が残るか -->
      <Border x:Name="FactsPanel" Visibility="Collapsed" Margin="0,12,0,0"
              Background="{StaticResource Bg.Subtle}" BorderBrush="{StaticResource Border.Soft}" BorderThickness="1"
              CornerRadius="{StaticResource Radius.Card}" Padding="14,10">
        <ItemsControl x:Name="FactsList">
          <ItemsControl.ItemTemplate>
            <DataTemplate>
              <DockPanel Margin="0,5">
                <!-- 印（Mark）：Kept 残る・Gone 消える・Next 続けて起きること・! 注意。Lucide の形で出す -->
                <Path x:Name="MarkIcon" DockPanel.Dock="Left" Width="14" Height="14" Margin="0,3,8,0" VerticalAlignment="Top" Stretch="Uniform"
                      Data="{StaticResource Icon.TriangleAlert}" Stroke="{Binding MarkBrush}" StrokeThickness="2"
                      StrokeStartLineCap="Round" StrokeEndLineCap="Round" StrokeLineJoin="Round" />
                <StackPanel>
                  <TextBlock Text="{Binding Title}" Foreground="{StaticResource Ink.Strong}" TextWrapping="Wrap" />
                  <TextBlock x:Name="FactDetail" Style="{StaticResource Meta}" Text="{Binding Detail}" Margin="0,3,0,0" />
                </StackPanel>
              </DockPanel>
              <DataTemplate.Triggers>
                <DataTrigger Binding="{Binding Mark}" Value="Kept">
                  <Setter TargetName="MarkIcon" Property="Data" Value="{StaticResource Icon.Check}" />
                </DataTrigger>
                <DataTrigger Binding="{Binding Mark}" Value="Gone">
                  <Setter TargetName="MarkIcon" Property="Data" Value="{StaticResource Icon.Close}" />
                </DataTrigger>
                <DataTrigger Binding="{Binding Mark}" Value="Next">
                  <Setter TargetName="MarkIcon" Property="Data" Value="{StaticResource Icon.ArrowRight}" />
                </DataTrigger>
                <DataTrigger Binding="{Binding Detail}" Value="">
                  <Setter TargetName="FactDetail" Property="Visibility" Value="Collapsed" />
                </DataTrigger>
              </DataTemplate.Triggers>
            </DataTemplate>
          </ItemsControl.ItemTemplate>
        </ItemsControl>
      </Border>

      <!-- 補足：読まなくても操作できる内容だけを書く（見出しの下に淡く出す） -->
      <TextBlock x:Name="HintText" Style="{StaticResource Note}" Visibility="Collapsed" Margin="0,8,0,0" />

      <!-- 詳しい内容（エラーの文面など）。選べる・コピーできるよう TextBox で出す -->
      <Border x:Name="DetailBox" Visibility="Collapsed" Margin="0,12,0,0"
              Background="{StaticResource Bg.Subtle}" BorderBrush="{StaticResource Border.Soft}" BorderThickness="1"
              CornerRadius="{StaticResource Radius.Control}" Padding="10,8">
        <TextBox x:Name="DetailText" IsReadOnly="True" TextWrapping="Wrap" BorderThickness="0" Background="Transparent"
                 Foreground="{StaticResource Ink.Muted}" FontSize="12" MaxHeight="160" VerticalScrollBarVisibility="Auto" />
      </Border>
    </StackPanel>
  </DockPanel>
</Window>
@@'@
${bundledXaml}[[System.IO.Path]::GetFullPath("${tebunkoRoot}\..\shared\xaml\dialog_wait.xaml")] = @'
<!-- 待つ間のダイアログ。閉じるときの待ち・中止の途中など、終わるまで待つ場面で出す。shell.ps1 の showWaitDialog が読み込む。
     利用者は閉じられない（呼び出し側が閉じる）。文言・秒読み・棒の値は呼び出し側の判断層が決め、ここは並べるだけ。
     色・文字・コントロールの形は scripts/shared/xaml/theme.xaml にまとめてある。 -->
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="お待ちください" Width="460" SizeToContent="Height" MaxHeight="620"
        WindowStartupLocation="CenterOwner" ShowInTaskbar="False" ResizeMode="NoResize"
        FontFamily="{DynamicResource Font.Body}" FontSize="13"
        TextOptions.TextFormattingMode="Display" TextOptions.TextRenderingMode="ClearType"
        Background="{DynamicResource Bg.Surface}" UseLayoutRounding="True" SnapsToDevicePixels="True">
  <Window.Resources>
    <ResourceDictionary>
      <ResourceDictionary.MergedDictionaries>
        <ResourceDictionary Source="theme.xaml" />
      </ResourceDictionary.MergedDictionaries>
      <Style TargetType="Button" BasedOn="{StaticResource Button.Base}">
        <Setter Property="MinWidth" Value="80" />
        <Setter Property="Height" Value="32" />
      </Style>
    </ResourceDictionary>
  </Window.Resources>

  <StackPanel Margin="20,16,20,20">
    <!-- 見出し：いま何をしているか -->
    <TextBlock x:Name="HeadingText" Style="{StaticResource Body}" TextWrapping="Wrap" />
    <!-- 説明：待つ理由（空なら隠す） -->
    <TextBlock x:Name="DescriptionText" Style="{StaticResource Note}" TextWrapping="Wrap" Visibility="Collapsed" Margin="0,8,0,0" />
    <!-- 棒：件数が分からないときは流れる棒、分かるときは割合 -->
    <ProgressBar x:Name="WaitBar" Minimum="0" Maximum="1" IsIndeterminate="True" Margin="0,14,0,0" />
    <!-- 秒読み：あと何秒で強制終了するか（空なら隠す） -->
    <TextBlock x:Name="CountdownText" Style="{StaticResource Meta}" Visibility="Collapsed" Margin="0,8,0,0" />
    <!-- 押せないボタン：閉じられないことを見せるだけ（空なら隠す） -->
    <Button x:Name="WaitButton" IsEnabled="False" Visibility="Collapsed" HorizontalAlignment="Right" Margin="0,16,0,0" />
  </StackPanel>
</Window>
@@'@
${bundledXaml}[[System.IO.Path]::GetFullPath("${tebunkoRoot}\..\shared\xaml\theme.xaml")] = @'
<!-- 画面の見た目の定義（色・文字・コントロールの形）。gui.ps1 の loadWindow が各画面に読み込む。

     文字の設計:
       大きさ  16 / 14 / 13 / 12 / 11 / 10。ダイアログの見出し 16、主役の値 14、本文 13、補助 12、補助の小 11、細目 10。
       太さ    Normal・Medium・SemiBold・Bold。Medium は項目の名前（ナビ・インデックス名・種別の札）、SemiBold は見出し・主ボタン・その画面の主役の値、Bold は件数・一致した文字などの強調に使う。
       濃さ    Ink.Strong（見出し・主キー）＞ Ink.Body（本文）＞ Ink.Muted（補助）＞ Ink.Faint（入力前の案内）。
               すべてを黒にすると重要度が伝わらないため、本文は真っ黒にしない。

     Windows 既定のコントロールは立体的で古いため、Button・TextBox・CheckBox・DataGrid・
     TreeViewItem・ScrollBar・ComboBox・MenuItem は独自のテンプレートにする。
     既定テンプレートを置き換えると既定のフォーカス表示も消えるため、キーボードで操作する箇所には
     必ずフォーカスの枠（Accent.Ring）を出す。
-->
<ResourceDictionary xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
                    xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">

  <!-- ============ 色のトークン（色を変えるのはここだけ） ============ -->
  <!-- 値は Figma の設計（theme の Variables）に合わせる。近い色はキーにまとめてある -->
  <!-- 背景 -->
  <SolidColorBrush x:Key="Bg.Window"      Color="#F5F7FA" />
  <SolidColorBrush x:Key="Bg.Surface"     Color="#FFFFFF" />
  <SolidColorBrush x:Key="Bg.Subtle"      Color="#F9FAFA" />
  <SolidColorBrush x:Key="Bg.Stripe"      Color="#FAFBFC" />
  <SolidColorBrush x:Key="Bg.Hover"       Color="#F3F3F4" />
  <SolidColorBrush x:Key="Bg.Pressed"     Color="#E8EBEF" />
  <SolidColorBrush x:Key="Bg.Pane"        Color="#F0F2F4" />
  <SolidColorBrush x:Key="Bg.Tag"         Color="#F1F3F4" />
  <SolidColorBrush x:Key="Bg.Button"      Color="#F2F2F5" />
  <SolidColorBrush x:Key="Bg.Summary"     Color="#F7FAFC" />
  <SolidColorBrush x:Key="Bg.TitleBar"    Color="#F0F0F0" />

  <!-- 枠・線 -->
  <SolidColorBrush x:Key="Border.Soft"      Color="#E0E2E5" />
  <SolidColorBrush x:Key="Border.Normal"    Color="#D9DEE3" />
  <SolidColorBrush x:Key="Border.Input"     Color="#D1D1D1" />
  <SolidColorBrush x:Key="Border.Strong"    Color="#C9CED4" />
  <SolidColorBrush x:Key="Border.Separator" Color="#D5D9DE" />
  <SolidColorBrush x:Key="Border.Splitter"  Color="#D0D4D9" />
  <SolidColorBrush x:Key="Border.Grip"      Color="#A9AFB6" />
  <SolidColorBrush x:Key="Border.Divider"   Color="#E5E8ED" />
  <SolidColorBrush x:Key="Border.Row"       Color="#EDF0F2" />
  <SolidColorBrush x:Key="Border.Dialog"    Color="#D1D6E0" />
  <SolidColorBrush x:Key="Border.Check"     Color="#9EA3AB" />
  <SolidColorBrush x:Key="Border.Window"    Color="#999999" />

  <!-- ダイアログの後ろの暗幕（窓いっぱいに掛ける） -->
  <SolidColorBrush x:Key="Overlay.Scrim"  Color="#000000" Opacity="0.35" />

  <!-- 文字・アイコン -->
  <SolidColorBrush x:Key="Ink.Strong"      Color="#202124" />
  <SolidColorBrush x:Key="Ink.Value"       Color="#212126" />
  <SolidColorBrush x:Key="Ink.Body"        Color="#5F6368" />
  <SolidColorBrush x:Key="Ink.Muted"       Color="#6B737D" />
  <SolidColorBrush x:Key="Ink.Subtle"      Color="#80868B" />
  <SolidColorBrush x:Key="Ink.Placeholder" Color="#9AA0A6" />
  <SolidColorBrush x:Key="Ink.Faint"       Color="#99A1AB" />
  <SolidColorBrush x:Key="Ink.Note"        Color="#8C949E" />
  <SolidColorBrush x:Key="Ink.Disabled"    Color="#B0B6BD" />
  <SolidColorBrush x:Key="Ink.OnAccent"    Color="#FFFFFF" />
  <SolidColorBrush x:Key="Button.Text"     Color="#4D4D4D" />
  <SolidColorBrush x:Key="Button.Icon"     Color="#666666" />

  <!-- 強調・状態 -->
  <SolidColorBrush x:Key="Accent"         Color="#0078D4" />
  <SolidColorBrush x:Key="Accent.Hover"   Color="#0B5CAD" />
  <SolidColorBrush x:Key="Accent.Soft"    Color="#E5F1FB" />
  <SolidColorBrush x:Key="Accent.Ring"    Color="#BFD3FE" />
  <SolidColorBrush x:Key="Select.Soft"    Color="#E1F2FF" />
  <!-- 入力欄で選んだ文字の地。SelectionOpacity 0.4 で重ねる（TextBox.Base） -->
  <SolidColorBrush x:Key="Select.Text"    Color="#0078D4" />
  <SolidColorBrush x:Key="Hit"            Color="#FFF176" />
  <SolidColorBrush x:Key="Hit.Cell"       Color="#FFF3CD" />
  <SolidColorBrush x:Key="Ok"             Color="#218A21" />
  <SolidColorBrush x:Key="Ok.Strong"      Color="#1E8E3E" />
  <SolidColorBrush x:Key="Ok.Soft"        Color="#E0F7E0" />
  <SolidColorBrush x:Key="Warn"           Color="#BA7D00" />
  <SolidColorBrush x:Key="Warn.Dot"       Color="#E8A400" />
  <SolidColorBrush x:Key="Warn.Soft"      Color="#FFF5E0" />
  <SolidColorBrush x:Key="Warn.Note"      Color="#FFF7E0" />
  <SolidColorBrush x:Key="Warn.Line"      Color="#F0C36D" />
  <SolidColorBrush x:Key="Warn.Strong"    Color="#6B4E00" />
  <SolidColorBrush x:Key="Danger.Text"    Color="#D13438" />
  <SolidColorBrush x:Key="Danger.Dot"     Color="#D93025" />
  <SolidColorBrush x:Key="Danger.Line"    Color="#E9B8A3" />
  <SolidColorBrush x:Key="Danger.Soft"    Color="#FFE6E6" />

  <!-- ファイルの種類のアイコン・フォルダ・進み具合のバー -->
  <SolidColorBrush x:Key="File.Excel"      Color="#107C41" />
  <SolidColorBrush x:Key="File.Word"       Color="#185ABD" />
  <SolidColorBrush x:Key="File.PowerPoint" Color="#C43E1C" />
  <SolidColorBrush x:Key="File.Folder"     Color="#E8A020" />

  <!-- イラストの線 -->
  <SolidColorBrush x:Key="Illust.Line"    Color="#D1D6DE" />

  <!-- 一覧の状態バッジ（4 段階）の色。背景と文字の組で、どの画面の状態表示にも使えるようにする -->
  <SolidColorBrush x:Key="Badge.Ok.Bg"     Color="#E0F7E0" />
  <SolidColorBrush x:Key="Badge.Ok.Text"   Color="#218A21" />
  <SolidColorBrush x:Key="Badge.Wait.Bg"   Color="#FFF5E0" />
  <SolidColorBrush x:Key="Badge.Wait.Text" Color="#BA7D00" />
  <!-- 使えない・足りないが、失敗ではないもの（高速検索の「不可」など）。Wait と同じ黄の系統で、文字だけ濃くする -->
  <SolidColorBrush x:Key="Badge.Warn.Bg"   Color="#FFF5E0" />
  <SolidColorBrush x:Key="Badge.Warn.Text" Color="#8A5A00" />
  <SolidColorBrush x:Key="Badge.Ng.Bg"     Color="#FFE6E6" />
  <SolidColorBrush x:Key="Badge.Ng.Text"   Color="#D13438" />
  <SolidColorBrush x:Key="Badge.None.Bg"   Color="#F1F3F4" />
  <SolidColorBrush x:Key="Badge.None.Text" Color="#5F6368" />
  <!-- 更新中（青）。Select.Soft の地・Accent の文字と同じ色 -->
  <SolidColorBrush x:Key="Badge.Run.Bg"      Color="#E1F2FF" />
  <SolidColorBrush x:Key="Badge.Run.Text"    Color="#0078D4" />

  <CornerRadius x:Key="Radius.Control">6</CornerRadius>
  <CornerRadius x:Key="Radius.Card">10</CornerRadius>

  <!-- ============ 文字 ============ -->
  <!-- 既定＝本文。真っ黒にせず、見出しとの差を残す -->
  <Style TargetType="TextBlock">
    <Setter Property="FontSize" Value="13" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Body}" />
  </Style>

  <!-- 区画の見出し -->
  <Style x:Key="Heading" TargetType="TextBlock">
    <Setter Property="FontSize" Value="13" />
    <Setter Property="FontWeight" Value="SemiBold" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Strong}" />
  </Style>

  <!-- ダイアログの見出し（これから何をするか） -->
  <Style x:Key="DialogHeading" TargetType="TextBlock">
    <Setter Property="FontSize" Value="16" />
    <Setter Property="FontWeight" Value="SemiBold" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Strong}" />
    <Setter Property="TextWrapping" Value="Wrap" />
  </Style>

  <!-- 入力欄の見出し -->
  <Style x:Key="Label" TargetType="TextBlock">
    <Setter Property="FontSize" Value="12" />
    <Setter Property="FontWeight" Value="SemiBold" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Strong}" />
    <Setter Property="VerticalAlignment" Value="Center" />
  </Style>

  <!-- その画面の主役の値（件数など）。画面に 1 つだけ -->
  <Style x:Key="Focal" TargetType="TextBlock">
    <Setter Property="FontSize" Value="14" />
    <Setter Property="FontWeight" Value="SemiBold" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Strong}" />
  </Style>

  <!-- 補助（説明文・ラベル） -->
  <Style x:Key="Meta" TargetType="TextBlock">
    <Setter Property="FontSize" Value="11" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Muted}" />
    <Setter Property="TextWrapping" Value="Wrap" />
  </Style>
  <!-- 旧名。既存の画面が Hint を参照しているため残す -->
  <Style x:Key="Hint" TargetType="TextBlock" BasedOn="{StaticResource Meta}" />

  <!-- 細目（常時は読まない情報） -->
  <Style x:Key="Micro" TargetType="TextBlock">
    <Setter Property="FontSize" Value="10" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Faint}" />
    <Setter Property="TextWrapping" Value="Wrap" />
  </Style>

  <!-- Figma の Text styles（フォントは Windows 標準の Segoe UI・Yu Gothic UI。太さは Figma の指定のうち、フォントにある太さ（Regular・SemiBold・Bold）で出る。Medium は Regular に寄る）。
       色は使う所で決める。下の既定は、その文字が一番よく使われる色。行の高さは書いてあるものだけ指定する
       （Brand の字間 0.2 は TextBlock に無いので付けない） -->
  <Style x:Key="ColumnHeader" TargetType="TextBlock">
    <Setter Property="FontSize" Value="10" />
    <Setter Property="FontWeight" Value="Bold" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Muted}" />
  </Style>
  <Style x:Key="Meta.Tall" TargetType="TextBlock" BasedOn="{StaticResource Meta}">
    <Setter Property="LineHeight" Value="16" />
    <Setter Property="LineStackingStrategy" Value="BlockLineHeight" />
  </Style>
  <Style x:Key="Meta.Strong" TargetType="TextBlock" BasedOn="{StaticResource Meta}">
    <Setter Property="FontWeight" Value="Bold" />
  </Style>
  <Style x:Key="Meta.Key" TargetType="TextBlock" BasedOn="{StaticResource Meta.Tall}">
    <Setter Property="FontWeight" Value="SemiBold" />
  </Style>
  <Style x:Key="Note" TargetType="TextBlock">
    <Setter Property="FontSize" Value="11" />
    <Setter Property="LineHeight" Value="17.6" />
    <Setter Property="LineStackingStrategy" Value="BlockLineHeight" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Note}" />
    <Setter Property="TextWrapping" Value="Wrap" />
  </Style>
  <Style x:Key="Chip" TargetType="TextBlock">
    <Setter Property="FontSize" Value="11" />
    <Setter Property="FontWeight" Value="Medium" />
    <Setter Property="Foreground" Value="{StaticResource Accent.Hover}" />
  </Style>
  <Style x:Key="Link.Text" TargetType="TextBlock">
    <Setter Property="FontSize" Value="11" />
    <Setter Property="FontWeight" Value="SemiBold" />
    <Setter Property="Foreground" Value="{StaticResource Accent}" />
  </Style>
  <Style x:Key="Label.Strong" TargetType="TextBlock" BasedOn="{StaticResource Label}">
    <Setter Property="FontWeight" Value="Bold" />
  </Style>
  <Style x:Key="Brand" TargetType="TextBlock">
    <Setter Property="FontSize" Value="12" />
    <Setter Property="FontWeight" Value="SemiBold" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Strong}" />
  </Style>
  <Style x:Key="Body" TargetType="TextBlock">
    <Setter Property="FontSize" Value="13" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Strong}" />
  </Style>
  <Style x:Key="Body.Strong" TargetType="TextBlock" BasedOn="{StaticResource Body}">
    <Setter Property="FontWeight" Value="Bold" />
  </Style>
  <Style x:Key="Nav" TargetType="TextBlock">
    <Setter Property="FontSize" Value="13" />
    <Setter Property="FontWeight" Value="Medium" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Strong}" />
  </Style>
  <Style x:Key="Nav.Tall" TargetType="TextBlock" BasedOn="{StaticResource Nav}">
    <Setter Property="LineHeight" Value="18" />
    <Setter Property="LineStackingStrategy" Value="BlockLineHeight" />
  </Style>
  <Style x:Key="PageTitle" TargetType="TextBlock">
    <Setter Property="FontSize" Value="16" />
    <Setter Property="FontWeight" Value="Bold" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Strong}" />
  </Style>
  <Style x:Key="Title" TargetType="TextBlock">
    <Setter Property="FontSize" Value="18" />
    <Setter Property="FontWeight" Value="SemiBold" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Strong}" />
  </Style>
  <Style x:Key="AppTitle" TargetType="TextBlock">
    <Setter Property="FontSize" Value="20" />
    <Setter Property="FontWeight" Value="SemiBold" />
    <Setter Property="LineHeight" Value="28" />
    <Setter Property="LineStackingStrategy" Value="BlockLineHeight" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Strong}" />
  </Style>

  <!-- ============ アイコン（Lucide v1.50.0（ISC ライセンス。Feather 由来の一部は MIT）の SVG を Geometry にしたもの。24x24 の座標のまま。
       使う側で Stretch=Uniform・Stroke・StrokeThickness（表示の大きさ × 2/24）・丸い端を指定する。
       Icon.Save は Lucide の download の形。ライセンス文は scripts/shared/licenses/ にある（単一 .ps1 では先頭のコメント） ============ -->
  <Geometry x:Key="Icon.Folder">M20 20a2 2 0 0 0 2-2V8a2 2 0 0 0-2-2h-7.9a2 2 0 0 1-1.69-.9L9.6 3.9A2 2 0 0 0 7.93 3H4a2 2 0 0 0-2 2v13a2 2 0 0 0 2 2Z</Geometry>
  <Geometry x:Key="Icon.FolderClosed">M20 20a2 2 0 0 0 2-2V8a2 2 0 0 0-2-2h-7.9a2 2 0 0 1-1.69-.9L9.6 3.9A2 2 0 0 0 7.93 3H4a2 2 0 0 0-2 2v13a2 2 0 0 0 2 2Z M2 10h20</Geometry>
  <Geometry x:Key="Icon.FolderOpen">m6 14 1.45-2.9A2 2 0 0 1 9.24 10H20a2 2 0 0 1 1.94 2.5l-1.55 6a2 2 0 0 1-1.94 1.5H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h3.9a2 2 0 0 1 1.69.9l.81 1.2a2 2 0 0 0 1.67.9H18a2 2 0 0 1 2 2v2</Geometry>
  <Geometry x:Key="Icon.ChevronDown">M6 9 L12 15 L18 9</Geometry>
  <Geometry x:Key="Icon.ChevronRight">M9 18 L15 12 L9 6</Geometry>
  <Geometry x:Key="Icon.RefreshCw">M3 12a9 9 0 0 1 9-9 9.75 9.75 0 0 1 6.74 2.74L21 8 M21 3v5h-5 M21 12a9 9 0 0 1-9 9 9.75 9.75 0 0 1-6.74-2.74L3 16 M8 16H3v5</Geometry>
  <Geometry x:Key="Icon.TriangleAlert">M21.73 18 L13.73 4a2 2 0 0 0-3.48 0 L2.27 18A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z M12 9v4 M12 17h.01</Geometry>
  <Geometry x:Key="Icon.File">M6 22a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h8a2.4 2.4 0 0 1 1.704.706l3.588 3.588A2.4 2.4 0 0 1 20 8v12a2 2 0 0 1-2 2z M14 2v5a1 1 0 0 0 1 1h5</Geometry>
  <Geometry x:Key="Icon.FileText">M6 22a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h8a2.4 2.4 0 0 1 1.704.706l3.588 3.588A2.4 2.4 0 0 1 20 8v12a2 2 0 0 1-2 2z M14 2v5a1 1 0 0 0 1 1h5 M10 9H8 M16 13H8 M16 17H8</Geometry>
  <Geometry x:Key="Icon.FolderSearch">M10.7 20H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h3.9a2 2 0 0 1 1.69.9l.81 1.2a2 2 0 0 0 1.67.9H20a2 2 0 0 1 2 2v4.1 M21 21 L19.1 19.1 M17 14a3 3 0 1 0 0.0001 0Z</Geometry>
  <Geometry x:Key="Icon.FileSpreadsheet">M6 22a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h8a2.4 2.4 0 0 1 1.704.706l3.588 3.588A2.4 2.4 0 0 1 20 8v12a2 2 0 0 1-2 2z M14 2v5a1 1 0 0 0 1 1h5 M8 13h2 M14 13h2 M8 17h2 M14 17h2</Geometry>
  <Geometry x:Key="Icon.Presentation">M2 3h20 M21 3v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V3 M7 21 L12 16 L17 21</Geometry>
  <Geometry x:Key="Icon.ChartColumn">M3 3v16a2 2 0 0 0 2 2h16 M18 17V9 M13 17V5 M8 17v-3</Geometry>
  <Geometry x:Key="Icon.Save">M12 15V3 M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4 M7 10 L12 15 L17 10</Geometry>
  <Geometry x:Key="Icon.StopCircle">M12 2a10 10 0 1 0 0.0001 0Z M10 9 L14 9 A1 1 0 0 1 15 10 L15 14 A1 1 0 0 1 14 15 L10 15 A1 1 0 0 1 9 14 L9 10 A1 1 0 0 1 10 9 Z</Geometry>
  <Geometry x:Key="Icon.Close">M18 6 L6 18 M6 6 L18 18</Geometry>
  <Geometry x:Key="Icon.CircleX">M12 2a10 10 0 1 0 0.0001 0Z M15 9 L9 15 M9 9 L15 15</Geometry>
  <Geometry x:Key="Icon.Search">M11 3a8 8 0 1 0 0.0001 0Z M21 21 L16.66 16.66</Geometry>
  <Geometry x:Key="Icon.CircleQuestionMark">M12 2a10 10 0 1 0 0.0001 0Z M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3 M12 17h.01</Geometry>
  <Geometry x:Key="Icon.Plus">M5 12h14 M12 5v14</Geometry>
  <Geometry x:Key="Icon.Check">M20 6 L9 17 L4 12</Geometry>
  <Geometry x:Key="Icon.Zap">M4 14a1 1 0 0 1-.78-1.63l9.9-10.2a.5.5 0 0 1 .86.46l-1.92 6.02A1 1 0 0 0 13 10h7a1 1 0 0 1 .78 1.63l-9.9 10.2a.5.5 0 0 1-.86-.46l1.92-6.02A1 1 0 0 0 11 14z</Geometry>
  <Geometry x:Key="Icon.Info">M12 2a10 10 0 1 0 0.0001 0Z M12 16v-4 M12 8h.01</Geometry>
  <Geometry x:Key="Icon.InfoCircle">M12 2a10 10 0 1 0 0.0001 0Z</Geometry>
  <Geometry x:Key="Icon.InfoGlyph.S12">M6,5.76 L6,8.4 M6,3.36 L6.01,3.36</Geometry>
  <Geometry x:Key="Icon.InfoGlyph.S13">M6.5,6.24 L6.5,9.1 M6.5,3.64 L6.51,3.64</Geometry>
  <Geometry x:Key="Icon.InfoGlyph.S14">M7,6.72 L7,9.8 M7,3.92 L7.01,3.92</Geometry>
  <Geometry x:Key="Icon.InfoGlyph.S16">M8,7.68 L8,11.2 M8,4.48 L8.01,4.48</Geometry>
  <Geometry x:Key="Icon.BadgeGlyphInfo">M12 16v-4 M12 8h.01</Geometry>
  <Geometry x:Key="Icon.BadgeGlyphWarn">M12 8v4 M12 16h.01</Geometry>
  <Geometry x:Key="Icon.BadgeGlyphError">M15 9 L9 15 M9 9 L15 15</Geometry>
  <Geometry x:Key="Icon.BadgeGlyphOk">M9 12 L11 14 L15 10</Geometry>
  <Geometry x:Key="Icon.CircleCheck">M12 2a10 10 0 1 0 0.0001 0Z M16 9 L10.5 14.5 L8 12</Geometry>
  <!-- Lucide ellipsis（行の［…］で使う） -->
  <Geometry x:Key="Icon.Ellipsis">M12 12a1 1 0 1 0 0.0001 0Z M19 12a1 1 0 1 0 0.0001 0Z M5 12a1 1 0 1 0 0.0001 0Z</Geometry>
  <Geometry x:Key="Icon.CircleAlert">M12 2a10 10 0 1 0 0.0001 0Z M12 8v4 M12 16h.01</Geometry>
  <Geometry x:Key="Icon.ArrowRight">M5 12h14 m12 5 7 7-7 7</Geometry>
  <!-- 図（空の状態の絵）。Icon.FolderSearch・Icon.CircleCheck を 24 の座標を 64 の大きさに拡げ、細い線（0.75）で描く Path の既定値 -->
  <Style x:Key="Illust.Path" TargetType="Path">
    <Setter Property="Width" Value="24" />
    <Setter Property="Height" Value="24" />
    <Setter Property="Stretch" Value="None" />
    <Setter Property="LayoutTransform">
      <Setter.Value>
        <ScaleTransform ScaleX="2.6666667" ScaleY="2.6666667" />
      </Setter.Value>
    </Setter>
    <Setter Property="Stroke" Value="{StaticResource Illust.Line}" />
    <Setter Property="StrokeThickness" Value="0.75" />
    <Setter Property="StrokeStartLineCap" Value="Round" />
    <Setter Property="StrokeEndLineCap" Value="Round" />
    <Setter Property="StrokeLineJoin" Value="Round" />
  </Style>

  <!-- ============ 小さな部品の Border・Ellipse の既定値（色は使う側で指定する） ============ -->
  <CornerRadius x:Key="Radius.Pill">12</CornerRadius>
  <!-- ファイルの種類の絞り込みの丸い札 -->
  <Style x:Key="Chip.Box" TargetType="Border">
    <Setter Property="CornerRadius" Value="{StaticResource Radius.Pill}" />
    <Setter Property="BorderThickness" Value="1" />
    <Setter Property="Padding" Value="8,4,8,4" />
  </Style>
  <!-- 左ナビの数・ドットの印 -->
  <Style x:Key="NavBadge.Count" TargetType="Border">
    <Setter Property="Background" Value="{StaticResource Bg.Tag}" />
    <Setter Property="CornerRadius" Value="8" />
    <Setter Property="Padding" Value="6,1,6,1" />
  </Style>
  <Style x:Key="NavBadge.Dot" TargetType="Ellipse">
    <Setter Property="Width" Value="6" />
    <Setter Property="Height" Value="6" />
  </Style>
  <!-- ナビ（左の欄）の項目。選んでいる項目は左に Accent の線・Select.Soft の地・Accent の太字にする。
       中の文字は Style を外した TextBlock にして、この項目の文字色・太さを受け継がせる -->
  <Style x:Key="Nav.List" TargetType="ListBox">
    <Setter Property="Background" Value="Transparent" />
    <Setter Property="BorderThickness" Value="0" />
    <Setter Property="Padding" Value="0" />
    <Setter Property="ScrollViewer.HorizontalScrollBarVisibility" Value="Disabled" />
    <Setter Property="ScrollViewer.VerticalScrollBarVisibility" Value="Disabled" />
    <Setter Property="KeyboardNavigation.TabNavigation" Value="Once" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="ListBox">
          <ItemsPresenter />
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
  <Style x:Key="NavItem" TargetType="ListBoxItem">
    <Setter Property="Height" Value="37" />
    <Setter Property="Padding" Value="31,0,12,0" />
    <Setter Property="FontSize" Value="13" />
    <Setter Property="FontWeight" Value="SemiBold" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Body}" />
    <Setter Property="HorizontalContentAlignment" Value="Stretch" />
    <Setter Property="VerticalContentAlignment" Value="Center" />
    <Setter Property="Focusable" Value="True" />
    <Setter Property="FocusVisualStyle" Value="{x:Null}" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="ListBoxItem">
          <Border x:Name="Bd" Background="Transparent" BorderBrush="Transparent" BorderThickness="3,0,0,0" SnapsToDevicePixels="True">
            <Grid>
              <Border x:Name="FocusRing" BorderBrush="{StaticResource Accent.Ring}" BorderThickness="1" Visibility="Collapsed" />
              <ContentPresenter Margin="{TemplateBinding Padding}"
                                HorizontalAlignment="{TemplateBinding HorizontalContentAlignment}"
                                VerticalAlignment="{TemplateBinding VerticalContentAlignment}" />
            </Grid>
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True">
              <Setter TargetName="Bd" Property="Background" Value="{StaticResource Bg.Hover}" />
            </Trigger>
            <Trigger Property="IsKeyboardFocused" Value="True">
              <Setter TargetName="FocusRing" Property="Visibility" Value="Visible" />
            </Trigger>
            <Trigger Property="IsSelected" Value="True">
              <Setter TargetName="Bd" Property="Background" Value="{StaticResource Select.Soft}" />
              <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource Accent}" />
              <Setter Property="Foreground" Value="{StaticResource Accent}" />
              <Setter Property="FontWeight" Value="Bold" />
            </Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
  <!-- 状態の札（インデックス・高速検索の 3 状態） -->
  <Style x:Key="StatusBadge" TargetType="Border">
    <Setter Property="CornerRadius" Value="8" />
    <Setter Property="BorderThickness" Value="1" />
    <Setter Property="Padding" Value="8,2,8,2" />
  </Style>
  <!-- 状態を丸いバッジで出す。Tag に Level（Ok / Wait / Warn / Ng / Run / None）を入れて、色だけ切り替える。状態の色の組は Badge.* にだけ置く -->
  <Style x:Key="LevelBadge" TargetType="Border" BasedOn="{StaticResource StatusBadge}">
    <Setter Property="HorizontalAlignment" Value="Left" />
    <Setter Property="VerticalAlignment" Value="Center" />
    <Setter Property="Background" Value="{StaticResource Badge.None.Bg}" />
    <Setter Property="BorderBrush" Value="Transparent" />
    <Style.Triggers>
      <DataTrigger Binding="{Binding RelativeSource={RelativeSource Self}, Path=Tag}" Value="Ok">
        <Setter Property="Background" Value="{StaticResource Badge.Ok.Bg}" />
      </DataTrigger>
      <DataTrigger Binding="{Binding RelativeSource={RelativeSource Self}, Path=Tag}" Value="Wait">
        <Setter Property="Background" Value="{StaticResource Badge.Wait.Bg}" />
      </DataTrigger>
      <DataTrigger Binding="{Binding RelativeSource={RelativeSource Self}, Path=Tag}" Value="Warn">
        <Setter Property="Background" Value="{StaticResource Badge.Warn.Bg}" />
      </DataTrigger>
      <DataTrigger Binding="{Binding RelativeSource={RelativeSource Self}, Path=Tag}" Value="Ng">
        <Setter Property="Background" Value="{StaticResource Badge.Ng.Bg}" />
      </DataTrigger>
      <DataTrigger Binding="{Binding RelativeSource={RelativeSource Self}, Path=Tag}" Value="Run">
        <Setter Property="Background" Value="{StaticResource Badge.Run.Bg}" />
      </DataTrigger>
    </Style.Triggers>
  </Style>
  <Style x:Key="LevelBadgeText" TargetType="TextBlock">
    <Setter Property="FontSize" Value="11" />
    <Setter Property="FontWeight" Value="SemiBold" />
    <Setter Property="Foreground" Value="{StaticResource Badge.None.Text}" />
    <Setter Property="TextWrapping" Value="NoWrap" />
    <Setter Property="TextTrimming" Value="CharacterEllipsis" />
    <Style.Triggers>
      <DataTrigger Binding="{Binding RelativeSource={RelativeSource Self}, Path=Tag}" Value="Ok">
        <Setter Property="Foreground" Value="{StaticResource Badge.Ok.Text}" />
      </DataTrigger>
      <DataTrigger Binding="{Binding RelativeSource={RelativeSource Self}, Path=Tag}" Value="Wait">
        <Setter Property="Foreground" Value="{StaticResource Badge.Wait.Text}" />
      </DataTrigger>
      <DataTrigger Binding="{Binding RelativeSource={RelativeSource Self}, Path=Tag}" Value="Warn">
        <Setter Property="Foreground" Value="{StaticResource Badge.Warn.Text}" />
      </DataTrigger>
      <DataTrigger Binding="{Binding RelativeSource={RelativeSource Self}, Path=Tag}" Value="Ng">
        <Setter Property="Foreground" Value="{StaticResource Badge.Ng.Text}" />
      </DataTrigger>
      <DataTrigger Binding="{Binding RelativeSource={RelativeSource Self}, Path=Tag}" Value="Run">
        <Setter Property="Foreground" Value="{StaticResource Badge.Run.Text}" />
      </DataTrigger>
    </Style.Triggers>
  </Style>
  <!-- 帯（バナー）。幅いっぱいの 1 行（高さ 40）。角丸・外枠は無く、左端に太い線を引く。地と線（BorderBrush）の色は使う側で状態ごとに指定する（Badge.Run.Bg / Accent、Warn.Soft / Warn、Ok.Soft / Ok、Danger.Soft / Danger.Text）。文字の色は下の Banner.*.Text -->
  <SolidColorBrush x:Key="Banner.Info.Text" Color="#0B3D66" />
  <SolidColorBrush x:Key="Banner.Warn.Text" Color="#5C3D00" />
  <SolidColorBrush x:Key="Banner.Ok.Text"   Color="#124D12" />
  <SolidColorBrush x:Key="Banner.Ng.Text"   Color="#7A1C1F" />
  <Style x:Key="Banner" TargetType="Border">
    <Setter Property="BorderThickness" Value="3,0,0,0" />
    <Setter Property="CornerRadius" Value="0" />
    <Setter Property="MinHeight" Value="40" />
    <Setter Property="Padding" Value="13,8,12,8" />
  </Style>

  <!-- 注意・エラー。色で区別し、太さは上げない -->
  <Style x:Key="WarnText" TargetType="TextBlock">
    <Setter Property="FontSize" Value="12" />
    <Setter Property="Foreground" Value="{StaticResource Warn}" />
    <Setter Property="TextWrapping" Value="Wrap" />
  </Style>
  <Style x:Key="ErrorText" TargetType="TextBlock">
    <Setter Property="FontSize" Value="12" />
    <Setter Property="Foreground" Value="{StaticResource Danger.Text}" />
    <Setter Property="TextWrapping" Value="Wrap" />
  </Style>

  <!-- 入力前の案内（入力欄に重ねる） -->
  <Style x:Key="Placeholder" TargetType="TextBlock">
    <Setter Property="FontSize" Value="13" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Faint}" />
    <Setter Property="IsHitTestVisible" Value="False" />
    <Setter Property="VerticalAlignment" Value="Center" />
    <Setter Property="Margin" Value="10,0" />
  </Style>

  <!-- 表のセル。主キーの列だけ濃くし、目で追う列を 1 本に絞る -->
  <Style x:Key="Cell" TargetType="TextBlock">
    <Setter Property="FontSize" Value="12" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Body}" />
    <Setter Property="TextTrimming" Value="CharacterEllipsis" />
  </Style>
  <Style x:Key="Cell.Key" TargetType="TextBlock" BasedOn="{StaticResource Cell}">
    <Setter Property="FontWeight" Value="Medium" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Strong}" />
  </Style>
  <Style x:Key="Cell.Meta" TargetType="TextBlock" BasedOn="{StaticResource Cell}">
    <Setter Property="Foreground" Value="{StaticResource Ink.Muted}" />
  </Style>
  <Style x:Key="Cell.Number" TargetType="TextBlock" BasedOn="{StaticResource Cell}">
    <Setter Property="TextAlignment" Value="Right" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Muted}" />
  </Style>
  <!-- 旧名。既存の画面が RightCell を参照しているため残す -->
  <Style x:Key="RightCell" TargetType="TextBlock" BasedOn="{StaticResource Cell.Number}" />

  <!-- ============ カード（区切りは影ではなく枠と背景の差で出す） ============ -->
  <Style x:Key="Card" TargetType="Border">
    <Setter Property="Background" Value="{StaticResource Bg.Surface}" />
    <Setter Property="BorderBrush" Value="{StaticResource Border.Soft}" />
    <Setter Property="BorderThickness" Value="1" />
    <Setter Property="CornerRadius" Value="{StaticResource Radius.Card}" />
    <Setter Property="Padding" Value="16" />
  </Style>

  <!-- ============ ボタン ============ -->
  <ControlTemplate x:Key="ButtonTemplate" TargetType="Button">
    <Border x:Name="Ring" CornerRadius="7" Padding="1" Background="Transparent">
      <Border x:Name="Bd"
              Background="{TemplateBinding Background}"
              BorderBrush="{TemplateBinding BorderBrush}"
              BorderThickness="1"
              CornerRadius="{StaticResource Radius.Control}"
              Padding="{TemplateBinding Padding}"
              SnapsToDevicePixels="True">
        <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" />
      </Border>
    </Border>
    <ControlTemplate.Triggers>
      <Trigger Property="IsPressed" Value="True">
        <Setter TargetName="Bd" Property="Opacity" Value="0.82" />
      </Trigger>
      <Trigger Property="IsKeyboardFocused" Value="True">
        <Setter TargetName="Ring" Property="Background" Value="{StaticResource Accent.Ring}" />
      </Trigger>
      <Trigger Property="IsEnabled" Value="False">
        <Setter TargetName="Bd" Property="Opacity" Value="0.45" />
      </Trigger>
    </ControlTemplate.Triggers>
  </ControlTemplate>

  <!-- 普通のボタンは太字にしない（太字が散ると、押す先が 1 つに見えなくなる） -->
  <Style x:Key="Button.Base" TargetType="Button">
    <Setter Property="Template" Value="{StaticResource ButtonTemplate}" />
    <Setter Property="MinWidth" Value="88" />
    <Setter Property="Height" Value="30" />
    <Setter Property="Padding" Value="12,0" />
    <Setter Property="FontSize" Value="12" />
    <Setter Property="Background" Value="{StaticResource Bg.Surface}" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Body}" />
    <Setter Property="BorderBrush" Value="{StaticResource Border.Normal}" />
    <Setter Property="Cursor" Value="Hand" />
    <Style.Triggers>
      <Trigger Property="IsMouseOver" Value="True">
        <Setter Property="Background" Value="{StaticResource Bg.Hover}" />
        <Setter Property="Foreground" Value="{StaticResource Ink.Strong}" />
      </Trigger>
      <Trigger Property="IsPressed" Value="True">
        <Setter Property="Background" Value="{StaticResource Bg.Pressed}" />
      </Trigger>
    </Style.Triggers>
  </Style>
  <Style TargetType="Button" BasedOn="{StaticResource Button.Base}" />

  <!-- 主ボタンだけ塗り＋太字。画面に 1 つ -->
  <Style x:Key="Primary" TargetType="Button" BasedOn="{StaticResource Button.Base}">
    <Setter Property="FontSize" Value="13" />
    <Setter Property="FontWeight" Value="SemiBold" />
    <Setter Property="Background" Value="{StaticResource Accent}" />
    <Setter Property="Foreground" Value="{StaticResource Ink.OnAccent}" />
    <Setter Property="BorderBrush" Value="{StaticResource Accent}" />
    <Style.Triggers>
      <Trigger Property="IsMouseOver" Value="True">
        <Setter Property="Background" Value="{StaticResource Accent.Hover}" />
        <Setter Property="BorderBrush" Value="{StaticResource Accent.Hover}" />
        <Setter Property="Foreground" Value="{StaticResource Ink.OnAccent}" />
      </Trigger>
    </Style.Triggers>
  </Style>

  <!-- 消す操作。赤は文字と枠だけに使い、面で塗らない -->
  <Style x:Key="Danger" TargetType="Button" BasedOn="{StaticResource Button.Base}">
    <Setter Property="Foreground" Value="{StaticResource Danger.Text}" />
    <Setter Property="BorderBrush" Value="{StaticResource Danger.Line}" />
    <Style.Triggers>
      <Trigger Property="IsMouseOver" Value="True">
        <Setter Property="Background" Value="{StaticResource Danger.Soft}" />
        <Setter Property="BorderBrush" Value="{StaticResource Danger.Text}" />
        <Setter Property="Foreground" Value="{StaticResource Danger.Text}" />
      </Trigger>
    </Style.Triggers>
  </Style>

  <!-- ダイアログの「削除する」など、取り消せない操作の実行ボタン。確認のダイアログでだけ、赤で塗る -->
  <SolidColorBrush x:Key="Danger.Hover" Color="#B3262A" />
  <Style x:Key="Danger.Filled" TargetType="Button" BasedOn="{StaticResource Button.Base}">
    <Setter Property="FontSize" Value="13" />
    <Setter Property="FontWeight" Value="SemiBold" />
    <Setter Property="Background" Value="{StaticResource Danger.Text}" />
    <Setter Property="Foreground" Value="{StaticResource Ink.OnAccent}" />
    <Setter Property="BorderBrush" Value="{StaticResource Danger.Text}" />
    <Style.Triggers>
      <Trigger Property="IsMouseOver" Value="True">
        <Setter Property="Background" Value="{StaticResource Danger.Hover}" />
        <Setter Property="BorderBrush" Value="{StaticResource Danger.Hover}" />
        <Setter Property="Foreground" Value="{StaticResource Ink.OnAccent}" />
      </Trigger>
    </Style.Triggers>
  </Style>

  <!-- 文字だけのボタン -->
  <Style x:Key="Link" TargetType="Button">
    <Setter Property="Cursor" Value="Hand" />
    <Setter Property="Foreground" Value="{StaticResource Accent}" />
    <Setter Property="FontSize" Value="12" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="Button">
          <Border x:Name="Ring" CornerRadius="5" Padding="2,1" Background="Transparent">
            <TextBlock x:Name="T" Text="{Binding Content, RelativeSource={RelativeSource TemplatedParent}}"
                       FontSize="{TemplateBinding FontSize}"
                       Foreground="{TemplateBinding Foreground}" VerticalAlignment="Center" />
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True">
              <Setter TargetName="T" Property="TextDecorations" Value="Underline" />
            </Trigger>
            <Trigger Property="IsKeyboardFocused" Value="True">
              <Setter TargetName="Ring" Property="Background" Value="{StaticResource Accent.Ring}" />
            </Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>

  <!-- 帯の中のボタン。白地に帯の状態色の枠と文字、小さい角丸、半太字。
       枠と文字の色は帯の状態で変わるので、使う側が状態ごとに付ける。
       見える枠（Bd）の高さが Height（24）になるよう、フォーカスの輪（Ring）を Margin=-1 で外へ出す -->
  <Style x:Key="Banner.Button" TargetType="Button">
    <Setter Property="Cursor" Value="Hand" />
    <Setter Property="MinWidth" Value="64" />
    <Setter Property="Height" Value="24" />
    <Setter Property="Padding" Value="10,4" />
    <Setter Property="FontSize" Value="11" />
    <Setter Property="FontWeight" Value="SemiBold" />
    <Setter Property="Background" Value="{StaticResource Bg.Surface}" />
    <Setter Property="Foreground" Value="{StaticResource Accent}" />
    <Setter Property="BorderBrush" Value="{StaticResource Accent}" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="Button">
          <Border x:Name="Ring" CornerRadius="5" Padding="1" Margin="-1" Background="Transparent">
            <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}"
                    BorderThickness="1" CornerRadius="4" Padding="{TemplateBinding Padding}" SnapsToDevicePixels="True">
              <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center" />
            </Border>
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True">
              <Setter TargetName="Bd" Property="Opacity" Value="0.8" />
            </Trigger>
            <Trigger Property="IsPressed" Value="True">
              <Setter TargetName="Bd" Property="Opacity" Value="0.65" />
            </Trigger>
            <Trigger Property="IsKeyboardFocused" Value="True">
              <Setter TargetName="Ring" Property="Background" Value="{StaticResource Accent.Ring}" />
            </Trigger>
            <Trigger Property="IsEnabled" Value="False">
              <Setter TargetName="Bd" Property="Opacity" Value="0.45" />
            </Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>

  <!-- 帯の閉じるボタン（×）。枠なしの 24 角。×の色（Foreground）は帯の状態で変わるので、使う側が状態ごとに付ける。
       中身は付けず、Foreground の色で×を描く -->
  <Style x:Key="Banner.Close" TargetType="Button">
    <Setter Property="Cursor" Value="Hand" />
    <Setter Property="Width" Value="24" />
    <Setter Property="Height" Value="24" />
    <Setter Property="Foreground" Value="{StaticResource Banner.Info.Text}" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="Button">
          <Border x:Name="Ring" CornerRadius="4" Background="Transparent">
            <Path Data="{StaticResource Icon.Close}" Width="10" Height="10" Stretch="Uniform"
                  Stroke="{TemplateBinding Foreground}" StrokeThickness="1.2" StrokeStartLineCap="Round" StrokeEndLineCap="Round"
                  HorizontalAlignment="Center" VerticalAlignment="Center" />
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True">
              <Setter TargetName="Ring" Property="Background" Value="#14000000" />
            </Trigger>
            <Trigger Property="IsKeyboardFocused" Value="True">
              <Setter TargetName="Ring" Property="Background" Value="{StaticResource Accent.Ring}" />
            </Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>

  <!-- 選択肢のボタン。1 行目に動作、2 行目にその結果 -->
  <Style x:Key="Choice" TargetType="Button">
    <Setter Property="Cursor" Value="Hand" />
    <Setter Property="Background" Value="{StaticResource Bg.Surface}" />
    <Setter Property="BorderBrush" Value="{StaticResource Border.Normal}" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Body}" />
    <Setter Property="Padding" Value="14,11" />
    <Setter Property="Margin" Value="0,0,0,8" />
    <Setter Property="HorizontalContentAlignment" Value="Stretch" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="Button">
          <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}"
                  BorderThickness="1" CornerRadius="{StaticResource Radius.Control}" Padding="{TemplateBinding Padding}">
            <ContentPresenter HorizontalAlignment="Left" VerticalAlignment="Center" />
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True">
              <Setter TargetName="Bd" Property="Background" Value="{StaticResource Accent.Soft}" />
              <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource Accent}" />
            </Trigger>
            <Trigger Property="IsKeyboardFocused" Value="True">
              <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource Accent}" />
              <Setter TargetName="Bd" Property="BorderThickness" Value="2" />
              <Setter TargetName="Bd" Property="Padding" Value="13,10" />
            </Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>

  <!-- ダイアログの下部に並ぶボタン（間隔を空ける） -->
  <Style x:Key="DialogButton" TargetType="Button" BasedOn="{StaticResource Button.Base}">
    <Setter Property="MinWidth" Value="104" />
    <Setter Property="Margin" Value="8,0,0,0" />
  </Style>

  <!-- アドレスバーの ← → ↑ -->
  <Style x:Key="ToolButton" TargetType="Button" BasedOn="{StaticResource Button.Base}">
    <Setter Property="MinWidth" Value="32" />
    <Setter Property="Width" Value="32" />
    <Setter Property="Padding" Value="0" />
    <Setter Property="Margin" Value="0,0,4,0" />
    <Setter Property="FontSize" Value="14" />
  </Style>

  <!-- ============ 入力欄 ============ -->
  <Style x:Key="TextBox.Base" TargetType="TextBox">
    <Setter Property="Height" Value="30" />
    <Setter Property="Padding" Value="9,0" />
    <Setter Property="FontSize" Value="13" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Strong}" />
    <Setter Property="CaretBrush" Value="{StaticResource Ink.Strong}" />
    <Setter Property="SelectionBrush" Value="{StaticResource Select.Text}" />
    <Setter Property="SelectionOpacity" Value="0.4" />
    <Setter Property="Background" Value="{StaticResource Bg.Surface}" />
    <Setter Property="BorderBrush" Value="{StaticResource Border.Normal}" />
    <Setter Property="VerticalContentAlignment" Value="Center" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="TextBox">
          <Border x:Name="Ring" CornerRadius="7" Padding="1" Background="Transparent">
            <Border x:Name="Bd" Background="{TemplateBinding Background}"
                    BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="1"
                    CornerRadius="{StaticResource Radius.Control}">
              <ScrollViewer x:Name="PART_ContentHost" Margin="{TemplateBinding Padding}"
                            VerticalAlignment="Center" Focusable="False" HorizontalScrollBarVisibility="Hidden" />
            </Border>
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True">
              <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource Ink.Faint}" />
            </Trigger>
            <Trigger Property="IsKeyboardFocusWithin" Value="True">
              <Setter TargetName="Ring" Property="Background" Value="{StaticResource Accent.Ring}" />
              <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource Accent}" />
            </Trigger>
            <Trigger Property="IsEnabled" Value="False">
              <Setter TargetName="Bd" Property="Background" Value="{StaticResource Bg.Hover}" />
              <Setter Property="Foreground" Value="{StaticResource Ink.Faint}" />
            </Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
  <Style TargetType="TextBox" BasedOn="{StaticResource TextBox.Base}" />

  <!-- ============ チェックボックス ============ -->
  <Style TargetType="CheckBox">
    <Setter Property="FontSize" Value="12" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Body}" />
    <Setter Property="Cursor" Value="Hand" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="CheckBox">
          <StackPanel Orientation="Horizontal" Background="Transparent">
            <Border x:Name="Ring" CornerRadius="6" Padding="1" Background="Transparent" VerticalAlignment="Center">
              <Border x:Name="Box" Width="16" Height="16" CornerRadius="4"
                      Background="{StaticResource Bg.Surface}" BorderBrush="{StaticResource Border.Check}" BorderThickness="1">
                <Grid>
                  <Path x:Name="Check" Visibility="Collapsed" Stretch="Uniform" Margin="3"
                        Stroke="{StaticResource Ink.OnAccent}" StrokeThickness="2" StrokeEndLineCap="Round" StrokeStartLineCap="Round"
                        Data="M 0,4 L 3.2,7.2 L 9,1" />
                  <Rectangle x:Name="Mid" Visibility="Collapsed" Width="8" Height="2" RadiusX="1" RadiusY="1" Fill="{StaticResource Ink.OnAccent}"
                             HorizontalAlignment="Center" VerticalAlignment="Center" />
                </Grid>
              </Border>
            </Border>
            <ContentPresenter x:Name="Label" Margin="7,0,0,0" VerticalAlignment="Center" RecognizesAccessKey="True" />
          </StackPanel>
          <ControlTemplate.Triggers>
            <Trigger Property="IsChecked" Value="True">
              <Setter TargetName="Box" Property="Background" Value="{StaticResource Accent}" />
              <Setter TargetName="Box" Property="BorderBrush" Value="{StaticResource Accent}" />
              <Setter TargetName="Check" Property="Visibility" Value="Visible" />
            </Trigger>
            <Trigger Property="IsChecked" Value="{x:Null}">
              <Setter TargetName="Box" Property="Background" Value="{StaticResource Accent}" />
              <Setter TargetName="Box" Property="BorderBrush" Value="{StaticResource Accent}" />
              <Setter TargetName="Mid" Property="Visibility" Value="Visible" />
            </Trigger>
            <Trigger Property="IsMouseOver" Value="True">
              <Setter TargetName="Box" Property="BorderBrush" Value="{StaticResource Accent}" />
              <Setter Property="Foreground" Value="{StaticResource Ink.Strong}" />
            </Trigger>
            <Trigger Property="IsKeyboardFocused" Value="True">
              <Setter TargetName="Ring" Property="Background" Value="{StaticResource Accent.Ring}" />
            </Trigger>
            <Trigger Property="IsEnabled" Value="False">
              <Setter Property="Opacity" Value="0.45" />
            </Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>

  <!-- ============ スクロールバー（細身・角丸・トラック透明） ============ -->
  <Style x:Key="ScrollThumb" TargetType="Thumb">
    <Setter Property="IsTabStop" Value="False" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="Thumb">
          <Border x:Name="T" Background="#CBD0D6" CornerRadius="4" Margin="3" />
          <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True">
              <Setter TargetName="T" Property="Background" Value="#A3ABB5" />
            </Trigger>
            <Trigger Property="IsDragging" Value="True">
              <Setter TargetName="T" Property="Background" Value="#78828F" />
            </Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
  <Style x:Key="ScrollHidden" TargetType="RepeatButton">
    <Setter Property="Opacity" Value="0" />
    <Setter Property="Focusable" Value="False" />
    <Setter Property="IsTabStop" Value="False" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="RepeatButton"><Border Background="Transparent" /></ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
  <Style TargetType="ScrollBar">
    <Setter Property="Background" Value="Transparent" />
    <Setter Property="Width" Value="12" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="ScrollBar">
          <Grid Background="Transparent">
            <Track x:Name="PART_Track" IsDirectionReversed="True">
              <Track.DecreaseRepeatButton>
                <RepeatButton Style="{StaticResource ScrollHidden}" Command="ScrollBar.PageUpCommand" />
              </Track.DecreaseRepeatButton>
              <Track.Thumb>
                <Thumb Style="{StaticResource ScrollThumb}" />
              </Track.Thumb>
              <Track.IncreaseRepeatButton>
                <RepeatButton Style="{StaticResource ScrollHidden}" Command="ScrollBar.PageDownCommand" />
              </Track.IncreaseRepeatButton>
            </Track>
          </Grid>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
    <Style.Triggers>
      <Trigger Property="Orientation" Value="Horizontal">
        <Setter Property="Width" Value="Auto" />
        <Setter Property="Height" Value="12" />
        <Setter Property="Template">
          <Setter.Value>
            <ControlTemplate TargetType="ScrollBar">
              <Grid Background="Transparent">
                <Track x:Name="PART_Track" IsDirectionReversed="False">
                  <Track.DecreaseRepeatButton>
                    <RepeatButton Style="{StaticResource ScrollHidden}" Command="ScrollBar.PageLeftCommand" />
                  </Track.DecreaseRepeatButton>
                  <Track.Thumb>
                    <Thumb Style="{StaticResource ScrollThumb}" />
                  </Track.Thumb>
                  <Track.IncreaseRepeatButton>
                    <RepeatButton Style="{StaticResource ScrollHidden}" Command="ScrollBar.PageRightCommand" />
                  </Track.IncreaseRepeatButton>
                </Track>
              </Grid>
            </ControlTemplate>
          </Setter.Value>
        </Setter>
      </Trigger>
    </Style.Triggers>
  </Style>

  <!-- ============ タブ（今の画面は使わない。左のナビで切り替える。立体をやめ、選択タブは下線で示す） ============ -->
  <Style TargetType="TabItem">
    <Setter Property="FontSize" Value="13" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Muted}" />
    <Setter Property="Cursor" Value="Hand" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="TabItem">
          <Grid Background="Transparent" Margin="0,0,4,0">
            <Border x:Name="Bd" Background="Transparent" BorderBrush="Transparent" BorderThickness="1"
                    CornerRadius="8,8,0,0" Padding="15,8">
              <ContentPresenter ContentSource="Header" VerticalAlignment="Center" />
            </Border>
            <Border x:Name="Line" Height="2" VerticalAlignment="Bottom" Margin="8,0" CornerRadius="1" Background="Transparent" />
          </Grid>
          <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True">
              <Setter TargetName="Bd" Property="Background" Value="{StaticResource Bg.Hover}" />
              <Setter Property="Foreground" Value="{StaticResource Ink.Strong}" />
            </Trigger>
            <Trigger Property="IsSelected" Value="True">
              <Setter TargetName="Line" Property="Background" Value="{StaticResource Accent}" />
              <Setter TargetName="Bd" Property="Background" Value="Transparent" />
              <Setter Property="Foreground" Value="{StaticResource Accent}" />
              <Setter Property="FontWeight" Value="SemiBold" />
            </Trigger>
            <Trigger Property="IsKeyboardFocusWithin" Value="True">
              <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource Accent.Ring}" />
            </Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
  <Style TargetType="TabControl">
    <Setter Property="Background" Value="Transparent" />
    <Setter Property="BorderThickness" Value="0" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="TabControl">
          <DockPanel>
            <Border DockPanel.Dock="Top" BorderBrush="{StaticResource Border.Soft}" BorderThickness="0,0,0,1">
              <TabPanel IsItemsHost="True" Panel.ZIndex="1" Margin="0,0,0,-1" />
            </Border>
            <ContentPresenter x:Name="PART_SelectedContentHost" ContentSource="SelectedContent" Margin="0,14,0,0" />
          </DockPanel>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>

  <!-- ============ 表 ============ -->
  <Style TargetType="DataGrid">
    <Setter Property="AutoGenerateColumns" Value="False" />
    <Setter Property="IsReadOnly" Value="True" />
    <Setter Property="HeadersVisibility" Value="Column" />
    <Setter Property="GridLinesVisibility" Value="None" />
    <Setter Property="BorderThickness" Value="0" />
    <Setter Property="Background" Value="{StaticResource Bg.Surface}" />
    <Setter Property="RowHeaderWidth" Value="0" />
    <Setter Property="RowHeight" Value="30" />
    <Setter Property="FontSize" Value="12" />
    <Setter Property="SelectionMode" Value="Extended" />
    <Setter Property="CanUserReorderColumns" Value="False" />
    <Setter Property="EnableRowVirtualization" Value="True" />
    <Setter Property="VirtualizingPanel.IsVirtualizing" Value="True" />
    <Setter Property="VirtualizingPanel.VirtualizationMode" Value="Recycling" />
  </Style>
  <!-- 列見出しは「読むもの」ではなく「位置を示す札」。小さく・薄く・太らせない -->
  <Style TargetType="DataGridColumnHeader">
    <Setter Property="Background" Value="{StaticResource Bg.Subtle}" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Muted}" />
    <Setter Property="FontSize" Value="11" />
    <Setter Property="Padding" Value="10,7" />
    <Setter Property="BorderBrush" Value="{StaticResource Border.Soft}" />
    <Setter Property="BorderThickness" Value="0,0,0,1" />
    <Setter Property="HorizontalContentAlignment" Value="Left" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="DataGridColumnHeader">
          <Border Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}"
                  BorderThickness="{TemplateBinding BorderThickness}" Padding="{TemplateBinding Padding}">
            <ContentPresenter VerticalAlignment="Center" />
          </Border>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
  <Style TargetType="DataGridRow">
    <Setter Property="Background" Value="{StaticResource Bg.Surface}" />
    <Setter Property="BorderBrush" Value="{StaticResource Border.Soft}" />
    <Setter Property="BorderThickness" Value="0,0,0,1" />
    <Style.Triggers>
      <Trigger Property="IsMouseOver" Value="True">
        <Setter Property="Background" Value="{StaticResource Bg.Hover}" />
      </Trigger>
      <Trigger Property="IsSelected" Value="True">
        <Setter Property="Background" Value="{StaticResource Accent.Soft}" />
      </Trigger>
    </Style.Triggers>
  </Style>
  <Style TargetType="DataGridCell">
    <Setter Property="Padding" Value="10,0" />
    <Setter Property="FontSize" Value="12" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Body}" />
    <Setter Property="BorderThickness" Value="0" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="DataGridCell">
          <Border Background="Transparent" Padding="{TemplateBinding Padding}">
            <ContentPresenter VerticalAlignment="Center" />
          </Border>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>

  <!-- ============ ツリー（既定の三角をシェブロンに） ============ -->
  <Style x:Key="TreeChevron" TargetType="ToggleButton">
    <Setter Property="Focusable" Value="False" />
    <Setter Property="Width" Value="18" />
    <Setter Property="Height" Value="18" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="ToggleButton">
          <Border Background="Transparent" Width="18" Height="18">
            <Path x:Name="Arrow" Data="M 0,0 L 4,4 L 0,8" Stroke="{StaticResource Ink.Faint}" StrokeThickness="1.6"
                  StrokeEndLineCap="Round" StrokeStartLineCap="Round"
                  HorizontalAlignment="Center" VerticalAlignment="Center" RenderTransformOrigin="0.4,0.5" />
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsChecked" Value="True">
              <Setter TargetName="Arrow" Property="RenderTransform">
                <Setter.Value>
                  <RotateTransform Angle="90" />
                </Setter.Value>
              </Setter>
            </Trigger>
            <Trigger Property="IsMouseOver" Value="True">
              <Setter TargetName="Arrow" Property="Stroke" Value="{StaticResource Ink.Strong}" />
            </Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
  <Style x:Key="TreeViewItem.Base" TargetType="TreeViewItem">
    <Setter Property="Foreground" Value="{StaticResource Ink.Body}" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="TreeViewItem">
          <StackPanel>
            <Border x:Name="Bd" CornerRadius="6" Background="Transparent" BorderBrush="Transparent" BorderThickness="1" Padding="2,1">
              <Grid>
                <Grid.ColumnDefinitions>
                  <ColumnDefinition Width="18" />
                  <ColumnDefinition Width="*" />
                </Grid.ColumnDefinitions>
                <ToggleButton x:Name="Expander" Grid.Column="0" Style="{StaticResource TreeChevron}"
                              IsChecked="{Binding IsExpanded, RelativeSource={RelativeSource TemplatedParent}}"
                              ClickMode="Press" />
                <ContentPresenter x:Name="PART_Header" Grid.Column="1" ContentSource="Header" VerticalAlignment="Center" />
              </Grid>
            </Border>
            <ItemsPresenter x:Name="ItemsHost" Margin="16,0,0,0" />
          </StackPanel>
          <ControlTemplate.Triggers>
            <Trigger Property="IsExpanded" Value="False">
              <Setter TargetName="ItemsHost" Property="Visibility" Value="Collapsed" />
            </Trigger>
            <Trigger Property="HasItems" Value="False">
              <Setter TargetName="Expander" Property="Visibility" Value="Hidden" />
            </Trigger>
            <Trigger Property="IsMouseOver" Value="True">
              <Setter TargetName="Bd" Property="Background" Value="{StaticResource Bg.Hover}" />
            </Trigger>
            <Trigger Property="IsSelected" Value="True">
              <Setter TargetName="Bd" Property="Background" Value="{StaticResource Accent.Soft}" />
            </Trigger>
            <Trigger Property="IsKeyboardFocused" Value="True">
              <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource Accent.Ring}" />
            </Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
  <Style TargetType="TreeViewItem" BasedOn="{StaticResource TreeViewItem.Base}" />
  <Style TargetType="TreeView">
    <Setter Property="Background" Value="{StaticResource Bg.Surface}" />
    <Setter Property="BorderBrush" Value="{StaticResource Border.Soft}" />
    <Setter Property="BorderThickness" Value="1" />
    <Setter Property="Padding" Value="6" />
    <!-- 長い名前があっても横スクロールにしない（横にずれると左端の名前が隠れて読めなくなる）。
         入りきらない名前は … で省く -->
    <Setter Property="ScrollViewer.HorizontalScrollBarVisibility" Value="Disabled" />
  </Style>

  <!-- ============ 選択肢（開き方） ============ -->
  <Style TargetType="ComboBoxItem">
    <Setter Property="FontSize" Value="12" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Body}" />
    <Setter Property="Padding" Value="10,6" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="ComboBoxItem">
          <Border x:Name="Bd" Background="Transparent" CornerRadius="4" Margin="3,1" Padding="{TemplateBinding Padding}">
            <ContentPresenter VerticalAlignment="Center" />
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsHighlighted" Value="True">
              <Setter TargetName="Bd" Property="Background" Value="{StaticResource Accent.Soft}" />
            </Trigger>
            <Trigger Property="IsSelected" Value="True">
              <Setter TargetName="Bd" Property="Background" Value="{StaticResource Accent.Soft}" />
              <Setter Property="Foreground" Value="{StaticResource Ink.Strong}" />
            </Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
  <Style TargetType="ComboBox">
    <Setter Property="Height" Value="30" />
    <Setter Property="FontSize" Value="12" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Body}" />
    <Setter Property="Background" Value="{StaticResource Bg.Surface}" />
    <Setter Property="BorderBrush" Value="{StaticResource Border.Normal}" />
    <Setter Property="Cursor" Value="Hand" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="ComboBox">
          <Border x:Name="Ring" CornerRadius="7" Padding="1" Background="Transparent">
            <Grid>
              <ToggleButton x:Name="Toggle" Focusable="False" ClickMode="Press"
                            IsChecked="{Binding IsDropDownOpen, Mode=TwoWay, RelativeSource={RelativeSource TemplatedParent}}">
                <ToggleButton.Template>
                  <ControlTemplate TargetType="ToggleButton">
                    <Border x:Name="Bd" Background="{StaticResource Bg.Surface}" BorderBrush="{StaticResource Border.Normal}"
                            BorderThickness="1" CornerRadius="{StaticResource Radius.Control}">
                      <Path x:Name="Arrow" HorizontalAlignment="Right" VerticalAlignment="Center" Margin="0,0,10,0"
                            Data="M 0,0 L 4,4 L 8,0" Stroke="{StaticResource Ink.Muted}" StrokeThickness="1.6"
                            StrokeEndLineCap="Round" StrokeStartLineCap="Round" />
                    </Border>
                    <ControlTemplate.Triggers>
                      <Trigger Property="IsMouseOver" Value="True">
                        <Setter TargetName="Bd" Property="Background" Value="{StaticResource Bg.Hover}" />
                        <Setter TargetName="Arrow" Property="Stroke" Value="{StaticResource Ink.Strong}" />
                      </Trigger>
                      <Trigger Property="IsChecked" Value="True">
                        <Setter TargetName="Bd" Property="BorderBrush" Value="{StaticResource Accent}" />
                      </Trigger>
                    </ControlTemplate.Triggers>
                  </ControlTemplate>
                </ToggleButton.Template>
              </ToggleButton>
              <ContentPresenter Content="{TemplateBinding SelectionBoxItem}"
                                ContentTemplate="{TemplateBinding SelectionBoxItemTemplate}"
                                Margin="10,0,26,0" VerticalAlignment="Center" IsHitTestVisible="False" />
              <Popup x:Name="PART_Popup" AllowsTransparency="True" Placement="Bottom"
                     IsOpen="{TemplateBinding IsDropDownOpen}" Focusable="False" PopupAnimation="Fade">
                <Border Background="{StaticResource Bg.Surface}" BorderBrush="{StaticResource Border.Normal}"
                        BorderThickness="1" CornerRadius="{StaticResource Radius.Control}" Margin="0,2,0,0"
                        MinWidth="{TemplateBinding ActualWidth}" MaxHeight="{TemplateBinding MaxDropDownHeight}">
                  <ScrollViewer>
                    <ItemsPresenter />
                  </ScrollViewer>
                </Border>
              </Popup>
            </Grid>
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsKeyboardFocusWithin" Value="True">
              <Setter TargetName="Ring" Property="Background" Value="{StaticResource Accent.Ring}" />
            </Trigger>
            <Trigger Property="IsEnabled" Value="False">
              <Setter Property="Opacity" Value="0.5" />
            </Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>

  <!-- ============ 右クリックメニュー ============
       キー無し（暗黙）の Style なので、ContextMenu・MenuItem・Separator を素のまま書けば効く。
       幅 216・角丸 6・内側の余白 4・枠 1・影。入力欄（TextBox など）の標準の右クリックのメニューは別の型なので変わらない。
       項目の高さ 31・余白 上下 7・左右 12・角丸 4・文字 13。削除のように赤にする項目だけ MenuItemDanger を付ける。
       先頭の項目を太字にするときは FontWeight を付ける -->
  <Style TargetType="ContextMenu">
    <Setter Property="Background" Value="{StaticResource Bg.Surface}" />
    <Setter Property="FontSize" Value="13" />
    <Setter Property="Foreground" Value="{StaticResource Ink.Strong}" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="ContextMenu">
          <!-- 影が切れないよう、外側に余白を取る（幅 216 は枠の幅） -->
          <Border Margin="0,0,10,12" Width="216" Background="{TemplateBinding Background}" BorderBrush="{StaticResource Border.Normal}"
                  BorderThickness="1" CornerRadius="6" Padding="4">
            <Border.Effect>
              <DropShadowEffect Color="#000000" Opacity="0.18" BlurRadius="12" ShadowDepth="3" Direction="270" />
            </Border.Effect>
            <StackPanel IsItemsHost="True" KeyboardNavigation.DirectionalNavigation="Cycle" />
          </Border>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
  <Style TargetType="MenuItem">
    <Setter Property="Foreground" Value="{StaticResource Ink.Strong}" />
    <Setter Property="FontSize" Value="13" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="MenuItem">
          <Border x:Name="Bd" Height="31" Background="Transparent" CornerRadius="4" Padding="12,7">
            <DockPanel>
              <ContentPresenter ContentSource="Header" VerticalAlignment="Center" RecognizesAccessKey="True" />
            </DockPanel>
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsHighlighted" Value="True">
              <Setter TargetName="Bd" Property="Background" Value="{StaticResource Accent.Soft}" />
            </Trigger>
            <Trigger Property="IsEnabled" Value="False">
              <Setter Property="Foreground" Value="{StaticResource Ink.Disabled}" />
              <Setter TargetName="Bd" Property="Background" Value="Transparent" />
            </Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
  <!-- 削除のような、取り消せない項目。MenuItem の見た目のまま、文字だけ赤にする -->
  <Style x:Key="MenuItemDanger" TargetType="MenuItem" BasedOn="{StaticResource {x:Type MenuItem}}">
    <Setter Property="Foreground" Value="{StaticResource Danger.Text}" />
  </Style>
  <Style TargetType="Separator">
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="Separator">
          <Border Height="1" Background="{StaticResource Border.Soft}" Margin="8,4" />
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>

  <!-- ============ 進捗バー（光沢のチャンクをやめる） ============ -->
  <Style TargetType="ProgressBar">
    <Setter Property="Height" Value="6" />
    <Setter Property="Foreground" Value="{StaticResource Accent}" />
    <Setter Property="Background" Value="{StaticResource Bg.Pressed}" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="ProgressBar">
          <Border Background="{TemplateBinding Background}" CornerRadius="3" ClipToBounds="True">
            <Grid>
              <Rectangle x:Name="PART_Track" />
              <Border x:Name="PART_Indicator" HorizontalAlignment="Left" Background="{TemplateBinding Foreground}" CornerRadius="3" />
            </Grid>
          </Border>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>

  <Style TargetType="GridSplitter">
    <Setter Property="Background" Value="Transparent" />
  </Style>

  <!-- 行を分ける仕切り（検索の結果とプレビューの間・インデックス管理の一覧と詳細の間）。
       高さ（当たり判定）は 11px、カーソルは上下、見た目は細い線と真ん中のつまみ（32x2）。乗せると濃くなる -->
  <Style x:Key="Splitter.Rows" TargetType="GridSplitter" BasedOn="{StaticResource {x:Type GridSplitter}}">
    <Setter Property="Height" Value="11" />
    <Setter Property="Cursor" Value="SizeNS" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="GridSplitter">
          <Border Background="Transparent">
            <Grid>
              <Border Height="1" Background="{StaticResource Border.Soft}" VerticalAlignment="Center" />
              <Border x:Name="Grip" Width="32" Height="2" CornerRadius="1" Background="{StaticResource Ink.Body}"
                      HorizontalAlignment="Center" VerticalAlignment="Center" />
            </Grid>
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True">
              <Setter TargetName="Grip" Property="Background" Value="{StaticResource Ink.Strong}" />
            </Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>

  <!-- 節（カード）。枠つきの面に、見出しの帯（Section.Header）と行（Section.Row）を縦に並べる。カードの間は 16（2 つ目からのカードに Margin="0,16,0,0" を付けて作る） -->
  <Style x:Key="Section.Card" TargetType="Border">
    <Setter Property="Background" Value="{StaticResource Bg.Surface}" />
    <Setter Property="BorderBrush" Value="{StaticResource Border.Soft}" />
    <Setter Property="BorderThickness" Value="1" />
    <Setter Property="CornerRadius" Value="{StaticResource Radius.Control}" />
  </Style>
  <Style x:Key="Section.Header" TargetType="Border">
    <Setter Property="Height" Value="32" />
    <Setter Property="Padding" Value="16,6" />
    <Setter Property="Background" Value="{StaticResource Bg.Window}" />
    <Setter Property="BorderBrush" Value="{StaticResource Border.Soft}" />
    <Setter Property="BorderThickness" Value="0,0,0,1" />
    <Setter Property="CornerRadius" Value="5,5,0,0" /> <!-- Radius.Control（6）から枠の 1 を引いた値 -->
  </Style>
  <Style x:Key="Section.Row" TargetType="Border">
    <Setter Property="Padding" Value="16,12" />
    <Setter Property="BorderBrush" Value="{StaticResource Border.Row}" />
    <Setter Property="BorderThickness" Value="0,1,0,0" />
  </Style>
  <!-- 値を見せるだけの欄（読み取り専用）。中の TextBlock が長い値を省略する -->
  <Style x:Key="Field.ReadOnly" TargetType="Border">
    <Setter Property="Height" Value="30" />
    <Setter Property="Padding" Value="10,0" />
    <Setter Property="Background" Value="{StaticResource Bg.Subtle}" />
    <Setter Property="BorderBrush" Value="{StaticResource Border.Soft}" />
    <Setter Property="BorderThickness" Value="1" />
    <Setter Property="CornerRadius" Value="{StaticResource Radius.Control}" />
  </Style>

  <Style TargetType="ToolTip">
    <Setter Property="Background" Value="#1F2937" />
    <Setter Property="Foreground" Value="White" />
    <Setter Property="FontSize" Value="12" />
    <Setter Property="Padding" Value="9,6" />
    <Setter Property="MaxWidth" Value="420" />
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="ToolTip">
          <Border Background="{TemplateBinding Background}" CornerRadius="6" Padding="{TemplateBinding Padding}">
            <!-- 長い説明を折り返す。TextWrapping は添付プロパティではないので、
                 中身（文字列）を出すテンプレートの側で指定する -->
            <ContentPresenter>
              <ContentPresenter.ContentTemplate>
                <DataTemplate>
                  <TextBlock Text="{Binding}" TextWrapping="Wrap" Foreground="White" />
                </DataTemplate>
              </ContentPresenter.ContentTemplate>
            </ContentPresenter>
          </Border>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
</ResourceDictionary>
@@'@

${bundledParts} = @{}
${bundledParts}['lib'] = @'
# tebunko の画面以外の部品の読み込み口。
# 画面（gui）・インデクサ・テスト・画面が起こす別スレッドから dot-source して使う。読み込む順に意味がある。
# 共通基盤（どのツールからも使う部品）の読み込み口。
# ツール側は、このファイルを dot-source すれば共通基盤がそろう。読み込む順に意味がある。
# フォルダ構成の基本（どのツールからも使う）。

# このファイルは scripts\shared\core\ に置く。3 つ上がリポジトリ直下になる（zip 版）。
# 単一 .ps1 版（展開せずに動く試験版。設計は docs/design/structure/single-script.md）は、
# scripts\ の下の階層が無いため、${bundledScriptPath}（結合の道具が入れる、自分自身のパス）があれば
# その .ps1 自身の置き場所を根フォルダとする
${pathsBundled} = Get-Variable -Name bundledScriptPath -ErrorAction SilentlyContinue
${rootDir} = if ($null -ne ${pathsBundled} -and ${pathsBundled}.Value) {
    Split-Path -Parent ${pathsBundled}.Value
} else {
    [System.IO.Path]::GetFullPath("$PSScriptRoot\..\..\..")
}
Remove-Variable -Name pathsBundled -ErrorAction SilentlyContinue
# データ（設定ファイル・work）の置き場所は data_dir.ps1 で決める（ツールのフォルダに書き込めないことがあるため）

${utf8Bom} = New-Object System.Text.UTF8Encoding($true)
# ファイルの読み書き（行ファイル・原子的な書き込み・長いパス・排他）。


# ---- パスの状態（見つかった・見つからない・接続できない・その他） ----
#
# Test-Path・File.Exists・Directory.Exists は、届かない共有でも多くの場合に例外を出さず $false を返す
# （「見つからない」と区別できない）。getPathState は、例外を投げる呼び出し（File.GetAttributes）で調べる。

${pathStateFound}       = "Found"
${pathStateMissing}     = "Missing"
${pathStateUnreachable} = "Unreachable"
${pathStateOther}       = "Other"

# 接続できない（届かない共有・ネットワークの問題）を表す Win32 のエラー番号
# ERROR_BAD_NETPATH(53)・ERROR_BAD_NET_NAME(67)・ERROR_NETNAME_DELETED(64)・ERROR_SEM_TIMEOUT(121)・
# ERROR_NETWORK_UNREACHABLE(1231)・ERROR_HOST_UNREACHABLE(1232)・ERROR_NO_NET_OR_BAD_PATH(1222)
${unreachableWin32Codes} = @(53, 67, 64, 121, 1231, 1232, 1222)

# ---- クラウドにだけあるファイル（OneDrive・SharePoint などのオンデマンド） ----
#
# 一覧（Get-ChildItem）が返す属性だけで見分ける。ファイルを開かないので、ダウンロードは起きない。
#   RECALL_ON_DATA_ACCESS(0x400000)・RECALL_ON_OPEN(0x40000)・OFFLINE(0x1000) のどれかが付いていれば、
#   中身は手元に無い（開くとダウンロードされる）。
#   PINNED(0x80000)・UNPINNED(0x100000)・ReparsePoint だけでは、クラウドにだけあるとは言えない。

${attributeRecallOnDataAccess} = 0x400000
${attributeRecallOnOpen}       = 0x40000
${attributeOffline}            = 0x1000

function testCloudOnlyAttributes {
    # ファイルの属性（数値）が、中身が手元に無い（クラウドにだけある）ことを表すとき $true
    param (
        [int]$attributes
    )

    $mask = ${attributeRecallOnDataAccess} -bor ${attributeRecallOnOpen} -bor ${attributeOffline}
    return (($attributes -band $mask) -ne 0)
}

function readListFile {
    # 1行1件のファイルを読み込む（空行を除く）。ファイルが無ければ空配列。
    # 読めない（ほかが書き込み中など）ときは例外にする。呼び出し側の $ErrorActionPreference が既定の Continue でも
    # 空の一覧と取り違えないよう -ErrorAction Stop を付ける
    param (
        [string]$path
    )

    if (!(Test-Path -LiteralPath $path)) {
        return @()
    }
    return @(Get-Content -LiteralPath $path -Encoding UTF8 -ErrorAction Stop | Where-Object { $_.Trim() -ne "" })
}

function writeListFile {
    param (
        [string]$path,
        [string[]]$lines
    )

    if ($null -eq $lines) {
        $lines = [string[]]@()
    }
    [System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($path)) | Out-Null
    [System.IO.File]::WriteAllLines($path, $lines, ${utf8Bom})
}

function formatFileTime {
    # 取り込み一覧に記録する日時の書式（秒まで）。更新の有無はこの文字列で比べる
    param (
        [datetime]$time
    )

    return $time.ToString("yyyy/MM/dd HH:mm:ss", [System.Globalization.CultureInfo]::InvariantCulture)
}

function writeTextLinesAtomic {
    # 途中で中断してもファイルが壊れないよう、一時ファイルに書いてから置き換える
    param (
        [string]$path,
        [object[]]$lines,
        [System.Text.Encoding]$encoding = ${utf8Bom}  # 文字コード（既定は BOM 付き UTF-8）
    )

    [System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($path)) | Out-Null
    $tmpPath = "${path}.tmp"
    [System.IO.File]::WriteAllLines($tmpPath, [string[]]@($lines), $encoding)
    # 書いた直後のファイルは、ウイルス対策ソフト等が一時的に掴んでいて置き換えられないことがあるため、少し待って数回試す
    for ($i = 1; $true; $i++) {
        try {
            if (Test-Path -LiteralPath $path) {
                # $null は空文字列として渡されて例外になるため、[NullString]::Value（バックアップを作らない）を渡す
                [System.IO.File]::Replace($tmpPath, $path, [NullString]::Value)
            } else {
                [System.IO.File]::Move($tmpPath, $path)
            }
            return
        } catch {
            if ($i -ge 5) {
                throw
            }
            Start-Sleep -Milliseconds 200
        }
    }
}

function toSafeFileName {
    # ファイル名に使えない文字を全角に変換
    param (
        [string]$name
    )

    $name = $name.Replace(">", "＞")
    $name = $name.Replace("<", "＜")
    $name = $name.Replace("\", "￥")
    $name = $name.Replace("*", "＊")
    $name = $name.Replace('"', '”')
    $name = $name.Replace(":", "：")
    $name = $name.Replace("?", "？")
    $name = $name.Replace("|", "｜")
    $name = $name.Replace("/", "／")

    return $name
}


${maxFileNameLength} = 255  # Windows のファイル名（パスの区切りの間の1つ）の上限


function toLongPath {
    # パスの先頭に \\?\ を付け、260文字を超えるパスもファイル操作（System.IO・-LiteralPath）で扱えるようにする。
    # ネットワークのパス（\\server\share\…）は \\?\UNC\server\share\… にする。付いていればそのまま返す。
    # Join-Path は \\?\ 付きのパスを扱えないため、パスを組み立てた後、ファイル操作に渡す直前に使う
    param (
        [string]$path
    )

    if (!$path -or $path.StartsWith("\\?\")) {
        return $path
    }
    $path = $path.Replace("/", "\")
    if ($path.StartsWith("\\")) {
        return "\\?\UNC\" + $path.Substring(2)
    }
    return "\\?\" + $path
}

function copyFileShared {
    # 元のファイルに影響を出さずにコピーする（インデックス作成は、元のファイルでなくこのコピーを読んで行う）。
    # 書き込み中のファイルも、読み取りだけで開いてコピーできる（書きかけの中身が入ることは、直接読む場合と同じ）。
    # 排他で開かれたファイルはコピーできず、取り込みの失敗になる。
    # File.Copy は元のファイルをほかのアプリの書き込みを拒否して開くため、コピーの間は利用者が上書き保存できず、
    # 利用者がファイルを開いて編集中だとコピーできないことがある。
    # ここでは読み取りだけで開き、ほかのアプリの読み書き・削除・名前変更を妨げない。
    # コピー先は通常の属性（読み取り専用などを付けない）で作り、既にあれば上書きする
    param (
        [string]$sourcePath,
        [string]$destPath
    )

    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $source = New-Object System.IO.FileStream((toLongPath $sourcePath), [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    try {
        $dest = New-Object System.IO.FileStream((toLongPath $destPath), [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
        try {
            $source.CopyTo($dest, 1MB)
        } finally {
            $dest.Dispose()
        }
    } finally {
        $source.Dispose()
    }
}

function fromLongPath {
    # toLongPath で付けた \\?\ を外し、通常のパスに戻す（Get-ChildItem の FullName 等から相対パスを求めるため）
    param (
        [string]$path
    )

    if ($path.StartsWith("\\?\UNC\")) {
        return "\\" + $path.Substring(8)
    }
    if ($path.StartsWith("\\?\")) {
        return $path.Substring(4)
    }
    return $path
}

function trimTrailingSeparator {
    # パスの末尾の \ と / を落とす（リンクの判定・削除の入口で使う。念のため、末尾の区切りでリンクの先を見ることが無いようにする）。
    # 途中の区切りは変えない（\\?\ で始まらないパスの / は、あとで toLongPath が \ にそろえる。\\?\ で始まるパスの / はそのまま）。
    # 落とした結果が空か : で終わるパス（C:\ ・ \\?\C:\ ・ \ ・ / ）と、\\?\ だけのパスは、そのまま返す。
    # それ以外は、UNC の根（\\server\share\）や \\?\Volume{...}\ も、末尾を落とす
    param (
        [string]$path
    )

    if (!$path) {
        return $path
    }
    $trimmed = $path.TrimEnd([char[]]@("\", "/"))
    if (!$trimmed -or $trimmed.EndsWith(":") -or $trimmed -eq "\\?") {
        return $path
    }
    return $trimmed
}

function setNotContentIndexed {
    # フォルダ（またはファイル）に「内容のインデックスを作成しない」属性（NotContentIndexed）を付ける。
    # 既に付いているものには付け直さない（Changed に数えない）ので、ほかの属性（読み取り専用など）は変えない。
    #   Recurse 無し: path 自身と、フォルダなら直下のファイルに付ける（下のフォルダには付けない）
    #   Recurse あり: path 自身と、下のすべてのフォルダ・ファイルに付ける
    # Recurse でフォルダを渡したときは、根フォルダの属性を下より先に確かめる。既に付いていれば
    # （前回すべて付け終えて根に付けたということなので）下はたどらず、GetAttributes 1 回だけで終える。
    # 根の属性は、下をすべて付け終えて成功したときにだけ最後に付ける（列挙・付与の途中で失敗した回は
    # 根に付けない。次回もう一度下からたどり直せるようにするため）。
    # 1件ずつの失敗（アクセス拒否など）も、列挙そのものの失敗（無いパス・列挙の途中で読めなくなったフォルダなど）も
    # 例外にせず、@{ Ok; Changed; Reason }（最初に見つかった理由を Reason に）を返す。
    # 呼び出し元（インデックス作成）は、Ok が $false でも処理を止めず、ログに 1 行残すだけにする
    param (
        [string]$path,
        [switch]$Recurse
    )

    $flag = [System.IO.FileAttributes]::NotContentIndexed
    $state = getPathState $path
    if ($state.State -ne ${pathStateFound}) {
        $reason = if ($state.Message) { $state.Message } else { "パスが見つかりません（${path}）" }
        return @{ Ok = $false; Changed = 0; Reason = $reason }
    }

    $long = toLongPath $path
    $deferRoot = [bool]($Recurse -and $state.IsDirectory)
    if ($deferRoot) {
        try {
            $rootAttrs = [System.IO.File]::GetAttributes($long)
        } catch {
            return @{ Ok = $false; Changed = 0; Reason = $_.Exception.Message }
        }
        if ($rootAttrs -band $flag) {
            return @{ Ok = $true; Changed = 0; Reason = "" }
        }
    }

    # 先に対象（path 自身と、必要なら中身）をすべて列挙してから属性を付ける。deferRoot のときは
    # 根自身をここでは含めず、下だけを集める（根は下がすべて終わったあとに付ける）。
    # 列挙そのものが例外になったら（途中で消えた・読めないフォルダがあるなど）、途中まで集めた分は捨てて Ok=$false にする
    $items = New-Object System.Collections.Generic.List[object]
    if (!$deferRoot) {
        $items.Add(@{ Path = $path; IsDirectory = $state.IsDirectory })
    }
    try {
        if ($state.IsDirectory) {
            $dirInfo = New-Object System.IO.DirectoryInfo $long
            if ($Recurse) {
                foreach ($entry in $dirInfo.EnumerateFileSystemInfos("*", [System.IO.SearchOption]::AllDirectories)) {
                    $items.Add(@{ Path = (fromLongPath $entry.FullName); IsDirectory = ($entry -is [System.IO.DirectoryInfo]) })
                }
            } else {
                foreach ($file in $dirInfo.EnumerateFiles("*", [System.IO.SearchOption]::TopDirectoryOnly)) {
                    $items.Add(@{ Path = (fromLongPath $file.FullName); IsDirectory = $false })
                }
            }
        }
    } catch {
        return @{ Ok = $false; Changed = 0; Reason = $_.Exception.Message }
    }

    $changed = 0
    $ok = $true
    $reason = ""
    foreach ($item in $items) {
        try {
            # フォルダ・ファイルどちらも [System.IO.File]::Get/SetAttributes で扱う（Directory クラスには同名のメソッドが無い）
            $itemLong = toLongPath $item.Path
            $attrs = [System.IO.File]::GetAttributes($itemLong)
            if ($attrs -band $flag) {
                continue
            }
            [System.IO.File]::SetAttributes($itemLong, ($attrs -bor $flag))
            $changed++
        } catch {
            $ok = $false
            if (!$reason) {
                $reason = $_.Exception.Message
            }
        }
    }

    if ($deferRoot -and $ok) {
        try {
            [System.IO.File]::SetAttributes($long, ($rootAttrs -bor $flag))
            $changed++
        } catch {
            $ok = $false
            if (!$reason) {
                $reason = $_.Exception.Message
            }
        }
    }

    return @{ Ok = $ok; Changed = $changed; Reason = $reason }
}

function testNotContentIndexed {
    # path に「内容のインデックスを作成しない」属性（NotContentIndexed）が付いているかを返す。
    # 属性を確かめられなければ（パスが無い・アクセスできないなど）例外にせず $false を返す
    param (
        [string]$path
    )

    try {
        $attrs = [System.IO.File]::GetAttributes((toLongPath $path))
        return [bool]($attrs -band [System.IO.FileAttributes]::NotContentIndexed)
    } catch {
        return $false
    }
}

function removeDirectoryRetry {
    # フォルダを中身ごと削除する。ウイルス対策ソフト・エクスプローラーが一時的に掴んでいることがあるため、少し待って数回試す
    param (
        [string]$path,
        [int]$tries = 3,
        [int]$waitMilliseconds = 200
    )

    # 中に長いパス（260文字超）のファイルがあっても削除できるよう \\?\ 付きで削除する
    $longPath = toLongPath $path
    for ($i = 1; $true; $i++) {
        if (![System.IO.Directory]::Exists($longPath)) {
            return
        }
        try {
            # リンク（ジャンクション・シンボリックリンク）は辿らず、リンクそのものだけを外す（removeTreeNoFollow）。
            # 消せなければ例外になり、catch で試し直す
            removeTreeNoFollow $longPath
            return
        } catch {
            if ($i -ge $tries) {
                throw
            }
            Start-Sleep -Milliseconds $waitMilliseconds
        }
    }
}

function getLinkKind {
    # item（Get-Item・Get-ChildItem・DirectoryInfo などが返す FileSystemInfo）の種類を返す。
    #   Link    … ジャンクション・シンボリックリンク（属性に ReparsePoint が付き、LinkType がそのどちらか）
    #   Unknown … 属性が読めない、またはフォルダなのに ReparsePoint が付き LinkType がジャンクション・シンボリックリンクと確かめられない
    #             （OneDrive のオンデマンドの置き場のフォルダなど）。リンクかどうか分からないので、辿らず、消しもしない
    #   Plain   … それ以外（ReparsePoint の付いたファイルは、辿るものが無いので Plain）
    # 先に属性の ReparsePoint を見て、付いているときだけ LinkType を読む（多くのファイルで余計な問い合わせをしない）。
    # 5.1 ではプロパティを読んだときの例外は $null になる（catch に届かない）ため、$null を読めなかったものとして扱う
    param (
        $item
    )

    $attributes = $item.Attributes
    if ($null -eq $attributes) {
        return "Unknown"
    }
    if (!($attributes -band [System.IO.FileAttributes]::ReparsePoint)) {
        return "Plain"
    }
    $linkType = [string]$item.LinkType
    if ($linkType -eq "Junction" -or $linkType -eq "SymbolicLink") {
        return "Link"
    }
    if ($attributes -band [System.IO.FileAttributes]::Directory) {
        return "Unknown"
    }
    return "Plain"
}

function testLinkItem {
    # item が、辿ってはいけないもの（getLinkKind が Link か Unknown）なら $true
    param (
        $item
    )

    return ((getLinkKind $item) -ne "Plain")
}

function testPathIsLink {
    # path そのもの（途中の階層は見ない）がジャンクション・シンボリックリンクなら $true。
    # 無い・空のパスは $false（まだ作っていない）。属性が読めない、リンクかどうか確かめられないフォルダ（getLinkKind が Unknown）のときは $true（辿らない側に倒す）
    param (
        [string]$path
    )

    if (!$path) {
        return $false
    }
    $long = toLongPath (trimTrailingSeparator $path)
    try {
        $attributes = [System.IO.File]::GetAttributes($long)
    } catch [System.IO.FileNotFoundException] {
        return $false
    } catch [System.IO.DirectoryNotFoundException] {
        return $false
    } catch {
        return $true
    }
    if (!($attributes -band [System.IO.FileAttributes]::ReparsePoint)) {
        return $false
    }
    if ($attributes -band [System.IO.FileAttributes]::Directory) {
        return (testLinkItem (New-Object System.IO.DirectoryInfo $long))
    }
    return (testLinkItem (New-Object System.IO.FileInfo $long))
}

function testPathHasLink {
    # base の下の path まで、途中の各階層（path を含み、base とそれより上は含まない）に、リンクがあれば $true。
    # 利用者が選んだ置き場（base）そのものが別の場所へのリンクでも、構成を変えずに使えるよう、base は見ない。
    # path が base と同じなら $false。base の下になければ、確かめられないので $true
    param (
        [string]$base,
        [string]$path
    )

    try {
        $baseFull = [System.IO.Path]::GetFullPath((fromLongPath $base)).TrimEnd("\")
        $pathFull = [System.IO.Path]::GetFullPath((fromLongPath $path)).TrimEnd("\")
    } catch {
        return $true
    }
    if ($pathFull.Equals($baseFull, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $false
    }
    if (!$pathFull.StartsWith("$baseFull\", [System.StringComparison]::OrdinalIgnoreCase)) {
        return $true
    }
    $current = $baseFull
    foreach ($name in $pathFull.Substring($baseFull.Length + 1).Split("\")) {
        $current = "$current\$name"
        if (testPathIsLink $current) {
            return $true
        }
        if (!(Test-Path -LiteralPath (toLongPath $current))) {
            return $false  # ここから先はまだ無い
        }
    }
    return $false
}

function removeEntryOnly {
    # ファイル 1 つ・リンク（ジャンクション・シンボリックリンク）1 つ・空のフォルダ 1 つ（item は FileSystemInfo）を、そのものだけ消す。
    # リンクの先は消さない。読み取り専用の属性は外してから消す
    param (
        [System.IO.FileSystemInfo]$item
    )

    $path = $item.FullName
    $attributes = $item.Attributes
    if ($attributes -band [System.IO.FileAttributes]::ReadOnly) {
        # 読み取り専用だけを外す（ほかの属性は変えない）
        [System.IO.File]::SetAttributes($path, ($attributes -band (-bnot [System.IO.FileAttributes]::ReadOnly)))
    }
    if ($item -is [System.IO.DirectoryInfo]) {
        [System.IO.Directory]::Delete($path, $false)
    } else {
        [System.IO.File]::Delete($path)
    }
}

function removeTreeNoFollow {
    # フォルダを中身ごと削除する。ジャンクション・シンボリックリンクは辿らず、リンクそのものだけを外す（先は消さない）。
    # path そのものがリンクなら、そのリンクだけを外す。フォルダが無ければ何もしない。
    # 先に全体を数える（リンクは辿らない）。リンクかどうか確かめられないフォルダ（getLinkKind が Unknown）が 1 つでもあれば、
    # 降りず、何も消さずに例外にする。何も消さないと言えるのは、この数える段で見つけた Unknown のときだけ。
    # そのあとで、ファイル・リンク・フォルダ（下から順）を消す。
    # 降りる直前と、フォルダのファイルを消す直前に、そのフォルダがリンクでないかを確かめ直す。
    # 数えたあとにフォルダがリンクに替わっていたら例外にする。それまでに消した分は戻らない。
    # 消す直前に確かめ直すのは、そのフォルダ自身だけ。上の階層が途中で替わったときは見つけられない。
    # 読み取り専用の属性は外して消す（Remove-Item -Force と同じ働き）。消せなければ例外にする
    param (
        [string]$path
    )

    $long = toLongPath (trimTrailingSeparator $path)
    if (![System.IO.Directory]::Exists($long)) {
        return
    }
    $filesByDirectory = New-Object 'System.Collections.Generic.Dictionary[string,System.Collections.Generic.List[string]]'
    $links = New-Object System.Collections.Generic.List[string]
    $directories = New-Object System.Collections.Generic.List[string]
    $pending = New-Object System.Collections.Generic.Stack[string]
    $pending.Push($long)
    while ($pending.Count -gt 0) {
        $current = New-Object System.IO.DirectoryInfo ($pending.Pop())
        $currentKind = getLinkKind $current
        if ($currentKind -eq "Unknown") {
            throw "リンクかどうか確かめられないフォルダのため、消しませんでした: $(fromLongPath $current.FullName)"
        }
        if ($currentKind -eq "Link") {
            $links.Add($current.FullName)
            continue
        }
        $directories.Add($current.FullName)
        $filesByDirectory[$current.FullName] = New-Object System.Collections.Generic.List[string]
        foreach ($entry in @($current.EnumerateFileSystemInfos("*", [System.IO.SearchOption]::TopDirectoryOnly))) {
            if ($entry -isnot [System.IO.DirectoryInfo]) {
                $filesByDirectory[$current.FullName].Add($entry.FullName)
            } elseif ((getLinkKind $entry) -eq "Link") {
                $links.Add($entry.FullName)
            } else {
                # 確かめられないもの（Unknown）も積む。降りる直前の確かめで例外にする（列挙の途中では投げない）
                $pending.Push($entry.FullName)
            }
        }
    }
    foreach ($directory in $directories) {
        if ((getLinkKind (New-Object System.IO.DirectoryInfo $directory)) -ne "Plain") {
            throw "数えたあとでリンクに替わったフォルダのため、中のファイルを消しませんでした: $(fromLongPath $directory)"
        }
        foreach ($file in $filesByDirectory[$directory]) {
            removeEntryOnly (New-Object System.IO.FileInfo $file)
        }
    }
    foreach ($link in $links) {
        removeEntryOnly (New-Object System.IO.DirectoryInfo $link)
    }
    for ($i = $directories.Count - 1; $i -ge 0; $i--) {
        removeEntryOnly (New-Object System.IO.DirectoryInfo $directories[$i])
    }
}

function moveDirectoryRetry {
    # フォルダを移動する。removeDirectoryRetry と同じ理由（ウイルス対策ソフト・エクスプローラーが、
    # 作ったばかり・書いたばかりのフォルダを一時的に掴んでいることがある）で、待つ時間を倍にしながら数回試す
    # （削除より、掴まれている時間が長くかかることがあるため、既定の回数・最初の待ち時間を大きくしている）
    param (
        [string]$source,
        [string]$destination,
        [int]$tries = 5,
        [int]$waitMilliseconds = 200
    )

    $longSource = toLongPath $source
    $longDestination = toLongPath $destination
    $wait = $waitMilliseconds
    for ($i = 1; $true; $i++) {
        try {
            [System.IO.Directory]::Move($longSource, $longDestination)
            return
        } catch {
            if ($i -ge $tries) {
                throw
            }
            Start-Sleep -Milliseconds $wait
            $wait *= 2
        }
    }
}

function testAnyEntry {
    # 列挙（[System.IO.Directory]::EnumerateFiles などの結果）に、predicate が $true を返すもの（省略したら何でも）が
    # 1 つでもあるか。見つけたところで列挙をやめ、列挙子を必ず Dispose する。
    # foreach を break・return・throw で途中で抜けると列挙子が Dispose されず、調べていた下のフォルダを開いたまま残る。
    # GC されるまで、そのフォルダと上のフォルダを移動・削除できなくなる（Directory.Move がアクセス拒否になる）ため、
    # 途中でやめる列挙はこの関数を通す
    param (
        [System.Collections.IEnumerable]$entries,
        [scriptblock]$predicate
    )

    $enumerator = $entries.GetEnumerator()
    try {
        while ($enumerator.MoveNext()) {
            if ($null -eq $predicate -or (& $predicate $enumerator.Current)) {
                return $true
            }
        }
        return $false
    } finally {
        if ($enumerator -is [System.IDisposable]) {
            $enumerator.Dispose()
        }
    }
}

function selectFirstEntries {
    # 列挙（[System.IO.Directory]::EnumerateFileSystemEntries などの結果）の先頭から count 件までを配列にして返す。
    # count 件で列挙をやめ、列挙子を必ず Dispose する（testAnyEntry と同じ理由。Select-Object -First で途中でやめる形にしない）
    param (
        [System.Collections.IEnumerable]$entries,
        [int]$count
    )

    $list = New-Object System.Collections.Generic.List[object]
    $enumerator = $entries.GetEnumerator()
    try {
        while ($list.Count -lt $count -and $enumerator.MoveNext()) {
            $list.Add($enumerator.Current)
        }
    } finally {
        if ($enumerator -is [System.IDisposable]) {
            $enumerator.Dispose()
        }
    }
    return , $list.ToArray()
}

function getFolderKey {
    # フォルダのパスから、名前付きミューテックス・イベントの名前に使う鍵（16 進 64 文字）を作る。大文字と小文字は区別しない。
    # 安全性のためではなく、パスを名前に使える長さと文字にするためのハッシュ。
    # FIPS 準拠の実装（SHA256CryptoServiceProvider）を使う。MD5 や SHA256Managed は、
    # FIPS モードを有効にした Windows では作るときに例外になり、起動できなくなるため
    param (
        [string]$dir
    )

    $sha = New-Object System.Security.Cryptography.SHA256CryptoServiceProvider
    try {
        return [BitConverter]::ToString($sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($dir.ToLowerInvariant()))).Replace("-", "")
    } finally {
        $sha.Dispose()
    }
}

function newAppMutex {
    # 同じツール（配置フォルダ）の処理を二重に動かさないための名前付きミューテックスを作り、@{ Mutex; Acquired } を返す。
    # Acquired が $false なら、ほかで実行中。プロセスが終われば解放されるため、強制終了されても残らない
    #   name: 処理の種類（"gui" = 画面、"indexer" = インデックス作成）
    param (
        [string]$name,
        [string]$dir = ${rootDir}
    )

    $key = getFolderKey $dir
    $createdNew = $false
    $mutex = New-Object System.Threading.Mutex($true, "Local\${appId}_${name}_${key}", [ref]$createdNew)
    return @{ Mutex = $mutex; Acquired = $createdNew }
}

function getPathErrorKind {
    # File.GetAttributes などが投げた例外（PowerShell から呼ぶと MethodInvocationException に包まれる）を、
    # 見つからない（FileNotFoundException・DirectoryNotFoundException）・接続できない（Win32 のエラー番号）・
    # その他（アクセス拒否・ログオンの失敗など上のどれにも当たらないもの）に分ける。純粋な関数（例外を受け取って値を返すだけ）
    param (
        $exception  # System.Exception（MethodInvocationException でもそのままでもよい）
    )

    $inner = $exception
    while ($inner -is [System.Management.Automation.MethodInvocationException] -and $null -ne $inner.InnerException) {
        $inner = $inner.InnerException
    }
    if ($inner -is [System.IO.FileNotFoundException] -or $inner -is [System.IO.DirectoryNotFoundException]) {
        return ${pathStateMissing}
    }
    $code = $inner.HResult -band 0xFFFF
    if (${unreachableWin32Codes} -contains $code) {
        return ${pathStateUnreachable}
    }
    return ${pathStateOther}
}

function getPathState {
    # パスの状態を、例外を投げる呼び出し（File.GetAttributes）で調べる。260 文字を超えるパスも扱えるよう \\?\ を付けて渡す。
    # 返すもの: @{ State（上の定数）; IsDirectory; Message（見つかったとき以外の例外の文面） }
    param (
        [string]$path
    )

    try {
        $attributes = [System.IO.File]::GetAttributes((toLongPath $path))
        return @{ State = ${pathStateFound}; IsDirectory = [bool]($attributes -band [System.IO.FileAttributes]::Directory); Message = "" }
    } catch {
        return @{ State = (getPathErrorKind $_.Exception); IsDirectory = $false; Message = $_.Exception.Message }
    }
}

function invokeWithNamedMutex {
    # 名前付きミューテックスを取って action を実行し、action の出力を返す（終わったら必ず手放す）。
    # 同じスレッドの入れ子は通す（ミューテックスは同じスレッドなら再び取れる）。
    # timeoutMilliseconds を過ぎても取れなければ、「排他の待ちが時間切れになりました」の例外にする。
    # 前の持ち主が手放さずに終わっていた（abandoned）ときは、取れたものとして続ける
    #   mutexName: ミューテックスの名前（呼ぶ側が決める。同じ名前どうしで排他する）。
    #   action から呼び出し元の変数を参照できるよう、この関数の変数の名前は目立つものにしてある（name・key・path などは使わない）
    param (
        [string]$mutexName,
        [int]$timeoutMilliseconds,
        [scriptblock]$action
    )

    $mutex = New-Object System.Threading.Mutex($false, $mutexName)
    try {
        $acquired = $false
        try {
            $acquired = $mutex.WaitOne($timeoutMilliseconds)
        } catch {
            # PowerShell では MethodInvocationException に包まれて届く。abandoned でも所有は移っている
            $inner = $_.Exception
            while ($null -ne $inner -and $inner -isnot [System.Threading.AbandonedMutexException]) {
                $inner = $inner.InnerException
            }
            if ($null -eq $inner) {
                throw
            }
            $acquired = $true
        }
        if (!$acquired) {
            throw "排他の待ちが時間切れになりました（${timeoutMilliseconds} ミリ秒。${mutexName}）。ほかの処理が終わってからやり直してください。"
        }
        try {
            & $action
        } finally {
            $mutex.ReleaseMutex()
        }
    } finally {
        $mutex.Dispose()
    }
}

# スレッドのプール（WorkerPool）。ランスペースと PowerShell のインスタンスを使い回し、仕事のたびに作って捨てない。
# 設計は docs/design/structure/threads.md「寿命」、docs/design/structure/classes.md「クラスと関数の使い分け」。
#
# WorkerPool は、作ったランスペースのスレッドだけから呼ぶ（PowerShell 5.1 のクラスのメソッドは、クラスを定義したランスペースで動くため）。
# 仕事のスクリプトは文字列で渡す（スクリプトブロックのまま渡すと、作ったランスペースに結び付いたまま別のスレッドで動いてしまう）。

function newWorkerState {
    # プールの各スレッドに読み込む関数・値だけを入れた InitialSessionState を作る
    # （lib.ps1 全体を読み込むと、スレッドを用意するだけで時間がかかるため）
    param (
        [string[]]$functions = @(),
        [string[]]$variables = @()
    )

    $state = [System.Management.Automation.Runspaces.InitialSessionState]::CreateDefault2()
    foreach ($name in $functions) {
        $state.Commands.Add([System.Management.Automation.Runspaces.SessionStateFunctionEntry]::new($name, (Get-Command $name -CommandType Function).Definition))
    }
    foreach ($name in $variables) {
        $state.Variables.Add([System.Management.Automation.Runspaces.SessionStateVariableEntry]::new($name, (Get-Variable $name -ValueOnly), ""))
    }
    return $state
}

function joinWorkerScript {
    # 部品の読み込み（Prelude）を、本体のスクリプト（script）につなぐ。呼び出し側の書き換えをせず、
    # 意味を変えない形でつなぐため、挿入する場所は本体の構文解析で決める:
    #   param ブロックがあればその直後、続けて最初の文が `$ErrorActionPreference = "Stop"` ならそのあとにも進める
    #   （部品が読めないときにスレッドを終える今の動きを保つため。tests/shared/core/worker_pool.Tests.ps1 が確かめる）。
    # Prelude は、同じランスペースで仕事のたびに呼ばれても 1 回だけ実行する（$global:workerPreludeDone で守る。
    # ランスペースを使い回さない呼び出し元でも害はない）
    param (
        [string]$prelude,
        [string]$script
    )

    $tokens = $null
    $errors = $null
    $ast = [System.Management.Automation.Language.Parser]::ParseInput($script, [ref]$tokens, [ref]$errors)
    if ($errors.Count -gt 0) {
        throw "joinWorkerScript: つなぐ本体の構文エラーです: $($errors[0].Message)"
    }
    $insertAt = if ($ast.ParamBlock) { $ast.ParamBlock.Extent.EndOffset } else { 0 }
    $statements = @($ast.EndBlock.Statements)
    if ($statements.Count -gt 0 -and $statements[0].Extent.Text -match '^\$ErrorActionPreference\s*=\s*"Stop"$') {
        $insertAt = $statements[0].Extent.EndOffset
    }
    $head = $script.Substring(0, $insertAt)
    $tail = $script.Substring($insertAt)
    $guarded = "`r`nif (!`$global:workerPreludeDone) {`r`n$prelude`r`n`$global:workerPreludeDone = `$true`r`n}"
    return "$head$guarded$tail"
}

function getWorkerCount {
    # プールのスレッドの数の既定（画面のために 1 コアを残す。1～max）
    param (
        [int]$max = 4,
        [int]$processors = [Environment]::ProcessorCount
    )

    return [Math]::Max(1, [Math]::Min($processors - 1, $max))
}

class WorkerPool {
    # スレッドの数
    [int]$Size
    # 各スレッドの優先度（Normal・BelowNormal など）。仕事を始めるたびに、そのスレッドに設定する
    [string]$Priority
    # 各スレッドで、最初の仕事の前に 1 回だけ実行するスクリプト（lib.ps1 の読み込みなど）。ランスペースの全体（global）で実行する
    [string]$Prelude = ""
    hidden [System.Management.Automation.Runspaces.RunspacePool]$Pool
    # 使い終わって空いている PowerShell のインスタンス
    hidden [System.Collections.Generic.Stack[powershell]]$Idle

    WorkerPool([int]$size, [System.Management.Automation.Runspaces.InitialSessionState]$state, [System.Management.Automation.Host.PSHost]$hostUi, [string]$priority) {
        $this.Size = [Math]::Max(1, $size)
        $this.Priority = [string][System.Threading.ThreadPriority]$priority
        $this.Idle = New-Object 'System.Collections.Generic.Stack[powershell]'
        # host は省けない（$null は受け付けない）。渡されなければ、このランスペースのものを使う
        if ($null -eq $hostUi) {
            $hostUi = Get-Host
        }
        $this.Pool = [runspacefactory]::CreateRunspacePool(1, $this.Size, $state, $hostUi)
        # 既定では仕事のたびに新しいスレッドを作る。ランスペースごとに 1 つのスレッドを使い続ける
        $this.Pool.ThreadOptions = [System.Management.Automation.Runspaces.PSThreadOptions]::ReuseThread
        $this.Pool.Open()
    }

    [hashtable] Submit([string]$script, [object[]]$arguments) {
        # 仕事を 1 つ始め、@{ PowerShell; Handle } を返す（Receive・Cancel に渡す）
        if ($null -eq $this.Pool) {
            throw "WorkerPool は閉じています。"
        }
        if ($this.Idle.Count -gt 0) {
            $ps = $this.Idle.Pop()
        } else {
            $ps = [powershell]::Create()
            $ps.RunspacePool = $this.Pool
        }
        # 優先度を設定してから仕事のスクリプトを呼ぶ（AddStatement で文を分けると、引数付きのスクリプトが終わらなくなるため、1 つのスクリプトにする）
        $text = "[System.Threading.Thread]::CurrentThread.Priority = '$($this.Priority)'`r`n"
        $body = "& {`r`n$script`r`n} @args"
        if ($this.Prelude) {
            # if の中は新しいスコープにならないため、prelude で読み込んだ関数はランスペースに残り、次の仕事でも使える
            $body = joinWorkerScript $this.Prelude $body
        }
        [void]$ps.AddScript("$text$body")
        foreach ($argument in $arguments) {
            [void]$ps.AddArgument($argument)
        }
        return @{ PowerShell = $ps; Handle = $ps.BeginInvoke() }
    }

    [object] Receive([hashtable]$job) {
        # 仕事の終わりを待って出力を返す。PowerShell のインスタンスは次の仕事に使い回す。仕事の例外はそのまま投げる
        $ps = $job.PowerShell
        try {
            $output = $ps.EndInvoke($job.Handle)
        } catch {
            $ps.Dispose()
            throw
        }
        $ps.Commands.Clear()
        $ps.Streams.ClearStreams()
        $this.Idle.Push($ps)
        # クラスのメソッドは戻り値を展開しない（PSDataCollection のまま返る）
        return $output
    }

    [void] Cancel([hashtable]$job) {
        # 仕事を止めて捨てる（止めたインスタンスは使い回さない）
        try {
            $job.PowerShell.Stop()
        } catch {
        }
        $job.PowerShell.Dispose()
    }

    [void] Close() {
        # スレッドを止めて片づける。何度呼んでもよい
        while ($this.Idle.Count -gt 0) {
            $this.Idle.Pop().Dispose()
        }
        if ($this.Pool) {
            $this.Pool.Dispose()
            $this.Pool = $null
        }
    }
}

class BackgroundQueue {
    # 画面から頼まれる短い仕事（プレビューの読み込み・状態の読み直し・プロセスの一覧など）を、使い回すスレッドで実行する。
    # 各スレッドでは、最初の仕事の前に 1 回だけ prelude（lib.ps1 の読み込みなど）を実行する（仕事のたびに読み込まない）。
    # 終わった仕事は Poll（画面のタイマー）で受け取り、画面のスレッドで onDone { param($output, $errorText) } を呼ぶ。
    # 画面のスレッドだけから呼ぶ
    hidden [WorkerPool]$Pool
    hidden [System.Collections.Generic.List[hashtable]]$Jobs

    BackgroundQueue([int]$size, [hashtable]$load, [System.Management.Automation.Host.PSHost]$hostUi) {
        # load は部品の読み込み口が返す @{ State; Prelude }。呼び出し元が Prelude に続けて
        # 呼びたい文を足したいときは、渡す前に $load.Prelude を書き換える
        $this.Jobs = New-Object 'System.Collections.Generic.List[hashtable]'
        $this.Pool = [WorkerPool]::new($size, $load.State, $hostUi, "Normal")
        $this.Pool.Prelude = $load.Prelude
    }

    [void] Post([string]$script, [object[]]$arguments, [scriptblock]$onDone) {
        # 仕事を 1 つ始める（スレッドが空いていなければ、空くのを待ってから始まる）
        $job = $this.Pool.Submit($script, $arguments)
        $job.OnDone = $onDone
        $this.Jobs.Add($job)
    }

    [int] Poll() {
        # 終わった仕事の onDone を呼び、まだ終わっていない仕事の数を返す
        foreach ($job in $this.Jobs.ToArray()) {
            if (!$job.Handle.IsCompleted) {
                continue
            }
            [void]$this.Jobs.Remove($job)
            $output = $null
            $errorText = $null
            try {
                if ($job.PowerShell.Streams.Error.Count -gt 0) {
                    $errorText = $job.PowerShell.Streams.Error[0].ToString()
                }
                $output = $this.Pool.Receive($job)
            } catch {
                # EndInvoke の呼び出しの例外に包まれているため、仕事が投げた元の例外の文面にする
                $exception = $_.Exception
                while ($exception.InnerException) {
                    $exception = $exception.InnerException
                }
                $errorText = $exception.Message
            }
            if ($job.OnDone) {
                & $job.OnDone $output $errorText
            }
        }
        return $this.Jobs.Count
    }

    [void] Close() {
        # 終わっていない仕事を止め、スレッドを片づける。何度呼んでもよい
        foreach ($job in $this.Jobs.ToArray()) {
            $this.Pool.Cancel($job)
        }
        $this.Jobs.Clear()
        $this.Pool.Close()
    }

    [void] Abandon() {
        # 画面を閉じるときだけに使う。Close と違い、止まった仕事（OS の呼び出しで戻らない届かない共有など）を待たずに戻る。
        # 終わった仕事は Close と同じく片づける（待たされないため）。終わっていない仕事には止める依頼（BeginStop）だけを出し、
        # その PowerShell のインスタンスと、この列のプール（RunspacePool）は Dispose しない
        # （PowerShell.Dispose() は動いている間は中で Stop を呼んで待ち、RunspacePool.Dispose() も止まったランスペースを待つため）。
        # 後始末はプロセスの終わりに任せる
        foreach ($job in $this.Jobs.ToArray()) {
            if ($job.Handle.IsCompleted) {
                try {
                    [void]$this.Pool.Receive($job)
                } catch {
                }
            } else {
                try {
                    [void]$job.PowerShell.BeginStop($null, $null)
                } catch {
                }
            }
        }
        $this.Jobs.Clear()
    }
}
# データ（設定ファイル）の置き場所の既定（どのツールからも使う）。
# ツールのフォルダに書き込めればそこに置く。書き込めないとき（Program Files・読み取り専用の共有フォルダに置いたとき）は、
# ツールが渡した逃げ先に置く（逃げ先はツールが決める。tebunko は既定のワークスペース）。
# work の置き場所は、ツールの側で決める（tebunko は設定の workspaceFolder）。

function testWritableFolder {
    # フォルダにファイルを作れるか。試しに作ったファイルは閉じると消える（DeleteOnClose）。フォルダが無ければ $false
    param (
        [string]$dir
    )

    if ([string]::IsNullOrWhiteSpace($dir) -or -not [System.IO.Directory]::Exists($dir)) {
        return $false
    }
    $probe = Join-Path $dir (".tebunko_write_test_" + [guid]::NewGuid().ToString("N") + ".tmp")
    try {
        $stream = New-Object System.IO.FileStream($probe, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write,
            [System.IO.FileShare]::None, 1, [System.IO.FileOptions]::DeleteOnClose)
        $stream.Dispose()
        return $true
    } catch {
        return $false
    }
}

function getDataDir {
    # 設定ファイルを置くフォルダを返す。ツールのフォルダに書き込めればそれ、書き込めなければ渡された逃げ先。
    # 逃げ先の既定値は持たない（shared はツールの既定の置き場所を知らない）
    param (
        [string]$root = ${rootDir},
        [Parameter(Mandatory = $true)]
        [string]$fallbackDir
    )

    if (testWritableFolder $root) {
        return $root
    }
    return $fallbackDir
}

# TSV とセルの文字列を扱う（判断層。ファイルに触らない）。

# インデックスのTSVで、セル内改行の代わりに使う文字（U+2028 LINE SEPARATOR）。
# TSVの1行 = Excelの1行を保つため、セル内改行はこの文字に置き換えて保存し、検索結果の出力時に改行へ戻す
${cellNewLine} = [string][char]0x2028

function replaceCellNewLine {
    # ダブルクォートで囲まれた1セル内の改行（LF・CR・CRLF）を、セル内改行を表す文字に置き換える
    param (
        [string]$inputString
    )

    # "" はクォート内のダブルクォートのエスケープだが、"…" "…" の2つに分けてマッチしても結果は同じ
    return [regex]::Replace($inputString, '"[^"]*"', { param($m) $m.Value -replace "\r\n|\r|\n", ${cellNewLine} })
}

function formatTsv {
    # Excelが出力したTSVを、1行目 = Excelの1行目、1列目 = A列 となるように整形する。
    # Excelは使用範囲（UsedRange）の左上のセルから出力するため、その行・列番号を firstRow・firstColumn に渡す。
    # セル内改行は置き換え、行末の空セルと末尾の空行は取り除く（途中の空行は行番号を保つため残す）。
    # 空白以外の文字が無ければ空文字を返す
    param (
        [string]$content,
        [int]$firstRow = 1,
        [int]$firstColumn = 1
    )

    $content = replaceCellNewLine $content
    $columnPadding = "`t" * ($firstColumn - 1)

    $lines = New-Object System.Collections.Generic.List[string]
    for ($i = 1; $i -lt $firstRow; $i++) {
        $lines.Add("")
    }
    foreach ($line in ($content -split "\r?\n")) {
        $lines.Add(($columnPadding + $line).TrimEnd("`t"))
    }
    while ($lines.Count -gt 0 -and $lines[$lines.Count - 1].Trim() -eq "") {
        $lines.RemoveAt($lines.Count - 1)
    }

    return ($lines -join "`r`n")
}

function countTsvFields {
    # TSVの1行をExcelに貼り付けたときのセル数を返す。
    # Excelと同じく、" で始まるセルは閉じる " までを1セルとする（中のタブ・改行は区切りとしない）
    param (
        [string]$line
    )

    # 先頭にタブを足し、どのセルも「タブ＋中身」で数える（^ を使うと、先頭の空のセルの後のタブを読み飛ばして1セル少なくなる）
    return [regex]::Matches("`t${line}", '\t(?:"(?:[^"]|"")*"[^\t]*|[^\t]*)').Count
}

function toColumnName {
    # 列番号を列名に変換する（1 → A、27 → AA）
    param (
        [int]$number
    )

    $name = ""
    while ($number -gt 0) {
        $number--
        $name = [string][char](65 + ($number % 26)) + $name
        $number = [math]::Floor($number / 26)
    }
    return $name
}


function splitTsvCells {
    # TSVの1行をセルに分ける。" で始まるセルは閉じる " までを1セルとし、囲みの " を外して "" を " に戻す（countTsvFields と同じ区切り方）
    param (
        [string]$line
    )

    $cells = New-Object System.Collections.Generic.List[string]
    foreach ($match in [regex]::Matches("`t${line}", '\t(?:"(?:[^"]|"")*"[^\t]*|[^\t]*)')) {
        $cell = $match.Value.Substring(1)
        if ($cell -match '^"(?<inner>(?:[^"]|"")*)"(?<rest>.*)$') {
            $cell = $Matches.inner.Replace('""', '"') + $Matches.rest
        }
        $cells.Add($cell)
    }
    return , $cells.ToArray()
}

function testTextTrimmed {
    # 文字が枠に入りきらず、省略（…）で切れているか。実際の幅（枠の ActualWidth）より、要る幅（文字を 1 行で出すのに要る幅）が
    # 誤差より大きいときだけ $true。幅 0 以下（まだ配置されていない・隠れている）は切れていないものとして $false。
    # 測る側（画面層）は幅を渡すだけで、切れているかの判定はここで決める
    param (
        [double]$actualWidth,
        [double]$requiredWidth,
        [double]$tolerance = 0.5   # 測り方による小数の誤差（これ以下の超過は切れていないとみなす）
    )

    if ($actualWidth -le 0) {
        return $false
    }
    return (($requiredWidth - $actualWidth) -gt $tolerance)
}

# テキストファイル（.txt など）の対象の拡張子・文字コードの判定・読み込み。
# 文字コードの判定（バイト列 → 文字コードまたはバイナリ）は、画面にもファイルにも触らない判断層の関数にする。
# ファイルを開いて読む関数（readTextFile）だけが状態層（ファイルに触る）。

# 既定のアプリで開く、取り込み対象のテキストファイルの拡張子（小文字）。
# 足す・減らすと tests\meta\safety.Tests.ps1 が固定の一覧で確かめる
${textOpenExtensions} = @(
    ".txt", ".csv", ".tsv", ".md", ".log", ".json", ".xml",
    ".c", ".h", ".cpp", ".cc", ".cxx", ".hpp", ".cs", ".java", ".kt", ".kts",
    ".go", ".rs", ".swift", ".scala", ".dart", ".vb", ".bas", ".pas", ".asm",
    ".m", ".r", ".jl", ".hs", ".ex", ".exs", ".erl", ".clj", ".groovy", ".lua",
    ".py", ".rb", ".pl", ".php", ".psm1", ".psd1", ".jsx", ".tsx", ".mjs", ".vue",
    ".sql", ".yaml", ".yml", ".toml", ".ini", ".cfg", ".conf", ".properties",
    ".gradle", ".cmake", ".proto", ".graphql", ".tf",
    ".html", ".htm", ".css", ".scss", ".less", ".rst", ".tex", ".diff", ".patch"
)

# 実行・登録が既定の動作になるため、既定のアプリではなくメモ帳で開く、取り込み対象のテキストファイルの拡張子（小文字）。
# ${textOpenExtensions} と合わせて ${textExtensions} になる。足す・減らすと tests\meta\safety.Tests.ps1 が固定の一覧で確かめる
${textNotepadExtensions} = @(".bat", ".cmd", ".ps1", ".vbs", ".js", ".reg", ".sh")

# 取り込み対象にするテキストファイルの拡張子（小文字。上の 2 つを合わせたもの）
${textExtensions} = @(${textOpenExtensions}) + @(${textNotepadExtensions})

# 元のファイルがこの大きさ（バイト）を超えたら、読まずに失敗にする
${textFileMaxBytes} = 10MB

# BOM の無い UTF-16 の判定に使う閾値（docs/design/indexing/text.md）。
#   先頭 ${textUtf16SampleBytes} バイト（偶数バイトに切り詰める）を 2 バイトずつの組として数え、
#   偶数の位置・奇数の位置のどちらかの NUL の割合が ${textUtf16NulRatioThreshold} 以上で、
#   もう片方が「多い側 ÷ ${textUtf16NulSkewDivisor}」以下なら UTF-16 と判定する
${textUtf16SampleBytes}      = 64KB
${textUtf16NulRatioThreshold} = 0.2
${textUtf16NulSkewDivisor}    = 10

# NUL の無い BOM 無し UTF-16（日本語だけの文章）の判定に使う閾値（docs/design/indexing/text.md）。
#   先頭 ${textUtf16SampleBytes} バイトを UTF-16 として読み、ひらがな・カタカナが ${textJpUtf16KanaRatio} 以上あり、
#   日本語の文章に出る文字（ASCII・句読点・かな・漢字・全角）以外が ${textJpUtf16OtherRatio} 以下なら UTF-16 と判定する
${textJpUtf16MinBytes}   = 8
${textJpUtf16KanaRatio}  = 0.2
${textJpUtf16OtherRatio} = 0.05

# 7 ビットだけ（ASCII の範囲）のバイト列は、ひらがなの UTF-16 と ASCII の文字列の見分けが付きにくいため、
# UTF-16 とみなすかなの割合をもっと高く求める
${textJpUtf16AsciiKanaRatio} = 0.9

# Shift_JIS として読めたとき、半角カナが「ASCII 以外の文字」のこの割合を超えると、半角カナの並びとして自然かを確かめる
# （濁点・半濁点が付けられるカナの後にしか来ないか。GBK・Big5 などを Shift_JIS として読むと崩れる）。
# EUC-JP としても読めるときは、この割合を超える側を EUC-JP とする
${textLegacyHalfKanaRatio} = 0.3

# 半角カナの数えは、読んだ結果の先頭からこの文字数だけ見る（大きなファイルで遅くならないため）
${textLegacySampleChars} = 32768

function testTextExtension {
    # ファイル名（またはパス）の拡張子が、取り込み対象のテキストの拡張子か（大文字・小文字を区別しない）
    param (
        [string]$path
    )

    $extension = [System.IO.Path]::GetExtension($path).ToLowerInvariant()
    return (${textExtensions} -contains $extension)
}

function testTextOpenWithNotepad {
    # ファイル名（またはパス）の拡張子が、既定のアプリではなくメモ帳で開くテキストの拡張子か（大文字・小文字を区別しない）。
    # .bat・.ps1・.js など、既定のアプリで開くと実行・登録になる拡張子がこちら
    param (
        [string]$path
    )

    $extension = [System.IO.Path]::GetExtension($path).ToLowerInvariant()
    return (${textNotepadExtensions} -contains $extension)
}

function getStrictUtf8Encoding {
    # 不正なバイト列（UTF-8として読めない並び）で例外にする UTF-8 のデコーダー（BOM は付けない）
    return [System.Text.Encoding]::GetEncoding("utf-8",
        [System.Text.EncoderExceptionFallback]::new(), [System.Text.DecoderExceptionFallback]::new())
}

function testTextPlausible {
    # 読んだ結果の文字列が、テキストとして自然か。制御文字（TAB・LF・FF・CR 以外）・私用領域・置き換え文字（U+FFFD）を含めば偽。
    # バイナリを Shift_JIS・EUC-JP などとして読んでしまったものを見分ける（Shift_JIS の外字（F040～F9FC）は私用領域に読まれるため偽になる）
    param (
        [string]$text
    )

    return (-not [regex]::IsMatch($text, '[\x00-\x08\x0B\x0E-\x1F\x7F-\x9F\uE000-\uF8FF\uFFFD]'))
}

function tryDecodeStrict {
    # コードページで読めないバイト列があれば $null、読めれば文字列
    param (
        [byte[]]$bytes,
        [int]$codePage
    )

    try {
        $encoding = [System.Text.Encoding]::GetEncoding($codePage,
            [System.Text.EncoderExceptionFallback]::new(), [System.Text.DecoderExceptionFallback]::new())
        return $encoding.GetString($bytes)
    } catch [System.Text.DecoderFallbackException] {
        return $null
    } catch [System.ArgumentException] {
        return $null
    }
}

function detectJapaneseUtf16WithoutNul {
    # NUL の無い（または NUL が改行の分しか無い）BOM 無し UTF-16（日本語だけの文章）の判定。
    # ひらがな・カタカナ・漢字は NUL を含まない。LE・BE の片方だけが日本語の文章として自然なときにその文字コードを返す。
    # 両方・どちらも当たらなければ $null。7 ビットだけのバイト列は、かなの割合をもっと高く求める（${textJpUtf16AsciiKanaRatio}）
    param (
        [byte[]]$bytes
    )

    $sampleLength = [Math]::Min($bytes.Length, [int]${textUtf16SampleBytes})
    $sampleLength -= ($sampleLength % 2)
    if ($sampleLength -lt ${textJpUtf16MinBytes}) { return $null }

    $ascii = $true
    for ($i = 0; $i -lt $sampleLength; $i++) {
        if ($bytes[$i] -ge 0x80) { $ascii = $false; break }
    }
    $kanaRatio = if ($ascii) { ${textJpUtf16AsciiKanaRatio} } else { ${textJpUtf16KanaRatio} }

    $found = @()
    foreach ($candidate in @(@("UTF16LE", [System.Text.Encoding]::Unicode), @("UTF16BE", [System.Text.Encoding]::BigEndianUnicode))) {
        $text = $candidate[1].GetString($bytes, 0, $sampleLength)
        $kana = [regex]::Matches($text, '[\u3040-\u30FF]').Count
        $other = [regex]::Matches($text, '[^\u0009\u000A\u000D -~\u3000-\u30FF\u4E00-\u9FFF\uFF00-\uFFEF]').Count
        if ($kana -ge ($text.Length * $kanaRatio) -and $other -le ($text.Length * ${textJpUtf16OtherRatio})) {
            $found += $candidate[0]
        }
    }
    if ($found.Count -eq 1) { return $found[0] }
    return $null
}

function getIso2022JpVerdict {
    # ISO-2022-JP（JIS）かの判定。戻り値: "yes" / "broken" / "none"
    #   yes: 7 ビットだけで、漢字への切り替え（ESC $ B・ESC $ @）を含み、ESC の並びがすべて規格のもの（ESC ( B・ESC ( J・ESC ( I を含む）
    #   broken: 漢字への切り替えを含むが、8 ビットのバイトや規格外の ESC の並びがある（JIS のつもりの壊れたもの。UTF-8 として読むと化けるので取り込まない）
    #   none: ESC が無い、または漢字への切り替えが無い（ESC ( B だけ・ESC [ などの端末の制御の並び）
    param (
        [byte[]]$bytes
    )

    if ([Array]::IndexOf($bytes, [byte]0x1B) -lt 0) { return "none" }
    # 1 バイトを 1 文字に読み（Latin-1）、正規表現で確かめる（バイトを 1 つずつ回さない。色つきのログなど ESC が多いだけのファイルを速く抜ける）
    $latin1 = [System.Text.Encoding]::GetEncoding(28591).GetString($bytes)
    if (-not [regex]::IsMatch($latin1, '\x1B\$[B@]')) { return "none" }
    # 規格外の ESC の並び（末尾で切れたものを含む）か、8 ビットのバイトがあれば、壊れたもの
    $broken = [regex]::IsMatch($latin1, '\x1B(?!\$[B@]|\([BJI])') -or [regex]::IsMatch($latin1, '[\x80-\xFF]')
    if ($broken) { return "broken" }
    return "yes"
}

function testHalfWidthKanaNatural {
    # 半角カナを多く含む文字列が、半角カナの並びとして自然か。濁点（ﾞ）・半濁点（ﾟ）は、付けられるカナ
    # （ｦ ｳ ｶ～ﾄ ﾊ～ﾎ ﾜ。半濁点は ﾊ～ﾎ）の直後にしか来ない。GBK・Big5 などを Shift_JIS として読むと崩れる
    param (
        [string]$text
    )

    if ([regex]::IsMatch($text, '(?<![\uFF66\uFF73\uFF76-\uFF84\uFF8A-\uFF8E\uFF9C])\uFF9E')) { return $false }
    if ([regex]::IsMatch($text, '(?<![\uFF8A-\uFF8E])\uFF9F')) { return $false }
    return $true
}

function detectLegacyJapaneseEncoding {
    # UTF-8 として読めなかった NUL の無いバイト列が、Shift_JIS か EUC-JP か。決められなければ $null（取り込まない）。
    #   Shift_JIS: コードページ 932 として不正なバイト列が無く、制御文字などが出ない。半角カナが多い（${textLegacyHalfKanaRatio} 超）ときは、
    #              半角カナの並びとして自然（testHalfWidthKanaNatural）なものだけ
    #   EUC-JP: コードページ 51932 として不正なバイト列が無く、制御文字などが出ず、ひらがな・カタカナを含む
    #           （かなの無い漢字だけの文章は、GBK・EUC-KR と構造が同じで見分けが付かない）
    #   両方に当たるときは、Shift_JIS として読むと半角カナばかりになる（EUC-JP のかなの見え方）なら EUC-JP、そうでなければあいまいなので $null
    param (
        [byte[]]$bytes
    )

    $sjis = tryDecodeStrict $bytes 932
    $sjisOk = $false
    $sjisHalfKanaHeavy = $false
    if ($null -ne $sjis -and (testTextPlausible $sjis)) {
        # 半角カナの数えは、最初の ASCII 以外の文字から一定の長さだけ（先頭が長い ASCII だけの行でも判定が変わらないように）
        $first = [regex]::Match($sjis, '[^\u0000-\u007F]').Index
        $sample = if ($sjis.Length - $first -gt ${textLegacySampleChars}) { $sjis.Substring($first, [int]${textLegacySampleChars}) } else { $sjis.Substring($first) }
        $nonAscii = [regex]::Matches($sample, '[^\u0000-\u007F]').Count
        $halfKana = [regex]::Matches($sample, '[\uFF61-\uFF9F]').Count
        $sjisHalfKanaHeavy = ($halfKana -gt ($nonAscii * ${textLegacyHalfKanaRatio}))
        $sjisOk = (-not $sjisHalfKanaHeavy) -or (testHalfWidthKanaNatural $sjis)
    }

    $euc = tryDecodeStrict $bytes 51932
    $eucOk = ($null -ne $euc -and (testTextPlausible $euc) -and [regex]::IsMatch($euc, '[\u3040-\u30FF]'))

    if ($sjisOk -and -not $eucOk) { return "ShiftJIS" }
    if ($eucOk -and -not $sjisOk) { return "EUCJP" }
    if ($eucOk -and $sjisOk -and $sjisHalfKanaHeavy) { return "EUCJP" }
    return $null
}

function detectTextEncoding {
    # バイト列だけから文字コードを判定する（ファイルに触らない）。
    # 順に確かめる: BOM → NUL の偏り（BOM の無い UTF-16）→ NUL の無い日本語の UTF-16 → NUL を含むか（バイナリ） →
    #   ISO-2022-JP → UTF-8 として正しく読めるか → Shift_JIS・EUC-JP。判定できないもの（バイナリ・UTF-32・GBK など）は $null を返す
    #   戻り値: "UTF8" / "UTF16LE" / "UTF16BE" / "ShiftJIS" / "EUCJP" / "ISO2022JP" / $null（取り込まない）
    param (
        [byte[]]$bytes
    )

    if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF) {
        return "UTF8"
    }
    # UTF-32 の BOM は UTF-16LE の BOM（FF FE）と同じ並びで始まるため、先に確かめて取り込まない
    if ($bytes.Length -ge 4 -and (
            ($bytes[0] -eq 0xFF -and $bytes[1] -eq 0xFE -and $bytes[2] -eq 0 -and $bytes[3] -eq 0) -or
            ($bytes[0] -eq 0 -and $bytes[1] -eq 0 -and $bytes[2] -eq 0xFE -and $bytes[3] -eq 0xFF))) {
        return $null
    }
    if ($bytes.Length -ge 2 -and $bytes[0] -eq 0xFF -and $bytes[1] -eq 0xFE) {
        return "UTF16LE"
    }
    if ($bytes.Length -ge 2 -and $bytes[0] -eq 0xFE -and $bytes[1] -eq 0xFF) {
        return "UTF16BE"
    }

    $sampleLength = [Math]::Min($bytes.Length, [int]${textUtf16SampleBytes})
    $sampleLength -= ($sampleLength % 2)
    if ($sampleLength -gt 0) {
        $even = 0  # 偶数の位置（0, 2, …）の NUL の数
        $odd = 0   # 奇数の位置（1, 3, …）の NUL の数
        for ($i = 0; $i -lt $sampleLength; $i++) {
            if ($bytes[$i] -eq 0) {
                if (($i % 2) -eq 0) { $even++ } else { $odd++ }
            }
        }
        $n = $sampleLength / 2
        if ($odd -ge ($n * ${textUtf16NulRatioThreshold}) -and $even -le ($odd / ${textUtf16NulSkewDivisor})) {
            return "UTF16LE"
        }
        if ($even -ge ($n * ${textUtf16NulRatioThreshold}) -and $odd -le ($even / ${textUtf16NulSkewDivisor})) {
            return "UTF16BE"
        }
        if ($even -gt 0 -or $odd -gt 0) {
            # NUL が 20% に届かない。改行（CRLF）や全角スペース・「一」など下位バイトが 00 の文字だけが NUL の
            # 日本語の UTF-16 かを確かめる（偶数・奇数の両側に NUL があってよい）。それ以外はバイナリ（UTF-32 もここ）
            return (detectJapaneseUtf16WithoutNul $bytes)
        }
    }

    $utf16 = detectJapaneseUtf16WithoutNul $bytes
    if ($null -ne $utf16) { return $utf16 }

    # ここまでで BOM の無い UTF-16 とは判定できなかった。NUL（0x00）をファイル全体のどこかに含むものはバイナリとみなす
    if ([Array]::IndexOf($bytes, [byte]0) -ge 0) { return $null }

    $iso = getIso2022JpVerdict $bytes
    if ($iso -eq "yes") { return "ISO2022JP" }
    if ($iso -eq "broken") { return $null }

    if ($null -ne (tryDecodeStrict $bytes 65001)) {
        return "UTF8"
    }
    return (detectLegacyJapaneseEncoding $bytes)
}

function decodeTextBytes {
    # detectTextEncoding が返した文字コードで、バイト列を文字列にする（BOM は取り除く）
    param (
        [byte[]]$bytes,
        [string]$encodingName
    )

    switch ($encodingName) {
        "UTF8" {
            $offset = if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF) { 3 } else { 0 }
            return (getStrictUtf8Encoding).GetString($bytes, $offset, $bytes.Length - $offset)
        }
        "UTF16LE" {
            $offset = if ($bytes.Length -ge 2 -and $bytes[0] -eq 0xFF -and $bytes[1] -eq 0xFE) { 2 } else { 0 }
            return [System.Text.Encoding]::Unicode.GetString($bytes, $offset, $bytes.Length - $offset)
        }
        "UTF16BE" {
            $offset = if ($bytes.Length -ge 2 -and $bytes[0] -eq 0xFE -and $bytes[1] -eq 0xFF) { 2 } else { 0 }
            return [System.Text.Encoding]::BigEndianUnicode.GetString($bytes, $offset, $bytes.Length - $offset)
        }
        "ShiftJIS" {
            return [System.Text.Encoding]::GetEncoding(932).GetString($bytes)
        }
        "EUCJP" {
            return [System.Text.Encoding]::GetEncoding(51932).GetString($bytes)
        }
        "ISO2022JP" {
            return [System.Text.Encoding]::GetEncoding(50221).GetString($bytes)
        }
    }
    throw "不明な文字コードです（${encodingName}）。"
}

function splitTextLines {
    # 文字列を行に分ける（CRLF・LF・CR のどれでも1行。StreamReader.ReadLine と同じ分け方）。
    # 途中の空の行は残し、行末の空白は取り除き（TrimEnd）、末尾の空の行は捨てる
    param (
        [string]$text
    )

    $lines = New-Object System.Collections.Generic.List[string]
    $reader = New-Object System.IO.StringReader($text)
    try {
        $line = $reader.ReadLine()
        while ($null -ne $line) {
            $lines.Add($line.TrimEnd())
            $line = $reader.ReadLine()
        }
    } finally {
        $reader.Dispose()
    }
    while ($lines.Count -gt 0 -and $lines[$lines.Count - 1] -eq "") {
        $lines.RemoveAt($lines.Count - 1)
    }
    return , $lines.ToArray()
}

function readTextFile {
    # テキストファイルを読み、行の並び（splitTextLines と同じ形）にして返す。
    # 元のファイルは読み取りだけで開く（共有は copyFileShared と同じ ReadWrite|Delete）。インデックス作成は、作業領域のコピーをこれで読む。
    # 大きさの上限を超える・バイナリと判定したときは、取り込み一覧・ログにそのまま出す文言で例外にする。
    # maxBytes はテストで上限を小さく差し替えるための引数（既定は textFileMaxBytes）
    param (
        [string]$path,
        [long]$maxBytes = ${textFileMaxBytes}
    )

    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $stream = [System.IO.FileStream]::new((toLongPath $path), [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    try {
        if ($stream.Length -gt $maxBytes) {
            throw "ファイルサイズが大きすぎるため更新できません。"
        }
        $bytes = New-Object byte[] ([int]$stream.Length)
        $read = 0
        while ($read -lt $bytes.Length) {
            $n = $stream.Read($bytes, $read, $bytes.Length - $read)
            if ($n -eq 0) { break }
            $read += $n
        }
    } finally {
        $stream.Dispose()
    }

    $encodingName = detectTextEncoding $bytes
    if ($null -eq $encodingName) {
        throw "テキストファイルではないため更新できません。"
    }
    return (splitTextLines (decodeTextBytes $bytes $encodingName))
}

# PDF の暗号化（標準のセキュリティハンドラー）を、空の利用者パスワードで復号する部品。PowerShell だけで書く（外の部品・Office を使わない）。
# 画面にもファイルにも触らない。pdf_file.ps1 の readPdfPages が、ストリームを取り出すときに使う。
#   読む    : AES-256（V5・R5・R6）。開くのに利用者パスワードが要らない（空のパスワードで鍵が作れて、/U の検証用のハッシュと合う）PDF だけ。
#   読まない: パスワードが要る PDF、AES-256 以外（RC4 40・128 ビット、AES-128 など。鍵の計算に MD5 が要り、FIPS 準拠を強制した機械で使えないため、
#             自前でも書かない。パスワードが要るかどうかも判定せず、必ず「方式に対応していない」にする）。例外にする（そのファイルだけ失敗）。
# 復号するのはストリームだけ（内容・フォントの対応表・オブジェクトのストリーム）。文字列は、読む内容がストリームの中にあるため復号しない。
# 使うのは SHA-2 と AES だけで、FIPS でも使える *CryptoServiceProvider の型を使う（SHA256Managed・AesManaged は FIPS で例外になる）。
# 鍵・途中の値は、例外の文にも記録にも出さない。壊れた辞書は、決まった長さの確かめと、R6 の繰り返しの上限（300 回。仕様では最大でも 288 回で終わる）で止める。
# 例外の文言は「PDF」で始める（readPdfPages は、それ以外の例外を「壊れている」に言い換える）。

# R6 の鍵の計算の繰り返しの上限（仕様では最後のバイトで終わる。最大でも 64 + 224 = 288 回で必ず終わる）
${pdfCryptR6MaxRounds} = 300

# 対応していない方式の例外の文
${pdfCryptUnsupported} = "PDFの暗号化の方式に対応していないため読めません。"

function joinPdfCryptBytes {
    # バイト列を順につなげる
    param (
        [object[]]$parts
    )

    $ms = [System.IO.MemoryStream]::new()
    foreach ($part in $parts) {
        if ($null -eq $part) { continue }
        $bytes = [byte[]]$part
        $ms.Write($bytes, 0, $bytes.Length)
    }
    return , $ms.ToArray()
}

function getPdfSha {
    # SHA-256・384・512
    param (
        [int]$bits,
        [byte[]]$data
    )

    if ($bits -eq 256) { $hash = New-Object System.Security.Cryptography.SHA256CryptoServiceProvider }
    elseif ($bits -eq 384) { $hash = New-Object System.Security.Cryptography.SHA384CryptoServiceProvider }
    else { $hash = New-Object System.Security.Cryptography.SHA512CryptoServiceProvider }
    try {
        return , $hash.ComputeHash($data)
    } finally {
        $hash.Dispose()
    }
}

function invokePdfAesCbc {
    # AES-CBC（詰め物なし。data は 16 の倍数）
    param (
        [byte[]]$key,
        [byte[]]$iv,
        [byte[]]$data,
        [bool]$encrypt
    )

    $aes = New-Object System.Security.Cryptography.AesCryptoServiceProvider
    try {
        $aes.Mode = [System.Security.Cryptography.CipherMode]::CBC
        $aes.Padding = [System.Security.Cryptography.PaddingMode]::None
        $aes.Key = $key
        $aes.IV = $iv
        if ($encrypt) { $transform = $aes.CreateEncryptor() } else { $transform = $aes.CreateDecryptor() }
        try {
            return , $transform.TransformFinalBlock($data, 0, $data.Length)
        } finally {
            $transform.Dispose()
        }
    } finally {
        $aes.Dispose()
    }
}

function getPdfCryptHashR56 {
    # R5・R6 の利用者パスワードのハッシュ（PDF 2.0 の Algorithm 2.B。R5 は SHA-256 の 1 回だけ）。32 バイトを返す
    param (
        [int]$revision,
        [byte[]]$passBytes,
        [byte[]]$salt,
        [byte[]]$userData
    )

    $k = getPdfSha 256 (joinPdfCryptBytes @($passBytes, $salt, $userData))
    if ($revision -lt 6) { return , $k }
    $round = 0
    do {
        $unit = joinPdfCryptBytes @($passBytes, $k, $userData)
        $repeated = New-Object byte[] ($unit.Length * 64)
        for ($j = 0; $j -lt 64; $j++) {
            [Array]::Copy($unit, 0, $repeated, $j * $unit.Length, $unit.Length)
        }
        $aesKey = New-Object byte[] 16
        $aesIv = New-Object byte[] 16
        [Array]::Copy($k, 0, $aesKey, 0, 16)
        [Array]::Copy($k, 16, $aesIv, 0, 16)
        $e = invokePdfAesCbc $aesKey $aesIv $repeated $true
        # 先頭 16 バイトを 1 つの大きな数とみなして 3 で割った余り（256 を 3 で割ると 1 余るので、バイトの和の余りと同じ）
        $sum = 0
        for ($j = 0; $j -lt 16; $j++) { $sum += $e[$j] }
        $k = getPdfSha (256 + 128 * ($sum % 3)) $e
        $round++
    } while (($round -lt 64 -or $e[$e.Length - 1] -gt $round - 32) -and $round -lt ${pdfCryptR6MaxRounds})
    $result = New-Object byte[] 32
    [Array]::Copy($k, 0, $result, 0, 32)
    return , $result
}

function getPdfStringBytes {
    # PDF の文字列（@{PdfType="str"}）をバイト列にする。文字列でなければ $null
    param (
        $value
    )

    if ($value -is [hashtable] -and $value.ContainsKey("PdfType") -and $value["PdfType"] -eq "str") {
        return , (${pdfLatin1}.GetBytes([string]$value["V"]))
    }
    return $null
}

function getPdfSlice {
    # バイト列の一部を新しい配列に写す
    param (
        [byte[]]$bytes,
        [int]$offset,
        [int]$length
    )

    $out = New-Object byte[] $length
    [Array]::Copy($bytes, $offset, $out, 0, $length)
    return , $out
}

function getPdfKeyR56 {
    # R5・R6 のファイルの鍵を、空の利用者パスワードで作る。/U の検証用のハッシュと合わなければ「パスワードが必要」の例外。
    # userBytes は /U（48 バイト以上）、userExtra は /UE（32 バイト以上）
    param (
        [int]$revision,
        [byte[]]$userBytes,
        [byte[]]$userExtra
    )

    $empty = New-Object byte[] 0
    $check = getPdfCryptHashR56 $revision $empty (getPdfSlice $userBytes 32 8) $empty
    $same = $true
    for ($i = 0; $i -lt 32; $i++) { if ($check[$i] -ne $userBytes[$i]) { $same = $false } }
    if (-not $same) { throw "PDFにパスワードが必要なため読めません。" }
    $intermediate = getPdfCryptHashR56 $revision $empty (getPdfSlice $userBytes 40 8) $empty
    return , (invokePdfAesCbc $intermediate (New-Object byte[] 16) (getPdfSlice $userExtra 0 32) $false)
}

function getPdfCryptMethod {
    # 暗号化フィルター（CF の項目）の方式を返す。AES-256（/AESV3）は AESV3、/None と /Identity は復号しない（None）。
    # それ以外は、対応しない方式として例外にする
    param (
        [hashtable]$doc,
        $cf,
        [string]$name
    )

    if ($name -ceq "/Identity") { return "None" }
    if (-not (testPdfDict $cf) -or $name.Length -lt 2) {
        throw ${pdfCryptUnsupported}
    }
    $filter = resolvePdf $doc $cf[$name.Substring(1)]
    if (-not (testPdfDict $filter)) {
        throw ${pdfCryptUnsupported}
    }
    $cfm = resolvePdf $doc $filter["CFM"]
    if ($cfm -ceq "/None") { return "None" }
    if ($cfm -ceq "/AESV3") { return "AESV3" }
    throw ${pdfCryptUnsupported}
}

function newPdfCrypt {
    # Encrypt の辞書（解決済み）から、空の利用者パスワードで鍵を作り、/U と照らして合えば復号の設定を返す。
    # 返す値: @{ Key; StmMethod; Cf }。AES-256（V5・R5・R6）だけを読む。
    # パスワードが要る（空のパスワードが /U と合わない）・対応しない方式・辞書が壊れているときは、そのファイルだけ例外にする
    param (
        [hashtable]$doc,
        [hashtable]$enc
    )

    if ((resolvePdf $doc $enc["Filter"]) -cne "/Standard") { throw ${pdfCryptUnsupported} }
    $v = resolvePdf $doc $enc["V"]
    $r = resolvePdf $doc $enc["R"]
    if ($v -isnot [double] -or $r -isnot [double]) { throw ${pdfCryptUnsupported} }
    if ($v -ne 5.0 -or ($r -ne 5.0 -and $r -ne 6.0)) { throw ${pdfCryptUnsupported} }
    $r = [int]$r

    # 復号の方式（ストリーム）
    $cf = resolvePdf $doc $enc["CF"]
    $stmName = resolvePdf $doc $enc["StmF"]
    if ($null -eq $stmName) { $stmName = "/Identity" }
    if ($stmName -isnot [string]) { throw ${pdfCryptUnsupported} }
    $method = getPdfCryptMethod $doc $cf $stmName

    $userBytes = getPdfStringBytes (resolvePdf $doc $enc["U"])
    $userExtra = getPdfStringBytes (resolvePdf $doc $enc["UE"])
    if ($null -eq $userBytes -or $userBytes.Length -lt 48 -or $null -eq $userExtra -or $userExtra.Length -lt 32) {
        throw "PDFの暗号化の情報が壊れているため読めません。"
    }
    $key = getPdfKeyR56 $r $userBytes $userExtra
    return @{ Key = $key; StmMethod = $method; Cf = $cf }
}

function getPdfStreamCryptMethod {
    # ストリーム 1 つの復号の方式（AESV3・None）を返す。相互参照のストリームは暗号化されない。
    # ストリームごとの /Crypt フィルターがあれば、その名前の方式（/Identity は復号しない）にする
    param (
        [hashtable]$doc,
        [hashtable]$stream
    )

    $crypt = $doc.Crypt
    $dict = $stream.Dict
    if ((resolvePdf $doc $dict["Type"]) -ceq "/XRef") { return "None" }
    $filters = resolvePdf $doc $dict["Filter"]
    if ($null -ne $filters) {
        $filterList = @($filters)
        $paramsList = @(resolvePdf $doc $dict["DecodeParms"])
        for ($i = 0; $i -lt $filterList.Count; $i++) {
            if ((resolvePdf $doc $filterList[$i]) -ceq "/Crypt") {
                $name = "/Identity"
                if ($i -lt $paramsList.Count) {
                    $params = resolvePdf $doc $paramsList[$i]
                    if ((testPdfDict $params) -and $null -ne (resolvePdf $doc $params["Name"])) { $name = resolvePdf $doc $params["Name"] }
                }
                if ($name -isnot [string]) { throw ${pdfCryptUnsupported} }
                return (getPdfCryptMethod $doc $crypt.Cf $name)
            }
        }
    }
    return $crypt.StmMethod
}

function unprotectPdfData {
    # ストリームの中身（圧縮を戻す前）を復号する。AES-256 はファイルの鍵をそのまま使う
    param (
        [hashtable]$crypt,
        [string]$method,
        [byte[]]$data
    )

    if ($method -ceq "None") { return , $data }
    # AES-CBC。先頭 16 バイトが初期ベクトル、最後に PKCS#7 の詰め物
    if ($data.Length -eq 0) { return , $data }
    if ($data.Length -lt 32 -or $data.Length % 16 -ne 0) {
        throw "PDFの暗号化されたデータが壊れているため読めません。"
    }
    $plain = invokePdfAesCbc $crypt.Key (getPdfSlice $data 0 16) (getPdfSlice $data 16 ($data.Length - 16)) $false
    $pad = $plain[$plain.Length - 1]
    if ($pad -lt 1 -or $pad -gt 16) {
        throw "PDFの暗号化されたデータが壊れているため読めません。"
    }
    return , (getPdfSlice $plain 0 ($plain.Length - $pad))
}

# PDF ファイルの対象の拡張子・文字の読み取り。PowerShell だけで読む（外の部品・Office を使わない）。
# バイト列 → ページごとの文字列（readPdfPages）は、画面にもファイルにも触らない判断層の関数にする。
# ファイルを開いて読む関数（readPdfFile）だけが状態層（ファイルに触る）。
# 読む範囲と上限は docs/design/indexing/pdf.md、細工した PDF から身を守ることは docs/safety/checks.md。
#   読む    : 相互参照の表・相互参照のストリーム（オブジェクトのストリーム）、圧縮なし・FlateDecode、
#             文字の命令 Tj・TJ・'・"、行送り Td・TD・T*・Tm・TL（縦の位置が変わったときに行を分ける。ET では分けない）、
#             フォントの ToUnicode、ToUnicode の無い単純フォント（WinAnsi 相当）
#   暗号化   : 空の利用者パスワードで開ける PDF は復号して読む（pdf_crypt.ps1）。パスワードが要るもの・未対応の方式は例外にする。
#   読まない: FlateDecode 以外の圧縮、ToUnicode の無い複合フォント（CID）、壊れた相互参照（修復しない）。例外にする。
#             Form XObject（Do）・注釈・フォーム・しおりの文字は例外にせず、読み飛ばす
# 例外の文言は「PDF」で始める（readPdfPages は、それ以外の例外を「壊れている」に言い換える）。

# 取り込み対象にする PDF の拡張子（小文字）。足す・減らすと tests\meta\safety.Tests.ps1 が固定の一覧で確かめる
${pdfExtensions} = @(".pdf")

# 元のファイルがこの大きさ（バイト）を超えたら、読まずに失敗にする
${pdfFileMaxBytes} = 100MB
# 1 ファイルの解凍後の合計がこの大きさ（バイト）を超えたら、失敗にする（圧縮爆弾）
${pdfInflatedMaxBytes} = 100MB
# 相互参照のオブジェクトの数の上限
${pdfObjectMaxCount} = 1000000
# ページツリー・間接参照・配列や辞書の入れ子の深さの上限
${pdfNestMaxDepth} = 64
# ページ数の上限
${pdfPageMaxCount} = 10000
# TJ の数値がこの値以下（1/1000 文字幅。負の向きが右への詰め）で、前後の文字がどちらも半角のときだけ空白を入れる
${pdfGapThreshold} = -250
# 文字の対応表（ToUnicode）の項目の、1 ファイルの合計の上限
${pdfMapMaxEntries} = 1000000
# たどる相互参照（Prev・XRefStm）の数の上限
${pdfXrefMaxCount} = 1000
# ストリームの終わりを探して読み進める文字数の合計の上限（ファイルの大きさの何倍まで）。
# /Length の合わないストリームが順や逆順に並ぶだけなら、探す量は約 1 倍に収まる。その余裕を見て 4 倍にする
${pdfSearchMaxRatio} = 4
# 同じ行とみなす縦位置の差（ポイント）の上限
${pdfLineTolerance} = 1.0

${pdfLatin1} = [System.Text.Encoding]::GetEncoding(28591)
${pdfWinAnsi} = [System.Text.Encoding]::GetEncoding(1252)
${pdfDelimiters} = [char[]]@(0, 9, 10, 12, 13, 32, '(', ')', '<', '>', '[', ']', '{', '}', '/', '%')
${pdfStringStops} = [char[]]@('(', ')', '\')
# readPdfPageText の字句の切り出し用の正規表現。部品は 1 か所で定義し、2 つの正規表現をここから組み立てる。
# 区切り・空白は ${pdfDelimiters} と同じ（テストが全コードで確かめる）。実行時のコンパイル（RegexOptions.Compiled）は使わない。
${pdfRegexSpace} = '[\x00-\x20]*'
${pdfRegexNotStart} = '\x00-\x20()<>\[\]{}/%'
${pdfRegexRest} = '[^\x00\x09\x0A\x0C\x0D\x20()<>\[\]{}/%]'
${pdfRegexWord} = "[^${pdfRegexNotStart}]${pdfRegexRest}*"
${pdfRegexName} = "/${pdfRegexRest}*"
${pdfRegexString} = '\([^()\\]*\)'
# ページの内容で、文字の位置や文字列に効く命令（' と " は英字で始まらないので、正規表現には要らない）。readPdfPageText の分岐と同じであることをテストが確かめる
${pdfTextOpNames} = [string[]]@("Tj", "TJ", "Tf", "BT", "Td", "TD", "TL", "T*", "Tm", "BI")
${pdfRegexTextOps} = (@(${pdfTextOpNames} | ForEach-Object { [regex]::Escape($_) }) -join "|")
# 空白を飛ばして、(1) 数値・キーワード、または (2) 名前・入れ子もエスケープも無い文字列・<< >> [ ] { } を 1 つ取る。
# コメント・16 進の文字列・入れ子やエスケープのある文字列・単独の < > ) は取らない（readPdfToken の 1 文字ずつ進める道に任せる）
${pdfTokenRegex} = [regex]::new("\G(?>${pdfRegexSpace})(?:(${pdfRegexWord})|(${pdfRegexName}|${pdfRegexString}|<<|>>|[\[\]{}]))")
# ページの内容の読み取り用。字句の取り方は pdfTokenRegex と同じで、先頭に「読み飛ばす並び」を足してある（グループ 1。語は 2、それ以外は 3）。
# 読み飛ばす並び = 数・名前・単純な文字列などの引数が最大 16 個並び、文字に効かない命令（英字で始まる語で、pdfTextOpNames 以外）で終わる。
# 命令を読むと数・名前・文字列は捨てられるので、飛ばしても結果は変わらない。文字に効く命令の前の引数は要るので、並びの終わりが文字に効かない命令のときだけ飛ばす。
# 並びの個数に上限があるのは、引数が延々と続く内容で、試みのたびに最後まで走って遅くなる（字句の数の 2 乗）のを防ぐため。上限より長い並びは 1 字句ずつ読む（結果は同じ）。
# 配列・辞書・コメント・入れ子の文字列を含むところは、ここに合わず 1 字句ずつ読む。
${pdfRegexArgStart} = "[^${pdfRegexNotStart}A-Za-z'`"]"
${pdfRegexArg} = "(?:${pdfRegexArgStart}${pdfRegexRest}*|${pdfRegexName}|${pdfRegexString})"
${pdfRegexSkip} = "(?>(?>${pdfRegexSpace})${pdfRegexArg}){0,16}(?>${pdfRegexSpace})(?!(?:${pdfRegexTextOps})(?!${pdfRegexRest}))[A-Za-z]${pdfRegexRest}*"
${pdfPageRegex} = [regex]::new("\G(?:(${pdfRegexSkip})|(?>${pdfRegexSpace})(?:(${pdfRegexWord})|(${pdfRegexName}|${pdfRegexString}|<<|>>|[\[\]{}])))")

function testPdfExtension {
    # ファイル名（またはパス）の拡張子が、取り込み対象の PDF の拡張子か（大文字・小文字を区別しない）
    param (
        [string]$path
    )

    $extension = [System.IO.Path]::GetExtension($path).ToLowerInvariant()
    return (${pdfExtensions} -contains $extension)
}

function newPdfLimits {
    # 読み取りの上限。既定は上の値。テストで小さく差し替えるための引数
    param (
        [long]$maxInflated = ${pdfInflatedMaxBytes},
        [int]$maxObjects = ${pdfObjectMaxCount},
        [int]$maxDepth = ${pdfNestMaxDepth},
        [int]$maxPages = ${pdfPageMaxCount},
        [int]$maxMapEntries = ${pdfMapMaxEntries},
        [int]$maxXref = ${pdfXrefMaxCount},
        [double]$maxSearchRatio = ${pdfSearchMaxRatio}
    )

    return @{
        MaxInflated = $maxInflated; MaxObjects = $maxObjects; MaxDepth = $maxDepth; MaxPages = $maxPages
        MaxMapEntries = $maxMapEntries; MaxXref = $maxXref; MaxSearchRatio = $maxSearchRatio
    }
}

function newPdfLexer {
    param (
        [string]$text,
        [int]$position = 0
    )

    return @{ S = $text; P = $position; K = "" }
}

function readPdfToken {
    # 字句を 1 つ読んで値を返す。種類は $st.K に入る:
    #   num（数値。double）/ name（先頭の / を除いた名前）/ str（文字列。丸括弧・16 進。1 バイト 1 文字の文字列）/
    #   kw（キーワード・演算子）/ [ / ] / << / >> / eof
    # 文字列全体に正規表現を当てず、1 文字ずつ進める（壊れた入力で後戻りが増えて固まらないため）
    param (
        [hashtable]$st
    )

    $s = $st.S
    $n = $s.Length
    $p = $st.P
    while ($true) {
        while ($p -lt $n -and [int]$s[$p] -le 32) { $p++ }
        if ($p -ge $n) {
            $st.P = $p
            $st.K = "eof"
            return $null
        }
        $c = $s[$p]
        if ($c -eq '%') {
            $e = $s.IndexOfAny([char[]]@([char]10, [char]13), $p)
            if ($e -lt 0) { $p = $n } else { $p = $e }
            continue
        }
        if ($c -eq '/') {
            $e = $s.IndexOfAny(${pdfDelimiters}, $p + 1)
            if ($e -lt 0) { $e = $n }
            $name = $s.Substring($p + 1, $e - $p - 1)
            if ($name.Contains("#")) {
                # 名前の # の戻しは readPdfPageText の字句の取り方と同じ。変えるときは 2 か所をそろえる
                $name = [regex]::Replace($name, '#([0-9A-Fa-f]{2})', { param($m) [string][char][Convert]::ToInt32($m.Groups[1].Value, 16) })
            }
            $st.P = $e
            $st.K = "name"
            return $name
        }
        if ($c -eq '(') {
            $sb = [System.Text.StringBuilder]::new()
            $nest = 1
            $p++
            while ($p -lt $n) {
                $q = $s.IndexOfAny(${pdfStringStops}, $p)
                if ($q -lt 0) {
                    [void]$sb.Append($s, $p, $n - $p)
                    $p = $n
                    break
                }
                [void]$sb.Append($s, $p, $q - $p)
                $ch = $s[$q]
                if ($ch -eq '(') {
                    $nest++
                    [void]$sb.Append('(')
                    $p = $q + 1
                } elseif ($ch -eq ')') {
                    $nest--
                    $p = $q + 1
                    if ($nest -eq 0) { break }
                    [void]$sb.Append(')')
                } else {
                    $q++
                    if ($q -ge $n) { $p = $n; break }
                    $e = $s[$q]
                    $p = $q + 1
                    if ($e -ceq 'n') { [void]$sb.Append([char]10) }
                    elseif ($e -ceq 'r') { [void]$sb.Append([char]13) }
                    elseif ($e -ceq 't') { [void]$sb.Append([char]9) }
                    elseif ($e -ceq 'b') { [void]$sb.Append([char]8) }
                    elseif ($e -ceq 'f') { [void]$sb.Append([char]12) }
                    elseif ($e -ge '0' -and $e -le '7') {
                        $value = [int]$e - 48
                        $digits = 1
                        while ($digits -lt 3 -and $p -lt $n -and $s[$p] -ge '0' -and $s[$p] -le '7') {
                            $value = $value * 8 + ([int]$s[$p] - 48)
                            $p++
                            $digits++
                        }
                        [void]$sb.Append([char]($value -band 255))
                    } elseif ($e -eq "`r") {
                        if ($p -lt $n -and $s[$p] -eq "`n") { $p++ }
                    } elseif ($e -eq "`n") {
                        # 行の継続（何も入れない）
                    } else {
                        [void]$sb.Append($e)
                    }
                }
            }
            $st.P = $p
            $st.K = "str"
            return $sb.ToString()
        }
        if ($c -eq '<') {
            if ($p + 1 -lt $n -and $s[$p + 1] -eq '<') {
                $st.P = $p + 2
                $st.K = "<<"
                return $null
            }
            $e = $s.IndexOf('>', $p + 1)
            if ($e -lt 0) { $e = $n }
            $hex = $s.Substring($p + 1, $e - $p - 1) -replace '[^0-9A-Fa-f]', ''
            if ($hex.Length % 2 -eq 1) { $hex += "0" }
            $sb = [System.Text.StringBuilder]::new()
            for ($i = 0; $i -lt $hex.Length; $i += 2) {
                [void]$sb.Append([char][Convert]::ToInt32($hex.Substring($i, 2), 16))
            }
            $st.P = [Math]::Min($e + 1, $n)
            $st.K = "str"
            return $sb.ToString()
        }
        if ($c -eq '>') {
            if ($p + 1 -lt $n -and $s[$p + 1] -eq '>') {
                $st.P = $p + 2
                $st.K = ">>"
                return $null
            }
            $p++
            continue
        }
        if ($c -eq '[') { $st.P = $p + 1; $st.K = "["; return $null }
        if ($c -eq ']') { $st.P = $p + 1; $st.K = "]"; return $null }
        if ($c -eq ')' ) { $p++; continue }
        if ($c -eq '{' -or $c -eq '}') { $st.P = $p + 1; $st.K = "kw"; return [string]$c }

        $e = $s.IndexOfAny(${pdfDelimiters}, $p)
        if ($e -lt 0) { $e = $n }
        $token = $s.Substring($p, $e - $p)
        $st.P = $e
        $d = 0.0
        if (($c -ge '0' -and $c -le '9') -or $c -eq '-' -or $c -eq '+' -or $c -eq '.') {
            # 数の判定は readPdfPageText の字句の取り方（2 か所）と同じ。変えるときは 3 か所をそろえる
            if ([double]::TryParse($token, [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$d) -and -not [double]::IsInfinity($d) -and -not [double]::IsNaN($d)) {
                $st.K = "num"
                return $d
            }
        }
        $st.K = "kw"
        return $token
    }
}

function readPdfValue {
    # 値（数値・名前 "/名前"・文字列 @{PdfType="str"}・配列 List・辞書 Hashtable・間接参照 @{PdfType="ref"; N}・真偽・null）を 1 つ読む。
    # 読み終わったあと $st.K が ] / >> / eof なら、値でなく終わりの印を読んだ（戻り値は $null）
    param (
        [hashtable]$doc,
        [hashtable]$st,
        [int]$depth,
        [bool]$allowRef = $true
    )

    if ($depth -gt $doc.Limits.MaxDepth) {
        throw "PDFの入れ子が深すぎるため読めません。"
    }
    $v = readPdfToken $st
    $kind = $st.K
    if ($kind -eq "num") {
        if ($allowRef -and $v -ge 0 -and $v -le 2147483647 -and $v -eq [Math]::Floor($v)) {
            $save = $st.P
            $g = readPdfToken $st
            if ($st.K -eq "num" -and $g -ge 0 -and $g -eq [Math]::Floor($g)) {
                $r = readPdfToken $st
                if ($st.K -eq "kw" -and $r -ceq "R") {
                    $st.K = "val"
                    return @{ PdfType = "ref"; N = [int]$v }
                }
            }
            $st.P = $save
            $st.K = "num"
        }
        return $v
    }
    if ($kind -eq "name") { return "/$v" }
    if ($kind -eq "str") { return @{ PdfType = "str"; V = $v } }
    if ($kind -eq "[") {
        $list = [System.Collections.Generic.List[object]]::new()
        while ($true) {
            $item = readPdfValue $doc $st ($depth + 1) $allowRef
            if ($st.K -eq "]" -or $st.K -eq "eof" -or $st.K -eq ">>") { break }
            if ($list.Count -ge $doc.Limits.MaxObjects) {
                throw "PDFの配列の要素の数が上限を超えるため読めません。"
            }
            $list.Add($item)
        }
        $st.K = "val"
        return , $list
    }
    if ($kind -eq "<<") {
        $dict = [System.Collections.Hashtable]::new()
        while ($true) {
            $key = readPdfToken $st
            if ($st.K -eq ">>" -or $st.K -eq "eof") { break }
            if ($st.K -ne "name") { continue }
            $item = readPdfValue $doc $st ($depth + 1) $allowRef
            if ($st.K -eq ">>" -or $st.K -eq "eof") { break }
            $dict[$key] = $item
            if ($dict.Count -gt $doc.Limits.MaxObjects) {
                throw "PDFの辞書の項目の数が上限を超えるため読めません。"
            }
        }
        $st.K = "val"
        return , $dict
    }
    if ($kind -eq "kw") {
        if ($v -ceq "true") { return $true }
        if ($v -ceq "false") { return $false }
        return $null
    }
    return $null
}

function testPdfRef {
    param ($v)
    return ($v -is [hashtable] -and $v.ContainsKey("PdfType") -and $v["PdfType"] -eq "ref")
}

function testPdfStream {
    param ($v)
    return ($v -is [hashtable] -and $v.ContainsKey("PdfType") -and $v["PdfType"] -eq "stream")
}

function testPdfDict {
    param ($v)
    return ($v -is [System.Collections.Hashtable] -and -not $v.ContainsKey("PdfType"))
}

function resolvePdf {
    # 間接参照をたどって値を返す（たどる回数に上限。循環は例外）
    param (
        [hashtable]$doc,
        $v
    )

    $count = 0
    while (testPdfRef $v) {
        $count++
        if ($count -gt $doc.Limits.MaxDepth) {
            throw "PDFの参照が循環しているため読めません。"
        }
        $v = getPdfObject $doc $v["N"]
    }
    return $v
}

function getPdfObject {
    # 番号のオブジェクトを読んで返す（読んだものは控える）。相互参照に無い・解放済みは $null。
    # 読んでいる最中に同じ番号を読もうとしたら（循環）、例外にする
    param (
        [hashtable]$doc,
        [int]$num
    )

    if ($doc.Cache.ContainsKey($num)) { return $doc.Cache[$num] }
    if (-not $doc.Xref.ContainsKey($num)) { return $null }
    $entry = $doc.Xref[$num]
    if ($entry.Type -eq 0) { return $null }
    if ($doc.Loading.ContainsKey($num)) {
        throw "PDFの参照が循環しているため読めません。"
    }
    if ($doc.Loading.Count -ge $doc.Limits.MaxDepth) {
        throw "PDFの参照が深すぎるため読めません。"
    }
    $doc.Loading[$num] = $true
    try {
        if ($entry.Type -eq 1) {
            $value = readPdfIndirectAt $doc $entry.Offset $num
        } else {
            $value = readPdfFromObjectStream $doc $entry.Stream $entry.Index $num
        }
    } finally {
        $doc.Loading.Remove($num)
    }
    $doc.Cache[$num] = $value
    return $value
}

function readPdfIndirectAt {
    # オフセットにある "N G obj ... endobj" を読む。ストリームなら @{PdfType="stream"; Dict; Start; Length} を返す。
    # expected が 0 以上なら、番号が合うことも確かめる
    param (
        [hashtable]$doc,
        [long]$offset,
        [int]$expected
    )

    $text = $doc.Text
    if ($offset -lt 0 -or $offset -ge $text.Length) {
        throw "PDFの相互参照がファイルの外を指しているため読めません。"
    }
    $st = newPdfLexer $text ([int]$offset)
    $a = readPdfToken $st
    $aKind = $st.K
    $gen = readPdfToken $st
    $c = readPdfToken $st
    if ($aKind -ne "num" -or $st.K -ne "kw" -or $c -cne "obj") {
        throw "PDFのオブジェクトが見つからないため読めません。"
    }
    if ($expected -ge 0 -and [int]$a -ne $expected) {
        throw "PDFのオブジェクトの番号が相互参照と合わないため読めません。"
    }
    $value = readPdfValue $doc $st 0
    if (-not (testPdfDict $value)) { return $value }

    $save = $st.P
    $t = readPdfToken $st
    if ($st.K -ne "kw" -or $t -cne "stream") { return $value }
    $start = $st.P
    if ($start -lt $text.Length -and $text[$start] -eq "`r") { $start++ }
    if ($start -lt $text.Length -and $text[$start] -eq "`n") { $start++ }
    $length = -1
    $declared = resolvePdf $doc $value["Length"]
    if ($declared -is [double] -and $declared -ge 0 -and $start + $declared -le $text.Length) {
        $after = [int]($start + $declared)
        $skip = 0
        while ($skip -lt 4 -and $after + $skip -lt $text.Length -and [int]$text[$after + $skip] -le 32) { $skip++ }
        if ([string]::CompareOrdinal($text, $after + $skip, "endstream", 0, 9) -eq 0) { $length = [int]$declared }
    }
    if ($length -lt 0) {
        # 長さが合わないストリームが多くても、同じ範囲を何度も探さないよう、直前に見つけた位置を使い回す
        # [From, At) には "endstream" の始まりが無い。前より手前から探すときは、手前の分だけ探して無ければ At を使う
        $found = $doc.EndSearch
        if ($start -ge $found.From -and $start -le $found.At) {
            $end = $found.At
        } elseif ($start -lt $found.From -and $found.At -ge $found.From) {
            $span = [Math]::Min($found.From - $start + 8, $text.Length - $start)
            $end = $text.IndexOf("endstream", $start, $span, [StringComparison]::Ordinal)
            if ($end -lt 0 -or $end -ge $found.From) {
                $doc.Searched += $span
                $end = $found.At
            } else {
                $doc.Searched += $end - $start
            }
            $found.From = $start
            $found.At = $end
        } else {
            $end = $text.IndexOf("endstream", $start, [StringComparison]::Ordinal)
            if ($end -lt 0) {
                throw "PDFのストリームの終わりが無いため読めません。"
            }
            $doc.Searched += $end - $start
            $found.From = $start
            $found.At = $end
        }
        if ($doc.Searched -gt $doc.Limits.MaxSearchRatio * $text.Length) {
            throw "PDFのストリームの終わりを探す量が上限を超えるため読めません。"
        }
        $length = $end - $start
        if ($length -gt 0 -and $text[$start + $length - 1] -eq "`n") { $length-- }
        if ($length -gt 0 -and $text[$start + $length - 1] -eq "`r") { $length-- }
    }
    return @{ PdfType = "stream"; Dict = $value; Start = $start; Length = $length; Num = [int]$a }
}

function expandPdfFlate {
    # zlib の先頭 2 バイトを飛ばして DeflateStream で解凍する。解凍後の合計が上限を超えたら例外
    param (
        [hashtable]$doc,
        [byte[]]$data
    )

    if ($data.Length -lt 3) {
        throw "PDFの圧縮されたデータが壊れているため読めません。"
    }
    $source = [System.IO.MemoryStream]::new($data, 2, $data.Length - 2)
    $deflate = [System.IO.Compression.DeflateStream]::new($source, [System.IO.Compression.CompressionMode]::Decompress)
    $output = [System.IO.MemoryStream]::new()
    $buffer = New-Object byte[] 65536
    try {
        while ($true) {
            $read = $deflate.Read($buffer, 0, $buffer.Length)
            if ($read -le 0) { break }
            $doc.Inflated += $read
            if ($doc.Inflated -gt $doc.Limits.MaxInflated) {
                throw "PDFの解凍後の大きさが上限を超えるため読めません。"
            }
            $output.Write($buffer, 0, $read)
        }
        return , $output.ToArray()
    } finally {
        $deflate.Dispose()
        $source.Dispose()
        $output.Dispose()
    }
}

function undoPdfPredictor {
    # FlateDecode の Predictor（PNG の 10～15）を戻す。TIFF（2）は読まない
    param (
        [byte[]]$data,
        $params
    )

    $predictor = 1
    if ((testPdfDict $params) -and $params.ContainsKey("Predictor")) { $predictor = [int]$params["Predictor"] }
    if ($predictor -le 1) { return , $data }
    if ($predictor -lt 10) {
        throw "PDFの未対応の圧縮のため読めません。"
    }
    $columns = 1
    $colors = 1
    $bits = 8
    if ($params.ContainsKey("Columns")) { $columns = [int]$params["Columns"] }
    if ($params.ContainsKey("Colors")) { $colors = [int]$params["Colors"] }
    if ($params.ContainsKey("BitsPerComponent")) { $bits = [int]$params["BitsPerComponent"] }
    $rowLength = [int][Math]::Ceiling($columns * $colors * $bits / 8.0)
    $bpp = [Math]::Max(1, [int][Math]::Ceiling($colors * $bits / 8.0))
    if ($rowLength -le 0) {
        throw "PDFの圧縮の指定が壊れているため読めません。"
    }
    $rows = [int][Math]::Floor($data.Length / ($rowLength + 1))
    $out = New-Object byte[] ($rows * $rowLength)
    for ($r = 0; $r -lt $rows; $r++) {
        $src = $r * ($rowLength + 1)
        $type = $data[$src]
        $dst = $r * $rowLength
        $prev = $dst - $rowLength
        for ($i = 0; $i -lt $rowLength; $i++) {
            $x = [int]$data[$src + 1 + $i]
            $left = 0
            if ($i -ge $bpp) { $left = [int]$out[$dst + $i - $bpp] }
            $up = 0
            if ($r -gt 0) { $up = [int]$out[$prev + $i] }
            $upLeft = 0
            if ($r -gt 0 -and $i -ge $bpp) { $upLeft = [int]$out[$prev + $i - $bpp] }
            if ($type -eq 0) { $v = $x }
            elseif ($type -eq 1) { $v = $x + $left }
            elseif ($type -eq 2) { $v = $x + $up }
            elseif ($type -eq 3) { $v = $x + [int][Math]::Floor(($left + $up) / 2) }
            elseif ($type -eq 4) {
                $pp = $left + $up - $upLeft
                $pa = [Math]::Abs($pp - $left)
                $pb = [Math]::Abs($pp - $up)
                $pc = [Math]::Abs($pp - $upLeft)
                if ($pa -le $pb -and $pa -le $pc) { $pred = $left } elseif ($pb -le $pc) { $pred = $up } else { $pred = $upLeft }
                $v = $x + $pred
            } else {
                throw "PDFの圧縮のデータが壊れているため読めません。"
            }
            $out[$dst + $i] = [byte]($v -band 255)
        }
    }
    return , $out
}

function getPdfStreamBytes {
    # ストリームの中身を、圧縮を戻して返す（圧縮なし・FlateDecode だけ。ほかは例外）
    param (
        [hashtable]$doc,
        [hashtable]$stream
    )

    $dict = $stream.Dict
    $filters = resolvePdf $doc $dict["Filter"]
    # 取り出す前の大きさも、圧縮の有無にかかわらず合計に数える（同じストリームを何度も参照されても増え続けないように）
    $doc.Inflated += $stream.Length
    if ($doc.Inflated -gt $doc.Limits.MaxInflated) {
        throw "PDFの解凍後の大きさが上限を超えるため読めません。"
    }
    $data = New-Object byte[] $stream.Length
    [Array]::Copy($doc.Bytes, $stream.Start, $data, 0, $stream.Length)
    if ($null -ne $doc.Crypt -and $stream.ContainsKey("Num")) {
        # 暗号化された PDF は、圧縮を戻す前に復号する
        $method = getPdfStreamCryptMethod $doc $stream
        $data = unprotectPdfData $doc.Crypt $method $data
    }
    if ($null -eq $filters) { return , $data }
    $filterList = @($filters)
    $paramsValue = resolvePdf $doc $dict["DecodeParms"]
    $paramsList = @($paramsValue)
    for ($i = 0; $i -lt $filterList.Count; $i++) {
        $name = resolvePdf $doc $filterList[$i]
        if ($name -ceq "/Crypt") {
            continue
        } elseif ($name -ceq "/FlateDecode" -or $name -ceq "/Fl") {
            $data = expandPdfFlate $doc $data
            $params = $null
            if ($i -lt $paramsList.Count) { $params = resolvePdf $doc $paramsList[$i] }
            $data = undoPdfPredictor $data $params
        } else {
            throw "PDFの未対応の圧縮のため読めません。"
        }
    }
    return , $data
}

function readPdfFromObjectStream {
    # オブジェクトのストリームの中の、番号のオブジェクトを読む
    param (
        [hashtable]$doc,
        [int]$streamNum,
        [int]$index,
        [int]$num
    )

    if (-not $doc.ObjStreams.ContainsKey($streamNum)) {
        $stream = getPdfObject $doc $streamNum
        if (-not (testPdfStream $stream)) {
            throw "PDFのオブジェクトのストリームが読めないため読めません。"
        }
        $bytes = getPdfStreamBytes $doc $stream
        $text = ${pdfLatin1}.GetString($bytes)
        $count = [int](resolvePdf $doc $stream.Dict["N"])
        $first = [int](resolvePdf $doc $stream.Dict["First"])
        if ($count -lt 0 -or $count -gt $doc.Limits.MaxObjects) {
            throw "PDFのオブジェクトの数が上限を超えるため読めません。"
        }
        # 見出しは 1 件に 4 文字（"1 0 "）以上要る。中身より多い件数は、確保する前に断る
        if ($count -gt [Math]::Floor($text.Length / 4)) {
            throw "PDFのオブジェクトのストリームの件数が中身と合わないため読めません。"
        }
        $st = newPdfLexer $text 0
        $numbers = New-Object int[] $count
        $offsets = New-Object int[] $count
        for ($i = 0; $i -lt $count; $i++) {
            $token = readPdfToken $st
            if ($st.K -ne "num") { throw "PDFのオブジェクトのストリームの見出しが読めないため読めません。" }
            $numbers[$i] = [int]$token
            $token = readPdfToken $st
            if ($st.K -ne "num") { throw "PDFのオブジェクトのストリームの見出しが読めないため読めません。" }
            $offsets[$i] = [int]$token
        }
        $doc.ObjStreams[$streamNum] = @{ Text = $text; First = $first; Numbers = $numbers; Offsets = $offsets }
    }
    $info = $doc.ObjStreams[$streamNum]
    $position = -1
    if ($index -ge 0 -and $index -lt $info.Numbers.Length -and $info.Numbers[$index] -eq $num) {
        $position = $index
    } else {
        # 位置は細工できるため、番号から位置への辞書を 1 度だけ作って引く（毎回先頭から探すと、件数の 2 乗の比較になる）
        if (-not $info.ContainsKey("Positions")) {
            $positions = @{}
            for ($i = 0; $i -lt $info.Numbers.Length; $i++) {
                if (-not $positions.ContainsKey($info.Numbers[$i])) { $positions[$info.Numbers[$i]] = $i }
            }
            $info.Positions = $positions
        }
        $position = if ($info.Positions.ContainsKey([int]$num)) { $info.Positions[[int]$num] } else { -1 }
    }
    if ($position -lt 0) { return $null }
    $st = newPdfLexer $info.Text ($info.First + $info.Offsets[$position])
    return (readPdfValue $doc $st 0)
}

function addPdfXrefEntry {
    param (
        [hashtable]$doc,
        [long]$num,
        [hashtable]$entry
    )

    # 同じ番号を繰り返しても増えないので、読んだ行の総数も数える
    $doc.XrefRows += 1
    if ($doc.XrefRows -gt $doc.Limits.MaxObjects) {
        throw "PDFのオブジェクトの数が上限を超えるため読めません。"
    }
    if ($num -lt 0 -or $num -gt 2147483647) { return }
    if (-not $doc.Xref.ContainsKey([int]$num)) {
        $doc.Xref[[int]$num] = $entry
        if ($doc.Xref.Count -gt $doc.Limits.MaxObjects) {
            throw "PDFのオブジェクトの数が上限を超えるため読めません。"
        }
    } elseif ($doc.Hybrid -and $doc.Xref[[int]$num].Type -eq 0 -and $entry.Type -ne 0) {
        $doc.Xref[[int]$num] = $entry
    }
}

function readPdfXref {
    # オフセットにある相互参照（表または相互参照のストリーム）を読み、前の相互参照（Prev・XRefStm）も順にたどる。
    # 新しいものが先に入る。暗号化（Encrypt）の辞書の場所と ID は doc に覚える。ファイルの外を指す・循環・数が上限を超えるのは例外。
    # 入れ子の呼び出しにせず、待ちの積み上げで読む（Prev が長く続いても呼び出しが深くならない）
    param (
        [hashtable]$doc,
        [long]$offset
    )

    $pending = [System.Collections.Generic.Stack[object]]::new()
    $pending.Push(@{ Offset = $offset; Hybrid = $false })
    while ($pending.Count -gt 0) {
        if ($doc.Visited.Count -ge $doc.Limits.MaxXref) {
            throw "PDFの相互参照の数が上限を超えるため読めません。"
        }
        $job = $pending.Pop()
        $next = readPdfXrefSection $doc $job.Offset $job.Hybrid
        # 先に XRefStm、次に Prev の順に読む（Prev を先に積む）
        if ($next.Prev -ge 0) { $pending.Push(@{ Offset = $next.Prev; Hybrid = $false }) }
        if ($next.Stm -ge 0) { $pending.Push(@{ Offset = $next.Stm; Hybrid = $true }) }
    }
}

function readPdfXrefSection {
    # 相互参照 1 つ分を読み、次に読む位置 @{ Stm; Prev }（無ければ -1）を返す。
    # hybrid（XRefStm で読むもの）は、表で「解放済み」とされた番号を上書きする（旧い読み手から隠すための作り）
    param (
        [hashtable]$doc,
        [long]$offset,
        [bool]$hybrid = $false
    )

    $doc.Hybrid = $hybrid

    $text = $doc.Text
    if ($offset -lt 0 -or $offset -ge $text.Length) {
        throw "PDFの相互参照がファイルの外を指しているため読めません。"
    }
    if ($doc.Visited.ContainsKey($offset)) {
        throw "PDFの相互参照が循環しているため読めません。"
    }
    $doc.Visited[$offset] = $true
    $p = [int]$offset
    while ($p -lt $text.Length -and [int]$text[$p] -le 32) { $p++ }
    $max = $doc.Limits.MaxObjects
    if ([string]::CompareOrdinal($text, $p, "xref", 0, 4) -eq 0) {
        $st = newPdfLexer $text ($p + 4)
        while ($true) {
            $a = readPdfToken $st
            if ($st.K -eq "kw" -and $a -ceq "trailer") { break }
            if ($st.K -ne "num") {
                throw "PDFの相互参照の表が読めないため読めません。"
            }
            $first = [long]$a
            $count = readPdfToken $st
            if ($st.K -ne "num" -or $count -lt 0 -or $count -gt $max) {
                throw "PDFの相互参照の表が読めない、またはオブジェクトの数が上限を超えるため読めません。"
            }
            $pp = $st.P
            for ($k = 0; $k -lt $count; $k++) {
                while ($pp -lt $text.Length -and [int]$text[$pp] -le 32) { $pp++ }
                $entryOffset = 0L
                $kind = ""
                if ($pp + 17 -lt $text.Length -and $text[$pp + 10] -eq " " -and $text[$pp + 16] -eq " " -and
                    [long]::TryParse($text.Substring($pp, 10), [ref]$entryOffset)) {
                    $kind = [string]$text[$pp + 17]
                    $pp += 18
                } else {
                    $st.P = $pp
                    $o = readPdfToken $st
                    $okO = ($st.K -eq "num")
                    [void](readPdfToken $st)
                    $t = readPdfToken $st
                    if (-not $okO -or $st.K -ne "kw") {
                        throw "PDFの相互参照の表が読めないため読めません。"
                    }
                    $entryOffset = [long]$o
                    $kind = [string]$t
                    $pp = $st.P
                }
                if ($kind -ceq "n" -and $entryOffset -gt 0) {
                    addPdfXrefEntry $doc ($first + $k) @{ Type = 1; Offset = $entryOffset }
                } else {
                    addPdfXrefEntry $doc ($first + $k) @{ Type = 0 }
                }
            }
            $st.P = $pp
        }
        $trailer = readPdfValue $doc $st 0
    } else {
        $stream = readPdfIndirectAt $doc $p -1
        if (-not (testPdfStream $stream) -or $stream.Dict["Type"] -cne "/XRef") {
            throw "PDFの相互参照が読めないため読めません。"
        }
        $trailer = $stream.Dict
        $data = getPdfStreamBytes $doc $stream
        $w = @(resolvePdf $doc $trailer["W"])
        if ($w.Count -ne 3) {
            throw "PDFの相互参照のストリームが壊れているため読めません。"
        }
        $w0 = [int]$w[0]
        $w1 = [int]$w[1]
        $w2 = [int]$w[2]
        if ($w0 -lt 0 -or $w1 -lt 0 -or $w2 -lt 0 -or $w0 -gt 8 -or $w1 -gt 8 -or $w2 -gt 8 -or ($w0 + $w1 + $w2) -eq 0) {
            throw "PDFの相互参照のストリームが壊れているため読めません。"
        }
        $rowLength = $w0 + $w1 + $w2
        $index = resolvePdf $doc $trailer["Index"]
        if ($null -eq $index) {
            $index = @(0, [int](resolvePdf $doc $trailer["Size"]))
        }
        $index = @($index)
        $pos = 0
        for ($g = 0; $g + 1 -lt $index.Count; $g += 2) {
            $first = [long]$index[$g]
            $count = [long]$index[$g + 1]
            if ($count -lt 0 -or $count -gt $max) {
                throw "PDFのオブジェクトの数が上限を超えるため読めません。"
            }
            for ($k = 0; $k -lt $count; $k++) {
                if ($pos + $rowLength -gt $data.Length) {
                    throw "PDFの相互参照のストリームが壊れているため読めません。"
                }
                $type = 1L
                if ($w0 -gt 0) {
                    $type = 0L
                    for ($j = 0; $j -lt $w0; $j++) { $type = $type * 256 + $data[$pos + $j] }
                }
                $f2 = 0L
                for ($j = 0; $j -lt $w1; $j++) { $f2 = $f2 * 256 + $data[$pos + $w0 + $j] }
                $f3 = 0L
                for ($j = 0; $j -lt $w2; $j++) { $f3 = $f3 * 256 + $data[$pos + $w0 + $w1 + $j] }
                $pos += $rowLength
                if ($type -eq 1) {
                    addPdfXrefEntry $doc ($first + $k) @{ Type = 1; Offset = $f2 }
                } elseif ($type -eq 2) {
                    addPdfXrefEntry $doc ($first + $k) @{ Type = 2; Stream = [int]$f2; Index = [int]$f3 }
                } else {
                    addPdfXrefEntry $doc ($first + $k) @{ Type = 0 }
                }
            }
        }
    }

    if (-not (testPdfDict $trailer)) {
        throw "PDFの相互参照のあとの情報が読めないため読めません。"
    }
    if ($trailer.ContainsKey("Encrypt") -and $null -eq $doc.EncryptEntry) {
        # 新しい方のトレーラーを使う。辞書は、相互参照がそろってから読む（readPdfPagesCore）
        $doc.EncryptEntry = $trailer["Encrypt"]
    }
    if ($null -eq $doc.Root -and $trailer.ContainsKey("Root")) {
        $doc.Root = $trailer["Root"]
    }
    $next = @{ Stm = -1L; Prev = -1L }
    if ($trailer.ContainsKey("XRefStm")) { $next.Stm = [long]$trailer["XRefStm"] }
    if ($trailer.ContainsKey("Prev")) { $next.Prev = [long]$trailer["Prev"] }
    return $next
}

function addPdfMapEntries {
    # 文字の対応表の項目を数え、1 ファイルの合計が上限を超えたら例外にする（doc が無いときは数えない）
    param (
        $doc,
        [long]$count
    )

    if ($null -eq $doc) { return }
    $doc.MapEntries += $count
    if ($doc.MapEntries -gt $doc.Limits.MaxMapEntries) {
        throw "PDFの文字の対応表が大きすぎるため読めません。"
    }
}

function readPdfToUnicode {
    # ToUnicode の CMap から、文字コード → 文字列の表 Map（キーは int）と、文字コードのバイト数 Width（0 は指定なし）を返す
    param (
        [string]$text,
        [hashtable]$doc = $null
    )

    $map = @{}
    $width = 0
    $st = newPdfLexer $text 0
    $utf16 = [System.Text.Encoding]::BigEndianUnicode
    while ($true) {
        $t = readPdfToken $st
        if ($st.K -eq "eof") { break }
        if ($st.K -ne "kw") { continue }
        if ($t -ceq "begincodespacerange") {
            while ($true) {
                $lo = readPdfToken $st
                if ($st.K -ne "str") { break }
                [void](readPdfToken $st)
                if ($width -eq 0 -and $lo.Length -ge 1 -and $lo.Length -le 2) { $width = $lo.Length }
            }
        } elseif ($t -ceq "beginbfchar") {
            while ($true) {
                $src = readPdfToken $st
                if ($st.K -ne "str") { break }
                $dst = readPdfToken $st
                if ($st.K -ne "str") { break }
                if ($src.Length -eq 0 -or $src.Length -gt 3) { continue }
                addPdfMapEntries $doc 1
                $map[(convertPdfCode $src)] = convertPdfUtf16 $dst $utf16
            }
        } elseif ($t -ceq "beginbfrange") {
            while ($true) {
                $lo = readPdfToken $st
                if ($st.K -ne "str") { break }
                $hi = readPdfToken $st
                if ($st.K -ne "str") { break }
                $dst = readPdfToken $st
                $kind = $st.K
                if ($lo.Length -eq 0 -or $lo.Length -gt 3 -or $hi.Length -eq 0 -or $hi.Length -gt 3) {
                    if ($kind -eq "[") {
                        while ($true) { [void](readPdfToken $st); if ($st.K -eq "]" -or $st.K -eq "eof") { break } }
                    }
                    continue
                }
                $from = convertPdfCode $lo
                $to = [Math]::Min((convertPdfCode $hi), $from + 65535)
                if ($kind -eq "str") {
                    $base = convertPdfUtf16 $dst $utf16
                    if ($base.Length -eq 0) { continue }
                    if ($to -ge $from) { addPdfMapEntries $doc ($to - $from + 1) }
                    $head = $base.Substring(0, $base.Length - 1)
                    $lastCode = [int]$base[$base.Length - 1]
                    for ($c = $from; $c -le $to; $c++) {
                        $map[[int]$c] = $head + [char](($lastCode + $c - $from) -band 65535)
                    }
                } elseif ($kind -eq "[") {
                    $c = $from
                    while ($true) {
                        $item = readPdfToken $st
                        if ($st.K -ne "str") { break }
                        if ($c -le $to) {
                            addPdfMapEntries $doc 1
                            $map[[int]$c] = convertPdfUtf16 $item $utf16
                        }
                        $c++
                    }
                }
            }
        }
    }
    return @{ Map = $map; Width = $width }
}

function convertPdfCode {
    # 1 バイト 1 文字の文字列を、ビッグエンディアンの文字コード（int）にする（3 バイトまで）
    param (
        [string]$s
    )

    $code = 0
    foreach ($ch in $s.ToCharArray()) { $code = $code * 256 + [int]$ch }
    return [int]$code
}

function convertPdfUtf16 {
    # 1 バイト 1 文字の文字列（UTF-16BE のバイト列）を文字列にする。奇数バイトのときは 1 バイトずつ文字にする
    param (
        [string]$s,
        $utf16
    )

    if ($s.Length % 2 -eq 1) { return $s }
    return $utf16.GetString(${pdfLatin1}.GetBytes($s))
}

function newPdfFont {
    # フォントの辞書から、文字列を文字にする規則 @{ Width; Map; NoMap } を作る。
    # ToUnicode があればそれを使う。無い単純フォントは WinAnsi 相当（Windows-1252）。無い複合フォント（CID）は NoMap（使ったときに例外）
    param (
        [hashtable]$doc,
        $dict
    )

    $font = @{ Width = 1; Map = $null; NoMap = $false }
    if (-not (testPdfDict $dict)) { return $font }
    $isComposite = ($dict["Subtype"] -ceq "/Type0")
    if ($isComposite) { $font.Width = 2 }
    $toUnicodeRef = $dict["ToUnicode"]
    $toUnicode = resolvePdf $doc $toUnicodeRef
    if (testPdfStream $toUnicode) {
        # 同じ ToUnicode を使うフォントが多くても、1 度だけ読む（番号ごとに控える）
        $key = $null
        if (testPdfRef $toUnicodeRef) { $key = $toUnicodeRef["N"] }
        if ($null -ne $key -and $doc.CMaps.ContainsKey($key)) {
            $cmap = $doc.CMaps[$key]
        } else {
            $bytes = getPdfStreamBytes $doc $toUnicode
            $cmap = readPdfToUnicode (${pdfLatin1}.GetString($bytes)) $doc
            if ($null -ne $key) { $doc.CMaps[$key] = $cmap }
        }
        $font.Map = $cmap.Map
        if ($cmap.Width -gt 0) { $font.Width = $cmap.Width }
    } elseif ($isComposite) {
        $font.NoMap = $true
    }
    return $font
}

function convertPdfStringToText {
    # 文字列（1 バイト 1 文字）を、フォントの規則で文字列にする
    param (
        $font,
        [string]$s
    )

    if ($null -ne $font -and $font.NoMap) {
        throw "PDFの文字の対応表が無いため読めません。"
    }
    if ($null -eq $font -or $null -eq $font.Map) {
        return ${pdfWinAnsi}.GetString(${pdfLatin1}.GetBytes($s))
    }
    $map = $font.Map
    $width = $font.Width
    $sb = [System.Text.StringBuilder]::new()
    for ($i = 0; $i -lt $s.Length; $i += $width) {
        if ($width -eq 2) {
            if ($i + 1 -ge $s.Length) { break }
            $code = [int]$s[$i] * 256 + [int]$s[$i + 1]
        } else {
            $code = [int]$s[$i]
        }
        if ($map.ContainsKey($code)) {
            [void]$sb.Append($map[$code])
        } elseif ($width -eq 1) {
            [void]$sb.Append(${pdfWinAnsi}.GetString([byte[]]@($code)))
        }
    }
    return $sb.ToString()
}

function testPdfHalfWidth {
    # 半角の文字か（ラテン文字の範囲）。TJ の詰めに空白を入れるかの判断に使う
    param (
        [char]$c
    )

    return ([int]$c -le 0x24F)
}

function getPdfGlyphCount {
    # 文字列が表す字形（フォントの 1 コード）の数。1 コードが 2 文字になる対応（合字）でも 1 と数える
    param (
        $font,
        [string]$s
    )

    if ($null -eq $font -or $null -eq $font.Map -or $font.Width -ne 2) { return $s.Length }
    return [int][Math]::Ceiling($s.Length / 2)
}

function addPdfText {
    # ページの文字に文字列を足す。詰め（Gap）が付いていて、前後の文字がどちらも半角のときだけ空白を入れる
    param (
        [hashtable]$ts,
        [string]$text,
        [int]$glyphs = 1
    )

    if ($text.Length -eq 0) { return }
    # 縦位置が前に出した文字と違うときだけ行を分ける（BT～ET で分かれていても、同じ縦位置なら同じ行）
    if ($ts.HasOut -and [Math]::Abs($ts.Y - $ts.OutY) -gt ${pdfLineTolerance}) {
        breakPdfLine $ts
    }
    $ts.HasOut = $true
    $ts.OutY = $ts.Y
    $ts.Run += $glyphs
    $sb = $ts.Sb
    if ($ts.Gap -and $sb.Length -gt 0) {
        $last = $sb[$sb.Length - 1]
        if ($last -ne "`n" -and $last -ne " " -and (testPdfHalfWidth $last) -and (testPdfHalfWidth $text[0]) -and $text[0] -ne " ") {
            [void]$sb.Append(" ")
        }
    }
    $ts.Gap = $false
    [void]$sb.Append($text)
}

function breakPdfLine {
    param (
        [hashtable]$ts
    )

    $sb = $ts.Sb
    if ($sb.Length -gt 0 -and $sb[$sb.Length - 1] -ne "`n") {
        [void]$sb.Append("`n")
    }
    $ts.Gap = $false
}

function readPdfPageText {
    # ページの内容（文字の命令）から文字列を作る。行送りは改行にする。
    # fontDict は フォント名 → フォント（辞書または参照）の辞書（無ければ $null）
    param (
        [hashtable]$doc,
        [string]$content,
        $fontDict
    )

    # Y は今の文字の縦位置（行の行列の y）、OutY は最後に出した文字の縦位置、Leading は行送り（TL）
    $ts = @{ Sb = [System.Text.StringBuilder]::new(); Gap = $false; Y = 0.0; OutY = 0.0; HasOut = $false; Leading = 0.0; Scale = 1.0; Run = 0 }
    # 字句は、関数を呼ばずに、位置指定の正規表現（トークンの切り出しは readPdfToken と同じ規則）でその場で切り出す。
    # 取れないもの（入れ子やエスケープのある文字列・16 進の文字列・コメントなど）だけ readPdfToken に任せる（$st.P で位置を渡す）
    $st = newPdfLexer $content 0
    $pos = 0
    $len = $content.Length
    $re = ${pdfPageRegex}
    $reTok = ${pdfTokenRegex}
    $emptyMatch = [System.Text.RegularExpressions.Match]::Empty
    $nums = [System.Collections.Generic.List[double]]::new()
    $lastStr = $null
    $lastName = $null
    $lastArray = $null
    $font = $null
    $fontSize = 0.0
    while ($true) {
        $m = if ($pos -lt $len) { $re.Match($content, $pos) } else { $emptyMatch }
        if ($m.Success) {
            $g = $m.Groups[1]
            if ($g.Success) {
                # 文字に効かない命令までの並びを、まとめて飛ばす
                $pos = $g.Index + $g.Length
                $nums.Clear()
                $lastStr = $null
                $lastName = $null
                $lastArray = $null
                continue
            }
            $g = $m.Groups[2]
            if ($g.Success) {
                $t = $g.Value
                $pos = $g.Index + $g.Length
                $kind = "kw"
                $c = $t[0]
                if (($c -ge '0' -and $c -le '9') -or $c -eq '-' -or $c -eq '+' -or $c -eq '.') {
                    $d = 0.0
                    # 数の判定は readPdfToken と、TJ の配列の中の取り方と同じ。変えるときは 3 か所をそろえる
                    if ([double]::TryParse($t, [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$d) -and -not [double]::IsInfinity($d) -and -not [double]::IsNaN($d)) {
                        $t = $d
                        $kind = "num"
                    }
                }
            } else {
                $g = $m.Groups[3]
                $t = $g.Value
                $pos = $g.Index + $g.Length
                $c = $t[0]
                if ($c -eq '/') {
                    $kind = "name"
                    $t = $t.Substring(1)
                    if ($t.Contains("#")) {
                        # 名前の # の戻しは readPdfToken と同じ。変えるときは 2 か所をそろえる
                        $t = [regex]::Replace($t, '#([0-9A-Fa-f]{2})', { param($m) [string][char][Convert]::ToInt32($m.Groups[1].Value, 16) })
                    }
                } elseif ($c -eq '(') {
                    $kind = "str"
                    $t = $t.Substring(1, $t.Length - 2)
                } elseif ($c -eq '[') { $kind = "["
                } elseif ($c -eq ']') { $kind = "]"
                } elseif ($c -eq '<') { $kind = "<<"
                } elseif ($c -eq '>') { $kind = ">>"
                } else { $kind = "kw" }
            }
        } else {
            $st.P = $pos
            $t = readPdfToken $st
            $kind = $st.K
            $pos = $st.P
        }
        if ($kind -eq "eof") { break }
        if ($kind -eq "num") {
            if ($nums.Count -ge 64) { $nums.Clear() }
            $nums.Add($t)
            continue
        }
        if ($kind -eq "name") { $lastName = $t; continue }
        if ($kind -eq "str") { $lastStr = $t; continue }
        if ($kind -eq "[") {
            $items = [System.Collections.Generic.List[object]]::new()
            while ($true) {
                $m = if ($pos -lt $len) { $reTok.Match($content, $pos) } else { $emptyMatch }
                if ($m.Success) {
                    $g = $m.Groups[1]
                    if ($g.Success) {
                        $pos = $g.Index + $g.Length
                        $c = $g.Value[0]
                        if (($c -ge '0' -and $c -le '9') -or $c -eq '-' -or $c -eq '+' -or $c -eq '.') {
                            $d = 0.0
                            # 数の判定は readPdfToken と、readPdfPageText の最初の字句の取り方と同じ。変えるときは 3 か所をそろえる
                            if ([double]::TryParse($g.Value, [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$d) -and -not [double]::IsInfinity($d) -and -not [double]::IsNaN($d)) {
                                $items.Add($d)
                            }
                        }
                    } else {
                        $g = $m.Groups[2]
                        $pos = $g.Index + $g.Length
                        $c = $g.Value[0]
                        if ($c -eq '(') { $items.Add($g.Value.Substring(1, $g.Value.Length - 2)) }
                        elseif ($c -eq ']') { break }
                    }
                } else {
                    $st.P = $pos
                    $item = readPdfToken $st
                    $pos = $st.P
                    if ($st.K -eq "]" -or $st.K -eq "eof") { break }
                    if ($st.K -eq "num" -or $st.K -eq "str") { $items.Add($item) }
                }
            }
            $lastArray = $items
            continue
        }
        if ($kind -eq "<<") {
            $nest = 1
            $st.P = $pos
            while ($nest -gt 0) {
                [void](readPdfToken $st)
                if ($st.K -eq "<<") { $nest++ } elseif ($st.K -eq ">>") { $nest-- } elseif ($st.K -eq "eof") { break }
            }
            $pos = $st.P
            continue
        }
        if ($kind -ne "kw") { continue }

        if ($t -ceq "Tj") {
            if ($null -ne $lastStr) { addPdfText $ts (convertPdfStringToText $font $lastStr) (getPdfGlyphCount $font $lastStr) }
        } elseif ($t -ceq "TJ") {
            if ($null -ne $lastArray) {
                foreach ($item in $lastArray) {
                    if ($item -is [string]) {
                        addPdfText $ts (convertPdfStringToText $font $item) (getPdfGlyphCount $font $item)
                    } elseif ($item -le ${pdfGapThreshold}) {
                        $ts.Gap = $true
                    }
                }
            }
        } elseif ($t -ceq "'" -or $t -ceq '"') {
            $ts.Y -= $ts.Leading * $ts.Scale
            $ts.Run = 0
            breakPdfLine $ts
            if ($null -ne $lastStr) { addPdfText $ts (convertPdfStringToText $font $lastStr) (getPdfGlyphCount $font $lastStr) }
        } elseif ($t -ceq "Tf") {
            $fontSize = if ($nums.Count -ge 1) { [Math]::Abs($nums[$nums.Count - 1]) } else { 0.0 }
            $font = $null
            if ($null -ne $lastName -and (testPdfDict $fontDict) -and $fontDict.ContainsKey($lastName)) {
                $font = getPdfFont $doc $fontDict[$lastName]
            }
        } elseif ($t -ceq "BT") {
            # テキストの行列は BT で初期化される（縦位置は 0 から）
            $ts.Y = 0.0
            $ts.Scale = 1.0
            $ts.Run = 0
        } elseif ($t -ceq "Td" -or $t -ceq "TD") {
            if ($nums.Count -ge 2) {
                # 縦の動きは、Tm の拡大（d）を掛けた値にする（`12 0 0 12 x y Tm` のあとの `0 -1 TD` は 12 ポイント動く）
                $ts.Y += $nums[1] * $ts.Scale
                if ($t -ceq "TD") { $ts.Leading = - $nums[1] }
                # 横にだけ動いたときは詰め。縦に動いたときは、次の文字を出すときに行を分ける。
                # 1 文字ずつ Td で並べる PDF（Chromium など）の文字を離さないよう、直前の Td 以降に出した文字が 1 文字以下で、
                # 前向きに 1 em より小さい動きは詰めにしない（空白は文字として入っている）。2 文字以上の語の後ろは空白でつなぐ
                $joined = ($fontSize -gt 0 -and $nums[0] -gt 0 -and $nums[0] -lt $fontSize -and $ts.Run -le 1)
                if ($nums[0] -ne 0 -and -not $joined) { $ts.Gap = $true }
                $ts.Run = 0
            }
        } elseif ($t -ceq "TL") {
            if ($nums.Count -ge 1) { $ts.Leading = $nums[0] }
        } elseif ($t -ceq "T*") {
            $ts.Y -= $ts.Leading * $ts.Scale
            $ts.Run = 0
            breakPdfLine $ts
        } elseif ($t -ceq "Tm") {
            if ($nums.Count -ge 6) {
                $ts.Y = $nums[5]
                # 上下を反転した行列（d が負）は、縦の動きの向きも反転するので、d の符号を残す
                $ts.Scale = [Math]::Sqrt($nums[2] * $nums[2] + $nums[3] * $nums[3])
                if ($nums[3] -lt 0) { $ts.Scale = -$ts.Scale }
                $ts.Run = 0
                $ts.Gap = $true
            }
        } elseif ($t -ceq "BI") {
            # 画像の中身（バイナリ）は読まない。ID から EI までを飛ばす
            $idPos = $content.IndexOf("ID", $pos, [StringComparison]::Ordinal)
            if ($idPos -lt 0) { break }
            $scan = $idPos + 2
            $endPos = -1
            while ($true) {
                $found = $content.IndexOf("EI", $scan, [StringComparison]::Ordinal)
                if ($found -lt 0) { break }
                $beforeOk = ($found -eq 0 -or [int]$content[$found - 1] -le 32)
                $afterOk = ($found + 2 -ge $content.Length -or [int]$content[$found + 2] -le 32)
                if ($beforeOk -and $afterOk) { $endPos = $found + 2; break }
                $scan = $found + 2
            }
            if ($endPos -lt 0) { break }
            $pos = $endPos
        }
        $nums.Clear()
        $lastStr = $null
        $lastName = $null
        $lastArray = $null
    }
    return ([regex]::Replace($ts.Sb.ToString(), '[\x00-\x09\x0B-\x1F\x7F]', " ")).TrimEnd("`n")
}

function getPdfFont {
    # フォント（辞書または参照）の規則を返す。参照のものは番号ごとに控える
    param (
        [hashtable]$doc,
        $ref
    )

    if (testPdfRef $ref) {
        $num = $ref["N"]
        if (-not $doc.Fonts.ContainsKey($num)) {
            $doc.Fonts[$num] = newPdfFont $doc (resolvePdf $doc $ref)
        }
        return $doc.Fonts[$num]
    }
    return (newPdfFont $doc $ref)
}

function walkPdfPages {
    # ページツリーをたどり、ページ（@{ Dict; Resources }）を順に pages に足す。
    # 同じノードを 2 度たどる（循環）・深すぎる・ページが多すぎるときは例外
    param (
        [hashtable]$doc,
        $node,
        $inheritedResources,
        [int]$depth,
        $pages
    )

    if ($depth -gt $doc.Limits.MaxDepth) {
        throw "PDFのページの入れ子が深すぎるため読めません。"
    }
    if (testPdfRef $node) {
        if ($doc.SeenNodes.ContainsKey($node["N"])) {
            throw "PDFのページの並びが循環しているため読めません。"
        }
        $doc.SeenNodes[$node["N"]] = $true
    }
    $dict = resolvePdf $doc $node
    if (-not (testPdfDict $dict)) { return }
    $resources = $inheritedResources
    if ($dict.ContainsKey("Resources")) { $resources = $dict["Resources"] }
    if ($dict.ContainsKey("Kids")) {
        $kids = resolvePdf $doc $dict["Kids"]
        foreach ($kid in @($kids)) {
            walkPdfPages $doc $kid $resources ($depth + 1) $pages
        }
        return
    }
    if ($pages.Count -ge $doc.Limits.MaxPages) {
        throw "PDFのページ数が上限を超えるため読めません。"
    }
    $pages.Add(@{ Dict = $dict; Resources = $resources })
}

function readPdfPages {
    # PDF のバイト列から、ページごとの文字列（行は改行で区切る。文字の無いページは空）の配列を返す。
    # 読めない PDF（パスワードが要る・暗号化の方式が未対応・壊れている・上限を超える・読まない圧縮・文字の対応表が無い）は、「PDF」で始まる日本語の例外にする
    param (
        [byte[]]$bytes,
        [hashtable]$limits = $null
    )

    if ($null -eq $limits) { $limits = newPdfLimits }
    try {
        return , (readPdfPagesCore $bytes $limits)
    } catch {
        $message = $_.Exception.Message
        if ($message.StartsWith("PDF")) {
            throw $message
        }
        throw "PDFが壊れているため読めません。"
    }
}

function readPdfPagesCore {
    param (
        [byte[]]$bytes,
        [hashtable]$limits
    )

    $text = ${pdfLatin1}.GetString($bytes)
    if ($text.IndexOf("%PDF-", 0, [Math]::Min(1024, $text.Length), [StringComparison]::Ordinal) -lt 0) {
        throw "PDFではないか、壊れているため読めません。"
    }
    $doc = @{
        Bytes = $bytes; Text = $text; Limits = $limits
        Xref = @{}; Cache = @{}; Loading = @{}; ObjStreams = @{}; Fonts = @{}; Visited = @{}; SeenNodes = @{}
        Inflated = [long]0; XrefRows = [long]0; Searched = [long]0; Root = $null; EndSearch = @{ From = 1; At = 0 }; Hybrid = $false; CMaps = @{}; MapEntries = [long]0
        Crypt = $null; EncryptEntry = $null
    }
    $start = $text.LastIndexOf("startxref", [StringComparison]::Ordinal)
    if ($start -lt 0) {
        throw "PDFの相互参照が見つからないため読めません。"
    }
    $st = newPdfLexer $text ($start + 9)
    $offset = readPdfToken $st
    if ($st.K -ne "num") {
        throw "PDFの相互参照の位置が読めないため読めません。"
    }
    readPdfXref $doc ([long]$offset)
    if ($null -ne $doc.EncryptEntry) {
        $enc = resolvePdf $doc $doc.EncryptEntry
        if (-not (testPdfDict $enc)) {
            throw "PDFの暗号化の情報が壊れているため読めません。"
        }
        $doc.Crypt = newPdfCrypt $doc $enc
    }

    $root = resolvePdf $doc $doc.Root
    if (-not (testPdfDict $root)) {
        throw "PDFの文書の入り口が見つからないため読めません。"
    }
    $pages = [System.Collections.Generic.List[object]]::new()
    walkPdfPages $doc $root["Pages"] $null 0 $pages

    $result = New-Object string[] $pages.Count
    for ($i = 0; $i -lt $pages.Count; $i++) {
        $page = $pages[$i]
        $contents = resolvePdf $doc $page.Dict["Contents"]
        $buffer = [System.IO.MemoryStream]::new()
        foreach ($item in @($contents)) {
            $stream = resolvePdf $doc $item
            if (testPdfStream $stream) {
                $data = getPdfStreamBytes $doc $stream
                $buffer.Write($data, 0, $data.Length)
                $buffer.WriteByte(10)
            }
        }
        $resources = resolvePdf $doc $page.Resources
        $fontDict = $null
        if (testPdfDict $resources) { $fontDict = resolvePdf $doc $resources["Font"] }
        $result[$i] = readPdfPageText $doc (${pdfLatin1}.GetString($buffer.ToArray())) $fontDict
    }
    return , $result
}

function readPdfFile {
    # PDF ファイルを読み、ページごとの文字列の配列を返す（readPdfPages）。
    # 大きさが maxBytes を超えるときは読まずに例外にする
    param (
        [string]$path,
        [long]$maxBytes = ${pdfFileMaxBytes},
        [hashtable]$limits = $null
    )

    if ([System.IO.FileInfo]::new((toLongPath $path)).Length -gt $maxBytes) {
        throw "ファイルサイズが大きすぎるため更新できません。"
    }
    $bytes = [System.IO.File]::ReadAllBytes((toLongPath $path))
    return , (readPdfPages $bytes $limits)
}

# TSV のファイルの読み書き（状態層）。整形の中身（formatTsv）は text.ps1（判断層）。

function prettyTsv {
    # Excelが出力したTSV（UTF-16）を整形してUTF-8で保存する。内容が空なら保存せず $false を返す
    #   firstRow, firstColumn: Excelが出力した範囲の左上のセルの行・列番号
    param (
        [string]$inputFilePath,
        [string]$outputFilePath,
        [int]$firstRow = 1,
        [int]$firstColumn = 1
    )

    $content = formatTsv ([System.IO.File]::ReadAllText((toLongPath $inputFilePath))) $firstRow $firstColumn
    if ($content -eq "") {
        return $false
    }

    [System.IO.File]::WriteAllText((toLongPath $outputFilePath), "${content}`r`n", ${utf8Bom})
    return $true
}

# フォルダのパス（正規化・同一判定・ドライブ・フォルダ選択の開始フォルダ）。

function normalizeFolderPath {
    # フォルダパスを1つの書き方にそろえる（書き方の違いで同じフォルダを別のフォルダとみなさないため）。
    #   ・前後の空白・" を取り除く
    #   ・環境変数（%USERPROFILE% など）を展開する
    #   ・/ を \ にそろえ、長いパス用の \\?\ ・ \\?\UNC\ を外す（ファイル操作に渡す直前に toLongPath で付け直す）
    #   ・重なった \ ・ . ・ .. を解決する
    #   ・相対パスはツールのフォルダ（$rootDir）からとみなして絶対パスにする
    #   ・末尾の \ を取り除く（ドライブ直下は "D:\" のまま。UNC の共有直下は "\\server\share"）
    # パスとして解釈できない場合（* ? を含む・共有名の無い \\server など）は、書かれたとおりに扱う
    param (
        [string]$path
    )

    $path = $path.Trim().Trim('"').Trim()
    if ($path -eq "") {
        return ""
    }
    if ($path.IndexOf("%") -ge 0) {
        $path = [System.Environment]::ExpandEnvironmentVariables($path).Trim()
    }
    $path = (fromLongPath ($path.Replace("/", "\"))).TrimEnd("\")
    if ($path -eq "") {
        return ""
    }
    # ドライブ名だけ（"D:"）はドライブ直下とする。
    # GetFullPath はそのドライブの「現在のフォルダ」を返すことがあるため、先に決める
    if ($path -match "^[A-Za-z]:$") {
        return "${path}\"
    }
    try {
        if (![System.IO.Path]::IsPathRooted($path)) {
            # 相対パスはツールのフォルダからとみなす
            $path = [System.IO.Path]::GetFullPath([System.IO.Path]::Combine(${rootDir}, $path)).TrimEnd("\")
        } elseif ($path -match "^[A-Za-z]:\\" -or $path.StartsWith("\\")) {
            $path = [System.IO.Path]::GetFullPath($path).TrimEnd("\")
        }
        # \ ひとつで始まるパス（"\server\share"）は、書き間違えた UNC パスのことが多いため、
        # 今のドライブのパスに直さず、書かれたとおりに扱う
    } catch {
        # パスとして解釈できない場合は、書かれたとおりに扱う（存在しないフォルダとして扱われる）
    }
    if ($path -match "^[A-Za-z]:$") {
        return "${path}\"
    }
    return $path
}

function getPathUnderFolder {
    # path が folder 自身か folder の下なら、folder からの相対パス（folder 自身は ""）を返す。
    # folder の下でなければ $null（大文字・小文字は区別しない）。
    # パスの文字数で切り出すと、書き方が少し違うだけ（末尾の \ ・\\?\ 付きなど）で取り違えるため、この関数を通す
    param (
        [string]$path,
        [string]$folder
    )

    $folder = $folder.TrimEnd("\")
    $path = $path.TrimEnd("\")
    if ($folder -eq "" -or $path -eq "") {
        return $null
    }
    if ($path.Equals($folder, [System.StringComparison]::OrdinalIgnoreCase)) {
        return ""
    }
    if ($path.StartsWith("${folder}\", [System.StringComparison]::OrdinalIgnoreCase)) {
        return $path.Substring($folder.Length + 1)
    }
    return $null
}


# ドライブ文字の割り当て先（ネットワークドライブ）は CIM で調べる（getDriveTargets 参照）。
# ※以前は Win32 API（QueryDosDevice）で subst も解決していたが、実行時コンパイル（csc.exe）を無くすため CIM に変更した。

${driveTargets} = $null


function testAnyNetworkPath {
    # 一覧の中にネットワークのパスが 1 つでもあるか（インデックスの一覧・設定にネットワークのパスがあるときだけ、
    # 起動時にドライブの割り当てを裏の列で照会するために使う）
    param (
        [string[]]$paths
    )

    foreach ($path in $paths) {
        if (testNetworkPath $path) {
            return $true
        }
    }
    return $false
}

function setDriveTargets {
    # getDriveTargets のキャッシュを外から設定する。ネットワークを調べる列で照会した結果を、
    # 画面のスレッドのキャッシュに入れるために使う（画面のスレッドで CIM を照会しないようにする）
    param (
        $targets
    )

    ${script:driveTargets} = $targets
}

function getDriveTargets {
    # ドライブ文字（"Z:"）→ 割り当て先（ネットワークドライブは "\\server\share"）を返す。
    # 同じプロセスでは1回だけ調べる（インデックス作成・検索の途中で割り当てが変わることは想定しない）。
    # subst で割り当てたドライブは解決しない（CIM で取れないため。実運用ではネットワークドライブが主）。
    if ($null -ne ${script:driveTargets}) {
        return ${script:driveTargets}
    }
    $map = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::OrdinalIgnoreCase)
    try {
        # DriveType=4 はネットワークドライブ。DeviceID="Z:"、ProviderName="\\server\share"
        foreach ($d in @(Get-CimInstance -ClassName Win32_LogicalDisk -Filter "DriveType=4" -ErrorAction SilentlyContinue)) {
            if ($d.ProviderName) {
                $map[$d.DeviceID] = $d.ProviderName.TrimEnd("\")
            }
        }
    } catch {
        # 調べられない環境では別名なしとする（パスを書かれたとおりに使う）
    }
    ${script:driveTargets} = $map
    return $map
}

function getFolderPathAliases {
    # 同じ場所を指す別の書き方を、path 自身を先頭にして返す（ドライブの割り当てをたどる）。
    # ファイルサーバーのフォルダは、ネットワークドライブ（Z:\…）と UNC パス（\\server\share\…）のどちらでも書けるため、
    # 設定に書いた書き方と、インデックスに記録した書き方が違っても同じフォルダと分かるようにする。
    #   Z: が \\server\share のネットワークドライブのとき
    #     "Z:\見積"             → @("Z:\見積", "\\server\share\見積")
    #     "\\server\share\見積" → @("\\server\share\見積", "Z:\見積")
    param (
        [string]$path,
        $drives = (getDriveTargets)  # ドライブ文字 → 割り当て先（テストで差し替える）
    )

    $result = New-Object System.Collections.Generic.List[string]
    $result.Add($path)
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    [void]$seen.Add($path.TrimEnd("\"))

    foreach ($entry in $drives.GetEnumerator()) {
        $alias = $null
        # ドライブ文字 → 割り当て先
        $rest = getPathUnderFolder $path $entry.Key
        if ($null -ne $rest) {
            $alias = if ($rest -eq "") { $entry.Value } else { joinSourcePath $entry.Value $rest }
        } else {
            # 割り当て先 → ドライブ文字
            $rest = getPathUnderFolder $path $entry.Value
            if ($null -ne $rest) {
                $alias = if ($rest -eq "") { "$($entry.Key)\" } else { joinSourcePath "$($entry.Key)\" $rest }
            }
        }
        if ($alias -and $seen.Add($alias.TrimEnd("\"))) {
            $result.Add($alias)
        }
    }
    return $result.ToArray()
}

function testSameFolder {
    # 2つのパスが同じフォルダを指すか（末尾の \ ・大文字と小文字の違いと、ネットワークドライブ・subst の割り当てをたどる）
    param (
        [string]$a,
        [string]$b,
        $drives = $null  # ドライブ文字 → 割り当て先（テストで差し替える。$null は getDriveTargets）
    )

    $target = $b.TrimEnd("\")
    # 書き方どおりに同じなら、ドライブの割り当て（CIM。初回は 0.2 秒以上、切断されたネットワークドライブがあるとさらにかかる）を調べない
    if ($a.TrimEnd("\").Equals($target, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $true
    }
    if ($null -eq $drives) {
        # getDriveTargets（CIM）が返す別名はネットワークドライブ⇔UNCの組しか無いため、
        # どちらかがローカル（ネットワークでない）なら、別名を調べても一致しえない。CIM を照会しない
        if (!(testNetworkPath $a) -or !(testNetworkPath $b)) {
            return $false
        }
        $drives = getDriveTargets
    }
    foreach ($alias in @(getFolderPathAliases $a $drives)) {
        if ($alias.TrimEnd("\").Equals($target, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $true
        }
    }
    return $false
}

function testFolderUnder {
    # path が folder 自身か folder の下のフォルダかを返す（testSameFolder と同じく、書き方の違い・ドライブの割り当てをたどる）。
    # クロール対象フォルダが入れ子になると、同じファイルが2つのインデックスに入り、検索結果にも二重に出るため、その確認に使う
    param (
        [string]$path,
        [string]$folder,
        $drives = $null  # ドライブ文字 → 割り当て先（テストで差し替える。$null は getDriveTargets）
    )

    if ($path -eq "" -or $folder -eq "") {
        return $false
    }
    # 書き方どおりに下にあれば、ドライブの割り当て（CIM）を調べない
    if ($null -ne (getPathUnderFolder $path $folder)) {
        return $true
    }
    if ($null -eq $drives) {
        # testSameFolder と同じ理由で、どちらかがローカルなら CIM を照会しない
        if (!(testNetworkPath $path) -or !(testNetworkPath $folder)) {
            return $false
        }
        $drives = getDriveTargets
    }
    foreach ($alias in @(getFolderPathAliases $path $drives)) {
        if ($null -ne (getPathUnderFolder $alias $folder)) {
            return $true
        }
    }
    return $false
}

function testNetworkPath {
    # パス（normalizeFolderPath 済み）がネットワークの場所を指すかを、共有に接続せずに見分ける。
    #   \\server\share\… ・\\?\UNC\… は UNC（ネットワーク）。
    #   \\?\C:\…（toLongPath の形）・\\.\… は \\ で始まるが UNC ではないため、ドライブ文字として扱う。
    #   ドライブ文字なら DriveInfo.DriveType を見る（GetDriveType は共有に接続しない）。
    #   Fixed・Removable・CDRom・Ram だけをローカルとし、Network と、切断したドライブがそう見えることのある
    #   NoRootDirectory・Unknown は、安全な側に倒してネットワークとする
    #   driveType: ドライブの種類を引く関数（テストで差し替える）。既定は実際の DriveInfo
    param (
        [string]$path,
        [scriptblock]$driveType = { param ($drive) ([System.IO.DriveInfo]$drive).DriveType }
    )

    if ($path -eq "") {
        return $false
    }
    $p = $path.Replace("/", "\")
    if ($p.StartsWith("\\?\UNC\")) {
        return $true
    }
    $rest = $p
    if ($p.StartsWith("\\?\") -or $p.StartsWith("\\.\")) {
        $rest = $p.Substring(4)
    } elseif ($p.StartsWith("\\")) {
        return $true  # \\server\share\…（UNC）
    }
    if ($rest -notmatch "^[A-Za-z]:") {
        return $false  # ドライブ文字が無い（相対パスなど）はローカルとみなす
    }
    $drive = "$($rest.Substring(0, 1)):\"
    try {
        $type = & $driveType $drive
    } catch {
        return $true  # 調べられなければ安全な側（ネットワーク）に倒す
    }
    return $type -notin @([System.IO.DriveType]::Fixed, [System.IO.DriveType]::Removable, [System.IO.DriveType]::CDRom, [System.IO.DriveType]::Ram)
}

function testLocalDrivePath {
    # パス（normalizeFolderPath 済み）が「ドライブ文字で始まり、ネットワークでない」= ローカルのドライブと分かるかを返す。
    # 共有に接続せずに見分ける。UNC・デバイス名の形（\.\UNC\… など）・相対パス・空は偽（testNetworkPath は
    # \.\ をドライブ文字の形として見るため、それだけではデバイス名の形を見分けられない）
    #   driveType: testNetworkPath と同じ（テストで差し替える）
    param (
        [string]$path,
        [scriptblock]$driveType = { param ($drive) ([System.IO.DriveInfo]$drive).DriveType }
    )

    return ($path -match '^[A-Za-z]:\\') -and !(testNetworkPath $path $driveType)
}


# ---- フォルダ選択の開始フォルダ ----


function getExistingAncestorFolder {
    # folder が今もあればそのまま、無ければその上の今もあるフォルダを返す（フォルダ選択を開く場所）。どこにも無ければ空。
    #   skipNetwork: $true なら、ネットワークのパスは調べずに空を返す（画面のスレッドで届かない共有に触らないため）
    param (
        [string]$folder,
        [bool]$skipNetwork = $false
    )

    if ($skipNetwork -and (testNetworkPath $folder)) {
        return ""
    }
    $dir = $folder
    while ($dir) {
        if (Test-Path -LiteralPath (toLongPath $dir) -PathType Container) {
            return $dir
        }
        $dir = Split-Path $dir -Parent
    }
    return ""
}


function getFolderLeafName {
    # フォルダ名（ドライブ直下はドライブ名、UNC の共有直下は共有名）を返す
    param (
        [string]$folderPath
    )

    $path = $folderPath.TrimEnd("\")
    $leaf = [System.IO.Path]::GetFileName($path)
    if ($leaf -eq "") {
        $leaf = $path.TrimEnd(":")
    }
    return $leaf
}

# 配布物の版の記録（VERSION.txt）の読み取り（状態層）。
# 中身は BOM 付き UTF-8・CRLF の2行（1行目: タグ名 / 2行目: コミットの SHA）。
# tools/new_version_text.ps1 が作り、tools/new_release_package.ps1（zip）・tools/new_installer.ps1（インストーラー）が書き込む。
# 作業ツリー（git のチェックアウト）には無く、配布物にだけある。
#
# 単一 .ps1 版（展開せずに動く試験版）は VERSION.txt を持てないため、結合の道具（tools/new_single_script.ps1）が
# 版の文字列を ${bundledVersion}（@{ Tag; Sha }）としてこのファイルより前に埋める。あればファイルを読まずそれを返す

function readVersionFile {
    # ファイルが無い・読めない・形が違うときは $null。あれば @{ Tag; Sha }
    param (
        [string]$path
    )

    $bundled = Get-Variable -Name bundledVersion -ErrorAction SilentlyContinue
    if ($null -ne $bundled) {
        return $bundled.Value
    }

    if (!(Test-Path -LiteralPath $path)) {
        return $null
    }
    try {
        $lines = [System.IO.File]::ReadAllLines($path)
    } catch {
        return $null
    }
    if ($lines.Count -ne 2) {
        return $null
    }
    if ($lines[0] -notmatch '^[A-Za-z0-9._-]+$' -or $lines[1] -notmatch '^[0-9a-f]{40}$') {
        return $null
    }
    return @{ Tag = $lines[0]; Sha = $lines[1] }
}

function resolveGitRef {
    # git のリファレンス（refs/heads/main など）が指すコミットの SHA を返す。無ければ空文字。
    # ファイルを読むだけ（外部プロセスの git は起動しない）。loose（refs\ の下のファイル）を先に見て、無ければ packed-refs を見る。
    #   dirs: 探すフォルダ（worktree の gitdir・共通の gitdir の順）
    param (
        [string]$ref,
        [string[]]$dirs
    )

    if ($ref -notmatch '^refs/[A-Za-z0-9._/-]+$' -or $ref.Contains("..")) {
        return ""
    }
    foreach ($dir in $dirs) {
        $loose = Join-Path $dir ($ref.Replace("/", "\"))
        if (Test-Path -LiteralPath $loose -PathType Leaf) {
            $text = ([System.IO.File]::ReadAllText($loose)).Trim()
            if ($text -match '^[0-9a-f]{40}$') {
                return $text
            }
        }
    }
    foreach ($dir in $dirs) {
        $refListFile = Join-Path $dir "packed-refs"
        if (!(Test-Path -LiteralPath $refListFile -PathType Leaf)) {
            continue
        }
        foreach ($line in [System.IO.File]::ReadAllLines($refListFile)) {
            if ($line -match '^([0-9a-f]{40}) (\S+)$' -and $Matches[2] -ceq $ref) {
                return $Matches[1]
            }
        }
    }
    return ""
}

function readDevVersion {
    # 配布物でない（VERSION.txt が無い）ときの版の手がかりを、作業ツリーの .git のファイルだけから読む。
    # 外部プロセス（git）は起動せず、ファイルを読むだけ。.git が無い・読めない・形が違うときは $null。
    # 返すもの: @{ Tag; AtHead; Sha }
    #   Sha    : HEAD のコミット（分からなければ空）
    #   Tag    : リリースのタグ（v<数>.<数>.<数>）。HEAD のコミットに付いたタグがあればそれ（複数なら版の並びで最も新しい）、
    #            無ければ全タグのうち版の並びで最も新しいもの（無ければ空）
    #   AtHead : Tag が HEAD のコミットに付いているか
    # 「最も新しいタグ」は版の並びで決める。.git のファイルだけでは、タグが HEAD の祖先かどうかは分からず、
    # 別のブランチのタグを拾うことがある（目安の表示のため、それでよい）。
    # 注釈付きタグは、packed-refs の ^ の行（指す先のコミット）で HEAD と照らす。refs\tags の下に置かれた注釈付きタグは、
    # タグの実体を読まないと指す先が分からないため、HEAD に付いた印にはならない（版の並びの比べには使う）。
    # worktree は .git がファイル（gitdir: <パス>）で、HEAD は gitdir に、タグ・packed-refs は commondir（共通の gitdir）にある
    param (
        [string]$rootDir
    )

    try {
        $dotGit = Join-Path $rootDir ".git"
        $gitDir = ""
        if (Test-Path -LiteralPath $dotGit -PathType Container) {
            $gitDir = $dotGit
        } elseif (Test-Path -LiteralPath $dotGit -PathType Leaf) {
            $first = [System.IO.File]::ReadAllLines($dotGit) | Select-Object -First 1
            if ($first -notmatch '^gitdir:\s*(.+)$') {
                return $null
            }
            $target = $Matches[1].Trim()
            if (![System.IO.Path]::IsPathRooted($target)) {
                $target = Join-Path $rootDir $target
            }
            $gitDir = [System.IO.Path]::GetFullPath($target)
        }
        if (!$gitDir -or !(Test-Path -LiteralPath $gitDir -PathType Container)) {
            return $null
        }
        $commonDir = $gitDir
        $commonFile = Join-Path $gitDir "commondir"
        if (Test-Path -LiteralPath $commonFile -PathType Leaf) {
            $common = ([System.IO.File]::ReadAllText($commonFile)).Trim()
            if ($common) {
                $commonDir = [System.IO.Path]::GetFullPath($(if ([System.IO.Path]::IsPathRooted($common)) { $common } else { Join-Path $gitDir $common }))
            }
        }

        # HEAD のコミット
        $sha = ""
        $headFile = Join-Path $gitDir "HEAD"
        if (Test-Path -LiteralPath $headFile -PathType Leaf) {
            $head = ([System.IO.File]::ReadAllLines($headFile) | Select-Object -First 1)
            if ($head -match '^ref:\s*(\S+)$') {
                $sha = resolveGitRef $Matches[1] @($gitDir, $commonDir)
            } elseif ($head -match '^[0-9a-f]{40}$') {
                $sha = $head
            }
        }

        # タグ（名前 → @{ Commit }）。packed-refs（注釈付きタグは次の行の ^ が指す先）を読み、loose のタグで上書きする
        $tags = @{}
        $refListFile = Join-Path $commonDir "packed-refs"
        if (Test-Path -LiteralPath $refListFile -PathType Leaf) {
            $last = ""
            foreach ($line in [System.IO.File]::ReadAllLines($refListFile)) {
                if ($line -match '^([0-9a-f]{40}) refs/tags/(v\d+\.\d+\.\d+)$') {
                    $last = $Matches[2]
                    $tags[$last] = $Matches[1]
                } elseif ($line -match '^\^([0-9a-f]{40})$' -and $last) {
                    $tags[$last] = $Matches[1]
                } else {
                    $last = ""
                }
            }
        }
        $tagsDir = Join-Path $commonDir "refs\tags"
        if (Test-Path -LiteralPath $tagsDir -PathType Container) {
            foreach ($file in @(Get-ChildItem -LiteralPath $tagsDir -File)) {
                if ($file.Name -match '^v\d+\.\d+\.\d+$') {
                    $text = ([System.IO.File]::ReadAllText($file.FullName)).Trim()
                    if ($text -match '^[0-9a-f]{40}$') {
                        $tags[$file.Name] = $text
                    }
                }
            }
        }

        $atHead = ""
        $latest = ""
        foreach ($name in @($tags.Keys)) {
            $isNewer = { param($a, $b) (-not $b) -or ([version]$a.Substring(1)) -gt ([version]$b.Substring(1)) }
            if (& $isNewer $name $latest) {
                $latest = $name
            }
            if ($sha -and $tags[$name] -eq $sha -and (& $isNewer $name $atHead)) {
                $atHead = $name
            }
        }
        if ($atHead) {
            return @{ Tag = $atHead; AtHead = $true; Sha = $sha }
        }
        if (!$latest -and !$sha) {
            return $null
        }
        return @{ Tag = $latest; AtHead = $false; Sha = $sha }
    } catch {
        return $null
    }
}

# 診断情報（ログの先頭の見出し）の組み立て（判断層）。
# ファイル・レジストリ・画面に触らない。調べる側は diagnostics.ps1 の getEnvironmentInfo。
# 利用者名・コンピューター名・ドメイン・パス・ネットワークの情報は、見出しに書かない。

function getVersionLabel {
    # readVersionFile の結果から、版・コミットの表示を決める: @{ Version; Commit（出さないときは空） }
    #   versionInfo: readVersionFile の戻り値（$null なら開発中に git から直接起動したときの表示にする）
    #   devInfo: readDevVersion の戻り値（versionInfo が $null のときだけ使う。タグ・コミットを添える。省くと「開発版」だけ）
    #     HEAD にタグがある: 開発版（v0.5.0・d79f898）/ 無い: 開発版（v0.5.0 より後・d79f898）/ コミットだけ: 開発版（d79f898）
    param (
        $versionInfo,
        $devInfo = $null
    )

    if ($null -eq $versionInfo) {
        $parts = @()
        if ($null -ne $devInfo) {
            $sha = if ($devInfo.Sha) { ([string]$devInfo.Sha).Substring(0, [Math]::Min(7, ([string]$devInfo.Sha).Length)) } else { "" }
            if ($devInfo.Tag) {
                $parts += $(if ($devInfo.AtHead) { [string]$devInfo.Tag } else { "$($devInfo.Tag) より後" })
            }
            if ($sha) {
                $parts += $sha
            }
        }
        if ($parts.Count -eq 0) {
            return @{ Version = "開発版"; Commit = "" }
        }
        return @{ Version = "開発版（$($parts -join '・')）"; Commit = "" }
    }
    return @{ Version = $versionInfo.Tag; Commit = $versionInfo.Sha.Substring(0, 7) }
}

function getOfficeKind {
    # 見つかった Office の実行ファイルのパスから、形態とビット数を決める: @{ Kind = "Click-to-Run" / "MSI"; Bits = 64 / 32 }
    #   programFiles64: 64 ビット側の Program Files / programFilesX86: x86 側の Program Files
    param (
        [string]$exePath,
        [string]$programFiles64,
        [string]$programFilesX86
    )

    $kind = "MSI"
    if ($exePath -match '(?i)\\root\\Office\d+\\') {
        $kind = "Click-to-Run"
    }
    $bits = 64
    if ($programFilesX86 -and $exePath.StartsWith($programFilesX86.TrimEnd("\") + "\", [System.StringComparison]::OrdinalIgnoreCase)) {
        $bits = 32
    }
    return @{ Kind = $kind; Bits = $bits }
}

function hideUserProfile {
    # 文字列の中の利用者のプロファイルのフォルダ（C:\Users\<利用者名>）を %USERPROFILE% に置き換える（大文字小文字は区別しない）。
    # 名前の前方だけが同じ別のフォルダ（末尾に文字が続く名前）は置き換えない
    param (
        [string]$text,
        [string]$profileDir
    )

    if (-not $text -or -not $profileDir) {
        return $text
    }
    $pattern = [regex]::Escape($profileDir.TrimEnd("\")) + '(?![\w.\-])'
    return [regex]::Replace($text, $pattern, '%USERPROFILE%', [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
}

function formatDiagnosticHeader {
    # ログの先頭に書く見出しの行（配列）を返す
    #   toolName: ツールの名前 / versionInfo: readVersionFile の結果 / envInfo: getEnvironmentInfo の結果 / now: 日時（DateTimeOffset）
    param (
        [string]$toolName,
        $versionInfo,
        $envInfo,
        [System.DateTimeOffset]$now,
        $devInfo = $null   # readDevVersion の結果（versionInfo が $null のとき、版にタグ・コミットを添える）
    )

    $unknown = "不明"
    $orUnknown = { param($value) if ($value) { [string]$value } else { $unknown } }
    $label = getVersionLabel $versionInfo $devInfo
    $versionText = $label.Version
    if ($label.Commit) {
        $versionText = "$($label.Version) ($($label.Commit))"
    }
    $bitsText = { param($is64) if ($null -eq $is64) { $unknown } elseif ($is64) { "64 ビット" } else { "32 ビット" } }

    $officeText = "見つからない"
    $officeItems = @($envInfo.Office)
    if ($null -eq $envInfo.Office) {
        $officeText = $unknown
    } elseif ($officeItems.Count -gt 0) {
        $officeText = (@($officeItems | ForEach-Object {
            "$($_.Name) $(& $orUnknown $_.Version) $($_.Kind) $($_.Bits) ビット"
        })) -join " / "
    }

    return @(
        "==== $toolName の診断情報 ===="
        "日時: $($now.ToString('yyyy-MM-dd HH:mm:ss zzz'))"
        "$toolName の版: $versionText"
        "OS: Windows $(& $orUnknown $envInfo.OsVersion)（ntoskrnl $(& $orUnknown $envInfo.OsFileVersion)・$(& $bitsText $envInfo.Os64)）"
        "PowerShell: $(& $orUnknown $envInfo.PsVersion)（$(& $bitsText $envInfo.Ps64)・$(& $orUnknown $envInfo.LanguageMode)）"
        "Office: $officeText"
        "表示言語: $(& $orUnknown $envInfo.UICulture)"
        "===="
    )
}

# 診断情報の収集と、ログの世代の入れ替え（状態層）。
# レジストリ・WMI・COM は使わず、Office も起動しない。ファイルの版情報と .NET・PowerShell の値だけを読む。
# 見出しの文面は diagnostics_view.ps1。

function getEnvironmentInfo {
    # OS・PowerShell・Office の情報を返す。調べられない項目は $null
    $info = @{ OsVersion = $null; OsFileVersion = $null; Os64 = $null; PsVersion = $null; Ps64 = $null; LanguageMode = $null; UICulture = $null; Office = @() }
    try { $info.OsVersion = [Environment]::OSVersion.Version.ToString() } catch {}
    try { $info.Os64 = [Environment]::Is64BitOperatingSystem } catch {}
    try { $info.Ps64 = [Environment]::Is64BitProcess } catch {}
    try { $info.PsVersion = $PSVersionTable.PSVersion.ToString() } catch {}
    try { $info.LanguageMode = [string]$ExecutionContext.SessionState.LanguageMode } catch {}
    try { $info.UICulture = [System.Globalization.CultureInfo]::CurrentUICulture.Name } catch {}
    try {
        $kernel = [System.Diagnostics.FileVersionInfo]::GetVersionInfo("$env:SystemRoot\System32\ntoskrnl.exe")
        $info.OsFileVersion = "$($kernel.FileMajorPart).$($kernel.FileMinorPart).$($kernel.FileBuildPart).$($kernel.FilePrivatePart)"
    } catch {}
    try {
        $info.Office = @(findOfficeApps -os64 ($info.Os64 -ne $false))
    } catch {
        $info.Office = $null   # 調べられなかった（見出しでは「不明」。「見つからない」とは区別する）
    }
    return $info
}

function findOfficeApps {
    # 決まった場所にある Office の実行ファイル（EXCEL.EXE・WINWORD.EXE・POWERPNT.EXE）を探し、@{ Name; Version; Kind; Bits } の配列を返す。
    # Program Files は、Windows のあるドライブ（$env:SystemRoot のドライブ）の決まった名前のフォルダとする
    # （環境変数 ProgramFiles は 32 ビットの PowerShell で x86 側を指し、安全性の検査も SystemRoot 以外の環境変数を許さないため）
    #   programFiles64 / programFilesX86: 探す 2 つの場所（省略すると Windows のあるドライブの決まった名前。テストでは別の場所を渡す）
    #   os64: 64 ビットの Windows か。32 ビットなら programFiles64 の場所を 32 ビット版の置き場として扱う
    # 調べている途中で例外になったら、そのまま投げる（呼び出し側が「不明」にする）
    param (
        [string]$programFiles64,
        [string]$programFilesX86,
        [bool]$os64 = $true
    )

    if (-not $programFiles64 -and -not $programFilesX86) {
        $systemDrive = [System.IO.Path]::GetPathRoot($env:SystemRoot)
        if (-not $systemDrive) {
            throw "Windows のあるドライブを取れない"   # 調べ損ね（見つからないとは別）
        }
        $programFiles64 = Join-Path $systemDrive "Program Files"
        $programFilesX86 = Join-Path $systemDrive "Program Files (x86)"
    }
    $x86Root = $programFilesX86
    if (-not $os64) {
        $x86Root = $programFiles64
    }
    $subDirs = @("Microsoft Office\root\Office16", "Microsoft Office\Office16", "Microsoft Office\Office15")
    $apps = @(@("Excel", "EXCEL.EXE"), @("Word", "WINWORD.EXE"), @("PowerPoint", "POWERPNT.EXE"))
    $found = New-Object System.Collections.Generic.List[object]
    foreach ($app in $apps) {
        $hit = $null
        foreach ($base in @($programFiles64, $programFilesX86)) {
            if (-not $base -or $hit) { continue }
            foreach ($sub in $subDirs) {
                $candidate = Join-Path (Join-Path $base $sub) $app[1]
                if (Test-Path -LiteralPath $candidate -PathType Leaf) {
                    $hit = $candidate
                    break
                }
            }
        }
        if ($hit) {
            $kind = getOfficeKind $hit $programFiles64 $x86Root
            $version = $null
            try { $version = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($hit).FileVersion } catch {}
            $found.Add(@{ Name = $app[0]; Version = $version; Kind = $kind.Kind; Bits = $kind.Bits })
        }
    }
    return $found.ToArray()
}

function getPreviousLogPath {
    # ログの前回の分の名前（<名前>_previous<拡張子>）。同じフォルダに置く
    param (
        [string]$path
    )

    $dir = [System.IO.Path]::GetDirectoryName($path)
    $name = [System.IO.Path]::GetFileNameWithoutExtension($path) + "_previous" + [System.IO.Path]::GetExtension($path)
    return (Join-Path $dir $name)
}

function rotateLogFile {
    # path が maxBytes 以上なら、前回の分（getPreviousLogPath。あれば上書き）に移す。0 はいつも移す。
    # 移したら $true。元が無い・上限未満・移せない（読み取り専用・開いたまま）は $false（例外は出さない）
    param (
        [string]$path,
        [long]$maxBytes
    )

    try {
        if (-not [System.IO.File]::Exists($path)) {
            return $false
        }
        if ($maxBytes -gt 0 -and (New-Object System.IO.FileInfo($path)).Length -lt $maxBytes) {
            return $false
        }
        $previous = getPreviousLogPath $path
        if ([System.IO.File]::Exists($previous)) {
            # 移せない（前回の分が読み取り専用・元が開いたまま・置き場所が対応しない）ときは失敗し、今のログは失わない。
            # 複写で逃げないのは、移せないあいだ書くたびに全量を複写することになるため
            [System.IO.File]::Replace($path, $previous, [NullString]::Value)
        } else {
            [System.IO.File]::Move($path, $previous)
        }
        return $true
    } catch {
        return $false
    }
}

# 取り込み対象にする Office ファイルの拡張子。

# 取り込み対象にする Office ファイルの拡張子（小文字）。
# インデクサ（indexer.ps1）の対象の判定で使う
${officeExtensions} = @(
    ".xlsx", ".xlsm", ".xls", ".xlsb",
    ".docx", ".docm", ".doc",
    ".pptx", ".pptm", ".ppt"
)

# このツールが起動した Excel・Word・PowerPoint の PID の記録と、実行中の Office の一覧・強制終了。
# 止めてよいのは「記録があり、記録と今のプロセスが合うもの」だけ。記録の無いもの（利用者・ほかのアプリのもの）は一覧に出ても止める対象にしない。

# ----------------------------------------------------------------------------
# 検索・Officeプロセス・画面（gui.ps1）で共有する処理
# ----------------------------------------------------------------------------

# 強制終了の対象: プロセス名 → 表示名
${officeProcessNames} = [ordered]@{ EXCEL = "Excel"; WINWORD = "Word"; POWERPNT = "PowerPoint" }

# 書きかけの記録（*.tmp）をこの時間より古ければ消す（書いている最中のものを消さないため）
${officeRecordTmpMaxAge} = [TimeSpan]::FromHours(1)

function getOfficeStartTicks {
    # プロセスの起動時刻（UTC の Ticks）。読めない（管理者として動いているなど）ときは $null
    param (
        $process
    )

    try {
        return [long]$process.StartTime.ToUniversalTime().Ticks
    } catch {
        return $null
    }
}

function testOfficeProcessHasWindow {
    # process に見えている窓があるか（Process.MainWindowHandle が 0 でない）。COM を使わず、相手のプロセスにメッセージも送らないため、固まったプロセスにも戻ってくる。
    # 利用者がそのプロセスを使っているかの見分けに使う（インデックス作成はファイルを窓無しで開くので、自分の取り込みだけなら窓は無い）。
    # 値を取り直してから見る（取り直さないと、前に読んだ値のままになる）。読めない（終わっているなど）ときは $false
    param (
        $process
    )

    try {
        try { $process.Refresh() } catch {}
        $handle = $process.MainWindowHandle
        return ($handle -is [IntPtr] -and $handle -ne [IntPtr]::Zero)
    } catch {
        return $false
    }
}

function compareOfficeProcess {
    # process を、控えたとき（プロセス名・起動時刻）と比べる。"Same"（同じ）・"Different"（別のプロセス）・"Unknown"（分からない）を返す。
    # 先に Handle を読んでプロセスのハンドルを開く（Process が持ち続けるので、このあと同じ process で Kill() するまで、その PID は別のプロセスに使われない）。
    # ハンドルが開けない・控えた起動時刻が無い（$null・0）・今の起動時刻が読めないときは "Unknown"（止めない）。名前か起動時刻が違えば "Different"
    param (
        $process,
        [string]$processName,
        $startTicks
    )

    try {
        if ($null -eq $process.Handle) {
            return "Unknown"
        }
        if ($process.ProcessName -ne $processName) {
            return "Different"
        }
    } catch {
        return "Unknown"
    }
    if ($null -eq $startTicks -or [long]$startTicks -le 0) {
        return "Unknown"
    }
    $actual = getOfficeStartTicks $process
    if ($null -eq $actual) {
        return "Unknown"
    }
    return $(if ([long]$actual -eq [long]$startTicks) { "Same" } else { "Different" })
}

function isSameOfficeProcess {
    # process が、控えたときと同じプロセス（プロセス名と起動時刻が同じ）か。止める前に必ず通す（PID が別のプロセスに使い回されていないかの確認）。
    # 同じと言えるときだけ $true。違う・分からないときは $false（止めない）。比べ方は compareOfficeProcess
    param (
        $process,
        [string]$processName,
        $startTicks
    )

    return ((compareOfficeProcess $process $processName $startTicks) -eq "Same")
}

# ----------------------------------------------------------------------------
# 記録（<ワークスペース>\office_pids\<PC の鍵>\<PID>.txt）
# 1 行・タブ区切り: <プロセス名> <起動時刻の Ticks> <持ち主の PID> <持ち主の起動時刻の Ticks>
# ----------------------------------------------------------------------------

function addOfficeRecord {
    # 起動した Office の記録を 1 つ書く。書けたら $true。場所が空・書けない（共有に届かない・権限が無い）ときは $false（呼ぶ側は取り込みを続ける）。
    # 持ち主は、省けばこのプロセス（記録を書いたプロセス）。書きかけを読ませないよう、.tmp に書いてから名前を変える
    param (
        [string]$dir,
        [int]$id,
        [string]$processName,
        [long]$startTicks,
        [int]$ownerId = 0,
        [long]$ownerStartTicks = 0
    )

    if (!$dir -or $startTicks -le 0) {
        return $false
    }
    $tmp = Join-Path $dir "$id.tmp"
    try {
        if ($ownerId -le 0) {
            $self = [System.Diagnostics.Process]::GetCurrentProcess()
            $ownerId = $self.Id
            $ticks = getOfficeStartTicks $self
            $ownerStartTicks = $(if ($null -ne $ticks) { $ticks } else { 0 })
        }
        [void][System.IO.Directory]::CreateDirectory($dir)
        [System.IO.File]::WriteAllText($tmp, "$processName`t$startTicks`t$ownerId`t$ownerStartTicks", (New-Object System.Text.UTF8Encoding($false)))
        $final = Join-Path $dir "$id.txt"
        [System.IO.File]::Delete($final)
        [System.IO.File]::Move($tmp, $final)
        return $true
    } catch {
        try { [System.IO.File]::Delete($tmp) } catch {}
        return $false
    }
}

function removeOfficeRecord {
    # PID の記録を消す。ファイルが無い・消せないときも失敗にしない（消せなければ次の起動の確認で、PID が無いものとして消える）
    param (
        [string]$dir,
        [int]$id
    )

    if (!$dir) {
        return
    }
    try {
        [System.IO.File]::Delete((Join-Path $dir "$id.txt"))
    } catch {}
}

function readOfficeRecords {
    # 記録を読み、今のプロセスと照らし合わせて @{ Id; ProcessName; StartTicks; OwnerId; OwnerStartTicks; Owned } の配列を返す。
    # Owned: PID があり、名前が同じで、起動時刻が読めて同じ（記録を書いたときのプロセスのまま）。
    # 次のものは、PID が別のプロセスのものになった・無くなった記録なので消す: PID のプロセスが無い・名前が違う・起動時刻が読めて違う。
    # 起動時刻が読めないときは Owned にせず、消しもしない。形の違う記録は使わず、消さない。古い .tmp（書きかけの残り）は消す。
    # フォルダが無い・読めないときは空の配列
    param (
        [string]$dir
    )

    $result = New-Object System.Collections.Generic.List[object]
    if (!$dir) {
        return $result.ToArray()
    }
    try {
        foreach ($tmp in [System.IO.Directory]::GetFiles($dir, "*.tmp")) {
            try {
                if ([System.IO.Path]::GetExtension($tmp) -eq ".tmp" -and
                    ([datetime]::UtcNow - [System.IO.File]::GetLastWriteTimeUtc($tmp)) -gt ${officeRecordTmpMaxAge}) {
                    [System.IO.File]::Delete($tmp)
                }
            } catch {}
        }
        $files = [System.IO.Directory]::GetFiles($dir, "*.txt")
    } catch {
        return $result.ToArray()
    }
    foreach ($file in $files) {
        $id = 0
        $startTicks = [long]0
        $ownerId = 0
        $ownerTicks = [long]0
        try {
            if ([System.IO.Path]::GetExtension($file) -ne ".txt") { continue }
            $fields = ([System.IO.File]::ReadAllText($file).Trim() -split "`t")
            if (!([int]::TryParse([System.IO.Path]::GetFileNameWithoutExtension($file), [ref]$id) -and $id -gt 0 -and $fields.Count -eq 4 -and
                    ${officeProcessNames}.Contains($fields[0]) -and [long]::TryParse($fields[1], [ref]$startTicks) -and $startTicks -gt 0 -and
                    [int]::TryParse($fields[2], [ref]$ownerId) -and [long]::TryParse($fields[3], [ref]$ownerTicks))) {
                continue
            }
        } catch {
            continue
        }
        $process = Get-Process -Id $id -ErrorAction SilentlyContinue
        $owned = $false
        if ($null -eq $process -or $process.ProcessName -ne $fields[0]) {
            removeOfficeRecord $dir $id
            continue
        }
        $actual = getOfficeStartTicks $process
        if ($null -ne $actual) {
            if ($actual -ne $startTicks) {
                removeOfficeRecord $dir $id
                continue
            }
            $owned = $true
        }
        $result.Add([pscustomobject]@{
            Id = $id; ProcessName = $fields[0]; StartTicks = $startTicks; OwnerId = $ownerId; OwnerStartTicks = $ownerTicks; Owned = $owned
        })
    }
    return $result.ToArray()
}

function getOfficeRecordOwner {
    # 記録を書いたプロセス（持ち主）の今の状態: Self（この画面のプロセス）・Other（生きているほかのプロセス）・Gone（もういない）。
    # 持ち主の起動時刻が読めない・記録に無いときは、生きていれば安全な側（Other）にする
    param (
        $record,
        [int]$selfId,
        [long]$selfStartTicks
    )

    if ($record.OwnerId -eq $selfId -and $record.OwnerStartTicks -eq $selfStartTicks) {
        return "Self"
    }
    $owner = Get-Process -Id $record.OwnerId -ErrorAction SilentlyContinue
    if ($null -eq $owner) {
        return "Gone"
    }
    $actual = getOfficeStartTicks $owner
    if ($null -ne $actual -and $record.OwnerStartTicks -gt 0 -and $actual -ne $record.OwnerStartTicks) {
        return "Gone"
    }
    return "Other"
}

# ----------------------------------------------------------------------------
# 一覧と強制終了
# ----------------------------------------------------------------------------

function getOfficeProcesses {
    # 自分のセッションで実行中の Excel・Word・PowerPoint を返す。各要素:
    #   Id・ProcessName・AppName・StartTime（読めなければ $null）・
    #   HasWindow（MainWindowHandle が 0 でない）・
    #   Owned（recordDir の記録があり、記録と今のプロセスの PID・名前・起動時刻が合う。recordDir が空なら常に $false）・
    #   Owner（Owned のとき、記録を書いたプロセスの状態 Self・Other・Gone。Owned でなければ空）
    # 残り物（止めてよいもの）の選び出しは判断層（getLeftoverPrompt）が行う。ここは材料を返すだけ。
    # recordDir を読むため、画面のスレッドでは呼ばない（startJob の中で呼ぶ）。
    # selfId・selfStartTicks は、この画面のプロセスの PID と起動時刻（省けば今のプロセス。テストで差し替える）
    param (
        [string]$recordDir = "",
        [int]$selfId = 0,
        [long]$selfStartTicks = 0
    )

    $current = [System.Diagnostics.Process]::GetCurrentProcess()
    if ($selfId -le 0) {
        $selfId = $current.Id
        $ticks = getOfficeStartTicks $current
        $selfStartTicks = $(if ($null -ne $ticks) { $ticks } else { 0 })
    }
    $records = @{}
    foreach ($record in @(readOfficeRecords $recordDir)) {
        $records[[int]$record.Id] = $record
    }

    $result = New-Object System.Collections.Generic.List[object]
    foreach ($process in @(Get-Process -Name @(${officeProcessNames}.Keys) -ErrorAction SilentlyContinue |
            Where-Object { $_.SessionId -eq $current.SessionId })) {
        $startTime = $null
        try {
            $startTime = $process.StartTime
        } catch {
            # 権限の無いプロセスは起動時刻を取得できない
        }
        $record = $records[[int]$process.Id]
        $owned = ($null -ne $record -and $record.Owned -and $record.ProcessName -eq $process.ProcessName)
        $result.Add([pscustomobject]@{
            Id          = $process.Id
            ProcessName = $process.ProcessName
            AppName     = ${officeProcessNames}[$process.ProcessName]
            StartTime   = $startTime
            HasWindow   = (testOfficeProcessHasWindow $process)
            Owned       = $owned
            Owner       = $(if ($owned) { getOfficeRecordOwner $record $selfId $selfStartTicks } else { "" })
        })
    }
    return $result.ToArray()
}

function stopOfficeProcesses {
    # 指定したプロセスを保存せずに終了し、@{ Id; Stopped; Status; Reason } の配列を返す。
    # targets は getOfficeProcesses の要素（Id・ProcessName・StartTime）。止める直前に、PID が今も同じプロセスか（名前・起動時刻）を照らし直す。
    #   Status: Stopped（止めた）・Changed（名前か起動時刻が違う・読めない・Office の名前でない。止めない）・
    #           Gone（もう無い。止めた扱いにも失敗にもしない）・Failed（止めようとして失敗）
    #   Reason: Changed のときは「PID <N> は確認の後に別のプロセスに変わったため、終了しませんでした。」、Failed のときは例外のメッセージ。それ以外は空
    # recordDir があれば、止めた・もう無いものの記録を消す。プロセスの強制終了は、ここの Stop-Process の 1 か所だけ（tests/meta/safety.Tests.ps1。止める前に isSameOfficeProcess を通す）
    param (
        [object[]]$targets,
        [string]$recordDir = ""
    )

    $results = New-Object System.Collections.Generic.List[object]
    foreach ($target in $targets) {
        $id = [int]$target.Id
        $process = Get-Process -Id $id -ErrorAction SilentlyContinue
        if ($null -eq $process) {
            removeOfficeRecord $recordDir $id
            $results.Add(@{ Id = $id; Stopped = $false; Status = "Gone"; Reason = "" })
            continue
        }
        $expected = $null
        try { $expected = [long]$target.StartTime.ToUniversalTime().Ticks } catch {}
        if (!${officeProcessNames}.Contains([string]$target.ProcessName) -or -not (isSameOfficeProcess $process ([string]$target.ProcessName) $expected)) {
            $results.Add(@{ Id = $id; Stopped = $false; Status = "Changed"; Reason = "PID $id は確認の後に別のプロセスに変わったため、終了しませんでした。" })
            continue
        }
        try {
            Stop-Process -Id $id -Force -ErrorAction Stop
            removeOfficeRecord $recordDir $id
            $results.Add(@{ Id = $id; Stopped = $true; Status = "Stopped"; Reason = "" })
        } catch {
            $results.Add(@{ Id = $id; Stopped = $false; Status = "Failed"; Reason = $_.Exception.Message })
        }
    }
    return $results.ToArray()
}

# 暗号化されたファイルの種類を、開かずに見分ける（判断層）。ファイル・COM・Officeには触らない。
# 入力は「先頭バイト列」と「複合ドキュメント形式（CFB）のディレクトリのエントリ名の配列（CFBでなければ $null）」だけ。
# 実際にファイルを読むのは状態層（office_protection.ps1）。
#
# 種類（getOfficeProtectionKind の戻り値）:
#   Zip      : 新形式（.docx 等）。ふつうに読む
#   Password : パスワード付き（新形式）。Word・PowerPoint は Office を使わずに失敗にする（Excel は今のまま Office に任せる）
#   Rights   : IRM・秘密度ラベルの暗号化。Office で開かない（ライセンス取得・サインイン画面を防ぐ）
#   Legacy   : 旧形式（.doc / .xls / .ppt）など、権限保護と分からないCFB。今と同じ（Officeで開く。ダミーのパスワードで失敗）
#   Text     : 空・RTF・HTML・UTF-8・UTF-16（BOM）など、NULを含まないテキストらしい内容。今と同じ（Officeで開く）
#   Unknown  : 上のどれでもない（先頭4KBにNULを含む）バイナリ。透過暗号化の製品の暗号文の見込みがある。
#              守りを付けてOfficeで開く予備を使う（extract_office.ps1 がアプリごとに切り替える）

${zipSignature}      = [byte[]](0x50, 0x4B, 0x03, 0x04)
${compoundSignature} = [byte[]](0xD0, 0xCF, 0x11, 0xE0, 0xA1, 0xB1, 0x1A, 0xE1)

# 権限保護（IRM・秘密度ラベル）を示すCFBのエントリ名（[MS-OFFCRYPTO] IRMDS）。
#   新形式: DataSpaceInfo配下の DRMEncryptedDataSpace・TransformInfo配下の DRMEncryptedTransform
#   旧形式: 保護された中身の \x09DRMContent（必須）と、\x09DRMDataSpace・\x09DRMTransform
#           （任意で \x09DRMViewerContent・\x09LZXDRMDataSpace・\x09LZXTransform）
${rightsProtectedEntryNames} = @(
    "DRMEncryptedDataSpace", "DRMEncryptedTransform",
    ([char]9 + "DRMContent"), ([char]9 + "DRMDataSpace"), ([char]9 + "DRMTransform"),
    ([char]9 + "DRMViewerContent"), ([char]9 + "LZXDRMDataSpace"), ([char]9 + "LZXTransform")
)
# パスワード保護（ECMA-376 標準・アジャイル暗号化）を示すCFBのエントリ名
${passwordProtectedEntryNames} = @("StrongEncryptionDataSpace", "EncryptionInfo")
# データスペース（新形式のパスワード・権限保護が共通で使うストレージ）の名前
${dataSpacesStorageName} = ([char]6 + "DataSpaces")

function testsByteSignature {
    # $bytes の先頭が $signature と一致するか。
    # 判断層はファイルを開けないため、office_reader.ps1 の isZipFile・isCompoundFile が読むのと同じ印を、
    # 既に読んである先頭バイト列（$bytes）の側で比べる（ファイルを開き直さない）
    param (
        [byte[]]$bytes,
        [byte[]]$signature
    )

    if ($null -eq $bytes -or $bytes.Length -lt $signature.Length) {
        return $false
    }
    for ($i = 0; $i -lt $signature.Length; $i++) {
        if ($bytes[$i] -ne $signature[$i]) {
            return $false
        }
    }
    return $true
}

function testsUnicodeTextBom {
    # UTF-16（Excelのテキスト保存・多くのUnicodeテキストエディタ）の先頭のBOM（FF FE）かどうか
    param (
        [byte[]]$bytes
    )

    return ($null -ne $bytes -and $bytes.Length -ge 2 -and $bytes[0] -eq 0xFF -and $bytes[1] -eq 0xFE)
}

function getOfficeProtectionKind {
    # 先頭バイト列とCFBのエントリ名（CFBでなければ $null）から、暗号化の種類を返す
    param (
        [byte[]]$head,
        [string[]]$cfbNames
    )

    if ($null -eq $head -or $head.Length -eq 0) {
        return "Text"
    }
    if (testsByteSignature $head ${zipSignature}) {
        return "Zip"
    }
    if (testsByteSignature $head ${compoundSignature}) {
        $names = @($cfbNames)
        if (@($names | Where-Object { ${rightsProtectedEntryNames} -contains $_ }).Count -gt 0) {
            return "Rights"
        }
        $hasDataSpaces = ($names -contains ${dataSpacesStorageName})
        $hasPasswordNames = (@($names | Where-Object { ${passwordProtectedEntryNames} -contains $_ }).Count -gt 0)
        if ($hasDataSpaces -and !$hasPasswordNames) {
            # データスペースはあるが、名前を1つも取りこぼした場合。安全側（Officeで開かない）に倒す
            return "Rights"
        }
        if ($hasPasswordNames) {
            return "Password"
        }
        return "Legacy"
    }

    # ZIPでもCFBでもない。先頭4KBにNUL（0x00）を含む（UTF-16のBOMで始まるものを除く）＝形式の分からないバイナリ。
    # 空・RTF（`{\rtf`）・HTML・UTF-8・UTF-16（BOM）は、いずれもNULを含まないテキストのため「Text」になる
    if (testsUnicodeTextBom $head) {
        return "Text"
    }
    if (@($head) -contains [byte]0) {
        return "Unknown"
    }
    return "Text"
}

function getProtectionFailureText {
    # 種類ごとの、取り込み一覧のエラー列に出す短い文言。文言が無い種類（Zip・Legacy・Text）は $null
    param (
        [string]$kind
    )

    switch ($kind) {
        "Password" { return "読み取りパスワードが設定されているため開けません（パスワード付きのファイルは更新できません）" }
        "Rights"   { return "IRM・秘密度ラベルで暗号化されているため更新できません。" }
        "Unknown"  { return "暗号化されているか壊れているため更新できません。" }
        default    { return $null }
    }
}

# Officeが保存した一時ファイル（変換した.docx・.pptx、Excelのテキスト保存）まで、透過暗号化の製品が
# 暗号化した場合の文言。ふつうのファイルでも起こりうるため、すべてのOfficeの出力でこの確認を行う
${officeOutputEncryptedMessage} = "ファイルを暗号化する製品が一時ファイルを暗号化したため更新できません。"

function testOfficeOutput {
    # Officeが保存した出力の先頭バイト列が、期待する形（Zip・UnicodeText）かどうか
    param (
        [byte[]]$head,
        [string]$expectedKind
    )

    if ($expectedKind -eq "Zip") {
        return (testsByteSignature $head ${zipSignature})
    }
    if ($expectedKind -eq "UnicodeText") {
        return (testsUnicodeTextBom $head)
    }
    return $false
}

# Workbook.FileFormat が、テキスト・HTML・CSVとして取り込まれた印の値（xlCSV=6・xlTextMac=19・xlTextWindows=20・
# xlTextMSDOS=21・xlCSVMac=22・xlCSVWindows=23・xlCSVMSDOS=24・xlUnicodeText=42・xlHtml=44・xlCSVUTF8=62・
# xlCurrentPlatformText=-4158）
${excelTextLikeFileFormats} = @(6, 19, 20, 21, 22, 23, 24, 42, 44, 62, -4158)

function testWorkbookFormat {
    # Workbook.FileFormat が、テキスト・HTML・CSVとして取り込まれた印でないか（「形式の分からないバイナリ」のときだけ確かめる。
    # 中身がHTML・CSV等の「Text」の種類のブックには当てない。当てると本来読めているものまで失敗になる）
    param (
        $fileFormat
    )

    return (${excelTextLikeFileFormats} -notcontains $fileFormat)
}

function getWordOpenFormat {
    # 拡張子に合う WdOpenFormat の値。「形式の分からないバイナリ」をWordで開くときだけ渡し、自動判定に任せない
    # （wdOpenFormatDocument=1・wdOpenFormatTemplate=2・wdOpenFormatXMLDocument=9・
    #   wdOpenFormatXMLDocumentMacroEnabled=10・wdOpenFormatXMLTemplate=11・wdOpenFormatAuto=0）
    param (
        [string]$extension
    )

    switch ($extension.ToLowerInvariant()) {
        ".doc"  { return 1 }
        ".dot"  { return 2 }
        ".docx" { return 9 }
        ".docm" { return 10 }
        ".dotx" { return 11 }
        ".dotm" { return 11 }
        default { return 0 }
    }
}

# 暗号化されたファイルの見分け（状態層）: ファイルの先頭バイト列と、複合ドキュメント形式（CFB。[MS-CFB]）の
# ディレクトリのエントリ名を読み、判断層（office_protection_view.ps1）に渡す。
# ファイルを読むだけで、Office・COMには触らない（getOfficeFileProtection を extract_office.ps1 が呼ぶ）。
#
# 壊れたCFB（FATの鎖が輪になる・範囲外のセクター・ディレクトリが途中で切れる）でも例外を出さず、
# 決まった時間で戻る（読める範囲まで返す。ヘッダーさえ読めなければ $null）。
# ディレクトリのエントリ名だけが目的のため、ミニFAT・ストリームの中身は読まない。

${cfbHeadLength}      = 4096          # 先頭バイト列の読み取り量（判断層の判定に使う分）
${cfbFreeSect}        = [uint32]0xFFFFFFFFL
${cfbEndOfChain}      = [uint32]0xFFFFFFFEL
${cfbFatSect}         = [uint32]0xFFFFFFFDL
${cfbDifSect}         = [uint32]0xFFFFFFFCL
${cfbMaxChainSectors} = 200000         # FAT・ディレクトリの鎖をたどる上限（壊れたファイルで止まらないため）

function readFileHead {
    # ファイルの先頭（既定は4096バイト）を読む。開けない・読めなければ空の配列
    param (
        [string]$path,
        [int]$length = ${cfbHeadLength}
    )

    try {
        $stream = [System.IO.File]::OpenRead((toLongPath $path))
    } catch {
        return [byte[]]@()
    }
    try {
        $buffer = New-Object byte[] $length
        $read = $stream.Read($buffer, 0, $length)
        if ($read -eq $length) {
            return $buffer
        }
        $head = New-Object byte[] ([Math]::Max($read, 0))
        if ($read -gt 0) {
            [System.Array]::Copy($buffer, $head, $read)
        }
        return $head
    } catch {
        return [byte[]]@()
    } finally {
        $stream.Dispose()
    }
}

function readUInt32LE {
    # 範囲外なら FREESECT（鎖の終わりと同じ扱いにする安全な既定値）を返す
    param (
        [byte[]]$bytes,
        [int]$offset
    )

    if ($null -eq $bytes -or $offset -lt 0 -or ($offset + 4) -gt $bytes.Length) {
        return ${cfbFreeSect}
    }
    return [System.BitConverter]::ToUInt32($bytes, $offset)
}

function readCfbSector {
    # セクター番号（0起点）1つ分のバイト列。範囲外・読めなければ $null
    param (
        $stream,
        [double]$sectorSize,
        [long]$fileLength,
        [uint32]$secId
    )

    if ($secId -eq ${cfbFreeSect} -or $secId -eq ${cfbEndOfChain} -or $secId -eq ${cfbFatSect} -or $secId -eq ${cfbDifSect}) {
        return $null
    }
    $offset = [int64]$sectorSize * ([int64]$secId + 1)
    if ($offset -lt 0 -or ($offset + $sectorSize) -gt $fileLength) {
        return $null
    }
    try {
        [void]$stream.Seek($offset, [System.IO.SeekOrigin]::Begin)
        $buffer = New-Object byte[] ([int]$sectorSize)
        if ($stream.Read($buffer, 0, [int]$sectorSize) -ne [int]$sectorSize) {
            return $null
        }
        return $buffer
    } catch {
        return $null
    }
}

function getCfbFatSectorIds {
    # FATセクターの並び（順番が、その並びのk番目が担当するセクター番号の範囲を決める索引）を返す。
    # DIFAT（ヘッダーの109件 + DIFATセクターの鎖）だけをたどり、FATセクターの中身はまだ読まない
    # （中身は、ディレクトリの鎖をたどるときに要る分だけ readCfbFatEntry が読む）
    param (
        $stream,
        [byte[]]$header,
        [double]$sectorSize,
        [long]$fileLength
    )

    $entriesPerSector = [int]($sectorSize / 4)
    $fatSectorIds = New-Object 'System.Collections.Generic.List[uint32]'
    for ($i = 0; $i -lt 109; $i++) {
        $value = readUInt32LE $header (76 + $i * 4)
        if ($value -ne ${cfbFreeSect}) {
            $fatSectorIds.Add($value)
        }
    }

    $difatSec = readUInt32LE $header 68
    $seenDifat = New-Object 'System.Collections.Generic.HashSet[uint32]'
    $steps = 0
    while ($difatSec -ne ${cfbEndOfChain} -and $difatSec -ne ${cfbFreeSect} -and $steps -lt ${cfbMaxChainSectors} -and $seenDifat.Add($difatSec)) {
        $buffer = readCfbSector $stream $sectorSize $fileLength $difatSec
        if ($null -eq $buffer) {
            break
        }
        $entriesInSector = $entriesPerSector - 1
        for ($i = 0; $i -lt $entriesInSector; $i++) {
            $value = readUInt32LE $buffer ($i * 4)
            if ($value -ne ${cfbFreeSect}) {
                $fatSectorIds.Add($value)
            }
        }
        $difatSec = readUInt32LE $buffer ($entriesInSector * 4)
        $steps++
    }
    return $fatSectorIds
}

function readCfbFatEntry {
    # セクター番号1つ分の、FATの次のセクター番号を返す。
    # そのセクター番号を持つFATセクター（$fatSectorIds の何番目か）だけを読み、$fatCache に貯めて使い回す
    # （旧形式のふつうのファイルでもディレクトリの判定のたびに動くため、FAT全体を毎回読まない）
    param (
        $stream,
        [double]$sectorSize,
        [long]$fileLength,
        [System.Collections.Generic.List[uint32]]$fatSectorIds,
        [System.Collections.Generic.Dictionary[int, byte[]]]$fatCache,
        [uint32]$secId
    )

    $entriesPerSector = [int]($sectorSize / 4)
    $position = [int]([Math]::Floor([double]$secId / $entriesPerSector))
    if ($position -lt 0 -or $position -ge $fatSectorIds.Count) {
        return ${cfbFreeSect}
    }
    if (!$fatCache.ContainsKey($position)) {
        $fatCache[$position] = readCfbSector $stream $sectorSize $fileLength $fatSectorIds[$position]
    }
    $buffer = $fatCache[$position]
    if ($null -eq $buffer) {
        return ${cfbFreeSect}
    }
    $offset = ([int]($secId % $entriesPerSector)) * 4
    return readUInt32LE $buffer $offset
}

function readCfbDirectoryEntryNames {
    # ディレクトリ（ルート・ストレージ・ストリーム）のエントリ名を、鎖をたどって集める
    param (
        $stream,
        [double]$sectorSize,
        [long]$fileLength,
        [System.Collections.Generic.List[uint32]]$fatSectorIds,
        [uint32]$firstDirSector
    )

    $names = New-Object 'System.Collections.Generic.List[string]'
    $entriesPerSector = [int]($sectorSize / 128)
    $fatCache = New-Object 'System.Collections.Generic.Dictionary[int, byte[]]'
    $seen = New-Object 'System.Collections.Generic.HashSet[uint32]'
    $sec = $firstDirSector
    $steps = 0
    while ($sec -ne ${cfbEndOfChain} -and $sec -ne ${cfbFreeSect} -and $steps -lt ${cfbMaxChainSectors} -and $seen.Add($sec)) {
        $buffer = readCfbSector $stream $sectorSize $fileLength $sec
        if ($null -eq $buffer) {
            break
        }
        for ($i = 0; $i -lt $entriesPerSector; $i++) {
            $entryOffset = $i * 128
            $nameLength = [System.BitConverter]::ToUInt16($buffer, $entryOffset + 64)
            if ($nameLength -ge 2 -and $nameLength -le 64) {
                $name = [System.Text.Encoding]::Unicode.GetString($buffer, $entryOffset, $nameLength - 2)
                if ($name -ne "") {
                    $names.Add($name)
                }
            }
        }
        $sec = readCfbFatEntry $stream $sectorSize $fileLength $fatSectorIds $fatCache $sec
        $steps++
    }
    return $names
}

function readCompoundEntryNames {
    # CFBのディレクトリのエントリ名の配列を返す。CFBでない・読めない・壊れている場合は $null
    # （判断層は $null を、権限保護と分からない「旧形式」として扱う）
    param (
        [string]$path
    )

    try {
        $stream = [System.IO.File]::OpenRead((toLongPath $path))
    } catch {
        return $null
    }
    try {
        $fileLength = $stream.Length
        if ($fileLength -lt 512) {
            return $null
        }
        $header = New-Object byte[] 512
        if ($stream.Read($header, 0, 512) -ne 512) {
            return $null
        }
        $signature = [byte[]](0xD0, 0xCF, 0x11, 0xE0, 0xA1, 0xB1, 0x1A, 0xE1)
        for ($i = 0; $i -lt 8; $i++) {
            if ($header[$i] -ne $signature[$i]) {
                return $null
            }
        }

        $sectorShift = [System.BitConverter]::ToUInt16($header, 30)
        if ($sectorShift -ne 9 -and $sectorShift -ne 12) {
            return $null
        }
        $sectorSize = [double][Math]::Pow(2, $sectorShift)
        $firstDirSector = readUInt32LE $header 48

        $fatSectorIds = getCfbFatSectorIds $stream $header $sectorSize $fileLength
        return @(readCfbDirectoryEntryNames $stream $sectorSize $fileLength $fatSectorIds $firstDirSector)
    } catch {
        return $null
    } finally {
        $stream.Dispose()
    }
}

function getOfficeFileProtection {
    # ファイルを読み、暗号化の種類（getOfficeProtectionKind の戻り値）を返す
    param (
        [string]$path
    )

    $head = readFileHead $path
    $cfbNames = readCompoundEntryNames $path
    return getOfficeProtectionKind $head $cfbNames
}

# 設定を先に読み込む（ワークスペースは設定の workspaceFolder で決まる。paths.ps1 の initWorkspace を
# 起動口（startGui・invokeIndexerMain）が壊れた設定ファイルの退避の後に呼んで決める）
# tebunko のログの先頭に書く見出しと、インデックス作成のログの書き口（状態層）。shared/ がツールの名前を知らないよう、名前はここで渡す。

function getToolDiagnosticHeader {
    # 見出しの行（配列）。版は配布物の VERSION.txt（無ければ開発版。.git のファイルから分かるタグとコミットを添える）
    $version = readVersionFile "${rootDir}\VERSION.txt"
    $devInfo = if ($null -eq $version) { readDevVersion ${rootDir} } else { $null }
    return formatDiagnosticHeader "tebunko" $version (getEnvironmentInfo) ([System.DateTimeOffset]::Now) $devInfo
}

# インデックス作成のログ（invokeIndexer が開く TextWriter。取り込みのスレッドでは 1 ファイル分を貯める StringWriter）
$script:indexerLog = $null
# ログをコンソールにも出すか（画面を使わずに indexer.ps1 を実行したとき）
$script:indexerEcho = $false

function writeIndexerLog {
    # インデックス作成の表示内容をログ（indexing_log.txt）に書く。color はコンソールに出すときの色
    param (
        [string]$text = "",
        [string]$color = ""
    )

    if ($null -ne $script:indexerLog) {
        try {
            $script:indexerLog.WriteLine($text)
        } catch {
            # ログのためだけの書き込みのため、書けなくてもインデックス作成は続ける
        }
    }
    if ($script:indexerEcho) {
        if ($color) {
            Write-Host $text -ForegroundColor $color
        } else {
            Write-Host $text
        }
    }
}

# setting.config の読み書き（tebunko の設定）。

# ツールの ID（多重起動の防止・ミューテックスの名前に使う）。
# 起動口（gui.ps1・indexer.ps1）が lib.ps1 より先に、このファイルだけを読み込んで設定を確かめる（repairBrokenSettings）ため、ここで決める
${appId} = "tebunko"

function getDefaultWorkDir {
    # 既定のワークスペース（%USERPROFILE%\Documents\tebunko_ws）。高速検索のため、Windows Search の索引の対象になる場所に置く。
    # OneDrive にリダイレクトされた「ドキュメント」ではなく、プロファイルの直下の Documents を使う（インデックスが同期でクラウドに上がらないように）
    # 環境変数 TEBUNKO_DEFAULT_WORKSPACE に絶対パスが入っていれば、それを既定のワークスペースにする（開発・確かめ用。
    # テストや実機の確かめが、利用者の既定のワークスペースに触れないようにするための差し替えの口）。入っているのに絶対パスでなければ、
    # 黙って既定のワークスペースに戻らないよう例外にする。引数 profileDir を渡したときは、環境変数を見ない
    param (
        [string]$profileDir = [System.Environment]::GetFolderPath("UserProfile")
    )

    $override = $env:TEBUNKO_DEFAULT_WORKSPACE
    if (!$PSBoundParameters.ContainsKey("profileDir") -and ![string]::IsNullOrWhiteSpace($override)) {
        $override = $override.Trim()
        # ドライブ直下だけ（C:\）やサーバー名だけ（\\server\）は、末尾の区切りを削ると別の意味になるため受け付けない
        if ($override -notmatch '^([A-Za-z]:[\\/]+[^\\/]|\\\\[^\\/]+[\\/]+[^\\/])') {
            throw "TEBUNKO_DEFAULT_WORKSPACE はフォルダまで含めた絶対パスで指定してください: $override"
        }
        return $override.TrimEnd("\", "/")
    }

    return Join-Path $profileDir "Documents\tebunko_ws"
}

function getSettingsFilePath {
    # 設定ファイルのパス。ツールのフォルダに書き込めればそこ、書き込めないとき（Program Files・読み取り専用の共有フォルダ）は
    # 既定のワークスペースの直下に置く（shared\core\data_dir.ps1 の getDataDir）。設定はワークスペースの場所を読む前に見つかる必要があるため、
    # ワークスペースを別の場所に移しても、設定は既定のワークスペースに残る
    param (
        [string]$root,
        [string]$defaultWorkDir
    )

    return Join-Path (getDataDir $root $defaultWorkDir) "setting.config"
}

# 設定ファイル（画面が読み書きする。インデクサはクロール対象フォルダと work の置き場所を読む）。内容は JSON。
# ツールのフォルダに書き込めないときは、既定のワークスペースの直下に置く
${settingsFile} = getSettingsFilePath ${rootDir} (getDefaultWorkDir)

function testSettingsFileName {
    # 設定ファイルと、それに付いてできるファイルの名前か（setting.config・保存の途中で止まると残る setting.config.tmp・
    # 壊れた設定の退避 setting.config.broken-<日時>（同じ名前があれば -2・-3… が付く））。
    # 既定のワークスペースの空の判定では、これらを tebunko のファイルとして数えない
    param (
        [string]$name
    )

    $base = [regex]::Escape([System.IO.Path]::GetFileName(${settingsFile}))
    return [bool]($name -imatch "^${base}(\.tmp|\.broken-\d{8}-\d{6}(-\d+)?)?$")
}

# 検索結果から元のファイルを開くときの開き方（設定 openMode の値）
${openModeNormal}   = "normal"    # そのまま開く（編集する）
${openModeReadOnly} = "readOnly"  # 読み取り専用で開く（誤って上書きしない）
${openModeNew}      = "new"       # 新規（元のファイルを基にした無題の文書）で開く。元のファイルを占有しない
${openModes}        = @(${openModeNormal}, ${openModeReadOnly}, ${openModeNew})

# インデックス作成で、クラウドにだけあるファイル（OneDrive・SharePoint のオンデマンド）をどうするか（設定 cloudFiles の値）
${cloudFilesAsk}      = "ask"       # ダウンロードせずに残す（確認の画面で、ダウンロードして取り込むかを選べる）
${cloudFilesDownload} = "download"  # 確認なしでダウンロードして取り込む
${cloudFilesModes}    = @(${cloudFilesAsk}, ${cloudFilesDownload})

# 検索の対象にするファイルの種類（検索バーのチップ。設定ファイルの fileKinds の値）
${fileKindNames} = @("excel", "word", "powerpoint", "text", "pdf")

function newSettings {
    # 設定の既定値。設定ファイル（JSON）のキーと同じ
    return [ordered]@{
        targetFolders      = @()      # クロール対象フォルダ: @{ name（インデックス名）; path（今フォルダが置かれている場所）; enabled }（記載順。enabled が false は登録のみで取り込まない）
        indexSources       = @()      # 取り込まないインデックスの元のフォルダ: @{ name; path }（別のPC・場所で作ったインデックスを検索するとき）
        searchExcludes     = @()      # 画面の検索対象ツリーでチェックを外したフォルダ: @{ path（フルパス）; subfolders（false はフォルダ直下のファイルだけ） }
        fileKinds          = @()      # 検索の対象にするファイルの種類（excel・word・powerpoint・text の配列。キーが無い・空ならすべて。readFileKinds）
        useRegex           = $false   # 検索ワードを正規表現として扱う
        caseSensitive      = $false   # 英字の大文字と小文字を区別する
        includeShapes      = $true    # 図形（テキストボックス等）の文字も検索する（場所 "<元の場所>[図形]"。index_name.ps1 の objectPlacePattern）
        includeComments    = $true    # コメントも検索する（場所 "<元の場所>[コメント]"）
        openMode           = ${openModeNormal}  # 検索結果の元のファイルの開き方: 通常（編集する）/ 読み取り専用 / 新規（元のファイルを基にした無題の文書。占有しない）
        workspaceFolder    = ""       # ワークスペース（インデックス・取り込み一覧・ログを置くフォルダ）。空なら既定（%USERPROFILE%\Documents\tebunko_ws。getDefaultWorkDir）
        cloudFiles         = ${cloudFilesAsk}  # クラウドにだけあるファイルの扱い: ask（ダウンロードせずに残す。確認の画面で選べる）/ download（ダウンロードして取り込む）。知らない値は ask（readCloudFiles）
        ingestThreads      = 0        # Office を使わずに読むファイル（.docx・.pptx など）の読み取りのスレッドの数（1～4。0 はコア数から決める。getIngestWorkerCount）。Excel・Word・PowerPoint は種類ごとに 1 つ
    }
}

function readSettings {
    # 設定を newSettings と同じ形で返す。記載の無い項目は既定値。設定ファイルが無ければ既定値
    param (
        [string]$path = ${settingsFile}
    )

    $settings = newSettings
    if (!(Test-Path -LiteralPath $path)) {
        return $settings
    }

    # ロック・共有違反などの読み込みの失敗（IOException）は、壊れているのではないため、そのまま例外にする
    $json = [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8)
    if ($json.Trim() -eq "") {
        return $settings
    }
    try {
        $data = ConvertFrom-Json $json
    } catch {
        # JSON として読めない（壊れている）ときは FormatException にする。ファイルは動かさない（退避は repairBrokenSettings が行う）
        throw (New-Object System.FormatException("$([System.IO.Path]::GetFileName($path)) を読み込めません。（$($_.Exception.Message)）"))
    }
    # 中身が null だけなら、空のファイルと同じく既定値（配列・数値だけのときと同じ扱い）
    if ($null -eq $data) {
        return $settings
    }
    foreach ($key in @($settings.Keys)) {
        $property = $data.PSObject.Properties[$key]
        if ($null -eq $property -or $null -eq $property.Value) {
            continue
        }
        if ($settings[$key] -is [array]) {
            $settings[$key] = @($property.Value | Where-Object { $null -ne $_ })
        } elseif ($settings[$key] -is [string]) {
            $settings[$key] = [string]$property.Value
        } elseif ($settings[$key] -is [int]) {
            # 数値。手で書き換えて数値にできないときは既定値
            $number = 0
            if ([int]::TryParse([string]$property.Value, [ref]$number)) {
                $settings[$key] = $number
            }
        } else {
            $settings[$key] = toSettingBool $property.Value $settings[$key]
        }
    }
    return $settings
}

function repairBrokenSettings {
    # 設定ファイルが JSON として読めないとき（ConvertFrom-Json の失敗だけ。空・null だけのファイルは今までどおり既定値で読むため対象外）、
    # 元の中身のまま setting.config.broken-<yyyyMMdd-HHmmss> に移し（同じ名前があれば -2・-3… を付けて、前の退避を上書きしない）、移したパスを返す。
    # 移すと設定ファイルが無くなり、既定値で起動できる。壊れていない・無いときは何もせず空文字を返す。
    # 移せなかったときは例外にする（壊れたファイルを残したまま既定値で上書きしないため）。
    # readSettings はファイルを動かさない。起動口（gui.ps1・indexer.ps1）が、起動の時に 1 回だけ呼ぶ
    param (
        [string]$path = ${settingsFile}
    )

    return invokeSettingsLocked -path $path -action {
        if (!(Test-Path -LiteralPath $path)) {
            return ""
        }
        $json = [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8)
        if ($json.Trim() -eq "") {
            return ""
        }
        try {
            $null = ConvertFrom-Json $json
            return ""
        } catch {
            # 壊れている。下で退避する
        }

        $brokenBase = "${path}.broken-" + (Get-Date).ToString("yyyyMMdd-HHmmss")
        $brokenPath = $brokenBase
        $serial = 2
        while (Test-Path -LiteralPath $brokenPath) {
            $brokenPath = "${brokenBase}-${serial}"
            $serial++
        }
        try {
            [System.IO.File]::Move($path, $brokenPath)
        } catch {
            throw "$([System.IO.Path]::GetFileName($path)) が壊れているため退避しようとしましたが、移せませんでした。tebunko を使っているほかのプログラム（ウイルス対策ソフトなど）を確かめてください。（$($_.Exception.Message)）"
        }
        return $brokenPath
    }
}

function getSettingsRecoveryMessage {
    # 壊れた設定ファイルを退避して既定の設定で起動したときの知らせの文言（画面の起動時・画面なしのインデクサで共通）。
    # brokenPath は repairBrokenSettings が返した、退避したファイルのパス
    param (
        [string]$brokenPath
    )

    return "設定ファイルが壊れていたため、既定の設定で起動しました。ワークスペースの場所・登録したフォルダなども既定に戻っています。`n元に戻すには、tebunko を閉じてから、退避したファイル（${brokenPath}）を直して setting.config に置き換え、開き直してください。"
}

function toSettingBool {
    # 設定ファイルの真偽値を読む。手で書き換えた "false" などの文字列は [bool] にすると $true になるため、
    # 文字列は true / false として読み、読めなければ既定値（default）にする
    param (
        $value,
        [bool]$default
    )

    if ($value -is [string]) {
        $parsed = $false
        if ([bool]::TryParse($value.Trim(), [ref]$parsed)) {
            return $parsed
        }
        return $default
    }
    return [bool]$value
}

function writeSettings {
    param (
        $settings,
        [string]$path = ${settingsFile}
    )

    # 書き込みの途中で止まっても設定ファイルが壊れないよう、一時ファイルに書いてから置き換える（BOM なし UTF-8）
    writeTextLinesAtomic $path @((ConvertTo-Json -InputObject $settings -Depth 5)) (New-Object System.Text.UTF8Encoding($false))
}

function invokeSettingsLocked {
    # 設定ファイルの「読む → 変える → 書く」の一続きを、ほかの画面・インデクサ（別のプロセスも）と同時に行わないよう、
    # 設定ファイルごとの名前付きミューテックスの中で action を実行する（同じスレッドの入れ子は通す）。
    # action の出力を返す。5 秒待っても取れなければ例外（invokeWithNamedMutex）
    param (
        [string]$path,
        [scriptblock]$action,
        [int]$timeoutMilliseconds = 5000
    )

    $lockKey = getFolderKey ([System.IO.Path]::GetFullPath($path))
    return invokeWithNamedMutex "Local\${appId}_settings_${lockKey}" $timeoutMilliseconds $action
}

function updateSettings {
    # 設定ファイルを読み直して key の値だけを変えて保存する（ほかの項目は、ほかの画面・処理が保存した内容を保つ）
    param (
        [string]$key,
        $value,
        [string]$path = ${settingsFile}
    )

    invokeSettingsLocked -path $path -action {
        $settings = readSettings $path
        $settings[$key] = $value
        writeSettings $settings $path
    }
}

function getTargetFolders {
    # クロール対象フォルダの一覧（記載順）を返す: @{ Name; Path; Enabled }。
    #   Name   : インデックス名（work\index 直下のフォルダ名）。インデックスの「名前」で、フォルダの置き場所（Path）とは分けて持つ。
    #            Path を書き換えても Name が同じなら同じインデックスとして扱う（取り込み直さない）。空なら取り込み時に割り当てる（assignIndexNames）
    #   Path   : そのフォルダが今置かれている場所
    #   Enabled: false はチェックなし（登録のみで取り込まない）
    # 同じフォルダ・同じ名前は最初のものだけ使う（名前の重複は、2 つ目以降を空にして割り当て直す）。
    # 書き方が違うだけで同じフォルダを指す場合（ネットワークドライブと UNC パスなど）も同じフォルダとみなす
    param (
        [string]$path = ${settingsFile}
    )

    $folders = New-Object System.Collections.Generic.List[object]
    $seenPath = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $seenName = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($item in @((readSettings $path).targetFolders)) {
        $folder = normalizeFolderPath ([string]$item.path)
        if ($folder -eq "" -or -not $seenPath.Add($folder)) {
            continue
        }
        if (@($folders | Where-Object { testSameFolder $_.Path $folder }).Count -gt 0) {
            continue
        }
        $name = toSafeFileName ([string]$item.name).Trim()
        if ($name -ne "" -and -not $seenName.Add($name)) {
            $name = ""
        }
        $folders.Add([pscustomobject]@{ Name = $name; Path = $folder; Enabled = ($item.enabled -ne $false) })
    }
    return $folders.ToArray()
}

function writeTargetFolders {
    # クロール対象フォルダの一覧（@{ Name; Path; Enabled } の配列）を保存する
    param (
        [object[]]$folders,
        [string]$path = ${settingsFile}
    )

    updateSettings "targetFolders" ([object[]]@($folders | Where-Object { $_ } | ForEach-Object {
        [pscustomobject]@{ name = [string]$_.Name; path = $_.Path; enabled = [bool]$_.Enabled }
    })) $path
}

function mergeAssignedIndexNames {
    # 今の設定のクロール対象フォルダ（current。getTargetFolders の形）に、インデクサ・画面が割り当てたインデックス名（assigned。
    # assignIndexNames の結果）を反映した一覧を返す。インデクサが始めに読んだ一覧を丸ごと書き戻すと、その間の画面での変更を消すため、
    # 書き戻す直前に読み直した一覧へ、割り当てた名前だけを足す。
    # 突き合わせる鍵はパス（大文字と小文字は区別しない）。名前は、今の一覧で名前が空の項目にだけ付ける。
    # 同じ名前をほかの項目が使っていれば付けない（空のまま。次の機会に割り当て直す）
    param (
        [object[]]$current,
        [object[]]$assigned
    )

    $assignedNames = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($item in @($assigned | Where-Object { $_ -and $_.Name })) {
        $assignedNames[[string]$item.Path] = [string]$item.Name
    }
    $used = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($item in @($current | Where-Object { $_ -and $_.Name })) {
        [void]$used.Add([string]$item.Name)
    }

    $result = New-Object System.Collections.Generic.List[object]
    foreach ($item in @($current | Where-Object { $_ })) {
        $name = [string]$item.Name
        if ($name -eq "" -and $assignedNames.ContainsKey([string]$item.Path) -and $used.Add($assignedNames[[string]$item.Path])) {
            $name = $assignedNames[[string]$item.Path]
        }
        $result.Add([pscustomobject]@{ Name = $name; Path = $item.Path; Enabled = $item.Enabled })
    }
    return $result.ToArray()
}

function saveAssignedIndexNames {
    # 割り当てたインデックス名（assigned。assignIndexNames の結果）を設定に保存し、保存した一覧（@{ Name; Path; Enabled }）を返す。
    # 設定を読み直し（ほかの画面・インデクサの変更を保つ）、mergeAssignedIndexNames で名前だけを足して書く（読む → 書くを排他の中で行う）。
    # 名前を付けられなかった項目（同じ名前をほかの項目が使っている・ほかが先に名前を付けた）は、返す一覧でも設定のとおり（空か、先に付いた名前）
    param (
        [object[]]$assigned,
        [string]$path = ${settingsFile}
    )

    return invokeSettingsLocked -path $path -action {
        $merged = @(mergeAssignedIndexNames @(getTargetFolders $path) $assigned)
        writeTargetFolders $merged $path
        return $merged
    }
}

function readIndexSources {
    # 取り込まないインデックスの元のフォルダ（indexSources）を @{ Name; Path } の配列で返す。
    # 別の PC・場所で作ったインデックスを検索するとき、そのインデックス名の元のフォルダを覚えておくために使う
    param (
        [string]$path = ${settingsFile}
    )

    $items = New-Object System.Collections.Generic.List[object]
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($item in @((readSettings $path).indexSources)) {
        $name = ([string]$item.name).Trim()
        $folder = normalizeFolderPath ([string]$item.path)
        if ($name -eq "" -or $folder -eq "" -or -not $seen.Add($name)) {
            continue
        }
        $items.Add([pscustomobject]@{ Name = $name; Path = $folder })
    }
    return $items.ToArray()
}

function writeIndexSources {
    param (
        [object[]]$sources,
        [string]$path = ${settingsFile}
    )

    updateSettings "indexSources" ([object[]]@($sources | Where-Object { $_ } | ForEach-Object {
        [pscustomobject]@{ name = $_.Name; path = $_.Path }
    })) $path
}

function setIndexSourceFolder {
    # インデックス名に対する元のフォルダ（今そのフォルダが置かれている場所）を設定に記録する。
    # クロール対象フォルダにある名前ならそのパスを書き換え、無ければ indexSources に記録する。
    # 「名前」と「置き場所」を分けて持つため、フォルダを移した場合もこの 1 か所を書き換えるだけで済む
    param (
        [string]$name,
        [string]$folder,
        [string]$path = ${settingsFile}
    )

    # 名前は文字の並びそのもの（大文字・小文字だけ区別しない）で比べる。-eq はカルチャに従い、ソフトハイフンなどを無視して
    # 別の名前（利用者自身の対象フォルダ）に一致してしまう。前後の空白（全角空白を含む）がある名前は、読み込み（readIndexSources）で
    # 前後を削るため同じ名前として読み戻せない。記録しない（確認の判定と食い違わせない）
    $name = [string]$name
    $folder = normalizeFolderPath $folder
    if (!(testSourceNameRecordable $name) -or $folder -eq "") {
        return
    }

    invokeSettingsLocked -path $path -action {
        $same = { param ($other) [string]::Equals([string]$other, $name, [System.StringComparison]::OrdinalIgnoreCase) }
        $targets = @(getTargetFolders $path)
        if (@($targets | Where-Object { & $same $_.Name }).Count -gt 0) {
            writeTargetFolders @($targets | ForEach-Object {
                if (& $same $_.Name) { [pscustomobject]@{ Name = $_.Name; Path = $folder; Enabled = $_.Enabled } } else { $_ }
            }) $path
            return
        }

        $sources = @(@(readIndexSources $path | Where-Object { !(& $same $_.Name) }) + @([pscustomobject]@{ Name = $name; Path = $folder }))
        writeIndexSources $sources $path
    }
}

${searchOptionKeys} = [ordered]@{
    UseRegex = "useRegex"; CaseSensitive = "caseSensitive"
    IncludeShapes = "includeShapes"; IncludeComments = "includeComments"
}


function readSearchOption {
    # 画面の検索オプションを @{ UseRegex; CaseSensitive; IncludeShapes; IncludeComments } で返す。
    # 設定が無ければ、文字どおり・大文字と小文字を区別しない・図形とコメントも検索する（検索するファイルの種類は readFileKinds）
    param (
        [string]$path = ${settingsFile}
    )

    $settings = readSettings $path
    $option = @{}
    foreach ($name in ${searchOptionKeys}.Keys) {
        $option[$name] = $settings[${searchOptionKeys}[$name]]
    }
    return $option
}

function writeSearchOption {
    # 画面の検索オプションを保存する。option（readSearchOption と同じ形）にある項目だけを変える
    param (
        [hashtable]$option,
        [string]$path = ${settingsFile}
    )

    invokeSettingsLocked -path $path -action {
        $settings = readSettings $path
        foreach ($name in ${searchOptionKeys}.Keys) {
            if ($option.ContainsKey($name)) {
                $settings[${searchOptionKeys}[$name]] = $option[$name]
            }
        }
        writeSettings $settings $path
    }
}

function readFileKinds {
    # 検索の対象にするファイルの種類（${fileKindNames} の値）を、${fileKindNames} の順の配列で返す。
    # キーが無い・空・知らない値だけのときは、すべての種類（絞り込まない）
    param (
        [string]$path = ${settingsFile}
    )

    $chosen = @(@((readSettings $path).fileKinds) | ForEach-Object { ([string]$_).Trim().ToLowerInvariant() })
    $kinds = @(${fileKindNames} | Where-Object { $chosen -contains $_ })
    if ($kinds.Count -eq 0) {
        return @(${fileKindNames})
    }
    return $kinds
}

function writeFileKinds {
    # 検索の対象にするファイルの種類を保存する。知らない値は捨てる（すべての種類を選んでいるときは空で保存する）。
    # 1 つも選んでいないときは保存しない（空は「すべて」の意味で保存の形を変えないため、前に保存した種類のまま）
    param (
        [object[]]$kinds,
        [string]$path = ${settingsFile}
    )

    $chosen = @(${fileKindNames} | Where-Object { @($kinds) -contains $_ })
    if ($chosen.Count -eq 0) {
        return
    }
    if ($chosen.Count -eq ${fileKindNames}.Count) {
        $chosen = @()
    }
    updateSettings "fileKinds" ([object[]]$chosen) $path
}

function readOpenMode {
    # 元のファイルの開き方（${openModes} のいずれか）を返す。設定が無い・知らない値なら「通常」
    param (
        [string]$path = ${settingsFile}
    )

    $mode = (readSettings $path).openMode
    if (${openModes} -contains $mode) {
        return $mode
    }
    return ${openModeNormal}
}

function writeOpenMode {
    param (
        [string]$mode,
        [string]$path = ${settingsFile}
    )

    updateSettings "openMode" $mode $path
}

function readCloudFiles {
    # クラウドにだけあるファイルの扱い（${cloudFilesModes} のいずれか）を返す。設定が無い・知らない値なら ask
    param (
        [string]$path = ${settingsFile}
    )

    $mode = (readSettings $path).cloudFiles
    if (${cloudFilesModes} -contains $mode) {
        return $mode
    }
    return ${cloudFilesAsk}
}

function writeCloudFiles {
    param (
        [string]$mode,
        [string]$path = ${settingsFile}
    )

    updateSettings "cloudFiles" $mode $path
}

# 既定のワークスペースが空でないときの文言（画面の［既定に戻す］・起動時、インデクサで共通）
function getDefaultWorkspaceError {
    param (
        [string]$folder
    )

    return "「${folder}」は空のフォルダではありません。ワークスペースには別の空のフォルダを選んでください（［設定］の［変更…］）。"
}

function testDefaultWorkspace {
    # 既定のワークスペースを使えるか: @{ Usable; Folder; Message }。
    # 使える: 無い（使うときに作る）・空（設定ファイルと、それに付いてできるファイルだけの場合を含む）・前から使っているワークスペース（content_index・前の版の index・ingest_status.tsv がある）。
    # それ以外（ほかのファイルが置いてある）は、インデックスのファイルと混ざるため使わせない
    param (
        [string]$folder = (getDefaultWorkDir)
    )

    $result = @{ Usable = $true; Folder = $folder; Message = "" }
    # 既定の場所がネットワークにある（プロファイルが共有にある・環境変数 TEBUNKO_DEFAULT_WORKSPACE が UNC のパス）ときは、
    # 画面のスレッドで中身を数えない（届かないと止まる）。確かめず、使えるものとして扱う
    if (testNetworkPath $folder) {
        return $result
    }
    if (![System.IO.Directory]::Exists($folder)) {
        return $result
    }
    # 設定ファイルと、それに付いてできるファイルは数えない（既定のワークスペースは、書き込めないときの設定ファイルの置き場所でもある）
    $names = @(foreach ($entry in (selectFirstEntries ([System.IO.Directory]::EnumerateFileSystemEntries($folder)) 1000)) {
        $name = [System.IO.Path]::GetFileName($entry)
        if (-not (testSettingsFileName $name)) { $name }
    })
    if ($names.Count -eq 0 -or ($names -contains "content_index") -or ($names -contains "index") -or ($names -contains [System.IO.Path]::GetFileName($workspace.StatusFile))) {
        return $result
    }
    $result.Usable = $false
    $result.Message = getDefaultWorkspaceError $folder
    return $result
}

function getWorkspaceBlockMessage {
    # 今のワークスペースが既定の場所で、そこにほかのファイルが置いてあるなら、その文言（使えるなら空）。
    # インデックスのファイルと混ざるため、インデックス作成を始めず、［設定］で別のフォルダを選んでもらう
    param (
        [string]$current = $workspace.Dir,
        [string]$defaultDir = (getDefaultWorkDir)
    )

    if (!(testSameFolder $current $defaultDir)) {
        return ""
    }
    return (testDefaultWorkspace $defaultDir).Message
}

function getWorkDir {
    # work の置き場所を返す。設定 workspaceFolder が空なら既定（getDefaultWorkDir）。
    # 手で書いた相対パスは、設定ファイルのフォルダからとみなす
    param (
        [string]$path = ${settingsFile}
    )

    $folder = ([string](readSettings $path).workspaceFolder).Trim()
    if ($folder -eq "") {
        return getDefaultWorkDir
    }
    $folder = [System.Environment]::ExpandEnvironmentVariables($folder)
    return [System.IO.Path]::GetFullPath([System.IO.Path]::Combine([System.IO.Path]::GetDirectoryName($path), $folder)).TrimEnd("\")
}

function writeWorkspaceFolder {
    # work の置き場所を保存する。既定の場所なら空にする（ツールのフォルダを移しても既定のまま付いてくるように）
    param (
        [string]$folder,
        [string]$path = ${settingsFile}
    )

    $folder = ([string]$folder).Trim().TrimEnd("\")
    if ($folder -ne "" -and (testSameFolder $folder (getDefaultWorkDir))) {
        $folder = ""
    }
    updateSettings "workspaceFolder" $folder $path
}

# 検索対象ツリーでチェックを外したフォルダ（設定の searchExcludes）の読み書きと、「フォルダとその下」の比較。
# インデックスの改名・削除（IndexCatalog）、ワークスペースの切り替え（WorkspaceMover）、検索対象ツリーの保存が、同じ部品を通す。
# 設定の読み書きは settings.ps1（invokeSettingsLocked・readSettings・updateSettings）を使う。

function testFolderOrUnder {
    # path が folder そのもの、または folder の下にあるかを返す（フォルダとその下の比較は、ここだけで行う）。
    # 大文字・小文字は区別しない（序数の比較。NTFS と同じ扱いで、文化による同一視はしない）。
    # folder の末尾の \ は無いものとして比べ、"<folder>\" で始まるものだけを「下」にする（Sales の下に Sales2 は入らない）。
    # folder が空なら、どれも含まない
    param (
        [string]$path,
        [string]$folder
    )

    $folder = ([string]$folder).TrimEnd("\")
    if ($folder -eq "" -or $null -eq $path) {
        return $false
    }
    return $path.Equals($folder, [System.StringComparison]::OrdinalIgnoreCase) -or
        $path.StartsWith($folder + "\", [System.StringComparison]::OrdinalIgnoreCase)
}

function readSearchExcludes {
    # 画面の検索対象ツリーでチェックを外したフォルダを @{ Path; Subfolders } の配列で返す（設定が無ければ空 = すべて検索する）。
    #   Subfolders: $true はフォルダ以下すべて、$false はフォルダ直下のファイルだけを外す
    param (
        [string]$path = ${settingsFile}
    )

    $result = New-Object System.Collections.Generic.List[object]
    foreach ($item in @((readSettings $path).searchExcludes)) {
        $folder = ([string]$item.path).Trim().TrimEnd("\")
        if ($folder -eq "") {
            continue
        }
        $subfolders = if ($null -eq $item.subfolders) { $true } else { toSettingBool $item.subfolders $true }
        $result.Add([pscustomobject]@{ Path = $folder; Subfolders = $subfolders })
    }
    return $result.ToArray()
}

function writeSearchExcludes {
    # 検索対象ツリーでチェックを外したフォルダ（@{ Path; Subfolders } の配列）を保存する
    param (
        [object[]]$excludes,
        [string]$path = ${settingsFile}
    )

    updateSettings "searchExcludes" ([object[]]@($excludes | Where-Object { $_ -and $_.Path } | ForEach-Object {
        [ordered]@{ path = [string]$_.Path; subfolders = [bool]$_.Subfolders }
    })) $path
}

function removeSearchExcludesUnder {
    # 検索対象ツリーでチェックを外した記録のうち、folder（インデックスのフォルダ）とその下のものを消す（比較は testFolderOrUnder）。
    # 記録は利便性のための一時的な情報のため、消せなくても例外にしない（インデックスの改名・削除は止めない）。
    # 消す記録が無ければ設定ファイルは書き換えない
    param (
        [string]$folder,
        [string]$path = ${settingsFile}
    )

    $folder = ([string]$folder).Trim().TrimEnd("\")
    if ($folder -eq "") {
        return
    }

    try {
        invokeSettingsLocked -path $path -action {
            $excludes = @(readSearchExcludes $path)
            $kept = @($excludes | Where-Object { -not (testFolderOrUnder $_.Path $folder) })
            if ($kept.Count -lt $excludes.Count) {
                writeSearchExcludes $kept $path
            }
        } | Out-Null
    } catch {
    }
}

function moveSearchExcludes {
    # 検索対象ツリーでチェックを外したフォルダ（searchExcludes。インデックスの下のフルパス）のうち、
    # ワークスペース from の index の下のものを、to の index の下に付け替えて保存する。付け替えた数を返す
    param (
        [string]$from,
        [string]$to,
        [string]$path = ${settingsFile}
    )

    $fromIndex = ([Workspace]::new($from.TrimEnd("\"))).IndexDir
    $toIndex = ([Workspace]::new($to.TrimEnd("\"))).IndexDir
    return invokeSettingsLocked -path $path -action {
        $count = 0
        $excludes = @(readSearchExcludes $path | ForEach-Object {
            $folder = $_.Path
            if (testFolderOrUnder $folder $fromIndex) {
                $folder = $toIndex + $folder.Substring($fromIndex.Length)
                $count++
            }
            [pscustomobject]@{ Path = $folder; Subfolders = $_.Subfolders }
        })
        if ($count -gt 0) {
            writeSearchExcludes $excludes $path
        }
        return $count
    }
}

# ワークスペース（インデックス・取り込み一覧・ログを置くフォルダ）の中の、tebunko が使うファイルの場所。
# 場所はフォルダ（Dir）から組み立てるだけで、設定は読まない。どのフォルダを使うかは設定の workspaceFolder で決まる（settings.ps1 の getWorkDir）。
# 今のワークスペースは paths.ps1 の ${workspace} に置く。別のスレッドへは Dir（文字列）を渡し、そこで作り直す。
# Workspace のメソッドは場所を組み立てるだけなので、.NET の型だけを使う（クラスのメソッドからスクリプトの関数は呼べるが、
# $script: 変数は呼び出し元によって見える範囲が違うため、クラスの本体では読まない。docs/design/structure/classes.md）

class Workspace {
    [string]$Dir
    [string]$IndexDir
    # 前の版（content_index・system_index に名前をそろえる前）が使っていた本文インデックスのフォルダ。
    # 新しい版はここを読まず、消しもしない（前の版のしるしの調べ・知らせ・［設定］で「移す」「消して最初から」の対象にするために持つ）
    [string]$LegacyIndexDir
    # システムインデックス（本文インデックスの 2-gram を書いた txt。index と同じ相対パスの構成。Windows Search に索引させる）と、その状態
    [string]$SystemIndexDir
    [string]$SystemIndexStateFile
    # 取り込んだTSVをインデックスに入れる直前に集めるフォルダ（publishIndexFiles）。
    # フォルダごと入れ替えるため、インデックスと同じドライブ（ワークスペースの中）に置く。
    # 検索対象に入らないよう index の外にする。インデックス作成を同時に複数実行しても混ざらないよう、プロセスごとに分ける
    [string]$PublishDir
    # 取り込み一覧・出力（自動生成）
    [string]$StatusFile
    [string]$IngestingFile  # 取り込み中のファイル。強制終了で残っていれば、そのファイルの取り込み中に止まった
    [string]$ResultFile
    # インデックス作成の記録。画面とインデクサの受け渡しはメモリ上で行う（indexer_state.ps1 の newIndexerChannel）
    [string]$IndexingLogFile  # インデクサの表示内容の記録（実行ごとに上書き）
    [string]$GuiErrorLogFile  # 画面で起きた予期しないエラーの記録（追記。原因を後から追えるようにする。1 MB で下の前回の分に回す）
    [string]$IndexingLogPreviousFile  # 前回のインデックス作成の記録（インデックス作成を始めるとき、今の記録をここへ移す）
    [string]$GuiErrorLogPreviousFile  # 画面エラーの記録の前回の分（1 MB を超えたとき、今の記録をここへ移す）
    # 取り込みの作業フォルダの置き場所（下は <PC の鍵>\<PID>\w<番号> と分かれる。selectTmpDir・getWorkspaceTmpDir）。
    # 前の版までの %TEMP%\tebunko\<PID> の代わりに、ワークスペースの中に置く（共有フォルダでも 1 か所にまとまる）
    [string]$TmpRoot
    # このツールが起動した Office の PID の記録の置き場所（下は <PC の鍵>\<PID>.txt と分かれる。getOfficePidDir・shared/office/office_process.ps1）。
    # 画面を起動したとき、前回残った Office を確認して止めるために使う。tmp の下には置かない（tmp は片付けで消える場所で、記録は画面ごと落ちた後に読むため）
    [string]$OfficePidRoot

    Workspace([string]$dir) {
        $this.Dir = $dir
        $this.IndexDir = "$dir\content_index"
        $this.LegacyIndexDir = "$dir\index"
        $this.SystemIndexDir = "$dir\system_index"
        $this.SystemIndexStateFile = "$dir\system_index_state.tsv"
        $this.PublishDir = "$dir\publish\$([System.Diagnostics.Process]::GetCurrentProcess().Id)"
        $this.StatusFile = "$dir\ingest_status.tsv"
        $this.IngestingFile = "$dir\ingesting.txt"
        $this.ResultFile = "$dir\search_results.txt"
        $this.IndexingLogFile = "$dir\indexing_log.txt"
        $this.GuiErrorLogFile = "$dir\gui_error_log.txt"
        $this.IndexingLogPreviousFile = "$dir\indexing_log_previous.txt"
        $this.GuiErrorLogPreviousFile = "$dir\gui_error_log_previous.txt"
        $this.TmpRoot = "$dir\tmp"
        $this.OfficePidRoot = "$dir\office_pids"
    }

    # ワークスペースを移すときに移すもの（tebunko が作るファイル・フォルダ）。利用者のほかのファイルは含めない。
    # 取り込みの出力（publish）はプロセスごとのフォルダ（PublishDir）の親を移す。
    # LegacyIndexDir は、あれば前の版のワークスペースとして tebunko のものと扱う（あるものだけが WorkspaceMover.ListEntries で拾われる）
    [string[]] Entries() {
        return @($this.IndexDir, $this.LegacyIndexDir, $this.SystemIndexDir, $this.SystemIndexStateFile, $this.StatusFile, $this.IngestingFile,
            $this.ResultFile, $this.IndexingLogFile, $this.GuiErrorLogFile,
            $this.IndexingLogPreviousFile, $this.GuiErrorLogPreviousFile, [System.IO.Path]::GetDirectoryName($this.PublishDir), $this.TmpRoot, $this.OfficePidRoot)
    }
}

# 前の版（content_index・system_index に名前をそろえる前）が system_index に置いていた txt の名前の型。
# 新しい版は system_index.txt を使うため、前の版の txt を見つける・片付けるためだけに使う（読み書きの形式は変えない）
${legacySystemIndexPattern} = "システムインデックス*.txt"

function getMachineKey {
    # この PC を識別する短い鍵（getFolderKey の先頭 8 文字）。
    # 共有フォルダのワークスペースを複数の PC から使うとき、一時フォルダを PC ごとに分けるために使う（getWorkspaceTmpDir）
    return (getFolderKey ([Environment]::MachineName)).Substring(0, 8)
}

function getOfficePidDir {
    # 起動した Office の PID の記録を置くフォルダ（$workspace.OfficePidRoot\<PC の鍵>）を返す。文字列を組み立てるだけで、ファイルには触らない。
    # 共有のワークスペースで、ほかの PC の PID と混ざらないよう PC ごとに分ける
    param (
        [Workspace]$workspace
    )

    return Join-Path $workspace.OfficePidRoot (getMachineKey)
}

function getWorkspaceJobQueue {
    # ネットワークの場所に触るかもしれない startJob の列を決める唯一の関数。
    # paths（ワークスペース・インデックスのフォルダ・元のフォルダ・記録の置き場所など）の中に 1 つでもネットワークの場所があれば、
    # 届かない共有で待たされても他の仕事を巻き込まない専用の列（"network"）、無ければ既定の列（"default"）
    param (
        [string[]]$paths
    )

    return $(if (testAnyNetworkPath $paths) { "network" } else { "default" })
}

function assertWorkspaceReachable {
    # インデックスの削除・名前の変更の裏の仕事の先頭で呼ぶ。ワークスペース（のインデックスのフォルダ）に届かないとき、
    # 例外にする（届かないのに「何もせず成功」にして、設定だけ変えてしまわないため）。無いこと（まだインデックスを作っていない）は例外にしない
    param (
        [string]$dir
    )

    $state = getPathState $dir
    if ($state.State -eq ${pathStateUnreachable}) {
        throw "ワークスペースに接続できません：${dir}"
    }
    if ($state.State -eq ${pathStateOther}) {
        throw "ワークスペースを確かめられません：$($state.Message)"
    }
}

function getWorkspaceTmpDir {
    # 取り込みの作業フォルダの候補（$workspace.TmpRoot\<PC の鍵>\<PID>）を返す。副作用は無い（selectTmpDir が使う）
    param (
        [Workspace]$workspace
    )

    return Join-Path $workspace.TmpRoot (Join-Path (getMachineKey) $PID)
}

function selectTmpDir {
    # 取り込みの作業フォルダの置き場所を決める: @{ Dir; Reason（置けないときだけ） }
    #   候補: getWorkspaceTmpDir（ワークスペースの tmp\ の下）
    #   候補のパスに [ ] があれば、置けない（Dir = ""、Reason = Brackets）。Excel は [ ] を含むパスに保存できないため
    #   候補の長さ + 取り込みのスレッドが下に作る最も長い名前の分（${tmpNameReserve}）が $excelMaxPath 以上でも、
    #     置けない（Dir = ""、Reason = TooLong）。Office は長すぎるパスを開けないため
    #   一時ファイルもワークスペースの下にしか置かない（%TEMP% には逃がさない）。
    #   置けないときは、呼び出し側（initTmpDir）が取り込みをすべてスキップする
    #   （どのファイルも中間 TSV などをこのフォルダに作るため、テキストファイルを含めすべての取り込みが対象になる）
    #   どちらでもなければ候補のまま（Reason = ""）
    param (
        [Workspace]$workspace
    )

    $candidate = getWorkspaceTmpDir $workspace
    if ($candidate.IndexOfAny([char[]]@("[", "]")) -ge 0) {
        return @{ Dir = ""; Reason = "Brackets" }
    }
    if (($candidate.Length + ${tmpNameReserve}) -ge $excelMaxPath) {
        return @{ Dir = ""; Reason = "TooLong" }
    }
    return @{ Dir = $candidate; Reason = "" }
}

function getTmpDirUnavailableMessage {
    # 取り込みの作業フォルダを置けない理由（selectTmpDir の Reason）を、利用者向けの1文にする。
    # initTmpDir のログと、invokeIngestTask が1ファイルごとに書くエラーの両方で使う
    param (
        [string]$reason
    )

    if ($reason -eq "Brackets") {
        return "ワークスペースのパスに [ ]（角かっこ）が含まれるため、更新の作業フォルダを置けません。"
    }
    if ($reason -eq "TooLong") {
        return "ワークスペースのパスが長すぎるため、更新の作業フォルダを置けません。"
    }
    if ($reason -eq "Link") {
        return "ワークスペースの作業領域の途中にリンク（ジャンクション・シンボリックリンク）があるため、更新の作業フォルダを置けません。"
    }
    return "更新の作業フォルダを置けません。"
}

function getLegacyIndexState {
    # 前の版のワークスペース（dir）の状態を返す: @{ HasLegacyIndex; ContentEmpty; HasLegacySystemIndex }
    #   HasLegacyIndex       : 前の版の index\ があり、直下のどれかのフォルダに legacySourceFolderFileName（元のフォルダ.txt）がある（前の版のしるし）。
    #                          index\ があるだけでは、利用者が選んだフォルダにたまたま index があるときと区別できないため、しるしとしない
    #   ContentEmpty         : content_index\ が無いか、下のフォルダを含めてファイルが 1 つも無い
    #   HasLegacySystemIndex : system_index\ の下に前の名前の txt（システムインデックス*.txt）がある。
    #                          ContentEmpty のときだけ調べる（片付けの条件にしか使わないため）
    param (
        [string]$dir
    )

    $ws = [Workspace]::new($dir)
    # 見つけたところで列挙をやめるため、testAnyEntry で調べる（foreach を break で抜けると、調べていたフォルダを
    # 掴んだまま残り、続くインポートの上書きで content_index\<名前> を移動できなくなる）
    $hasLegacyIndex = $false
    $longLegacy = toLongPath $ws.LegacyIndexDir
    if ([System.IO.Directory]::Exists($longLegacy)) {
        $hasLegacyIndex = testAnyEntry ([System.IO.Directory]::EnumerateDirectories($longLegacy)) {
            param ($sub)
            [System.IO.File]::Exists("$sub\${legacySourceFolderFileName}")
        }
    }

    $contentEmpty = $true
    $longContent = toLongPath $ws.IndexDir
    if ([System.IO.Directory]::Exists($longContent)) {
        $contentEmpty = !(testAnyEntry ([System.IO.Directory]::EnumerateFiles($longContent, "*", [System.IO.SearchOption]::AllDirectories)))
    }

    $hasLegacySystemIndex = $false
    if ($contentEmpty) {
        $longSystem = toLongPath $ws.SystemIndexDir
        if ([System.IO.Directory]::Exists($longSystem)) {
            $hasLegacySystemIndex = testAnyEntry ([System.IO.Directory]::EnumerateFiles($longSystem, ${legacySystemIndexPattern}, [System.IO.SearchOption]::AllDirectories))
        }
    }

    return @{ HasLegacyIndex = $hasLegacyIndex; ContentEmpty = $contentEmpty; HasLegacySystemIndex = $hasLegacySystemIndex }
}

function testLegacyCleanupNeeded {
    # 取り込み直しを始めるときに、前の版のシステムインデックスを片付けるかどうか（getLegacyIndexState の結果から決まる）。
    # content_index\ が空で、かつ、前の版のしるしがあるか、system_index\ に前の名前の txt が残っているときに片付ける
    # （取り込み直す前に利用者が index\ を消していても、前の名前の txt を残さないため）
    param (
        $state
    )

    return ($state.ContentEmpty -and ($state.HasLegacyIndex -or $state.HasLegacySystemIndex))
}

function getLegacyIndexMessage {
    # 前の版のワークスペース（index\。しるしあり）が見つかったときの知らせ。しるしが無ければ空
    param (
        [string]$dir,
        [bool]$hasLegacyIndex
    )

    if (!$hasLegacyIndex) {
        return ""
    }
    $legacyDir = [Workspace]::new($dir).LegacyIndexDir
    return "前の版のインデックス（「${legacyDir}」）は、この版では使えません。［すべて更新］で、元のファイルをすべて更新し直します。" +
        "更新し直した後、「${legacyDir}」フォルダは削除してかまいません。"
}

function clearLegacySystemIndex {
    # 前の版のシステムインデックス（system_index\ と、システムインデックスの状態ファイルの中身）を片付ける: @{ Ok; Reason（失敗のときだけ） }
    # 片付けの順番: (1) updateSystemIndexState の排他の中で、状態ファイルの中身を空にする（ファイルは消さない。
    #     画面の検索（fast_search.ps1）やインデックスの削除（index_store.ps1）が同じ排他で書き換えるため、
    #     消した直後に前のキーを書き戻されないようにする）。
    # (2) system_index\ を removeDirectoryRetry で消す（Windows Search が txt を一時的に開くことがあるため）。
    # どちらかに失敗したら Ok = $false（途中で止まっても、次に呼べば同じ状態から続けられる）
    param (
        [string]$dir
    )

    $ws = [Workspace]::new($dir)
    $cleared = updateSystemIndexState {
        param ($state)
        $state.Covered.Clear()
        $state.Pending.Clear()
        $state.Excluded.Clear()
    } $ws.SystemIndexStateFile
    if (!$cleared) {
        return @{ Ok = $false; Reason = "システムインデックスの状態ファイル（$([System.IO.Path]::GetFileName($ws.SystemIndexStateFile))）を開けませんでした" }
    }
    try {
        removeDirectoryRetry $ws.SystemIndexDir
    } catch {
        return @{ Ok = $false; Reason = $_.Exception.Message }
    }
    return @{ Ok = $true; Reason = "" }
}

function newWorkspace {
    # ワークスペースの場所（Dir。文字列）から Workspace を作る。クラスの本体は別のクラスの型を書かないため、クラスから作るときはこれを呼ぶ
    param (
        [string]$dir
    )

    return [Workspace]::new($dir)
}

# ワークスペースの切り替え（中身を移す・消して最初からやり直す・選んだ先のインデックスを使う・searchExcludes の付け替え・保存・失敗したら戻す）。
# 画面（ui\settings\settings.ps1 の applyWorkspace・startWorkspaceMove）は、確かめて利用者に選ばせたあと ChangeWorkspace を呼び、結果を出して画面を切り替えるだけにする。
# ListEntries などの確かめは画面のスレッドで、ChangeWorkspace は裏のスレッド（startWorkspaceMove の startJob）で使う。切り替えの前に、画面は本文インデックスのファイルを読んでいる検索を止める（移せないため）。
#
# クラスの本体では $script: 変数・ほかのクラスの型・呼び出し元の変数を使わない（docs/design/structure/classes.md）。
# 設定ファイルの場所はコンストラクタで受け取る。ワークスペースの中の場所は Workspace（workspace.ps1）から組み立てる。
# searchExcludes の付け替えは、IndexCatalog と同じ部品（search_excludes.ps1 の moveSearchExcludes）を通す。
# メソッドの中のローカル変数は、プロパティと大文字・小文字だけの違いにしない
class WorkspaceMover {
    hidden [string]$SettingsPath

    WorkspaceMover([string]$settingsPath) {
        $this.SettingsPath = $settingsPath
    }

    [string[]] ListEntries([string]$dir) {
        # ワークスペース dir にある、tebunko のファイル・フォルダ（Workspace.Entries のうち、あるもの）のフルパスを返す
        return @((newWorkspace $dir).Entries() | Where-Object {
            $long = toLongPath $_
            [System.IO.Directory]::Exists($long) -or [System.IO.File]::Exists($long)
        })
    }

    [string[]] Conflicts([string]$from, [string]$to) {
        # ワークスペース from の中身を to へ移すとき、to に同じ名前が既にあるもの（移せないもの）の名前を返す
        return @($this.ListEntries($from) | ForEach-Object { [System.IO.Path]::GetFileName($_) } | Where-Object {
            $long = toLongPath (Join-Path $to $_)
            [System.IO.Directory]::Exists($long) -or [System.IO.File]::Exists($long)
        })
    }

    [hashtable] ChangeWorkspace([string]$mode, [string]$from, [string]$to) {
        # ワークスペースを from から to に変える（設定に保存する）。mode:
        #   "use"   … to にあるインデックスを使う。from の中身は移さず、インデックスの一覧を to のものにする
        #   "move"  … from の中身を to へ移す
        #   "reset" … to の tebunko のファイル・フォルダを消してから、from の中身を移す
        # 戻り値: @{ Ok; Stage（失敗した段階。"remove"・"move"）; Message（失敗の理由）; Targets（"use" で使うインデックスの数）; Count（"move"・"reset" で移した数）}。
        # 失敗したときは設定を変えない（移せなかったら、移した分は from に戻してある）
        if ($mode -eq "use") {
            # 共有されたワークスペースなどを使う。今の中身は移さず、インデックスの一覧をこのワークスペースのものにする
            $targets = $this.UseTargets($to)
            writeWorkspaceFolder $to $this.SettingsPath
            return @{ Ok = $true; Stage = ""; Message = ""; Targets = $targets; Count = 0 }
        }
        if ($mode -eq "reset") {
            try {
                [void]$this.RemoveEntries($to)
            } catch {
                return @{ Ok = $false; Stage = "remove"; Message = $_.Exception.Message; Targets = 0; Count = 0 }
            }
        }
        try {
            $count = $this.MoveEntries($from, $to)
        } catch {
            return @{ Ok = $false; Stage = "move"; Message = $_.Exception.Message; Targets = 0; Count = 0 }
        }
        # 検索対象ツリーでチェックを外したフォルダも、移した先のインデックスに付け替える
        [void](moveSearchExcludes $from $to $this.SettingsPath)
        writeWorkspaceFolder $to $this.SettingsPath
        return @{ Ok = $true; Stage = ""; Message = ""; Targets = 0; Count = $count }
    }

    [int] MoveEntries([string]$from, [string]$to) {
        # ワークスペース from の中身（tebunko のファイル・フォルダ）を to へ移し、移した数を返す。ほかのファイルは移さない。
        # to に同じ名前があれば、何も移さずに例外にする。途中で移せなかったら、移した分を from へ戻してから例外にする
        # （どちらかのワークスペースに中身がそろった状態にし、半分ずつに分かれたままにしない）
        $conflicts = @($this.Conflicts($from, $to))
        if ($conflicts.Count -gt 0) {
            throw "「${to}」には、すでに $($conflicts -join '、') があります。空のフォルダを選んでください。"
        }
        $entries = @($this.ListEntries($from))
        [System.IO.Directory]::CreateDirectory((toLongPath $to)) | Out-Null
        $moved = New-Object System.Collections.Generic.List[string]
        try {
            foreach ($source in $entries) {
                $this.MoveEntry($source, (Join-Path $to ([System.IO.Path]::GetFileName($source))))
                $moved.Add($source)
            }
        } catch {
            $reason = $_.Exception.Message
            for ($i = $moved.Count - 1; $i -ge 0; $i--) {
                try {
                    $this.MoveEntry((Join-Path $to ([System.IO.Path]::GetFileName($moved[$i]))), $moved[$i])
                } catch {
                    # 戻せなかったものは、移した先に残る（例外のメッセージで両方の場所を伝える）
                }
            }
            throw "ワークスペースの中身を「${to}」へ移せませんでした（${reason}）。ファイルを開いているアプリを閉じてから、もう一度変えてください。中身は「${from}」に残しています。"
        }
        return $moved.Count
    }

    [int] RemoveEntries([string]$dir) {
        # ワークスペース dir の tebunko のファイル・フォルダ（Workspace.Entries）を削除し、削除した数を返す。ほかのファイルは消さない。
        # ワークスペースに選んだフォルダのインデックスを使わず、消して最初からやり直すときに使う
        $entries = @($this.ListEntries($dir))
        foreach ($entry in $entries) {
            $long = toLongPath $entry
            if ([System.IO.Directory]::Exists($long)) {
                removeDirectoryRetry $entry
            } else {
                [System.IO.File]::Delete($long)
            }
        }
        return $entries.Count
    }

    [int] UseTargets([string]$dir) {
        # ワークスペース dir の取り込み一覧にあるクロール対象フォルダを、インデックスの一覧（設定の targetFolders）にし、その数を返す。
        # ほかの人が作ったワークスペースを使うとき、一覧をそのワークスペースに合わせる（合わせないままインデックス作成をすると、
        # 一覧に無いインデックスは、インデックス更新の確認に「削除予定」として出る。findDroppedIndexes）。取り込み一覧が無ければ一覧は変えない
        $map = getIndexNameMap (newWorkspace $dir.TrimEnd("\")).StatusFile
        if ($map.Count -eq 0) {
            return 0
        }
        writeTargetFolders @($map.Keys | ForEach-Object { [pscustomobject]@{ Name = $_; Path = $map[$_]; Enabled = $true } }) $this.SettingsPath
        return $map.Count
    }

    hidden [void] MoveEntry([string]$source, [string]$dest) {
        # ファイル・フォルダを 1 つ移す。同じドライブならそのまま移し、別のドライブのフォルダは写してから元を消す
        # （Directory.Move は別のドライブへ移せないため）。写している途中で失敗したら、写した分を消して例外にする
        $longSource = toLongPath $source
        $longDest = toLongPath $dest
        if (![System.IO.Directory]::Exists($longSource)) {
            # File.Move は別のドライブへも移せる
            [System.IO.File]::Move($longSource, $longDest)
            return
        }
        if ([System.IO.Path]::GetPathRoot($source) -eq [System.IO.Path]::GetPathRoot($dest)) {
            [System.IO.Directory]::Move($longSource, $longDest)
            return
        }
        try {
            $this.CopyTree($longSource, $longDest)
        } catch {
            removeDirectoryRetry $dest
            throw
        }
        removeDirectoryRetry $source
    }

    hidden [void] CopyTree([string]$source, [string]$dest) {
        # フォルダを中身ごと写す（\\?\ 付きのパスを受け取る）
        [System.IO.Directory]::CreateDirectory($dest) | Out-Null
        foreach ($file in [System.IO.Directory]::GetFiles($source)) {
            [System.IO.File]::Copy($file, [System.IO.Path]::Combine($dest, [System.IO.Path]::GetFileName($file)))
        }
        foreach ($sub in [System.IO.Directory]::GetDirectories($source)) {
            $this.CopyTree($sub, [System.IO.Path]::Combine($dest, [System.IO.Path]::GetFileName($sub)))
        }
    }
}

# ［新規で開く］のためのコピー（テキスト・PDF など、「新規」の開き方が無い種類のファイル）の作成と片付け（状態層）。
# コピーは $workspace.TmpRoot\<PC の鍵>\open_copy\<12 桁の文字>\<元の名前>（コピー yyyyMMdd-HHmm）.<拡張子> に置く（getOpenCopyDir・getOpenCopyName）。
# 片付けは GUI の起動時にだけ行い、1 日より古いものを消す（開いているコピーは消せずに残る。閉じるときには消さない）。
# 作る・消すときは、置き場所がワークスペースの TmpRoot\<PC の鍵>\open_copy そのものであり、リンク（ジャンクション・シンボリックリンク）で
# 外へつながっていないことを確かめてから行う（testOpenCopyDir）。

# open_copy の置き場所の名前（片付けが、消してよい場所かを見るときにも使う）
${openCopyDirName} = "open_copy"
# 開くためのコピーを残す日数（これより古いものを起動時に消す）
${openCopyKeepDays} = 1

function getOpenCopyDir {
    # 開くためのコピーを置くフォルダ（$workspace.TmpRoot\<PC の鍵>\open_copy）を返す。文字列を組み立てるだけで、ファイルには触らない。
    # 取り込みの作業フォルダ（<PC の鍵>\<PID>）と同じ親の下に置くが、名前が数字でないため、取り込みの片付け（removeStaleProcessDirs）は触らない
    param (
        [Workspace]$workspace
    )

    return Join-Path $workspace.TmpRoot (Join-Path (getMachineKey) ${openCopyDirName})
}

function testOpenCopyReparsePoint {
    # path がリンク（ReparsePoint）か。無いパスは $false（まだ作っていない）。属性が読めないなど、確かめられないときは $true（辿らない側に倒す）
    param (
        [string]$path
    )

    try {
        $attributes = [System.IO.File]::GetAttributes((toLongPath $path))
    } catch [System.IO.FileNotFoundException] {
        return $false
    } catch [System.IO.DirectoryNotFoundException] {
        return $false
    } catch {
        return $true
    }
    return [bool]($attributes -band [System.IO.FileAttributes]::ReparsePoint)
}

function testOpenCopyDir {
    # copyDir が、open_copy の置き場所として使ってよいものか。コピーの作成・片付けは、これが真のときだけ行う。
    #   絶対パス（ドライブ付き・UNC）で、途中に .. や余計な区切りを含まず、tmpRoot\<PC の鍵>\open_copy と一致すること
    #   copyDir・その親（<PC の鍵>）・その親（tmpRoot）が、リンク（ReparsePoint）でないこと（まだ無ければ問題にしない）
    # 空・ドライブの直下・相対パス・別の場所の open_copy・リンクの先は $false
    param (
        [string]$copyDir,
        [string]$tmpRoot
    )

    if (!$copyDir -or !$copyDir.Trim() -or !$tmpRoot -or !$tmpRoot.Trim()) {
        return $false
    }
    $trimmed = $copyDir.TrimEnd([char]92, [char]47)
    if ($trimmed -notmatch '^([A-Za-z]:\\|\\\\[^\\])' -or $tmpRoot -notmatch '^([A-Za-z]:\\|\\\\[^\\])') {
        return $false
    }
    try {
        $full = [System.IO.Path]::GetFullPath($trimmed)
        $expected = [System.IO.Path]::GetFullPath((Join-Path (Join-Path $tmpRoot (getMachineKey)) ${openCopyDirName}))
    } catch {
        return $false
    }
    if (![string]::Equals($trimmed, $full, [System.StringComparison]::OrdinalIgnoreCase) -or
        ![string]::Equals($full, $expected.TrimEnd([char]92), [System.StringComparison]::OrdinalIgnoreCase)) {
        return $false
    }
    $keyDir = [System.IO.Path]::GetDirectoryName($full)
    foreach ($checked in @($full, $keyDir, [System.IO.Path]::GetDirectoryName($keyDir))) {
        if (testOpenCopyReparsePoint $checked) {
            return $false
        }
    }
    return $true
}

function getOpenCopyName {
    # 開くためのコピーの名前 <元の名前>（コピー yyyyMMdd-HHmm）.<拡張子>（コピーだと分かる名前にする）。
    # パスの区切りが紛れていても、ファイル名だけを使う。名前が空なら空文字。
    # 同じ名前のコピーが重ならないよう、置く場所は copySourceForOpen が 1 回ごとに別のフォルダにする
    param (
        [string]$book,
        [datetime]$now = (Get-Date)
    )

    $leaf = [System.IO.Path]::GetFileName(([string]$book).TrimEnd('.', ' ').Replace("/", "\"))
    if (!$leaf) {
        return ""
    }
    $extension = [System.IO.Path]::GetExtension($leaf)
    $baseName = $leaf.Substring(0, $leaf.Length - $extension.Length)
    $stamp = $now.ToString("yyyyMMdd-HHmm", [System.Globalization.CultureInfo]::InvariantCulture)
    return "${baseName}（コピー ${stamp}）${extension}"
}

function getOpenCopyBlocker {
    # コピーを作らずに断る理由（ファイルには触らない）。作れるなら空文字。
    #   NoName  … 名前が空
    #   TooLong … コピーのパスが長すぎる（260 文字の制限）
    # 名前に [ ] を含んでも断らない（コピーも開くのも、パスをそのまま（リテラルで）扱う）
    param (
        [string]$book,
        [string]$copyDir,
        [datetime]$now = (Get-Date)
    )

    $name = getOpenCopyName $book $now
    if (!$name) {
        return "NoName"
    }
    # <copyDir>\<12 桁>\<名前>
    if ($copyDir.TrimEnd([char]92).Length + 1 + 12 + 1 + $name.Length -ge 259) {
        return "TooLong"
    }
    return ""
}

function copySourceForOpen {
    # 元のファイルのコピーを copyDir の下に作る（元のファイルは変えない）。@{ Path; Reason } を返す。
    #   作れたとき: Path = コピーのパス、Reason = ""
    #   作れなかったとき: Path = ""、Reason = Place（置き場所の確かめで断った）・NoName／TooLong（getOpenCopyBlocker の結果）・Failed（作る・書くのに失敗した）
    # 同じ名前のコピーが重ならないよう、1 回ごとに別のフォルダ（copyDir\<12 桁の文字>）に置く。名前は getOpenCopyName。
    param (
        [string]$sourcePath,
        [string]$book,
        [string]$copyDir,
        [string]$tmpRoot,
        [datetime]$now = (Get-Date)
    )

    if (!(testOpenCopyDir $copyDir $tmpRoot)) {
        return @{ Path = ""; Reason = "Place" }
    }
    $blocker = getOpenCopyBlocker $book $copyDir $now
    if ($blocker) {
        return @{ Path = ""; Reason = $blocker }
    }
    $name = getOpenCopyName $book $now
    $dir = Join-Path $copyDir ([guid]::NewGuid().ToString("N").Substring(0, 12))
    $destPath = Join-Path $dir $name
    try {
        [System.IO.Directory]::CreateDirectory((toLongPath $dir)) | Out-Null
        copyFileShared $sourcePath $destPath
    } catch {
        return @{ Path = ""; Reason = "Failed" }
    }
    return @{ Path = $destPath; Reason = "" }
}

function getOpenCopyLatestTime {
    # 1 つ下のフォルダの「最後に使った日時」。フォルダの作成・更新と、中のファイルの更新のうち新しいもの
    # （編集して保存したコピーを、作ってから 1 日たったからといってすぐ消さないため）
    param (
        [System.IO.DirectoryInfo]$folder
    )

    $latest = $folder.CreationTime
    if ($folder.LastWriteTime -gt $latest) {
        $latest = $folder.LastWriteTime
    }
    foreach ($copy in @(Get-ChildItem -LiteralPath $folder.FullName -File -Force)) {
        if ($copy.LastWriteTime -gt $latest) {
            $latest = $copy.LastWriteTime
        }
    }
    return $latest
}

function clearOldOpenCopies {
    # copyDir の下の、最後に使ってから keepDays 日より古いコピー（1 つ下のフォルダごと）を消し、消したフォルダの数を返す。
    # 最後に使った日時は getOpenCopyLatestTime。現在より先の日時（時計のずれ）は新しい扱いになり、消さずに残る（消さない側に倒す）。
    # 消すのは open_copy の 1 つ下のフォルダの中のファイルだけ（testOpenCopyDir が偽なら何もしない。フォルダごとに消す直前にも確かめ、偽になっていればそこで止める）。
    # リンク（ジャンクション・シンボリックリンク）は辿らず、使用中で消せないコピーは残す。再帰の削除は使わない
    param (
        [string]$copyDir,
        [string]$tmpRoot,
        [datetime]$now = (Get-Date),
        [int]$keepDays = ${openCopyKeepDays}
    )

    if (!(testOpenCopyDir $copyDir $tmpRoot) -or !(Test-Path -LiteralPath $copyDir -PathType Container)) {
        return 0
    }
    $limit = $now.AddDays(-$keepDays)
    $prefix = $copyDir.TrimEnd([char]92) + "\"
    $cleared = 0
    foreach ($old in @(Get-ChildItem -LiteralPath $copyDir -Directory -Force)) {
        if ($old.Attributes -band [System.IO.FileAttributes]::ReparsePoint) {
            continue
        }
        if (!$old.FullName.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase) -or (getOpenCopyLatestTime $old) -ge $limit) {
            continue
        }
        # 確かめてから消すまでの間に置き場所がリンクに替わっていないか、フォルダごとに消す直前にもう一度確かめる
        if (!(testOpenCopyDir $copyDir $tmpRoot)) {
            break
        }
        # 消すフォルダ自身も、列挙してから消すまでの間にリンクに替わっていないかを確かめる（リンクなら辿らない）
        if (testOpenCopyReparsePoint $old.FullName) {
            continue
        }
        foreach ($copy in @(Get-ChildItem -LiteralPath $old.FullName -File -Force)) {
            if ($copy.Attributes -band [System.IO.FileAttributes]::ReparsePoint) {
                continue
            }
            try {
                [System.IO.File]::SetAttributes((toLongPath $copy.FullName), [System.IO.FileAttributes]::Normal)
                [System.IO.File]::Delete((toLongPath $copy.FullName))
            } catch {
                # 開いているコピーは残す（次の起動で消す）
            }
        }
        try {
            [System.IO.Directory]::Delete((toLongPath $old.FullName), $false)
            $cleared++
        } catch {
            # 中にコピーが残っている（開いている）・既に無い
        }
    }
    return $cleared
}

# 部品（lib・indexerLib）の読み込み先をまとめる。
# zip 版は scripts 配下の実際のファイルを dot-source し、単一 .ps1 版（展開せずに動く試験版）は
# 埋め込んだ部品の文字列（${bundledParts}）を関数（importTebunkoPart）としてランスペースに登録する。
# 設計は docs/design/structure/single-script.md・docs/design/structure/classes.md「クラスのつなぎ方」。
#
# 画面だけのクラス（SearchTarget・IndexNode など、ui\ 配下）は ${bundledParts} に含まれない。背景の
# スレッド・別のランスペースがこの部品だけを読み込んでも、画面のクラスを二重にコンパイルしない
# （PowerShell 5.1 は class を構文解析の時点でそのランスペースの型として登録するため、同じ名前の class を
# 別のランスペースでもう一度解析すると、型が別物になり画面のスレッドとキャストできなくなる）。
#
# 単一 .ps1 版かどうかは、先頭で定義する変数 ${bundledParts} の有無だけで決める
# （結合の道具 tools/new_single_script.ps1 が作る）。
# 別スレッド・別ランスペースで部品を読み込むところは、パスの文字列やソースを直接組み立てず、必ずここを通す。

function getPartLoad {
    # 戻り値は @{ State = <InitialSessionState>; Prelude = <部品を読み込む 1 行の文字列> }。
    # 呼び出し側は、この State でランスペース（または WorkerPool）を作り、Prelude を本体の前につないで
    # （shared\core\worker_pool.ps1 の joinWorkerScript）動かす。
    #
    # zip 版: State はただの既定値、Prelude はそのファイルを dot-source する 1 行。
    # 単一 .ps1 版: State に、埋め込んだ部品の文字列を本体に持つ関数 importTebunkoPart を登録し、
    #   Prelude はその関数を呼ぶだけの 1 行（". importTebunkoPart"）。関数の本体は、その State で
    #   ランスペースを作ったときに 1 回だけ構文解析される
    param (
        [ValidateSet("lib", "indexerLib")]
        [string]$name,
        # 部品を読み込んだあとに続けて呼ぶ文（例: initWorkspace）。空なら足さない
        [string]$then = ""
    )

    $state = [System.Management.Automation.Runspaces.InitialSessionState]::CreateDefault2()
    $bundled = Get-Variable -Name bundledParts -ErrorAction SilentlyContinue
    if ($null -ne $bundled -and $bundled.Value) {
        $body = $bundled.Value[$name]
        if ($null -eq $body) {
            throw "単一 .ps1 版に ${name} の部品が入っていません。"
        }
        $entry = New-Object System.Management.Automation.Runspaces.SessionStateFunctionEntry("importTebunkoPart", $body)
        $state.Commands.Add($entry)
        # 部品の中（version.ps1 の readVersionFile など）が ${bundledScriptPath}・${bundledVersion} を見るため、
        # 呼び出したスレッドの値をそのまま渡す（bundledParts も渡す。取り込みのスレッドの中でもう一度 getPartLoad を呼ぶため）
        foreach ($varName in "bundledParts", "bundledScriptPath", "bundledVersion") {
            $variable = Get-Variable -Name $varName -ErrorAction SilentlyContinue
            if ($null -ne $variable) {
                $variableEntry = New-Object System.Management.Automation.Runspaces.SessionStateVariableEntry($varName, $variable.Value, "")
                $state.Variables.Add($variableEntry)
            }
        }
        $prelude = ". importTebunkoPart"
        if ($then) { $prelude = "$prelude; $then" }
        return @{ State = $state; Prelude = $prelude }
    }

    # indexerLib は、取り込みのスレッド・インデクサの司令のスレッドの両方から使うため、
    # 関数（indexer_lib.ps1）と、呼び出す口（invokeIndexerMain・indexer_main.ps1）をまとめて読み込む
    $paths = switch ($name) {
        "lib" { @("$PSScriptRoot\..\lib.ps1") }
        "indexerLib" { @("$PSScriptRoot\..\indexer\indexer_lib.ps1", "$PSScriptRoot\..\indexer\indexer_main.ps1") }
    }
    $prelude = ($paths | ForEach-Object {
        # 一重引用符の文字（' と、PowerShell が同じ引用符として扱う U+2018・U+2019・U+201A・U+201B）は、重ねて文字列の中に入れる
        $resolved = [regex]::Replace([System.Management.Automation.WildcardPattern]::Escape([System.IO.Path]::GetFullPath($_).Replace('`', '``')), "(['\u2018\u2019\u201A\u201B])", '$1$1')
        ". '$resolved'"
    }) -join "; "
    if ($then) { $prelude = "$prelude; $then" }
    return @{ State = $state; Prelude = $prelude }
}

# tebunko が使うファイルの場所と、そこに書く値の定義。

# 取り込みの作業フォルダ（本体はワークスペースの tmp\ の下。index_migrate.ps1 の initTmpDir が
# インデックス作成の始めに selectTmpDir で決めて入れる）。決めるまでの既定値は空。
# 置けなかったとき（パスに [ ] がある・長すぎる）も空のまま（どのファイルも中間 TSV などをこのフォルダに作るため、
# テキストファイルを含めすべての取り込みをスキップする。%TEMP% には逃がさない）
${tmpDir} = ""
# ${tmpDir} を置けなかった理由（selectTmpDir の Reason）。置けたときは空
${tmpDirReason} = ""

# 前の版（%TEMP%\tebunko\<PID> に一時ファイルを置いていた版）が残した作業フォルダの片付け専用。
# 今の版はここには書き込まない（removeStaleTmpDirs が、強制終了などで残った前の版のフォルダを消すためだけに使う）
${legacyTmpParent} = Join-Path ([System.IO.Path]::GetTempPath()) "tebunko"

# Excelで開けるパスの長さの目安（古い版の上限）。作業フォルダの候補がこれ以上ならワークスペースの tmp\ を諦める
$excelMaxPath = 218
# 取り込みのスレッドが作業フォルダの下に作る、最も長いファイル名の分（"\w999\converted.pptx"）。
# selectTmpDir で、この分を足しても $excelMaxPath を超えないかを見る
${tmpNameReserve} = "\w999\converted.pptx".Length

# ワークスペース（インデックス・取り込み一覧・ログ・取り込みの出力の置き場所。中の場所は workspace.ps1 の Workspace）。
# setting.config の workspaceFolder で変えられる。空なら既定（settings.ps1 の getWorkDir）。
# 読み込んだとき（スクリプトの読み込み時）には決めず、起動口（startGui・invokeIndexerMain）が
# 壊れた設定ファイルの退避の後に呼ぶ（単一 .ps1 版は setting.config を読む前に読み込みだけ先に済ませるため）
function initWorkspace {
    ${script:workspace} = [Workspace]::new((getWorkDir))
}

# 取り込みのスレッドが、司令のスレッドから受け取った場所（Workspace）を、呼んだスクリプトのスコープに置く。
# $workspace を決めるのはこのファイルだけにするため、取り込みのスレッドのスクリプトからもここを呼ぶ
# （取り込みのスレッドでは、呼んだスコープは global。部品を読み込んだのと同じスコープになる）
function setCallerWorkspace {
    param (
        $value
    )

    Set-Variable -Name workspace -Value $value -Scope 1
}

# インデックスのフォルダに置く、インデックス名とクロール対象フォルダの対応（インデクサが作成する）。
# インデックスのフォルダごと別の場所・PCへコピーしても、検索結果から元のファイルの場所が分かるようにする。
# 拡張子を .tsv にすると検索対象になるため .txt にする
${sourceFolderFileName} = "source_folder.txt"

# 前の版(ワークスペースのファイル名を英語化する前)の元のフォルダの記録。
# getLegacyIndexState が旧版の index\ フォルダを見分けるためだけに使う。読み取り専用。
${legacySourceFolderFileName} = "元のフォルダ.txt"

# インデックス作成の進み具合の段階（writeIndexingProgress の phase）
${indexingPhaseCrawl}   = "クロール"  # 取り込み対象のファイルを探している（件数はまだ分からない）
${indexingPhaseConfirm} = "確認"      # 取り込み対象を数え終え、画面で取り込むかどうかを選ぶのを待っている
${indexingPhaseIngest}  = "取り込み"  # 1ファイルずつ取り込んでいる
${indexingPhaseFinish}  = "仕上げ"    # 後片付け（Officeアプリの終了・取り込み一覧の書き直し）

# 取り込み予定（newIngestPlanRow）の列と、インデックスごとの区分
${ingestPlanColumns} = @("インデックス名", "元のフォルダ", "区分", "ファイル数", "取り込み対象", "新規", "更新あり", "前回未完了", "インデックスなし", "前回失敗", "クラウド", "クラウド失敗", "クラウド容量", "クラウド失敗容量")
${planKindIngest}    = "取り込み"      # チェックが付いていて元のフォルダも見つかった（数えた結果を出す）
${planKindUnchecked} = "チェックなし"  # チェックが外れているため数えていない
${planKindMissing}   = "フォルダなし"  # 元のフォルダが見つからないため数えていない
${planKindDropped}   = "削除予定"      # 設定から外れたインデックス（確認で［更新を開始］が押されたときだけ消す）

# 取り込み一覧の列と状態
${statusColumns}   = @("相対パス", "更新日時", "サイズ", "状態", "TSV数", "取り込み日時", "エラー", "抽出版")
${statusFolderKey} = "クロール対象フォルダ"
${stateNew}    = "未取り込み"
${stateDone}   = "済"
${stateFailed} = "失敗"

# 取り込み一覧（status ファイル）の読み書き（状態層）。列と状態の定義は paths.ps1。

function newStatusRow {
    # 取り込み一覧の1行（1ファイル）を作る
    param (
        [string]$relPath,
        [string]$updated = "",
        [string]$size = "",
        [string]$state = ${stateNew},
        [string]$tsvCount = "",
        [string]$ingested = "",
        [string]$errorMessage = "",
        [string]$extractVersion = ""
    )

    return [pscustomobject]@{
        相対パス = $relPath
        更新日時 = $updated
        サイズ   = $size
        状態     = $state
        TSV数    = $tsvCount
        取り込み日時 = $ingested
        エラー   = $errorMessage
        抽出版   = $extractVersion
    }
}

# 1行1件を保つため、タブ・改行はスペースにする（この文字を含む値だけ置き換える）
${statusLineBreaks} = [char[]]@("`t", "`r", "`n")


function toStatusLine {
    # 取り込み一覧の1行を文字列にする（1件ずつの追記用。addStatusRow）。
    # エラーメッセージ等のタブ・改行は、1行1件を保つためスペースにする。
    # 数万行をまとめて書き出す writeStatusFile では、同じ整形をその場に展開している（関数の呼び出しだけで
    # 5万行あたり数秒かかるため）。整形を変えるときは両方を直す（テストで同じ結果になることを確かめている）
    param (
        $row
    )

    $errorText = [string]$row.エラー
    if ($errorText.IndexOfAny(${statusLineBreaks}) -ge 0) {
        $errorText = $errorText -replace "[\t\r\n]+", " "
    }
    return [string]::Join("`t", @(
        [string]$row.相対パス, [string]$row.更新日時, [string]$row.サイズ, [string]$row.状態,
        [string]$row.TSV数, [string]$row.取り込み日時, $errorText, [string]$row.抽出版))
}

function readStatusFile {
    # 取り込み一覧を読み込み、@{ Folders; Rows } を返す。ファイルが無ければ空。
    #   Folders: クロール対象フォルダ @{ Path; Name（インデックス名） } の配列
    #   Rows   : 相対パス（"インデックス名\フォルダからの相対パス"。大文字・小文字を区別しない）→ 行
    # インデックス作成中は1件ごとに行を追記するため、同じ相対パスの行は後の行を優先する。列数の合わない行（書き込み途中で中断した行など）は無視する
    param (
        [string]$path = $workspace.StatusFile
    )

    $rows = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
    $folders = New-Object System.Collections.Generic.List[object]
    $result = @{ Folders = $folders; Rows = $rows }
    if (!(Test-Path -LiteralPath $path)) {
        return $result
    }

    # インデックス作成中に画面などから読んでも、インデクサの追記・置き換えを妨げないよう共有を許して開く
    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $stream = New-Object System.IO.FileStream($path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    $reader = New-Object System.IO.StreamReader($stream, ${utf8Bom})
    try {
        $lines = $reader.ReadToEnd() -split "\r?\n"
    } finally {
        $reader.Dispose()
    }

    $columnCount = ${statusColumns}.Count
    foreach ($line in $lines) {
        $fields = $line.Split("`t")
        if ($fields[0] -eq ${statusFolderKey} -and $fields.Count -eq 3) {
            $folders.Add([pscustomobject]@{ Path = $fields[1]; Name = $fields[2] })
            continue
        }
        if ($fields.Count -ne $columnCount -or $fields[0] -eq "" -or $fields[0] -eq ${statusColumns}[0]) {
            continue
        }
        # 数万行を読むため、1行ごとの関数呼び出し（newStatusRow）は使わずにその場で作る（列は $statusColumns と同じ）
        $rows[$fields[0]] = [pscustomobject]@{
            相対パス = $fields[0]
            更新日時 = $fields[1]
            サイズ   = $fields[2]
            状態     = $fields[3]
            TSV数    = $fields[4]
            取り込み日時 = $fields[5]
            エラー   = $fields[6]
            抽出版   = $fields[7]
        }
    }
    return $result
}

function writeStatusFile {
    # 取り込み一覧を書き出す（1ファイル1行）。途中で中断しても壊れないよう、一時ファイルに書いてから置き換える
    #   folders: クロール対象フォルダ @{ Path; Name } の配列。"クロール対象フォルダ<TAB>パス<TAB>インデックス名" の行にする
    param (
        [object[]]$folders,
        [object[]]$rows,
        [string]$path = $workspace.StatusFile
    )

    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($folder in @($folders | Where-Object { $_ })) {
        $lines.Add("${statusFolderKey}`t$($folder.Path)`t$($folder.Name)")
    }
    $lines.Add((${statusColumns} -join "`t"))
    # 数万行を書き出すため、1行ごとの関数呼び出し（toStatusLine）・パイプライン（Where-Object）は使わない
    # （5万行で約 10 秒 → 約 0.2 秒。この間はインデックス作成の進み具合が止まって見えるため速くする）
    foreach ($row in $rows) {
        if ($null -eq $row) {
            continue
        }
        $errorText = [string]$row.エラー
        if ($errorText.IndexOfAny(${statusLineBreaks}) -ge 0) {
            $errorText = $errorText -replace "[\t\r\n]+", " "
        }
        $lines.Add([string]::Join("`t", @(
            [string]$row.相対パス, [string]$row.更新日時, [string]$row.サイズ, [string]$row.状態,
            [string]$row.TSV数, [string]$row.取り込み日時, $errorText, [string]$row.抽出版)))
    }

    writeTextLinesAtomic $path $lines
}

function getIndexNameMap {
    # 取り込み一覧に記録したインデックス名 → クロール対象フォルダのパス（大文字・小文字を区別しない）。
    # クロール対象フォルダの行は先頭にあるため、見出し行まで読んで打ち切る（取り込み一覧が大きくても時間がかからないように）
    param (
        [string]$path = $workspace.StatusFile
    )

    $map = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::OrdinalIgnoreCase)
    if (!(Test-Path -LiteralPath $path)) {
        return , $map
    }
    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $stream = New-Object System.IO.FileStream($path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    $reader = New-Object System.IO.StreamReader($stream, ${utf8Bom})
    try {
        $header = ${statusColumns} -join "`t"
        while ($null -ne ($line = $reader.ReadLine())) {
            if ($line -eq $header) {
                break
            }
            $fields = $line.Split("`t")
            if ($fields[0] -eq ${statusFolderKey} -and $fields.Count -eq 3 -and $fields[2]) {
                $map[$fields[2]] = $fields[1]
            }
        }
    } finally {
        $reader.Dispose()
    }
    return , $map
}

# インデックス名に対する元のフォルダを記録できるかの判断（判断層。ファイルに触らない）。

function testSourceNameRecordable {
    # インデックス名に対する元のフォルダを設定に記録できる名前か。空の名前と、前後に空白（全角空白・NBSP・タブを含む）がある名前は、
    # 設定を読み戻すとき前後の空白が削られて同じ名前にならない（確かめ済みにならない）ため記録しない。
    # 状態層（setIndexSourceFolder）の入口の条件と、画面の文言（記録されないときは毎回確かめる）で同じ判断を使う。
    # 文字数で比べる（-ne はカルチャに従う）
    param (
        [string]$name
    )

    $trimmed = $name.Trim()
    return $trimmed.Length -gt 0 -and $trimmed.Length -eq $name.Length
}

# インデックス名と TSV のファイル名の決め方（判断層。ファイルに触らない）。

function newIndexName {
    # クロール対象フォルダのインデックス名（work\index 直下のフォルダ名）を作る。
    # フォルダ名（ドライブ直下はドライブ名）を使い、usedNames と重複すれば「名前(2)」「名前(3)」…とする
    param (
        [string]$folderPath,
        $usedNames = $null  # HashSet[string]・配列・1 個の文字列・$null のいずれでもよい
    )

    $base = toSafeFileName (getFolderLeafName $folderPath)
    if ($base -eq "") {
        $base = "フォルダ"
    }

    # 呼び出し側から $null や文字列の配列で渡されても落ちないよう、ここで集合に直す（大文字・小文字は区別しない）
    $used = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    # 集合が 1 要素の配列に入って渡されても（@(関数) で受けた場合など）、中身を 1 つずつ取り出す
    foreach ($entry in @($usedNames)) {
        foreach ($usedName in @($entry)) {
            if ($usedName) {
                [void]$used.Add([string]$usedName)
            }
        }
    }

    $name = $base
    for ($i = 2; $used.Contains($name); $i++) {
        # 長いフォルダ名に (2) を付けるとファイル名の上限を超えてフォルダを作れないため、上限に収まるよう名前を切り詰める
        $suffix = "(${i})"
        $name = $base.Substring(0, [Math]::Min($base.Length, ${maxFileNameLength} - $suffix.Length)) + $suffix
    }
    return $name
}

function assignIndexNames {
    # クロール対象フォルダ（getTargetFolders）にインデックス名を割り当て、@{ Path; Enabled; Name } の配列を返す。
    # インデックス名は設定に持つ（getTargetFolders の Name）。フォルダの置き場所（Path）を書き換えても名前は変わらないため、
    # フォルダを移しても同じインデックスとして扱える（インデックスを作り直さない）。
    # 名前が無い場合（新しく追加したフォルダ）は、前回の取り込み一覧の同じパスの名前を使い、
    # それも無ければフォルダ名から重複しない名前を作る
    param (
        [object[]]$targetFolders,
        [object[]]$previousFolders  # readStatusFile の Folders（@{ Path; Name }）
    )

    $previousNames = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($folder in @($previousFolders | Where-Object { $_ -and $_.Name })) {
        $previousNames[$folder.Path] = $folder.Name
    }

    # 設定にある名前・前回の名前は使わない（別のフォルダに同じ名前を付けてインデックスを取り違えないため）
    $used = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($name in $previousNames.Values) {
        [void]$used.Add($name)
    }
    foreach ($folder in @($targetFolders | Where-Object { $_ -and $_.Name })) {
        [void]$used.Add($folder.Name)
    }

    $result = New-Object System.Collections.Generic.List[object]
    foreach ($folder in @($targetFolders | Where-Object { $_ })) {
        $name = [string]$folder.Name
        if ($name -eq "") {
            if ($previousNames.ContainsKey($folder.Path)) {
                $name = $previousNames[$folder.Path]
            } else {
                $name = newIndexName $folder.Path $used
            }
            [void]$used.Add($name)
        }
        $result.Add([pscustomobject]@{ Path = $folder.Path; Enabled = $folder.Enabled; Name = $name })
    }
    return $result.ToArray()
}

function splitIndexRelPath {
    # work\index からの相対パスを、先頭のインデックス名と残り（クロール対象フォルダからの相対パス）に分ける: @{ Name; Rest }
    # （String.Split([char], 2) は .NET Framework では Split(params char[]) になり、2 も区切り文字とみなされるため使わない）
    param (
        [string]$relPath
    )

    $i = $relPath.IndexOf("\")
    if ($i -lt 0) {
        return @{ Name = $relPath; Rest = "" }
    }
    return @{ Name = $relPath.Substring(0, $i); Rest = $relPath.Substring($i + 1) }
}


# Windows で使えないファイル名（インデックス名に使えるかの判定に使う）
${reservedFileNames} = @("CON", "PRN", "AUX", "NUL") +
    @(1..9 | ForEach-Object { "COM$_" }) + @(1..9 | ForEach-Object { "LPT$_" })


function testIndexName {
    # インデックス名（work\index 直下のフォルダ名）として使えるかを調べ、使えない理由を返す（使えれば空文字列）。
    #   usedNames: ほかのインデックスが使っている名前（大文字・小文字を区別しない）
    param (
        [string]$name,
        [object[]]$usedNames = @()
    )

    $name = [string]$name
    if ($name -eq "") {
        return "名前を入力してください。"
    }
    if ($name -ne $name.Trim()) {
        return "名前の前後に空白は使えません。"
    }
    if ($name.Length -gt ${maxFileNameLength}) {
        return "名前が長すぎます（${maxFileNameLength} 文字まで）。"
    }
    if (@([System.IO.Path]::GetInvalidFileNameChars() | Where-Object { $name.IndexOf($_) -ge 0 }).Count -gt 0) {
        return "名前に使えない文字が含まれています（\ / : * ? " + [char]34 + " < > | と制御文字）。"
    }
    if ($name.EndsWith(".")) {
        return "名前の最後に . は使えません。"
    }
    if (${reservedFileNames} -contains $name.Split(".")[0].ToUpperInvariant()) {
        return "「${name}」は Windows で使えない名前です。"
    }
    foreach ($used in @($usedNames)) {
        if ([string]::Equals([string]$used, $name, [System.StringComparison]::OrdinalIgnoreCase)) {
            return "「${name}」は、ほかのインデックスが使っています。別の名前を付けてください。"
        }
    }
    return ""
}

function encodeIndexPlace {
    # インデックスのTSVのファイル名に入れる場所（シート名・ページ・スライド）を符号化する。
    # ファイル名に使えない文字・制御文字と、_・符号化に使う % を "%XX"（16進数）にする（decodeIndexPlace で元に戻す）。
    #   ・全角に置き換えると `a"b` と `a”b` が同じファイル名になり、後のシートで上書きされるため、元に戻せる形にする
    param (
        [string]$place
    )

    return [regex]::Replace($place, '[\x00-\x1F"%*/:<>?\\_|]', { param($m) '%{0:X2}' -f [int][char]$m.Value })
}

function decodeIndexPlace {
    # encodeIndexPlace で符号化した場所を元に戻す（encodeIndexPlace が作る "%XX" だけを戻す）
    param (
        [string]$place
    )

    # 符号化した文字が無ければそのまま返す（検索のたびに全TSVの名前を分解するため、置換の呼び出しを省く）
    if ($place.IndexOf("%") -lt 0) {
        return $place
    }
    return [regex]::Replace($place, '%(?:[01][0-9A-F]|2[25AF]|3[ACEF]|5[CF]|7C)', { param($m) [string][char][Convert]::ToInt32($m.Value.Substring(1), 16) })
}

# 決まった場所（ページ・スライド・ヘッダー/フッター・脚注・文書・本文）は、ファイル名を ASCII の固定名にする。
# 符号化した場所（encodeIndexPlace）には "_" が出ないため（"_" は "%5F" にする）、固定名に "_" を使っても
# シート名由来のファイル名と重ならない（convertIndexFileNameToPlace で戻すときの手掛かりにする）。
function convertPlaceBaseToFixedFileName {
    # 場所の元の部分（種類を除いた部分）を、決まったASCIIのファイル名にする（当てはまらなければ空文字列）。
    #   数字はそのまま桁を写す（int にしない。"001" は "001" のまま）
    param (
        [string]$base
    )

    if ($base -match '^ページ(\d+)$') { return "page_$($Matches[1])" }
    if ($base -match '^スライド(\d+)（非表示）$') { return "slide_$($Matches[1])_hidden" }
    if ($base -match '^スライド(\d+)_ノート$') { return "slide_$($Matches[1])_notes" }
    if ($base -match '^スライド(\d+)$') { return "slide_$($Matches[1])" }
    if ($base -eq "ヘッダー・フッター") { return "header_footer" }
    if ($base -eq "脚注") { return "doc_footnotes" }
    if ($base -eq "文書") { return "doc_whole" }
    if ($base -eq "本文") { return "doc_body" }
    return ""
}

function convertFixedFileNameToPlaceBase {
    # convertPlaceBaseToFixedFileName の逆変換（当てはまらなければ空文字列）
    param (
        [string]$fileBase
    )

    if ($fileBase -match '^page_(\d+)$') { return "ページ$($Matches[1])" }
    if ($fileBase -match '^slide_(\d+)_hidden$') { return "スライド$($Matches[1])（非表示）" }
    if ($fileBase -match '^slide_(\d+)_notes$') { return "スライド$($Matches[1])_ノート" }
    if ($fileBase -match '^slide_(\d+)$') { return "スライド$($Matches[1])" }
    if ($fileBase -eq "header_footer") { return "ヘッダー・フッター" }
    if ($fileBase -eq "doc_footnotes") { return "脚注" }
    if ($fileBase -eq "doc_whole") { return "文書" }
    if ($fileBase -eq "doc_body") { return "本文" }
    return ""
}

function toIndexFileName {
    # インデックスのTSVのファイル名 "<場所>.tsv" を返す。
    #   ・決まった場所（ページ・スライド・ヘッダー/フッター・脚注・文書・本文）は ASCII の固定名にする
    #   ・それ以外（Excelのシート名）は encodeIndexPlace で符号化する
    #   ・図形・コメント・ヘッダー・フッター・埋め込みは、末尾に英語の種類 "[shape]" "[comment]" "[header_footer]" "[embed<N>]" を付ける（placeKindFileNames）
    # 元のファイル名はフォルダ名（= 元のファイル名そのもの）にするため、ファイル名には入れない。
    # ファイル名の上限（255文字）は長いパスの対応（toLongPath）でも超えられないため、超える場合は分かるメッセージで例外にする
    param (
        [string]$place
    )

    $split = splitObjectPlace $place
    $fixedName = convertPlaceBaseToFixedFileName $split.Base
    $base = if ($fixedName) { $fixedName } else { encodeIndexPlace $split.Base }
    $suffix = if ($split.Kind) { "[$(${placeKindFileNames}[$split.Kind])$(if ($split.Number -gt 0) { $split.Number })]" } else { "" }
    $name = "{0}{1}.tsv" -f $base, $suffix
    if ($name.Length -gt ${maxFileNameLength}) {
        throw "インデックスのファイル名が長すぎるため保存できません（$($name.Length) 文字。上限 ${maxFileNameLength} 文字）: ${name}"
    }
    return $name
}

function convertIndexFileNameToPlace {
    # toIndexFileName の逆変換。ファイル名（拡張子 .tsv を除いたもの）から場所を復元する。
    #   戻す順番: (1) 末尾の "[shape]"・"[comment]"・"[header_footer]"・"[embed<N>]"（placeKindFileNames の値）を外す →
    #             (2) 残りに "_" があれば固定の場所の表で戻し、無ければ decodeIndexPlace で戻す →
    #             (3) (1) で外した種類を日本語（[図形]・[コメント]・[ヘッダー・フッター]・[埋め込み<N>]）で付け直す
    param (
        [string]$fileNameWithoutExtension
    )

    $kind = ""
    $body = $fileNameWithoutExtension
    $fileKindAlternation = (${placeKindFileNames}.Values | ForEach-Object { [regex]::Escape($_) }) -join "|"
    if ($fileNameWithoutExtension -match "^(?<base>.+)\[(?<kind>$fileKindAlternation)(?<number>${objectPlaceNumberPattern})?\]`$") {
        $kindName = $Matches.kind
        $kind = (${placeKindFileNames}.GetEnumerator() | Where-Object { $_.Value -eq $kindName } | Select-Object -First 1).Key
        # 番号は埋め込みにだけ付く（ほかの種類に付いた名前は、この関数が作らない形のため戻さない）
        if (($kind -eq ${placeKindEmbed}) -eq [bool]$Matches.number) {
            $body = $Matches.base
            if ($Matches.number) { $kind = "${kind}$($Matches.number)" }
        } else {
            $kind = ""
        }
    }

    if ($body.IndexOf("_") -ge 0) {
        $base = convertFixedFileNameToPlaceBase $body
    } else {
        $base = decodeIndexPlace $body
    }

    if ($kind) { return "$base[$kind]" }
    return $base
}


# 図形・コメントなど、本文（セル・段落）以外の文字の場所は "<元の場所>[<種類>]" とする。
# 元の場所は、Excel ではシート名（例: "売上[図形]"。office_reader.ps1 の readXlsxObjectUnits）。
# Word はページ、PowerPoint はスライドを元の場所にする（例: "ページ003[コメント]" "スライド002[図形]"）。
# Excel のシート名には [ ] を使えず、Word・PowerPoint の場所（ページNNN・スライドNNN 等）にも付かないため、ふつうの場所と重ならない。
# 種類ごとに、検索に含めるかを画面で選べる（search_query.ps1 の newPlaceExclude）。
# 種類を足すときは、ここ（placeKindFileNames にも足す）と書き出す側（office_reader.ps1）をそろえる。検索の除外・画面の判定の正規表現は newObjectPlaceKindPattern が表から組み立てる
${placeKindShape}   = "図形"      # 図形・テキストボックス・WordArt・SmartArt・グラフ（PowerPoint のテキストボックス・図形はスライドの本文）
${placeKindComment} = "コメント"  # コメント（メモ・スレッド形式のコメント）
${placeKindHeaderFooter} = "ヘッダー・フッター"  # Excel のヘッダー・フッター（Word・PowerPoint の "ヘッダー・フッター" は場所の名前で、種類ではない）。いつも検索する（除外の選択肢は無い）
${placeKindEmbed}   = "埋め込み"  # Word・PowerPoint に埋め込んだ Office のファイル（.xlsx・.docx・.pptx など）の中の文字。場所は "<元の場所>[埋め込み<N>]"（N は 1 ファイルの中の通し番号。ほかの種類と違い、番号が付く）。図形と一緒に検索の有無を切り替える

# 種類ごとの、TSVのファイル名に付ける英語の名前（toIndexFileName・convertIndexFileNameToPlace で使う）。
# 番号の付く種類（埋め込み）のファイル名は "[embed<N>]"
${placeKindFileNames} = @{ ${placeKindShape} = "shape"; ${placeKindComment} = "comment"; ${placeKindHeaderFooter} = "header_footer"; ${placeKindEmbed} = "embed" }

# ${objectPlacePattern} の種類の選択肢は ${placeKindFileNames} のキーから組み立てる（足し忘れを防ぐ）。
# 番号の付く種類（埋め込み）は選択肢に入れず、番号（先頭が 0 でない数字）を付けた形だけを別に当てる
# （"[埋め込み]"・"[埋め込み01]" はふつうの場所とする）
${objectPlaceKindAlternation} = (${placeKindFileNames}.Keys | Where-Object { $_ -ne ${placeKindEmbed} } | ForEach-Object { [regex]::Escape($_) }) -join "|"
${objectPlaceNumberPattern} = "[1-9][0-9]{0,8}"
${objectPlacePattern} = "^(?<base>.*)\[(?:(?<kind>${objectPlaceKindAlternation})|(?<numberedKind>$([regex]::Escape(${placeKindEmbed})))(?<number>${objectPlaceNumberPattern}))\]$"


function newObjectPlaceKindPattern {
    # 場所の末尾の種類だけを当てる正規表現の文字列を、${placeKindFileNames} の表から組み立てる。
    # 検索から外す場所（search_query.ps1 の newPlaceExclude）と画面の判定（ui/search/result_types.ps1 の HitRow.ObjectPlaceRegex）が使う。
    #   例（全部）: \[(?:図形|コメント|ヘッダー・フッター|埋め込み[1-9][0-9]{0,8})\]$（選択肢の並びは表の順による）
    # kinds: 当てる種類の名前の並び（省略または空は全部）。番号の付く種類（埋め込み）は番号の形を付けて当てる
    param (
        [string[]]$kinds = @()
    )

    if ($kinds.Count -eq 0) {
        $kinds = @(${placeKindFileNames}.Keys)
    }
    $alternatives = foreach ($kind in $kinds) {
        if ($kind -eq ${placeKindEmbed}) { "$([regex]::Escape($kind))${objectPlaceNumberPattern}" } else { [regex]::Escape($kind) }
    }
    return "\[(?:$(@($alternatives) -join '|'))\]`$"
}


function splitObjectPlace {
    # 場所を @{ Base（元の場所）; Kind（種類。ふつうの場所は空）; Number（埋め込みの番号。ほかは 0） } に分ける。
    #   例: "売上[図形]" → @{ Base = "売上"; Kind = "図形"; Number = 0 } / "ページ001" → @{ Base = "ページ001"; Kind = ""; Number = 0 }
    #       "ページ003[埋め込み2]" → @{ Base = "ページ003"; Kind = "埋め込み"; Number = 2 }
    param (
        [string]$place
    )

    if ($place -match ${objectPlacePattern}) {
        if ($Matches.numberedKind) {
            return @{ Base = $Matches.base; Kind = $Matches.numberedKind; Number = [int]$Matches.number }
        }
        return @{ Base = $Matches.base; Kind = $Matches.kind; Number = 0 }
    }
    return @{ Base = $place; Kind = ""; Number = 0 }
}


function describePlace {
    # 場所ごとの表記と「種別」を @{ Place; Kind } で返す（TSV の名前は変えず、表示だけを変える）。
    # 画面の見出しの要約・検索結果ファイル・コピーに使う。表の「場所」の列は、これにセル番地を足した describeHitPlace を使う
    #   Excel      : "売上" → [シート]売上・セル / "売上[図形]" → [シート]売上・図形 / "売上[コメント]" → [シート]売上・コメント
    #                / "売上[ヘッダー・フッター]" → [シート]売上・ヘッダー・フッター
    #   Word       : "ページ003" → 3 ページ（目安）・本文（ページは保存時の区切りから数えた目安のため）/ "脚注" → 脚注・本文
    #   PowerPoint : "スライド002（非表示）" → スライド 2（非表示）・本文 / "スライド002_ノート" → スライド 2・ノート
    #   テキスト   : "本文" → 空・本文（場所は 1 つだけのため、表の「場所」の列は describeHitPlace の "N 行目" だけで足りる）
    # 種別は、図形・コメントなら場所の種類の名前そのまま（検索条件の［図形も検索］［コメントも検索］と同じ言葉）。
    # 埋め込みは番号を付けた "埋め込み 1"（場所は元の場所のページ・スライドの表記のまま）
    param (
        [string]$book,
        [string]$place
    )

    if (testTextExtension $book) {
        return @{ Place = ""; Kind = "本文" }
    }

    $split = splitObjectPlace $place
    $base = $split.Base
    $kind = $split.Kind
    if ($split.Number -gt 0) { $kind = "$kind $($split.Number)" }

    if ($book -match '\.xls[a-z]?$') {
        return @{ Place = "[シート]$base"; Kind = $(if ($kind) { $kind } else { "セル" }) }
    }
    if ($base -eq "") {
        return @{ Place = ""; Kind = $(if ($kind) { $kind } else { "本文" }) }
    }
    if ($base -match '^ページ(\d+)$') {
        if (testPdfExtension $book) {
            return @{ Place = "$([int]$Matches[1]) ページ"; Kind = $(if ($kind) { $kind } else { "本文" }) }
        }
        return @{ Place = "$([int]$Matches[1]) ページ（目安）"; Kind = $(if ($kind) { $kind } else { "本文" }) }
    }
    if ($base -match '^スライド(\d+)_ノート$') {
        return @{ Place = "スライド $([int]$Matches[1])"; Kind = $(if ($kind) { $kind } else { "ノート" }) }
    }
    if ($base -match '^スライド(\d+)(（非表示）)?$') {
        return @{ Place = "スライド $([int]$Matches[1])$($Matches[2])"; Kind = $(if ($kind) { $kind } else { "本文" }) }
    }
    # ヘッダー・フッター・脚注など、番号の無い場所
    return @{ Place = $base; Kind = $(if ($kind) { $kind } else { "本文" }) }
}


function describeHitPlace {
    # 結果の表の「場所」の列とプレビューの題に出す、行ごとの場所の表記を返す（場所ごとの表記にセル番地を足したもの）。
    # Excel だけ足す（Word・PowerPoint は場所ごとと同じ）。テキストは行番号だけ（"N 行目"）を返す（場所は 1 つしかないため）。
    #   セル             : [シート]売上!B12 / 1 行に複数のセルが一致 [シート]売上!B12 ほか 2 / セル番地が求まらないとき [シート]売上 12 行目
    #   図形・コメント   : [シート]売上!D5 / セル番地が求まらないとき [シート]売上（行番号は通し番号のため出さない）
    #   ヘッダー・フッター: [シート]売上（行にセル番地が無く、matchCell が空のため）
    #   テキスト         : 12 行目
    param (
        [string]$place,
        [bool]$isExcel,
        [bool]$isObjectPlace,
        [string]$matchCell,
        [int]$matchCount,
        [int]$lineNumber,
        [bool]$isText = $false
    )

    if ($isText) { return "$lineNumber 行目" }
    if (-not $isExcel) { return $place }
    if ($isObjectPlace) {
        if ($matchCell) { return "$place!$matchCell" }
        return $place
    }
    if (-not $matchCell) { return "$place $lineNumber 行目" }
    if ($matchCount -gt 1) { return "$place!$matchCell ほか $($matchCount - 1)" }
    return "$place!$matchCell"
}


# インデックスの「元のファイル名のフォルダ」と分かる名前（Office・テキスト・PDF の拡張子で終わる）
${indexBookDirPattern} = "\.(?:xls|doc|ppt)[a-z]?$|(?:$(((${textExtensions} + ${pdfExtensions}) | ForEach-Object { [regex]::Escape($_) }) -join '|'))$"

# インデックス（work\index 配下）の作成・集計・改名・削除。

function testStatusRowFailed {
    # 取り込み一覧の行を「失敗」として数えるか。状態が「失敗」の行と、「未取り込み」で理由（エラー）が書いてある行
    # （利用者の PowerPoint のために取り込めなかったファイル。次の更新で取り込むため状態は「未取り込み」のまま）
    param (
        $row
    )

    $state = [string]$row.状態
    return ($state -eq ${stateFailed}) -or ($state -eq ${stateNew} -and [string]$row.エラー -ne "")
}

function getIndexStats {
    # 取り込み一覧の行をインデックス名ごとに集計する（画面のインデックス一覧に出す件数・最終更新）:
    #   インデックス名（大文字・小文字を区別しない）→ @{ Total; Done; Pending; Failed; LastIngested（"yyyy/MM/dd HH:mm:ss"。無ければ空） }
    # rows は readStatusFile の Rows（相対パス → 行）。取り込み一覧を読み直さずに済むよう、読み込み済みの行を受け取る
    param (
        $rows
    )

    $stats = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
    if ($null -eq $rows) {
        return , $stats
    }
    foreach ($entry in $rows.GetEnumerator()) {
        $name = (splitIndexRelPath $entry.Key).Name
        if ($name -eq "") {
            continue
        }
        if (!$stats.ContainsKey($name)) {
            $stats[$name] = @{ Total = 0; Done = 0; Pending = 0; Failed = 0; LastIngested = "" }
        }
        $stat = $stats[$name]
        $stat.Total++
        $state = [string]$entry.Value.状態
        if ($state -eq ${stateDone}) {
            $stat.Done++
        } elseif (testStatusRowFailed $entry.Value) {
            $stat.Failed++
        } elseif ($state -eq ${stateNew}) {
            $stat.Pending++
        }
        # 取り込み日時は "yyyy/MM/dd HH:mm:ss" のため、文字列のまま比べて新しい方を残せる
        $ingested = [string]$entry.Value.取り込み日時
        if ($ingested -gt $stat.LastIngested) {
            $stat.LastIngested = $ingested
        }
    }
    return , $stats
}

function removeSystemIndexOfWorkspace {
    # インデックスのフォルダ（dir = <ワークスペース>\index）と同じワークスペースの system_index から、インデックス name の分を消す。
    # 消せなくても（状態ファイルがほかに開かれている等）インデックスの操作は続ける。次のインデックス作成で整理される
    param (
        [string]$name,
        [string]$dir
    )

    $owner = [Workspace]::new([System.IO.Path]::GetDirectoryName($dir.TrimEnd("\")))
    try {
        [void](removeSystemIndexOf $name $owner.SystemIndexDir $owner.SystemIndexStateFile)
    } catch {
    }
}

function getSearchIndexes {
    # インデックスの一覧（getSearchIndexData の Indexes）。引数は getSearchIndexData と同じ
    param (
        [string]$dir = $workspace.IndexDir,
        [string]$statusPath = $workspace.StatusFile,
        [string]$settingsPath = ${settingsFile}
    )

    return @((getSearchIndexData $dir $statusPath $settingsPath).Indexes)
}

function getSearchIndexData {
    # @{ Root（dir のフルパス）; Sources（インデックス名 → 元のフォルダ。getSourceFolderMap の結果）; Indexes } を返す。
    # Indexes はインデックスの一覧（work\index 直下のフォルダ 1 つがインデックス 1 つ）で、
    # @{ Name（インデックス名）; Path（インデックスのフォルダのフルパス）; SourcePath（元のフォルダ。分からなければ ""） } の配列で返す。
    # 並びは［インデックス管理］の一覧（targetFolders）と同じにし、その一覧に無いもの
    # （別の場所・PC から work\index にコピーしたインデックスなど）は名前順で後ろに付ける
    param (
        [string]$dir = $workspace.IndexDir,
        [string]$statusPath = $workspace.StatusFile,
        [string]$settingsPath = ${settingsFile}
    )

    if (!(Test-Path -LiteralPath $dir -PathType Container)) {
        return @{ Root = $dir; Indexes = @(); Sources = @{} }
    }
    $root = (Resolve-Path -LiteralPath $dir).ProviderPath.TrimEnd("\")
    $sources = getSourceFolderMap $root $statusPath $settingsPath

    # ［インデックス管理］の一覧の順番（インデックス名 → 何番目か）
    $order = New-Object 'System.Collections.Generic.Dictionary[string,int]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($folder in @(getTargetFolders $settingsPath | Where-Object { $_.Name })) {
        if (!$order.ContainsKey($folder.Name)) {
            $order[$folder.Name] = $order.Count
        }
    }

    $indexes = New-Object System.Collections.Generic.List[object]
    foreach ($sub in @(Get-ChildItem -LiteralPath (toLongPath $root) -Directory -ErrorAction SilentlyContinue)) {
        $name = $sub.Name
        $path = (fromLongPath $sub.FullName)
        if (!$sources.ContainsKey($name)) {
            # 取り込み一覧にも設定にも無いインデックス（別の場所・PC からコピーしたものなど）は、
            # そのフォルダの中の source_folder.txt から元のフォルダを読む
            $own = readSourceFolderFile $path
            if ($own.ContainsKey($name)) {
                $sources[$name] = $own[$name]
            }
        }
        $indexes.Add([pscustomobject]@{
            Name       = $name
            Path       = $path
            SourcePath = $(if ($sources.ContainsKey($name)) { $sources[$name] } else { "" })
            Order      = $(if ($order.ContainsKey($name)) { $order[$name] } else { [int]::MaxValue })
        })
    }
    $sorted = @($indexes | Sort-Object Order, Name | ForEach-Object {
        [pscustomobject]@{ Name = $_.Name; Path = $_.Path; SourcePath = $_.SourcePath }
    })
    return @{ Root = $root; Indexes = $sorted; Sources = $sources }
}


# インデックスのフォルダが壊れている（0 バイトのTSVがある）ことを表す件数。testIndexComplete は取り込み直す
${indexBrokenCount} = -1


function getContentIndexKeyOf {
    # getIndexTsvCounts の本文インデックスのファイルのキー（「<インデックスのフォルダからのフォルダ>\content_index.<拡張子>」）を返す
    param (
        [string]$relDir,
        [string]$extension
    )

    $name = "${contentIndexFileNamePrefix}.$extension"
    if ($relDir) { return "$relDir\$name" }
    return $name
}

function getIndexTsvCounts {
    # インデックスのフォルダの中のフォルダごとのTSVの数を返す（取り込み一覧の「済」と、インデックスの実体が合っているかの確認に使う）:
    #   インデックスのフォルダからの相対パス（大文字・小文字を区別しない）→ そのフォルダの直下のTSVの数
    #   本文インデックスのファイル（content_index.<拡張子>.<番号>.tsv）は、「<フォルダ>\content_index.<拡張子>」 → 1（どれかが 0 バイトなら ${indexBrokenCount}）
    # 元のファイル1つにつき1フォルダ（<ファイル名.xlsx>\<場所>.tsv）のため、キーは取り込み一覧の相対パスと同じになる。
    # 0 バイトのTSVがあるフォルダは ${indexBrokenCount}（-1）にする。
    # 空のシート・ページは保存しない（prettyTsv / writeUnits）ため、0 バイトのTSVは書き込みの途中で
    # 電源が落ちた場合などに限られ、そのままでは検索しても中身が出てこない。
    # 列挙できないとき（アクセス権が無い等）は $null を返す（呼び出し元は確認しない）
    param (
        [string]$dir = $workspace.IndexDir
    )

    $counts = New-Object 'System.Collections.Generic.Dictionary[string,int]' ([System.StringComparer]::OrdinalIgnoreCase)
    $root = toLongPath ([string]$dir).TrimEnd("\")
    if (!$root -or ![System.IO.Directory]::Exists($root)) {
        return , $counts
    }

    # 1ファイルずつ調べると件数の分だけ時間がかかるため、フォルダ・TSVをそれぞれ1回ずつ列挙して数える
    # （大きさは列挙のときに分かるため、1件ずつ調べる必要は無い）
    $prefix = $root.Length + 1
    try {
        # 内容が空のファイル（TSV 0 件）はフォルダだけが残るため、フォルダも 0 件として数える
        foreach ($sub in [System.IO.Directory]::EnumerateDirectories($root, "*", [System.IO.SearchOption]::AllDirectories)) {
            $counts[$sub.Substring($prefix)] = 0
        }
        foreach ($file in (New-Object System.IO.DirectoryInfo($root)).EnumerateFiles("*.tsv", [System.IO.SearchOption]::AllDirectories)) {
            $contentIndexInfo = readContentIndexFileName $file.Name
            if ($null -ne $contentIndexInfo) {
                # 本文インデックスのファイル（content_index.<拡張子>.<番号>.tsv）は、番号を除いた「<フォルダ>\content_index.<拡張子>」をキーにする
                # （testIndexComplete が拡張子ごとに見る）。どれか 1 つでも 0 バイトなら壊れているとする
                $contentIndexDir = if ($file.DirectoryName.Length -ge $prefix) { $file.DirectoryName.Substring($prefix) } else { "" }
                $key = getContentIndexKeyOf $contentIndexDir $contentIndexInfo.Extension
                $current = 0
                if ($file.Length -eq 0 -or ($counts.TryGetValue($key, [ref]$current) -and $current -eq ${indexBrokenCount})) {
                    $counts[$key] = ${indexBrokenCount}
                } else {
                    $counts[$key] = 1
                }
                continue
            }
            $parent = [System.IO.Path]::GetDirectoryName($file.FullName)
            if ($parent.Length -lt $prefix) {
                continue  # インデックスのフォルダの直下のTSVは、どのファイルのものか分からないため数えない
            }
            $key = $parent.Substring($prefix)
            $count = 0
            if (!$counts.TryGetValue($key, [ref]$count)) {
                $count = 0
            }
            if ($file.Length -eq 0 -or $count -eq ${indexBrokenCount}) {
                $counts[$key] = ${indexBrokenCount}
            } else {
                $counts[$key] = $count + 1
            }
        }
    } catch {
        return $null
    }
    return , $counts
}

function testIndexComplete {
    # 取り込み一覧の行（状態が「済」）に対して、インデックスの実体がそろっているかを返す。
    # 利用者が work\content_index のフォルダ・ファイルを直接削除した場合に、「済」のまま検索できなくなるのを防ぐ。
    # 元のファイルの中身は、フォルダの本文インデックスのファイル（content_index.<拡張子>.tsv）か、本文インデックスのファイルに入れる前の TSV
    # （<ファイル名.xlsx>\<場所>.tsv。インデックス作成が途中で止まったとき）のどちらかにある
    #   row    : 取り込み一覧の行（TSV数 を使う）
    #   relPath: 取り込み一覧の相対パス（= インデックスのフォルダからの相対パス）
    #   counts : getIndexTsvCounts の結果（$null なら確認せず、そろっているものとして扱う）
    param (
        $row,
        [string]$relPath,
        $counts
    )

    if ($null -eq $counts -or $null -eq $row) {
        return $true
    }
    # 本文インデックスのファイル: そのフォルダ・その拡張子の本文インデックスのファイルがあれば、そろっているものとする
    # （本文インデックスのファイルの中の元のファイルごとの場所の数は、中身を読まないと分からないため数えない）
    $contentIndexRel = getContentIndexKeyOf ([string][System.IO.Path]::GetDirectoryName($relPath)) (getContentIndexExtension $relPath)
    $contentIndexCount = 0
    if ($counts.TryGetValue($contentIndexRel, [ref]$contentIndexCount) -and $contentIndexCount -ne ${indexBrokenCount}) {
        return $true
    }
    $expected = 0
    if (-not [int]::TryParse([string]$row.TSV数, [ref]$expected)) {
        return $true  # TSVの数を記録していない行は確認できない
    }
    $actual = 0
    if (-not $counts.TryGetValue($relPath, [ref]$actual)) {
        return $false  # 本文インデックスのファイルも、元のファイルごとのフォルダも無い
    }
    if ($actual -eq ${indexBrokenCount}) {
        return $false  # 0 バイトのTSVがある（書き込みの途中で電源が落ちた場合など）
    }
    # 余分なTSVがあっても（利用者が置いた等）取り込み直さない。足りない場合だけ作り直す
    return ($actual -ge $expected)
}

function publishIndexFiles {
    # 取り込んで作ったTSV（fromDir の直下）を、その元のファイルのインデックスのフォルダ（bookDir）に入れる。
    # 作りかけのインデックスを残さないよう、いったん stagingDir に集めてから bookDir ごと入れ替える。
    # 途中で強制終了されても、bookDir は「前回のまま」か「今回の分がそろった状態」のどちらかになる
    # （1件ずつ bookDir へ移すと、途中で止まったときに一部のシートだけのインデックスが残り、検索で気付けない）。
    # 以前のインデックスはフォルダごと置き換える（シートの削除・名前変更に追従するため）
    param (
        [string]$fromDir,
        [string]$bookDir,
        [string]$stagingDir
    )

    removeDirectoryRetry $stagingDir
    [System.IO.Directory]::CreateDirectory((toLongPath $stagingDir)) | Out-Null
    foreach ($file in @(Get-ChildItem -LiteralPath (toLongPath $fromDir) -Filter "*.tsv" -File)) {
        [System.IO.File]::Move($file.FullName, (toLongPath (Join-Path $stagingDir $file.Name)))
    }

    removeDirectoryRetry $bookDir
    [System.IO.Directory]::CreateDirectory((toLongPath ([System.IO.Path]::GetDirectoryName($bookDir)))) | Out-Null
    try {
        [System.IO.Directory]::Move((toLongPath $stagingDir), (toLongPath $bookDir))
    } catch [System.IO.IOException] {
        # work を別のドライブへのリンクにしている場合など、フォルダごとは移せないときは1件ずつ移す
        [System.IO.Directory]::CreateDirectory((toLongPath $bookDir)) | Out-Null
        foreach ($file in @(Get-ChildItem -LiteralPath (toLongPath $stagingDir) -Filter "*.tsv" -File)) {
            [System.IO.File]::Move($file.FullName, (toLongPath (Join-Path $bookDir $file.Name)))
        }
        removeDirectoryRetry $stagingDir
    }
    # bookDir はワークスペースの中（同じドライブ）の一時フォルダから Move で入れるため、親（content_index\）の
    # NotContentIndexed 属性を継がない。ここで、入れた分（フォルダと直下の TSV）だけに付ける
    [void](setNotContentIndexed $bookDir)
}

# 検索用の本文インデックスのファイル（フォルダ 1 つ・元のファイルの拡張子 1 つにつき、大きさで分けて 1 つ以上。content_index.xlsx.001.tsv など）の形式（判断層）。
# ファイル（元のファイル）ごと・場所（シート・ページ・スライドなど）ごとに、メタ情報の行と今の TSV の中身を並べる。
#
#   <RS> 版=1
#   <RS> ファイル名=(株)山田商事_見積書.xlsx
#   <RS> 種類=Excel
#   <RS> シート=見積
#   <RS> 対象=本文
#   品名→数量→単価        ← 今の TSV の中身そのまま（→ はタブ）。この行が 1 行目
#
# ・メタ情報の行は「RS（U+001E）、半角スペース、キー=値」。1 行に 1 項目。
#   ファイル名= で新しいファイル、シート= ページ= スライド= 部分= で新しい場所が始まる。知らないキーは読み飛ばす
# ・中身には U+001C～U+001F を入れない（書くときに取り除く）ため、行の先頭が RS ならメタ情報の行
# ・改行は LF にそろえる。行の分け方は StreamReader.ReadLine と同じ（CRLF・LF・CR）にし、行番号を変えない
# ・文字コードは UTF-16LE（BOM 付き。content_index_store.ps1 が読み書きする）
# ・Excel の図形・コメントの行は「セル番地 + タブ + 文字」の形。検索は区切りのタブ（最初のタブ）より後だけを照合する（CellPrefixed。content_index_search.ps1）

# 本文インデックスのファイルの名前は「content_index.<元のファイルの拡張子（小文字）>.<番号（3 桁以上）>.tsv」（content_index.xlsx.001.tsv など）。
# 1 つの本文インデックスのファイルが contentIndexFileMaxBytes 以上になったら、それ以上ブックを足さず、次の番号の本文インデックスのファイルに足す
# 先頭の語（content_index）は 1 か所の定数にする（index_store.ps1 の getContentIndexKeyOf も使う）
${contentIndexFileNamePrefix} = "content_index"
${contentIndexFilePattern} = "${contentIndexFileNamePrefix}.*.tsv"
${contentIndexFileNamePattern} = "^${contentIndexFileNamePrefix}\.(?<ext>[^.]+)\.(?<part>\d{3,})\.tsv$"
${contentIndexFileMaxBytes} = 4MB
${contentIndexVersion} = 1
${contentIndexMark} = [char]0x1E

# 場所のまとまりを始めるキー
${contentIndexPlaceKeys} = @("シート", "ページ", "スライド", "部分")


function getContentIndexFileKind {
    # 元のファイル名から種類（Excel・Word・PowerPoint・テキスト・PDF）を返す。分からなければ空
    param (
        [string]$book
    )

    if ($book -match '\.xls[a-z]?$') { return "Excel" }
    if ($book -match '\.doc[a-z]?$') { return "Word" }
    if ($book -match '\.ppt[a-z]?$') { return "PowerPoint" }
    if (testTextExtension $book) { return "テキスト" }
    if (testPdfExtension $book) { return "PDF" }
    return ""
}

function getContentIndexExtension {
    # 元のファイル名から、本文インデックスのファイルを分ける拡張子（小文字・先頭の . なし）を返す
    param (
        [string]$book
    )

    return [System.IO.Path]::GetExtension($book).TrimStart(".").ToLowerInvariant()
}


function getContentIndexFileName {
    # 拡張子・番号の本文インデックスのファイルの名前（content_index.xlsx.001.tsv など）を返す
    param (
        [string]$extension,
        [int]$part = 1
    )

    return "${contentIndexFileNamePrefix}.{0}.{1:D3}.tsv" -f $extension, $part
}


function readContentIndexFileName {
    # 本文インデックスのファイルの名前から @{ Extension; Part } を返す。本文インデックスのファイルの名前でなければ $null
    param (
        [string]$name
    )

    if ($name -match ${contentIndexFileNamePattern}) {
        return @{ Extension = $Matches.ext.ToLowerInvariant(); Part = [int]$Matches.part }
    }
    return $null
}


function splitContentIndexBooksByExtension {
    # 元のファイルの並びを、拡張子ごとの並び（[ordered] 拡張子 → 並び。拡張子は現れた順）に分ける。各並びの中の順は変えない
    param (
        $books
    )

    $groups = [ordered]@{}
    foreach ($book in $books) {
        $extension = getContentIndexExtension ([string]$book.Name)
        if (!$groups.Contains($extension)) {
            $groups[$extension] = New-Object System.Collections.Generic.List[object]
        }
        $groups[$extension].Add($book)
    }
    return $groups
}


function encodeContentIndexValue {
    # メタ情報の値を 1 行に収まる形にする。制御文字（タブを除く）と % を "%XX" にする（decodeContentIndexValue で戻す）
    param (
        [string]$value
    )

    if ($value -notmatch '[\x00-\x08\x0A-\x1F%]') {
        return $value
    }
    return [regex]::Replace($value, '[\x00-\x08\x0A-\x1F%]', { param($m) '%{0:X2}' -f [int][char]$m.Value })
}


function decodeContentIndexValue {
    # encodeContentIndexValue で符号化した値を戻す
    param (
        [string]$value
    )

    if ($value.IndexOf("%") -lt 0) {
        return $value
    }
    return [regex]::Replace($value, '%(?:[01][0-9A-F]|25)', { param($m) [string][char][Convert]::ToInt32($m.Value.Substring(1), 16) })
}


function convertPlaceToContentIndexMeta {
    # 今の場所の名前（TSV のファイル名。"見積[図形]"・"ページ001"・"スライド002（非表示）"・"スライド001_ノート" など）を、
    # 場所のメタ情報（[ordered] キー → 値）にする。convertContentIndexMetaToPlace で必ず元の名前に戻る形にし、
    # 分けられない名前は「部分=名前そのまま・対象=本文」にする
    param (
        [string]$book,
        [string]$place
    )

    $split = splitObjectPlace $place
    $target = if ($split.Kind) { $split.Kind } else { "本文" }
    $meta = [ordered]@{}
    switch (getContentIndexFileKind $book) {
        "Excel" {
            $meta["シート"] = $split.Base
            $meta["対象"] = $target
        }
        "Word" {
            if ($split.Base -match '^ページ(\d+)$') {
                $meta["ページ"] = [string][int]$Matches[1]
            } else {
                $meta["部分"] = $split.Base
            }
            $meta["対象"] = $target
        }
        "PowerPoint" {
            if (!$split.Kind -and $split.Base -match '^スライド(\d+)_ノート$') {
                $meta["スライド"] = [string][int]$Matches[1]
                $meta["対象"] = "ノート"
            } elseif ($split.Base -match '^スライド(\d+)(（非表示）)?$') {
                $meta["スライド"] = [string][int]$Matches[1]
                $meta["対象"] = $target
                if ($Matches[2]) { $meta["非表示"] = "はい" }
            } else {
                $meta["部分"] = $split.Base
                $meta["対象"] = $target
            }
        }
        default {
            $meta["部分"] = $split.Base
            $meta["対象"] = $target
        }
    }
    if ($split.Number -gt 0) {
        # 埋め込みの番号（"ページ003[埋め込み2]" → 対象=埋め込み・埋め込み=2。場所を始めるキーではない）
        $meta["埋め込み"] = [string]$split.Number
    }
    if ((convertContentIndexMetaToPlace $meta) -cne $place) {
        # 番号の桁が違う（"ページ1"）など、組み立て直すと同じ名前にならないものは、名前をそのまま持つ
        $meta = [ordered]@{ "部分" = $place; "対象" = "本文" }
    }
    return $meta
}


function convertContentIndexMetaToPlace {
    # 場所のメタ情報から、今の場所の名前（画面の表示・図形とコメントの除外・元のファイルを開く処理が使う形）を組み立てる
    param (
        $meta
    )

    $target = [string]$meta["対象"]
    $suffix = if ($target -eq ${placeKindShape} -or $target -eq ${placeKindComment} -or $target -eq ${placeKindHeaderFooter}) { "[$target]" } else { "" }
    if ($target -eq ${placeKindEmbed} -and $meta.Contains("埋め込み")) {
        $suffix = "[$target$([string]$meta["埋め込み"])]"
    }
    if ($meta.Contains("シート")) {
        return [string]$meta["シート"] + $suffix
    }
    if ($meta.Contains("ページ")) {
        return ("ページ{0:D3}" -f [int]$meta["ページ"]) + $suffix
    }
    if ($meta.Contains("スライド")) {
        $base = "スライド{0:D3}" -f [int]$meta["スライド"]
        if ($target -eq "ノート") {
            return "${base}_ノート"
        }
        if ($meta["非表示"] -eq "はい") {
            $base += "（非表示）"
        }
        return $base + $suffix
    }
    if ($target -eq "本文") {
        return [string]$meta["部分"]
    }
    return [string]$meta["部分"] + $suffix
}


function convertToContentIndexBody {
    # TSV の中身を、本文インデックスのファイルに入れる形（LF 区切り・末尾に LF・U+001C～U+001F を除く）にする。
    # 行の分け方は StreamReader.ReadLine と同じ（CRLF・LF・CR で分け、末尾の改行の後ろは行にしない）。中身が空なら空を返す
    param (
        [string]$text
    )

    if ($text.Length -eq 0) {
        return ""
    }
    $body = $text.Replace("`r`n", "`n").Replace("`r", "`n")
    if ($body.IndexOfAny([char[]]@([char]0x1C, [char]0x1D, [char]0x1E, [char]0x1F)) -ge 0) {
        $body = [regex]::Replace($body, '[\x1C-\x1F]', "")
    }
    if ($body.EndsWith("`n")) {
        return $body
    }
    return $body + "`n"
}


function convertBookToContentIndexBlock {
    # 元のファイル 1 つの中身から、本文インデックスのファイルに入れるまとまり（「ファイル名=」の行から最後の行まで）の文字列を作る。
    #   book: @{ Name（元のファイル名）; Places（@{ Place（今の場所の名前）; Text（TSV の中身） } の並び） }
    #         または @{ Name; Block }（前の本文インデックスのファイルから取り出したまとまり。そのまま返す）
    param (
        $book
    )

    if ($null -ne $book.Block) {
        return [string]$book.Block
    }
    $mark = [string]${contentIndexMark}
    $name = [string]$book.Name
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.Append("$mark ファイル名=").Append((encodeContentIndexValue $name)).Append("`n")
    $kind = getContentIndexFileKind $name
    if ($kind) {
        [void]$sb.Append("$mark 種類=$kind`n")
    }
    foreach ($place in $book.Places) {
        $meta = convertPlaceToContentIndexMeta $name ([string]$place.Place)
        foreach ($key in $meta.Keys) {
            [void]$sb.Append("$mark ").Append($key).Append("=").Append((encodeContentIndexValue ([string]$meta[$key]))).Append("`n")
        }
        [void]$sb.Append((convertToContentIndexBody ([string]$place.Text)))
    }
    return $sb.ToString()
}


function convertToContentIndexText {
    # 元のファイルの並びから、本文インデックスのファイルの文字列を作る（この順に書く）。
    #   books: convertBookToContentIndexBlock に渡せるもの（@{ Name; Places } か @{ Name; Block }）の並び
    param (
        $books
    )

    $sb = New-Object System.Text.StringBuilder
    [void]$sb.Append("$([string]${contentIndexMark}) 版=${contentIndexVersion}`n")
    foreach ($book in $books) {
        [void]$sb.Append((convertBookToContentIndexBlock $book))
    }
    return $sb.ToString()
}


function planContentIndexParts {
    # フォルダ 1 つの、拡張子ごと・番号ごとの本文インデックスのファイルに、どの元のファイルを入れるかを決める。
    #   parts  : 前の本文インデックスのファイルの並び。@{ Extension; Part; Books（@{ Name; Block } の並び。ファイルの中の順） }
    #   books  : 足す・入れ替える元のファイル（@{ Name; Block }）。元のファイル名の順に足す
    #   remove : 外す元のファイル名
    #   maxBytes: この大きさ（UTF-16 のバイト数）以上の本文インデックスのファイルには、もう足さない
    # 決め方:
    #   ・入れ替える元のファイルは、今入っている本文インデックスのファイルの同じ位置で入れ替える（ほかの本文インデックスのファイルへ移さない）
    #   ・外す元のファイルは、入っている本文インデックスのファイルから外す
    #   ・新しい元のファイルは、その拡張子の最後の番号の本文インデックスのファイルが maxBytes 未満ならそこに、以上なら次の番号の新しい本文インデックスのファイルに足す
    #   ・1 つの元のファイルは 2 つの本文インデックスのファイルにまたがらない（1 つで maxBytes を超えても、その 1 つで 1 つの本文インデックスのファイルにする）
    # @{ Extension; Part; Books; Changed（書き直しが要る） } の並び（拡張子・番号の順）を返す。
    # 元のファイルが無くなった本文インデックスのファイルは、Books が空で Changed が $true（消す）
    param (
        $parts,
        $books,
        [string[]]$remove = @(),
        [long]$maxBytes = ${contentIndexFileMaxBytes}
    )

    $removeSet = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($name in $remove) { [void]$removeSet.Add($name) }
    $replace = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($book in $books) { $replace[[string]$book.Name] = $book }

    $plan = New-Object System.Collections.Generic.List[hashtable]
    foreach ($part in @($parts | Sort-Object { $_.Extension }, { $_.Part })) {
        $kept = New-Object System.Collections.Generic.List[object]
        $changed = $false
        foreach ($book in $part.Books) {
            $name = [string]$book.Name
            if ($removeSet.Contains($name)) {
                $changed = $true
            } elseif ($replace.ContainsKey($name)) {
                $kept.Add($replace[$name])
                [void]$replace.Remove($name)
                $changed = $true
            } else {
                $kept.Add($book)
            }
        }
        $plan.Add(@{ Extension = [string]$part.Extension; Part = [int]$part.Part; Books = $kept; Changed = $changed })
    }

    # 新しい元のファイル（どの本文インデックスのファイルにも無かったもの）を、元のファイル名の順に足す
    foreach ($book in @($replace.Values | Sort-Object { [string]$_.Name })) {
        $extension = getContentIndexExtension ([string]$book.Name)
        $last = $null
        foreach ($p in $plan) {
            if ($p.Extension -eq $extension -and ($null -eq $last -or $p.Part -gt $last.Part)) { $last = $p }
        }
        if ($null -eq $last -or (measureContentIndexPartBytes $last.Books) -ge $maxBytes) {
            $number = if ($null -eq $last) { 1 } else { $last.Part + 1 }
            $last = @{ Extension = $extension; Part = $number; Books = (New-Object System.Collections.Generic.List[object]); Changed = $true }
            $plan.Add($last)
        }
        $last.Books.Add($book)
        $last.Changed = $true
    }
    return , @($plan | Sort-Object { $_.Extension }, { $_.Part })
}


function measureContentIndexPartBytes {
    # 本文インデックスのファイルの大きさ（UTF-16 のバイト数。BOM と版の行を含む）を、元のファイルのまとまり（@{ Name; Block }）の並びから求める
    param (
        $books
    )

    $chars = 1 + ("$([string]${contentIndexMark}) 版=${contentIndexVersion}`n").Length
    foreach ($book in $books) {
        $chars += ([string]$book.Block).Length
    }
    return [long]$chars * 2
}

function testContentIndexCellPrefixed {
    # 場所の行が「セル番地 + 区切りのタブ + 文字」の形か（Excel の図形・コメント）を返す。検索は、この形の行では区切りのタブより後だけを照合する
    param (
        [string]$book,
        $meta
    )

    $target = [string]$meta["対象"]
    return ((getContentIndexFileKind $book) -eq "Excel") -and ($target -eq ${placeKindShape} -or $target -eq ${placeKindComment})
}


function readContentIndexPlaces {
    # 本文インデックスのファイルの文字列を読み、場所ごとの @{ Book; Location（今の場所の名前）; CellPrefixed（行の先頭がセル番地と区切りのタブか）; Start（中身の先頭の位置）; End（中身の終わりの次の位置） }
    # を先頭から順に返す。版が分からないときは例外にする
    param (
        [string]$text
    )

    $places = New-Object System.Collections.Generic.List[hashtable]
    $mark = ${contentIndexMark}
    $placeKeys = ${contentIndexPlaceKeys}
    $book = ""
    $current = $null
    $meta = $null
    $versionSeen = $false
    $pos = $text.IndexOf($mark)
    while ($pos -ge 0) {
        $lineEnd = $text.IndexOf([char]10, $pos)
        if ($lineEnd -lt 0) { $lineEnd = $text.Length }
        $line = $text.Substring($pos + 2, [Math]::Max(0, $lineEnd - $pos - 2))
        $eq = $line.IndexOf("=")
        if ($eq -gt 0) {
            $key = $line.Substring(0, $eq)
            $value = decodeContentIndexValue $line.Substring($eq + 1)
            if ($key -eq "版") {
                if ($value -ne [string]${contentIndexVersion}) {
                    throw "集約ファイルの版が違います（$value）"
                }
                $versionSeen = $true
            } elseif ($key -eq "ファイル名" -or $placeKeys -contains $key) {
                if ($current) {
                    $current.End = $pos
                    $current.Location = convertContentIndexMetaToPlace $meta
                    $current.CellPrefixed = testContentIndexCellPrefixed $current.Book $meta
                    $places.Add($current)
                    $current = $null
                }
                if ($key -eq "ファイル名") {
                    $book = $value
                } else {
                    $meta = [ordered]@{ $key = $value }
                    $current = @{ Book = $book; Location = ""; CellPrefixed = $false; Start = $lineEnd + 1; End = $lineEnd + 1 }
                }
            } elseif ($current) {
                $meta[$key] = $value
                $current.Start = $lineEnd + 1
            }
        }
        $pos = if ($lineEnd -lt $text.Length) { $text.IndexOf($mark, $lineEnd + 1) } else { -1 }
    }
    if ($current) {
        $current.End = $text.Length
        $current.Location = convertContentIndexMetaToPlace $meta
        $current.CellPrefixed = testContentIndexCellPrefixed $current.Book $meta
        $places.Add($current)
    }
    if (!$versionSeen -and $text.Length -gt 0) {
        throw "集約ファイルの版がありません"
    }
    return , $places
}


function splitContentIndexTextByBook {
    # 本文インデックスのファイルの文字列を、元のファイルごとのまとまり（@{ Name; Block }。Block は「ファイル名=」の行から次の「ファイル名=」の行の前まで）
    # に分けて先頭から順に返す（元のファイルを入れ替えるとき、変わらないファイルをそのまま写すため）。版が違えば例外にする
    param (
        [string]$text
    )

    $books = New-Object System.Collections.Generic.List[hashtable]
    if ($text.Length -eq 0) {
        return , $books
    }
    $head = "$([string]${contentIndexMark}) ファイル名="
    $versionLine = "$([string]${contentIndexMark}) 版="
    $firstEnd = $text.IndexOf([char]10)
    if (!$text.StartsWith($versionLine, [System.StringComparison]::Ordinal) -or $firstEnd -lt 0 -or $text.Substring($versionLine.Length, $firstEnd - $versionLine.Length) -ne [string]${contentIndexVersion}) {
        throw "集約ファイルの版が違います"
    }
    $pos = $text.IndexOf("`n$head", [System.StringComparison]::Ordinal)
    while ($pos -ge 0) {
        $start = $pos + 1
        $lineEnd = $text.IndexOf([char]10, $start)
        $name = decodeContentIndexValue $text.Substring($start + $head.Length, $lineEnd - $start - $head.Length)
        $next = $text.IndexOf("`n$head", $lineEnd, [System.StringComparison]::Ordinal)
        $end = if ($next -ge 0) { $next + 1 } else { $text.Length }
        $books.Add(@{ Name = $name; Block = $text.Substring($start, $end - $start) })
        $pos = $next
    }
    return , $books
}


function getContentIndexBodyText {
    # 本文インデックスのファイルの文字列から、メタ情報の行（先頭が RS の行）を除いた中身だけを返す（システムインデックスの語を作るため。
    # メタ情報の「ファイル名」「シート」などの語が入ると、その語で探したときにどのフォルダも候補になってしまう）
    param (
        [string]$text
    )

    if ($text.IndexOf([char]0x1E) -lt 0) {
        return $text
    }
    return [regex]::Replace($text, "(?m)^\x1E[^\n]*\n?", "")
}
# ［検索］の検索対象ツリーのデータ集め（状態層。画面に触らない）。
# ワークスペースのフォルダを読むので、届かないネットワークのワークスペースでは、画面のスレッドでなく裏の列（network）から呼ぶ。
# 画面（ui\index_tree.ps1・ui\index\index_types.ps1 の IndexNode）は、この結果を受け取って組み立てるだけにする。

function testIndexBookName {
    # 元のファイルごとのフォルダと分かる拡張子か。Office は拡張子の形（.xls・.doc・.ppt で始まり 4～5 文字）で見分け、
    # テキストは対象の拡張子の一覧（shared\core\text_file.ps1 の testTextExtension。一覧はそこにだけある）で見分ける
    param (
        [string]$name
    )

    $ext = [System.IO.Path]::GetExtension($name).ToLowerInvariant()
    if ($ext.Length -ge 4 -and $ext.Length -le 5 -and
        ($ext.StartsWith(".xls") -or $ext.StartsWith(".doc") -or $ext.StartsWith(".ppt"))) {
        return $true
    }
    return ((testTextExtension $name) -or (testPdfExtension $name))
}

function testIndexBookDirPath {
    # 元のファイルごとのフォルダ（本文インデックスにする前の TSV・中身が空のファイルのフォルダ）か。名前が .xlsx などで終わる本物のフォルダと
    # 区別するため、サブフォルダも本文インデックスのファイル（content_index.*.tsv）も無いことも見る（content_index_store.ps1 の testIndexBookDir と同じ判定）
    param (
        [string]$dir
    )

    if (-not (testIndexBookName ([System.IO.Path]::GetFileName($dir.TrimEnd('\'))))) {
        return $false
    }
    try {
        # 列挙子（Enumerate*）を途中で抜けると、GC まで調べたフォルダを掴んだまま残り、インポートの上書きで
        # content_index\<名前> を移動できなくなる。直下だけなので配列（Get*）で受ける（ここの関数はどれも同じ）
        $long = toLongPath $dir
        if ([System.IO.Directory]::GetDirectories($long).Length -gt 0) { return $false }
        if ([System.IO.Directory]::GetFiles($long, ${contentIndexFilePattern}).Length -gt 0) { return $false }
        return $true
    } catch {
        return $false
    }
}

function testIndexFolderHasSubfolders {
    # インデックスのフォルダの直下に、本のフォルダでないサブフォルダがあるか
    param (
        [string]$dir
    )

    try {
        foreach ($sub in [System.IO.Directory]::GetDirectories((toLongPath $dir))) {
            if (-not (testIndexBookDirPath $sub)) { return $true }
        }
        return $false
    } catch {
        return $false
    }
}

function testIndexFolderHasFiles {
    # インデックスのフォルダの直下に、ファイル（本文インデックスのファイル・本文インデックスにする前の TSV）があるか
    param (
        [string]$dir
    )

    try {
        # 本文インデックスのファイル（content_index.<拡張子>.tsv。content_index_format.ps1 の contentIndexFilePattern）か、本文インデックスにする前の TSV があれば、フォルダ直下にファイルがある
        $long = toLongPath $dir
        if ([System.IO.Directory]::GetFiles($long, ${contentIndexFilePattern}).Length -gt 0) { return $true }
        foreach ($sub in [System.IO.Directory]::GetDirectories($long)) {
            if (-not (testIndexBookDirPath $sub)) { continue }
            if ([System.IO.Directory]::GetFiles($sub, "*.tsv").Length -gt 0) { return $true }
        }
        return $false
    } catch {
        return $false
    }
}

function getIndexFolderChildren {
    # インデックスのフォルダ（dir）の子を @{ HasFiles; Folders = @(@{ Name; HasSubfolders }); Error } で返す。
    # Folders は本のフォルダを除いた名前順。読めなかったときは Error に文面を入れ、Folders は空にする
    param (
        [string]$dir
    )

    $names = New-Object System.Collections.Generic.List[string]
    try {
        foreach ($sub in [System.IO.Directory]::GetDirectories((toLongPath $dir))) {
            if (testIndexBookDirPath $sub) { continue }
            $names.Add([System.IO.Path]::GetFileName($sub))
        }
    } catch {
        return @{ HasFiles = $false; Folders = @(); Error = $_.Exception.Message }
    }
    $names.Sort([System.StringComparer]::CurrentCultureIgnoreCase)
    $folders = @($names | ForEach-Object {
        @{ Name = $_; HasSubfolders = (testIndexFolderHasSubfolders (Join-Path $dir $_)) }
    })
    return @{ HasFiles = (testIndexFolderHasFiles $dir); Folders = $folders; Error = "" }
}

function getIndexTreeData {
    # 検索対象ツリーの材料を集める。
    #   dir: インデックスのフォルダ（work\index）  paths: 展開していたフォルダ・チェックを外したフォルダ（インデックスの根から先祖すべての子も返す）
    # 返すもの: @{ State（getPathState の State）; Message; Root; Sources（getSourceFolderMap の結果）;
    #   Indexes = @(@{ Name; SourcePath; Exists; HasSubfolders }); Children = @{ <フォルダ> = getIndexFolderChildren の結果 } }
    # インデックスのフォルダに接続できない・その他のときは、列挙せずに State と文面だけを返す
    # （Test-Path が $false を返して「インデックスが無い」と取り違えないため）
    param (
        [string]$dir,
        [string]$statusPath,
        [string]$settingsPath,
        [string[]]$paths = @()
    )

    $result = @{ State = ${pathStateMissing}; Message = ""; Root = $dir; Sources = @{}; Indexes = @(); Children = @{} }
    $state = getPathState $dir
    if ($state.State -ne ${pathStateFound}) {
        $result.State = $state.State
        $result.Message = $state.Message
        return $result
    }
    $result.State = ${pathStateFound}

    $data = getSearchIndexData $dir $statusPath $settingsPath
    $root = [string]$data.Root
    $result.Root = $root
    $result.Sources = $data.Sources
    $indexes = New-Object System.Collections.Generic.List[object]
    foreach ($index in @($data.Indexes)) {
        $path = "$root\$($index.Name)"
        $exists = [System.IO.Directory]::Exists((toLongPath $path))
        $indexes.Add(@{
            Name          = $index.Name
            SourcePath    = $(if ($index.SourcePath) { [string]$index.SourcePath } else { "" })
            Exists        = $exists
            HasSubfolders = ($exists -and (testIndexFolderHasSubfolders $path))
        })
    }
    $result.Indexes = $indexes.ToArray()

    # 先祖すべての子を入れる（深い階層の展開・除外を戻すため）
    foreach ($index in $indexes) {
        if (-not $index.Exists) { continue }
        $indexRoot = "$root\$($index.Name)"
        foreach ($target in @($paths)) {
            $target = ([string]$target).TrimEnd("\")
            $isRoot = $target.Equals($indexRoot, [System.StringComparison]::OrdinalIgnoreCase)
            if (-not $isRoot -and -not $target.StartsWith("$indexRoot\", [System.StringComparison]::OrdinalIgnoreCase)) { continue }
            $segments = @($target.Substring($indexRoot.Length).Split([char[]]@("\"), [System.StringSplitOptions]::RemoveEmptyEntries))
            $current = $indexRoot
            for ($i = 0; $i -le $segments.Count; $i++) {
                if (-not $result.Children.ContainsKey($current)) {
                    $result.Children[$current] = getIndexFolderChildren $current
                }
                if ($i -ge $segments.Count) { break }
                $next = $segments[$i]
                $known = $result.Children[$current]
                if (-not (@($known.Folders) | Where-Object { $_.Name -ieq $next })) { break }
                $current = "$current\$next"
            }
        }
    }
    return $result
}

# 検索用の本文インデックスのファイル（content_index_format.ps1）の読み書き（状態層）。
# 本文インデックスのファイルは work\content_index の中のフォルダごと・元のファイルの拡張子ごとに、大きさで分けて置く（content_index.xlsx.001.tsv など）。UTF-16LE（BOM 付き）で書く
# （UTF-8 より文字列への変換が速い。日本語が多いと大きさはほとんど変わらない）。

function writeContentIndexFile {
    # 本文インデックスのファイルを書く。一時ファイル（<名前>.tmp）に書き終えてから置き換えるため、途中で止まっても前のファイルが残る
    param (
        [string]$path,
        [string]$text
    )

    $longPath = toLongPath $path
    $tmp = "$longPath.tmp"
    [System.IO.File]::WriteAllText($tmp, $text, [System.Text.UnicodeEncoding]::new($false, $true))
    if ([System.IO.File]::Exists($longPath)) {
        # 3 つ目の引数（控え）に $null を渡すと PowerShell が空の文字列にして例外になるため、NullString を渡す
        [System.IO.File]::Replace($tmp, $longPath, [NullString]::Value)
    } else {
        [System.IO.File]::Move($tmp, $longPath)
    }
}


function readContentIndexText {
    # 本文インデックスのファイルを文字列で読む（インデックス作成中の置き換えと同時に読めるよう、共有モードは ReadWrite|Delete）
    param (
        [string]$path
    )

    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $stream = [System.IO.FileStream]::new((toLongPath $path), [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    $reader = [System.IO.StreamReader]::new($stream, [System.Text.Encoding]::Unicode, $true)
    try {
        return $reader.ReadToEnd()
    } finally {
        $reader.Dispose()
    }
}


function readContentIndexRange {
    # 本文インデックスのファイル（UTF-16LE・BOM 付き）の、文字の位置 start（含む）から end（含まない）までを start から数えて、
    # firstLine 行目の先頭（firstLine が 1 以下なら start）から lines 個目の改行までを文字列で返す（それより前の行は持たない）。
    # BOM が無い（UTF-16LE でない）ときは $null（呼び出し側が全体を読む）。
    # checkpoints（ハッシュテーブル）を渡すと、通った 200 行ごとの行の先頭（行の番号 → 文字の位置）を足す
    # （start の行の番号が baseLine。次に読むとき、目当ての行の手前の位置から読めるようにする）
    param (
        [string]$path,
        [int]$start,
        [int]$end,
        [int]$firstLine,
        [int]$lines,
        [int]$baseLine = 1,
        $checkpoints = $null
    )

    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $stream = [System.IO.FileStream]::new((toLongPath $path), [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    try {
        $bom = New-Object byte[] 2
        if ($stream.Read($bom, 0, 2) -ne 2 -or $bom[0] -ne 0xFF -or $bom[1] -ne 0xFE) { return $null }
        [void]$stream.Seek(2L + 2L * $start, [System.IO.SeekOrigin]::Begin)
        $reader = [System.IO.StreamReader]::new($stream, [System.Text.UnicodeEncoding]::new($false, $false), $false)
        $builder = New-Object System.Text.StringBuilder
        $buffer = New-Object char[] 65536
        $remaining = $end - $start
        $newlines = 0
        $skip = [Math]::Max(0, $firstLine - 1)
        $started = ($skip -eq 0)
        while ($remaining -gt 0 -and $newlines -lt $lines) {
            $consumed = ($end - $start) - $remaining
            $got = $reader.Read($buffer, 0, [Math]::Min($buffer.Length, $remaining))
            if ($got -le 0) { break }
            $keepFrom = if ($started) { 0 } else { -1 }
            $from = 0
            while ($from -lt $got) {
                $found = [Array]::IndexOf($buffer, [char]10, $from, $got - $from)
                if ($found -lt 0) { break }
                $newlines++
                $from = $found + 1
                if ($null -ne $checkpoints) {
                    $nextLine = $baseLine + $newlines
                    if (($nextLine - 1) % 200 -eq 0) { $checkpoints[$nextLine] = $start + $consumed + $from }
                }
                if (!$started -and $newlines -eq $skip) { $started = $true; $keepFrom = $from }
            }
            # 読み飛ばす行のチャンクは捨てる（行数だけ数える）
            if ($keepFrom -ge 0 -and $keepFrom -lt $got) { [void]$builder.Append($buffer, $keepFrom, $got - $keepFrom) }
            $remaining -= $got
        }
        return $builder.ToString()
    } finally {
        $stream.Dispose()
    }
}


function testIndexBookDir {
    # インデックスの中のフォルダが、元のファイルごとのフォルダ（<ファイル名.xlsx>\<場所>.tsv。本文インデックスのファイルに入れる前の TSV の置き場所）か。
    # 名前だけでは、名前が .xlsx などで終わる本物のフォルダ（元のフォルダの名前をそのまま使う）と区別できないため、中身も見る:
    #   ・名前が Office・テキストの拡張子で終わる（indexBookDirPattern）
    #   ・サブフォルダも本文インデックスのファイル（content_index.<拡張子>.tsv）も無い
    #   ・withTsv なら、TSV が 1 つ以上ある（取り込んだが中身が空のファイルのフォルダは、本文インデックスのファイルに入れるものが無い）
    # 読めないフォルダは $false（本文インデックスのファイルに入れる・消す対象にしない）
    param (
        [string]$dir,
        [bool]$withTsv = $true
    )

    if ([System.IO.Path]::GetFileName($dir.TrimEnd("\")) -notmatch ${indexBookDirPattern}) {
        return $false
    }
    $long = toLongPath $dir
    try {
        # 途中で戻っても、調べたフォルダを掴んだまま残さない（testAnyEntry・配列で受ける GetFiles）
        if (testAnyEntry ([System.IO.Directory]::EnumerateDirectories($long))) {
            return $false
        }
        $hasTsv = $false
        foreach ($file in [System.IO.Directory]::GetFiles($long, "*.tsv")) {
            if ([System.IO.Path]::GetFileName($file) -like ${contentIndexFilePattern}) {
                return $false
            }
            $hasTsv = $true
        }
        return ($hasTsv -or !$withTsv)
    } catch {
        return $false
    }
}

function getIndexFolderBooks {
    # 今の形式のインデックスのフォルダ 1 つ（直下の <ファイル名.xlsx>\<場所>.tsv）から、本文インデックスのファイルに入れる元のファイルの並びを作る。
    # 並びは今の検索結果と同じ順（前の名前の付け方（フォルダのパス + encodeIndexPlace 場所 + ".tsv"）で並べたときと同じ順に
    # なるよう、実際のファイル名（英語の固定名・符号化したシート名）から場所を戻し、その前の名前の付け方の文字列を並べ替えの鍵にする）。
    # @{ Name; Places（@{ Place; Path } の並び） } の並びを返す
    param (
        [string]$folder
    )

    $longDir = toLongPath $folder
    $entries = New-Object System.Collections.Generic.List[hashtable]
    $keys = New-Object System.Collections.Generic.List[string]
    foreach ($sub in [System.IO.Directory]::EnumerateDirectories($longDir)) {
        if (!(testIndexBookDir $sub)) {
            continue
        }
        $name = [System.IO.Path]::GetFileName($sub)
        foreach ($path in [System.IO.Directory]::GetFiles($sub, "*.tsv", [System.IO.SearchOption]::TopDirectoryOnly)) {
            # 長いパス（\\?\ 付き）は [System.IO.Path]::GetDirectoryName で崩れることがあるため、
            # ここで分かっている $sub・$name をそのまま使い、$path から作り直さない。
            $place = convertIndexFileNameToPlace ([System.IO.Path]::GetFileNameWithoutExtension($path))
            $legacyName = "{0}.tsv" -f (encodeIndexPlace $place)
            # Join-Path は \\?\ 付きの長いパスで「drive」が null というエラーになるため、
            # プロバイダーを介さない [System.IO.Path]::Combine で組み立てる。
            $key = [System.IO.Path]::Combine($sub, $legacyName)
            $entries.Add(@{ Name = $name; Place = $place; Path = $path })
            $keys.Add($key)
        }
    }
    $keyArray = $keys.ToArray()
    $entryArray = $entries.ToArray()
    [System.Array]::Sort($keyArray, $entryArray, [System.StringComparer]::CurrentCultureIgnoreCase)

    $books = New-Object System.Collections.Generic.List[hashtable]
    $current = $null
    foreach ($entry in $entryArray) {
        if (!$current -or $current.Name -ne $entry.Name) {
            $current = @{ Name = $entry.Name; Places = New-Object System.Collections.Generic.List[hashtable] }
            $books.Add($current)
        }
        $current.Places.Add(@{ Place = $entry.Place; Path = $entry.Path })
    }
    return , $books
}


function convertFolderToContentIndex {
    # 今の形式のインデックスのフォルダ 1 つ（直下の <ファイル名.xlsx>\<場所>.tsv）から、拡張子ごと・番号ごとの本文インデックスのファイル
    # （destFolder\content_index.xlsx.001.tsv など）を書く。destFolder に前の本文インデックスのファイルがあれば、それとまぜる（planContentIndexParts）:
    #   ・TSV のある元のファイルは、TSV の中身で入れ替える（前の本文インデックスのファイルに無ければ、最後の番号の本文インデックスのファイルに足す。
    #     contentIndexFileMaxBytes 以上なら次の番号の本文インデックスのファイルを作る）
    #   ・removeBooks に挙げた元のファイルは外す（元のファイルが無くなった）
    #   ・それ以外の元のファイルは、前の本文インデックスのファイルのまま。変わらない本文インデックスのファイルは書き直さない
    # 元のファイルが無くなった本文インデックスのファイルは消す。removeTsv なら、本文インデックスのファイルを書き終えた後に、
    # 読み込んだ元のファイルのフォルダ（TSV）を消す（TSV は一時的な置き場で、残すとインデックスの容量が倍になるため）。
    # 書き終える前に止まっても、TSV か前の本文インデックスのファイルのどちらかに中身が残る。
    # @{ Books; Tsv; Chars; Files（本文インデックスのファイルの数）; Written（書き直した数）;
    #    Texts（そのフォルダのすべての本文インデックスのファイルの中身。システムインデックスを読み直さずに作るため） } を返す
    param (
        [string]$folder,
        [string]$destFolder,
        [string[]]$removeBooks = @(),
        [bool]$removeTsv = $false,
        [long]$maxBytes = ${contentIndexFileMaxBytes}
    )

    $books = getIndexFolderBooks $folder
    $tsvCount = 0
    $newBooks = New-Object System.Collections.Generic.List[hashtable]
    foreach ($book in $books) {
        foreach ($place in $book.Places) {
            $place.Text = [System.IO.File]::ReadAllText($place.Path)
            $tsvCount++
        }
        $newBooks.Add(@{ Name = $book.Name; Block = (convertBookToContentIndexBlock $book) })
    }
    $longDest = toLongPath $destFolder
    # 前の本文インデックスのファイル（番号の付いた名前のもの）を読む
    $parts = New-Object System.Collections.Generic.List[hashtable]
    $oldTexts = @{}
    if ([System.IO.Directory]::Exists($longDest)) {
        foreach ($old in [System.IO.Directory]::GetFiles($longDest, ${contentIndexFilePattern})) {
            $info = readContentIndexFileName ([System.IO.Path]::GetFileName($old))
            if ($null -eq $info) { continue }
            $text = readContentIndexText $old
            $oldTexts[(getContentIndexFileName $info.Extension $info.Part)] = $text
            $parts.Add(@{ Extension = $info.Extension; Part = $info.Part; Books = (splitContentIndexTextByBook $text) })
        }
    }

    $plan = planContentIndexParts $parts $newBooks $removeBooks $maxBytes
    $texts = New-Object System.Collections.Generic.List[string]
    $bookTotal = 0
    $written = 0
    $chars = 0L
    foreach ($part in $plan) {
        $name = getContentIndexFileName $part.Extension $part.Part
        $path = Join-Path $destFolder $name
        if ($part.Books.Count -eq 0) {
            if ([System.IO.File]::Exists((toLongPath $path))) { [System.IO.File]::Delete((toLongPath $path)) }
            continue
        }
        if ($part.Changed) {
            [void][System.IO.Directory]::CreateDirectory($longDest)
            $text = convertToContentIndexText $part.Books
            writeContentIndexFile $path $text
            $written++
        } else {
            $text = $oldTexts[$name]
        }
        $texts.Add($text)
        $bookTotal += $part.Books.Count
        $chars += $text.Length
    }
    if ($removeTsv) {
        foreach ($book in $books) {
            $bookDir = [System.IO.Path]::GetDirectoryName($book.Places[0].Path)
            removeDirectoryRetry $bookDir
        }
    }
    return @{ Books = $bookTotal; Tsv = $tsvCount; Chars = $chars; Files = $texts.Count; Written = $written; Texts = [string[]]$texts.ToArray() }
}

function updateFolderContentIndex {
    # インデックスのフォルダ 1 つで、置かれた TSV（追加・更新した元のファイル）を本文インデックスのファイルに入れ、TSV を消す。
    # removeBooks に挙げた元のファイル（無くなったもの）は本文インデックスのファイルから外す
    param (
        [string]$folder,
        [string[]]$removeBooks = @()
    )

    return convertFolderToContentIndex $folder $folder $removeBooks $true
}

function findContentIndexFiles {
    # インデックスのフォルダ以下の本文インデックスのファイルを列挙し、フォルダの順・フォルダの中は名前の順に並べて返す。
    #   root   : インデックスのフォルダ（相対パスの基準）
    #   relPath: その中のフォルダ（空は root 自身）
    #   recurse: $false なら、そのフォルダの本文インデックスのファイルだけ
    # 各要素は @{ Path（\\?\ 付き）; Root; RelDir（root からのフォルダ）; RelPath; Ticks; Size }
    param (
        [string]$root,
        [string]$relPath = "",
        [bool]$recurse = $true
    )

    $root = $root.TrimEnd("\")
    $relPath = $relPath.Trim("\")
    $dir = if ($relPath) { "${root}\${relPath}" } else { $root }
    $longDir = toLongPath $dir
    if (![System.IO.Directory]::Exists($longDir)) {
        return , @()
    }
    $option = if ($recurse) { [System.IO.SearchOption]::AllDirectories } else { [System.IO.SearchOption]::TopDirectoryOnly }
    $found = [System.IO.DirectoryInfo]::new($longDir).GetFiles(${contentIndexFilePattern}, $option)
    $plainDir = fromLongPath $longDir
    $list = New-Object System.Collections.Generic.List[hashtable]
    foreach ($file in $found) {
        $full = $plainDir + $file.FullName.Substring($longDir.Length)
        $rel = $full.Substring($root.Length + 1)
        $list.Add(@{
            Path = $file.FullName; Root = $root; RelPath = $rel
            RelDir = [string][System.IO.Path]::GetDirectoryName($rel)
            Ticks = $file.LastWriteTimeUtc.Ticks; Size = $file.Length
        })
    }
    # フォルダの順、フォルダの中は本文インデックスのファイルの名前の順（現在のカルチャ・大文字と小文字を区別しない）
    $items = [hashtable[]]@($list | Sort-Object @{ Expression = { $_.RelDir } }, @{ Expression = { [System.IO.Path]::GetFileName($_.RelPath) } })
    return , $items
}


function findIndexFoldersWithBooks {
    # インデックスのフォルダ以下で、元のファイルごとのフォルダ（<ファイル名.xlsx>。本文インデックスのファイルに入れる前の TSV）が
    # 直下にあるフォルダを返す（インデックス作成が途中で止まったとき）。root 自身も含む
    param (
        [string]$root
    )

    $found = New-Object System.Collections.Generic.List[string]
    $longRoot = toLongPath $root.TrimEnd("\")
    if (![System.IO.Directory]::Exists($longRoot)) {
        return , $found.ToArray()
    }
    $dirs = @($longRoot) + @([System.IO.Directory]::GetDirectories($longRoot, "*", [System.IO.SearchOption]::AllDirectories))
    foreach ($dir in $dirs) {
        if ($dir -ne $longRoot -and (testIndexBookDir $dir $false)) { continue }
        if (testAnyEntry ([System.IO.Directory]::EnumerateDirectories($dir)) { param ($sub) testIndexBookDir $sub }) {
            $found.Add((fromLongPath $dir))
        }
    }
    return , $found.ToArray()
}


function publishIndexFolders {
    # インデックス作成で TSV を置いた・元のファイルが無くなったフォルダを、まとめて書き出す。フォルダごとに次を続けて行う:
    #   1. 本文インデックスのファイルを書く（前の本文インデックスのファイルとまぜ、無くなった元のファイルは外す）
    #   2. 元のファイルごとのフォルダの TSV を消す
    #   3. 書いた本文インデックスのファイルの中身から、そのフォルダのシステムインデックスの txt を作る（読み直さない）
    # txt の状態（反映待ち）はまとめて状態ファイルに書く。書き出したフォルダの数を返す。
    #   pending: フォルダ（フルパス）→ 無くなった元のファイル名の集まり
    param (
        $pending,
        [string]$indexRoot = $workspace.IndexDir,
        [string]$systemRoot = $workspace.SystemIndexDir,
        [string]$statePath = $workspace.SystemIndexStateFile
    )

    $results = New-Object System.Collections.Generic.List[hashtable]
    foreach ($folder in @($pending.Keys)) {
        $contentIndexFile = updateFolderContentIndex $folder ([string[]]@($pending[$folder]))
        # 書いた本文インデックスのファイルは、フォルダごとに書いた直後にここで NotContentIndexed を付ける（件数が多いため失敗してもログに出さない）
        [void](setNotContentIndexed $folder)
        $results.Add((writeSystemIndexFolder $folder $indexRoot $systemRoot $contentIndexFile.Texts))
    }
    if ($results.Count -gt 0) {
        $saved = updateSystemIndexState { param ($state) setSystemIndexResults $state $results.ToArray() } $statePath
        if (!$saved) {
            writeIndexerLog "システムインデックスの状態を書き込めませんでした（インデックス作成の終わりに作り直します）。" "Yellow"
        }
    }
    return $results.Count
}


function readContentIndexLines {
    # 本文インデックスのファイルの中の、元のファイル book・場所 location の firstLine 行目から count 行を返す（画面の選択行のプレビュー。
    # 行の数え方は検索と同じ）。戻り値は @{ Rows = @{ LineNumber; Line } の配列; End = 頼んだ数より少なく返ったか（場所の終わりまで読んだ）; Marks = 更新した控え }。
    # cache（検索のキャッシュ）に同じ本文インデックスのファイルの内容があれば、ファイルを読み直さない。読めない・見つからなければ Rows は空・End は $true。
    #
    # marks は、繰り返し読むときに先頭から読み飛ばさないための控え（@{ Path; Ticks; Size; Places; Checkpoints }。
    # ファイルのパス・更新日時・大きさが同じ間だけ使う）。呼び出し側が引数で渡し、戻り値の Marks で受け取る
    # （読み足しは別の runspace で動くため、$script: には置かない。渡された控えは書き換えず、新しいものを返す）。
    # Places は場所の一覧、Checkpoints は場所ごと（Book と Location をタブでつないだ名前）の、200 行ごとの行の先頭の位置（行の番号 → 文字の位置）
    param (
        [string]$path,
        [string]$book,
        [string]$location,
        [int]$firstLine,
        [int]$count,
        $cache = $null,
        $marks = $null
    )

    $first = [Math]::Max(1, $firstLine)
    $last = $first + $count - 1
    if ($count -le 0) { return @{ Rows = @(); End = $false; Marks = $marks } }
    $nothing = @{ Rows = @(); End = $true; Marks = $marks }
    $text = $null
    $places = $null
    $longPath = toLongPath $path
    $entry = $null
    if ($null -ne $cache -and $cache.Texts.TryGetValue($longPath, [ref]$entry) -and $entry.Count -ge 4) {
        $info = [System.IO.FileInfo]::new($longPath)
        if ($info.Exists -and $entry[0] -eq $info.LastWriteTimeUtc.Ticks -and $entry[1] -eq $info.Length) {
            $text = $entry[2]
            $places = $entry[3]
        }
    }
    $isRange = $false
    $newMarks = $marks
    $checkpoints = $null
    $allCheckpoints = $null
    $placeKey = "$book`t$location"
    try {
        if ($null -eq $text) {
            # キャッシュに無いときは、ファイルの全体を文字列にしない。控えがあれば、その場所の目当ての行の手前の位置から必要な行までだけを読む
            # （続けて読むたびに、全体を読み直さず、場所の先頭からも読み飛ばさない）
            $info = [System.IO.FileInfo]::new($longPath)
            if (!$info.Exists) { return $nothing }
            if ($null -ne $marks -and $marks.Path -eq $longPath -and $marks.Ticks -eq $info.LastWriteTimeUtc.Ticks -and $marks.Size -eq $info.Length) {
                $places = $marks.Places
                $allCheckpoints = $(if ($null -ne $marks.Checkpoints) { $marks.Checkpoints.Clone() } else { @{} })
                $found = $false
                foreach ($place in $places) {
                    if ($place.Book -ne $book -or $place.Location -ne $location) { continue }
                    $found = $true
                    # 位置は場所ごとに控える（行の番号が同じでも、別の場所の位置は使わない）
                    $checkpoints = $(if ($allCheckpoints.ContainsKey($placeKey)) { $allCheckpoints[$placeKey].Clone() } else { @{} })
                    $allCheckpoints[$placeKey] = $checkpoints
                    $base = 1
                    $startPosition = $place.Start
                    foreach ($key in $checkpoints.Keys) {
                        if ($key -le $first -and $key -gt $base) { $base = $key; $startPosition = $checkpoints[$key] }
                    }
                    $text = readContentIndexRange $path $startPosition $place.End ($first - $base + 1) ($last - $base + 1) $base $checkpoints
                    break
                }
                # 控えが今のファイルのものなら、無い場所はファイルを読まずに空
                if (!$found) { return $nothing }
                if ($null -ne $text) {
                    # 読んでいる間にファイルが置き換わっていたら、古い位置で読んだ行は使わず、全体を読み直す
                    $again = [System.IO.FileInfo]::new($longPath)
                    if ($again.Exists -and $again.LastWriteTimeUtc.Ticks -eq $info.LastWriteTimeUtc.Ticks -and $again.Length -eq $info.Length) { $isRange = $true } else { $text = $null }
                }
            }
            if ($null -eq $text) {
                $text = readContentIndexText $path
                $places = readContentIndexPlaces $text
                $checkpoints = @{}
                $allCheckpoints = @{ $placeKey = $checkpoints }
            }
            $newMarks = @{ Path = $longPath; Ticks = $info.LastWriteTimeUtc.Ticks; Size = $info.Length; Places = $places; Checkpoints = $allCheckpoints }
        }
    } catch [System.IO.IOException] {
        return $nothing
    } catch [System.UnauthorizedAccessException] {
        return $nothing
    }
    $rows = New-Object System.Collections.Generic.List[psobject]
    $isTextBook = (getContentIndexFileKind $book) -eq "テキスト"
    foreach ($place in $places) {
        if ($place.Book -ne $book -or $place.Location -ne $location) { continue }
        # 範囲だけ読んだときは、text の先頭が $first 行目の先頭
        $number = if ($isRange) { $first - 1 } else { 0 }
        $placeEnd = if ($isRange) { $text.Length } else { [Math]::Min($place.End, $text.Length) }
        $pos = if ($isRange) { 0 } else { $place.Start }
        # ファイルの全体を読んだときは、通った 200 行ごとの行の先頭を控える（範囲を読んだときは readContentIndexRange が控える）
        $record = !$isRange -and $null -ne $checkpoints
        while ($pos -lt $placeEnd) {
            $n = $text.IndexOf([char]10, $pos, $placeEnd - $pos)
            if ($n -lt 0) { $n = $placeEnd }
            $number++
            if ($record -and $number -gt 1 -and ($number - 1) % 200 -eq 0) { $checkpoints[$number] = $pos }
            if ($number -gt $last) { break }
            if ($number -ge $first) {
                $line = $text.Substring($pos, $n - $pos)
                if ($isTextBook) {
                    # 前後の行はどこが一致したかが分からないため、先頭から切る
                    $line = truncateHitLine $line -1
                }
                $rows.Add([pscustomobject]@{ LineNumber = $number; Line = $line })
            }
            $pos = $n + 1
        }
        break
    }
    return @{ Rows = $rows.ToArray(); End = ($rows.Count -lt $count); Marks = $newMarks }
}


# システムインデックス（system_index の txt）と、その状態ファイル（system_index_state.tsv）の読み書き（状態層）。
# txt は index の中のフォルダ 1 つにつき 1 つ（分けたときは複数）で、index と同じ相対パスの system_index の中に置く。
# 中身は、そのフォルダ直下の本文インデックスのファイル（content_index.<拡張子>.tsv）と、インデックス作成の途中で残った、直下のブックのフォルダ（<ファイル名.xlsx>）の中の TSV から作る（search_gram.ps1）。
# 本文インデックスのファイルのメタ情報の行は除く（getContentIndexBodyText）。

function getSystemIndexFolderTsvPaths {
    # index の中のフォルダ 1 つの、システムインデックスの元になるファイル（直下の本文インデックスのファイル・TSV と、直下のブックのフォルダの中の TSV。\\?\ 付き）。
    # 検索対象のツリーで「フォルダ直下のファイル」を選んだときと同じ範囲（getContentIndexFiles の Recurse = $false）
    param (
        [string]$folder
    )

    $long = toLongPath $folder
    $paths = New-Object System.Collections.Generic.List[string]
    if (![System.IO.Directory]::Exists($long)) {
        return , $paths.ToArray()
    }
    $paths.AddRange([System.IO.Directory]::GetFiles($long, "*.tsv"))
    foreach ($sub in [System.IO.Directory]::GetDirectories($long)) {
        if (testIndexBookDir $sub) {
            $paths.AddRange([System.IO.Directory]::GetFiles($sub, "*.tsv"))
        }
    }
    return , $paths.ToArray()
}

function writeSystemIndexFolder {
    # index の中のフォルダ 1 つについて、system_index の txt を作り直す。
    # @{ Rel（index からの相対パス）; Files（@{ Rel（system_index からの txt の相対パス）; Ticks（更新日時。UTC の Ticks） } の配列）;
    #    Excluded（パスが長すぎて作らなかった） } を返す。本文インデックスのファイル・TSV が無くなったフォルダは txt を消して Files を空で返す
    #   texts: そのフォルダの本文インデックスのファイルの中身（インデックス作成で書いたばかりのもの）。渡せばファイルを読み直さない
    param (
        [string]$folder,
        [string]$indexRoot,
        [string]$systemRoot,
        [string[]]$texts = $null
    )

    $rel = $folder.Substring($indexRoot.TrimEnd("\").Length).Trim("\")
    $outDir = "$($systemRoot.TrimEnd('\'))\$rel"
    $longOut = toLongPath $outDir
    $result = @{ Rel = $rel; Files = @(); Excluded = $false }

    # 前の txt（分けた数が変わることもあるため、すべて）を消す
    if ([System.IO.Directory]::Exists($longOut)) {
        foreach ($old in [System.IO.Directory]::GetFiles($longOut, "$([System.IO.Path]::GetFileNameWithoutExtension(${systemIndexFileName}))*.txt")) {
            [System.IO.File]::Delete($old)
        }
    }
    $set = New-Object 'System.Collections.Generic.HashSet[uint32]'
    if ($null -ne $texts) {
        if ($texts.Count -eq 0) {
            return $result
        }
        foreach ($text in $texts) {
            addTextGrams $set (getContentIndexBodyText $text)
        }
    } else {
        $tsvPaths = getSystemIndexFolderTsvPaths $folder
        if ($tsvPaths.Count -eq 0) {
            return $result
        }
        foreach ($path in $tsvPaths) {
            $text = [System.IO.File]::ReadAllText($path)
            if ([System.IO.Path]::GetFileName($path) -like ${contentIndexFilePattern}) {
                $text = getContentIndexBodyText $text
            }
            addTextGrams $set $text
        }
    }
    $values = New-Object 'uint32[]' $set.Count
    $set.CopyTo($values)
    [Array]::Sort($values)
    $parts = getGramPartCount $values.Length
    if (!(testSystemIndexPath $outDir $parts)) {
        $result.Excluded = $true
        return $result
    }

    [System.IO.Directory]::CreateDirectory($longOut) | Out-Null
    $perPart = [int][Math]::Ceiling($values.Length / $parts)
    $names = getSystemIndexFileNames $parts
    $files = New-Object System.Collections.Generic.List[hashtable]
    for ($p = 0; $p -lt $parts; $p++) {
        $start = $p * $perPart
        $text = convertToGramText $values $start ([Math]::Min($perPart, $values.Length - $start))
        $path = "$longOut\$($names[$p])"
        [System.IO.File]::WriteAllText($path, $text, [System.Text.Encoding]::ASCII)
        $files.Add(@{ Rel = "$rel\$($names[$p])"; Ticks = [System.IO.File]::GetLastWriteTimeUtc($path).Ticks })
    }
    $result.Files = $files.ToArray()
    return $result
}

# txt をまとめて作るときのスレッドの数の上限（物理メモリ 8GB の PC で 4 スレッドのときにメモリが足りなくなったことがあるため）
${systemIndexWorkerMax} = 4

function writeSystemIndexFolders {
    # index の中のフォルダの txt を、まとめて作り直す（並列）。writeSystemIndexFolder の結果の配列を返す。
    #   shouldStop: $true を返すと、始めていない分を作らずに止める（作った分だけを返す）
    param (
        [string[]]$folders,
        [string]$indexRoot,
        [string]$systemRoot,
        [int]$workers = 0,
        [scriptblock]$shouldStop = $null
    )

    $results = New-Object System.Collections.Generic.List[hashtable]
    if ($folders.Count -eq 0) {
        return , $results.ToArray()
    }
    if ($workers -le 0) {
        $workers = [Math]::Min([Environment]::ProcessorCount, ${systemIndexWorkerMax})
    }
    $workers = [Math]::Min($workers, $folders.Count)
    if ($workers -le 1) {
        foreach ($folder in $folders) {
            if ($shouldStop -and (& $shouldStop)) {
                break
            }
            $results.Add((writeSystemIndexFolder $folder $indexRoot $systemRoot))
        }
        return , $results.ToArray()
    }

    # 各スレッドには必要な関数・値だけを読み込む（lib.ps1 全体を読み込むと、スレッドを用意するだけで時間がかかるため）。
    # インデックス作成の処理のため、スレッドの優先度を下げる（画面・検索を先に動かす。docs/design/structure/threads.md「スレッドの一覧」）
    $state = newWorkerState @("writeSystemIndexFolder", "getSystemIndexFolderTsvPaths", "addTextGrams", "convertToGramText",
        "getGramPartCount", "getSystemIndexFileNames", "testSystemIndexPath", "toLongPath", "getContentIndexBodyText", "testIndexBookDir", "testAnyEntry") `
        @("systemIndexFileName", "systemIndexPartBytes", "systemIndexPathMax", "indexBookDirPattern", "contentIndexFilePattern")
    $pool = [WorkerPool]::new($workers, $state, $Host, "BelowNormal")
    $pending = New-Object System.Collections.Generic.Queue[hashtable]
    $jobScript = {
        param ($folder, $indexRoot, $systemRoot)
        # 別スレッドは既定では .NET の例外で止まらず、書けなかった txt を作ったものとして返してしまう。例外で止めて呼び出し元に伝える
        $ErrorActionPreference = "Stop"
        @{ Result = writeSystemIndexFolder $folder $indexRoot $systemRoot }
    }.ToString()
    try {
        $next = 0
        while ($next -lt $folders.Count -or $pending.Count -gt 0) {
            # スレッド数の 2 倍まで先に始めておき、終わった順ではなく始めた順に受け取る
            while ($pending.Count -lt $workers * 2 -and $next -lt $folders.Count) {
                if ($shouldStop -and (& $shouldStop)) {
                    $next = $folders.Count
                    break
                }
                $pending.Enqueue($pool.Submit($jobScript, @($folders[$next], $indexRoot, $systemRoot)))
                $next++
            }
            if ($pending.Count -eq 0) {
                break
            }
            $output = $pool.Receive($pending.Dequeue())
            if ($output.Count -gt 0) {
                $results.Add($output[0].Result)
            }
        }
    } finally {
        foreach ($job in $pending) {
            $pool.Cancel($job)
        }
        $pool.Close()
    }
    return , $results.ToArray()
}

function readSystemIndexState {
    # 状態ファイルを読む（convertFromSystemIndexState の形）。無ければ空。
    # 書き込み中などで読めなければ $null（高速検索を使わず、すべてを照合する）
    param (
        [string]$path = $workspace.SystemIndexStateFile
    )

    if (![System.IO.File]::Exists($path)) {
        return newSystemIndexState
    }
    for ($i = 1; $i -le 10; $i++) {
        try {
            $stream = [System.IO.FileStream]::new($path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read)
            try {
                $reader = [System.IO.StreamReader]::new($stream, [System.Text.Encoding]::UTF8, $true)
                return convertFromSystemIndexState ($reader.ReadToEnd() -split "\r?\n")
            } finally {
                $stream.Dispose()
            }
        } catch [System.IO.IOException] {
            Start-Sleep -Milliseconds 100
        }
    }
    return $null
}

function updateSystemIndexState {
    # 状態ファイルを排他で開き、change（{ param($state) }）で書き換えて保存する。
    # インデクサ（取り込み）と画面（検索のたびの整理）が同時に書かないよう、開いている間はほかから開けない。
    # 開けなければ少し待って数回試し、それでも開けなければ $false を返す（書き換えは次の機会に回る）
    param (
        [scriptblock]$change,
        [string]$path = $workspace.SystemIndexStateFile
    )

    [System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($path)) | Out-Null
    $stream = $null
    for ($i = 1; $i -le 20 -and $null -eq $stream; $i++) {
        try {
            $stream = [System.IO.FileStream]::new($path, [System.IO.FileMode]::OpenOrCreate, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None)
        } catch [System.IO.IOException] {
            Start-Sleep -Milliseconds 100
        }
    }
    if ($null -eq $stream) {
        return $false
    }
    try {
        $reader = [System.IO.StreamReader]::new($stream, [System.Text.Encoding]::UTF8, $true, 4096, $true)
        $state = convertFromSystemIndexState ($reader.ReadToEnd() -split "\r?\n")
        $reader.Dispose()
        & $change $state
        $bytes = ${utf8Bom}.GetPreamble() + ${utf8Bom}.GetBytes(((convertToSystemIndexState $state) -join "`r`n") + "`r`n")
        $stream.SetLength(0)
        $stream.Write($bytes, 0, $bytes.Length)
    } finally {
        $stream.Dispose()
    }
    return $true
}

function removeSystemIndexEntries {
    # 状態から、相対パス rel のフォルダ（とその中）の行を消す。indexName を渡したら、そのインデックスの「対応済み」も消す
    param (
        $state,
        [string]$rel,
        [string]$indexName = ""
    )

    foreach ($key in @($state.Pending.Keys)) {
        if ($key.StartsWith("$rel\", [System.StringComparison]::OrdinalIgnoreCase)) {
            [void]$state.Pending.Remove($key)
        }
    }
    foreach ($key in @($state.Excluded)) {
        if ($key.Equals($rel, [System.StringComparison]::OrdinalIgnoreCase) -or $key.StartsWith("$rel\", [System.StringComparison]::OrdinalIgnoreCase)) {
            [void]$state.Excluded.Remove($key)
        }
    }
    if ($indexName) {
        [void]$state.Covered.Remove($indexName)
    }
}

function setSystemIndexResults {
    # writeSystemIndexFolder の結果を状態に書く（フォルダの前の行は消して、作った txt を反映待ちにする）
    param (
        $state,
        [object[]]$results
    )

    foreach ($result in $results) {
        # フォルダ直下の txt の行だけを消す（サブフォルダの行は、サブフォルダの結果で書き換わる）
        foreach ($key in @($state.Pending.Keys)) {
            if ([System.IO.Path]::GetDirectoryName($key) -eq $result.Rel) {
                [void]$state.Pending.Remove($key)
            }
        }
        [void]$state.Excluded.Remove($result.Rel)
        foreach ($file in $result.Files) {
            $state.Pending[$file.Rel] = $file.Ticks
        }
        if ($result.Excluded) {
            [void]$state.Excluded.Add($result.Rel)
        }
    }
}

function markSystemIndexChanged {
    # TSV を入れ替えたフォルダを「反映待ち（日時は 0）」にする（txt を作り直すまで、そのフォルダは .NET で照合させる）。
    # 0 は txt の更新日時とも Windows Search の DateModified とも一致しないため、前の txt が索引されていても反映済みにならない
    # （今の日時にすると、txt を書いたのと同じ秒の中では一致して、反映済みと取り違える）
    param (
        [string[]]$rels,
        [string]$path = $workspace.SystemIndexStateFile
    )

    return updateSystemIndexState {
        param ($state)
        foreach ($rel in $rels) {
            $state.Pending["$rel\${systemIndexFileName}"] = 0
        }
    } $path
}

function getSystemIndexStaleFolders {
    # txt の作り直しが要る index の中のフォルダ（フルパス）を返す。
    #   txt が無い・TSV より古い・状態が「反映待ち」なのに txt の更新日時と合わない（取り込みの途中で止まった）もの
    param (
        [string]$indexRoot,
        [string]$systemRoot,
        $state
    )

    $stale = New-Object System.Collections.Generic.List[string]
    $longRoot = toLongPath $indexRoot
    if (![System.IO.Directory]::Exists($longRoot)) {
        return , $stale.ToArray()
    }
    $rootLength = $indexRoot.TrimEnd("\").Length
    foreach ($longDir in [System.IO.Directory]::EnumerateDirectories($longRoot, "*", [System.IO.SearchOption]::AllDirectories)) {
        # 元のファイルごとのフォルダ（本文インデックスにする前の TSV・中身が空のファイル）は、親のフォルダの txt に入る
        if (testIndexBookDir $longDir $false) {
            continue
        }
        $folder = fromLongPath $longDir
        $rel = $folder.Substring($rootLength).Trim("\")
        if ($state.Excluded.Contains($rel)) {
            continue
        }
        $tsvPaths = getSystemIndexFolderTsvPaths $folder
        $txtDir = toLongPath "$($systemRoot.TrimEnd('\'))\$rel"
        $txts = if ([System.IO.Directory]::Exists($txtDir)) { @([System.IO.Directory]::GetFiles($txtDir, "$([System.IO.Path]::GetFileNameWithoutExtension(${systemIndexFileName}))*.txt")) } else { @() }
        if ($tsvPaths.Count -eq 0) {
            if ($txts.Count -gt 0) {
                $stale.Add($folder)   # TSV が無くなった（txt を消す）
            }
            continue
        }
        if ($txts.Count -eq 0) {
            $stale.Add($folder)
            continue
        }
        $oldest = ($txts | ForEach-Object { [System.IO.File]::GetLastWriteTimeUtc($_) } | Measure-Object -Minimum).Minimum
        $newestTsv = ($tsvPaths | ForEach-Object { [System.IO.File]::GetLastWriteTimeUtc($_) } | Measure-Object -Maximum).Maximum
        $marked = $state.Pending.ContainsKey("$rel\${systemIndexFileName}") -and
            $state.Pending["$rel\${systemIndexFileName}"] -ne [System.IO.File]::GetLastWriteTimeUtc("$txtDir\${systemIndexFileName}").Ticks
        if ($newestTsv -gt $oldest -or $marked) {
            $stale.Add($folder)
        }
    }
    return , $stale.ToArray()
}

function updateSystemIndexes {
    # インデックス作成の終わりに、システムインデックスの作り直しが要るフォルダをまとめて作り直し、状態ファイルに書く。
    # すべてのフォルダの txt がそろったインデックスは「対応済み」にする（対応済みでないインデックスは、高速検索でもすべてを照合する）。
    # 利用者の作業の邪魔にならないよう、作るスレッドの優先度を下げる（writeSystemIndexFolders）。shouldStop が $true を返せば、始めていない分は作らない。
    # 作り直したフォルダの数と、作り終えていないインデックスの数を @{ Built; Unfinished } で返す
    param (
        [string]$indexRoot = $workspace.IndexDir,
        [string]$systemRoot = $workspace.SystemIndexDir,
        [string]$statePath = $workspace.SystemIndexStateFile,
        [scriptblock]$shouldStop = $null
    )

    $state = readSystemIndexState $statePath
    if ($null -eq $state) {
        writeIndexerLog "システムインデックスの状態を読めないため、作り直しは次のインデックス作成に回します。" "Yellow"
        return @{ Built = 0; Unfinished = -1 }
    }
    # 無くなったインデックス（設定から外した・画面で削除した）の txt と状態の行を消す
    $names = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    if ([System.IO.Directory]::Exists((toLongPath $indexRoot))) {
        foreach ($dir in [System.IO.Directory]::GetDirectories((toLongPath $indexRoot))) {
            [void]$names.Add([System.IO.Path]::GetFileName($dir))
        }
    }
    $gone = New-Object System.Collections.Generic.List[string]
    if ([System.IO.Directory]::Exists((toLongPath $systemRoot))) {
        foreach ($dir in [System.IO.Directory]::GetDirectories((toLongPath $systemRoot))) {
            $gone.Add([System.IO.Path]::GetFileName($dir))
        }
    }
    $gone.AddRange([string[]]@($state.Covered))
    foreach ($name in ($gone | Sort-Object -Unique)) {
        if (!$names.Contains($name)) {
            [void](removeSystemIndexOf $name $systemRoot $statePath)
            [void]$state.Covered.Remove($name)
        }
    }

    $stale = getSystemIndexStaleFolders $indexRoot $systemRoot $state
    $results = @()
    if ($stale.Count -gt 0) {
        writeIndexerLog "システムインデックス（高速検索用）を作っています…（$($stale.Count) フォルダ）"
        $results = writeSystemIndexFolders $stale $indexRoot $systemRoot 0 $shouldStop

    }
    # 作り終えていないフォルダがあるインデックスは、対応済みにしない
    $built = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($result in $results) {
        [void]$built.Add($result.Rel)
    }
    $unfinished = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    $rootLength = $indexRoot.TrimEnd("\").Length
    foreach ($folder in $stale) {
        $rel = $folder.Substring($rootLength).Trim("\")
        if (!$built.Contains($rel)) {
            [void]$unfinished.Add((getIndexNameOfRelPath $rel))
        }
    }
    $saved = updateSystemIndexState {
        param ($current)
        setSystemIndexResults $current $results
        foreach ($name in $names) {
            if ($unfinished.Contains($name)) {
                [void]$current.Covered.Remove($name)
            } else {
                [void]$current.Covered.Add($name)
            }
        }
    } $statePath
    if (!$saved) {
        writeIndexerLog "システムインデックスの状態を書き込めなかったため、次のインデックス作成で作り直します。" "Yellow"
    } elseif ($unfinished.Count -gt 0) {
        writeIndexerLog "中止したため、システムインデックスの一部（$($stale.Count - $built.Count) フォルダ）は次のインデックス作成で作ります。" "Yellow"
    }
    return @{ Built = $built.Count; Unfinished = $unfinished.Count }
}

function removeSystemIndexOf {
    # インデックス（または index の中のフォルダ）を消したとき、system_index の同じフォルダと状態の行を消す
    param (
        [string]$rel,
        [string]$systemRoot = $workspace.SystemIndexDir,
        [string]$path = $workspace.SystemIndexStateFile
    )

    $dir = toLongPath "$($systemRoot.TrimEnd('\'))\$rel"
    if ([System.IO.Directory]::Exists($dir)) {
        removeDirectoryRetry "$($systemRoot.TrimEnd('\'))\$rel"
    }
    $name = getIndexNameOfRelPath $rel
    $indexName = if ($name -eq $rel) { $name } else { "" }
    return updateSystemIndexState { param ($state) removeSystemIndexEntries $state $rel $indexName } $path
}

# インデックス作成の状態（取り込み一覧・取り込み中のファイル）の読み書きと、画面とインデクサの受け渡しの口・ログ。

# 1ファイルの取り込みの制限時間（分）。超えたらOfficeアプリを強制終了し、そのファイルは失敗とする（クラウドからのダウンロードも含む。確認の文言も同じ値を使う）
${ingestFileTimeoutMinutes} = 10

function describeIngestError {
    # 取り込みで発生した例外から、取り込み一覧のエラー列・画面に表示する失敗の理由を返す。
    # Officeアプリのメッセージは分かりにくい（パスワード付きでも「入力したパスワードが間違っています」等）ため、
    # よくある原因は「原因（詳細: 元のメッセージ）」の形に言い換える
    param (
        [System.Exception]$exception
    )

    # メソッド呼び出しの例外（「"7" 個の引数を指定して "Open" を呼び出し中に例外が発生しました」等）は、中の例外が本来の理由
    $base = $exception.GetBaseException()
    $message = ($base.Message -replace "\s+", " ").Trim()
    $code = "{0:X8}" -f $base.HResult
    if ($message -eq "") {
        $message = "エラーコード 0x${code}"
    }

    # スクリプト自身が throw したメッセージは、利用者向けに書いてあるためそのまま使う
    if ($base.GetType() -eq [System.Management.Automation.RuntimeException]) {
        return $message
    }

    if ($message -match "パスワード|password") {
        # 元のメッセージ（パスワードが間違っています等）は、パスワードを入力していない利用者には誤解を招くため付けない
        return "読み取りパスワードが設定されているため開けません（パスワード付きのファイルは更新できません）"
    }

    $cause = $null
    if ($base -is [System.IO.FileNotFoundException] -or $base -is [System.IO.DirectoryNotFoundException]) {
        $cause = "ファイルが見つかりません（更新中に移動・削除・名前変更された可能性があります）"
    } elseif ($base -is [System.UnauthorizedAccessException] -or $code -eq "80070005") {
        $cause = "ファイルを読むアクセス権がありません"
    } elseif ($base -is [System.IO.PathTooLongException]) {
        $cause = "パスが長すぎるため読めません"
    } elseif ($base -is [System.OutOfMemoryException]) {
        # 巨大なシート（テキストにして約 1GB 超）は、整形（prettyTsv）で一度に読み込めずメモリ不足になる
        $cause = "シート・文書が大きすぎて更新できません（メモリが不足しました）"
    } elseif (@("80070020", "80070021") -contains $code) {
        # 共有違反・ロック違反
        $cause = "ほかのアプリ・利用者がファイルを使用中のため読めません（ファイルを閉じてから再度更新してください）"
    } elseif (@("80040154", "80080005", "800401F3") -contains $code) {
        # クラス未登録・サーバーの起動失敗・ProgID 不正
        $cause = "Officeアプリ（Excel・Word・PowerPoint）を起動できませんでした（インストール・ライセンス認証の状態を確認してください）"
    } elseif (@("800706BA", "800706BE", "80010105", "80010108") -contains $code) {
        # RPC サーバーを利用できない・呼び出し失敗・サーバーで例外・切断
        $cause = "Officeアプリが異常終了したか、内部でエラーが発生しました（ファイルが壊れている、または大きすぎる可能性があります）"
    } elseif (@("80010001", "8001010A") -contains $code) {
        # 呼び出しの拒否・処理中のため後で再試行
        $cause = "Officeアプリが応答しませんでした（Officeアプリでダイアログを表示中などの可能性があります）"
    } elseif ($base -is [System.IO.InvalidDataException] -or $base -is [System.Xml.XmlException] -or
              $message -match "ファイル形式|破損|壊れ|corrupt|file format") {
        $cause = "ファイルが壊れているか、拡張子と中身の形式が一致していません"
    }

    if ($cause) {
        return "${cause}（詳細: ${message}）"
    }
    return $message
}

function addStatusRow {
    # 取り込み一覧の末尾に1行追記する（readStatusFile では後の行が優先される）
    param (
        $row,
        [string]$path = $workspace.StatusFile
    )

    [System.IO.File]::AppendAllText($path, "$(toStatusLine $row)`r`n", ${utf8Bom})
}

function readIngestingFiles {
    # 取り込み中のファイルの記録を読み、@{ RelPath = 相対パス; Count = 続けて取り込みを始めて終わらなかった回数 } の配列を返す。
    # 取り込みを複数のスレッドで行うため、1 行に 1 ファイル。記録が無ければ空。壊れた行は読み飛ばす
    param (
        [string]$path = $workspace.IngestingFile
    )

    $result = New-Object System.Collections.Generic.List[hashtable]
    foreach ($line in @(readListFile $path)) {
        $fields = $line.Split("`t")
        $count = 0
        if ($fields.Count -ne 2 -or -not [int]::TryParse($fields[0], [ref]$count) -or $count -lt 1 -or $fields[1] -eq "") {
            continue
        }
        $result.Add(@{ RelPath = $fields[1]; Count = $count })
    }
    return , $result.ToArray()
}

function writeIngestingFiles {
    # 取り込み中のファイル（@{ RelPath; Count } の並び）を "回数<TAB>相対パス" で記録する。無ければ記録を消す
    param (
        [object[]]$entries,
        [string]$path = $workspace.IngestingFile
    )

    $lines = @($entries | Where-Object { $_ } | ForEach-Object { "$($_.Count)`t$($_.RelPath)" })
    if ($lines.Count -eq 0) {
        removeIngestingFile $path
        return
    }
    writeListFile $path $lines
}

function removeIngestingFile {
    param (
        [string]$path = $workspace.IngestingFile
    )

    if (Test-Path -LiteralPath $path) {
        Remove-Item -LiteralPath $path -Force
    }
}

# ----------------------------------------------------------------------------
# 画面（または indexer.ps1）とインデクサの受け渡しの口（docs/design/structure/threads.md「画面とインデクサの受け渡し」）
# ----------------------------------------------------------------------------

function newIndexerChannel {
    # 受け渡しの口を作る。画面とインデクサのスレッドの両方から読み書きするため Synchronized にする。
    #   画面が書く      : RetryFailed・IncludeCloud（クラウドにだけあるファイルもダウンロードして取り込むか）・ConfirmTargets・Workers（取り込みのスレッドの数。0 は司令のスレッドで取り込む、-1 は設定・コア数から決める）・Stop・Answer・
    #                     OnlyNames（更新するインデックス名の配列。空なら、チェックの付いたものすべて）
    #   インデクサが書く: Progress（readIndexingProgress の形）・Plan（取り込み予定）・Error・ExitCode（0 完了 / 1 エラー / 2 中止）・
    #                     CloudSkipped（クラウドにだけあるため、ダウンロードせずに残した件数）・
    #                     OnlySkipped（OnlyNames のうち、更新できなかった名前の @{ Name; Reason } の配列）
    #   OfficePids: インデックス作成が起動した Office の PID → @{ ProcessName; StartTicks }（閉じるときに止まらなければ、名前と起動時刻が合う PID だけを止める）
    #   UserOfficePids: 取り込み中に見える窓があった（利用者が使った）PowerPoint の PID → @{ ProcessName; StartTicks }（制限時間を過ぎても、閉じるときも止めない）
    param (
        [bool]$retryFailed = $false,
        [bool]$confirmTargets = $false,
        [int]$workers = -1,
        [string[]]$onlyNames = @(),
        [bool]$includeCloud = $false
    )

    return [hashtable]::Synchronized(@{
        RetryFailed = $retryFailed; IncludeCloud = $includeCloud; ConfirmTargets = $confirmTargets; Workers = $workers
        OnlyNames = @($onlyNames | Where-Object { $_ }); OnlySkipped = @()
        Progress = $null; Stop = $false
        Plan = $null; Answer = $null; Answered = New-Object System.Threading.ManualResetEvent($false)
        Error = ""; ExitCode = $null; CloudSkipped = 0
        OfficePids = New-Object 'System.Collections.Concurrent.ConcurrentDictionary[int,object]'
        UserOfficePids = New-Object 'System.Collections.Concurrent.ConcurrentDictionary[int,object]'
    })
}

# いま動いているインデックス作成の受け渡しの口（invokeIndexer が入れる。$null なら進み具合を伝えない）
$script:indexerChannel = $null

function writeIndexingProgress {
    # インデックス作成の進み具合を受け渡しの口に入れる（画面が 1 秒ごとに読む）
    param (
        [string]$phase,
        [int]$processed = 0,
        [int]$remaining = 0,
        [int]$failed = 0,
        [string]$detail = "",
        $channel = $script:indexerChannel
    )

    if ($null -ne $channel) {
        $channel.Progress = @{ Phase = $phase; Processed = $processed; Remaining = $remaining; Failed = $failed; Detail = ($detail -replace "[\t\r\n]+", " ") }
    }
}

function readIndexingProgress {
    # インデックス作成の進み具合（@{ Phase; Processed; Remaining; Failed; Detail }）を返す。まだ無ければ $null
    param (
        $channel
    )

    if ($null -eq $channel) {
        return $null
    }
    return $channel.Progress
}

function requestIndexingStop {
    # 中止を求める。取り込みはファイルの切れ目で止まる。確認を待っていれば、取りやめの返事にする
    param (
        $channel
    )

    $channel.Stop = $true
    [void]$channel.Answered.Set()
}

function answerIndexingPlan {
    # 確認の返事を返す。取り込む → @{ RetryFailed; IncludeCloud } ／ 取りやめ → $null
    param (
        $channel,
        $answer
    )

    $channel.Answer = $answer
    if ($null -eq $answer) {
        $channel.Stop = $true
    }
    [void]$channel.Answered.Set()
}

function testIndexerRunning {
    # この work でインデックス作成が動いているか（画面のスレッド・画面を使わない indexer.ps1 のどちらでも）。
    # インデックス作成が持つ鍵（newAppMutex "indexer"）を取れるかで調べ、取れたらすぐ放す
    param (
        [string]$dir = $workspace.Dir
    )

    $mutex = newAppMutex "indexer" $dir
    try {
        return !$mutex.Acquired
    } finally {
        if ($mutex.Acquired) {
            $mutex.Mutex.ReleaseMutex()
        }
        $mutex.Mutex.Dispose()
    }
}

function writeZipSizeLimitLog {
    # .docx・.pptx・.xlsx の部品がサイズの上限を超えたときの詳細をログに書く（画面には出さない）。
    # 原因を調べられるよう、部品名・大きさ・部品ごとか合計かはここだけに書く。
    # 呼び出し元（extract_office.ps1・indexer_run.ps1・office_reader.ps1 のグラフ・SmartArt 読み取り）は、
    # 捕まえた例外をそのまま渡せばよい。ZipSizeLimitException かどうかはここで確かめ、違えば何もしない
    # （param の型を [ZipSizeLimitException] にしないのは、indexer_state.ps1 が office_reader.ps1 より先に
    # 読み込まれ、その時点ではクラスがまだ無いため）
    param (
        [System.Exception]$exception
    )

    if ($exception -isnot [ZipSizeLimitException]) {
        return
    }

    $kindText = switch ($exception.LimitKind) { "Total" { "1ファイルの合計" } "Output" { "埋め込みから出す文字の合計" } default { "部品ごと" } }
    $mb = [math]::Round($exception.MeasuredBytes / 1MB, 1)
    writeIndexerLog "    サイズの上限（${kindText}）を超えました: $($exception.PartName)（$($exception.MeasuredBytes) バイト、約${mb}MB）" "Yellow"
}

function newIngestPlanRow {
    # 取り込み予定（インデックス1件分）の行を作る
    param (
        [string]$name,
        [string]$path,
        [string]$kind = ${planKindIngest},
        [int]$total = 0,    # 見つかった Office ファイルの数
        [int]$targets = 0,  # 今回取り込むファイルの数（新規＋更新あり＋前回未完了＋インデックスなし）
        [int]$new = 0,
        [int]$updated = 0,
        [int]$pending = 0,
        [int]$lost = 0,     # インデックス（TSV）が無くなった・壊れているため取り込み直す
        [int]$failed = 0,   # 前回失敗し、その後更新されていない（再取り込みするかは画面で選ぶ）
        [int]$cloud = 0,        # クラウドにだけあるため、取り込み対象に数えていないファイル（新規・更新あり・前回未完了など）
        [int]$cloudFailed = 0,  # クラウドにだけあり、前回失敗したファイル
        [long]$cloudBytes = 0,  # クラウドにだけあり、取り込み対象のファイルの合計サイズ（バイト）
        [long]$cloudFailedBytes = 0  # クラウドにだけあり、前回失敗したファイルの合計サイズ（バイト）
    )

    return [pscustomobject]@{
        インデックス名 = $name
        元のフォルダ   = $path
        区分           = $kind
        ファイル数     = $total
        取り込み対象       = $targets
        新規           = $new
        更新あり       = $updated
        前回未完了     = $pending
        インデックスなし   = $lost
        前回失敗       = $failed
        クラウド       = $cloud
        クラウド失敗   = $cloudFailed
        クラウド容量   = $cloudBytes
        クラウド失敗容量 = $cloudFailedBytes
    }
}

function readStatusLines {
    # 取り込み一覧を1行ずつ読む（インデックス作成中でも読めるよう共有を許して開く）。ファイルが無ければ空
    param (
        [string]$path = $workspace.StatusFile
    )

    if (!(Test-Path -LiteralPath $path)) {
        return @()
    }
    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $stream = New-Object System.IO.FileStream($path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    $reader = New-Object System.IO.StreamReader($stream, ${utf8Bom})
    try {
        $text = $reader.ReadToEnd()
    } finally {
        $reader.Dispose()
    }
    return @($text -split "\r?\n" | Where-Object { $_ -ne "" })
}

function renameStatusIndexName {
    # 取り込み一覧に記録したインデックス名を書き換える（クロール対象フォルダの行と、各行の相対パスの先頭）。
    # 行の順序と内容をそのまま保つため、行ごとに書き換えて置き換える
    param (
        [string]$oldName,
        [string]$newName,
        [string]$path = $workspace.StatusFile
    )

    $lines = @(readStatusLines $path)
    if ($lines.Count -eq 0) {
        return
    }

    $result = New-Object System.Collections.Generic.List[string]
    foreach ($line in $lines) {
        $fields = $line.Split("`t")
        if ($fields[0] -eq ${statusFolderKey} -and $fields.Count -eq 3 -and [string]::Equals($fields[2], $oldName, [System.StringComparison]::OrdinalIgnoreCase)) {
            $fields[2] = $newName
            $result.Add($fields -join "`t")
            continue
        }
        if ($fields.Count -eq ${statusColumns}.Count -and $fields[0] -ne "") {
            $split = splitIndexRelPath $fields[0]
            if ($split.Rest -ne "" -and [string]::Equals($split.Name, $oldName, [System.StringComparison]::OrdinalIgnoreCase)) {
                $fields[0] = "${newName}\$($split.Rest)"
                $result.Add($fields -join "`t")
                continue
            }
        }
        $result.Add($line)
    }
    writeTextLinesAtomic $path $result
}

function removeStatusIndexName {
    # 取り込み一覧から、あるインデックスの記録（クロール対象フォルダの行と、そのインデックスの各行）を取り除く
    param (
        [string]$name,
        [string]$path = $workspace.StatusFile
    )

    $lines = @(readStatusLines $path)
    if ($lines.Count -eq 0) {
        return
    }

    $result = New-Object System.Collections.Generic.List[string]
    foreach ($line in $lines) {
        $fields = $line.Split("`t")
        if ($fields[0] -eq ${statusFolderKey} -and $fields.Count -eq 3 -and [string]::Equals($fields[2], $name, [System.StringComparison]::OrdinalIgnoreCase)) {
            continue
        }
        if ($fields.Count -eq ${statusColumns}.Count -and $fields[0] -ne "") {
            $split = splitIndexRelPath $fields[0]
            if ($split.Rest -ne "" -and [string]::Equals($split.Name, $name, [System.StringComparison]::OrdinalIgnoreCase)) {
                continue
            }
        }
        $result.Add($line)
    }
    writeTextLinesAtomic $path $result
}

function getIndexingState {
    # 取り込み一覧からインデックス作成の状態を返す:
    #   @{ Exists; Folders（クロール対象フォルダ @{ Path; Name } の配列）; Total; Pending（未取り込み）; Failed; Done; IngestedSince（since 以降に取り込んだ件数）; Updated（取り込み一覧の更新日時）;
    #      FailedRows（失敗したファイルの行。取り込み日時の新しい順）; IndexStats（インデックス名ごとの集計。getIndexStats） }
    param (
        [datetime]$since = [datetime]::MaxValue,
        [string]$path = $workspace.StatusFile
    )

    $state = @{ Exists = $false; Folders = @(); Total = 0; Pending = 0; Failed = 0; Done = 0; IngestedSince = 0; Updated = $null; FailedRows = @(); IndexStats = (getIndexStats $null) }
    if (!(Test-Path -LiteralPath $path)) {
        return $state
    }

    $state.Exists = $true
    $state.Updated = (Get-Item -LiteralPath $path).LastWriteTime
    $status = readStatusFile $path
    $state.Folders = $status.Folders.ToArray()
    $state.Total = $status.Rows.Count
    $state.IndexStats = getIndexStats $status.Rows
    # since を指定しないとき（画面の集計）は、行ごとの日時の解析（数万行では数秒かかる）を省く
    $countSince = ($since -ne [datetime]::MaxValue)
    $sinceSecond = if ($countSince) { $since.AddTicks(-($since.Ticks % [timespan]::TicksPerSecond)) } else { $since }
    $failedRows = New-Object System.Collections.Generic.List[object]
    foreach ($row in $status.Rows.Values) {
        if (testStatusRowFailed $row) {
            $state.Failed++
            $failedRows.Add($row)
        } elseif ($row.状態 -eq ${stateNew}) {
            $state.Pending++
        } elseif ($row.状態 -eq ${stateDone}) {
            $state.Done++
        }

        $ingested = [datetime]::MinValue
        if ($countSince -and $row.取り込み日時 -and [datetime]::TryParseExact($row.取り込み日時, "yyyy/MM/dd HH:mm:ss", [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::None, [ref]$ingested) -and $ingested -ge $sinceSecond) {
            $state.IngestedSince++
        }
    }
    # 取り込み日時は "yyyy/MM/dd HH:mm:ss" のため、文字列の順で新しい順に並ぶ
    $state.FailedRows = @($failedRows | Sort-Object -Property @{ Expression = { [string]$_.取り込み日時 }; Descending = $true }, @{ Expression = { $_.相対パス } })
    return $state
}

# 取り込み一覧・取り込み中のファイルの読み書きと、今回の取り込みでの失敗・元ファイルが無くなった行の記録をまとめる（StatusLedger）。
# 列と状態の定義（core/paths.ps1 の ${statusColumns} など）は判断層（indexer_decide.ps1）・index_store.ps1 なども読むため、
# 今の場所（paths.ps1 の変数）のまま動かさない（docs/design/structure/classes.md）。
# 保存先（取り込み一覧・取り込み中のファイル）は、コンストラクタで受け取った $workspace（Workspace のインスタンス。
# 場所を暗黙に使わないため、メソッドの中で ${workspace} を読まない）の StatusFile・IngestingFile から決める
class StatusLedger {
    hidden $Workspace
    # 今回の取り込みで失敗したファイル（@{ RelPath; Message } の並び）
    [System.Collections.Generic.List[object]]$Failures
    # 取り込みの直前に元のファイルが無くなっていた相対パス（取り込み一覧から除く）
    [System.Collections.Generic.HashSet[string]]$DroppedRows

    StatusLedger($workspace) {
        $this.Workspace = $workspace
        $this.Failures = New-Object System.Collections.Generic.List[object]
        $this.DroppedRows = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    }

    [hashtable] ReadStatus() {
        # 取り込み一覧を読み込む（readStatusFile と同じ形。@{ Folders; Rows }）
        return readStatusFile $this.Workspace.StatusFile
    }

    [void] WriteStatus($folders, $rows) {
        # 取り込み一覧を書き出す（1ファイル1行）
        writeStatusFile $folders $rows $this.Workspace.StatusFile
    }

    [void] AddRow($row) {
        # 取り込み一覧の末尾に1行追記する
        addStatusRow $row $this.Workspace.StatusFile
    }

    [object[]] ReadIngestingFiles() {
        # 取り込み中のファイルの記録を読む（@{ RelPath; Count } の並び）
        return readIngestingFiles $this.Workspace.IngestingFile
    }

    [void] WriteIngestingFiles([object[]]$entries) {
        # 取り込み中のファイルの記録を書く（無ければ記録を消す）
        writeIngestingFiles $entries $this.Workspace.IngestingFile
    }

    [void] RemoveIngestingFile() {
        removeIngestingFile $this.Workspace.IngestingFile
    }

    [void] RenameIndexName([string]$oldName, [string]$newName) {
        # 取り込み一覧に記録したインデックス名を書き換える（クロール対象フォルダの行と、各行の相対パスの先頭）
        renameStatusIndexName $oldName $newName $this.Workspace.StatusFile
    }

    [void] RemoveIndexName([string]$name) {
        # 取り込み一覧から、あるインデックスの記録（クロール対象フォルダの行と、そのインデックスの各行）を取り除く
        removeStatusIndexName $name $this.Workspace.StatusFile
    }

    [void] AddFailure([string]$relPath, [string]$message) {
        # 今回の取り込みで失敗したファイルを記録する
        $this.Failures.Add(@{ RelPath = $relPath; Message = $message })
    }

    [void] AddDropped([string]$relPath) {
        # 取り込みの直前に元のファイルが無くなっていた（取り込み一覧・インデックスから除く）ファイルを記録する
        [void]$this.DroppedRows.Add($relPath)
    }
}

# インデックスの改名・削除・名前の割り当て・一覧と元のフォルダの記録の保存。
# インデックス 1 つの情報は複数の保存先に分かれて置かれている: 設定の targetFolders、取り込み一覧、インデックスのフォルダ（content_index\<名前>）と
# 元のフォルダの記録（source_folder.txt）、設定の searchExcludes、システムインデックス（system_index）。
# このクラスは、改名・削除でそれらを書き換える手順と順番、途中で失敗したときの扱い（止める・残す）だけを持つ。一覧（targetFolders）と元のフォルダの記録の書き直しは、画面が SaveTargets・WriteSourceFile（改名では RenameIndexWithSource）で呼ぶ。保存先の形式は知らず、
# 保存先ごとの読み書きは既存の関数（searchExcludes は core\search_excludes.ps1）と、作る側から渡された StatusLedger に任せる。
# 画面は呼んで結果を出すだけにする（画面の手順をここに引き寄せる）。
#
# クラスの本体では $script: 変数・ほかのクラスの型・呼び出し元の変数を使わない（docs/design/structure/classes.md）。
# 場所は、コンストラクタで受け取る workspace（Workspace のインスタンス）と設定ファイルの場所で決める。
# 取り込み一覧は ledger（StatusLedger のインスタンス。作る側が作って渡す）を通して書く。
# 別のスレッドへはインスタンスを渡さず、ワークスペースの場所（文字列）を渡して newIndexCatalog で作り直す。
# メソッドの中のローカル変数は、プロパティと大文字・小文字だけの違いにしない
class IndexCatalog {
    hidden $Workspace
    hidden [string]$SettingsPath
    hidden $Ledger

    IndexCatalog($workspace, [string]$settingsPath, $ledger) {
        $this.Workspace = $workspace
        $this.SettingsPath = $settingsPath
        $this.Ledger = $ledger
    }

    [void] AssertReachable() {
        # インデックスの削除・名前の変更の裏の仕事の先頭で呼ぶ。ワークスペースに届かないときは例外にする
        # （届かないのに「何もせず成功」にして、設定だけ変えてしまわないため）
        assertWorkspaceReachable $this.Workspace.IndexDir
    }

    [void] RenameIndex([string]$oldName, [string]$newName) {
        # インデックス名を変える（画面の詳細の名前の欄）。インデックスのフォルダ（content_index\<名前>）を改名し、
        # 取り込み一覧の記録も書き換えるため、名前を変えてもインデックスは作り直さない。
        # インデックス作成中は呼ばない（画面はインデックス作成中この操作を無効にする）。
        # フォルダの改名か取り込み一覧の書き換えに失敗したら例外にする（システムインデックスと searchExcludes の整理は、失敗しても止めない）
        $dir = $this.Workspace.IndexDir
        # 大文字・小文字だけの変更も改名するため、同じ名前かは大文字・小文字を区別して比べる（-ceq）
        if ($oldName -eq "" -or $newName -eq "" -or $oldName -ceq $newName) {
            return
        }

        $from = Join-Path $dir $oldName
        $to   = Join-Path $dir $newName
        if (Test-Path -LiteralPath $from -PathType Container) {
            if ([string]::Equals($oldName, $newName, [System.StringComparison]::OrdinalIgnoreCase)) {
                # 大文字・小文字だけを変える場合は、そのままでは改名できないため一時名を経由する
                $tmp = Join-Path $dir "${oldName}_rename_$([System.Diagnostics.Process]::GetCurrentProcess().Id)"
                [System.IO.Directory]::Move((toLongPath $from), (toLongPath $tmp))
                [System.IO.Directory]::Move((toLongPath $tmp), (toLongPath $to))
            } else {
                if (Test-Path -LiteralPath $to) {
                    throw "「${newName}」のフォルダが既にあるため、名前を変えられません: ${to}"
                }
                [System.IO.Directory]::Move((toLongPath $from), (toLongPath $to))
            }
        }
        $this.Ledger.RenameIndexName($oldName, $newName)
        # 高速検索の システムインデックス（同じワークスペースの system_index）は古い名前の分を消す。次のインデックス作成で作り直す
        removeSystemIndexOfWorkspace $oldName $dir
        # 外したフォルダの記録（searchExcludes）は旧名・新名の下のものを消す（付け替えず、検索対象に戻す）
        removeSearchExcludesUnder $from $this.SettingsPath
        removeSearchExcludesUnder $to $this.SettingsPath
    }

    [hashtable] RenameIndexWithSource([string]$oldName, [string]$newName, $folders) {
        # 名前を変え（RenameIndex）、続けて元のフォルダの記録（source_folder.txt）を書き直す。
        # 書き直しに失敗しても、改名は済んでいるので改名の失敗にはしない。書けなかった理由を SourceFolderError で返す（成功なら空）。
        # 改名の失敗は、RenameIndex の例外のまま呼び出し元へ出る
        $this.RenameIndex($oldName, $newName)
        $sourceError = ""
        try {
            $this.WriteSourceFile($folders)
        } catch {
            $sourceError = $_.Exception.Message
        }
        return @{ SourceFolderError = $sourceError }
    }

    [void] RemoveIndex([string]$name) {
        # インデックスを削除する（画面の［削除］）。インデックスのフォルダ（content_index\<名前>）と、取り込み一覧の記録を削除する。
        # インデックス作成中は呼ばない（画面はインデックス作成中この操作を無効にする）。
        # フォルダを消せなければ例外にして、取り込み一覧の記録は残す
        $dir = $this.Workspace.IndexDir
        if ($name -eq "") {
            return
        }
        $target = Join-Path $dir $name
        if (Test-Path -LiteralPath $target -PathType Container) {
            # 中に長いパス（260文字超）のTSVがあっても削除でき、中のリンク（ジャンクション・シンボリックリンク）の先は消さない
            # （removeDirectoryRetry）。消せなければ例外にして、取り込み一覧の記録を残す（フォルダが残ったまま記録だけ消えないように）
            removeDirectoryRetry $target
        }
        $this.Ledger.RemoveIndexName($name)
        removeSystemIndexOfWorkspace $name $dir
        # 外したフォルダの記録（searchExcludes）も消す
        removeSearchExcludesUnder $target $this.SettingsPath
    }

    [object[]] RemoveIndexes([string[]]$names) {
        # 選んだインデックスをまとめて削除する（画面の［削除］）。1 つずつ RemoveIndex を呼び、途中で 1 つ失敗しても残りを続ける。
        # 戻り値は名前ごとの結果の配列（@{ Name; Ok; Reason }）。Reason は失敗したときの理由（成功なら ""）。
        # 画面のスレッドでは呼ばず、別スレッドの仕事の中で呼ぶ
        $results = New-Object System.Collections.Generic.List[object]
        foreach ($name in @($names)) {
            if ([string]::IsNullOrEmpty($name)) {
                $results.Add([pscustomobject]@{ Name = [string]$name; Ok = $false; Reason = "インデックス名が空です" })
                continue
            }
            try {
                $this.RemoveIndex($name)
                $results.Add([pscustomobject]@{ Name = $name; Ok = $true; Reason = "" })
            } catch {
                $results.Add([pscustomobject]@{ Name = $name; Ok = $false; Reason = $_.Exception.Message })
            }
        }
        return $results.ToArray()
    }

    [object[]] AssignAndSaveNames($folders) {
        # 名前の決まっていないインデックス（設定ファイルを直接書き換えた場合など）に名前を割り当てて、設定に保存する。保存した一覧を返す。
        # 取り込み一覧の読み込みは排他の外で済ませ、設定の読み直しと書き込みだけを saveAssignedIndexNames が排他の中で行う
        $status = $this.Ledger.ReadStatus()
        $assigned = @(assignIndexNames $folders $status.Folders)
        return @(saveAssignedIndexNames $assigned $this.SettingsPath)
    }

    [object[]] StoreAssignedNames($assigned) {
        # 割り当てた名前（assignIndexNames の結果）を設定に保存し、保存した一覧（@{ Name; Path; Enabled }）を返す。
        # インデクサが、司令のスレッドで作ったこのクラスの経由で名前を保存する
        return @(saveAssignedIndexNames $assigned $this.SettingsPath)
    }

    [void] SaveTargets($folders) {
        # インデックスの一覧（@{ Name; Path; Enabled } の配列）を設定に書く
        writeTargetFolders $folders $this.SettingsPath
    }

    [void] WriteSourceFile($folders) {
        # インデックスのフォルダの source_folder.txt を、一覧（@{ Name; Path } の配列）に合わせて書き直す（インデックスが無いフォルダには書かない）
        writeSourceFolderFile $folders $this.Workspace.IndexDir
    }
}

function newIndexCatalog {
    # ワークスペースの場所（Dir。文字列）から IndexCatalog を作る。取り込み一覧を書く StatusLedger もここで作って渡す。
    # 画面のスレッドでも、別のスレッドの仕事の中でも使う（スレッドをまたいでインスタンスを渡さず、場所を渡して作り直すため）
    param (
        [string]$workspaceDir,
        [string]$settingsPath = ${settingsFile}
    )

    $target = [Workspace]::new($workspaceDir)
    return [IndexCatalog]::new($target, $settingsPath, [StatusLedger]::new($target))
}

# 1 ファイルを取り込み直すかどうかの判断（差分取り込みの要）。
# ファイルにも画面にも触らないため、そのままテストできる（tests\tebunko\indexer\indexer_decide.Tests.ps1）。

# 読み取る内容（抽出版）。読み取る場所を増やしたら、その形式の版を上げる。
# 前の版で取り込んだファイルは、更新が無くても取り込み直す（取り込み一覧の「抽出版」。空は 1）
#   2: Excel（.xlsx / .xlsm）の図形・コメントを読む。
#      Word・PowerPoint のコメント・SmartArt・グラフを読み、Word のテキストボックスを本文から図形に分ける
#      （Word・PowerPoint は旧形式も新形式に変換してから読むため、.doc / .ppt も上げる）
#   3: Excel のグラフ・SmartArt（表示のグラフシートを含む）を読む。
#      グラフの読み方を、タイトル・軸ラベル・系列名だけにし、項目名は読まないようにする
#      （.xlsx / .xlsm はグラフ・SmartArt を読むようになった分で 3。.docx / .docm / .pptx / .pptm は
#      項目名を読まなくなった分だけ上げる。.doc / .ppt はこのアイテムでは上げない）
#   4: Excel（.xlsx / .xlsm）のヘッダー・フッター（表示のワークシート・グラフシート）を読む。
#   4（.docx / .docm / .doc / .pptx / .pptm）: Word・PowerPoint に埋め込んだ Office のファイル（Word 文書・Excel ブック・
#      PowerPoint）の中の文字を、"ページNNN[埋め込みN]"・"スライドNNN[埋め込みN]" として読む
#      （.doc は Word が新形式に変換した後も埋め込みが残るため上げる。.ppt は変換後に埋め込みが残らないため上げない）。
${extractVersions} = @{
    ".xlsx" = 4; ".xlsm" = 4
    ".docx" = 4; ".docm" = 4; ".doc" = 4
    ".pptx" = 4; ".pptm" = 4; ".ppt" = 2
}

function getExtractVersion {
    # ファイルの形式（拡張子）の今の抽出版を返す
    param (
        [string]$path
    )

    $version = ${extractVersions}[[System.IO.Path]::GetExtension($path).ToLowerInvariant()]
    return $(if ($null -eq $version) { 1 } else { $version })
}

function testExtractOutdated {
    # 取り込み一覧の行が、今の抽出版より前の版で取り込んだものか
    param (
        $row
    )

    $version = 1
    if ($row.抽出版) {
        [void][int]::TryParse([string]$row.抽出版, [ref]$version)
    }
    return ($version -lt (getExtractVersion $row.相対パス))
}

function getIngestDecision {
    # 前回の取り込み一覧の行と、いまのファイルの更新日時・サイズから、取り込むかどうかと、その理由を返す。
    #   Ingest: 取り込むか / Reason: done（取り込み済み）・failed（前回失敗。再取り込みするかは呼び出し元が決める）・
    #            new（一覧に無い）・updated（更新された）・pending（前回未完了）・lost（インデックスが無い・壊れている）・
    #            outdated（前の抽出版で取り込んだ）
    param (
        $old,                 # 前回の取り込み一覧の行（無ければ $null）
        [string]$updated,     # いまのファイルの更新日時（formatFileTime）
        [string]$size,        # いまのファイルのサイズ（文字列）
        [bool]$indexComplete  # インデックス（TSV）がそろっているか（状態が「済」のときだけ意味がある）
    )

    # 前回と更新日時・サイズが同じで、前回「未取り込み」で終わっていなければ、同じファイルとみなす
    $sameFile = ($old -and $old.更新日時 -eq $updated -and $old.サイズ -eq $size -and $old.状態 -ne ${stateNew})
    # 取り込み済みでも、インデックス（TSV）が無くなっていれば取り込み直す。
    # 一覧だけを見ると「済」のままになり、検索しても出てこない状態が続くため
    $lostIndex = ($sameFile -and $old.状態 -eq ${stateDone} -and -not $indexComplete)

    if ($sameFile -and -not $lostIndex) {
        if ($old.状態 -eq ${stateFailed}) {
            return @{ Ingest = $false; Reason = "failed" }
        }
        if (testExtractOutdated $old) {
            return @{ Ingest = $true; Reason = "outdated" }
        }
        return @{ Ingest = $false; Reason = "done" }
    }
    if ($lostIndex) {
        return @{ Ingest = $true; Reason = "lost" }
    }
    if ($null -eq $old) {
        return @{ Ingest = $true; Reason = "new" }
    }
    if ($old.状態 -eq ${stateNew}) {
        return @{ Ingest = $true; Reason = "pending" }
    }
    return @{ Ingest = $true; Reason = "updated" }
}

# 利用者が使っている PowerPoint のために取り込めなかったファイルの理由（取り込み一覧の「エラー」列と、更新に失敗したファイルの一覧に出す。
# 状態は「未取り込み」のまま残すので、閉じてからの次の更新で、再取り込みを選ばなくても取り込む）
${postponedReasonRunning} = "PowerPoint が起動していたため取り込めませんでした。PowerPoint を閉じてから、もう一度更新してください。"
${postponedReasonInUse}   = "PowerPoint を使っている方がいたため取り込めませんでした。PowerPoint を保存して閉じてから、もう一度更新してください。"

# 取り込みのレーン（docs/design/indexing/parallel.md）。Office のレーンはアプリごとに 1 つのスレッドで、そのアプリを 1 つ持つ。
# 読み取りのレーンは Office を使わず、ZIP の中の XML を直接読む（複数のスレッド）
${laneExcel}      = "Excel"
${laneWord}       = "Word"
${lanePowerPoint} = "PowerPoint"
${laneReader}     = "Reader"

function getIngestLane {
    # 取り込むファイルのレーンを拡張子で決める。Excel はセルの表示値を読むため、すべて Excel のレーン。
    # Word・PowerPoint は、旧形式（.doc / .ppt）だけ Office のレーン、新形式は読み取りのレーン
    # （中身が旧形式・パスワード付きと分かったら、読み取りのスレッドが Office のレーンに回し直す。getOfficeLane）。
    # テキストの拡張子（.txt 等）と PDF（.pdf）は、どの分岐にも当たらないため既定の読み取りのレーンになる（Office を使わずに読むため）
    param (
        [string]$relPath
    )

    switch -Regex ([System.IO.Path]::GetExtension($relPath).ToLowerInvariant()) {
        "^\.xls"   { return ${laneExcel} }
        "^\.doc$"  { return ${laneWord} }
        "^\.ppt$"  { return ${lanePowerPoint} }
    }
    return ${laneReader}
}

function getOfficeLane {
    # 読み取りのスレッドが Office が要ると返したファイルの、回し先の Office のレーン
    param (
        [string]$relPath
    )

    if ([System.IO.Path]::GetExtension($relPath).ToLowerInvariant().StartsWith(".ppt")) {
        return ${lanePowerPoint}
    }
    return ${laneWord}
}
function splitCloudItems {
    # クラウドにだけあるファイルの一覧を、取り込むものと、ダウンロードせずに残すものに分ける。
    #   取り込む: 「ダウンロードして取り込む」が選ばれていて、取り込み対象のもの（Failed が $false）。
    #            前回失敗したもの（Failed が $true）は、「前回失敗したものも取り込み直す」も選ばれているときだけ
    #   items の各要素は createTargetList が返す Cloud の要素（Failed: 前回失敗したファイルか）
    param (
        $items,
        [bool]$retryFailed,
        [bool]$includeCloud
    )

    $included = New-Object System.Collections.Generic.List[object]
    $skipped = New-Object System.Collections.Generic.List[object]
    # List[object] を @() に渡すと PowerShell 5.1 で落ちることがあるため、そのまま回す
    foreach ($item in $items) {
        if ($includeCloud -and ((-not $item.Failed) -or $retryFailed)) {
            $included.Add($item)
        }
        else {
            $skipped.Add($item)
        }
    }
    return @{ Included = $included; Skipped = $skipped }
}

# 画面のインデックス作成 1 回分（IndexingSession）。インデクサの司令のスレッドを作り、indexer.ps1 を受け渡しの口（newIndexerChannel）付きで実行する。
# 設計は docs/design/structure/threads.md「スレッドの一覧」「画面とインデクサの受け渡し」、docs/design/structure/closing.md「閉じるときの順番」。
#
# IndexingSession は画面のスレッドだけから呼ぶ（PowerShell 5.1 のクラスのメソッドは、定義したランスペースで動くため）。
# 画面とインデクサのやり取りは、すべて受け渡しの口で行う（中止・確認の返事・進み具合・終了コード）

# インデクサの司令のスレッドで動かすスクリプト。インデックス作成の処理のため、スレッドの優先度を下げる。
# indexerLib の部品（Prelude）は IndexingSession のコンストラクタが、この本体の param ブロックの
# あとにつなぐ（joinWorkerScript）。invokeIndexerMain は indexer\indexer_main.ps1 の関数
${indexingSessionScript} = {
    param ($channel)
    [System.Threading.Thread]::CurrentThread.Priority = [System.Threading.ThreadPriority]::BelowNormal
    invokeIndexerMain -Channel $channel
}

class IndexingSession {
    # 受け渡しの口
    [hashtable]$Channel
    # 始めた時刻
    [datetime]$Started
    hidden [System.Management.Automation.Runspaces.Runspace]$Runspace
    hidden [powershell]$PowerShell
    hidden [System.IAsyncResult]$Handle

    IndexingSession([string]$script, [hashtable]$indexerLoad, [hashtable]$channel) {
        $this.Channel = $channel
        $this.Started = Get-Date
        # 司令のスレッドは COM に触らないため MTA（Office は取り込みのスレッド（STA）が扱う）
        $this.Runspace = [runspacefactory]::CreateRunspace($indexerLoad.State)
        $this.Runspace.ApartmentState = [System.Threading.ApartmentState]::MTA
        $this.Runspace.Open()
        $this.PowerShell = [powershell]::Create()
        $this.PowerShell.Runspace = $this.Runspace
        $joined = if ($indexerLoad.Prelude) { joinWorkerScript $indexerLoad.Prelude $script } else { $script }
        [void]$this.PowerShell.AddScript($joined).AddArgument($channel)
        $this.Handle = $this.PowerShell.BeginInvoke()
    }

    [bool] IsRunning() {
        return $null -ne $this.PowerShell -and !$this.Handle.IsCompleted
    }

    [void] Stop() {
        # 中止を求める（取り込み中のファイルが終わったところで止まる。確認を待っていれば取りやめる）
        $this.Channel.Stop = $true
        [void]$this.Channel.Answered.Set()
    }

    [bool] Wait([int]$milliseconds) {
        # 終わるのを待つ。終わっていれば $true
        if ($null -eq $this.PowerShell) {
            return $true
        }
        return $this.Handle.AsyncWaitHandle.WaitOne($milliseconds)
    }

    [int] GetExitCode() {
        # 終了コード（0 完了 / 1 エラー / 2 中止）。インデクサが終了コードを入れずに止まったとき（読み込めない等）は 1
        if ($null -ne $this.Channel.ExitCode) {
            return [int]$this.Channel.ExitCode
        }
        return 1
    }

    [string] GetError() {
        # 続けられないエラーの内容。インデクサが入れていなければ、スレッドが止まった理由
        if ($this.Channel.Error) {
            return [string]$this.Channel.Error
        }
        $this.Collect()
        return $this.Failure
    }

    [int] GetCloudSkipped() {
        # クラウドにだけあるため、ダウンロードせずに残した件数。無ければ 0
        if ($null -ne $this.Channel.CloudSkipped) {
            return [int]$this.Channel.CloudSkipped
        }
        return 0
    }

    hidden [string]$Failure = ""
    hidden [bool]$Ended = $false

    hidden [void] Collect() {
        # 終わったスレッドの結果を受け取り、止まった理由（例外・エラー）を Failure に残す（1 回だけ）
        if ($this.Ended -or $null -eq $this.PowerShell -or !$this.Handle.IsCompleted) {
            return
        }
        $this.Ended = $true
        try {
            [void]$this.PowerShell.EndInvoke($this.Handle)
            if ($this.PowerShell.Streams.Error.Count -gt 0) {
                $this.Failure = $this.PowerShell.Streams.Error[0].ToString()
            }
        } catch {
            $exception = $_.Exception
            while ($exception.InnerException) {
                $exception = $exception.InnerException
            }
            $this.Failure = $exception.Message
        }
    }

    [int] KillOffice() {
        # インデックス作成が起動して PID を記録した Office だけを止め、止めた数を返す（閉じるときに終わらない場合の最後の手段）
        $count = 0
        foreach ($id in @($this.Channel.OfficePids.Keys)) {
            try {
                $process = [System.Diagnostics.Process]::GetProcessById($id)
                # 終了済みで ID が別のプロセスに使われている場合に備え、記録したプロセス名と起動時刻が同じか確かめる
                $entry = $this.Channel.OfficePids[$id]
                if (isSameOfficeProcess $process $entry.ProcessName $entry.StartTicks) {
                    # 利用者が使っている（取り込み中に見える窓があった）PowerPoint は止めない
                    $mark = $null
                    if ($this.Channel.UserOfficePids.TryGetValue($id, [ref]$mark) -and $mark.StartTicks -eq $entry.StartTicks) {
                        continue
                    }
                    # 今、見える窓があるプロセスも止めない（アプリを問わない。取り込みのプロセスは窓を出さない）
                    if (testOfficeProcessHasWindow $process) {
                        continue
                    }
                    $process.Kill()
                    $count++
                }
            } catch {
            }
        }
        return $count
    }

    [void] Close() {
        # スレッドを片づける。終わっていなければ中止を求めて待つ（呼ぶ側が終わるのを待ってから呼ぶ）。何度呼んでもよい
        if ($null -eq $this.PowerShell) {
            return
        }
        if (!$this.Handle.IsCompleted) {
            $this.Stop()
            if (!$this.Wait(5000)) {
                try {
                    $this.PowerShell.Stop()
                } catch {
                }
            }
        }
        $this.Collect()
        $this.PowerShell.Dispose()
        $this.PowerShell = $null
        $this.Runspace.Dispose()
        $this.Runspace = $null
    }
}

function newIndexingSession {
    # インデックス作成を始める（画面の［すべて更新］）。終わったら Close を呼ぶ
    param (
        [hashtable]$channel
    )

    $indexerLoad = getPartLoad indexerLib
    return [IndexingSession]::new(${indexingSessionScript}.ToString(), $indexerLoad, $channel)
}

# 検索の条件（正規表現・対象ファイル）の組み立て（判断層。ファイルに触らない）。

function isValidRegex {
    # 正規表現として正しいか
    param (
        [string]$pattern
    )

    try {
        [void][regex]::new($pattern)
        return $true
    } catch {
        return $false
    }
}


# 1行の照合にかけてよい時間。正規表現によっては終わらなくなるため、超えたら検索を止める
${regexTimeout} = [timespan]::FromSeconds(5)

function getRegexScanMode {
    # 正規表現を TSV の全文（改行は LF にそろえ、^ $ は行の先頭・末尾に一致させる）にかけてよいかを返す。
    # 1 行ずつ PowerShell で照合すると遅いため、全文への照合（.NET の中で走る）で済ませられる場合を見分ける。
    #   "lines" : 一致は必ず 1 行の中に収まり、行の外の文字を見ない。全文での一致の位置から、ヒットした行が分かる
    #   "filter": 行をまたいで一致することはあるが、1 行で一致するなら全文でも必ず一致する。
    #             全文で一致しない TSV は読み飛ばせる（一致した TSV は 1 行ずつ照合し直す）
    #   "scan"  : 全文では 1 行と結果が変わりうる（\A \z、否定の先読み・後読み、(?i) 等）。1 行ずつ照合する
    # 判定は安全側に倒す（分からない書き方は "filter" か "scan"）。検索結果は照合のしかたによらず同じになる
    param (
        [string]$pattern
    )

    $lines = $true
    $inClass = $false
    $classStart = 0
    $length = $pattern.Length
    for ($i = 0; $i -lt $length; $i++) {
        $c = $pattern[$i]
        if ($c -eq '\') {
            $i++
            if ($i -ge $length) {
                return "scan"
            }
            $e = $pattern[$i]
            if ("AzZG".IndexOf($e) -ge 0) {
                return "scan"   # 文字列の先頭・末尾は、1 行と全文とで位置が違う
            }
            if ("sWDpPnrxuc0123456789".IndexOf($e) -ge 0) {
                $lines = $false  # 改行にも一致しうる（\s \W \D \p{..} \n \x0A \u000A \cJ 8 進数・後方参照）
            }
            if ($inClass -and $i + 1 -lt $length -and $pattern[$i + 1] -eq '-') {
                $lines = $false  # エスケープから始まる範囲（[\t-z] 等）は改行を含みうる
            }
            continue
        }
        if ([int]$c -lt 0x20) {
            $lines = $false      # 制御文字をそのまま含む（改行・タブから始まる範囲など）
        }
        if ($inClass) {
            if ($c -eq ']' -and $i -gt $classStart) {
                $inClass = $false
            }
            continue
        }
        if ($c -eq '[') {
            $inClass = $true
            if ($i + 1 -lt $length -and $pattern[$i + 1] -eq '^') {
                $lines = $false  # 否定の文字クラスは改行に一致する
                $i++
            }
            $classStart = $i + 1  # 先頭の ] は文字として扱われる
            continue
        }
        if ($c -eq '(' -and $i + 1 -lt $length -and $pattern[$i + 1] -eq '?') {
            $rest = $pattern.Substring($i + 2)
            if ($rest.StartsWith(":") -or $rest.StartsWith(">")) {
                continue
            }
            if ($rest.StartsWith("=") -or $rest.StartsWith("<=")) {
                $lines = $false  # 肯定の先読み・後読みは行の外（改行）を見る。全文で一致が増えるだけなので "filter" にはできる
                continue
            }
            if ($rest -match "^(<[A-Za-z_]|'[A-Za-z_])") {
                continue         # 名前付きグループ
            }
            return "scan"        # 否定の先読み・後読み、(?i) 等のオプション、条件分岐、コメント
        }
    }
    if ($lines) {
        return "lines"
    }
    return "filter"
}


function newSearchRegex {
    # 検索条件から、検索と一致箇所の強調で使う正規表現を作る（画面の検索と結果の表示で共通）。
    #   simpleMatch  : $true ならワードを文字どおりに探す。$false なら正規表現として探し、正規表現として不正なら文字どおりに探す
    #   caseSensitive: 英字の大文字・小文字を区別する（既定は区別しない）
    # @{ Regex; SimpleMatch（実際に文字どおり探すか）; TextRegex; ScanMode } を返す。
    #   TextRegex: TSV の全文にかける正規表現（Regex に Multiline を足したもの。^ $ が行の先頭・末尾に一致する）
    #   ScanMode : TextRegex を全文にかけてよいか（getRegexScanMode）
    param (
        [string]$word,
        [bool]$simpleMatch = $true,
        [bool]$caseSensitive = $false
    )

    if (!$simpleMatch -and !(isValidRegex $word)) {
        $simpleMatch = $true
    }
    $pattern = if ($simpleMatch) { [regex]::Escape($word) } else { $word }
    # CultureInvariant: 大文字・小文字を区別しないときの照合が、区別する場合と同程度に速くなる（日本語の照合結果は変わらない）
    $options = [System.Text.RegularExpressions.RegexOptions]::CultureInvariant
    if (!$caseSensitive) {
        $options = $options -bor [System.Text.RegularExpressions.RegexOptions]::IgnoreCase
    }
    $textOptions = $options -bor [System.Text.RegularExpressions.RegexOptions]::Multiline
    return @{
        Regex       = New-Object System.Text.RegularExpressions.Regex($pattern, $options, ${regexTimeout})
        SimpleMatch = $simpleMatch
        TextRegex   = New-Object System.Text.RegularExpressions.Regex($pattern, $textOptions, ${regexTimeout})
        ScanMode    = getRegexScanMode $pattern
    }
}

function newPlaceExclude {
    # 検索から外す場所（図形・コメント）の正規表現を返す。どちらも検索するなら $null。
    # 場所の名前は "<元の場所>[<種類>]"（index_name.ps1 の objectPlacePattern）。Excel・Word・PowerPoint で共通
    param (
        [bool]$includeShapes = $true,
        [bool]$includeComments = $true
    )

    $kinds = @()
    # 埋め込み（"[埋め込み<N>]"）は図形と一緒に切り替える（検索の選択肢を増やさない）
    if (!$includeShapes) { $kinds += ${placeKindShape}; $kinds += ${placeKindEmbed} }
    if (!$includeComments) { $kinds += ${placeKindComment} }
    if ($kinds.Count -eq 0) {
        return $null
    }
    return [regex]::new((newObjectPlaceKindPattern -kinds $kinds))
}

# テキストのヒットの行・プレビューの前後の行を切る長さ（文字）と、一致の位置から遡る長さ（文字）。
# 1 行が数 MB になりうる .json・.xml・.log の描画で画面が固まらないよう、取り込みでは切らず、表示・出力の直前だけ切る
${hitLineMaxChars} = 1000
${hitLineBeforeMatchChars} = 200

function truncateHitLine {
    # 長い行（テキストのヒットの行・前後の行）を、一致の位置を中心に hitLineMaxChars 文字に切る。
    # 一致の位置（matchIndex。行の中の位置。分からなければ -1）の hitLineBeforeMatchChars 文字前から hitLineMaxChars 文字を取り、
    # 省いた側に "…" を付ける。hitLineMaxChars 以下ならそのまま返す
    param (
        [string]$line,
        [int]$matchIndex = -1
    )

    if ($line.Length -le ${hitLineMaxChars}) {
        return $line
    }
    $start = if ($matchIndex -lt 0) { 0 } else { [Math]::Max(0, $matchIndex - ${hitLineBeforeMatchChars}) }
    $end = [Math]::Min($line.Length, $start + ${hitLineMaxChars})
    $result = $line.Substring($start, $end - $start)
    if ($start -gt 0) { $result = "…" + $result }
    if ($end -lt $line.Length) { $result = $result + "…" }
    return $result
}

function getFileKindExtensions {
    # 検索バーのチップの種類（excel・word・powerpoint・text・pdf）ごとの拡張子（小文字）を返す。知らない種類は空
    param (
        [string]$kind
    )

    switch ($kind) {
        "excel" { return @(${officeExtensions} | Where-Object { $_ -like ".xl*" }) }
        "word" { return @(${officeExtensions} | Where-Object { $_ -like ".do*" }) }
        "powerpoint" { return @(${officeExtensions} | Where-Object { $_ -like ".pp*" }) }
        "text" { return @(${textExtensions}) }
        "pdf" { return @(${pdfExtensions}) }
    }
    return @()
}

function newFileKindFilter {
    # 選んだ種類（readFileKinds の値）から、対象ファイルの条件（newFileFilter に渡す文字列。"*.xlsx;*.xls" の形）を作る。
    # すべての種類を選んでいる・空・知らない種類だけのときは空（絞り込まない）
    param (
        [object[]]$kinds
    )

    $chosen = @(${fileKindNames} | Where-Object { @($kinds) -contains $_ })
    if ($chosen.Count -eq 0 -or $chosen.Count -eq ${fileKindNames}.Count) {
        return ""
    }
    return (@($chosen | ForEach-Object { getFileKindExtensions $_ } | ForEach-Object { "*$_" }) -join ";")
}

function newFileFilter {
    # 対象ファイルの指定（例: "*.xlsx;見積*;!*old*"）を、元のファイル名に対する正規表現 @{ Include; Exclude } にする（無い側は $null）。
    #   ; で区切る（全角の ； も可）。! で始まるものは除外。* は任意の文字列、? は任意の1文字。大文字・小文字を区別しない
    #   * も ? も無いものは部分一致（「見積」は「*見積*」）
    param (
        [string]$filter
    )

    $include = New-Object System.Collections.Generic.List[string]
    $exclude = New-Object System.Collections.Generic.List[string]
    foreach ($item in ([string]$filter).Split([char[]]";；")) {
        $item = $item.Trim()
        $list = $include
        if ($item.StartsWith("!") -or $item.StartsWith("！")) {
            $list = $exclude
            $item = $item.Substring(1).Trim()
        }
        if ($item -eq "") {
            continue
        }
        if ($item.IndexOfAny([char[]]"*?") -lt 0) {
            $item = "*${item}*"
        }
        $list.Add("^" + [regex]::Escape($item).Replace("\*", ".*").Replace("\?", ".") + "$")
    }

    $options = [System.Text.RegularExpressions.RegexOptions]::IgnoreCase -bor [System.Text.RegularExpressions.RegexOptions]::CultureInvariant
    $result = @{ Include = $null; Exclude = $null }
    if ($include.Count -gt 0) {
        $result.Include = New-Object System.Text.RegularExpressions.Regex(($include -join "|"), $options)
    }
    if ($exclude.Count -gt 0) {
        $result.Exclude = New-Object System.Text.RegularExpressions.Regex(($exclude -join "|"), $options)
    }
    return $result
}

# 高速検索（Windows Search で検索語を含みうるフォルダを先に絞る）の決まり（判断層。ファイルにも画面にも触らない）。
# システムインデックス（system_index の txt）は、文字の 2-gram を英数字の語にしたものを空白区切りで書く。
# Windows Search は語単位でしか一致を取らないため、本文をそのまま索引させると語の途中からの一致を落とすが、
# 2-gram の語なら、ワードを含む本文の txt には、ワードのすべての 2-gram が必ず入っている。

# システムインデックスの名前（置き場所は paths.ps1 の $workspace.SystemIndexDir）
${systemIndexFileName}      = "system_index.txt"
${systemIndexFileLike}      = "system[_]index%"      # 問い合わせの LIKE（分けたものも含む）。LIKE の _ は任意の1文字のため [_] と書く
${systemIndexSplitLike}     = "system[_]index[_]%"   # 分けたもの（system_index_1.txt …）だけ

# 1 つの txt の大きさの上限（これを超えたら語の範囲で分ける。実測では 16MB までは末尾まで索引された）
${systemIndexPartBytes} = 8MB
# txt のパスの長さの上限（これ以上は作らず、そのフォルダは .NET で照合する。Windows Search が長いパスを索引しないおそれがあるため）
${systemIndexPathMax} = 240
# 1 回の問い合わせに使う語の数の上限（多いときは均等に間引く。間引いても候補が増えるだけで漏れない）
${searchGramMax} = 16

# 状態ファイルの行の種別
${systemIndexCovered}  = "対応済み"   # インデックスのすべてのフォルダに txt がある（または対象外として記録した）
${systemIndexPending}  = "反映待ち"   # txt を書いた（値は txt の更新日時。UTC の Ticks）
${systemIndexExcluded} = "対象外"     # txt を作らなかったフォルダ（常に .NET で照合する）

function convertToGramToken {
    # 2 文字（小文字にしたもの）を語にする: x ＋ UTF-16LE の 4 バイトの 16 進（例: "ニタ" → xcb30bf30）
    param (
        [string]$pair
    )

    return "x" + [System.BitConverter]::ToString([System.Text.Encoding]::Unicode.GetBytes($pair)).Replace("-", "").ToLowerInvariant()
}

function getSearchGrams {
    # 検索語から、問い合わせに使う語を返す（重複なし・最大 searchGramMax 個）。
    # 空白で区切り、2 文字以上の部分の隣り合う 2 文字を語にする。語が無ければ空（高速検索は使えない）
    param (
        [string]$word
    )

    $grams = New-Object System.Collections.Generic.List[string]
    $seen = New-Object System.Collections.Generic.HashSet[string]
    foreach ($part in ([string]$word).ToLowerInvariant() -split "[\s\u2028]+") {
        for ($i = 0; $i -lt $part.Length - 1; $i++) {
            $token = convertToGramToken $part.Substring($i, 2)
            if ($seen.Add($token)) {
                $grams.Add($token)
            }
        }
    }
    if ($grams.Count -le ${searchGramMax}) {
        return , $grams.ToArray()
    }
    # 均等に間引く（先頭と末尾は残す）
    $picked = New-Object System.Collections.Generic.List[string]
    for ($k = 0; $k -lt ${searchGramMax}; $k++) {
        $picked.Add($grams[[int][Math]::Round($k * ($grams.Count - 1) / (${searchGramMax} - 1))])
    }
    return , $picked.ToArray()
}

function testFastSearchUsable {
    # 高速検索を使えるか（画面の「使用可 / 使用不可」）。
    #   available: Windows Search を開けて、system_index が索引の対象（windows_search.ps1 の testWindowsSearch）
    param (
        [bool]$available,
        [bool]$useRegex,
        [string]$word
    )

    return ($available -and !$useRegex -and (getSearchGrams $word).Count -gt 0)
}

function addTextGrams {
    # 本文の 2-gram を、語の値（uint32。UTF-16LE の 2 文字をそのまま 4 バイトの整数にしたもの）として set に足す。
    # 1 文字ずつ PowerShell で回すと遅いため、char[] を uint32[] に写して .NET の HashSet で重複を除く。
    # 空白を含む 2-gram も入るが、問い合わせには使わないため害は無い（除く方が遅い）
    param (
        [System.Collections.Generic.HashSet[uint32]]$set,
        [string]$text
    )

    $chars = $text.ToLowerInvariant().ToCharArray()
    $even = $chars.Length -shr 1
    $odd = ($chars.Length - 1) -shr 1
    if ($even -gt 0) {
        $u0 = New-Object 'uint32[]' $even
        [System.Buffer]::BlockCopy($chars, 0, $u0, 0, $even * 4)
        $set.UnionWith($u0)
    }
    if ($odd -gt 0) {
        # 1 文字ずらした並びは、2 バイトずらして写せば作れる
        $u1 = New-Object 'uint32[]' $odd
        [System.Buffer]::BlockCopy($chars, 2, $u1, 0, $odd * 4)
        $set.UnionWith($u1)
    }
}

function convertToGramText {
    # 語の値（昇順に並べたもの）の start から count 個を、txt に書く文字列にする（x ＋ 16 進 8 桁を空白区切り）
    param (
        [uint32[]]$values,
        [int]$start = 0,
        [int]$count = -1
    )

    if ($count -lt 0) {
        $count = $values.Length - $start
    }
    if ($count -le 0) {
        return ""
    }
    $bytes = New-Object 'byte[]' ($count * 4)
    [System.Buffer]::BlockCopy($values, $start * 4, $bytes, 0, $count * 4)
    $hex = [System.BitConverter]::ToString($bytes).Replace("-", "").ToLowerInvariant()
    return [regex]::Replace($hex, "(.{8})", 'x$1 ')
}

function getGramPartCount {
    # 語の数から、txt をいくつに分けるかを返す（1 語は "x" ＋ 8 桁 ＋ 空白の 10 バイト）
    param (
        [int]$count,
        [long]$partBytes = ${systemIndexPartBytes}
    )

    $perPart = [Math]::Max(1, [int][Math]::Floor($partBytes / 10))
    return [Math]::Max(1, [int][Math]::Ceiling($count / $perPart))
}

function getSystemIndexFileNames {
    # txt の名前（分けないときは 1 つ。分けるときは system_index_1.txt …）
    param (
        [int]$parts
    )

    if ($parts -le 1) {
        return , @(${systemIndexFileName})
    }
    $base = [System.IO.Path]::GetFileNameWithoutExtension(${systemIndexFileName})
    return , @(1..$parts | ForEach-Object { "${base}_$_.txt" })
}

function testSystemIndexPath {
    # txt のパスが長すぎないか（分けたときは最も長い名前で判定する）
    param (
        [string]$folder,
        [int]$parts = 1
    )

    $longest = @(getSystemIndexFileNames $parts | Sort-Object Length -Descending)[0]
    return ("$folder\$longest").Length -lt ${systemIndexPathMax}
}

function convertFolderRoot {
    # フォルダのパスの先頭（fromRoot）を toRoot に置き換える（system_index と index は同じ相対パスの構成）。
    # fromRoot の外のパスは $null
    param (
        [string]$path,
        [string]$fromRoot,
        [string]$toRoot
    )

    $from = $fromRoot.TrimEnd("\")
    if ($path.Equals($from, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $toRoot.TrimEnd("\")
    }
    if ($path.StartsWith("$from\", [System.StringComparison]::OrdinalIgnoreCase)) {
        return $toRoot.TrimEnd("\") + $path.Substring($from.Length)
    }
    return $null
}

function getRelativePath {
    # root からの相対パス（root の外・root そのものは $null）
    param (
        [string]$path,
        [string]$root
    )

    $base = $root.TrimEnd("\")
    if ($path.StartsWith("$base\", [System.StringComparison]::OrdinalIgnoreCase) -and $path.Length -gt $base.Length + 1) {
        return $path.Substring($base.Length + 1)
    }
    return $null
}

function convertItemUrl {
    # Windows Search の System.ItemUrl（file:C:/…）をパスにする。% は符号化されていないため URL として戻さない
    param (
        [string]$url
    )

    return $url.Substring($url.IndexOf(":") + 1).Replace("/", "\")
}

function convertToScopeUrl {
    # SCOPE に書く URL（file:C:/…）。SQL の文字列に入れるため ' は重ねる
    param (
        [string]$path
    )

    return ("file:" + $path.TrimEnd("\").Replace("\", "/")).Replace("'", "''")
}

function newSystemIndexQuery {
    # 候補の txt（分けていないもの）を探す問い合わせ
    param (
        [string]$scopeDir,
        [string[]]$grams
    )

    $condition = ($grams | ForEach-Object { "`"$_`"" }) -join " AND "
    return "SELECT System.ItemUrl FROM SystemIndex WHERE SCOPE='$(convertToScopeUrl $scopeDir)' AND System.FileName = '${systemIndexFileName}' AND CONTAINS(System.Search.Contents, '$condition')"
}

function newSystemIndexSplitQuery {
    # 分けた txt から、語を 1 つ含むものを探す問い合わせ（分けた txt は AND で 1 回に問えないため語ごとに問う）
    param (
        [string]$scopeDir,
        [string]$gram
    )

    return "SELECT System.ItemUrl FROM SystemIndex WHERE SCOPE='$(convertToScopeUrl $scopeDir)' AND System.FileName LIKE '${systemIndexSplitLike}' AND CONTAINS(System.Search.Contents, '`"$gram`"')"
}

function newSystemIndexStateQuery {
    # 反映の判定に使う値（GatherTime・DateModified）を取る問い合わせ
    param (
        [string]$scopeDir
    )

    return "SELECT System.ItemUrl, System.Search.GatherTime, System.DateModified FROM SystemIndex WHERE SCOPE='$(convertToScopeUrl $scopeDir)' AND System.FileName LIKE '${systemIndexFileLike}'"
}

function testSystemIndexReflected {
    # txt が Windows Search に反映済みか: 本文を読み終えた（GatherTime がある）かつ、今の版を索引した
    # （DateModified が txt の更新日時を秒で切り捨てた値と同じ。Windows Search は秒未満を切り捨てて持つ）
    param (
        $gatherTime,
        $dateModified,
        [long]$fileTicksUtc
    )

    if ($null -eq $gatherTime -or $gatherTime -is [System.DBNull] -or $null -eq $dateModified -or $dateModified -is [System.DBNull]) {
        return $false
    }
    return ([datetime]$dateModified).Ticks -eq ($fileTicksUtc - ($fileTicksUtc % [timespan]::TicksPerSecond))
}

function testFolderInTarget {
    # フォルダ（TSV のフォルダ）が検索対象に入るか。recurse が $false なら対象フォルダそのものだけ
    param (
        [string]$folder,
        [string]$targetDir,
        [bool]$recurse
    )

    $target = $targetDir.TrimEnd("\")
    if ($folder.Equals($target, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $true
    }
    return ($recurse -and $folder.StartsWith("$target\", [System.StringComparison]::OrdinalIgnoreCase))
}

function convertFromSystemIndexState {
    # 状態ファイルの行を読む（パスは system_index からの相対パス）。形の違う行は無視する。
    #   Covered : 対応済みのインデックス名 / Pending: txt の相対パス → 書いた日時（Ticks）/ Excluded: 対象外のフォルダの相対パス
    param (
        [string[]]$lines
    )

    $state = newSystemIndexState
    foreach ($line in $lines) {
        $cells = ([string]$line).Split("`t")
        if ($cells.Count -lt 2 -or $cells[1] -eq "") {
            continue
        }
        switch ($cells[0]) {
            ${systemIndexCovered} { [void]$state.Covered.Add($cells[1]) }
            ${systemIndexExcluded} { [void]$state.Excluded.Add($cells[1]) }
            ${systemIndexPending} {
                $ticks = 0L
                if ($cells.Count -ge 3 -and [long]::TryParse($cells[2], [ref]$ticks)) {
                    $state.Pending[$cells[1]] = $ticks
                }
            }
        }
    }
    return $state
}

function newSystemIndexState {
    # 空の状態
    return @{
        Covered  = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
        Pending  = New-Object 'System.Collections.Generic.Dictionary[string,long]' ([System.StringComparer]::OrdinalIgnoreCase)
        Excluded = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    }
}

function convertToSystemIndexState {
    # 状態を状態ファイルの行にする（対応済み・対象外・反映待ちの順。それぞれ名前順）
    param (
        $state
    )

    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($name in ($state.Covered | Sort-Object)) {
        $lines.Add("${systemIndexCovered}`t$name`t")
    }
    foreach ($rel in ($state.Excluded | Sort-Object)) {
        $lines.Add("${systemIndexExcluded}`t$rel`t")
    }
    foreach ($rel in ($state.Pending.Keys | Sort-Object)) {
        $lines.Add("${systemIndexPending}`t$rel`t$($state.Pending[$rel])")
    }
    return , $lines.ToArray()
}

function getIndexNameOfRelPath {
    # system_index（index）からの相対パスの先頭（インデックス名）
    param (
        [string]$relPath
    )

    return ([string]$relPath).Split("\")[0]
}

# Windows Search への問い合わせ（OLE DB の Search.CollatorDSO）。読み取り（SELECT）だけを送る。
# 管理者権限は要らない。Windows Search のサービスが止まっている・ポリシーで無効なときは開けない（高速検索を使わない）。

function openWindowsSearch {
    # Windows Search への接続を開く。開けなければ $null
    try {
        $connection = New-Object System.Data.OleDb.OleDbConnection "Provider=Search.CollatorDSO;Extended Properties='Application=Windows';"
        $connection.Open()
        return $connection
    } catch {
        return $null
    }
}

function invokeWindowsSearch {
    # 問い合わせを実行し、行（object[]）の一覧を返す。SELECT 以外は送らない
    param (
        $connection,
        [string]$sql,
        [int]$timeoutSeconds = 10
    )

    if ($sql -notmatch "^\s*SELECT\s") {
        throw "Windows Search へは SELECT だけを送る: $sql"
    }
    $command = $connection.CreateCommand()
    $command.CommandText = $sql
    $command.CommandTimeout = $timeoutSeconds
    $rows = New-Object 'System.Collections.Generic.List[object[]]'
    $reader = $command.ExecuteReader()
    try {
        while ($reader.Read()) {
            $values = New-Object object[] $reader.FieldCount
            [void]$reader.GetValues($values)
            $rows.Add($values)
        }
    } finally {
        $reader.Dispose()
        $command.Dispose()
    }
    return , $rows
}

function getWindowsSearchState {
    # 高速検索に使えるかと、使えない理由。次のどれかの文字列を返す（画面の文言は ui/index/index_list_view.ps1 の getFastSearchRowView）。
    #   NoFolder     : system_index のフォルダが無い（インデックスを作っていない・ワークスペースが違う）
    #   NoConnection : Windows Search を開けない、または問い合わせに失敗した（時間切れを含む）
    #   NotInScope   : system_index が 0 件で、ワークスペースの中も 1 件も索引されていない（索引の対象外とみなす）
    #   NotYet       : system_index が 0 件だが、ワークスペースの中のほかのものは索引されている（対象だが、まだ索引されていないとみなす）
    #   Ok           : system_index が 1 件以上索引されている（フォルダ自体が SystemIndex に入っている）
    # 管理者権限なしに索引の対象の一覧を読む方法が無いため、NotInScope と NotYet はワークスペースの中の様子で見分ける。
    #   workspaceDir: 空なら、systemRoot の 1 つ上（ワークスペース）
    #   connection  : 開いた接続。$null なら自分で開いて閉じる（渡したら呼び出し側が閉じる）
    param (
        [string]$systemRoot = $workspace.SystemIndexDir,
        [string]$workspaceDir = "",
        $connection = $null
    )

    if (![System.IO.Directory]::Exists((toLongPath $systemRoot))) {
        return "NoFolder"
    }
    if (!$workspaceDir) {
        $workspaceDir = [System.IO.Path]::GetDirectoryName($systemRoot.TrimEnd("\"))
    }
    $own = $null -eq $connection
    if ($own) {
        $connection = openWindowsSearch
        if ($null -eq $connection) {
            return "NoConnection"
        }
    }
    try {
        $rows = invokeWindowsSearch $connection "SELECT TOP 1 System.ItemUrl FROM SystemIndex WHERE SCOPE='$(convertToScopeUrl $systemRoot)'"
        if ($rows.Count -gt 0) {
            return "Ok"
        }
        $rows = invokeWindowsSearch $connection "SELECT TOP 1 System.ItemUrl FROM SystemIndex WHERE SCOPE='$(convertToScopeUrl $workspaceDir)'"
        return $(if ($rows.Count -gt 0) { "NotYet" } else { "NotInScope" })
    } catch {
        return "NoConnection"
    } finally {
        if ($own) {
            $connection.Dispose()
        }
    }
}

function testWindowsSearch {
    # 高速検索に使えるか: Windows Search を開けて、system_index が索引の対象か（getWindowsSearchState が Ok）
    param (
        [string]$systemRoot = $workspace.SystemIndexDir
    )

    return (getWindowsSearchState $systemRoot) -eq "Ok"
}

function testTsvIndexedByWindowsSearch {
    # 本文インデックス（index の TSV）が Windows Search に索引されているか（利用者が対象から外していないか）。
    # 外していなくても結果は正しいが、txt の索引が遅くなるため、画面で案内を出すのに使う
    #   connection: 開いた接続。$null なら自分で開いて閉じる（渡したら呼び出し側が閉じる）
    param (
        [string]$indexRoot = $workspace.IndexDir,
        $connection = $null
    )

    $own = $null -eq $connection
    if ($own) {
        $connection = openWindowsSearch
        if ($null -eq $connection) {
            return $false
        }
    }
    try {
        $rows = invokeWindowsSearch $connection "SELECT TOP 1 System.ItemUrl FROM SystemIndex WHERE SCOPE='$(convertToScopeUrl $indexRoot)' AND System.FileExtension = '.tsv'"
        return $rows.Count -gt 0
    } catch {
        return $false
    } finally {
        if ($own) {
            $connection.Dispose()
        }
    }
}

# 高速検索: Windows Search で検索語を含みうるフォルダを先に絞り、照合する本文インデックスのファイルを集める（状態層）。
# 集めた本文インデックスのファイルは、今までどおり searchContentIndex で照合する。結果（行・行番号・順番）は、すべてを照合したときと同じになる:
#   反映済みの システムインデックスには、そのフォルダの本文インデックスのファイルのすべての 2-gram が入っていて、検索語の語はその一部のため、
#   当たる本文インデックスのファイルのフォルダは必ず候補に入る。反映済みでない・対象外・対応済みでないものは、候補に関係なく照合する。

function getReflectedSystemIndexEntries {
    # 状態ファイルの反映待ちの行を、Windows Search の索引と照らして、反映済みになったものとまだのものに分ける。
    # @{ Reflected（反映済みになった行の相対パス）; Unreflected（まだ反映されていない行があるフォルダの相対パス） } を返す。
    # 反映待ちが無ければ、Windows Search には問い合わせない。問い合わせに失敗したら例外のまま投げる
    #   ask: { param($sql) 行（object[]）の一覧 }（呼び出し元の $query・$connection を見る。& で呼ぶと呼び出し元の変数が見える）
    param (
        $state,
        [string]$systemRootPath,
        [scriptblock]$ask
    )

    $reflected = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    $unreflected = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    if ($state.Pending.Count -gt 0) {
        foreach ($row in (& $ask (newSystemIndexStateQuery $systemRootPath))) {
            $rel = getRelativePath (convertItemUrl ([string]$row[0])) $systemRootPath
            if ($rel -and $state.Pending.ContainsKey($rel) -and (testSystemIndexReflected $row[1] $row[2] $state.Pending[$rel])) {
                [void]$reflected.Add($rel)
            }
        }
        foreach ($rel in $state.Pending.Keys) {
            if (!$reflected.Contains($rel)) {
                [void]$unreflected.Add([System.IO.Path]::GetDirectoryName($rel))
            }
        }
    }
    return @{ Reflected = $reflected; Unreflected = $unreflected }
}

function getFastSearchContentIndexFiles {
    # 高速検索で照合する本文インデックスのファイルを、getContentIndexFiles と同じ形（@{ Folders; ContentIndexFiles }）に Fast（@{ Candidates; Unreflected }）を足して返す。
    # 高速検索を使えないとき（検索語から語を作れない・状態ファイルを読めない・Windows Search に問い合わせられない）は $null
    # （呼び出し側が getContentIndexFiles ですべての本文インデックスのファイルを集める）。
    #   folders: getContentIndexFiles と同じ（文字列、または @{ Root; RelPath; Recurse }）
    #   query  : { param($sql) 行（object[]）の一覧 }。$null なら Windows Search を開いて問い合わせる（テストで差し替える）
    param (
        [string]$word,
        [object[]]$folders,
        [scriptblock]$query = $null,
        [string]$indexRoot = $workspace.IndexDir,
        [string]$systemRoot = $workspace.SystemIndexDir,
        [string]$statePath = $workspace.SystemIndexStateFile,
        [scriptblock]$onProgress = $null
    )

    $grams = getSearchGrams $word
    if ($grams.Count -eq 0) {
        return $null
    }
    $state = readSystemIndexState $statePath
    if ($null -eq $state) {
        return $null
    }
    $connection = $null
    if ($null -eq $query) {
        $connection = openWindowsSearch
        if ($null -eq $connection) {
            return $null
        }
    }
    # 問い合わせ（差し替えが無ければ開いた接続で）。& で呼ぶと、この関数の $query・$connection が見える
    $ask = {
        param ($sql)
        if ($query) { & $query $sql } else { invokeWindowsSearch $connection $sql }
    }

    $indexRootPath = $indexRoot.TrimEnd("\")
    $systemRootPath = $systemRoot.TrimEnd("\")
    $targets = New-Object System.Collections.Generic.List[object]
    $candidates = 0
    try {
        # 反映の判定（状態ファイルに反映待ちがあるものだけ。反映済みになった行は、この後で状態から消す）
        $entries = getReflectedSystemIndexEntries $state $systemRootPath $ask
        $reflected = $entries.Reflected
        $unreflected = $entries.Unreflected

        foreach ($folder in $folders) {
            if ($folder -is [string]) {
                $folder = @{ Root = $folder; RelPath = ""; Recurse = $true }
            }
            $root = ([string]$folder.Root).TrimEnd("\")
            $relPath = ([string]$folder.RelPath).Trim("\")
            $targetDir = if ($relPath) { "$root\$relPath" } else { $root }
            # 別の場所のインデックス・インデックス全体・対応済みでないインデックス・無いフォルダは、今までどおりすべてを列挙する
            if (!$root.Equals($indexRootPath, [System.StringComparison]::OrdinalIgnoreCase) -or $relPath -eq "" -or
                !$state.Covered.Contains((getIndexNameOfRelPath $relPath)) -or ![System.IO.Directory]::Exists((toLongPath $targetDir))) {
                $targets.Add($folder)
                continue
            }
            $found = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
            $scopeDir = "$systemRootPath\$relPath"
            if ([System.IO.Directory]::Exists((toLongPath $scopeDir))) {
                foreach ($row in (& $ask (newSystemIndexQuery $scopeDir $grams))) {
                    $rel = getRelativePath ([System.IO.Path]::GetDirectoryName((convertItemUrl ([string]$row[0])))) $systemRootPath
                    if ($rel) { [void]$found.Add($rel) }
                }
                # 分けた txt は、語ごとに問い合わせ、すべての語がどれかの部分で見つかったフォルダを候補にする
                $split = $null
                foreach ($gram in $grams) {
                    $hit = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
                    foreach ($row in (& $ask (newSystemIndexSplitQuery $scopeDir $gram))) {
                        $rel = getRelativePath ([System.IO.Path]::GetDirectoryName((convertItemUrl ([string]$row[0])))) $systemRootPath
                        if ($rel) { [void]$hit.Add($rel) }
                    }
                    if ($null -eq $split) { $split = $hit } else { $split.IntersectWith($hit) }
                    if ($split.Count -eq 0) { break }
                }
                if ($split) { $found.UnionWith($split) }
            }
            $candidates += $found.Count
            $found.UnionWith($unreflected)
            $found.UnionWith($state.Excluded)
            foreach ($rel in $found) {
                $dir = "$indexRootPath\$rel"
                if ((testFolderInTarget $dir $targetDir ([bool]$folder.Recurse)) -and [System.IO.Directory]::Exists((toLongPath $dir))) {
                    $targets.Add(@{ Root = $indexRootPath; RelPath = $rel; Recurse = $false })
                }
            }
        }
    } catch {
        return $null
    } finally {
        if ($connection) {
            $connection.Dispose()
        }
    }

    $index = getContentIndexFiles $targets.ToArray() $onProgress
    if ($reflected.Count -gt 0) {
        # 反映済みになった行を消す（txt が書き直されて日時が変わった行は残す）。書けなくても検索は続ける。
        # 書き換えの中から見る値は、updateSystemIndexState の変数と名前が重ならないようにする（呼び出し先の $state が見えてしまう）
        $readTicks = $state.Pending
        [void](updateSystemIndexState {
            param ($current)
            foreach ($rel in $reflected) {
                if ($current.Pending.ContainsKey($rel) -and $current.Pending[$rel] -eq $readTicks[$rel]) {
                    [void]$current.Pending.Remove($rel)
                }
            }
        } $statePath)
    }
    $index.Fast = @{ Candidates = $candidates; Unreflected = $unreflected.Count }
    return $index
}

function getSystemIndexProgress {
    # システムインデックス（高速検索用の txt）が Windows Search にどこまで反映されたかを数える。画面が「確かめるとき」だけ呼ぶ（検索では呼ばない）。
    # @{ Folders; Waiting; ContentIndexed; ByIndex } を返す。状態ファイルを読めない・Windows Search に問い合わせられないときは $null。
    #   Folders       : txt があるフォルダと、状態ファイルの反映待ちのフォルダを合わせた数（分けた txt は 1 つのフォルダに数える）
    #   Waiting       : 反映待ちのうち、Windows Search でまだ反映済みでないフォルダの数（getFastSearchContentIndexFiles と同じ判定）
    #   ContentIndexed: 本文インデックス（index の TSV）も Windows Search に索引されているか（反映が遅い理由の案内に使う）
    #   ByIndex       : インデックス名（system_index からの相対パスの先頭のフォルダ名） → @{ Folders; Waiting } の辞書（OrdinalIgnoreCase）
    #   query         : getFastSearchContentIndexFiles と同じ。$null なら Windows Search を開いて問い合わせる（テストで差し替える）
    #   connection    : 開いた接続（渡したら呼び出し側が閉じる）。$null なら query が無いときだけ自分で開いて閉じる
    param (
        [scriptblock]$query = $null,
        [string]$indexRoot = $workspace.IndexDir,
        [string]$systemRoot = $workspace.SystemIndexDir,
        [string]$statePath = $workspace.SystemIndexStateFile,
        $connection = $null
    )

    $state = readSystemIndexState $statePath
    if ($null -eq $state) {
        return $null
    }
    $own = $false
    if ($null -eq $query -and $null -eq $connection) {
        $connection = openWindowsSearch
        if ($null -eq $connection) {
            return $null
        }
        $own = $true
    }
    # 問い合わせ（差し替えが無ければ開いた接続で）。& で呼ぶと、この関数の $query・$connection が見える
    $ask = {
        param ($sql)
        if ($query) { & $query $sql } else { invokeWindowsSearch $connection $sql }
    }

    $systemRootPath = $systemRoot.TrimEnd("\")
    try {
        $entries = getReflectedSystemIndexEntries $state $systemRootPath $ask
        $folders = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
        $longRoot = toLongPath $systemRootPath
        if ([System.IO.Directory]::Exists($longRoot)) {
            $pattern = "$([System.IO.Path]::GetFileNameWithoutExtension(${systemIndexFileName}))*.txt"
            foreach ($file in [System.IO.Directory]::EnumerateFiles($longRoot, $pattern, [System.IO.SearchOption]::AllDirectories)) {
                $rel = getRelativePath (fromLongPath ([System.IO.Path]::GetDirectoryName($file))) $systemRootPath
                if ($rel) { [void]$folders.Add($rel) }
            }
        }
        foreach ($key in $state.Pending.Keys) {
            [void]$folders.Add([System.IO.Path]::GetDirectoryName($key))
        }
        $contentIndexed = testTsvIndexedByWindowsSearch $indexRoot $connection
    } catch {
        return $null
    } finally {
        if ($own) {
            $connection.Dispose()
        }
    }
    $byIndex = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($rel in $folders) {
        $name = $rel.Split([char[]]"\")[0]
        if (!$byIndex.ContainsKey($name)) {
            $byIndex[$name] = @{ Folders = 0; Waiting = 0 }
        }
        $byIndex[$name].Folders++
    }
    foreach ($rel in $entries.Unreflected) {
        $name = $rel.Split([char[]]"\")[0]
        if ($byIndex.ContainsKey($name)) {
            $byIndex[$name].Waiting++
        }
    }
    return @{ Folders = $folders.Count; Waiting = $entries.Unreflected.Count; ContentIndexed = $contentIndexed; ByIndex = $byIndex }
}

# 検索結果の組み立て・書き出しと、インデックスの有無・件数（検索そのものは content_index_search.ps1）。

function toResultLine {
    # 検索結果1件を "ファイル名<TAB>場所<TAB>種別<TAB>行番号<TAB>該当行" に整形する。場所・種別は場所ごとの表記（describePlace。画面の見出しの要約と同じ）。
    # Excelに貼り付けたとき、該当行の各セルが元の列の順（5列目 = A列）に並ぶようにする
    param (
        [string]$book,
        [string]$location,
        [int]$lineNumber,
        [string]$line
    )

    if ($book -match "\.xls[a-z]?$") {
        # セル内改行を戻す（改行を含むセルは " で囲まれているため、貼り付けても1セルのまま）
        $line = $line.Replace(${cellNewLine}, "`n")
    } else {
        # Word・PowerPointの行（段落、または表の1行をタブ区切りにしたもの）は " で囲まれていない。
        # Excelは " で始まるセルを囲みの " と解釈して後続がずれるため、そのセルだけ " で囲む
        $line = @($line.Split("`t") | ForEach-Object {
            if ($_.StartsWith('"')) { '"' + $_.Replace('"', '""') + '"' } else { $_ }
        }) -join "`t"
    }
    # 場所（シート名）にタブ・改行が入っていると、列・行が分かれてしまうためスペースにする
    # （Excelのシート名はタブ・改行を含められる）
    $described = describePlace $book $location
    $place = [regex]::Replace($described.Place, '[\x00-\x1F]', " ")
    return "${book}`t${place}`t$($described.Kind)`t${lineNumber}`t${line}"
}

function toResultHeader {
    # 検索結果の見出し行 "ファイル名<TAB>場所<TAB>種別<TAB>行<TAB>A<TAB>B…" を返す（列名は columnCount 列分）
    param (
        [int]$columnCount
    )

    $names = New-Object System.Collections.Generic.List[string]
    $names.AddRange([string[]]@("ファイル名", "場所", "種別", "行"))
    for ($i = 1; $i -le $columnCount; $i++) {
        $names.Add((toColumnName $i))
    }
    return ($names -join "`t")
}


# 検索で読んだ本文インデックスのファイルの内容を残しておく量の上限（文字数。1 文字 2 バイトのため約 128MB）
${searchCacheMaxChars} = 64000000

function newTsvTextCache {
    # 検索で読んだ本文インデックスのファイルの内容を、次の検索で使い回すための入れ物を作る（画面が 1 つ持ち、検索のたびに searchContentIndex に渡す）。
    # 2 回目以降の検索ではファイルを開かない。更新日時・サイズが列挙したときと違う本文インデックスのファイル（書き直した等）は読み直す。
    # 並列検索の各スレッドから使うため、中身は ConcurrentDictionary。
    #   Texts: 本文インデックスのファイルの \\?\ 付きのパス → @(更新日時（UTC の Ticks）, サイズ, 内容, 場所の一覧, 最後に使った世代) / Chars: 残している文字数 / MaxChars: 上限
    #   Generation: 今の世代（検索 1 回ごとに trimTsvTextCache が 1 つ進める）
    param (
        [long]$maxChars = ${searchCacheMaxChars}
    )

    return @{
        Texts      = New-Object 'System.Collections.Concurrent.ConcurrentDictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
        Chars      = [long[]]::new(1)
        MaxChars   = $maxChars
        Generation = [long[]]::new(1)
    }
}

# 検索の後、キャッシュがこの割合を超えていたら、空きを作る（次の検索で新しく読んだものが入るように）
${searchCacheKeepRatio} = 0.9

function trimTsvTextCache {
    # 検索 1 回の後に呼ぶ（検索の司令のスレッド）。上限の keepRatio を超えていたら、今の世代で使わなかったものを、
    # 古い世代から追い出す（消した本文インデックスのファイル・検索しなくなったフォルダの分）。今の世代で使ったものは残す
    # （毎回同じ本文インデックスのファイルを順に読むため、使った順だけで追い出すと、上限より大きいインデックスでは何も残らない）。
    # 最後に世代を 1 つ進める。追い出した数を返す
    param (
        $cache,
        [double]$keepRatio = ${searchCacheKeepRatio}
    )

    $removed = 0
    [System.Threading.Monitor]::Enter($cache)
    try {
        $current = $cache.Generation[0]
        $limit = [long]($cache.MaxChars * $keepRatio)
        if ($cache.Chars[0] -gt $limit) {
            $old = @($cache.Texts.GetEnumerator() | Where-Object { $_.Value[4] -lt $current } | Sort-Object { $_.Value[4] })
            foreach ($item in $old) {
                if ($cache.Chars[0] -le $limit) {
                    break
                }
                $entry = $null
                if ($cache.Texts.TryRemove($item.Key, [ref]$entry)) {
                    $cache.Chars[0] -= $entry[2].Length
                    $removed++
                }
            }
        }
        $cache.Generation[0] = $current + 1
    } finally {
        [System.Threading.Monitor]::Exit($cache)
    }
    return $removed
}

function newSearchRequest {
    # 検索の要求 1 つを作る（画面が作り、検索の司令のスレッド（SearchService）が invokeSearchRequest で実行する）。
    # 画面と司令のスレッドの両方から読み書きするため、Synchronized の hashtable にする。
    #   画面が書く: 検索条件・Stop（取り消し）
    #   司令が書く: Queue（ヒット）・Done / Total / IndexTotal / Scanned（進み具合）・Folders・FastUsed / FastAvailable・Truncated / Cancelled / Error・Finished
    #   workDir: 高速検索で使うワークスペース（司令のスレッドは lib.ps1 を読み込んだときのワークスペースを覚えているため、画面から渡す）
    param (
        [string]$word,
        [bool]$simpleMatch,
        $folders,
        [int]$limit,
        [hashtable]$option = @{},
        [bool]$useFast = $false,
        [string]$workDir = $workspace.Dir
    )

    return [hashtable]::Synchronized(@{
        Word = $word; SimpleMatch = $simpleMatch; Folders = $folders; Limit = $limit; WorkDir = $workDir
        CaseSensitive = [bool]$option.CaseSensitive; FileFilter = (newFileKindFilter $option.FileKinds)
        IncludeShapes = ($option.IncludeShapes -ne $false); IncludeComments = ($option.IncludeComments -ne $false)
        UseFast = $useFast; FastUsed = $false; FastAvailable = $null
        Queue = New-Object 'System.Collections.Concurrent.ConcurrentQueue[object]'
        Stop = $false; Finished = $false; Done = 0; Total = -1; IndexTotal = -1; Scanned = 0
        Truncated = $false; Cancelled = $false; Error = $null
    })
}

function invokeSearchRequest {
    # 検索の要求（newSearchRequest）を実行し、ヒットと進み具合を要求に少しずつ入れる。最後に Finished を立てる。
    # 例外は投げずに Error に入れる。始める前に取り消されていたら（次の要求が来た等）、何もせずに Cancelled にする。
    #   pool : 照合のプール（newContentIndexWorkerPool）。$null なら searchContentIndex が必要なときだけ作る
    #   cache: 読んだ本文インデックスのファイルの内容の入れ物（newTsvTextCache）
    param (
        [hashtable]$request,
        $pool = $null,
        $cache = $null
    )

    try {
        if ($request.Stop) {
            $request.Cancelled = $true
            return
        }
        $word = $request.Word
        $folders = $request.Folders
        # 高速検索が使えるなら、Windows Search で検索語を含みうるフォルダを先に絞る（使えなければ $null で、すべてを集める）
        $index = $null
        if ($request.UseFast) {
            $own = [Workspace]::new($request.WorkDir)
            $request.FastAvailable = testWindowsSearch $own.SystemIndexDir
            if ($request.FastAvailable) {
                $index = getFastSearchContentIndexFiles $word $folders -indexRoot $own.IndexDir -systemRoot $own.SystemIndexDir -statePath $own.SystemIndexStateFile `
                    -onProgress { param ($count) $request.Scanned = $count }
            }
        }
        $request.FastUsed = ($null -ne $index)
        if ($null -eq $index) {
            # 途中の件数を画面に伝える（止まって見えないように）
            $index = getContentIndexFiles $folders { param ($count) $request.Scanned = $count }
        }
        $request.Folders = $index.Folders
        $request.Total = $index.ContentIndexFiles.Count
        $request.IndexTotal = $index.ContentIndexFiles.Count
        $result = searchContentIndex $word $index.ContentIndexFiles $request.SimpleMatch $request.Limit -caseSensitive $request.CaseSensitive `
            -fileFilter $request.FileFilter -cache $cache -includeShapes $request.IncludeShapes -includeComments $request.IncludeComments -pool $pool `
            -onProgress {
            param ($done, $total, $newHits)
            foreach ($hit in $newHits) {
                $request.Queue.Enqueue($hit)
            }
            $request.Total = $total
            $request.Done = $done
        } -shouldStop { $request.Stop }
        $request.Total = $result.Total
        $request.Truncated = $result.Truncated
        $request.Cancelled = $result.Cancelled
    } catch {
        $request.Error = $_.Exception.Message
    } finally {
        $request.Finished = $true
    }
}

function testIndexExists {
    # 検索対象インデックスに本文インデックスのファイルが1件でもあるか（最初の1件が見つかった時点で打ち切る）
    param (
        [string[]]$folders = @($workspace.IndexDir)
    )

    foreach ($dir in $folders) {
        if (!(Test-Path -LiteralPath $dir -PathType Container)) {
            continue
        }
        try {
            # 1 件見つけたらやめる。列挙子を閉じずに戻ると content_index の下のフォルダを掴んだまま残り、
            # 続くインポートの上書きで移動できなくなるため testAnyEntry を通す
            if (testAnyEntry ([System.IO.Directory]::EnumerateFiles((toLongPath (Resolve-Path -LiteralPath $dir).ProviderPath), ${contentIndexFilePattern}, [System.IO.SearchOption]::AllDirectories))) {
                return $true
            }
        } catch {
            # アクセスできないフォルダがある場合は、件数を数える方で判定する
            if (@(Get-ChildItem -LiteralPath $dir -Filter ${contentIndexFilePattern} -File -Recurse -ErrorAction SilentlyContinue).Count -gt 0) {
                return $true
            }
        }
    }
    return $false
}

function getIndexSummary {
    # 検索対象インデックスの本文インデックスのファイルの件数と最新の更新日時を返す: @{ Count; LastWrite（無ければ $null）; Missing（存在しないフォルダ） }
    param (
        [string[]]$folders = @($workspace.IndexDir)
    )

    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $summary = @{ Count = 0; LastWrite = $null; Missing = @() }
    foreach ($dir in $folders) {
        if (!(Test-Path -LiteralPath $dir -PathType Container)) {
            $summary.Missing += $dir
            continue
        }
        $longDir = toLongPath (Resolve-Path -LiteralPath $dir).ProviderPath
        # アクセスできないフォルダがあると .NET の列挙は途中で止まるため、そのときは Get-ChildItem で数える（読めるものだけ）
        try {
            $found = [System.IO.DirectoryInfo]::new($longDir).GetFiles(${contentIndexFilePattern}, [System.IO.SearchOption]::AllDirectories)
        } catch {
            $found = @(Get-ChildItem -LiteralPath $longDir -Filter ${contentIndexFilePattern} -File -Recurse -ErrorAction SilentlyContinue)
        }
        foreach ($file in $found) {
            if (!$seen.Add($file.FullName)) {
                continue
            }
            $summary.Count++
            if ($null -eq $summary.LastWrite -or $file.LastWriteTime -gt $summary.LastWrite) {
                $summary.LastWrite = $file.LastWriteTime
            }
        }
    }
    return $summary
}

function toSearchResultLines {
    # 検索結果を検索結果ファイルの形式にし、@{ Header（見出し行）; Lines } を返す（画面のファイル出力・コピーで共通）。
    # Excelに貼り付けたときに元のセル位置が分かるよう、行番号（TSVの行番号 = Excelの行番号）を付け、
    # 見出しには該当行の最大セル数分の列名（A, B, C…）を付ける
    param (
        [object[]]$hits
    )

    $lines = New-Object System.Collections.Generic.List[string]
    $columnCount = 0
    foreach ($hit in $hits) {
        # ファイル名の前に、クロール対象フォルダからの相対フォルダを付ける
        $line = toResultLine $hit.Book $hit.Location $hit.LineNumber $hit.Line
        if ($hit.RelDir) {
            $line = "$($hit.RelDir)\${line}"
        }
        $lines.Add($line)
        $columnCount = [math]::Max($columnCount, (countTsvFields $line) - 4)  # ファイル名・場所・種別・行番号の4列を除く
    }
    return @{ Header = (toResultHeader $columnCount); Lines = $lines }
}

function writeSearchResult {
    # 1ワード分の検索結果を検索結果ファイルに書き出す
    param (
        [System.IO.TextWriter]$writer,
        [string]$word,
        [object[]]$hits
    )

    $result = toSearchResultLines $hits
    $writer.WriteLine("【検索文字列　${word}】 $($result.Lines.Count) 件")
    $writer.WriteLine($result.Header)
    foreach ($line in $result.Lines) {
        $writer.WriteLine($line)
    }
    $writer.WriteLine("")
}

# 検索用の本文インデックスのファイル（content_index_format.ps1）を検索する。
# 本文インデックスのファイルの全文に 1 回照合し、一致しないファイルは飛ばす。一致したら、位置から場所と行を求める。
# 照合のしかた（lines・filter・scan。search_query.ps1 の getRegexScanMode）で、全文への照合と 1 行ずつの照合の結果を同じにする。
# Excel の図形・コメントの行は「セル番地 + タブ + 文字」の形のため、区切りのタブより後から始まる一致だけをヒットにする（セル番地だけの一致を除く）。

function testCellPrefixedHit {
    # セル番地 + 区切りのタブ + 文字 の行で、区切りのタブ（最初のタブ）より後から始まる一致があるか。文字の中のタブは文字として扱う。
    # 開始位置つきの照合なので、後読みは前の文字（区切りのタブ）も見える。区切りのタブが無い行は一致なし
    param (
        [regex]$regex,
        [string]$line
    )

    $tab = $line.IndexOf([char]9)
    return ($tab -ge 0) -and $regex.IsMatch($line, $tab + 1)
}


function searchContentIndexFiles {
    # contentIndexFiles の start から count 件の本文インデックスのファイルを読み、regex に一致する行を PSCustomObject で返す（1 行に複数一致しても 1 件）。
    # max 以上（max+1 件目）が見つかった時点で打ち切る（負は上限なし）。読めないファイルは飛ばす。
    #   include / exclude: 元のファイル名の条件（$null は条件なし） / excludePlace: 除く場所（図形・コメント）
    #   cache: newTsvTextCache。更新日時・大きさが同じなら、前に読んだ内容と場所の一覧を使う
    # 照合が時間切れ（RegexMatchTimeoutException）なら、そのまま呼び出し元へ伝える
    param (
        $contentIndexFiles,
        [int]$start,
        [int]$count,
        [regex]$regex,
        [int]$max,
        [regex]$textRegex = $null,
        [string]$scanMode = "scan",
        $cache = $null,
        [regex]$include = $null,
        [regex]$exclude = $null,
        [regex]$excludePlace = $null
    )

    # 並列検索の別スレッドでも動くよう、コマンドレットは使わない
    $hits = [System.Collections.Generic.List[psobject]]::new()
    $end = [Math]::Min($contentIndexFiles.Count, $start + $count)
    $lf = [char]10
    $mark = [char]0x1E
    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $mode = if ($null -eq $textRegex) { "scan" } else { $scanMode }
    for ($i = $start; $i -lt $end; $i++) {
        $contentIndexFile = $contentIndexFiles[$i]
        $text = $null
        $places = $null
        $cached = $false
        if ($null -ne $cache) {
            $entry = $null
            if ($cache.Texts.TryGetValue($contentIndexFile.Path, [ref]$entry) -and $entry[0] -eq $contentIndexFile.Ticks -and $entry[1] -eq $contentIndexFile.Size) {
                $text = $entry[2]
                $places = $entry[3]
                $cached = $true
                # この検索で使ったことを残す（trimTsvTextCache は、使われていない古いものから追い出す）
                $entry[4] = $cache.Generation[0]
            }
        }
        if ($null -eq $text) {
            try {
                $stream = [System.IO.FileStream]::new($contentIndexFile.Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
                $reader = [System.IO.StreamReader]::new($stream, [System.Text.Encoding]::Unicode, $true)
                try { $text = $reader.ReadToEnd() } finally { $reader.Dispose() }
            } catch [System.IO.IOException] {
                continue
            } catch [System.UnauthorizedAccessException] {
                continue
            }
        }
        # 一致しなければ、場所の一覧も作らずに次へ（場所の一覧は、一致したときか、キャッシュに入れるときだけ作る）。
        # 全文への照合が時間切れなら、このファイルは 1 行ずつ照合する
        $contentIndexMode = $mode
        $matched = $true
        if ($contentIndexMode -ne "scan") {
            try {
                $matched = $textRegex.IsMatch($text)
            } catch [System.Text.RegularExpressions.RegexMatchTimeoutException] {
                $contentIndexMode = "scan"
            }
        }
        if ($null -eq $places -and ($matched -or $null -ne $cache)) {
            $places = readContentIndexPlaces $text
        }
        if ($null -ne $cache -and !$cached) {
            [System.Threading.Monitor]::Enter($cache)
            try {
                $old = $null
                if ($cache.Texts.TryRemove($contentIndexFile.Path, [ref]$old)) {
                    $cache.Chars[0] -= $old[2].Length
                }
                if ($cache.Chars[0] + $text.Length -le $cache.MaxChars) {
                    $cache.Texts[$contentIndexFile.Path] = [object[]]@($contentIndexFile.Ticks, $contentIndexFile.Size, $text, $places, $cache.Generation[0])
                    $cache.Chars[0] += $text.Length
                }
            } finally {
                [System.Threading.Monitor]::Exit($cache)
            }
        }
        if (!$matched) { continue }

        $before = $hits.Count
        $lineMode = $contentIndexMode -eq "lines"
        if ($lineMode) {
            try {
                $length = $text.Length
                $p = 0            # 今の場所（places の番号）
                $number = 0       # 今の場所で、pos までに数えた行の数
                $pos = -1         # 行を数え終えた位置（-1 は場所が変わったので数え直し）
                $lastP = -1       # 直前に判定した場所の番号（isTextBook を場所が変わったときだけ判定し直す）
                $isTextBook = $false
                $m = $textRegex.Match($text)
                while ($m.Success) {
                    $index = $m.Index
                    if ($index -ge $length) { break }
                    $lineStart = if ($index -eq 0) { 0 } else { $text.LastIndexOf($lf, $index - 1) + 1 }
                    $lineEnd = $text.IndexOf($lf, $index)
                    if ($lineEnd -lt 0) { $lineEnd = $length }
                    if ($lineStart -lt $length -and $text[$lineStart] -eq $mark) {
                        # メタ情報の行（ファイル名・場所の名前）の中の一致は捨てる
                        if ($lineEnd -ge $length) { break }
                        $m = $textRegex.Match($text, $lineEnd + 1)
                        continue
                    }
                    while ($p -lt $places.Count -and $places[$p].End -le $lineStart) { $p++; $pos = -1 }
                    if ($p -ge $places.Count) { break }
                    $place = $places[$p]
                    if ($p -ne $lastP) {
                        $isTextBook = ((getContentIndexFileKind $place.Book) -eq "テキスト")
                        $lastP = $p
                    }
                    $skip = ($include -and !$include.IsMatch($place.Book)) -or ($exclude -and $exclude.IsMatch($place.Book)) -or
                        ($excludePlace -and $excludePlace.IsMatch($place.Location))
                    if ($skip) {
                        if ($place.End -ge $length) { break }
                        $m = $textRegex.Match($text, $place.End)
                        continue
                    }
                    if ($pos -lt 0) { $pos = $place.Start; $number = 1 }
                    # 前に数えた位置から行の先頭までの改行を数える（Substring を作らない）
                    while ($pos -lt $lineStart) {
                        $n = $text.IndexOf($lf, $pos, $lineStart - $pos)
                        if ($n -lt 0) { break }
                        $number++
                        $pos = $n + 1
                    }
                    $pos = $lineStart
                    $line = $text.Substring($lineStart, $lineEnd - $lineStart)
                    if ($place.CellPrefixed -and !(testCellPrefixedHit $regex $line)) {
                        # セル番地だけに一致した行はヒットにしない（行番号の数え方は崩さない）
                        if ($lineEnd -ge $length) { break }
                        $m = $textRegex.Match($text, $lineEnd + 1)
                        continue
                    }
                    if ($isTextBook) {
                        $line = truncateHitLine $line ($index - $lineStart)
                    }
                    $hits.Add([pscustomobject]@{
                        Root = $contentIndexFile.Root; RelPath = $contentIndexFile.RelPath; RelDir = $contentIndexFile.RelDir; FileName = $place.Book
                        Book = $place.Book; Location = $place.Location; LineNumber = $number; Line = $line
                    })
                    if ($max -ge 0 -and $hits.Count -gt $max) { return , $hits }
                    if ($lineEnd -ge $length) { break }
                    $m = $textRegex.Match($text, $lineEnd + 1)
                }
                continue
            } catch [System.Text.RegularExpressions.RegexMatchTimeoutException] {
                # 全文への照合が時間切れなら、1 行ずつ照合し直す
                if ($hits.Count -gt $before) { $hits.RemoveRange($before, $hits.Count - $before) }
            }
        }
        # filter・scan（と lines の時間切れ）: 場所ごとに 1 行ずつ照合する
        foreach ($place in $places) {
            if ($include -and !$include.IsMatch($place.Book)) { continue }
            if ($exclude -and $exclude.IsMatch($place.Book)) { continue }
            if ($excludePlace -and $excludePlace.IsMatch($place.Location)) { continue }
            $isTextBook = ((getContentIndexFileKind $place.Book) -eq "テキスト")
            $number = 0
            $pos = $place.Start
            while ($pos -lt $place.End) {
                $n = $text.IndexOf($lf, $pos, $place.End - $pos)
                if ($n -lt 0) { $n = $place.End }
                $number++
                $line = $text.Substring($pos, $n - $pos)
                $pos = $n + 1
                $lineMatch = $regex.Match($line)
                if (!$lineMatch.Success) { continue }
                if ($place.CellPrefixed -and !(testCellPrefixedHit $regex $line)) { continue }
                if ($isTextBook) {
                    $line = truncateHitLine $line $lineMatch.Index
                }
                $hits.Add([pscustomobject]@{
                    Root = $contentIndexFile.Root; RelPath = $contentIndexFile.RelPath; RelDir = $contentIndexFile.RelDir; FileName = $place.Book
                    Book = $place.Book; Location = $place.Location; LineNumber = $number; Line = $line
                })
                if ($max -ge 0 -and $hits.Count -gt $max) { return , $hits }
            }
        }
    }
    return , $hits
}


# 本文インデックスのファイルの検索で、1 つのスレッドにまとめて渡す大きさの目安（バイト）
${contentIndexTaskBytes} = 16MB

# 本文インデックスのファイルの検索の各スレッドで動かすスクリプト。@{ Hits; Timeout } を返す
${contentIndexWorkerScript} = {
    param ($contentIndexFiles, $start, $count, $regex, $max, $textRegex, $scanMode, $cache, $include, $exclude, $excludePlace)
    try {
        $hits = searchContentIndexFiles $contentIndexFiles $start $count $regex $max $textRegex $scanMode $cache $include $exclude $excludePlace
        @{ Hits = $hits; Timeout = $false }
    } catch {
        if ($_.Exception -is [System.Text.RegularExpressions.RegexMatchTimeoutException] -or
            $_.Exception.InnerException -is [System.Text.RegularExpressions.RegexMatchTimeoutException]) {
            @{ Hits = $null; Timeout = $true }
        } else {
            throw
        }
    }
}


function newContentIndexWorkerPool {
    # 本文インデックスのファイルの照合のプール（WorkerPool）を作る。各スレッドには照合に要る関数と値だけを読み込む。
    # 利用者が結果を待つ処理のため、優先度は下げない（docs/design/structure/threads.md「スレッドの一覧」）
    param (
        [int]$workers = (getWorkerCount)
    )

    $state = newWorkerState @("searchContentIndexFiles", "testCellPrefixedHit", "readContentIndexPlaces", "testContentIndexCellPrefixed", "convertContentIndexMetaToPlace", "decodeContentIndexValue", "getContentIndexFileKind", "testTextExtension", "testPdfExtension", "truncateHitLine") `
        @("contentIndexMark", "contentIndexVersion", "contentIndexPlaceKeys", "placeKindShape", "placeKindComment", "placeKindHeaderFooter", "placeKindEmbed", "textExtensions", "pdfExtensions", "hitLineMaxChars", "hitLineBeforeMatchChars")
    return [WorkerPool]::new($workers, $state, $Host, "Normal")
}


function splitContentIndexTasks {
    # 本文インデックスのファイルの並びを、1 つのスレッドに渡す単位（@{ Start; Count }）に分ける（合計がおよそ contentIndexTaskBytes になるまでまとめる）
    param (
        $contentIndexFiles,
        [long]$taskBytes = ${contentIndexTaskBytes}
    )

    $tasks = New-Object System.Collections.Generic.List[hashtable]
    $start = 0
    $bytes = 0L
    for ($i = 0; $i -lt $contentIndexFiles.Count; $i++) {
        $bytes += [long]$contentIndexFiles[$i].Size
        if ($bytes -ge $taskBytes -or $i -eq $contentIndexFiles.Count - 1) {
            $tasks.Add(@{ Start = $start; Count = $i - $start + 1 })
            $start = $i + 1
            $bytes = 0L
        }
    }
    return , $tasks
}


function searchContentIndex {
    # 本文インデックスのファイルをワードで検索し、ヒットした行を返す（画面の検索処理）。
    #   contentIndexFiles        : findContentIndexFiles・getContentIndexFiles の結果
    #   simpleMatch  : $true なら文字どおりに検索する。$false なら正規表現として検索し、正規表現として不正なら文字どおりに検索する
    #   limit        : 件数の上限（0 は上限なし）。超えたら打ち切る
    #   shouldStop   : $true を返すと中止する
    #   caseSensitive: 英字の大文字・小文字を区別する（newSearchRegex）
    #   fileFilter   : 対象ファイル（newFileFilter）。元のファイル名が一致しないものは検索しない
    #   workerCount  : 並列に検索するスレッドの数（0 は CPU のコア数から決める。最大 4）
    #   cache        : 読んだ本文インデックスのファイルの内容を次の検索で使い回す入れ物（newTsvTextCache。$null は使い回さない）
    #   includeShapes / includeComments: 図形・コメントの場所（"<シート名>[図形]" 等）も検索する（newPlaceExclude）
    #   taskBytes    : 1 つのスレッドにまとめて渡す大きさの目安（バイト）
    #   onProgress   : 1 つの作業を照合するたびに呼ぶ { param($done, $total, $newHits) }（done・total は本文インデックスのファイルの数）
    #   pool         : 照合に使うプール（newContentIndexWorkerPool。検索の司令が使い回す）。$null なら、並列にするときだけ作って最後に閉じる
    # @{ Hits; SimpleMatch（実際に文字どおり検索したか）; Total（本文インデックスのファイルの数）; Truncated; Cancelled } を返す。
    # Hits の各要素は PSCustomObject（Root; RelPath（本文インデックスのファイル）; RelDir; FileName; Book; Location; LineNumber; Line）
    param (
        [string]$word,
        $contentIndexFiles,
        [bool]$simpleMatch = $false,
        [int]$limit = 0,
        [scriptblock]$shouldStop = $null,
        [bool]$caseSensitive = $false,
        [string]$fileFilter = "",
        [int]$workerCount = 0,
        $cache = $null,
        [bool]$includeShapes = $true,
        [bool]$includeComments = $true,
        [long]$taskBytes = ${contentIndexTaskBytes},
        [scriptblock]$onProgress = $null,
        $pool = $null
    )

    $search = newSearchRegex $word $simpleMatch $caseSensitive
    $filter = newFileFilter $fileFilter
    $excludePlace = newPlaceExclude $includeShapes $includeComments
    $hits = New-Object System.Collections.Generic.List[psobject]
    $result = @{ Hits = $hits; SimpleMatch = $search.SimpleMatch; Total = $contentIndexFiles.Count; Truncated = $false; Cancelled = $false }
    $timeoutMessage = "正規表現の照合に時間がかかりすぎるため、検索を中止しました。正規表現を見直してください。"
    $tasks = splitContentIndexTasks $contentIndexFiles $taskBytes
    $workers = if ($pool) { $pool.Size } elseif ($workerCount -gt 0) { $workerCount } else { getWorkerCount }
    if ($tasks.Count -lt 2) { $workers = 1 }

    $ownPool = $null
    $pending = New-Object System.Collections.Generic.Queue[hashtable]
    try {
        if ($workers -le 1) {
            $pool = $null
        } elseif ($null -eq $pool) {
            $ownPool = newContentIndexWorkerPool $workers
            $pool = $ownPool
        }
        $next = 0
        while ($next -lt $tasks.Count -or $pending.Count -gt 0) {
            if ($shouldStop -and (& $shouldStop)) {
                $result.Cancelled = $true
                break
            }
            if ($pool) {
                while ($pending.Count -lt $workers * 2 -and $next -lt $tasks.Count) {
                    $max = if ($limit -gt 0) { $limit - $hits.Count } else { -1 }
                    $task = $tasks[$next]
                    $job = $pool.Submit(${contentIndexWorkerScript}.ToString(), @($contentIndexFiles, $task.Start, $task.Count, $search.Regex, $max, $search.TextRegex,
                            $search.ScanMode, $cache, $filter.Include, $filter.Exclude, $excludePlace))
                    $job.Done = $task.Start + $task.Count
                    $pending.Enqueue($job)
                    $next++
                }
                $output = $pool.Receive($pending.Dequeue())
                if ($output[0].Timeout) { throw $timeoutMessage }
                $newHits = $output[0].Hits
                $done = $job.Done
            } else {
                $task = $tasks[$next]
                $next++
                $done = $task.Start + $task.Count
                $max = if ($limit -gt 0) { $limit - $hits.Count } else { -1 }
                try {
                    $newHits = searchContentIndexFiles $contentIndexFiles $task.Start $task.Count $search.Regex $max $search.TextRegex $search.ScanMode $cache $filter.Include $filter.Exclude $excludePlace
                } catch [System.Text.RegularExpressions.RegexMatchTimeoutException] {
                    throw $timeoutMessage
                }
            }
            $max = if ($limit -gt 0) { $limit - $hits.Count } else { -1 }
            if ($max -ge 0 -and $newHits.Count -gt $max) {
                $newHits.RemoveRange($max, $newHits.Count - $max)
                $result.Truncated = $true
            }
            $hits.AddRange($newHits)
            if ($onProgress) {
                & $onProgress $done $contentIndexFiles.Count $newHits
            }
            if ($result.Truncated) { break }
        }
    } finally {
        foreach ($job in $pending) {
            $pool.Cancel($job)
        }
        if ($ownPool) { $ownPool.Close() }
    }
    return $result
}


function getContentIndexFiles {
    # 検索対象の本文インデックスのファイルを集め、@{ Folders; ContentIndexFiles } を返す。
    #   folders: 検索対象インデックスのフォルダ（文字列。フォルダ以下すべて）、または
    #            @{ Root（インデックスのフォルダ）; RelPath（その中のフォルダ。空は Root 自身）; Recurse（$false は直下のファイルだけ） }
    #   Folders: フォルダごとの @{ Path; Root（フルパス）; Exists; Count }
    #   ContentIndexFiles  : findContentIndexFiles の結果をつないだもの（入れ子のフォルダを選んでも重複しない）
    #   onProgress: 数えた件数を知らせる { param($count) }
    param (
        [object[]]$folders = @($workspace.IndexDir),
        [scriptblock]$onProgress = $null
    )

    $folderInfo = New-Object System.Collections.Generic.List[object]
    $contentIndexFiles = New-Object System.Collections.Generic.List[hashtable]
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($target in $folders) {
        if ($target -is [string]) {
            $target = @{ Root = $target; RelPath = ""; Recurse = $true }
        }
        $relPath = ([string]$target.RelPath).Trim("\")
        $dir = if ($relPath) { "$(([string]$target.Root).TrimEnd('\'))\${relPath}" } else { [string]$target.Root }
        if (!(Test-Path -LiteralPath $target.Root -PathType Container) -or ![System.IO.Directory]::Exists((toLongPath $dir))) {
            $folderInfo.Add(@{ Path = $dir; Root = ""; Exists = $false; Count = 0 })
            continue
        }
        $root = (Resolve-Path -LiteralPath $target.Root).ProviderPath.TrimEnd("\")
        $found = findContentIndexFiles $root $relPath ([bool]$target.Recurse)
        $folderInfo.Add(@{ Path = $dir; Root = $root; Exists = $true; Count = $found.Count })
        foreach ($contentIndexFile in $found) {
            if ($seen.Add($contentIndexFile.Path)) { $contentIndexFiles.Add($contentIndexFile) }
        }
        if ($onProgress) { & $onProgress $contentIndexFiles.Count }
    }
    # フォルダの順、フォルダの中は名前の順（findContentIndexFiles と同じ）。検索対象を複数選んだときも順が崩れないよう並べ直す
    $sorted = [hashtable[]]@($contentIndexFiles | Sort-Object @{ Expression = { $_.Root } }, @{ Expression = { $_.RelDir } }, @{ Expression = { [System.IO.Path]::GetFileName($_.RelPath) } })
    return @{ Folders = $folderInfo.ToArray(); ContentIndexFiles = $sorted }
}
# 検索の司令のスレッド（SearchService）。画面を開いている間 1 つだけ動かし、検索の要求（newSearchRequest）を順に実行する。
# lib.ps1 の読み込みと照合のプールの用意は、スレッドを始めたときに 1 回だけ行う（検索のたびに行わない）。
# 設計は docs/design/structure/threads.md「スレッドの一覧」「寿命」。
#
# SearchService は画面のスレッドだけから呼ぶ（PowerShell 5.1 のクラスのメソッドは、定義したランスペースで動くため）。
# スレッドをまたいで使う要求は、Synchronized の hashtable（newSearchRequest）にする。

# 司令のスレッドで動かすスクリプト。要求の列が閉じられる（Close）まで、要求を 1 つずつ実行する。
# lib の部品（Prelude）は SearchService.Start が、この param ブロックのあとにつなぐ（joinWorkerScript）
${searchServiceScript} = {
    param ($requests, $cache, $workers)
    # 読み込めなければスレッドを終える（画面は IsRunning・GetFailure で知り、次の要求で作り直す）
    $ErrorActionPreference = "Stop"
    initWorkspace
    $ErrorActionPreference = "Continue"
    $pool = if ($workers -gt 1) { newContentIndexWorkerPool $workers } else { $null }
    try {
        foreach ($request in $requests.GetConsumingEnumerable()) {
            invokeSearchRequest $request $pool $cache
            if ($cache) {
                [void](trimTsvTextCache $cache)
            }
        }
    } finally {
        if ($pool) {
            $pool.Close()
        }
    }
}

# 閉じるときに、実行中の検索が止まるのを待つ時間（ミリ秒）。過ぎたらスレッドを止める
${searchServiceCloseMilliseconds} = 5000

class SearchService {
    # 照合のプールのスレッドの数
    [int]$Workers
    hidden [string]$Script
    hidden [hashtable]$LibLoad
    hidden $Cache
    hidden [int]$CloseMilliseconds
    hidden [System.Collections.Concurrent.BlockingCollection[hashtable]]$Requests
    hidden [System.Management.Automation.Runspaces.Runspace]$Runspace
    hidden [powershell]$PowerShell
    hidden [System.IAsyncResult]$Handle
    # いま実行している（最後に渡した）要求
    hidden [hashtable]$Current

    SearchService([string]$script, [hashtable]$libLoad, $cache, [int]$workers, [int]$closeMilliseconds) {
        $this.Script = $script
        $this.LibLoad = $libLoad
        $this.Cache = $cache
        $this.Workers = [Math]::Max(1, $workers)
        $this.CloseMilliseconds = $closeMilliseconds
        $this.Start()
    }

    hidden [void] Start() {
        $this.Requests = New-Object 'System.Collections.Concurrent.BlockingCollection[hashtable]'
        $rs = [runspacefactory]::CreateRunspace($this.LibLoad.State)
        $rs.Open()
        $ps = [powershell]::Create()
        $ps.Runspace = $rs
        $joined = if ($this.LibLoad.Prelude) { joinWorkerScript $this.LibLoad.Prelude $this.Script } else { $this.Script }
        [void]$ps.AddScript($joined).AddArgument($this.Requests).AddArgument($this.Cache).AddArgument($this.Workers)
        $this.Runspace = $rs
        $this.PowerShell = $ps
        $this.Handle = $ps.BeginInvoke()
    }

    [bool] IsRunning() {
        # 司令のスレッドが動いているか（lib.ps1 を読み込めなかった等で止まっていれば $false）
        return $null -ne $this.PowerShell -and !$this.Handle.IsCompleted
    }

    [string] GetFailure() {
        # 司令のスレッドが止まっていれば、その理由（無ければ空）
        if ($null -eq $this.PowerShell -or !$this.Handle.IsCompleted) {
            return ""
        }
        if ($this.PowerShell.Streams.Error.Count -gt 0) {
            return $this.PowerShell.Streams.Error[0].ToString()
        }
        return "検索のスレッドが止まりました。"
    }

    [hashtable] Request([hashtable]$request) {
        # 要求を渡す。実行中の要求は取り消す（次の要求が先に始まる）。司令のスレッドが止まっていれば作り直す
        $this.Cancel()
        if (!$this.IsRunning()) {
            $this.Shutdown()
            $this.Start()
        }
        $this.Current = $request
        $this.Requests.Add($request)
        return $request
    }

    [void] Cancel() {
        # 実行中の要求を取り消す（照合の作業の切れ目で止まる）
        if ($this.Current) {
            $this.Current.Stop = $true
        }
    }

    [void] Close() {
        # 検索を取り消し、司令のスレッドと照合のプールを片づける。何度呼んでもよい
        $this.Cancel()
        $this.Shutdown()
        $this.Current = $null
    }

    hidden [void] Shutdown() {
        if ($this.Requests) {
            $this.Requests.CompleteAdding()
        }
        if ($this.PowerShell) {
            if (!$this.Handle.AsyncWaitHandle.WaitOne($this.CloseMilliseconds)) {
                try {
                    $this.PowerShell.Stop()
                } catch {
                }
            }
            $this.PowerShell.Dispose()
            $this.PowerShell = $null
        }
        if ($this.Runspace) {
            $this.Runspace.Dispose()
            $this.Runspace = $null
        }
        if ($this.Requests) {
            $this.Requests.Dispose()
            $this.Requests = $null
        }
    }
}

function newSearchService {
    # 検索の司令のスレッドを始める（画面を開いたときに 1 回）。閉じるときは Close を呼ぶ
    param (
        $cache = $null,
        [int]$workers = (getWorkerCount)
    )

    $libLoad = getPartLoad lib
    return [SearchService]::new(${searchServiceScript}.ToString(), $libLoad, $cache, $workers, ${searchServiceCloseMilliseconds})
}

# 検索結果から元のファイルの場所を求める（source_folder.txt の読み書きを含む）。

function writeSourceFolderFile {
    # 各インデックスのフォルダに、インデックス名とクロール対象フォルダの対応（source_folder.txt）を書き出す。
    # 1行目は説明、2行目は "インデックス名<TAB>クロール対象フォルダ"。
    # インデックス1件につき1ファイルのため、<インデックス名> のフォルダだけを別の PC・場所へコピーしても
    # 元のファイルの場所が分かる（work\index ごとコピーした場合は readSourceFolderFile が各フォルダを読む）
    param (
        [object[]]$folders,  # assignIndexNames の結果（@{ Path; Name }）
        [string]$dir = $workspace.IndexDir
    )

    $header = "# 検索結果から元のファイルを開くときに使う、インデックス名とクロール対象フォルダの対応です（インデックス作成のたびに作り直します）"
    $items = @($folders | Where-Object { $_ -and $_.Name })
    foreach ($folder in $items) {
        # インデックスのフォルダがまだ無い（1件も取り込んでいない）場合は作らない
        $indexPath = Join-Path $dir $folder.Name
        if (Test-Path -LiteralPath (toLongPath $indexPath) -PathType Container) {
            $sourceFilePath = Join-Path $indexPath ${sourceFolderFileName}
            writeListFile $sourceFilePath @($header, "$($folder.Name)`t$($folder.Path)")
            # 画面（インデックス一覧の保存）からも呼ばれるため、書いたファイルだけに付ける（件数が多いため失敗してもログに出さない）
            [void](setNotContentIndexed $sourceFilePath)
        }
    }
}

function readSourceFolderFile {
    # インデックスのフォルダ（dir）直下の source_folder.txt を読み、インデックス名 → クロール対象フォルダ を返す
    # （大文字・小文字を区別しない）。ファイルが無ければ空。
    # ファイルは各インデックスのフォルダ（work\index\<インデックス名>）に置くため、dir にはそのフォルダを渡す。
    # dir の下を探し回らないのは、インデックスのフォルダの下が元のファイル1つにつき1フォルダ（数万個）になるため
    param (
        [string]$dir
    )

    $map = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($line in @(readListFile (Join-Path $dir ${sourceFolderFileName}))) {
        $fields = $line.Split("`t")
        if ($fields.Count -eq 2 -and $fields[0] -ne "" -and $fields[1] -ne "") {
            $map[$fields[0]] = $fields[1]
        }
    }
    return , $map
}

function getSourceFolderMap {
    # インデックスのフォルダ（dir）の インデックス名 → 元のフォルダ（今そのフォルダが置かれている場所）を返す。
    # 次の順に読み、後のもので上書きする（後のものが優先）:
    #   1. dir 直下の source_folder.txt … インデックスを作ったときの場所。インデックスをコピーしても付いてくる
    #   2. 既定のインデックス（work\index）なら取り込み一覧の記録
    #   3. 設定のインデックス名に対する場所（targetFolders・indexSources）… 利用者が指定した「今の場所」のため最も優先する
    param (
        [string]$dir,
        [string]$statusPath = $workspace.StatusFile,
        [string]$settingsPath = ${settingsFile},
        [string]$indexDir = $workspace.IndexDir
    )

    $map = readSourceFolderFile $dir
    if ((Test-Path -LiteralPath $indexDir -PathType Container) -and
        (testSameFolder $dir (Resolve-Path -LiteralPath $indexDir).ProviderPath)) {
        foreach ($entry in (getIndexNameMap $statusPath).GetEnumerator()) {
            $map[$entry.Key] = $entry.Value
        }
    }
    foreach ($folder in @(getTargetFolders $settingsPath | Where-Object { $_.Name })) {
        $map[$folder.Name] = $folder.Path
    }
    foreach ($source in @(readIndexSources $settingsPath)) {
        $map[$source.Name] = $source.Path
    }
    return , $map
}

function joinSourcePath {
    # フォルダ・相対フォルダ（空でも可）・ファイル名をつなぐ（ドライブ直下 "D:\" でも \ が重ならないようにする）
    param (
        [string]$folder,
        [string]$rest,
        [string]$name = ""
    )

    $path = $folder.TrimEnd("\")
    foreach ($part in @($rest, $name)) {
        if ($part) {
            $path += "\$part"
        }
    }
    return $path
}

function findSourceLocationInMaps {
    # 検索結果の元のファイルの場所を、キャッシュ（maps）だけで求める。ファイルは読まない。
    # 返すもの: @{ Resolved; Location; Pending }
    #   Resolved: 場所が決まったか。$false なら、Pending のフォルダの対応（getSourceFolderMap）を maps に足してから、もう一度呼ぶ
    #   Location: @{ Name（インデックス名）; Folder（元のフォルダ）; Rest（その下の相対フォルダ）; Known }。元のフォルダが分からなければ Known = $false・Folder = ""
    #             （Name は返すため、フォルダを選んでもらえば設定に記録できる）
    # インデックスのフォルダ（Root）の下は "インデックス名\相対フォルダ" のため、インデックス名から元のフォルダを引く。
    # 検索対象にインデックス名のフォルダ（…\index\<インデックス名>）を直接指定した場合は、親フォルダの記録を使う。
    param (
        $hit,
        [hashtable]$maps = @{}
    )

    $root = ([string]$hit.Root).TrimEnd("\")
    $relDir = [string]$hit.RelDir
    $candidates = New-Object System.Collections.Generic.List[object]
    if ($relDir) {
        $parts = splitIndexRelPath $relDir
        $candidates.Add(@{ Dir = $root; Name = $parts.Name; Rest = $parts.Rest })
        # インデックスのフォルダの中の記録（<インデックス名> のフォルダだけを別の場所へコピーした場合）
        $candidates.Add(@{ Dir = (Join-Path $root $parts.Name); Name = $parts.Name; Rest = $parts.Rest })
    }
    # 検索対象にインデックス名のフォルダ（…\index\<インデックス名>）を直接指定した場合。
    # そのフォルダ自身の記録を先に見て、無ければ親フォルダの記録を見る
    $leaf = Split-Path $root -Leaf
    $candidates.Add(@{ Dir = $root; Name = $leaf; Rest = $relDir })
    $parent = Split-Path $root -Parent
    if ($parent) {
        $candidates.Add(@{ Dir = $parent; Name = $leaf; Rest = $relDir })
    }

    foreach ($candidate in $candidates) {
        if (!$maps.ContainsKey($candidate.Dir)) {
            return @{ Resolved = $false; Location = $null; Pending = $candidate.Dir }
        }
        $map = $maps[$candidate.Dir]
        if ($map.ContainsKey($candidate.Name)) {
            return @{ Resolved = $true; Location = @{ Name = $candidate.Name; Folder = $map[$candidate.Name]; Rest = $candidate.Rest; Known = $true }; Pending = "" }
        }
    }

    # 分からない場合も、インデックス名と、その下の相対フォルダは分かる（検索対象にインデックス名のフォルダを直接指定した場合は Rest がすべて）
    if ($candidates.Count -gt 0) {
        $unknown = @{ Name = $candidates[0].Name; Folder = ""; Rest = $candidates[0].Rest; Known = $false }
    } else {
        $unknown = @{ Name = (Split-Path $root -Leaf); Folder = ""; Rest = ""; Known = $false }
    }
    return @{ Resolved = $true; Location = $unknown; Pending = "" }
}

function getSourceLocation {
    # 検索結果の元のファイルの場所を @{ Name; Folder; Rest; Known } で返す（findSourceLocationInMaps と同じ）。
    # キャッシュに無いフォルダの対応は、読んで maps に足す
    #   maps: フォルダ → getSourceFolderMap の結果 のキャッシュ（読んだ結果を追加する）
    param (
        $hit,
        [hashtable]$maps = @{}
    )

    while ($true) {
        $found = findSourceLocationInMaps $hit $maps
        if ($found.Resolved) {
            return $found.Location
        }
        $maps[$found.Pending] = getSourceFolderMap $found.Pending
    }
}

function readSourceLocation {
    # getSourceLocation の、裏のスレッドから呼ぶ版。$workspace・設定の場所に頼らず、場所を引数で受ける。
    # maps は書き換えず、複製に足して返す: @{ Location; Maps }（呼んだ側が Maps をキャッシュに足す）
    param (
        $hit,
        [hashtable]$maps,
        [string]$statusPath,
        [string]$settingsPath,
        [string]$indexDir
    )

    $copy = $maps.Clone()
    while ($true) {
        $found = findSourceLocationInMaps $hit $copy
        if ($found.Resolved) {
            return @{ Location = $found.Location; Maps = $copy }
        }
        $copy[$found.Pending] = getSourceFolderMap $found.Pending $statusPath $settingsPath $indexDir
    }
}

function findMovedSource {
    # 元のファイルが見つからないとき、選んでもらったフォルダ（picked）の中から探す。
    # picked は元のフォルダ（インデックスのルート）に当たるフォルダでも、その下のどのフォルダ（ファイルのあるフォルダなど）に当たるフォルダでもよい。
    # 上の階層に当たるとみなす方から順に試し、見つかれば @{ Path（見つかったファイル）; Root（元のフォルダに当たるフォルダ。遡れなければ ""） }、
    # 見つからなければ $null を返す。Root を設定に記録すれば（setIndexSourceFolder）、同じインデックスのほかのファイルも開ける
    param (
        [string]$picked,
        [string]$rest,
        [string]$book
    )

    $picked = normalizeFolderPath $picked
    $segments = [string[]]@($rest.Split([char[]]@("\"), [System.StringSplitOptions]::RemoveEmptyEntries))
    for ($skip = 0; $skip -le $segments.Count; $skip++) {
        # 先頭の skip 個のフォルダは picked より上、残りは picked の下にあるとみなす
        $below = [string]::Join("\", $segments, $skip, $segments.Count - $skip)
        $candidate = joinSourcePath $picked $below $book
        if (Test-Path -LiteralPath (toLongPath $candidate) -PathType Leaf) {
            # 選んだフォルダは「元のフォルダ＋先頭 skip 個のフォルダ」に当たるため、skip 個上が元のフォルダに当たる
            $root = $picked
            for ($i = 0; $i -lt $skip -and $root; $i++) {
                $root = Split-Path $root -Parent
            }
            return @{ Path = $candidate; Root = [string]$root }
        }
    }
    return $null
}

function findSourceFileState {
    # 元のファイルを確かめる（getPathState を使う。Test-Path のまま移さない。届かない共有では例外を出さずに
    # $false を返すことがあり、「見つからない」と区別できないため）。ネットワークのパスなら裏のスレッドから呼ぶ想定。
    #   location: getSourceLocation の結果（Folder・Rest・Name を使う。Known は呼ぶ側で見て、$false ならこの関数を呼ばない）
    #   book: 元のファイル名
    #   drives: ドライブの割り当て（テストで差し替える・裏のスレッドでは省いてその場で照会させる）。
    #           ローカルのパスには別名が無いため、ローカルのときはここまで来ない（getDriveTargets を呼ばない）
    # 返すもの: @{ State（Found・Missing・Unreachable・Other）; Path; Alias; Initial; Message }
    #   State=Found: Path に見つかった場所（別名で見つかったときは Alias にその新しい元のフォルダ）
    #   State=Missing: Initial にフォルダ選択の開始フォルダ（無ければ空）
    #   State=Unreachable・Other: Message に例外の文面（接続できない・その他は、上のフォルダも別名も調べない）
    param (
        $location,
        [string]$book,
        $drives = $null
    )

    $path = joinSourcePath $location.Folder $location.Rest $book
    $state = getPathState $path
    if ($state.State -eq ${pathStateFound}) {
        return @{ State = ${pathStateFound}; Path = $path }
    }
    if ($state.State -ne ${pathStateMissing}) {
        return @{ State = $state.State; Message = $state.Message }
    }
    if (testNetworkPath $location.Folder) {
        if ($null -eq $drives) {
            $drives = getDriveTargets
        }
        foreach ($alias in @(getFolderPathAliases $location.Folder $drives | Select-Object -Skip 1)) {
            $candidate = joinSourcePath $alias $location.Rest $book
            if ((getPathState $candidate).State -eq ${pathStateFound}) {
                return @{ State = ${pathStateFound}; Path = $candidate; Alias = $alias }
            }
        }
    }
    return @{ State = ${pathStateMissing}; Initial = (getExistingAncestorFolder $path) }
}

function resolveSourcePath {
    # 検索結果の元のファイルのパスを返す（ファイルがあるかは確かめない）。元のフォルダが分からなければ $null
    #   maps: getSourceLocation のキャッシュ
    param (
        $hit,
        [hashtable]$maps = @{}
    )

    $location = getSourceLocation $hit $maps
    if (!$location.Known) {
        return $null
    }
    return (joinSourcePath $location.Folder $location.Rest $hit.Book)
}

function getConfirmedSourceNames {
    # 利用者が元のフォルダを決めている（確かめ済みの）インデックス名を返す: @{ Confirmed; Crawled }
    #   Confirmed: 設定の targetFolders と indexSources の名前（元のフォルダの記録が設定にあるもの）
    #   Crawled  : そのうち targetFolders の名前（このワークスペースで自分が作ったインデックス）
    # この外のインデックス（content_index\ に手でコピーしたもの）の元のフォルダは、source_folder.txt を書いた人が決めたもの。
    # 設定は小さいローカルのファイルのため、呼ぶたびに読む（キャッシュしない）
    param (
        [string]$settingsPath = ${settingsFile}
    )

    $crawled = @(getTargetFolders $settingsPath | Where-Object { $_.Name } | ForEach-Object { [string]$_.Name })
    $confirmed = @($crawled) + @(readIndexSources $settingsPath | ForEach-Object { [string]$_.Name })
    return @{ Confirmed = [string[]]$confirmed; Crawled = [string[]]$crawled }
}

# インデックスのエクスポート・インポートの判断（目録の確かめ・zip のエントリー名の安全性・名前の決め方）。
# 画面に触らず、ファイルにも触らない（判断層）。

# 目録（tebunko-index.json）の形式
${indexArchiveFormat}            = "tebunko-index"
${indexArchiveFormatVersion}     = 1  # この版が読める形式の版（本文インデックスのファイルの形・zip の中の配置・目録・取り込み一覧の列を変えたら上げる）
${indexArchiveManifestFileName}  = "tebunko-index.json"
${indexArchiveStatusEntryName}   = "ingest_status.tsv"
${indexArchiveMaxManifestBytes}  = 64MB   # 目録（tebunko-index.json）自体の大きさの上限（zip bomb 対策）
${indexArchiveFreeSpaceMargin}   = 1GB    # インポートに求める空き容量の余裕（目録の合計 + この量）

# 同じ名前のインデックスがあったときの扱い（importIndex・getImportIndexName に渡す）
${importCollisionRename}    = "Rename"
${importCollisionOverwrite} = "Overwrite"
${importCollisionCancel}    = "Cancel"


function testPathSegments {
    # 区切り文字で分けたパスの各区切り（segments）が、ファイル名として安全に使えるかを調べ、
    # 使えない理由を返す（使えれば空文字列）。zip のエントリー名（/ 区切り）・取り込み一覧の相対パス（\ 区切り）の
    # どちらからも呼べる、区切り文字に依らない共通の確かめ
    param (
        [string[]]$segments
    )

    foreach ($segment in $segments) {
        if ($segment -eq "" -or $segment -eq "." -or $segment -eq "..") {
            return "使えない区切り（空・.・..）が含まれています。"
        }
        if ($segment.Length -gt ${maxFileNameLength}) {
            return "1 つの区切りが長すぎます（${maxFileNameLength} 文字まで）。"
        }
        if (@([System.IO.Path]::GetInvalidFileNameChars() | Where-Object { $segment.IndexOf($_) -ge 0 }).Count -gt 0) {
            return "使えない文字が含まれています。"
        }
        if ($segment.EndsWith(".") -or $segment.EndsWith(" ")) {
            return "区切りの最後に . や空白は使えません。"
        }
        if (${reservedFileNames} -contains $segment.Split(".")[0].ToUpperInvariant()) {
            return "Windows で使えない名前（$segment）が含まれています。"
        }
    }
    return ""
}


function testIndexArchiveEntryPath {
    # zip のエントリー名（/ 区切り）が、展開先のパスとして安全かを調べ、使えない理由を返す（使えれば空文字列）。
    # \ 区切り・絶対パス（/ 始まり・ドライブ文字・UNC）は、どれも展開先のパスの外に出るおそれがあるため受け付けない（zip slip 対策）
    param (
        [string]$path
    )

    if ($path -eq "") {
        return "エントリーの名前が空です。"
    }
    if ($path.IndexOf("\") -ge 0) {
        return "エントリーの名前に \ が含まれています（/ 区切りにしてください）: ${path}"
    }
    if ($path.StartsWith("/")) {
        return "エントリーの名前が / で始まっています: ${path}"
    }
    if ($path -match "^[A-Za-z]:") {
        return "エントリーの名前がドライブ文字で始まっています: ${path}"
    }
    $reason = testPathSegments ($path.Split("/"))
    if ($reason) {
        return "エントリー「${path}」の名前が使えません（${reason}）"
    }
    return ""
}


function testIndexArchiveEntryLocation {
    # zip のエントリー名（testIndexArchiveEntryPath を通ったもの）が、持ち出すファイルの置き場所として
    # 許されているか（ingest_status.tsv、または content_index/ の下の本文インデックスのファイルの名前の型）を返す
    param (
        [string]$path
    )

    if ($path -ceq ${indexArchiveStatusEntryName}) {
        return $true
    }
    if (!$path.StartsWith("content_index/", [System.StringComparison]::Ordinal)) {
        return $false
    }
    $name = $path.Substring("content_index/".Length)
    if ($name -eq "") {
        return $false
    }
    $lastSlash = $name.LastIndexOf("/")
    $fileName = if ($lastSlash -ge 0) { $name.Substring($lastSlash + 1) } else { $name }
    return ($null -ne (readContentIndexFileName $fileName))
}


function getManifestSourceFolder {
    # 目録の sourceFolder を返す。絶対パス・UNC でない、または制御文字を含むときは空（呼ぶ側に指定させる）
    param (
        $manifest
    )

    $folder = [string]$manifest.sourceFolder
    if ($folder -eq "") {
        return ""
    }
    if ($folder.IndexOfAny([char[]]@(0..31)) -ge 0) {
        return ""
    }
    if ($folder -notmatch "^[A-Za-z]:\\" -and !$folder.StartsWith("\\")) {
        return ""
    }
    return $folder
}


function testIndexArchiveManifest {
    # 目録（ConvertFrom-Json の結果。読めなければ $null）と、zip の中の全エントリー名（目録自身を含む）・
    # 目録エントリーの展開後の大きさから、この zip をインポートしてよいかを調べ、使えない理由を返す（使えれば空文字列）。
    # 1 つでも受け付けない点があればインポート全体を止めるため、最初に見つかった理由だけを返す
    param (
        $manifest,
        [string[]]$entryNames,
        [long]$manifestBytes
    )

    if ($manifestBytes -gt ${indexArchiveMaxManifestBytes}) {
        return "目録（${indexArchiveManifestFileName}）が大きすぎます。"
    }
    if ($null -eq $manifest) {
        return "tebunko のインデックスの zip ではない、または壊れています（目録を読めません）。"
    }
    if ([string]$manifest.format -ne ${indexArchiveFormat}) {
        return "tebunko のインデックスの zip ではない、または壊れています（形式が違います）。"
    }
    $version = 0
    if (-not [int]::TryParse([string]$manifest.formatVersion, [ref]$version) -or $version -lt 1) {
        return "tebunko のインデックスの zip ではない、または壊れています（形式の版が読めません）。"
    }
    if ($version -gt ${indexArchiveFormatVersion}) {
        return "新しい版の tebunko で作られたインデックスのため、この版では読み込めません。"
    }

    $nameReason = testIndexName ([string]$manifest.indexName) @()
    if ($nameReason) {
        return "目録のインデックス名が使えません（${nameReason}）"
    }

    # zip の中に同じ名前のエントリーが 2 つあれば止める（ZipArchive は許すため、ここで数える）
    $seenEntries = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($entryName in $entryNames) {
        if (!$seenEntries.Add($entryName)) {
            return "zip の中に同じ名前のエントリーが 2 つあります: ${entryName}"
        }
    }

    $fileMap = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($file in @($manifest.files | Where-Object { $_ })) {
        $path = [string]$file.path
        $reason = testIndexArchiveEntryPath $path
        if ($reason) {
            return $reason
        }
        if (!(testIndexArchiveEntryLocation $path)) {
            return "目録に、許されない場所のエントリーがあります: ${path}"
        }
        if ($fileMap.ContainsKey($path)) {
            return "目録に同じパスが 2 つあります: ${path}"
        }
        $size = [long]0
        if (-not [long]::TryParse([string]$file.size, [ref]$size) -or $size -lt 0) {
            return "目録のファイルの大きさが読めません: ${path}"
        }
        if ([string]$file.sha256 -eq "") {
            return "目録のファイルの SHA-256 がありません: ${path}"
        }
        $fileMap[$path] = $file
    }
    if (!$fileMap.ContainsKey(${indexArchiveStatusEntryName})) {
        return "目録に ${indexArchiveStatusEntryName} がありません。"
    }

    # zip の中のエントリー（目録自身を除く）が、すべて目録にあるか。目録にあるのに zip に無いものが無いか
    $zipEntries = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($entryName in $entryNames) {
        if ($entryName -ieq ${indexArchiveManifestFileName}) {
            continue
        }
        [void]$zipEntries.Add($entryName)
        if (!$fileMap.ContainsKey($entryName)) {
            return "目録に無いエントリーが zip にあります: ${entryName}"
        }
    }
    foreach ($path in $fileMap.Keys) {
        if (!$zipEntries.Contains($path)) {
            return "目録にあるのに zip に無いエントリーがあります: ${path}"
        }
    }

    return ""
}


function testImportedStatusRelPath {
    # ingest_status.tsv の1行の相対パス（\ 区切り。インデックス名は付いていない）が安全に使えるかを返す（使えれば空文字列）
    param (
        [string]$relPath
    )

    if ($relPath -eq "") {
        return "相対パスが空です。"
    }
    return (testPathSegments ($relPath.Split("\")))
}


function testImportedStatusRow {
    # ingest_status.tsv の1行（列は statusColumns と同じ）が受け付けられるかを返す（使えれば空文字列）
    param (
        [string]$line
    )

    $fields = $line.Split("`t")
    if ($fields.Count -ne ${statusColumns}.Count) {
        return "列の数が違います。"
    }
    if (@(${stateNew}, ${stateDone}, ${stateFailed}) -notcontains $fields[3]) {
        return "状態の値（$($fields[3])）が違います。"
    }
    return (testImportedStatusRelPath $fields[0])
}


function testImportedStatusLines {
    # ingest_status.tsv 全体（見出し行 + データ行）が受け付けられるかを返す（使えれば空文字列）。
    # 見出しが違う・列や状態や相対パスがおかしい行がある・同じ相対パスが2つある、のいずれかで止める
    param (
        [string[]]$lines
    )

    if ($lines.Count -eq 0 -or $lines[0] -ne (${statusColumns} -join "`t")) {
        return "ingest_status.tsv の見出しが違います。"
    }
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    for ($i = 1; $i -lt $lines.Count; $i++) {
        $line = $lines[$i]
        if ($line -eq "") {
            continue
        }
        $reason = testImportedStatusRow $line
        if ($reason) {
            return "ingest_status.tsv の $($i + 1) 行目が読めません（${reason}）"
        }
        $relPath = $line.Split("`t")[0]
        if (!$seen.Add($relPath)) {
            return "ingest_status.tsv に同じ相対パスが 2 つあります: ${relPath}"
        }
    }
    return ""
}


function getIndexFolderConflict {
    # 元のフォルダが、ほかのクロール対象のインデックスと重なるかを調べ、直してほしい内容を返す（問題なければ空文字列）。
    # 画面の追加と詳細欄の編集（testIndexEditInput）とインポート（importIndex）の両方が使う、1 つの決まり。
    # 同じフォルダは、getTargetFolders が 2 つ目以降を読まないため設定に残らない。入れ子のフォルダは、
    # 同じファイルが 2 つのインデックスに入り、取り込みも検索結果も二重になる
    param (
        [string]$folder,   # 正規化済みの元のフォルダ
        $others            # 比べる相手（Name・Path を持つ行。置き換える・編集中の行は呼び出し側で外しておく）
    )

    foreach ($other in @($others)) {
        if (testSameFolder $other.Path $folder) {
            return "「${folder}」のインデックス [$($other.Name)] が既にあります。"
        }
        if (testFolderUnder $folder $other.Path) {
            return "「${folder}」は、インデックス [$($other.Name)]（$($other.Path)）の中のフォルダです。" +
                "同じファイルが二重にインデックスに入るため、登録できません。検索する範囲を絞るときは［検索］の検索対象で外してください。"
        }
        if (testFolderUnder $other.Path $folder) {
            return "「${folder}」の中には、インデックス [$($other.Name)]（$($other.Path)）があります。" +
                "同じファイルが二重にインデックスに入るため、登録できません。まとめるときは、先に [$($other.Name)] を削除してください。"
        }
    }
    return ""
}


function getImportIndexName {
    # 同じ名前のインデックスがあったときの扱い（collisionMode）から、インポートで使う名前を決める。
    #   Rename    : usedNames と重ならない名前にする（今の newIndexName の決まり「名前(2)」「名前(3)」…）
    #   Overwrite : suggestedName のまま（そのインデックスを置き換える）
    #   Cancel    : 何もしない（$null）
    param (
        [string]$suggestedName,
        $usedNames = @(),
        [string]$collisionMode
    )

    if ($collisionMode -eq ${importCollisionCancel}) {
        return $null
    }
    if ($collisionMode -eq ${importCollisionOverwrite}) {
        return $suggestedName
    }
    return (newIndexName $suggestedName $usedNames)
}


function getExportFileName {
    # エクスポートの既定のファイル名（"<インデックス名>_インデックス_<yyyyMMdd>.zip"）を返す。
    # usedNames（保存先フォルダに既にあるファイル名）と重なれば "(2)" "(3)" … を付ける
    param (
        [string]$indexName,
        $usedNames = @(),
        [datetime]$now = (Get-Date)
    )

    $base = "$(toSafeFileName $indexName)_インデックス_$($now.ToString('yyyyMMdd'))"
    $used = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($usedName in @($usedNames)) {
        if ($usedName) {
            [void]$used.Add([string]$usedName)
        }
    }
    $name = "${base}.zip"
    for ($i = 2; $used.Contains($name); $i++) {
        $name = "${base}(${i}).zip"
    }
    return $name
}

# インデックスのエクスポート・インポート（状態層。zip の読み書き・ワークスペースの書き換え）。
# 画面にも利用者にも問い合わせない（画面なしで呼べる形にする）。安全性の確かめは index_archive_rules.ps1（判断層）で行う。

# System.IO.Compression.ZipFile・ZipArchive は既定では読み込まれていないアセンブリにあるため、ここで読み込む
Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem

function getBytesSha256 {
    # バイト列の SHA-256（16進64文字）を返す
    param (
        [byte[]]$bytes
    )

    $sha = New-Object System.Security.Cryptography.SHA256CryptoServiceProvider
    try {
        return [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace("-", "")
    } finally {
        $sha.Dispose()
    }
}

function writeArchiveBytes {
    # バイト列を zip の1エントリーとして書く
    param (
        $archive,
        [string]$entryPath,
        [byte[]]$bytes
    )

    $entry = $archive.CreateEntry($entryPath, [System.IO.Compression.CompressionLevel]::Optimal)
    $stream = $entry.Open()
    try {
        $stream.Write($bytes, 0, $bytes.Length)
    } finally {
        $stream.Dispose()
    }
}

function writeArchiveFile {
    # ファイルを1つ、ストリームで zip の1エントリーに写す（メモリに全体を読まない）。
    # 写しながら SHA-256 を計算し、@{ Size; Sha256 } を返す
    param (
        $archive,
        [string]$entryPath,
        [string]$sourcePath
    )

    $entry = $archive.CreateEntry($entryPath, [System.IO.Compression.CompressionLevel]::Optimal)
    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $source = New-Object System.IO.FileStream((toLongPath $sourcePath), [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    $sha = New-Object System.Security.Cryptography.SHA256CryptoServiceProvider
    try {
        $size = $source.Length
        $entryStream = $entry.Open()
        try {
            $crypto = New-Object System.Security.Cryptography.CryptoStream($entryStream, $sha, [System.Security.Cryptography.CryptoStreamMode]::Write)
            try {
                $source.CopyTo($crypto)
                $crypto.FlushFinalBlock()
            } finally {
                $crypto.Dispose()
            }
        } finally {
            $entryStream.Dispose()
        }
        return @{ Size = $size; Sha256 = [BitConverter]::ToString($sha.Hash).Replace("-", "") }
    } finally {
        $source.Dispose()
        $sha.Dispose()
    }
}

function exportIndex {
    # 1 つのインデックスを 1 つの zip に書き出す: @{ Name; Path; Files; Bytes }。画面にも利用者にも問い合わせない。
    # インデックス作成のロックを取れなければ例外（ほかで実行中）
    param (
        [string]$name,
        [string]$destPath,
        $ws = $workspace,
        [string]$settingsPath = ${settingsFile}
    )

    $lock = newAppMutex "indexer" $ws.Dir
    if (!$lock.Acquired) {
        $lock.Mutex.Dispose()
        throw "更新中はエクスポートできません。更新が終わってからやり直してください。"
    }
    try {
        return (exportIndexCore $name $destPath $ws $settingsPath)
    } finally {
        $lock.Mutex.ReleaseMutex()
        $lock.Mutex.Dispose()
    }
}

function exportIndexToFolder {
    # 1 つのインデックスを、書き出し先のフォルダの中の zip に書き出す（ファイル名は getExportFileName で決め、
    # フォルダに同じ名前があれば番号を付ける）。書き出し先のフォルダが無ければ例外。戻り値は exportIndex と同じ。
    # 届かないネットワークのフォルダで止まりうるので、画面のスレッドでは呼ばず、別スレッドの仕事の中で呼ぶ
    param (
        [string]$name,
        [string]$folder,
        $ws = $workspace,
        [string]$settingsPath = ${settingsFile}
    )

    if (!(Test-Path -LiteralPath (toLongPath $folder) -PathType Container)) {
        throw "書き出し先のフォルダが見つかりません：$folder"
    }
    $used = @(Get-ChildItem -LiteralPath (toLongPath $folder) -File -ErrorAction SilentlyContinue | ForEach-Object { $_.Name })
    $destPath = Join-Path $folder (getExportFileName $name $used)
    return (exportIndex $name $destPath $ws $settingsPath)
}

function exportIndexes {
    # 選んだインデックスを、書き出し先のフォルダの中の zip にまとめて書き出す（インデックス 1 つにつき zip 1 つ）。
    # 1 つずつ exportIndexToFolder を呼び、途中で 1 つ失敗しても残りを続ける。
    # 戻り値は名前ごとの結果の配列（@{ Name; Ok; Reason; Path }）。Reason は失敗したときの理由（成功なら ""）、Path は書き出した zip（失敗なら ""）。
    # 画面のスレッドでは呼ばず、別スレッドの仕事の中で呼ぶ
    param (
        [string[]]$names,
        [string]$destination,
        $ws = $workspace,
        [string]$settingsPath = ${settingsFile}
    )

    $results = New-Object System.Collections.Generic.List[object]
    foreach ($name in @($names)) {
        try {
            $exported = exportIndexToFolder $name $destination $ws $settingsPath
            $results.Add([pscustomobject]@{ Name = $name; Ok = $true; Reason = ""; Path = $exported.Path })
        } catch {
            $results.Add([pscustomobject]@{ Name = $name; Ok = $false; Reason = $_.Exception.Message; Path = "" })
        }
    }
    return , $results.ToArray()
}

function getIndexExportSize {
    # エクスポートする前に、選んだインデックスが zip に入れる本文インデックスのファイル（*.tsv）の大きさの合計を数える。
    # 戻り値: @{ Bytes（合計のバイト数）; Missing（インデックスのフォルダが無かった名前の配列）}。
    # 数えるのは zip に入る元のファイルの大きさで、zip にした後の大きさではない。
    # 画面のスレッドでは呼ばず、別スレッドの仕事の中で呼ぶ
    param (
        [string[]]$names,
        $ws = $workspace
    )

    $bytes = [long]0
    $missing = New-Object System.Collections.Generic.List[string]
    foreach ($name in @($names)) {
        $indexDir = Join-Path $ws.IndexDir $name
        if (!(Test-Path -LiteralPath (toLongPath $indexDir) -PathType Container)) {
            $missing.Add($name)
            continue
        }
        foreach ($file in [System.IO.Directory]::GetFiles((toLongPath $indexDir), "*.tsv", [System.IO.SearchOption]::AllDirectories)) {
            $bytes += ([System.IO.FileInfo]::new($file)).Length
        }
    }
    return @{ Bytes = $bytes; Missing = $missing.ToArray() }
}

function exportIndexCore {
    param (
        [string]$name,
        [string]$destPath,
        $ws,
        [string]$settingsPath
    )

    $indexDir = Join-Path $ws.IndexDir $name
    if (!(Test-Path -LiteralPath (toLongPath $indexDir) -PathType Container)) {
        throw "インデックス [${name}] が見つかりません。"
    }
    $status = readStatusFile $ws.StatusFile
    if (@($status.Folders | Where-Object { [string]::Equals([string]$_.Name, $name, [System.StringComparison]::OrdinalIgnoreCase) }).Count -eq 0) {
        throw "取り込み一覧に、インデックス [${name}] の記録がありません。"
    }

    # 入れる前の TSV（本文インデックスのファイル以外の *.tsv）が残っていれば、途中で止まったインデックスとして止める
    $longIndexDir = toLongPath $indexDir
    $prefixLength = $indexDir.TrimEnd("\").Length + 1
    $contentIndexFiles = New-Object System.Collections.Generic.List[string]
    # 途中で throw して抜けても下のフォルダを掴んだまま残らないよう、列挙子（EnumerateFiles）でなく配列（GetFiles）で受ける
    foreach ($file in [System.IO.Directory]::GetFiles($longIndexDir, "*.tsv", [System.IO.SearchOption]::AllDirectories)) {
        $rel = (fromLongPath $file).Substring($prefixLength)
        $fileName = [System.IO.Path]::GetFileName($rel)
        if ($null -eq (readContentIndexFileName $fileName)) {
            throw "更新を最後まで行ってからエクスポートしてください（更新の途中のファイルが残っています: ${rel}）。"
        }
        $contentIndexFiles.Add($rel)
    }

    # 取り込み一覧のうち、このインデックスの行だけを抜き出し、相対パスの先頭の "<名前>\" を外す
    $prefix = "$name\"
    $rows = New-Object System.Collections.Generic.List[string]
    $rows.Add((${statusColumns} -join "`t"))
    foreach ($entry in $status.Rows.GetEnumerator()) {
        if ($entry.Key.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) {
            $row = $entry.Value
            $stripped = [pscustomobject]@{
                相対パス = $entry.Key.Substring($prefix.Length); 更新日時 = $row.更新日時; サイズ = $row.サイズ; 状態 = $row.状態
                TSV数 = $row.TSV数; 取り込み日時 = $row.取り込み日時; エラー = $row.エラー; 抽出版 = $row.抽出版
            }
            $rows.Add((toStatusLine $stripped))
        }
    }
    $statusText = [string]::Join("`r`n", $rows) + "`r`n"

    $tmpPath = "${destPath}.tmp"
    [System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($tmpPath)) | Out-Null
    if (Test-Path -LiteralPath $tmpPath) {
        Remove-Item -LiteralPath $tmpPath -Force
    }

    try {
        $manifestFiles = New-Object System.Collections.Generic.List[object]
        $totalBytes = [long]0
        $archive = [System.IO.Compression.ZipFile]::Open($tmpPath, [System.IO.Compression.ZipArchiveMode]::Create, [System.Text.Encoding]::UTF8)
        try {
            $statusBytes = ${utf8Bom}.GetBytes($statusText)
            writeArchiveBytes $archive ${indexArchiveStatusEntryName} $statusBytes
            $manifestFiles.Add([ordered]@{ path = ${indexArchiveStatusEntryName}; size = [long]$statusBytes.Length; sha256 = (getBytesSha256 $statusBytes) })
            $totalBytes += $statusBytes.Length

            foreach ($rel in $contentIndexFiles) {
                $entryPath = "content_index/" + $rel.Replace("\", "/")
                $written = writeArchiveFile $archive $entryPath (Join-Path $indexDir $rel)
                $manifestFiles.Add([ordered]@{ path = $entryPath; size = [long]$written.Size; sha256 = $written.Sha256 })
                $totalBytes += $written.Size
            }

            $sourceFolder = ""
            $ownFile = readSourceFolderFile $indexDir
            if ($ownFile.ContainsKey($name)) {
                $sourceFolder = $ownFile[$name]
            } else {
                $sourceMap = getSourceFolderMap $ws.IndexDir $ws.StatusFile $settingsPath
                if ($sourceMap.ContainsKey($name)) {
                    $sourceFolder = $sourceMap[$name]
                }
            }
            $version = readVersionFile (Join-Path ${rootDir} "VERSION.txt")
            $manifest = [ordered]@{
                format        = ${indexArchiveFormat}
                formatVersion = ${indexArchiveFormatVersion}
                appVersion    = $(if ($version) { $version.Tag } else { "" })
                exportedAt    = (Get-Date).ToString("yyyy-MM-ddTHH:mm:sszzz")
                indexName     = $name
                sourceFolder  = $sourceFolder
                files         = $manifestFiles.ToArray()
            }
            $manifestJson = ConvertTo-Json -InputObject $manifest -Depth 5
            writeArchiveBytes $archive ${indexArchiveManifestFileName} ((New-Object System.Text.UTF8Encoding($false)).GetBytes($manifestJson))
        } finally {
            $archive.Dispose()
        }
    } catch {
        if (Test-Path -LiteralPath $tmpPath) {
            Remove-Item -LiteralPath $tmpPath -Force -ErrorAction SilentlyContinue
        }
        throw
    }
    try {
        if (Test-Path -LiteralPath $destPath) {
            Remove-Item -LiteralPath $destPath -Force
        }
        [System.IO.File]::Move((toLongPath $tmpPath), (toLongPath $destPath))
    } catch {
        if (Test-Path -LiteralPath $tmpPath) {
            Remove-Item -LiteralPath $tmpPath -Force -ErrorAction SilentlyContinue
        }
        throw
    }
    return @{ Name = $name; Path = $destPath; Files = $manifestFiles.Count; Bytes = $totalBytes }
}

function openIndexArchive {
    # zip を開き、目録（testIndexArchiveManifest）を確かめる。確かめられなければ、開いたアーカイブを閉じて例外にする。
    # 返すもの: @{ Archive; Manifest }（呼んだ側が Archive.Dispose() を行う）
    param (
        [string]$zipPath
    )

    try {
        $archive = [System.IO.Compression.ZipFile]::Open($zipPath, [System.IO.Compression.ZipArchiveMode]::Read, [System.Text.Encoding]::UTF8)
    } catch {
        throw "tebunko のインデックスの zip ではない、または壊れています（$($_.Exception.Message)）。"
    }
    try {
        $entryNames = @($archive.Entries | ForEach-Object { $_.FullName })
        $manifestEntry = $archive.Entries | Where-Object { $_.FullName -ceq ${indexArchiveManifestFileName} } | Select-Object -First 1
        $manifest = $null
        $manifestBytes = [long]0
        if ($null -ne $manifestEntry) {
            $manifestBytes = $manifestEntry.Length
            if ($manifestBytes -le ${indexArchiveMaxManifestBytes}) {
                $reader = New-Object System.IO.StreamReader($manifestEntry.Open(), [System.Text.Encoding]::UTF8)
                try {
                    $json = $reader.ReadToEnd()
                } finally {
                    $reader.Dispose()
                }
                try {
                    $manifest = ConvertFrom-Json $json
                } catch {
                    $manifest = $null
                }
            }
        }
        $reason = testIndexArchiveManifest $manifest $entryNames $manifestBytes
        if ($reason) {
            throw $reason
        }
        return @{ Archive = $archive; Manifest = $manifest }
    } catch {
        $archive.Dispose()
        throw
    }
}

function readIndexArchiveInfo {
    # 目録だけを読んで確かめる（インポートせずに、画面が既定の名前・元のフォルダ・合計の大きさを出すために使う）。
    # 返すもの: @{ IndexName; SourceFolder; Files; Bytes; FormatVersion; AppVersion; ExportedAt（目録の exportedAt のまま。無ければ空） }
    param (
        [string]$zipPath
    )

    $opened = openIndexArchive $zipPath
    try {
        $manifest = $opened.Manifest
        $bytes = [long]0
        foreach ($file in @($manifest.files)) {
            $bytes += [long]$file.size
        }
        return @{
            IndexName     = [string]$manifest.indexName
            SourceFolder  = (getManifestSourceFolder $manifest)
            Files         = @($manifest.files).Count
            Bytes         = $bytes
            FormatVersion = [int]$manifest.formatVersion
            AppVersion    = [string]$manifest.appVersion
            ExportedAt    = [string]$manifest.exportedAt
        }
    } finally {
        $opened.Archive.Dispose()
    }
}

function getImportArchiveInfo {
    # readIndexArchiveInfo の結果に、元のフォルダがこの PC にあるか（SourceExists）を足して返す（インポートの裏の仕事で使う）。
    # 目録の元のフォルダは zip の送り手が自由に書けるため、ネットワークの場所なら接続せず（Test-Path を呼ばず）$null（分からない）にする。
    # 利用者が元のフォルダを見て確かめる前に、サインイン情報が相手のサーバーへ送られないようにするため
    param (
        [string]$zipPath
    )

    $info = readIndexArchiveInfo $zipPath
    $exists = $false
    try {
        $folder = normalizeFolderPath ([string]$info.SourceFolder)
        if (testLocalDrivePath $folder) {
            $exists = [bool](Test-Path -LiteralPath $folder -PathType Container)
        } elseif ($folder) {
            # ローカルのドライブと分かるときだけ調べる。ネットワークの場所や、デバイス名の形（\\.\UNC\・\\.\GLOBALROOT\ など）は
            # 調べず「分からない」にする
            $exists = $null
        }
    } catch {
        # 使えない文字を含むなど。無いものとして扱う
    }
    $info.SourceExists = $exists
    return $info
}

function getImportUsedIndexNames {
    # 今使われているインデックス名（設定の targetFolders・indexSources、content_index\ 直下のフォルダ、
    # 取り込み一覧のクロール対象フォルダの行）を集めて返す（大文字・小文字を区別しない集合）
    param (
        $ws,
        [string]$settingsPath
    )

    $names = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($folder in @(getTargetFolders $settingsPath)) {
        if ($folder.Name) {
            [void]$names.Add($folder.Name)
        }
    }
    foreach ($source in @(readIndexSources $settingsPath)) {
        if ($source.Name) {
            [void]$names.Add($source.Name)
        }
    }
    if (Test-Path -LiteralPath (toLongPath $ws.IndexDir) -PathType Container) {
        foreach ($dir in [System.IO.Directory]::GetDirectories((toLongPath $ws.IndexDir))) {
            [void]$names.Add([System.IO.Path]::GetFileName($dir))
        }
    }
    foreach ($folder in (readStatusFile $ws.StatusFile).Folders.ToArray()) {
        if ($folder.Name) {
            [void]$names.Add($folder.Name)
        }
    }
    return , $names
}

function extractArchiveEntryToFile {
    # zip のエントリーを、目録の大きさ（expectedSize）を超えないようストリームで写す。
    # 書き終えたら大きさと SHA-256 を比べ、違えば例外にする（写したファイルは呼び出し側が消す）
    param (
        $entry,
        [long]$expectedSize,
        [string]$expectedSha256,
        [string]$destPath
    )

    [System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName((toLongPath $destPath))) | Out-Null
    $source = $entry.Open()
    $sha = New-Object System.Security.Cryptography.SHA256CryptoServiceProvider
    $total = [long]0
    try {
        $dest = New-Object System.IO.FileStream((toLongPath $destPath), [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
        try {
            $buffer = New-Object byte[] 1MB
            while ($true) {
                $read = $source.Read($buffer, 0, $buffer.Length)
                if ($read -le 0) {
                    break
                }
                $total += $read
                if ($total -gt $expectedSize) {
                    throw "エントリー「$($entry.FullName)」が目録の大きさより大きく展開されました。"
                }
                [void]$sha.TransformBlock($buffer, 0, $read, $buffer, 0)
                $dest.Write($buffer, 0, $read)
            }
        } finally {
            $dest.Dispose()
        }
        [void]$sha.TransformFinalBlock([byte[]]@(), 0, 0)
        $actualHash = [BitConverter]::ToString($sha.Hash).Replace("-", "")
    } finally {
        $source.Dispose()
        $sha.Dispose()
    }
    if ($total -ne $expectedSize -or $actualHash -ne $expectedSha256) {
        throw "エントリー「$($entry.FullName)」の大きさか内容が目録と違います。"
    }
}

function getWorkspaceFreeSpace {
    # root（ドライブのルート）の空き容量（バイト）を返す。UNC（\\server\share）など、ドライブとして扱えず調べられないときは $null
    # （調べられないだけでインポートを止めない。呼び出し側が確かめを飛ばす）
    param (
        [string]$root
    )

    try {
        return ([System.IO.DriveInfo]$root).AvailableFreeSpace
    } catch {
        return $null
    }
}

function importIndex {
    # zip から 1 つのインデックスをインポートする: @{ Name; SourcePath; Enabled; Files; Bytes; Warnings }。
    # collisionMode（Rename・Overwrite・Cancel）が Cancel なら $null を返す（ワークスペースは変えない）。
    # name・sourceFolder を省くと目録の値を使う。インデックス作成のロックを取れなければ例外
    param (
        [string]$zipPath,
        [string]$collisionMode,
        [string]$name = "",
        [string]$sourceFolder = "",
        $ws = $workspace,
        [string]$settingsPath = ${settingsFile},
        [scriptblock]$getFreeSpace = { param ($root) getWorkspaceFreeSpace $root }
    )

    $lock = newAppMutex "indexer" $ws.Dir
    if (!$lock.Acquired) {
        $lock.Mutex.Dispose()
        throw "更新中はインポートできません。更新が終わってからやり直してください。"
    }
    try {
        return (importIndexCore $zipPath $collisionMode $name $sourceFolder $ws $settingsPath $getFreeSpace)
    } finally {
        $lock.Mutex.ReleaseMutex()
        $lock.Mutex.Dispose()
    }
}

function testImportFreeSpace {
    # 空き容量が「目録の合計 + 余裕」に足りなければ、理由を返す（足りていれば空文字列）。
    # 空き容量を調べられないとき（getFreeSpace が $null を返す・例外になる。UNC のワークスペースなど）は確かめない
    param (
        [long]$totalBytes,
        [string]$root,
        [scriptblock]$getFreeSpace
    )

    $freeSpace = $null
    try {
        $freeSpace = & $getFreeSpace $root
    } catch {
    }
    if ($null -eq $freeSpace) {
        return ""
    }
    $needed = $totalBytes + ${indexArchiveFreeSpaceMargin}
    if ($freeSpace -lt $needed) {
        return "保存先の空き容量が足りません（必要 約 $([Math]::Ceiling($needed / 1MB)) MB）。"
    }
    return ""
}

function expandImportArchive {
    # 7. 目録にあるエントリーを作業フォルダ（<workDir>\new）に展開する（目録のパスからだけ作る。エントリーの名前からは作らない）。
    # 書き込む前に、大きさと SHA-256 を目録と比べる。source_folder.txt もここで作る。
    # 返すもの: @{ NewDir; Rows }（Rows は取り込み一覧に足す行。相対パスの先頭にインデックス名を付けたもの）。
    # 途中で失敗したら、作業フォルダを消して例外にする
    param (
        $archive,
        $fileEntries,
        [string]$workDir,
        [string]$finalName,
        [string]$folder
    )

    $newDir = Join-Path $workDir "new"
    removeDirectoryRetry $workDir
    [System.IO.Directory]::CreateDirectory((toLongPath $newDir)) | Out-Null
    try {
        $statusTmpPath = Join-Path $workDir ${indexArchiveStatusEntryName}
        $statusLines = $null
        foreach ($file in $fileEntries) {
            $path = [string]$file.path
            $entry = $archive.GetEntry($path)
            if ($null -eq $entry) {
                throw "目録にあるのに zip に無いエントリーがあります: ${path}"
            }
            $size = [long]$file.size
            $sha256 = [string]$file.sha256
            if ($path -ceq ${indexArchiveStatusEntryName}) {
                extractArchiveEntryToFile $entry $size $sha256 $statusTmpPath
                $bytes = [System.IO.File]::ReadAllBytes((toLongPath $statusTmpPath))
                $text = ${utf8Bom}.GetString($bytes)
                $statusLines = @($text -split "\r?\n" | Where-Object { $_ -ne "" })
                $reason = testImportedStatusLines $statusLines
                if ($reason) {
                    throw "ingest_status.tsv を読み込めません（${reason}）"
                }
            } else {
                $rel = $path.Substring("content_index/".Length).Replace("/", "\")
                extractArchiveEntryToFile $entry $size $sha256 (Join-Path $newDir $rel)
            }
        }
        if ($null -eq $statusLines) {
            throw "目録に ${indexArchiveStatusEntryName} がありません。"
        }

        $rows = New-Object System.Collections.Generic.List[object]
        foreach ($line in @($statusLines | Select-Object -Skip 1)) {
            $fields = $line.Split("`t")
            $rows.Add((newStatusRow "${finalName}\$($fields[0])" $fields[1] $fields[2] $fields[3] $fields[4] $fields[5] $fields[6] $fields[7]))
        }

        $header = "# 検索結果から元のファイルを開くときに使う、インデックス名とクロール対象フォルダの対応です（インデックス作成のたびに作り直します）"
        writeListFile (Join-Path $newDir ${sourceFolderFileName}) @($header, "${finalName}`t${folder}")
        return @{ NewDir = $newDir; Rows = $rows.ToArray() }
    } catch {
        removeDirectoryRetry $workDir
        throw
    }
}

function restoreImportedSettings {
    # registerImportedIndexInSettings で変える前の内容（before）に、設定の 3 つの項目（クロール対象・検索だけのインデックス・検索から外したフォルダ）を戻す。
    # ほかの項目には触らない
    param (
        $before,
        [string]$settingsPath
    )

    invokeSettingsLocked -path $settingsPath -action {
        writeTargetFolders $before.Targets $settingsPath
        if ($before.SourcesChanged) {
            writeIndexSources $before.Sources $settingsPath
        }
        if ($before.ExcludesChanged) {
            writeSearchExcludes $before.Excludes $settingsPath
        }
    } | Out-Null
}

function registerImportedIndexInSettings {
    # 8. 設定にインデックスを登録する（クロール対象に名前と元のフォルダを入れる。同じ名前があれば置き換え、同じ名前の検索だけのインデックスは外す。
    # 上書きなら、前のインデックスの検索から外したフォルダの記録も消す）。
    # 途中で失敗したら、変える前に戻して例外にする。成功したら、戻すための @{ Targets; Sources; Excludes; SourcesChanged; ExcludesChanged } を返す
    param (
        [string]$finalName,
        [string]$folder,
        [bool]$overwrite,
        [string]$indexDir,
        [string]$settingsPath
    )

    $before = invokeSettingsLocked -path $settingsPath -action {
        return @{
            Targets = @(getTargetFolders $settingsPath); Sources = @(readIndexSources $settingsPath)
            Excludes = @(readSearchExcludes $settingsPath); SourcesChanged = $false; ExcludesChanged = $false
        }
    }
    try {
        invokeSettingsLocked -path $settingsPath -action {
            $enabled = [System.IO.Directory]::Exists((toLongPath $folder))
            $entry = [pscustomobject]@{ Name = $finalName; Path = $folder; Enabled = $enabled }
            $targets = New-Object System.Collections.Generic.List[object]
            $found = $false
            foreach ($target in $before.Targets) {
                if ($target.Name -ieq $finalName) {
                    $targets.Add($entry)
                    $found = $true
                } else {
                    $targets.Add($target)
                }
            }
            if (!$found) {
                $targets.Add($entry)
            }
            writeTargetFolders $targets.ToArray() $settingsPath
            if (@($before.Sources | Where-Object { $_.Name -ieq $finalName }).Count -gt 0) {
                $before.SourcesChanged = $true
                writeIndexSources @($before.Sources | Where-Object { $_.Name -ine $finalName }) $settingsPath
            }
            if ($overwrite) {
                $before.ExcludesChanged = $true
                [void](removeSearchExcludesUnder $indexDir $settingsPath)
            }
        } | Out-Null
    } catch {
        restoreImportedSettings $before $settingsPath
        throw
    }
    return $before
}

function swapInImportedIndexDir {
    # 9. content_index\<名前> を展開したフォルダ（newDir）に入れ替える。前のフォルダは previous に退避する。
    # 失敗したら、退避したフォルダを戻して例外にする。成功したら、戻すための @{ TargetDir; PreviousDir; HadPrevious } を返す
    param (
        [string]$newDir,
        [string]$targetDir,
        [string]$previousDir,
        [string]$indexRoot
    )

    # ウイルス対策ソフトが、作ったばかり・書いたばかりのフォルダ（$targetDir は前の取り込みで、$newDir はこの
    # インポートの展開で、それぞれ書いたばかり）を一時的に掴んでいることがあるため、moveDirectoryRetry で試し直す
    # （removeDirectoryRetry と同じ理由。docs/design/index-data/format.md「インポート」を参照）
    $hadPrevious = Test-Path -LiteralPath (toLongPath $targetDir) -PathType Container
    if ($hadPrevious) {
        moveDirectoryRetry $targetDir $previousDir
    }
    try {
        [System.IO.Directory]::CreateDirectory((toLongPath $indexRoot)) | Out-Null
        moveDirectoryRetry $newDir $targetDir
    } catch {
        if ($hadPrevious) {
            moveDirectoryRetry $previousDir $targetDir
        }
        throw
    }
    return @{ TargetDir = $targetDir; PreviousDir = $previousDir; HadPrevious = $hadPrevious }
}

function restoreSwappedIndexDir {
    # swapInImportedIndexDir で入れ替えたフォルダを、入れ替える前に戻す（入れたものを消し、退避した前のフォルダを戻す）
    param (
        $swap
    )

    removeDirectoryRetry $swap.TargetDir
    if ($swap.HadPrevious) {
        moveDirectoryRetry $swap.PreviousDir $swap.TargetDir
    }
}

function rewriteStatusForImport {
    # 10. 取り込み一覧を書き直す（このインデックスの前のクロール対象フォルダの行と各行を消し、新しい行を足す）。
    # ほかのインデックスの行は残す。見出しの行を含め、インデクサが書くのと同じ形（writeStatusFile）で書く
    param (
        [string]$statusPath,
        [string]$finalName,
        [string]$folder,
        $importedRows
    )

    $status = readStatusFile $statusPath
    $folders = New-Object System.Collections.Generic.List[object]
    foreach ($other in $status.Folders) {
        if (![string]::Equals($other.Name, $finalName, [System.StringComparison]::OrdinalIgnoreCase)) {
            $folders.Add($other)
        }
    }
    $folders.Add([pscustomobject]@{ Path = $folder; Name = $finalName })

    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($row in $status.Rows.Values) {
        if (![string]::Equals((splitIndexRelPath $row.相対パス).Name, $finalName, [System.StringComparison]::OrdinalIgnoreCase)) {
            $rows.Add($row)
        }
    }
    foreach ($row in $importedRows) {
        $rows.Add($row)
    }
    writeStatusFile $folders.ToArray() $rows.ToArray() $statusPath
}

function importIndexCore {
    param (
        [string]$zipPath,
        [string]$collisionMode,
        [string]$name,
        [string]$sourceFolder,
        $ws,
        [string]$settingsPath,
        [scriptblock]$getFreeSpace
    )

    # 前の版のワークスペース（index\ あり・content_index\ が空）を、取り込み直しを始めるときと同じ手順で片付ける。
    # content_index\ にこのインポートの分を足す前に行う（片付けに失敗したら、以降は行わない）
    $legacyState = getLegacyIndexState $ws.Dir
    if (testLegacyCleanupNeeded $legacyState) {
        $cleanup = clearLegacySystemIndex $ws.Dir
        if (!$cleanup.Ok) {
            throw "前の版のインデックス（高速検索用）を片付けられませんでした（$($cleanup.Reason)）。tebunko の画面やエクスプローラーで開いていれば閉じてから、もう一度インポートしてください。"
        }
    }

    $opened = openIndexArchive $zipPath
    $archive = $opened.Archive
    try {
        $manifest = $opened.Manifest
        $suggestedName = if ($name) { $name } else { [string]$manifest.indexName }
        # 集合を返す関数なので、@() で包まない（包むと集合が 1 要素の配列になり、newIndexName が名前を突き合わせられず、
        # 「別名」でも同じ名前のインデックスを上書きしてしまう）
        $usedNames = getImportUsedIndexNames $ws $settingsPath
        $finalName = getImportIndexName $suggestedName $usedNames $collisionMode
        if ($null -eq $finalName) {
            return $null
        }
        $nameReason = testIndexName $finalName @()
        if ($nameReason) {
            throw $nameReason
        }
        $overwrite = ($collisionMode -eq ${importCollisionOverwrite})

        $folder = if ($sourceFolder) { normalizeFolderPath $sourceFolder } else { getManifestSourceFolder $manifest }
        if ($folder -eq "") {
            throw "元のフォルダを指定してください。"
        }

        $totalBytes = [long]0
        $fileEntries = @($manifest.files)
        foreach ($file in $fileEntries) {
            $totalBytes += [long]$file.size
        }
        $spaceReason = testImportFreeSpace $totalBytes ([System.IO.Path]::GetPathRoot($ws.Dir)) $getFreeSpace
        if ($spaceReason) {
            throw $spaceReason
        }

        # 同じ元のフォルダが、別の名前のクロール対象フォルダに既にある・入れ子になっていれば止める（getTargetFolders は同じフォルダの 2 つ目以降を読まないため、
        # 登録しても設定に残らず、次のインデックス作成の確認に、このインデックスが「削除予定」として出る。画面の追加・編集と同じ getIndexFolderConflict の決まり）。
        # 検索だけのインデックス（indexSources）の元のフォルダと同じなら、止めずに知らせる
        $conflict = getIndexFolderConflict $folder @(getTargetFolders $settingsPath | Where-Object { $_.Name -ine $finalName })
        if ($conflict -ne "") {
            throw $conflict
        }
        $warnings = New-Object System.Collections.Generic.List[string]
        foreach ($other in @(readIndexSources $settingsPath | Where-Object { $_.Name -ine $finalName })) {
            if (testSameFolder $other.Path $folder) {
                $warnings.Add("元のフォルダ「${folder}」は、インデックス [$($other.Name)] としても登録されています。")
                break
            }
        }

        $workDir = Join-Path $ws.PublishDir "import"
        $expanded = expandImportArchive $archive $fileEntries $workDir $finalName $folder
        $targetIndexDir = Join-Path $ws.IndexDir $finalName
        try {
            $before = registerImportedIndexInSettings $finalName $folder $overwrite $targetIndexDir $settingsPath
            try {
                $swap = swapInImportedIndexDir $expanded.NewDir $targetIndexDir (Join-Path $workDir "previous") $ws.IndexDir
                # Directory.Move で入れたフォルダは、work\content_index の NotContentIndexed を受け継がない。
                # 根に付いたあとの -Recurse は中へ降りないため（publish.md）、入れた直後に付ける（失敗しても止めない）
                setNotContentIndexed $targetIndexDir -Recurse | Out-Null
                try {
                    rewriteStatusForImport $ws.StatusFile $finalName $folder $expanded.Rows
                } catch {
                    restoreSwappedIndexDir $swap
                    throw
                }
            } catch {
                restoreImportedSettings $before $settingsPath
                throw
            }
        } catch {
            removeDirectoryRetry $workDir
            throw
        }

        # 11. 上書きなら、前のシステムインデックスを消す（消せなくても続ける。次のインデックス作成で整理される）
        if ($overwrite) {
            removeSystemIndexOfWorkspace $finalName $ws.IndexDir
        }
        # 12. 作業フォルダを消す
        removeDirectoryRetry $workDir

        return @{
            Name = $finalName; SourcePath = $folder; Enabled = [System.IO.Directory]::Exists((toLongPath $folder))
            Files = $fileEntries.Count; Bytes = $totalBytes; Warnings = $warnings.ToArray()
        }
    } finally {
        $archive.Dispose()
    }
}
@@'@
${bundledParts}['indexerLib'] = @'
# インデックス作成の部品の読み込み口。indexer.ps1 と、取り込みのスレッド（indexer_run.ps1 の ingestWorkerScript）が dot-source する。
# 画面は読み込まない（インデックス作成は、画面のインデクサのスレッドが indexer.ps1 を実行して行う）
# tebunko の画面以外の部品の読み込み口。
# 画面（gui）・インデクサ・テスト・画面が起こす別スレッドから dot-source して使う。読み込む順に意味がある。
# 共通基盤（どのツールからも使う部品）の読み込み口。
# ツール側は、このファイルを dot-source すれば共通基盤がそろう。読み込む順に意味がある。
# フォルダ構成の基本（どのツールからも使う）。

# このファイルは scripts\shared\core\ に置く。3 つ上がリポジトリ直下になる（zip 版）。
# 単一 .ps1 版（展開せずに動く試験版。設計は docs/design/structure/single-script.md）は、
# scripts\ の下の階層が無いため、${bundledScriptPath}（結合の道具が入れる、自分自身のパス）があれば
# その .ps1 自身の置き場所を根フォルダとする
${pathsBundled} = Get-Variable -Name bundledScriptPath -ErrorAction SilentlyContinue
${rootDir} = if ($null -ne ${pathsBundled} -and ${pathsBundled}.Value) {
    Split-Path -Parent ${pathsBundled}.Value
} else {
    [System.IO.Path]::GetFullPath("$PSScriptRoot\..\..\..")
}
Remove-Variable -Name pathsBundled -ErrorAction SilentlyContinue
# データ（設定ファイル・work）の置き場所は data_dir.ps1 で決める（ツールのフォルダに書き込めないことがあるため）

${utf8Bom} = New-Object System.Text.UTF8Encoding($true)
# ファイルの読み書き（行ファイル・原子的な書き込み・長いパス・排他）。


# ---- パスの状態（見つかった・見つからない・接続できない・その他） ----
#
# Test-Path・File.Exists・Directory.Exists は、届かない共有でも多くの場合に例外を出さず $false を返す
# （「見つからない」と区別できない）。getPathState は、例外を投げる呼び出し（File.GetAttributes）で調べる。

${pathStateFound}       = "Found"
${pathStateMissing}     = "Missing"
${pathStateUnreachable} = "Unreachable"
${pathStateOther}       = "Other"

# 接続できない（届かない共有・ネットワークの問題）を表す Win32 のエラー番号
# ERROR_BAD_NETPATH(53)・ERROR_BAD_NET_NAME(67)・ERROR_NETNAME_DELETED(64)・ERROR_SEM_TIMEOUT(121)・
# ERROR_NETWORK_UNREACHABLE(1231)・ERROR_HOST_UNREACHABLE(1232)・ERROR_NO_NET_OR_BAD_PATH(1222)
${unreachableWin32Codes} = @(53, 67, 64, 121, 1231, 1232, 1222)

# ---- クラウドにだけあるファイル（OneDrive・SharePoint などのオンデマンド） ----
#
# 一覧（Get-ChildItem）が返す属性だけで見分ける。ファイルを開かないので、ダウンロードは起きない。
#   RECALL_ON_DATA_ACCESS(0x400000)・RECALL_ON_OPEN(0x40000)・OFFLINE(0x1000) のどれかが付いていれば、
#   中身は手元に無い（開くとダウンロードされる）。
#   PINNED(0x80000)・UNPINNED(0x100000)・ReparsePoint だけでは、クラウドにだけあるとは言えない。

${attributeRecallOnDataAccess} = 0x400000
${attributeRecallOnOpen}       = 0x40000
${attributeOffline}            = 0x1000

function testCloudOnlyAttributes {
    # ファイルの属性（数値）が、中身が手元に無い（クラウドにだけある）ことを表すとき $true
    param (
        [int]$attributes
    )

    $mask = ${attributeRecallOnDataAccess} -bor ${attributeRecallOnOpen} -bor ${attributeOffline}
    return (($attributes -band $mask) -ne 0)
}

function readListFile {
    # 1行1件のファイルを読み込む（空行を除く）。ファイルが無ければ空配列。
    # 読めない（ほかが書き込み中など）ときは例外にする。呼び出し側の $ErrorActionPreference が既定の Continue でも
    # 空の一覧と取り違えないよう -ErrorAction Stop を付ける
    param (
        [string]$path
    )

    if (!(Test-Path -LiteralPath $path)) {
        return @()
    }
    return @(Get-Content -LiteralPath $path -Encoding UTF8 -ErrorAction Stop | Where-Object { $_.Trim() -ne "" })
}

function writeListFile {
    param (
        [string]$path,
        [string[]]$lines
    )

    if ($null -eq $lines) {
        $lines = [string[]]@()
    }
    [System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($path)) | Out-Null
    [System.IO.File]::WriteAllLines($path, $lines, ${utf8Bom})
}

function formatFileTime {
    # 取り込み一覧に記録する日時の書式（秒まで）。更新の有無はこの文字列で比べる
    param (
        [datetime]$time
    )

    return $time.ToString("yyyy/MM/dd HH:mm:ss", [System.Globalization.CultureInfo]::InvariantCulture)
}

function writeTextLinesAtomic {
    # 途中で中断してもファイルが壊れないよう、一時ファイルに書いてから置き換える
    param (
        [string]$path,
        [object[]]$lines,
        [System.Text.Encoding]$encoding = ${utf8Bom}  # 文字コード（既定は BOM 付き UTF-8）
    )

    [System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($path)) | Out-Null
    $tmpPath = "${path}.tmp"
    [System.IO.File]::WriteAllLines($tmpPath, [string[]]@($lines), $encoding)
    # 書いた直後のファイルは、ウイルス対策ソフト等が一時的に掴んでいて置き換えられないことがあるため、少し待って数回試す
    for ($i = 1; $true; $i++) {
        try {
            if (Test-Path -LiteralPath $path) {
                # $null は空文字列として渡されて例外になるため、[NullString]::Value（バックアップを作らない）を渡す
                [System.IO.File]::Replace($tmpPath, $path, [NullString]::Value)
            } else {
                [System.IO.File]::Move($tmpPath, $path)
            }
            return
        } catch {
            if ($i -ge 5) {
                throw
            }
            Start-Sleep -Milliseconds 200
        }
    }
}

function toSafeFileName {
    # ファイル名に使えない文字を全角に変換
    param (
        [string]$name
    )

    $name = $name.Replace(">", "＞")
    $name = $name.Replace("<", "＜")
    $name = $name.Replace("\", "￥")
    $name = $name.Replace("*", "＊")
    $name = $name.Replace('"', '”')
    $name = $name.Replace(":", "：")
    $name = $name.Replace("?", "？")
    $name = $name.Replace("|", "｜")
    $name = $name.Replace("/", "／")

    return $name
}


${maxFileNameLength} = 255  # Windows のファイル名（パスの区切りの間の1つ）の上限


function toLongPath {
    # パスの先頭に \\?\ を付け、260文字を超えるパスもファイル操作（System.IO・-LiteralPath）で扱えるようにする。
    # ネットワークのパス（\\server\share\…）は \\?\UNC\server\share\… にする。付いていればそのまま返す。
    # Join-Path は \\?\ 付きのパスを扱えないため、パスを組み立てた後、ファイル操作に渡す直前に使う
    param (
        [string]$path
    )

    if (!$path -or $path.StartsWith("\\?\")) {
        return $path
    }
    $path = $path.Replace("/", "\")
    if ($path.StartsWith("\\")) {
        return "\\?\UNC\" + $path.Substring(2)
    }
    return "\\?\" + $path
}

function copyFileShared {
    # 元のファイルに影響を出さずにコピーする（インデックス作成は、元のファイルでなくこのコピーを読んで行う）。
    # 書き込み中のファイルも、読み取りだけで開いてコピーできる（書きかけの中身が入ることは、直接読む場合と同じ）。
    # 排他で開かれたファイルはコピーできず、取り込みの失敗になる。
    # File.Copy は元のファイルをほかのアプリの書き込みを拒否して開くため、コピーの間は利用者が上書き保存できず、
    # 利用者がファイルを開いて編集中だとコピーできないことがある。
    # ここでは読み取りだけで開き、ほかのアプリの読み書き・削除・名前変更を妨げない。
    # コピー先は通常の属性（読み取り専用などを付けない）で作り、既にあれば上書きする
    param (
        [string]$sourcePath,
        [string]$destPath
    )

    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $source = New-Object System.IO.FileStream((toLongPath $sourcePath), [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    try {
        $dest = New-Object System.IO.FileStream((toLongPath $destPath), [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
        try {
            $source.CopyTo($dest, 1MB)
        } finally {
            $dest.Dispose()
        }
    } finally {
        $source.Dispose()
    }
}

function fromLongPath {
    # toLongPath で付けた \\?\ を外し、通常のパスに戻す（Get-ChildItem の FullName 等から相対パスを求めるため）
    param (
        [string]$path
    )

    if ($path.StartsWith("\\?\UNC\")) {
        return "\\" + $path.Substring(8)
    }
    if ($path.StartsWith("\\?\")) {
        return $path.Substring(4)
    }
    return $path
}

function trimTrailingSeparator {
    # パスの末尾の \ と / を落とす（リンクの判定・削除の入口で使う。念のため、末尾の区切りでリンクの先を見ることが無いようにする）。
    # 途中の区切りは変えない（\\?\ で始まらないパスの / は、あとで toLongPath が \ にそろえる。\\?\ で始まるパスの / はそのまま）。
    # 落とした結果が空か : で終わるパス（C:\ ・ \\?\C:\ ・ \ ・ / ）と、\\?\ だけのパスは、そのまま返す。
    # それ以外は、UNC の根（\\server\share\）や \\?\Volume{...}\ も、末尾を落とす
    param (
        [string]$path
    )

    if (!$path) {
        return $path
    }
    $trimmed = $path.TrimEnd([char[]]@("\", "/"))
    if (!$trimmed -or $trimmed.EndsWith(":") -or $trimmed -eq "\\?") {
        return $path
    }
    return $trimmed
}

function setNotContentIndexed {
    # フォルダ（またはファイル）に「内容のインデックスを作成しない」属性（NotContentIndexed）を付ける。
    # 既に付いているものには付け直さない（Changed に数えない）ので、ほかの属性（読み取り専用など）は変えない。
    #   Recurse 無し: path 自身と、フォルダなら直下のファイルに付ける（下のフォルダには付けない）
    #   Recurse あり: path 自身と、下のすべてのフォルダ・ファイルに付ける
    # Recurse でフォルダを渡したときは、根フォルダの属性を下より先に確かめる。既に付いていれば
    # （前回すべて付け終えて根に付けたということなので）下はたどらず、GetAttributes 1 回だけで終える。
    # 根の属性は、下をすべて付け終えて成功したときにだけ最後に付ける（列挙・付与の途中で失敗した回は
    # 根に付けない。次回もう一度下からたどり直せるようにするため）。
    # 1件ずつの失敗（アクセス拒否など）も、列挙そのものの失敗（無いパス・列挙の途中で読めなくなったフォルダなど）も
    # 例外にせず、@{ Ok; Changed; Reason }（最初に見つかった理由を Reason に）を返す。
    # 呼び出し元（インデックス作成）は、Ok が $false でも処理を止めず、ログに 1 行残すだけにする
    param (
        [string]$path,
        [switch]$Recurse
    )

    $flag = [System.IO.FileAttributes]::NotContentIndexed
    $state = getPathState $path
    if ($state.State -ne ${pathStateFound}) {
        $reason = if ($state.Message) { $state.Message } else { "パスが見つかりません（${path}）" }
        return @{ Ok = $false; Changed = 0; Reason = $reason }
    }

    $long = toLongPath $path
    $deferRoot = [bool]($Recurse -and $state.IsDirectory)
    if ($deferRoot) {
        try {
            $rootAttrs = [System.IO.File]::GetAttributes($long)
        } catch {
            return @{ Ok = $false; Changed = 0; Reason = $_.Exception.Message }
        }
        if ($rootAttrs -band $flag) {
            return @{ Ok = $true; Changed = 0; Reason = "" }
        }
    }

    # 先に対象（path 自身と、必要なら中身）をすべて列挙してから属性を付ける。deferRoot のときは
    # 根自身をここでは含めず、下だけを集める（根は下がすべて終わったあとに付ける）。
    # 列挙そのものが例外になったら（途中で消えた・読めないフォルダがあるなど）、途中まで集めた分は捨てて Ok=$false にする
    $items = New-Object System.Collections.Generic.List[object]
    if (!$deferRoot) {
        $items.Add(@{ Path = $path; IsDirectory = $state.IsDirectory })
    }
    try {
        if ($state.IsDirectory) {
            $dirInfo = New-Object System.IO.DirectoryInfo $long
            if ($Recurse) {
                foreach ($entry in $dirInfo.EnumerateFileSystemInfos("*", [System.IO.SearchOption]::AllDirectories)) {
                    $items.Add(@{ Path = (fromLongPath $entry.FullName); IsDirectory = ($entry -is [System.IO.DirectoryInfo]) })
                }
            } else {
                foreach ($file in $dirInfo.EnumerateFiles("*", [System.IO.SearchOption]::TopDirectoryOnly)) {
                    $items.Add(@{ Path = (fromLongPath $file.FullName); IsDirectory = $false })
                }
            }
        }
    } catch {
        return @{ Ok = $false; Changed = 0; Reason = $_.Exception.Message }
    }

    $changed = 0
    $ok = $true
    $reason = ""
    foreach ($item in $items) {
        try {
            # フォルダ・ファイルどちらも [System.IO.File]::Get/SetAttributes で扱う（Directory クラスには同名のメソッドが無い）
            $itemLong = toLongPath $item.Path
            $attrs = [System.IO.File]::GetAttributes($itemLong)
            if ($attrs -band $flag) {
                continue
            }
            [System.IO.File]::SetAttributes($itemLong, ($attrs -bor $flag))
            $changed++
        } catch {
            $ok = $false
            if (!$reason) {
                $reason = $_.Exception.Message
            }
        }
    }

    if ($deferRoot -and $ok) {
        try {
            [System.IO.File]::SetAttributes($long, ($rootAttrs -bor $flag))
            $changed++
        } catch {
            $ok = $false
            if (!$reason) {
                $reason = $_.Exception.Message
            }
        }
    }

    return @{ Ok = $ok; Changed = $changed; Reason = $reason }
}

function testNotContentIndexed {
    # path に「内容のインデックスを作成しない」属性（NotContentIndexed）が付いているかを返す。
    # 属性を確かめられなければ（パスが無い・アクセスできないなど）例外にせず $false を返す
    param (
        [string]$path
    )

    try {
        $attrs = [System.IO.File]::GetAttributes((toLongPath $path))
        return [bool]($attrs -band [System.IO.FileAttributes]::NotContentIndexed)
    } catch {
        return $false
    }
}

function removeDirectoryRetry {
    # フォルダを中身ごと削除する。ウイルス対策ソフト・エクスプローラーが一時的に掴んでいることがあるため、少し待って数回試す
    param (
        [string]$path,
        [int]$tries = 3,
        [int]$waitMilliseconds = 200
    )

    # 中に長いパス（260文字超）のファイルがあっても削除できるよう \\?\ 付きで削除する
    $longPath = toLongPath $path
    for ($i = 1; $true; $i++) {
        if (![System.IO.Directory]::Exists($longPath)) {
            return
        }
        try {
            # リンク（ジャンクション・シンボリックリンク）は辿らず、リンクそのものだけを外す（removeTreeNoFollow）。
            # 消せなければ例外になり、catch で試し直す
            removeTreeNoFollow $longPath
            return
        } catch {
            if ($i -ge $tries) {
                throw
            }
            Start-Sleep -Milliseconds $waitMilliseconds
        }
    }
}

function getLinkKind {
    # item（Get-Item・Get-ChildItem・DirectoryInfo などが返す FileSystemInfo）の種類を返す。
    #   Link    … ジャンクション・シンボリックリンク（属性に ReparsePoint が付き、LinkType がそのどちらか）
    #   Unknown … 属性が読めない、またはフォルダなのに ReparsePoint が付き LinkType がジャンクション・シンボリックリンクと確かめられない
    #             （OneDrive のオンデマンドの置き場のフォルダなど）。リンクかどうか分からないので、辿らず、消しもしない
    #   Plain   … それ以外（ReparsePoint の付いたファイルは、辿るものが無いので Plain）
    # 先に属性の ReparsePoint を見て、付いているときだけ LinkType を読む（多くのファイルで余計な問い合わせをしない）。
    # 5.1 ではプロパティを読んだときの例外は $null になる（catch に届かない）ため、$null を読めなかったものとして扱う
    param (
        $item
    )

    $attributes = $item.Attributes
    if ($null -eq $attributes) {
        return "Unknown"
    }
    if (!($attributes -band [System.IO.FileAttributes]::ReparsePoint)) {
        return "Plain"
    }
    $linkType = [string]$item.LinkType
    if ($linkType -eq "Junction" -or $linkType -eq "SymbolicLink") {
        return "Link"
    }
    if ($attributes -band [System.IO.FileAttributes]::Directory) {
        return "Unknown"
    }
    return "Plain"
}

function testLinkItem {
    # item が、辿ってはいけないもの（getLinkKind が Link か Unknown）なら $true
    param (
        $item
    )

    return ((getLinkKind $item) -ne "Plain")
}

function testPathIsLink {
    # path そのもの（途中の階層は見ない）がジャンクション・シンボリックリンクなら $true。
    # 無い・空のパスは $false（まだ作っていない）。属性が読めない、リンクかどうか確かめられないフォルダ（getLinkKind が Unknown）のときは $true（辿らない側に倒す）
    param (
        [string]$path
    )

    if (!$path) {
        return $false
    }
    $long = toLongPath (trimTrailingSeparator $path)
    try {
        $attributes = [System.IO.File]::GetAttributes($long)
    } catch [System.IO.FileNotFoundException] {
        return $false
    } catch [System.IO.DirectoryNotFoundException] {
        return $false
    } catch {
        return $true
    }
    if (!($attributes -band [System.IO.FileAttributes]::ReparsePoint)) {
        return $false
    }
    if ($attributes -band [System.IO.FileAttributes]::Directory) {
        return (testLinkItem (New-Object System.IO.DirectoryInfo $long))
    }
    return (testLinkItem (New-Object System.IO.FileInfo $long))
}

function testPathHasLink {
    # base の下の path まで、途中の各階層（path を含み、base とそれより上は含まない）に、リンクがあれば $true。
    # 利用者が選んだ置き場（base）そのものが別の場所へのリンクでも、構成を変えずに使えるよう、base は見ない。
    # path が base と同じなら $false。base の下になければ、確かめられないので $true
    param (
        [string]$base,
        [string]$path
    )

    try {
        $baseFull = [System.IO.Path]::GetFullPath((fromLongPath $base)).TrimEnd("\")
        $pathFull = [System.IO.Path]::GetFullPath((fromLongPath $path)).TrimEnd("\")
    } catch {
        return $true
    }
    if ($pathFull.Equals($baseFull, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $false
    }
    if (!$pathFull.StartsWith("$baseFull\", [System.StringComparison]::OrdinalIgnoreCase)) {
        return $true
    }
    $current = $baseFull
    foreach ($name in $pathFull.Substring($baseFull.Length + 1).Split("\")) {
        $current = "$current\$name"
        if (testPathIsLink $current) {
            return $true
        }
        if (!(Test-Path -LiteralPath (toLongPath $current))) {
            return $false  # ここから先はまだ無い
        }
    }
    return $false
}

function removeEntryOnly {
    # ファイル 1 つ・リンク（ジャンクション・シンボリックリンク）1 つ・空のフォルダ 1 つ（item は FileSystemInfo）を、そのものだけ消す。
    # リンクの先は消さない。読み取り専用の属性は外してから消す
    param (
        [System.IO.FileSystemInfo]$item
    )

    $path = $item.FullName
    $attributes = $item.Attributes
    if ($attributes -band [System.IO.FileAttributes]::ReadOnly) {
        # 読み取り専用だけを外す（ほかの属性は変えない）
        [System.IO.File]::SetAttributes($path, ($attributes -band (-bnot [System.IO.FileAttributes]::ReadOnly)))
    }
    if ($item -is [System.IO.DirectoryInfo]) {
        [System.IO.Directory]::Delete($path, $false)
    } else {
        [System.IO.File]::Delete($path)
    }
}

function removeTreeNoFollow {
    # フォルダを中身ごと削除する。ジャンクション・シンボリックリンクは辿らず、リンクそのものだけを外す（先は消さない）。
    # path そのものがリンクなら、そのリンクだけを外す。フォルダが無ければ何もしない。
    # 先に全体を数える（リンクは辿らない）。リンクかどうか確かめられないフォルダ（getLinkKind が Unknown）が 1 つでもあれば、
    # 降りず、何も消さずに例外にする。何も消さないと言えるのは、この数える段で見つけた Unknown のときだけ。
    # そのあとで、ファイル・リンク・フォルダ（下から順）を消す。
    # 降りる直前と、フォルダのファイルを消す直前に、そのフォルダがリンクでないかを確かめ直す。
    # 数えたあとにフォルダがリンクに替わっていたら例外にする。それまでに消した分は戻らない。
    # 消す直前に確かめ直すのは、そのフォルダ自身だけ。上の階層が途中で替わったときは見つけられない。
    # 読み取り専用の属性は外して消す（Remove-Item -Force と同じ働き）。消せなければ例外にする
    param (
        [string]$path
    )

    $long = toLongPath (trimTrailingSeparator $path)
    if (![System.IO.Directory]::Exists($long)) {
        return
    }
    $filesByDirectory = New-Object 'System.Collections.Generic.Dictionary[string,System.Collections.Generic.List[string]]'
    $links = New-Object System.Collections.Generic.List[string]
    $directories = New-Object System.Collections.Generic.List[string]
    $pending = New-Object System.Collections.Generic.Stack[string]
    $pending.Push($long)
    while ($pending.Count -gt 0) {
        $current = New-Object System.IO.DirectoryInfo ($pending.Pop())
        $currentKind = getLinkKind $current
        if ($currentKind -eq "Unknown") {
            throw "リンクかどうか確かめられないフォルダのため、消しませんでした: $(fromLongPath $current.FullName)"
        }
        if ($currentKind -eq "Link") {
            $links.Add($current.FullName)
            continue
        }
        $directories.Add($current.FullName)
        $filesByDirectory[$current.FullName] = New-Object System.Collections.Generic.List[string]
        foreach ($entry in @($current.EnumerateFileSystemInfos("*", [System.IO.SearchOption]::TopDirectoryOnly))) {
            if ($entry -isnot [System.IO.DirectoryInfo]) {
                $filesByDirectory[$current.FullName].Add($entry.FullName)
            } elseif ((getLinkKind $entry) -eq "Link") {
                $links.Add($entry.FullName)
            } else {
                # 確かめられないもの（Unknown）も積む。降りる直前の確かめで例外にする（列挙の途中では投げない）
                $pending.Push($entry.FullName)
            }
        }
    }
    foreach ($directory in $directories) {
        if ((getLinkKind (New-Object System.IO.DirectoryInfo $directory)) -ne "Plain") {
            throw "数えたあとでリンクに替わったフォルダのため、中のファイルを消しませんでした: $(fromLongPath $directory)"
        }
        foreach ($file in $filesByDirectory[$directory]) {
            removeEntryOnly (New-Object System.IO.FileInfo $file)
        }
    }
    foreach ($link in $links) {
        removeEntryOnly (New-Object System.IO.DirectoryInfo $link)
    }
    for ($i = $directories.Count - 1; $i -ge 0; $i--) {
        removeEntryOnly (New-Object System.IO.DirectoryInfo $directories[$i])
    }
}

function moveDirectoryRetry {
    # フォルダを移動する。removeDirectoryRetry と同じ理由（ウイルス対策ソフト・エクスプローラーが、
    # 作ったばかり・書いたばかりのフォルダを一時的に掴んでいることがある）で、待つ時間を倍にしながら数回試す
    # （削除より、掴まれている時間が長くかかることがあるため、既定の回数・最初の待ち時間を大きくしている）
    param (
        [string]$source,
        [string]$destination,
        [int]$tries = 5,
        [int]$waitMilliseconds = 200
    )

    $longSource = toLongPath $source
    $longDestination = toLongPath $destination
    $wait = $waitMilliseconds
    for ($i = 1; $true; $i++) {
        try {
            [System.IO.Directory]::Move($longSource, $longDestination)
            return
        } catch {
            if ($i -ge $tries) {
                throw
            }
            Start-Sleep -Milliseconds $wait
            $wait *= 2
        }
    }
}

function testAnyEntry {
    # 列挙（[System.IO.Directory]::EnumerateFiles などの結果）に、predicate が $true を返すもの（省略したら何でも）が
    # 1 つでもあるか。見つけたところで列挙をやめ、列挙子を必ず Dispose する。
    # foreach を break・return・throw で途中で抜けると列挙子が Dispose されず、調べていた下のフォルダを開いたまま残る。
    # GC されるまで、そのフォルダと上のフォルダを移動・削除できなくなる（Directory.Move がアクセス拒否になる）ため、
    # 途中でやめる列挙はこの関数を通す
    param (
        [System.Collections.IEnumerable]$entries,
        [scriptblock]$predicate
    )

    $enumerator = $entries.GetEnumerator()
    try {
        while ($enumerator.MoveNext()) {
            if ($null -eq $predicate -or (& $predicate $enumerator.Current)) {
                return $true
            }
        }
        return $false
    } finally {
        if ($enumerator -is [System.IDisposable]) {
            $enumerator.Dispose()
        }
    }
}

function selectFirstEntries {
    # 列挙（[System.IO.Directory]::EnumerateFileSystemEntries などの結果）の先頭から count 件までを配列にして返す。
    # count 件で列挙をやめ、列挙子を必ず Dispose する（testAnyEntry と同じ理由。Select-Object -First で途中でやめる形にしない）
    param (
        [System.Collections.IEnumerable]$entries,
        [int]$count
    )

    $list = New-Object System.Collections.Generic.List[object]
    $enumerator = $entries.GetEnumerator()
    try {
        while ($list.Count -lt $count -and $enumerator.MoveNext()) {
            $list.Add($enumerator.Current)
        }
    } finally {
        if ($enumerator -is [System.IDisposable]) {
            $enumerator.Dispose()
        }
    }
    return , $list.ToArray()
}

function getFolderKey {
    # フォルダのパスから、名前付きミューテックス・イベントの名前に使う鍵（16 進 64 文字）を作る。大文字と小文字は区別しない。
    # 安全性のためではなく、パスを名前に使える長さと文字にするためのハッシュ。
    # FIPS 準拠の実装（SHA256CryptoServiceProvider）を使う。MD5 や SHA256Managed は、
    # FIPS モードを有効にした Windows では作るときに例外になり、起動できなくなるため
    param (
        [string]$dir
    )

    $sha = New-Object System.Security.Cryptography.SHA256CryptoServiceProvider
    try {
        return [BitConverter]::ToString($sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($dir.ToLowerInvariant()))).Replace("-", "")
    } finally {
        $sha.Dispose()
    }
}

function newAppMutex {
    # 同じツール（配置フォルダ）の処理を二重に動かさないための名前付きミューテックスを作り、@{ Mutex; Acquired } を返す。
    # Acquired が $false なら、ほかで実行中。プロセスが終われば解放されるため、強制終了されても残らない
    #   name: 処理の種類（"gui" = 画面、"indexer" = インデックス作成）
    param (
        [string]$name,
        [string]$dir = ${rootDir}
    )

    $key = getFolderKey $dir
    $createdNew = $false
    $mutex = New-Object System.Threading.Mutex($true, "Local\${appId}_${name}_${key}", [ref]$createdNew)
    return @{ Mutex = $mutex; Acquired = $createdNew }
}

function getPathErrorKind {
    # File.GetAttributes などが投げた例外（PowerShell から呼ぶと MethodInvocationException に包まれる）を、
    # 見つからない（FileNotFoundException・DirectoryNotFoundException）・接続できない（Win32 のエラー番号）・
    # その他（アクセス拒否・ログオンの失敗など上のどれにも当たらないもの）に分ける。純粋な関数（例外を受け取って値を返すだけ）
    param (
        $exception  # System.Exception（MethodInvocationException でもそのままでもよい）
    )

    $inner = $exception
    while ($inner -is [System.Management.Automation.MethodInvocationException] -and $null -ne $inner.InnerException) {
        $inner = $inner.InnerException
    }
    if ($inner -is [System.IO.FileNotFoundException] -or $inner -is [System.IO.DirectoryNotFoundException]) {
        return ${pathStateMissing}
    }
    $code = $inner.HResult -band 0xFFFF
    if (${unreachableWin32Codes} -contains $code) {
        return ${pathStateUnreachable}
    }
    return ${pathStateOther}
}

function getPathState {
    # パスの状態を、例外を投げる呼び出し（File.GetAttributes）で調べる。260 文字を超えるパスも扱えるよう \\?\ を付けて渡す。
    # 返すもの: @{ State（上の定数）; IsDirectory; Message（見つかったとき以外の例外の文面） }
    param (
        [string]$path
    )

    try {
        $attributes = [System.IO.File]::GetAttributes((toLongPath $path))
        return @{ State = ${pathStateFound}; IsDirectory = [bool]($attributes -band [System.IO.FileAttributes]::Directory); Message = "" }
    } catch {
        return @{ State = (getPathErrorKind $_.Exception); IsDirectory = $false; Message = $_.Exception.Message }
    }
}

function invokeWithNamedMutex {
    # 名前付きミューテックスを取って action を実行し、action の出力を返す（終わったら必ず手放す）。
    # 同じスレッドの入れ子は通す（ミューテックスは同じスレッドなら再び取れる）。
    # timeoutMilliseconds を過ぎても取れなければ、「排他の待ちが時間切れになりました」の例外にする。
    # 前の持ち主が手放さずに終わっていた（abandoned）ときは、取れたものとして続ける
    #   mutexName: ミューテックスの名前（呼ぶ側が決める。同じ名前どうしで排他する）。
    #   action から呼び出し元の変数を参照できるよう、この関数の変数の名前は目立つものにしてある（name・key・path などは使わない）
    param (
        [string]$mutexName,
        [int]$timeoutMilliseconds,
        [scriptblock]$action
    )

    $mutex = New-Object System.Threading.Mutex($false, $mutexName)
    try {
        $acquired = $false
        try {
            $acquired = $mutex.WaitOne($timeoutMilliseconds)
        } catch {
            # PowerShell では MethodInvocationException に包まれて届く。abandoned でも所有は移っている
            $inner = $_.Exception
            while ($null -ne $inner -and $inner -isnot [System.Threading.AbandonedMutexException]) {
                $inner = $inner.InnerException
            }
            if ($null -eq $inner) {
                throw
            }
            $acquired = $true
        }
        if (!$acquired) {
            throw "排他の待ちが時間切れになりました（${timeoutMilliseconds} ミリ秒。${mutexName}）。ほかの処理が終わってからやり直してください。"
        }
        try {
            & $action
        } finally {
            $mutex.ReleaseMutex()
        }
    } finally {
        $mutex.Dispose()
    }
}

# スレッドのプール（WorkerPool）。ランスペースと PowerShell のインスタンスを使い回し、仕事のたびに作って捨てない。
# 設計は docs/design/structure/threads.md「寿命」、docs/design/structure/classes.md「クラスと関数の使い分け」。
#
# WorkerPool は、作ったランスペースのスレッドだけから呼ぶ（PowerShell 5.1 のクラスのメソッドは、クラスを定義したランスペースで動くため）。
# 仕事のスクリプトは文字列で渡す（スクリプトブロックのまま渡すと、作ったランスペースに結び付いたまま別のスレッドで動いてしまう）。

function newWorkerState {
    # プールの各スレッドに読み込む関数・値だけを入れた InitialSessionState を作る
    # （lib.ps1 全体を読み込むと、スレッドを用意するだけで時間がかかるため）
    param (
        [string[]]$functions = @(),
        [string[]]$variables = @()
    )

    $state = [System.Management.Automation.Runspaces.InitialSessionState]::CreateDefault2()
    foreach ($name in $functions) {
        $state.Commands.Add([System.Management.Automation.Runspaces.SessionStateFunctionEntry]::new($name, (Get-Command $name -CommandType Function).Definition))
    }
    foreach ($name in $variables) {
        $state.Variables.Add([System.Management.Automation.Runspaces.SessionStateVariableEntry]::new($name, (Get-Variable $name -ValueOnly), ""))
    }
    return $state
}

function joinWorkerScript {
    # 部品の読み込み（Prelude）を、本体のスクリプト（script）につなぐ。呼び出し側の書き換えをせず、
    # 意味を変えない形でつなぐため、挿入する場所は本体の構文解析で決める:
    #   param ブロックがあればその直後、続けて最初の文が `$ErrorActionPreference = "Stop"` ならそのあとにも進める
    #   （部品が読めないときにスレッドを終える今の動きを保つため。tests/shared/core/worker_pool.Tests.ps1 が確かめる）。
    # Prelude は、同じランスペースで仕事のたびに呼ばれても 1 回だけ実行する（$global:workerPreludeDone で守る。
    # ランスペースを使い回さない呼び出し元でも害はない）
    param (
        [string]$prelude,
        [string]$script
    )

    $tokens = $null
    $errors = $null
    $ast = [System.Management.Automation.Language.Parser]::ParseInput($script, [ref]$tokens, [ref]$errors)
    if ($errors.Count -gt 0) {
        throw "joinWorkerScript: つなぐ本体の構文エラーです: $($errors[0].Message)"
    }
    $insertAt = if ($ast.ParamBlock) { $ast.ParamBlock.Extent.EndOffset } else { 0 }
    $statements = @($ast.EndBlock.Statements)
    if ($statements.Count -gt 0 -and $statements[0].Extent.Text -match '^\$ErrorActionPreference\s*=\s*"Stop"$') {
        $insertAt = $statements[0].Extent.EndOffset
    }
    $head = $script.Substring(0, $insertAt)
    $tail = $script.Substring($insertAt)
    $guarded = "`r`nif (!`$global:workerPreludeDone) {`r`n$prelude`r`n`$global:workerPreludeDone = `$true`r`n}"
    return "$head$guarded$tail"
}

function getWorkerCount {
    # プールのスレッドの数の既定（画面のために 1 コアを残す。1～max）
    param (
        [int]$max = 4,
        [int]$processors = [Environment]::ProcessorCount
    )

    return [Math]::Max(1, [Math]::Min($processors - 1, $max))
}

class WorkerPool {
    # スレッドの数
    [int]$Size
    # 各スレッドの優先度（Normal・BelowNormal など）。仕事を始めるたびに、そのスレッドに設定する
    [string]$Priority
    # 各スレッドで、最初の仕事の前に 1 回だけ実行するスクリプト（lib.ps1 の読み込みなど）。ランスペースの全体（global）で実行する
    [string]$Prelude = ""
    hidden [System.Management.Automation.Runspaces.RunspacePool]$Pool
    # 使い終わって空いている PowerShell のインスタンス
    hidden [System.Collections.Generic.Stack[powershell]]$Idle

    WorkerPool([int]$size, [System.Management.Automation.Runspaces.InitialSessionState]$state, [System.Management.Automation.Host.PSHost]$hostUi, [string]$priority) {
        $this.Size = [Math]::Max(1, $size)
        $this.Priority = [string][System.Threading.ThreadPriority]$priority
        $this.Idle = New-Object 'System.Collections.Generic.Stack[powershell]'
        # host は省けない（$null は受け付けない）。渡されなければ、このランスペースのものを使う
        if ($null -eq $hostUi) {
            $hostUi = Get-Host
        }
        $this.Pool = [runspacefactory]::CreateRunspacePool(1, $this.Size, $state, $hostUi)
        # 既定では仕事のたびに新しいスレッドを作る。ランスペースごとに 1 つのスレッドを使い続ける
        $this.Pool.ThreadOptions = [System.Management.Automation.Runspaces.PSThreadOptions]::ReuseThread
        $this.Pool.Open()
    }

    [hashtable] Submit([string]$script, [object[]]$arguments) {
        # 仕事を 1 つ始め、@{ PowerShell; Handle } を返す（Receive・Cancel に渡す）
        if ($null -eq $this.Pool) {
            throw "WorkerPool は閉じています。"
        }
        if ($this.Idle.Count -gt 0) {
            $ps = $this.Idle.Pop()
        } else {
            $ps = [powershell]::Create()
            $ps.RunspacePool = $this.Pool
        }
        # 優先度を設定してから仕事のスクリプトを呼ぶ（AddStatement で文を分けると、引数付きのスクリプトが終わらなくなるため、1 つのスクリプトにする）
        $text = "[System.Threading.Thread]::CurrentThread.Priority = '$($this.Priority)'`r`n"
        $body = "& {`r`n$script`r`n} @args"
        if ($this.Prelude) {
            # if の中は新しいスコープにならないため、prelude で読み込んだ関数はランスペースに残り、次の仕事でも使える
            $body = joinWorkerScript $this.Prelude $body
        }
        [void]$ps.AddScript("$text$body")
        foreach ($argument in $arguments) {
            [void]$ps.AddArgument($argument)
        }
        return @{ PowerShell = $ps; Handle = $ps.BeginInvoke() }
    }

    [object] Receive([hashtable]$job) {
        # 仕事の終わりを待って出力を返す。PowerShell のインスタンスは次の仕事に使い回す。仕事の例外はそのまま投げる
        $ps = $job.PowerShell
        try {
            $output = $ps.EndInvoke($job.Handle)
        } catch {
            $ps.Dispose()
            throw
        }
        $ps.Commands.Clear()
        $ps.Streams.ClearStreams()
        $this.Idle.Push($ps)
        # クラスのメソッドは戻り値を展開しない（PSDataCollection のまま返る）
        return $output
    }

    [void] Cancel([hashtable]$job) {
        # 仕事を止めて捨てる（止めたインスタンスは使い回さない）
        try {
            $job.PowerShell.Stop()
        } catch {
        }
        $job.PowerShell.Dispose()
    }

    [void] Close() {
        # スレッドを止めて片づける。何度呼んでもよい
        while ($this.Idle.Count -gt 0) {
            $this.Idle.Pop().Dispose()
        }
        if ($this.Pool) {
            $this.Pool.Dispose()
            $this.Pool = $null
        }
    }
}

class BackgroundQueue {
    # 画面から頼まれる短い仕事（プレビューの読み込み・状態の読み直し・プロセスの一覧など）を、使い回すスレッドで実行する。
    # 各スレッドでは、最初の仕事の前に 1 回だけ prelude（lib.ps1 の読み込みなど）を実行する（仕事のたびに読み込まない）。
    # 終わった仕事は Poll（画面のタイマー）で受け取り、画面のスレッドで onDone { param($output, $errorText) } を呼ぶ。
    # 画面のスレッドだけから呼ぶ
    hidden [WorkerPool]$Pool
    hidden [System.Collections.Generic.List[hashtable]]$Jobs

    BackgroundQueue([int]$size, [hashtable]$load, [System.Management.Automation.Host.PSHost]$hostUi) {
        # load は部品の読み込み口が返す @{ State; Prelude }。呼び出し元が Prelude に続けて
        # 呼びたい文を足したいときは、渡す前に $load.Prelude を書き換える
        $this.Jobs = New-Object 'System.Collections.Generic.List[hashtable]'
        $this.Pool = [WorkerPool]::new($size, $load.State, $hostUi, "Normal")
        $this.Pool.Prelude = $load.Prelude
    }

    [void] Post([string]$script, [object[]]$arguments, [scriptblock]$onDone) {
        # 仕事を 1 つ始める（スレッドが空いていなければ、空くのを待ってから始まる）
        $job = $this.Pool.Submit($script, $arguments)
        $job.OnDone = $onDone
        $this.Jobs.Add($job)
    }

    [int] Poll() {
        # 終わった仕事の onDone を呼び、まだ終わっていない仕事の数を返す
        foreach ($job in $this.Jobs.ToArray()) {
            if (!$job.Handle.IsCompleted) {
                continue
            }
            [void]$this.Jobs.Remove($job)
            $output = $null
            $errorText = $null
            try {
                if ($job.PowerShell.Streams.Error.Count -gt 0) {
                    $errorText = $job.PowerShell.Streams.Error[0].ToString()
                }
                $output = $this.Pool.Receive($job)
            } catch {
                # EndInvoke の呼び出しの例外に包まれているため、仕事が投げた元の例外の文面にする
                $exception = $_.Exception
                while ($exception.InnerException) {
                    $exception = $exception.InnerException
                }
                $errorText = $exception.Message
            }
            if ($job.OnDone) {
                & $job.OnDone $output $errorText
            }
        }
        return $this.Jobs.Count
    }

    [void] Close() {
        # 終わっていない仕事を止め、スレッドを片づける。何度呼んでもよい
        foreach ($job in $this.Jobs.ToArray()) {
            $this.Pool.Cancel($job)
        }
        $this.Jobs.Clear()
        $this.Pool.Close()
    }

    [void] Abandon() {
        # 画面を閉じるときだけに使う。Close と違い、止まった仕事（OS の呼び出しで戻らない届かない共有など）を待たずに戻る。
        # 終わった仕事は Close と同じく片づける（待たされないため）。終わっていない仕事には止める依頼（BeginStop）だけを出し、
        # その PowerShell のインスタンスと、この列のプール（RunspacePool）は Dispose しない
        # （PowerShell.Dispose() は動いている間は中で Stop を呼んで待ち、RunspacePool.Dispose() も止まったランスペースを待つため）。
        # 後始末はプロセスの終わりに任せる
        foreach ($job in $this.Jobs.ToArray()) {
            if ($job.Handle.IsCompleted) {
                try {
                    [void]$this.Pool.Receive($job)
                } catch {
                }
            } else {
                try {
                    [void]$job.PowerShell.BeginStop($null, $null)
                } catch {
                }
            }
        }
        $this.Jobs.Clear()
    }
}
# データ（設定ファイル）の置き場所の既定（どのツールからも使う）。
# ツールのフォルダに書き込めればそこに置く。書き込めないとき（Program Files・読み取り専用の共有フォルダに置いたとき）は、
# ツールが渡した逃げ先に置く（逃げ先はツールが決める。tebunko は既定のワークスペース）。
# work の置き場所は、ツールの側で決める（tebunko は設定の workspaceFolder）。

function testWritableFolder {
    # フォルダにファイルを作れるか。試しに作ったファイルは閉じると消える（DeleteOnClose）。フォルダが無ければ $false
    param (
        [string]$dir
    )

    if ([string]::IsNullOrWhiteSpace($dir) -or -not [System.IO.Directory]::Exists($dir)) {
        return $false
    }
    $probe = Join-Path $dir (".tebunko_write_test_" + [guid]::NewGuid().ToString("N") + ".tmp")
    try {
        $stream = New-Object System.IO.FileStream($probe, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write,
            [System.IO.FileShare]::None, 1, [System.IO.FileOptions]::DeleteOnClose)
        $stream.Dispose()
        return $true
    } catch {
        return $false
    }
}

function getDataDir {
    # 設定ファイルを置くフォルダを返す。ツールのフォルダに書き込めればそれ、書き込めなければ渡された逃げ先。
    # 逃げ先の既定値は持たない（shared はツールの既定の置き場所を知らない）
    param (
        [string]$root = ${rootDir},
        [Parameter(Mandatory = $true)]
        [string]$fallbackDir
    )

    if (testWritableFolder $root) {
        return $root
    }
    return $fallbackDir
}

# TSV とセルの文字列を扱う（判断層。ファイルに触らない）。

# インデックスのTSVで、セル内改行の代わりに使う文字（U+2028 LINE SEPARATOR）。
# TSVの1行 = Excelの1行を保つため、セル内改行はこの文字に置き換えて保存し、検索結果の出力時に改行へ戻す
${cellNewLine} = [string][char]0x2028

function replaceCellNewLine {
    # ダブルクォートで囲まれた1セル内の改行（LF・CR・CRLF）を、セル内改行を表す文字に置き換える
    param (
        [string]$inputString
    )

    # "" はクォート内のダブルクォートのエスケープだが、"…" "…" の2つに分けてマッチしても結果は同じ
    return [regex]::Replace($inputString, '"[^"]*"', { param($m) $m.Value -replace "\r\n|\r|\n", ${cellNewLine} })
}

function formatTsv {
    # Excelが出力したTSVを、1行目 = Excelの1行目、1列目 = A列 となるように整形する。
    # Excelは使用範囲（UsedRange）の左上のセルから出力するため、その行・列番号を firstRow・firstColumn に渡す。
    # セル内改行は置き換え、行末の空セルと末尾の空行は取り除く（途中の空行は行番号を保つため残す）。
    # 空白以外の文字が無ければ空文字を返す
    param (
        [string]$content,
        [int]$firstRow = 1,
        [int]$firstColumn = 1
    )

    $content = replaceCellNewLine $content
    $columnPadding = "`t" * ($firstColumn - 1)

    $lines = New-Object System.Collections.Generic.List[string]
    for ($i = 1; $i -lt $firstRow; $i++) {
        $lines.Add("")
    }
    foreach ($line in ($content -split "\r?\n")) {
        $lines.Add(($columnPadding + $line).TrimEnd("`t"))
    }
    while ($lines.Count -gt 0 -and $lines[$lines.Count - 1].Trim() -eq "") {
        $lines.RemoveAt($lines.Count - 1)
    }

    return ($lines -join "`r`n")
}

function countTsvFields {
    # TSVの1行をExcelに貼り付けたときのセル数を返す。
    # Excelと同じく、" で始まるセルは閉じる " までを1セルとする（中のタブ・改行は区切りとしない）
    param (
        [string]$line
    )

    # 先頭にタブを足し、どのセルも「タブ＋中身」で数える（^ を使うと、先頭の空のセルの後のタブを読み飛ばして1セル少なくなる）
    return [regex]::Matches("`t${line}", '\t(?:"(?:[^"]|"")*"[^\t]*|[^\t]*)').Count
}

function toColumnName {
    # 列番号を列名に変換する（1 → A、27 → AA）
    param (
        [int]$number
    )

    $name = ""
    while ($number -gt 0) {
        $number--
        $name = [string][char](65 + ($number % 26)) + $name
        $number = [math]::Floor($number / 26)
    }
    return $name
}


function splitTsvCells {
    # TSVの1行をセルに分ける。" で始まるセルは閉じる " までを1セルとし、囲みの " を外して "" を " に戻す（countTsvFields と同じ区切り方）
    param (
        [string]$line
    )

    $cells = New-Object System.Collections.Generic.List[string]
    foreach ($match in [regex]::Matches("`t${line}", '\t(?:"(?:[^"]|"")*"[^\t]*|[^\t]*)')) {
        $cell = $match.Value.Substring(1)
        if ($cell -match '^"(?<inner>(?:[^"]|"")*)"(?<rest>.*)$') {
            $cell = $Matches.inner.Replace('""', '"') + $Matches.rest
        }
        $cells.Add($cell)
    }
    return , $cells.ToArray()
}

function testTextTrimmed {
    # 文字が枠に入りきらず、省略（…）で切れているか。実際の幅（枠の ActualWidth）より、要る幅（文字を 1 行で出すのに要る幅）が
    # 誤差より大きいときだけ $true。幅 0 以下（まだ配置されていない・隠れている）は切れていないものとして $false。
    # 測る側（画面層）は幅を渡すだけで、切れているかの判定はここで決める
    param (
        [double]$actualWidth,
        [double]$requiredWidth,
        [double]$tolerance = 0.5   # 測り方による小数の誤差（これ以下の超過は切れていないとみなす）
    )

    if ($actualWidth -le 0) {
        return $false
    }
    return (($requiredWidth - $actualWidth) -gt $tolerance)
}

# テキストファイル（.txt など）の対象の拡張子・文字コードの判定・読み込み。
# 文字コードの判定（バイト列 → 文字コードまたはバイナリ）は、画面にもファイルにも触らない判断層の関数にする。
# ファイルを開いて読む関数（readTextFile）だけが状態層（ファイルに触る）。

# 既定のアプリで開く、取り込み対象のテキストファイルの拡張子（小文字）。
# 足す・減らすと tests\meta\safety.Tests.ps1 が固定の一覧で確かめる
${textOpenExtensions} = @(
    ".txt", ".csv", ".tsv", ".md", ".log", ".json", ".xml",
    ".c", ".h", ".cpp", ".cc", ".cxx", ".hpp", ".cs", ".java", ".kt", ".kts",
    ".go", ".rs", ".swift", ".scala", ".dart", ".vb", ".bas", ".pas", ".asm",
    ".m", ".r", ".jl", ".hs", ".ex", ".exs", ".erl", ".clj", ".groovy", ".lua",
    ".py", ".rb", ".pl", ".php", ".psm1", ".psd1", ".jsx", ".tsx", ".mjs", ".vue",
    ".sql", ".yaml", ".yml", ".toml", ".ini", ".cfg", ".conf", ".properties",
    ".gradle", ".cmake", ".proto", ".graphql", ".tf",
    ".html", ".htm", ".css", ".scss", ".less", ".rst", ".tex", ".diff", ".patch"
)

# 実行・登録が既定の動作になるため、既定のアプリではなくメモ帳で開く、取り込み対象のテキストファイルの拡張子（小文字）。
# ${textOpenExtensions} と合わせて ${textExtensions} になる。足す・減らすと tests\meta\safety.Tests.ps1 が固定の一覧で確かめる
${textNotepadExtensions} = @(".bat", ".cmd", ".ps1", ".vbs", ".js", ".reg", ".sh")

# 取り込み対象にするテキストファイルの拡張子（小文字。上の 2 つを合わせたもの）
${textExtensions} = @(${textOpenExtensions}) + @(${textNotepadExtensions})

# 元のファイルがこの大きさ（バイト）を超えたら、読まずに失敗にする
${textFileMaxBytes} = 10MB

# BOM の無い UTF-16 の判定に使う閾値（docs/design/indexing/text.md）。
#   先頭 ${textUtf16SampleBytes} バイト（偶数バイトに切り詰める）を 2 バイトずつの組として数え、
#   偶数の位置・奇数の位置のどちらかの NUL の割合が ${textUtf16NulRatioThreshold} 以上で、
#   もう片方が「多い側 ÷ ${textUtf16NulSkewDivisor}」以下なら UTF-16 と判定する
${textUtf16SampleBytes}      = 64KB
${textUtf16NulRatioThreshold} = 0.2
${textUtf16NulSkewDivisor}    = 10

# NUL の無い BOM 無し UTF-16（日本語だけの文章）の判定に使う閾値（docs/design/indexing/text.md）。
#   先頭 ${textUtf16SampleBytes} バイトを UTF-16 として読み、ひらがな・カタカナが ${textJpUtf16KanaRatio} 以上あり、
#   日本語の文章に出る文字（ASCII・句読点・かな・漢字・全角）以外が ${textJpUtf16OtherRatio} 以下なら UTF-16 と判定する
${textJpUtf16MinBytes}   = 8
${textJpUtf16KanaRatio}  = 0.2
${textJpUtf16OtherRatio} = 0.05

# 7 ビットだけ（ASCII の範囲）のバイト列は、ひらがなの UTF-16 と ASCII の文字列の見分けが付きにくいため、
# UTF-16 とみなすかなの割合をもっと高く求める
${textJpUtf16AsciiKanaRatio} = 0.9

# Shift_JIS として読めたとき、半角カナが「ASCII 以外の文字」のこの割合を超えると、半角カナの並びとして自然かを確かめる
# （濁点・半濁点が付けられるカナの後にしか来ないか。GBK・Big5 などを Shift_JIS として読むと崩れる）。
# EUC-JP としても読めるときは、この割合を超える側を EUC-JP とする
${textLegacyHalfKanaRatio} = 0.3

# 半角カナの数えは、読んだ結果の先頭からこの文字数だけ見る（大きなファイルで遅くならないため）
${textLegacySampleChars} = 32768

function testTextExtension {
    # ファイル名（またはパス）の拡張子が、取り込み対象のテキストの拡張子か（大文字・小文字を区別しない）
    param (
        [string]$path
    )

    $extension = [System.IO.Path]::GetExtension($path).ToLowerInvariant()
    return (${textExtensions} -contains $extension)
}

function testTextOpenWithNotepad {
    # ファイル名（またはパス）の拡張子が、既定のアプリではなくメモ帳で開くテキストの拡張子か（大文字・小文字を区別しない）。
    # .bat・.ps1・.js など、既定のアプリで開くと実行・登録になる拡張子がこちら
    param (
        [string]$path
    )

    $extension = [System.IO.Path]::GetExtension($path).ToLowerInvariant()
    return (${textNotepadExtensions} -contains $extension)
}

function getStrictUtf8Encoding {
    # 不正なバイト列（UTF-8として読めない並び）で例外にする UTF-8 のデコーダー（BOM は付けない）
    return [System.Text.Encoding]::GetEncoding("utf-8",
        [System.Text.EncoderExceptionFallback]::new(), [System.Text.DecoderExceptionFallback]::new())
}

function testTextPlausible {
    # 読んだ結果の文字列が、テキストとして自然か。制御文字（TAB・LF・FF・CR 以外）・私用領域・置き換え文字（U+FFFD）を含めば偽。
    # バイナリを Shift_JIS・EUC-JP などとして読んでしまったものを見分ける（Shift_JIS の外字（F040～F9FC）は私用領域に読まれるため偽になる）
    param (
        [string]$text
    )

    return (-not [regex]::IsMatch($text, '[\x00-\x08\x0B\x0E-\x1F\x7F-\x9F\uE000-\uF8FF\uFFFD]'))
}

function tryDecodeStrict {
    # コードページで読めないバイト列があれば $null、読めれば文字列
    param (
        [byte[]]$bytes,
        [int]$codePage
    )

    try {
        $encoding = [System.Text.Encoding]::GetEncoding($codePage,
            [System.Text.EncoderExceptionFallback]::new(), [System.Text.DecoderExceptionFallback]::new())
        return $encoding.GetString($bytes)
    } catch [System.Text.DecoderFallbackException] {
        return $null
    } catch [System.ArgumentException] {
        return $null
    }
}

function detectJapaneseUtf16WithoutNul {
    # NUL の無い（または NUL が改行の分しか無い）BOM 無し UTF-16（日本語だけの文章）の判定。
    # ひらがな・カタカナ・漢字は NUL を含まない。LE・BE の片方だけが日本語の文章として自然なときにその文字コードを返す。
    # 両方・どちらも当たらなければ $null。7 ビットだけのバイト列は、かなの割合をもっと高く求める（${textJpUtf16AsciiKanaRatio}）
    param (
        [byte[]]$bytes
    )

    $sampleLength = [Math]::Min($bytes.Length, [int]${textUtf16SampleBytes})
    $sampleLength -= ($sampleLength % 2)
    if ($sampleLength -lt ${textJpUtf16MinBytes}) { return $null }

    $ascii = $true
    for ($i = 0; $i -lt $sampleLength; $i++) {
        if ($bytes[$i] -ge 0x80) { $ascii = $false; break }
    }
    $kanaRatio = if ($ascii) { ${textJpUtf16AsciiKanaRatio} } else { ${textJpUtf16KanaRatio} }

    $found = @()
    foreach ($candidate in @(@("UTF16LE", [System.Text.Encoding]::Unicode), @("UTF16BE", [System.Text.Encoding]::BigEndianUnicode))) {
        $text = $candidate[1].GetString($bytes, 0, $sampleLength)
        $kana = [regex]::Matches($text, '[\u3040-\u30FF]').Count
        $other = [regex]::Matches($text, '[^\u0009\u000A\u000D -~\u3000-\u30FF\u4E00-\u9FFF\uFF00-\uFFEF]').Count
        if ($kana -ge ($text.Length * $kanaRatio) -and $other -le ($text.Length * ${textJpUtf16OtherRatio})) {
            $found += $candidate[0]
        }
    }
    if ($found.Count -eq 1) { return $found[0] }
    return $null
}

function getIso2022JpVerdict {
    # ISO-2022-JP（JIS）かの判定。戻り値: "yes" / "broken" / "none"
    #   yes: 7 ビットだけで、漢字への切り替え（ESC $ B・ESC $ @）を含み、ESC の並びがすべて規格のもの（ESC ( B・ESC ( J・ESC ( I を含む）
    #   broken: 漢字への切り替えを含むが、8 ビットのバイトや規格外の ESC の並びがある（JIS のつもりの壊れたもの。UTF-8 として読むと化けるので取り込まない）
    #   none: ESC が無い、または漢字への切り替えが無い（ESC ( B だけ・ESC [ などの端末の制御の並び）
    param (
        [byte[]]$bytes
    )

    if ([Array]::IndexOf($bytes, [byte]0x1B) -lt 0) { return "none" }
    # 1 バイトを 1 文字に読み（Latin-1）、正規表現で確かめる（バイトを 1 つずつ回さない。色つきのログなど ESC が多いだけのファイルを速く抜ける）
    $latin1 = [System.Text.Encoding]::GetEncoding(28591).GetString($bytes)
    if (-not [regex]::IsMatch($latin1, '\x1B\$[B@]')) { return "none" }
    # 規格外の ESC の並び（末尾で切れたものを含む）か、8 ビットのバイトがあれば、壊れたもの
    $broken = [regex]::IsMatch($latin1, '\x1B(?!\$[B@]|\([BJI])') -or [regex]::IsMatch($latin1, '[\x80-\xFF]')
    if ($broken) { return "broken" }
    return "yes"
}

function testHalfWidthKanaNatural {
    # 半角カナを多く含む文字列が、半角カナの並びとして自然か。濁点（ﾞ）・半濁点（ﾟ）は、付けられるカナ
    # （ｦ ｳ ｶ～ﾄ ﾊ～ﾎ ﾜ。半濁点は ﾊ～ﾎ）の直後にしか来ない。GBK・Big5 などを Shift_JIS として読むと崩れる
    param (
        [string]$text
    )

    if ([regex]::IsMatch($text, '(?<![\uFF66\uFF73\uFF76-\uFF84\uFF8A-\uFF8E\uFF9C])\uFF9E')) { return $false }
    if ([regex]::IsMatch($text, '(?<![\uFF8A-\uFF8E])\uFF9F')) { return $false }
    return $true
}

function detectLegacyJapaneseEncoding {
    # UTF-8 として読めなかった NUL の無いバイト列が、Shift_JIS か EUC-JP か。決められなければ $null（取り込まない）。
    #   Shift_JIS: コードページ 932 として不正なバイト列が無く、制御文字などが出ない。半角カナが多い（${textLegacyHalfKanaRatio} 超）ときは、
    #              半角カナの並びとして自然（testHalfWidthKanaNatural）なものだけ
    #   EUC-JP: コードページ 51932 として不正なバイト列が無く、制御文字などが出ず、ひらがな・カタカナを含む
    #           （かなの無い漢字だけの文章は、GBK・EUC-KR と構造が同じで見分けが付かない）
    #   両方に当たるときは、Shift_JIS として読むと半角カナばかりになる（EUC-JP のかなの見え方）なら EUC-JP、そうでなければあいまいなので $null
    param (
        [byte[]]$bytes
    )

    $sjis = tryDecodeStrict $bytes 932
    $sjisOk = $false
    $sjisHalfKanaHeavy = $false
    if ($null -ne $sjis -and (testTextPlausible $sjis)) {
        # 半角カナの数えは、最初の ASCII 以外の文字から一定の長さだけ（先頭が長い ASCII だけの行でも判定が変わらないように）
        $first = [regex]::Match($sjis, '[^\u0000-\u007F]').Index
        $sample = if ($sjis.Length - $first -gt ${textLegacySampleChars}) { $sjis.Substring($first, [int]${textLegacySampleChars}) } else { $sjis.Substring($first) }
        $nonAscii = [regex]::Matches($sample, '[^\u0000-\u007F]').Count
        $halfKana = [regex]::Matches($sample, '[\uFF61-\uFF9F]').Count
        $sjisHalfKanaHeavy = ($halfKana -gt ($nonAscii * ${textLegacyHalfKanaRatio}))
        $sjisOk = (-not $sjisHalfKanaHeavy) -or (testHalfWidthKanaNatural $sjis)
    }

    $euc = tryDecodeStrict $bytes 51932
    $eucOk = ($null -ne $euc -and (testTextPlausible $euc) -and [regex]::IsMatch($euc, '[\u3040-\u30FF]'))

    if ($sjisOk -and -not $eucOk) { return "ShiftJIS" }
    if ($eucOk -and -not $sjisOk) { return "EUCJP" }
    if ($eucOk -and $sjisOk -and $sjisHalfKanaHeavy) { return "EUCJP" }
    return $null
}

function detectTextEncoding {
    # バイト列だけから文字コードを判定する（ファイルに触らない）。
    # 順に確かめる: BOM → NUL の偏り（BOM の無い UTF-16）→ NUL の無い日本語の UTF-16 → NUL を含むか（バイナリ） →
    #   ISO-2022-JP → UTF-8 として正しく読めるか → Shift_JIS・EUC-JP。判定できないもの（バイナリ・UTF-32・GBK など）は $null を返す
    #   戻り値: "UTF8" / "UTF16LE" / "UTF16BE" / "ShiftJIS" / "EUCJP" / "ISO2022JP" / $null（取り込まない）
    param (
        [byte[]]$bytes
    )

    if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF) {
        return "UTF8"
    }
    # UTF-32 の BOM は UTF-16LE の BOM（FF FE）と同じ並びで始まるため、先に確かめて取り込まない
    if ($bytes.Length -ge 4 -and (
            ($bytes[0] -eq 0xFF -and $bytes[1] -eq 0xFE -and $bytes[2] -eq 0 -and $bytes[3] -eq 0) -or
            ($bytes[0] -eq 0 -and $bytes[1] -eq 0 -and $bytes[2] -eq 0xFE -and $bytes[3] -eq 0xFF))) {
        return $null
    }
    if ($bytes.Length -ge 2 -and $bytes[0] -eq 0xFF -and $bytes[1] -eq 0xFE) {
        return "UTF16LE"
    }
    if ($bytes.Length -ge 2 -and $bytes[0] -eq 0xFE -and $bytes[1] -eq 0xFF) {
        return "UTF16BE"
    }

    $sampleLength = [Math]::Min($bytes.Length, [int]${textUtf16SampleBytes})
    $sampleLength -= ($sampleLength % 2)
    if ($sampleLength -gt 0) {
        $even = 0  # 偶数の位置（0, 2, …）の NUL の数
        $odd = 0   # 奇数の位置（1, 3, …）の NUL の数
        for ($i = 0; $i -lt $sampleLength; $i++) {
            if ($bytes[$i] -eq 0) {
                if (($i % 2) -eq 0) { $even++ } else { $odd++ }
            }
        }
        $n = $sampleLength / 2
        if ($odd -ge ($n * ${textUtf16NulRatioThreshold}) -and $even -le ($odd / ${textUtf16NulSkewDivisor})) {
            return "UTF16LE"
        }
        if ($even -ge ($n * ${textUtf16NulRatioThreshold}) -and $odd -le ($even / ${textUtf16NulSkewDivisor})) {
            return "UTF16BE"
        }
        if ($even -gt 0 -or $odd -gt 0) {
            # NUL が 20% に届かない。改行（CRLF）や全角スペース・「一」など下位バイトが 00 の文字だけが NUL の
            # 日本語の UTF-16 かを確かめる（偶数・奇数の両側に NUL があってよい）。それ以外はバイナリ（UTF-32 もここ）
            return (detectJapaneseUtf16WithoutNul $bytes)
        }
    }

    $utf16 = detectJapaneseUtf16WithoutNul $bytes
    if ($null -ne $utf16) { return $utf16 }

    # ここまでで BOM の無い UTF-16 とは判定できなかった。NUL（0x00）をファイル全体のどこかに含むものはバイナリとみなす
    if ([Array]::IndexOf($bytes, [byte]0) -ge 0) { return $null }

    $iso = getIso2022JpVerdict $bytes
    if ($iso -eq "yes") { return "ISO2022JP" }
    if ($iso -eq "broken") { return $null }

    if ($null -ne (tryDecodeStrict $bytes 65001)) {
        return "UTF8"
    }
    return (detectLegacyJapaneseEncoding $bytes)
}

function decodeTextBytes {
    # detectTextEncoding が返した文字コードで、バイト列を文字列にする（BOM は取り除く）
    param (
        [byte[]]$bytes,
        [string]$encodingName
    )

    switch ($encodingName) {
        "UTF8" {
            $offset = if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF) { 3 } else { 0 }
            return (getStrictUtf8Encoding).GetString($bytes, $offset, $bytes.Length - $offset)
        }
        "UTF16LE" {
            $offset = if ($bytes.Length -ge 2 -and $bytes[0] -eq 0xFF -and $bytes[1] -eq 0xFE) { 2 } else { 0 }
            return [System.Text.Encoding]::Unicode.GetString($bytes, $offset, $bytes.Length - $offset)
        }
        "UTF16BE" {
            $offset = if ($bytes.Length -ge 2 -and $bytes[0] -eq 0xFE -and $bytes[1] -eq 0xFF) { 2 } else { 0 }
            return [System.Text.Encoding]::BigEndianUnicode.GetString($bytes, $offset, $bytes.Length - $offset)
        }
        "ShiftJIS" {
            return [System.Text.Encoding]::GetEncoding(932).GetString($bytes)
        }
        "EUCJP" {
            return [System.Text.Encoding]::GetEncoding(51932).GetString($bytes)
        }
        "ISO2022JP" {
            return [System.Text.Encoding]::GetEncoding(50221).GetString($bytes)
        }
    }
    throw "不明な文字コードです（${encodingName}）。"
}

function splitTextLines {
    # 文字列を行に分ける（CRLF・LF・CR のどれでも1行。StreamReader.ReadLine と同じ分け方）。
    # 途中の空の行は残し、行末の空白は取り除き（TrimEnd）、末尾の空の行は捨てる
    param (
        [string]$text
    )

    $lines = New-Object System.Collections.Generic.List[string]
    $reader = New-Object System.IO.StringReader($text)
    try {
        $line = $reader.ReadLine()
        while ($null -ne $line) {
            $lines.Add($line.TrimEnd())
            $line = $reader.ReadLine()
        }
    } finally {
        $reader.Dispose()
    }
    while ($lines.Count -gt 0 -and $lines[$lines.Count - 1] -eq "") {
        $lines.RemoveAt($lines.Count - 1)
    }
    return , $lines.ToArray()
}

function readTextFile {
    # テキストファイルを読み、行の並び（splitTextLines と同じ形）にして返す。
    # 元のファイルは読み取りだけで開く（共有は copyFileShared と同じ ReadWrite|Delete）。インデックス作成は、作業領域のコピーをこれで読む。
    # 大きさの上限を超える・バイナリと判定したときは、取り込み一覧・ログにそのまま出す文言で例外にする。
    # maxBytes はテストで上限を小さく差し替えるための引数（既定は textFileMaxBytes）
    param (
        [string]$path,
        [long]$maxBytes = ${textFileMaxBytes}
    )

    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $stream = [System.IO.FileStream]::new((toLongPath $path), [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    try {
        if ($stream.Length -gt $maxBytes) {
            throw "ファイルサイズが大きすぎるため更新できません。"
        }
        $bytes = New-Object byte[] ([int]$stream.Length)
        $read = 0
        while ($read -lt $bytes.Length) {
            $n = $stream.Read($bytes, $read, $bytes.Length - $read)
            if ($n -eq 0) { break }
            $read += $n
        }
    } finally {
        $stream.Dispose()
    }

    $encodingName = detectTextEncoding $bytes
    if ($null -eq $encodingName) {
        throw "テキストファイルではないため更新できません。"
    }
    return (splitTextLines (decodeTextBytes $bytes $encodingName))
}

# PDF の暗号化（標準のセキュリティハンドラー）を、空の利用者パスワードで復号する部品。PowerShell だけで書く（外の部品・Office を使わない）。
# 画面にもファイルにも触らない。pdf_file.ps1 の readPdfPages が、ストリームを取り出すときに使う。
#   読む    : AES-256（V5・R5・R6）。開くのに利用者パスワードが要らない（空のパスワードで鍵が作れて、/U の検証用のハッシュと合う）PDF だけ。
#   読まない: パスワードが要る PDF、AES-256 以外（RC4 40・128 ビット、AES-128 など。鍵の計算に MD5 が要り、FIPS 準拠を強制した機械で使えないため、
#             自前でも書かない。パスワードが要るかどうかも判定せず、必ず「方式に対応していない」にする）。例外にする（そのファイルだけ失敗）。
# 復号するのはストリームだけ（内容・フォントの対応表・オブジェクトのストリーム）。文字列は、読む内容がストリームの中にあるため復号しない。
# 使うのは SHA-2 と AES だけで、FIPS でも使える *CryptoServiceProvider の型を使う（SHA256Managed・AesManaged は FIPS で例外になる）。
# 鍵・途中の値は、例外の文にも記録にも出さない。壊れた辞書は、決まった長さの確かめと、R6 の繰り返しの上限（300 回。仕様では最大でも 288 回で終わる）で止める。
# 例外の文言は「PDF」で始める（readPdfPages は、それ以外の例外を「壊れている」に言い換える）。

# R6 の鍵の計算の繰り返しの上限（仕様では最後のバイトで終わる。最大でも 64 + 224 = 288 回で必ず終わる）
${pdfCryptR6MaxRounds} = 300

# 対応していない方式の例外の文
${pdfCryptUnsupported} = "PDFの暗号化の方式に対応していないため読めません。"

function joinPdfCryptBytes {
    # バイト列を順につなげる
    param (
        [object[]]$parts
    )

    $ms = [System.IO.MemoryStream]::new()
    foreach ($part in $parts) {
        if ($null -eq $part) { continue }
        $bytes = [byte[]]$part
        $ms.Write($bytes, 0, $bytes.Length)
    }
    return , $ms.ToArray()
}

function getPdfSha {
    # SHA-256・384・512
    param (
        [int]$bits,
        [byte[]]$data
    )

    if ($bits -eq 256) { $hash = New-Object System.Security.Cryptography.SHA256CryptoServiceProvider }
    elseif ($bits -eq 384) { $hash = New-Object System.Security.Cryptography.SHA384CryptoServiceProvider }
    else { $hash = New-Object System.Security.Cryptography.SHA512CryptoServiceProvider }
    try {
        return , $hash.ComputeHash($data)
    } finally {
        $hash.Dispose()
    }
}

function invokePdfAesCbc {
    # AES-CBC（詰め物なし。data は 16 の倍数）
    param (
        [byte[]]$key,
        [byte[]]$iv,
        [byte[]]$data,
        [bool]$encrypt
    )

    $aes = New-Object System.Security.Cryptography.AesCryptoServiceProvider
    try {
        $aes.Mode = [System.Security.Cryptography.CipherMode]::CBC
        $aes.Padding = [System.Security.Cryptography.PaddingMode]::None
        $aes.Key = $key
        $aes.IV = $iv
        if ($encrypt) { $transform = $aes.CreateEncryptor() } else { $transform = $aes.CreateDecryptor() }
        try {
            return , $transform.TransformFinalBlock($data, 0, $data.Length)
        } finally {
            $transform.Dispose()
        }
    } finally {
        $aes.Dispose()
    }
}

function getPdfCryptHashR56 {
    # R5・R6 の利用者パスワードのハッシュ（PDF 2.0 の Algorithm 2.B。R5 は SHA-256 の 1 回だけ）。32 バイトを返す
    param (
        [int]$revision,
        [byte[]]$passBytes,
        [byte[]]$salt,
        [byte[]]$userData
    )

    $k = getPdfSha 256 (joinPdfCryptBytes @($passBytes, $salt, $userData))
    if ($revision -lt 6) { return , $k }
    $round = 0
    do {
        $unit = joinPdfCryptBytes @($passBytes, $k, $userData)
        $repeated = New-Object byte[] ($unit.Length * 64)
        for ($j = 0; $j -lt 64; $j++) {
            [Array]::Copy($unit, 0, $repeated, $j * $unit.Length, $unit.Length)
        }
        $aesKey = New-Object byte[] 16
        $aesIv = New-Object byte[] 16
        [Array]::Copy($k, 0, $aesKey, 0, 16)
        [Array]::Copy($k, 16, $aesIv, 0, 16)
        $e = invokePdfAesCbc $aesKey $aesIv $repeated $true
        # 先頭 16 バイトを 1 つの大きな数とみなして 3 で割った余り（256 を 3 で割ると 1 余るので、バイトの和の余りと同じ）
        $sum = 0
        for ($j = 0; $j -lt 16; $j++) { $sum += $e[$j] }
        $k = getPdfSha (256 + 128 * ($sum % 3)) $e
        $round++
    } while (($round -lt 64 -or $e[$e.Length - 1] -gt $round - 32) -and $round -lt ${pdfCryptR6MaxRounds})
    $result = New-Object byte[] 32
    [Array]::Copy($k, 0, $result, 0, 32)
    return , $result
}

function getPdfStringBytes {
    # PDF の文字列（@{PdfType="str"}）をバイト列にする。文字列でなければ $null
    param (
        $value
    )

    if ($value -is [hashtable] -and $value.ContainsKey("PdfType") -and $value["PdfType"] -eq "str") {
        return , (${pdfLatin1}.GetBytes([string]$value["V"]))
    }
    return $null
}

function getPdfSlice {
    # バイト列の一部を新しい配列に写す
    param (
        [byte[]]$bytes,
        [int]$offset,
        [int]$length
    )

    $out = New-Object byte[] $length
    [Array]::Copy($bytes, $offset, $out, 0, $length)
    return , $out
}

function getPdfKeyR56 {
    # R5・R6 のファイルの鍵を、空の利用者パスワードで作る。/U の検証用のハッシュと合わなければ「パスワードが必要」の例外。
    # userBytes は /U（48 バイト以上）、userExtra は /UE（32 バイト以上）
    param (
        [int]$revision,
        [byte[]]$userBytes,
        [byte[]]$userExtra
    )

    $empty = New-Object byte[] 0
    $check = getPdfCryptHashR56 $revision $empty (getPdfSlice $userBytes 32 8) $empty
    $same = $true
    for ($i = 0; $i -lt 32; $i++) { if ($check[$i] -ne $userBytes[$i]) { $same = $false } }
    if (-not $same) { throw "PDFにパスワードが必要なため読めません。" }
    $intermediate = getPdfCryptHashR56 $revision $empty (getPdfSlice $userBytes 40 8) $empty
    return , (invokePdfAesCbc $intermediate (New-Object byte[] 16) (getPdfSlice $userExtra 0 32) $false)
}

function getPdfCryptMethod {
    # 暗号化フィルター（CF の項目）の方式を返す。AES-256（/AESV3）は AESV3、/None と /Identity は復号しない（None）。
    # それ以外は、対応しない方式として例外にする
    param (
        [hashtable]$doc,
        $cf,
        [string]$name
    )

    if ($name -ceq "/Identity") { return "None" }
    if (-not (testPdfDict $cf) -or $name.Length -lt 2) {
        throw ${pdfCryptUnsupported}
    }
    $filter = resolvePdf $doc $cf[$name.Substring(1)]
    if (-not (testPdfDict $filter)) {
        throw ${pdfCryptUnsupported}
    }
    $cfm = resolvePdf $doc $filter["CFM"]
    if ($cfm -ceq "/None") { return "None" }
    if ($cfm -ceq "/AESV3") { return "AESV3" }
    throw ${pdfCryptUnsupported}
}

function newPdfCrypt {
    # Encrypt の辞書（解決済み）から、空の利用者パスワードで鍵を作り、/U と照らして合えば復号の設定を返す。
    # 返す値: @{ Key; StmMethod; Cf }。AES-256（V5・R5・R6）だけを読む。
    # パスワードが要る（空のパスワードが /U と合わない）・対応しない方式・辞書が壊れているときは、そのファイルだけ例外にする
    param (
        [hashtable]$doc,
        [hashtable]$enc
    )

    if ((resolvePdf $doc $enc["Filter"]) -cne "/Standard") { throw ${pdfCryptUnsupported} }
    $v = resolvePdf $doc $enc["V"]
    $r = resolvePdf $doc $enc["R"]
    if ($v -isnot [double] -or $r -isnot [double]) { throw ${pdfCryptUnsupported} }
    if ($v -ne 5.0 -or ($r -ne 5.0 -and $r -ne 6.0)) { throw ${pdfCryptUnsupported} }
    $r = [int]$r

    # 復号の方式（ストリーム）
    $cf = resolvePdf $doc $enc["CF"]
    $stmName = resolvePdf $doc $enc["StmF"]
    if ($null -eq $stmName) { $stmName = "/Identity" }
    if ($stmName -isnot [string]) { throw ${pdfCryptUnsupported} }
    $method = getPdfCryptMethod $doc $cf $stmName

    $userBytes = getPdfStringBytes (resolvePdf $doc $enc["U"])
    $userExtra = getPdfStringBytes (resolvePdf $doc $enc["UE"])
    if ($null -eq $userBytes -or $userBytes.Length -lt 48 -or $null -eq $userExtra -or $userExtra.Length -lt 32) {
        throw "PDFの暗号化の情報が壊れているため読めません。"
    }
    $key = getPdfKeyR56 $r $userBytes $userExtra
    return @{ Key = $key; StmMethod = $method; Cf = $cf }
}

function getPdfStreamCryptMethod {
    # ストリーム 1 つの復号の方式（AESV3・None）を返す。相互参照のストリームは暗号化されない。
    # ストリームごとの /Crypt フィルターがあれば、その名前の方式（/Identity は復号しない）にする
    param (
        [hashtable]$doc,
        [hashtable]$stream
    )

    $crypt = $doc.Crypt
    $dict = $stream.Dict
    if ((resolvePdf $doc $dict["Type"]) -ceq "/XRef") { return "None" }
    $filters = resolvePdf $doc $dict["Filter"]
    if ($null -ne $filters) {
        $filterList = @($filters)
        $paramsList = @(resolvePdf $doc $dict["DecodeParms"])
        for ($i = 0; $i -lt $filterList.Count; $i++) {
            if ((resolvePdf $doc $filterList[$i]) -ceq "/Crypt") {
                $name = "/Identity"
                if ($i -lt $paramsList.Count) {
                    $params = resolvePdf $doc $paramsList[$i]
                    if ((testPdfDict $params) -and $null -ne (resolvePdf $doc $params["Name"])) { $name = resolvePdf $doc $params["Name"] }
                }
                if ($name -isnot [string]) { throw ${pdfCryptUnsupported} }
                return (getPdfCryptMethod $doc $crypt.Cf $name)
            }
        }
    }
    return $crypt.StmMethod
}

function unprotectPdfData {
    # ストリームの中身（圧縮を戻す前）を復号する。AES-256 はファイルの鍵をそのまま使う
    param (
        [hashtable]$crypt,
        [string]$method,
        [byte[]]$data
    )

    if ($method -ceq "None") { return , $data }
    # AES-CBC。先頭 16 バイトが初期ベクトル、最後に PKCS#7 の詰め物
    if ($data.Length -eq 0) { return , $data }
    if ($data.Length -lt 32 -or $data.Length % 16 -ne 0) {
        throw "PDFの暗号化されたデータが壊れているため読めません。"
    }
    $plain = invokePdfAesCbc $crypt.Key (getPdfSlice $data 0 16) (getPdfSlice $data 16 ($data.Length - 16)) $false
    $pad = $plain[$plain.Length - 1]
    if ($pad -lt 1 -or $pad -gt 16) {
        throw "PDFの暗号化されたデータが壊れているため読めません。"
    }
    return , (getPdfSlice $plain 0 ($plain.Length - $pad))
}

# PDF ファイルの対象の拡張子・文字の読み取り。PowerShell だけで読む（外の部品・Office を使わない）。
# バイト列 → ページごとの文字列（readPdfPages）は、画面にもファイルにも触らない判断層の関数にする。
# ファイルを開いて読む関数（readPdfFile）だけが状態層（ファイルに触る）。
# 読む範囲と上限は docs/design/indexing/pdf.md、細工した PDF から身を守ることは docs/safety/checks.md。
#   読む    : 相互参照の表・相互参照のストリーム（オブジェクトのストリーム）、圧縮なし・FlateDecode、
#             文字の命令 Tj・TJ・'・"、行送り Td・TD・T*・Tm・TL（縦の位置が変わったときに行を分ける。ET では分けない）、
#             フォントの ToUnicode、ToUnicode の無い単純フォント（WinAnsi 相当）
#   暗号化   : 空の利用者パスワードで開ける PDF は復号して読む（pdf_crypt.ps1）。パスワードが要るもの・未対応の方式は例外にする。
#   読まない: FlateDecode 以外の圧縮、ToUnicode の無い複合フォント（CID）、壊れた相互参照（修復しない）。例外にする。
#             Form XObject（Do）・注釈・フォーム・しおりの文字は例外にせず、読み飛ばす
# 例外の文言は「PDF」で始める（readPdfPages は、それ以外の例外を「壊れている」に言い換える）。

# 取り込み対象にする PDF の拡張子（小文字）。足す・減らすと tests\meta\safety.Tests.ps1 が固定の一覧で確かめる
${pdfExtensions} = @(".pdf")

# 元のファイルがこの大きさ（バイト）を超えたら、読まずに失敗にする
${pdfFileMaxBytes} = 100MB
# 1 ファイルの解凍後の合計がこの大きさ（バイト）を超えたら、失敗にする（圧縮爆弾）
${pdfInflatedMaxBytes} = 100MB
# 相互参照のオブジェクトの数の上限
${pdfObjectMaxCount} = 1000000
# ページツリー・間接参照・配列や辞書の入れ子の深さの上限
${pdfNestMaxDepth} = 64
# ページ数の上限
${pdfPageMaxCount} = 10000
# TJ の数値がこの値以下（1/1000 文字幅。負の向きが右への詰め）で、前後の文字がどちらも半角のときだけ空白を入れる
${pdfGapThreshold} = -250
# 文字の対応表（ToUnicode）の項目の、1 ファイルの合計の上限
${pdfMapMaxEntries} = 1000000
# たどる相互参照（Prev・XRefStm）の数の上限
${pdfXrefMaxCount} = 1000
# ストリームの終わりを探して読み進める文字数の合計の上限（ファイルの大きさの何倍まで）。
# /Length の合わないストリームが順や逆順に並ぶだけなら、探す量は約 1 倍に収まる。その余裕を見て 4 倍にする
${pdfSearchMaxRatio} = 4
# 同じ行とみなす縦位置の差（ポイント）の上限
${pdfLineTolerance} = 1.0

${pdfLatin1} = [System.Text.Encoding]::GetEncoding(28591)
${pdfWinAnsi} = [System.Text.Encoding]::GetEncoding(1252)
${pdfDelimiters} = [char[]]@(0, 9, 10, 12, 13, 32, '(', ')', '<', '>', '[', ']', '{', '}', '/', '%')
${pdfStringStops} = [char[]]@('(', ')', '\')
# readPdfPageText の字句の切り出し用の正規表現。部品は 1 か所で定義し、2 つの正規表現をここから組み立てる。
# 区切り・空白は ${pdfDelimiters} と同じ（テストが全コードで確かめる）。実行時のコンパイル（RegexOptions.Compiled）は使わない。
${pdfRegexSpace} = '[\x00-\x20]*'
${pdfRegexNotStart} = '\x00-\x20()<>\[\]{}/%'
${pdfRegexRest} = '[^\x00\x09\x0A\x0C\x0D\x20()<>\[\]{}/%]'
${pdfRegexWord} = "[^${pdfRegexNotStart}]${pdfRegexRest}*"
${pdfRegexName} = "/${pdfRegexRest}*"
${pdfRegexString} = '\([^()\\]*\)'
# ページの内容で、文字の位置や文字列に効く命令（' と " は英字で始まらないので、正規表現には要らない）。readPdfPageText の分岐と同じであることをテストが確かめる
${pdfTextOpNames} = [string[]]@("Tj", "TJ", "Tf", "BT", "Td", "TD", "TL", "T*", "Tm", "BI")
${pdfRegexTextOps} = (@(${pdfTextOpNames} | ForEach-Object { [regex]::Escape($_) }) -join "|")
# 空白を飛ばして、(1) 数値・キーワード、または (2) 名前・入れ子もエスケープも無い文字列・<< >> [ ] { } を 1 つ取る。
# コメント・16 進の文字列・入れ子やエスケープのある文字列・単独の < > ) は取らない（readPdfToken の 1 文字ずつ進める道に任せる）
${pdfTokenRegex} = [regex]::new("\G(?>${pdfRegexSpace})(?:(${pdfRegexWord})|(${pdfRegexName}|${pdfRegexString}|<<|>>|[\[\]{}]))")
# ページの内容の読み取り用。字句の取り方は pdfTokenRegex と同じで、先頭に「読み飛ばす並び」を足してある（グループ 1。語は 2、それ以外は 3）。
# 読み飛ばす並び = 数・名前・単純な文字列などの引数が最大 16 個並び、文字に効かない命令（英字で始まる語で、pdfTextOpNames 以外）で終わる。
# 命令を読むと数・名前・文字列は捨てられるので、飛ばしても結果は変わらない。文字に効く命令の前の引数は要るので、並びの終わりが文字に効かない命令のときだけ飛ばす。
# 並びの個数に上限があるのは、引数が延々と続く内容で、試みのたびに最後まで走って遅くなる（字句の数の 2 乗）のを防ぐため。上限より長い並びは 1 字句ずつ読む（結果は同じ）。
# 配列・辞書・コメント・入れ子の文字列を含むところは、ここに合わず 1 字句ずつ読む。
${pdfRegexArgStart} = "[^${pdfRegexNotStart}A-Za-z'`"]"
${pdfRegexArg} = "(?:${pdfRegexArgStart}${pdfRegexRest}*|${pdfRegexName}|${pdfRegexString})"
${pdfRegexSkip} = "(?>(?>${pdfRegexSpace})${pdfRegexArg}){0,16}(?>${pdfRegexSpace})(?!(?:${pdfRegexTextOps})(?!${pdfRegexRest}))[A-Za-z]${pdfRegexRest}*"
${pdfPageRegex} = [regex]::new("\G(?:(${pdfRegexSkip})|(?>${pdfRegexSpace})(?:(${pdfRegexWord})|(${pdfRegexName}|${pdfRegexString}|<<|>>|[\[\]{}])))")

function testPdfExtension {
    # ファイル名（またはパス）の拡張子が、取り込み対象の PDF の拡張子か（大文字・小文字を区別しない）
    param (
        [string]$path
    )

    $extension = [System.IO.Path]::GetExtension($path).ToLowerInvariant()
    return (${pdfExtensions} -contains $extension)
}

function newPdfLimits {
    # 読み取りの上限。既定は上の値。テストで小さく差し替えるための引数
    param (
        [long]$maxInflated = ${pdfInflatedMaxBytes},
        [int]$maxObjects = ${pdfObjectMaxCount},
        [int]$maxDepth = ${pdfNestMaxDepth},
        [int]$maxPages = ${pdfPageMaxCount},
        [int]$maxMapEntries = ${pdfMapMaxEntries},
        [int]$maxXref = ${pdfXrefMaxCount},
        [double]$maxSearchRatio = ${pdfSearchMaxRatio}
    )

    return @{
        MaxInflated = $maxInflated; MaxObjects = $maxObjects; MaxDepth = $maxDepth; MaxPages = $maxPages
        MaxMapEntries = $maxMapEntries; MaxXref = $maxXref; MaxSearchRatio = $maxSearchRatio
    }
}

function newPdfLexer {
    param (
        [string]$text,
        [int]$position = 0
    )

    return @{ S = $text; P = $position; K = "" }
}

function readPdfToken {
    # 字句を 1 つ読んで値を返す。種類は $st.K に入る:
    #   num（数値。double）/ name（先頭の / を除いた名前）/ str（文字列。丸括弧・16 進。1 バイト 1 文字の文字列）/
    #   kw（キーワード・演算子）/ [ / ] / << / >> / eof
    # 文字列全体に正規表現を当てず、1 文字ずつ進める（壊れた入力で後戻りが増えて固まらないため）
    param (
        [hashtable]$st
    )

    $s = $st.S
    $n = $s.Length
    $p = $st.P
    while ($true) {
        while ($p -lt $n -and [int]$s[$p] -le 32) { $p++ }
        if ($p -ge $n) {
            $st.P = $p
            $st.K = "eof"
            return $null
        }
        $c = $s[$p]
        if ($c -eq '%') {
            $e = $s.IndexOfAny([char[]]@([char]10, [char]13), $p)
            if ($e -lt 0) { $p = $n } else { $p = $e }
            continue
        }
        if ($c -eq '/') {
            $e = $s.IndexOfAny(${pdfDelimiters}, $p + 1)
            if ($e -lt 0) { $e = $n }
            $name = $s.Substring($p + 1, $e - $p - 1)
            if ($name.Contains("#")) {
                # 名前の # の戻しは readPdfPageText の字句の取り方と同じ。変えるときは 2 か所をそろえる
                $name = [regex]::Replace($name, '#([0-9A-Fa-f]{2})', { param($m) [string][char][Convert]::ToInt32($m.Groups[1].Value, 16) })
            }
            $st.P = $e
            $st.K = "name"
            return $name
        }
        if ($c -eq '(') {
            $sb = [System.Text.StringBuilder]::new()
            $nest = 1
            $p++
            while ($p -lt $n) {
                $q = $s.IndexOfAny(${pdfStringStops}, $p)
                if ($q -lt 0) {
                    [void]$sb.Append($s, $p, $n - $p)
                    $p = $n
                    break
                }
                [void]$sb.Append($s, $p, $q - $p)
                $ch = $s[$q]
                if ($ch -eq '(') {
                    $nest++
                    [void]$sb.Append('(')
                    $p = $q + 1
                } elseif ($ch -eq ')') {
                    $nest--
                    $p = $q + 1
                    if ($nest -eq 0) { break }
                    [void]$sb.Append(')')
                } else {
                    $q++
                    if ($q -ge $n) { $p = $n; break }
                    $e = $s[$q]
                    $p = $q + 1
                    if ($e -ceq 'n') { [void]$sb.Append([char]10) }
                    elseif ($e -ceq 'r') { [void]$sb.Append([char]13) }
                    elseif ($e -ceq 't') { [void]$sb.Append([char]9) }
                    elseif ($e -ceq 'b') { [void]$sb.Append([char]8) }
                    elseif ($e -ceq 'f') { [void]$sb.Append([char]12) }
                    elseif ($e -ge '0' -and $e -le '7') {
                        $value = [int]$e - 48
                        $digits = 1
                        while ($digits -lt 3 -and $p -lt $n -and $s[$p] -ge '0' -and $s[$p] -le '7') {
                            $value = $value * 8 + ([int]$s[$p] - 48)
                            $p++
                            $digits++
                        }
                        [void]$sb.Append([char]($value -band 255))
                    } elseif ($e -eq "`r") {
                        if ($p -lt $n -and $s[$p] -eq "`n") { $p++ }
                    } elseif ($e -eq "`n") {
                        # 行の継続（何も入れない）
                    } else {
                        [void]$sb.Append($e)
                    }
                }
            }
            $st.P = $p
            $st.K = "str"
            return $sb.ToString()
        }
        if ($c -eq '<') {
            if ($p + 1 -lt $n -and $s[$p + 1] -eq '<') {
                $st.P = $p + 2
                $st.K = "<<"
                return $null
            }
            $e = $s.IndexOf('>', $p + 1)
            if ($e -lt 0) { $e = $n }
            $hex = $s.Substring($p + 1, $e - $p - 1) -replace '[^0-9A-Fa-f]', ''
            if ($hex.Length % 2 -eq 1) { $hex += "0" }
            $sb = [System.Text.StringBuilder]::new()
            for ($i = 0; $i -lt $hex.Length; $i += 2) {
                [void]$sb.Append([char][Convert]::ToInt32($hex.Substring($i, 2), 16))
            }
            $st.P = [Math]::Min($e + 1, $n)
            $st.K = "str"
            return $sb.ToString()
        }
        if ($c -eq '>') {
            if ($p + 1 -lt $n -and $s[$p + 1] -eq '>') {
                $st.P = $p + 2
                $st.K = ">>"
                return $null
            }
            $p++
            continue
        }
        if ($c -eq '[') { $st.P = $p + 1; $st.K = "["; return $null }
        if ($c -eq ']') { $st.P = $p + 1; $st.K = "]"; return $null }
        if ($c -eq ')' ) { $p++; continue }
        if ($c -eq '{' -or $c -eq '}') { $st.P = $p + 1; $st.K = "kw"; return [string]$c }

        $e = $s.IndexOfAny(${pdfDelimiters}, $p)
        if ($e -lt 0) { $e = $n }
        $token = $s.Substring($p, $e - $p)
        $st.P = $e
        $d = 0.0
        if (($c -ge '0' -and $c -le '9') -or $c -eq '-' -or $c -eq '+' -or $c -eq '.') {
            # 数の判定は readPdfPageText の字句の取り方（2 か所）と同じ。変えるときは 3 か所をそろえる
            if ([double]::TryParse($token, [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$d) -and -not [double]::IsInfinity($d) -and -not [double]::IsNaN($d)) {
                $st.K = "num"
                return $d
            }
        }
        $st.K = "kw"
        return $token
    }
}

function readPdfValue {
    # 値（数値・名前 "/名前"・文字列 @{PdfType="str"}・配列 List・辞書 Hashtable・間接参照 @{PdfType="ref"; N}・真偽・null）を 1 つ読む。
    # 読み終わったあと $st.K が ] / >> / eof なら、値でなく終わりの印を読んだ（戻り値は $null）
    param (
        [hashtable]$doc,
        [hashtable]$st,
        [int]$depth,
        [bool]$allowRef = $true
    )

    if ($depth -gt $doc.Limits.MaxDepth) {
        throw "PDFの入れ子が深すぎるため読めません。"
    }
    $v = readPdfToken $st
    $kind = $st.K
    if ($kind -eq "num") {
        if ($allowRef -and $v -ge 0 -and $v -le 2147483647 -and $v -eq [Math]::Floor($v)) {
            $save = $st.P
            $g = readPdfToken $st
            if ($st.K -eq "num" -and $g -ge 0 -and $g -eq [Math]::Floor($g)) {
                $r = readPdfToken $st
                if ($st.K -eq "kw" -and $r -ceq "R") {
                    $st.K = "val"
                    return @{ PdfType = "ref"; N = [int]$v }
                }
            }
            $st.P = $save
            $st.K = "num"
        }
        return $v
    }
    if ($kind -eq "name") { return "/$v" }
    if ($kind -eq "str") { return @{ PdfType = "str"; V = $v } }
    if ($kind -eq "[") {
        $list = [System.Collections.Generic.List[object]]::new()
        while ($true) {
            $item = readPdfValue $doc $st ($depth + 1) $allowRef
            if ($st.K -eq "]" -or $st.K -eq "eof" -or $st.K -eq ">>") { break }
            if ($list.Count -ge $doc.Limits.MaxObjects) {
                throw "PDFの配列の要素の数が上限を超えるため読めません。"
            }
            $list.Add($item)
        }
        $st.K = "val"
        return , $list
    }
    if ($kind -eq "<<") {
        $dict = [System.Collections.Hashtable]::new()
        while ($true) {
            $key = readPdfToken $st
            if ($st.K -eq ">>" -or $st.K -eq "eof") { break }
            if ($st.K -ne "name") { continue }
            $item = readPdfValue $doc $st ($depth + 1) $allowRef
            if ($st.K -eq ">>" -or $st.K -eq "eof") { break }
            $dict[$key] = $item
            if ($dict.Count -gt $doc.Limits.MaxObjects) {
                throw "PDFの辞書の項目の数が上限を超えるため読めません。"
            }
        }
        $st.K = "val"
        return , $dict
    }
    if ($kind -eq "kw") {
        if ($v -ceq "true") { return $true }
        if ($v -ceq "false") { return $false }
        return $null
    }
    return $null
}

function testPdfRef {
    param ($v)
    return ($v -is [hashtable] -and $v.ContainsKey("PdfType") -and $v["PdfType"] -eq "ref")
}

function testPdfStream {
    param ($v)
    return ($v -is [hashtable] -and $v.ContainsKey("PdfType") -and $v["PdfType"] -eq "stream")
}

function testPdfDict {
    param ($v)
    return ($v -is [System.Collections.Hashtable] -and -not $v.ContainsKey("PdfType"))
}

function resolvePdf {
    # 間接参照をたどって値を返す（たどる回数に上限。循環は例外）
    param (
        [hashtable]$doc,
        $v
    )

    $count = 0
    while (testPdfRef $v) {
        $count++
        if ($count -gt $doc.Limits.MaxDepth) {
            throw "PDFの参照が循環しているため読めません。"
        }
        $v = getPdfObject $doc $v["N"]
    }
    return $v
}

function getPdfObject {
    # 番号のオブジェクトを読んで返す（読んだものは控える）。相互参照に無い・解放済みは $null。
    # 読んでいる最中に同じ番号を読もうとしたら（循環）、例外にする
    param (
        [hashtable]$doc,
        [int]$num
    )

    if ($doc.Cache.ContainsKey($num)) { return $doc.Cache[$num] }
    if (-not $doc.Xref.ContainsKey($num)) { return $null }
    $entry = $doc.Xref[$num]
    if ($entry.Type -eq 0) { return $null }
    if ($doc.Loading.ContainsKey($num)) {
        throw "PDFの参照が循環しているため読めません。"
    }
    if ($doc.Loading.Count -ge $doc.Limits.MaxDepth) {
        throw "PDFの参照が深すぎるため読めません。"
    }
    $doc.Loading[$num] = $true
    try {
        if ($entry.Type -eq 1) {
            $value = readPdfIndirectAt $doc $entry.Offset $num
        } else {
            $value = readPdfFromObjectStream $doc $entry.Stream $entry.Index $num
        }
    } finally {
        $doc.Loading.Remove($num)
    }
    $doc.Cache[$num] = $value
    return $value
}

function readPdfIndirectAt {
    # オフセットにある "N G obj ... endobj" を読む。ストリームなら @{PdfType="stream"; Dict; Start; Length} を返す。
    # expected が 0 以上なら、番号が合うことも確かめる
    param (
        [hashtable]$doc,
        [long]$offset,
        [int]$expected
    )

    $text = $doc.Text
    if ($offset -lt 0 -or $offset -ge $text.Length) {
        throw "PDFの相互参照がファイルの外を指しているため読めません。"
    }
    $st = newPdfLexer $text ([int]$offset)
    $a = readPdfToken $st
    $aKind = $st.K
    $gen = readPdfToken $st
    $c = readPdfToken $st
    if ($aKind -ne "num" -or $st.K -ne "kw" -or $c -cne "obj") {
        throw "PDFのオブジェクトが見つからないため読めません。"
    }
    if ($expected -ge 0 -and [int]$a -ne $expected) {
        throw "PDFのオブジェクトの番号が相互参照と合わないため読めません。"
    }
    $value = readPdfValue $doc $st 0
    if (-not (testPdfDict $value)) { return $value }

    $save = $st.P
    $t = readPdfToken $st
    if ($st.K -ne "kw" -or $t -cne "stream") { return $value }
    $start = $st.P
    if ($start -lt $text.Length -and $text[$start] -eq "`r") { $start++ }
    if ($start -lt $text.Length -and $text[$start] -eq "`n") { $start++ }
    $length = -1
    $declared = resolvePdf $doc $value["Length"]
    if ($declared -is [double] -and $declared -ge 0 -and $start + $declared -le $text.Length) {
        $after = [int]($start + $declared)
        $skip = 0
        while ($skip -lt 4 -and $after + $skip -lt $text.Length -and [int]$text[$after + $skip] -le 32) { $skip++ }
        if ([string]::CompareOrdinal($text, $after + $skip, "endstream", 0, 9) -eq 0) { $length = [int]$declared }
    }
    if ($length -lt 0) {
        # 長さが合わないストリームが多くても、同じ範囲を何度も探さないよう、直前に見つけた位置を使い回す
        # [From, At) には "endstream" の始まりが無い。前より手前から探すときは、手前の分だけ探して無ければ At を使う
        $found = $doc.EndSearch
        if ($start -ge $found.From -and $start -le $found.At) {
            $end = $found.At
        } elseif ($start -lt $found.From -and $found.At -ge $found.From) {
            $span = [Math]::Min($found.From - $start + 8, $text.Length - $start)
            $end = $text.IndexOf("endstream", $start, $span, [StringComparison]::Ordinal)
            if ($end -lt 0 -or $end -ge $found.From) {
                $doc.Searched += $span
                $end = $found.At
            } else {
                $doc.Searched += $end - $start
            }
            $found.From = $start
            $found.At = $end
        } else {
            $end = $text.IndexOf("endstream", $start, [StringComparison]::Ordinal)
            if ($end -lt 0) {
                throw "PDFのストリームの終わりが無いため読めません。"
            }
            $doc.Searched += $end - $start
            $found.From = $start
            $found.At = $end
        }
        if ($doc.Searched -gt $doc.Limits.MaxSearchRatio * $text.Length) {
            throw "PDFのストリームの終わりを探す量が上限を超えるため読めません。"
        }
        $length = $end - $start
        if ($length -gt 0 -and $text[$start + $length - 1] -eq "`n") { $length-- }
        if ($length -gt 0 -and $text[$start + $length - 1] -eq "`r") { $length-- }
    }
    return @{ PdfType = "stream"; Dict = $value; Start = $start; Length = $length; Num = [int]$a }
}

function expandPdfFlate {
    # zlib の先頭 2 バイトを飛ばして DeflateStream で解凍する。解凍後の合計が上限を超えたら例外
    param (
        [hashtable]$doc,
        [byte[]]$data
    )

    if ($data.Length -lt 3) {
        throw "PDFの圧縮されたデータが壊れているため読めません。"
    }
    $source = [System.IO.MemoryStream]::new($data, 2, $data.Length - 2)
    $deflate = [System.IO.Compression.DeflateStream]::new($source, [System.IO.Compression.CompressionMode]::Decompress)
    $output = [System.IO.MemoryStream]::new()
    $buffer = New-Object byte[] 65536
    try {
        while ($true) {
            $read = $deflate.Read($buffer, 0, $buffer.Length)
            if ($read -le 0) { break }
            $doc.Inflated += $read
            if ($doc.Inflated -gt $doc.Limits.MaxInflated) {
                throw "PDFの解凍後の大きさが上限を超えるため読めません。"
            }
            $output.Write($buffer, 0, $read)
        }
        return , $output.ToArray()
    } finally {
        $deflate.Dispose()
        $source.Dispose()
        $output.Dispose()
    }
}

function undoPdfPredictor {
    # FlateDecode の Predictor（PNG の 10～15）を戻す。TIFF（2）は読まない
    param (
        [byte[]]$data,
        $params
    )

    $predictor = 1
    if ((testPdfDict $params) -and $params.ContainsKey("Predictor")) { $predictor = [int]$params["Predictor"] }
    if ($predictor -le 1) { return , $data }
    if ($predictor -lt 10) {
        throw "PDFの未対応の圧縮のため読めません。"
    }
    $columns = 1
    $colors = 1
    $bits = 8
    if ($params.ContainsKey("Columns")) { $columns = [int]$params["Columns"] }
    if ($params.ContainsKey("Colors")) { $colors = [int]$params["Colors"] }
    if ($params.ContainsKey("BitsPerComponent")) { $bits = [int]$params["BitsPerComponent"] }
    $rowLength = [int][Math]::Ceiling($columns * $colors * $bits / 8.0)
    $bpp = [Math]::Max(1, [int][Math]::Ceiling($colors * $bits / 8.0))
    if ($rowLength -le 0) {
        throw "PDFの圧縮の指定が壊れているため読めません。"
    }
    $rows = [int][Math]::Floor($data.Length / ($rowLength + 1))
    $out = New-Object byte[] ($rows * $rowLength)
    for ($r = 0; $r -lt $rows; $r++) {
        $src = $r * ($rowLength + 1)
        $type = $data[$src]
        $dst = $r * $rowLength
        $prev = $dst - $rowLength
        for ($i = 0; $i -lt $rowLength; $i++) {
            $x = [int]$data[$src + 1 + $i]
            $left = 0
            if ($i -ge $bpp) { $left = [int]$out[$dst + $i - $bpp] }
            $up = 0
            if ($r -gt 0) { $up = [int]$out[$prev + $i] }
            $upLeft = 0
            if ($r -gt 0 -and $i -ge $bpp) { $upLeft = [int]$out[$prev + $i - $bpp] }
            if ($type -eq 0) { $v = $x }
            elseif ($type -eq 1) { $v = $x + $left }
            elseif ($type -eq 2) { $v = $x + $up }
            elseif ($type -eq 3) { $v = $x + [int][Math]::Floor(($left + $up) / 2) }
            elseif ($type -eq 4) {
                $pp = $left + $up - $upLeft
                $pa = [Math]::Abs($pp - $left)
                $pb = [Math]::Abs($pp - $up)
                $pc = [Math]::Abs($pp - $upLeft)
                if ($pa -le $pb -and $pa -le $pc) { $pred = $left } elseif ($pb -le $pc) { $pred = $up } else { $pred = $upLeft }
                $v = $x + $pred
            } else {
                throw "PDFの圧縮のデータが壊れているため読めません。"
            }
            $out[$dst + $i] = [byte]($v -band 255)
        }
    }
    return , $out
}

function getPdfStreamBytes {
    # ストリームの中身を、圧縮を戻して返す（圧縮なし・FlateDecode だけ。ほかは例外）
    param (
        [hashtable]$doc,
        [hashtable]$stream
    )

    $dict = $stream.Dict
    $filters = resolvePdf $doc $dict["Filter"]
    # 取り出す前の大きさも、圧縮の有無にかかわらず合計に数える（同じストリームを何度も参照されても増え続けないように）
    $doc.Inflated += $stream.Length
    if ($doc.Inflated -gt $doc.Limits.MaxInflated) {
        throw "PDFの解凍後の大きさが上限を超えるため読めません。"
    }
    $data = New-Object byte[] $stream.Length
    [Array]::Copy($doc.Bytes, $stream.Start, $data, 0, $stream.Length)
    if ($null -ne $doc.Crypt -and $stream.ContainsKey("Num")) {
        # 暗号化された PDF は、圧縮を戻す前に復号する
        $method = getPdfStreamCryptMethod $doc $stream
        $data = unprotectPdfData $doc.Crypt $method $data
    }
    if ($null -eq $filters) { return , $data }
    $filterList = @($filters)
    $paramsValue = resolvePdf $doc $dict["DecodeParms"]
    $paramsList = @($paramsValue)
    for ($i = 0; $i -lt $filterList.Count; $i++) {
        $name = resolvePdf $doc $filterList[$i]
        if ($name -ceq "/Crypt") {
            continue
        } elseif ($name -ceq "/FlateDecode" -or $name -ceq "/Fl") {
            $data = expandPdfFlate $doc $data
            $params = $null
            if ($i -lt $paramsList.Count) { $params = resolvePdf $doc $paramsList[$i] }
            $data = undoPdfPredictor $data $params
        } else {
            throw "PDFの未対応の圧縮のため読めません。"
        }
    }
    return , $data
}

function readPdfFromObjectStream {
    # オブジェクトのストリームの中の、番号のオブジェクトを読む
    param (
        [hashtable]$doc,
        [int]$streamNum,
        [int]$index,
        [int]$num
    )

    if (-not $doc.ObjStreams.ContainsKey($streamNum)) {
        $stream = getPdfObject $doc $streamNum
        if (-not (testPdfStream $stream)) {
            throw "PDFのオブジェクトのストリームが読めないため読めません。"
        }
        $bytes = getPdfStreamBytes $doc $stream
        $text = ${pdfLatin1}.GetString($bytes)
        $count = [int](resolvePdf $doc $stream.Dict["N"])
        $first = [int](resolvePdf $doc $stream.Dict["First"])
        if ($count -lt 0 -or $count -gt $doc.Limits.MaxObjects) {
            throw "PDFのオブジェクトの数が上限を超えるため読めません。"
        }
        # 見出しは 1 件に 4 文字（"1 0 "）以上要る。中身より多い件数は、確保する前に断る
        if ($count -gt [Math]::Floor($text.Length / 4)) {
            throw "PDFのオブジェクトのストリームの件数が中身と合わないため読めません。"
        }
        $st = newPdfLexer $text 0
        $numbers = New-Object int[] $count
        $offsets = New-Object int[] $count
        for ($i = 0; $i -lt $count; $i++) {
            $token = readPdfToken $st
            if ($st.K -ne "num") { throw "PDFのオブジェクトのストリームの見出しが読めないため読めません。" }
            $numbers[$i] = [int]$token
            $token = readPdfToken $st
            if ($st.K -ne "num") { throw "PDFのオブジェクトのストリームの見出しが読めないため読めません。" }
            $offsets[$i] = [int]$token
        }
        $doc.ObjStreams[$streamNum] = @{ Text = $text; First = $first; Numbers = $numbers; Offsets = $offsets }
    }
    $info = $doc.ObjStreams[$streamNum]
    $position = -1
    if ($index -ge 0 -and $index -lt $info.Numbers.Length -and $info.Numbers[$index] -eq $num) {
        $position = $index
    } else {
        # 位置は細工できるため、番号から位置への辞書を 1 度だけ作って引く（毎回先頭から探すと、件数の 2 乗の比較になる）
        if (-not $info.ContainsKey("Positions")) {
            $positions = @{}
            for ($i = 0; $i -lt $info.Numbers.Length; $i++) {
                if (-not $positions.ContainsKey($info.Numbers[$i])) { $positions[$info.Numbers[$i]] = $i }
            }
            $info.Positions = $positions
        }
        $position = if ($info.Positions.ContainsKey([int]$num)) { $info.Positions[[int]$num] } else { -1 }
    }
    if ($position -lt 0) { return $null }
    $st = newPdfLexer $info.Text ($info.First + $info.Offsets[$position])
    return (readPdfValue $doc $st 0)
}

function addPdfXrefEntry {
    param (
        [hashtable]$doc,
        [long]$num,
        [hashtable]$entry
    )

    # 同じ番号を繰り返しても増えないので、読んだ行の総数も数える
    $doc.XrefRows += 1
    if ($doc.XrefRows -gt $doc.Limits.MaxObjects) {
        throw "PDFのオブジェクトの数が上限を超えるため読めません。"
    }
    if ($num -lt 0 -or $num -gt 2147483647) { return }
    if (-not $doc.Xref.ContainsKey([int]$num)) {
        $doc.Xref[[int]$num] = $entry
        if ($doc.Xref.Count -gt $doc.Limits.MaxObjects) {
            throw "PDFのオブジェクトの数が上限を超えるため読めません。"
        }
    } elseif ($doc.Hybrid -and $doc.Xref[[int]$num].Type -eq 0 -and $entry.Type -ne 0) {
        $doc.Xref[[int]$num] = $entry
    }
}

function readPdfXref {
    # オフセットにある相互参照（表または相互参照のストリーム）を読み、前の相互参照（Prev・XRefStm）も順にたどる。
    # 新しいものが先に入る。暗号化（Encrypt）の辞書の場所と ID は doc に覚える。ファイルの外を指す・循環・数が上限を超えるのは例外。
    # 入れ子の呼び出しにせず、待ちの積み上げで読む（Prev が長く続いても呼び出しが深くならない）
    param (
        [hashtable]$doc,
        [long]$offset
    )

    $pending = [System.Collections.Generic.Stack[object]]::new()
    $pending.Push(@{ Offset = $offset; Hybrid = $false })
    while ($pending.Count -gt 0) {
        if ($doc.Visited.Count -ge $doc.Limits.MaxXref) {
            throw "PDFの相互参照の数が上限を超えるため読めません。"
        }
        $job = $pending.Pop()
        $next = readPdfXrefSection $doc $job.Offset $job.Hybrid
        # 先に XRefStm、次に Prev の順に読む（Prev を先に積む）
        if ($next.Prev -ge 0) { $pending.Push(@{ Offset = $next.Prev; Hybrid = $false }) }
        if ($next.Stm -ge 0) { $pending.Push(@{ Offset = $next.Stm; Hybrid = $true }) }
    }
}

function readPdfXrefSection {
    # 相互参照 1 つ分を読み、次に読む位置 @{ Stm; Prev }（無ければ -1）を返す。
    # hybrid（XRefStm で読むもの）は、表で「解放済み」とされた番号を上書きする（旧い読み手から隠すための作り）
    param (
        [hashtable]$doc,
        [long]$offset,
        [bool]$hybrid = $false
    )

    $doc.Hybrid = $hybrid

    $text = $doc.Text
    if ($offset -lt 0 -or $offset -ge $text.Length) {
        throw "PDFの相互参照がファイルの外を指しているため読めません。"
    }
    if ($doc.Visited.ContainsKey($offset)) {
        throw "PDFの相互参照が循環しているため読めません。"
    }
    $doc.Visited[$offset] = $true
    $p = [int]$offset
    while ($p -lt $text.Length -and [int]$text[$p] -le 32) { $p++ }
    $max = $doc.Limits.MaxObjects
    if ([string]::CompareOrdinal($text, $p, "xref", 0, 4) -eq 0) {
        $st = newPdfLexer $text ($p + 4)
        while ($true) {
            $a = readPdfToken $st
            if ($st.K -eq "kw" -and $a -ceq "trailer") { break }
            if ($st.K -ne "num") {
                throw "PDFの相互参照の表が読めないため読めません。"
            }
            $first = [long]$a
            $count = readPdfToken $st
            if ($st.K -ne "num" -or $count -lt 0 -or $count -gt $max) {
                throw "PDFの相互参照の表が読めない、またはオブジェクトの数が上限を超えるため読めません。"
            }
            $pp = $st.P
            for ($k = 0; $k -lt $count; $k++) {
                while ($pp -lt $text.Length -and [int]$text[$pp] -le 32) { $pp++ }
                $entryOffset = 0L
                $kind = ""
                if ($pp + 17 -lt $text.Length -and $text[$pp + 10] -eq " " -and $text[$pp + 16] -eq " " -and
                    [long]::TryParse($text.Substring($pp, 10), [ref]$entryOffset)) {
                    $kind = [string]$text[$pp + 17]
                    $pp += 18
                } else {
                    $st.P = $pp
                    $o = readPdfToken $st
                    $okO = ($st.K -eq "num")
                    [void](readPdfToken $st)
                    $t = readPdfToken $st
                    if (-not $okO -or $st.K -ne "kw") {
                        throw "PDFの相互参照の表が読めないため読めません。"
                    }
                    $entryOffset = [long]$o
                    $kind = [string]$t
                    $pp = $st.P
                }
                if ($kind -ceq "n" -and $entryOffset -gt 0) {
                    addPdfXrefEntry $doc ($first + $k) @{ Type = 1; Offset = $entryOffset }
                } else {
                    addPdfXrefEntry $doc ($first + $k) @{ Type = 0 }
                }
            }
            $st.P = $pp
        }
        $trailer = readPdfValue $doc $st 0
    } else {
        $stream = readPdfIndirectAt $doc $p -1
        if (-not (testPdfStream $stream) -or $stream.Dict["Type"] -cne "/XRef") {
            throw "PDFの相互参照が読めないため読めません。"
        }
        $trailer = $stream.Dict
        $data = getPdfStreamBytes $doc $stream
        $w = @(resolvePdf $doc $trailer["W"])
        if ($w.Count -ne 3) {
            throw "PDFの相互参照のストリームが壊れているため読めません。"
        }
        $w0 = [int]$w[0]
        $w1 = [int]$w[1]
        $w2 = [int]$w[2]
        if ($w0 -lt 0 -or $w1 -lt 0 -or $w2 -lt 0 -or $w0 -gt 8 -or $w1 -gt 8 -or $w2 -gt 8 -or ($w0 + $w1 + $w2) -eq 0) {
            throw "PDFの相互参照のストリームが壊れているため読めません。"
        }
        $rowLength = $w0 + $w1 + $w2
        $index = resolvePdf $doc $trailer["Index"]
        if ($null -eq $index) {
            $index = @(0, [int](resolvePdf $doc $trailer["Size"]))
        }
        $index = @($index)
        $pos = 0
        for ($g = 0; $g + 1 -lt $index.Count; $g += 2) {
            $first = [long]$index[$g]
            $count = [long]$index[$g + 1]
            if ($count -lt 0 -or $count -gt $max) {
                throw "PDFのオブジェクトの数が上限を超えるため読めません。"
            }
            for ($k = 0; $k -lt $count; $k++) {
                if ($pos + $rowLength -gt $data.Length) {
                    throw "PDFの相互参照のストリームが壊れているため読めません。"
                }
                $type = 1L
                if ($w0 -gt 0) {
                    $type = 0L
                    for ($j = 0; $j -lt $w0; $j++) { $type = $type * 256 + $data[$pos + $j] }
                }
                $f2 = 0L
                for ($j = 0; $j -lt $w1; $j++) { $f2 = $f2 * 256 + $data[$pos + $w0 + $j] }
                $f3 = 0L
                for ($j = 0; $j -lt $w2; $j++) { $f3 = $f3 * 256 + $data[$pos + $w0 + $w1 + $j] }
                $pos += $rowLength
                if ($type -eq 1) {
                    addPdfXrefEntry $doc ($first + $k) @{ Type = 1; Offset = $f2 }
                } elseif ($type -eq 2) {
                    addPdfXrefEntry $doc ($first + $k) @{ Type = 2; Stream = [int]$f2; Index = [int]$f3 }
                } else {
                    addPdfXrefEntry $doc ($first + $k) @{ Type = 0 }
                }
            }
        }
    }

    if (-not (testPdfDict $trailer)) {
        throw "PDFの相互参照のあとの情報が読めないため読めません。"
    }
    if ($trailer.ContainsKey("Encrypt") -and $null -eq $doc.EncryptEntry) {
        # 新しい方のトレーラーを使う。辞書は、相互参照がそろってから読む（readPdfPagesCore）
        $doc.EncryptEntry = $trailer["Encrypt"]
    }
    if ($null -eq $doc.Root -and $trailer.ContainsKey("Root")) {
        $doc.Root = $trailer["Root"]
    }
    $next = @{ Stm = -1L; Prev = -1L }
    if ($trailer.ContainsKey("XRefStm")) { $next.Stm = [long]$trailer["XRefStm"] }
    if ($trailer.ContainsKey("Prev")) { $next.Prev = [long]$trailer["Prev"] }
    return $next
}

function addPdfMapEntries {
    # 文字の対応表の項目を数え、1 ファイルの合計が上限を超えたら例外にする（doc が無いときは数えない）
    param (
        $doc,
        [long]$count
    )

    if ($null -eq $doc) { return }
    $doc.MapEntries += $count
    if ($doc.MapEntries -gt $doc.Limits.MaxMapEntries) {
        throw "PDFの文字の対応表が大きすぎるため読めません。"
    }
}

function readPdfToUnicode {
    # ToUnicode の CMap から、文字コード → 文字列の表 Map（キーは int）と、文字コードのバイト数 Width（0 は指定なし）を返す
    param (
        [string]$text,
        [hashtable]$doc = $null
    )

    $map = @{}
    $width = 0
    $st = newPdfLexer $text 0
    $utf16 = [System.Text.Encoding]::BigEndianUnicode
    while ($true) {
        $t = readPdfToken $st
        if ($st.K -eq "eof") { break }
        if ($st.K -ne "kw") { continue }
        if ($t -ceq "begincodespacerange") {
            while ($true) {
                $lo = readPdfToken $st
                if ($st.K -ne "str") { break }
                [void](readPdfToken $st)
                if ($width -eq 0 -and $lo.Length -ge 1 -and $lo.Length -le 2) { $width = $lo.Length }
            }
        } elseif ($t -ceq "beginbfchar") {
            while ($true) {
                $src = readPdfToken $st
                if ($st.K -ne "str") { break }
                $dst = readPdfToken $st
                if ($st.K -ne "str") { break }
                if ($src.Length -eq 0 -or $src.Length -gt 3) { continue }
                addPdfMapEntries $doc 1
                $map[(convertPdfCode $src)] = convertPdfUtf16 $dst $utf16
            }
        } elseif ($t -ceq "beginbfrange") {
            while ($true) {
                $lo = readPdfToken $st
                if ($st.K -ne "str") { break }
                $hi = readPdfToken $st
                if ($st.K -ne "str") { break }
                $dst = readPdfToken $st
                $kind = $st.K
                if ($lo.Length -eq 0 -or $lo.Length -gt 3 -or $hi.Length -eq 0 -or $hi.Length -gt 3) {
                    if ($kind -eq "[") {
                        while ($true) { [void](readPdfToken $st); if ($st.K -eq "]" -or $st.K -eq "eof") { break } }
                    }
                    continue
                }
                $from = convertPdfCode $lo
                $to = [Math]::Min((convertPdfCode $hi), $from + 65535)
                if ($kind -eq "str") {
                    $base = convertPdfUtf16 $dst $utf16
                    if ($base.Length -eq 0) { continue }
                    if ($to -ge $from) { addPdfMapEntries $doc ($to - $from + 1) }
                    $head = $base.Substring(0, $base.Length - 1)
                    $lastCode = [int]$base[$base.Length - 1]
                    for ($c = $from; $c -le $to; $c++) {
                        $map[[int]$c] = $head + [char](($lastCode + $c - $from) -band 65535)
                    }
                } elseif ($kind -eq "[") {
                    $c = $from
                    while ($true) {
                        $item = readPdfToken $st
                        if ($st.K -ne "str") { break }
                        if ($c -le $to) {
                            addPdfMapEntries $doc 1
                            $map[[int]$c] = convertPdfUtf16 $item $utf16
                        }
                        $c++
                    }
                }
            }
        }
    }
    return @{ Map = $map; Width = $width }
}

function convertPdfCode {
    # 1 バイト 1 文字の文字列を、ビッグエンディアンの文字コード（int）にする（3 バイトまで）
    param (
        [string]$s
    )

    $code = 0
    foreach ($ch in $s.ToCharArray()) { $code = $code * 256 + [int]$ch }
    return [int]$code
}

function convertPdfUtf16 {
    # 1 バイト 1 文字の文字列（UTF-16BE のバイト列）を文字列にする。奇数バイトのときは 1 バイトずつ文字にする
    param (
        [string]$s,
        $utf16
    )

    if ($s.Length % 2 -eq 1) { return $s }
    return $utf16.GetString(${pdfLatin1}.GetBytes($s))
}

function newPdfFont {
    # フォントの辞書から、文字列を文字にする規則 @{ Width; Map; NoMap } を作る。
    # ToUnicode があればそれを使う。無い単純フォントは WinAnsi 相当（Windows-1252）。無い複合フォント（CID）は NoMap（使ったときに例外）
    param (
        [hashtable]$doc,
        $dict
    )

    $font = @{ Width = 1; Map = $null; NoMap = $false }
    if (-not (testPdfDict $dict)) { return $font }
    $isComposite = ($dict["Subtype"] -ceq "/Type0")
    if ($isComposite) { $font.Width = 2 }
    $toUnicodeRef = $dict["ToUnicode"]
    $toUnicode = resolvePdf $doc $toUnicodeRef
    if (testPdfStream $toUnicode) {
        # 同じ ToUnicode を使うフォントが多くても、1 度だけ読む（番号ごとに控える）
        $key = $null
        if (testPdfRef $toUnicodeRef) { $key = $toUnicodeRef["N"] }
        if ($null -ne $key -and $doc.CMaps.ContainsKey($key)) {
            $cmap = $doc.CMaps[$key]
        } else {
            $bytes = getPdfStreamBytes $doc $toUnicode
            $cmap = readPdfToUnicode (${pdfLatin1}.GetString($bytes)) $doc
            if ($null -ne $key) { $doc.CMaps[$key] = $cmap }
        }
        $font.Map = $cmap.Map
        if ($cmap.Width -gt 0) { $font.Width = $cmap.Width }
    } elseif ($isComposite) {
        $font.NoMap = $true
    }
    return $font
}

function convertPdfStringToText {
    # 文字列（1 バイト 1 文字）を、フォントの規則で文字列にする
    param (
        $font,
        [string]$s
    )

    if ($null -ne $font -and $font.NoMap) {
        throw "PDFの文字の対応表が無いため読めません。"
    }
    if ($null -eq $font -or $null -eq $font.Map) {
        return ${pdfWinAnsi}.GetString(${pdfLatin1}.GetBytes($s))
    }
    $map = $font.Map
    $width = $font.Width
    $sb = [System.Text.StringBuilder]::new()
    for ($i = 0; $i -lt $s.Length; $i += $width) {
        if ($width -eq 2) {
            if ($i + 1 -ge $s.Length) { break }
            $code = [int]$s[$i] * 256 + [int]$s[$i + 1]
        } else {
            $code = [int]$s[$i]
        }
        if ($map.ContainsKey($code)) {
            [void]$sb.Append($map[$code])
        } elseif ($width -eq 1) {
            [void]$sb.Append(${pdfWinAnsi}.GetString([byte[]]@($code)))
        }
    }
    return $sb.ToString()
}

function testPdfHalfWidth {
    # 半角の文字か（ラテン文字の範囲）。TJ の詰めに空白を入れるかの判断に使う
    param (
        [char]$c
    )

    return ([int]$c -le 0x24F)
}

function getPdfGlyphCount {
    # 文字列が表す字形（フォントの 1 コード）の数。1 コードが 2 文字になる対応（合字）でも 1 と数える
    param (
        $font,
        [string]$s
    )

    if ($null -eq $font -or $null -eq $font.Map -or $font.Width -ne 2) { return $s.Length }
    return [int][Math]::Ceiling($s.Length / 2)
}

function addPdfText {
    # ページの文字に文字列を足す。詰め（Gap）が付いていて、前後の文字がどちらも半角のときだけ空白を入れる
    param (
        [hashtable]$ts,
        [string]$text,
        [int]$glyphs = 1
    )

    if ($text.Length -eq 0) { return }
    # 縦位置が前に出した文字と違うときだけ行を分ける（BT～ET で分かれていても、同じ縦位置なら同じ行）
    if ($ts.HasOut -and [Math]::Abs($ts.Y - $ts.OutY) -gt ${pdfLineTolerance}) {
        breakPdfLine $ts
    }
    $ts.HasOut = $true
    $ts.OutY = $ts.Y
    $ts.Run += $glyphs
    $sb = $ts.Sb
    if ($ts.Gap -and $sb.Length -gt 0) {
        $last = $sb[$sb.Length - 1]
        if ($last -ne "`n" -and $last -ne " " -and (testPdfHalfWidth $last) -and (testPdfHalfWidth $text[0]) -and $text[0] -ne " ") {
            [void]$sb.Append(" ")
        }
    }
    $ts.Gap = $false
    [void]$sb.Append($text)
}

function breakPdfLine {
    param (
        [hashtable]$ts
    )

    $sb = $ts.Sb
    if ($sb.Length -gt 0 -and $sb[$sb.Length - 1] -ne "`n") {
        [void]$sb.Append("`n")
    }
    $ts.Gap = $false
}

function readPdfPageText {
    # ページの内容（文字の命令）から文字列を作る。行送りは改行にする。
    # fontDict は フォント名 → フォント（辞書または参照）の辞書（無ければ $null）
    param (
        [hashtable]$doc,
        [string]$content,
        $fontDict
    )

    # Y は今の文字の縦位置（行の行列の y）、OutY は最後に出した文字の縦位置、Leading は行送り（TL）
    $ts = @{ Sb = [System.Text.StringBuilder]::new(); Gap = $false; Y = 0.0; OutY = 0.0; HasOut = $false; Leading = 0.0; Scale = 1.0; Run = 0 }
    # 字句は、関数を呼ばずに、位置指定の正規表現（トークンの切り出しは readPdfToken と同じ規則）でその場で切り出す。
    # 取れないもの（入れ子やエスケープのある文字列・16 進の文字列・コメントなど）だけ readPdfToken に任せる（$st.P で位置を渡す）
    $st = newPdfLexer $content 0
    $pos = 0
    $len = $content.Length
    $re = ${pdfPageRegex}
    $reTok = ${pdfTokenRegex}
    $emptyMatch = [System.Text.RegularExpressions.Match]::Empty
    $nums = [System.Collections.Generic.List[double]]::new()
    $lastStr = $null
    $lastName = $null
    $lastArray = $null
    $font = $null
    $fontSize = 0.0
    while ($true) {
        $m = if ($pos -lt $len) { $re.Match($content, $pos) } else { $emptyMatch }
        if ($m.Success) {
            $g = $m.Groups[1]
            if ($g.Success) {
                # 文字に効かない命令までの並びを、まとめて飛ばす
                $pos = $g.Index + $g.Length
                $nums.Clear()
                $lastStr = $null
                $lastName = $null
                $lastArray = $null
                continue
            }
            $g = $m.Groups[2]
            if ($g.Success) {
                $t = $g.Value
                $pos = $g.Index + $g.Length
                $kind = "kw"
                $c = $t[0]
                if (($c -ge '0' -and $c -le '9') -or $c -eq '-' -or $c -eq '+' -or $c -eq '.') {
                    $d = 0.0
                    # 数の判定は readPdfToken と、TJ の配列の中の取り方と同じ。変えるときは 3 か所をそろえる
                    if ([double]::TryParse($t, [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$d) -and -not [double]::IsInfinity($d) -and -not [double]::IsNaN($d)) {
                        $t = $d
                        $kind = "num"
                    }
                }
            } else {
                $g = $m.Groups[3]
                $t = $g.Value
                $pos = $g.Index + $g.Length
                $c = $t[0]
                if ($c -eq '/') {
                    $kind = "name"
                    $t = $t.Substring(1)
                    if ($t.Contains("#")) {
                        # 名前の # の戻しは readPdfToken と同じ。変えるときは 2 か所をそろえる
                        $t = [regex]::Replace($t, '#([0-9A-Fa-f]{2})', { param($m) [string][char][Convert]::ToInt32($m.Groups[1].Value, 16) })
                    }
                } elseif ($c -eq '(') {
                    $kind = "str"
                    $t = $t.Substring(1, $t.Length - 2)
                } elseif ($c -eq '[') { $kind = "["
                } elseif ($c -eq ']') { $kind = "]"
                } elseif ($c -eq '<') { $kind = "<<"
                } elseif ($c -eq '>') { $kind = ">>"
                } else { $kind = "kw" }
            }
        } else {
            $st.P = $pos
            $t = readPdfToken $st
            $kind = $st.K
            $pos = $st.P
        }
        if ($kind -eq "eof") { break }
        if ($kind -eq "num") {
            if ($nums.Count -ge 64) { $nums.Clear() }
            $nums.Add($t)
            continue
        }
        if ($kind -eq "name") { $lastName = $t; continue }
        if ($kind -eq "str") { $lastStr = $t; continue }
        if ($kind -eq "[") {
            $items = [System.Collections.Generic.List[object]]::new()
            while ($true) {
                $m = if ($pos -lt $len) { $reTok.Match($content, $pos) } else { $emptyMatch }
                if ($m.Success) {
                    $g = $m.Groups[1]
                    if ($g.Success) {
                        $pos = $g.Index + $g.Length
                        $c = $g.Value[0]
                        if (($c -ge '0' -and $c -le '9') -or $c -eq '-' -or $c -eq '+' -or $c -eq '.') {
                            $d = 0.0
                            # 数の判定は readPdfToken と、readPdfPageText の最初の字句の取り方と同じ。変えるときは 3 か所をそろえる
                            if ([double]::TryParse($g.Value, [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$d) -and -not [double]::IsInfinity($d) -and -not [double]::IsNaN($d)) {
                                $items.Add($d)
                            }
                        }
                    } else {
                        $g = $m.Groups[2]
                        $pos = $g.Index + $g.Length
                        $c = $g.Value[0]
                        if ($c -eq '(') { $items.Add($g.Value.Substring(1, $g.Value.Length - 2)) }
                        elseif ($c -eq ']') { break }
                    }
                } else {
                    $st.P = $pos
                    $item = readPdfToken $st
                    $pos = $st.P
                    if ($st.K -eq "]" -or $st.K -eq "eof") { break }
                    if ($st.K -eq "num" -or $st.K -eq "str") { $items.Add($item) }
                }
            }
            $lastArray = $items
            continue
        }
        if ($kind -eq "<<") {
            $nest = 1
            $st.P = $pos
            while ($nest -gt 0) {
                [void](readPdfToken $st)
                if ($st.K -eq "<<") { $nest++ } elseif ($st.K -eq ">>") { $nest-- } elseif ($st.K -eq "eof") { break }
            }
            $pos = $st.P
            continue
        }
        if ($kind -ne "kw") { continue }

        if ($t -ceq "Tj") {
            if ($null -ne $lastStr) { addPdfText $ts (convertPdfStringToText $font $lastStr) (getPdfGlyphCount $font $lastStr) }
        } elseif ($t -ceq "TJ") {
            if ($null -ne $lastArray) {
                foreach ($item in $lastArray) {
                    if ($item -is [string]) {
                        addPdfText $ts (convertPdfStringToText $font $item) (getPdfGlyphCount $font $item)
                    } elseif ($item -le ${pdfGapThreshold}) {
                        $ts.Gap = $true
                    }
                }
            }
        } elseif ($t -ceq "'" -or $t -ceq '"') {
            $ts.Y -= $ts.Leading * $ts.Scale
            $ts.Run = 0
            breakPdfLine $ts
            if ($null -ne $lastStr) { addPdfText $ts (convertPdfStringToText $font $lastStr) (getPdfGlyphCount $font $lastStr) }
        } elseif ($t -ceq "Tf") {
            $fontSize = if ($nums.Count -ge 1) { [Math]::Abs($nums[$nums.Count - 1]) } else { 0.0 }
            $font = $null
            if ($null -ne $lastName -and (testPdfDict $fontDict) -and $fontDict.ContainsKey($lastName)) {
                $font = getPdfFont $doc $fontDict[$lastName]
            }
        } elseif ($t -ceq "BT") {
            # テキストの行列は BT で初期化される（縦位置は 0 から）
            $ts.Y = 0.0
            $ts.Scale = 1.0
            $ts.Run = 0
        } elseif ($t -ceq "Td" -or $t -ceq "TD") {
            if ($nums.Count -ge 2) {
                # 縦の動きは、Tm の拡大（d）を掛けた値にする（`12 0 0 12 x y Tm` のあとの `0 -1 TD` は 12 ポイント動く）
                $ts.Y += $nums[1] * $ts.Scale
                if ($t -ceq "TD") { $ts.Leading = - $nums[1] }
                # 横にだけ動いたときは詰め。縦に動いたときは、次の文字を出すときに行を分ける。
                # 1 文字ずつ Td で並べる PDF（Chromium など）の文字を離さないよう、直前の Td 以降に出した文字が 1 文字以下で、
                # 前向きに 1 em より小さい動きは詰めにしない（空白は文字として入っている）。2 文字以上の語の後ろは空白でつなぐ
                $joined = ($fontSize -gt 0 -and $nums[0] -gt 0 -and $nums[0] -lt $fontSize -and $ts.Run -le 1)
                if ($nums[0] -ne 0 -and -not $joined) { $ts.Gap = $true }
                $ts.Run = 0
            }
        } elseif ($t -ceq "TL") {
            if ($nums.Count -ge 1) { $ts.Leading = $nums[0] }
        } elseif ($t -ceq "T*") {
            $ts.Y -= $ts.Leading * $ts.Scale
            $ts.Run = 0
            breakPdfLine $ts
        } elseif ($t -ceq "Tm") {
            if ($nums.Count -ge 6) {
                $ts.Y = $nums[5]
                # 上下を反転した行列（d が負）は、縦の動きの向きも反転するので、d の符号を残す
                $ts.Scale = [Math]::Sqrt($nums[2] * $nums[2] + $nums[3] * $nums[3])
                if ($nums[3] -lt 0) { $ts.Scale = -$ts.Scale }
                $ts.Run = 0
                $ts.Gap = $true
            }
        } elseif ($t -ceq "BI") {
            # 画像の中身（バイナリ）は読まない。ID から EI までを飛ばす
            $idPos = $content.IndexOf("ID", $pos, [StringComparison]::Ordinal)
            if ($idPos -lt 0) { break }
            $scan = $idPos + 2
            $endPos = -1
            while ($true) {
                $found = $content.IndexOf("EI", $scan, [StringComparison]::Ordinal)
                if ($found -lt 0) { break }
                $beforeOk = ($found -eq 0 -or [int]$content[$found - 1] -le 32)
                $afterOk = ($found + 2 -ge $content.Length -or [int]$content[$found + 2] -le 32)
                if ($beforeOk -and $afterOk) { $endPos = $found + 2; break }
                $scan = $found + 2
            }
            if ($endPos -lt 0) { break }
            $pos = $endPos
        }
        $nums.Clear()
        $lastStr = $null
        $lastName = $null
        $lastArray = $null
    }
    return ([regex]::Replace($ts.Sb.ToString(), '[\x00-\x09\x0B-\x1F\x7F]', " ")).TrimEnd("`n")
}

function getPdfFont {
    # フォント（辞書または参照）の規則を返す。参照のものは番号ごとに控える
    param (
        [hashtable]$doc,
        $ref
    )

    if (testPdfRef $ref) {
        $num = $ref["N"]
        if (-not $doc.Fonts.ContainsKey($num)) {
            $doc.Fonts[$num] = newPdfFont $doc (resolvePdf $doc $ref)
        }
        return $doc.Fonts[$num]
    }
    return (newPdfFont $doc $ref)
}

function walkPdfPages {
    # ページツリーをたどり、ページ（@{ Dict; Resources }）を順に pages に足す。
    # 同じノードを 2 度たどる（循環）・深すぎる・ページが多すぎるときは例外
    param (
        [hashtable]$doc,
        $node,
        $inheritedResources,
        [int]$depth,
        $pages
    )

    if ($depth -gt $doc.Limits.MaxDepth) {
        throw "PDFのページの入れ子が深すぎるため読めません。"
    }
    if (testPdfRef $node) {
        if ($doc.SeenNodes.ContainsKey($node["N"])) {
            throw "PDFのページの並びが循環しているため読めません。"
        }
        $doc.SeenNodes[$node["N"]] = $true
    }
    $dict = resolvePdf $doc $node
    if (-not (testPdfDict $dict)) { return }
    $resources = $inheritedResources
    if ($dict.ContainsKey("Resources")) { $resources = $dict["Resources"] }
    if ($dict.ContainsKey("Kids")) {
        $kids = resolvePdf $doc $dict["Kids"]
        foreach ($kid in @($kids)) {
            walkPdfPages $doc $kid $resources ($depth + 1) $pages
        }
        return
    }
    if ($pages.Count -ge $doc.Limits.MaxPages) {
        throw "PDFのページ数が上限を超えるため読めません。"
    }
    $pages.Add(@{ Dict = $dict; Resources = $resources })
}

function readPdfPages {
    # PDF のバイト列から、ページごとの文字列（行は改行で区切る。文字の無いページは空）の配列を返す。
    # 読めない PDF（パスワードが要る・暗号化の方式が未対応・壊れている・上限を超える・読まない圧縮・文字の対応表が無い）は、「PDF」で始まる日本語の例外にする
    param (
        [byte[]]$bytes,
        [hashtable]$limits = $null
    )

    if ($null -eq $limits) { $limits = newPdfLimits }
    try {
        return , (readPdfPagesCore $bytes $limits)
    } catch {
        $message = $_.Exception.Message
        if ($message.StartsWith("PDF")) {
            throw $message
        }
        throw "PDFが壊れているため読めません。"
    }
}

function readPdfPagesCore {
    param (
        [byte[]]$bytes,
        [hashtable]$limits
    )

    $text = ${pdfLatin1}.GetString($bytes)
    if ($text.IndexOf("%PDF-", 0, [Math]::Min(1024, $text.Length), [StringComparison]::Ordinal) -lt 0) {
        throw "PDFではないか、壊れているため読めません。"
    }
    $doc = @{
        Bytes = $bytes; Text = $text; Limits = $limits
        Xref = @{}; Cache = @{}; Loading = @{}; ObjStreams = @{}; Fonts = @{}; Visited = @{}; SeenNodes = @{}
        Inflated = [long]0; XrefRows = [long]0; Searched = [long]0; Root = $null; EndSearch = @{ From = 1; At = 0 }; Hybrid = $false; CMaps = @{}; MapEntries = [long]0
        Crypt = $null; EncryptEntry = $null
    }
    $start = $text.LastIndexOf("startxref", [StringComparison]::Ordinal)
    if ($start -lt 0) {
        throw "PDFの相互参照が見つからないため読めません。"
    }
    $st = newPdfLexer $text ($start + 9)
    $offset = readPdfToken $st
    if ($st.K -ne "num") {
        throw "PDFの相互参照の位置が読めないため読めません。"
    }
    readPdfXref $doc ([long]$offset)
    if ($null -ne $doc.EncryptEntry) {
        $enc = resolvePdf $doc $doc.EncryptEntry
        if (-not (testPdfDict $enc)) {
            throw "PDFの暗号化の情報が壊れているため読めません。"
        }
        $doc.Crypt = newPdfCrypt $doc $enc
    }

    $root = resolvePdf $doc $doc.Root
    if (-not (testPdfDict $root)) {
        throw "PDFの文書の入り口が見つからないため読めません。"
    }
    $pages = [System.Collections.Generic.List[object]]::new()
    walkPdfPages $doc $root["Pages"] $null 0 $pages

    $result = New-Object string[] $pages.Count
    for ($i = 0; $i -lt $pages.Count; $i++) {
        $page = $pages[$i]
        $contents = resolvePdf $doc $page.Dict["Contents"]
        $buffer = [System.IO.MemoryStream]::new()
        foreach ($item in @($contents)) {
            $stream = resolvePdf $doc $item
            if (testPdfStream $stream) {
                $data = getPdfStreamBytes $doc $stream
                $buffer.Write($data, 0, $data.Length)
                $buffer.WriteByte(10)
            }
        }
        $resources = resolvePdf $doc $page.Resources
        $fontDict = $null
        if (testPdfDict $resources) { $fontDict = resolvePdf $doc $resources["Font"] }
        $result[$i] = readPdfPageText $doc (${pdfLatin1}.GetString($buffer.ToArray())) $fontDict
    }
    return , $result
}

function readPdfFile {
    # PDF ファイルを読み、ページごとの文字列の配列を返す（readPdfPages）。
    # 大きさが maxBytes を超えるときは読まずに例外にする
    param (
        [string]$path,
        [long]$maxBytes = ${pdfFileMaxBytes},
        [hashtable]$limits = $null
    )

    if ([System.IO.FileInfo]::new((toLongPath $path)).Length -gt $maxBytes) {
        throw "ファイルサイズが大きすぎるため更新できません。"
    }
    $bytes = [System.IO.File]::ReadAllBytes((toLongPath $path))
    return , (readPdfPages $bytes $limits)
}

# TSV のファイルの読み書き（状態層）。整形の中身（formatTsv）は text.ps1（判断層）。

function prettyTsv {
    # Excelが出力したTSV（UTF-16）を整形してUTF-8で保存する。内容が空なら保存せず $false を返す
    #   firstRow, firstColumn: Excelが出力した範囲の左上のセルの行・列番号
    param (
        [string]$inputFilePath,
        [string]$outputFilePath,
        [int]$firstRow = 1,
        [int]$firstColumn = 1
    )

    $content = formatTsv ([System.IO.File]::ReadAllText((toLongPath $inputFilePath))) $firstRow $firstColumn
    if ($content -eq "") {
        return $false
    }

    [System.IO.File]::WriteAllText((toLongPath $outputFilePath), "${content}`r`n", ${utf8Bom})
    return $true
}

# フォルダのパス（正規化・同一判定・ドライブ・フォルダ選択の開始フォルダ）。

function normalizeFolderPath {
    # フォルダパスを1つの書き方にそろえる（書き方の違いで同じフォルダを別のフォルダとみなさないため）。
    #   ・前後の空白・" を取り除く
    #   ・環境変数（%USERPROFILE% など）を展開する
    #   ・/ を \ にそろえ、長いパス用の \\?\ ・ \\?\UNC\ を外す（ファイル操作に渡す直前に toLongPath で付け直す）
    #   ・重なった \ ・ . ・ .. を解決する
    #   ・相対パスはツールのフォルダ（$rootDir）からとみなして絶対パスにする
    #   ・末尾の \ を取り除く（ドライブ直下は "D:\" のまま。UNC の共有直下は "\\server\share"）
    # パスとして解釈できない場合（* ? を含む・共有名の無い \\server など）は、書かれたとおりに扱う
    param (
        [string]$path
    )

    $path = $path.Trim().Trim('"').Trim()
    if ($path -eq "") {
        return ""
    }
    if ($path.IndexOf("%") -ge 0) {
        $path = [System.Environment]::ExpandEnvironmentVariables($path).Trim()
    }
    $path = (fromLongPath ($path.Replace("/", "\"))).TrimEnd("\")
    if ($path -eq "") {
        return ""
    }
    # ドライブ名だけ（"D:"）はドライブ直下とする。
    # GetFullPath はそのドライブの「現在のフォルダ」を返すことがあるため、先に決める
    if ($path -match "^[A-Za-z]:$") {
        return "${path}\"
    }
    try {
        if (![System.IO.Path]::IsPathRooted($path)) {
            # 相対パスはツールのフォルダからとみなす
            $path = [System.IO.Path]::GetFullPath([System.IO.Path]::Combine(${rootDir}, $path)).TrimEnd("\")
        } elseif ($path -match "^[A-Za-z]:\\" -or $path.StartsWith("\\")) {
            $path = [System.IO.Path]::GetFullPath($path).TrimEnd("\")
        }
        # \ ひとつで始まるパス（"\server\share"）は、書き間違えた UNC パスのことが多いため、
        # 今のドライブのパスに直さず、書かれたとおりに扱う
    } catch {
        # パスとして解釈できない場合は、書かれたとおりに扱う（存在しないフォルダとして扱われる）
    }
    if ($path -match "^[A-Za-z]:$") {
        return "${path}\"
    }
    return $path
}

function getPathUnderFolder {
    # path が folder 自身か folder の下なら、folder からの相対パス（folder 自身は ""）を返す。
    # folder の下でなければ $null（大文字・小文字は区別しない）。
    # パスの文字数で切り出すと、書き方が少し違うだけ（末尾の \ ・\\?\ 付きなど）で取り違えるため、この関数を通す
    param (
        [string]$path,
        [string]$folder
    )

    $folder = $folder.TrimEnd("\")
    $path = $path.TrimEnd("\")
    if ($folder -eq "" -or $path -eq "") {
        return $null
    }
    if ($path.Equals($folder, [System.StringComparison]::OrdinalIgnoreCase)) {
        return ""
    }
    if ($path.StartsWith("${folder}\", [System.StringComparison]::OrdinalIgnoreCase)) {
        return $path.Substring($folder.Length + 1)
    }
    return $null
}


# ドライブ文字の割り当て先（ネットワークドライブ）は CIM で調べる（getDriveTargets 参照）。
# ※以前は Win32 API（QueryDosDevice）で subst も解決していたが、実行時コンパイル（csc.exe）を無くすため CIM に変更した。

${driveTargets} = $null


function testAnyNetworkPath {
    # 一覧の中にネットワークのパスが 1 つでもあるか（インデックスの一覧・設定にネットワークのパスがあるときだけ、
    # 起動時にドライブの割り当てを裏の列で照会するために使う）
    param (
        [string[]]$paths
    )

    foreach ($path in $paths) {
        if (testNetworkPath $path) {
            return $true
        }
    }
    return $false
}

function setDriveTargets {
    # getDriveTargets のキャッシュを外から設定する。ネットワークを調べる列で照会した結果を、
    # 画面のスレッドのキャッシュに入れるために使う（画面のスレッドで CIM を照会しないようにする）
    param (
        $targets
    )

    ${script:driveTargets} = $targets
}

function getDriveTargets {
    # ドライブ文字（"Z:"）→ 割り当て先（ネットワークドライブは "\\server\share"）を返す。
    # 同じプロセスでは1回だけ調べる（インデックス作成・検索の途中で割り当てが変わることは想定しない）。
    # subst で割り当てたドライブは解決しない（CIM で取れないため。実運用ではネットワークドライブが主）。
    if ($null -ne ${script:driveTargets}) {
        return ${script:driveTargets}
    }
    $map = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::OrdinalIgnoreCase)
    try {
        # DriveType=4 はネットワークドライブ。DeviceID="Z:"、ProviderName="\\server\share"
        foreach ($d in @(Get-CimInstance -ClassName Win32_LogicalDisk -Filter "DriveType=4" -ErrorAction SilentlyContinue)) {
            if ($d.ProviderName) {
                $map[$d.DeviceID] = $d.ProviderName.TrimEnd("\")
            }
        }
    } catch {
        # 調べられない環境では別名なしとする（パスを書かれたとおりに使う）
    }
    ${script:driveTargets} = $map
    return $map
}

function getFolderPathAliases {
    # 同じ場所を指す別の書き方を、path 自身を先頭にして返す（ドライブの割り当てをたどる）。
    # ファイルサーバーのフォルダは、ネットワークドライブ（Z:\…）と UNC パス（\\server\share\…）のどちらでも書けるため、
    # 設定に書いた書き方と、インデックスに記録した書き方が違っても同じフォルダと分かるようにする。
    #   Z: が \\server\share のネットワークドライブのとき
    #     "Z:\見積"             → @("Z:\見積", "\\server\share\見積")
    #     "\\server\share\見積" → @("\\server\share\見積", "Z:\見積")
    param (
        [string]$path,
        $drives = (getDriveTargets)  # ドライブ文字 → 割り当て先（テストで差し替える）
    )

    $result = New-Object System.Collections.Generic.List[string]
    $result.Add($path)
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    [void]$seen.Add($path.TrimEnd("\"))

    foreach ($entry in $drives.GetEnumerator()) {
        $alias = $null
        # ドライブ文字 → 割り当て先
        $rest = getPathUnderFolder $path $entry.Key
        if ($null -ne $rest) {
            $alias = if ($rest -eq "") { $entry.Value } else { joinSourcePath $entry.Value $rest }
        } else {
            # 割り当て先 → ドライブ文字
            $rest = getPathUnderFolder $path $entry.Value
            if ($null -ne $rest) {
                $alias = if ($rest -eq "") { "$($entry.Key)\" } else { joinSourcePath "$($entry.Key)\" $rest }
            }
        }
        if ($alias -and $seen.Add($alias.TrimEnd("\"))) {
            $result.Add($alias)
        }
    }
    return $result.ToArray()
}

function testSameFolder {
    # 2つのパスが同じフォルダを指すか（末尾の \ ・大文字と小文字の違いと、ネットワークドライブ・subst の割り当てをたどる）
    param (
        [string]$a,
        [string]$b,
        $drives = $null  # ドライブ文字 → 割り当て先（テストで差し替える。$null は getDriveTargets）
    )

    $target = $b.TrimEnd("\")
    # 書き方どおりに同じなら、ドライブの割り当て（CIM。初回は 0.2 秒以上、切断されたネットワークドライブがあるとさらにかかる）を調べない
    if ($a.TrimEnd("\").Equals($target, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $true
    }
    if ($null -eq $drives) {
        # getDriveTargets（CIM）が返す別名はネットワークドライブ⇔UNCの組しか無いため、
        # どちらかがローカル（ネットワークでない）なら、別名を調べても一致しえない。CIM を照会しない
        if (!(testNetworkPath $a) -or !(testNetworkPath $b)) {
            return $false
        }
        $drives = getDriveTargets
    }
    foreach ($alias in @(getFolderPathAliases $a $drives)) {
        if ($alias.TrimEnd("\").Equals($target, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $true
        }
    }
    return $false
}

function testFolderUnder {
    # path が folder 自身か folder の下のフォルダかを返す（testSameFolder と同じく、書き方の違い・ドライブの割り当てをたどる）。
    # クロール対象フォルダが入れ子になると、同じファイルが2つのインデックスに入り、検索結果にも二重に出るため、その確認に使う
    param (
        [string]$path,
        [string]$folder,
        $drives = $null  # ドライブ文字 → 割り当て先（テストで差し替える。$null は getDriveTargets）
    )

    if ($path -eq "" -or $folder -eq "") {
        return $false
    }
    # 書き方どおりに下にあれば、ドライブの割り当て（CIM）を調べない
    if ($null -ne (getPathUnderFolder $path $folder)) {
        return $true
    }
    if ($null -eq $drives) {
        # testSameFolder と同じ理由で、どちらかがローカルなら CIM を照会しない
        if (!(testNetworkPath $path) -or !(testNetworkPath $folder)) {
            return $false
        }
        $drives = getDriveTargets
    }
    foreach ($alias in @(getFolderPathAliases $path $drives)) {
        if ($null -ne (getPathUnderFolder $alias $folder)) {
            return $true
        }
    }
    return $false
}

function testNetworkPath {
    # パス（normalizeFolderPath 済み）がネットワークの場所を指すかを、共有に接続せずに見分ける。
    #   \\server\share\… ・\\?\UNC\… は UNC（ネットワーク）。
    #   \\?\C:\…（toLongPath の形）・\\.\… は \\ で始まるが UNC ではないため、ドライブ文字として扱う。
    #   ドライブ文字なら DriveInfo.DriveType を見る（GetDriveType は共有に接続しない）。
    #   Fixed・Removable・CDRom・Ram だけをローカルとし、Network と、切断したドライブがそう見えることのある
    #   NoRootDirectory・Unknown は、安全な側に倒してネットワークとする
    #   driveType: ドライブの種類を引く関数（テストで差し替える）。既定は実際の DriveInfo
    param (
        [string]$path,
        [scriptblock]$driveType = { param ($drive) ([System.IO.DriveInfo]$drive).DriveType }
    )

    if ($path -eq "") {
        return $false
    }
    $p = $path.Replace("/", "\")
    if ($p.StartsWith("\\?\UNC\")) {
        return $true
    }
    $rest = $p
    if ($p.StartsWith("\\?\") -or $p.StartsWith("\\.\")) {
        $rest = $p.Substring(4)
    } elseif ($p.StartsWith("\\")) {
        return $true  # \\server\share\…（UNC）
    }
    if ($rest -notmatch "^[A-Za-z]:") {
        return $false  # ドライブ文字が無い（相対パスなど）はローカルとみなす
    }
    $drive = "$($rest.Substring(0, 1)):\"
    try {
        $type = & $driveType $drive
    } catch {
        return $true  # 調べられなければ安全な側（ネットワーク）に倒す
    }
    return $type -notin @([System.IO.DriveType]::Fixed, [System.IO.DriveType]::Removable, [System.IO.DriveType]::CDRom, [System.IO.DriveType]::Ram)
}

function testLocalDrivePath {
    # パス（normalizeFolderPath 済み）が「ドライブ文字で始まり、ネットワークでない」= ローカルのドライブと分かるかを返す。
    # 共有に接続せずに見分ける。UNC・デバイス名の形（\.\UNC\… など）・相対パス・空は偽（testNetworkPath は
    # \.\ をドライブ文字の形として見るため、それだけではデバイス名の形を見分けられない）
    #   driveType: testNetworkPath と同じ（テストで差し替える）
    param (
        [string]$path,
        [scriptblock]$driveType = { param ($drive) ([System.IO.DriveInfo]$drive).DriveType }
    )

    return ($path -match '^[A-Za-z]:\\') -and !(testNetworkPath $path $driveType)
}


# ---- フォルダ選択の開始フォルダ ----


function getExistingAncestorFolder {
    # folder が今もあればそのまま、無ければその上の今もあるフォルダを返す（フォルダ選択を開く場所）。どこにも無ければ空。
    #   skipNetwork: $true なら、ネットワークのパスは調べずに空を返す（画面のスレッドで届かない共有に触らないため）
    param (
        [string]$folder,
        [bool]$skipNetwork = $false
    )

    if ($skipNetwork -and (testNetworkPath $folder)) {
        return ""
    }
    $dir = $folder
    while ($dir) {
        if (Test-Path -LiteralPath (toLongPath $dir) -PathType Container) {
            return $dir
        }
        $dir = Split-Path $dir -Parent
    }
    return ""
}


function getFolderLeafName {
    # フォルダ名（ドライブ直下はドライブ名、UNC の共有直下は共有名）を返す
    param (
        [string]$folderPath
    )

    $path = $folderPath.TrimEnd("\")
    $leaf = [System.IO.Path]::GetFileName($path)
    if ($leaf -eq "") {
        $leaf = $path.TrimEnd(":")
    }
    return $leaf
}

# 配布物の版の記録（VERSION.txt）の読み取り（状態層）。
# 中身は BOM 付き UTF-8・CRLF の2行（1行目: タグ名 / 2行目: コミットの SHA）。
# tools/new_version_text.ps1 が作り、tools/new_release_package.ps1（zip）・tools/new_installer.ps1（インストーラー）が書き込む。
# 作業ツリー（git のチェックアウト）には無く、配布物にだけある。
#
# 単一 .ps1 版（展開せずに動く試験版）は VERSION.txt を持てないため、結合の道具（tools/new_single_script.ps1）が
# 版の文字列を ${bundledVersion}（@{ Tag; Sha }）としてこのファイルより前に埋める。あればファイルを読まずそれを返す

function readVersionFile {
    # ファイルが無い・読めない・形が違うときは $null。あれば @{ Tag; Sha }
    param (
        [string]$path
    )

    $bundled = Get-Variable -Name bundledVersion -ErrorAction SilentlyContinue
    if ($null -ne $bundled) {
        return $bundled.Value
    }

    if (!(Test-Path -LiteralPath $path)) {
        return $null
    }
    try {
        $lines = [System.IO.File]::ReadAllLines($path)
    } catch {
        return $null
    }
    if ($lines.Count -ne 2) {
        return $null
    }
    if ($lines[0] -notmatch '^[A-Za-z0-9._-]+$' -or $lines[1] -notmatch '^[0-9a-f]{40}$') {
        return $null
    }
    return @{ Tag = $lines[0]; Sha = $lines[1] }
}

function resolveGitRef {
    # git のリファレンス（refs/heads/main など）が指すコミットの SHA を返す。無ければ空文字。
    # ファイルを読むだけ（外部プロセスの git は起動しない）。loose（refs\ の下のファイル）を先に見て、無ければ packed-refs を見る。
    #   dirs: 探すフォルダ（worktree の gitdir・共通の gitdir の順）
    param (
        [string]$ref,
        [string[]]$dirs
    )

    if ($ref -notmatch '^refs/[A-Za-z0-9._/-]+$' -or $ref.Contains("..")) {
        return ""
    }
    foreach ($dir in $dirs) {
        $loose = Join-Path $dir ($ref.Replace("/", "\"))
        if (Test-Path -LiteralPath $loose -PathType Leaf) {
            $text = ([System.IO.File]::ReadAllText($loose)).Trim()
            if ($text -match '^[0-9a-f]{40}$') {
                return $text
            }
        }
    }
    foreach ($dir in $dirs) {
        $refListFile = Join-Path $dir "packed-refs"
        if (!(Test-Path -LiteralPath $refListFile -PathType Leaf)) {
            continue
        }
        foreach ($line in [System.IO.File]::ReadAllLines($refListFile)) {
            if ($line -match '^([0-9a-f]{40}) (\S+)$' -and $Matches[2] -ceq $ref) {
                return $Matches[1]
            }
        }
    }
    return ""
}

function readDevVersion {
    # 配布物でない（VERSION.txt が無い）ときの版の手がかりを、作業ツリーの .git のファイルだけから読む。
    # 外部プロセス（git）は起動せず、ファイルを読むだけ。.git が無い・読めない・形が違うときは $null。
    # 返すもの: @{ Tag; AtHead; Sha }
    #   Sha    : HEAD のコミット（分からなければ空）
    #   Tag    : リリースのタグ（v<数>.<数>.<数>）。HEAD のコミットに付いたタグがあればそれ（複数なら版の並びで最も新しい）、
    #            無ければ全タグのうち版の並びで最も新しいもの（無ければ空）
    #   AtHead : Tag が HEAD のコミットに付いているか
    # 「最も新しいタグ」は版の並びで決める。.git のファイルだけでは、タグが HEAD の祖先かどうかは分からず、
    # 別のブランチのタグを拾うことがある（目安の表示のため、それでよい）。
    # 注釈付きタグは、packed-refs の ^ の行（指す先のコミット）で HEAD と照らす。refs\tags の下に置かれた注釈付きタグは、
    # タグの実体を読まないと指す先が分からないため、HEAD に付いた印にはならない（版の並びの比べには使う）。
    # worktree は .git がファイル（gitdir: <パス>）で、HEAD は gitdir に、タグ・packed-refs は commondir（共通の gitdir）にある
    param (
        [string]$rootDir
    )

    try {
        $dotGit = Join-Path $rootDir ".git"
        $gitDir = ""
        if (Test-Path -LiteralPath $dotGit -PathType Container) {
            $gitDir = $dotGit
        } elseif (Test-Path -LiteralPath $dotGit -PathType Leaf) {
            $first = [System.IO.File]::ReadAllLines($dotGit) | Select-Object -First 1
            if ($first -notmatch '^gitdir:\s*(.+)$') {
                return $null
            }
            $target = $Matches[1].Trim()
            if (![System.IO.Path]::IsPathRooted($target)) {
                $target = Join-Path $rootDir $target
            }
            $gitDir = [System.IO.Path]::GetFullPath($target)
        }
        if (!$gitDir -or !(Test-Path -LiteralPath $gitDir -PathType Container)) {
            return $null
        }
        $commonDir = $gitDir
        $commonFile = Join-Path $gitDir "commondir"
        if (Test-Path -LiteralPath $commonFile -PathType Leaf) {
            $common = ([System.IO.File]::ReadAllText($commonFile)).Trim()
            if ($common) {
                $commonDir = [System.IO.Path]::GetFullPath($(if ([System.IO.Path]::IsPathRooted($common)) { $common } else { Join-Path $gitDir $common }))
            }
        }

        # HEAD のコミット
        $sha = ""
        $headFile = Join-Path $gitDir "HEAD"
        if (Test-Path -LiteralPath $headFile -PathType Leaf) {
            $head = ([System.IO.File]::ReadAllLines($headFile) | Select-Object -First 1)
            if ($head -match '^ref:\s*(\S+)$') {
                $sha = resolveGitRef $Matches[1] @($gitDir, $commonDir)
            } elseif ($head -match '^[0-9a-f]{40}$') {
                $sha = $head
            }
        }

        # タグ（名前 → @{ Commit }）。packed-refs（注釈付きタグは次の行の ^ が指す先）を読み、loose のタグで上書きする
        $tags = @{}
        $refListFile = Join-Path $commonDir "packed-refs"
        if (Test-Path -LiteralPath $refListFile -PathType Leaf) {
            $last = ""
            foreach ($line in [System.IO.File]::ReadAllLines($refListFile)) {
                if ($line -match '^([0-9a-f]{40}) refs/tags/(v\d+\.\d+\.\d+)$') {
                    $last = $Matches[2]
                    $tags[$last] = $Matches[1]
                } elseif ($line -match '^\^([0-9a-f]{40})$' -and $last) {
                    $tags[$last] = $Matches[1]
                } else {
                    $last = ""
                }
            }
        }
        $tagsDir = Join-Path $commonDir "refs\tags"
        if (Test-Path -LiteralPath $tagsDir -PathType Container) {
            foreach ($file in @(Get-ChildItem -LiteralPath $tagsDir -File)) {
                if ($file.Name -match '^v\d+\.\d+\.\d+$') {
                    $text = ([System.IO.File]::ReadAllText($file.FullName)).Trim()
                    if ($text -match '^[0-9a-f]{40}$') {
                        $tags[$file.Name] = $text
                    }
                }
            }
        }

        $atHead = ""
        $latest = ""
        foreach ($name in @($tags.Keys)) {
            $isNewer = { param($a, $b) (-not $b) -or ([version]$a.Substring(1)) -gt ([version]$b.Substring(1)) }
            if (& $isNewer $name $latest) {
                $latest = $name
            }
            if ($sha -and $tags[$name] -eq $sha -and (& $isNewer $name $atHead)) {
                $atHead = $name
            }
        }
        if ($atHead) {
            return @{ Tag = $atHead; AtHead = $true; Sha = $sha }
        }
        if (!$latest -and !$sha) {
            return $null
        }
        return @{ Tag = $latest; AtHead = $false; Sha = $sha }
    } catch {
        return $null
    }
}

# 診断情報（ログの先頭の見出し）の組み立て（判断層）。
# ファイル・レジストリ・画面に触らない。調べる側は diagnostics.ps1 の getEnvironmentInfo。
# 利用者名・コンピューター名・ドメイン・パス・ネットワークの情報は、見出しに書かない。

function getVersionLabel {
    # readVersionFile の結果から、版・コミットの表示を決める: @{ Version; Commit（出さないときは空） }
    #   versionInfo: readVersionFile の戻り値（$null なら開発中に git から直接起動したときの表示にする）
    #   devInfo: readDevVersion の戻り値（versionInfo が $null のときだけ使う。タグ・コミットを添える。省くと「開発版」だけ）
    #     HEAD にタグがある: 開発版（v0.5.0・d79f898）/ 無い: 開発版（v0.5.0 より後・d79f898）/ コミットだけ: 開発版（d79f898）
    param (
        $versionInfo,
        $devInfo = $null
    )

    if ($null -eq $versionInfo) {
        $parts = @()
        if ($null -ne $devInfo) {
            $sha = if ($devInfo.Sha) { ([string]$devInfo.Sha).Substring(0, [Math]::Min(7, ([string]$devInfo.Sha).Length)) } else { "" }
            if ($devInfo.Tag) {
                $parts += $(if ($devInfo.AtHead) { [string]$devInfo.Tag } else { "$($devInfo.Tag) より後" })
            }
            if ($sha) {
                $parts += $sha
            }
        }
        if ($parts.Count -eq 0) {
            return @{ Version = "開発版"; Commit = "" }
        }
        return @{ Version = "開発版（$($parts -join '・')）"; Commit = "" }
    }
    return @{ Version = $versionInfo.Tag; Commit = $versionInfo.Sha.Substring(0, 7) }
}

function getOfficeKind {
    # 見つかった Office の実行ファイルのパスから、形態とビット数を決める: @{ Kind = "Click-to-Run" / "MSI"; Bits = 64 / 32 }
    #   programFiles64: 64 ビット側の Program Files / programFilesX86: x86 側の Program Files
    param (
        [string]$exePath,
        [string]$programFiles64,
        [string]$programFilesX86
    )

    $kind = "MSI"
    if ($exePath -match '(?i)\\root\\Office\d+\\') {
        $kind = "Click-to-Run"
    }
    $bits = 64
    if ($programFilesX86 -and $exePath.StartsWith($programFilesX86.TrimEnd("\") + "\", [System.StringComparison]::OrdinalIgnoreCase)) {
        $bits = 32
    }
    return @{ Kind = $kind; Bits = $bits }
}

function hideUserProfile {
    # 文字列の中の利用者のプロファイルのフォルダ（C:\Users\<利用者名>）を %USERPROFILE% に置き換える（大文字小文字は区別しない）。
    # 名前の前方だけが同じ別のフォルダ（末尾に文字が続く名前）は置き換えない
    param (
        [string]$text,
        [string]$profileDir
    )

    if (-not $text -or -not $profileDir) {
        return $text
    }
    $pattern = [regex]::Escape($profileDir.TrimEnd("\")) + '(?![\w.\-])'
    return [regex]::Replace($text, $pattern, '%USERPROFILE%', [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
}

function formatDiagnosticHeader {
    # ログの先頭に書く見出しの行（配列）を返す
    #   toolName: ツールの名前 / versionInfo: readVersionFile の結果 / envInfo: getEnvironmentInfo の結果 / now: 日時（DateTimeOffset）
    param (
        [string]$toolName,
        $versionInfo,
        $envInfo,
        [System.DateTimeOffset]$now,
        $devInfo = $null   # readDevVersion の結果（versionInfo が $null のとき、版にタグ・コミットを添える）
    )

    $unknown = "不明"
    $orUnknown = { param($value) if ($value) { [string]$value } else { $unknown } }
    $label = getVersionLabel $versionInfo $devInfo
    $versionText = $label.Version
    if ($label.Commit) {
        $versionText = "$($label.Version) ($($label.Commit))"
    }
    $bitsText = { param($is64) if ($null -eq $is64) { $unknown } elseif ($is64) { "64 ビット" } else { "32 ビット" } }

    $officeText = "見つからない"
    $officeItems = @($envInfo.Office)
    if ($null -eq $envInfo.Office) {
        $officeText = $unknown
    } elseif ($officeItems.Count -gt 0) {
        $officeText = (@($officeItems | ForEach-Object {
            "$($_.Name) $(& $orUnknown $_.Version) $($_.Kind) $($_.Bits) ビット"
        })) -join " / "
    }

    return @(
        "==== $toolName の診断情報 ===="
        "日時: $($now.ToString('yyyy-MM-dd HH:mm:ss zzz'))"
        "$toolName の版: $versionText"
        "OS: Windows $(& $orUnknown $envInfo.OsVersion)（ntoskrnl $(& $orUnknown $envInfo.OsFileVersion)・$(& $bitsText $envInfo.Os64)）"
        "PowerShell: $(& $orUnknown $envInfo.PsVersion)（$(& $bitsText $envInfo.Ps64)・$(& $orUnknown $envInfo.LanguageMode)）"
        "Office: $officeText"
        "表示言語: $(& $orUnknown $envInfo.UICulture)"
        "===="
    )
}

# 診断情報の収集と、ログの世代の入れ替え（状態層）。
# レジストリ・WMI・COM は使わず、Office も起動しない。ファイルの版情報と .NET・PowerShell の値だけを読む。
# 見出しの文面は diagnostics_view.ps1。

function getEnvironmentInfo {
    # OS・PowerShell・Office の情報を返す。調べられない項目は $null
    $info = @{ OsVersion = $null; OsFileVersion = $null; Os64 = $null; PsVersion = $null; Ps64 = $null; LanguageMode = $null; UICulture = $null; Office = @() }
    try { $info.OsVersion = [Environment]::OSVersion.Version.ToString() } catch {}
    try { $info.Os64 = [Environment]::Is64BitOperatingSystem } catch {}
    try { $info.Ps64 = [Environment]::Is64BitProcess } catch {}
    try { $info.PsVersion = $PSVersionTable.PSVersion.ToString() } catch {}
    try { $info.LanguageMode = [string]$ExecutionContext.SessionState.LanguageMode } catch {}
    try { $info.UICulture = [System.Globalization.CultureInfo]::CurrentUICulture.Name } catch {}
    try {
        $kernel = [System.Diagnostics.FileVersionInfo]::GetVersionInfo("$env:SystemRoot\System32\ntoskrnl.exe")
        $info.OsFileVersion = "$($kernel.FileMajorPart).$($kernel.FileMinorPart).$($kernel.FileBuildPart).$($kernel.FilePrivatePart)"
    } catch {}
    try {
        $info.Office = @(findOfficeApps -os64 ($info.Os64 -ne $false))
    } catch {
        $info.Office = $null   # 調べられなかった（見出しでは「不明」。「見つからない」とは区別する）
    }
    return $info
}

function findOfficeApps {
    # 決まった場所にある Office の実行ファイル（EXCEL.EXE・WINWORD.EXE・POWERPNT.EXE）を探し、@{ Name; Version; Kind; Bits } の配列を返す。
    # Program Files は、Windows のあるドライブ（$env:SystemRoot のドライブ）の決まった名前のフォルダとする
    # （環境変数 ProgramFiles は 32 ビットの PowerShell で x86 側を指し、安全性の検査も SystemRoot 以外の環境変数を許さないため）
    #   programFiles64 / programFilesX86: 探す 2 つの場所（省略すると Windows のあるドライブの決まった名前。テストでは別の場所を渡す）
    #   os64: 64 ビットの Windows か。32 ビットなら programFiles64 の場所を 32 ビット版の置き場として扱う
    # 調べている途中で例外になったら、そのまま投げる（呼び出し側が「不明」にする）
    param (
        [string]$programFiles64,
        [string]$programFilesX86,
        [bool]$os64 = $true
    )

    if (-not $programFiles64 -and -not $programFilesX86) {
        $systemDrive = [System.IO.Path]::GetPathRoot($env:SystemRoot)
        if (-not $systemDrive) {
            throw "Windows のあるドライブを取れない"   # 調べ損ね（見つからないとは別）
        }
        $programFiles64 = Join-Path $systemDrive "Program Files"
        $programFilesX86 = Join-Path $systemDrive "Program Files (x86)"
    }
    $x86Root = $programFilesX86
    if (-not $os64) {
        $x86Root = $programFiles64
    }
    $subDirs = @("Microsoft Office\root\Office16", "Microsoft Office\Office16", "Microsoft Office\Office15")
    $apps = @(@("Excel", "EXCEL.EXE"), @("Word", "WINWORD.EXE"), @("PowerPoint", "POWERPNT.EXE"))
    $found = New-Object System.Collections.Generic.List[object]
    foreach ($app in $apps) {
        $hit = $null
        foreach ($base in @($programFiles64, $programFilesX86)) {
            if (-not $base -or $hit) { continue }
            foreach ($sub in $subDirs) {
                $candidate = Join-Path (Join-Path $base $sub) $app[1]
                if (Test-Path -LiteralPath $candidate -PathType Leaf) {
                    $hit = $candidate
                    break
                }
            }
        }
        if ($hit) {
            $kind = getOfficeKind $hit $programFiles64 $x86Root
            $version = $null
            try { $version = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($hit).FileVersion } catch {}
            $found.Add(@{ Name = $app[0]; Version = $version; Kind = $kind.Kind; Bits = $kind.Bits })
        }
    }
    return $found.ToArray()
}

function getPreviousLogPath {
    # ログの前回の分の名前（<名前>_previous<拡張子>）。同じフォルダに置く
    param (
        [string]$path
    )

    $dir = [System.IO.Path]::GetDirectoryName($path)
    $name = [System.IO.Path]::GetFileNameWithoutExtension($path) + "_previous" + [System.IO.Path]::GetExtension($path)
    return (Join-Path $dir $name)
}

function rotateLogFile {
    # path が maxBytes 以上なら、前回の分（getPreviousLogPath。あれば上書き）に移す。0 はいつも移す。
    # 移したら $true。元が無い・上限未満・移せない（読み取り専用・開いたまま）は $false（例外は出さない）
    param (
        [string]$path,
        [long]$maxBytes
    )

    try {
        if (-not [System.IO.File]::Exists($path)) {
            return $false
        }
        if ($maxBytes -gt 0 -and (New-Object System.IO.FileInfo($path)).Length -lt $maxBytes) {
            return $false
        }
        $previous = getPreviousLogPath $path
        if ([System.IO.File]::Exists($previous)) {
            # 移せない（前回の分が読み取り専用・元が開いたまま・置き場所が対応しない）ときは失敗し、今のログは失わない。
            # 複写で逃げないのは、移せないあいだ書くたびに全量を複写することになるため
            [System.IO.File]::Replace($path, $previous, [NullString]::Value)
        } else {
            [System.IO.File]::Move($path, $previous)
        }
        return $true
    } catch {
        return $false
    }
}

# 取り込み対象にする Office ファイルの拡張子。

# 取り込み対象にする Office ファイルの拡張子（小文字）。
# インデクサ（indexer.ps1）の対象の判定で使う
${officeExtensions} = @(
    ".xlsx", ".xlsm", ".xls", ".xlsb",
    ".docx", ".docm", ".doc",
    ".pptx", ".pptm", ".ppt"
)

# このツールが起動した Excel・Word・PowerPoint の PID の記録と、実行中の Office の一覧・強制終了。
# 止めてよいのは「記録があり、記録と今のプロセスが合うもの」だけ。記録の無いもの（利用者・ほかのアプリのもの）は一覧に出ても止める対象にしない。

# ----------------------------------------------------------------------------
# 検索・Officeプロセス・画面（gui.ps1）で共有する処理
# ----------------------------------------------------------------------------

# 強制終了の対象: プロセス名 → 表示名
${officeProcessNames} = [ordered]@{ EXCEL = "Excel"; WINWORD = "Word"; POWERPNT = "PowerPoint" }

# 書きかけの記録（*.tmp）をこの時間より古ければ消す（書いている最中のものを消さないため）
${officeRecordTmpMaxAge} = [TimeSpan]::FromHours(1)

function getOfficeStartTicks {
    # プロセスの起動時刻（UTC の Ticks）。読めない（管理者として動いているなど）ときは $null
    param (
        $process
    )

    try {
        return [long]$process.StartTime.ToUniversalTime().Ticks
    } catch {
        return $null
    }
}

function testOfficeProcessHasWindow {
    # process に見えている窓があるか（Process.MainWindowHandle が 0 でない）。COM を使わず、相手のプロセスにメッセージも送らないため、固まったプロセスにも戻ってくる。
    # 利用者がそのプロセスを使っているかの見分けに使う（インデックス作成はファイルを窓無しで開くので、自分の取り込みだけなら窓は無い）。
    # 値を取り直してから見る（取り直さないと、前に読んだ値のままになる）。読めない（終わっているなど）ときは $false
    param (
        $process
    )

    try {
        try { $process.Refresh() } catch {}
        $handle = $process.MainWindowHandle
        return ($handle -is [IntPtr] -and $handle -ne [IntPtr]::Zero)
    } catch {
        return $false
    }
}

function compareOfficeProcess {
    # process を、控えたとき（プロセス名・起動時刻）と比べる。"Same"（同じ）・"Different"（別のプロセス）・"Unknown"（分からない）を返す。
    # 先に Handle を読んでプロセスのハンドルを開く（Process が持ち続けるので、このあと同じ process で Kill() するまで、その PID は別のプロセスに使われない）。
    # ハンドルが開けない・控えた起動時刻が無い（$null・0）・今の起動時刻が読めないときは "Unknown"（止めない）。名前か起動時刻が違えば "Different"
    param (
        $process,
        [string]$processName,
        $startTicks
    )

    try {
        if ($null -eq $process.Handle) {
            return "Unknown"
        }
        if ($process.ProcessName -ne $processName) {
            return "Different"
        }
    } catch {
        return "Unknown"
    }
    if ($null -eq $startTicks -or [long]$startTicks -le 0) {
        return "Unknown"
    }
    $actual = getOfficeStartTicks $process
    if ($null -eq $actual) {
        return "Unknown"
    }
    return $(if ([long]$actual -eq [long]$startTicks) { "Same" } else { "Different" })
}

function isSameOfficeProcess {
    # process が、控えたときと同じプロセス（プロセス名と起動時刻が同じ）か。止める前に必ず通す（PID が別のプロセスに使い回されていないかの確認）。
    # 同じと言えるときだけ $true。違う・分からないときは $false（止めない）。比べ方は compareOfficeProcess
    param (
        $process,
        [string]$processName,
        $startTicks
    )

    return ((compareOfficeProcess $process $processName $startTicks) -eq "Same")
}

# ----------------------------------------------------------------------------
# 記録（<ワークスペース>\office_pids\<PC の鍵>\<PID>.txt）
# 1 行・タブ区切り: <プロセス名> <起動時刻の Ticks> <持ち主の PID> <持ち主の起動時刻の Ticks>
# ----------------------------------------------------------------------------

function addOfficeRecord {
    # 起動した Office の記録を 1 つ書く。書けたら $true。場所が空・書けない（共有に届かない・権限が無い）ときは $false（呼ぶ側は取り込みを続ける）。
    # 持ち主は、省けばこのプロセス（記録を書いたプロセス）。書きかけを読ませないよう、.tmp に書いてから名前を変える
    param (
        [string]$dir,
        [int]$id,
        [string]$processName,
        [long]$startTicks,
        [int]$ownerId = 0,
        [long]$ownerStartTicks = 0
    )

    if (!$dir -or $startTicks -le 0) {
        return $false
    }
    $tmp = Join-Path $dir "$id.tmp"
    try {
        if ($ownerId -le 0) {
            $self = [System.Diagnostics.Process]::GetCurrentProcess()
            $ownerId = $self.Id
            $ticks = getOfficeStartTicks $self
            $ownerStartTicks = $(if ($null -ne $ticks) { $ticks } else { 0 })
        }
        [void][System.IO.Directory]::CreateDirectory($dir)
        [System.IO.File]::WriteAllText($tmp, "$processName`t$startTicks`t$ownerId`t$ownerStartTicks", (New-Object System.Text.UTF8Encoding($false)))
        $final = Join-Path $dir "$id.txt"
        [System.IO.File]::Delete($final)
        [System.IO.File]::Move($tmp, $final)
        return $true
    } catch {
        try { [System.IO.File]::Delete($tmp) } catch {}
        return $false
    }
}

function removeOfficeRecord {
    # PID の記録を消す。ファイルが無い・消せないときも失敗にしない（消せなければ次の起動の確認で、PID が無いものとして消える）
    param (
        [string]$dir,
        [int]$id
    )

    if (!$dir) {
        return
    }
    try {
        [System.IO.File]::Delete((Join-Path $dir "$id.txt"))
    } catch {}
}

function readOfficeRecords {
    # 記録を読み、今のプロセスと照らし合わせて @{ Id; ProcessName; StartTicks; OwnerId; OwnerStartTicks; Owned } の配列を返す。
    # Owned: PID があり、名前が同じで、起動時刻が読めて同じ（記録を書いたときのプロセスのまま）。
    # 次のものは、PID が別のプロセスのものになった・無くなった記録なので消す: PID のプロセスが無い・名前が違う・起動時刻が読めて違う。
    # 起動時刻が読めないときは Owned にせず、消しもしない。形の違う記録は使わず、消さない。古い .tmp（書きかけの残り）は消す。
    # フォルダが無い・読めないときは空の配列
    param (
        [string]$dir
    )

    $result = New-Object System.Collections.Generic.List[object]
    if (!$dir) {
        return $result.ToArray()
    }
    try {
        foreach ($tmp in [System.IO.Directory]::GetFiles($dir, "*.tmp")) {
            try {
                if ([System.IO.Path]::GetExtension($tmp) -eq ".tmp" -and
                    ([datetime]::UtcNow - [System.IO.File]::GetLastWriteTimeUtc($tmp)) -gt ${officeRecordTmpMaxAge}) {
                    [System.IO.File]::Delete($tmp)
                }
            } catch {}
        }
        $files = [System.IO.Directory]::GetFiles($dir, "*.txt")
    } catch {
        return $result.ToArray()
    }
    foreach ($file in $files) {
        $id = 0
        $startTicks = [long]0
        $ownerId = 0
        $ownerTicks = [long]0
        try {
            if ([System.IO.Path]::GetExtension($file) -ne ".txt") { continue }
            $fields = ([System.IO.File]::ReadAllText($file).Trim() -split "`t")
            if (!([int]::TryParse([System.IO.Path]::GetFileNameWithoutExtension($file), [ref]$id) -and $id -gt 0 -and $fields.Count -eq 4 -and
                    ${officeProcessNames}.Contains($fields[0]) -and [long]::TryParse($fields[1], [ref]$startTicks) -and $startTicks -gt 0 -and
                    [int]::TryParse($fields[2], [ref]$ownerId) -and [long]::TryParse($fields[3], [ref]$ownerTicks))) {
                continue
            }
        } catch {
            continue
        }
        $process = Get-Process -Id $id -ErrorAction SilentlyContinue
        $owned = $false
        if ($null -eq $process -or $process.ProcessName -ne $fields[0]) {
            removeOfficeRecord $dir $id
            continue
        }
        $actual = getOfficeStartTicks $process
        if ($null -ne $actual) {
            if ($actual -ne $startTicks) {
                removeOfficeRecord $dir $id
                continue
            }
            $owned = $true
        }
        $result.Add([pscustomobject]@{
            Id = $id; ProcessName = $fields[0]; StartTicks = $startTicks; OwnerId = $ownerId; OwnerStartTicks = $ownerTicks; Owned = $owned
        })
    }
    return $result.ToArray()
}

function getOfficeRecordOwner {
    # 記録を書いたプロセス（持ち主）の今の状態: Self（この画面のプロセス）・Other（生きているほかのプロセス）・Gone（もういない）。
    # 持ち主の起動時刻が読めない・記録に無いときは、生きていれば安全な側（Other）にする
    param (
        $record,
        [int]$selfId,
        [long]$selfStartTicks
    )

    if ($record.OwnerId -eq $selfId -and $record.OwnerStartTicks -eq $selfStartTicks) {
        return "Self"
    }
    $owner = Get-Process -Id $record.OwnerId -ErrorAction SilentlyContinue
    if ($null -eq $owner) {
        return "Gone"
    }
    $actual = getOfficeStartTicks $owner
    if ($null -ne $actual -and $record.OwnerStartTicks -gt 0 -and $actual -ne $record.OwnerStartTicks) {
        return "Gone"
    }
    return "Other"
}

# ----------------------------------------------------------------------------
# 一覧と強制終了
# ----------------------------------------------------------------------------

function getOfficeProcesses {
    # 自分のセッションで実行中の Excel・Word・PowerPoint を返す。各要素:
    #   Id・ProcessName・AppName・StartTime（読めなければ $null）・
    #   HasWindow（MainWindowHandle が 0 でない）・
    #   Owned（recordDir の記録があり、記録と今のプロセスの PID・名前・起動時刻が合う。recordDir が空なら常に $false）・
    #   Owner（Owned のとき、記録を書いたプロセスの状態 Self・Other・Gone。Owned でなければ空）
    # 残り物（止めてよいもの）の選び出しは判断層（getLeftoverPrompt）が行う。ここは材料を返すだけ。
    # recordDir を読むため、画面のスレッドでは呼ばない（startJob の中で呼ぶ）。
    # selfId・selfStartTicks は、この画面のプロセスの PID と起動時刻（省けば今のプロセス。テストで差し替える）
    param (
        [string]$recordDir = "",
        [int]$selfId = 0,
        [long]$selfStartTicks = 0
    )

    $current = [System.Diagnostics.Process]::GetCurrentProcess()
    if ($selfId -le 0) {
        $selfId = $current.Id
        $ticks = getOfficeStartTicks $current
        $selfStartTicks = $(if ($null -ne $ticks) { $ticks } else { 0 })
    }
    $records = @{}
    foreach ($record in @(readOfficeRecords $recordDir)) {
        $records[[int]$record.Id] = $record
    }

    $result = New-Object System.Collections.Generic.List[object]
    foreach ($process in @(Get-Process -Name @(${officeProcessNames}.Keys) -ErrorAction SilentlyContinue |
            Where-Object { $_.SessionId -eq $current.SessionId })) {
        $startTime = $null
        try {
            $startTime = $process.StartTime
        } catch {
            # 権限の無いプロセスは起動時刻を取得できない
        }
        $record = $records[[int]$process.Id]
        $owned = ($null -ne $record -and $record.Owned -and $record.ProcessName -eq $process.ProcessName)
        $result.Add([pscustomobject]@{
            Id          = $process.Id
            ProcessName = $process.ProcessName
            AppName     = ${officeProcessNames}[$process.ProcessName]
            StartTime   = $startTime
            HasWindow   = (testOfficeProcessHasWindow $process)
            Owned       = $owned
            Owner       = $(if ($owned) { getOfficeRecordOwner $record $selfId $selfStartTicks } else { "" })
        })
    }
    return $result.ToArray()
}

function stopOfficeProcesses {
    # 指定したプロセスを保存せずに終了し、@{ Id; Stopped; Status; Reason } の配列を返す。
    # targets は getOfficeProcesses の要素（Id・ProcessName・StartTime）。止める直前に、PID が今も同じプロセスか（名前・起動時刻）を照らし直す。
    #   Status: Stopped（止めた）・Changed（名前か起動時刻が違う・読めない・Office の名前でない。止めない）・
    #           Gone（もう無い。止めた扱いにも失敗にもしない）・Failed（止めようとして失敗）
    #   Reason: Changed のときは「PID <N> は確認の後に別のプロセスに変わったため、終了しませんでした。」、Failed のときは例外のメッセージ。それ以外は空
    # recordDir があれば、止めた・もう無いものの記録を消す。プロセスの強制終了は、ここの Stop-Process の 1 か所だけ（tests/meta/safety.Tests.ps1。止める前に isSameOfficeProcess を通す）
    param (
        [object[]]$targets,
        [string]$recordDir = ""
    )

    $results = New-Object System.Collections.Generic.List[object]
    foreach ($target in $targets) {
        $id = [int]$target.Id
        $process = Get-Process -Id $id -ErrorAction SilentlyContinue
        if ($null -eq $process) {
            removeOfficeRecord $recordDir $id
            $results.Add(@{ Id = $id; Stopped = $false; Status = "Gone"; Reason = "" })
            continue
        }
        $expected = $null
        try { $expected = [long]$target.StartTime.ToUniversalTime().Ticks } catch {}
        if (!${officeProcessNames}.Contains([string]$target.ProcessName) -or -not (isSameOfficeProcess $process ([string]$target.ProcessName) $expected)) {
            $results.Add(@{ Id = $id; Stopped = $false; Status = "Changed"; Reason = "PID $id は確認の後に別のプロセスに変わったため、終了しませんでした。" })
            continue
        }
        try {
            Stop-Process -Id $id -Force -ErrorAction Stop
            removeOfficeRecord $recordDir $id
            $results.Add(@{ Id = $id; Stopped = $true; Status = "Stopped"; Reason = "" })
        } catch {
            $results.Add(@{ Id = $id; Stopped = $false; Status = "Failed"; Reason = $_.Exception.Message })
        }
    }
    return $results.ToArray()
}

# 暗号化されたファイルの種類を、開かずに見分ける（判断層）。ファイル・COM・Officeには触らない。
# 入力は「先頭バイト列」と「複合ドキュメント形式（CFB）のディレクトリのエントリ名の配列（CFBでなければ $null）」だけ。
# 実際にファイルを読むのは状態層（office_protection.ps1）。
#
# 種類（getOfficeProtectionKind の戻り値）:
#   Zip      : 新形式（.docx 等）。ふつうに読む
#   Password : パスワード付き（新形式）。Word・PowerPoint は Office を使わずに失敗にする（Excel は今のまま Office に任せる）
#   Rights   : IRM・秘密度ラベルの暗号化。Office で開かない（ライセンス取得・サインイン画面を防ぐ）
#   Legacy   : 旧形式（.doc / .xls / .ppt）など、権限保護と分からないCFB。今と同じ（Officeで開く。ダミーのパスワードで失敗）
#   Text     : 空・RTF・HTML・UTF-8・UTF-16（BOM）など、NULを含まないテキストらしい内容。今と同じ（Officeで開く）
#   Unknown  : 上のどれでもない（先頭4KBにNULを含む）バイナリ。透過暗号化の製品の暗号文の見込みがある。
#              守りを付けてOfficeで開く予備を使う（extract_office.ps1 がアプリごとに切り替える）

${zipSignature}      = [byte[]](0x50, 0x4B, 0x03, 0x04)
${compoundSignature} = [byte[]](0xD0, 0xCF, 0x11, 0xE0, 0xA1, 0xB1, 0x1A, 0xE1)

# 権限保護（IRM・秘密度ラベル）を示すCFBのエントリ名（[MS-OFFCRYPTO] IRMDS）。
#   新形式: DataSpaceInfo配下の DRMEncryptedDataSpace・TransformInfo配下の DRMEncryptedTransform
#   旧形式: 保護された中身の \x09DRMContent（必須）と、\x09DRMDataSpace・\x09DRMTransform
#           （任意で \x09DRMViewerContent・\x09LZXDRMDataSpace・\x09LZXTransform）
${rightsProtectedEntryNames} = @(
    "DRMEncryptedDataSpace", "DRMEncryptedTransform",
    ([char]9 + "DRMContent"), ([char]9 + "DRMDataSpace"), ([char]9 + "DRMTransform"),
    ([char]9 + "DRMViewerContent"), ([char]9 + "LZXDRMDataSpace"), ([char]9 + "LZXTransform")
)
# パスワード保護（ECMA-376 標準・アジャイル暗号化）を示すCFBのエントリ名
${passwordProtectedEntryNames} = @("StrongEncryptionDataSpace", "EncryptionInfo")
# データスペース（新形式のパスワード・権限保護が共通で使うストレージ）の名前
${dataSpacesStorageName} = ([char]6 + "DataSpaces")

function testsByteSignature {
    # $bytes の先頭が $signature と一致するか。
    # 判断層はファイルを開けないため、office_reader.ps1 の isZipFile・isCompoundFile が読むのと同じ印を、
    # 既に読んである先頭バイト列（$bytes）の側で比べる（ファイルを開き直さない）
    param (
        [byte[]]$bytes,
        [byte[]]$signature
    )

    if ($null -eq $bytes -or $bytes.Length -lt $signature.Length) {
        return $false
    }
    for ($i = 0; $i -lt $signature.Length; $i++) {
        if ($bytes[$i] -ne $signature[$i]) {
            return $false
        }
    }
    return $true
}

function testsUnicodeTextBom {
    # UTF-16（Excelのテキスト保存・多くのUnicodeテキストエディタ）の先頭のBOM（FF FE）かどうか
    param (
        [byte[]]$bytes
    )

    return ($null -ne $bytes -and $bytes.Length -ge 2 -and $bytes[0] -eq 0xFF -and $bytes[1] -eq 0xFE)
}

function getOfficeProtectionKind {
    # 先頭バイト列とCFBのエントリ名（CFBでなければ $null）から、暗号化の種類を返す
    param (
        [byte[]]$head,
        [string[]]$cfbNames
    )

    if ($null -eq $head -or $head.Length -eq 0) {
        return "Text"
    }
    if (testsByteSignature $head ${zipSignature}) {
        return "Zip"
    }
    if (testsByteSignature $head ${compoundSignature}) {
        $names = @($cfbNames)
        if (@($names | Where-Object { ${rightsProtectedEntryNames} -contains $_ }).Count -gt 0) {
            return "Rights"
        }
        $hasDataSpaces = ($names -contains ${dataSpacesStorageName})
        $hasPasswordNames = (@($names | Where-Object { ${passwordProtectedEntryNames} -contains $_ }).Count -gt 0)
        if ($hasDataSpaces -and !$hasPasswordNames) {
            # データスペースはあるが、名前を1つも取りこぼした場合。安全側（Officeで開かない）に倒す
            return "Rights"
        }
        if ($hasPasswordNames) {
            return "Password"
        }
        return "Legacy"
    }

    # ZIPでもCFBでもない。先頭4KBにNUL（0x00）を含む（UTF-16のBOMで始まるものを除く）＝形式の分からないバイナリ。
    # 空・RTF（`{\rtf`）・HTML・UTF-8・UTF-16（BOM）は、いずれもNULを含まないテキストのため「Text」になる
    if (testsUnicodeTextBom $head) {
        return "Text"
    }
    if (@($head) -contains [byte]0) {
        return "Unknown"
    }
    return "Text"
}

function getProtectionFailureText {
    # 種類ごとの、取り込み一覧のエラー列に出す短い文言。文言が無い種類（Zip・Legacy・Text）は $null
    param (
        [string]$kind
    )

    switch ($kind) {
        "Password" { return "読み取りパスワードが設定されているため開けません（パスワード付きのファイルは更新できません）" }
        "Rights"   { return "IRM・秘密度ラベルで暗号化されているため更新できません。" }
        "Unknown"  { return "暗号化されているか壊れているため更新できません。" }
        default    { return $null }
    }
}

# Officeが保存した一時ファイル（変換した.docx・.pptx、Excelのテキスト保存）まで、透過暗号化の製品が
# 暗号化した場合の文言。ふつうのファイルでも起こりうるため、すべてのOfficeの出力でこの確認を行う
${officeOutputEncryptedMessage} = "ファイルを暗号化する製品が一時ファイルを暗号化したため更新できません。"

function testOfficeOutput {
    # Officeが保存した出力の先頭バイト列が、期待する形（Zip・UnicodeText）かどうか
    param (
        [byte[]]$head,
        [string]$expectedKind
    )

    if ($expectedKind -eq "Zip") {
        return (testsByteSignature $head ${zipSignature})
    }
    if ($expectedKind -eq "UnicodeText") {
        return (testsUnicodeTextBom $head)
    }
    return $false
}

# Workbook.FileFormat が、テキスト・HTML・CSVとして取り込まれた印の値（xlCSV=6・xlTextMac=19・xlTextWindows=20・
# xlTextMSDOS=21・xlCSVMac=22・xlCSVWindows=23・xlCSVMSDOS=24・xlUnicodeText=42・xlHtml=44・xlCSVUTF8=62・
# xlCurrentPlatformText=-4158）
${excelTextLikeFileFormats} = @(6, 19, 20, 21, 22, 23, 24, 42, 44, 62, -4158)

function testWorkbookFormat {
    # Workbook.FileFormat が、テキスト・HTML・CSVとして取り込まれた印でないか（「形式の分からないバイナリ」のときだけ確かめる。
    # 中身がHTML・CSV等の「Text」の種類のブックには当てない。当てると本来読めているものまで失敗になる）
    param (
        $fileFormat
    )

    return (${excelTextLikeFileFormats} -notcontains $fileFormat)
}

function getWordOpenFormat {
    # 拡張子に合う WdOpenFormat の値。「形式の分からないバイナリ」をWordで開くときだけ渡し、自動判定に任せない
    # （wdOpenFormatDocument=1・wdOpenFormatTemplate=2・wdOpenFormatXMLDocument=9・
    #   wdOpenFormatXMLDocumentMacroEnabled=10・wdOpenFormatXMLTemplate=11・wdOpenFormatAuto=0）
    param (
        [string]$extension
    )

    switch ($extension.ToLowerInvariant()) {
        ".doc"  { return 1 }
        ".dot"  { return 2 }
        ".docx" { return 9 }
        ".docm" { return 10 }
        ".dotx" { return 11 }
        ".dotm" { return 11 }
        default { return 0 }
    }
}

# 暗号化されたファイルの見分け（状態層）: ファイルの先頭バイト列と、複合ドキュメント形式（CFB。[MS-CFB]）の
# ディレクトリのエントリ名を読み、判断層（office_protection_view.ps1）に渡す。
# ファイルを読むだけで、Office・COMには触らない（getOfficeFileProtection を extract_office.ps1 が呼ぶ）。
#
# 壊れたCFB（FATの鎖が輪になる・範囲外のセクター・ディレクトリが途中で切れる）でも例外を出さず、
# 決まった時間で戻る（読める範囲まで返す。ヘッダーさえ読めなければ $null）。
# ディレクトリのエントリ名だけが目的のため、ミニFAT・ストリームの中身は読まない。

${cfbHeadLength}      = 4096          # 先頭バイト列の読み取り量（判断層の判定に使う分）
${cfbFreeSect}        = [uint32]0xFFFFFFFFL
${cfbEndOfChain}      = [uint32]0xFFFFFFFEL
${cfbFatSect}         = [uint32]0xFFFFFFFDL
${cfbDifSect}         = [uint32]0xFFFFFFFCL
${cfbMaxChainSectors} = 200000         # FAT・ディレクトリの鎖をたどる上限（壊れたファイルで止まらないため）

function readFileHead {
    # ファイルの先頭（既定は4096バイト）を読む。開けない・読めなければ空の配列
    param (
        [string]$path,
        [int]$length = ${cfbHeadLength}
    )

    try {
        $stream = [System.IO.File]::OpenRead((toLongPath $path))
    } catch {
        return [byte[]]@()
    }
    try {
        $buffer = New-Object byte[] $length
        $read = $stream.Read($buffer, 0, $length)
        if ($read -eq $length) {
            return $buffer
        }
        $head = New-Object byte[] ([Math]::Max($read, 0))
        if ($read -gt 0) {
            [System.Array]::Copy($buffer, $head, $read)
        }
        return $head
    } catch {
        return [byte[]]@()
    } finally {
        $stream.Dispose()
    }
}

function readUInt32LE {
    # 範囲外なら FREESECT（鎖の終わりと同じ扱いにする安全な既定値）を返す
    param (
        [byte[]]$bytes,
        [int]$offset
    )

    if ($null -eq $bytes -or $offset -lt 0 -or ($offset + 4) -gt $bytes.Length) {
        return ${cfbFreeSect}
    }
    return [System.BitConverter]::ToUInt32($bytes, $offset)
}

function readCfbSector {
    # セクター番号（0起点）1つ分のバイト列。範囲外・読めなければ $null
    param (
        $stream,
        [double]$sectorSize,
        [long]$fileLength,
        [uint32]$secId
    )

    if ($secId -eq ${cfbFreeSect} -or $secId -eq ${cfbEndOfChain} -or $secId -eq ${cfbFatSect} -or $secId -eq ${cfbDifSect}) {
        return $null
    }
    $offset = [int64]$sectorSize * ([int64]$secId + 1)
    if ($offset -lt 0 -or ($offset + $sectorSize) -gt $fileLength) {
        return $null
    }
    try {
        [void]$stream.Seek($offset, [System.IO.SeekOrigin]::Begin)
        $buffer = New-Object byte[] ([int]$sectorSize)
        if ($stream.Read($buffer, 0, [int]$sectorSize) -ne [int]$sectorSize) {
            return $null
        }
        return $buffer
    } catch {
        return $null
    }
}

function getCfbFatSectorIds {
    # FATセクターの並び（順番が、その並びのk番目が担当するセクター番号の範囲を決める索引）を返す。
    # DIFAT（ヘッダーの109件 + DIFATセクターの鎖）だけをたどり、FATセクターの中身はまだ読まない
    # （中身は、ディレクトリの鎖をたどるときに要る分だけ readCfbFatEntry が読む）
    param (
        $stream,
        [byte[]]$header,
        [double]$sectorSize,
        [long]$fileLength
    )

    $entriesPerSector = [int]($sectorSize / 4)
    $fatSectorIds = New-Object 'System.Collections.Generic.List[uint32]'
    for ($i = 0; $i -lt 109; $i++) {
        $value = readUInt32LE $header (76 + $i * 4)
        if ($value -ne ${cfbFreeSect}) {
            $fatSectorIds.Add($value)
        }
    }

    $difatSec = readUInt32LE $header 68
    $seenDifat = New-Object 'System.Collections.Generic.HashSet[uint32]'
    $steps = 0
    while ($difatSec -ne ${cfbEndOfChain} -and $difatSec -ne ${cfbFreeSect} -and $steps -lt ${cfbMaxChainSectors} -and $seenDifat.Add($difatSec)) {
        $buffer = readCfbSector $stream $sectorSize $fileLength $difatSec
        if ($null -eq $buffer) {
            break
        }
        $entriesInSector = $entriesPerSector - 1
        for ($i = 0; $i -lt $entriesInSector; $i++) {
            $value = readUInt32LE $buffer ($i * 4)
            if ($value -ne ${cfbFreeSect}) {
                $fatSectorIds.Add($value)
            }
        }
        $difatSec = readUInt32LE $buffer ($entriesInSector * 4)
        $steps++
    }
    return $fatSectorIds
}

function readCfbFatEntry {
    # セクター番号1つ分の、FATの次のセクター番号を返す。
    # そのセクター番号を持つFATセクター（$fatSectorIds の何番目か）だけを読み、$fatCache に貯めて使い回す
    # （旧形式のふつうのファイルでもディレクトリの判定のたびに動くため、FAT全体を毎回読まない）
    param (
        $stream,
        [double]$sectorSize,
        [long]$fileLength,
        [System.Collections.Generic.List[uint32]]$fatSectorIds,
        [System.Collections.Generic.Dictionary[int, byte[]]]$fatCache,
        [uint32]$secId
    )

    $entriesPerSector = [int]($sectorSize / 4)
    $position = [int]([Math]::Floor([double]$secId / $entriesPerSector))
    if ($position -lt 0 -or $position -ge $fatSectorIds.Count) {
        return ${cfbFreeSect}
    }
    if (!$fatCache.ContainsKey($position)) {
        $fatCache[$position] = readCfbSector $stream $sectorSize $fileLength $fatSectorIds[$position]
    }
    $buffer = $fatCache[$position]
    if ($null -eq $buffer) {
        return ${cfbFreeSect}
    }
    $offset = ([int]($secId % $entriesPerSector)) * 4
    return readUInt32LE $buffer $offset
}

function readCfbDirectoryEntryNames {
    # ディレクトリ（ルート・ストレージ・ストリーム）のエントリ名を、鎖をたどって集める
    param (
        $stream,
        [double]$sectorSize,
        [long]$fileLength,
        [System.Collections.Generic.List[uint32]]$fatSectorIds,
        [uint32]$firstDirSector
    )

    $names = New-Object 'System.Collections.Generic.List[string]'
    $entriesPerSector = [int]($sectorSize / 128)
    $fatCache = New-Object 'System.Collections.Generic.Dictionary[int, byte[]]'
    $seen = New-Object 'System.Collections.Generic.HashSet[uint32]'
    $sec = $firstDirSector
    $steps = 0
    while ($sec -ne ${cfbEndOfChain} -and $sec -ne ${cfbFreeSect} -and $steps -lt ${cfbMaxChainSectors} -and $seen.Add($sec)) {
        $buffer = readCfbSector $stream $sectorSize $fileLength $sec
        if ($null -eq $buffer) {
            break
        }
        for ($i = 0; $i -lt $entriesPerSector; $i++) {
            $entryOffset = $i * 128
            $nameLength = [System.BitConverter]::ToUInt16($buffer, $entryOffset + 64)
            if ($nameLength -ge 2 -and $nameLength -le 64) {
                $name = [System.Text.Encoding]::Unicode.GetString($buffer, $entryOffset, $nameLength - 2)
                if ($name -ne "") {
                    $names.Add($name)
                }
            }
        }
        $sec = readCfbFatEntry $stream $sectorSize $fileLength $fatSectorIds $fatCache $sec
        $steps++
    }
    return $names
}

function readCompoundEntryNames {
    # CFBのディレクトリのエントリ名の配列を返す。CFBでない・読めない・壊れている場合は $null
    # （判断層は $null を、権限保護と分からない「旧形式」として扱う）
    param (
        [string]$path
    )

    try {
        $stream = [System.IO.File]::OpenRead((toLongPath $path))
    } catch {
        return $null
    }
    try {
        $fileLength = $stream.Length
        if ($fileLength -lt 512) {
            return $null
        }
        $header = New-Object byte[] 512
        if ($stream.Read($header, 0, 512) -ne 512) {
            return $null
        }
        $signature = [byte[]](0xD0, 0xCF, 0x11, 0xE0, 0xA1, 0xB1, 0x1A, 0xE1)
        for ($i = 0; $i -lt 8; $i++) {
            if ($header[$i] -ne $signature[$i]) {
                return $null
            }
        }

        $sectorShift = [System.BitConverter]::ToUInt16($header, 30)
        if ($sectorShift -ne 9 -and $sectorShift -ne 12) {
            return $null
        }
        $sectorSize = [double][Math]::Pow(2, $sectorShift)
        $firstDirSector = readUInt32LE $header 48

        $fatSectorIds = getCfbFatSectorIds $stream $header $sectorSize $fileLength
        return @(readCfbDirectoryEntryNames $stream $sectorSize $fileLength $fatSectorIds $firstDirSector)
    } catch {
        return $null
    } finally {
        $stream.Dispose()
    }
}

function getOfficeFileProtection {
    # ファイルを読み、暗号化の種類（getOfficeProtectionKind の戻り値）を返す
    param (
        [string]$path
    )

    $head = readFileHead $path
    $cfbNames = readCompoundEntryNames $path
    return getOfficeProtectionKind $head $cfbNames
}

# 設定を先に読み込む（ワークスペースは設定の workspaceFolder で決まる。paths.ps1 の initWorkspace を
# 起動口（startGui・invokeIndexerMain）が壊れた設定ファイルの退避の後に呼んで決める）
# tebunko のログの先頭に書く見出しと、インデックス作成のログの書き口（状態層）。shared/ がツールの名前を知らないよう、名前はここで渡す。

function getToolDiagnosticHeader {
    # 見出しの行（配列）。版は配布物の VERSION.txt（無ければ開発版。.git のファイルから分かるタグとコミットを添える）
    $version = readVersionFile "${rootDir}\VERSION.txt"
    $devInfo = if ($null -eq $version) { readDevVersion ${rootDir} } else { $null }
    return formatDiagnosticHeader "tebunko" $version (getEnvironmentInfo) ([System.DateTimeOffset]::Now) $devInfo
}

# インデックス作成のログ（invokeIndexer が開く TextWriter。取り込みのスレッドでは 1 ファイル分を貯める StringWriter）
$script:indexerLog = $null
# ログをコンソールにも出すか（画面を使わずに indexer.ps1 を実行したとき）
$script:indexerEcho = $false

function writeIndexerLog {
    # インデックス作成の表示内容をログ（indexing_log.txt）に書く。color はコンソールに出すときの色
    param (
        [string]$text = "",
        [string]$color = ""
    )

    if ($null -ne $script:indexerLog) {
        try {
            $script:indexerLog.WriteLine($text)
        } catch {
            # ログのためだけの書き込みのため、書けなくてもインデックス作成は続ける
        }
    }
    if ($script:indexerEcho) {
        if ($color) {
            Write-Host $text -ForegroundColor $color
        } else {
            Write-Host $text
        }
    }
}

# setting.config の読み書き（tebunko の設定）。

# ツールの ID（多重起動の防止・ミューテックスの名前に使う）。
# 起動口（gui.ps1・indexer.ps1）が lib.ps1 より先に、このファイルだけを読み込んで設定を確かめる（repairBrokenSettings）ため、ここで決める
${appId} = "tebunko"

function getDefaultWorkDir {
    # 既定のワークスペース（%USERPROFILE%\Documents\tebunko_ws）。高速検索のため、Windows Search の索引の対象になる場所に置く。
    # OneDrive にリダイレクトされた「ドキュメント」ではなく、プロファイルの直下の Documents を使う（インデックスが同期でクラウドに上がらないように）
    # 環境変数 TEBUNKO_DEFAULT_WORKSPACE に絶対パスが入っていれば、それを既定のワークスペースにする（開発・確かめ用。
    # テストや実機の確かめが、利用者の既定のワークスペースに触れないようにするための差し替えの口）。入っているのに絶対パスでなければ、
    # 黙って既定のワークスペースに戻らないよう例外にする。引数 profileDir を渡したときは、環境変数を見ない
    param (
        [string]$profileDir = [System.Environment]::GetFolderPath("UserProfile")
    )

    $override = $env:TEBUNKO_DEFAULT_WORKSPACE
    if (!$PSBoundParameters.ContainsKey("profileDir") -and ![string]::IsNullOrWhiteSpace($override)) {
        $override = $override.Trim()
        # ドライブ直下だけ（C:\）やサーバー名だけ（\\server\）は、末尾の区切りを削ると別の意味になるため受け付けない
        if ($override -notmatch '^([A-Za-z]:[\\/]+[^\\/]|\\\\[^\\/]+[\\/]+[^\\/])') {
            throw "TEBUNKO_DEFAULT_WORKSPACE はフォルダまで含めた絶対パスで指定してください: $override"
        }
        return $override.TrimEnd("\", "/")
    }

    return Join-Path $profileDir "Documents\tebunko_ws"
}

function getSettingsFilePath {
    # 設定ファイルのパス。ツールのフォルダに書き込めればそこ、書き込めないとき（Program Files・読み取り専用の共有フォルダ）は
    # 既定のワークスペースの直下に置く（shared\core\data_dir.ps1 の getDataDir）。設定はワークスペースの場所を読む前に見つかる必要があるため、
    # ワークスペースを別の場所に移しても、設定は既定のワークスペースに残る
    param (
        [string]$root,
        [string]$defaultWorkDir
    )

    return Join-Path (getDataDir $root $defaultWorkDir) "setting.config"
}

# 設定ファイル（画面が読み書きする。インデクサはクロール対象フォルダと work の置き場所を読む）。内容は JSON。
# ツールのフォルダに書き込めないときは、既定のワークスペースの直下に置く
${settingsFile} = getSettingsFilePath ${rootDir} (getDefaultWorkDir)

function testSettingsFileName {
    # 設定ファイルと、それに付いてできるファイルの名前か（setting.config・保存の途中で止まると残る setting.config.tmp・
    # 壊れた設定の退避 setting.config.broken-<日時>（同じ名前があれば -2・-3… が付く））。
    # 既定のワークスペースの空の判定では、これらを tebunko のファイルとして数えない
    param (
        [string]$name
    )

    $base = [regex]::Escape([System.IO.Path]::GetFileName(${settingsFile}))
    return [bool]($name -imatch "^${base}(\.tmp|\.broken-\d{8}-\d{6}(-\d+)?)?$")
}

# 検索結果から元のファイルを開くときの開き方（設定 openMode の値）
${openModeNormal}   = "normal"    # そのまま開く（編集する）
${openModeReadOnly} = "readOnly"  # 読み取り専用で開く（誤って上書きしない）
${openModeNew}      = "new"       # 新規（元のファイルを基にした無題の文書）で開く。元のファイルを占有しない
${openModes}        = @(${openModeNormal}, ${openModeReadOnly}, ${openModeNew})

# インデックス作成で、クラウドにだけあるファイル（OneDrive・SharePoint のオンデマンド）をどうするか（設定 cloudFiles の値）
${cloudFilesAsk}      = "ask"       # ダウンロードせずに残す（確認の画面で、ダウンロードして取り込むかを選べる）
${cloudFilesDownload} = "download"  # 確認なしでダウンロードして取り込む
${cloudFilesModes}    = @(${cloudFilesAsk}, ${cloudFilesDownload})

# 検索の対象にするファイルの種類（検索バーのチップ。設定ファイルの fileKinds の値）
${fileKindNames} = @("excel", "word", "powerpoint", "text", "pdf")

function newSettings {
    # 設定の既定値。設定ファイル（JSON）のキーと同じ
    return [ordered]@{
        targetFolders      = @()      # クロール対象フォルダ: @{ name（インデックス名）; path（今フォルダが置かれている場所）; enabled }（記載順。enabled が false は登録のみで取り込まない）
        indexSources       = @()      # 取り込まないインデックスの元のフォルダ: @{ name; path }（別のPC・場所で作ったインデックスを検索するとき）
        searchExcludes     = @()      # 画面の検索対象ツリーでチェックを外したフォルダ: @{ path（フルパス）; subfolders（false はフォルダ直下のファイルだけ） }
        fileKinds          = @()      # 検索の対象にするファイルの種類（excel・word・powerpoint・text の配列。キーが無い・空ならすべて。readFileKinds）
        useRegex           = $false   # 検索ワードを正規表現として扱う
        caseSensitive      = $false   # 英字の大文字と小文字を区別する
        includeShapes      = $true    # 図形（テキストボックス等）の文字も検索する（場所 "<元の場所>[図形]"。index_name.ps1 の objectPlacePattern）
        includeComments    = $true    # コメントも検索する（場所 "<元の場所>[コメント]"）
        openMode           = ${openModeNormal}  # 検索結果の元のファイルの開き方: 通常（編集する）/ 読み取り専用 / 新規（元のファイルを基にした無題の文書。占有しない）
        workspaceFolder    = ""       # ワークスペース（インデックス・取り込み一覧・ログを置くフォルダ）。空なら既定（%USERPROFILE%\Documents\tebunko_ws。getDefaultWorkDir）
        cloudFiles         = ${cloudFilesAsk}  # クラウドにだけあるファイルの扱い: ask（ダウンロードせずに残す。確認の画面で選べる）/ download（ダウンロードして取り込む）。知らない値は ask（readCloudFiles）
        ingestThreads      = 0        # Office を使わずに読むファイル（.docx・.pptx など）の読み取りのスレッドの数（1～4。0 はコア数から決める。getIngestWorkerCount）。Excel・Word・PowerPoint は種類ごとに 1 つ
    }
}

function readSettings {
    # 設定を newSettings と同じ形で返す。記載の無い項目は既定値。設定ファイルが無ければ既定値
    param (
        [string]$path = ${settingsFile}
    )

    $settings = newSettings
    if (!(Test-Path -LiteralPath $path)) {
        return $settings
    }

    # ロック・共有違反などの読み込みの失敗（IOException）は、壊れているのではないため、そのまま例外にする
    $json = [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8)
    if ($json.Trim() -eq "") {
        return $settings
    }
    try {
        $data = ConvertFrom-Json $json
    } catch {
        # JSON として読めない（壊れている）ときは FormatException にする。ファイルは動かさない（退避は repairBrokenSettings が行う）
        throw (New-Object System.FormatException("$([System.IO.Path]::GetFileName($path)) を読み込めません。（$($_.Exception.Message)）"))
    }
    # 中身が null だけなら、空のファイルと同じく既定値（配列・数値だけのときと同じ扱い）
    if ($null -eq $data) {
        return $settings
    }
    foreach ($key in @($settings.Keys)) {
        $property = $data.PSObject.Properties[$key]
        if ($null -eq $property -or $null -eq $property.Value) {
            continue
        }
        if ($settings[$key] -is [array]) {
            $settings[$key] = @($property.Value | Where-Object { $null -ne $_ })
        } elseif ($settings[$key] -is [string]) {
            $settings[$key] = [string]$property.Value
        } elseif ($settings[$key] -is [int]) {
            # 数値。手で書き換えて数値にできないときは既定値
            $number = 0
            if ([int]::TryParse([string]$property.Value, [ref]$number)) {
                $settings[$key] = $number
            }
        } else {
            $settings[$key] = toSettingBool $property.Value $settings[$key]
        }
    }
    return $settings
}

function repairBrokenSettings {
    # 設定ファイルが JSON として読めないとき（ConvertFrom-Json の失敗だけ。空・null だけのファイルは今までどおり既定値で読むため対象外）、
    # 元の中身のまま setting.config.broken-<yyyyMMdd-HHmmss> に移し（同じ名前があれば -2・-3… を付けて、前の退避を上書きしない）、移したパスを返す。
    # 移すと設定ファイルが無くなり、既定値で起動できる。壊れていない・無いときは何もせず空文字を返す。
    # 移せなかったときは例外にする（壊れたファイルを残したまま既定値で上書きしないため）。
    # readSettings はファイルを動かさない。起動口（gui.ps1・indexer.ps1）が、起動の時に 1 回だけ呼ぶ
    param (
        [string]$path = ${settingsFile}
    )

    return invokeSettingsLocked -path $path -action {
        if (!(Test-Path -LiteralPath $path)) {
            return ""
        }
        $json = [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8)
        if ($json.Trim() -eq "") {
            return ""
        }
        try {
            $null = ConvertFrom-Json $json
            return ""
        } catch {
            # 壊れている。下で退避する
        }

        $brokenBase = "${path}.broken-" + (Get-Date).ToString("yyyyMMdd-HHmmss")
        $brokenPath = $brokenBase
        $serial = 2
        while (Test-Path -LiteralPath $brokenPath) {
            $brokenPath = "${brokenBase}-${serial}"
            $serial++
        }
        try {
            [System.IO.File]::Move($path, $brokenPath)
        } catch {
            throw "$([System.IO.Path]::GetFileName($path)) が壊れているため退避しようとしましたが、移せませんでした。tebunko を使っているほかのプログラム（ウイルス対策ソフトなど）を確かめてください。（$($_.Exception.Message)）"
        }
        return $brokenPath
    }
}

function getSettingsRecoveryMessage {
    # 壊れた設定ファイルを退避して既定の設定で起動したときの知らせの文言（画面の起動時・画面なしのインデクサで共通）。
    # brokenPath は repairBrokenSettings が返した、退避したファイルのパス
    param (
        [string]$brokenPath
    )

    return "設定ファイルが壊れていたため、既定の設定で起動しました。ワークスペースの場所・登録したフォルダなども既定に戻っています。`n元に戻すには、tebunko を閉じてから、退避したファイル（${brokenPath}）を直して setting.config に置き換え、開き直してください。"
}

function toSettingBool {
    # 設定ファイルの真偽値を読む。手で書き換えた "false" などの文字列は [bool] にすると $true になるため、
    # 文字列は true / false として読み、読めなければ既定値（default）にする
    param (
        $value,
        [bool]$default
    )

    if ($value -is [string]) {
        $parsed = $false
        if ([bool]::TryParse($value.Trim(), [ref]$parsed)) {
            return $parsed
        }
        return $default
    }
    return [bool]$value
}

function writeSettings {
    param (
        $settings,
        [string]$path = ${settingsFile}
    )

    # 書き込みの途中で止まっても設定ファイルが壊れないよう、一時ファイルに書いてから置き換える（BOM なし UTF-8）
    writeTextLinesAtomic $path @((ConvertTo-Json -InputObject $settings -Depth 5)) (New-Object System.Text.UTF8Encoding($false))
}

function invokeSettingsLocked {
    # 設定ファイルの「読む → 変える → 書く」の一続きを、ほかの画面・インデクサ（別のプロセスも）と同時に行わないよう、
    # 設定ファイルごとの名前付きミューテックスの中で action を実行する（同じスレッドの入れ子は通す）。
    # action の出力を返す。5 秒待っても取れなければ例外（invokeWithNamedMutex）
    param (
        [string]$path,
        [scriptblock]$action,
        [int]$timeoutMilliseconds = 5000
    )

    $lockKey = getFolderKey ([System.IO.Path]::GetFullPath($path))
    return invokeWithNamedMutex "Local\${appId}_settings_${lockKey}" $timeoutMilliseconds $action
}

function updateSettings {
    # 設定ファイルを読み直して key の値だけを変えて保存する（ほかの項目は、ほかの画面・処理が保存した内容を保つ）
    param (
        [string]$key,
        $value,
        [string]$path = ${settingsFile}
    )

    invokeSettingsLocked -path $path -action {
        $settings = readSettings $path
        $settings[$key] = $value
        writeSettings $settings $path
    }
}

function getTargetFolders {
    # クロール対象フォルダの一覧（記載順）を返す: @{ Name; Path; Enabled }。
    #   Name   : インデックス名（work\index 直下のフォルダ名）。インデックスの「名前」で、フォルダの置き場所（Path）とは分けて持つ。
    #            Path を書き換えても Name が同じなら同じインデックスとして扱う（取り込み直さない）。空なら取り込み時に割り当てる（assignIndexNames）
    #   Path   : そのフォルダが今置かれている場所
    #   Enabled: false はチェックなし（登録のみで取り込まない）
    # 同じフォルダ・同じ名前は最初のものだけ使う（名前の重複は、2 つ目以降を空にして割り当て直す）。
    # 書き方が違うだけで同じフォルダを指す場合（ネットワークドライブと UNC パスなど）も同じフォルダとみなす
    param (
        [string]$path = ${settingsFile}
    )

    $folders = New-Object System.Collections.Generic.List[object]
    $seenPath = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $seenName = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($item in @((readSettings $path).targetFolders)) {
        $folder = normalizeFolderPath ([string]$item.path)
        if ($folder -eq "" -or -not $seenPath.Add($folder)) {
            continue
        }
        if (@($folders | Where-Object { testSameFolder $_.Path $folder }).Count -gt 0) {
            continue
        }
        $name = toSafeFileName ([string]$item.name).Trim()
        if ($name -ne "" -and -not $seenName.Add($name)) {
            $name = ""
        }
        $folders.Add([pscustomobject]@{ Name = $name; Path = $folder; Enabled = ($item.enabled -ne $false) })
    }
    return $folders.ToArray()
}

function writeTargetFolders {
    # クロール対象フォルダの一覧（@{ Name; Path; Enabled } の配列）を保存する
    param (
        [object[]]$folders,
        [string]$path = ${settingsFile}
    )

    updateSettings "targetFolders" ([object[]]@($folders | Where-Object { $_ } | ForEach-Object {
        [pscustomobject]@{ name = [string]$_.Name; path = $_.Path; enabled = [bool]$_.Enabled }
    })) $path
}

function mergeAssignedIndexNames {
    # 今の設定のクロール対象フォルダ（current。getTargetFolders の形）に、インデクサ・画面が割り当てたインデックス名（assigned。
    # assignIndexNames の結果）を反映した一覧を返す。インデクサが始めに読んだ一覧を丸ごと書き戻すと、その間の画面での変更を消すため、
    # 書き戻す直前に読み直した一覧へ、割り当てた名前だけを足す。
    # 突き合わせる鍵はパス（大文字と小文字は区別しない）。名前は、今の一覧で名前が空の項目にだけ付ける。
    # 同じ名前をほかの項目が使っていれば付けない（空のまま。次の機会に割り当て直す）
    param (
        [object[]]$current,
        [object[]]$assigned
    )

    $assignedNames = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($item in @($assigned | Where-Object { $_ -and $_.Name })) {
        $assignedNames[[string]$item.Path] = [string]$item.Name
    }
    $used = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($item in @($current | Where-Object { $_ -and $_.Name })) {
        [void]$used.Add([string]$item.Name)
    }

    $result = New-Object System.Collections.Generic.List[object]
    foreach ($item in @($current | Where-Object { $_ })) {
        $name = [string]$item.Name
        if ($name -eq "" -and $assignedNames.ContainsKey([string]$item.Path) -and $used.Add($assignedNames[[string]$item.Path])) {
            $name = $assignedNames[[string]$item.Path]
        }
        $result.Add([pscustomobject]@{ Name = $name; Path = $item.Path; Enabled = $item.Enabled })
    }
    return $result.ToArray()
}

function saveAssignedIndexNames {
    # 割り当てたインデックス名（assigned。assignIndexNames の結果）を設定に保存し、保存した一覧（@{ Name; Path; Enabled }）を返す。
    # 設定を読み直し（ほかの画面・インデクサの変更を保つ）、mergeAssignedIndexNames で名前だけを足して書く（読む → 書くを排他の中で行う）。
    # 名前を付けられなかった項目（同じ名前をほかの項目が使っている・ほかが先に名前を付けた）は、返す一覧でも設定のとおり（空か、先に付いた名前）
    param (
        [object[]]$assigned,
        [string]$path = ${settingsFile}
    )

    return invokeSettingsLocked -path $path -action {
        $merged = @(mergeAssignedIndexNames @(getTargetFolders $path) $assigned)
        writeTargetFolders $merged $path
        return $merged
    }
}

function readIndexSources {
    # 取り込まないインデックスの元のフォルダ（indexSources）を @{ Name; Path } の配列で返す。
    # 別の PC・場所で作ったインデックスを検索するとき、そのインデックス名の元のフォルダを覚えておくために使う
    param (
        [string]$path = ${settingsFile}
    )

    $items = New-Object System.Collections.Generic.List[object]
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($item in @((readSettings $path).indexSources)) {
        $name = ([string]$item.name).Trim()
        $folder = normalizeFolderPath ([string]$item.path)
        if ($name -eq "" -or $folder -eq "" -or -not $seen.Add($name)) {
            continue
        }
        $items.Add([pscustomobject]@{ Name = $name; Path = $folder })
    }
    return $items.ToArray()
}

function writeIndexSources {
    param (
        [object[]]$sources,
        [string]$path = ${settingsFile}
    )

    updateSettings "indexSources" ([object[]]@($sources | Where-Object { $_ } | ForEach-Object {
        [pscustomobject]@{ name = $_.Name; path = $_.Path }
    })) $path
}

function setIndexSourceFolder {
    # インデックス名に対する元のフォルダ（今そのフォルダが置かれている場所）を設定に記録する。
    # クロール対象フォルダにある名前ならそのパスを書き換え、無ければ indexSources に記録する。
    # 「名前」と「置き場所」を分けて持つため、フォルダを移した場合もこの 1 か所を書き換えるだけで済む
    param (
        [string]$name,
        [string]$folder,
        [string]$path = ${settingsFile}
    )

    # 名前は文字の並びそのもの（大文字・小文字だけ区別しない）で比べる。-eq はカルチャに従い、ソフトハイフンなどを無視して
    # 別の名前（利用者自身の対象フォルダ）に一致してしまう。前後の空白（全角空白を含む）がある名前は、読み込み（readIndexSources）で
    # 前後を削るため同じ名前として読み戻せない。記録しない（確認の判定と食い違わせない）
    $name = [string]$name
    $folder = normalizeFolderPath $folder
    if (!(testSourceNameRecordable $name) -or $folder -eq "") {
        return
    }

    invokeSettingsLocked -path $path -action {
        $same = { param ($other) [string]::Equals([string]$other, $name, [System.StringComparison]::OrdinalIgnoreCase) }
        $targets = @(getTargetFolders $path)
        if (@($targets | Where-Object { & $same $_.Name }).Count -gt 0) {
            writeTargetFolders @($targets | ForEach-Object {
                if (& $same $_.Name) { [pscustomobject]@{ Name = $_.Name; Path = $folder; Enabled = $_.Enabled } } else { $_ }
            }) $path
            return
        }

        $sources = @(@(readIndexSources $path | Where-Object { !(& $same $_.Name) }) + @([pscustomobject]@{ Name = $name; Path = $folder }))
        writeIndexSources $sources $path
    }
}

${searchOptionKeys} = [ordered]@{
    UseRegex = "useRegex"; CaseSensitive = "caseSensitive"
    IncludeShapes = "includeShapes"; IncludeComments = "includeComments"
}


function readSearchOption {
    # 画面の検索オプションを @{ UseRegex; CaseSensitive; IncludeShapes; IncludeComments } で返す。
    # 設定が無ければ、文字どおり・大文字と小文字を区別しない・図形とコメントも検索する（検索するファイルの種類は readFileKinds）
    param (
        [string]$path = ${settingsFile}
    )

    $settings = readSettings $path
    $option = @{}
    foreach ($name in ${searchOptionKeys}.Keys) {
        $option[$name] = $settings[${searchOptionKeys}[$name]]
    }
    return $option
}

function writeSearchOption {
    # 画面の検索オプションを保存する。option（readSearchOption と同じ形）にある項目だけを変える
    param (
        [hashtable]$option,
        [string]$path = ${settingsFile}
    )

    invokeSettingsLocked -path $path -action {
        $settings = readSettings $path
        foreach ($name in ${searchOptionKeys}.Keys) {
            if ($option.ContainsKey($name)) {
                $settings[${searchOptionKeys}[$name]] = $option[$name]
            }
        }
        writeSettings $settings $path
    }
}

function readFileKinds {
    # 検索の対象にするファイルの種類（${fileKindNames} の値）を、${fileKindNames} の順の配列で返す。
    # キーが無い・空・知らない値だけのときは、すべての種類（絞り込まない）
    param (
        [string]$path = ${settingsFile}
    )

    $chosen = @(@((readSettings $path).fileKinds) | ForEach-Object { ([string]$_).Trim().ToLowerInvariant() })
    $kinds = @(${fileKindNames} | Where-Object { $chosen -contains $_ })
    if ($kinds.Count -eq 0) {
        return @(${fileKindNames})
    }
    return $kinds
}

function writeFileKinds {
    # 検索の対象にするファイルの種類を保存する。知らない値は捨てる（すべての種類を選んでいるときは空で保存する）。
    # 1 つも選んでいないときは保存しない（空は「すべて」の意味で保存の形を変えないため、前に保存した種類のまま）
    param (
        [object[]]$kinds,
        [string]$path = ${settingsFile}
    )

    $chosen = @(${fileKindNames} | Where-Object { @($kinds) -contains $_ })
    if ($chosen.Count -eq 0) {
        return
    }
    if ($chosen.Count -eq ${fileKindNames}.Count) {
        $chosen = @()
    }
    updateSettings "fileKinds" ([object[]]$chosen) $path
}

function readOpenMode {
    # 元のファイルの開き方（${openModes} のいずれか）を返す。設定が無い・知らない値なら「通常」
    param (
        [string]$path = ${settingsFile}
    )

    $mode = (readSettings $path).openMode
    if (${openModes} -contains $mode) {
        return $mode
    }
    return ${openModeNormal}
}

function writeOpenMode {
    param (
        [string]$mode,
        [string]$path = ${settingsFile}
    )

    updateSettings "openMode" $mode $path
}

function readCloudFiles {
    # クラウドにだけあるファイルの扱い（${cloudFilesModes} のいずれか）を返す。設定が無い・知らない値なら ask
    param (
        [string]$path = ${settingsFile}
    )

    $mode = (readSettings $path).cloudFiles
    if (${cloudFilesModes} -contains $mode) {
        return $mode
    }
    return ${cloudFilesAsk}
}

function writeCloudFiles {
    param (
        [string]$mode,
        [string]$path = ${settingsFile}
    )

    updateSettings "cloudFiles" $mode $path
}

# 既定のワークスペースが空でないときの文言（画面の［既定に戻す］・起動時、インデクサで共通）
function getDefaultWorkspaceError {
    param (
        [string]$folder
    )

    return "「${folder}」は空のフォルダではありません。ワークスペースには別の空のフォルダを選んでください（［設定］の［変更…］）。"
}

function testDefaultWorkspace {
    # 既定のワークスペースを使えるか: @{ Usable; Folder; Message }。
    # 使える: 無い（使うときに作る）・空（設定ファイルと、それに付いてできるファイルだけの場合を含む）・前から使っているワークスペース（content_index・前の版の index・ingest_status.tsv がある）。
    # それ以外（ほかのファイルが置いてある）は、インデックスのファイルと混ざるため使わせない
    param (
        [string]$folder = (getDefaultWorkDir)
    )

    $result = @{ Usable = $true; Folder = $folder; Message = "" }
    # 既定の場所がネットワークにある（プロファイルが共有にある・環境変数 TEBUNKO_DEFAULT_WORKSPACE が UNC のパス）ときは、
    # 画面のスレッドで中身を数えない（届かないと止まる）。確かめず、使えるものとして扱う
    if (testNetworkPath $folder) {
        return $result
    }
    if (![System.IO.Directory]::Exists($folder)) {
        return $result
    }
    # 設定ファイルと、それに付いてできるファイルは数えない（既定のワークスペースは、書き込めないときの設定ファイルの置き場所でもある）
    $names = @(foreach ($entry in (selectFirstEntries ([System.IO.Directory]::EnumerateFileSystemEntries($folder)) 1000)) {
        $name = [System.IO.Path]::GetFileName($entry)
        if (-not (testSettingsFileName $name)) { $name }
    })
    if ($names.Count -eq 0 -or ($names -contains "content_index") -or ($names -contains "index") -or ($names -contains [System.IO.Path]::GetFileName($workspace.StatusFile))) {
        return $result
    }
    $result.Usable = $false
    $result.Message = getDefaultWorkspaceError $folder
    return $result
}

function getWorkspaceBlockMessage {
    # 今のワークスペースが既定の場所で、そこにほかのファイルが置いてあるなら、その文言（使えるなら空）。
    # インデックスのファイルと混ざるため、インデックス作成を始めず、［設定］で別のフォルダを選んでもらう
    param (
        [string]$current = $workspace.Dir,
        [string]$defaultDir = (getDefaultWorkDir)
    )

    if (!(testSameFolder $current $defaultDir)) {
        return ""
    }
    return (testDefaultWorkspace $defaultDir).Message
}

function getWorkDir {
    # work の置き場所を返す。設定 workspaceFolder が空なら既定（getDefaultWorkDir）。
    # 手で書いた相対パスは、設定ファイルのフォルダからとみなす
    param (
        [string]$path = ${settingsFile}
    )

    $folder = ([string](readSettings $path).workspaceFolder).Trim()
    if ($folder -eq "") {
        return getDefaultWorkDir
    }
    $folder = [System.Environment]::ExpandEnvironmentVariables($folder)
    return [System.IO.Path]::GetFullPath([System.IO.Path]::Combine([System.IO.Path]::GetDirectoryName($path), $folder)).TrimEnd("\")
}

function writeWorkspaceFolder {
    # work の置き場所を保存する。既定の場所なら空にする（ツールのフォルダを移しても既定のまま付いてくるように）
    param (
        [string]$folder,
        [string]$path = ${settingsFile}
    )

    $folder = ([string]$folder).Trim().TrimEnd("\")
    if ($folder -ne "" -and (testSameFolder $folder (getDefaultWorkDir))) {
        $folder = ""
    }
    updateSettings "workspaceFolder" $folder $path
}

# 検索対象ツリーでチェックを外したフォルダ（設定の searchExcludes）の読み書きと、「フォルダとその下」の比較。
# インデックスの改名・削除（IndexCatalog）、ワークスペースの切り替え（WorkspaceMover）、検索対象ツリーの保存が、同じ部品を通す。
# 設定の読み書きは settings.ps1（invokeSettingsLocked・readSettings・updateSettings）を使う。

function testFolderOrUnder {
    # path が folder そのもの、または folder の下にあるかを返す（フォルダとその下の比較は、ここだけで行う）。
    # 大文字・小文字は区別しない（序数の比較。NTFS と同じ扱いで、文化による同一視はしない）。
    # folder の末尾の \ は無いものとして比べ、"<folder>\" で始まるものだけを「下」にする（Sales の下に Sales2 は入らない）。
    # folder が空なら、どれも含まない
    param (
        [string]$path,
        [string]$folder
    )

    $folder = ([string]$folder).TrimEnd("\")
    if ($folder -eq "" -or $null -eq $path) {
        return $false
    }
    return $path.Equals($folder, [System.StringComparison]::OrdinalIgnoreCase) -or
        $path.StartsWith($folder + "\", [System.StringComparison]::OrdinalIgnoreCase)
}

function readSearchExcludes {
    # 画面の検索対象ツリーでチェックを外したフォルダを @{ Path; Subfolders } の配列で返す（設定が無ければ空 = すべて検索する）。
    #   Subfolders: $true はフォルダ以下すべて、$false はフォルダ直下のファイルだけを外す
    param (
        [string]$path = ${settingsFile}
    )

    $result = New-Object System.Collections.Generic.List[object]
    foreach ($item in @((readSettings $path).searchExcludes)) {
        $folder = ([string]$item.path).Trim().TrimEnd("\")
        if ($folder -eq "") {
            continue
        }
        $subfolders = if ($null -eq $item.subfolders) { $true } else { toSettingBool $item.subfolders $true }
        $result.Add([pscustomobject]@{ Path = $folder; Subfolders = $subfolders })
    }
    return $result.ToArray()
}

function writeSearchExcludes {
    # 検索対象ツリーでチェックを外したフォルダ（@{ Path; Subfolders } の配列）を保存する
    param (
        [object[]]$excludes,
        [string]$path = ${settingsFile}
    )

    updateSettings "searchExcludes" ([object[]]@($excludes | Where-Object { $_ -and $_.Path } | ForEach-Object {
        [ordered]@{ path = [string]$_.Path; subfolders = [bool]$_.Subfolders }
    })) $path
}

function removeSearchExcludesUnder {
    # 検索対象ツリーでチェックを外した記録のうち、folder（インデックスのフォルダ）とその下のものを消す（比較は testFolderOrUnder）。
    # 記録は利便性のための一時的な情報のため、消せなくても例外にしない（インデックスの改名・削除は止めない）。
    # 消す記録が無ければ設定ファイルは書き換えない
    param (
        [string]$folder,
        [string]$path = ${settingsFile}
    )

    $folder = ([string]$folder).Trim().TrimEnd("\")
    if ($folder -eq "") {
        return
    }

    try {
        invokeSettingsLocked -path $path -action {
            $excludes = @(readSearchExcludes $path)
            $kept = @($excludes | Where-Object { -not (testFolderOrUnder $_.Path $folder) })
            if ($kept.Count -lt $excludes.Count) {
                writeSearchExcludes $kept $path
            }
        } | Out-Null
    } catch {
    }
}

function moveSearchExcludes {
    # 検索対象ツリーでチェックを外したフォルダ（searchExcludes。インデックスの下のフルパス）のうち、
    # ワークスペース from の index の下のものを、to の index の下に付け替えて保存する。付け替えた数を返す
    param (
        [string]$from,
        [string]$to,
        [string]$path = ${settingsFile}
    )

    $fromIndex = ([Workspace]::new($from.TrimEnd("\"))).IndexDir
    $toIndex = ([Workspace]::new($to.TrimEnd("\"))).IndexDir
    return invokeSettingsLocked -path $path -action {
        $count = 0
        $excludes = @(readSearchExcludes $path | ForEach-Object {
            $folder = $_.Path
            if (testFolderOrUnder $folder $fromIndex) {
                $folder = $toIndex + $folder.Substring($fromIndex.Length)
                $count++
            }
            [pscustomobject]@{ Path = $folder; Subfolders = $_.Subfolders }
        })
        if ($count -gt 0) {
            writeSearchExcludes $excludes $path
        }
        return $count
    }
}

# ワークスペース（インデックス・取り込み一覧・ログを置くフォルダ）の中の、tebunko が使うファイルの場所。
# 場所はフォルダ（Dir）から組み立てるだけで、設定は読まない。どのフォルダを使うかは設定の workspaceFolder で決まる（settings.ps1 の getWorkDir）。
# 今のワークスペースは paths.ps1 の ${workspace} に置く。別のスレッドへは Dir（文字列）を渡し、そこで作り直す。
# Workspace のメソッドは場所を組み立てるだけなので、.NET の型だけを使う（クラスのメソッドからスクリプトの関数は呼べるが、
# $script: 変数は呼び出し元によって見える範囲が違うため、クラスの本体では読まない。docs/design/structure/classes.md）

class Workspace {
    [string]$Dir
    [string]$IndexDir
    # 前の版（content_index・system_index に名前をそろえる前）が使っていた本文インデックスのフォルダ。
    # 新しい版はここを読まず、消しもしない（前の版のしるしの調べ・知らせ・［設定］で「移す」「消して最初から」の対象にするために持つ）
    [string]$LegacyIndexDir
    # システムインデックス（本文インデックスの 2-gram を書いた txt。index と同じ相対パスの構成。Windows Search に索引させる）と、その状態
    [string]$SystemIndexDir
    [string]$SystemIndexStateFile
    # 取り込んだTSVをインデックスに入れる直前に集めるフォルダ（publishIndexFiles）。
    # フォルダごと入れ替えるため、インデックスと同じドライブ（ワークスペースの中）に置く。
    # 検索対象に入らないよう index の外にする。インデックス作成を同時に複数実行しても混ざらないよう、プロセスごとに分ける
    [string]$PublishDir
    # 取り込み一覧・出力（自動生成）
    [string]$StatusFile
    [string]$IngestingFile  # 取り込み中のファイル。強制終了で残っていれば、そのファイルの取り込み中に止まった
    [string]$ResultFile
    # インデックス作成の記録。画面とインデクサの受け渡しはメモリ上で行う（indexer_state.ps1 の newIndexerChannel）
    [string]$IndexingLogFile  # インデクサの表示内容の記録（実行ごとに上書き）
    [string]$GuiErrorLogFile  # 画面で起きた予期しないエラーの記録（追記。原因を後から追えるようにする。1 MB で下の前回の分に回す）
    [string]$IndexingLogPreviousFile  # 前回のインデックス作成の記録（インデックス作成を始めるとき、今の記録をここへ移す）
    [string]$GuiErrorLogPreviousFile  # 画面エラーの記録の前回の分（1 MB を超えたとき、今の記録をここへ移す）
    # 取り込みの作業フォルダの置き場所（下は <PC の鍵>\<PID>\w<番号> と分かれる。selectTmpDir・getWorkspaceTmpDir）。
    # 前の版までの %TEMP%\tebunko\<PID> の代わりに、ワークスペースの中に置く（共有フォルダでも 1 か所にまとまる）
    [string]$TmpRoot
    # このツールが起動した Office の PID の記録の置き場所（下は <PC の鍵>\<PID>.txt と分かれる。getOfficePidDir・shared/office/office_process.ps1）。
    # 画面を起動したとき、前回残った Office を確認して止めるために使う。tmp の下には置かない（tmp は片付けで消える場所で、記録は画面ごと落ちた後に読むため）
    [string]$OfficePidRoot

    Workspace([string]$dir) {
        $this.Dir = $dir
        $this.IndexDir = "$dir\content_index"
        $this.LegacyIndexDir = "$dir\index"
        $this.SystemIndexDir = "$dir\system_index"
        $this.SystemIndexStateFile = "$dir\system_index_state.tsv"
        $this.PublishDir = "$dir\publish\$([System.Diagnostics.Process]::GetCurrentProcess().Id)"
        $this.StatusFile = "$dir\ingest_status.tsv"
        $this.IngestingFile = "$dir\ingesting.txt"
        $this.ResultFile = "$dir\search_results.txt"
        $this.IndexingLogFile = "$dir\indexing_log.txt"
        $this.GuiErrorLogFile = "$dir\gui_error_log.txt"
        $this.IndexingLogPreviousFile = "$dir\indexing_log_previous.txt"
        $this.GuiErrorLogPreviousFile = "$dir\gui_error_log_previous.txt"
        $this.TmpRoot = "$dir\tmp"
        $this.OfficePidRoot = "$dir\office_pids"
    }

    # ワークスペースを移すときに移すもの（tebunko が作るファイル・フォルダ）。利用者のほかのファイルは含めない。
    # 取り込みの出力（publish）はプロセスごとのフォルダ（PublishDir）の親を移す。
    # LegacyIndexDir は、あれば前の版のワークスペースとして tebunko のものと扱う（あるものだけが WorkspaceMover.ListEntries で拾われる）
    [string[]] Entries() {
        return @($this.IndexDir, $this.LegacyIndexDir, $this.SystemIndexDir, $this.SystemIndexStateFile, $this.StatusFile, $this.IngestingFile,
            $this.ResultFile, $this.IndexingLogFile, $this.GuiErrorLogFile,
            $this.IndexingLogPreviousFile, $this.GuiErrorLogPreviousFile, [System.IO.Path]::GetDirectoryName($this.PublishDir), $this.TmpRoot, $this.OfficePidRoot)
    }
}

# 前の版（content_index・system_index に名前をそろえる前）が system_index に置いていた txt の名前の型。
# 新しい版は system_index.txt を使うため、前の版の txt を見つける・片付けるためだけに使う（読み書きの形式は変えない）
${legacySystemIndexPattern} = "システムインデックス*.txt"

function getMachineKey {
    # この PC を識別する短い鍵（getFolderKey の先頭 8 文字）。
    # 共有フォルダのワークスペースを複数の PC から使うとき、一時フォルダを PC ごとに分けるために使う（getWorkspaceTmpDir）
    return (getFolderKey ([Environment]::MachineName)).Substring(0, 8)
}

function getOfficePidDir {
    # 起動した Office の PID の記録を置くフォルダ（$workspace.OfficePidRoot\<PC の鍵>）を返す。文字列を組み立てるだけで、ファイルには触らない。
    # 共有のワークスペースで、ほかの PC の PID と混ざらないよう PC ごとに分ける
    param (
        [Workspace]$workspace
    )

    return Join-Path $workspace.OfficePidRoot (getMachineKey)
}

function getWorkspaceJobQueue {
    # ネットワークの場所に触るかもしれない startJob の列を決める唯一の関数。
    # paths（ワークスペース・インデックスのフォルダ・元のフォルダ・記録の置き場所など）の中に 1 つでもネットワークの場所があれば、
    # 届かない共有で待たされても他の仕事を巻き込まない専用の列（"network"）、無ければ既定の列（"default"）
    param (
        [string[]]$paths
    )

    return $(if (testAnyNetworkPath $paths) { "network" } else { "default" })
}

function assertWorkspaceReachable {
    # インデックスの削除・名前の変更の裏の仕事の先頭で呼ぶ。ワークスペース（のインデックスのフォルダ）に届かないとき、
    # 例外にする（届かないのに「何もせず成功」にして、設定だけ変えてしまわないため）。無いこと（まだインデックスを作っていない）は例外にしない
    param (
        [string]$dir
    )

    $state = getPathState $dir
    if ($state.State -eq ${pathStateUnreachable}) {
        throw "ワークスペースに接続できません：${dir}"
    }
    if ($state.State -eq ${pathStateOther}) {
        throw "ワークスペースを確かめられません：$($state.Message)"
    }
}

function getWorkspaceTmpDir {
    # 取り込みの作業フォルダの候補（$workspace.TmpRoot\<PC の鍵>\<PID>）を返す。副作用は無い（selectTmpDir が使う）
    param (
        [Workspace]$workspace
    )

    return Join-Path $workspace.TmpRoot (Join-Path (getMachineKey) $PID)
}

function selectTmpDir {
    # 取り込みの作業フォルダの置き場所を決める: @{ Dir; Reason（置けないときだけ） }
    #   候補: getWorkspaceTmpDir（ワークスペースの tmp\ の下）
    #   候補のパスに [ ] があれば、置けない（Dir = ""、Reason = Brackets）。Excel は [ ] を含むパスに保存できないため
    #   候補の長さ + 取り込みのスレッドが下に作る最も長い名前の分（${tmpNameReserve}）が $excelMaxPath 以上でも、
    #     置けない（Dir = ""、Reason = TooLong）。Office は長すぎるパスを開けないため
    #   一時ファイルもワークスペースの下にしか置かない（%TEMP% には逃がさない）。
    #   置けないときは、呼び出し側（initTmpDir）が取り込みをすべてスキップする
    #   （どのファイルも中間 TSV などをこのフォルダに作るため、テキストファイルを含めすべての取り込みが対象になる）
    #   どちらでもなければ候補のまま（Reason = ""）
    param (
        [Workspace]$workspace
    )

    $candidate = getWorkspaceTmpDir $workspace
    if ($candidate.IndexOfAny([char[]]@("[", "]")) -ge 0) {
        return @{ Dir = ""; Reason = "Brackets" }
    }
    if (($candidate.Length + ${tmpNameReserve}) -ge $excelMaxPath) {
        return @{ Dir = ""; Reason = "TooLong" }
    }
    return @{ Dir = $candidate; Reason = "" }
}

function getTmpDirUnavailableMessage {
    # 取り込みの作業フォルダを置けない理由（selectTmpDir の Reason）を、利用者向けの1文にする。
    # initTmpDir のログと、invokeIngestTask が1ファイルごとに書くエラーの両方で使う
    param (
        [string]$reason
    )

    if ($reason -eq "Brackets") {
        return "ワークスペースのパスに [ ]（角かっこ）が含まれるため、更新の作業フォルダを置けません。"
    }
    if ($reason -eq "TooLong") {
        return "ワークスペースのパスが長すぎるため、更新の作業フォルダを置けません。"
    }
    if ($reason -eq "Link") {
        return "ワークスペースの作業領域の途中にリンク（ジャンクション・シンボリックリンク）があるため、更新の作業フォルダを置けません。"
    }
    return "更新の作業フォルダを置けません。"
}

function getLegacyIndexState {
    # 前の版のワークスペース（dir）の状態を返す: @{ HasLegacyIndex; ContentEmpty; HasLegacySystemIndex }
    #   HasLegacyIndex       : 前の版の index\ があり、直下のどれかのフォルダに legacySourceFolderFileName（元のフォルダ.txt）がある（前の版のしるし）。
    #                          index\ があるだけでは、利用者が選んだフォルダにたまたま index があるときと区別できないため、しるしとしない
    #   ContentEmpty         : content_index\ が無いか、下のフォルダを含めてファイルが 1 つも無い
    #   HasLegacySystemIndex : system_index\ の下に前の名前の txt（システムインデックス*.txt）がある。
    #                          ContentEmpty のときだけ調べる（片付けの条件にしか使わないため）
    param (
        [string]$dir
    )

    $ws = [Workspace]::new($dir)
    # 見つけたところで列挙をやめるため、testAnyEntry で調べる（foreach を break で抜けると、調べていたフォルダを
    # 掴んだまま残り、続くインポートの上書きで content_index\<名前> を移動できなくなる）
    $hasLegacyIndex = $false
    $longLegacy = toLongPath $ws.LegacyIndexDir
    if ([System.IO.Directory]::Exists($longLegacy)) {
        $hasLegacyIndex = testAnyEntry ([System.IO.Directory]::EnumerateDirectories($longLegacy)) {
            param ($sub)
            [System.IO.File]::Exists("$sub\${legacySourceFolderFileName}")
        }
    }

    $contentEmpty = $true
    $longContent = toLongPath $ws.IndexDir
    if ([System.IO.Directory]::Exists($longContent)) {
        $contentEmpty = !(testAnyEntry ([System.IO.Directory]::EnumerateFiles($longContent, "*", [System.IO.SearchOption]::AllDirectories)))
    }

    $hasLegacySystemIndex = $false
    if ($contentEmpty) {
        $longSystem = toLongPath $ws.SystemIndexDir
        if ([System.IO.Directory]::Exists($longSystem)) {
            $hasLegacySystemIndex = testAnyEntry ([System.IO.Directory]::EnumerateFiles($longSystem, ${legacySystemIndexPattern}, [System.IO.SearchOption]::AllDirectories))
        }
    }

    return @{ HasLegacyIndex = $hasLegacyIndex; ContentEmpty = $contentEmpty; HasLegacySystemIndex = $hasLegacySystemIndex }
}

function testLegacyCleanupNeeded {
    # 取り込み直しを始めるときに、前の版のシステムインデックスを片付けるかどうか（getLegacyIndexState の結果から決まる）。
    # content_index\ が空で、かつ、前の版のしるしがあるか、system_index\ に前の名前の txt が残っているときに片付ける
    # （取り込み直す前に利用者が index\ を消していても、前の名前の txt を残さないため）
    param (
        $state
    )

    return ($state.ContentEmpty -and ($state.HasLegacyIndex -or $state.HasLegacySystemIndex))
}

function getLegacyIndexMessage {
    # 前の版のワークスペース（index\。しるしあり）が見つかったときの知らせ。しるしが無ければ空
    param (
        [string]$dir,
        [bool]$hasLegacyIndex
    )

    if (!$hasLegacyIndex) {
        return ""
    }
    $legacyDir = [Workspace]::new($dir).LegacyIndexDir
    return "前の版のインデックス（「${legacyDir}」）は、この版では使えません。［すべて更新］で、元のファイルをすべて更新し直します。" +
        "更新し直した後、「${legacyDir}」フォルダは削除してかまいません。"
}

function clearLegacySystemIndex {
    # 前の版のシステムインデックス（system_index\ と、システムインデックスの状態ファイルの中身）を片付ける: @{ Ok; Reason（失敗のときだけ） }
    # 片付けの順番: (1) updateSystemIndexState の排他の中で、状態ファイルの中身を空にする（ファイルは消さない。
    #     画面の検索（fast_search.ps1）やインデックスの削除（index_store.ps1）が同じ排他で書き換えるため、
    #     消した直後に前のキーを書き戻されないようにする）。
    # (2) system_index\ を removeDirectoryRetry で消す（Windows Search が txt を一時的に開くことがあるため）。
    # どちらかに失敗したら Ok = $false（途中で止まっても、次に呼べば同じ状態から続けられる）
    param (
        [string]$dir
    )

    $ws = [Workspace]::new($dir)
    $cleared = updateSystemIndexState {
        param ($state)
        $state.Covered.Clear()
        $state.Pending.Clear()
        $state.Excluded.Clear()
    } $ws.SystemIndexStateFile
    if (!$cleared) {
        return @{ Ok = $false; Reason = "システムインデックスの状態ファイル（$([System.IO.Path]::GetFileName($ws.SystemIndexStateFile))）を開けませんでした" }
    }
    try {
        removeDirectoryRetry $ws.SystemIndexDir
    } catch {
        return @{ Ok = $false; Reason = $_.Exception.Message }
    }
    return @{ Ok = $true; Reason = "" }
}

function newWorkspace {
    # ワークスペースの場所（Dir。文字列）から Workspace を作る。クラスの本体は別のクラスの型を書かないため、クラスから作るときはこれを呼ぶ
    param (
        [string]$dir
    )

    return [Workspace]::new($dir)
}

# ワークスペースの切り替え（中身を移す・消して最初からやり直す・選んだ先のインデックスを使う・searchExcludes の付け替え・保存・失敗したら戻す）。
# 画面（ui\settings\settings.ps1 の applyWorkspace・startWorkspaceMove）は、確かめて利用者に選ばせたあと ChangeWorkspace を呼び、結果を出して画面を切り替えるだけにする。
# ListEntries などの確かめは画面のスレッドで、ChangeWorkspace は裏のスレッド（startWorkspaceMove の startJob）で使う。切り替えの前に、画面は本文インデックスのファイルを読んでいる検索を止める（移せないため）。
#
# クラスの本体では $script: 変数・ほかのクラスの型・呼び出し元の変数を使わない（docs/design/structure/classes.md）。
# 設定ファイルの場所はコンストラクタで受け取る。ワークスペースの中の場所は Workspace（workspace.ps1）から組み立てる。
# searchExcludes の付け替えは、IndexCatalog と同じ部品（search_excludes.ps1 の moveSearchExcludes）を通す。
# メソッドの中のローカル変数は、プロパティと大文字・小文字だけの違いにしない
class WorkspaceMover {
    hidden [string]$SettingsPath

    WorkspaceMover([string]$settingsPath) {
        $this.SettingsPath = $settingsPath
    }

    [string[]] ListEntries([string]$dir) {
        # ワークスペース dir にある、tebunko のファイル・フォルダ（Workspace.Entries のうち、あるもの）のフルパスを返す
        return @((newWorkspace $dir).Entries() | Where-Object {
            $long = toLongPath $_
            [System.IO.Directory]::Exists($long) -or [System.IO.File]::Exists($long)
        })
    }

    [string[]] Conflicts([string]$from, [string]$to) {
        # ワークスペース from の中身を to へ移すとき、to に同じ名前が既にあるもの（移せないもの）の名前を返す
        return @($this.ListEntries($from) | ForEach-Object { [System.IO.Path]::GetFileName($_) } | Where-Object {
            $long = toLongPath (Join-Path $to $_)
            [System.IO.Directory]::Exists($long) -or [System.IO.File]::Exists($long)
        })
    }

    [hashtable] ChangeWorkspace([string]$mode, [string]$from, [string]$to) {
        # ワークスペースを from から to に変える（設定に保存する）。mode:
        #   "use"   … to にあるインデックスを使う。from の中身は移さず、インデックスの一覧を to のものにする
        #   "move"  … from の中身を to へ移す
        #   "reset" … to の tebunko のファイル・フォルダを消してから、from の中身を移す
        # 戻り値: @{ Ok; Stage（失敗した段階。"remove"・"move"）; Message（失敗の理由）; Targets（"use" で使うインデックスの数）; Count（"move"・"reset" で移した数）}。
        # 失敗したときは設定を変えない（移せなかったら、移した分は from に戻してある）
        if ($mode -eq "use") {
            # 共有されたワークスペースなどを使う。今の中身は移さず、インデックスの一覧をこのワークスペースのものにする
            $targets = $this.UseTargets($to)
            writeWorkspaceFolder $to $this.SettingsPath
            return @{ Ok = $true; Stage = ""; Message = ""; Targets = $targets; Count = 0 }
        }
        if ($mode -eq "reset") {
            try {
                [void]$this.RemoveEntries($to)
            } catch {
                return @{ Ok = $false; Stage = "remove"; Message = $_.Exception.Message; Targets = 0; Count = 0 }
            }
        }
        try {
            $count = $this.MoveEntries($from, $to)
        } catch {
            return @{ Ok = $false; Stage = "move"; Message = $_.Exception.Message; Targets = 0; Count = 0 }
        }
        # 検索対象ツリーでチェックを外したフォルダも、移した先のインデックスに付け替える
        [void](moveSearchExcludes $from $to $this.SettingsPath)
        writeWorkspaceFolder $to $this.SettingsPath
        return @{ Ok = $true; Stage = ""; Message = ""; Targets = 0; Count = $count }
    }

    [int] MoveEntries([string]$from, [string]$to) {
        # ワークスペース from の中身（tebunko のファイル・フォルダ）を to へ移し、移した数を返す。ほかのファイルは移さない。
        # to に同じ名前があれば、何も移さずに例外にする。途中で移せなかったら、移した分を from へ戻してから例外にする
        # （どちらかのワークスペースに中身がそろった状態にし、半分ずつに分かれたままにしない）
        $conflicts = @($this.Conflicts($from, $to))
        if ($conflicts.Count -gt 0) {
            throw "「${to}」には、すでに $($conflicts -join '、') があります。空のフォルダを選んでください。"
        }
        $entries = @($this.ListEntries($from))
        [System.IO.Directory]::CreateDirectory((toLongPath $to)) | Out-Null
        $moved = New-Object System.Collections.Generic.List[string]
        try {
            foreach ($source in $entries) {
                $this.MoveEntry($source, (Join-Path $to ([System.IO.Path]::GetFileName($source))))
                $moved.Add($source)
            }
        } catch {
            $reason = $_.Exception.Message
            for ($i = $moved.Count - 1; $i -ge 0; $i--) {
                try {
                    $this.MoveEntry((Join-Path $to ([System.IO.Path]::GetFileName($moved[$i]))), $moved[$i])
                } catch {
                    # 戻せなかったものは、移した先に残る（例外のメッセージで両方の場所を伝える）
                }
            }
            throw "ワークスペースの中身を「${to}」へ移せませんでした（${reason}）。ファイルを開いているアプリを閉じてから、もう一度変えてください。中身は「${from}」に残しています。"
        }
        return $moved.Count
    }

    [int] RemoveEntries([string]$dir) {
        # ワークスペース dir の tebunko のファイル・フォルダ（Workspace.Entries）を削除し、削除した数を返す。ほかのファイルは消さない。
        # ワークスペースに選んだフォルダのインデックスを使わず、消して最初からやり直すときに使う
        $entries = @($this.ListEntries($dir))
        foreach ($entry in $entries) {
            $long = toLongPath $entry
            if ([System.IO.Directory]::Exists($long)) {
                removeDirectoryRetry $entry
            } else {
                [System.IO.File]::Delete($long)
            }
        }
        return $entries.Count
    }

    [int] UseTargets([string]$dir) {
        # ワークスペース dir の取り込み一覧にあるクロール対象フォルダを、インデックスの一覧（設定の targetFolders）にし、その数を返す。
        # ほかの人が作ったワークスペースを使うとき、一覧をそのワークスペースに合わせる（合わせないままインデックス作成をすると、
        # 一覧に無いインデックスは、インデックス更新の確認に「削除予定」として出る。findDroppedIndexes）。取り込み一覧が無ければ一覧は変えない
        $map = getIndexNameMap (newWorkspace $dir.TrimEnd("\")).StatusFile
        if ($map.Count -eq 0) {
            return 0
        }
        writeTargetFolders @($map.Keys | ForEach-Object { [pscustomobject]@{ Name = $_; Path = $map[$_]; Enabled = $true } }) $this.SettingsPath
        return $map.Count
    }

    hidden [void] MoveEntry([string]$source, [string]$dest) {
        # ファイル・フォルダを 1 つ移す。同じドライブならそのまま移し、別のドライブのフォルダは写してから元を消す
        # （Directory.Move は別のドライブへ移せないため）。写している途中で失敗したら、写した分を消して例外にする
        $longSource = toLongPath $source
        $longDest = toLongPath $dest
        if (![System.IO.Directory]::Exists($longSource)) {
            # File.Move は別のドライブへも移せる
            [System.IO.File]::Move($longSource, $longDest)
            return
        }
        if ([System.IO.Path]::GetPathRoot($source) -eq [System.IO.Path]::GetPathRoot($dest)) {
            [System.IO.Directory]::Move($longSource, $longDest)
            return
        }
        try {
            $this.CopyTree($longSource, $longDest)
        } catch {
            removeDirectoryRetry $dest
            throw
        }
        removeDirectoryRetry $source
    }

    hidden [void] CopyTree([string]$source, [string]$dest) {
        # フォルダを中身ごと写す（\\?\ 付きのパスを受け取る）
        [System.IO.Directory]::CreateDirectory($dest) | Out-Null
        foreach ($file in [System.IO.Directory]::GetFiles($source)) {
            [System.IO.File]::Copy($file, [System.IO.Path]::Combine($dest, [System.IO.Path]::GetFileName($file)))
        }
        foreach ($sub in [System.IO.Directory]::GetDirectories($source)) {
            $this.CopyTree($sub, [System.IO.Path]::Combine($dest, [System.IO.Path]::GetFileName($sub)))
        }
    }
}

# ［新規で開く］のためのコピー（テキスト・PDF など、「新規」の開き方が無い種類のファイル）の作成と片付け（状態層）。
# コピーは $workspace.TmpRoot\<PC の鍵>\open_copy\<12 桁の文字>\<元の名前>（コピー yyyyMMdd-HHmm）.<拡張子> に置く（getOpenCopyDir・getOpenCopyName）。
# 片付けは GUI の起動時にだけ行い、1 日より古いものを消す（開いているコピーは消せずに残る。閉じるときには消さない）。
# 作る・消すときは、置き場所がワークスペースの TmpRoot\<PC の鍵>\open_copy そのものであり、リンク（ジャンクション・シンボリックリンク）で
# 外へつながっていないことを確かめてから行う（testOpenCopyDir）。

# open_copy の置き場所の名前（片付けが、消してよい場所かを見るときにも使う）
${openCopyDirName} = "open_copy"
# 開くためのコピーを残す日数（これより古いものを起動時に消す）
${openCopyKeepDays} = 1

function getOpenCopyDir {
    # 開くためのコピーを置くフォルダ（$workspace.TmpRoot\<PC の鍵>\open_copy）を返す。文字列を組み立てるだけで、ファイルには触らない。
    # 取り込みの作業フォルダ（<PC の鍵>\<PID>）と同じ親の下に置くが、名前が数字でないため、取り込みの片付け（removeStaleProcessDirs）は触らない
    param (
        [Workspace]$workspace
    )

    return Join-Path $workspace.TmpRoot (Join-Path (getMachineKey) ${openCopyDirName})
}

function testOpenCopyReparsePoint {
    # path がリンク（ReparsePoint）か。無いパスは $false（まだ作っていない）。属性が読めないなど、確かめられないときは $true（辿らない側に倒す）
    param (
        [string]$path
    )

    try {
        $attributes = [System.IO.File]::GetAttributes((toLongPath $path))
    } catch [System.IO.FileNotFoundException] {
        return $false
    } catch [System.IO.DirectoryNotFoundException] {
        return $false
    } catch {
        return $true
    }
    return [bool]($attributes -band [System.IO.FileAttributes]::ReparsePoint)
}

function testOpenCopyDir {
    # copyDir が、open_copy の置き場所として使ってよいものか。コピーの作成・片付けは、これが真のときだけ行う。
    #   絶対パス（ドライブ付き・UNC）で、途中に .. や余計な区切りを含まず、tmpRoot\<PC の鍵>\open_copy と一致すること
    #   copyDir・その親（<PC の鍵>）・その親（tmpRoot）が、リンク（ReparsePoint）でないこと（まだ無ければ問題にしない）
    # 空・ドライブの直下・相対パス・別の場所の open_copy・リンクの先は $false
    param (
        [string]$copyDir,
        [string]$tmpRoot
    )

    if (!$copyDir -or !$copyDir.Trim() -or !$tmpRoot -or !$tmpRoot.Trim()) {
        return $false
    }
    $trimmed = $copyDir.TrimEnd([char]92, [char]47)
    if ($trimmed -notmatch '^([A-Za-z]:\\|\\\\[^\\])' -or $tmpRoot -notmatch '^([A-Za-z]:\\|\\\\[^\\])') {
        return $false
    }
    try {
        $full = [System.IO.Path]::GetFullPath($trimmed)
        $expected = [System.IO.Path]::GetFullPath((Join-Path (Join-Path $tmpRoot (getMachineKey)) ${openCopyDirName}))
    } catch {
        return $false
    }
    if (![string]::Equals($trimmed, $full, [System.StringComparison]::OrdinalIgnoreCase) -or
        ![string]::Equals($full, $expected.TrimEnd([char]92), [System.StringComparison]::OrdinalIgnoreCase)) {
        return $false
    }
    $keyDir = [System.IO.Path]::GetDirectoryName($full)
    foreach ($checked in @($full, $keyDir, [System.IO.Path]::GetDirectoryName($keyDir))) {
        if (testOpenCopyReparsePoint $checked) {
            return $false
        }
    }
    return $true
}

function getOpenCopyName {
    # 開くためのコピーの名前 <元の名前>（コピー yyyyMMdd-HHmm）.<拡張子>（コピーだと分かる名前にする）。
    # パスの区切りが紛れていても、ファイル名だけを使う。名前が空なら空文字。
    # 同じ名前のコピーが重ならないよう、置く場所は copySourceForOpen が 1 回ごとに別のフォルダにする
    param (
        [string]$book,
        [datetime]$now = (Get-Date)
    )

    $leaf = [System.IO.Path]::GetFileName(([string]$book).TrimEnd('.', ' ').Replace("/", "\"))
    if (!$leaf) {
        return ""
    }
    $extension = [System.IO.Path]::GetExtension($leaf)
    $baseName = $leaf.Substring(0, $leaf.Length - $extension.Length)
    $stamp = $now.ToString("yyyyMMdd-HHmm", [System.Globalization.CultureInfo]::InvariantCulture)
    return "${baseName}（コピー ${stamp}）${extension}"
}

function getOpenCopyBlocker {
    # コピーを作らずに断る理由（ファイルには触らない）。作れるなら空文字。
    #   NoName  … 名前が空
    #   TooLong … コピーのパスが長すぎる（260 文字の制限）
    # 名前に [ ] を含んでも断らない（コピーも開くのも、パスをそのまま（リテラルで）扱う）
    param (
        [string]$book,
        [string]$copyDir,
        [datetime]$now = (Get-Date)
    )

    $name = getOpenCopyName $book $now
    if (!$name) {
        return "NoName"
    }
    # <copyDir>\<12 桁>\<名前>
    if ($copyDir.TrimEnd([char]92).Length + 1 + 12 + 1 + $name.Length -ge 259) {
        return "TooLong"
    }
    return ""
}

function copySourceForOpen {
    # 元のファイルのコピーを copyDir の下に作る（元のファイルは変えない）。@{ Path; Reason } を返す。
    #   作れたとき: Path = コピーのパス、Reason = ""
    #   作れなかったとき: Path = ""、Reason = Place（置き場所の確かめで断った）・NoName／TooLong（getOpenCopyBlocker の結果）・Failed（作る・書くのに失敗した）
    # 同じ名前のコピーが重ならないよう、1 回ごとに別のフォルダ（copyDir\<12 桁の文字>）に置く。名前は getOpenCopyName。
    param (
        [string]$sourcePath,
        [string]$book,
        [string]$copyDir,
        [string]$tmpRoot,
        [datetime]$now = (Get-Date)
    )

    if (!(testOpenCopyDir $copyDir $tmpRoot)) {
        return @{ Path = ""; Reason = "Place" }
    }
    $blocker = getOpenCopyBlocker $book $copyDir $now
    if ($blocker) {
        return @{ Path = ""; Reason = $blocker }
    }
    $name = getOpenCopyName $book $now
    $dir = Join-Path $copyDir ([guid]::NewGuid().ToString("N").Substring(0, 12))
    $destPath = Join-Path $dir $name
    try {
        [System.IO.Directory]::CreateDirectory((toLongPath $dir)) | Out-Null
        copyFileShared $sourcePath $destPath
    } catch {
        return @{ Path = ""; Reason = "Failed" }
    }
    return @{ Path = $destPath; Reason = "" }
}

function getOpenCopyLatestTime {
    # 1 つ下のフォルダの「最後に使った日時」。フォルダの作成・更新と、中のファイルの更新のうち新しいもの
    # （編集して保存したコピーを、作ってから 1 日たったからといってすぐ消さないため）
    param (
        [System.IO.DirectoryInfo]$folder
    )

    $latest = $folder.CreationTime
    if ($folder.LastWriteTime -gt $latest) {
        $latest = $folder.LastWriteTime
    }
    foreach ($copy in @(Get-ChildItem -LiteralPath $folder.FullName -File -Force)) {
        if ($copy.LastWriteTime -gt $latest) {
            $latest = $copy.LastWriteTime
        }
    }
    return $latest
}

function clearOldOpenCopies {
    # copyDir の下の、最後に使ってから keepDays 日より古いコピー（1 つ下のフォルダごと）を消し、消したフォルダの数を返す。
    # 最後に使った日時は getOpenCopyLatestTime。現在より先の日時（時計のずれ）は新しい扱いになり、消さずに残る（消さない側に倒す）。
    # 消すのは open_copy の 1 つ下のフォルダの中のファイルだけ（testOpenCopyDir が偽なら何もしない。フォルダごとに消す直前にも確かめ、偽になっていればそこで止める）。
    # リンク（ジャンクション・シンボリックリンク）は辿らず、使用中で消せないコピーは残す。再帰の削除は使わない
    param (
        [string]$copyDir,
        [string]$tmpRoot,
        [datetime]$now = (Get-Date),
        [int]$keepDays = ${openCopyKeepDays}
    )

    if (!(testOpenCopyDir $copyDir $tmpRoot) -or !(Test-Path -LiteralPath $copyDir -PathType Container)) {
        return 0
    }
    $limit = $now.AddDays(-$keepDays)
    $prefix = $copyDir.TrimEnd([char]92) + "\"
    $cleared = 0
    foreach ($old in @(Get-ChildItem -LiteralPath $copyDir -Directory -Force)) {
        if ($old.Attributes -band [System.IO.FileAttributes]::ReparsePoint) {
            continue
        }
        if (!$old.FullName.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase) -or (getOpenCopyLatestTime $old) -ge $limit) {
            continue
        }
        # 確かめてから消すまでの間に置き場所がリンクに替わっていないか、フォルダごとに消す直前にもう一度確かめる
        if (!(testOpenCopyDir $copyDir $tmpRoot)) {
            break
        }
        # 消すフォルダ自身も、列挙してから消すまでの間にリンクに替わっていないかを確かめる（リンクなら辿らない）
        if (testOpenCopyReparsePoint $old.FullName) {
            continue
        }
        foreach ($copy in @(Get-ChildItem -LiteralPath $old.FullName -File -Force)) {
            if ($copy.Attributes -band [System.IO.FileAttributes]::ReparsePoint) {
                continue
            }
            try {
                [System.IO.File]::SetAttributes((toLongPath $copy.FullName), [System.IO.FileAttributes]::Normal)
                [System.IO.File]::Delete((toLongPath $copy.FullName))
            } catch {
                # 開いているコピーは残す（次の起動で消す）
            }
        }
        try {
            [System.IO.Directory]::Delete((toLongPath $old.FullName), $false)
            $cleared++
        } catch {
            # 中にコピーが残っている（開いている）・既に無い
        }
    }
    return $cleared
}

# 部品（lib・indexerLib）の読み込み先をまとめる。
# zip 版は scripts 配下の実際のファイルを dot-source し、単一 .ps1 版（展開せずに動く試験版）は
# 埋め込んだ部品の文字列（${bundledParts}）を関数（importTebunkoPart）としてランスペースに登録する。
# 設計は docs/design/structure/single-script.md・docs/design/structure/classes.md「クラスのつなぎ方」。
#
# 画面だけのクラス（SearchTarget・IndexNode など、ui\ 配下）は ${bundledParts} に含まれない。背景の
# スレッド・別のランスペースがこの部品だけを読み込んでも、画面のクラスを二重にコンパイルしない
# （PowerShell 5.1 は class を構文解析の時点でそのランスペースの型として登録するため、同じ名前の class を
# 別のランスペースでもう一度解析すると、型が別物になり画面のスレッドとキャストできなくなる）。
#
# 単一 .ps1 版かどうかは、先頭で定義する変数 ${bundledParts} の有無だけで決める
# （結合の道具 tools/new_single_script.ps1 が作る）。
# 別スレッド・別ランスペースで部品を読み込むところは、パスの文字列やソースを直接組み立てず、必ずここを通す。

function getPartLoad {
    # 戻り値は @{ State = <InitialSessionState>; Prelude = <部品を読み込む 1 行の文字列> }。
    # 呼び出し側は、この State でランスペース（または WorkerPool）を作り、Prelude を本体の前につないで
    # （shared\core\worker_pool.ps1 の joinWorkerScript）動かす。
    #
    # zip 版: State はただの既定値、Prelude はそのファイルを dot-source する 1 行。
    # 単一 .ps1 版: State に、埋め込んだ部品の文字列を本体に持つ関数 importTebunkoPart を登録し、
    #   Prelude はその関数を呼ぶだけの 1 行（". importTebunkoPart"）。関数の本体は、その State で
    #   ランスペースを作ったときに 1 回だけ構文解析される
    param (
        [ValidateSet("lib", "indexerLib")]
        [string]$name,
        # 部品を読み込んだあとに続けて呼ぶ文（例: initWorkspace）。空なら足さない
        [string]$then = ""
    )

    $state = [System.Management.Automation.Runspaces.InitialSessionState]::CreateDefault2()
    $bundled = Get-Variable -Name bundledParts -ErrorAction SilentlyContinue
    if ($null -ne $bundled -and $bundled.Value) {
        $body = $bundled.Value[$name]
        if ($null -eq $body) {
            throw "単一 .ps1 版に ${name} の部品が入っていません。"
        }
        $entry = New-Object System.Management.Automation.Runspaces.SessionStateFunctionEntry("importTebunkoPart", $body)
        $state.Commands.Add($entry)
        # 部品の中（version.ps1 の readVersionFile など）が ${bundledScriptPath}・${bundledVersion} を見るため、
        # 呼び出したスレッドの値をそのまま渡す（bundledParts も渡す。取り込みのスレッドの中でもう一度 getPartLoad を呼ぶため）
        foreach ($varName in "bundledParts", "bundledScriptPath", "bundledVersion") {
            $variable = Get-Variable -Name $varName -ErrorAction SilentlyContinue
            if ($null -ne $variable) {
                $variableEntry = New-Object System.Management.Automation.Runspaces.SessionStateVariableEntry($varName, $variable.Value, "")
                $state.Variables.Add($variableEntry)
            }
        }
        $prelude = ". importTebunkoPart"
        if ($then) { $prelude = "$prelude; $then" }
        return @{ State = $state; Prelude = $prelude }
    }

    # indexerLib は、取り込みのスレッド・インデクサの司令のスレッドの両方から使うため、
    # 関数（indexer_lib.ps1）と、呼び出す口（invokeIndexerMain・indexer_main.ps1）をまとめて読み込む
    $paths = switch ($name) {
        "lib" { @("$PSScriptRoot\..\lib.ps1") }
        "indexerLib" { @("$PSScriptRoot\..\indexer\indexer_lib.ps1", "$PSScriptRoot\..\indexer\indexer_main.ps1") }
    }
    $prelude = ($paths | ForEach-Object {
        # 一重引用符の文字（' と、PowerShell が同じ引用符として扱う U+2018・U+2019・U+201A・U+201B）は、重ねて文字列の中に入れる
        $resolved = [regex]::Replace([System.Management.Automation.WildcardPattern]::Escape([System.IO.Path]::GetFullPath($_).Replace('`', '``')), "(['\u2018\u2019\u201A\u201B])", '$1$1')
        ". '$resolved'"
    }) -join "; "
    if ($then) { $prelude = "$prelude; $then" }
    return @{ State = $state; Prelude = $prelude }
}

# tebunko が使うファイルの場所と、そこに書く値の定義。

# 取り込みの作業フォルダ（本体はワークスペースの tmp\ の下。index_migrate.ps1 の initTmpDir が
# インデックス作成の始めに selectTmpDir で決めて入れる）。決めるまでの既定値は空。
# 置けなかったとき（パスに [ ] がある・長すぎる）も空のまま（どのファイルも中間 TSV などをこのフォルダに作るため、
# テキストファイルを含めすべての取り込みをスキップする。%TEMP% には逃がさない）
${tmpDir} = ""
# ${tmpDir} を置けなかった理由（selectTmpDir の Reason）。置けたときは空
${tmpDirReason} = ""

# 前の版（%TEMP%\tebunko\<PID> に一時ファイルを置いていた版）が残した作業フォルダの片付け専用。
# 今の版はここには書き込まない（removeStaleTmpDirs が、強制終了などで残った前の版のフォルダを消すためだけに使う）
${legacyTmpParent} = Join-Path ([System.IO.Path]::GetTempPath()) "tebunko"

# Excelで開けるパスの長さの目安（古い版の上限）。作業フォルダの候補がこれ以上ならワークスペースの tmp\ を諦める
$excelMaxPath = 218
# 取り込みのスレッドが作業フォルダの下に作る、最も長いファイル名の分（"\w999\converted.pptx"）。
# selectTmpDir で、この分を足しても $excelMaxPath を超えないかを見る
${tmpNameReserve} = "\w999\converted.pptx".Length

# ワークスペース（インデックス・取り込み一覧・ログ・取り込みの出力の置き場所。中の場所は workspace.ps1 の Workspace）。
# setting.config の workspaceFolder で変えられる。空なら既定（settings.ps1 の getWorkDir）。
# 読み込んだとき（スクリプトの読み込み時）には決めず、起動口（startGui・invokeIndexerMain）が
# 壊れた設定ファイルの退避の後に呼ぶ（単一 .ps1 版は setting.config を読む前に読み込みだけ先に済ませるため）
function initWorkspace {
    ${script:workspace} = [Workspace]::new((getWorkDir))
}

# 取り込みのスレッドが、司令のスレッドから受け取った場所（Workspace）を、呼んだスクリプトのスコープに置く。
# $workspace を決めるのはこのファイルだけにするため、取り込みのスレッドのスクリプトからもここを呼ぶ
# （取り込みのスレッドでは、呼んだスコープは global。部品を読み込んだのと同じスコープになる）
function setCallerWorkspace {
    param (
        $value
    )

    Set-Variable -Name workspace -Value $value -Scope 1
}

# インデックスのフォルダに置く、インデックス名とクロール対象フォルダの対応（インデクサが作成する）。
# インデックスのフォルダごと別の場所・PCへコピーしても、検索結果から元のファイルの場所が分かるようにする。
# 拡張子を .tsv にすると検索対象になるため .txt にする
${sourceFolderFileName} = "source_folder.txt"

# 前の版(ワークスペースのファイル名を英語化する前)の元のフォルダの記録。
# getLegacyIndexState が旧版の index\ フォルダを見分けるためだけに使う。読み取り専用。
${legacySourceFolderFileName} = "元のフォルダ.txt"

# インデックス作成の進み具合の段階（writeIndexingProgress の phase）
${indexingPhaseCrawl}   = "クロール"  # 取り込み対象のファイルを探している（件数はまだ分からない）
${indexingPhaseConfirm} = "確認"      # 取り込み対象を数え終え、画面で取り込むかどうかを選ぶのを待っている
${indexingPhaseIngest}  = "取り込み"  # 1ファイルずつ取り込んでいる
${indexingPhaseFinish}  = "仕上げ"    # 後片付け（Officeアプリの終了・取り込み一覧の書き直し）

# 取り込み予定（newIngestPlanRow）の列と、インデックスごとの区分
${ingestPlanColumns} = @("インデックス名", "元のフォルダ", "区分", "ファイル数", "取り込み対象", "新規", "更新あり", "前回未完了", "インデックスなし", "前回失敗", "クラウド", "クラウド失敗", "クラウド容量", "クラウド失敗容量")
${planKindIngest}    = "取り込み"      # チェックが付いていて元のフォルダも見つかった（数えた結果を出す）
${planKindUnchecked} = "チェックなし"  # チェックが外れているため数えていない
${planKindMissing}   = "フォルダなし"  # 元のフォルダが見つからないため数えていない
${planKindDropped}   = "削除予定"      # 設定から外れたインデックス（確認で［更新を開始］が押されたときだけ消す）

# 取り込み一覧の列と状態
${statusColumns}   = @("相対パス", "更新日時", "サイズ", "状態", "TSV数", "取り込み日時", "エラー", "抽出版")
${statusFolderKey} = "クロール対象フォルダ"
${stateNew}    = "未取り込み"
${stateDone}   = "済"
${stateFailed} = "失敗"

# 取り込み一覧（status ファイル）の読み書き（状態層）。列と状態の定義は paths.ps1。

function newStatusRow {
    # 取り込み一覧の1行（1ファイル）を作る
    param (
        [string]$relPath,
        [string]$updated = "",
        [string]$size = "",
        [string]$state = ${stateNew},
        [string]$tsvCount = "",
        [string]$ingested = "",
        [string]$errorMessage = "",
        [string]$extractVersion = ""
    )

    return [pscustomobject]@{
        相対パス = $relPath
        更新日時 = $updated
        サイズ   = $size
        状態     = $state
        TSV数    = $tsvCount
        取り込み日時 = $ingested
        エラー   = $errorMessage
        抽出版   = $extractVersion
    }
}

# 1行1件を保つため、タブ・改行はスペースにする（この文字を含む値だけ置き換える）
${statusLineBreaks} = [char[]]@("`t", "`r", "`n")


function toStatusLine {
    # 取り込み一覧の1行を文字列にする（1件ずつの追記用。addStatusRow）。
    # エラーメッセージ等のタブ・改行は、1行1件を保つためスペースにする。
    # 数万行をまとめて書き出す writeStatusFile では、同じ整形をその場に展開している（関数の呼び出しだけで
    # 5万行あたり数秒かかるため）。整形を変えるときは両方を直す（テストで同じ結果になることを確かめている）
    param (
        $row
    )

    $errorText = [string]$row.エラー
    if ($errorText.IndexOfAny(${statusLineBreaks}) -ge 0) {
        $errorText = $errorText -replace "[\t\r\n]+", " "
    }
    return [string]::Join("`t", @(
        [string]$row.相対パス, [string]$row.更新日時, [string]$row.サイズ, [string]$row.状態,
        [string]$row.TSV数, [string]$row.取り込み日時, $errorText, [string]$row.抽出版))
}

function readStatusFile {
    # 取り込み一覧を読み込み、@{ Folders; Rows } を返す。ファイルが無ければ空。
    #   Folders: クロール対象フォルダ @{ Path; Name（インデックス名） } の配列
    #   Rows   : 相対パス（"インデックス名\フォルダからの相対パス"。大文字・小文字を区別しない）→ 行
    # インデックス作成中は1件ごとに行を追記するため、同じ相対パスの行は後の行を優先する。列数の合わない行（書き込み途中で中断した行など）は無視する
    param (
        [string]$path = $workspace.StatusFile
    )

    $rows = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
    $folders = New-Object System.Collections.Generic.List[object]
    $result = @{ Folders = $folders; Rows = $rows }
    if (!(Test-Path -LiteralPath $path)) {
        return $result
    }

    # インデックス作成中に画面などから読んでも、インデクサの追記・置き換えを妨げないよう共有を許して開く
    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $stream = New-Object System.IO.FileStream($path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    $reader = New-Object System.IO.StreamReader($stream, ${utf8Bom})
    try {
        $lines = $reader.ReadToEnd() -split "\r?\n"
    } finally {
        $reader.Dispose()
    }

    $columnCount = ${statusColumns}.Count
    foreach ($line in $lines) {
        $fields = $line.Split("`t")
        if ($fields[0] -eq ${statusFolderKey} -and $fields.Count -eq 3) {
            $folders.Add([pscustomobject]@{ Path = $fields[1]; Name = $fields[2] })
            continue
        }
        if ($fields.Count -ne $columnCount -or $fields[0] -eq "" -or $fields[0] -eq ${statusColumns}[0]) {
            continue
        }
        # 数万行を読むため、1行ごとの関数呼び出し（newStatusRow）は使わずにその場で作る（列は $statusColumns と同じ）
        $rows[$fields[0]] = [pscustomobject]@{
            相対パス = $fields[0]
            更新日時 = $fields[1]
            サイズ   = $fields[2]
            状態     = $fields[3]
            TSV数    = $fields[4]
            取り込み日時 = $fields[5]
            エラー   = $fields[6]
            抽出版   = $fields[7]
        }
    }
    return $result
}

function writeStatusFile {
    # 取り込み一覧を書き出す（1ファイル1行）。途中で中断しても壊れないよう、一時ファイルに書いてから置き換える
    #   folders: クロール対象フォルダ @{ Path; Name } の配列。"クロール対象フォルダ<TAB>パス<TAB>インデックス名" の行にする
    param (
        [object[]]$folders,
        [object[]]$rows,
        [string]$path = $workspace.StatusFile
    )

    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($folder in @($folders | Where-Object { $_ })) {
        $lines.Add("${statusFolderKey}`t$($folder.Path)`t$($folder.Name)")
    }
    $lines.Add((${statusColumns} -join "`t"))
    # 数万行を書き出すため、1行ごとの関数呼び出し（toStatusLine）・パイプライン（Where-Object）は使わない
    # （5万行で約 10 秒 → 約 0.2 秒。この間はインデックス作成の進み具合が止まって見えるため速くする）
    foreach ($row in $rows) {
        if ($null -eq $row) {
            continue
        }
        $errorText = [string]$row.エラー
        if ($errorText.IndexOfAny(${statusLineBreaks}) -ge 0) {
            $errorText = $errorText -replace "[\t\r\n]+", " "
        }
        $lines.Add([string]::Join("`t", @(
            [string]$row.相対パス, [string]$row.更新日時, [string]$row.サイズ, [string]$row.状態,
            [string]$row.TSV数, [string]$row.取り込み日時, $errorText, [string]$row.抽出版)))
    }

    writeTextLinesAtomic $path $lines
}

function getIndexNameMap {
    # 取り込み一覧に記録したインデックス名 → クロール対象フォルダのパス（大文字・小文字を区別しない）。
    # クロール対象フォルダの行は先頭にあるため、見出し行まで読んで打ち切る（取り込み一覧が大きくても時間がかからないように）
    param (
        [string]$path = $workspace.StatusFile
    )

    $map = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::OrdinalIgnoreCase)
    if (!(Test-Path -LiteralPath $path)) {
        return , $map
    }
    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $stream = New-Object System.IO.FileStream($path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    $reader = New-Object System.IO.StreamReader($stream, ${utf8Bom})
    try {
        $header = ${statusColumns} -join "`t"
        while ($null -ne ($line = $reader.ReadLine())) {
            if ($line -eq $header) {
                break
            }
            $fields = $line.Split("`t")
            if ($fields[0] -eq ${statusFolderKey} -and $fields.Count -eq 3 -and $fields[2]) {
                $map[$fields[2]] = $fields[1]
            }
        }
    } finally {
        $reader.Dispose()
    }
    return , $map
}

# インデックス名に対する元のフォルダを記録できるかの判断（判断層。ファイルに触らない）。

function testSourceNameRecordable {
    # インデックス名に対する元のフォルダを設定に記録できる名前か。空の名前と、前後に空白（全角空白・NBSP・タブを含む）がある名前は、
    # 設定を読み戻すとき前後の空白が削られて同じ名前にならない（確かめ済みにならない）ため記録しない。
    # 状態層（setIndexSourceFolder）の入口の条件と、画面の文言（記録されないときは毎回確かめる）で同じ判断を使う。
    # 文字数で比べる（-ne はカルチャに従う）
    param (
        [string]$name
    )

    $trimmed = $name.Trim()
    return $trimmed.Length -gt 0 -and $trimmed.Length -eq $name.Length
}

# インデックス名と TSV のファイル名の決め方（判断層。ファイルに触らない）。

function newIndexName {
    # クロール対象フォルダのインデックス名（work\index 直下のフォルダ名）を作る。
    # フォルダ名（ドライブ直下はドライブ名）を使い、usedNames と重複すれば「名前(2)」「名前(3)」…とする
    param (
        [string]$folderPath,
        $usedNames = $null  # HashSet[string]・配列・1 個の文字列・$null のいずれでもよい
    )

    $base = toSafeFileName (getFolderLeafName $folderPath)
    if ($base -eq "") {
        $base = "フォルダ"
    }

    # 呼び出し側から $null や文字列の配列で渡されても落ちないよう、ここで集合に直す（大文字・小文字は区別しない）
    $used = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    # 集合が 1 要素の配列に入って渡されても（@(関数) で受けた場合など）、中身を 1 つずつ取り出す
    foreach ($entry in @($usedNames)) {
        foreach ($usedName in @($entry)) {
            if ($usedName) {
                [void]$used.Add([string]$usedName)
            }
        }
    }

    $name = $base
    for ($i = 2; $used.Contains($name); $i++) {
        # 長いフォルダ名に (2) を付けるとファイル名の上限を超えてフォルダを作れないため、上限に収まるよう名前を切り詰める
        $suffix = "(${i})"
        $name = $base.Substring(0, [Math]::Min($base.Length, ${maxFileNameLength} - $suffix.Length)) + $suffix
    }
    return $name
}

function assignIndexNames {
    # クロール対象フォルダ（getTargetFolders）にインデックス名を割り当て、@{ Path; Enabled; Name } の配列を返す。
    # インデックス名は設定に持つ（getTargetFolders の Name）。フォルダの置き場所（Path）を書き換えても名前は変わらないため、
    # フォルダを移しても同じインデックスとして扱える（インデックスを作り直さない）。
    # 名前が無い場合（新しく追加したフォルダ）は、前回の取り込み一覧の同じパスの名前を使い、
    # それも無ければフォルダ名から重複しない名前を作る
    param (
        [object[]]$targetFolders,
        [object[]]$previousFolders  # readStatusFile の Folders（@{ Path; Name }）
    )

    $previousNames = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($folder in @($previousFolders | Where-Object { $_ -and $_.Name })) {
        $previousNames[$folder.Path] = $folder.Name
    }

    # 設定にある名前・前回の名前は使わない（別のフォルダに同じ名前を付けてインデックスを取り違えないため）
    $used = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($name in $previousNames.Values) {
        [void]$used.Add($name)
    }
    foreach ($folder in @($targetFolders | Where-Object { $_ -and $_.Name })) {
        [void]$used.Add($folder.Name)
    }

    $result = New-Object System.Collections.Generic.List[object]
    foreach ($folder in @($targetFolders | Where-Object { $_ })) {
        $name = [string]$folder.Name
        if ($name -eq "") {
            if ($previousNames.ContainsKey($folder.Path)) {
                $name = $previousNames[$folder.Path]
            } else {
                $name = newIndexName $folder.Path $used
            }
            [void]$used.Add($name)
        }
        $result.Add([pscustomobject]@{ Path = $folder.Path; Enabled = $folder.Enabled; Name = $name })
    }
    return $result.ToArray()
}

function splitIndexRelPath {
    # work\index からの相対パスを、先頭のインデックス名と残り（クロール対象フォルダからの相対パス）に分ける: @{ Name; Rest }
    # （String.Split([char], 2) は .NET Framework では Split(params char[]) になり、2 も区切り文字とみなされるため使わない）
    param (
        [string]$relPath
    )

    $i = $relPath.IndexOf("\")
    if ($i -lt 0) {
        return @{ Name = $relPath; Rest = "" }
    }
    return @{ Name = $relPath.Substring(0, $i); Rest = $relPath.Substring($i + 1) }
}


# Windows で使えないファイル名（インデックス名に使えるかの判定に使う）
${reservedFileNames} = @("CON", "PRN", "AUX", "NUL") +
    @(1..9 | ForEach-Object { "COM$_" }) + @(1..9 | ForEach-Object { "LPT$_" })


function testIndexName {
    # インデックス名（work\index 直下のフォルダ名）として使えるかを調べ、使えない理由を返す（使えれば空文字列）。
    #   usedNames: ほかのインデックスが使っている名前（大文字・小文字を区別しない）
    param (
        [string]$name,
        [object[]]$usedNames = @()
    )

    $name = [string]$name
    if ($name -eq "") {
        return "名前を入力してください。"
    }
    if ($name -ne $name.Trim()) {
        return "名前の前後に空白は使えません。"
    }
    if ($name.Length -gt ${maxFileNameLength}) {
        return "名前が長すぎます（${maxFileNameLength} 文字まで）。"
    }
    if (@([System.IO.Path]::GetInvalidFileNameChars() | Where-Object { $name.IndexOf($_) -ge 0 }).Count -gt 0) {
        return "名前に使えない文字が含まれています（\ / : * ? " + [char]34 + " < > | と制御文字）。"
    }
    if ($name.EndsWith(".")) {
        return "名前の最後に . は使えません。"
    }
    if (${reservedFileNames} -contains $name.Split(".")[0].ToUpperInvariant()) {
        return "「${name}」は Windows で使えない名前です。"
    }
    foreach ($used in @($usedNames)) {
        if ([string]::Equals([string]$used, $name, [System.StringComparison]::OrdinalIgnoreCase)) {
            return "「${name}」は、ほかのインデックスが使っています。別の名前を付けてください。"
        }
    }
    return ""
}

function encodeIndexPlace {
    # インデックスのTSVのファイル名に入れる場所（シート名・ページ・スライド）を符号化する。
    # ファイル名に使えない文字・制御文字と、_・符号化に使う % を "%XX"（16進数）にする（decodeIndexPlace で元に戻す）。
    #   ・全角に置き換えると `a"b` と `a”b` が同じファイル名になり、後のシートで上書きされるため、元に戻せる形にする
    param (
        [string]$place
    )

    return [regex]::Replace($place, '[\x00-\x1F"%*/:<>?\\_|]', { param($m) '%{0:X2}' -f [int][char]$m.Value })
}

function decodeIndexPlace {
    # encodeIndexPlace で符号化した場所を元に戻す（encodeIndexPlace が作る "%XX" だけを戻す）
    param (
        [string]$place
    )

    # 符号化した文字が無ければそのまま返す（検索のたびに全TSVの名前を分解するため、置換の呼び出しを省く）
    if ($place.IndexOf("%") -lt 0) {
        return $place
    }
    return [regex]::Replace($place, '%(?:[01][0-9A-F]|2[25AF]|3[ACEF]|5[CF]|7C)', { param($m) [string][char][Convert]::ToInt32($m.Value.Substring(1), 16) })
}

# 決まった場所（ページ・スライド・ヘッダー/フッター・脚注・文書・本文）は、ファイル名を ASCII の固定名にする。
# 符号化した場所（encodeIndexPlace）には "_" が出ないため（"_" は "%5F" にする）、固定名に "_" を使っても
# シート名由来のファイル名と重ならない（convertIndexFileNameToPlace で戻すときの手掛かりにする）。
function convertPlaceBaseToFixedFileName {
    # 場所の元の部分（種類を除いた部分）を、決まったASCIIのファイル名にする（当てはまらなければ空文字列）。
    #   数字はそのまま桁を写す（int にしない。"001" は "001" のまま）
    param (
        [string]$base
    )

    if ($base -match '^ページ(\d+)$') { return "page_$($Matches[1])" }
    if ($base -match '^スライド(\d+)（非表示）$') { return "slide_$($Matches[1])_hidden" }
    if ($base -match '^スライド(\d+)_ノート$') { return "slide_$($Matches[1])_notes" }
    if ($base -match '^スライド(\d+)$') { return "slide_$($Matches[1])" }
    if ($base -eq "ヘッダー・フッター") { return "header_footer" }
    if ($base -eq "脚注") { return "doc_footnotes" }
    if ($base -eq "文書") { return "doc_whole" }
    if ($base -eq "本文") { return "doc_body" }
    return ""
}

function convertFixedFileNameToPlaceBase {
    # convertPlaceBaseToFixedFileName の逆変換（当てはまらなければ空文字列）
    param (
        [string]$fileBase
    )

    if ($fileBase -match '^page_(\d+)$') { return "ページ$($Matches[1])" }
    if ($fileBase -match '^slide_(\d+)_hidden$') { return "スライド$($Matches[1])（非表示）" }
    if ($fileBase -match '^slide_(\d+)_notes$') { return "スライド$($Matches[1])_ノート" }
    if ($fileBase -match '^slide_(\d+)$') { return "スライド$($Matches[1])" }
    if ($fileBase -eq "header_footer") { return "ヘッダー・フッター" }
    if ($fileBase -eq "doc_footnotes") { return "脚注" }
    if ($fileBase -eq "doc_whole") { return "文書" }
    if ($fileBase -eq "doc_body") { return "本文" }
    return ""
}

function toIndexFileName {
    # インデックスのTSVのファイル名 "<場所>.tsv" を返す。
    #   ・決まった場所（ページ・スライド・ヘッダー/フッター・脚注・文書・本文）は ASCII の固定名にする
    #   ・それ以外（Excelのシート名）は encodeIndexPlace で符号化する
    #   ・図形・コメント・ヘッダー・フッター・埋め込みは、末尾に英語の種類 "[shape]" "[comment]" "[header_footer]" "[embed<N>]" を付ける（placeKindFileNames）
    # 元のファイル名はフォルダ名（= 元のファイル名そのもの）にするため、ファイル名には入れない。
    # ファイル名の上限（255文字）は長いパスの対応（toLongPath）でも超えられないため、超える場合は分かるメッセージで例外にする
    param (
        [string]$place
    )

    $split = splitObjectPlace $place
    $fixedName = convertPlaceBaseToFixedFileName $split.Base
    $base = if ($fixedName) { $fixedName } else { encodeIndexPlace $split.Base }
    $suffix = if ($split.Kind) { "[$(${placeKindFileNames}[$split.Kind])$(if ($split.Number -gt 0) { $split.Number })]" } else { "" }
    $name = "{0}{1}.tsv" -f $base, $suffix
    if ($name.Length -gt ${maxFileNameLength}) {
        throw "インデックスのファイル名が長すぎるため保存できません（$($name.Length) 文字。上限 ${maxFileNameLength} 文字）: ${name}"
    }
    return $name
}

function convertIndexFileNameToPlace {
    # toIndexFileName の逆変換。ファイル名（拡張子 .tsv を除いたもの）から場所を復元する。
    #   戻す順番: (1) 末尾の "[shape]"・"[comment]"・"[header_footer]"・"[embed<N>]"（placeKindFileNames の値）を外す →
    #             (2) 残りに "_" があれば固定の場所の表で戻し、無ければ decodeIndexPlace で戻す →
    #             (3) (1) で外した種類を日本語（[図形]・[コメント]・[ヘッダー・フッター]・[埋め込み<N>]）で付け直す
    param (
        [string]$fileNameWithoutExtension
    )

    $kind = ""
    $body = $fileNameWithoutExtension
    $fileKindAlternation = (${placeKindFileNames}.Values | ForEach-Object { [regex]::Escape($_) }) -join "|"
    if ($fileNameWithoutExtension -match "^(?<base>.+)\[(?<kind>$fileKindAlternation)(?<number>${objectPlaceNumberPattern})?\]`$") {
        $kindName = $Matches.kind
        $kind = (${placeKindFileNames}.GetEnumerator() | Where-Object { $_.Value -eq $kindName } | Select-Object -First 1).Key
        # 番号は埋め込みにだけ付く（ほかの種類に付いた名前は、この関数が作らない形のため戻さない）
        if (($kind -eq ${placeKindEmbed}) -eq [bool]$Matches.number) {
            $body = $Matches.base
            if ($Matches.number) { $kind = "${kind}$($Matches.number)" }
        } else {
            $kind = ""
        }
    }

    if ($body.IndexOf("_") -ge 0) {
        $base = convertFixedFileNameToPlaceBase $body
    } else {
        $base = decodeIndexPlace $body
    }

    if ($kind) { return "$base[$kind]" }
    return $base
}


# 図形・コメントなど、本文（セル・段落）以外の文字の場所は "<元の場所>[<種類>]" とする。
# 元の場所は、Excel ではシート名（例: "売上[図形]"。office_reader.ps1 の readXlsxObjectUnits）。
# Word はページ、PowerPoint はスライドを元の場所にする（例: "ページ003[コメント]" "スライド002[図形]"）。
# Excel のシート名には [ ] を使えず、Word・PowerPoint の場所（ページNNN・スライドNNN 等）にも付かないため、ふつうの場所と重ならない。
# 種類ごとに、検索に含めるかを画面で選べる（search_query.ps1 の newPlaceExclude）。
# 種類を足すときは、ここ（placeKindFileNames にも足す）と書き出す側（office_reader.ps1）をそろえる。検索の除外・画面の判定の正規表現は newObjectPlaceKindPattern が表から組み立てる
${placeKindShape}   = "図形"      # 図形・テキストボックス・WordArt・SmartArt・グラフ（PowerPoint のテキストボックス・図形はスライドの本文）
${placeKindComment} = "コメント"  # コメント（メモ・スレッド形式のコメント）
${placeKindHeaderFooter} = "ヘッダー・フッター"  # Excel のヘッダー・フッター（Word・PowerPoint の "ヘッダー・フッター" は場所の名前で、種類ではない）。いつも検索する（除外の選択肢は無い）
${placeKindEmbed}   = "埋め込み"  # Word・PowerPoint に埋め込んだ Office のファイル（.xlsx・.docx・.pptx など）の中の文字。場所は "<元の場所>[埋め込み<N>]"（N は 1 ファイルの中の通し番号。ほかの種類と違い、番号が付く）。図形と一緒に検索の有無を切り替える

# 種類ごとの、TSVのファイル名に付ける英語の名前（toIndexFileName・convertIndexFileNameToPlace で使う）。
# 番号の付く種類（埋め込み）のファイル名は "[embed<N>]"
${placeKindFileNames} = @{ ${placeKindShape} = "shape"; ${placeKindComment} = "comment"; ${placeKindHeaderFooter} = "header_footer"; ${placeKindEmbed} = "embed" }

# ${objectPlacePattern} の種類の選択肢は ${placeKindFileNames} のキーから組み立てる（足し忘れを防ぐ）。
# 番号の付く種類（埋め込み）は選択肢に入れず、番号（先頭が 0 でない数字）を付けた形だけを別に当てる
# （"[埋め込み]"・"[埋め込み01]" はふつうの場所とする）
${objectPlaceKindAlternation} = (${placeKindFileNames}.Keys | Where-Object { $_ -ne ${placeKindEmbed} } | ForEach-Object { [regex]::Escape($_) }) -join "|"
${objectPlaceNumberPattern} = "[1-9][0-9]{0,8}"
${objectPlacePattern} = "^(?<base>.*)\[(?:(?<kind>${objectPlaceKindAlternation})|(?<numberedKind>$([regex]::Escape(${placeKindEmbed})))(?<number>${objectPlaceNumberPattern}))\]$"


function newObjectPlaceKindPattern {
    # 場所の末尾の種類だけを当てる正規表現の文字列を、${placeKindFileNames} の表から組み立てる。
    # 検索から外す場所（search_query.ps1 の newPlaceExclude）と画面の判定（ui/search/result_types.ps1 の HitRow.ObjectPlaceRegex）が使う。
    #   例（全部）: \[(?:図形|コメント|ヘッダー・フッター|埋め込み[1-9][0-9]{0,8})\]$（選択肢の並びは表の順による）
    # kinds: 当てる種類の名前の並び（省略または空は全部）。番号の付く種類（埋め込み）は番号の形を付けて当てる
    param (
        [string[]]$kinds = @()
    )

    if ($kinds.Count -eq 0) {
        $kinds = @(${placeKindFileNames}.Keys)
    }
    $alternatives = foreach ($kind in $kinds) {
        if ($kind -eq ${placeKindEmbed}) { "$([regex]::Escape($kind))${objectPlaceNumberPattern}" } else { [regex]::Escape($kind) }
    }
    return "\[(?:$(@($alternatives) -join '|'))\]`$"
}


function splitObjectPlace {
    # 場所を @{ Base（元の場所）; Kind（種類。ふつうの場所は空）; Number（埋め込みの番号。ほかは 0） } に分ける。
    #   例: "売上[図形]" → @{ Base = "売上"; Kind = "図形"; Number = 0 } / "ページ001" → @{ Base = "ページ001"; Kind = ""; Number = 0 }
    #       "ページ003[埋め込み2]" → @{ Base = "ページ003"; Kind = "埋め込み"; Number = 2 }
    param (
        [string]$place
    )

    if ($place -match ${objectPlacePattern}) {
        if ($Matches.numberedKind) {
            return @{ Base = $Matches.base; Kind = $Matches.numberedKind; Number = [int]$Matches.number }
        }
        return @{ Base = $Matches.base; Kind = $Matches.kind; Number = 0 }
    }
    return @{ Base = $place; Kind = ""; Number = 0 }
}


function describePlace {
    # 場所ごとの表記と「種別」を @{ Place; Kind } で返す（TSV の名前は変えず、表示だけを変える）。
    # 画面の見出しの要約・検索結果ファイル・コピーに使う。表の「場所」の列は、これにセル番地を足した describeHitPlace を使う
    #   Excel      : "売上" → [シート]売上・セル / "売上[図形]" → [シート]売上・図形 / "売上[コメント]" → [シート]売上・コメント
    #                / "売上[ヘッダー・フッター]" → [シート]売上・ヘッダー・フッター
    #   Word       : "ページ003" → 3 ページ（目安）・本文（ページは保存時の区切りから数えた目安のため）/ "脚注" → 脚注・本文
    #   PowerPoint : "スライド002（非表示）" → スライド 2（非表示）・本文 / "スライド002_ノート" → スライド 2・ノート
    #   テキスト   : "本文" → 空・本文（場所は 1 つだけのため、表の「場所」の列は describeHitPlace の "N 行目" だけで足りる）
    # 種別は、図形・コメントなら場所の種類の名前そのまま（検索条件の［図形も検索］［コメントも検索］と同じ言葉）。
    # 埋め込みは番号を付けた "埋め込み 1"（場所は元の場所のページ・スライドの表記のまま）
    param (
        [string]$book,
        [string]$place
    )

    if (testTextExtension $book) {
        return @{ Place = ""; Kind = "本文" }
    }

    $split = splitObjectPlace $place
    $base = $split.Base
    $kind = $split.Kind
    if ($split.Number -gt 0) { $kind = "$kind $($split.Number)" }

    if ($book -match '\.xls[a-z]?$') {
        return @{ Place = "[シート]$base"; Kind = $(if ($kind) { $kind } else { "セル" }) }
    }
    if ($base -eq "") {
        return @{ Place = ""; Kind = $(if ($kind) { $kind } else { "本文" }) }
    }
    if ($base -match '^ページ(\d+)$') {
        if (testPdfExtension $book) {
            return @{ Place = "$([int]$Matches[1]) ページ"; Kind = $(if ($kind) { $kind } else { "本文" }) }
        }
        return @{ Place = "$([int]$Matches[1]) ページ（目安）"; Kind = $(if ($kind) { $kind } else { "本文" }) }
    }
    if ($base -match '^スライド(\d+)_ノート$') {
        return @{ Place = "スライド $([int]$Matches[1])"; Kind = $(if ($kind) { $kind } else { "ノート" }) }
    }
    if ($base -match '^スライド(\d+)(（非表示）)?$') {
        return @{ Place = "スライド $([int]$Matches[1])$($Matches[2])"; Kind = $(if ($kind) { $kind } else { "本文" }) }
    }
    # ヘッダー・フッター・脚注など、番号の無い場所
    return @{ Place = $base; Kind = $(if ($kind) { $kind } else { "本文" }) }
}


function describeHitPlace {
    # 結果の表の「場所」の列とプレビューの題に出す、行ごとの場所の表記を返す（場所ごとの表記にセル番地を足したもの）。
    # Excel だけ足す（Word・PowerPoint は場所ごとと同じ）。テキストは行番号だけ（"N 行目"）を返す（場所は 1 つしかないため）。
    #   セル             : [シート]売上!B12 / 1 行に複数のセルが一致 [シート]売上!B12 ほか 2 / セル番地が求まらないとき [シート]売上 12 行目
    #   図形・コメント   : [シート]売上!D5 / セル番地が求まらないとき [シート]売上（行番号は通し番号のため出さない）
    #   ヘッダー・フッター: [シート]売上（行にセル番地が無く、matchCell が空のため）
    #   テキスト         : 12 行目
    param (
        [string]$place,
        [bool]$isExcel,
        [bool]$isObjectPlace,
        [string]$matchCell,
        [int]$matchCount,
        [int]$lineNumber,
        [bool]$isText = $false
    )

    if ($isText) { return "$lineNumber 行目" }
    if (-not $isExcel) { return $place }
    if ($isObjectPlace) {
        if ($matchCell) { return "$place!$matchCell" }
        return $place
    }
    if (-not $matchCell) { return "$place $lineNumber 行目" }
    if ($matchCount -gt 1) { return "$place!$matchCell ほか $($matchCount - 1)" }
    return "$place!$matchCell"
}


# インデックスの「元のファイル名のフォルダ」と分かる名前（Office・テキスト・PDF の拡張子で終わる）
${indexBookDirPattern} = "\.(?:xls|doc|ppt)[a-z]?$|(?:$(((${textExtensions} + ${pdfExtensions}) | ForEach-Object { [regex]::Escape($_) }) -join '|'))$"

# インデックス（work\index 配下）の作成・集計・改名・削除。

function testStatusRowFailed {
    # 取り込み一覧の行を「失敗」として数えるか。状態が「失敗」の行と、「未取り込み」で理由（エラー）が書いてある行
    # （利用者の PowerPoint のために取り込めなかったファイル。次の更新で取り込むため状態は「未取り込み」のまま）
    param (
        $row
    )

    $state = [string]$row.状態
    return ($state -eq ${stateFailed}) -or ($state -eq ${stateNew} -and [string]$row.エラー -ne "")
}

function getIndexStats {
    # 取り込み一覧の行をインデックス名ごとに集計する（画面のインデックス一覧に出す件数・最終更新）:
    #   インデックス名（大文字・小文字を区別しない）→ @{ Total; Done; Pending; Failed; LastIngested（"yyyy/MM/dd HH:mm:ss"。無ければ空） }
    # rows は readStatusFile の Rows（相対パス → 行）。取り込み一覧を読み直さずに済むよう、読み込み済みの行を受け取る
    param (
        $rows
    )

    $stats = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
    if ($null -eq $rows) {
        return , $stats
    }
    foreach ($entry in $rows.GetEnumerator()) {
        $name = (splitIndexRelPath $entry.Key).Name
        if ($name -eq "") {
            continue
        }
        if (!$stats.ContainsKey($name)) {
            $stats[$name] = @{ Total = 0; Done = 0; Pending = 0; Failed = 0; LastIngested = "" }
        }
        $stat = $stats[$name]
        $stat.Total++
        $state = [string]$entry.Value.状態
        if ($state -eq ${stateDone}) {
            $stat.Done++
        } elseif (testStatusRowFailed $entry.Value) {
            $stat.Failed++
        } elseif ($state -eq ${stateNew}) {
            $stat.Pending++
        }
        # 取り込み日時は "yyyy/MM/dd HH:mm:ss" のため、文字列のまま比べて新しい方を残せる
        $ingested = [string]$entry.Value.取り込み日時
        if ($ingested -gt $stat.LastIngested) {
            $stat.LastIngested = $ingested
        }
    }
    return , $stats
}

function removeSystemIndexOfWorkspace {
    # インデックスのフォルダ（dir = <ワークスペース>\index）と同じワークスペースの system_index から、インデックス name の分を消す。
    # 消せなくても（状態ファイルがほかに開かれている等）インデックスの操作は続ける。次のインデックス作成で整理される
    param (
        [string]$name,
        [string]$dir
    )

    $owner = [Workspace]::new([System.IO.Path]::GetDirectoryName($dir.TrimEnd("\")))
    try {
        [void](removeSystemIndexOf $name $owner.SystemIndexDir $owner.SystemIndexStateFile)
    } catch {
    }
}

function getSearchIndexes {
    # インデックスの一覧（getSearchIndexData の Indexes）。引数は getSearchIndexData と同じ
    param (
        [string]$dir = $workspace.IndexDir,
        [string]$statusPath = $workspace.StatusFile,
        [string]$settingsPath = ${settingsFile}
    )

    return @((getSearchIndexData $dir $statusPath $settingsPath).Indexes)
}

function getSearchIndexData {
    # @{ Root（dir のフルパス）; Sources（インデックス名 → 元のフォルダ。getSourceFolderMap の結果）; Indexes } を返す。
    # Indexes はインデックスの一覧（work\index 直下のフォルダ 1 つがインデックス 1 つ）で、
    # @{ Name（インデックス名）; Path（インデックスのフォルダのフルパス）; SourcePath（元のフォルダ。分からなければ ""） } の配列で返す。
    # 並びは［インデックス管理］の一覧（targetFolders）と同じにし、その一覧に無いもの
    # （別の場所・PC から work\index にコピーしたインデックスなど）は名前順で後ろに付ける
    param (
        [string]$dir = $workspace.IndexDir,
        [string]$statusPath = $workspace.StatusFile,
        [string]$settingsPath = ${settingsFile}
    )

    if (!(Test-Path -LiteralPath $dir -PathType Container)) {
        return @{ Root = $dir; Indexes = @(); Sources = @{} }
    }
    $root = (Resolve-Path -LiteralPath $dir).ProviderPath.TrimEnd("\")
    $sources = getSourceFolderMap $root $statusPath $settingsPath

    # ［インデックス管理］の一覧の順番（インデックス名 → 何番目か）
    $order = New-Object 'System.Collections.Generic.Dictionary[string,int]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($folder in @(getTargetFolders $settingsPath | Where-Object { $_.Name })) {
        if (!$order.ContainsKey($folder.Name)) {
            $order[$folder.Name] = $order.Count
        }
    }

    $indexes = New-Object System.Collections.Generic.List[object]
    foreach ($sub in @(Get-ChildItem -LiteralPath (toLongPath $root) -Directory -ErrorAction SilentlyContinue)) {
        $name = $sub.Name
        $path = (fromLongPath $sub.FullName)
        if (!$sources.ContainsKey($name)) {
            # 取り込み一覧にも設定にも無いインデックス（別の場所・PC からコピーしたものなど）は、
            # そのフォルダの中の source_folder.txt から元のフォルダを読む
            $own = readSourceFolderFile $path
            if ($own.ContainsKey($name)) {
                $sources[$name] = $own[$name]
            }
        }
        $indexes.Add([pscustomobject]@{
            Name       = $name
            Path       = $path
            SourcePath = $(if ($sources.ContainsKey($name)) { $sources[$name] } else { "" })
            Order      = $(if ($order.ContainsKey($name)) { $order[$name] } else { [int]::MaxValue })
        })
    }
    $sorted = @($indexes | Sort-Object Order, Name | ForEach-Object {
        [pscustomobject]@{ Name = $_.Name; Path = $_.Path; SourcePath = $_.SourcePath }
    })
    return @{ Root = $root; Indexes = $sorted; Sources = $sources }
}


# インデックスのフォルダが壊れている（0 バイトのTSVがある）ことを表す件数。testIndexComplete は取り込み直す
${indexBrokenCount} = -1


function getContentIndexKeyOf {
    # getIndexTsvCounts の本文インデックスのファイルのキー（「<インデックスのフォルダからのフォルダ>\content_index.<拡張子>」）を返す
    param (
        [string]$relDir,
        [string]$extension
    )

    $name = "${contentIndexFileNamePrefix}.$extension"
    if ($relDir) { return "$relDir\$name" }
    return $name
}

function getIndexTsvCounts {
    # インデックスのフォルダの中のフォルダごとのTSVの数を返す（取り込み一覧の「済」と、インデックスの実体が合っているかの確認に使う）:
    #   インデックスのフォルダからの相対パス（大文字・小文字を区別しない）→ そのフォルダの直下のTSVの数
    #   本文インデックスのファイル（content_index.<拡張子>.<番号>.tsv）は、「<フォルダ>\content_index.<拡張子>」 → 1（どれかが 0 バイトなら ${indexBrokenCount}）
    # 元のファイル1つにつき1フォルダ（<ファイル名.xlsx>\<場所>.tsv）のため、キーは取り込み一覧の相対パスと同じになる。
    # 0 バイトのTSVがあるフォルダは ${indexBrokenCount}（-1）にする。
    # 空のシート・ページは保存しない（prettyTsv / writeUnits）ため、0 バイトのTSVは書き込みの途中で
    # 電源が落ちた場合などに限られ、そのままでは検索しても中身が出てこない。
    # 列挙できないとき（アクセス権が無い等）は $null を返す（呼び出し元は確認しない）
    param (
        [string]$dir = $workspace.IndexDir
    )

    $counts = New-Object 'System.Collections.Generic.Dictionary[string,int]' ([System.StringComparer]::OrdinalIgnoreCase)
    $root = toLongPath ([string]$dir).TrimEnd("\")
    if (!$root -or ![System.IO.Directory]::Exists($root)) {
        return , $counts
    }

    # 1ファイルずつ調べると件数の分だけ時間がかかるため、フォルダ・TSVをそれぞれ1回ずつ列挙して数える
    # （大きさは列挙のときに分かるため、1件ずつ調べる必要は無い）
    $prefix = $root.Length + 1
    try {
        # 内容が空のファイル（TSV 0 件）はフォルダだけが残るため、フォルダも 0 件として数える
        foreach ($sub in [System.IO.Directory]::EnumerateDirectories($root, "*", [System.IO.SearchOption]::AllDirectories)) {
            $counts[$sub.Substring($prefix)] = 0
        }
        foreach ($file in (New-Object System.IO.DirectoryInfo($root)).EnumerateFiles("*.tsv", [System.IO.SearchOption]::AllDirectories)) {
            $contentIndexInfo = readContentIndexFileName $file.Name
            if ($null -ne $contentIndexInfo) {
                # 本文インデックスのファイル（content_index.<拡張子>.<番号>.tsv）は、番号を除いた「<フォルダ>\content_index.<拡張子>」をキーにする
                # （testIndexComplete が拡張子ごとに見る）。どれか 1 つでも 0 バイトなら壊れているとする
                $contentIndexDir = if ($file.DirectoryName.Length -ge $prefix) { $file.DirectoryName.Substring($prefix) } else { "" }
                $key = getContentIndexKeyOf $contentIndexDir $contentIndexInfo.Extension
                $current = 0
                if ($file.Length -eq 0 -or ($counts.TryGetValue($key, [ref]$current) -and $current -eq ${indexBrokenCount})) {
                    $counts[$key] = ${indexBrokenCount}
                } else {
                    $counts[$key] = 1
                }
                continue
            }
            $parent = [System.IO.Path]::GetDirectoryName($file.FullName)
            if ($parent.Length -lt $prefix) {
                continue  # インデックスのフォルダの直下のTSVは、どのファイルのものか分からないため数えない
            }
            $key = $parent.Substring($prefix)
            $count = 0
            if (!$counts.TryGetValue($key, [ref]$count)) {
                $count = 0
            }
            if ($file.Length -eq 0 -or $count -eq ${indexBrokenCount}) {
                $counts[$key] = ${indexBrokenCount}
            } else {
                $counts[$key] = $count + 1
            }
        }
    } catch {
        return $null
    }
    return , $counts
}

function testIndexComplete {
    # 取り込み一覧の行（状態が「済」）に対して、インデックスの実体がそろっているかを返す。
    # 利用者が work\content_index のフォルダ・ファイルを直接削除した場合に、「済」のまま検索できなくなるのを防ぐ。
    # 元のファイルの中身は、フォルダの本文インデックスのファイル（content_index.<拡張子>.tsv）か、本文インデックスのファイルに入れる前の TSV
    # （<ファイル名.xlsx>\<場所>.tsv。インデックス作成が途中で止まったとき）のどちらかにある
    #   row    : 取り込み一覧の行（TSV数 を使う）
    #   relPath: 取り込み一覧の相対パス（= インデックスのフォルダからの相対パス）
    #   counts : getIndexTsvCounts の結果（$null なら確認せず、そろっているものとして扱う）
    param (
        $row,
        [string]$relPath,
        $counts
    )

    if ($null -eq $counts -or $null -eq $row) {
        return $true
    }
    # 本文インデックスのファイル: そのフォルダ・その拡張子の本文インデックスのファイルがあれば、そろっているものとする
    # （本文インデックスのファイルの中の元のファイルごとの場所の数は、中身を読まないと分からないため数えない）
    $contentIndexRel = getContentIndexKeyOf ([string][System.IO.Path]::GetDirectoryName($relPath)) (getContentIndexExtension $relPath)
    $contentIndexCount = 0
    if ($counts.TryGetValue($contentIndexRel, [ref]$contentIndexCount) -and $contentIndexCount -ne ${indexBrokenCount}) {
        return $true
    }
    $expected = 0
    if (-not [int]::TryParse([string]$row.TSV数, [ref]$expected)) {
        return $true  # TSVの数を記録していない行は確認できない
    }
    $actual = 0
    if (-not $counts.TryGetValue($relPath, [ref]$actual)) {
        return $false  # 本文インデックスのファイルも、元のファイルごとのフォルダも無い
    }
    if ($actual -eq ${indexBrokenCount}) {
        return $false  # 0 バイトのTSVがある（書き込みの途中で電源が落ちた場合など）
    }
    # 余分なTSVがあっても（利用者が置いた等）取り込み直さない。足りない場合だけ作り直す
    return ($actual -ge $expected)
}

function publishIndexFiles {
    # 取り込んで作ったTSV（fromDir の直下）を、その元のファイルのインデックスのフォルダ（bookDir）に入れる。
    # 作りかけのインデックスを残さないよう、いったん stagingDir に集めてから bookDir ごと入れ替える。
    # 途中で強制終了されても、bookDir は「前回のまま」か「今回の分がそろった状態」のどちらかになる
    # （1件ずつ bookDir へ移すと、途中で止まったときに一部のシートだけのインデックスが残り、検索で気付けない）。
    # 以前のインデックスはフォルダごと置き換える（シートの削除・名前変更に追従するため）
    param (
        [string]$fromDir,
        [string]$bookDir,
        [string]$stagingDir
    )

    removeDirectoryRetry $stagingDir
    [System.IO.Directory]::CreateDirectory((toLongPath $stagingDir)) | Out-Null
    foreach ($file in @(Get-ChildItem -LiteralPath (toLongPath $fromDir) -Filter "*.tsv" -File)) {
        [System.IO.File]::Move($file.FullName, (toLongPath (Join-Path $stagingDir $file.Name)))
    }

    removeDirectoryRetry $bookDir
    [System.IO.Directory]::CreateDirectory((toLongPath ([System.IO.Path]::GetDirectoryName($bookDir)))) | Out-Null
    try {
        [System.IO.Directory]::Move((toLongPath $stagingDir), (toLongPath $bookDir))
    } catch [System.IO.IOException] {
        # work を別のドライブへのリンクにしている場合など、フォルダごとは移せないときは1件ずつ移す
        [System.IO.Directory]::CreateDirectory((toLongPath $bookDir)) | Out-Null
        foreach ($file in @(Get-ChildItem -LiteralPath (toLongPath $stagingDir) -Filter "*.tsv" -File)) {
            [System.IO.File]::Move($file.FullName, (toLongPath (Join-Path $bookDir $file.Name)))
        }
        removeDirectoryRetry $stagingDir
    }
    # bookDir はワークスペースの中（同じドライブ）の一時フォルダから Move で入れるため、親（content_index\）の
    # NotContentIndexed 属性を継がない。ここで、入れた分（フォルダと直下の TSV）だけに付ける
    [void](setNotContentIndexed $bookDir)
}

# 検索用の本文インデックスのファイル（フォルダ 1 つ・元のファイルの拡張子 1 つにつき、大きさで分けて 1 つ以上。content_index.xlsx.001.tsv など）の形式（判断層）。
# ファイル（元のファイル）ごと・場所（シート・ページ・スライドなど）ごとに、メタ情報の行と今の TSV の中身を並べる。
#
#   <RS> 版=1
#   <RS> ファイル名=(株)山田商事_見積書.xlsx
#   <RS> 種類=Excel
#   <RS> シート=見積
#   <RS> 対象=本文
#   品名→数量→単価        ← 今の TSV の中身そのまま（→ はタブ）。この行が 1 行目
#
# ・メタ情報の行は「RS（U+001E）、半角スペース、キー=値」。1 行に 1 項目。
#   ファイル名= で新しいファイル、シート= ページ= スライド= 部分= で新しい場所が始まる。知らないキーは読み飛ばす
# ・中身には U+001C～U+001F を入れない（書くときに取り除く）ため、行の先頭が RS ならメタ情報の行
# ・改行は LF にそろえる。行の分け方は StreamReader.ReadLine と同じ（CRLF・LF・CR）にし、行番号を変えない
# ・文字コードは UTF-16LE（BOM 付き。content_index_store.ps1 が読み書きする）
# ・Excel の図形・コメントの行は「セル番地 + タブ + 文字」の形。検索は区切りのタブ（最初のタブ）より後だけを照合する（CellPrefixed。content_index_search.ps1）

# 本文インデックスのファイルの名前は「content_index.<元のファイルの拡張子（小文字）>.<番号（3 桁以上）>.tsv」（content_index.xlsx.001.tsv など）。
# 1 つの本文インデックスのファイルが contentIndexFileMaxBytes 以上になったら、それ以上ブックを足さず、次の番号の本文インデックスのファイルに足す
# 先頭の語（content_index）は 1 か所の定数にする（index_store.ps1 の getContentIndexKeyOf も使う）
${contentIndexFileNamePrefix} = "content_index"
${contentIndexFilePattern} = "${contentIndexFileNamePrefix}.*.tsv"
${contentIndexFileNamePattern} = "^${contentIndexFileNamePrefix}\.(?<ext>[^.]+)\.(?<part>\d{3,})\.tsv$"
${contentIndexFileMaxBytes} = 4MB
${contentIndexVersion} = 1
${contentIndexMark} = [char]0x1E

# 場所のまとまりを始めるキー
${contentIndexPlaceKeys} = @("シート", "ページ", "スライド", "部分")


function getContentIndexFileKind {
    # 元のファイル名から種類（Excel・Word・PowerPoint・テキスト・PDF）を返す。分からなければ空
    param (
        [string]$book
    )

    if ($book -match '\.xls[a-z]?$') { return "Excel" }
    if ($book -match '\.doc[a-z]?$') { return "Word" }
    if ($book -match '\.ppt[a-z]?$') { return "PowerPoint" }
    if (testTextExtension $book) { return "テキスト" }
    if (testPdfExtension $book) { return "PDF" }
    return ""
}

function getContentIndexExtension {
    # 元のファイル名から、本文インデックスのファイルを分ける拡張子（小文字・先頭の . なし）を返す
    param (
        [string]$book
    )

    return [System.IO.Path]::GetExtension($book).TrimStart(".").ToLowerInvariant()
}


function getContentIndexFileName {
    # 拡張子・番号の本文インデックスのファイルの名前（content_index.xlsx.001.tsv など）を返す
    param (
        [string]$extension,
        [int]$part = 1
    )

    return "${contentIndexFileNamePrefix}.{0}.{1:D3}.tsv" -f $extension, $part
}


function readContentIndexFileName {
    # 本文インデックスのファイルの名前から @{ Extension; Part } を返す。本文インデックスのファイルの名前でなければ $null
    param (
        [string]$name
    )

    if ($name -match ${contentIndexFileNamePattern}) {
        return @{ Extension = $Matches.ext.ToLowerInvariant(); Part = [int]$Matches.part }
    }
    return $null
}


function splitContentIndexBooksByExtension {
    # 元のファイルの並びを、拡張子ごとの並び（[ordered] 拡張子 → 並び。拡張子は現れた順）に分ける。各並びの中の順は変えない
    param (
        $books
    )

    $groups = [ordered]@{}
    foreach ($book in $books) {
        $extension = getContentIndexExtension ([string]$book.Name)
        if (!$groups.Contains($extension)) {
            $groups[$extension] = New-Object System.Collections.Generic.List[object]
        }
        $groups[$extension].Add($book)
    }
    return $groups
}


function encodeContentIndexValue {
    # メタ情報の値を 1 行に収まる形にする。制御文字（タブを除く）と % を "%XX" にする（decodeContentIndexValue で戻す）
    param (
        [string]$value
    )

    if ($value -notmatch '[\x00-\x08\x0A-\x1F%]') {
        return $value
    }
    return [regex]::Replace($value, '[\x00-\x08\x0A-\x1F%]', { param($m) '%{0:X2}' -f [int][char]$m.Value })
}


function decodeContentIndexValue {
    # encodeContentIndexValue で符号化した値を戻す
    param (
        [string]$value
    )

    if ($value.IndexOf("%") -lt 0) {
        return $value
    }
    return [regex]::Replace($value, '%(?:[01][0-9A-F]|25)', { param($m) [string][char][Convert]::ToInt32($m.Value.Substring(1), 16) })
}


function convertPlaceToContentIndexMeta {
    # 今の場所の名前（TSV のファイル名。"見積[図形]"・"ページ001"・"スライド002（非表示）"・"スライド001_ノート" など）を、
    # 場所のメタ情報（[ordered] キー → 値）にする。convertContentIndexMetaToPlace で必ず元の名前に戻る形にし、
    # 分けられない名前は「部分=名前そのまま・対象=本文」にする
    param (
        [string]$book,
        [string]$place
    )

    $split = splitObjectPlace $place
    $target = if ($split.Kind) { $split.Kind } else { "本文" }
    $meta = [ordered]@{}
    switch (getContentIndexFileKind $book) {
        "Excel" {
            $meta["シート"] = $split.Base
            $meta["対象"] = $target
        }
        "Word" {
            if ($split.Base -match '^ページ(\d+)$') {
                $meta["ページ"] = [string][int]$Matches[1]
            } else {
                $meta["部分"] = $split.Base
            }
            $meta["対象"] = $target
        }
        "PowerPoint" {
            if (!$split.Kind -and $split.Base -match '^スライド(\d+)_ノート$') {
                $meta["スライド"] = [string][int]$Matches[1]
                $meta["対象"] = "ノート"
            } elseif ($split.Base -match '^スライド(\d+)(（非表示）)?$') {
                $meta["スライド"] = [string][int]$Matches[1]
                $meta["対象"] = $target
                if ($Matches[2]) { $meta["非表示"] = "はい" }
            } else {
                $meta["部分"] = $split.Base
                $meta["対象"] = $target
            }
        }
        default {
            $meta["部分"] = $split.Base
            $meta["対象"] = $target
        }
    }
    if ($split.Number -gt 0) {
        # 埋め込みの番号（"ページ003[埋め込み2]" → 対象=埋め込み・埋め込み=2。場所を始めるキーではない）
        $meta["埋め込み"] = [string]$split.Number
    }
    if ((convertContentIndexMetaToPlace $meta) -cne $place) {
        # 番号の桁が違う（"ページ1"）など、組み立て直すと同じ名前にならないものは、名前をそのまま持つ
        $meta = [ordered]@{ "部分" = $place; "対象" = "本文" }
    }
    return $meta
}


function convertContentIndexMetaToPlace {
    # 場所のメタ情報から、今の場所の名前（画面の表示・図形とコメントの除外・元のファイルを開く処理が使う形）を組み立てる
    param (
        $meta
    )

    $target = [string]$meta["対象"]
    $suffix = if ($target -eq ${placeKindShape} -or $target -eq ${placeKindComment} -or $target -eq ${placeKindHeaderFooter}) { "[$target]" } else { "" }
    if ($target -eq ${placeKindEmbed} -and $meta.Contains("埋め込み")) {
        $suffix = "[$target$([string]$meta["埋め込み"])]"
    }
    if ($meta.Contains("シート")) {
        return [string]$meta["シート"] + $suffix
    }
    if ($meta.Contains("ページ")) {
        return ("ページ{0:D3}" -f [int]$meta["ページ"]) + $suffix
    }
    if ($meta.Contains("スライド")) {
        $base = "スライド{0:D3}" -f [int]$meta["スライド"]
        if ($target -eq "ノート") {
            return "${base}_ノート"
        }
        if ($meta["非表示"] -eq "はい") {
            $base += "（非表示）"
        }
        return $base + $suffix
    }
    if ($target -eq "本文") {
        return [string]$meta["部分"]
    }
    return [string]$meta["部分"] + $suffix
}


function convertToContentIndexBody {
    # TSV の中身を、本文インデックスのファイルに入れる形（LF 区切り・末尾に LF・U+001C～U+001F を除く）にする。
    # 行の分け方は StreamReader.ReadLine と同じ（CRLF・LF・CR で分け、末尾の改行の後ろは行にしない）。中身が空なら空を返す
    param (
        [string]$text
    )

    if ($text.Length -eq 0) {
        return ""
    }
    $body = $text.Replace("`r`n", "`n").Replace("`r", "`n")
    if ($body.IndexOfAny([char[]]@([char]0x1C, [char]0x1D, [char]0x1E, [char]0x1F)) -ge 0) {
        $body = [regex]::Replace($body, '[\x1C-\x1F]', "")
    }
    if ($body.EndsWith("`n")) {
        return $body
    }
    return $body + "`n"
}


function convertBookToContentIndexBlock {
    # 元のファイル 1 つの中身から、本文インデックスのファイルに入れるまとまり（「ファイル名=」の行から最後の行まで）の文字列を作る。
    #   book: @{ Name（元のファイル名）; Places（@{ Place（今の場所の名前）; Text（TSV の中身） } の並び） }
    #         または @{ Name; Block }（前の本文インデックスのファイルから取り出したまとまり。そのまま返す）
    param (
        $book
    )

    if ($null -ne $book.Block) {
        return [string]$book.Block
    }
    $mark = [string]${contentIndexMark}
    $name = [string]$book.Name
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.Append("$mark ファイル名=").Append((encodeContentIndexValue $name)).Append("`n")
    $kind = getContentIndexFileKind $name
    if ($kind) {
        [void]$sb.Append("$mark 種類=$kind`n")
    }
    foreach ($place in $book.Places) {
        $meta = convertPlaceToContentIndexMeta $name ([string]$place.Place)
        foreach ($key in $meta.Keys) {
            [void]$sb.Append("$mark ").Append($key).Append("=").Append((encodeContentIndexValue ([string]$meta[$key]))).Append("`n")
        }
        [void]$sb.Append((convertToContentIndexBody ([string]$place.Text)))
    }
    return $sb.ToString()
}


function convertToContentIndexText {
    # 元のファイルの並びから、本文インデックスのファイルの文字列を作る（この順に書く）。
    #   books: convertBookToContentIndexBlock に渡せるもの（@{ Name; Places } か @{ Name; Block }）の並び
    param (
        $books
    )

    $sb = New-Object System.Text.StringBuilder
    [void]$sb.Append("$([string]${contentIndexMark}) 版=${contentIndexVersion}`n")
    foreach ($book in $books) {
        [void]$sb.Append((convertBookToContentIndexBlock $book))
    }
    return $sb.ToString()
}


function planContentIndexParts {
    # フォルダ 1 つの、拡張子ごと・番号ごとの本文インデックスのファイルに、どの元のファイルを入れるかを決める。
    #   parts  : 前の本文インデックスのファイルの並び。@{ Extension; Part; Books（@{ Name; Block } の並び。ファイルの中の順） }
    #   books  : 足す・入れ替える元のファイル（@{ Name; Block }）。元のファイル名の順に足す
    #   remove : 外す元のファイル名
    #   maxBytes: この大きさ（UTF-16 のバイト数）以上の本文インデックスのファイルには、もう足さない
    # 決め方:
    #   ・入れ替える元のファイルは、今入っている本文インデックスのファイルの同じ位置で入れ替える（ほかの本文インデックスのファイルへ移さない）
    #   ・外す元のファイルは、入っている本文インデックスのファイルから外す
    #   ・新しい元のファイルは、その拡張子の最後の番号の本文インデックスのファイルが maxBytes 未満ならそこに、以上なら次の番号の新しい本文インデックスのファイルに足す
    #   ・1 つの元のファイルは 2 つの本文インデックスのファイルにまたがらない（1 つで maxBytes を超えても、その 1 つで 1 つの本文インデックスのファイルにする）
    # @{ Extension; Part; Books; Changed（書き直しが要る） } の並び（拡張子・番号の順）を返す。
    # 元のファイルが無くなった本文インデックスのファイルは、Books が空で Changed が $true（消す）
    param (
        $parts,
        $books,
        [string[]]$remove = @(),
        [long]$maxBytes = ${contentIndexFileMaxBytes}
    )

    $removeSet = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($name in $remove) { [void]$removeSet.Add($name) }
    $replace = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($book in $books) { $replace[[string]$book.Name] = $book }

    $plan = New-Object System.Collections.Generic.List[hashtable]
    foreach ($part in @($parts | Sort-Object { $_.Extension }, { $_.Part })) {
        $kept = New-Object System.Collections.Generic.List[object]
        $changed = $false
        foreach ($book in $part.Books) {
            $name = [string]$book.Name
            if ($removeSet.Contains($name)) {
                $changed = $true
            } elseif ($replace.ContainsKey($name)) {
                $kept.Add($replace[$name])
                [void]$replace.Remove($name)
                $changed = $true
            } else {
                $kept.Add($book)
            }
        }
        $plan.Add(@{ Extension = [string]$part.Extension; Part = [int]$part.Part; Books = $kept; Changed = $changed })
    }

    # 新しい元のファイル（どの本文インデックスのファイルにも無かったもの）を、元のファイル名の順に足す
    foreach ($book in @($replace.Values | Sort-Object { [string]$_.Name })) {
        $extension = getContentIndexExtension ([string]$book.Name)
        $last = $null
        foreach ($p in $plan) {
            if ($p.Extension -eq $extension -and ($null -eq $last -or $p.Part -gt $last.Part)) { $last = $p }
        }
        if ($null -eq $last -or (measureContentIndexPartBytes $last.Books) -ge $maxBytes) {
            $number = if ($null -eq $last) { 1 } else { $last.Part + 1 }
            $last = @{ Extension = $extension; Part = $number; Books = (New-Object System.Collections.Generic.List[object]); Changed = $true }
            $plan.Add($last)
        }
        $last.Books.Add($book)
        $last.Changed = $true
    }
    return , @($plan | Sort-Object { $_.Extension }, { $_.Part })
}


function measureContentIndexPartBytes {
    # 本文インデックスのファイルの大きさ（UTF-16 のバイト数。BOM と版の行を含む）を、元のファイルのまとまり（@{ Name; Block }）の並びから求める
    param (
        $books
    )

    $chars = 1 + ("$([string]${contentIndexMark}) 版=${contentIndexVersion}`n").Length
    foreach ($book in $books) {
        $chars += ([string]$book.Block).Length
    }
    return [long]$chars * 2
}

function testContentIndexCellPrefixed {
    # 場所の行が「セル番地 + 区切りのタブ + 文字」の形か（Excel の図形・コメント）を返す。検索は、この形の行では区切りのタブより後だけを照合する
    param (
        [string]$book,
        $meta
    )

    $target = [string]$meta["対象"]
    return ((getContentIndexFileKind $book) -eq "Excel") -and ($target -eq ${placeKindShape} -or $target -eq ${placeKindComment})
}


function readContentIndexPlaces {
    # 本文インデックスのファイルの文字列を読み、場所ごとの @{ Book; Location（今の場所の名前）; CellPrefixed（行の先頭がセル番地と区切りのタブか）; Start（中身の先頭の位置）; End（中身の終わりの次の位置） }
    # を先頭から順に返す。版が分からないときは例外にする
    param (
        [string]$text
    )

    $places = New-Object System.Collections.Generic.List[hashtable]
    $mark = ${contentIndexMark}
    $placeKeys = ${contentIndexPlaceKeys}
    $book = ""
    $current = $null
    $meta = $null
    $versionSeen = $false
    $pos = $text.IndexOf($mark)
    while ($pos -ge 0) {
        $lineEnd = $text.IndexOf([char]10, $pos)
        if ($lineEnd -lt 0) { $lineEnd = $text.Length }
        $line = $text.Substring($pos + 2, [Math]::Max(0, $lineEnd - $pos - 2))
        $eq = $line.IndexOf("=")
        if ($eq -gt 0) {
            $key = $line.Substring(0, $eq)
            $value = decodeContentIndexValue $line.Substring($eq + 1)
            if ($key -eq "版") {
                if ($value -ne [string]${contentIndexVersion}) {
                    throw "集約ファイルの版が違います（$value）"
                }
                $versionSeen = $true
            } elseif ($key -eq "ファイル名" -or $placeKeys -contains $key) {
                if ($current) {
                    $current.End = $pos
                    $current.Location = convertContentIndexMetaToPlace $meta
                    $current.CellPrefixed = testContentIndexCellPrefixed $current.Book $meta
                    $places.Add($current)
                    $current = $null
                }
                if ($key -eq "ファイル名") {
                    $book = $value
                } else {
                    $meta = [ordered]@{ $key = $value }
                    $current = @{ Book = $book; Location = ""; CellPrefixed = $false; Start = $lineEnd + 1; End = $lineEnd + 1 }
                }
            } elseif ($current) {
                $meta[$key] = $value
                $current.Start = $lineEnd + 1
            }
        }
        $pos = if ($lineEnd -lt $text.Length) { $text.IndexOf($mark, $lineEnd + 1) } else { -1 }
    }
    if ($current) {
        $current.End = $text.Length
        $current.Location = convertContentIndexMetaToPlace $meta
        $current.CellPrefixed = testContentIndexCellPrefixed $current.Book $meta
        $places.Add($current)
    }
    if (!$versionSeen -and $text.Length -gt 0) {
        throw "集約ファイルの版がありません"
    }
    return , $places
}


function splitContentIndexTextByBook {
    # 本文インデックスのファイルの文字列を、元のファイルごとのまとまり（@{ Name; Block }。Block は「ファイル名=」の行から次の「ファイル名=」の行の前まで）
    # に分けて先頭から順に返す（元のファイルを入れ替えるとき、変わらないファイルをそのまま写すため）。版が違えば例外にする
    param (
        [string]$text
    )

    $books = New-Object System.Collections.Generic.List[hashtable]
    if ($text.Length -eq 0) {
        return , $books
    }
    $head = "$([string]${contentIndexMark}) ファイル名="
    $versionLine = "$([string]${contentIndexMark}) 版="
    $firstEnd = $text.IndexOf([char]10)
    if (!$text.StartsWith($versionLine, [System.StringComparison]::Ordinal) -or $firstEnd -lt 0 -or $text.Substring($versionLine.Length, $firstEnd - $versionLine.Length) -ne [string]${contentIndexVersion}) {
        throw "集約ファイルの版が違います"
    }
    $pos = $text.IndexOf("`n$head", [System.StringComparison]::Ordinal)
    while ($pos -ge 0) {
        $start = $pos + 1
        $lineEnd = $text.IndexOf([char]10, $start)
        $name = decodeContentIndexValue $text.Substring($start + $head.Length, $lineEnd - $start - $head.Length)
        $next = $text.IndexOf("`n$head", $lineEnd, [System.StringComparison]::Ordinal)
        $end = if ($next -ge 0) { $next + 1 } else { $text.Length }
        $books.Add(@{ Name = $name; Block = $text.Substring($start, $end - $start) })
        $pos = $next
    }
    return , $books
}


function getContentIndexBodyText {
    # 本文インデックスのファイルの文字列から、メタ情報の行（先頭が RS の行）を除いた中身だけを返す（システムインデックスの語を作るため。
    # メタ情報の「ファイル名」「シート」などの語が入ると、その語で探したときにどのフォルダも候補になってしまう）
    param (
        [string]$text
    )

    if ($text.IndexOf([char]0x1E) -lt 0) {
        return $text
    }
    return [regex]::Replace($text, "(?m)^\x1E[^\n]*\n?", "")
}
# ［検索］の検索対象ツリーのデータ集め（状態層。画面に触らない）。
# ワークスペースのフォルダを読むので、届かないネットワークのワークスペースでは、画面のスレッドでなく裏の列（network）から呼ぶ。
# 画面（ui\index_tree.ps1・ui\index\index_types.ps1 の IndexNode）は、この結果を受け取って組み立てるだけにする。

function testIndexBookName {
    # 元のファイルごとのフォルダと分かる拡張子か。Office は拡張子の形（.xls・.doc・.ppt で始まり 4～5 文字）で見分け、
    # テキストは対象の拡張子の一覧（shared\core\text_file.ps1 の testTextExtension。一覧はそこにだけある）で見分ける
    param (
        [string]$name
    )

    $ext = [System.IO.Path]::GetExtension($name).ToLowerInvariant()
    if ($ext.Length -ge 4 -and $ext.Length -le 5 -and
        ($ext.StartsWith(".xls") -or $ext.StartsWith(".doc") -or $ext.StartsWith(".ppt"))) {
        return $true
    }
    return ((testTextExtension $name) -or (testPdfExtension $name))
}

function testIndexBookDirPath {
    # 元のファイルごとのフォルダ（本文インデックスにする前の TSV・中身が空のファイルのフォルダ）か。名前が .xlsx などで終わる本物のフォルダと
    # 区別するため、サブフォルダも本文インデックスのファイル（content_index.*.tsv）も無いことも見る（content_index_store.ps1 の testIndexBookDir と同じ判定）
    param (
        [string]$dir
    )

    if (-not (testIndexBookName ([System.IO.Path]::GetFileName($dir.TrimEnd('\'))))) {
        return $false
    }
    try {
        # 列挙子（Enumerate*）を途中で抜けると、GC まで調べたフォルダを掴んだまま残り、インポートの上書きで
        # content_index\<名前> を移動できなくなる。直下だけなので配列（Get*）で受ける（ここの関数はどれも同じ）
        $long = toLongPath $dir
        if ([System.IO.Directory]::GetDirectories($long).Length -gt 0) { return $false }
        if ([System.IO.Directory]::GetFiles($long, ${contentIndexFilePattern}).Length -gt 0) { return $false }
        return $true
    } catch {
        return $false
    }
}

function testIndexFolderHasSubfolders {
    # インデックスのフォルダの直下に、本のフォルダでないサブフォルダがあるか
    param (
        [string]$dir
    )

    try {
        foreach ($sub in [System.IO.Directory]::GetDirectories((toLongPath $dir))) {
            if (-not (testIndexBookDirPath $sub)) { return $true }
        }
        return $false
    } catch {
        return $false
    }
}

function testIndexFolderHasFiles {
    # インデックスのフォルダの直下に、ファイル（本文インデックスのファイル・本文インデックスにする前の TSV）があるか
    param (
        [string]$dir
    )

    try {
        # 本文インデックスのファイル（content_index.<拡張子>.tsv。content_index_format.ps1 の contentIndexFilePattern）か、本文インデックスにする前の TSV があれば、フォルダ直下にファイルがある
        $long = toLongPath $dir
        if ([System.IO.Directory]::GetFiles($long, ${contentIndexFilePattern}).Length -gt 0) { return $true }
        foreach ($sub in [System.IO.Directory]::GetDirectories($long)) {
            if (-not (testIndexBookDirPath $sub)) { continue }
            if ([System.IO.Directory]::GetFiles($sub, "*.tsv").Length -gt 0) { return $true }
        }
        return $false
    } catch {
        return $false
    }
}

function getIndexFolderChildren {
    # インデックスのフォルダ（dir）の子を @{ HasFiles; Folders = @(@{ Name; HasSubfolders }); Error } で返す。
    # Folders は本のフォルダを除いた名前順。読めなかったときは Error に文面を入れ、Folders は空にする
    param (
        [string]$dir
    )

    $names = New-Object System.Collections.Generic.List[string]
    try {
        foreach ($sub in [System.IO.Directory]::GetDirectories((toLongPath $dir))) {
            if (testIndexBookDirPath $sub) { continue }
            $names.Add([System.IO.Path]::GetFileName($sub))
        }
    } catch {
        return @{ HasFiles = $false; Folders = @(); Error = $_.Exception.Message }
    }
    $names.Sort([System.StringComparer]::CurrentCultureIgnoreCase)
    $folders = @($names | ForEach-Object {
        @{ Name = $_; HasSubfolders = (testIndexFolderHasSubfolders (Join-Path $dir $_)) }
    })
    return @{ HasFiles = (testIndexFolderHasFiles $dir); Folders = $folders; Error = "" }
}

function getIndexTreeData {
    # 検索対象ツリーの材料を集める。
    #   dir: インデックスのフォルダ（work\index）  paths: 展開していたフォルダ・チェックを外したフォルダ（インデックスの根から先祖すべての子も返す）
    # 返すもの: @{ State（getPathState の State）; Message; Root; Sources（getSourceFolderMap の結果）;
    #   Indexes = @(@{ Name; SourcePath; Exists; HasSubfolders }); Children = @{ <フォルダ> = getIndexFolderChildren の結果 } }
    # インデックスのフォルダに接続できない・その他のときは、列挙せずに State と文面だけを返す
    # （Test-Path が $false を返して「インデックスが無い」と取り違えないため）
    param (
        [string]$dir,
        [string]$statusPath,
        [string]$settingsPath,
        [string[]]$paths = @()
    )

    $result = @{ State = ${pathStateMissing}; Message = ""; Root = $dir; Sources = @{}; Indexes = @(); Children = @{} }
    $state = getPathState $dir
    if ($state.State -ne ${pathStateFound}) {
        $result.State = $state.State
        $result.Message = $state.Message
        return $result
    }
    $result.State = ${pathStateFound}

    $data = getSearchIndexData $dir $statusPath $settingsPath
    $root = [string]$data.Root
    $result.Root = $root
    $result.Sources = $data.Sources
    $indexes = New-Object System.Collections.Generic.List[object]
    foreach ($index in @($data.Indexes)) {
        $path = "$root\$($index.Name)"
        $exists = [System.IO.Directory]::Exists((toLongPath $path))
        $indexes.Add(@{
            Name          = $index.Name
            SourcePath    = $(if ($index.SourcePath) { [string]$index.SourcePath } else { "" })
            Exists        = $exists
            HasSubfolders = ($exists -and (testIndexFolderHasSubfolders $path))
        })
    }
    $result.Indexes = $indexes.ToArray()

    # 先祖すべての子を入れる（深い階層の展開・除外を戻すため）
    foreach ($index in $indexes) {
        if (-not $index.Exists) { continue }
        $indexRoot = "$root\$($index.Name)"
        foreach ($target in @($paths)) {
            $target = ([string]$target).TrimEnd("\")
            $isRoot = $target.Equals($indexRoot, [System.StringComparison]::OrdinalIgnoreCase)
            if (-not $isRoot -and -not $target.StartsWith("$indexRoot\", [System.StringComparison]::OrdinalIgnoreCase)) { continue }
            $segments = @($target.Substring($indexRoot.Length).Split([char[]]@("\"), [System.StringSplitOptions]::RemoveEmptyEntries))
            $current = $indexRoot
            for ($i = 0; $i -le $segments.Count; $i++) {
                if (-not $result.Children.ContainsKey($current)) {
                    $result.Children[$current] = getIndexFolderChildren $current
                }
                if ($i -ge $segments.Count) { break }
                $next = $segments[$i]
                $known = $result.Children[$current]
                if (-not (@($known.Folders) | Where-Object { $_.Name -ieq $next })) { break }
                $current = "$current\$next"
            }
        }
    }
    return $result
}

# 検索用の本文インデックスのファイル（content_index_format.ps1）の読み書き（状態層）。
# 本文インデックスのファイルは work\content_index の中のフォルダごと・元のファイルの拡張子ごとに、大きさで分けて置く（content_index.xlsx.001.tsv など）。UTF-16LE（BOM 付き）で書く
# （UTF-8 より文字列への変換が速い。日本語が多いと大きさはほとんど変わらない）。

function writeContentIndexFile {
    # 本文インデックスのファイルを書く。一時ファイル（<名前>.tmp）に書き終えてから置き換えるため、途中で止まっても前のファイルが残る
    param (
        [string]$path,
        [string]$text
    )

    $longPath = toLongPath $path
    $tmp = "$longPath.tmp"
    [System.IO.File]::WriteAllText($tmp, $text, [System.Text.UnicodeEncoding]::new($false, $true))
    if ([System.IO.File]::Exists($longPath)) {
        # 3 つ目の引数（控え）に $null を渡すと PowerShell が空の文字列にして例外になるため、NullString を渡す
        [System.IO.File]::Replace($tmp, $longPath, [NullString]::Value)
    } else {
        [System.IO.File]::Move($tmp, $longPath)
    }
}


function readContentIndexText {
    # 本文インデックスのファイルを文字列で読む（インデックス作成中の置き換えと同時に読めるよう、共有モードは ReadWrite|Delete）
    param (
        [string]$path
    )

    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $stream = [System.IO.FileStream]::new((toLongPath $path), [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    $reader = [System.IO.StreamReader]::new($stream, [System.Text.Encoding]::Unicode, $true)
    try {
        return $reader.ReadToEnd()
    } finally {
        $reader.Dispose()
    }
}


function readContentIndexRange {
    # 本文インデックスのファイル（UTF-16LE・BOM 付き）の、文字の位置 start（含む）から end（含まない）までを start から数えて、
    # firstLine 行目の先頭（firstLine が 1 以下なら start）から lines 個目の改行までを文字列で返す（それより前の行は持たない）。
    # BOM が無い（UTF-16LE でない）ときは $null（呼び出し側が全体を読む）。
    # checkpoints（ハッシュテーブル）を渡すと、通った 200 行ごとの行の先頭（行の番号 → 文字の位置）を足す
    # （start の行の番号が baseLine。次に読むとき、目当ての行の手前の位置から読めるようにする）
    param (
        [string]$path,
        [int]$start,
        [int]$end,
        [int]$firstLine,
        [int]$lines,
        [int]$baseLine = 1,
        $checkpoints = $null
    )

    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $stream = [System.IO.FileStream]::new((toLongPath $path), [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    try {
        $bom = New-Object byte[] 2
        if ($stream.Read($bom, 0, 2) -ne 2 -or $bom[0] -ne 0xFF -or $bom[1] -ne 0xFE) { return $null }
        [void]$stream.Seek(2L + 2L * $start, [System.IO.SeekOrigin]::Begin)
        $reader = [System.IO.StreamReader]::new($stream, [System.Text.UnicodeEncoding]::new($false, $false), $false)
        $builder = New-Object System.Text.StringBuilder
        $buffer = New-Object char[] 65536
        $remaining = $end - $start
        $newlines = 0
        $skip = [Math]::Max(0, $firstLine - 1)
        $started = ($skip -eq 0)
        while ($remaining -gt 0 -and $newlines -lt $lines) {
            $consumed = ($end - $start) - $remaining
            $got = $reader.Read($buffer, 0, [Math]::Min($buffer.Length, $remaining))
            if ($got -le 0) { break }
            $keepFrom = if ($started) { 0 } else { -1 }
            $from = 0
            while ($from -lt $got) {
                $found = [Array]::IndexOf($buffer, [char]10, $from, $got - $from)
                if ($found -lt 0) { break }
                $newlines++
                $from = $found + 1
                if ($null -ne $checkpoints) {
                    $nextLine = $baseLine + $newlines
                    if (($nextLine - 1) % 200 -eq 0) { $checkpoints[$nextLine] = $start + $consumed + $from }
                }
                if (!$started -and $newlines -eq $skip) { $started = $true; $keepFrom = $from }
            }
            # 読み飛ばす行のチャンクは捨てる（行数だけ数える）
            if ($keepFrom -ge 0 -and $keepFrom -lt $got) { [void]$builder.Append($buffer, $keepFrom, $got - $keepFrom) }
            $remaining -= $got
        }
        return $builder.ToString()
    } finally {
        $stream.Dispose()
    }
}


function testIndexBookDir {
    # インデックスの中のフォルダが、元のファイルごとのフォルダ（<ファイル名.xlsx>\<場所>.tsv。本文インデックスのファイルに入れる前の TSV の置き場所）か。
    # 名前だけでは、名前が .xlsx などで終わる本物のフォルダ（元のフォルダの名前をそのまま使う）と区別できないため、中身も見る:
    #   ・名前が Office・テキストの拡張子で終わる（indexBookDirPattern）
    #   ・サブフォルダも本文インデックスのファイル（content_index.<拡張子>.tsv）も無い
    #   ・withTsv なら、TSV が 1 つ以上ある（取り込んだが中身が空のファイルのフォルダは、本文インデックスのファイルに入れるものが無い）
    # 読めないフォルダは $false（本文インデックスのファイルに入れる・消す対象にしない）
    param (
        [string]$dir,
        [bool]$withTsv = $true
    )

    if ([System.IO.Path]::GetFileName($dir.TrimEnd("\")) -notmatch ${indexBookDirPattern}) {
        return $false
    }
    $long = toLongPath $dir
    try {
        # 途中で戻っても、調べたフォルダを掴んだまま残さない（testAnyEntry・配列で受ける GetFiles）
        if (testAnyEntry ([System.IO.Directory]::EnumerateDirectories($long))) {
            return $false
        }
        $hasTsv = $false
        foreach ($file in [System.IO.Directory]::GetFiles($long, "*.tsv")) {
            if ([System.IO.Path]::GetFileName($file) -like ${contentIndexFilePattern}) {
                return $false
            }
            $hasTsv = $true
        }
        return ($hasTsv -or !$withTsv)
    } catch {
        return $false
    }
}

function getIndexFolderBooks {
    # 今の形式のインデックスのフォルダ 1 つ（直下の <ファイル名.xlsx>\<場所>.tsv）から、本文インデックスのファイルに入れる元のファイルの並びを作る。
    # 並びは今の検索結果と同じ順（前の名前の付け方（フォルダのパス + encodeIndexPlace 場所 + ".tsv"）で並べたときと同じ順に
    # なるよう、実際のファイル名（英語の固定名・符号化したシート名）から場所を戻し、その前の名前の付け方の文字列を並べ替えの鍵にする）。
    # @{ Name; Places（@{ Place; Path } の並び） } の並びを返す
    param (
        [string]$folder
    )

    $longDir = toLongPath $folder
    $entries = New-Object System.Collections.Generic.List[hashtable]
    $keys = New-Object System.Collections.Generic.List[string]
    foreach ($sub in [System.IO.Directory]::EnumerateDirectories($longDir)) {
        if (!(testIndexBookDir $sub)) {
            continue
        }
        $name = [System.IO.Path]::GetFileName($sub)
        foreach ($path in [System.IO.Directory]::GetFiles($sub, "*.tsv", [System.IO.SearchOption]::TopDirectoryOnly)) {
            # 長いパス（\\?\ 付き）は [System.IO.Path]::GetDirectoryName で崩れることがあるため、
            # ここで分かっている $sub・$name をそのまま使い、$path から作り直さない。
            $place = convertIndexFileNameToPlace ([System.IO.Path]::GetFileNameWithoutExtension($path))
            $legacyName = "{0}.tsv" -f (encodeIndexPlace $place)
            # Join-Path は \\?\ 付きの長いパスで「drive」が null というエラーになるため、
            # プロバイダーを介さない [System.IO.Path]::Combine で組み立てる。
            $key = [System.IO.Path]::Combine($sub, $legacyName)
            $entries.Add(@{ Name = $name; Place = $place; Path = $path })
            $keys.Add($key)
        }
    }
    $keyArray = $keys.ToArray()
    $entryArray = $entries.ToArray()
    [System.Array]::Sort($keyArray, $entryArray, [System.StringComparer]::CurrentCultureIgnoreCase)

    $books = New-Object System.Collections.Generic.List[hashtable]
    $current = $null
    foreach ($entry in $entryArray) {
        if (!$current -or $current.Name -ne $entry.Name) {
            $current = @{ Name = $entry.Name; Places = New-Object System.Collections.Generic.List[hashtable] }
            $books.Add($current)
        }
        $current.Places.Add(@{ Place = $entry.Place; Path = $entry.Path })
    }
    return , $books
}


function convertFolderToContentIndex {
    # 今の形式のインデックスのフォルダ 1 つ（直下の <ファイル名.xlsx>\<場所>.tsv）から、拡張子ごと・番号ごとの本文インデックスのファイル
    # （destFolder\content_index.xlsx.001.tsv など）を書く。destFolder に前の本文インデックスのファイルがあれば、それとまぜる（planContentIndexParts）:
    #   ・TSV のある元のファイルは、TSV の中身で入れ替える（前の本文インデックスのファイルに無ければ、最後の番号の本文インデックスのファイルに足す。
    #     contentIndexFileMaxBytes 以上なら次の番号の本文インデックスのファイルを作る）
    #   ・removeBooks に挙げた元のファイルは外す（元のファイルが無くなった）
    #   ・それ以外の元のファイルは、前の本文インデックスのファイルのまま。変わらない本文インデックスのファイルは書き直さない
    # 元のファイルが無くなった本文インデックスのファイルは消す。removeTsv なら、本文インデックスのファイルを書き終えた後に、
    # 読み込んだ元のファイルのフォルダ（TSV）を消す（TSV は一時的な置き場で、残すとインデックスの容量が倍になるため）。
    # 書き終える前に止まっても、TSV か前の本文インデックスのファイルのどちらかに中身が残る。
    # @{ Books; Tsv; Chars; Files（本文インデックスのファイルの数）; Written（書き直した数）;
    #    Texts（そのフォルダのすべての本文インデックスのファイルの中身。システムインデックスを読み直さずに作るため） } を返す
    param (
        [string]$folder,
        [string]$destFolder,
        [string[]]$removeBooks = @(),
        [bool]$removeTsv = $false,
        [long]$maxBytes = ${contentIndexFileMaxBytes}
    )

    $books = getIndexFolderBooks $folder
    $tsvCount = 0
    $newBooks = New-Object System.Collections.Generic.List[hashtable]
    foreach ($book in $books) {
        foreach ($place in $book.Places) {
            $place.Text = [System.IO.File]::ReadAllText($place.Path)
            $tsvCount++
        }
        $newBooks.Add(@{ Name = $book.Name; Block = (convertBookToContentIndexBlock $book) })
    }
    $longDest = toLongPath $destFolder
    # 前の本文インデックスのファイル（番号の付いた名前のもの）を読む
    $parts = New-Object System.Collections.Generic.List[hashtable]
    $oldTexts = @{}
    if ([System.IO.Directory]::Exists($longDest)) {
        foreach ($old in [System.IO.Directory]::GetFiles($longDest, ${contentIndexFilePattern})) {
            $info = readContentIndexFileName ([System.IO.Path]::GetFileName($old))
            if ($null -eq $info) { continue }
            $text = readContentIndexText $old
            $oldTexts[(getContentIndexFileName $info.Extension $info.Part)] = $text
            $parts.Add(@{ Extension = $info.Extension; Part = $info.Part; Books = (splitContentIndexTextByBook $text) })
        }
    }

    $plan = planContentIndexParts $parts $newBooks $removeBooks $maxBytes
    $texts = New-Object System.Collections.Generic.List[string]
    $bookTotal = 0
    $written = 0
    $chars = 0L
    foreach ($part in $plan) {
        $name = getContentIndexFileName $part.Extension $part.Part
        $path = Join-Path $destFolder $name
        if ($part.Books.Count -eq 0) {
            if ([System.IO.File]::Exists((toLongPath $path))) { [System.IO.File]::Delete((toLongPath $path)) }
            continue
        }
        if ($part.Changed) {
            [void][System.IO.Directory]::CreateDirectory($longDest)
            $text = convertToContentIndexText $part.Books
            writeContentIndexFile $path $text
            $written++
        } else {
            $text = $oldTexts[$name]
        }
        $texts.Add($text)
        $bookTotal += $part.Books.Count
        $chars += $text.Length
    }
    if ($removeTsv) {
        foreach ($book in $books) {
            $bookDir = [System.IO.Path]::GetDirectoryName($book.Places[0].Path)
            removeDirectoryRetry $bookDir
        }
    }
    return @{ Books = $bookTotal; Tsv = $tsvCount; Chars = $chars; Files = $texts.Count; Written = $written; Texts = [string[]]$texts.ToArray() }
}

function updateFolderContentIndex {
    # インデックスのフォルダ 1 つで、置かれた TSV（追加・更新した元のファイル）を本文インデックスのファイルに入れ、TSV を消す。
    # removeBooks に挙げた元のファイル（無くなったもの）は本文インデックスのファイルから外す
    param (
        [string]$folder,
        [string[]]$removeBooks = @()
    )

    return convertFolderToContentIndex $folder $folder $removeBooks $true
}

function findContentIndexFiles {
    # インデックスのフォルダ以下の本文インデックスのファイルを列挙し、フォルダの順・フォルダの中は名前の順に並べて返す。
    #   root   : インデックスのフォルダ（相対パスの基準）
    #   relPath: その中のフォルダ（空は root 自身）
    #   recurse: $false なら、そのフォルダの本文インデックスのファイルだけ
    # 各要素は @{ Path（\\?\ 付き）; Root; RelDir（root からのフォルダ）; RelPath; Ticks; Size }
    param (
        [string]$root,
        [string]$relPath = "",
        [bool]$recurse = $true
    )

    $root = $root.TrimEnd("\")
    $relPath = $relPath.Trim("\")
    $dir = if ($relPath) { "${root}\${relPath}" } else { $root }
    $longDir = toLongPath $dir
    if (![System.IO.Directory]::Exists($longDir)) {
        return , @()
    }
    $option = if ($recurse) { [System.IO.SearchOption]::AllDirectories } else { [System.IO.SearchOption]::TopDirectoryOnly }
    $found = [System.IO.DirectoryInfo]::new($longDir).GetFiles(${contentIndexFilePattern}, $option)
    $plainDir = fromLongPath $longDir
    $list = New-Object System.Collections.Generic.List[hashtable]
    foreach ($file in $found) {
        $full = $plainDir + $file.FullName.Substring($longDir.Length)
        $rel = $full.Substring($root.Length + 1)
        $list.Add(@{
            Path = $file.FullName; Root = $root; RelPath = $rel
            RelDir = [string][System.IO.Path]::GetDirectoryName($rel)
            Ticks = $file.LastWriteTimeUtc.Ticks; Size = $file.Length
        })
    }
    # フォルダの順、フォルダの中は本文インデックスのファイルの名前の順（現在のカルチャ・大文字と小文字を区別しない）
    $items = [hashtable[]]@($list | Sort-Object @{ Expression = { $_.RelDir } }, @{ Expression = { [System.IO.Path]::GetFileName($_.RelPath) } })
    return , $items
}


function findIndexFoldersWithBooks {
    # インデックスのフォルダ以下で、元のファイルごとのフォルダ（<ファイル名.xlsx>。本文インデックスのファイルに入れる前の TSV）が
    # 直下にあるフォルダを返す（インデックス作成が途中で止まったとき）。root 自身も含む
    param (
        [string]$root
    )

    $found = New-Object System.Collections.Generic.List[string]
    $longRoot = toLongPath $root.TrimEnd("\")
    if (![System.IO.Directory]::Exists($longRoot)) {
        return , $found.ToArray()
    }
    $dirs = @($longRoot) + @([System.IO.Directory]::GetDirectories($longRoot, "*", [System.IO.SearchOption]::AllDirectories))
    foreach ($dir in $dirs) {
        if ($dir -ne $longRoot -and (testIndexBookDir $dir $false)) { continue }
        if (testAnyEntry ([System.IO.Directory]::EnumerateDirectories($dir)) { param ($sub) testIndexBookDir $sub }) {
            $found.Add((fromLongPath $dir))
        }
    }
    return , $found.ToArray()
}


function publishIndexFolders {
    # インデックス作成で TSV を置いた・元のファイルが無くなったフォルダを、まとめて書き出す。フォルダごとに次を続けて行う:
    #   1. 本文インデックスのファイルを書く（前の本文インデックスのファイルとまぜ、無くなった元のファイルは外す）
    #   2. 元のファイルごとのフォルダの TSV を消す
    #   3. 書いた本文インデックスのファイルの中身から、そのフォルダのシステムインデックスの txt を作る（読み直さない）
    # txt の状態（反映待ち）はまとめて状態ファイルに書く。書き出したフォルダの数を返す。
    #   pending: フォルダ（フルパス）→ 無くなった元のファイル名の集まり
    param (
        $pending,
        [string]$indexRoot = $workspace.IndexDir,
        [string]$systemRoot = $workspace.SystemIndexDir,
        [string]$statePath = $workspace.SystemIndexStateFile
    )

    $results = New-Object System.Collections.Generic.List[hashtable]
    foreach ($folder in @($pending.Keys)) {
        $contentIndexFile = updateFolderContentIndex $folder ([string[]]@($pending[$folder]))
        # 書いた本文インデックスのファイルは、フォルダごとに書いた直後にここで NotContentIndexed を付ける（件数が多いため失敗してもログに出さない）
        [void](setNotContentIndexed $folder)
        $results.Add((writeSystemIndexFolder $folder $indexRoot $systemRoot $contentIndexFile.Texts))
    }
    if ($results.Count -gt 0) {
        $saved = updateSystemIndexState { param ($state) setSystemIndexResults $state $results.ToArray() } $statePath
        if (!$saved) {
            writeIndexerLog "システムインデックスの状態を書き込めませんでした（インデックス作成の終わりに作り直します）。" "Yellow"
        }
    }
    return $results.Count
}


function readContentIndexLines {
    # 本文インデックスのファイルの中の、元のファイル book・場所 location の firstLine 行目から count 行を返す（画面の選択行のプレビュー。
    # 行の数え方は検索と同じ）。戻り値は @{ Rows = @{ LineNumber; Line } の配列; End = 頼んだ数より少なく返ったか（場所の終わりまで読んだ）; Marks = 更新した控え }。
    # cache（検索のキャッシュ）に同じ本文インデックスのファイルの内容があれば、ファイルを読み直さない。読めない・見つからなければ Rows は空・End は $true。
    #
    # marks は、繰り返し読むときに先頭から読み飛ばさないための控え（@{ Path; Ticks; Size; Places; Checkpoints }。
    # ファイルのパス・更新日時・大きさが同じ間だけ使う）。呼び出し側が引数で渡し、戻り値の Marks で受け取る
    # （読み足しは別の runspace で動くため、$script: には置かない。渡された控えは書き換えず、新しいものを返す）。
    # Places は場所の一覧、Checkpoints は場所ごと（Book と Location をタブでつないだ名前）の、200 行ごとの行の先頭の位置（行の番号 → 文字の位置）
    param (
        [string]$path,
        [string]$book,
        [string]$location,
        [int]$firstLine,
        [int]$count,
        $cache = $null,
        $marks = $null
    )

    $first = [Math]::Max(1, $firstLine)
    $last = $first + $count - 1
    if ($count -le 0) { return @{ Rows = @(); End = $false; Marks = $marks } }
    $nothing = @{ Rows = @(); End = $true; Marks = $marks }
    $text = $null
    $places = $null
    $longPath = toLongPath $path
    $entry = $null
    if ($null -ne $cache -and $cache.Texts.TryGetValue($longPath, [ref]$entry) -and $entry.Count -ge 4) {
        $info = [System.IO.FileInfo]::new($longPath)
        if ($info.Exists -and $entry[0] -eq $info.LastWriteTimeUtc.Ticks -and $entry[1] -eq $info.Length) {
            $text = $entry[2]
            $places = $entry[3]
        }
    }
    $isRange = $false
    $newMarks = $marks
    $checkpoints = $null
    $allCheckpoints = $null
    $placeKey = "$book`t$location"
    try {
        if ($null -eq $text) {
            # キャッシュに無いときは、ファイルの全体を文字列にしない。控えがあれば、その場所の目当ての行の手前の位置から必要な行までだけを読む
            # （続けて読むたびに、全体を読み直さず、場所の先頭からも読み飛ばさない）
            $info = [System.IO.FileInfo]::new($longPath)
            if (!$info.Exists) { return $nothing }
            if ($null -ne $marks -and $marks.Path -eq $longPath -and $marks.Ticks -eq $info.LastWriteTimeUtc.Ticks -and $marks.Size -eq $info.Length) {
                $places = $marks.Places
                $allCheckpoints = $(if ($null -ne $marks.Checkpoints) { $marks.Checkpoints.Clone() } else { @{} })
                $found = $false
                foreach ($place in $places) {
                    if ($place.Book -ne $book -or $place.Location -ne $location) { continue }
                    $found = $true
                    # 位置は場所ごとに控える（行の番号が同じでも、別の場所の位置は使わない）
                    $checkpoints = $(if ($allCheckpoints.ContainsKey($placeKey)) { $allCheckpoints[$placeKey].Clone() } else { @{} })
                    $allCheckpoints[$placeKey] = $checkpoints
                    $base = 1
                    $startPosition = $place.Start
                    foreach ($key in $checkpoints.Keys) {
                        if ($key -le $first -and $key -gt $base) { $base = $key; $startPosition = $checkpoints[$key] }
                    }
                    $text = readContentIndexRange $path $startPosition $place.End ($first - $base + 1) ($last - $base + 1) $base $checkpoints
                    break
                }
                # 控えが今のファイルのものなら、無い場所はファイルを読まずに空
                if (!$found) { return $nothing }
                if ($null -ne $text) {
                    # 読んでいる間にファイルが置き換わっていたら、古い位置で読んだ行は使わず、全体を読み直す
                    $again = [System.IO.FileInfo]::new($longPath)
                    if ($again.Exists -and $again.LastWriteTimeUtc.Ticks -eq $info.LastWriteTimeUtc.Ticks -and $again.Length -eq $info.Length) { $isRange = $true } else { $text = $null }
                }
            }
            if ($null -eq $text) {
                $text = readContentIndexText $path
                $places = readContentIndexPlaces $text
                $checkpoints = @{}
                $allCheckpoints = @{ $placeKey = $checkpoints }
            }
            $newMarks = @{ Path = $longPath; Ticks = $info.LastWriteTimeUtc.Ticks; Size = $info.Length; Places = $places; Checkpoints = $allCheckpoints }
        }
    } catch [System.IO.IOException] {
        return $nothing
    } catch [System.UnauthorizedAccessException] {
        return $nothing
    }
    $rows = New-Object System.Collections.Generic.List[psobject]
    $isTextBook = (getContentIndexFileKind $book) -eq "テキスト"
    foreach ($place in $places) {
        if ($place.Book -ne $book -or $place.Location -ne $location) { continue }
        # 範囲だけ読んだときは、text の先頭が $first 行目の先頭
        $number = if ($isRange) { $first - 1 } else { 0 }
        $placeEnd = if ($isRange) { $text.Length } else { [Math]::Min($place.End, $text.Length) }
        $pos = if ($isRange) { 0 } else { $place.Start }
        # ファイルの全体を読んだときは、通った 200 行ごとの行の先頭を控える（範囲を読んだときは readContentIndexRange が控える）
        $record = !$isRange -and $null -ne $checkpoints
        while ($pos -lt $placeEnd) {
            $n = $text.IndexOf([char]10, $pos, $placeEnd - $pos)
            if ($n -lt 0) { $n = $placeEnd }
            $number++
            if ($record -and $number -gt 1 -and ($number - 1) % 200 -eq 0) { $checkpoints[$number] = $pos }
            if ($number -gt $last) { break }
            if ($number -ge $first) {
                $line = $text.Substring($pos, $n - $pos)
                if ($isTextBook) {
                    # 前後の行はどこが一致したかが分からないため、先頭から切る
                    $line = truncateHitLine $line -1
                }
                $rows.Add([pscustomobject]@{ LineNumber = $number; Line = $line })
            }
            $pos = $n + 1
        }
        break
    }
    return @{ Rows = $rows.ToArray(); End = ($rows.Count -lt $count); Marks = $newMarks }
}


# システムインデックス（system_index の txt）と、その状態ファイル（system_index_state.tsv）の読み書き（状態層）。
# txt は index の中のフォルダ 1 つにつき 1 つ（分けたときは複数）で、index と同じ相対パスの system_index の中に置く。
# 中身は、そのフォルダ直下の本文インデックスのファイル（content_index.<拡張子>.tsv）と、インデックス作成の途中で残った、直下のブックのフォルダ（<ファイル名.xlsx>）の中の TSV から作る（search_gram.ps1）。
# 本文インデックスのファイルのメタ情報の行は除く（getContentIndexBodyText）。

function getSystemIndexFolderTsvPaths {
    # index の中のフォルダ 1 つの、システムインデックスの元になるファイル（直下の本文インデックスのファイル・TSV と、直下のブックのフォルダの中の TSV。\\?\ 付き）。
    # 検索対象のツリーで「フォルダ直下のファイル」を選んだときと同じ範囲（getContentIndexFiles の Recurse = $false）
    param (
        [string]$folder
    )

    $long = toLongPath $folder
    $paths = New-Object System.Collections.Generic.List[string]
    if (![System.IO.Directory]::Exists($long)) {
        return , $paths.ToArray()
    }
    $paths.AddRange([System.IO.Directory]::GetFiles($long, "*.tsv"))
    foreach ($sub in [System.IO.Directory]::GetDirectories($long)) {
        if (testIndexBookDir $sub) {
            $paths.AddRange([System.IO.Directory]::GetFiles($sub, "*.tsv"))
        }
    }
    return , $paths.ToArray()
}

function writeSystemIndexFolder {
    # index の中のフォルダ 1 つについて、system_index の txt を作り直す。
    # @{ Rel（index からの相対パス）; Files（@{ Rel（system_index からの txt の相対パス）; Ticks（更新日時。UTC の Ticks） } の配列）;
    #    Excluded（パスが長すぎて作らなかった） } を返す。本文インデックスのファイル・TSV が無くなったフォルダは txt を消して Files を空で返す
    #   texts: そのフォルダの本文インデックスのファイルの中身（インデックス作成で書いたばかりのもの）。渡せばファイルを読み直さない
    param (
        [string]$folder,
        [string]$indexRoot,
        [string]$systemRoot,
        [string[]]$texts = $null
    )

    $rel = $folder.Substring($indexRoot.TrimEnd("\").Length).Trim("\")
    $outDir = "$($systemRoot.TrimEnd('\'))\$rel"
    $longOut = toLongPath $outDir
    $result = @{ Rel = $rel; Files = @(); Excluded = $false }

    # 前の txt（分けた数が変わることもあるため、すべて）を消す
    if ([System.IO.Directory]::Exists($longOut)) {
        foreach ($old in [System.IO.Directory]::GetFiles($longOut, "$([System.IO.Path]::GetFileNameWithoutExtension(${systemIndexFileName}))*.txt")) {
            [System.IO.File]::Delete($old)
        }
    }
    $set = New-Object 'System.Collections.Generic.HashSet[uint32]'
    if ($null -ne $texts) {
        if ($texts.Count -eq 0) {
            return $result
        }
        foreach ($text in $texts) {
            addTextGrams $set (getContentIndexBodyText $text)
        }
    } else {
        $tsvPaths = getSystemIndexFolderTsvPaths $folder
        if ($tsvPaths.Count -eq 0) {
            return $result
        }
        foreach ($path in $tsvPaths) {
            $text = [System.IO.File]::ReadAllText($path)
            if ([System.IO.Path]::GetFileName($path) -like ${contentIndexFilePattern}) {
                $text = getContentIndexBodyText $text
            }
            addTextGrams $set $text
        }
    }
    $values = New-Object 'uint32[]' $set.Count
    $set.CopyTo($values)
    [Array]::Sort($values)
    $parts = getGramPartCount $values.Length
    if (!(testSystemIndexPath $outDir $parts)) {
        $result.Excluded = $true
        return $result
    }

    [System.IO.Directory]::CreateDirectory($longOut) | Out-Null
    $perPart = [int][Math]::Ceiling($values.Length / $parts)
    $names = getSystemIndexFileNames $parts
    $files = New-Object System.Collections.Generic.List[hashtable]
    for ($p = 0; $p -lt $parts; $p++) {
        $start = $p * $perPart
        $text = convertToGramText $values $start ([Math]::Min($perPart, $values.Length - $start))
        $path = "$longOut\$($names[$p])"
        [System.IO.File]::WriteAllText($path, $text, [System.Text.Encoding]::ASCII)
        $files.Add(@{ Rel = "$rel\$($names[$p])"; Ticks = [System.IO.File]::GetLastWriteTimeUtc($path).Ticks })
    }
    $result.Files = $files.ToArray()
    return $result
}

# txt をまとめて作るときのスレッドの数の上限（物理メモリ 8GB の PC で 4 スレッドのときにメモリが足りなくなったことがあるため）
${systemIndexWorkerMax} = 4

function writeSystemIndexFolders {
    # index の中のフォルダの txt を、まとめて作り直す（並列）。writeSystemIndexFolder の結果の配列を返す。
    #   shouldStop: $true を返すと、始めていない分を作らずに止める（作った分だけを返す）
    param (
        [string[]]$folders,
        [string]$indexRoot,
        [string]$systemRoot,
        [int]$workers = 0,
        [scriptblock]$shouldStop = $null
    )

    $results = New-Object System.Collections.Generic.List[hashtable]
    if ($folders.Count -eq 0) {
        return , $results.ToArray()
    }
    if ($workers -le 0) {
        $workers = [Math]::Min([Environment]::ProcessorCount, ${systemIndexWorkerMax})
    }
    $workers = [Math]::Min($workers, $folders.Count)
    if ($workers -le 1) {
        foreach ($folder in $folders) {
            if ($shouldStop -and (& $shouldStop)) {
                break
            }
            $results.Add((writeSystemIndexFolder $folder $indexRoot $systemRoot))
        }
        return , $results.ToArray()
    }

    # 各スレッドには必要な関数・値だけを読み込む（lib.ps1 全体を読み込むと、スレッドを用意するだけで時間がかかるため）。
    # インデックス作成の処理のため、スレッドの優先度を下げる（画面・検索を先に動かす。docs/design/structure/threads.md「スレッドの一覧」）
    $state = newWorkerState @("writeSystemIndexFolder", "getSystemIndexFolderTsvPaths", "addTextGrams", "convertToGramText",
        "getGramPartCount", "getSystemIndexFileNames", "testSystemIndexPath", "toLongPath", "getContentIndexBodyText", "testIndexBookDir", "testAnyEntry") `
        @("systemIndexFileName", "systemIndexPartBytes", "systemIndexPathMax", "indexBookDirPattern", "contentIndexFilePattern")
    $pool = [WorkerPool]::new($workers, $state, $Host, "BelowNormal")
    $pending = New-Object System.Collections.Generic.Queue[hashtable]
    $jobScript = {
        param ($folder, $indexRoot, $systemRoot)
        # 別スレッドは既定では .NET の例外で止まらず、書けなかった txt を作ったものとして返してしまう。例外で止めて呼び出し元に伝える
        $ErrorActionPreference = "Stop"
        @{ Result = writeSystemIndexFolder $folder $indexRoot $systemRoot }
    }.ToString()
    try {
        $next = 0
        while ($next -lt $folders.Count -or $pending.Count -gt 0) {
            # スレッド数の 2 倍まで先に始めておき、終わった順ではなく始めた順に受け取る
            while ($pending.Count -lt $workers * 2 -and $next -lt $folders.Count) {
                if ($shouldStop -and (& $shouldStop)) {
                    $next = $folders.Count
                    break
                }
                $pending.Enqueue($pool.Submit($jobScript, @($folders[$next], $indexRoot, $systemRoot)))
                $next++
            }
            if ($pending.Count -eq 0) {
                break
            }
            $output = $pool.Receive($pending.Dequeue())
            if ($output.Count -gt 0) {
                $results.Add($output[0].Result)
            }
        }
    } finally {
        foreach ($job in $pending) {
            $pool.Cancel($job)
        }
        $pool.Close()
    }
    return , $results.ToArray()
}

function readSystemIndexState {
    # 状態ファイルを読む（convertFromSystemIndexState の形）。無ければ空。
    # 書き込み中などで読めなければ $null（高速検索を使わず、すべてを照合する）
    param (
        [string]$path = $workspace.SystemIndexStateFile
    )

    if (![System.IO.File]::Exists($path)) {
        return newSystemIndexState
    }
    for ($i = 1; $i -le 10; $i++) {
        try {
            $stream = [System.IO.FileStream]::new($path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read)
            try {
                $reader = [System.IO.StreamReader]::new($stream, [System.Text.Encoding]::UTF8, $true)
                return convertFromSystemIndexState ($reader.ReadToEnd() -split "\r?\n")
            } finally {
                $stream.Dispose()
            }
        } catch [System.IO.IOException] {
            Start-Sleep -Milliseconds 100
        }
    }
    return $null
}

function updateSystemIndexState {
    # 状態ファイルを排他で開き、change（{ param($state) }）で書き換えて保存する。
    # インデクサ（取り込み）と画面（検索のたびの整理）が同時に書かないよう、開いている間はほかから開けない。
    # 開けなければ少し待って数回試し、それでも開けなければ $false を返す（書き換えは次の機会に回る）
    param (
        [scriptblock]$change,
        [string]$path = $workspace.SystemIndexStateFile
    )

    [System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($path)) | Out-Null
    $stream = $null
    for ($i = 1; $i -le 20 -and $null -eq $stream; $i++) {
        try {
            $stream = [System.IO.FileStream]::new($path, [System.IO.FileMode]::OpenOrCreate, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None)
        } catch [System.IO.IOException] {
            Start-Sleep -Milliseconds 100
        }
    }
    if ($null -eq $stream) {
        return $false
    }
    try {
        $reader = [System.IO.StreamReader]::new($stream, [System.Text.Encoding]::UTF8, $true, 4096, $true)
        $state = convertFromSystemIndexState ($reader.ReadToEnd() -split "\r?\n")
        $reader.Dispose()
        & $change $state
        $bytes = ${utf8Bom}.GetPreamble() + ${utf8Bom}.GetBytes(((convertToSystemIndexState $state) -join "`r`n") + "`r`n")
        $stream.SetLength(0)
        $stream.Write($bytes, 0, $bytes.Length)
    } finally {
        $stream.Dispose()
    }
    return $true
}

function removeSystemIndexEntries {
    # 状態から、相対パス rel のフォルダ（とその中）の行を消す。indexName を渡したら、そのインデックスの「対応済み」も消す
    param (
        $state,
        [string]$rel,
        [string]$indexName = ""
    )

    foreach ($key in @($state.Pending.Keys)) {
        if ($key.StartsWith("$rel\", [System.StringComparison]::OrdinalIgnoreCase)) {
            [void]$state.Pending.Remove($key)
        }
    }
    foreach ($key in @($state.Excluded)) {
        if ($key.Equals($rel, [System.StringComparison]::OrdinalIgnoreCase) -or $key.StartsWith("$rel\", [System.StringComparison]::OrdinalIgnoreCase)) {
            [void]$state.Excluded.Remove($key)
        }
    }
    if ($indexName) {
        [void]$state.Covered.Remove($indexName)
    }
}

function setSystemIndexResults {
    # writeSystemIndexFolder の結果を状態に書く（フォルダの前の行は消して、作った txt を反映待ちにする）
    param (
        $state,
        [object[]]$results
    )

    foreach ($result in $results) {
        # フォルダ直下の txt の行だけを消す（サブフォルダの行は、サブフォルダの結果で書き換わる）
        foreach ($key in @($state.Pending.Keys)) {
            if ([System.IO.Path]::GetDirectoryName($key) -eq $result.Rel) {
                [void]$state.Pending.Remove($key)
            }
        }
        [void]$state.Excluded.Remove($result.Rel)
        foreach ($file in $result.Files) {
            $state.Pending[$file.Rel] = $file.Ticks
        }
        if ($result.Excluded) {
            [void]$state.Excluded.Add($result.Rel)
        }
    }
}

function markSystemIndexChanged {
    # TSV を入れ替えたフォルダを「反映待ち（日時は 0）」にする（txt を作り直すまで、そのフォルダは .NET で照合させる）。
    # 0 は txt の更新日時とも Windows Search の DateModified とも一致しないため、前の txt が索引されていても反映済みにならない
    # （今の日時にすると、txt を書いたのと同じ秒の中では一致して、反映済みと取り違える）
    param (
        [string[]]$rels,
        [string]$path = $workspace.SystemIndexStateFile
    )

    return updateSystemIndexState {
        param ($state)
        foreach ($rel in $rels) {
            $state.Pending["$rel\${systemIndexFileName}"] = 0
        }
    } $path
}

function getSystemIndexStaleFolders {
    # txt の作り直しが要る index の中のフォルダ（フルパス）を返す。
    #   txt が無い・TSV より古い・状態が「反映待ち」なのに txt の更新日時と合わない（取り込みの途中で止まった）もの
    param (
        [string]$indexRoot,
        [string]$systemRoot,
        $state
    )

    $stale = New-Object System.Collections.Generic.List[string]
    $longRoot = toLongPath $indexRoot
    if (![System.IO.Directory]::Exists($longRoot)) {
        return , $stale.ToArray()
    }
    $rootLength = $indexRoot.TrimEnd("\").Length
    foreach ($longDir in [System.IO.Directory]::EnumerateDirectories($longRoot, "*", [System.IO.SearchOption]::AllDirectories)) {
        # 元のファイルごとのフォルダ（本文インデックスにする前の TSV・中身が空のファイル）は、親のフォルダの txt に入る
        if (testIndexBookDir $longDir $false) {
            continue
        }
        $folder = fromLongPath $longDir
        $rel = $folder.Substring($rootLength).Trim("\")
        if ($state.Excluded.Contains($rel)) {
            continue
        }
        $tsvPaths = getSystemIndexFolderTsvPaths $folder
        $txtDir = toLongPath "$($systemRoot.TrimEnd('\'))\$rel"
        $txts = if ([System.IO.Directory]::Exists($txtDir)) { @([System.IO.Directory]::GetFiles($txtDir, "$([System.IO.Path]::GetFileNameWithoutExtension(${systemIndexFileName}))*.txt")) } else { @() }
        if ($tsvPaths.Count -eq 0) {
            if ($txts.Count -gt 0) {
                $stale.Add($folder)   # TSV が無くなった（txt を消す）
            }
            continue
        }
        if ($txts.Count -eq 0) {
            $stale.Add($folder)
            continue
        }
        $oldest = ($txts | ForEach-Object { [System.IO.File]::GetLastWriteTimeUtc($_) } | Measure-Object -Minimum).Minimum
        $newestTsv = ($tsvPaths | ForEach-Object { [System.IO.File]::GetLastWriteTimeUtc($_) } | Measure-Object -Maximum).Maximum
        $marked = $state.Pending.ContainsKey("$rel\${systemIndexFileName}") -and
            $state.Pending["$rel\${systemIndexFileName}"] -ne [System.IO.File]::GetLastWriteTimeUtc("$txtDir\${systemIndexFileName}").Ticks
        if ($newestTsv -gt $oldest -or $marked) {
            $stale.Add($folder)
        }
    }
    return , $stale.ToArray()
}

function updateSystemIndexes {
    # インデックス作成の終わりに、システムインデックスの作り直しが要るフォルダをまとめて作り直し、状態ファイルに書く。
    # すべてのフォルダの txt がそろったインデックスは「対応済み」にする（対応済みでないインデックスは、高速検索でもすべてを照合する）。
    # 利用者の作業の邪魔にならないよう、作るスレッドの優先度を下げる（writeSystemIndexFolders）。shouldStop が $true を返せば、始めていない分は作らない。
    # 作り直したフォルダの数と、作り終えていないインデックスの数を @{ Built; Unfinished } で返す
    param (
        [string]$indexRoot = $workspace.IndexDir,
        [string]$systemRoot = $workspace.SystemIndexDir,
        [string]$statePath = $workspace.SystemIndexStateFile,
        [scriptblock]$shouldStop = $null
    )

    $state = readSystemIndexState $statePath
    if ($null -eq $state) {
        writeIndexerLog "システムインデックスの状態を読めないため、作り直しは次のインデックス作成に回します。" "Yellow"
        return @{ Built = 0; Unfinished = -1 }
    }
    # 無くなったインデックス（設定から外した・画面で削除した）の txt と状態の行を消す
    $names = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    if ([System.IO.Directory]::Exists((toLongPath $indexRoot))) {
        foreach ($dir in [System.IO.Directory]::GetDirectories((toLongPath $indexRoot))) {
            [void]$names.Add([System.IO.Path]::GetFileName($dir))
        }
    }
    $gone = New-Object System.Collections.Generic.List[string]
    if ([System.IO.Directory]::Exists((toLongPath $systemRoot))) {
        foreach ($dir in [System.IO.Directory]::GetDirectories((toLongPath $systemRoot))) {
            $gone.Add([System.IO.Path]::GetFileName($dir))
        }
    }
    $gone.AddRange([string[]]@($state.Covered))
    foreach ($name in ($gone | Sort-Object -Unique)) {
        if (!$names.Contains($name)) {
            [void](removeSystemIndexOf $name $systemRoot $statePath)
            [void]$state.Covered.Remove($name)
        }
    }

    $stale = getSystemIndexStaleFolders $indexRoot $systemRoot $state
    $results = @()
    if ($stale.Count -gt 0) {
        writeIndexerLog "システムインデックス（高速検索用）を作っています…（$($stale.Count) フォルダ）"
        $results = writeSystemIndexFolders $stale $indexRoot $systemRoot 0 $shouldStop

    }
    # 作り終えていないフォルダがあるインデックスは、対応済みにしない
    $built = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($result in $results) {
        [void]$built.Add($result.Rel)
    }
    $unfinished = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    $rootLength = $indexRoot.TrimEnd("\").Length
    foreach ($folder in $stale) {
        $rel = $folder.Substring($rootLength).Trim("\")
        if (!$built.Contains($rel)) {
            [void]$unfinished.Add((getIndexNameOfRelPath $rel))
        }
    }
    $saved = updateSystemIndexState {
        param ($current)
        setSystemIndexResults $current $results
        foreach ($name in $names) {
            if ($unfinished.Contains($name)) {
                [void]$current.Covered.Remove($name)
            } else {
                [void]$current.Covered.Add($name)
            }
        }
    } $statePath
    if (!$saved) {
        writeIndexerLog "システムインデックスの状態を書き込めなかったため、次のインデックス作成で作り直します。" "Yellow"
    } elseif ($unfinished.Count -gt 0) {
        writeIndexerLog "中止したため、システムインデックスの一部（$($stale.Count - $built.Count) フォルダ）は次のインデックス作成で作ります。" "Yellow"
    }
    return @{ Built = $built.Count; Unfinished = $unfinished.Count }
}

function removeSystemIndexOf {
    # インデックス（または index の中のフォルダ）を消したとき、system_index の同じフォルダと状態の行を消す
    param (
        [string]$rel,
        [string]$systemRoot = $workspace.SystemIndexDir,
        [string]$path = $workspace.SystemIndexStateFile
    )

    $dir = toLongPath "$($systemRoot.TrimEnd('\'))\$rel"
    if ([System.IO.Directory]::Exists($dir)) {
        removeDirectoryRetry "$($systemRoot.TrimEnd('\'))\$rel"
    }
    $name = getIndexNameOfRelPath $rel
    $indexName = if ($name -eq $rel) { $name } else { "" }
    return updateSystemIndexState { param ($state) removeSystemIndexEntries $state $rel $indexName } $path
}

# インデックス作成の状態（取り込み一覧・取り込み中のファイル）の読み書きと、画面とインデクサの受け渡しの口・ログ。

# 1ファイルの取り込みの制限時間（分）。超えたらOfficeアプリを強制終了し、そのファイルは失敗とする（クラウドからのダウンロードも含む。確認の文言も同じ値を使う）
${ingestFileTimeoutMinutes} = 10

function describeIngestError {
    # 取り込みで発生した例外から、取り込み一覧のエラー列・画面に表示する失敗の理由を返す。
    # Officeアプリのメッセージは分かりにくい（パスワード付きでも「入力したパスワードが間違っています」等）ため、
    # よくある原因は「原因（詳細: 元のメッセージ）」の形に言い換える
    param (
        [System.Exception]$exception
    )

    # メソッド呼び出しの例外（「"7" 個の引数を指定して "Open" を呼び出し中に例外が発生しました」等）は、中の例外が本来の理由
    $base = $exception.GetBaseException()
    $message = ($base.Message -replace "\s+", " ").Trim()
    $code = "{0:X8}" -f $base.HResult
    if ($message -eq "") {
        $message = "エラーコード 0x${code}"
    }

    # スクリプト自身が throw したメッセージは、利用者向けに書いてあるためそのまま使う
    if ($base.GetType() -eq [System.Management.Automation.RuntimeException]) {
        return $message
    }

    if ($message -match "パスワード|password") {
        # 元のメッセージ（パスワードが間違っています等）は、パスワードを入力していない利用者には誤解を招くため付けない
        return "読み取りパスワードが設定されているため開けません（パスワード付きのファイルは更新できません）"
    }

    $cause = $null
    if ($base -is [System.IO.FileNotFoundException] -or $base -is [System.IO.DirectoryNotFoundException]) {
        $cause = "ファイルが見つかりません（更新中に移動・削除・名前変更された可能性があります）"
    } elseif ($base -is [System.UnauthorizedAccessException] -or $code -eq "80070005") {
        $cause = "ファイルを読むアクセス権がありません"
    } elseif ($base -is [System.IO.PathTooLongException]) {
        $cause = "パスが長すぎるため読めません"
    } elseif ($base -is [System.OutOfMemoryException]) {
        # 巨大なシート（テキストにして約 1GB 超）は、整形（prettyTsv）で一度に読み込めずメモリ不足になる
        $cause = "シート・文書が大きすぎて更新できません（メモリが不足しました）"
    } elseif (@("80070020", "80070021") -contains $code) {
        # 共有違反・ロック違反
        $cause = "ほかのアプリ・利用者がファイルを使用中のため読めません（ファイルを閉じてから再度更新してください）"
    } elseif (@("80040154", "80080005", "800401F3") -contains $code) {
        # クラス未登録・サーバーの起動失敗・ProgID 不正
        $cause = "Officeアプリ（Excel・Word・PowerPoint）を起動できませんでした（インストール・ライセンス認証の状態を確認してください）"
    } elseif (@("800706BA", "800706BE", "80010105", "80010108") -contains $code) {
        # RPC サーバーを利用できない・呼び出し失敗・サーバーで例外・切断
        $cause = "Officeアプリが異常終了したか、内部でエラーが発生しました（ファイルが壊れている、または大きすぎる可能性があります）"
    } elseif (@("80010001", "8001010A") -contains $code) {
        # 呼び出しの拒否・処理中のため後で再試行
        $cause = "Officeアプリが応答しませんでした（Officeアプリでダイアログを表示中などの可能性があります）"
    } elseif ($base -is [System.IO.InvalidDataException] -or $base -is [System.Xml.XmlException] -or
              $message -match "ファイル形式|破損|壊れ|corrupt|file format") {
        $cause = "ファイルが壊れているか、拡張子と中身の形式が一致していません"
    }

    if ($cause) {
        return "${cause}（詳細: ${message}）"
    }
    return $message
}

function addStatusRow {
    # 取り込み一覧の末尾に1行追記する（readStatusFile では後の行が優先される）
    param (
        $row,
        [string]$path = $workspace.StatusFile
    )

    [System.IO.File]::AppendAllText($path, "$(toStatusLine $row)`r`n", ${utf8Bom})
}

function readIngestingFiles {
    # 取り込み中のファイルの記録を読み、@{ RelPath = 相対パス; Count = 続けて取り込みを始めて終わらなかった回数 } の配列を返す。
    # 取り込みを複数のスレッドで行うため、1 行に 1 ファイル。記録が無ければ空。壊れた行は読み飛ばす
    param (
        [string]$path = $workspace.IngestingFile
    )

    $result = New-Object System.Collections.Generic.List[hashtable]
    foreach ($line in @(readListFile $path)) {
        $fields = $line.Split("`t")
        $count = 0
        if ($fields.Count -ne 2 -or -not [int]::TryParse($fields[0], [ref]$count) -or $count -lt 1 -or $fields[1] -eq "") {
            continue
        }
        $result.Add(@{ RelPath = $fields[1]; Count = $count })
    }
    return , $result.ToArray()
}

function writeIngestingFiles {
    # 取り込み中のファイル（@{ RelPath; Count } の並び）を "回数<TAB>相対パス" で記録する。無ければ記録を消す
    param (
        [object[]]$entries,
        [string]$path = $workspace.IngestingFile
    )

    $lines = @($entries | Where-Object { $_ } | ForEach-Object { "$($_.Count)`t$($_.RelPath)" })
    if ($lines.Count -eq 0) {
        removeIngestingFile $path
        return
    }
    writeListFile $path $lines
}

function removeIngestingFile {
    param (
        [string]$path = $workspace.IngestingFile
    )

    if (Test-Path -LiteralPath $path) {
        Remove-Item -LiteralPath $path -Force
    }
}

# ----------------------------------------------------------------------------
# 画面（または indexer.ps1）とインデクサの受け渡しの口（docs/design/structure/threads.md「画面とインデクサの受け渡し」）
# ----------------------------------------------------------------------------

function newIndexerChannel {
    # 受け渡しの口を作る。画面とインデクサのスレッドの両方から読み書きするため Synchronized にする。
    #   画面が書く      : RetryFailed・IncludeCloud（クラウドにだけあるファイルもダウンロードして取り込むか）・ConfirmTargets・Workers（取り込みのスレッドの数。0 は司令のスレッドで取り込む、-1 は設定・コア数から決める）・Stop・Answer・
    #                     OnlyNames（更新するインデックス名の配列。空なら、チェックの付いたものすべて）
    #   インデクサが書く: Progress（readIndexingProgress の形）・Plan（取り込み予定）・Error・ExitCode（0 完了 / 1 エラー / 2 中止）・
    #                     CloudSkipped（クラウドにだけあるため、ダウンロードせずに残した件数）・
    #                     OnlySkipped（OnlyNames のうち、更新できなかった名前の @{ Name; Reason } の配列）
    #   OfficePids: インデックス作成が起動した Office の PID → @{ ProcessName; StartTicks }（閉じるときに止まらなければ、名前と起動時刻が合う PID だけを止める）
    #   UserOfficePids: 取り込み中に見える窓があった（利用者が使った）PowerPoint の PID → @{ ProcessName; StartTicks }（制限時間を過ぎても、閉じるときも止めない）
    param (
        [bool]$retryFailed = $false,
        [bool]$confirmTargets = $false,
        [int]$workers = -1,
        [string[]]$onlyNames = @(),
        [bool]$includeCloud = $false
    )

    return [hashtable]::Synchronized(@{
        RetryFailed = $retryFailed; IncludeCloud = $includeCloud; ConfirmTargets = $confirmTargets; Workers = $workers
        OnlyNames = @($onlyNames | Where-Object { $_ }); OnlySkipped = @()
        Progress = $null; Stop = $false
        Plan = $null; Answer = $null; Answered = New-Object System.Threading.ManualResetEvent($false)
        Error = ""; ExitCode = $null; CloudSkipped = 0
        OfficePids = New-Object 'System.Collections.Concurrent.ConcurrentDictionary[int,object]'
        UserOfficePids = New-Object 'System.Collections.Concurrent.ConcurrentDictionary[int,object]'
    })
}

# いま動いているインデックス作成の受け渡しの口（invokeIndexer が入れる。$null なら進み具合を伝えない）
$script:indexerChannel = $null

function writeIndexingProgress {
    # インデックス作成の進み具合を受け渡しの口に入れる（画面が 1 秒ごとに読む）
    param (
        [string]$phase,
        [int]$processed = 0,
        [int]$remaining = 0,
        [int]$failed = 0,
        [string]$detail = "",
        $channel = $script:indexerChannel
    )

    if ($null -ne $channel) {
        $channel.Progress = @{ Phase = $phase; Processed = $processed; Remaining = $remaining; Failed = $failed; Detail = ($detail -replace "[\t\r\n]+", " ") }
    }
}

function readIndexingProgress {
    # インデックス作成の進み具合（@{ Phase; Processed; Remaining; Failed; Detail }）を返す。まだ無ければ $null
    param (
        $channel
    )

    if ($null -eq $channel) {
        return $null
    }
    return $channel.Progress
}

function requestIndexingStop {
    # 中止を求める。取り込みはファイルの切れ目で止まる。確認を待っていれば、取りやめの返事にする
    param (
        $channel
    )

    $channel.Stop = $true
    [void]$channel.Answered.Set()
}

function answerIndexingPlan {
    # 確認の返事を返す。取り込む → @{ RetryFailed; IncludeCloud } ／ 取りやめ → $null
    param (
        $channel,
        $answer
    )

    $channel.Answer = $answer
    if ($null -eq $answer) {
        $channel.Stop = $true
    }
    [void]$channel.Answered.Set()
}

function testIndexerRunning {
    # この work でインデックス作成が動いているか（画面のスレッド・画面を使わない indexer.ps1 のどちらでも）。
    # インデックス作成が持つ鍵（newAppMutex "indexer"）を取れるかで調べ、取れたらすぐ放す
    param (
        [string]$dir = $workspace.Dir
    )

    $mutex = newAppMutex "indexer" $dir
    try {
        return !$mutex.Acquired
    } finally {
        if ($mutex.Acquired) {
            $mutex.Mutex.ReleaseMutex()
        }
        $mutex.Mutex.Dispose()
    }
}

function writeZipSizeLimitLog {
    # .docx・.pptx・.xlsx の部品がサイズの上限を超えたときの詳細をログに書く（画面には出さない）。
    # 原因を調べられるよう、部品名・大きさ・部品ごとか合計かはここだけに書く。
    # 呼び出し元（extract_office.ps1・indexer_run.ps1・office_reader.ps1 のグラフ・SmartArt 読み取り）は、
    # 捕まえた例外をそのまま渡せばよい。ZipSizeLimitException かどうかはここで確かめ、違えば何もしない
    # （param の型を [ZipSizeLimitException] にしないのは、indexer_state.ps1 が office_reader.ps1 より先に
    # 読み込まれ、その時点ではクラスがまだ無いため）
    param (
        [System.Exception]$exception
    )

    if ($exception -isnot [ZipSizeLimitException]) {
        return
    }

    $kindText = switch ($exception.LimitKind) { "Total" { "1ファイルの合計" } "Output" { "埋め込みから出す文字の合計" } default { "部品ごと" } }
    $mb = [math]::Round($exception.MeasuredBytes / 1MB, 1)
    writeIndexerLog "    サイズの上限（${kindText}）を超えました: $($exception.PartName)（$($exception.MeasuredBytes) バイト、約${mb}MB）" "Yellow"
}

function newIngestPlanRow {
    # 取り込み予定（インデックス1件分）の行を作る
    param (
        [string]$name,
        [string]$path,
        [string]$kind = ${planKindIngest},
        [int]$total = 0,    # 見つかった Office ファイルの数
        [int]$targets = 0,  # 今回取り込むファイルの数（新規＋更新あり＋前回未完了＋インデックスなし）
        [int]$new = 0,
        [int]$updated = 0,
        [int]$pending = 0,
        [int]$lost = 0,     # インデックス（TSV）が無くなった・壊れているため取り込み直す
        [int]$failed = 0,   # 前回失敗し、その後更新されていない（再取り込みするかは画面で選ぶ）
        [int]$cloud = 0,        # クラウドにだけあるため、取り込み対象に数えていないファイル（新規・更新あり・前回未完了など）
        [int]$cloudFailed = 0,  # クラウドにだけあり、前回失敗したファイル
        [long]$cloudBytes = 0,  # クラウドにだけあり、取り込み対象のファイルの合計サイズ（バイト）
        [long]$cloudFailedBytes = 0  # クラウドにだけあり、前回失敗したファイルの合計サイズ（バイト）
    )

    return [pscustomobject]@{
        インデックス名 = $name
        元のフォルダ   = $path
        区分           = $kind
        ファイル数     = $total
        取り込み対象       = $targets
        新規           = $new
        更新あり       = $updated
        前回未完了     = $pending
        インデックスなし   = $lost
        前回失敗       = $failed
        クラウド       = $cloud
        クラウド失敗   = $cloudFailed
        クラウド容量   = $cloudBytes
        クラウド失敗容量 = $cloudFailedBytes
    }
}

function readStatusLines {
    # 取り込み一覧を1行ずつ読む（インデックス作成中でも読めるよう共有を許して開く）。ファイルが無ければ空
    param (
        [string]$path = $workspace.StatusFile
    )

    if (!(Test-Path -LiteralPath $path)) {
        return @()
    }
    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $stream = New-Object System.IO.FileStream($path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    $reader = New-Object System.IO.StreamReader($stream, ${utf8Bom})
    try {
        $text = $reader.ReadToEnd()
    } finally {
        $reader.Dispose()
    }
    return @($text -split "\r?\n" | Where-Object { $_ -ne "" })
}

function renameStatusIndexName {
    # 取り込み一覧に記録したインデックス名を書き換える（クロール対象フォルダの行と、各行の相対パスの先頭）。
    # 行の順序と内容をそのまま保つため、行ごとに書き換えて置き換える
    param (
        [string]$oldName,
        [string]$newName,
        [string]$path = $workspace.StatusFile
    )

    $lines = @(readStatusLines $path)
    if ($lines.Count -eq 0) {
        return
    }

    $result = New-Object System.Collections.Generic.List[string]
    foreach ($line in $lines) {
        $fields = $line.Split("`t")
        if ($fields[0] -eq ${statusFolderKey} -and $fields.Count -eq 3 -and [string]::Equals($fields[2], $oldName, [System.StringComparison]::OrdinalIgnoreCase)) {
            $fields[2] = $newName
            $result.Add($fields -join "`t")
            continue
        }
        if ($fields.Count -eq ${statusColumns}.Count -and $fields[0] -ne "") {
            $split = splitIndexRelPath $fields[0]
            if ($split.Rest -ne "" -and [string]::Equals($split.Name, $oldName, [System.StringComparison]::OrdinalIgnoreCase)) {
                $fields[0] = "${newName}\$($split.Rest)"
                $result.Add($fields -join "`t")
                continue
            }
        }
        $result.Add($line)
    }
    writeTextLinesAtomic $path $result
}

function removeStatusIndexName {
    # 取り込み一覧から、あるインデックスの記録（クロール対象フォルダの行と、そのインデックスの各行）を取り除く
    param (
        [string]$name,
        [string]$path = $workspace.StatusFile
    )

    $lines = @(readStatusLines $path)
    if ($lines.Count -eq 0) {
        return
    }

    $result = New-Object System.Collections.Generic.List[string]
    foreach ($line in $lines) {
        $fields = $line.Split("`t")
        if ($fields[0] -eq ${statusFolderKey} -and $fields.Count -eq 3 -and [string]::Equals($fields[2], $name, [System.StringComparison]::OrdinalIgnoreCase)) {
            continue
        }
        if ($fields.Count -eq ${statusColumns}.Count -and $fields[0] -ne "") {
            $split = splitIndexRelPath $fields[0]
            if ($split.Rest -ne "" -and [string]::Equals($split.Name, $name, [System.StringComparison]::OrdinalIgnoreCase)) {
                continue
            }
        }
        $result.Add($line)
    }
    writeTextLinesAtomic $path $result
}

function getIndexingState {
    # 取り込み一覧からインデックス作成の状態を返す:
    #   @{ Exists; Folders（クロール対象フォルダ @{ Path; Name } の配列）; Total; Pending（未取り込み）; Failed; Done; IngestedSince（since 以降に取り込んだ件数）; Updated（取り込み一覧の更新日時）;
    #      FailedRows（失敗したファイルの行。取り込み日時の新しい順）; IndexStats（インデックス名ごとの集計。getIndexStats） }
    param (
        [datetime]$since = [datetime]::MaxValue,
        [string]$path = $workspace.StatusFile
    )

    $state = @{ Exists = $false; Folders = @(); Total = 0; Pending = 0; Failed = 0; Done = 0; IngestedSince = 0; Updated = $null; FailedRows = @(); IndexStats = (getIndexStats $null) }
    if (!(Test-Path -LiteralPath $path)) {
        return $state
    }

    $state.Exists = $true
    $state.Updated = (Get-Item -LiteralPath $path).LastWriteTime
    $status = readStatusFile $path
    $state.Folders = $status.Folders.ToArray()
    $state.Total = $status.Rows.Count
    $state.IndexStats = getIndexStats $status.Rows
    # since を指定しないとき（画面の集計）は、行ごとの日時の解析（数万行では数秒かかる）を省く
    $countSince = ($since -ne [datetime]::MaxValue)
    $sinceSecond = if ($countSince) { $since.AddTicks(-($since.Ticks % [timespan]::TicksPerSecond)) } else { $since }
    $failedRows = New-Object System.Collections.Generic.List[object]
    foreach ($row in $status.Rows.Values) {
        if (testStatusRowFailed $row) {
            $state.Failed++
            $failedRows.Add($row)
        } elseif ($row.状態 -eq ${stateNew}) {
            $state.Pending++
        } elseif ($row.状態 -eq ${stateDone}) {
            $state.Done++
        }

        $ingested = [datetime]::MinValue
        if ($countSince -and $row.取り込み日時 -and [datetime]::TryParseExact($row.取り込み日時, "yyyy/MM/dd HH:mm:ss", [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::None, [ref]$ingested) -and $ingested -ge $sinceSecond) {
            $state.IngestedSince++
        }
    }
    # 取り込み日時は "yyyy/MM/dd HH:mm:ss" のため、文字列の順で新しい順に並ぶ
    $state.FailedRows = @($failedRows | Sort-Object -Property @{ Expression = { [string]$_.取り込み日時 }; Descending = $true }, @{ Expression = { $_.相対パス } })
    return $state
}

# 取り込み一覧・取り込み中のファイルの読み書きと、今回の取り込みでの失敗・元ファイルが無くなった行の記録をまとめる（StatusLedger）。
# 列と状態の定義（core/paths.ps1 の ${statusColumns} など）は判断層（indexer_decide.ps1）・index_store.ps1 なども読むため、
# 今の場所（paths.ps1 の変数）のまま動かさない（docs/design/structure/classes.md）。
# 保存先（取り込み一覧・取り込み中のファイル）は、コンストラクタで受け取った $workspace（Workspace のインスタンス。
# 場所を暗黙に使わないため、メソッドの中で ${workspace} を読まない）の StatusFile・IngestingFile から決める
class StatusLedger {
    hidden $Workspace
    # 今回の取り込みで失敗したファイル（@{ RelPath; Message } の並び）
    [System.Collections.Generic.List[object]]$Failures
    # 取り込みの直前に元のファイルが無くなっていた相対パス（取り込み一覧から除く）
    [System.Collections.Generic.HashSet[string]]$DroppedRows

    StatusLedger($workspace) {
        $this.Workspace = $workspace
        $this.Failures = New-Object System.Collections.Generic.List[object]
        $this.DroppedRows = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    }

    [hashtable] ReadStatus() {
        # 取り込み一覧を読み込む（readStatusFile と同じ形。@{ Folders; Rows }）
        return readStatusFile $this.Workspace.StatusFile
    }

    [void] WriteStatus($folders, $rows) {
        # 取り込み一覧を書き出す（1ファイル1行）
        writeStatusFile $folders $rows $this.Workspace.StatusFile
    }

    [void] AddRow($row) {
        # 取り込み一覧の末尾に1行追記する
        addStatusRow $row $this.Workspace.StatusFile
    }

    [object[]] ReadIngestingFiles() {
        # 取り込み中のファイルの記録を読む（@{ RelPath; Count } の並び）
        return readIngestingFiles $this.Workspace.IngestingFile
    }

    [void] WriteIngestingFiles([object[]]$entries) {
        # 取り込み中のファイルの記録を書く（無ければ記録を消す）
        writeIngestingFiles $entries $this.Workspace.IngestingFile
    }

    [void] RemoveIngestingFile() {
        removeIngestingFile $this.Workspace.IngestingFile
    }

    [void] RenameIndexName([string]$oldName, [string]$newName) {
        # 取り込み一覧に記録したインデックス名を書き換える（クロール対象フォルダの行と、各行の相対パスの先頭）
        renameStatusIndexName $oldName $newName $this.Workspace.StatusFile
    }

    [void] RemoveIndexName([string]$name) {
        # 取り込み一覧から、あるインデックスの記録（クロール対象フォルダの行と、そのインデックスの各行）を取り除く
        removeStatusIndexName $name $this.Workspace.StatusFile
    }

    [void] AddFailure([string]$relPath, [string]$message) {
        # 今回の取り込みで失敗したファイルを記録する
        $this.Failures.Add(@{ RelPath = $relPath; Message = $message })
    }

    [void] AddDropped([string]$relPath) {
        # 取り込みの直前に元のファイルが無くなっていた（取り込み一覧・インデックスから除く）ファイルを記録する
        [void]$this.DroppedRows.Add($relPath)
    }
}

# インデックスの改名・削除・名前の割り当て・一覧と元のフォルダの記録の保存。
# インデックス 1 つの情報は複数の保存先に分かれて置かれている: 設定の targetFolders、取り込み一覧、インデックスのフォルダ（content_index\<名前>）と
# 元のフォルダの記録（source_folder.txt）、設定の searchExcludes、システムインデックス（system_index）。
# このクラスは、改名・削除でそれらを書き換える手順と順番、途中で失敗したときの扱い（止める・残す）だけを持つ。一覧（targetFolders）と元のフォルダの記録の書き直しは、画面が SaveTargets・WriteSourceFile（改名では RenameIndexWithSource）で呼ぶ。保存先の形式は知らず、
# 保存先ごとの読み書きは既存の関数（searchExcludes は core\search_excludes.ps1）と、作る側から渡された StatusLedger に任せる。
# 画面は呼んで結果を出すだけにする（画面の手順をここに引き寄せる）。
#
# クラスの本体では $script: 変数・ほかのクラスの型・呼び出し元の変数を使わない（docs/design/structure/classes.md）。
# 場所は、コンストラクタで受け取る workspace（Workspace のインスタンス）と設定ファイルの場所で決める。
# 取り込み一覧は ledger（StatusLedger のインスタンス。作る側が作って渡す）を通して書く。
# 別のスレッドへはインスタンスを渡さず、ワークスペースの場所（文字列）を渡して newIndexCatalog で作り直す。
# メソッドの中のローカル変数は、プロパティと大文字・小文字だけの違いにしない
class IndexCatalog {
    hidden $Workspace
    hidden [string]$SettingsPath
    hidden $Ledger

    IndexCatalog($workspace, [string]$settingsPath, $ledger) {
        $this.Workspace = $workspace
        $this.SettingsPath = $settingsPath
        $this.Ledger = $ledger
    }

    [void] AssertReachable() {
        # インデックスの削除・名前の変更の裏の仕事の先頭で呼ぶ。ワークスペースに届かないときは例外にする
        # （届かないのに「何もせず成功」にして、設定だけ変えてしまわないため）
        assertWorkspaceReachable $this.Workspace.IndexDir
    }

    [void] RenameIndex([string]$oldName, [string]$newName) {
        # インデックス名を変える（画面の詳細の名前の欄）。インデックスのフォルダ（content_index\<名前>）を改名し、
        # 取り込み一覧の記録も書き換えるため、名前を変えてもインデックスは作り直さない。
        # インデックス作成中は呼ばない（画面はインデックス作成中この操作を無効にする）。
        # フォルダの改名か取り込み一覧の書き換えに失敗したら例外にする（システムインデックスと searchExcludes の整理は、失敗しても止めない）
        $dir = $this.Workspace.IndexDir
        # 大文字・小文字だけの変更も改名するため、同じ名前かは大文字・小文字を区別して比べる（-ceq）
        if ($oldName -eq "" -or $newName -eq "" -or $oldName -ceq $newName) {
            return
        }

        $from = Join-Path $dir $oldName
        $to   = Join-Path $dir $newName
        if (Test-Path -LiteralPath $from -PathType Container) {
            if ([string]::Equals($oldName, $newName, [System.StringComparison]::OrdinalIgnoreCase)) {
                # 大文字・小文字だけを変える場合は、そのままでは改名できないため一時名を経由する
                $tmp = Join-Path $dir "${oldName}_rename_$([System.Diagnostics.Process]::GetCurrentProcess().Id)"
                [System.IO.Directory]::Move((toLongPath $from), (toLongPath $tmp))
                [System.IO.Directory]::Move((toLongPath $tmp), (toLongPath $to))
            } else {
                if (Test-Path -LiteralPath $to) {
                    throw "「${newName}」のフォルダが既にあるため、名前を変えられません: ${to}"
                }
                [System.IO.Directory]::Move((toLongPath $from), (toLongPath $to))
            }
        }
        $this.Ledger.RenameIndexName($oldName, $newName)
        # 高速検索の システムインデックス（同じワークスペースの system_index）は古い名前の分を消す。次のインデックス作成で作り直す
        removeSystemIndexOfWorkspace $oldName $dir
        # 外したフォルダの記録（searchExcludes）は旧名・新名の下のものを消す（付け替えず、検索対象に戻す）
        removeSearchExcludesUnder $from $this.SettingsPath
        removeSearchExcludesUnder $to $this.SettingsPath
    }

    [hashtable] RenameIndexWithSource([string]$oldName, [string]$newName, $folders) {
        # 名前を変え（RenameIndex）、続けて元のフォルダの記録（source_folder.txt）を書き直す。
        # 書き直しに失敗しても、改名は済んでいるので改名の失敗にはしない。書けなかった理由を SourceFolderError で返す（成功なら空）。
        # 改名の失敗は、RenameIndex の例外のまま呼び出し元へ出る
        $this.RenameIndex($oldName, $newName)
        $sourceError = ""
        try {
            $this.WriteSourceFile($folders)
        } catch {
            $sourceError = $_.Exception.Message
        }
        return @{ SourceFolderError = $sourceError }
    }

    [void] RemoveIndex([string]$name) {
        # インデックスを削除する（画面の［削除］）。インデックスのフォルダ（content_index\<名前>）と、取り込み一覧の記録を削除する。
        # インデックス作成中は呼ばない（画面はインデックス作成中この操作を無効にする）。
        # フォルダを消せなければ例外にして、取り込み一覧の記録は残す
        $dir = $this.Workspace.IndexDir
        if ($name -eq "") {
            return
        }
        $target = Join-Path $dir $name
        if (Test-Path -LiteralPath $target -PathType Container) {
            # 中に長いパス（260文字超）のTSVがあっても削除でき、中のリンク（ジャンクション・シンボリックリンク）の先は消さない
            # （removeDirectoryRetry）。消せなければ例外にして、取り込み一覧の記録を残す（フォルダが残ったまま記録だけ消えないように）
            removeDirectoryRetry $target
        }
        $this.Ledger.RemoveIndexName($name)
        removeSystemIndexOfWorkspace $name $dir
        # 外したフォルダの記録（searchExcludes）も消す
        removeSearchExcludesUnder $target $this.SettingsPath
    }

    [object[]] RemoveIndexes([string[]]$names) {
        # 選んだインデックスをまとめて削除する（画面の［削除］）。1 つずつ RemoveIndex を呼び、途中で 1 つ失敗しても残りを続ける。
        # 戻り値は名前ごとの結果の配列（@{ Name; Ok; Reason }）。Reason は失敗したときの理由（成功なら ""）。
        # 画面のスレッドでは呼ばず、別スレッドの仕事の中で呼ぶ
        $results = New-Object System.Collections.Generic.List[object]
        foreach ($name in @($names)) {
            if ([string]::IsNullOrEmpty($name)) {
                $results.Add([pscustomobject]@{ Name = [string]$name; Ok = $false; Reason = "インデックス名が空です" })
                continue
            }
            try {
                $this.RemoveIndex($name)
                $results.Add([pscustomobject]@{ Name = $name; Ok = $true; Reason = "" })
            } catch {
                $results.Add([pscustomobject]@{ Name = $name; Ok = $false; Reason = $_.Exception.Message })
            }
        }
        return $results.ToArray()
    }

    [object[]] AssignAndSaveNames($folders) {
        # 名前の決まっていないインデックス（設定ファイルを直接書き換えた場合など）に名前を割り当てて、設定に保存する。保存した一覧を返す。
        # 取り込み一覧の読み込みは排他の外で済ませ、設定の読み直しと書き込みだけを saveAssignedIndexNames が排他の中で行う
        $status = $this.Ledger.ReadStatus()
        $assigned = @(assignIndexNames $folders $status.Folders)
        return @(saveAssignedIndexNames $assigned $this.SettingsPath)
    }

    [object[]] StoreAssignedNames($assigned) {
        # 割り当てた名前（assignIndexNames の結果）を設定に保存し、保存した一覧（@{ Name; Path; Enabled }）を返す。
        # インデクサが、司令のスレッドで作ったこのクラスの経由で名前を保存する
        return @(saveAssignedIndexNames $assigned $this.SettingsPath)
    }

    [void] SaveTargets($folders) {
        # インデックスの一覧（@{ Name; Path; Enabled } の配列）を設定に書く
        writeTargetFolders $folders $this.SettingsPath
    }

    [void] WriteSourceFile($folders) {
        # インデックスのフォルダの source_folder.txt を、一覧（@{ Name; Path } の配列）に合わせて書き直す（インデックスが無いフォルダには書かない）
        writeSourceFolderFile $folders $this.Workspace.IndexDir
    }
}

function newIndexCatalog {
    # ワークスペースの場所（Dir。文字列）から IndexCatalog を作る。取り込み一覧を書く StatusLedger もここで作って渡す。
    # 画面のスレッドでも、別のスレッドの仕事の中でも使う（スレッドをまたいでインスタンスを渡さず、場所を渡して作り直すため）
    param (
        [string]$workspaceDir,
        [string]$settingsPath = ${settingsFile}
    )

    $target = [Workspace]::new($workspaceDir)
    return [IndexCatalog]::new($target, $settingsPath, [StatusLedger]::new($target))
}

# 1 ファイルを取り込み直すかどうかの判断（差分取り込みの要）。
# ファイルにも画面にも触らないため、そのままテストできる（tests\tebunko\indexer\indexer_decide.Tests.ps1）。

# 読み取る内容（抽出版）。読み取る場所を増やしたら、その形式の版を上げる。
# 前の版で取り込んだファイルは、更新が無くても取り込み直す（取り込み一覧の「抽出版」。空は 1）
#   2: Excel（.xlsx / .xlsm）の図形・コメントを読む。
#      Word・PowerPoint のコメント・SmartArt・グラフを読み、Word のテキストボックスを本文から図形に分ける
#      （Word・PowerPoint は旧形式も新形式に変換してから読むため、.doc / .ppt も上げる）
#   3: Excel のグラフ・SmartArt（表示のグラフシートを含む）を読む。
#      グラフの読み方を、タイトル・軸ラベル・系列名だけにし、項目名は読まないようにする
#      （.xlsx / .xlsm はグラフ・SmartArt を読むようになった分で 3。.docx / .docm / .pptx / .pptm は
#      項目名を読まなくなった分だけ上げる。.doc / .ppt はこのアイテムでは上げない）
#   4: Excel（.xlsx / .xlsm）のヘッダー・フッター（表示のワークシート・グラフシート）を読む。
#   4（.docx / .docm / .doc / .pptx / .pptm）: Word・PowerPoint に埋め込んだ Office のファイル（Word 文書・Excel ブック・
#      PowerPoint）の中の文字を、"ページNNN[埋め込みN]"・"スライドNNN[埋め込みN]" として読む
#      （.doc は Word が新形式に変換した後も埋め込みが残るため上げる。.ppt は変換後に埋め込みが残らないため上げない）。
${extractVersions} = @{
    ".xlsx" = 4; ".xlsm" = 4
    ".docx" = 4; ".docm" = 4; ".doc" = 4
    ".pptx" = 4; ".pptm" = 4; ".ppt" = 2
}

function getExtractVersion {
    # ファイルの形式（拡張子）の今の抽出版を返す
    param (
        [string]$path
    )

    $version = ${extractVersions}[[System.IO.Path]::GetExtension($path).ToLowerInvariant()]
    return $(if ($null -eq $version) { 1 } else { $version })
}

function testExtractOutdated {
    # 取り込み一覧の行が、今の抽出版より前の版で取り込んだものか
    param (
        $row
    )

    $version = 1
    if ($row.抽出版) {
        [void][int]::TryParse([string]$row.抽出版, [ref]$version)
    }
    return ($version -lt (getExtractVersion $row.相対パス))
}

function getIngestDecision {
    # 前回の取り込み一覧の行と、いまのファイルの更新日時・サイズから、取り込むかどうかと、その理由を返す。
    #   Ingest: 取り込むか / Reason: done（取り込み済み）・failed（前回失敗。再取り込みするかは呼び出し元が決める）・
    #            new（一覧に無い）・updated（更新された）・pending（前回未完了）・lost（インデックスが無い・壊れている）・
    #            outdated（前の抽出版で取り込んだ）
    param (
        $old,                 # 前回の取り込み一覧の行（無ければ $null）
        [string]$updated,     # いまのファイルの更新日時（formatFileTime）
        [string]$size,        # いまのファイルのサイズ（文字列）
        [bool]$indexComplete  # インデックス（TSV）がそろっているか（状態が「済」のときだけ意味がある）
    )

    # 前回と更新日時・サイズが同じで、前回「未取り込み」で終わっていなければ、同じファイルとみなす
    $sameFile = ($old -and $old.更新日時 -eq $updated -and $old.サイズ -eq $size -and $old.状態 -ne ${stateNew})
    # 取り込み済みでも、インデックス（TSV）が無くなっていれば取り込み直す。
    # 一覧だけを見ると「済」のままになり、検索しても出てこない状態が続くため
    $lostIndex = ($sameFile -and $old.状態 -eq ${stateDone} -and -not $indexComplete)

    if ($sameFile -and -not $lostIndex) {
        if ($old.状態 -eq ${stateFailed}) {
            return @{ Ingest = $false; Reason = "failed" }
        }
        if (testExtractOutdated $old) {
            return @{ Ingest = $true; Reason = "outdated" }
        }
        return @{ Ingest = $false; Reason = "done" }
    }
    if ($lostIndex) {
        return @{ Ingest = $true; Reason = "lost" }
    }
    if ($null -eq $old) {
        return @{ Ingest = $true; Reason = "new" }
    }
    if ($old.状態 -eq ${stateNew}) {
        return @{ Ingest = $true; Reason = "pending" }
    }
    return @{ Ingest = $true; Reason = "updated" }
}

# 利用者が使っている PowerPoint のために取り込めなかったファイルの理由（取り込み一覧の「エラー」列と、更新に失敗したファイルの一覧に出す。
# 状態は「未取り込み」のまま残すので、閉じてからの次の更新で、再取り込みを選ばなくても取り込む）
${postponedReasonRunning} = "PowerPoint が起動していたため取り込めませんでした。PowerPoint を閉じてから、もう一度更新してください。"
${postponedReasonInUse}   = "PowerPoint を使っている方がいたため取り込めませんでした。PowerPoint を保存して閉じてから、もう一度更新してください。"

# 取り込みのレーン（docs/design/indexing/parallel.md）。Office のレーンはアプリごとに 1 つのスレッドで、そのアプリを 1 つ持つ。
# 読み取りのレーンは Office を使わず、ZIP の中の XML を直接読む（複数のスレッド）
${laneExcel}      = "Excel"
${laneWord}       = "Word"
${lanePowerPoint} = "PowerPoint"
${laneReader}     = "Reader"

function getIngestLane {
    # 取り込むファイルのレーンを拡張子で決める。Excel はセルの表示値を読むため、すべて Excel のレーン。
    # Word・PowerPoint は、旧形式（.doc / .ppt）だけ Office のレーン、新形式は読み取りのレーン
    # （中身が旧形式・パスワード付きと分かったら、読み取りのスレッドが Office のレーンに回し直す。getOfficeLane）。
    # テキストの拡張子（.txt 等）と PDF（.pdf）は、どの分岐にも当たらないため既定の読み取りのレーンになる（Office を使わずに読むため）
    param (
        [string]$relPath
    )

    switch -Regex ([System.IO.Path]::GetExtension($relPath).ToLowerInvariant()) {
        "^\.xls"   { return ${laneExcel} }
        "^\.doc$"  { return ${laneWord} }
        "^\.ppt$"  { return ${lanePowerPoint} }
    }
    return ${laneReader}
}

function getOfficeLane {
    # 読み取りのスレッドが Office が要ると返したファイルの、回し先の Office のレーン
    param (
        [string]$relPath
    )

    if ([System.IO.Path]::GetExtension($relPath).ToLowerInvariant().StartsWith(".ppt")) {
        return ${lanePowerPoint}
    }
    return ${laneWord}
}
function splitCloudItems {
    # クラウドにだけあるファイルの一覧を、取り込むものと、ダウンロードせずに残すものに分ける。
    #   取り込む: 「ダウンロードして取り込む」が選ばれていて、取り込み対象のもの（Failed が $false）。
    #            前回失敗したもの（Failed が $true）は、「前回失敗したものも取り込み直す」も選ばれているときだけ
    #   items の各要素は createTargetList が返す Cloud の要素（Failed: 前回失敗したファイルか）
    param (
        $items,
        [bool]$retryFailed,
        [bool]$includeCloud
    )

    $included = New-Object System.Collections.Generic.List[object]
    $skipped = New-Object System.Collections.Generic.List[object]
    # List[object] を @() に渡すと PowerShell 5.1 で落ちることがあるため、そのまま回す
    foreach ($item in $items) {
        if ($includeCloud -and ((-not $item.Failed) -or $retryFailed)) {
            $included.Add($item)
        }
        else {
            $skipped.Add($item)
        }
    }
    return @{ Included = $included; Skipped = $skipped }
}

# 画面のインデックス作成 1 回分（IndexingSession）。インデクサの司令のスレッドを作り、indexer.ps1 を受け渡しの口（newIndexerChannel）付きで実行する。
# 設計は docs/design/structure/threads.md「スレッドの一覧」「画面とインデクサの受け渡し」、docs/design/structure/closing.md「閉じるときの順番」。
#
# IndexingSession は画面のスレッドだけから呼ぶ（PowerShell 5.1 のクラスのメソッドは、定義したランスペースで動くため）。
# 画面とインデクサのやり取りは、すべて受け渡しの口で行う（中止・確認の返事・進み具合・終了コード）

# インデクサの司令のスレッドで動かすスクリプト。インデックス作成の処理のため、スレッドの優先度を下げる。
# indexerLib の部品（Prelude）は IndexingSession のコンストラクタが、この本体の param ブロックの
# あとにつなぐ（joinWorkerScript）。invokeIndexerMain は indexer\indexer_main.ps1 の関数
${indexingSessionScript} = {
    param ($channel)
    [System.Threading.Thread]::CurrentThread.Priority = [System.Threading.ThreadPriority]::BelowNormal
    invokeIndexerMain -Channel $channel
}

class IndexingSession {
    # 受け渡しの口
    [hashtable]$Channel
    # 始めた時刻
    [datetime]$Started
    hidden [System.Management.Automation.Runspaces.Runspace]$Runspace
    hidden [powershell]$PowerShell
    hidden [System.IAsyncResult]$Handle

    IndexingSession([string]$script, [hashtable]$indexerLoad, [hashtable]$channel) {
        $this.Channel = $channel
        $this.Started = Get-Date
        # 司令のスレッドは COM に触らないため MTA（Office は取り込みのスレッド（STA）が扱う）
        $this.Runspace = [runspacefactory]::CreateRunspace($indexerLoad.State)
        $this.Runspace.ApartmentState = [System.Threading.ApartmentState]::MTA
        $this.Runspace.Open()
        $this.PowerShell = [powershell]::Create()
        $this.PowerShell.Runspace = $this.Runspace
        $joined = if ($indexerLoad.Prelude) { joinWorkerScript $indexerLoad.Prelude $script } else { $script }
        [void]$this.PowerShell.AddScript($joined).AddArgument($channel)
        $this.Handle = $this.PowerShell.BeginInvoke()
    }

    [bool] IsRunning() {
        return $null -ne $this.PowerShell -and !$this.Handle.IsCompleted
    }

    [void] Stop() {
        # 中止を求める（取り込み中のファイルが終わったところで止まる。確認を待っていれば取りやめる）
        $this.Channel.Stop = $true
        [void]$this.Channel.Answered.Set()
    }

    [bool] Wait([int]$milliseconds) {
        # 終わるのを待つ。終わっていれば $true
        if ($null -eq $this.PowerShell) {
            return $true
        }
        return $this.Handle.AsyncWaitHandle.WaitOne($milliseconds)
    }

    [int] GetExitCode() {
        # 終了コード（0 完了 / 1 エラー / 2 中止）。インデクサが終了コードを入れずに止まったとき（読み込めない等）は 1
        if ($null -ne $this.Channel.ExitCode) {
            return [int]$this.Channel.ExitCode
        }
        return 1
    }

    [string] GetError() {
        # 続けられないエラーの内容。インデクサが入れていなければ、スレッドが止まった理由
        if ($this.Channel.Error) {
            return [string]$this.Channel.Error
        }
        $this.Collect()
        return $this.Failure
    }

    [int] GetCloudSkipped() {
        # クラウドにだけあるため、ダウンロードせずに残した件数。無ければ 0
        if ($null -ne $this.Channel.CloudSkipped) {
            return [int]$this.Channel.CloudSkipped
        }
        return 0
    }

    hidden [string]$Failure = ""
    hidden [bool]$Ended = $false

    hidden [void] Collect() {
        # 終わったスレッドの結果を受け取り、止まった理由（例外・エラー）を Failure に残す（1 回だけ）
        if ($this.Ended -or $null -eq $this.PowerShell -or !$this.Handle.IsCompleted) {
            return
        }
        $this.Ended = $true
        try {
            [void]$this.PowerShell.EndInvoke($this.Handle)
            if ($this.PowerShell.Streams.Error.Count -gt 0) {
                $this.Failure = $this.PowerShell.Streams.Error[0].ToString()
            }
        } catch {
            $exception = $_.Exception
            while ($exception.InnerException) {
                $exception = $exception.InnerException
            }
            $this.Failure = $exception.Message
        }
    }

    [int] KillOffice() {
        # インデックス作成が起動して PID を記録した Office だけを止め、止めた数を返す（閉じるときに終わらない場合の最後の手段）
        $count = 0
        foreach ($id in @($this.Channel.OfficePids.Keys)) {
            try {
                $process = [System.Diagnostics.Process]::GetProcessById($id)
                # 終了済みで ID が別のプロセスに使われている場合に備え、記録したプロセス名と起動時刻が同じか確かめる
                $entry = $this.Channel.OfficePids[$id]
                if (isSameOfficeProcess $process $entry.ProcessName $entry.StartTicks) {
                    # 利用者が使っている（取り込み中に見える窓があった）PowerPoint は止めない
                    $mark = $null
                    if ($this.Channel.UserOfficePids.TryGetValue($id, [ref]$mark) -and $mark.StartTicks -eq $entry.StartTicks) {
                        continue
                    }
                    # 今、見える窓があるプロセスも止めない（アプリを問わない。取り込みのプロセスは窓を出さない）
                    if (testOfficeProcessHasWindow $process) {
                        continue
                    }
                    $process.Kill()
                    $count++
                }
            } catch {
            }
        }
        return $count
    }

    [void] Close() {
        # スレッドを片づける。終わっていなければ中止を求めて待つ（呼ぶ側が終わるのを待ってから呼ぶ）。何度呼んでもよい
        if ($null -eq $this.PowerShell) {
            return
        }
        if (!$this.Handle.IsCompleted) {
            $this.Stop()
            if (!$this.Wait(5000)) {
                try {
                    $this.PowerShell.Stop()
                } catch {
                }
            }
        }
        $this.Collect()
        $this.PowerShell.Dispose()
        $this.PowerShell = $null
        $this.Runspace.Dispose()
        $this.Runspace = $null
    }
}

function newIndexingSession {
    # インデックス作成を始める（画面の［すべて更新］）。終わったら Close を呼ぶ
    param (
        [hashtable]$channel
    )

    $indexerLoad = getPartLoad indexerLib
    return [IndexingSession]::new(${indexingSessionScript}.ToString(), $indexerLoad, $channel)
}

# 検索の条件（正規表現・対象ファイル）の組み立て（判断層。ファイルに触らない）。

function isValidRegex {
    # 正規表現として正しいか
    param (
        [string]$pattern
    )

    try {
        [void][regex]::new($pattern)
        return $true
    } catch {
        return $false
    }
}


# 1行の照合にかけてよい時間。正規表現によっては終わらなくなるため、超えたら検索を止める
${regexTimeout} = [timespan]::FromSeconds(5)

function getRegexScanMode {
    # 正規表現を TSV の全文（改行は LF にそろえ、^ $ は行の先頭・末尾に一致させる）にかけてよいかを返す。
    # 1 行ずつ PowerShell で照合すると遅いため、全文への照合（.NET の中で走る）で済ませられる場合を見分ける。
    #   "lines" : 一致は必ず 1 行の中に収まり、行の外の文字を見ない。全文での一致の位置から、ヒットした行が分かる
    #   "filter": 行をまたいで一致することはあるが、1 行で一致するなら全文でも必ず一致する。
    #             全文で一致しない TSV は読み飛ばせる（一致した TSV は 1 行ずつ照合し直す）
    #   "scan"  : 全文では 1 行と結果が変わりうる（\A \z、否定の先読み・後読み、(?i) 等）。1 行ずつ照合する
    # 判定は安全側に倒す（分からない書き方は "filter" か "scan"）。検索結果は照合のしかたによらず同じになる
    param (
        [string]$pattern
    )

    $lines = $true
    $inClass = $false
    $classStart = 0
    $length = $pattern.Length
    for ($i = 0; $i -lt $length; $i++) {
        $c = $pattern[$i]
        if ($c -eq '\') {
            $i++
            if ($i -ge $length) {
                return "scan"
            }
            $e = $pattern[$i]
            if ("AzZG".IndexOf($e) -ge 0) {
                return "scan"   # 文字列の先頭・末尾は、1 行と全文とで位置が違う
            }
            if ("sWDpPnrxuc0123456789".IndexOf($e) -ge 0) {
                $lines = $false  # 改行にも一致しうる（\s \W \D \p{..} \n \x0A \u000A \cJ 8 進数・後方参照）
            }
            if ($inClass -and $i + 1 -lt $length -and $pattern[$i + 1] -eq '-') {
                $lines = $false  # エスケープから始まる範囲（[\t-z] 等）は改行を含みうる
            }
            continue
        }
        if ([int]$c -lt 0x20) {
            $lines = $false      # 制御文字をそのまま含む（改行・タブから始まる範囲など）
        }
        if ($inClass) {
            if ($c -eq ']' -and $i -gt $classStart) {
                $inClass = $false
            }
            continue
        }
        if ($c -eq '[') {
            $inClass = $true
            if ($i + 1 -lt $length -and $pattern[$i + 1] -eq '^') {
                $lines = $false  # 否定の文字クラスは改行に一致する
                $i++
            }
            $classStart = $i + 1  # 先頭の ] は文字として扱われる
            continue
        }
        if ($c -eq '(' -and $i + 1 -lt $length -and $pattern[$i + 1] -eq '?') {
            $rest = $pattern.Substring($i + 2)
            if ($rest.StartsWith(":") -or $rest.StartsWith(">")) {
                continue
            }
            if ($rest.StartsWith("=") -or $rest.StartsWith("<=")) {
                $lines = $false  # 肯定の先読み・後読みは行の外（改行）を見る。全文で一致が増えるだけなので "filter" にはできる
                continue
            }
            if ($rest -match "^(<[A-Za-z_]|'[A-Za-z_])") {
                continue         # 名前付きグループ
            }
            return "scan"        # 否定の先読み・後読み、(?i) 等のオプション、条件分岐、コメント
        }
    }
    if ($lines) {
        return "lines"
    }
    return "filter"
}


function newSearchRegex {
    # 検索条件から、検索と一致箇所の強調で使う正規表現を作る（画面の検索と結果の表示で共通）。
    #   simpleMatch  : $true ならワードを文字どおりに探す。$false なら正規表現として探し、正規表現として不正なら文字どおりに探す
    #   caseSensitive: 英字の大文字・小文字を区別する（既定は区別しない）
    # @{ Regex; SimpleMatch（実際に文字どおり探すか）; TextRegex; ScanMode } を返す。
    #   TextRegex: TSV の全文にかける正規表現（Regex に Multiline を足したもの。^ $ が行の先頭・末尾に一致する）
    #   ScanMode : TextRegex を全文にかけてよいか（getRegexScanMode）
    param (
        [string]$word,
        [bool]$simpleMatch = $true,
        [bool]$caseSensitive = $false
    )

    if (!$simpleMatch -and !(isValidRegex $word)) {
        $simpleMatch = $true
    }
    $pattern = if ($simpleMatch) { [regex]::Escape($word) } else { $word }
    # CultureInvariant: 大文字・小文字を区別しないときの照合が、区別する場合と同程度に速くなる（日本語の照合結果は変わらない）
    $options = [System.Text.RegularExpressions.RegexOptions]::CultureInvariant
    if (!$caseSensitive) {
        $options = $options -bor [System.Text.RegularExpressions.RegexOptions]::IgnoreCase
    }
    $textOptions = $options -bor [System.Text.RegularExpressions.RegexOptions]::Multiline
    return @{
        Regex       = New-Object System.Text.RegularExpressions.Regex($pattern, $options, ${regexTimeout})
        SimpleMatch = $simpleMatch
        TextRegex   = New-Object System.Text.RegularExpressions.Regex($pattern, $textOptions, ${regexTimeout})
        ScanMode    = getRegexScanMode $pattern
    }
}

function newPlaceExclude {
    # 検索から外す場所（図形・コメント）の正規表現を返す。どちらも検索するなら $null。
    # 場所の名前は "<元の場所>[<種類>]"（index_name.ps1 の objectPlacePattern）。Excel・Word・PowerPoint で共通
    param (
        [bool]$includeShapes = $true,
        [bool]$includeComments = $true
    )

    $kinds = @()
    # 埋め込み（"[埋め込み<N>]"）は図形と一緒に切り替える（検索の選択肢を増やさない）
    if (!$includeShapes) { $kinds += ${placeKindShape}; $kinds += ${placeKindEmbed} }
    if (!$includeComments) { $kinds += ${placeKindComment} }
    if ($kinds.Count -eq 0) {
        return $null
    }
    return [regex]::new((newObjectPlaceKindPattern -kinds $kinds))
}

# テキストのヒットの行・プレビューの前後の行を切る長さ（文字）と、一致の位置から遡る長さ（文字）。
# 1 行が数 MB になりうる .json・.xml・.log の描画で画面が固まらないよう、取り込みでは切らず、表示・出力の直前だけ切る
${hitLineMaxChars} = 1000
${hitLineBeforeMatchChars} = 200

function truncateHitLine {
    # 長い行（テキストのヒットの行・前後の行）を、一致の位置を中心に hitLineMaxChars 文字に切る。
    # 一致の位置（matchIndex。行の中の位置。分からなければ -1）の hitLineBeforeMatchChars 文字前から hitLineMaxChars 文字を取り、
    # 省いた側に "…" を付ける。hitLineMaxChars 以下ならそのまま返す
    param (
        [string]$line,
        [int]$matchIndex = -1
    )

    if ($line.Length -le ${hitLineMaxChars}) {
        return $line
    }
    $start = if ($matchIndex -lt 0) { 0 } else { [Math]::Max(0, $matchIndex - ${hitLineBeforeMatchChars}) }
    $end = [Math]::Min($line.Length, $start + ${hitLineMaxChars})
    $result = $line.Substring($start, $end - $start)
    if ($start -gt 0) { $result = "…" + $result }
    if ($end -lt $line.Length) { $result = $result + "…" }
    return $result
}

function getFileKindExtensions {
    # 検索バーのチップの種類（excel・word・powerpoint・text・pdf）ごとの拡張子（小文字）を返す。知らない種類は空
    param (
        [string]$kind
    )

    switch ($kind) {
        "excel" { return @(${officeExtensions} | Where-Object { $_ -like ".xl*" }) }
        "word" { return @(${officeExtensions} | Where-Object { $_ -like ".do*" }) }
        "powerpoint" { return @(${officeExtensions} | Where-Object { $_ -like ".pp*" }) }
        "text" { return @(${textExtensions}) }
        "pdf" { return @(${pdfExtensions}) }
    }
    return @()
}

function newFileKindFilter {
    # 選んだ種類（readFileKinds の値）から、対象ファイルの条件（newFileFilter に渡す文字列。"*.xlsx;*.xls" の形）を作る。
    # すべての種類を選んでいる・空・知らない種類だけのときは空（絞り込まない）
    param (
        [object[]]$kinds
    )

    $chosen = @(${fileKindNames} | Where-Object { @($kinds) -contains $_ })
    if ($chosen.Count -eq 0 -or $chosen.Count -eq ${fileKindNames}.Count) {
        return ""
    }
    return (@($chosen | ForEach-Object { getFileKindExtensions $_ } | ForEach-Object { "*$_" }) -join ";")
}

function newFileFilter {
    # 対象ファイルの指定（例: "*.xlsx;見積*;!*old*"）を、元のファイル名に対する正規表現 @{ Include; Exclude } にする（無い側は $null）。
    #   ; で区切る（全角の ； も可）。! で始まるものは除外。* は任意の文字列、? は任意の1文字。大文字・小文字を区別しない
    #   * も ? も無いものは部分一致（「見積」は「*見積*」）
    param (
        [string]$filter
    )

    $include = New-Object System.Collections.Generic.List[string]
    $exclude = New-Object System.Collections.Generic.List[string]
    foreach ($item in ([string]$filter).Split([char[]]";；")) {
        $item = $item.Trim()
        $list = $include
        if ($item.StartsWith("!") -or $item.StartsWith("！")) {
            $list = $exclude
            $item = $item.Substring(1).Trim()
        }
        if ($item -eq "") {
            continue
        }
        if ($item.IndexOfAny([char[]]"*?") -lt 0) {
            $item = "*${item}*"
        }
        $list.Add("^" + [regex]::Escape($item).Replace("\*", ".*").Replace("\?", ".") + "$")
    }

    $options = [System.Text.RegularExpressions.RegexOptions]::IgnoreCase -bor [System.Text.RegularExpressions.RegexOptions]::CultureInvariant
    $result = @{ Include = $null; Exclude = $null }
    if ($include.Count -gt 0) {
        $result.Include = New-Object System.Text.RegularExpressions.Regex(($include -join "|"), $options)
    }
    if ($exclude.Count -gt 0) {
        $result.Exclude = New-Object System.Text.RegularExpressions.Regex(($exclude -join "|"), $options)
    }
    return $result
}

# 高速検索（Windows Search で検索語を含みうるフォルダを先に絞る）の決まり（判断層。ファイルにも画面にも触らない）。
# システムインデックス（system_index の txt）は、文字の 2-gram を英数字の語にしたものを空白区切りで書く。
# Windows Search は語単位でしか一致を取らないため、本文をそのまま索引させると語の途中からの一致を落とすが、
# 2-gram の語なら、ワードを含む本文の txt には、ワードのすべての 2-gram が必ず入っている。

# システムインデックスの名前（置き場所は paths.ps1 の $workspace.SystemIndexDir）
${systemIndexFileName}      = "system_index.txt"
${systemIndexFileLike}      = "system[_]index%"      # 問い合わせの LIKE（分けたものも含む）。LIKE の _ は任意の1文字のため [_] と書く
${systemIndexSplitLike}     = "system[_]index[_]%"   # 分けたもの（system_index_1.txt …）だけ

# 1 つの txt の大きさの上限（これを超えたら語の範囲で分ける。実測では 16MB までは末尾まで索引された）
${systemIndexPartBytes} = 8MB
# txt のパスの長さの上限（これ以上は作らず、そのフォルダは .NET で照合する。Windows Search が長いパスを索引しないおそれがあるため）
${systemIndexPathMax} = 240
# 1 回の問い合わせに使う語の数の上限（多いときは均等に間引く。間引いても候補が増えるだけで漏れない）
${searchGramMax} = 16

# 状態ファイルの行の種別
${systemIndexCovered}  = "対応済み"   # インデックスのすべてのフォルダに txt がある（または対象外として記録した）
${systemIndexPending}  = "反映待ち"   # txt を書いた（値は txt の更新日時。UTC の Ticks）
${systemIndexExcluded} = "対象外"     # txt を作らなかったフォルダ（常に .NET で照合する）

function convertToGramToken {
    # 2 文字（小文字にしたもの）を語にする: x ＋ UTF-16LE の 4 バイトの 16 進（例: "ニタ" → xcb30bf30）
    param (
        [string]$pair
    )

    return "x" + [System.BitConverter]::ToString([System.Text.Encoding]::Unicode.GetBytes($pair)).Replace("-", "").ToLowerInvariant()
}

function getSearchGrams {
    # 検索語から、問い合わせに使う語を返す（重複なし・最大 searchGramMax 個）。
    # 空白で区切り、2 文字以上の部分の隣り合う 2 文字を語にする。語が無ければ空（高速検索は使えない）
    param (
        [string]$word
    )

    $grams = New-Object System.Collections.Generic.List[string]
    $seen = New-Object System.Collections.Generic.HashSet[string]
    foreach ($part in ([string]$word).ToLowerInvariant() -split "[\s\u2028]+") {
        for ($i = 0; $i -lt $part.Length - 1; $i++) {
            $token = convertToGramToken $part.Substring($i, 2)
            if ($seen.Add($token)) {
                $grams.Add($token)
            }
        }
    }
    if ($grams.Count -le ${searchGramMax}) {
        return , $grams.ToArray()
    }
    # 均等に間引く（先頭と末尾は残す）
    $picked = New-Object System.Collections.Generic.List[string]
    for ($k = 0; $k -lt ${searchGramMax}; $k++) {
        $picked.Add($grams[[int][Math]::Round($k * ($grams.Count - 1) / (${searchGramMax} - 1))])
    }
    return , $picked.ToArray()
}

function testFastSearchUsable {
    # 高速検索を使えるか（画面の「使用可 / 使用不可」）。
    #   available: Windows Search を開けて、system_index が索引の対象（windows_search.ps1 の testWindowsSearch）
    param (
        [bool]$available,
        [bool]$useRegex,
        [string]$word
    )

    return ($available -and !$useRegex -and (getSearchGrams $word).Count -gt 0)
}

function addTextGrams {
    # 本文の 2-gram を、語の値（uint32。UTF-16LE の 2 文字をそのまま 4 バイトの整数にしたもの）として set に足す。
    # 1 文字ずつ PowerShell で回すと遅いため、char[] を uint32[] に写して .NET の HashSet で重複を除く。
    # 空白を含む 2-gram も入るが、問い合わせには使わないため害は無い（除く方が遅い）
    param (
        [System.Collections.Generic.HashSet[uint32]]$set,
        [string]$text
    )

    $chars = $text.ToLowerInvariant().ToCharArray()
    $even = $chars.Length -shr 1
    $odd = ($chars.Length - 1) -shr 1
    if ($even -gt 0) {
        $u0 = New-Object 'uint32[]' $even
        [System.Buffer]::BlockCopy($chars, 0, $u0, 0, $even * 4)
        $set.UnionWith($u0)
    }
    if ($odd -gt 0) {
        # 1 文字ずらした並びは、2 バイトずらして写せば作れる
        $u1 = New-Object 'uint32[]' $odd
        [System.Buffer]::BlockCopy($chars, 2, $u1, 0, $odd * 4)
        $set.UnionWith($u1)
    }
}

function convertToGramText {
    # 語の値（昇順に並べたもの）の start から count 個を、txt に書く文字列にする（x ＋ 16 進 8 桁を空白区切り）
    param (
        [uint32[]]$values,
        [int]$start = 0,
        [int]$count = -1
    )

    if ($count -lt 0) {
        $count = $values.Length - $start
    }
    if ($count -le 0) {
        return ""
    }
    $bytes = New-Object 'byte[]' ($count * 4)
    [System.Buffer]::BlockCopy($values, $start * 4, $bytes, 0, $count * 4)
    $hex = [System.BitConverter]::ToString($bytes).Replace("-", "").ToLowerInvariant()
    return [regex]::Replace($hex, "(.{8})", 'x$1 ')
}

function getGramPartCount {
    # 語の数から、txt をいくつに分けるかを返す（1 語は "x" ＋ 8 桁 ＋ 空白の 10 バイト）
    param (
        [int]$count,
        [long]$partBytes = ${systemIndexPartBytes}
    )

    $perPart = [Math]::Max(1, [int][Math]::Floor($partBytes / 10))
    return [Math]::Max(1, [int][Math]::Ceiling($count / $perPart))
}

function getSystemIndexFileNames {
    # txt の名前（分けないときは 1 つ。分けるときは system_index_1.txt …）
    param (
        [int]$parts
    )

    if ($parts -le 1) {
        return , @(${systemIndexFileName})
    }
    $base = [System.IO.Path]::GetFileNameWithoutExtension(${systemIndexFileName})
    return , @(1..$parts | ForEach-Object { "${base}_$_.txt" })
}

function testSystemIndexPath {
    # txt のパスが長すぎないか（分けたときは最も長い名前で判定する）
    param (
        [string]$folder,
        [int]$parts = 1
    )

    $longest = @(getSystemIndexFileNames $parts | Sort-Object Length -Descending)[0]
    return ("$folder\$longest").Length -lt ${systemIndexPathMax}
}

function convertFolderRoot {
    # フォルダのパスの先頭（fromRoot）を toRoot に置き換える（system_index と index は同じ相対パスの構成）。
    # fromRoot の外のパスは $null
    param (
        [string]$path,
        [string]$fromRoot,
        [string]$toRoot
    )

    $from = $fromRoot.TrimEnd("\")
    if ($path.Equals($from, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $toRoot.TrimEnd("\")
    }
    if ($path.StartsWith("$from\", [System.StringComparison]::OrdinalIgnoreCase)) {
        return $toRoot.TrimEnd("\") + $path.Substring($from.Length)
    }
    return $null
}

function getRelativePath {
    # root からの相対パス（root の外・root そのものは $null）
    param (
        [string]$path,
        [string]$root
    )

    $base = $root.TrimEnd("\")
    if ($path.StartsWith("$base\", [System.StringComparison]::OrdinalIgnoreCase) -and $path.Length -gt $base.Length + 1) {
        return $path.Substring($base.Length + 1)
    }
    return $null
}

function convertItemUrl {
    # Windows Search の System.ItemUrl（file:C:/…）をパスにする。% は符号化されていないため URL として戻さない
    param (
        [string]$url
    )

    return $url.Substring($url.IndexOf(":") + 1).Replace("/", "\")
}

function convertToScopeUrl {
    # SCOPE に書く URL（file:C:/…）。SQL の文字列に入れるため ' は重ねる
    param (
        [string]$path
    )

    return ("file:" + $path.TrimEnd("\").Replace("\", "/")).Replace("'", "''")
}

function newSystemIndexQuery {
    # 候補の txt（分けていないもの）を探す問い合わせ
    param (
        [string]$scopeDir,
        [string[]]$grams
    )

    $condition = ($grams | ForEach-Object { "`"$_`"" }) -join " AND "
    return "SELECT System.ItemUrl FROM SystemIndex WHERE SCOPE='$(convertToScopeUrl $scopeDir)' AND System.FileName = '${systemIndexFileName}' AND CONTAINS(System.Search.Contents, '$condition')"
}

function newSystemIndexSplitQuery {
    # 分けた txt から、語を 1 つ含むものを探す問い合わせ（分けた txt は AND で 1 回に問えないため語ごとに問う）
    param (
        [string]$scopeDir,
        [string]$gram
    )

    return "SELECT System.ItemUrl FROM SystemIndex WHERE SCOPE='$(convertToScopeUrl $scopeDir)' AND System.FileName LIKE '${systemIndexSplitLike}' AND CONTAINS(System.Search.Contents, '`"$gram`"')"
}

function newSystemIndexStateQuery {
    # 反映の判定に使う値（GatherTime・DateModified）を取る問い合わせ
    param (
        [string]$scopeDir
    )

    return "SELECT System.ItemUrl, System.Search.GatherTime, System.DateModified FROM SystemIndex WHERE SCOPE='$(convertToScopeUrl $scopeDir)' AND System.FileName LIKE '${systemIndexFileLike}'"
}

function testSystemIndexReflected {
    # txt が Windows Search に反映済みか: 本文を読み終えた（GatherTime がある）かつ、今の版を索引した
    # （DateModified が txt の更新日時を秒で切り捨てた値と同じ。Windows Search は秒未満を切り捨てて持つ）
    param (
        $gatherTime,
        $dateModified,
        [long]$fileTicksUtc
    )

    if ($null -eq $gatherTime -or $gatherTime -is [System.DBNull] -or $null -eq $dateModified -or $dateModified -is [System.DBNull]) {
        return $false
    }
    return ([datetime]$dateModified).Ticks -eq ($fileTicksUtc - ($fileTicksUtc % [timespan]::TicksPerSecond))
}

function testFolderInTarget {
    # フォルダ（TSV のフォルダ）が検索対象に入るか。recurse が $false なら対象フォルダそのものだけ
    param (
        [string]$folder,
        [string]$targetDir,
        [bool]$recurse
    )

    $target = $targetDir.TrimEnd("\")
    if ($folder.Equals($target, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $true
    }
    return ($recurse -and $folder.StartsWith("$target\", [System.StringComparison]::OrdinalIgnoreCase))
}

function convertFromSystemIndexState {
    # 状態ファイルの行を読む（パスは system_index からの相対パス）。形の違う行は無視する。
    #   Covered : 対応済みのインデックス名 / Pending: txt の相対パス → 書いた日時（Ticks）/ Excluded: 対象外のフォルダの相対パス
    param (
        [string[]]$lines
    )

    $state = newSystemIndexState
    foreach ($line in $lines) {
        $cells = ([string]$line).Split("`t")
        if ($cells.Count -lt 2 -or $cells[1] -eq "") {
            continue
        }
        switch ($cells[0]) {
            ${systemIndexCovered} { [void]$state.Covered.Add($cells[1]) }
            ${systemIndexExcluded} { [void]$state.Excluded.Add($cells[1]) }
            ${systemIndexPending} {
                $ticks = 0L
                if ($cells.Count -ge 3 -and [long]::TryParse($cells[2], [ref]$ticks)) {
                    $state.Pending[$cells[1]] = $ticks
                }
            }
        }
    }
    return $state
}

function newSystemIndexState {
    # 空の状態
    return @{
        Covered  = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
        Pending  = New-Object 'System.Collections.Generic.Dictionary[string,long]' ([System.StringComparer]::OrdinalIgnoreCase)
        Excluded = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    }
}

function convertToSystemIndexState {
    # 状態を状態ファイルの行にする（対応済み・対象外・反映待ちの順。それぞれ名前順）
    param (
        $state
    )

    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($name in ($state.Covered | Sort-Object)) {
        $lines.Add("${systemIndexCovered}`t$name`t")
    }
    foreach ($rel in ($state.Excluded | Sort-Object)) {
        $lines.Add("${systemIndexExcluded}`t$rel`t")
    }
    foreach ($rel in ($state.Pending.Keys | Sort-Object)) {
        $lines.Add("${systemIndexPending}`t$rel`t$($state.Pending[$rel])")
    }
    return , $lines.ToArray()
}

function getIndexNameOfRelPath {
    # system_index（index）からの相対パスの先頭（インデックス名）
    param (
        [string]$relPath
    )

    return ([string]$relPath).Split("\")[0]
}

# Windows Search への問い合わせ（OLE DB の Search.CollatorDSO）。読み取り（SELECT）だけを送る。
# 管理者権限は要らない。Windows Search のサービスが止まっている・ポリシーで無効なときは開けない（高速検索を使わない）。

function openWindowsSearch {
    # Windows Search への接続を開く。開けなければ $null
    try {
        $connection = New-Object System.Data.OleDb.OleDbConnection "Provider=Search.CollatorDSO;Extended Properties='Application=Windows';"
        $connection.Open()
        return $connection
    } catch {
        return $null
    }
}

function invokeWindowsSearch {
    # 問い合わせを実行し、行（object[]）の一覧を返す。SELECT 以外は送らない
    param (
        $connection,
        [string]$sql,
        [int]$timeoutSeconds = 10
    )

    if ($sql -notmatch "^\s*SELECT\s") {
        throw "Windows Search へは SELECT だけを送る: $sql"
    }
    $command = $connection.CreateCommand()
    $command.CommandText = $sql
    $command.CommandTimeout = $timeoutSeconds
    $rows = New-Object 'System.Collections.Generic.List[object[]]'
    $reader = $command.ExecuteReader()
    try {
        while ($reader.Read()) {
            $values = New-Object object[] $reader.FieldCount
            [void]$reader.GetValues($values)
            $rows.Add($values)
        }
    } finally {
        $reader.Dispose()
        $command.Dispose()
    }
    return , $rows
}

function getWindowsSearchState {
    # 高速検索に使えるかと、使えない理由。次のどれかの文字列を返す（画面の文言は ui/index/index_list_view.ps1 の getFastSearchRowView）。
    #   NoFolder     : system_index のフォルダが無い（インデックスを作っていない・ワークスペースが違う）
    #   NoConnection : Windows Search を開けない、または問い合わせに失敗した（時間切れを含む）
    #   NotInScope   : system_index が 0 件で、ワークスペースの中も 1 件も索引されていない（索引の対象外とみなす）
    #   NotYet       : system_index が 0 件だが、ワークスペースの中のほかのものは索引されている（対象だが、まだ索引されていないとみなす）
    #   Ok           : system_index が 1 件以上索引されている（フォルダ自体が SystemIndex に入っている）
    # 管理者権限なしに索引の対象の一覧を読む方法が無いため、NotInScope と NotYet はワークスペースの中の様子で見分ける。
    #   workspaceDir: 空なら、systemRoot の 1 つ上（ワークスペース）
    #   connection  : 開いた接続。$null なら自分で開いて閉じる（渡したら呼び出し側が閉じる）
    param (
        [string]$systemRoot = $workspace.SystemIndexDir,
        [string]$workspaceDir = "",
        $connection = $null
    )

    if (![System.IO.Directory]::Exists((toLongPath $systemRoot))) {
        return "NoFolder"
    }
    if (!$workspaceDir) {
        $workspaceDir = [System.IO.Path]::GetDirectoryName($systemRoot.TrimEnd("\"))
    }
    $own = $null -eq $connection
    if ($own) {
        $connection = openWindowsSearch
        if ($null -eq $connection) {
            return "NoConnection"
        }
    }
    try {
        $rows = invokeWindowsSearch $connection "SELECT TOP 1 System.ItemUrl FROM SystemIndex WHERE SCOPE='$(convertToScopeUrl $systemRoot)'"
        if ($rows.Count -gt 0) {
            return "Ok"
        }
        $rows = invokeWindowsSearch $connection "SELECT TOP 1 System.ItemUrl FROM SystemIndex WHERE SCOPE='$(convertToScopeUrl $workspaceDir)'"
        return $(if ($rows.Count -gt 0) { "NotYet" } else { "NotInScope" })
    } catch {
        return "NoConnection"
    } finally {
        if ($own) {
            $connection.Dispose()
        }
    }
}

function testWindowsSearch {
    # 高速検索に使えるか: Windows Search を開けて、system_index が索引の対象か（getWindowsSearchState が Ok）
    param (
        [string]$systemRoot = $workspace.SystemIndexDir
    )

    return (getWindowsSearchState $systemRoot) -eq "Ok"
}

function testTsvIndexedByWindowsSearch {
    # 本文インデックス（index の TSV）が Windows Search に索引されているか（利用者が対象から外していないか）。
    # 外していなくても結果は正しいが、txt の索引が遅くなるため、画面で案内を出すのに使う
    #   connection: 開いた接続。$null なら自分で開いて閉じる（渡したら呼び出し側が閉じる）
    param (
        [string]$indexRoot = $workspace.IndexDir,
        $connection = $null
    )

    $own = $null -eq $connection
    if ($own) {
        $connection = openWindowsSearch
        if ($null -eq $connection) {
            return $false
        }
    }
    try {
        $rows = invokeWindowsSearch $connection "SELECT TOP 1 System.ItemUrl FROM SystemIndex WHERE SCOPE='$(convertToScopeUrl $indexRoot)' AND System.FileExtension = '.tsv'"
        return $rows.Count -gt 0
    } catch {
        return $false
    } finally {
        if ($own) {
            $connection.Dispose()
        }
    }
}

# 高速検索: Windows Search で検索語を含みうるフォルダを先に絞り、照合する本文インデックスのファイルを集める（状態層）。
# 集めた本文インデックスのファイルは、今までどおり searchContentIndex で照合する。結果（行・行番号・順番）は、すべてを照合したときと同じになる:
#   反映済みの システムインデックスには、そのフォルダの本文インデックスのファイルのすべての 2-gram が入っていて、検索語の語はその一部のため、
#   当たる本文インデックスのファイルのフォルダは必ず候補に入る。反映済みでない・対象外・対応済みでないものは、候補に関係なく照合する。

function getReflectedSystemIndexEntries {
    # 状態ファイルの反映待ちの行を、Windows Search の索引と照らして、反映済みになったものとまだのものに分ける。
    # @{ Reflected（反映済みになった行の相対パス）; Unreflected（まだ反映されていない行があるフォルダの相対パス） } を返す。
    # 反映待ちが無ければ、Windows Search には問い合わせない。問い合わせに失敗したら例外のまま投げる
    #   ask: { param($sql) 行（object[]）の一覧 }（呼び出し元の $query・$connection を見る。& で呼ぶと呼び出し元の変数が見える）
    param (
        $state,
        [string]$systemRootPath,
        [scriptblock]$ask
    )

    $reflected = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    $unreflected = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    if ($state.Pending.Count -gt 0) {
        foreach ($row in (& $ask (newSystemIndexStateQuery $systemRootPath))) {
            $rel = getRelativePath (convertItemUrl ([string]$row[0])) $systemRootPath
            if ($rel -and $state.Pending.ContainsKey($rel) -and (testSystemIndexReflected $row[1] $row[2] $state.Pending[$rel])) {
                [void]$reflected.Add($rel)
            }
        }
        foreach ($rel in $state.Pending.Keys) {
            if (!$reflected.Contains($rel)) {
                [void]$unreflected.Add([System.IO.Path]::GetDirectoryName($rel))
            }
        }
    }
    return @{ Reflected = $reflected; Unreflected = $unreflected }
}

function getFastSearchContentIndexFiles {
    # 高速検索で照合する本文インデックスのファイルを、getContentIndexFiles と同じ形（@{ Folders; ContentIndexFiles }）に Fast（@{ Candidates; Unreflected }）を足して返す。
    # 高速検索を使えないとき（検索語から語を作れない・状態ファイルを読めない・Windows Search に問い合わせられない）は $null
    # （呼び出し側が getContentIndexFiles ですべての本文インデックスのファイルを集める）。
    #   folders: getContentIndexFiles と同じ（文字列、または @{ Root; RelPath; Recurse }）
    #   query  : { param($sql) 行（object[]）の一覧 }。$null なら Windows Search を開いて問い合わせる（テストで差し替える）
    param (
        [string]$word,
        [object[]]$folders,
        [scriptblock]$query = $null,
        [string]$indexRoot = $workspace.IndexDir,
        [string]$systemRoot = $workspace.SystemIndexDir,
        [string]$statePath = $workspace.SystemIndexStateFile,
        [scriptblock]$onProgress = $null
    )

    $grams = getSearchGrams $word
    if ($grams.Count -eq 0) {
        return $null
    }
    $state = readSystemIndexState $statePath
    if ($null -eq $state) {
        return $null
    }
    $connection = $null
    if ($null -eq $query) {
        $connection = openWindowsSearch
        if ($null -eq $connection) {
            return $null
        }
    }
    # 問い合わせ（差し替えが無ければ開いた接続で）。& で呼ぶと、この関数の $query・$connection が見える
    $ask = {
        param ($sql)
        if ($query) { & $query $sql } else { invokeWindowsSearch $connection $sql }
    }

    $indexRootPath = $indexRoot.TrimEnd("\")
    $systemRootPath = $systemRoot.TrimEnd("\")
    $targets = New-Object System.Collections.Generic.List[object]
    $candidates = 0
    try {
        # 反映の判定（状態ファイルに反映待ちがあるものだけ。反映済みになった行は、この後で状態から消す）
        $entries = getReflectedSystemIndexEntries $state $systemRootPath $ask
        $reflected = $entries.Reflected
        $unreflected = $entries.Unreflected

        foreach ($folder in $folders) {
            if ($folder -is [string]) {
                $folder = @{ Root = $folder; RelPath = ""; Recurse = $true }
            }
            $root = ([string]$folder.Root).TrimEnd("\")
            $relPath = ([string]$folder.RelPath).Trim("\")
            $targetDir = if ($relPath) { "$root\$relPath" } else { $root }
            # 別の場所のインデックス・インデックス全体・対応済みでないインデックス・無いフォルダは、今までどおりすべてを列挙する
            if (!$root.Equals($indexRootPath, [System.StringComparison]::OrdinalIgnoreCase) -or $relPath -eq "" -or
                !$state.Covered.Contains((getIndexNameOfRelPath $relPath)) -or ![System.IO.Directory]::Exists((toLongPath $targetDir))) {
                $targets.Add($folder)
                continue
            }
            $found = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
            $scopeDir = "$systemRootPath\$relPath"
            if ([System.IO.Directory]::Exists((toLongPath $scopeDir))) {
                foreach ($row in (& $ask (newSystemIndexQuery $scopeDir $grams))) {
                    $rel = getRelativePath ([System.IO.Path]::GetDirectoryName((convertItemUrl ([string]$row[0])))) $systemRootPath
                    if ($rel) { [void]$found.Add($rel) }
                }
                # 分けた txt は、語ごとに問い合わせ、すべての語がどれかの部分で見つかったフォルダを候補にする
                $split = $null
                foreach ($gram in $grams) {
                    $hit = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
                    foreach ($row in (& $ask (newSystemIndexSplitQuery $scopeDir $gram))) {
                        $rel = getRelativePath ([System.IO.Path]::GetDirectoryName((convertItemUrl ([string]$row[0])))) $systemRootPath
                        if ($rel) { [void]$hit.Add($rel) }
                    }
                    if ($null -eq $split) { $split = $hit } else { $split.IntersectWith($hit) }
                    if ($split.Count -eq 0) { break }
                }
                if ($split) { $found.UnionWith($split) }
            }
            $candidates += $found.Count
            $found.UnionWith($unreflected)
            $found.UnionWith($state.Excluded)
            foreach ($rel in $found) {
                $dir = "$indexRootPath\$rel"
                if ((testFolderInTarget $dir $targetDir ([bool]$folder.Recurse)) -and [System.IO.Directory]::Exists((toLongPath $dir))) {
                    $targets.Add(@{ Root = $indexRootPath; RelPath = $rel; Recurse = $false })
                }
            }
        }
    } catch {
        return $null
    } finally {
        if ($connection) {
            $connection.Dispose()
        }
    }

    $index = getContentIndexFiles $targets.ToArray() $onProgress
    if ($reflected.Count -gt 0) {
        # 反映済みになった行を消す（txt が書き直されて日時が変わった行は残す）。書けなくても検索は続ける。
        # 書き換えの中から見る値は、updateSystemIndexState の変数と名前が重ならないようにする（呼び出し先の $state が見えてしまう）
        $readTicks = $state.Pending
        [void](updateSystemIndexState {
            param ($current)
            foreach ($rel in $reflected) {
                if ($current.Pending.ContainsKey($rel) -and $current.Pending[$rel] -eq $readTicks[$rel]) {
                    [void]$current.Pending.Remove($rel)
                }
            }
        } $statePath)
    }
    $index.Fast = @{ Candidates = $candidates; Unreflected = $unreflected.Count }
    return $index
}

function getSystemIndexProgress {
    # システムインデックス（高速検索用の txt）が Windows Search にどこまで反映されたかを数える。画面が「確かめるとき」だけ呼ぶ（検索では呼ばない）。
    # @{ Folders; Waiting; ContentIndexed; ByIndex } を返す。状態ファイルを読めない・Windows Search に問い合わせられないときは $null。
    #   Folders       : txt があるフォルダと、状態ファイルの反映待ちのフォルダを合わせた数（分けた txt は 1 つのフォルダに数える）
    #   Waiting       : 反映待ちのうち、Windows Search でまだ反映済みでないフォルダの数（getFastSearchContentIndexFiles と同じ判定）
    #   ContentIndexed: 本文インデックス（index の TSV）も Windows Search に索引されているか（反映が遅い理由の案内に使う）
    #   ByIndex       : インデックス名（system_index からの相対パスの先頭のフォルダ名） → @{ Folders; Waiting } の辞書（OrdinalIgnoreCase）
    #   query         : getFastSearchContentIndexFiles と同じ。$null なら Windows Search を開いて問い合わせる（テストで差し替える）
    #   connection    : 開いた接続（渡したら呼び出し側が閉じる）。$null なら query が無いときだけ自分で開いて閉じる
    param (
        [scriptblock]$query = $null,
        [string]$indexRoot = $workspace.IndexDir,
        [string]$systemRoot = $workspace.SystemIndexDir,
        [string]$statePath = $workspace.SystemIndexStateFile,
        $connection = $null
    )

    $state = readSystemIndexState $statePath
    if ($null -eq $state) {
        return $null
    }
    $own = $false
    if ($null -eq $query -and $null -eq $connection) {
        $connection = openWindowsSearch
        if ($null -eq $connection) {
            return $null
        }
        $own = $true
    }
    # 問い合わせ（差し替えが無ければ開いた接続で）。& で呼ぶと、この関数の $query・$connection が見える
    $ask = {
        param ($sql)
        if ($query) { & $query $sql } else { invokeWindowsSearch $connection $sql }
    }

    $systemRootPath = $systemRoot.TrimEnd("\")
    try {
        $entries = getReflectedSystemIndexEntries $state $systemRootPath $ask
        $folders = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
        $longRoot = toLongPath $systemRootPath
        if ([System.IO.Directory]::Exists($longRoot)) {
            $pattern = "$([System.IO.Path]::GetFileNameWithoutExtension(${systemIndexFileName}))*.txt"
            foreach ($file in [System.IO.Directory]::EnumerateFiles($longRoot, $pattern, [System.IO.SearchOption]::AllDirectories)) {
                $rel = getRelativePath (fromLongPath ([System.IO.Path]::GetDirectoryName($file))) $systemRootPath
                if ($rel) { [void]$folders.Add($rel) }
            }
        }
        foreach ($key in $state.Pending.Keys) {
            [void]$folders.Add([System.IO.Path]::GetDirectoryName($key))
        }
        $contentIndexed = testTsvIndexedByWindowsSearch $indexRoot $connection
    } catch {
        return $null
    } finally {
        if ($own) {
            $connection.Dispose()
        }
    }
    $byIndex = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($rel in $folders) {
        $name = $rel.Split([char[]]"\")[0]
        if (!$byIndex.ContainsKey($name)) {
            $byIndex[$name] = @{ Folders = 0; Waiting = 0 }
        }
        $byIndex[$name].Folders++
    }
    foreach ($rel in $entries.Unreflected) {
        $name = $rel.Split([char[]]"\")[0]
        if ($byIndex.ContainsKey($name)) {
            $byIndex[$name].Waiting++
        }
    }
    return @{ Folders = $folders.Count; Waiting = $entries.Unreflected.Count; ContentIndexed = $contentIndexed; ByIndex = $byIndex }
}

# 検索結果の組み立て・書き出しと、インデックスの有無・件数（検索そのものは content_index_search.ps1）。

function toResultLine {
    # 検索結果1件を "ファイル名<TAB>場所<TAB>種別<TAB>行番号<TAB>該当行" に整形する。場所・種別は場所ごとの表記（describePlace。画面の見出しの要約と同じ）。
    # Excelに貼り付けたとき、該当行の各セルが元の列の順（5列目 = A列）に並ぶようにする
    param (
        [string]$book,
        [string]$location,
        [int]$lineNumber,
        [string]$line
    )

    if ($book -match "\.xls[a-z]?$") {
        # セル内改行を戻す（改行を含むセルは " で囲まれているため、貼り付けても1セルのまま）
        $line = $line.Replace(${cellNewLine}, "`n")
    } else {
        # Word・PowerPointの行（段落、または表の1行をタブ区切りにしたもの）は " で囲まれていない。
        # Excelは " で始まるセルを囲みの " と解釈して後続がずれるため、そのセルだけ " で囲む
        $line = @($line.Split("`t") | ForEach-Object {
            if ($_.StartsWith('"')) { '"' + $_.Replace('"', '""') + '"' } else { $_ }
        }) -join "`t"
    }
    # 場所（シート名）にタブ・改行が入っていると、列・行が分かれてしまうためスペースにする
    # （Excelのシート名はタブ・改行を含められる）
    $described = describePlace $book $location
    $place = [regex]::Replace($described.Place, '[\x00-\x1F]', " ")
    return "${book}`t${place}`t$($described.Kind)`t${lineNumber}`t${line}"
}

function toResultHeader {
    # 検索結果の見出し行 "ファイル名<TAB>場所<TAB>種別<TAB>行<TAB>A<TAB>B…" を返す（列名は columnCount 列分）
    param (
        [int]$columnCount
    )

    $names = New-Object System.Collections.Generic.List[string]
    $names.AddRange([string[]]@("ファイル名", "場所", "種別", "行"))
    for ($i = 1; $i -le $columnCount; $i++) {
        $names.Add((toColumnName $i))
    }
    return ($names -join "`t")
}


# 検索で読んだ本文インデックスのファイルの内容を残しておく量の上限（文字数。1 文字 2 バイトのため約 128MB）
${searchCacheMaxChars} = 64000000

function newTsvTextCache {
    # 検索で読んだ本文インデックスのファイルの内容を、次の検索で使い回すための入れ物を作る（画面が 1 つ持ち、検索のたびに searchContentIndex に渡す）。
    # 2 回目以降の検索ではファイルを開かない。更新日時・サイズが列挙したときと違う本文インデックスのファイル（書き直した等）は読み直す。
    # 並列検索の各スレッドから使うため、中身は ConcurrentDictionary。
    #   Texts: 本文インデックスのファイルの \\?\ 付きのパス → @(更新日時（UTC の Ticks）, サイズ, 内容, 場所の一覧, 最後に使った世代) / Chars: 残している文字数 / MaxChars: 上限
    #   Generation: 今の世代（検索 1 回ごとに trimTsvTextCache が 1 つ進める）
    param (
        [long]$maxChars = ${searchCacheMaxChars}
    )

    return @{
        Texts      = New-Object 'System.Collections.Concurrent.ConcurrentDictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
        Chars      = [long[]]::new(1)
        MaxChars   = $maxChars
        Generation = [long[]]::new(1)
    }
}

# 検索の後、キャッシュがこの割合を超えていたら、空きを作る（次の検索で新しく読んだものが入るように）
${searchCacheKeepRatio} = 0.9

function trimTsvTextCache {
    # 検索 1 回の後に呼ぶ（検索の司令のスレッド）。上限の keepRatio を超えていたら、今の世代で使わなかったものを、
    # 古い世代から追い出す（消した本文インデックスのファイル・検索しなくなったフォルダの分）。今の世代で使ったものは残す
    # （毎回同じ本文インデックスのファイルを順に読むため、使った順だけで追い出すと、上限より大きいインデックスでは何も残らない）。
    # 最後に世代を 1 つ進める。追い出した数を返す
    param (
        $cache,
        [double]$keepRatio = ${searchCacheKeepRatio}
    )

    $removed = 0
    [System.Threading.Monitor]::Enter($cache)
    try {
        $current = $cache.Generation[0]
        $limit = [long]($cache.MaxChars * $keepRatio)
        if ($cache.Chars[0] -gt $limit) {
            $old = @($cache.Texts.GetEnumerator() | Where-Object { $_.Value[4] -lt $current } | Sort-Object { $_.Value[4] })
            foreach ($item in $old) {
                if ($cache.Chars[0] -le $limit) {
                    break
                }
                $entry = $null
                if ($cache.Texts.TryRemove($item.Key, [ref]$entry)) {
                    $cache.Chars[0] -= $entry[2].Length
                    $removed++
                }
            }
        }
        $cache.Generation[0] = $current + 1
    } finally {
        [System.Threading.Monitor]::Exit($cache)
    }
    return $removed
}

function newSearchRequest {
    # 検索の要求 1 つを作る（画面が作り、検索の司令のスレッド（SearchService）が invokeSearchRequest で実行する）。
    # 画面と司令のスレッドの両方から読み書きするため、Synchronized の hashtable にする。
    #   画面が書く: 検索条件・Stop（取り消し）
    #   司令が書く: Queue（ヒット）・Done / Total / IndexTotal / Scanned（進み具合）・Folders・FastUsed / FastAvailable・Truncated / Cancelled / Error・Finished
    #   workDir: 高速検索で使うワークスペース（司令のスレッドは lib.ps1 を読み込んだときのワークスペースを覚えているため、画面から渡す）
    param (
        [string]$word,
        [bool]$simpleMatch,
        $folders,
        [int]$limit,
        [hashtable]$option = @{},
        [bool]$useFast = $false,
        [string]$workDir = $workspace.Dir
    )

    return [hashtable]::Synchronized(@{
        Word = $word; SimpleMatch = $simpleMatch; Folders = $folders; Limit = $limit; WorkDir = $workDir
        CaseSensitive = [bool]$option.CaseSensitive; FileFilter = (newFileKindFilter $option.FileKinds)
        IncludeShapes = ($option.IncludeShapes -ne $false); IncludeComments = ($option.IncludeComments -ne $false)
        UseFast = $useFast; FastUsed = $false; FastAvailable = $null
        Queue = New-Object 'System.Collections.Concurrent.ConcurrentQueue[object]'
        Stop = $false; Finished = $false; Done = 0; Total = -1; IndexTotal = -1; Scanned = 0
        Truncated = $false; Cancelled = $false; Error = $null
    })
}

function invokeSearchRequest {
    # 検索の要求（newSearchRequest）を実行し、ヒットと進み具合を要求に少しずつ入れる。最後に Finished を立てる。
    # 例外は投げずに Error に入れる。始める前に取り消されていたら（次の要求が来た等）、何もせずに Cancelled にする。
    #   pool : 照合のプール（newContentIndexWorkerPool）。$null なら searchContentIndex が必要なときだけ作る
    #   cache: 読んだ本文インデックスのファイルの内容の入れ物（newTsvTextCache）
    param (
        [hashtable]$request,
        $pool = $null,
        $cache = $null
    )

    try {
        if ($request.Stop) {
            $request.Cancelled = $true
            return
        }
        $word = $request.Word
        $folders = $request.Folders
        # 高速検索が使えるなら、Windows Search で検索語を含みうるフォルダを先に絞る（使えなければ $null で、すべてを集める）
        $index = $null
        if ($request.UseFast) {
            $own = [Workspace]::new($request.WorkDir)
            $request.FastAvailable = testWindowsSearch $own.SystemIndexDir
            if ($request.FastAvailable) {
                $index = getFastSearchContentIndexFiles $word $folders -indexRoot $own.IndexDir -systemRoot $own.SystemIndexDir -statePath $own.SystemIndexStateFile `
                    -onProgress { param ($count) $request.Scanned = $count }
            }
        }
        $request.FastUsed = ($null -ne $index)
        if ($null -eq $index) {
            # 途中の件数を画面に伝える（止まって見えないように）
            $index = getContentIndexFiles $folders { param ($count) $request.Scanned = $count }
        }
        $request.Folders = $index.Folders
        $request.Total = $index.ContentIndexFiles.Count
        $request.IndexTotal = $index.ContentIndexFiles.Count
        $result = searchContentIndex $word $index.ContentIndexFiles $request.SimpleMatch $request.Limit -caseSensitive $request.CaseSensitive `
            -fileFilter $request.FileFilter -cache $cache -includeShapes $request.IncludeShapes -includeComments $request.IncludeComments -pool $pool `
            -onProgress {
            param ($done, $total, $newHits)
            foreach ($hit in $newHits) {
                $request.Queue.Enqueue($hit)
            }
            $request.Total = $total
            $request.Done = $done
        } -shouldStop { $request.Stop }
        $request.Total = $result.Total
        $request.Truncated = $result.Truncated
        $request.Cancelled = $result.Cancelled
    } catch {
        $request.Error = $_.Exception.Message
    } finally {
        $request.Finished = $true
    }
}

function testIndexExists {
    # 検索対象インデックスに本文インデックスのファイルが1件でもあるか（最初の1件が見つかった時点で打ち切る）
    param (
        [string[]]$folders = @($workspace.IndexDir)
    )

    foreach ($dir in $folders) {
        if (!(Test-Path -LiteralPath $dir -PathType Container)) {
            continue
        }
        try {
            # 1 件見つけたらやめる。列挙子を閉じずに戻ると content_index の下のフォルダを掴んだまま残り、
            # 続くインポートの上書きで移動できなくなるため testAnyEntry を通す
            if (testAnyEntry ([System.IO.Directory]::EnumerateFiles((toLongPath (Resolve-Path -LiteralPath $dir).ProviderPath), ${contentIndexFilePattern}, [System.IO.SearchOption]::AllDirectories))) {
                return $true
            }
        } catch {
            # アクセスできないフォルダがある場合は、件数を数える方で判定する
            if (@(Get-ChildItem -LiteralPath $dir -Filter ${contentIndexFilePattern} -File -Recurse -ErrorAction SilentlyContinue).Count -gt 0) {
                return $true
            }
        }
    }
    return $false
}

function getIndexSummary {
    # 検索対象インデックスの本文インデックスのファイルの件数と最新の更新日時を返す: @{ Count; LastWrite（無ければ $null）; Missing（存在しないフォルダ） }
    param (
        [string[]]$folders = @($workspace.IndexDir)
    )

    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $summary = @{ Count = 0; LastWrite = $null; Missing = @() }
    foreach ($dir in $folders) {
        if (!(Test-Path -LiteralPath $dir -PathType Container)) {
            $summary.Missing += $dir
            continue
        }
        $longDir = toLongPath (Resolve-Path -LiteralPath $dir).ProviderPath
        # アクセスできないフォルダがあると .NET の列挙は途中で止まるため、そのときは Get-ChildItem で数える（読めるものだけ）
        try {
            $found = [System.IO.DirectoryInfo]::new($longDir).GetFiles(${contentIndexFilePattern}, [System.IO.SearchOption]::AllDirectories)
        } catch {
            $found = @(Get-ChildItem -LiteralPath $longDir -Filter ${contentIndexFilePattern} -File -Recurse -ErrorAction SilentlyContinue)
        }
        foreach ($file in $found) {
            if (!$seen.Add($file.FullName)) {
                continue
            }
            $summary.Count++
            if ($null -eq $summary.LastWrite -or $file.LastWriteTime -gt $summary.LastWrite) {
                $summary.LastWrite = $file.LastWriteTime
            }
        }
    }
    return $summary
}

function toSearchResultLines {
    # 検索結果を検索結果ファイルの形式にし、@{ Header（見出し行）; Lines } を返す（画面のファイル出力・コピーで共通）。
    # Excelに貼り付けたときに元のセル位置が分かるよう、行番号（TSVの行番号 = Excelの行番号）を付け、
    # 見出しには該当行の最大セル数分の列名（A, B, C…）を付ける
    param (
        [object[]]$hits
    )

    $lines = New-Object System.Collections.Generic.List[string]
    $columnCount = 0
    foreach ($hit in $hits) {
        # ファイル名の前に、クロール対象フォルダからの相対フォルダを付ける
        $line = toResultLine $hit.Book $hit.Location $hit.LineNumber $hit.Line
        if ($hit.RelDir) {
            $line = "$($hit.RelDir)\${line}"
        }
        $lines.Add($line)
        $columnCount = [math]::Max($columnCount, (countTsvFields $line) - 4)  # ファイル名・場所・種別・行番号の4列を除く
    }
    return @{ Header = (toResultHeader $columnCount); Lines = $lines }
}

function writeSearchResult {
    # 1ワード分の検索結果を検索結果ファイルに書き出す
    param (
        [System.IO.TextWriter]$writer,
        [string]$word,
        [object[]]$hits
    )

    $result = toSearchResultLines $hits
    $writer.WriteLine("【検索文字列　${word}】 $($result.Lines.Count) 件")
    $writer.WriteLine($result.Header)
    foreach ($line in $result.Lines) {
        $writer.WriteLine($line)
    }
    $writer.WriteLine("")
}

# 検索用の本文インデックスのファイル（content_index_format.ps1）を検索する。
# 本文インデックスのファイルの全文に 1 回照合し、一致しないファイルは飛ばす。一致したら、位置から場所と行を求める。
# 照合のしかた（lines・filter・scan。search_query.ps1 の getRegexScanMode）で、全文への照合と 1 行ずつの照合の結果を同じにする。
# Excel の図形・コメントの行は「セル番地 + タブ + 文字」の形のため、区切りのタブより後から始まる一致だけをヒットにする（セル番地だけの一致を除く）。

function testCellPrefixedHit {
    # セル番地 + 区切りのタブ + 文字 の行で、区切りのタブ（最初のタブ）より後から始まる一致があるか。文字の中のタブは文字として扱う。
    # 開始位置つきの照合なので、後読みは前の文字（区切りのタブ）も見える。区切りのタブが無い行は一致なし
    param (
        [regex]$regex,
        [string]$line
    )

    $tab = $line.IndexOf([char]9)
    return ($tab -ge 0) -and $regex.IsMatch($line, $tab + 1)
}


function searchContentIndexFiles {
    # contentIndexFiles の start から count 件の本文インデックスのファイルを読み、regex に一致する行を PSCustomObject で返す（1 行に複数一致しても 1 件）。
    # max 以上（max+1 件目）が見つかった時点で打ち切る（負は上限なし）。読めないファイルは飛ばす。
    #   include / exclude: 元のファイル名の条件（$null は条件なし） / excludePlace: 除く場所（図形・コメント）
    #   cache: newTsvTextCache。更新日時・大きさが同じなら、前に読んだ内容と場所の一覧を使う
    # 照合が時間切れ（RegexMatchTimeoutException）なら、そのまま呼び出し元へ伝える
    param (
        $contentIndexFiles,
        [int]$start,
        [int]$count,
        [regex]$regex,
        [int]$max,
        [regex]$textRegex = $null,
        [string]$scanMode = "scan",
        $cache = $null,
        [regex]$include = $null,
        [regex]$exclude = $null,
        [regex]$excludePlace = $null
    )

    # 並列検索の別スレッドでも動くよう、コマンドレットは使わない
    $hits = [System.Collections.Generic.List[psobject]]::new()
    $end = [Math]::Min($contentIndexFiles.Count, $start + $count)
    $lf = [char]10
    $mark = [char]0x1E
    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $mode = if ($null -eq $textRegex) { "scan" } else { $scanMode }
    for ($i = $start; $i -lt $end; $i++) {
        $contentIndexFile = $contentIndexFiles[$i]
        $text = $null
        $places = $null
        $cached = $false
        if ($null -ne $cache) {
            $entry = $null
            if ($cache.Texts.TryGetValue($contentIndexFile.Path, [ref]$entry) -and $entry[0] -eq $contentIndexFile.Ticks -and $entry[1] -eq $contentIndexFile.Size) {
                $text = $entry[2]
                $places = $entry[3]
                $cached = $true
                # この検索で使ったことを残す（trimTsvTextCache は、使われていない古いものから追い出す）
                $entry[4] = $cache.Generation[0]
            }
        }
        if ($null -eq $text) {
            try {
                $stream = [System.IO.FileStream]::new($contentIndexFile.Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
                $reader = [System.IO.StreamReader]::new($stream, [System.Text.Encoding]::Unicode, $true)
                try { $text = $reader.ReadToEnd() } finally { $reader.Dispose() }
            } catch [System.IO.IOException] {
                continue
            } catch [System.UnauthorizedAccessException] {
                continue
            }
        }
        # 一致しなければ、場所の一覧も作らずに次へ（場所の一覧は、一致したときか、キャッシュに入れるときだけ作る）。
        # 全文への照合が時間切れなら、このファイルは 1 行ずつ照合する
        $contentIndexMode = $mode
        $matched = $true
        if ($contentIndexMode -ne "scan") {
            try {
                $matched = $textRegex.IsMatch($text)
            } catch [System.Text.RegularExpressions.RegexMatchTimeoutException] {
                $contentIndexMode = "scan"
            }
        }
        if ($null -eq $places -and ($matched -or $null -ne $cache)) {
            $places = readContentIndexPlaces $text
        }
        if ($null -ne $cache -and !$cached) {
            [System.Threading.Monitor]::Enter($cache)
            try {
                $old = $null
                if ($cache.Texts.TryRemove($contentIndexFile.Path, [ref]$old)) {
                    $cache.Chars[0] -= $old[2].Length
                }
                if ($cache.Chars[0] + $text.Length -le $cache.MaxChars) {
                    $cache.Texts[$contentIndexFile.Path] = [object[]]@($contentIndexFile.Ticks, $contentIndexFile.Size, $text, $places, $cache.Generation[0])
                    $cache.Chars[0] += $text.Length
                }
            } finally {
                [System.Threading.Monitor]::Exit($cache)
            }
        }
        if (!$matched) { continue }

        $before = $hits.Count
        $lineMode = $contentIndexMode -eq "lines"
        if ($lineMode) {
            try {
                $length = $text.Length
                $p = 0            # 今の場所（places の番号）
                $number = 0       # 今の場所で、pos までに数えた行の数
                $pos = -1         # 行を数え終えた位置（-1 は場所が変わったので数え直し）
                $lastP = -1       # 直前に判定した場所の番号（isTextBook を場所が変わったときだけ判定し直す）
                $isTextBook = $false
                $m = $textRegex.Match($text)
                while ($m.Success) {
                    $index = $m.Index
                    if ($index -ge $length) { break }
                    $lineStart = if ($index -eq 0) { 0 } else { $text.LastIndexOf($lf, $index - 1) + 1 }
                    $lineEnd = $text.IndexOf($lf, $index)
                    if ($lineEnd -lt 0) { $lineEnd = $length }
                    if ($lineStart -lt $length -and $text[$lineStart] -eq $mark) {
                        # メタ情報の行（ファイル名・場所の名前）の中の一致は捨てる
                        if ($lineEnd -ge $length) { break }
                        $m = $textRegex.Match($text, $lineEnd + 1)
                        continue
                    }
                    while ($p -lt $places.Count -and $places[$p].End -le $lineStart) { $p++; $pos = -1 }
                    if ($p -ge $places.Count) { break }
                    $place = $places[$p]
                    if ($p -ne $lastP) {
                        $isTextBook = ((getContentIndexFileKind $place.Book) -eq "テキスト")
                        $lastP = $p
                    }
                    $skip = ($include -and !$include.IsMatch($place.Book)) -or ($exclude -and $exclude.IsMatch($place.Book)) -or
                        ($excludePlace -and $excludePlace.IsMatch($place.Location))
                    if ($skip) {
                        if ($place.End -ge $length) { break }
                        $m = $textRegex.Match($text, $place.End)
                        continue
                    }
                    if ($pos -lt 0) { $pos = $place.Start; $number = 1 }
                    # 前に数えた位置から行の先頭までの改行を数える（Substring を作らない）
                    while ($pos -lt $lineStart) {
                        $n = $text.IndexOf($lf, $pos, $lineStart - $pos)
                        if ($n -lt 0) { break }
                        $number++
                        $pos = $n + 1
                    }
                    $pos = $lineStart
                    $line = $text.Substring($lineStart, $lineEnd - $lineStart)
                    if ($place.CellPrefixed -and !(testCellPrefixedHit $regex $line)) {
                        # セル番地だけに一致した行はヒットにしない（行番号の数え方は崩さない）
                        if ($lineEnd -ge $length) { break }
                        $m = $textRegex.Match($text, $lineEnd + 1)
                        continue
                    }
                    if ($isTextBook) {
                        $line = truncateHitLine $line ($index - $lineStart)
                    }
                    $hits.Add([pscustomobject]@{
                        Root = $contentIndexFile.Root; RelPath = $contentIndexFile.RelPath; RelDir = $contentIndexFile.RelDir; FileName = $place.Book
                        Book = $place.Book; Location = $place.Location; LineNumber = $number; Line = $line
                    })
                    if ($max -ge 0 -and $hits.Count -gt $max) { return , $hits }
                    if ($lineEnd -ge $length) { break }
                    $m = $textRegex.Match($text, $lineEnd + 1)
                }
                continue
            } catch [System.Text.RegularExpressions.RegexMatchTimeoutException] {
                # 全文への照合が時間切れなら、1 行ずつ照合し直す
                if ($hits.Count -gt $before) { $hits.RemoveRange($before, $hits.Count - $before) }
            }
        }
        # filter・scan（と lines の時間切れ）: 場所ごとに 1 行ずつ照合する
        foreach ($place in $places) {
            if ($include -and !$include.IsMatch($place.Book)) { continue }
            if ($exclude -and $exclude.IsMatch($place.Book)) { continue }
            if ($excludePlace -and $excludePlace.IsMatch($place.Location)) { continue }
            $isTextBook = ((getContentIndexFileKind $place.Book) -eq "テキスト")
            $number = 0
            $pos = $place.Start
            while ($pos -lt $place.End) {
                $n = $text.IndexOf($lf, $pos, $place.End - $pos)
                if ($n -lt 0) { $n = $place.End }
                $number++
                $line = $text.Substring($pos, $n - $pos)
                $pos = $n + 1
                $lineMatch = $regex.Match($line)
                if (!$lineMatch.Success) { continue }
                if ($place.CellPrefixed -and !(testCellPrefixedHit $regex $line)) { continue }
                if ($isTextBook) {
                    $line = truncateHitLine $line $lineMatch.Index
                }
                $hits.Add([pscustomobject]@{
                    Root = $contentIndexFile.Root; RelPath = $contentIndexFile.RelPath; RelDir = $contentIndexFile.RelDir; FileName = $place.Book
                    Book = $place.Book; Location = $place.Location; LineNumber = $number; Line = $line
                })
                if ($max -ge 0 -and $hits.Count -gt $max) { return , $hits }
            }
        }
    }
    return , $hits
}


# 本文インデックスのファイルの検索で、1 つのスレッドにまとめて渡す大きさの目安（バイト）
${contentIndexTaskBytes} = 16MB

# 本文インデックスのファイルの検索の各スレッドで動かすスクリプト。@{ Hits; Timeout } を返す
${contentIndexWorkerScript} = {
    param ($contentIndexFiles, $start, $count, $regex, $max, $textRegex, $scanMode, $cache, $include, $exclude, $excludePlace)
    try {
        $hits = searchContentIndexFiles $contentIndexFiles $start $count $regex $max $textRegex $scanMode $cache $include $exclude $excludePlace
        @{ Hits = $hits; Timeout = $false }
    } catch {
        if ($_.Exception -is [System.Text.RegularExpressions.RegexMatchTimeoutException] -or
            $_.Exception.InnerException -is [System.Text.RegularExpressions.RegexMatchTimeoutException]) {
            @{ Hits = $null; Timeout = $true }
        } else {
            throw
        }
    }
}


function newContentIndexWorkerPool {
    # 本文インデックスのファイルの照合のプール（WorkerPool）を作る。各スレッドには照合に要る関数と値だけを読み込む。
    # 利用者が結果を待つ処理のため、優先度は下げない（docs/design/structure/threads.md「スレッドの一覧」）
    param (
        [int]$workers = (getWorkerCount)
    )

    $state = newWorkerState @("searchContentIndexFiles", "testCellPrefixedHit", "readContentIndexPlaces", "testContentIndexCellPrefixed", "convertContentIndexMetaToPlace", "decodeContentIndexValue", "getContentIndexFileKind", "testTextExtension", "testPdfExtension", "truncateHitLine") `
        @("contentIndexMark", "contentIndexVersion", "contentIndexPlaceKeys", "placeKindShape", "placeKindComment", "placeKindHeaderFooter", "placeKindEmbed", "textExtensions", "pdfExtensions", "hitLineMaxChars", "hitLineBeforeMatchChars")
    return [WorkerPool]::new($workers, $state, $Host, "Normal")
}


function splitContentIndexTasks {
    # 本文インデックスのファイルの並びを、1 つのスレッドに渡す単位（@{ Start; Count }）に分ける（合計がおよそ contentIndexTaskBytes になるまでまとめる）
    param (
        $contentIndexFiles,
        [long]$taskBytes = ${contentIndexTaskBytes}
    )

    $tasks = New-Object System.Collections.Generic.List[hashtable]
    $start = 0
    $bytes = 0L
    for ($i = 0; $i -lt $contentIndexFiles.Count; $i++) {
        $bytes += [long]$contentIndexFiles[$i].Size
        if ($bytes -ge $taskBytes -or $i -eq $contentIndexFiles.Count - 1) {
            $tasks.Add(@{ Start = $start; Count = $i - $start + 1 })
            $start = $i + 1
            $bytes = 0L
        }
    }
    return , $tasks
}


function searchContentIndex {
    # 本文インデックスのファイルをワードで検索し、ヒットした行を返す（画面の検索処理）。
    #   contentIndexFiles        : findContentIndexFiles・getContentIndexFiles の結果
    #   simpleMatch  : $true なら文字どおりに検索する。$false なら正規表現として検索し、正規表現として不正なら文字どおりに検索する
    #   limit        : 件数の上限（0 は上限なし）。超えたら打ち切る
    #   shouldStop   : $true を返すと中止する
    #   caseSensitive: 英字の大文字・小文字を区別する（newSearchRegex）
    #   fileFilter   : 対象ファイル（newFileFilter）。元のファイル名が一致しないものは検索しない
    #   workerCount  : 並列に検索するスレッドの数（0 は CPU のコア数から決める。最大 4）
    #   cache        : 読んだ本文インデックスのファイルの内容を次の検索で使い回す入れ物（newTsvTextCache。$null は使い回さない）
    #   includeShapes / includeComments: 図形・コメントの場所（"<シート名>[図形]" 等）も検索する（newPlaceExclude）
    #   taskBytes    : 1 つのスレッドにまとめて渡す大きさの目安（バイト）
    #   onProgress   : 1 つの作業を照合するたびに呼ぶ { param($done, $total, $newHits) }（done・total は本文インデックスのファイルの数）
    #   pool         : 照合に使うプール（newContentIndexWorkerPool。検索の司令が使い回す）。$null なら、並列にするときだけ作って最後に閉じる
    # @{ Hits; SimpleMatch（実際に文字どおり検索したか）; Total（本文インデックスのファイルの数）; Truncated; Cancelled } を返す。
    # Hits の各要素は PSCustomObject（Root; RelPath（本文インデックスのファイル）; RelDir; FileName; Book; Location; LineNumber; Line）
    param (
        [string]$word,
        $contentIndexFiles,
        [bool]$simpleMatch = $false,
        [int]$limit = 0,
        [scriptblock]$shouldStop = $null,
        [bool]$caseSensitive = $false,
        [string]$fileFilter = "",
        [int]$workerCount = 0,
        $cache = $null,
        [bool]$includeShapes = $true,
        [bool]$includeComments = $true,
        [long]$taskBytes = ${contentIndexTaskBytes},
        [scriptblock]$onProgress = $null,
        $pool = $null
    )

    $search = newSearchRegex $word $simpleMatch $caseSensitive
    $filter = newFileFilter $fileFilter
    $excludePlace = newPlaceExclude $includeShapes $includeComments
    $hits = New-Object System.Collections.Generic.List[psobject]
    $result = @{ Hits = $hits; SimpleMatch = $search.SimpleMatch; Total = $contentIndexFiles.Count; Truncated = $false; Cancelled = $false }
    $timeoutMessage = "正規表現の照合に時間がかかりすぎるため、検索を中止しました。正規表現を見直してください。"
    $tasks = splitContentIndexTasks $contentIndexFiles $taskBytes
    $workers = if ($pool) { $pool.Size } elseif ($workerCount -gt 0) { $workerCount } else { getWorkerCount }
    if ($tasks.Count -lt 2) { $workers = 1 }

    $ownPool = $null
    $pending = New-Object System.Collections.Generic.Queue[hashtable]
    try {
        if ($workers -le 1) {
            $pool = $null
        } elseif ($null -eq $pool) {
            $ownPool = newContentIndexWorkerPool $workers
            $pool = $ownPool
        }
        $next = 0
        while ($next -lt $tasks.Count -or $pending.Count -gt 0) {
            if ($shouldStop -and (& $shouldStop)) {
                $result.Cancelled = $true
                break
            }
            if ($pool) {
                while ($pending.Count -lt $workers * 2 -and $next -lt $tasks.Count) {
                    $max = if ($limit -gt 0) { $limit - $hits.Count } else { -1 }
                    $task = $tasks[$next]
                    $job = $pool.Submit(${contentIndexWorkerScript}.ToString(), @($contentIndexFiles, $task.Start, $task.Count, $search.Regex, $max, $search.TextRegex,
                            $search.ScanMode, $cache, $filter.Include, $filter.Exclude, $excludePlace))
                    $job.Done = $task.Start + $task.Count
                    $pending.Enqueue($job)
                    $next++
                }
                $output = $pool.Receive($pending.Dequeue())
                if ($output[0].Timeout) { throw $timeoutMessage }
                $newHits = $output[0].Hits
                $done = $job.Done
            } else {
                $task = $tasks[$next]
                $next++
                $done = $task.Start + $task.Count
                $max = if ($limit -gt 0) { $limit - $hits.Count } else { -1 }
                try {
                    $newHits = searchContentIndexFiles $contentIndexFiles $task.Start $task.Count $search.Regex $max $search.TextRegex $search.ScanMode $cache $filter.Include $filter.Exclude $excludePlace
                } catch [System.Text.RegularExpressions.RegexMatchTimeoutException] {
                    throw $timeoutMessage
                }
            }
            $max = if ($limit -gt 0) { $limit - $hits.Count } else { -1 }
            if ($max -ge 0 -and $newHits.Count -gt $max) {
                $newHits.RemoveRange($max, $newHits.Count - $max)
                $result.Truncated = $true
            }
            $hits.AddRange($newHits)
            if ($onProgress) {
                & $onProgress $done $contentIndexFiles.Count $newHits
            }
            if ($result.Truncated) { break }
        }
    } finally {
        foreach ($job in $pending) {
            $pool.Cancel($job)
        }
        if ($ownPool) { $ownPool.Close() }
    }
    return $result
}


function getContentIndexFiles {
    # 検索対象の本文インデックスのファイルを集め、@{ Folders; ContentIndexFiles } を返す。
    #   folders: 検索対象インデックスのフォルダ（文字列。フォルダ以下すべて）、または
    #            @{ Root（インデックスのフォルダ）; RelPath（その中のフォルダ。空は Root 自身）; Recurse（$false は直下のファイルだけ） }
    #   Folders: フォルダごとの @{ Path; Root（フルパス）; Exists; Count }
    #   ContentIndexFiles  : findContentIndexFiles の結果をつないだもの（入れ子のフォルダを選んでも重複しない）
    #   onProgress: 数えた件数を知らせる { param($count) }
    param (
        [object[]]$folders = @($workspace.IndexDir),
        [scriptblock]$onProgress = $null
    )

    $folderInfo = New-Object System.Collections.Generic.List[object]
    $contentIndexFiles = New-Object System.Collections.Generic.List[hashtable]
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($target in $folders) {
        if ($target -is [string]) {
            $target = @{ Root = $target; RelPath = ""; Recurse = $true }
        }
        $relPath = ([string]$target.RelPath).Trim("\")
        $dir = if ($relPath) { "$(([string]$target.Root).TrimEnd('\'))\${relPath}" } else { [string]$target.Root }
        if (!(Test-Path -LiteralPath $target.Root -PathType Container) -or ![System.IO.Directory]::Exists((toLongPath $dir))) {
            $folderInfo.Add(@{ Path = $dir; Root = ""; Exists = $false; Count = 0 })
            continue
        }
        $root = (Resolve-Path -LiteralPath $target.Root).ProviderPath.TrimEnd("\")
        $found = findContentIndexFiles $root $relPath ([bool]$target.Recurse)
        $folderInfo.Add(@{ Path = $dir; Root = $root; Exists = $true; Count = $found.Count })
        foreach ($contentIndexFile in $found) {
            if ($seen.Add($contentIndexFile.Path)) { $contentIndexFiles.Add($contentIndexFile) }
        }
        if ($onProgress) { & $onProgress $contentIndexFiles.Count }
    }
    # フォルダの順、フォルダの中は名前の順（findContentIndexFiles と同じ）。検索対象を複数選んだときも順が崩れないよう並べ直す
    $sorted = [hashtable[]]@($contentIndexFiles | Sort-Object @{ Expression = { $_.Root } }, @{ Expression = { $_.RelDir } }, @{ Expression = { [System.IO.Path]::GetFileName($_.RelPath) } })
    return @{ Folders = $folderInfo.ToArray(); ContentIndexFiles = $sorted }
}
# 検索の司令のスレッド（SearchService）。画面を開いている間 1 つだけ動かし、検索の要求（newSearchRequest）を順に実行する。
# lib.ps1 の読み込みと照合のプールの用意は、スレッドを始めたときに 1 回だけ行う（検索のたびに行わない）。
# 設計は docs/design/structure/threads.md「スレッドの一覧」「寿命」。
#
# SearchService は画面のスレッドだけから呼ぶ（PowerShell 5.1 のクラスのメソッドは、定義したランスペースで動くため）。
# スレッドをまたいで使う要求は、Synchronized の hashtable（newSearchRequest）にする。

# 司令のスレッドで動かすスクリプト。要求の列が閉じられる（Close）まで、要求を 1 つずつ実行する。
# lib の部品（Prelude）は SearchService.Start が、この param ブロックのあとにつなぐ（joinWorkerScript）
${searchServiceScript} = {
    param ($requests, $cache, $workers)
    # 読み込めなければスレッドを終える（画面は IsRunning・GetFailure で知り、次の要求で作り直す）
    $ErrorActionPreference = "Stop"
    initWorkspace
    $ErrorActionPreference = "Continue"
    $pool = if ($workers -gt 1) { newContentIndexWorkerPool $workers } else { $null }
    try {
        foreach ($request in $requests.GetConsumingEnumerable()) {
            invokeSearchRequest $request $pool $cache
            if ($cache) {
                [void](trimTsvTextCache $cache)
            }
        }
    } finally {
        if ($pool) {
            $pool.Close()
        }
    }
}

# 閉じるときに、実行中の検索が止まるのを待つ時間（ミリ秒）。過ぎたらスレッドを止める
${searchServiceCloseMilliseconds} = 5000

class SearchService {
    # 照合のプールのスレッドの数
    [int]$Workers
    hidden [string]$Script
    hidden [hashtable]$LibLoad
    hidden $Cache
    hidden [int]$CloseMilliseconds
    hidden [System.Collections.Concurrent.BlockingCollection[hashtable]]$Requests
    hidden [System.Management.Automation.Runspaces.Runspace]$Runspace
    hidden [powershell]$PowerShell
    hidden [System.IAsyncResult]$Handle
    # いま実行している（最後に渡した）要求
    hidden [hashtable]$Current

    SearchService([string]$script, [hashtable]$libLoad, $cache, [int]$workers, [int]$closeMilliseconds) {
        $this.Script = $script
        $this.LibLoad = $libLoad
        $this.Cache = $cache
        $this.Workers = [Math]::Max(1, $workers)
        $this.CloseMilliseconds = $closeMilliseconds
        $this.Start()
    }

    hidden [void] Start() {
        $this.Requests = New-Object 'System.Collections.Concurrent.BlockingCollection[hashtable]'
        $rs = [runspacefactory]::CreateRunspace($this.LibLoad.State)
        $rs.Open()
        $ps = [powershell]::Create()
        $ps.Runspace = $rs
        $joined = if ($this.LibLoad.Prelude) { joinWorkerScript $this.LibLoad.Prelude $this.Script } else { $this.Script }
        [void]$ps.AddScript($joined).AddArgument($this.Requests).AddArgument($this.Cache).AddArgument($this.Workers)
        $this.Runspace = $rs
        $this.PowerShell = $ps
        $this.Handle = $ps.BeginInvoke()
    }

    [bool] IsRunning() {
        # 司令のスレッドが動いているか（lib.ps1 を読み込めなかった等で止まっていれば $false）
        return $null -ne $this.PowerShell -and !$this.Handle.IsCompleted
    }

    [string] GetFailure() {
        # 司令のスレッドが止まっていれば、その理由（無ければ空）
        if ($null -eq $this.PowerShell -or !$this.Handle.IsCompleted) {
            return ""
        }
        if ($this.PowerShell.Streams.Error.Count -gt 0) {
            return $this.PowerShell.Streams.Error[0].ToString()
        }
        return "検索のスレッドが止まりました。"
    }

    [hashtable] Request([hashtable]$request) {
        # 要求を渡す。実行中の要求は取り消す（次の要求が先に始まる）。司令のスレッドが止まっていれば作り直す
        $this.Cancel()
        if (!$this.IsRunning()) {
            $this.Shutdown()
            $this.Start()
        }
        $this.Current = $request
        $this.Requests.Add($request)
        return $request
    }

    [void] Cancel() {
        # 実行中の要求を取り消す（照合の作業の切れ目で止まる）
        if ($this.Current) {
            $this.Current.Stop = $true
        }
    }

    [void] Close() {
        # 検索を取り消し、司令のスレッドと照合のプールを片づける。何度呼んでもよい
        $this.Cancel()
        $this.Shutdown()
        $this.Current = $null
    }

    hidden [void] Shutdown() {
        if ($this.Requests) {
            $this.Requests.CompleteAdding()
        }
        if ($this.PowerShell) {
            if (!$this.Handle.AsyncWaitHandle.WaitOne($this.CloseMilliseconds)) {
                try {
                    $this.PowerShell.Stop()
                } catch {
                }
            }
            $this.PowerShell.Dispose()
            $this.PowerShell = $null
        }
        if ($this.Runspace) {
            $this.Runspace.Dispose()
            $this.Runspace = $null
        }
        if ($this.Requests) {
            $this.Requests.Dispose()
            $this.Requests = $null
        }
    }
}

function newSearchService {
    # 検索の司令のスレッドを始める（画面を開いたときに 1 回）。閉じるときは Close を呼ぶ
    param (
        $cache = $null,
        [int]$workers = (getWorkerCount)
    )

    $libLoad = getPartLoad lib
    return [SearchService]::new(${searchServiceScript}.ToString(), $libLoad, $cache, $workers, ${searchServiceCloseMilliseconds})
}

# 検索結果から元のファイルの場所を求める（source_folder.txt の読み書きを含む）。

function writeSourceFolderFile {
    # 各インデックスのフォルダに、インデックス名とクロール対象フォルダの対応（source_folder.txt）を書き出す。
    # 1行目は説明、2行目は "インデックス名<TAB>クロール対象フォルダ"。
    # インデックス1件につき1ファイルのため、<インデックス名> のフォルダだけを別の PC・場所へコピーしても
    # 元のファイルの場所が分かる（work\index ごとコピーした場合は readSourceFolderFile が各フォルダを読む）
    param (
        [object[]]$folders,  # assignIndexNames の結果（@{ Path; Name }）
        [string]$dir = $workspace.IndexDir
    )

    $header = "# 検索結果から元のファイルを開くときに使う、インデックス名とクロール対象フォルダの対応です（インデックス作成のたびに作り直します）"
    $items = @($folders | Where-Object { $_ -and $_.Name })
    foreach ($folder in $items) {
        # インデックスのフォルダがまだ無い（1件も取り込んでいない）場合は作らない
        $indexPath = Join-Path $dir $folder.Name
        if (Test-Path -LiteralPath (toLongPath $indexPath) -PathType Container) {
            $sourceFilePath = Join-Path $indexPath ${sourceFolderFileName}
            writeListFile $sourceFilePath @($header, "$($folder.Name)`t$($folder.Path)")
            # 画面（インデックス一覧の保存）からも呼ばれるため、書いたファイルだけに付ける（件数が多いため失敗してもログに出さない）
            [void](setNotContentIndexed $sourceFilePath)
        }
    }
}

function readSourceFolderFile {
    # インデックスのフォルダ（dir）直下の source_folder.txt を読み、インデックス名 → クロール対象フォルダ を返す
    # （大文字・小文字を区別しない）。ファイルが無ければ空。
    # ファイルは各インデックスのフォルダ（work\index\<インデックス名>）に置くため、dir にはそのフォルダを渡す。
    # dir の下を探し回らないのは、インデックスのフォルダの下が元のファイル1つにつき1フォルダ（数万個）になるため
    param (
        [string]$dir
    )

    $map = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($line in @(readListFile (Join-Path $dir ${sourceFolderFileName}))) {
        $fields = $line.Split("`t")
        if ($fields.Count -eq 2 -and $fields[0] -ne "" -and $fields[1] -ne "") {
            $map[$fields[0]] = $fields[1]
        }
    }
    return , $map
}

function getSourceFolderMap {
    # インデックスのフォルダ（dir）の インデックス名 → 元のフォルダ（今そのフォルダが置かれている場所）を返す。
    # 次の順に読み、後のもので上書きする（後のものが優先）:
    #   1. dir 直下の source_folder.txt … インデックスを作ったときの場所。インデックスをコピーしても付いてくる
    #   2. 既定のインデックス（work\index）なら取り込み一覧の記録
    #   3. 設定のインデックス名に対する場所（targetFolders・indexSources）… 利用者が指定した「今の場所」のため最も優先する
    param (
        [string]$dir,
        [string]$statusPath = $workspace.StatusFile,
        [string]$settingsPath = ${settingsFile},
        [string]$indexDir = $workspace.IndexDir
    )

    $map = readSourceFolderFile $dir
    if ((Test-Path -LiteralPath $indexDir -PathType Container) -and
        (testSameFolder $dir (Resolve-Path -LiteralPath $indexDir).ProviderPath)) {
        foreach ($entry in (getIndexNameMap $statusPath).GetEnumerator()) {
            $map[$entry.Key] = $entry.Value
        }
    }
    foreach ($folder in @(getTargetFolders $settingsPath | Where-Object { $_.Name })) {
        $map[$folder.Name] = $folder.Path
    }
    foreach ($source in @(readIndexSources $settingsPath)) {
        $map[$source.Name] = $source.Path
    }
    return , $map
}

function joinSourcePath {
    # フォルダ・相対フォルダ（空でも可）・ファイル名をつなぐ（ドライブ直下 "D:\" でも \ が重ならないようにする）
    param (
        [string]$folder,
        [string]$rest,
        [string]$name = ""
    )

    $path = $folder.TrimEnd("\")
    foreach ($part in @($rest, $name)) {
        if ($part) {
            $path += "\$part"
        }
    }
    return $path
}

function findSourceLocationInMaps {
    # 検索結果の元のファイルの場所を、キャッシュ（maps）だけで求める。ファイルは読まない。
    # 返すもの: @{ Resolved; Location; Pending }
    #   Resolved: 場所が決まったか。$false なら、Pending のフォルダの対応（getSourceFolderMap）を maps に足してから、もう一度呼ぶ
    #   Location: @{ Name（インデックス名）; Folder（元のフォルダ）; Rest（その下の相対フォルダ）; Known }。元のフォルダが分からなければ Known = $false・Folder = ""
    #             （Name は返すため、フォルダを選んでもらえば設定に記録できる）
    # インデックスのフォルダ（Root）の下は "インデックス名\相対フォルダ" のため、インデックス名から元のフォルダを引く。
    # 検索対象にインデックス名のフォルダ（…\index\<インデックス名>）を直接指定した場合は、親フォルダの記録を使う。
    param (
        $hit,
        [hashtable]$maps = @{}
    )

    $root = ([string]$hit.Root).TrimEnd("\")
    $relDir = [string]$hit.RelDir
    $candidates = New-Object System.Collections.Generic.List[object]
    if ($relDir) {
        $parts = splitIndexRelPath $relDir
        $candidates.Add(@{ Dir = $root; Name = $parts.Name; Rest = $parts.Rest })
        # インデックスのフォルダの中の記録（<インデックス名> のフォルダだけを別の場所へコピーした場合）
        $candidates.Add(@{ Dir = (Join-Path $root $parts.Name); Name = $parts.Name; Rest = $parts.Rest })
    }
    # 検索対象にインデックス名のフォルダ（…\index\<インデックス名>）を直接指定した場合。
    # そのフォルダ自身の記録を先に見て、無ければ親フォルダの記録を見る
    $leaf = Split-Path $root -Leaf
    $candidates.Add(@{ Dir = $root; Name = $leaf; Rest = $relDir })
    $parent = Split-Path $root -Parent
    if ($parent) {
        $candidates.Add(@{ Dir = $parent; Name = $leaf; Rest = $relDir })
    }

    foreach ($candidate in $candidates) {
        if (!$maps.ContainsKey($candidate.Dir)) {
            return @{ Resolved = $false; Location = $null; Pending = $candidate.Dir }
        }
        $map = $maps[$candidate.Dir]
        if ($map.ContainsKey($candidate.Name)) {
            return @{ Resolved = $true; Location = @{ Name = $candidate.Name; Folder = $map[$candidate.Name]; Rest = $candidate.Rest; Known = $true }; Pending = "" }
        }
    }

    # 分からない場合も、インデックス名と、その下の相対フォルダは分かる（検索対象にインデックス名のフォルダを直接指定した場合は Rest がすべて）
    if ($candidates.Count -gt 0) {
        $unknown = @{ Name = $candidates[0].Name; Folder = ""; Rest = $candidates[0].Rest; Known = $false }
    } else {
        $unknown = @{ Name = (Split-Path $root -Leaf); Folder = ""; Rest = ""; Known = $false }
    }
    return @{ Resolved = $true; Location = $unknown; Pending = "" }
}

function getSourceLocation {
    # 検索結果の元のファイルの場所を @{ Name; Folder; Rest; Known } で返す（findSourceLocationInMaps と同じ）。
    # キャッシュに無いフォルダの対応は、読んで maps に足す
    #   maps: フォルダ → getSourceFolderMap の結果 のキャッシュ（読んだ結果を追加する）
    param (
        $hit,
        [hashtable]$maps = @{}
    )

    while ($true) {
        $found = findSourceLocationInMaps $hit $maps
        if ($found.Resolved) {
            return $found.Location
        }
        $maps[$found.Pending] = getSourceFolderMap $found.Pending
    }
}

function readSourceLocation {
    # getSourceLocation の、裏のスレッドから呼ぶ版。$workspace・設定の場所に頼らず、場所を引数で受ける。
    # maps は書き換えず、複製に足して返す: @{ Location; Maps }（呼んだ側が Maps をキャッシュに足す）
    param (
        $hit,
        [hashtable]$maps,
        [string]$statusPath,
        [string]$settingsPath,
        [string]$indexDir
    )

    $copy = $maps.Clone()
    while ($true) {
        $found = findSourceLocationInMaps $hit $copy
        if ($found.Resolved) {
            return @{ Location = $found.Location; Maps = $copy }
        }
        $copy[$found.Pending] = getSourceFolderMap $found.Pending $statusPath $settingsPath $indexDir
    }
}

function findMovedSource {
    # 元のファイルが見つからないとき、選んでもらったフォルダ（picked）の中から探す。
    # picked は元のフォルダ（インデックスのルート）に当たるフォルダでも、その下のどのフォルダ（ファイルのあるフォルダなど）に当たるフォルダでもよい。
    # 上の階層に当たるとみなす方から順に試し、見つかれば @{ Path（見つかったファイル）; Root（元のフォルダに当たるフォルダ。遡れなければ ""） }、
    # 見つからなければ $null を返す。Root を設定に記録すれば（setIndexSourceFolder）、同じインデックスのほかのファイルも開ける
    param (
        [string]$picked,
        [string]$rest,
        [string]$book
    )

    $picked = normalizeFolderPath $picked
    $segments = [string[]]@($rest.Split([char[]]@("\"), [System.StringSplitOptions]::RemoveEmptyEntries))
    for ($skip = 0; $skip -le $segments.Count; $skip++) {
        # 先頭の skip 個のフォルダは picked より上、残りは picked の下にあるとみなす
        $below = [string]::Join("\", $segments, $skip, $segments.Count - $skip)
        $candidate = joinSourcePath $picked $below $book
        if (Test-Path -LiteralPath (toLongPath $candidate) -PathType Leaf) {
            # 選んだフォルダは「元のフォルダ＋先頭 skip 個のフォルダ」に当たるため、skip 個上が元のフォルダに当たる
            $root = $picked
            for ($i = 0; $i -lt $skip -and $root; $i++) {
                $root = Split-Path $root -Parent
            }
            return @{ Path = $candidate; Root = [string]$root }
        }
    }
    return $null
}

function findSourceFileState {
    # 元のファイルを確かめる（getPathState を使う。Test-Path のまま移さない。届かない共有では例外を出さずに
    # $false を返すことがあり、「見つからない」と区別できないため）。ネットワークのパスなら裏のスレッドから呼ぶ想定。
    #   location: getSourceLocation の結果（Folder・Rest・Name を使う。Known は呼ぶ側で見て、$false ならこの関数を呼ばない）
    #   book: 元のファイル名
    #   drives: ドライブの割り当て（テストで差し替える・裏のスレッドでは省いてその場で照会させる）。
    #           ローカルのパスには別名が無いため、ローカルのときはここまで来ない（getDriveTargets を呼ばない）
    # 返すもの: @{ State（Found・Missing・Unreachable・Other）; Path; Alias; Initial; Message }
    #   State=Found: Path に見つかった場所（別名で見つかったときは Alias にその新しい元のフォルダ）
    #   State=Missing: Initial にフォルダ選択の開始フォルダ（無ければ空）
    #   State=Unreachable・Other: Message に例外の文面（接続できない・その他は、上のフォルダも別名も調べない）
    param (
        $location,
        [string]$book,
        $drives = $null
    )

    $path = joinSourcePath $location.Folder $location.Rest $book
    $state = getPathState $path
    if ($state.State -eq ${pathStateFound}) {
        return @{ State = ${pathStateFound}; Path = $path }
    }
    if ($state.State -ne ${pathStateMissing}) {
        return @{ State = $state.State; Message = $state.Message }
    }
    if (testNetworkPath $location.Folder) {
        if ($null -eq $drives) {
            $drives = getDriveTargets
        }
        foreach ($alias in @(getFolderPathAliases $location.Folder $drives | Select-Object -Skip 1)) {
            $candidate = joinSourcePath $alias $location.Rest $book
            if ((getPathState $candidate).State -eq ${pathStateFound}) {
                return @{ State = ${pathStateFound}; Path = $candidate; Alias = $alias }
            }
        }
    }
    return @{ State = ${pathStateMissing}; Initial = (getExistingAncestorFolder $path) }
}

function resolveSourcePath {
    # 検索結果の元のファイルのパスを返す（ファイルがあるかは確かめない）。元のフォルダが分からなければ $null
    #   maps: getSourceLocation のキャッシュ
    param (
        $hit,
        [hashtable]$maps = @{}
    )

    $location = getSourceLocation $hit $maps
    if (!$location.Known) {
        return $null
    }
    return (joinSourcePath $location.Folder $location.Rest $hit.Book)
}

function getConfirmedSourceNames {
    # 利用者が元のフォルダを決めている（確かめ済みの）インデックス名を返す: @{ Confirmed; Crawled }
    #   Confirmed: 設定の targetFolders と indexSources の名前（元のフォルダの記録が設定にあるもの）
    #   Crawled  : そのうち targetFolders の名前（このワークスペースで自分が作ったインデックス）
    # この外のインデックス（content_index\ に手でコピーしたもの）の元のフォルダは、source_folder.txt を書いた人が決めたもの。
    # 設定は小さいローカルのファイルのため、呼ぶたびに読む（キャッシュしない）
    param (
        [string]$settingsPath = ${settingsFile}
    )

    $crawled = @(getTargetFolders $settingsPath | Where-Object { $_.Name } | ForEach-Object { [string]$_.Name })
    $confirmed = @($crawled) + @(readIndexSources $settingsPath | ForEach-Object { [string]$_.Name })
    return @{ Confirmed = [string[]]$confirmed; Crawled = [string[]]$crawled }
}

# インデックスのエクスポート・インポートの判断（目録の確かめ・zip のエントリー名の安全性・名前の決め方）。
# 画面に触らず、ファイルにも触らない（判断層）。

# 目録（tebunko-index.json）の形式
${indexArchiveFormat}            = "tebunko-index"
${indexArchiveFormatVersion}     = 1  # この版が読める形式の版（本文インデックスのファイルの形・zip の中の配置・目録・取り込み一覧の列を変えたら上げる）
${indexArchiveManifestFileName}  = "tebunko-index.json"
${indexArchiveStatusEntryName}   = "ingest_status.tsv"
${indexArchiveMaxManifestBytes}  = 64MB   # 目録（tebunko-index.json）自体の大きさの上限（zip bomb 対策）
${indexArchiveFreeSpaceMargin}   = 1GB    # インポートに求める空き容量の余裕（目録の合計 + この量）

# 同じ名前のインデックスがあったときの扱い（importIndex・getImportIndexName に渡す）
${importCollisionRename}    = "Rename"
${importCollisionOverwrite} = "Overwrite"
${importCollisionCancel}    = "Cancel"


function testPathSegments {
    # 区切り文字で分けたパスの各区切り（segments）が、ファイル名として安全に使えるかを調べ、
    # 使えない理由を返す（使えれば空文字列）。zip のエントリー名（/ 区切り）・取り込み一覧の相対パス（\ 区切り）の
    # どちらからも呼べる、区切り文字に依らない共通の確かめ
    param (
        [string[]]$segments
    )

    foreach ($segment in $segments) {
        if ($segment -eq "" -or $segment -eq "." -or $segment -eq "..") {
            return "使えない区切り（空・.・..）が含まれています。"
        }
        if ($segment.Length -gt ${maxFileNameLength}) {
            return "1 つの区切りが長すぎます（${maxFileNameLength} 文字まで）。"
        }
        if (@([System.IO.Path]::GetInvalidFileNameChars() | Where-Object { $segment.IndexOf($_) -ge 0 }).Count -gt 0) {
            return "使えない文字が含まれています。"
        }
        if ($segment.EndsWith(".") -or $segment.EndsWith(" ")) {
            return "区切りの最後に . や空白は使えません。"
        }
        if (${reservedFileNames} -contains $segment.Split(".")[0].ToUpperInvariant()) {
            return "Windows で使えない名前（$segment）が含まれています。"
        }
    }
    return ""
}


function testIndexArchiveEntryPath {
    # zip のエントリー名（/ 区切り）が、展開先のパスとして安全かを調べ、使えない理由を返す（使えれば空文字列）。
    # \ 区切り・絶対パス（/ 始まり・ドライブ文字・UNC）は、どれも展開先のパスの外に出るおそれがあるため受け付けない（zip slip 対策）
    param (
        [string]$path
    )

    if ($path -eq "") {
        return "エントリーの名前が空です。"
    }
    if ($path.IndexOf("\") -ge 0) {
        return "エントリーの名前に \ が含まれています（/ 区切りにしてください）: ${path}"
    }
    if ($path.StartsWith("/")) {
        return "エントリーの名前が / で始まっています: ${path}"
    }
    if ($path -match "^[A-Za-z]:") {
        return "エントリーの名前がドライブ文字で始まっています: ${path}"
    }
    $reason = testPathSegments ($path.Split("/"))
    if ($reason) {
        return "エントリー「${path}」の名前が使えません（${reason}）"
    }
    return ""
}


function testIndexArchiveEntryLocation {
    # zip のエントリー名（testIndexArchiveEntryPath を通ったもの）が、持ち出すファイルの置き場所として
    # 許されているか（ingest_status.tsv、または content_index/ の下の本文インデックスのファイルの名前の型）を返す
    param (
        [string]$path
    )

    if ($path -ceq ${indexArchiveStatusEntryName}) {
        return $true
    }
    if (!$path.StartsWith("content_index/", [System.StringComparison]::Ordinal)) {
        return $false
    }
    $name = $path.Substring("content_index/".Length)
    if ($name -eq "") {
        return $false
    }
    $lastSlash = $name.LastIndexOf("/")
    $fileName = if ($lastSlash -ge 0) { $name.Substring($lastSlash + 1) } else { $name }
    return ($null -ne (readContentIndexFileName $fileName))
}


function getManifestSourceFolder {
    # 目録の sourceFolder を返す。絶対パス・UNC でない、または制御文字を含むときは空（呼ぶ側に指定させる）
    param (
        $manifest
    )

    $folder = [string]$manifest.sourceFolder
    if ($folder -eq "") {
        return ""
    }
    if ($folder.IndexOfAny([char[]]@(0..31)) -ge 0) {
        return ""
    }
    if ($folder -notmatch "^[A-Za-z]:\\" -and !$folder.StartsWith("\\")) {
        return ""
    }
    return $folder
}


function testIndexArchiveManifest {
    # 目録（ConvertFrom-Json の結果。読めなければ $null）と、zip の中の全エントリー名（目録自身を含む）・
    # 目録エントリーの展開後の大きさから、この zip をインポートしてよいかを調べ、使えない理由を返す（使えれば空文字列）。
    # 1 つでも受け付けない点があればインポート全体を止めるため、最初に見つかった理由だけを返す
    param (
        $manifest,
        [string[]]$entryNames,
        [long]$manifestBytes
    )

    if ($manifestBytes -gt ${indexArchiveMaxManifestBytes}) {
        return "目録（${indexArchiveManifestFileName}）が大きすぎます。"
    }
    if ($null -eq $manifest) {
        return "tebunko のインデックスの zip ではない、または壊れています（目録を読めません）。"
    }
    if ([string]$manifest.format -ne ${indexArchiveFormat}) {
        return "tebunko のインデックスの zip ではない、または壊れています（形式が違います）。"
    }
    $version = 0
    if (-not [int]::TryParse([string]$manifest.formatVersion, [ref]$version) -or $version -lt 1) {
        return "tebunko のインデックスの zip ではない、または壊れています（形式の版が読めません）。"
    }
    if ($version -gt ${indexArchiveFormatVersion}) {
        return "新しい版の tebunko で作られたインデックスのため、この版では読み込めません。"
    }

    $nameReason = testIndexName ([string]$manifest.indexName) @()
    if ($nameReason) {
        return "目録のインデックス名が使えません（${nameReason}）"
    }

    # zip の中に同じ名前のエントリーが 2 つあれば止める（ZipArchive は許すため、ここで数える）
    $seenEntries = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($entryName in $entryNames) {
        if (!$seenEntries.Add($entryName)) {
            return "zip の中に同じ名前のエントリーが 2 つあります: ${entryName}"
        }
    }

    $fileMap = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($file in @($manifest.files | Where-Object { $_ })) {
        $path = [string]$file.path
        $reason = testIndexArchiveEntryPath $path
        if ($reason) {
            return $reason
        }
        if (!(testIndexArchiveEntryLocation $path)) {
            return "目録に、許されない場所のエントリーがあります: ${path}"
        }
        if ($fileMap.ContainsKey($path)) {
            return "目録に同じパスが 2 つあります: ${path}"
        }
        $size = [long]0
        if (-not [long]::TryParse([string]$file.size, [ref]$size) -or $size -lt 0) {
            return "目録のファイルの大きさが読めません: ${path}"
        }
        if ([string]$file.sha256 -eq "") {
            return "目録のファイルの SHA-256 がありません: ${path}"
        }
        $fileMap[$path] = $file
    }
    if (!$fileMap.ContainsKey(${indexArchiveStatusEntryName})) {
        return "目録に ${indexArchiveStatusEntryName} がありません。"
    }

    # zip の中のエントリー（目録自身を除く）が、すべて目録にあるか。目録にあるのに zip に無いものが無いか
    $zipEntries = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($entryName in $entryNames) {
        if ($entryName -ieq ${indexArchiveManifestFileName}) {
            continue
        }
        [void]$zipEntries.Add($entryName)
        if (!$fileMap.ContainsKey($entryName)) {
            return "目録に無いエントリーが zip にあります: ${entryName}"
        }
    }
    foreach ($path in $fileMap.Keys) {
        if (!$zipEntries.Contains($path)) {
            return "目録にあるのに zip に無いエントリーがあります: ${path}"
        }
    }

    return ""
}


function testImportedStatusRelPath {
    # ingest_status.tsv の1行の相対パス（\ 区切り。インデックス名は付いていない）が安全に使えるかを返す（使えれば空文字列）
    param (
        [string]$relPath
    )

    if ($relPath -eq "") {
        return "相対パスが空です。"
    }
    return (testPathSegments ($relPath.Split("\")))
}


function testImportedStatusRow {
    # ingest_status.tsv の1行（列は statusColumns と同じ）が受け付けられるかを返す（使えれば空文字列）
    param (
        [string]$line
    )

    $fields = $line.Split("`t")
    if ($fields.Count -ne ${statusColumns}.Count) {
        return "列の数が違います。"
    }
    if (@(${stateNew}, ${stateDone}, ${stateFailed}) -notcontains $fields[3]) {
        return "状態の値（$($fields[3])）が違います。"
    }
    return (testImportedStatusRelPath $fields[0])
}


function testImportedStatusLines {
    # ingest_status.tsv 全体（見出し行 + データ行）が受け付けられるかを返す（使えれば空文字列）。
    # 見出しが違う・列や状態や相対パスがおかしい行がある・同じ相対パスが2つある、のいずれかで止める
    param (
        [string[]]$lines
    )

    if ($lines.Count -eq 0 -or $lines[0] -ne (${statusColumns} -join "`t")) {
        return "ingest_status.tsv の見出しが違います。"
    }
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    for ($i = 1; $i -lt $lines.Count; $i++) {
        $line = $lines[$i]
        if ($line -eq "") {
            continue
        }
        $reason = testImportedStatusRow $line
        if ($reason) {
            return "ingest_status.tsv の $($i + 1) 行目が読めません（${reason}）"
        }
        $relPath = $line.Split("`t")[0]
        if (!$seen.Add($relPath)) {
            return "ingest_status.tsv に同じ相対パスが 2 つあります: ${relPath}"
        }
    }
    return ""
}


function getIndexFolderConflict {
    # 元のフォルダが、ほかのクロール対象のインデックスと重なるかを調べ、直してほしい内容を返す（問題なければ空文字列）。
    # 画面の追加と詳細欄の編集（testIndexEditInput）とインポート（importIndex）の両方が使う、1 つの決まり。
    # 同じフォルダは、getTargetFolders が 2 つ目以降を読まないため設定に残らない。入れ子のフォルダは、
    # 同じファイルが 2 つのインデックスに入り、取り込みも検索結果も二重になる
    param (
        [string]$folder,   # 正規化済みの元のフォルダ
        $others            # 比べる相手（Name・Path を持つ行。置き換える・編集中の行は呼び出し側で外しておく）
    )

    foreach ($other in @($others)) {
        if (testSameFolder $other.Path $folder) {
            return "「${folder}」のインデックス [$($other.Name)] が既にあります。"
        }
        if (testFolderUnder $folder $other.Path) {
            return "「${folder}」は、インデックス [$($other.Name)]（$($other.Path)）の中のフォルダです。" +
                "同じファイルが二重にインデックスに入るため、登録できません。検索する範囲を絞るときは［検索］の検索対象で外してください。"
        }
        if (testFolderUnder $other.Path $folder) {
            return "「${folder}」の中には、インデックス [$($other.Name)]（$($other.Path)）があります。" +
                "同じファイルが二重にインデックスに入るため、登録できません。まとめるときは、先に [$($other.Name)] を削除してください。"
        }
    }
    return ""
}


function getImportIndexName {
    # 同じ名前のインデックスがあったときの扱い（collisionMode）から、インポートで使う名前を決める。
    #   Rename    : usedNames と重ならない名前にする（今の newIndexName の決まり「名前(2)」「名前(3)」…）
    #   Overwrite : suggestedName のまま（そのインデックスを置き換える）
    #   Cancel    : 何もしない（$null）
    param (
        [string]$suggestedName,
        $usedNames = @(),
        [string]$collisionMode
    )

    if ($collisionMode -eq ${importCollisionCancel}) {
        return $null
    }
    if ($collisionMode -eq ${importCollisionOverwrite}) {
        return $suggestedName
    }
    return (newIndexName $suggestedName $usedNames)
}


function getExportFileName {
    # エクスポートの既定のファイル名（"<インデックス名>_インデックス_<yyyyMMdd>.zip"）を返す。
    # usedNames（保存先フォルダに既にあるファイル名）と重なれば "(2)" "(3)" … を付ける
    param (
        [string]$indexName,
        $usedNames = @(),
        [datetime]$now = (Get-Date)
    )

    $base = "$(toSafeFileName $indexName)_インデックス_$($now.ToString('yyyyMMdd'))"
    $used = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($usedName in @($usedNames)) {
        if ($usedName) {
            [void]$used.Add([string]$usedName)
        }
    }
    $name = "${base}.zip"
    for ($i = 2; $used.Contains($name); $i++) {
        $name = "${base}(${i}).zip"
    }
    return $name
}

# インデックスのエクスポート・インポート（状態層。zip の読み書き・ワークスペースの書き換え）。
# 画面にも利用者にも問い合わせない（画面なしで呼べる形にする）。安全性の確かめは index_archive_rules.ps1（判断層）で行う。

# System.IO.Compression.ZipFile・ZipArchive は既定では読み込まれていないアセンブリにあるため、ここで読み込む
Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem

function getBytesSha256 {
    # バイト列の SHA-256（16進64文字）を返す
    param (
        [byte[]]$bytes
    )

    $sha = New-Object System.Security.Cryptography.SHA256CryptoServiceProvider
    try {
        return [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace("-", "")
    } finally {
        $sha.Dispose()
    }
}

function writeArchiveBytes {
    # バイト列を zip の1エントリーとして書く
    param (
        $archive,
        [string]$entryPath,
        [byte[]]$bytes
    )

    $entry = $archive.CreateEntry($entryPath, [System.IO.Compression.CompressionLevel]::Optimal)
    $stream = $entry.Open()
    try {
        $stream.Write($bytes, 0, $bytes.Length)
    } finally {
        $stream.Dispose()
    }
}

function writeArchiveFile {
    # ファイルを1つ、ストリームで zip の1エントリーに写す（メモリに全体を読まない）。
    # 写しながら SHA-256 を計算し、@{ Size; Sha256 } を返す
    param (
        $archive,
        [string]$entryPath,
        [string]$sourcePath
    )

    $entry = $archive.CreateEntry($entryPath, [System.IO.Compression.CompressionLevel]::Optimal)
    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $source = New-Object System.IO.FileStream((toLongPath $sourcePath), [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    $sha = New-Object System.Security.Cryptography.SHA256CryptoServiceProvider
    try {
        $size = $source.Length
        $entryStream = $entry.Open()
        try {
            $crypto = New-Object System.Security.Cryptography.CryptoStream($entryStream, $sha, [System.Security.Cryptography.CryptoStreamMode]::Write)
            try {
                $source.CopyTo($crypto)
                $crypto.FlushFinalBlock()
            } finally {
                $crypto.Dispose()
            }
        } finally {
            $entryStream.Dispose()
        }
        return @{ Size = $size; Sha256 = [BitConverter]::ToString($sha.Hash).Replace("-", "") }
    } finally {
        $source.Dispose()
        $sha.Dispose()
    }
}

function exportIndex {
    # 1 つのインデックスを 1 つの zip に書き出す: @{ Name; Path; Files; Bytes }。画面にも利用者にも問い合わせない。
    # インデックス作成のロックを取れなければ例外（ほかで実行中）
    param (
        [string]$name,
        [string]$destPath,
        $ws = $workspace,
        [string]$settingsPath = ${settingsFile}
    )

    $lock = newAppMutex "indexer" $ws.Dir
    if (!$lock.Acquired) {
        $lock.Mutex.Dispose()
        throw "更新中はエクスポートできません。更新が終わってからやり直してください。"
    }
    try {
        return (exportIndexCore $name $destPath $ws $settingsPath)
    } finally {
        $lock.Mutex.ReleaseMutex()
        $lock.Mutex.Dispose()
    }
}

function exportIndexToFolder {
    # 1 つのインデックスを、書き出し先のフォルダの中の zip に書き出す（ファイル名は getExportFileName で決め、
    # フォルダに同じ名前があれば番号を付ける）。書き出し先のフォルダが無ければ例外。戻り値は exportIndex と同じ。
    # 届かないネットワークのフォルダで止まりうるので、画面のスレッドでは呼ばず、別スレッドの仕事の中で呼ぶ
    param (
        [string]$name,
        [string]$folder,
        $ws = $workspace,
        [string]$settingsPath = ${settingsFile}
    )

    if (!(Test-Path -LiteralPath (toLongPath $folder) -PathType Container)) {
        throw "書き出し先のフォルダが見つかりません：$folder"
    }
    $used = @(Get-ChildItem -LiteralPath (toLongPath $folder) -File -ErrorAction SilentlyContinue | ForEach-Object { $_.Name })
    $destPath = Join-Path $folder (getExportFileName $name $used)
    return (exportIndex $name $destPath $ws $settingsPath)
}

function exportIndexes {
    # 選んだインデックスを、書き出し先のフォルダの中の zip にまとめて書き出す（インデックス 1 つにつき zip 1 つ）。
    # 1 つずつ exportIndexToFolder を呼び、途中で 1 つ失敗しても残りを続ける。
    # 戻り値は名前ごとの結果の配列（@{ Name; Ok; Reason; Path }）。Reason は失敗したときの理由（成功なら ""）、Path は書き出した zip（失敗なら ""）。
    # 画面のスレッドでは呼ばず、別スレッドの仕事の中で呼ぶ
    param (
        [string[]]$names,
        [string]$destination,
        $ws = $workspace,
        [string]$settingsPath = ${settingsFile}
    )

    $results = New-Object System.Collections.Generic.List[object]
    foreach ($name in @($names)) {
        try {
            $exported = exportIndexToFolder $name $destination $ws $settingsPath
            $results.Add([pscustomobject]@{ Name = $name; Ok = $true; Reason = ""; Path = $exported.Path })
        } catch {
            $results.Add([pscustomobject]@{ Name = $name; Ok = $false; Reason = $_.Exception.Message; Path = "" })
        }
    }
    return , $results.ToArray()
}

function getIndexExportSize {
    # エクスポートする前に、選んだインデックスが zip に入れる本文インデックスのファイル（*.tsv）の大きさの合計を数える。
    # 戻り値: @{ Bytes（合計のバイト数）; Missing（インデックスのフォルダが無かった名前の配列）}。
    # 数えるのは zip に入る元のファイルの大きさで、zip にした後の大きさではない。
    # 画面のスレッドでは呼ばず、別スレッドの仕事の中で呼ぶ
    param (
        [string[]]$names,
        $ws = $workspace
    )

    $bytes = [long]0
    $missing = New-Object System.Collections.Generic.List[string]
    foreach ($name in @($names)) {
        $indexDir = Join-Path $ws.IndexDir $name
        if (!(Test-Path -LiteralPath (toLongPath $indexDir) -PathType Container)) {
            $missing.Add($name)
            continue
        }
        foreach ($file in [System.IO.Directory]::GetFiles((toLongPath $indexDir), "*.tsv", [System.IO.SearchOption]::AllDirectories)) {
            $bytes += ([System.IO.FileInfo]::new($file)).Length
        }
    }
    return @{ Bytes = $bytes; Missing = $missing.ToArray() }
}

function exportIndexCore {
    param (
        [string]$name,
        [string]$destPath,
        $ws,
        [string]$settingsPath
    )

    $indexDir = Join-Path $ws.IndexDir $name
    if (!(Test-Path -LiteralPath (toLongPath $indexDir) -PathType Container)) {
        throw "インデックス [${name}] が見つかりません。"
    }
    $status = readStatusFile $ws.StatusFile
    if (@($status.Folders | Where-Object { [string]::Equals([string]$_.Name, $name, [System.StringComparison]::OrdinalIgnoreCase) }).Count -eq 0) {
        throw "取り込み一覧に、インデックス [${name}] の記録がありません。"
    }

    # 入れる前の TSV（本文インデックスのファイル以外の *.tsv）が残っていれば、途中で止まったインデックスとして止める
    $longIndexDir = toLongPath $indexDir
    $prefixLength = $indexDir.TrimEnd("\").Length + 1
    $contentIndexFiles = New-Object System.Collections.Generic.List[string]
    # 途中で throw して抜けても下のフォルダを掴んだまま残らないよう、列挙子（EnumerateFiles）でなく配列（GetFiles）で受ける
    foreach ($file in [System.IO.Directory]::GetFiles($longIndexDir, "*.tsv", [System.IO.SearchOption]::AllDirectories)) {
        $rel = (fromLongPath $file).Substring($prefixLength)
        $fileName = [System.IO.Path]::GetFileName($rel)
        if ($null -eq (readContentIndexFileName $fileName)) {
            throw "更新を最後まで行ってからエクスポートしてください（更新の途中のファイルが残っています: ${rel}）。"
        }
        $contentIndexFiles.Add($rel)
    }

    # 取り込み一覧のうち、このインデックスの行だけを抜き出し、相対パスの先頭の "<名前>\" を外す
    $prefix = "$name\"
    $rows = New-Object System.Collections.Generic.List[string]
    $rows.Add((${statusColumns} -join "`t"))
    foreach ($entry in $status.Rows.GetEnumerator()) {
        if ($entry.Key.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) {
            $row = $entry.Value
            $stripped = [pscustomobject]@{
                相対パス = $entry.Key.Substring($prefix.Length); 更新日時 = $row.更新日時; サイズ = $row.サイズ; 状態 = $row.状態
                TSV数 = $row.TSV数; 取り込み日時 = $row.取り込み日時; エラー = $row.エラー; 抽出版 = $row.抽出版
            }
            $rows.Add((toStatusLine $stripped))
        }
    }
    $statusText = [string]::Join("`r`n", $rows) + "`r`n"

    $tmpPath = "${destPath}.tmp"
    [System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($tmpPath)) | Out-Null
    if (Test-Path -LiteralPath $tmpPath) {
        Remove-Item -LiteralPath $tmpPath -Force
    }

    try {
        $manifestFiles = New-Object System.Collections.Generic.List[object]
        $totalBytes = [long]0
        $archive = [System.IO.Compression.ZipFile]::Open($tmpPath, [System.IO.Compression.ZipArchiveMode]::Create, [System.Text.Encoding]::UTF8)
        try {
            $statusBytes = ${utf8Bom}.GetBytes($statusText)
            writeArchiveBytes $archive ${indexArchiveStatusEntryName} $statusBytes
            $manifestFiles.Add([ordered]@{ path = ${indexArchiveStatusEntryName}; size = [long]$statusBytes.Length; sha256 = (getBytesSha256 $statusBytes) })
            $totalBytes += $statusBytes.Length

            foreach ($rel in $contentIndexFiles) {
                $entryPath = "content_index/" + $rel.Replace("\", "/")
                $written = writeArchiveFile $archive $entryPath (Join-Path $indexDir $rel)
                $manifestFiles.Add([ordered]@{ path = $entryPath; size = [long]$written.Size; sha256 = $written.Sha256 })
                $totalBytes += $written.Size
            }

            $sourceFolder = ""
            $ownFile = readSourceFolderFile $indexDir
            if ($ownFile.ContainsKey($name)) {
                $sourceFolder = $ownFile[$name]
            } else {
                $sourceMap = getSourceFolderMap $ws.IndexDir $ws.StatusFile $settingsPath
                if ($sourceMap.ContainsKey($name)) {
                    $sourceFolder = $sourceMap[$name]
                }
            }
            $version = readVersionFile (Join-Path ${rootDir} "VERSION.txt")
            $manifest = [ordered]@{
                format        = ${indexArchiveFormat}
                formatVersion = ${indexArchiveFormatVersion}
                appVersion    = $(if ($version) { $version.Tag } else { "" })
                exportedAt    = (Get-Date).ToString("yyyy-MM-ddTHH:mm:sszzz")
                indexName     = $name
                sourceFolder  = $sourceFolder
                files         = $manifestFiles.ToArray()
            }
            $manifestJson = ConvertTo-Json -InputObject $manifest -Depth 5
            writeArchiveBytes $archive ${indexArchiveManifestFileName} ((New-Object System.Text.UTF8Encoding($false)).GetBytes($manifestJson))
        } finally {
            $archive.Dispose()
        }
    } catch {
        if (Test-Path -LiteralPath $tmpPath) {
            Remove-Item -LiteralPath $tmpPath -Force -ErrorAction SilentlyContinue
        }
        throw
    }
    try {
        if (Test-Path -LiteralPath $destPath) {
            Remove-Item -LiteralPath $destPath -Force
        }
        [System.IO.File]::Move((toLongPath $tmpPath), (toLongPath $destPath))
    } catch {
        if (Test-Path -LiteralPath $tmpPath) {
            Remove-Item -LiteralPath $tmpPath -Force -ErrorAction SilentlyContinue
        }
        throw
    }
    return @{ Name = $name; Path = $destPath; Files = $manifestFiles.Count; Bytes = $totalBytes }
}

function openIndexArchive {
    # zip を開き、目録（testIndexArchiveManifest）を確かめる。確かめられなければ、開いたアーカイブを閉じて例外にする。
    # 返すもの: @{ Archive; Manifest }（呼んだ側が Archive.Dispose() を行う）
    param (
        [string]$zipPath
    )

    try {
        $archive = [System.IO.Compression.ZipFile]::Open($zipPath, [System.IO.Compression.ZipArchiveMode]::Read, [System.Text.Encoding]::UTF8)
    } catch {
        throw "tebunko のインデックスの zip ではない、または壊れています（$($_.Exception.Message)）。"
    }
    try {
        $entryNames = @($archive.Entries | ForEach-Object { $_.FullName })
        $manifestEntry = $archive.Entries | Where-Object { $_.FullName -ceq ${indexArchiveManifestFileName} } | Select-Object -First 1
        $manifest = $null
        $manifestBytes = [long]0
        if ($null -ne $manifestEntry) {
            $manifestBytes = $manifestEntry.Length
            if ($manifestBytes -le ${indexArchiveMaxManifestBytes}) {
                $reader = New-Object System.IO.StreamReader($manifestEntry.Open(), [System.Text.Encoding]::UTF8)
                try {
                    $json = $reader.ReadToEnd()
                } finally {
                    $reader.Dispose()
                }
                try {
                    $manifest = ConvertFrom-Json $json
                } catch {
                    $manifest = $null
                }
            }
        }
        $reason = testIndexArchiveManifest $manifest $entryNames $manifestBytes
        if ($reason) {
            throw $reason
        }
        return @{ Archive = $archive; Manifest = $manifest }
    } catch {
        $archive.Dispose()
        throw
    }
}

function readIndexArchiveInfo {
    # 目録だけを読んで確かめる（インポートせずに、画面が既定の名前・元のフォルダ・合計の大きさを出すために使う）。
    # 返すもの: @{ IndexName; SourceFolder; Files; Bytes; FormatVersion; AppVersion; ExportedAt（目録の exportedAt のまま。無ければ空） }
    param (
        [string]$zipPath
    )

    $opened = openIndexArchive $zipPath
    try {
        $manifest = $opened.Manifest
        $bytes = [long]0
        foreach ($file in @($manifest.files)) {
            $bytes += [long]$file.size
        }
        return @{
            IndexName     = [string]$manifest.indexName
            SourceFolder  = (getManifestSourceFolder $manifest)
            Files         = @($manifest.files).Count
            Bytes         = $bytes
            FormatVersion = [int]$manifest.formatVersion
            AppVersion    = [string]$manifest.appVersion
            ExportedAt    = [string]$manifest.exportedAt
        }
    } finally {
        $opened.Archive.Dispose()
    }
}

function getImportArchiveInfo {
    # readIndexArchiveInfo の結果に、元のフォルダがこの PC にあるか（SourceExists）を足して返す（インポートの裏の仕事で使う）。
    # 目録の元のフォルダは zip の送り手が自由に書けるため、ネットワークの場所なら接続せず（Test-Path を呼ばず）$null（分からない）にする。
    # 利用者が元のフォルダを見て確かめる前に、サインイン情報が相手のサーバーへ送られないようにするため
    param (
        [string]$zipPath
    )

    $info = readIndexArchiveInfo $zipPath
    $exists = $false
    try {
        $folder = normalizeFolderPath ([string]$info.SourceFolder)
        if (testLocalDrivePath $folder) {
            $exists = [bool](Test-Path -LiteralPath $folder -PathType Container)
        } elseif ($folder) {
            # ローカルのドライブと分かるときだけ調べる。ネットワークの場所や、デバイス名の形（\\.\UNC\・\\.\GLOBALROOT\ など）は
            # 調べず「分からない」にする
            $exists = $null
        }
    } catch {
        # 使えない文字を含むなど。無いものとして扱う
    }
    $info.SourceExists = $exists
    return $info
}

function getImportUsedIndexNames {
    # 今使われているインデックス名（設定の targetFolders・indexSources、content_index\ 直下のフォルダ、
    # 取り込み一覧のクロール対象フォルダの行）を集めて返す（大文字・小文字を区別しない集合）
    param (
        $ws,
        [string]$settingsPath
    )

    $names = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($folder in @(getTargetFolders $settingsPath)) {
        if ($folder.Name) {
            [void]$names.Add($folder.Name)
        }
    }
    foreach ($source in @(readIndexSources $settingsPath)) {
        if ($source.Name) {
            [void]$names.Add($source.Name)
        }
    }
    if (Test-Path -LiteralPath (toLongPath $ws.IndexDir) -PathType Container) {
        foreach ($dir in [System.IO.Directory]::GetDirectories((toLongPath $ws.IndexDir))) {
            [void]$names.Add([System.IO.Path]::GetFileName($dir))
        }
    }
    foreach ($folder in (readStatusFile $ws.StatusFile).Folders.ToArray()) {
        if ($folder.Name) {
            [void]$names.Add($folder.Name)
        }
    }
    return , $names
}

function extractArchiveEntryToFile {
    # zip のエントリーを、目録の大きさ（expectedSize）を超えないようストリームで写す。
    # 書き終えたら大きさと SHA-256 を比べ、違えば例外にする（写したファイルは呼び出し側が消す）
    param (
        $entry,
        [long]$expectedSize,
        [string]$expectedSha256,
        [string]$destPath
    )

    [System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName((toLongPath $destPath))) | Out-Null
    $source = $entry.Open()
    $sha = New-Object System.Security.Cryptography.SHA256CryptoServiceProvider
    $total = [long]0
    try {
        $dest = New-Object System.IO.FileStream((toLongPath $destPath), [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
        try {
            $buffer = New-Object byte[] 1MB
            while ($true) {
                $read = $source.Read($buffer, 0, $buffer.Length)
                if ($read -le 0) {
                    break
                }
                $total += $read
                if ($total -gt $expectedSize) {
                    throw "エントリー「$($entry.FullName)」が目録の大きさより大きく展開されました。"
                }
                [void]$sha.TransformBlock($buffer, 0, $read, $buffer, 0)
                $dest.Write($buffer, 0, $read)
            }
        } finally {
            $dest.Dispose()
        }
        [void]$sha.TransformFinalBlock([byte[]]@(), 0, 0)
        $actualHash = [BitConverter]::ToString($sha.Hash).Replace("-", "")
    } finally {
        $source.Dispose()
        $sha.Dispose()
    }
    if ($total -ne $expectedSize -or $actualHash -ne $expectedSha256) {
        throw "エントリー「$($entry.FullName)」の大きさか内容が目録と違います。"
    }
}

function getWorkspaceFreeSpace {
    # root（ドライブのルート）の空き容量（バイト）を返す。UNC（\\server\share）など、ドライブとして扱えず調べられないときは $null
    # （調べられないだけでインポートを止めない。呼び出し側が確かめを飛ばす）
    param (
        [string]$root
    )

    try {
        return ([System.IO.DriveInfo]$root).AvailableFreeSpace
    } catch {
        return $null
    }
}

function importIndex {
    # zip から 1 つのインデックスをインポートする: @{ Name; SourcePath; Enabled; Files; Bytes; Warnings }。
    # collisionMode（Rename・Overwrite・Cancel）が Cancel なら $null を返す（ワークスペースは変えない）。
    # name・sourceFolder を省くと目録の値を使う。インデックス作成のロックを取れなければ例外
    param (
        [string]$zipPath,
        [string]$collisionMode,
        [string]$name = "",
        [string]$sourceFolder = "",
        $ws = $workspace,
        [string]$settingsPath = ${settingsFile},
        [scriptblock]$getFreeSpace = { param ($root) getWorkspaceFreeSpace $root }
    )

    $lock = newAppMutex "indexer" $ws.Dir
    if (!$lock.Acquired) {
        $lock.Mutex.Dispose()
        throw "更新中はインポートできません。更新が終わってからやり直してください。"
    }
    try {
        return (importIndexCore $zipPath $collisionMode $name $sourceFolder $ws $settingsPath $getFreeSpace)
    } finally {
        $lock.Mutex.ReleaseMutex()
        $lock.Mutex.Dispose()
    }
}

function testImportFreeSpace {
    # 空き容量が「目録の合計 + 余裕」に足りなければ、理由を返す（足りていれば空文字列）。
    # 空き容量を調べられないとき（getFreeSpace が $null を返す・例外になる。UNC のワークスペースなど）は確かめない
    param (
        [long]$totalBytes,
        [string]$root,
        [scriptblock]$getFreeSpace
    )

    $freeSpace = $null
    try {
        $freeSpace = & $getFreeSpace $root
    } catch {
    }
    if ($null -eq $freeSpace) {
        return ""
    }
    $needed = $totalBytes + ${indexArchiveFreeSpaceMargin}
    if ($freeSpace -lt $needed) {
        return "保存先の空き容量が足りません（必要 約 $([Math]::Ceiling($needed / 1MB)) MB）。"
    }
    return ""
}

function expandImportArchive {
    # 7. 目録にあるエントリーを作業フォルダ（<workDir>\new）に展開する（目録のパスからだけ作る。エントリーの名前からは作らない）。
    # 書き込む前に、大きさと SHA-256 を目録と比べる。source_folder.txt もここで作る。
    # 返すもの: @{ NewDir; Rows }（Rows は取り込み一覧に足す行。相対パスの先頭にインデックス名を付けたもの）。
    # 途中で失敗したら、作業フォルダを消して例外にする
    param (
        $archive,
        $fileEntries,
        [string]$workDir,
        [string]$finalName,
        [string]$folder
    )

    $newDir = Join-Path $workDir "new"
    removeDirectoryRetry $workDir
    [System.IO.Directory]::CreateDirectory((toLongPath $newDir)) | Out-Null
    try {
        $statusTmpPath = Join-Path $workDir ${indexArchiveStatusEntryName}
        $statusLines = $null
        foreach ($file in $fileEntries) {
            $path = [string]$file.path
            $entry = $archive.GetEntry($path)
            if ($null -eq $entry) {
                throw "目録にあるのに zip に無いエントリーがあります: ${path}"
            }
            $size = [long]$file.size
            $sha256 = [string]$file.sha256
            if ($path -ceq ${indexArchiveStatusEntryName}) {
                extractArchiveEntryToFile $entry $size $sha256 $statusTmpPath
                $bytes = [System.IO.File]::ReadAllBytes((toLongPath $statusTmpPath))
                $text = ${utf8Bom}.GetString($bytes)
                $statusLines = @($text -split "\r?\n" | Where-Object { $_ -ne "" })
                $reason = testImportedStatusLines $statusLines
                if ($reason) {
                    throw "ingest_status.tsv を読み込めません（${reason}）"
                }
            } else {
                $rel = $path.Substring("content_index/".Length).Replace("/", "\")
                extractArchiveEntryToFile $entry $size $sha256 (Join-Path $newDir $rel)
            }
        }
        if ($null -eq $statusLines) {
            throw "目録に ${indexArchiveStatusEntryName} がありません。"
        }

        $rows = New-Object System.Collections.Generic.List[object]
        foreach ($line in @($statusLines | Select-Object -Skip 1)) {
            $fields = $line.Split("`t")
            $rows.Add((newStatusRow "${finalName}\$($fields[0])" $fields[1] $fields[2] $fields[3] $fields[4] $fields[5] $fields[6] $fields[7]))
        }

        $header = "# 検索結果から元のファイルを開くときに使う、インデックス名とクロール対象フォルダの対応です（インデックス作成のたびに作り直します）"
        writeListFile (Join-Path $newDir ${sourceFolderFileName}) @($header, "${finalName}`t${folder}")
        return @{ NewDir = $newDir; Rows = $rows.ToArray() }
    } catch {
        removeDirectoryRetry $workDir
        throw
    }
}

function restoreImportedSettings {
    # registerImportedIndexInSettings で変える前の内容（before）に、設定の 3 つの項目（クロール対象・検索だけのインデックス・検索から外したフォルダ）を戻す。
    # ほかの項目には触らない
    param (
        $before,
        [string]$settingsPath
    )

    invokeSettingsLocked -path $settingsPath -action {
        writeTargetFolders $before.Targets $settingsPath
        if ($before.SourcesChanged) {
            writeIndexSources $before.Sources $settingsPath
        }
        if ($before.ExcludesChanged) {
            writeSearchExcludes $before.Excludes $settingsPath
        }
    } | Out-Null
}

function registerImportedIndexInSettings {
    # 8. 設定にインデックスを登録する（クロール対象に名前と元のフォルダを入れる。同じ名前があれば置き換え、同じ名前の検索だけのインデックスは外す。
    # 上書きなら、前のインデックスの検索から外したフォルダの記録も消す）。
    # 途中で失敗したら、変える前に戻して例外にする。成功したら、戻すための @{ Targets; Sources; Excludes; SourcesChanged; ExcludesChanged } を返す
    param (
        [string]$finalName,
        [string]$folder,
        [bool]$overwrite,
        [string]$indexDir,
        [string]$settingsPath
    )

    $before = invokeSettingsLocked -path $settingsPath -action {
        return @{
            Targets = @(getTargetFolders $settingsPath); Sources = @(readIndexSources $settingsPath)
            Excludes = @(readSearchExcludes $settingsPath); SourcesChanged = $false; ExcludesChanged = $false
        }
    }
    try {
        invokeSettingsLocked -path $settingsPath -action {
            $enabled = [System.IO.Directory]::Exists((toLongPath $folder))
            $entry = [pscustomobject]@{ Name = $finalName; Path = $folder; Enabled = $enabled }
            $targets = New-Object System.Collections.Generic.List[object]
            $found = $false
            foreach ($target in $before.Targets) {
                if ($target.Name -ieq $finalName) {
                    $targets.Add($entry)
                    $found = $true
                } else {
                    $targets.Add($target)
                }
            }
            if (!$found) {
                $targets.Add($entry)
            }
            writeTargetFolders $targets.ToArray() $settingsPath
            if (@($before.Sources | Where-Object { $_.Name -ieq $finalName }).Count -gt 0) {
                $before.SourcesChanged = $true
                writeIndexSources @($before.Sources | Where-Object { $_.Name -ine $finalName }) $settingsPath
            }
            if ($overwrite) {
                $before.ExcludesChanged = $true
                [void](removeSearchExcludesUnder $indexDir $settingsPath)
            }
        } | Out-Null
    } catch {
        restoreImportedSettings $before $settingsPath
        throw
    }
    return $before
}

function swapInImportedIndexDir {
    # 9. content_index\<名前> を展開したフォルダ（newDir）に入れ替える。前のフォルダは previous に退避する。
    # 失敗したら、退避したフォルダを戻して例外にする。成功したら、戻すための @{ TargetDir; PreviousDir; HadPrevious } を返す
    param (
        [string]$newDir,
        [string]$targetDir,
        [string]$previousDir,
        [string]$indexRoot
    )

    # ウイルス対策ソフトが、作ったばかり・書いたばかりのフォルダ（$targetDir は前の取り込みで、$newDir はこの
    # インポートの展開で、それぞれ書いたばかり）を一時的に掴んでいることがあるため、moveDirectoryRetry で試し直す
    # （removeDirectoryRetry と同じ理由。docs/design/index-data/format.md「インポート」を参照）
    $hadPrevious = Test-Path -LiteralPath (toLongPath $targetDir) -PathType Container
    if ($hadPrevious) {
        moveDirectoryRetry $targetDir $previousDir
    }
    try {
        [System.IO.Directory]::CreateDirectory((toLongPath $indexRoot)) | Out-Null
        moveDirectoryRetry $newDir $targetDir
    } catch {
        if ($hadPrevious) {
            moveDirectoryRetry $previousDir $targetDir
        }
        throw
    }
    return @{ TargetDir = $targetDir; PreviousDir = $previousDir; HadPrevious = $hadPrevious }
}

function restoreSwappedIndexDir {
    # swapInImportedIndexDir で入れ替えたフォルダを、入れ替える前に戻す（入れたものを消し、退避した前のフォルダを戻す）
    param (
        $swap
    )

    removeDirectoryRetry $swap.TargetDir
    if ($swap.HadPrevious) {
        moveDirectoryRetry $swap.PreviousDir $swap.TargetDir
    }
}

function rewriteStatusForImport {
    # 10. 取り込み一覧を書き直す（このインデックスの前のクロール対象フォルダの行と各行を消し、新しい行を足す）。
    # ほかのインデックスの行は残す。見出しの行を含め、インデクサが書くのと同じ形（writeStatusFile）で書く
    param (
        [string]$statusPath,
        [string]$finalName,
        [string]$folder,
        $importedRows
    )

    $status = readStatusFile $statusPath
    $folders = New-Object System.Collections.Generic.List[object]
    foreach ($other in $status.Folders) {
        if (![string]::Equals($other.Name, $finalName, [System.StringComparison]::OrdinalIgnoreCase)) {
            $folders.Add($other)
        }
    }
    $folders.Add([pscustomobject]@{ Path = $folder; Name = $finalName })

    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($row in $status.Rows.Values) {
        if (![string]::Equals((splitIndexRelPath $row.相対パス).Name, $finalName, [System.StringComparison]::OrdinalIgnoreCase)) {
            $rows.Add($row)
        }
    }
    foreach ($row in $importedRows) {
        $rows.Add($row)
    }
    writeStatusFile $folders.ToArray() $rows.ToArray() $statusPath
}

function importIndexCore {
    param (
        [string]$zipPath,
        [string]$collisionMode,
        [string]$name,
        [string]$sourceFolder,
        $ws,
        [string]$settingsPath,
        [scriptblock]$getFreeSpace
    )

    # 前の版のワークスペース（index\ あり・content_index\ が空）を、取り込み直しを始めるときと同じ手順で片付ける。
    # content_index\ にこのインポートの分を足す前に行う（片付けに失敗したら、以降は行わない）
    $legacyState = getLegacyIndexState $ws.Dir
    if (testLegacyCleanupNeeded $legacyState) {
        $cleanup = clearLegacySystemIndex $ws.Dir
        if (!$cleanup.Ok) {
            throw "前の版のインデックス（高速検索用）を片付けられませんでした（$($cleanup.Reason)）。tebunko の画面やエクスプローラーで開いていれば閉じてから、もう一度インポートしてください。"
        }
    }

    $opened = openIndexArchive $zipPath
    $archive = $opened.Archive
    try {
        $manifest = $opened.Manifest
        $suggestedName = if ($name) { $name } else { [string]$manifest.indexName }
        # 集合を返す関数なので、@() で包まない（包むと集合が 1 要素の配列になり、newIndexName が名前を突き合わせられず、
        # 「別名」でも同じ名前のインデックスを上書きしてしまう）
        $usedNames = getImportUsedIndexNames $ws $settingsPath
        $finalName = getImportIndexName $suggestedName $usedNames $collisionMode
        if ($null -eq $finalName) {
            return $null
        }
        $nameReason = testIndexName $finalName @()
        if ($nameReason) {
            throw $nameReason
        }
        $overwrite = ($collisionMode -eq ${importCollisionOverwrite})

        $folder = if ($sourceFolder) { normalizeFolderPath $sourceFolder } else { getManifestSourceFolder $manifest }
        if ($folder -eq "") {
            throw "元のフォルダを指定してください。"
        }

        $totalBytes = [long]0
        $fileEntries = @($manifest.files)
        foreach ($file in $fileEntries) {
            $totalBytes += [long]$file.size
        }
        $spaceReason = testImportFreeSpace $totalBytes ([System.IO.Path]::GetPathRoot($ws.Dir)) $getFreeSpace
        if ($spaceReason) {
            throw $spaceReason
        }

        # 同じ元のフォルダが、別の名前のクロール対象フォルダに既にある・入れ子になっていれば止める（getTargetFolders は同じフォルダの 2 つ目以降を読まないため、
        # 登録しても設定に残らず、次のインデックス作成の確認に、このインデックスが「削除予定」として出る。画面の追加・編集と同じ getIndexFolderConflict の決まり）。
        # 検索だけのインデックス（indexSources）の元のフォルダと同じなら、止めずに知らせる
        $conflict = getIndexFolderConflict $folder @(getTargetFolders $settingsPath | Where-Object { $_.Name -ine $finalName })
        if ($conflict -ne "") {
            throw $conflict
        }
        $warnings = New-Object System.Collections.Generic.List[string]
        foreach ($other in @(readIndexSources $settingsPath | Where-Object { $_.Name -ine $finalName })) {
            if (testSameFolder $other.Path $folder) {
                $warnings.Add("元のフォルダ「${folder}」は、インデックス [$($other.Name)] としても登録されています。")
                break
            }
        }

        $workDir = Join-Path $ws.PublishDir "import"
        $expanded = expandImportArchive $archive $fileEntries $workDir $finalName $folder
        $targetIndexDir = Join-Path $ws.IndexDir $finalName
        try {
            $before = registerImportedIndexInSettings $finalName $folder $overwrite $targetIndexDir $settingsPath
            try {
                $swap = swapInImportedIndexDir $expanded.NewDir $targetIndexDir (Join-Path $workDir "previous") $ws.IndexDir
                # Directory.Move で入れたフォルダは、work\content_index の NotContentIndexed を受け継がない。
                # 根に付いたあとの -Recurse は中へ降りないため（publish.md）、入れた直後に付ける（失敗しても止めない）
                setNotContentIndexed $targetIndexDir -Recurse | Out-Null
                try {
                    rewriteStatusForImport $ws.StatusFile $finalName $folder $expanded.Rows
                } catch {
                    restoreSwappedIndexDir $swap
                    throw
                }
            } catch {
                restoreImportedSettings $before $settingsPath
                throw
            }
        } catch {
            removeDirectoryRetry $workDir
            throw
        }

        # 11. 上書きなら、前のシステムインデックスを消す（消せなくても続ける。次のインデックス作成で整理される）
        if ($overwrite) {
            removeSystemIndexOfWorkspace $finalName $ws.IndexDir
        }
        # 12. 作業フォルダを消す
        removeDirectoryRetry $workDir

        return @{
            Name = $finalName; SourcePath = $folder; Enabled = [System.IO.Directory]::Exists((toLongPath $folder))
            Files = $fileEntries.Count; Bytes = $totalBytes; Warnings = $warnings.ToArray()
        }
    } finally {
        $archive.Dispose()
    }
}

# Word（.docx / .docm）・PowerPoint（.pptx / .pptm）のファイルと、Excel（.xlsx / .xlsm）の図形・コメントからテキストを読み出す。
# ファイルはZIP（Office Open XML）として直接読むため、Word・PowerPoint・Excelは使わない。
# インデクサ・テストから dot-source して使う。共通の部品（shared.ps1）を先に読み込んでおくこと。
#
# 読み出した結果は「場所 → 行の一覧」の順序付き辞書（ユニット）で返す。
#   Word      : ページ001, ページ001[図形], ページ001[コメント], ページ001[埋め込み1], ページ002, ..., ヘッダー・フッター, 脚注
#   PowerPoint: スライド001, スライド001[図形], スライド001[コメント], スライド001[埋め込み1], スライド001_ノート, スライド002（非表示）, ..., ヘッダー・フッター
#   Excel     : <シート名>[図形]（グラフ・SmartArt の文字を含む。表示のグラフシートも含む）, <シート名>[コメント],
#              <シート名>[ヘッダー・フッター]（セルの値はインデクサが Excel で読む）
# 1行は段落1つ、または表の1行（セルをタブ区切り）。図形・コメントの場所は図形・コメント1つ
# （Word・PowerPoint は文字だけ、Excel は "<セル番地><TAB><文字>"）。
# 埋め込みの場所は、埋め込んだ Office のファイル（Office Open XML）1 つの中の文字をまとめたもの
# （office_embedded.ps1。[埋め込み<N>] の N は 1 ファイルの中の通し番号）。

Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem

${nsWord}    = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
${nsDrawing} = "http://schemas.openxmlformats.org/drawingml/2006/main"
${nsPresent} = "http://schemas.openxmlformats.org/presentationml/2006/main"
${nsCompat}  = "http://schemas.openxmlformats.org/markup-compatibility/2006"
${nsRel}     = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"
${nsPkgRel}  = "http://schemas.openxmlformats.org/package/2006/relationships"
${nsDiagram} = "http://schemas.openxmlformats.org/drawingml/2006/diagram"
${nsChart}   = "http://schemas.openxmlformats.org/drawingml/2006/chart"
${nsOffice}  = "urn:schemas-microsoft-com:office:office"

# PowerPointで読み飛ばすプレースホルダー（スライド番号・日付・ヘッダー・フッター・スライド画像）
${skipPlaceholderTypes} = @("sldNum", "dt", "hdr", "ftr", "sldImg")

# ZIPの部品（ファイル）1つの展開後の大きさと、1ファイルの合計（readDocxUnits・readPptxUnits・
# readXlsxObjectUnitsがファイルを開くたびに0から数える）の上限。どちらもバイト（entry.Lengthと同じ単位）。
# ZIP爆弾（小さく圧縮した巨大な部品）・部品を大量に並べたファイルでメモリを使い切るのを防ぐ（readZipEntry）。
# setting.config には出さない定数（値を変えたい場合は docs/design/indexing/known-issues.md を参照）。
# $script: の変数は読み取りのスレッド（runspace）ごとに別になる。ファイルの合計はスレッドごとに独立して
# 数えたいので都合がよい（テストから一時的に値を変えるときは、この $script: を直接上書きする）
$script:zipPartMaxBytes = 100MB
$script:zipTotalMaxBytes = 300MB
# シートの部品を流れで読む（readXlsxSheetHeaderFooter）ときの、展開後の大きさ（バイト）の上限。流れ読みは文字列にしない
# のでメモリを使わず、かかるのは時間だけ。シートは sheetData が大きく、実在のブックでも部品の上限（100MB）を超えうる
# ため、部品の上限より大きい別の値にする（超えたシートは、そのシートのヘッダー・フッターだけ読めなかった扱い）。
# 1ファイルの合計（zipTotalMaxBytes）には数えないので、シートごとに最大この大きさまで読む
$script:zipSheetStreamMaxBytes = 1000MB
# 1ファイルの合計（バイト）。readZipEntry が確保する大きさ（entry.Length）を足していく
$script:zipTotalReadBytes = 0

# サイズの上限を超えた（ZIP爆弾・巨大なXML等の見込み）ときに投げる、利用者向けの短い文言。
# 画面には部品ごとか合計かの区別・部品名・大きさを出さない（分かると悪用のヒントになるため）。
# 原因を調べられるよう、部品名・大きさ・部品ごとか合計かはインデックス作成のログにだけ書く。
# shared/ はツール（インデックス作成のログ）を知らないため、ここでは書かず、
# ZipSizeLimitException のプロパティで呼び出し元（tebunko/indexer）に伝える
$script:zipTooLargeMessage = "ファイルサイズが大きすぎるため更新できません。"

class ZipSizeLimitException : System.Exception {
    # .Message は今までどおり利用者向けの簡潔な文言のまま（$script:zipTooLargeMessage）。
    # 部品名・大きさ・部品ごとか合計かは、ここのプロパティにだけ持ち、呼び出し元がインデックス作成のログに書く
    [string]$PartName     # ZIP内のパス（例: "word/document.xml"）
    [long]$MeasuredBytes  # 超えたと分かった時点の大きさ（バイト）。偽りのヘッダーのときは、実際の大きさまでは分からないため、検出できた時点の値
    [string]$LimitKind    # "Part"（部品ごとの上限。偽りのヘッダーを含む）または "Total"（1ファイルの合計の上限）

    ZipSizeLimitException([string]$message, [string]$partName, [long]$measuredBytes, [string]$limitKind) : base($message) {
        $this.PartName = $partName
        $this.MeasuredBytes = $measuredBytes
        $this.LimitKind = $limitKind
    }
}

function isZipFile {
    # ファイルの先頭がZIPのシグネチャ（PK\x03\x04）かどうか。
    # パスワード付きのOfficeファイルや旧形式は、拡張子が .docx 等でもZIPではない
    param (
        [string]$path
    )

    $stream = [System.IO.File]::OpenRead((toLongPath $path))
    try {
        $head = New-Object byte[] 4
        $read = $stream.Read($head, 0, 4)
        return ($read -eq 4 -and $head[0] -eq 0x50 -and $head[1] -eq 0x4B -and $head[2] -eq 0x03 -and $head[3] -eq 0x04)
    } finally {
        $stream.Dispose()
    }
}

function isCompoundFile {
    # ファイルの先頭が複合ドキュメント形式（旧形式の .doc / .ppt、パスワード付きのOfficeファイル）のシグネチャかどうか
    param (
        [string]$path
    )

    $signature = [byte[]](0xD0, 0xCF, 0x11, 0xE0, 0xA1, 0xB1, 0x1A, 0xE1)
    $stream = [System.IO.File]::OpenRead((toLongPath $path))
    try {
        $head = New-Object byte[] 8
        if ($stream.Read($head, 0, 8) -ne 8) {
            return $false
        }
        for ($i = 0; $i -lt 8; $i++) {
            if ($head[$i] -ne $signature[$i]) {
                return $false
            }
        }
        return $true
    } finally {
        $stream.Dispose()
    }
}

# 読み取りのスレッド（runspace）ごとに使い回す、部品の読み取り用の入れ物。大きな部品を読むときに、
# 部品の大きさぶんの配列を毎回確保しない（ラージオブジェクトヒープに乗らない大きさ（85,000 バイト
# 未満。既定 32768 バイト）にとどめ、GC の負担を減らす）
$script:zipReadBufferSize = 32768
$script:zipReadBuffer = $null

function checkZipEntrySize {
    # 部品の展開後の大きさ（entry.Length）を、部品ごとの上限（zipPartMaxBytes）と1ファイルの合計の上限
    # （zipTotalMaxBytes）に照らして数え、超えれば ZipSizeLimitException にする。超えなければ大きさを返す
    # （readZipEntry・readZipEntryBytes が、読む前に呼ぶ。合計は「確保する大きさ」で数える）
    param (
        [System.IO.Compression.ZipArchiveEntry]$entry,
        [string]$entryName
    )

    $length = $entry.Length
    if ($length -gt $script:zipPartMaxBytes) {
        throw [ZipSizeLimitException]::new($script:zipTooLargeMessage, $entryName, $length, "Part")
    }
    $script:zipTotalReadBytes += $length
    if ($script:zipTotalReadBytes -gt $script:zipTotalMaxBytes) {
        throw [ZipSizeLimitException]::new($script:zipTooLargeMessage, $entryName, $script:zipTotalReadBytes, "Total")
    }
    return $length
}

function readZipEntryBytes {
    # ZIP内のファイルをバイト列で返す。無ければ $null（埋め込んだファイルを読むときに使う。ふつうの部品は readZipEntry）。
    # 大きさの数え方と上限は readZipEntry と同じ。バイト列は申告の大きさ（entry.Length。上限の範囲内）だけ確保し、
    # 読み終えたあとにもう 1 バイト読めたら、中身がヘッダーより長い（偽りのヘッダー）として部品ごとの上限の超過にする
    param (
        [System.IO.Compression.ZipArchive]$zip,
        [string]$entryName
    )

    $entry = $zip.GetEntry($entryName)
    if ($null -eq $entry) {
        return $null
    }

    $length = checkZipEntrySize $entry $entryName
    $bytes = New-Object byte[] ([int]$length)
    $filled = 0
    $stream = $entry.Open()
    try {
        while ($filled -lt $length) {
            $read = $stream.Read($bytes, $filled, [int]($length - $filled))
            if ($read -le 0) {
                break
            }
            $filled += $read
        }
        if ($filled -eq $length -and $stream.ReadByte() -ge 0) {
            throw [ZipSizeLimitException]::new($script:zipTooLargeMessage, $entryName, $length + 1, "Part")
        }
    } finally {
        $stream.Dispose()
    }
    if ($filled -lt $length) {
        $shortBytes = New-Object byte[] $filled
        [System.Array]::Copy($bytes, $shortBytes, $filled)
        $bytes = $shortBytes
    }
    return , $bytes
}

function readZipEntry {
    # ZIP内のファイルを文字列で返す。無ければ $null。
    #
    # 展開後の大きさ（entry.Length。中央ディレクトリの値）が部品ごとの上限（zipPartMaxBytes）を超える、
    # または1ファイルの合計（zipTotalReadBytes）が合計の上限（zipTotalMaxBytes）を超えると例外にする。
    # 合計は、実際に読んだ量ではなく「確保する大きさ」（entry.Length）で、読む前に数える
    # （ヘッダーの大きさを偽って中身を小さくした部品を並べても、合計の上限で打ち切るため）。
    #
    # entry.Length の値は、細工して実際より小さく書き換えられる（偽りのヘッダー）。これを見つけるため、
    # 実際に読む量を Length + 1 バイトまでに絞る（入れ物は小さく使い回し、1回ごとの Stream.Read の
    # 要求バイト数を「残り（Length + 1 - 既読量）」で頭打ちにする）。既読量が Length + 1 バイトに届いたら、
    # 中身がヘッダーより長いと分かるので、そこで止めて例外にする。展開はここで必ず止まり、
    # 上限のバイト数を超えて進まない（部品の大きさぶんの配列は作らない）。
    #
    # 読んだバイト列は、今までの StreamReader（UTF-8を指定し、BOMを見て文字コードを決める）と同じ規則で
    # 文字列にする（BOM付きUTF-8・UTF-16 LE/BEを見分け、無ければUTF-8）。入れ物（$script:zipReadBuffer）に
    # 入った分だけ Decoder で文字に直し、StringBuilder に積む（文字の境界がまたがっても Decoder が覚える）
    param (
        [System.IO.Compression.ZipArchive]$zip,
        [string]$entryName
    )

    $entry = $zip.GetEntry($entryName)
    if ($null -eq $entry) {
        return $null
    }

    $length = checkZipEntrySize $entry $entryName

    if ($null -eq $script:zipReadBuffer) {
        # BOM の見分けに先頭 3 バイトが要るため、3 より小さくしない
        $script:zipReadBuffer = New-Object byte[] ([Math]::Max(3, $script:zipReadBufferSize))
    }
    $buffer = $script:zipReadBuffer
    $budget = $length + 1  # 偽りのヘッダーを見つけるため、読む量はこれより増やさない
    $totalRead = 0L
    $sb = New-Object System.Text.StringBuilder  # 容量は渡さない（申告の大きさぶんを先に確保しないため）
    $decoder = $null
    $charBuffer = $null
    $first = $true

    $stream = $entry.Open()
    try {
        while ($totalRead -lt $budget) {
            $want = [Math]::Min($buffer.Length, [long]($budget - $totalRead))
            $filled = 0
            $endOfStream = $false
            while ($filled -lt $want) {
                $read = $stream.Read($buffer, $filled, [int]($want - $filled))
                if ($read -le 0) {
                    $endOfStream = $true
                    break
                }
                $filled += $read
            }
            $totalRead += $filled
            if ($totalRead -gt $length) {
                # 中身がヘッダーの値より長い（偽りのヘッダー）。実際の大きさは分からないため、検出できた時点の値を記録する
                throw [ZipSizeLimitException]::new($script:zipTooLargeMessage, $entryName, $totalRead, "Part")
            }

            $byteOffset = 0
            if ($first) {
                $first = $false
                $encoding = [System.Text.Encoding]::UTF8
                if ($filled -ge 3 -and $buffer[0] -eq 0xEF -and $buffer[1] -eq 0xBB -and $buffer[2] -eq 0xBF) {
                    $byteOffset = 3
                } elseif ($filled -ge 2 -and $buffer[0] -eq 0xFF -and $buffer[1] -eq 0xFE) {
                    $encoding = [System.Text.Encoding]::Unicode
                    $byteOffset = 2
                } elseif ($filled -ge 2 -and $buffer[0] -eq 0xFE -and $buffer[1] -eq 0xFF) {
                    $encoding = [System.Text.Encoding]::BigEndianUnicode
                    $byteOffset = 2
                }
                $decoder = $encoding.GetDecoder()
                $charBuffer = New-Object char[] ($encoding.GetMaxCharCount($buffer.Length))
            }
            $byteCount = $filled - $byteOffset
            if ($byteCount -gt 0) {
                $charCount = $decoder.GetChars($buffer, $byteOffset, $byteCount, $charBuffer, 0, $false)
                if ($charCount -gt 0) {
                    [void]$sb.Append($charBuffer, 0, $charCount)
                }
            }
            if ($endOfStream) {
                break
            }
        }
        if ($null -ne $decoder) {
            # 最後にDecoderの中に残っている分（サロゲートペアの前半など）を吐き出させる
            $charCount = $decoder.GetChars([byte[]]@(), 0, 0, $charBuffer, 0, $true)
            if ($charCount -gt 0) {
                [void]$sb.Append($charBuffer, 0, $charCount)
            }
        }
    } finally {
        $stream.Dispose()
    }

    return $sb.ToString()
}

function resolveZipPath {
    # リレーションシップの Target（相対パス）を、ZIP内のパスに変換する
    param (
        [string]$baseDir,   # 例: "ppt/slides"
        [string]$target     # 例: "../notesSlides/notesSlide1.xml"
    )

    if ($target.StartsWith("/")) {
        return $target.TrimStart("/")
    }

    $parts = New-Object System.Collections.Generic.List[string]
    foreach ($part in (("$baseDir/$target") -split "/")) {
        if ($part -eq "..") {
            if ($parts.Count -gt 0) { $parts.RemoveAt($parts.Count - 1) }
        } elseif ($part -ne "" -and $part -ne ".") {
            $parts.Add($part)
        }
    }
    return ($parts -join "/")
}

function newXmlDocument {
    # XML文字列から XmlDocument を作る。既存の New-Object + LoadXml と同じ挙動
    # （文字の検査はせず、余白は詰める）にしつつ、DTD（<!DOCTYPE ...>）の処理を禁止する。
    # DTDの実体参照を入れ子にして膨張させる攻撃（billion laughs）を防ぐため
    # （readXmlLines と同じ禁止を、LoadXmlを使うすべての呼び出し元にも揃える）
    param (
        [string]$xml
    )

    $settings = New-Object System.Xml.XmlReaderSettings
    $settings.DtdProcessing = [System.Xml.DtdProcessing]::Prohibit
    $settings.XmlResolver = $null
    $settings.CheckCharacters = $false
    $reader = [System.Xml.XmlReader]::Create((New-Object System.IO.StringReader($xml)), $settings)
    try {
        $doc = New-Object System.Xml.XmlDocument
        $doc.PreserveWhitespace = $false
        $doc.Load($reader)
        return , $doc  # XmlDocument は IEnumerable なので、, を付けないとパイプラインで展開される
    } finally {
        $reader.Dispose()
    }
}

function readRelationships {
    # .rels ファイルを読み、Id → @{ Type; Target（ZIP内のパス） } の辞書を返す
    param (
        [System.IO.Compression.ZipArchive]$zip,
        [string]$partName   # 例: "ppt/slides/slide1.xml"
    )

    $dir = [System.IO.Path]::GetDirectoryName($partName).Replace("\", "/")
    $relsName = "$dir/_rels/$([System.IO.Path]::GetFileName($partName)).rels"

    $result = @{}
    $xml = readZipEntry $zip $relsName
    if ($null -eq $xml) {
        return $result
    }

    $doc = newXmlDocument $xml
    foreach ($rel in $doc.GetElementsByTagName("Relationship", ${nsPkgRel})) {
        if ($rel.GetAttribute("TargetMode") -eq "External") {
            continue
        }
        $result[$rel.GetAttribute("Id")] = @{
            Type   = $rel.GetAttribute("Type")
            Target = resolveZipPath $dir $rel.GetAttribute("Target")
        }
    }
    return $result
}

function readXmlLines {
    # WordprocessingML / DrawingML のXMLから、段落・表の行ごとのテキストを文書順に返す。
    # 戻り値: @{ Page = ページ番号; Text = テキスト } の配列
    #
    # ・表の1行はセルをタブ区切りにして1行とする（セル内の複数段落はスペース区切り）
    # ・テキストボックス内の段落は、それぞれ1行とする
    # ・互換用の代替表示（mc:Fallback）は、同じ内容が重複するため読まない
    # ・ページは、手動の改ページ・段落前で改ページ・セクション区切り（連続以外）で数える。
    #   $pageMode = "rendered" の場合は、Wordが保存時に記録したページ区切り（lastRenderedPageBreak）でも数える。
    #   ただし手動の改ページ等の直後（本文が出る前）の lastRenderedPageBreak は同じ区切りなので数えない
    #   （Wordは手動の改ページの後に lastRenderedPageBreak を記録する場合としない場合がある）
    #   $pageMode = "none" の場合はページを数えない（PowerPoint）
    # ・PowerPoint: $onlyPlaceholders を指定すると、その種類のプレースホルダー（例: "ftr"）のテキストだけを読む。
    #   指定しない場合は、スライド番号・日付・ヘッダー・フッター・スライド画像のプレースホルダーを読まない
    # ・$objects（リスト）を渡すと、本文以外の文字の在りかを、ページ付きでそこに集める（渡さなければ今までどおり）:
    #     @{ Kind = "shape";   Page; Text }   Word のテキストボックス・図形内の文字（本文の行には入れない。段落はスペースでつなぐ）
    #     @{ Kind = "diagram"; Page; RelId }  SmartArt（dgm:relIds の r:dm。データはリレーションシップの先）
    #     @{ Kind = "chart";   Page; RelId }  グラフ（c:chart の r:id）
    #     @{ Kind = "comment"; Page; Id }     コメントの参照（w:commentReference の w:id）
    #     @{ Kind = "embed";   Page; RelId }  埋め込んだファイル（Word は o:OLEObject（Type="Embed"）・w:objectEmbed、
    #                                         PowerPoint は p:oleObj の r:id。リレーションシップの先は呼び出し元が読む）
    param (
        [string]$xml,
        [string]$ns,
        [string]$pageMode = "none",
        [string[]]$onlyPlaceholders = $null,
        [System.Collections.Generic.List[object]]$objects = $null
    )

    # 要素・テキストごとに呼ぶため、PowerShell で遅い書き方（スクリプトブロックの呼び出し・switch・型名の解決・
    # PSCustomObject の作成）を避けている（段落 3,000 の文書で約 2 秒かかっていた）。出力は以前と同じ
    $lines = New-Object System.Collections.Generic.List[object]
    # 開いている段落（p）・表の行（tr）・セル（tc）。種類ごとに積み、最も内側は末尾（XmlReader は開始と終了の対応を保証する）
    $pFrames = New-Object System.Collections.Generic.List[hashtable]
    $trFrames = New-Object System.Collections.Generic.List[hashtable]
    $tcFrames = New-Object System.Collections.Generic.List[hashtable]
    $page = 1
    $breakPending = $false  # 手動の改ページ等の後、まだ本文が出ていない
    $inText = $false
    $inSectPr = $false
    $skipShapeText = $false
    # 開いているテキストボックス（$objects を渡したときだけ使う）。TcBase は開いた時点のセルの数（テキストボックスの外のセル）
    $collect = ($null -ne $objects)
    $boxFrames = New-Object System.Collections.Generic.List[hashtable]

    $elementType = [System.Xml.XmlNodeType]::Element
    $endElementType = [System.Xml.XmlNodeType]::EndElement
    $textType = [System.Xml.XmlNodeType]::Text
    $significantWhitespaceType = [System.Xml.XmlNodeType]::SignificantWhitespace
    $whitespaceType = [System.Xml.XmlNodeType]::Whitespace
    $cdataType = [System.Xml.XmlNodeType]::CDATA
    $onlyMode = ($null -ne $onlyPlaceholders)

    $settings = New-Object System.Xml.XmlReaderSettings
    $settings.DtdProcessing = [System.Xml.DtdProcessing]::Prohibit
    $reader = [System.Xml.XmlReader]::Create((New-Object System.IO.StringReader($xml)), $settings)
    try {
        $hasNode = $reader.Read()
        while ($hasNode) {
            $nodeType = $reader.NodeType

            if ($nodeType -eq $elementType) {
                $name = $reader.LocalName
                $uri = $reader.NamespaceURI
                $isEmpty = $reader.IsEmptyElement

                # 読み飛ばす要素（Skip() で次の要素に進むため、Read() はしない）
                $skip = $false
                if ($uri -eq ${nsCompat} -and $name -eq "Fallback") {
                    $skip = $true
                } elseif ($uri -eq ${nsWord} -and $name -eq "moveFrom") {
                    $skip = $true  # 変更履歴の移動元（移動先と重複する）
                } elseif ($uri -eq ${nsPresent} -and $name -eq "txBody" -and $skipShapeText) {
                    $skip = $true
                } elseif ($uri -eq ${nsPresent} -and $name -eq "graphicFrame" -and $onlyMode) {
                    $skip = $true  # 表など（プレースホルダーではない）
                } elseif ($uri -eq $ns -and $name -eq "rPr" -and -not $isEmpty) {
                    $skip = $true  # 文字の書式（テキストを含まない。1 文字ごとに付くことも多く、読むだけで時間がかかる）
                }
                if ($skip) {
                    $reader.Skip()
                    $hasNode = -not $reader.EOF
                    continue
                }

                if ($uri -eq $ns) {
                    if ($name -eq "p") {
                        if (-not $isEmpty) {
                            $pFrames.Add(@{ Text = (New-Object System.Text.StringBuilder); Page = $null; BreakAfter = $false })
                        }
                    } elseif ($name -eq "tr") {
                        if (-not $isEmpty) {
                            $trFrames.Add(@{ Cells = (New-Object System.Collections.Generic.List[string]); Page = $null })
                        }
                    } elseif ($name -eq "tc") {
                        if ($isEmpty) {
                            if ($trFrames.Count -gt 0) { $trFrames[$trFrames.Count - 1].Cells.Add("") }
                        } else {
                            $tcFrames.Add(@{ Text = (New-Object System.Text.StringBuilder); Page = $null })
                        }
                    } elseif ($name -eq "t") {
                        $inText = -not $isEmpty
                    } elseif ($name -eq "tab" -or $name -eq "cr" -or $name -eq "noBreakHyphen") {
                        if ($pFrames.Count -gt 0) {
                            [void]$pFrames[$pFrames.Count - 1].Text.Append($(if ($name -eq "noBreakHyphen") { "-" } else { " " }))
                        }
                    } elseif ($name -eq "br") {
                        $breakType = $reader.GetAttribute("type", $ns)
                        if ($breakType -ne "page" -and $breakType -ne "column") {
                            if ($pFrames.Count -gt 0) {
                                [void]$pFrames[$pFrames.Count - 1].Text.Append(" ")
                            }
                        } elseif ($pageMode -ne "none" -and $breakType -eq "page") {
                            $page++
                            $breakPending = $true
                        }
                    } elseif ($name -eq "lastRenderedPageBreak") {
                        if ($pageMode -eq "rendered") {
                            if ($breakPending) {
                                $breakPending = $false
                            } else {
                                $page++
                            }
                        }
                    } elseif ($name -eq "pageBreakBefore") {
                        if ($pageMode -ne "none" -and $reader.GetAttribute("val", $ns) -notin @("0", "false", "off")) {
                            $page++
                            $breakPending = $true
                        }
                    } elseif ($name -eq "sectPr") {
                        # 段落内のセクション区切り: 既定（次のページから開始）なら、段落の後で改ページ
                        if ($pageMode -ne "none" -and $pFrames.Count -gt 0) {
                            $inSectPr = -not $isEmpty
                            $pFrames[$pFrames.Count - 1].BreakAfter = $true
                        }
                    } elseif ($name -eq "type") {
                        if ($inSectPr -and $reader.GetAttribute("val", $ns) -eq "continuous") {
                            if ($pFrames.Count -gt 0) { $pFrames[$pFrames.Count - 1].BreakAfter = $false }
                        }
                    } elseif ($collect -and $name -eq "txbxContent") {
                        if (-not $isEmpty) {
                            $boxFrames.Add(@{ Lines = (New-Object System.Collections.Generic.List[string]); Page = $page; TcBase = $tcFrames.Count })
                        }
                    } elseif ($collect -and $name -eq "commentReference") {
                        $objects.Add(@{ Kind = "comment"; Page = $page; Id = $reader.GetAttribute("id", $ns) })
                    } elseif ($collect -and $name -eq "objectEmbed") {
                        $objects.Add(@{ Kind = "embed"; Page = $page; RelId = $reader.GetAttribute("id", ${nsRel}) })
                    }
                } elseif ($collect -and $uri -eq ${nsOffice} -and $name -eq "OLEObject") {
                    if ($reader.GetAttribute("Type") -eq "Embed") {
                        $objects.Add(@{ Kind = "embed"; Page = $page; RelId = $reader.GetAttribute("id", ${nsRel}) })
                    }
                } elseif ($collect -and $uri -eq ${nsDiagram} -and $name -eq "relIds") {
                    $objects.Add(@{ Kind = "diagram"; Page = $page; RelId = $reader.GetAttribute("dm", ${nsRel}) })
                } elseif ($collect -and $uri -eq ${nsChart} -and $name -eq "chart") {
                    $objects.Add(@{ Kind = "chart"; Page = $page; RelId = $reader.GetAttribute("id", ${nsRel}) })
                } elseif ($uri -eq ${nsPresent}) {
                    if ($name -eq "sp") {
                        $skipShapeText = $onlyMode
                    } elseif ($name -eq "ph") {
                        if ($onlyMode) {
                            $skipShapeText = ($reader.GetAttribute("type") -notin $onlyPlaceholders)
                        } else {
                            $skipShapeText = ($reader.GetAttribute("type") -in ${skipPlaceholderTypes})
                        }
                    } elseif ($collect -and $name -eq "oleObj") {
                        $objects.Add(@{ Kind = "embed"; Page = $page; RelId = $reader.GetAttribute("id", ${nsRel}) })
                    }
                }
            } elseif ($nodeType -eq $endElementType) {
                if ($reader.NamespaceURI -eq $ns) {
                    $name = $reader.LocalName
                    # 段落・表の行が終わったら、テキストを親のセルに追加する。セルの中でなければ1行として出力する
                    $text = $null
                    if ($name -eq "t") {
                        $inText = $false
                    } elseif ($name -eq "sectPr") {
                        $inSectPr = $false
                    } elseif ($name -eq "p") {
                        $p = $pFrames[$pFrames.Count - 1]
                        $pFrames.RemoveAt($pFrames.Count - 1)
                        $text = $p.Text.ToString().Trim()
                        $textPage = $p.Page
                        $separator = " "
                        if ($p.BreakAfter) {
                            $page++
                            $breakPending = $true
                        }
                    } elseif ($name -eq "tc") {
                        $cell = $tcFrames[$tcFrames.Count - 1]
                        $tcFrames.RemoveAt($tcFrames.Count - 1)
                        if ($trFrames.Count -gt 0) {
                            $row = $trFrames[$trFrames.Count - 1]
                            $row.Cells.Add($cell.Text.ToString())
                            if ($null -eq $row.Page) {
                                $row.Page = $cell.Page
                            }
                        }
                    } elseif ($name -eq "tr") {
                        $row = $trFrames[$trFrames.Count - 1]
                        $trFrames.RemoveAt($trFrames.Count - 1)
                        # 入れ子の表の行は、外側のセルの中ではスペース区切りにする（テキストボックスの外のセルは数えない）
                        $cellBase = $(if ($boxFrames.Count -gt 0) { $boxFrames[$boxFrames.Count - 1].TcBase } else { 0 })
                        $text = ($row.Cells -join $(if ($tcFrames.Count -gt $cellBase) { " " } else { "`t" })).TrimEnd()
                        $textPage = $(if ($null -ne $row.Page) { $row.Page } else { $page })
                        $separator = " "
                    } elseif ($name -eq "txbxContent" -and $boxFrames.Count -gt 0) {
                        # テキストボックスが終わったら、段落をスペースでつないで図形 1 つにする
                        $box = $boxFrames[$boxFrames.Count - 1]
                        $boxFrames.RemoveAt($boxFrames.Count - 1)
                        if ($box.Lines.Count -gt 0) {
                            $objects.Add(@{ Kind = "shape"; Page = $box.Page; Text = ($box.Lines -join " ") })
                        }
                    }
                    if ($text) {
                        # テキストボックスの中（その中のセルは除く）なら、テキストボックスの行にする
                        $box = $null
                        if ($boxFrames.Count -gt 0 -and $tcFrames.Count -le $boxFrames[$boxFrames.Count - 1].TcBase) {
                            $box = $boxFrames[$boxFrames.Count - 1]
                        }
                        if ($box) {
                            $box.Lines.Add($text)
                        } elseif ($tcFrames.Count -gt 0) {
                            $cell = $tcFrames[$tcFrames.Count - 1]
                            if ($cell.Text.Length -gt 0) {
                                [void]$cell.Text.Append($separator)
                            }
                            [void]$cell.Text.Append($text)
                            if ($null -eq $cell.Page) {
                                $cell.Page = $textPage
                            }
                        } else {
                            $lines.Add([pscustomobject]@{ Page = $textPage; Text = $text })
                        }
                    }
                }
            } elseif ($inText -and ($nodeType -eq $textType -or $nodeType -eq $significantWhitespaceType -or
                                    $nodeType -eq $whitespaceType -or $nodeType -eq $cdataType)) {
                if ($pFrames.Count -gt 0) {
                    $p = $pFrames[$pFrames.Count - 1]
                    if ($null -eq $p.Page) {
                        $p.Page = $page
                    }
                    $value = $reader.Value
                    [void]$p.Text.Append($value.Replace("`t", " ").Replace("`r", " ").Replace("`n", " "))
                    if ($value.Trim() -ne "") {
                        $breakPending = $false
                    }
                }
            }

            $hasNode = $reader.Read()
        }
    } finally {
        $reader.Dispose()
    }

    return $lines.ToArray()
}

function addUnitLines {
    # ユニット（順序付き辞書）に行を追加する
    param (
        [System.Collections.Specialized.OrderedDictionary]$units,
        [string]$unitName,
        [string[]]$lines
    )

    if (-not $units.Contains($unitName)) {
        $units[$unitName] = New-Object System.Collections.Generic.List[string]
    }
    foreach ($line in $lines) {
        $units[$unitName].Add($line)
    }
}

function readDiagramText {
    # SmartArt のデータ（diagrams/dataN.xml）の文字を、スペースでつないで 1 つにする。
    # 同じ文字の描画用（diagrams/drawingN.xml）は、重複するため読まない
    param (
        [string]$xml
    )

    return (@(readXmlLines $xml ${nsDrawing} | ForEach-Object { $_.Text }) -join " ")
}

function readChartTxText {
    # c:tx（グラフのタイトル・軸ラベル・系列名で使う、文字を持つ要素）の文字を返す。
    # セル参照（c:strRef/c:strCache/c:pt/c:v）と直値（c:v）の両方を読む。c:rich（a:p）は呼び出し元が別に読む
    param (
        [System.Xml.XmlElement]$parent
    )

    $found = New-Object System.Collections.Generic.List[string]
    foreach ($child in $parent.ChildNodes) {
        if ($child.LocalName -ne "tx") {
            continue
        }
        foreach ($v in $child.GetElementsByTagName("v", ${nsChart})) {
            $text = $v.InnerText.Trim()
            if ($text -ne "") { $found.Add($text) }
        }
        break
    }
    return $found
}

function readChartText {
    # グラフ（charts/chartN.xml）の文字（タイトル・軸ラベル・系列名）を、スペースでつないで 1 つにする。
    # 項目名（横軸の項目。c:cat。点の数だけある）と数値（c:val）は読まない。同じ文字は 1 回だけにする。
    # 系列（c:ser）とタイトル・軸（c:title）の数だけ調べるため、項目の点数が多いグラフでも遅くならない
    param (
        [string]$xml
    )

    $texts = New-Object System.Collections.Generic.List[string]
    $seen = New-Object System.Collections.Generic.HashSet[string]
    # タイトル・軸ラベル（c:rich の a:p。手で直したデータラベルの文字も同じ形のため、ここで読む）
    foreach ($line in (readXmlLines $xml ${nsDrawing})) {
        if ($seen.Add($line.Text)) { $texts.Add($line.Text) }
    }
    $doc = newXmlDocument $xml
    # タイトル・軸ラベルのうち、セル参照の文字（c:title/c:tx/c:strRef/c:strCache/c:pt/c:v。直値の c:rich は上で読み済み）
    foreach ($title in $doc.GetElementsByTagName("title", ${nsChart})) {
        foreach ($text in (readChartTxText $title)) {
            if ($seen.Add($text)) { $texts.Add($text) }
        }
    }
    # 系列名（c:ser/c:tx の文字。セル参照なら c:strRef/c:strCache/c:pt/c:v、直値なら c:v）
    foreach ($ser in $doc.GetElementsByTagName("ser", ${nsChart})) {
        foreach ($text in (readChartTxText $ser)) {
            if ($seen.Add($text)) { $texts.Add($text) }
        }
    }
    return ($texts -join " ")
}

function readObjectText {
    # readXmlLines が集めた SmartArt・グラフの参照（RelId）から、その文字を返す（読めなければ空）
    param (
        [System.IO.Compression.ZipArchive]$zip,
        [hashtable]$rels,   # readRelationships の結果
        $object
    )

    $rel = $rels[[string]$object.RelId]
    if ($null -eq $rel) {
        return ""
    }
    $xml = readZipEntry $zip $rel.Target
    if ($null -eq $xml) {
        return ""
    }
    if ($object.Kind -eq "diagram") {
        return (readDiagramText $xml)
    }
    return (readChartText $xml)
}

function readWordComments {
    # Word のコメント（word/comments.xml）を、w:id → 文字（段落をスペースでつなぐ）の辞書で返す。
    # 返信も別のコメント（別の w:id）として入っている。作成者名は読まない
    param (
        [string]$xml
    )

    $comments = @{}
    if (-not $xml) {
        return $comments  # コメントが無い（[string] の引数は $null を空文字にする）
    }
    $doc = newXmlDocument $xml
    foreach ($comment in $doc.GetElementsByTagName("comment", ${nsWord})) {
        $text = @(readXmlLines $comment.OuterXml ${nsWord} | ForEach-Object { $_.Text }) -join " "
        if ($text -ne "") {
            $comments[$comment.GetAttribute("id", ${nsWord})] = $text
        }
    }
    return $comments
}

function readSlideComments {
    # PowerPoint のスライドのコメントを、コメント・返信ごとの文字の配列で返す（作成者名は読まない）。
    #   旧形式（ppt/comments/commentN.xml）: p:cm の p:text
    #   新形式（ppt/comments/modernComment_*.xml）: p188:cm の p188:txBody と、返信（p188:reply）の p188:txBody
    param (
        [string]$xml
    )

    $texts = New-Object System.Collections.Generic.List[string]
    $doc = newXmlDocument $xml
    foreach ($cm in @($doc.SelectNodes("//*") | Where-Object { $_.LocalName -eq "cm" })) {
        if ($cm.NamespaceURI -eq ${nsPresent}) {
            $body = @($cm.ChildNodes | Where-Object { $_.LocalName -eq "text" })
            if ($body.Count -gt 0 -and $body[0].InnerText.Trim() -ne "") { $texts.Add($body[0].InnerText.Trim()) }
            continue
        }
        # 新形式: XML では返信の一覧（replyLst）が本文（txBody）より前にあるため、本文を先に出してから返信を出す
        $bodies = @($cm.ChildNodes | Where-Object { $_.LocalName -eq "txBody" })
        foreach ($reply in @($cm.ChildNodes | Where-Object { $_.LocalName -eq "replyLst" } | ForEach-Object { $_.ChildNodes } | Where-Object { $_.LocalName -eq "reply" })) {
            $bodies += @($reply.ChildNodes | Where-Object { $_.LocalName -eq "txBody" })
        }
        foreach ($body in $bodies) {
            $text = @(readXmlLines $body.OuterXml ${nsDrawing} | ForEach-Object { $_.Text }) -join " "
            if ($text -ne "") { $texts.Add($text) }
        }
    }
    return $texts.ToArray()
}

function readDocxUnits {
    # Word（.docx / .docm）のテキストを、ページ・ヘッダー/フッター・脚注ごとに返す。
    # 本文のテキストボックス・図形内の文字と SmartArt・グラフの文字は "ページNNN[図形]"、
    # コメントは "ページNNN[コメント]"（コメントを付けた所のページ）に分ける（1 行は図形・コメント 1 つ）。
    # 埋め込んだ Office のファイルの文字は "ページNNN[埋め込み<N>]"（N は 1 ファイルの中の、参照の順の通し番号。
    # 読まなかったものは欠番。office_embedded.ps1）。
    # $failures・$sizeFailures を渡すと、読めなかった埋め込みの部品の名前と、大きさの上限の例外を追加する
    # （呼び出し元がインデックス作成のログに書く。shared/ はツールを知らないため、ここでは書かない）。
    # ファイルを開き、合計（zipTotalReadBytes）を 0 から数え直して、閉じる。読む本体は readDocxUnitsFromZip
    param (
        [string]$path,
        [System.Collections.Generic.List[string]]$failures = $null,
        [System.Collections.Generic.List[object]]$sizeFailures = $null
    )

    $script:zipTotalReadBytes = 0  # このファイル1つ分の、readZipEntryが読む合計（zipTotalMaxBytes）を0から数え直す
    $zip = [System.IO.Compression.ZipFile]::OpenRead((toLongPath $path))
    try {
        return (readDocxUnitsFromZip $zip $true $failures $sizeFailures)
    } finally {
        $zip.Dispose()
    }
}

function readDocxUnitsFromZip {
    # 開いた Word の ZipArchive から、readDocxUnits と同じユニットを返す（開く・閉じる・合計の数え直しはしない）。
    # $readEmbeds が $false なら埋め込みは読まない（埋め込みの中の Word 文書を読むとき。深さは 1 段まで）
    param (
        [System.IO.Compression.ZipArchive]$zip,
        [bool]$readEmbeds,
        [System.Collections.Generic.List[string]]$failures = $null,
        [System.Collections.Generic.List[object]]$sizeFailures = $null
    )

    $units = New-Object System.Collections.Specialized.OrderedDictionary
    $body = readZipEntry $zip "word/document.xml"
    if ($null -eq $body) {
        throw "Word文書の本文（word/document.xml）がありません。"
    }

    # Wordで保存されたファイルには、保存時点のページ区切りが記録されている。無ければ手動の改ページで数える
    $pageMode = $(if ($body.Contains("lastRenderedPageBreak")) { "rendered" } else { "explicit" })
    # 本文は行数が多いため、1行ずつ addUnitLines を呼ばずにページのユニットへ入れる（結果は addUnitLines と同じ）
    $lastPage = $null
    $pageLines = $null
    $objects = New-Object System.Collections.Generic.List[object]
    foreach ($line in (readXmlLines $body ${nsWord} $pageMode $null $objects)) {
        if ($null -eq $pageLines -or $line.Page -ne $lastPage) {
            $unitName = "ページ{0:D3}" -f $line.Page
            if (-not $units.Contains($unitName)) {
                $units[$unitName] = New-Object System.Collections.Generic.List[string]
            }
            $pageLines = $units[$unitName]
            $lastPage = $line.Page
        }
        $pageLines.Add($line.Text)
    }

    # 本文の XML の文字列は、ここから先で使わない。埋め込みを読む前に放す（同時に持つメモリを抑える）
    $body = $null

    # 図形（テキストボックス・SmartArt・グラフ）・コメント・埋め込み。文書の中の順に、そのページの場所へ入れる
    $rels = readRelationships $zip "word/document.xml"
    $comments = readWordComments (readZipEntry $zip "word/comments.xml")
    $usedComments = New-Object System.Collections.Generic.HashSet[string]
    $embedState = newEmbeddedState
    foreach ($object in $objects) {
        $base = "ページ{0:D3}" -f $object.Page
        if ($object.Kind -eq "shape") {
            addUnitLines $units "${base}[図形]" @($object.Text)
        } elseif ($object.Kind -eq "comment") {
            $id = [string]$object.Id
            if ($comments.ContainsKey($id) -and $usedComments.Add($id)) {
                addUnitLines $units "${base}[コメント]" @($comments[$id])
            }
        } elseif ($object.Kind -eq "embed") {
            if ($readEmbeds) {
                $embedded = readEmbeddedObjectLines $zip $rels $object $embedState $failures $sizeFailures
                if ($null -ne $embedded -and $embedded.Lines.Count -gt 0) {
                    addUnitLines $units "${base}[埋め込み$($embedded.Number)]" $embedded.Lines
                }
            }
        } else {
            $text = readObjectText $zip $rels $object
            if ($text -ne "") {
                addUnitLines $units "${base}[図形]" @($text)
            }
        }
    }
    # 本文に参照の無いコメント（ヘッダー・脚注に付けたものなど）は、場所が分からないため "文書[コメント]" にまとめる
    foreach ($id in @($comments.Keys | Sort-Object { $n = 0; [void][int]::TryParse($_, [ref]$n); $n })) {
        if (-not $usedComments.Contains($id)) {
            addUnitLines $units "文書[コメント]" @($comments[$id])
        }
    }

    # ヘッダー・フッター（セクションごとに同じ内容が並ぶため、重複は除く）
    $seen = New-Object System.Collections.Generic.HashSet[string]
    $parts = @($zip.Entries | Where-Object { $_.FullName -match "^word/(header|footer)\d*\.xml$" } |
        Sort-Object { $_.FullName -notmatch "/header" }, FullName)  # ヘッダー → フッターの順
    foreach ($part in $parts) {
        foreach ($line in (readXmlLines (readZipEntry $zip $part.FullName) ${nsWord})) {
            if ($seen.Add($line.Text)) {
                addUnitLines $units "ヘッダー・フッター" @($line.Text)
            }
        }
    }

    # 脚注・文末脚注
    foreach ($partName in @("word/footnotes.xml", "word/endnotes.xml")) {
        $xml = readZipEntry $zip $partName
        if ($null -ne $xml) {
            addUnitLines $units "脚注" @(readXmlLines $xml ${nsWord} | ForEach-Object { $_.Text })
        }
    }

    return $units
}

function readPptxUnits {
    # PowerPoint（.pptx / .pptm）のテキストを、スライド・ノートごと（スライドの表示順）と、
    # スライドのフッター（全スライド分をまとめ、重複を除く）に分けて返す。
    # 埋め込んだ Office のファイルの文字は "スライドNNN[埋め込み<N>]"（N は 1 ファイルの中の、参照の順の通し番号。
    # 読まなかったものは欠番。office_embedded.ps1）。
    # $failures・$sizeFailures の意味と、ファイルの開閉・合計の数え直しは readDocxUnits と同じ。読む本体は readPptxUnitsFromZip
    param (
        [string]$path,
        [System.Collections.Generic.List[string]]$failures = $null,
        [System.Collections.Generic.List[object]]$sizeFailures = $null
    )

    $script:zipTotalReadBytes = 0  # このファイル1つ分の、readZipEntryが読む合計（zipTotalMaxBytes）を0から数え直す
    $zip = [System.IO.Compression.ZipFile]::OpenRead((toLongPath $path))
    try {
        return (readPptxUnitsFromZip $zip $true $failures $sizeFailures)
    } finally {
        $zip.Dispose()
    }
}

function readPptxUnitsFromZip {
    # 開いた PowerPoint の ZipArchive から、readPptxUnits と同じユニットを返す（開く・閉じる・合計の数え直しはしない）。
    # $readEmbeds が $false なら埋め込みは読まない（埋め込みの中の PowerPoint を読むとき。深さは 1 段まで）
    param (
        [System.IO.Compression.ZipArchive]$zip,
        [bool]$readEmbeds,
        [System.Collections.Generic.List[string]]$failures = $null,
        [System.Collections.Generic.List[object]]$sizeFailures = $null
    )

    $units = New-Object System.Collections.Specialized.OrderedDictionary
    $footers = New-Object System.Collections.Generic.List[string]
    $seenFooters = New-Object System.Collections.Generic.HashSet[string]
    $embedState = newEmbeddedState
    $presentationXml = readZipEntry $zip "ppt/presentation.xml"
    if ($null -eq $presentationXml) {
        throw "PowerPointのプレゼンテーション情報（ppt/presentation.xml）がありません。"
    }
    $presentation = newXmlDocument $presentationXml
    $presentationRels = readRelationships $zip "ppt/presentation.xml"

    # スライドの表示順は sldIdLst の順（ファイル名の番号とは一致しないことがある）
    $number = 0
    foreach ($slideId in $presentation.GetElementsByTagName("sldId", ${nsPresent})) {
        $number++
        $rel = $presentationRels[$slideId.GetAttribute("id", ${nsRel})]
        if ($null -eq $rel) {
            continue
        }

        $slideXml = readZipEntry $zip $rel.Target
        if ($null -eq $slideXml) {
            continue
        }

        $unitName = "スライド{0:D3}" -f $number
        if ($slideXml -match '^[\s\S]{0,2000}?<p:sld\b[^>]*\sshow="(0|false)"') {
            $unitName += "（非表示）"
        }
        # テキストボックス・図形の文字はスライドの本文にする（スライドの文字はほとんどが図形のため）。
        # SmartArt・グラフの文字は "スライドNNN[図形]"、コメントは "スライドNNN[コメント]" に分ける
        $objects = New-Object System.Collections.Generic.List[object]
        addUnitLines $units $unitName @(readXmlLines $slideXml ${nsDrawing} "none" $null $objects | ForEach-Object { $_.Text })
        $slideRels = readRelationships $zip $rel.Target
        foreach ($object in $objects) {
            if ($object.Kind -eq "embed") {
                continue  # 埋め込みは、スライドの文字をすべて読んだあとに読む（下）
            }
            $text = readObjectText $zip $slideRels $object
            if ($text -ne "") {
                addUnitLines $units "${unitName}[図形]" @($text)
            }
        }
        foreach ($slideRel in $slideRels.Values) {
            if ($slideRel.Type -like "*/comments") {
                $commentsXml = readZipEntry $zip $slideRel.Target
                if ($null -ne $commentsXml) {
                    addUnitLines $units "${unitName}[コメント]" @(readSlideComments $commentsXml)
                }
            }
        }

        # スライドのフッター（各スライドに同じ内容が並ぶため、重複は除く）
        foreach ($line in (readXmlLines $slideXml ${nsDrawing} "none" @("ftr"))) {
            if ($seenFooters.Add($line.Text)) {
                $footers.Add($line.Text)
            }
        }

        # 発表者ノート
        foreach ($slideRel in $slideRels.Values) {
            if ($slideRel.Type -like "*/notesSlide") {
                $notesXml = readZipEntry $zip $slideRel.Target
                if ($null -ne $notesXml) {
                    addUnitLines $units ("スライド{0:D3}_ノート" -f $number) @(readXmlLines $notesXml ${nsDrawing} | ForEach-Object { $_.Text })
                }
            }
        }

        # 埋め込んだファイル（スライドの中の XML の順）。スライドの XML の文字列は、ここから先で使わない
        # ので、埋め込みを読む前に放す（同時に持つメモリを抑える）
        $slideXml = $null
        if ($readEmbeds) {
            foreach ($object in @($objects | Where-Object { $_.Kind -eq "embed" })) {
                $embedded = readEmbeddedObjectLines $zip $slideRels $object $embedState $failures $sizeFailures
                if ($null -ne $embedded -and $embedded.Lines.Count -gt 0) {
                    addUnitLines $units "${unitName}[埋め込み$($embedded.Number)]" $embedded.Lines
                }
            }
        }
    }

    if ($footers.Count -gt 0) {
        addUnitLines $units "ヘッダー・フッター" $footers.ToArray()
    }

    return $units
}

function toObjectCellText {
    # 図形・コメントの文字を、Excel のテキスト保存と同じ形の 1 セルにする。
    # 改行はセル内改行（$cellNewLine）にし、改行・" ・タブを含むときは " で囲む（中の " は "" にする）
    param (
        [string[]]$lines
    )

    $text = ($lines -join "`n").Trim()
    if ($text.IndexOfAny([char[]]@('"', "`t", "`r", "`n")) -lt 0) {
        return $text
    }
    $text = ($text -replace "\r\n|\r|\n", ${cellNewLine}).Replace('"', '""')
    return "`"$text`""
}

function readXlsxShapeRows {
    # 図形（xl/drawings/drawingN.xml）ごとの文字を @{ Row; Column; Text } の配列で返す。
    # 行・列は図形の左上のセル（1 から数える）。グループ化した図形は、まとめて 1 つの図形とする。
    # $zip・$drawingPath（この図形の部品自身の ZIP 内のパス）を渡すと、グラフ（c:chart）・SmartArt（dgm:relIds）の
    # 参照も解決し、テキストボックスの段落 → グラフ・SmartArt の文字（XML の順）の順に 1 つの図形（1 行）にする。
    # リレーションシップ（_rels）は、参照が 1 つ以上あるときだけ読む。
    # 参照の先・リレーションシップが無い、部品が読めない（XML が壊れているなど）ときは、そのグラフ・SmartArt だけを
    # 空にして続ける（同じ図形の中のほかの文字、ほかの図形は出す）。$failures を渡すと、読めなかった部品の名前を追加する。
    # サイズの上限（ZipSizeLimitException）で読めなかったときは、原因を調べられるよう、その例外自体を
    # $sizeFailures に追加する（呼び出し元がインデックス作成のログに部品名・大きさ・部品ごとか合計かを書く）
    param (
        [string]$xml,
        [System.IO.Compression.ZipArchive]$zip = $null,
        [string]$drawingPath = $null,
        [System.Collections.Generic.List[string]]$failures = $null,
        [System.Collections.Generic.List[object]]$sizeFailures = $null
    )

    $nsSheetDrawing = "http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing"
    $doc = newXmlDocument $xml
    $rows = New-Object System.Collections.Generic.List[object]
    $rels = $null  # この図形の部品（drawingN.xml）自身のリレーションシップ。参照が1つ以上あるときだけ読む
    foreach ($anchor in @($doc.DocumentElement.SelectNodes("//*")) | Where-Object {
            $_.NamespaceURI -eq $nsSheetDrawing -and $_.LocalName -in @("twoCellAnchor", "oneCellAnchor", "absoluteAnchor") }) {
        # 互換用の代替表示（mc:Fallback）の中は、mc:Choice と同じ図形なので読まない
        $inFallback = $false
        for ($node = $anchor.ParentNode; $null -ne $node; $node = $node.ParentNode) {
            if ($node.NamespaceURI -eq ${nsCompat} -and $node.LocalName -eq "Fallback") {
                $inFallback = $true
                break
            }
        }
        if ($inFallback) {
            continue
        }

        $objects = New-Object System.Collections.Generic.List[object]
        $lines = New-Object System.Collections.Generic.List[string]
        foreach ($line in (readXmlLines $anchor.OuterXml ${nsDrawing} "none" $null $objects)) {
            $lines.Add($line.Text)
        }
        # グラフ（c:chart）・SmartArt（dgm:relIds）の文字を、テキストボックスの段落の後、XML の順に並べる
        foreach ($object in @($objects | Where-Object { $_.Kind -eq "chart" -or $_.Kind -eq "diagram" })) {
            $text = ""
            try {
                # リレーションシップ自体（drawingN.xml.rels）が壊れていても、この図形だけを空にしてほかは捨てない
                if ($null -eq $rels) {
                    $rels = $(if ($zip -and $drawingPath) { readRelationships $zip $drawingPath } else { @{} })
                }
                $text = readObjectText $zip $rels $object
            } catch {
                if ($null -ne $sizeFailures -and $_.Exception -is [ZipSizeLimitException]) {
                    # サイズの上限を超えたときは、例外自体を渡す（部品名は例外の PartName に入っている）
                    $sizeFailures.Add($_.Exception)
                }
                if ($null -ne $failures) {
                    if ($null -eq $rels -and $drawingPath) {
                        # リレーションシップ自体（drawingN.xml.rels）が読めなかった場合は、図形の部品の名前を記録する
                        # （$object.RelId だけでは、どの部品が壊れているのか分からないため）
                        $failures.Add($drawingPath)
                    } else {
                        $rel = $(if ($rels) { $rels[[string]$object.RelId] } else { $null })
                        $failures.Add($(if ($rel) { $rel.Target } else { [string]$object.RelId }))
                    }
                }
            }
            if ($text -ne "") {
                $lines.Add($text)
            }
        }
        if ($lines.Count -eq 0) {
            continue
        }
        # 位置をセルで持たない図形（absoluteAnchor）は A1 とする
        $row = 1
        $column = 1
        $from = $anchor.GetElementsByTagName("from", $nsSheetDrawing)
        if ($from.Count -gt 0) {
            $row = 1 + [int]$from[0].GetElementsByTagName("row", $nsSheetDrawing)[0].InnerText
            $column = 1 + [int]$from[0].GetElementsByTagName("col", $nsSheetDrawing)[0].InnerText
        }
        $rows.Add(@{ Row = $row; Column = $column; Text = (toObjectCellText $lines.ToArray()) })
    }
    return $rows.ToArray()
}

function readXlsxCommentRows {
    # コメント（メモ。xl/commentsN.xml）とスレッド形式のコメント（xl/threadedComments/*.xml）の文字を、
    # セル番地 → 文字の辞書で返す。スレッド形式のコメントがあるセルは、その文字（返信を含む）を使う
    # （同じセルのメモには、古い版の Excel 向けの案内文とコメントが入っているため）
    param (
        [string]$commentsXml,
        [string[]]$threadedXmls
    )

    $nsSheet = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
    $nsThreaded = "http://schemas.microsoft.com/office/spreadsheetml/2018/threadedcomments"
    $result = [ordered]@{}

    foreach ($xml in @($threadedXmls | Where-Object { $_ })) {
        $doc = newXmlDocument $xml
        foreach ($comment in $doc.GetElementsByTagName("threadedComment", $nsThreaded)) {
            $ref = $comment.GetAttribute("ref")
            $text = @($comment.GetElementsByTagName("text", $nsThreaded) | ForEach-Object { $_.InnerText }) -join "`n"
            if (-not $ref -or $text.Trim() -eq "") {
                continue
            }
            if ($result.Contains($ref)) {
                $result[$ref] += "`n" + $text
            } else {
                $result[$ref] = $text
            }
        }
    }

    if ($commentsXml) {
        $doc = newXmlDocument $commentsXml
        foreach ($comment in $doc.GetElementsByTagName("comment", $nsSheet)) {
            $ref = $comment.GetAttribute("ref")
            if (-not $ref -or $result.Contains($ref)) {
                continue
            }
            # ふりがな（rPh）は読まない
            $text = @($comment.GetElementsByTagName("t", $nsSheet) | Where-Object { $_.ParentNode.LocalName -ne "rPh" } |
                ForEach-Object { $_.InnerText }) -join ""
            if ($text.Trim() -ne "") {
                $result[$ref] = $text
            }
        }
    }
    return $result
}

function getCellPosition {
    # セル番地（例: "AB12"）を @(行, 列) にする。読めなければ @(0, 0)
    param (
        [string]$ref
    )

    $m = [regex]::Match($ref, '^\$?([A-Za-z]+)\$?(\d+)$')
    if (-not $m.Success) {
        return @(0, 0)
    }
    $column = 0
    foreach ($ch in $m.Groups[1].Value.ToUpperInvariant().ToCharArray()) {
        $column = $column * 26 + ([int]$ch - [int][char]"A" + 1)
    }
    return @([int]$m.Groups[2].Value, $column)
}

function addSortedShapeLines {
    # 図形の一覧を、上の行から（同じ行は左から、同じセルは XML の順に）並べてユニットに加える。
    # Sort-Object は同じキーの順を保たない（インデックス作成のたびに順が変わる）ため、XML の順もキーにする
    param (
        [System.Collections.Specialized.OrderedDictionary]$units,
        [string]$unitName,
        [System.Collections.Generic.List[object]]$shapes
    )

    for ($i = 0; $i -lt $shapes.Count; $i++) {
        $shapes[$i].Order = $i
    }
    $lines = @($shapes | Sort-Object { $_.Row }, { $_.Column }, { $_.Order } |
        ForEach-Object { "$(toColumnName $_.Column)$($_.Row)`t$($_.Text)" })
    if ($lines.Count -gt 0) {
        addUnitLines $units $unitName $lines
    }
}

function getHeaderFooterLines {
    # Excel のヘッダー・フッターの書式コード付きの文字（例: "&L社外秘&C&"ＭＳ ゴシック,太字"&12見出し&R&P / &N ページ"）を、
    # 検索する行の一覧にする。左（&L）・中央（&C。区切りが無い先頭も中央）・右（&R）の順で、1 区分の 1 段落が 1 行。
    # 印刷時に決まる値（&P ページ・&N 総ページ・&D 日付・&T 時刻・&Z パス・&F ファイル名・&A シート名・&G 画像）と、
    # 書式（フォント・大きさ・色・&B &I &U &E &S &X &Y &O &H）は文字にしない。&& は & 1 文字。知らない & の続きはそのまま残す。
    # タブはスペースにして前後の空白を落とし、空の行は出さない。1 行ずつ toObjectCellText を通す
    # （Excel の行は " で囲んだセルを外す前提のため）
    param (
        [string]$code
    )

    $sections = @{ L = New-Object System.Text.StringBuilder; C = New-Object System.Text.StringBuilder; R = New-Object System.Text.StringBuilder }
    $current = $sections["C"]
    $length = $code.Length
    $i = 0
    while ($i -lt $length) {
        $ch = $code[$i]
        if ($ch -ne '&' -or $i + 1 -ge $length) {
            [void]$current.Append($ch)
            $i++
            continue
        }
        $next = $code[$i + 1]
        if ($next -eq '&') {
            [void]$current.Append('&')
            $i += 2
        } elseif ($next -cin @('L', 'C', 'R')) {
            $current = $sections[[string]$next]
            $i += 2
        } elseif ($next -ceq 'P') {
            # &P+1 &P-1（ページ番号の加減）の数字も取り除く
            $m = [regex]::Match($code.Substring($i), '^&P(?:[+-]\d+)?')
            $i += $m.Length
        } elseif ($next -cin @('N', 'D', 'T', 'Z', 'F', 'A', 'G', 'B', 'I', 'U', 'E', 'S', 'X', 'Y', 'O', 'H')) {
            $i += 2
        } elseif ($next -eq '"') {
            $close = $code.IndexOf('"', $i + 2)
            if ($close -lt 0) {
                [void]$current.Append('&')
                $i++
            } else {
                $i = $close + 1
            }
        } elseif ($next -ceq 'K') {
            $m = [regex]::Match($code.Substring($i), '^&K(?:[0-9A-Fa-f]{6}|[0-9]{2}[+-][0-9]{3})')
            if ($m.Success) {
                $i += $m.Length
            } else {
                [void]$current.Append('&')
                $i++
            }
        } elseif ($next -ge [char]'0' -and $next -le [char]'9') {
            $m = [regex]::Match($code.Substring($i), '^&\d{1,3}')
            $i += $m.Length
        } else {
            [void]$current.Append('&')
            $i++
        }
    }

    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($key in @("L", "C", "R")) {
        foreach ($part in ($sections[$key].ToString() -split "\r\n|\r|\n")) {
            $text = $part.Replace("`t", " ").Trim()
            if ($text -ne "") {
                $lines.Add((toObjectCellText @($text)))
            }
        }
    }
    return $lines.ToArray()
}

function readXlsxHeaderFooterLines {
    # シート（ワークシート・グラフシート）の XML（XmlReader）から、ヘッダー・フッターの検索する行を返す。
    # 並びは ヘッダー → フッター、それぞれ 先頭ページ（differentFirst のとき）→ 奇数（通常）ページ →
    # 偶数ページ（differentOddEven のとき）。同じ文字の行は 1 回だけ。
    # sheetData（セルの値。大きいシートでは数百 MB になる）は読まずに飛ばし、headerFooter を読んだら終わる
    param (
        [System.Xml.XmlReader]$reader
    )

    $nsSheet = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
    $texts = @{}
    $differentFirst = $false
    $differentOddEven = $false
    $hasNode = $reader.Read()
    while ($hasNode) {
        if ($reader.NodeType -eq [System.Xml.XmlNodeType]::Element -and $reader.NamespaceURI -eq $nsSheet) {
            if ($reader.LocalName -eq "sheetData") {
                $reader.Skip()
                $hasNode = -not $reader.EOF
                continue
            }
            if ($reader.LocalName -eq "headerFooter") {
                $differentFirst = $reader.GetAttribute("differentFirst") -in @("1", "true")
                $differentOddEven = $reader.GetAttribute("differentOddEven") -in @("1", "true")
                $sub = $reader.ReadSubtree()
                try {
                    $sub.Read() | Out-Null  # headerFooter 自身
                    $hasChild = $sub.Read()
                    while ($hasChild) {
                        if ($sub.NodeType -eq [System.Xml.XmlNodeType]::Element -and $sub.Depth -eq 1 -and $sub.NamespaceURI -eq $nsSheet) {
                            $childName = $sub.LocalName  # 読んだ後は位置が進むため、先に控える
                            $texts[$childName] = $sub.ReadElementContentAsString()
                            $hasChild = -not $sub.EOF
                        } else {
                            $hasChild = $sub.Read()
                        }
                    }
                } finally {
                    $sub.Dispose()
                }
                break
            }
        }
        $hasNode = $reader.Read()
    }

    $names = New-Object System.Collections.Generic.List[string]
    foreach ($kind in @("Header", "Footer")) {
        if ($differentFirst) { $names.Add("first$kind") }
        $names.Add("odd$kind")
        if ($differentOddEven) { $names.Add("even$kind") }
    }
    $lines = New-Object System.Collections.Generic.List[string]
    $seen = New-Object System.Collections.Generic.HashSet[string]
    foreach ($name in $names) {
        if (-not $texts.ContainsKey($name)) {
            continue
        }
        foreach ($line in (getHeaderFooterLines $texts[$name])) {
            if ($seen.Add($line)) { $lines.Add($line) }
        }
    }
    return $lines.ToArray()
}

function readXlsxSheetHeaderFooter {
    # ZIP の中のシートの部品（$entryName）か、読み込み済みの文字列（$xml。グラフシート）から、
    # ヘッダー・フッターの行を返す。読めない（XML が壊れているなど）ときは空にし、$failures に部品の名前を足す
    param (
        [System.IO.Compression.ZipArchive]$zip,
        [string]$entryName,
        [string]$xml = $null,
        [System.Collections.Generic.List[string]]$failures = $null
    )

    $settings = New-Object System.Xml.XmlReaderSettings
    $settings.DtdProcessing = [System.Xml.DtdProcessing]::Prohibit
    # シートの部品は sheetData が大きいため、文字列にせず流れで読む（readZipEntry は使わない）。
    # 代わりに、申告の大きさ（entry.Length）が上限（zipSheetStreamMaxBytes）を超える部品は開かずに読めなかった扱いにする。
    # MaxCharactersInDocument は、申告を偽った部品（実際は大きいのに小さく申告）を打ち切る守り（XmlException → 読めなかった扱い）
    $settings.MaxCharactersInDocument = $script:zipSheetStreamMaxBytes
    $stream = $null
    $reader = $null
    try {
        if ($xml) {
            $reader = [System.Xml.XmlReader]::Create((New-Object System.IO.StringReader($xml)), $settings)
        } else {
            $entry = $zip.GetEntry($entryName)
            if ($null -eq $entry) {
                return @()
            }
            if ($entry.Length -gt $script:zipSheetStreamMaxBytes) {
                # 申告の大きさが流れ読みの上限を超える（開かずに読めなかった扱いにし、理由をログに出せるようにする）
                if ($null -ne $failures) {
                    $failures.Add("$entryName（流れ読みの上限 $([long]($script:zipSheetStreamMaxBytes / 1MB))MB を超えています）")
                }
                return @()
            }
            $stream = $entry.Open()
            $reader = [System.Xml.XmlReader]::Create($stream, $settings)
        }
        return @(readXlsxHeaderFooterLines $reader)
    } catch {
        if ($null -ne $failures) {
            if ($_.Exception.Message -like "*MaxCharactersInDocument*") {
                $failures.Add("$entryName（流れ読みの上限 $([long]($script:zipSheetStreamMaxBytes / 1MB))MB を超えています）")
            } else {
                $failures.Add($entryName)
            }
        }
        return @()
    } finally {
        if ($null -ne $reader) { $reader.Dispose() }
        if ($null -ne $stream) { $stream.Dispose() }
    }
}

function readXlsxObjectUnits {
    # Excel（.xlsx / .xlsm）の表示シート・表示のグラフシートにある図形（テキストボックス・グループ・WordArt・
    # グラフ・SmartArt を含む）・コメント・ヘッダー／フッターの文字を、"<シート名>[図形]" "<シート名>[コメント]"
    # "<シート名>[ヘッダー・フッター]" の場所ごとに返す（シート名には [ ] を使えないため、実在のシートと重ならない）。
    # 図形・コメントの 1 行は "<セル番地><TAB><文字>"。セル番地は図形の左上・コメントのセルで、シートの上の行から順に並べる。
    # ヘッダー・フッターの 1 行は文字だけ（セル番地は無い。getHeaderFooterLines・readXlsxHeaderFooterLines）。
    # セルの値は Excel のテキスト保存で読むため、ここでは読まない。
    # ZIP の中身が Excel のブック（xl/workbook.xml）でなければ（.xlsb など）、何も返さない。
    # $failures を渡すと、読めなかったグラフ・SmartArt の部品の名前を追加する（呼び出し元でログに書く。
    # shared/ はツールを知らないため、ここでは書かない）。
    # $sizeFailures を渡すと、サイズの上限（ZipSizeLimitException）で読めなかったグラフ・SmartArt の
    # 例外自体を追加する（呼び出し元が部品名・大きさ・部品ごとか合計かをログに書く）
    param (
        [string]$path,
        [System.Collections.Generic.List[string]]$failures = $null,
        [System.Collections.Generic.List[object]]$sizeFailures = $null
    )

    $script:zipTotalReadBytes = 0  # このファイル1つ分の、readZipEntryが読む合計（zipTotalMaxBytes）を0から数え直す
    $units = New-Object System.Collections.Specialized.OrderedDictionary
    $nsSheet = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
    $zip = [System.IO.Compression.ZipFile]::OpenRead((toLongPath $path))
    try {
        $workbookXml = readZipEntry $zip "xl/workbook.xml"
        if ($null -eq $workbookXml) {
            return $units
        }
        $workbook = newXmlDocument $workbookXml
        $workbookRels = readRelationships $zip "xl/workbook.xml"

        foreach ($sheet in $workbook.GetElementsByTagName("sheet", $nsSheet)) {
            # 非表示（hidden）・完全に非表示（veryHidden）のシートは、セルと同じく読まない
            if ($sheet.GetAttribute("state") -in @("hidden", "veryHidden")) {
                continue
            }
            $rel = $workbookRels[$sheet.GetAttribute("id", ${nsRel})]
            if ($null -eq $rel) {
                continue
            }
            $sheetName = $sheet.GetAttribute("name")

            if ($rel.Type -like "*/chartsheet") {
                # 表示のグラフシート: グラフ自体を absoluteAnchor で置いた図形の部品を、通常のシートと同じ形で読む。
                # 位置をセルで持たないため、セル番地は今の決まりどおり A1 になる
                $chartsheetXml = readZipEntry $zip $rel.Target
                if ($null -eq $chartsheetXml) {
                    continue
                }
                $shapes = New-Object System.Collections.Generic.List[object]
                foreach ($csRel in (readRelationships $zip $rel.Target).Values) {
                    if ($csRel.Type -notlike "*/drawing") {
                        continue
                    }
                    $xml = readZipEntry $zip $csRel.Target
                    if ($null -ne $xml) {
                        $shapes.AddRange([object[]]@(readXlsxShapeRows $xml $zip $csRel.Target $failures $sizeFailures))
                    }
                }
                addSortedShapeLines $units "${sheetName}[図形]" $shapes
                $headerFooter = @(readXlsxSheetHeaderFooter $zip $rel.Target $chartsheetXml $failures)
                if ($headerFooter.Count -gt 0) {
                    addUnitLines $units "${sheetName}[ヘッダー・フッター]" $headerFooter
                }
                continue
            }
            if ($rel.Type -notlike "*/worksheet") {
                continue  # ダイアログシートなど
            }

            $shapes = New-Object System.Collections.Generic.List[object]
            $commentsXml = $null
            $threadedXmls = New-Object System.Collections.Generic.List[string]
            foreach ($sheetRel in (readRelationships $zip $rel.Target).Values) {
                # 要る 3 種類だけ読む（埋め込み・背景の画像など、関係のない大きな部品でサイズの上限に当たらないように）
                if ($sheetRel.Type -notlike "*/drawing" -and $sheetRel.Type -notlike "*/comments" -and $sheetRel.Type -notlike "*/threadedComment") {
                    continue
                }
                $xml = readZipEntry $zip $sheetRel.Target
                if ($null -eq $xml) {
                    continue
                }
                if ($sheetRel.Type -like "*/drawing") {
                    $shapes.AddRange([object[]]@(readXlsxShapeRows $xml $zip $sheetRel.Target $failures $sizeFailures))
                } elseif ($sheetRel.Type -like "*/comments") {
                    $commentsXml = $xml
                } elseif ($sheetRel.Type -like "*/threadedComment") {
                    $threadedXmls.Add($xml)
                }
            }
            addSortedShapeLines $units "${sheetName}[図形]" $shapes

            $comments = readXlsxCommentRows $commentsXml $threadedXmls.ToArray()
            $lines = @($comments.Keys | Sort-Object { (getCellPosition $_)[0] }, { (getCellPosition $_)[1] } |
                ForEach-Object { "$($_.Replace('$', ''))`t$(toObjectCellText @($comments[$_] -split "\r\n|\r|\n"))" })
            if ($lines.Count -gt 0) {
                addUnitLines $units "${sheetName}[コメント]" $lines
            }

            $headerFooter = @(readXlsxSheetHeaderFooter $zip $rel.Target $null $failures)
            if ($headerFooter.Count -gt 0) {
                addUnitLines $units "${sheetName}[ヘッダー・フッター]" $headerFooter
            }
        }
    } finally {
        $zip.Dispose()
    }
    return $units
}

function writeUnits {
    # ユニットごとに "<場所>.tsv" を出力し、出力したファイル数を返す（空のユニットは出力しない）。
    # 元のファイル名は、出力先のフォルダ名（インデクサが作業フォルダから移すときのフォルダ）になる
    param (
        [System.Collections.Specialized.OrderedDictionary]$units,
        [string]$outDir
    )

    $count = 0
    foreach ($unitName in $units.Keys) {
        $lines = New-Object System.Collections.Generic.List[string]
        foreach ($line in $units[$unitName]) {
            $line = $line.TrimEnd()
            if ($line -ne "") {
                $lines.Add($line)
            }
        }
        if ($lines.Count -eq 0) {
            continue
        }

        $path = Join-Path $outDir (toIndexFileName $unitName)
        [System.IO.File]::WriteAllLines((toLongPath $path), $lines, ${utf8Bom})
        $count++
    }
    return $count
}

# Word・PowerPoint に埋め込んだ Office のファイル（Office Open XML。Word 文書・Excel ブック・PowerPoint）の中の文字を読み出す。
# 埋め込んだファイルは、親のファイルの ZIP の中の 1 つの部品（word/embeddings/*.xlsx など。リレーションシップの種類が package）で、
# それ自体が ZIP になっている。部品をバイト列で読み（readZipEntryBytes。部品ごと・1ファイルの合計の上限は親と同じに数える）、
# メモリ上で開いて読む。ファイルには書き出さない。埋め込んだブックのシートも同じ readZipEntryBytes で読むため、
# 申告の大きさを偽ったシートも、親と同じく部品ごとの上限（zipPartMaxBytes）で打ち切り、シートの大きさは合計に数える
# office_reader.ps1 を先に読み込んでおくこと（readDocxUnits・readPptxUnits が readEmbeddedObjectLines を呼ぶ）。
#
# ・形式は、拡張子や名前ではなく中身で決める（xl/workbook.xml があれば Excel、word/document.xml があれば Word、
#   ppt/presentation.xml があれば PowerPoint）。ZIP でない・どれにも当たらないものは読まない（失敗にもしない）
# ・Excel のブックは、表示のシートの文字のセル（共有文字列・インライン文字列・数式の文字の結果）を、行ごとに
#   タブ区切りの 1 行にして返す。表示の範囲に限らず、ほかの表示のシートも読む（非表示・完全に非表示のシートは読まない）
# ・Word・PowerPoint は、中の全ユニットの行を順に並べて返す（埋め込みの中の埋め込みは読まない。深さは 1 段まで）
# ・同じ部品を指す参照（代替表示と本体など）は 1 回だけ読む。N は 1 ファイルの中の、参照の順の通し番号
#   （番号は読む前に振るため、読めなかったものは欠番になる）
# ・出す量にも上限がある。共有文字列は 1 つを多数のセルが参照でき、数 KB の埋め込みから巨大な行ができるため、
#   読んだ入力の大きさとは別に、出す行の文字数（共有文字列を解いた後・参照のたびに数える）を 1 ファイル（親）の中の
#   全埋め込みで合計し、embeddedOutputMaxChars を超えたらその埋め込みを読まない（ZipSizeLimitException の LimitKind が Output）

# 1 ファイル（親の Word・PowerPoint）の全埋め込みから出す、行の文字数の合計の上限（文字）。
# $script: の変数は読み取りのスレッド（runspace）ごとに別になる（テストから一時的に値を変えるときは、この変数を直接上書きする）
$script:embeddedOutputMaxChars = 32MB

function newEmbeddedState {
    # 1 ファイル（親の Word・PowerPoint）の埋め込みを数える状態を返す（通し番号・読んだ部品の名前・出した文字数の合計）
    return @{ Next = 1; Seen = (New-Object System.Collections.Generic.HashSet[string]); OutputChars = 0L }
}

function addEmbeddedOutputChars {
    # 埋め込みから出す行の文字数を合計に足し、上限（embeddedOutputMaxChars）を超えたら ZipSizeLimitException（Output）にする。
    # $state が $null のときは数えない
    param (
        [hashtable]$state,
        [long]$chars
    )

    if ($null -eq $state) {
        return
    }
    $state.OutputChars += $chars
    if ($state.OutputChars -gt $script:embeddedOutputMaxChars) {
        throw [ZipSizeLimitException]::new($script:zipTooLargeMessage, "(埋め込みから出す文字)", $state.OutputChars, "Output")
    }
}

function readXlsxSharedStrings {
    # 共有文字列（xl/sharedStrings.xml）を、番号の順の配列で返す。読み仮名（rPh）は含めない。無ければ空
    param (
        [System.IO.Compression.ZipArchive]$zip
    )

    $xml = readZipEntry $zip "xl/sharedStrings.xml"
    $strings = New-Object System.Collections.Generic.List[string]
    if (-not $xml) {
        return $strings.ToArray()
    }

    $settings = New-Object System.Xml.XmlReaderSettings
    $settings.DtdProcessing = [System.Xml.DtdProcessing]::Prohibit
    $reader = [System.Xml.XmlReader]::Create((New-Object System.IO.StringReader($xml)), $settings)
    try {
        $sb = New-Object System.Text.StringBuilder
        $inT = $false
        $inPhonetic = $false
        while ($reader.Read()) {
            $type = $reader.NodeType
            if ($type -eq [System.Xml.XmlNodeType]::Element) {
                $name = $reader.LocalName
                if ($name -eq "si") {
                    [void]$sb.Clear()
                    if ($reader.IsEmptyElement) { $strings.Add("") }
                } elseif ($name -eq "rPh") {
                    $inPhonetic = -not $reader.IsEmptyElement
                } elseif ($name -eq "t") {
                    $inT = -not $reader.IsEmptyElement
                }
            } elseif ($type -eq [System.Xml.XmlNodeType]::EndElement) {
                $name = $reader.LocalName
                if ($name -eq "si") {
                    $strings.Add($sb.ToString())
                } elseif ($name -eq "rPh") {
                    $inPhonetic = $false
                } elseif ($name -eq "t") {
                    $inT = $false
                }
            } elseif ($inT -and -not $inPhonetic) {
                if ($type -eq [System.Xml.XmlNodeType]::Text -or $type -eq [System.Xml.XmlNodeType]::SignificantWhitespace -or
                    $type -eq [System.Xml.XmlNodeType]::Whitespace -or $type -eq [System.Xml.XmlNodeType]::CDATA) {
                    [void]$sb.Append($reader.Value)
                }
            }
        }
    } finally {
        $reader.Dispose()
    }
    return $strings.ToArray()
}

function readXlsxSheetCellLines {
    # シートの部品（xl/worksheets/sheetN.xml）を流れで読み、文字のセルを行ごとにタブ区切りにして返す。
    # 文字のセルの文字数は、共有文字列を解いたあとで、参照のたびに $state の合計に足す（上限を超えたら例外。addEmbeddedOutputChars）
    param (
        [System.IO.Stream]$stream,
        [string[]]$sharedStrings,
        [hashtable]$state = $null
    )

    $settings = New-Object System.Xml.XmlReaderSettings
    $settings.DtdProcessing = [System.Xml.DtdProcessing]::Prohibit
    $settings.MaxCharactersInDocument = $script:zipPartMaxBytes
    $reader = [System.Xml.XmlReader]::Create($stream, $settings)
    $lines = New-Object System.Collections.Generic.List[string]
    try {
        $rowCells = New-Object System.Collections.Generic.List[string]
        $cellType = $null
        $valueText = New-Object System.Text.StringBuilder
        $inlineText = New-Object System.Text.StringBuilder
        $inValue = $false
        $inInline = $false
        $inT = $false
        $inPhonetic = $false
        while ($reader.Read()) {
            $type = $reader.NodeType
            if ($type -eq [System.Xml.XmlNodeType]::Element) {
                $name = $reader.LocalName
                $isEmpty = $reader.IsEmptyElement
                if ($name -eq "row") {
                    $rowCells.Clear()
                } elseif ($name -eq "c") {
                    $cellType = $reader.GetAttribute("t")
                    [void]$valueText.Clear()
                    [void]$inlineText.Clear()
                } elseif ($name -eq "v") {
                    $inValue = -not $isEmpty
                } elseif ($name -eq "is") {
                    $inInline = -not $isEmpty
                } elseif ($name -eq "rPh") {
                    $inPhonetic = -not $isEmpty
                } elseif ($name -eq "t") {
                    $inT = -not $isEmpty
                }
            } elseif ($type -eq [System.Xml.XmlNodeType]::EndElement) {
                $name = $reader.LocalName
                if ($name -eq "v") {
                    $inValue = $false
                } elseif ($name -eq "is") {
                    $inInline = $false
                } elseif ($name -eq "rPh") {
                    $inPhonetic = $false
                } elseif ($name -eq "t") {
                    $inT = $false
                } elseif ($name -eq "c") {
                    $text = $null
                    if ($cellType -eq "s") {
                        $index = 0
                        if ([int]::TryParse($valueText.ToString().Trim(), [ref]$index) -and $index -ge 0 -and $index -lt $sharedStrings.Count) {
                            $text = $sharedStrings[$index]
                        }
                    } elseif ($cellType -eq "inlineStr") {
                        $text = $inlineText.ToString()
                    } elseif ($cellType -eq "str") {
                        $text = $valueText.ToString()
                    }
                    if ($null -ne $text) {
                        addEmbeddedOutputChars $state ($text.Length + 1)
                        $text = ($text -replace "[\r\n\t]+", " ").Trim()
                        if ($text -ne "") {
                            $rowCells.Add($text)
                        }
                    }
                } elseif ($name -eq "row") {
                    if ($rowCells.Count -gt 0) {
                        $lines.Add(($rowCells -join "`t"))
                    }
                    $rowCells.Clear()
                }
            } elseif ($type -eq [System.Xml.XmlNodeType]::Text -or $type -eq [System.Xml.XmlNodeType]::SignificantWhitespace -or
                $type -eq [System.Xml.XmlNodeType]::Whitespace -or $type -eq [System.Xml.XmlNodeType]::CDATA) {
                if ($inValue) {
                    [void]$valueText.Append($reader.Value)
                } elseif ($inInline -and $inT -and -not $inPhonetic) {
                    [void]$inlineText.Append($reader.Value)
                }
            }
        }
    } finally {
        $reader.Dispose()
    }
    return $lines.ToArray()
}

function readXlsxCellLines {
    # 開いたブック（ZipArchive）の、表示のワークシートの文字のセルを、シートの順・行の順に並べた行の配列で返す
    # （数値・日付・空のセルは読まない）。シートの部品は readZipEntryBytes でバイト列に読む（部品ごとの上限・
    # 1 ファイルの合計の上限は親と同じ。申告を偽ったシートは、部品ごとの上限の超過として例外になる）。
    # 出す文字数は $state の合計に数え、上限を超えたら例外にする
    param (
        [System.IO.Compression.ZipArchive]$zip,
        [hashtable]$state = $null
    )

    $lines = New-Object System.Collections.Generic.List[string]
    $workbookXml = readZipEntry $zip "xl/workbook.xml"
    if ($null -eq $workbookXml) {
        return $lines.ToArray()
    }
    $workbook = newXmlDocument $workbookXml
    $workbookRels = readRelationships $zip "xl/workbook.xml"
    $nsSheet = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"

    $sharedStrings = $null
    foreach ($sheet in $workbook.GetElementsByTagName("sheet", $nsSheet)) {
        if ($sheet.GetAttribute("state") -in @("hidden", "veryHidden")) {
            continue
        }
        $rel = $workbookRels[$sheet.GetAttribute("id", ${nsRel})]
        if ($null -eq $rel -or $rel.Type -notlike "*/worksheet") {
            continue
        }
        $bytes = readZipEntryBytes $zip $rel.Target
        if ($null -eq $bytes) {
            continue
        }
        if ($null -eq $sharedStrings) {
            $sharedStrings = @(readXlsxSharedStrings $zip)
        }
        $stream = New-Object System.IO.MemoryStream (, $bytes)
        try {
            $lines.AddRange([string[]]@(readXlsxSheetCellLines $stream $sharedStrings $state))
        } finally {
            $stream.Dispose()
        }
    }
    return $lines.ToArray()
}

function readEmbeddedPackageLines {
    # 埋め込んだファイルのバイト列から、文字の行を返す（形式は中身で決める。読めない形式は空）
    param (
        [byte[]]$bytes,
        [hashtable]$state = $null,
        [System.Collections.Generic.List[string]]$failures = $null,
        [System.Collections.Generic.List[object]]$sizeFailures = $null
    )

    $lines = New-Object System.Collections.Generic.List[string]
    # ZIP の先頭の印（PK 03 04）。ZIP でなければ（古い形式の OLE など）読まない
    if ($bytes.Length -lt 4 -or $bytes[0] -ne 0x50 -or $bytes[1] -ne 0x4B -or $bytes[2] -ne 3 -or $bytes[3] -ne 4) {
        return $lines.ToArray()
    }

    $memory = New-Object System.IO.MemoryStream (, $bytes)
    $inner = $null
    try {
        $inner = New-Object System.IO.Compression.ZipArchive ($memory, [System.IO.Compression.ZipArchiveMode]::Read, $false)
        if ($null -ne $inner.GetEntry("xl/workbook.xml")) {
            $lines.AddRange([string[]]@(readXlsxCellLines $inner $state))
        } else {
            $units = $null
            if ($null -ne $inner.GetEntry("word/document.xml")) {
                $units = readDocxUnitsFromZip $inner $false $failures $sizeFailures
            } elseif ($null -ne $inner.GetEntry("ppt/presentation.xml")) {
                $units = readPptxUnitsFromZip $inner $false $failures $sizeFailures
            }
            if ($null -ne $units) {
                foreach ($unitName in $units.Keys) {
                    foreach ($line in $units[$unitName]) {
                        addEmbeddedOutputChars $state ($line.Length + 1)
                        $lines.Add($line)
                    }
                }
            }
        }
    } finally {
        if ($null -ne $inner) { $inner.Dispose() }
        $memory.Dispose()
    }
    return $lines.ToArray()
}

function readEmbeddedObjectLines {
    # readXmlLines が集めた埋め込み（Kind が embed）の参照から、埋め込んだファイルの文字を返す。
    # 戻り値: @{ Number = 通し番号; Lines = 行の配列 }。読まない（参照の先が無い・埋め込んだファイルではない・
    # 読んだことのある部品・読めない）ときは $null。
    #
    # 読めないとき: 部品ごとの上限・出す量の上限（ZipSizeLimitException の LimitKind が Part・Output）・壊れた XML・壊れた ZIP など
    # 何かの例外は、その埋め込みだけを読まなかった扱いにし、$failures に部品の名前、大きさの上限なら $sizeFailures に例外を
    # 追加して続ける（ほかの埋め込み・親の文字は出す。埋め込み 1 つで親のファイルの取り込みを失敗にしない）。
    # 投げ直すのは、1 ファイルの合計の上限（LimitKind が Total。ファイル全体の上限）と、中止・停止・メモリ不足の例外
    param (
        [System.IO.Compression.ZipArchive]$zip,
        [hashtable]$rels,   # readRelationships の結果
        $object,
        [hashtable]$state,  # newEmbeddedState の結果
        [System.Collections.Generic.List[string]]$failures = $null,
        [System.Collections.Generic.List[object]]$sizeFailures = $null
    )

    $rel = $rels[[string]$object.RelId]
    if ($null -eq $rel -or $rel.Type -notlike "*/package") {
        return $null
    }
    if (-not $state.Seen.Add([string]$rel.Target)) {
        return $null
    }
    $number = $state.Next
    $state.Next = $number + 1
    $outputBefore = $state.OutputChars  # 読めなかった埋め込みが出しかけた分は、合計から戻す（あとの埋め込みを巻き込まない）

    try {
        $bytes = readZipEntryBytes $zip $rel.Target
        if ($null -eq $bytes) {
            return $null
        }
        $lines = @(readEmbeddedPackageLines $bytes $state $failures $sizeFailures)
    } catch {
        $exception = $_.Exception
        # .NET のメソッド（XmlReader.Read など）の例外は、MethodInvocationException に包まれて届く
        while ($exception -is [System.Management.Automation.MethodInvocationException] -and $null -ne $exception.InnerException) {
            $exception = $exception.InnerException
        }
        $isSize = ($exception -is [ZipSizeLimitException])
        if ($isSize -and $exception.LimitKind -eq "Total") {
            throw
        }
        if ($exception -is [System.OperationCanceledException] -or $exception -is [System.Management.Automation.PipelineStoppedException] -or
            $exception -is [System.OutOfMemoryException]) {
            throw
        }
        $state.OutputChars = $outputBefore
        if ($isSize -and $null -ne $sizeFailures) {
            $sizeFailures.Add($exception)
        }
        if ($null -ne $failures) {
            $failures.Add([string]$rel.Target)
        }
        return $null
    }
    return @{ Number = $number; Lines = $lines }
}

# Officeアプリ（Excel・Word・PowerPoint）の起動・終了と、1ファイルの制限時間の監視。
# COM を使う処理だけをまとめる。使う側が dot-source する（shared.ps1 では読み込まない）。

# ----------------------------------------------------------------------------
# Officeアプリ（Excel・Word・PowerPoint）の起動・終了
# ----------------------------------------------------------------------------

# 起動中のアプリ: 名前 → @{ Com; Pid; Shared }
$script:apps = @{}

# ExitWait: Quit の後、終わるのを待つ時間（ミリ秒）。過ぎたら強制終了する（quitApp）。
#   Excel は抽出で取り出したCOMオブジェクトが解放されきらないため、インデクサが動いている間は Quit しても終わらず、
#   待ちの上限まで待ってから強制終了していた（実測: 毎回 5 秒待って強制終了）。待つだけ無駄なため短くする。
#   GC で解放を促して自分で終わらせる方法は、インデクサの終了が COM の解放待ちで約 60 秒止まることがあった（実測 25 回中 1～2 回）ため採らない
# 利用者に渡すときの、アプリごとの違い（handOverForeignApp・restoreHandedOverApp）:
#   Items      : 開いているファイルの一覧を持つ、アプリのプロパティの名前（Workbooks・Documents・Presentations）
#   Close      : 自分のファイルを保存せずに閉じる処理（引数は 1 つのファイル）
#   Restore    : 渡すときに戻す設定。getApp が変える設定は、ここに全部ある（テストで確かめる）。Required は戻らないと渡し切れない設定、
#                Optional は戻ればよい設定、ShowWindow は窓を出すか（Visible を真にする行は restoreHandedOverApp の中の 1 か所だけ）
#   WindowCheck: ファイルの一覧を読めないとき、見える窓があるかで利用者のものかを判断するか
#                （Word は自分で窓を隠しているため窓では判断できない。読めなければ渡しも終了もせず、持ち続けて後で読み直す）
#   GuardUserWindow: 取り込み中に、見える窓が一度でもあったプロセス（利用者がファイルを開いた）を、制限時間を過ぎても強制終了しない（OfficeWatchdog）。
#                （PowerPoint だけ。Excel・Word は、非表示のプロセスで利用者のファイルを開いたときに窓が見えるかを確かめていないため対象にしない）
$appInfo = @{
    Excel      = @{
        ProgId = "Excel.Application"; Process = "EXCEL"; ExitWait = 1000
        Items = "Workbooks"; Close = { param ($item) $item.Close($false) }
        Restore = @{
            Required = @(@("DisplayAlerts", $true), @("UserControl", $true))
            Optional = @(@("EnableEvents", $true), @("ScreenUpdating", $true), @("AskToUpdateLinks", $true), @("AutomationSecurity", 1))
            ShowWindow = $true
        }
        WindowCheck = $true
    }
    Word       = @{
        ProgId = "Word.Application"; Process = "WINWORD"; ExitWait = 5000
        Items = "Documents"; Close = { param ($item) $item.Close(0) }  # wdDoNotSaveChanges
        Restore = @{
            Required = @(,@("DisplayAlerts", -1))  # wdAlertsAll
            Optional = @(,@("AutomationSecurity", 1))
            ShowWindow = $true
        }
        WindowCheck = $false
    }
    # SingleInstance: 1つのセッションに1つのプロセスしか持てないアプリ（PowerPointだけ）。
    # 既に起動している（利用者が開いている）ときは、接続せずに使わない（下の getApp）
    PowerPoint = @{
        ProgId = "PowerPoint.Application"; Process = "POWERPNT"; ExitWait = 5000; SingleInstance = $true
        Items = "Presentations"; Close = { param ($item) $item.Close() }
        Restore = @{
            Required = @(,@("DisplayAlerts", 2))  # ppAlertsAll
            Optional = @(,@("AutomationSecurity", 1))
            ShowWindow = $false
        }
        WindowCheck = $true
        GuardUserWindow = $true
    }
}

# SingleInstance のアプリが、既に自分のセッションで起動している（利用者が使用中の）ときに投げる例外の文言。
# 呼ぶ側は "<アプリ名>${officeAppInUseMessage}" の形で使う。Reroute（extract_office.ps1 の officeRequiredMessage・
# OperationCanceledException）と取り違えないよう、型（InvalidOperationException）でも区別する
${officeAppInUseMessage} = " が起動しているため、更新に使用できません"

# 起動した Office のプロセスの優先度は下げない（Normal のまま）。利用者がダブルクリックしたファイルがインデックス作成の Excel・Word で開くことがあり、
# PowerPoint は 1 つのプロセスしか持てないため、利用者とプロセスを共有しないと確実には言えない。利用者の操作を遅くしないよう、
# 優先度を下げるのは、利用者と共有しないインデックス作成のスレッドだけにする（docs/design/structure/threads.md「スレッドの一覧」）
# 起動したアプリの PID を入れる入れ物（ConcurrentDictionary[int,object]。値は @{ ProcessName; StartTicks }。$null なら入れない）。
# 画面が閉じるときに、インデックス作成が起動した Office を、プロセス名と起動時刻を照らしてから止めるために使う
$script:officePidSink = $null
# 起動した Office の PID の記録を置くフォルダ（<ワークスペース>\office_pids\<PC の鍵>。$null なら書かない）。
# shared はツールを知らないため、使う側（インデックス作成）が場所を決めて入れる（office_process.ps1 の addOfficeRecord・removeOfficeRecord）。
# 記録は、次に画面を起動したときに、残った Office を確認して止めるために使う（書けなくても取り込みは続ける。その Office は止める対象にならない）
$script:officeRecordDir = $null
# 自分が開くファイルの置き場（インデックス作成の作業領域の一時フォルダ。$null なら、開いているファイルをすべて利用者のものとみなす）。
# 使う側が入れる。置き場の外のファイルが Excel・Word・PowerPoint に開かれたら、利用者が開いたファイルとして扱う（getForeignWorkbookCount・handOverApp）
$script:officeOwnDir = $null
# Excel・Word・PowerPoint を利用者に渡そうとしたときに呼ぶ処理（スクリプトブロック。引数はアプリ名と、渡し切れたか（戻しきれたか。$null は、渡すか決められず持ち続ける）。呼ぶ変数が $null なら何もしない）。ログを書く使う側が入れる
$script:onOfficeHandOver = $null
# 渡そうとして戻しきれなかったアプリ（COM の参照を放さずに持ち続ける）
$script:officeKeptApps = @()
# 渡し切れずに持ち続けたアプリを仕上げ直して待つ、取り込みのスレッドの終わりの上限（秒）と間隔（ミリ秒）
$script:officeKeptWaitSeconds = 30
$script:officeKeptWaitStep = 500

function resolveLongName {
    # 8.3 の短い名前（TEST~1 など）を含むパスを長い名前にする。読めなければ $null
    param ([string]$path)

    try {
        return (Get-Item -LiteralPath $path -ErrorAction Stop).FullName
    } catch {
        return $null
    }
}

function resolveOwnDir {
    # 自分が開くブックの置き場（一時フォルダ）を、比べる形にする。短い名前を長くできなければ、そのまま使う。
    # 置き場が決まっていなければ $null（そのときは開いたブックをすべて利用者のものと数える）
    param ([string]$dir)

    if (-not $dir) {
        return $null
    }
    $long = resolveLongName $dir
    return $(if ($long) { $long } else { $dir })
}

function isUnderDir {
    # path が dir の下にあるか。両方を正規化し、dir は区切りで終わる形にして、大文字小文字を区別せずに前置で比べる
    # （tmp と tmp2 を取り違えない）。正規化できない（URL など）ときは、下に無いものとする
    param ([string]$path, [string]$dir)

    try {
        $full = [System.IO.Path]::GetFullPath($path)
        $base = [System.IO.Path]::GetFullPath($dir).TrimEnd('\') + '\'
        return $full.StartsWith($base, [System.StringComparison]::OrdinalIgnoreCase)
    } catch {
        return $false
    }
}

function getWorkbookSplit {
    # アプリで開いているファイル（Excel のブック・Word の文書・PowerPoint のプレゼンテーション）を、自分が開いたもの（置き場の下）と
    # 利用者が開いたもの（外）に分ける。@{ Own; Foreign }
    # 開いたファイルの FullName を控えて照合する方法は、失敗の途中で Open が戻らなかったファイルを控えられないため採らない。
    # 短い名前（~ を含む）は長い名前にしてから比べる。読めなければ、置き場の下と確かめられないので利用者のものと数える
    # （データを失わない側。自分のものは置き場の下にあり、読める）
    param ($com, [string]$name)

    $own = New-Object System.Collections.ArrayList
    $foreign = New-Object System.Collections.ArrayList
    $workbooks = $com.($appInfo[$name].Items)
    try {
        foreach ($book in @($workbooks)) {
            if ($null -eq $book) { continue }
            $full = [string]$book.FullName
            if ($full.Contains('~')) {
                $full = resolveLongName $full
            }
            if ($full -and $script:officeOwnDir -and (isUnderDir $full $script:officeOwnDir)) {
                [void]$own.Add($book)
            } else {
                [void]$foreign.Add($book)
            }
        }
    } finally {
        try { releaseComObject $workbooks } catch {}
    }
    return @{ Own = $own; Foreign = $foreign }
}

function releaseWorkbookSplit {
    # getWorkbookSplit で取り出したファイルの参照を放す（残すとアプリが終わらなくなる）
    param ($split)

    foreach ($book in @($split.Own) + @($split.Foreign)) { try { releaseComObject $book } catch {} }
}

function getForeignWorkbookCount {
    # アプリで利用者が開いたファイル（置き場の外）の数。読めない（COM の例外）ときは -1（分からない。handOverForeignApp が判断する）
    param ($com, [string]$name)

    try {
        $split = getWorkbookSplit $com $name
        $count = @($split.Foreign).Count
        # 取り出したファイルの参照を残すとアプリが終わらなくなるため、数えたら放す
        releaseWorkbookSplit $split
        return $count
    } catch {
        return -1
    }
}

function testProcessHasWindow {
    # 起動で控えた PID のプロセスに、見える窓があるか。PID だけを見る（窓を中身で探さない）。控えていなければ（0）偽
    param ([int]$processId, [string]$processName)

    if ($processId -le 0) {
        return $false
    }
    $process = Get-Process -Id $processId -ErrorAction SilentlyContinue
    return [bool]($process -and $process.ProcessName -eq $processName -and $process.MainWindowHandle -ne 0)
}

function testProcessExists {
    # 指定した PID に、指定した名前のプロセスがあるか。PID と名前だけを見る
    param ([int]$processId, [string]$processName)

    $process = Get-Process -Id $processId -ErrorAction SilentlyContinue
    return [bool]($process -and $process.ProcessName -eq $processName)
}

function getMonotonicMilliseconds {
    # 経過時間の計測用の、戻らない時計（ミリ秒）
    return [long]([System.Diagnostics.Stopwatch]::GetTimestamp() * 1000 / [System.Diagnostics.Stopwatch]::Frequency)
}

function getOwnSessionProcessIds {
    # 自分のセッションで動いている、指定した名前のプロセスのIDの一覧。
    # ほかのセッション（同じPCの別の利用者・別の作業フォルダの tebunko 等）のプロセスは、自分のものと取り違えないため数えない
    param (
        [string]$processName,
        [int]$sessionId
    )

    return @(Get-Process -Name $processName -ErrorAction SilentlyContinue |
        Where-Object { $_.SessionId -eq $sessionId } | ForEach-Object { $_.Id })
}

function getApp {
    # アプリのCOMオブジェクトを返す。起動していなければ起動する。
    # SingleInstance のアプリ（PowerPoint）が既に自分のセッションで起動しているときは、新しいプロセスができず
    # 利用者のアプリに接続することになるため、接続せずに例外を投げる（呼ぶ側は後回しにする）
    param (
        [string]$name
    )

    if (-not $script:apps.ContainsKey($name)) {
        $info = $appInfo[$name]
        $sessionId = [System.Diagnostics.Process]::GetCurrentProcess().SessionId

        if ($info.SingleInstance -and (getOwnSessionProcessIds $info.Process $sessionId).Count -gt 0) {
            throw (New-Object System.InvalidOperationException "${name}${officeAppInUseMessage}")
        }

        # 終了できなかった場合に強制終了するため、新しく起動したプロセスのIDを控えておく
        $before = getOwnSessionProcessIds $info.Process $sessionId
        $com = New-Object -ComObject $info.ProgId
        $after = getOwnSessionProcessIds $info.Process $sessionId
        $newIds = @($after | Where-Object { $before -notcontains $_ })

        if ($info.SingleInstance -and $newIds.Count -eq 0) {
            # 事前の確認から New-Object の間に、利用者が先にアプリを起動した（先に接続した）。
            # DisplayAlerts・AutomationSecurity などの設定を変える前に解放し、利用者のアプリに触らない
            try { releaseComObject $com } catch {}
            throw (New-Object System.InvalidOperationException "${name}${officeAppInUseMessage}")
        }
        # 起動時刻を控える。止める前に、控えたときと同じプロセスか照らすために使う（isSameOfficeProcess）。読めなければ $null（止める対象にならない）
        $startTicks = $null
        if ($newIds.Count -eq 1) {
            $started = Get-Process -Id ([int]$newIds[0]) -ErrorAction SilentlyContinue
            if ($started -and $started.ProcessName -eq $info.Process) {
                $startTicks = getOfficeStartTicks $started
            }
        }
        if ($newIds.Count -eq 1 -and $script:officePidSink) {
            $script:officePidSink[[int]$newIds[0]] = @{ ProcessName = $info.Process; StartTicks = $startTicks }
        }
        if ($newIds.Count -eq 1 -and $script:officeRecordDir -and $null -ne $startTicks) {
            # 起動時刻が読めたときだけ記録する（読めなければ、残っても止める対象にならない）
            [void](addOfficeRecord $script:officeRecordDir ([int]$newIds[0]) $info.Process $startTicks)
        }

        switch ($name) {
            "Excel" {
                $com.Visible = $false
                $com.DisplayAlerts = $false
                $com.EnableEvents = $false
                $com.ScreenUpdating = $false
                $com.AskToUpdateLinks = $false
            }
            "Word" {
                $com.Visible = $false
                $com.DisplayAlerts = 0  # wdAlertsNone
            }
            "PowerPoint" {
                # PowerPointはウィンドウを隠せないため、ファイルをウィンドウ無しで開く（Visible は変更しない）
                $com.DisplayAlerts = 1  # ppAlertsNone
            }
        }
        $com.AutomationSecurity = 3  # msoAutomationSecurityForceDisable（マクロ無効）

        # Excel・Word は起動中のアプリに接続することがある（新しいプロセスができない場合。PowerPoint は上で防いでいるため
        # ここには来ない）。その場合は利用者のものなので終了させない
        $script:apps[$name] = @{
            Com         = $com
            Pid         = $(if ($newIds.Count -eq 1) { $newIds[0] } else { 0 })
            ProcessName = $info.Process
            StartTicks  = $startTicks
            Shared      = ($newIds.Count -eq 0)
            GuardWindow = [bool]$info.GuardUserWindow
        }
        $script:officeWatchdog.UpdateWatchedPids($script:apps)
    }
    return $script:apps[$name].Com
}

function restoreHandedOverApp {
    # 渡すアプリに対して、(0) 自分が開いたファイル（置き場の下と確かめられたもの）を保存せずに閉じる (1) 必須の設定（$appInfo の Restore.Required と、窓を出すアプリは Visible）
    # (2) 任意の設定を戻す。state に済んだものを控えるので、何度呼んでも済んだものはやり直さない。全部済んだら $true
    # tries: 必須の設定をやり直す回数（失敗したときだけ間を置く）。利用者のファイルは閉じない
    param ($state, [int]$tries = 1)

    $com = $state.Com
    $info = $appInfo[$state.Name]
    if (-not $state.BooksClosed) {
        try {
            $books = getWorkbookSplit $com $state.Name
            # 前の回の一覧の参照は、取り直した一覧に置き換える前に放す
            if ($state.Books) {
                releaseWorkbookSplit $state.Books
            }
            $closeFailed = $false
            foreach ($book in $books.Own) {
                try { & $info.Close $book } catch { $closeFailed = $true }
            }
            $state.Books = $books
            # 閉じられなかったものが 1 つでもあれば、立てない（次回に一覧を取り直す。閉じたものは一覧から消えるので二重には閉じない）
            $state.BooksClosed = (-not $closeFailed)
        } catch {}
    }
    # 窓・UserControl・DisplayAlerts が戻らないまま参照を放すと、Excel が保存の確認なしに終わりうるため、成功を確かめる
    $required = @($info.Restore.Required)
    if ($info.Restore.ShowWindow) { $required += , @("Visible", $true) }
    $optional = @($info.Restore.Optional)
    for ($try = 0; $try -lt $tries; $try++) {
        $left = @($required | Where-Object { -not $state.Done[$_[0]] })
        if ($left.Count -eq 0) { break }
        if ($try -gt 0) { Start-Sleep -Milliseconds 200 }
        foreach ($setting in $left) {
            try { $com.($setting[0]) = $setting[1]; $state.Done[$setting[0]] = $true } catch {}
        }
    }
    foreach ($setting in @($optional | Where-Object { -not $state.Done[$_[0]] })) {
        try { $com.($setting[0]) = $setting[1]; $state.Done[$setting[0]] = $true } catch {}
    }
    return [bool]($state.BooksClosed -and (@($required + $optional | Where-Object { -not $state.Done[$_[0]] }).Count -eq 0))
}

function releaseHandedOverApp {
    # このスレッドが持つ COM を解放しきる。WaitForPendingFinalizers は長く止まることがあるため使わない
    param ($state)

    try {
        if ($state.Books) {
            releaseWorkbookSplit $state.Books
        }
        releaseComObject $state.Com
        [GC]::Collect()
    } catch {}
}

function untrackApp {
    # アプリを (a) 見張りの対象から外す (b) 一括終了の対象から外す (c) 残り物の確認の記録から消す。誰も止めなくなる。それぞれ、ほかが失敗しても行う
    param ([string]$name, $app)

    try { $script:apps.Remove($name) } catch {}
    try { $script:officeWatchdog.UpdateWatchedPids($script:apps) } catch {}
    try {
        if ($app.Pid -and $script:officePidSink) {
            $removed = $null
            [void]$script:officePidSink.TryRemove([int]$app.Pid, [ref]$removed)
        }
    } catch {}
    try {
        if ($app.Pid -and $script:officeRecordDir) {
            removeOfficeRecord $script:officeRecordDir ([int]$app.Pid)
        }
    } catch {}
}

function keepUndecidedApp {
    # ファイルの一覧が読めず、利用者のファイルがあるか分からないアプリ（窓で判断できない Word）を、終了させず・渡さず、持ち続ける。
    # 利用者のファイルがあるかもしれないので、誰も止めない（untrackApp）。retryKeptApps が一覧を読み直し、利用者のファイルがあれば渡し、
    # 自分のファイルだけなら終了させる
    param ([string]$name)

    $app = $script:apps[$name]
    untrackApp $name $app
    $script:officeKeptApps += , @{ Name = $name; Com = $app.Com; Pid = [int]$app.Pid; StartTicks = $app.StartTicks; BooksClosed = $false; Books = $null; Done = @{}; Undecided = $true }
    if ($script:onOfficeHandOver) {
        # 渡したかどうかがまだ決まっていない（$null）ことを知らせる
        try { & $script:onOfficeHandOver $name $null } catch {}
    }
}

function quitApp {
    # アプリを終了させる。Quit し、COM の参照を放し、控えた PID のプロセス（名前も合うもの）が終わるのを待つ。
    # GC::WaitForPendingFinalizers() は COM の解放待ちで長時間（約 60 秒）止まることがあるため使わず、
    # 待ち時間（ExitWait）を過ぎても終わらなければ PID を指定して強制終了する（名前では止めない）。終わったと確かめられたら $true。
    # 待つ前・止める前に、控えたプロセスと同じか（名前・起動時刻）を照らす（isSameOfficeProcess）。起動時刻が違えば、控えたプロセスはもう終わっているので $true
    # （別のプロセスを待たず、止めない）。起動時刻が読めない・控えていないときは、止めず待たずに $false（記録を残し、次の起動の確認に任せる）
    param ([string]$name, $com, [int]$processId, $startTicks = $null)

    try { $com.Quit() } catch {}
    try { releaseComObject $com } catch {}
    if ($processId -le 0) {
        return $true
    }
    $process = Get-Process -Id $processId -ErrorAction SilentlyContinue
    if ($null -eq $process -or $process.ProcessName -ne $appInfo[$name].Process) {
        return $true
    }
    if (-not (isSameOfficeProcess $process $appInfo[$name].Process $startTicks)) {
        # Quit の直後に自分で終わったものは、終わったとして返す。起動時刻が違えば控えたプロセスは終わっている。分からないときは $false
        try { if ($process.HasExited) { return $true } } catch {}
        return ((compareOfficeProcess $process $appInfo[$name].Process $startTicks) -eq "Different")
    }
    $wait = $appInfo[$name].ExitWait
    if ($process.WaitForExit($wait)) {
        return $true
    }
    # 終了処理中のプロセスは Kill() が「アクセス拒否」で失敗することがあるが、そのまま終了するため無視する
    try { $process.Kill() } catch {}
    # 強制終了は非同期のため、同じ上限で終わるのを待つ。それでも残った場合は、次の getApp が
    # 利用者のものとみなして後回しにする（安全な側に倒れる）
    return [bool]$process.WaitForExit($wait)
}

function quitKeptApp {
    # 自分のファイルだけだと分かった、持ち続けたアプリを終了させる（quitApp）
    param ($state)

    [void](quitApp $state.Name $state.Com $state.Pid $state.StartTicks)
}

function handOverApp {
    # 起動したアプリ（Excel・Word・PowerPoint）を、利用者に渡す。Quit も強制終了もしない（利用者のファイルを閉じない）。渡したアプリはもう使わない。
    # 見張り・終了時の一括終了・次の起動の残り物の確認のどれからも外すので、誰も止めない。
    # Shared のアプリ（利用者のアプリに接続したもの）には当てない（止めず、設定も変えない）
    param ([string]$name)

    $app = $script:apps[$name]
    if ($null -eq $app -or $app.Shared) {
        return $false
    }
    untrackApp $name $app

    # 自分のファイルを閉じる・設定を戻す・窓を出す、を全部通して初めて「渡した」。通らなければ、持ち続けて後で設定し直す
    $state = @{ Name = $name; Com = $app.Com; Pid = [int]$app.Pid; StartTicks = $app.StartTicks; BooksClosed = $false; Books = $null; Done = @{} }
    $ok = restoreHandedOverApp $state 3
    if ($ok) {
        releaseHandedOverApp $state
    } else {
        # 戻しきれなかったアプリは、参照を放すと終わるおそれがあるため、放さずに持ち続ける（止めも強制終了もしない）。
        # retryKeptApps と waitKeptApps が設定し直す。取り込みのスレッドが終わるまでに通らなければ、参照が切れる
        $script:officeKeptApps += , $state
    }

    if ($script:onOfficeHandOver) {
        try { & $script:onOfficeHandOver $name $ok } catch {}
    }
    return $ok
}

function retryKeptApps {
    # 渡し切れずに持ち続けているアプリをもう一度仕上げる（済んでいないものだけ）。全部通れば参照を放して「渡した」ログを書く。待たない。
    # 控えた PID のプロセスが（その名前で）もう無ければ、利用者が先に終えたので、参照だけ放して一覧から外す（PID と名前だけを見る。窓は探さない。止めない）
    if (@($script:officeKeptApps).Count -eq 0) {
        return
    }
    $remaining = @()
    foreach ($kept in @($script:officeKeptApps)) {
        if ($kept.Pid -gt 0 -and -not (testProcessExists ([int]$kept.Pid) $appInfo[$kept.Name].Process)) {
            releaseHandedOverApp $kept
            continue
        }
        if ($kept.Undecided) {
            # 利用者のファイルがあるか、一覧を読み直す。まだ読めなければ、そのまま持ち続ける
            $foreignCount = getForeignWorkbookCount $kept.Com $kept.Name
            if ($foreignCount -lt 0) {
                $remaining += , $kept
                continue
            }
            if ($foreignCount -eq 0) {
                quitKeptApp $kept
                continue
            }
            $kept.Undecided = $false
        }
        if (restoreHandedOverApp $kept 1) {
            releaseHandedOverApp $kept
            if ($script:onOfficeHandOver) {
                try { & $script:onOfficeHandOver $kept.Name $true } catch {}
            }
        } else {
            $remaining += , $kept
        }
    }
    $script:officeKeptApps = $remaining
}

function waitKeptApps {
    # 取り込みのスレッドの終わりに限り、持ち続けているアプリを、間を置いて上限まで仕上げ直す。持ち続けが無ければ待たない。
    # shouldStop が真を返したら（中止・画面を閉じる）次の刻みで抜ける。上限に届かなかったものは、そのまま持ち続け（スレッドが終わると参照が切れる）
    param ([scriptblock]$shouldStop = { $false })

    $started = getMonotonicMilliseconds
    while (@($script:officeKeptApps).Count -gt 0) {
        retryKeptApps
        if (@($script:officeKeptApps).Count -eq 0 -or ((getMonotonicMilliseconds) - $started) -ge ($script:officeKeptWaitSeconds * 1000) -or (& $shouldStop)) {
            break
        }
        Start-Sleep -Milliseconds $script:officeKeptWaitStep
    }
}

function handOverForeignApp {
    # 起動したアプリ（Excel・Word・PowerPoint）に利用者が開いたファイルがあれば、利用者に渡して $true を返す。無ければ何もせず $false
    param ([string]$name)

    # 前に戻しきれなかったアプリがあれば、ここで仕上げ直す
    retryKeptApps
    $app = $script:apps[$name]
    if ($null -eq $app -or $app.Shared) {
        return $false
    }
    $count = getForeignWorkbookCount $app.Com $name
    if ($count -eq 0) {
        # 利用者のファイルが今は無い（開いて閉じた）なら、利用者が使った印を消す。印が残ると、
        # 次のファイルで固まっても止められず、窓の無い固まったアプリが残るため（また窓が見えれば、見張りが印を付け直す）
        if ($app.Pid -and $script:officeWatchdog.State.Users) {
            $removed = $null
            [void]$script:officeWatchdog.State.Users.TryRemove([int]$app.Pid, [ref]$removed)
        }
        return $false
    }
    # ファイルの一覧を読めない（COM が呼び出しを拒んだ。利用者が操作中のことがある）ときは、
    #   窓で判断できるアプリ（Excel・PowerPoint）: 見える窓があれば利用者が使っているとみなして渡し、無ければ何もしない（今までどおり終了させる）
    #   窓で判断できないアプリ（Word。自分で窓を隠している）: 渡しも終了もさせず、持ち続けて後で一覧を読み直す（空の窓を出さず、データも失わない）
    if ($count -lt 0) {
        if ($appInfo[$name].WindowCheck) {
            if (-not (testProcessHasWindow ([int]$app.Pid) $appInfo[$name].Process)) { return $false }
        } else {
            keepUndecidedApp $name
            return $true
        }
    }
    [void](handOverApp $name)
    return $true
}

function stopApp {
    param (
        [string]$name
    )

    $app = $script:apps[$name]
    if ($null -eq $app) {
        return
    }
    # インデックス作成中に利用者が同じアプリでファイルを開いた場合は、閉じずに利用者に渡す（自分のファイルだけなら、下で終了させる）
    if (handOverForeignApp $name) {
        return
    }
    $script:apps.Remove($name)
    $script:officeWatchdog.UpdateWatchedPids($script:apps)

    # 利用者のアプリに接続したもの（Shared）は、終了させず、参照だけ放す。利用者に渡したものとして、記録も消す
    if ($app.Shared) {
        try { releaseComObject $app.Com } catch {}
        $exited = $true
    } else {
        $exited = quitApp $name $app.Com $app.Pid $app.StartTicks
    }
    # 記録は、プロセスが終わったと確かめてから消す。終わらなければ残す（次の起動の確認に任せる）
    if ($app.Pid -and $script:officeRecordDir -and $exited) {
        removeOfficeRecord $script:officeRecordDir ([int]$app.Pid)
    }
    if ($app.Pid -and $script:officePidSink) {
        $removed = $null
        [void]$script:officePidSink.TryRemove([int]$app.Pid, [ref]$removed)
    }
}

function stopAllApps {
    retryKeptApps
    # 1つのアプリの終了に失敗しても、残りのアプリは終了させる
    foreach ($name in @($script:apps.Keys)) {
        try {
            stopApp $name
        } catch {
            Write-Host "    ${name} の終了に失敗しました: $($_.Exception.Message)" -ForegroundColor Yellow
        }
    }
}

function getAppName {
    # 拡張子から、抽出に使うアプリの名前を返す
    param (
        [string]$path
    )

    switch -Regex ([System.IO.Path]::GetExtension($path).ToLower()) {
        "^\.xls" { return "Excel" }
        "^\.doc" { return "Word" }
        "^\.ppt" { return "PowerPoint" }
    }
    return $null
}

function releaseComObject($object) {
    if ($null -ne $object) {
        [void][System.Runtime.InteropServices.Marshal]::ReleaseComObject($object)
    }
}

# ----------------------------------------------------------------------------
# 1ファイルの制限時間の監視
# ----------------------------------------------------------------------------

function getWatchdogVerdict {
    # 見張りが、控えたプロセス 1 つをどうするかを決める。'Skip'（何もしない）／'Spare'（期限を過ぎたが、利用者が使ったので止めない）／'Kill'（期限を過ぎたので止める）
    # entry: @{ Id; StartTicks; GuardWindow }、hasWindow: 今、窓が見えるか、users: 「利用者が使った」印（PID → @{ StartTicks }。窓が見えたらここに入れる）、due: 制限時間を過ぎたか
    # 印は、起動時刻が同じものだけを有効とする（PID が使い回されたプロセスを守らない）
    param ($entry, [bool]$hasWindow, $users, [bool]$due)

    if ($entry.GuardWindow) {
        if ($hasWindow) {
            $users[[int]$entry.Id] = @{ ProcessName = $entry.ProcessName; StartTicks = $entry.StartTicks }
        }
        $mark = $null
        if ($users.TryGetValue([int]$entry.Id, [ref]$mark) -and $mark.StartTicks -eq $entry.StartTicks) {
            if ($due) { return 'Spare' }
            return 'Skip'
        }
    }
    if ($due) { return 'Kill' }
    return 'Skip'
}

# 取り込み中のCOM呼び出しは応答が無いと戻らず、Ctrl+C も効かないため、別スレッドで制限時間を監視する。
# 制限時間を過ぎたら、自分で起動したOfficeアプリを強制終了する（COM呼び出しが例外で戻り、そのファイルは失敗になる）。
# スレッド（ランスペース）ごとに 1 つ持つ（下の $script:officeWatchdog）。見張りのスレッド（[PowerShell]::Create() の別のランスペース）へは、
# クラスではなく State（[hashtable]::Synchronized）を渡す。
class OfficeWatchdog {
    # 見張りのスレッドと共有する値。
    #   Deadline: 取り込み中のファイルの制限時刻（取り込み中でなければ MaxValue）
    #   Pids    : 強制終了してよいプロセス（自分で起動したOfficeアプリ）。@{ Id; ProcessName; StartTicks } の配列。止める前に起動時刻を照らす
    #   TimedOut: 制限時間を過ぎて強制終了した
    #   Stop    : 見張りのスレッドに終わりを伝える
    #   Users   : 取り込み中に、見える窓が一度でもあったプロセス（利用者が使った印）。PID → @{ ProcessName; StartTicks }（ConcurrentDictionary）。
    #             印のあるプロセスは、制限時間を過ぎても強制終了しない。画面を閉じるときの KillOffice と共有するため、使う側が入れ替える
    #   Abandon : 印のあるプロセスを止めずに、制限時間を過ぎたレーンを諦めたと、司令に伝える入れ物（Synchronized な @{ Abandoned }）。
    #             取り込みのスレッドが入れる。無ければ（司令のスレッドで取り込むとき）止めないだけにする
    #   WindowProbe: 窓があるかを見分ける関数の名前（既定は testOfficeProcessHasWindow。テストで差し替える）
    [hashtable]$State
    # 強制終了してよいプロセスの名前（Officeアプリ）
    [string[]]$ProcessNames
    hidden $Thread

    OfficeWatchdog([string[]]$processNames) {
        $this.State = [hashtable]::Synchronized(@{
            Deadline = [datetime]::MaxValue; Pids = @(); TimedOut = $false; Stop = $false
            Users = (New-Object 'System.Collections.Concurrent.ConcurrentDictionary[int,object]'); Abandon = $null
            WindowProbe = 'testOfficeProcessHasWindow'
        })
        $this.ProcessNames = $processNames
        $this.Thread = $null
    }

    [void] UpdateWatchedPids([hashtable]$apps) {
        # 強制終了してよいプロセスIDを、起動中のアプリのうち自分で起動したものにする（利用者のアプリは終了させない）
        $previous = @($this.State.Pids)
        $this.State.Pids = @($apps.Values | Where-Object { -not $_.Shared -and $_.Pid } |
            ForEach-Object { @{ Id = [int]$_.Pid; ProcessName = $_.ProcessName; StartTicks = $_.StartTicks; GuardWindow = [bool]$_.GuardWindow } })
        # 見張りから外れたプロセス（終わった・利用者に渡した）と、同じ PID でも起動時刻が違うもの（PID が使い回された）の「利用者が使った」印は消す
        # （古い印で、別のプロセスを止めなくならないように）。ほかのレーンの印は、自分が見張ったことのある PID だけを対象にして消さない
        foreach ($old in $previous) {
            $now = @($this.State.Pids | Where-Object { $_.Id -eq $old.Id })
            if ($now.Count -eq 0 -or $now[0].StartTicks -ne $old.StartTicks) {
                $removed = $null
                [void]$this.State.Users.TryRemove([int]$old.Id, [ref]$removed)
            }
        }
        foreach ($entry in @($this.State.Pids)) {
            $mark = $null
            if ($this.State.Users.TryGetValue([int]$entry.Id, [ref]$mark) -and $mark.StartTicks -ne $entry.StartTicks) {
                $removed = $null
                [void]$this.State.Users.TryRemove([int]$entry.Id, [ref]$removed)
            }
        }
    }

    [void] Start() {
        # 見張りは別のランスペースで動くので、照合の関数の定義を渡す（式を書き写さない。worker_pool.ps1 と同じ InitialSessionState の形）
        $sessionState = [System.Management.Automation.Runspaces.InitialSessionState]::CreateDefault2()
        $functionNames = @('isSameOfficeProcess', 'compareOfficeProcess', 'getOfficeStartTicks', 'testOfficeProcessHasWindow', 'getWatchdogVerdict')
        if ($this.State.WindowProbe -and $functionNames -notcontains [string]$this.State.WindowProbe) {
            $functionNames += [string]$this.State.WindowProbe
        }
        foreach ($name in $functionNames) {
            $sessionState.Commands.Add([System.Management.Automation.Runspaces.SessionStateFunctionEntry]::new($name, (Get-Command $name -CommandType Function).Definition))
        }
        $runspace = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace($sessionState)
        $runspace.Open()
        $ps = [PowerShell]::Create()
        $ps.Runspace = $runspace
        [void]$ps.AddScript({
            param($watch, [string[]]$processNames)
            while (-not $watch.Stop) {
                Start-Sleep -Milliseconds 500
                $deadline = $watch.Deadline
                if ($deadline -eq [datetime]::MaxValue) {
                    continue
                }
                $due = ([datetime]::Now -ge $deadline)
                # 取り込み中は毎回、窓のあるプロセスに「利用者が使った」印を残す（固まったプロセスの窓は、約 5 秒で別のプロセスのゴースト窓に差し替わって
                # 見えなくなるので、制限時間を過ぎたときに見るだけでは足りない。固まる前に見た窓を、固まった後の判断に使う）。
                # 制限時間を過ぎたとき、印のあるプロセスは止めず、止めた分だけを targets に集める
                $spared = $false
                $targets = New-Object System.Collections.Generic.List[object]
                foreach ($entry in @($watch.Pids)) {
                    # 期限の前に見るのは、窓を見張るアプリ（PowerPoint）だけ（ほかは期限を過ぎてから見る）
                    if (-not $due -and -not $entry.GuardWindow) {
                        continue
                    }
                    $process = $null
                    $keep = $false
                    try {
                        # 終了済みでIDが別のプロセスに再利用されている場合に備え、Officeアプリであること、控えたときと同じプロセスであること（名前・起動時刻）を確かめる
                        $process = [System.Diagnostics.Process]::GetProcessById([int]$entry.Id)
                        if ((isSameOfficeProcess $process $entry.ProcessName $entry.StartTicks) -and $processNames -contains $process.ProcessName) {
                            $hasWindow = $false
                            if ($entry.GuardWindow) {
                                $hasWindow = [bool](& $watch.WindowProbe $process)
                            }
                            $verdict = getWatchdogVerdict $entry $hasWindow $watch.Users $due
                            if ($verdict -eq 'Spare') {
                                $spared = $true
                            } elseif ($verdict -eq 'Kill') {
                                $targets.Add(@{ Entry = $entry; Process = $process })
                                $keep = $true
                            }
                        }
                    } catch {
                    } finally {
                        if ($null -ne $process -and -not $keep) {
                            try { $process.Dispose() } catch {}
                        }
                    }
                }
                if (-not $due) {
                    continue
                }
                $watch.Deadline = [datetime]::MaxValue
                if ($spared -and $null -ne $watch.Abandon) {
                    $watch.Abandon.Abandoned = $true
                }
                if ($targets.Count -gt 0 -or -not $spared) {
                    $watch.TimedOut = $true
                }
                foreach ($target in $targets) {
                    try {
                        if (isSameOfficeProcess $target.Process $target.Entry.ProcessName $target.Entry.StartTicks) {
                            $target.Process.Kill()
                        }
                    } catch {
                    } finally {
                        try { $target.Process.Dispose() } catch {}
                    }
                }
            }
        }).AddArgument($this.State).AddArgument($this.ProcessNames)
        $this.Thread = @{ PowerShell = $ps; Runspace = $runspace; Handle = $ps.BeginInvoke() }
    }

    [void] Stop() {
        if ($null -eq $this.Thread) {
            return
        }
        $this.State.Stop = $true
        try { [void]$this.Thread.PowerShell.EndInvoke($this.Thread.Handle) } catch {}
        $this.Thread.PowerShell.Dispose()
        $this.Thread.Runspace.Dispose()
        $this.Thread = $null
    }

    [bool] IsRunning() {
        return ($null -ne $this.Thread)
    }
}

$script:officeWatchdog = [OfficeWatchdog]::new([string[]]@($appInfo.Values | ForEach-Object { $_.Process }))

# 取り込んだ・元のファイルが無くなったフォルダを、本文インデックスに書き出してよいかを決める（PendingPublish）。
# フォルダごとの取り込み中の数（Busy）とまだ渡していない数（Pending）を数え、どちらも 0 になったフォルダを
# 書き出してよいフォルダとして返す（TakeFlushable）。取り込みの前に無くなったフォルダ（Skip）・後回し（Complete。
# 成功・失敗と同じ扱い）も、この数に反映する。書き出し（publishIndexFolders）は司令（invokeIndexerBody）が呼ぶ。

class PendingPublish {
    # フォルダ（フルパス）→ そのフォルダで無くなった元のファイル名の集まり。まだ書き出していないもの
    hidden [System.Collections.Generic.Dictionary[string,object]]$Folders
    # フォルダごとの、取り込み中の数（Busy）・まだ渡していない数（Pending）。どちらも 0 で書き出してよい
    hidden [System.Collections.Generic.Dictionary[string,int]]$Busy
    hidden [System.Collections.Generic.Dictionary[string,int]]$Pending

    PendingPublish() {
        $this.Folders = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
        $this.Busy = New-Object 'System.Collections.Generic.Dictionary[string,int]' ([System.StringComparer]::OrdinalIgnoreCase)
        $this.Pending = New-Object 'System.Collections.Generic.Dictionary[string,int]' ([System.StringComparer]::OrdinalIgnoreCase)
    }

    [void] MarkFolder([string]$folder) {
        # 前回のインデックス作成で本文インデックスに入れていないフォルダを、書き出し待ちにする（無くなったファイルの記録は無し）
        if (!$this.Folders.ContainsKey($folder)) {
            $this.Folders[$folder] = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
        }
    }

    [void] Add([string]$relPath, [bool]$removed) {
        # 取り込んだ・無くなった元のファイルのフォルダを、書き出し待ちにする
        $folder = [System.IO.Path]::GetDirectoryName((getBookDir $relPath))
        if (!$this.Folders.ContainsKey($folder)) {
            $this.Folders[$folder] = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
        }
        if ($removed) {
            [void]$this.Folders[$folder].Add([System.IO.Path]::GetFileName($relPath))
        }
    }

    [void] AddPending([string]$folder) {
        # 取り込み対象を数えるとき、そのファイルの分だけ「まだ渡していない数」を1つ足す
        $this.Pending[$folder] = [int]$this.Pending[$folder] + 1
    }

    [void] Dispatch([string]$folder) {
        # ファイルを1つ、取り込みのスレッド（または司令のスレッド）に渡す（渡していない→取り込み中）
        $this.Pending[$folder] = [int]$this.Pending[$folder] - 1
        $this.Busy[$folder] = [int]$this.Busy[$folder] + 1
    }

    [void] Skip([string]$folder) {
        # ファイルを1つ、渡さずに済ませる（取り込みの直前に元のファイルが無くなった等。取り込み中にはしない）
        $this.Pending[$folder] = [int]$this.Pending[$folder] - 1
    }

    [void] Complete([string]$folder) {
        # 取り込み中のファイルが1つ終わる（成功・失敗・後回しのどれでも）
        $this.Busy[$folder] = [int]$this.Busy[$folder] - 1
    }

    [System.Collections.Generic.Dictionary[string,object]] TakeFlushable() {
        # 取り込み中・まだ渡していないファイルがどちらも無いフォルダを取り出し、書き出し待ちから外して返す
        $keep = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($folder in @($this.Busy.Keys | Where-Object { $this.Busy[$_] -gt 0 })) {
            [void]$keep.Add($folder)
        }
        foreach ($folder in @($this.Pending.Keys | Where-Object { $this.Pending[$_] -gt 0 })) {
            [void]$keep.Add($folder)
        }
        return $this.take($keep)
    }

    [System.Collections.Generic.Dictionary[string,object]] TakeAll() {
        # 取り込み中・まだ渡していない数を見ずに、書き出し待ちのフォルダをすべて取り出す
        # （インデックス作成の終わり。中止・続けられないエラーでも、取り込んだ分は残さず書き出す）
        return $this.take((New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)))
    }

    hidden [System.Collections.Generic.Dictionary[string,object]] take($keep) {
        $flush = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($folder in @($this.Folders.Keys)) {
            if (!$keep.Contains($folder)) {
                $flush[$folder] = $this.Folders[$folder]
                [void]$this.Folders.Remove($folder)
            }
        }
        return $flush
    }
}

# インデックス作成の司令のスレッドの進み具合と、画面の確認待ちをまとめる（IndexingReporter）。
# 受け渡しの口（newIndexerChannel。hashtable のまま）を持ち、進み具合を書く（writeIndexingProgress を呼ぶ）・
# 画面の確認を待つ（waitForIndexingApproval だった処理をメソッドにした）。
# ログ（writeIndexerLog・$script:indexerLog）は部品として別に残し、ここには入れない（docs/design/structure/classes.md）。
# クラスの本体では $script: 変数を直接読まない（docs/design/structure/classes.md「クラスと関数の使い分け」）ため、
# インデックス作成の段階（${indexingPhase*}）は呼び出し元（司令）から引数で受け取る

class IndexingReporter {
    # 受け渡しの口（画面とやり取りする hashtable。newIndexerChannel）
    $Channel

    IndexingReporter($channel) {
        $this.Channel = $channel
    }

    [void] Progress([string]$phase, [int]$processed, [int]$remaining, [int]$failed, [string]$detail) {
        # インデックス作成の進み具合を受け渡しの口に書く（画面が 1 秒ごとに読む）
        writeIndexingProgress $phase $processed $remaining $failed $detail $this.Channel
    }

    [object] WaitForApproval([string]$phase, $plan, [int]$targetCount, [int]$failedCount, [int]$timeoutMinutes) {
        # 取り込み対象の件数を画面に渡し、［更新を開始］か［キャンセル］の返事を待つ。
        #   取り込む → @{ RetryFailed; IncludeCloud } / 取りやめ（中止を求められた場合を含む） → $null
        # 画面が返事をしないまま待ち続けないよう、timeoutMinutes で打ち切って取りやめる。
        # ローカル変数はプロパティ名 Channel と大文字・小文字だけの違いにしない（$ch にする。PowerShell のクラスは
        # 同名（大文字・小文字を区別しない）のローカル変数への代入をプロパティへの代入と見なし、$this. を要求してエラーになる）
        $ch = $this.Channel
        [void]$ch.Answered.Reset()
        $ch.Answer = $null
        $ch.Plan = @($plan)
        writeIndexingProgress $phase 0 $targetCount $failedCount "更新する内容を画面で確認しています…" $ch
        writeIndexerLog ""
        writeIndexerLog "取り込み対象を画面に表示しました。［更新を開始］が押されるまで待ちます。（${timeoutMinutes} 分待っても返事が無ければ取りやめます）"

        try {
            if (!$ch.Answered.WaitOne([TimeSpan]::FromMinutes($timeoutMinutes))) {
                writeIndexerLog "画面からの返事が ${timeoutMinutes} 分ありませんでした。インデックス作成を取りやめます。" "Yellow"
                return $null
            }
            if ($ch.Stop) {
                return $null
            }
            return $ch.Answer
        } finally {
            $ch.Plan = $null
        }
    }
}

# クロール（どのファイルを取り込むかを数え、画面の返事を待つ）。

# 取り込み対象の拡張子（Office は shared\office\office_files.ps1、テキストは shared\core\text_file.ps1、PDF は shared\core\pdf_file.ps1）
$targetExtensions = @(${officeExtensions}) + @(${textExtensions}) + @(${pdfExtensions})

# tebunko が作ったファイルを、名前だけで見分けるパターン（テキストの拡張子のものだけに当たる。どこにあっても外す）。
#   ・今の版の本文インデックス（content_index.xlsx.001.tsv 等。contentIndexFileNamePattern と同じ組み立て）
#   ・前の版（名前をそろえる前）の本文インデックスのファイル（content.xlsx.001.tsv 等）
#   ・システムインデックス（今の版 system_index*.txt・前の版 システムインデックス*.txt。search_gram.ps1 の systemIndexFileName・
#     workspace.ps1 の legacySystemIndexPattern と同じ組み立て）
${tebunkoOwnFileNamePatterns} = @(
    "${contentIndexFileNamePrefix}.*.tsv",
    "content.*.tsv",
    "$([System.IO.Path]::GetFileNameWithoutExtension(${systemIndexFileName}))*.txt",
    ${legacySystemIndexPattern}
)

function testTebunkoOwnFileName {
    # ファイル名（拡張子を含む）が、上のパターンのどれかに当たるか
    param (
        [string]$name
    )

    foreach ($pattern in ${tebunkoOwnFileNamePatterns}) {
        if ($name -like $pattern) {
            return $true
        }
    }
    return $false
}

# ----------------------------------------------------------------------------
# 取り込み対象
# ----------------------------------------------------------------------------

function selectOnlyNames {
    # 選んだインデックス名（onlyNames）を、名前を割り当て済みのクロール対象フォルダ（folders）に当てはめる。
    # 戻り値: @{ Selected（今回更新する名前の集合。大文字・小文字を区別しない）; Skipped（更新できない名前の @{ Name; Reason } の配列） }
    # 更新できないのは、設定に無い名前と、チェックが付いていない名前（チェックを付けるのは画面側）
    param (
        [object[]]$folders,
        [string[]]$onlyNames
    )

    $selected = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $skipped = New-Object System.Collections.Generic.List[object]
    foreach ($name in @($onlyNames | Where-Object { $_ })) {
        $folder = @($folders | Where-Object { $_.Name -eq $name }) | Select-Object -First 1
        if (!$folder) {
            $skipped.Add([pscustomobject]@{ Name = $name; Reason = "設定にありません" })
        } elseif (!$folder.Enabled) {
            $skipped.Add([pscustomobject]@{ Name = $name; Reason = "チェックが付いていません" })
        } else {
            [void]$selected.Add($name)
        }
    }
    return @{ Selected = $selected; Skipped = $skipped.ToArray() }
}

function getBookDir {
    # 取り込み対象のファイルの相対パスから、そのファイルのインデックスを入れるフォルダを返す。
    # 相対パスの最後は元のファイル名のため、インデックスフォルダと相対パスをつなぐとフォルダ名になる
    #   例: "営業\2024\A社.xlsx" → "work\index\営業\2024\A社.xlsx"（この中に "明細.tsv" 等を入れる）
    param (
        [string]$relPath
    )

    return (Join-Path $workspace.IndexDir $relPath)
}

function removeBookDir {
    # そのファイルのインデックスのフォルダを削除する（元のファイルが無くなったとき・取り込み直すとき）。
    # ウイルス対策ソフト・エクスプローラーが一時的に掴んでいることがあるため、少し待って数回試す
    param (
        [string]$bookDir
    )

    removeDirectoryRetry $bookDir
}

function getTebunkoExcludeDirs {
    # 除外するフォルダ（tebunko が作ったワークスペース）の一覧を返す。
    #   ・今のワークスペース（$workspace.Entries()。content_index・前の版の index・system_index・取り込み一覧 等）
    #   ・スキャンで見つけたファイルの中に取り込み一覧（$workspace.StatusFile と同じ名前）があれば、
    #     そのフォルダをほかのワークスペースとみなし、その Entries() も外す
    #     （以前の既定の場所・切り替える前のワークスペース・ほかの人のワークスペースを、テキストの拡張子（.tsv 等）で拾わないため）
    param (
        [object[]]$scannedFiles
    )

    $statusFileName = [System.IO.Path]::GetFileName($workspace.StatusFile)
    $dirs = New-Object System.Collections.Generic.List[string]
    $dirs.AddRange([string[]]$workspace.Entries())
    foreach ($file in $scannedFiles) {
        if ($file.Name -eq $statusFileName) {
            $otherDir = [System.IO.Path]::GetDirectoryName((fromLongPath $file.FullName))
            $dirs.AddRange([string[]]([Workspace]::new($otherDir).Entries()))
        }
    }
    return @($dirs | Where-Object { $_ } | Select-Object -Unique)
}

function testUnderAnyDir {
    # \\?\ 付きのフルパス（またはそのもの）が、dirs（\\?\ の付かない通常のパス）のどれかの下・そのものかを返す。
    #   dirPrefixes: dirs を toLongPath して末尾の \ を外したもの（呼び出し側で 1 回だけ作り、ファイルごとに作り直さない）
    param (
        [string]$fullName,
        [string[]]$dirPrefixes
    )

    foreach ($prefix in $dirPrefixes) {
        if ($fullName.Equals($prefix, [System.StringComparison]::OrdinalIgnoreCase) -or
            $fullName.StartsWith("$prefix\", [System.StringComparison]::OrdinalIgnoreCase)) {
            return $true
        }
    }
    return $false
}

function findTargetFiles {
    # クロール対象フォルダ配下の、取り込み対象（Office・テキストの拡張子）のファイルを検索し、
    # @{ Root; Files; HasError（アクセスできないフォルダがあった） } を返す。
    # Root は実際に列挙したフォルダ（\\?\ の付かない通常のパス）。相対パスはこの Root から求める
    # （設定に書かれたパスは、末尾の \ ・ドライブ文字と UNC パスなど書き方が違うことがあるため、文字数で切り出さない）。
    # tebunko が作ったファイル（getTebunkoExcludeDirs のフォルダの下・名前で分かるファイル）は対象に含めない
    param (
        [string]$targetFolder
    )

    # \\?\ を付けないと、パスが約248文字を超えるフォルダの中を検索できない（アクセスできないフォルダ扱いになる）。
    # 見つかったファイルの FullName は \\?\ 付きになる（fromLongPath で戻す）
    $scanErrors = $null
    $root = (Resolve-Path -LiteralPath $targetFolder).ProviderPath
    $scanned = @(Get-ChildItem -LiteralPath (toLongPath $root) -Recurse -File -ErrorAction SilentlyContinue -ErrorVariable scanErrors |
        Where-Object { ($targetExtensions -contains $_.Extension.ToLower()) -and -not $_.Name.StartsWith('~$') })

    # 除外するフォルダの \\?\ 付きの前方一致の文字列を先に作る（ファイルごとにドライブの割り当てをたどる処理は呼ばない）。
    # このクロール対象フォルダの外にあるものは、どのファイルにも当たらないため先に落とす（比べる数を減らす）
    $longRootPrefix = (toLongPath $root).TrimEnd("\")
    $excludeDirPrefixes = @(getTebunkoExcludeDirs $scanned | ForEach-Object { (toLongPath $_).TrimEnd("\") } | Where-Object {
        $_.Equals($longRootPrefix, [System.StringComparison]::OrdinalIgnoreCase) -or $_.StartsWith("$longRootPrefix\", [System.StringComparison]::OrdinalIgnoreCase)
    })
    $files = @($scanned | Where-Object {
        if ($excludeDirPrefixes.Count -gt 0 -and (testUnderAnyDir $_.FullName $excludeDirPrefixes)) { return $false }
        # 名前で分かる tebunko のファイル（content_index.*.tsv 等）は、テキストの拡張子にしか当たらないため、それだけ調べる
        if ((testTextExtension $_.Name) -and (testTebunkoOwnFileName $_.Name)) { return $false }
        return $true
    })

    return @{ Root = $root; Files = $files; HasError = (@($scanErrors).Count -gt 0) }
}

function createTargetList {
    # クロール対象フォルダを1つ検索して取り込み一覧の行を作り直し、次を返す。
    #   Rows   : 全ファイルの行 / Targets: 取り込む行 / Failed: 前回失敗し、更新の無い行
    #   Cloud  : 取り込む（または前回失敗した）ファイルのうち、クラウドにだけあるもの（OneDrive 等のオンデマンド）。
    #            開くとダウンロードされるため Targets・Failed には入れず、呼び出し元が取り込むかを決める。
    #            各要素は @{ RelPath; Row（取り込むときの行）; Old; Failed; Length; PendingOld }。
    #            Rows には前回の行をそのまま入れる（前回の行が無い・前回未完了のときは入れない）
    #   Plan   : 画面の確認に出す件数（newIngestPlanRow。取り込み予定.tsv の1行）
    #   Removed: 元のファイルが無くなったファイルの相対パス（呼び出し元が本文インデックスのファイルから外す）
    # 行の相対パスは "インデックス名\フォルダからの相対パス"（= work\index からの相対パス）とする。
    # ・前回の一覧と更新日時・サイズが同じで取り込み済み（済）のファイルは取り込まない
    # ・取り込み済みでも、インデックス（TSV）が無くなっていれば取り込み直す（利用者が work\index を直接削除した場合など）
    # ・元ファイルが無くなったファイルは、インデックスを削除して一覧から除く（アクセスできないフォルダがあった場合は除かない）
    param (
        $folder,   # @{ Path; Name }
        $previous, # readStatusFile の Rows（相対パス → 行）
        $counts    # getIndexTsvCounts の結果（インデックスの実体。$null なら確認しない）
    )

    $prefix = "$($folder.Name)\"
    $scan = findTargetFiles $folder.Path
    $rows = New-Object System.Collections.Generic.List[object]
    $targets = New-Object System.Collections.Generic.List[object]
    $failed = New-Object System.Collections.Generic.List[object]
    $cloud = New-Object System.Collections.Generic.List[object]
    # 取り込み予定に出す、クラウドにだけあるファイルの件数と容量（取り込みの対象と、前回失敗を分けて、下のループで足す）
    $cloudCount = 0
    $cloudFailedCount = 0
    [long]$cloudBytes = 0
    [long]$cloudFailedBytes = 0
    $found = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $count = @{ Done = 0; New = 0; Updated = 0; Pending = 0; Lost = 0 }

    # 列挙したファイルの FullName は、\\?\ 付きの Root で始まる。ファイルが多いと1件ずつの関数呼び出しだけで
    # 時間がかかるため、その場合は先頭を切り落として相対パスにする（それ以外は getPathUnderFolder で求める）
    $longRoot = (toLongPath $scan.Root).TrimEnd("\") + "\"
    foreach ($file in $scan.Files) {
        $fullName = $file.FullName
        if ($fullName.Length -gt $longRoot.Length -and $fullName.StartsWith($longRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
            $relative = $fullName.Substring($longRoot.Length)
        } else {
            $relative = getPathUnderFolder (fromLongPath $fullName) $scan.Root
        }
        if ($null -eq $relative -or $relative -eq "") {
            $relative = $file.Name  # 通常は起こらない（$scan.Root の下を列挙している）
        }
        $relPath = $prefix + $relative
        [void]$found.Add($relPath)
        $updated = formatFileTime $file.LastWriteTime
        $size = [string]$file.Length

        $old = $null
        [void]$previous.TryGetValue($relPath, [ref]$old)

        # 取り込むかどうかの判断は indexer_decide.ps1（テストしやすいように分けてある）
        # インデックス（TSV）の有無は、前回と同じファイルで「済」のときだけ調べる（取り込み直すものには要らない）
        $indexComplete = $true
        if ($old -and $old.状態 -eq ${stateDone} -and $old.更新日時 -eq $updated -and $old.サイズ -eq $size) {
            $indexComplete = [bool](testIndexComplete $old $relPath $counts)
        }
        $decision = getIngestDecision $old $updated $size $indexComplete

        # 読む必要があるファイル（取り込む・前回失敗）だけ、クラウドにだけあるかを調べる。
        # 属性は一覧が返したものを見るだけで、ファイルは開かない（ダウンロードは起きない）
        if (($decision.Ingest -or $decision.Reason -eq "failed") -and (testCloudOnlyAttributes ([int]$file.Attributes))) {
            $isFailed = (-not $decision.Ingest)
            $pendingOld = [bool]($old -and $old.状態 -eq ${stateNew})
            if ($isFailed) {
                $cloudFailedCount++
                $cloudFailedBytes += [long]$file.Length
            } else {
                $cloudCount++
                $cloudBytes += [long]$file.Length
            }
            $cloud.Add(@{
                RelPath    = $relPath
                Row        = $(if ($isFailed) { $old } else { newStatusRow $relPath $updated $size ${stateNew} })
                Old        = $old
                Failed     = $isFailed
                Length     = [long]$file.Length
                PendingOld = $pendingOld
            })
            # 取り込まないときは前回の行を残す（前回の行が無い・前回未完了なら、行を作らない）
            if ($old -and -not $pendingOld) {
                $rows.Add($old)
            }
            continue
        }

        if (-not $decision.Ingest) {
            # 更新なし。失敗したファイルを再取り込みするかは呼び出し元で決める
            $row = $old
            if ($decision.Reason -eq "failed") {
                $failed.Add($row)
            } else {
                $count.Done++
            }
        } else {
            $row = newStatusRow $relPath $updated $size ${stateNew}
            $targets.Add($row)
            switch ($decision.Reason) {
                "lost"    { $count.Lost++ }
                "new"     { $count.New++ }
                "pending" { $count.Pending++ }
                default   { $count.Updated++ }  # updated と outdated（前の抽出版で取り込んだ。画面では更新ありと同じに扱う）
            }
        }
        $rows.Add($row)
    }

    $removed = New-Object System.Collections.Generic.List[string]
    foreach ($relPath in @($previous.Keys)) {
        if (!$relPath.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase) -or $found.Contains($relPath)) {
            continue
        }
        if ($scan.HasError) {
            $rows.Add($previous[$relPath])
            continue
        }
        removeBookDir (getBookDir $relPath)
        $removed.Add($relPath)
    }

    $detail = "取り込み済み {0} 件 / 新規 {1} 件 / 更新あり {2} 件 / 前回未完了 {3} 件 / 前回失敗 {4} 件" -f
        $count.Done, $count.New, $count.Updated, $count.Pending, $failed.Count
    if ($count.Lost -gt 0) {
        # インデックスを直接削除された場合など。ふだんは 0 件のため、あるときだけ表示する
        $detail += " / インデックスが無い・壊れている $($count.Lost) 件"
    }
    if ($cloud.Count -gt 0) {
        $detail += " / クラウドにだけある $($cloud.Count) 件"
    }
    writeIndexerLog ("  [{0}] 対象ファイル {1} 件（{2}）" -f $folder.Name, $scan.Files.Count, $detail)
    if ($count.Lost -gt 0) {
        writeIndexerLog "    インデックス（TSV）が無くなった・壊れている $($count.Lost) 件は取り込み直します。（インデックスを直接削除した・0 バイトのTSVが残っている）" "Yellow"
    }
    if ($removed.Count -gt 0) {
        writeIndexerLog "    元ファイルが無くなった $($removed.Count) 件は、インデックスから除きます。"
    }
    if ($scan.HasError) {
        writeIndexerLog "    アクセスできないフォルダがあったため、元ファイルが無くなったかどうかの確認は行いませんでした。" "Yellow"
    }

    $plan = newIngestPlanRow $folder.Name $folder.Path ${planKindIngest} $scan.Files.Count $targets.Count `
        $count.New $count.Updated $count.Pending $count.Lost $failed.Count `
        $cloudCount $cloudFailedCount $cloudBytes $cloudFailedBytes
    return @{ Rows = $rows; Targets = $targets; Failed = $failed; Cloud = $cloud; Plan = $plan; Removed = $removed.ToArray() }
}

# ----------------------------------------------------------------------------
# 取り込む順番を決める（IngestPlanner）
# ----------------------------------------------------------------------------

# インデックス作成の司令（invokeIndexerBody）の前半。クロール対象フォルダにインデックス名を割り当て、クロールして、
# 取り込む順番（Targets）・画面に出す件数（Plan）・取り込み一覧に書く行（Rows）を組み立てる。
# 取り込み直すかの判断は indexer_decide.ps1（判断層）の関数を、createTargetList 経由でそのまま呼ぶ。
# 進み具合・画面の確認・取り込み一覧の読み書きは持たない（IndexingReporter・StatusLedger を司令がつなぐ）。
# クラスの本体では $script: 変数を読まない決まり（docs/design/structure/classes.md。テストと本番で読める範囲が違うため）なので、
# 計画の種類・状態の値は kinds（Unchecked・Missing・Dropped・StateFailed の 4 つ。足りなければ例外）、
# 名前の保存は、司令が渡す save（割り当てた名前を設定に保存し、保存した一覧を返すスクリプトブロック。IndexCatalog.StoreAssignedNames）に任せる。
# メソッドは次の順に呼ぶ: AssignNames → SaveNames → SelectOnly（選んだときだけ）→ Crawl →
#   KeepForCancel（取りやめるとき）か ApplyFailed → ApplyInterrupted → FolderByName。Crawl は AssignNames より前なら例外にする。
# メソッドの中のローカル変数は、プロパティと大文字・小文字だけの違いにしない
class IngestPlanner {
    # 名前を割り当てたクロール対象フォルダ（@{ Path; Name; Enabled } の並び）
    [object[]]$Folders
    # 前回の取り込み一覧の行（相対パス → 行）
    $Previous
    # 設定から外れたインデックス（findDroppedIndexes の結果）
    [object[]]$Dropped
    # 選んだインデックスだけを更新するときの当てはめ（selectOnlyNames の結果。選ばなければ $null）
    $Only
    # 全ファイルの行・取り込む行・前回失敗し更新の無い行・クラウドにだけあるファイル・画面の確認に出す件数
    [System.Collections.Generic.List[object]]$Rows
    [System.Collections.Generic.List[object]]$Targets
    [System.Collections.Generic.List[object]]$Failed
    # クラウドにだけあるファイル（createTargetList の Cloud。取り込むかは確認の後に司令が決める）
    [System.Collections.Generic.List[object]]$Cloud
    [System.Collections.Generic.List[object]]$Plan
    # 元のファイルが無くなったファイルの相対パス（司令が本文インデックスのファイルから外す）
    [System.Collections.Generic.List[string]]$RemovedPaths
    # 前回、取り込み中に強制終了して最後に回したファイル（相対パス → 回数）
    $Carried
    hidden $Kinds

    IngestPlanner([hashtable]$kinds) {
        foreach ($key in @("Unchecked", "Missing", "Dropped", "StateFailed")) {
            if (-not $kinds.ContainsKey($key) -or $null -eq $kinds[$key]) {
                throw "IngestPlanner: kinds に $key がありません"
            }
        }
        $this.Kinds = $kinds
        $this.Rows = New-Object System.Collections.Generic.List[object]
        $this.Targets = New-Object System.Collections.Generic.List[object]
        $this.Failed = New-Object System.Collections.Generic.List[object]
        $this.Cloud = New-Object System.Collections.Generic.List[object]
        $this.Plan = New-Object System.Collections.Generic.List[object]
        $this.RemovedPaths = New-Object System.Collections.Generic.List[string]
        $this.Carried = New-Object 'System.Collections.Generic.Dictionary[string,int]' ([System.StringComparer]::OrdinalIgnoreCase)
    }

    [void] AssignNames($targetFolders, $status) {
        # クロール対象フォルダごとにインデックス名（work\content_index 直下のフォルダ名）を決める。前回と同じフォルダは同じ名前を使う。
        # status: 取り込み一覧（StatusLedger の ReadStatus。@{ Folders; Rows }）。
        # 設定から外れたインデックスは、ここでは消さない（確認ダイアログに「削除予定」として出す）
        $this.Folders = @(assignIndexNames $targetFolders $status.Folders)
        $this.Previous = $status.Rows
        $this.Dropped = @(findDroppedIndexes $this.Folders $status.Folders)
    }

    [void] SaveNames($targetFolders, [scriptblock]$save) {
        # 新しく割り当てたインデックス名を設定に保存する（インデックスの「名前」と「置き場所」を設定で分けて持つため。
        # 名前が設定にあれば、フォルダを移してパスを書き換えても同じインデックスとして扱える）
        if (@($targetFolders | Where-Object { -not $_.Name }).Count -eq 0) {
            return
        }
        # 保存した一覧（読み直して名前だけを足したもの）の名前で続ける。この間に画面で外した・名前を付けられなかったフォルダは、今回は取り込まない
        $saved = @(& $save $this.Folders)
        $this.Folders = @($saved | Where-Object {
            $savedPath = $_.Path
            $_.Name -and @($targetFolders | Where-Object { $_.Path -eq $savedPath }).Count -gt 0
        })
        writeIndexerLog "インデックス名を設定に保存しました: $((@($this.Folders | ForEach-Object { $_.Name }) -join '、'))"
    }

    [object[]] SelectOnly([string[]]$onlyNames) {
        # 選んだインデックスだけを更新するとき。選ばなかったインデックスは、この回では一切触らない
        # （取り込み一覧の行は前回のまま・確認の表に出さない・失敗の一覧に加えない）。
        # 更新できない名前（@{ Name; Reason } の並び）を返す。更新できるものが 1 つも無いかは Only.Selected.Count で見る
        $this.Only = selectOnlyNames $this.Folders $onlyNames
        foreach ($skip in $this.Only.Skipped) {
            writeIndexerLog "  [$($skip.Name)] 更新できません（$($skip.Reason)）" "Yellow"
        }
        return @($this.Only.Skipped)
    }

    [void] Crawl($indexCounts, [scriptblock]$onFolder) {
        # クロール対象フォルダを順に検索して、Rows・Targets・Failed・Plan・RemovedPaths を組み立てる。
        # onFolder: フォルダを検索する直前に呼ぶ（司令が進み具合を画面に出す。$null なら何もしない）
        if ($null -eq $this.Folders) {
            throw "IngestPlanner: Crawl の前に AssignNames を呼んでください"
        }
        foreach ($folder in $this.Folders) {
            if ($null -ne $this.Only -and !$this.Only.Selected.Contains([string]$folder.Name)) {
                # 選ばなかったインデックス（下で前回の結果をそのまま残す）
            } elseif (-not $folder.Enabled) {
                writeIndexerLog "  [$($folder.Name)] $($folder.Path) … チェックなしのため取り込みません（インデックスはそのまま残します）"
                $this.Plan.Add((newIngestPlanRow $folder.Name $folder.Path $this.Kinds.Unchecked))
            } elseif (!(Test-Path -LiteralPath $folder.Path -PathType Container)) {
                writeIndexerLog "  [$($folder.Name)] $($folder.Path) … フォルダが見つからないため取り込みません" "Yellow"
                $this.Plan.Add((newIngestPlanRow $folder.Name $folder.Path $this.Kinds.Missing))
            } else {
                writeIndexerLog "  [$($folder.Name)] $($folder.Path)"
                if ($null -ne $onFolder) {
                    $null = & $onFolder $folder
                }
                $list = createTargetList $folder $this.Previous $indexCounts
                $this.Rows.AddRange($list.Rows)
                $this.Targets.AddRange($list.Targets)
                $this.Failed.AddRange($list.Failed)
                $this.Cloud.AddRange($list.Cloud)
                $this.Plan.Add($list.Plan)
                $this.RemovedPaths.AddRange([string[]]@($list.Removed))
                continue
            }

            # 取り込まないフォルダは前回の結果をそのまま残す
            $prefix = "$($folder.Name)\"
            foreach ($key in @($this.Previous.Keys)) {
                if ($key.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) {
                    $this.Rows.Add($this.Previous[$key])
                }
            }
        }

        foreach ($item in $this.Dropped) {
            $this.Plan.Add((newIngestPlanRow $item.Name $item.Path $this.Kinds.Dropped))
        }
    }

    [object[]] KeepForCancel() {
        # 画面で取りやめたときに書く取り込み一覧の行。1件も取り込んでいないため、取り込み対象にした行は前回の記録のまま
        # （一覧に無かったファイルは記録しない）にする。「未取り込み」で記録すると、次回［すべて更新］が［続きから再開］になり、
        # 中断したように見えるため
        $targetPaths = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($row in $this.Targets) {
            [void]$targetPaths.Add($row.相対パス)
        }
        $keep = New-Object System.Collections.Generic.List[object]
        # クラウドにだけあって前回未完了のファイルは、取り込み一覧に前回の行を残す（取りやめでは何も消さない）
        foreach ($item in $this.Cloud) {
            if ($item.PendingOld) {
                $keep.Add($item.Old)
            }
        }
        foreach ($row in $this.Rows) {
            if (!$targetPaths.Contains($row.相対パス)) {
                $keep.Add($row)
                continue
            }
            $old = $null
            if ($this.Previous.TryGetValue($row.相対パス, [ref]$old)) {
                $keep.Add($old)
            }
        }
        return $keep.ToArray()
    }

    [void] ApplyFailed([bool]$retry) {
        # 前回取り込みに失敗し、その後更新されていないファイルを、取り込み直す（retry）か、スキップするかを決める
        if ($this.Failed.Count -eq 0) {
            return
        }
        writeIndexerLog ""
        if ($retry) {
            writeIndexerLog "前回取り込みに失敗し、その後更新されていないファイル $($this.Failed.Count) 件も再取り込みします。"
            $this.Targets.AddRange($this.Failed)
        } else {
            writeIndexerLog "前回取り込みに失敗し、その後更新されていないファイル $($this.Failed.Count) 件はスキップします。（パスワード付きなど）"
        }
    }

    [void] ApplyInterrupted([object[]]$entries, [int]$interruptLimit) {
        # 前回、取り込み中に強制終了した（ウィンドウを閉じた・PCが停止した等）ファイルは、同じファイルで止まり続けないよう最後に回す。
        # 続けて interruptLimit 回強制終了したファイルは、応答しなくなるファイルとみなして失敗とする。
        # 最後に回したファイルは Carried に残す（取り込みを始めるまで記録を残し、その前にまた止まっても回数が分かるように）。
        # entries: StatusLedger の ReadIngestingFiles（@{ RelPath; Count } の並び）
        foreach ($entry in $entries) {
            $hit = @($this.Targets | Where-Object { $_.相対パス -eq $entry.RelPath }) | Select-Object -First 1
            if (!$hit) {
                continue
            }
            [void]$this.Targets.Remove($hit)
            if ($entry.Count -ge $interruptLimit) {
                $hit.状態 = $this.Kinds.StateFailed
                $hit.TSV数 = ""
                $hit.取り込み日時 = formatFileTime (Get-Date)
                $hit.エラー = "更新中に $($entry.Count) 回続けて強制終了されたため、更新を中止しました（Officeアプリが応答しなくなる可能性があります）"
                writeIndexerLog ""
                writeIndexerLog "取り込み中に $($entry.Count) 回続けて強制終了したファイルは、失敗としてスキップします: $($hit.相対パス)" "Yellow"
            } else {
                $this.Targets.Add($hit)
                $this.Carried[$hit.相対パス] = $entry.Count
                writeIndexerLog ""
                writeIndexerLog "前回、取り込み中に強制終了したファイルは最後に取り込みます: $($hit.相対パス)" "Yellow"
            }
        }
    }

    [object] FolderByName() {
        # インデックス名 → クロール対象フォルダ
        $byName = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($folder in $this.Folders) {
            $byName[$folder.Name] = $folder.Path.TrimEnd("\")
        }
        return $byName
    }
}

# 1ファイルから文字を抽出して TSV に書き出す（Excel のセルは COM、Excel の図形・コメントと Word・PowerPoint はファイルを直接読む）。
# $excelMaxPath（Excelで開けるパスの長さの目安）は paths.ps1 で定義する（selectTmpDir でも使うため）

$excelExtraCells = 1000000  # 使用範囲がデータの範囲よりこのセル数以上広いシートは、データの範囲だけを一時シートにコピーしてから書き出す

# ----------------------------------------------------------------------------
# 暗号化されたファイルの扱い（office_protection.ps1・office_protection_view.ps1）
# ----------------------------------------------------------------------------

# 「形式の分からないバイナリ」（透過暗号化の製品の暗号文の見込み）をOfficeで開く予備を、アプリごとに使うかどうか。
# 実機で数秒以内に例外にならない・ダイアログが出るアプリは $false にする（docs/design/indexing/known-issues.md）
${officeFallbackEnabled} = @{ Word = $true; Excel = $true; PowerPoint = $true }

function testOfficeFallbackEnabled {
    param (
        [string]$appName
    )

    return [bool]${officeFallbackEnabled}[$appName]
}

function throwProtectionFailure {
    # 暗号化の判定で、Officeにまだ一度も触れていない状態の失敗にする。
    # invokeIngestTask（indexer_run.ps1）が、この印（Data の OfficeUntouched）を見て stopApp を呼ばずに済ませる
    # （IRM・パスワード付きのファイルが並んでも、そのたびにOfficeを起動し直さないため）
    param (
        [string]$message
    )

    $exception = New-Object System.Management.Automation.RuntimeException($message)
    $exception.Data["OfficeUntouched"] = $true
    throw $exception
}

function isOfficeRequiredException {
    # invokeIngestTask（indexer_run.ps1）と見分け方をそろえる（重複させない）
    param (
        [System.Exception]$exception
    )

    $base = $exception.GetBaseException()
    return ($base -is [System.OperationCanceledException] -and $base.Message -eq ${officeRequiredMessage})
}

function isOfficeAppInUseException {
    # invokeIngestTask（indexer_run.ps1）と見分け方をそろえる（重複させない）
    param (
        [System.Exception]$exception
    )

    $base = $exception.GetBaseException()
    return ($base -is [System.InvalidOperationException] -and $base.Message.EndsWith(${officeAppInUseMessage}))
}

function isPassthroughIngestException {
    # 見張りの時間切れ・「Officeが要る」・「利用者のOfficeが使用中」の例外は、暗号化の失敗として包み直さずそのまま通す
    param (
        [System.Exception]$exception
    )

    if ($script:officeWatchdog.State.TimedOut) {
        return $true
    }
    if (isOfficeRequiredException $exception) {
        return $true
    }
    if (isOfficeAppInUseException $exception) {
        return $true
    }
    return $false
}

function failProtectionCheck {
    # 暗号化の判定で、Officeを開く前に作業フォルダのコピーを消してから失敗にする（throwProtectionFailure）
    param (
        [string]$copyPath,
        [string]$message
    )

    Remove-Item -LiteralPath $copyPath -Force
    throwProtectionFailure $message
}

function logProtectionKind {
    # 暗号化の判定の結果をインデックス作成ログに書く（Password・Rights・Unknownだけ。旧形式・ふつうのテキストは書かない）
    param (
        [string]$kind
    )

    if ($kind -eq "Password" -or $kind -eq "Rights" -or $kind -eq "Unknown") {
        writeIndexerLog "    暗号化の判定: $kind" "Yellow"
    }
}

# ----------------------------------------------------------------------------
# 抽出
# ----------------------------------------------------------------------------

function copyDataRangeToTempSheet {
    # 使用範囲（UsedRange）が実際のデータよりずっと広いシートのために、データのある範囲だけを
    # 同じブックの一時シートへ同じ位置でコピーし、その一時シートを返す。縮める必要が無い・できない場合は $null を返す。
    #
    # 最終行・右端のセルに書式だけが残っていると使用範囲がシート全体になり、Excelのテキスト保存が
    # 空セルのタブだけで数GBを書き出して制限時間も超える（実測: 10分で6GB、終わらない）。
    # 元のシートの行・列は削除しない（そこを参照する数式が #REF! になり、ほかのシートの表示値まで変わるため）。
    param (
        $workbook,
        $worksheet
    )

    $usedRange = $worksheet.UsedRange
    try {
        $firstRow = $usedRange.Row
        $firstColumn = $usedRange.Column
        $usedLastRow = $firstRow + $usedRange.Rows.Count - 1
        $usedLastColumn = $firstColumn + $usedRange.Columns.Count - 1
    } finally {
        releaseComObject $usedRange
    }

    # 使用範囲そのものが縮める基準より狭ければ、データの範囲を探すまでもない（ほとんどのシート）。
    # 大きいシートでは Find に時間がかかるため、シートごとに呼ばないようにする
    $usedCells = [double]($usedLastRow - $firstRow + 1) * ($usedLastColumn - $firstColumn + 1)
    if ($usedCells -lt $excelExtraCells) {
        return $null
    }

    # 値・数式のある最後の行・列を探す（書式だけのセルには当たらない）。
    # 引数: What, After, LookIn（-4123 = xlFormulas）, LookAt, SearchOrder（1 = xlByRows / 2 = xlByColumns）, SearchDirection（2 = xlPrevious）
    $topLeft = $worksheet.Range("A1")
    $cells = $worksheet.Cells
    try {
        $found = $cells.Find("*", $topLeft, -4123, [Type]::Missing, 1, 2)
        $dataLastRow = if ($found) { $found.Row } else { 0 }
        $found = $cells.Find("*", $topLeft, -4123, [Type]::Missing, 2, 2)
        $dataLastColumn = if ($found) { $found.Column } else { 0 }
    } finally {
        releaseComObject $cells
        releaseComObject $topLeft
    }

    # 値のあるセルが無い（書式だけのシート）場合は、そのまま書き出して空のTSVとして扱う
    if ($dataLastRow -lt $firstRow -or $dataLastColumn -lt $firstColumn) {
        return $null
    }

    # セル数は int を超えるため double で数える（シート全体は約 172 億セル）
    $dataCells = [double]($dataLastRow - $firstRow + 1) * ($dataLastColumn - $firstColumn + 1)
    if (($usedCells - $dataCells) -lt $excelExtraCells) {
        return $null
    }

    # 数式の参照先がずれないよう、コピー先は元と同じ位置（行・列）にする
    $temp = $null
    try {
        $temp = $workbook.Worksheets.Add()
        $source = $worksheet.Range($worksheet.Cells.Item($firstRow, $firstColumn), $worksheet.Cells.Item($dataLastRow, $dataLastColumn))
        try {
            [void]$source.Copy($temp.Cells.Item($firstRow, $firstColumn))
        } finally {
            releaseComObject $source
        }
        return $temp
    } catch {
        # ブックの構成が保護されている場合など。元のシートをそのまま書き出す（時間切れで失敗することがある）
        writeIndexerLog "    $($worksheet.Name) の使用範囲を縮められませんでした: $($_.Exception.Message)" "Yellow"
        if ($temp) {
            $temp.Delete()
            releaseComObject $temp
        }
        return $null
    }
}

function extractWorkbook {
    # Excelファイルをシートごとに作業フォルダへTSV出力し、出力したシート数を返す
    param (
        [string]$sourcePath
    )

    $bookName = [System.IO.Path]::GetFileName($sourcePath)

    # 元のファイルに影響を出さないよう、作業フォルダにコピーしてからコピーを開く
    # （Excelで開いている間、元のファイルを利用者が上書き保存・移動できなくなるのを防ぐ。長いパスのファイルも開ける）。
    # ファイル名を参照する数式（CELL("filename") 等）の表示値が変わらないよう、コピーは元と同じファイル名にする。
    # 作業フォルダ＋ファイル名が長すぎてExcelで開けない場合だけ、短い名前にする。
    # コピーはブックを閉じた後に削除する（開けずに例外になった場合は、次のファイルの取り込み前・終了時に作業フォルダごと空にする）
    $copyPath = Join-Path $tmpDir $bookName
    if ($copyPath.Length -ge $excelMaxPath) {
        $copyPath = Join-Path $tmpDir ("source" + [System.IO.Path]::GetExtension($sourcePath))
    }
    copyFileShared $sourcePath $copyPath
    $openPath = $copyPath

    # 図形・コメントの文字は、テキスト保存には出ないため、新形式（ZIP）のブックを直接読む（Excel より速い）。
    # 旧形式（.xls）・パスワード付きのブックは ZIP ではないため読まない。
    # 読めなくてもセルの値は取り込めるため、インデックス作成ログに記録して続ける
    $objectUnits = $null
    $protection = $null
    if (isZipFile $copyPath) {
        $chartFailures = New-Object System.Collections.Generic.List[string]
        $chartSizeFailures = New-Object System.Collections.Generic.List[object]
        try {
            $objectUnits = readXlsxObjectUnits $copyPath $chartFailures $chartSizeFailures
        } catch {
            # サイズの上限を超えたとき（ZipSizeLimitException）は、原因を調べられるよう部品名・大きさ・
            # 部品ごとか合計かをインデックス作成のログに書く。画面には出さない（悪用のヒントになるため）
            writeZipSizeLimitLog $_.Exception
            writeIndexerLog "    図形・コメントを読み取れませんでした: $($_.Exception.Message)" "Yellow"
        }
        # 1つのグラフ・SmartArt・シートのヘッダー/フッターが読めなくても、そこだけを空にしてほかは読む（readXlsxObjectUnits）。
        # shared/ はツールを知らないため、読めなかった部品の名前・サイズの上限の詳細をここでログに書く
        foreach ($sizeFailure in $chartSizeFailures) {
            writeZipSizeLimitLog $sizeFailure
        }
        foreach ($failure in $chartFailures) {
            writeIndexerLog "    一部を読み取れませんでした: $failure" "Yellow"
        }
    } else {
        # IRM・秘密度ラベルの暗号化は、Excelを起動せずに失敗にする（サインイン画面を防ぐ）。
        # パスワード付き（既定のパスワードで暗号化されたブックを含む）は、今までどおりExcelに任せる。
        # 「形式の分からないバイナリ」（透過暗号化の製品の暗号文の見込み）は、アプリごとの切り替えが $false なら
        # Excelを起動せずに失敗にする
        $protection = getOfficeFileProtection $copyPath
        logProtectionKind $protection
        if ($protection -eq "Rights") {
            failProtectionCheck $copyPath (getProtectionFailureText "Rights")
        }
        if ($protection -eq "Unknown" -and !(testOfficeFallbackEnabled "Excel")) {
            failProtectionCheck $copyPath (getProtectionFailureText "Unknown")
        }
    }

    # 読み取り専用・リンク更新なしで開く。
    # パスワード付きのファイルは、ダイアログを出さずにエラーとするためダミーのパスワードを渡す。
    # 「形式の分からないバイナリ」で開けなかったときは、元の例外をログに書いて文言を言い換える
    # （見張りの時間切れ・「Officeが要る」・「利用者のOfficeが使用中」の例外はそのまま通す）
    $workbooks = (getApp "Excel").Workbooks
    try {
        try {
            $wb = $workbooks.Open($openPath, 0, $true, [Type]::Missing, "dummy", "dummy", $true)
        } catch {
            if ($protection -ne "Unknown" -or (isPassthroughIngestException $_.Exception)) {
                throw
            }
            writeIndexerLog "    予備の読み取りに失敗しました: $(describeIngestError $_.Exception)" "Yellow"
            throw (getProtectionFailureText "Unknown")
        }
    } finally {
        releaseComObject $workbooks
    }

    # 「形式の分からないバイナリ」は、開けた後のブックの形式（テキスト・HTML・CSVでない）も確かめる。
    # ほかの種類（HTML の .xls など）には当てない（本来読めているものまで失敗にしないため）
    if ($protection -eq "Unknown" -and !(testWorkbookFormat $wb.FileFormat)) {
        $wb.Close($false)
        releaseComObject $wb
        Remove-Item -LiteralPath $copyPath -Force
        throw (getProtectionFailureText "Unknown")
    }

    $sheets = New-Object System.Collections.Generic.List[object]
    try {
        $worksheets = $wb.Worksheets
        foreach ($ws in @($worksheets)) {
            try {
                # 非表示シートは除外（-1 = xlSheetVisible。0 = 非表示、2 = 完全に非表示）
                if ($ws.Visible -ne -1) {
                    continue
                }

                # Excelは [ ] を含むパスに保存できないため、一時ファイル名で保存し、整形時にリネームする
                $tmpPath = Join-Path $tmpDir ("sheet{0}.tmp" -f $ws.Index)
                $tsvPath = Join-Path $tmpDir (toIndexFileName $ws.Name)

                # 使用範囲が実際のデータよりずっと広いシートは、データの範囲だけを一時シートにコピーしてから書き出す
                $temp = copyDataRangeToTempSheet $wb $ws
                $target = if ($temp) { $temp } else { $ws }
                try {
                    # Excelは使用範囲（UsedRange）の左上のセルから出力するため、整形時にA1からの位置に戻せるよう控えておく。
                    # 一時シートは書式だけのセルが無く、元のシートより使用範囲が狭いことがあるため、書き出すシートから取る
                    $usedRange = $target.UsedRange
                    try {
                        $firstRow = $usedRange.Row
                        $firstColumn = $usedRange.Column
                    } finally {
                        releaseComObject $usedRange
                    }

                    [void]$target.Activate()
                    [void]$target.SaveAs($tmpPath, 42)  # 42 = xlUnicodeText
                } finally {
                    if ($temp) {
                        # 一時シートは、次のシートの Index がずれないようすぐ削除する（ブックは保存せずに閉じる）
                        $temp.Delete()
                        releaseComObject $temp
                    }
                }
                $sheets.Add(@($tmpPath, $tsvPath, $firstRow, $firstColumn))
            } finally {
                releaseComObject $ws
            }
        }
        releaseComObject $worksheets
    } finally {
        # 保存したファイルはブックを閉じるまでロックされている
        $wb.Close($false)
        releaseComObject $wb
        Remove-Item -LiteralPath $copyPath -Force
    }

    $count = 0
    foreach ($sheet in $sheets) {
        # 透過暗号化の製品が、Excelの保存したこの一時ファイルまで暗号化していないかを確かめる。
        # ブックを閉じた後（このループ）でないと、保存したファイルはExcelがロックしていて読めない
        if (!(testOfficeOutput (readFileHead $sheet[0]) "UnicodeText")) {
            throw ${officeOutputEncryptedMessage}
        }
        if (prettyTsv $sheet[0] $sheet[1] $sheet[2] $sheet[3]) {
            $count++
        }
        Remove-Item -LiteralPath $sheet[0] -Force
    }
    if ($null -ne $objectUnits) {
        $count += writeUnits $objectUnits $tmpDir
    }
    return $count
}

function extractWithWord {
    # Wordで開き、.docx 形式で保存する（旧形式 .doc 等を読めるようにするため）。
    # $format を渡すと、自動判定に任せずその形式で開く（「形式の分からないバイナリ」を開くときだけ使う。
    # 文字コードを選ぶダイアログや、暗号文をテキストとして読むことを防ぐ）
    param (
        [string]$sourcePath,
        [string]$destPath,
        $format = [Type]::Missing
    )

    # 読み取り専用で開く。パスワード付きのファイルは、ダイアログを出さずにエラーとするためダミーのパスワードを渡す
    #   引数: FileName, ConfirmConversions, ReadOnly, AddToRecentFiles, PasswordDocument, PasswordTemplate,
    #         Revert, WritePasswordDocument, WritePasswordTemplate, Format, Encoding, Visible
    $documents = (getApp "Word").Documents
    try {
        $doc = $documents.Open($sourcePath, $false, $true, $false, "dummy", "dummy", $false, "dummy", "dummy", $format, [Type]::Missing, $false)
    } finally {
        releaseComObject $documents
    }

    try {
        # 保存時のページ区切り（ページ番号の目安）を正しく記録させるため、ページ割りを確定させてから保存する
        $doc.Repaginate()
        [void]$doc.SaveAs2($destPath, 12)  # 12 = wdFormatXMLDocument（.docx）
    } finally {
        $doc.Close(0)
        releaseComObject $doc
    }
}

function extractWithPowerPoint {
    # PowerPointで開き、.pptx 形式で保存する（旧形式 .ppt 等を読めるようにするため）
    param (
        [string]$sourcePath,
        [string]$destPath
    )

    # 読み取り専用・ウィンドウ無しで開く。
    # ファイル名の後ろに "::<パスワード>::" を付けると、パスワード付きのファイルはダイアログを出さずにエラーになる
    $presentations = (getApp "PowerPoint").Presentations
    try {
        $pres = $presentations.Open("${sourcePath}::dummy::", -1, 0, 0)  # ReadOnly, Untitled = False, WithWindow = False
    } finally {
        releaseComObject $presentations
    }

    try {
        [void]$pres.SaveAs($destPath, 24)  # 24 = ppSaveAsOpenXMLPresentation（.pptx）
    } finally {
        $pres.Close()
        releaseComObject $pres
    }
}

# 読み取りのスレッド（Office を持たない）なら $true。Office が要るファイルは「Office が要る」の例外にする
$script:officeUnavailable = $false
# Office が要るときの例外の文言（invokeIngestTask が見分けて、司令に回し直しを頼む）
${officeRequiredMessage} = "このファイルの更新には Word・PowerPoint が要ります。"

function extractWithOffice {
    # Word・PowerPointどちらかで新形式に変換する（呼び分けをまとめる）。
    # $wordFormat を渡すと、Wordはその形式に固定して開く（「形式の分からないバイナリ」のときだけ渡す）
    param (
        [bool]$isWord,
        [string]$copyPath,
        [string]$readPath,
        $wordFormat = [Type]::Missing
    )

    if ($isWord) {
        extractWithWord $copyPath $readPath $wordFormat
    } else {
        extractWithPowerPoint $copyPath $readPath
    }
}

function verifyOfficeOutputIsZip {
    # Officeが保存した出力（$readPath）の先頭がZIPかを確かめる。
    # 透過暗号化の製品がこの一時ファイルまで暗号化していないか（ふつうのファイルでも起こりうる）
    param (
        [string]$readPath
    )

    if (!(testOfficeOutput (readFileHead $readPath) "Zip")) {
        throw ${officeOutputEncryptedMessage}
    }
}

function extractDocument {
    # Word・PowerPointのファイルを場所（ページ・スライド）ごとに作業フォルダへTSV出力し、出力した数を返す
    param (
        [string]$sourcePath
    )

    $isWord = ((getAppName $sourcePath) -eq "Word")
    $appName = $(if ($isWord) { "Word" } else { "PowerPoint" })

    # 元のファイルに影響を出さないよう、作業フォルダにコピーしてからコピーを読む（読んでいる間も、利用者が上書き保存・移動できる）。
    # 新形式（ZIP）はコピーをそのまま読む。
    # 旧形式・パスワード付き・拡張子と中身が異なるファイルは、Word・PowerPointで新形式に変換してから読む
    $copyPath = Join-Path $tmpDir ("source" + [System.IO.Path]::GetExtension($sourcePath))
    $readPath = $copyPath
    $workFiles = @($copyPath)
    try {
        copyFileShared $sourcePath $copyPath
        if (!(isZipFile $copyPath)) {
            $protection = getOfficeFileProtection $copyPath
            logProtectionKind $protection

            # パスワード付き（新形式）・IRM・秘密度ラベルの暗号化は、Office を使わずに失敗にする
            # （Word・PowerPointはサインイン画面が出ないようにするため。Excelは別処理で今のまま）
            if ($protection -eq "Password" -or $protection -eq "Rights") {
                throwProtectionFailure (getProtectionFailureText $protection)
            }

            if ($protection -eq "Unknown") {
                # 「形式の分からないバイナリ」（透過暗号化の製品の暗号文の見込み）。
                # アプリごとの切り替えが $false なら、Officeを使わずに失敗にする
                if (!(testOfficeFallbackEnabled $appName)) {
                    throwProtectionFailure (getProtectionFailureText "Unknown")
                }
                # 読み取りのスレッド（Office を持たない）では、Office のレーンに回す
                if ($script:officeUnavailable) {
                    throw (New-Object System.OperationCanceledException ${officeRequiredMessage})
                }

                # 拡張子は元のまま変えない（付け替えると、Wordが文字コードを尋ねる・PowerPointがアウトラインとして
                # 開くことがあるため）。Wordは形式を拡張子に合わせて固定し、自動判定に任せない
                $readPath = Join-Path $tmpDir $(if ($isWord) { "converted.docx" } else { "converted.pptx" })
                $workFiles = @($copyPath, $readPath)
                $wordFormat = getWordOpenFormat ([System.IO.Path]::GetExtension($copyPath))
                try {
                    extractWithOffice $isWord $copyPath $readPath $wordFormat
                } catch {
                    if (isPassthroughIngestException $_.Exception) {
                        throw
                    }
                    writeIndexerLog "    予備の読み取りに失敗しました: $(describeIngestError $_.Exception)" "Yellow"
                    throw (getProtectionFailureText "Unknown")
                }
                verifyOfficeOutputIsZip $readPath
            } else {
                # Legacy（旧形式・権限保護と分からないCFB）・Text（空・RTF・HTML・UTF-8・UTF-16等）は今と同じ

                # PowerPointは、プレゼンテーションではないファイル（中身がテキスト等）もアウトラインとして開き、
                # 文字化けした内容になるため、旧形式（複合ドキュメント形式）でなければ取り込まない。
                # Wordはテキスト・HTML・RTFも正しく読めるため、そのまま Word で開く
                if (!$isWord -and !(isCompoundFile $copyPath)) {
                    throw "ファイルが壊れているか、PowerPointのファイルではありません（新形式（ZIP）でも旧形式でもない内容です）。"
                }

                # 読み取りのスレッド（Office を持たない）では、Office のレーンに回す（indexer_run.ps1 の runIngestWorker・invokeIngestTask）
                if ($script:officeUnavailable) {
                    throw (New-Object System.OperationCanceledException ${officeRequiredMessage})
                }

                # Word・PowerPointは拡張子と中身が異なるファイル（中身が .doc の .docx 等）を開けないため、
                # コピーに旧形式の拡張子を付け直してから開く
                if ($isWord) {
                    $legacyPath = Join-Path $tmpDir "source.doc"
                    $readPath = Join-Path $tmpDir "converted.docx"
                } else {
                    $legacyPath = Join-Path $tmpDir "source.ppt"
                    $readPath = Join-Path $tmpDir "converted.pptx"
                }
                if ($legacyPath -ne $copyPath) {
                    [System.IO.File]::Move($copyPath, $legacyPath)
                    $copyPath = $legacyPath
                }
                $workFiles = @($copyPath, $readPath)

                extractWithOffice $isWord $copyPath $readPath
                verifyOfficeOutputIsZip $readPath
            }
        }

        # 埋め込んだファイルが読めなくても、その埋め込みだけを読まずに続ける（readDocxUnits・readPptxUnits）。
        # shared/ はツールを知らないため、読めなかった部品の名前・サイズの上限の詳細をここでログに書く
        $embedFailures = New-Object System.Collections.Generic.List[string]
        $embedSizeFailures = New-Object System.Collections.Generic.List[object]
        if ($isWord) {
            $units = readDocxUnits $readPath $embedFailures $embedSizeFailures
        } else {
            $units = readPptxUnits $readPath $embedFailures $embedSizeFailures
        }
        foreach ($sizeFailure in $embedSizeFailures) {
            writeZipSizeLimitLog $sizeFailure
        }
        foreach ($failure in $embedFailures) {
            writeIndexerLog "    埋め込みを読み取れませんでした: $failure" "Yellow"
        }
    } finally {
        foreach ($path in $workFiles) {
            if (Test-Path -LiteralPath $path) {
                Remove-Item -LiteralPath $path -Force
            }
        }
    }

    return (writeUnits $units $tmpDir)
}

function ingestFile {
    # 1ファイルを取り込み、作成したTSVの数を返す。
    # テキストの拡張子（textExtensions）・PDF の拡張子（pdfExtensions）は Office を使わず読み取りのレーンで取り込む（extract_text.ps1・extract_pdf.ps1）
    param (
        [string]$sourcePath
    )

    if (testTextExtension $sourcePath) {
        return (extractTextFile $sourcePath $tmpDir)
    }
    if (testPdfExtension $sourcePath) {
        return (extractPdfFile $sourcePath $tmpDir)
    }
    if ((getAppName $sourcePath) -eq "Excel") {
        return (extractWorkbook $sourcePath)
    }
    return (extractDocument $sourcePath)
}

# 1ファイル（テキスト）から行を読み、場所「本文」のTSVに書き出す。

function extractTextFile {
    # テキストファイル 1 つを読み、場所「本文」の TSV 1 つを outDir に書き出す（本文インデックスに 種類=テキスト・部分=本文・対象=本文 で載る）。
    # 出力した TSV の数（0 か 1）を返す。空のファイル・空の行だけのファイルは 0（次のインデックス作成で取り込み直さない）。
    # 元のファイルには影響を出さないため、読み取りだけ・共有モードで outDir に source.copy へコピーし（名前は .tsv にならない固定の名前。消せずに残っても TSV として公開されない）（copyFileShared）、コピーを読んで、
    # TSV を書く前に消す（outDir の中身は本文インデックスに回るので、コピーを残さない）。強制終了で残ったコピーは作業フォルダごと片付けられる。
    # 大きさの上限は、コピーの前に元の大きさ（メタデータ。元は開かない）で確かめる。コピーを読むときの確かめ（readTextFile）は、コピー中に大きくなった場合の保険。
    # バイナリの判定は readTextFile（shared\core\text_file.ps1）が例外にする。
    # maxBytes はテストで上限を小さく差し替えるための引数（既定は textFileMaxBytes）
    param (
        [string]$sourcePath,
        [string]$outDir,
        [long]$maxBytes = ${textFileMaxBytes}
    )

    if ([System.IO.FileInfo]::new((toLongPath $sourcePath)).Length -gt $maxBytes) {
        throw "ファイルサイズが大きすぎるため更新できません。"
    }
    $copyPath = Join-Path $outDir "source.copy"
    $removeError = $null
    try {
        copyFileShared $sourcePath $copyPath
        $lines = readTextFile $copyPath $maxBytes
    } finally {
        try {
            if (Test-Path -LiteralPath (toLongPath $copyPath)) {
                Remove-Item -LiteralPath (toLongPath $copyPath) -Force -ErrorAction Stop
            }
        } catch {
            $removeError = $_.Exception.Message
        }
    }
    if ($removeError) {
        throw "作業領域のコピーを消せませんでした: $removeError"
    }
    if ($lines.Count -eq 0) {
        return 0
    }
    $path = Join-Path $outDir (toIndexFileName "本文")
    [System.IO.File]::WriteAllLines((toLongPath $path), $lines, ${utf8Bom})
    return 1
}

# 1ファイル（PDF）からページごとの文字を読み、場所「ページN」のTSVに書き出す。

function extractPdfFile {
    # PDF ファイル 1 つを読み、ページごとの TSV（"ページ001" など）を outDir に書き出す（本文インデックスに 種類=PDF で載る）。
    # 出力した TSV の数を返す。文字の無いページは出さず、文字の無い PDF（画像だけ）は 0（次のインデックス作成で取り込み直さない）。
    # 元のファイルには影響を出さないため、extractTextFile と同じく、読み取りだけ・共有モードで outDir に source.copy へコピーし（copyFileShared）、
    # コピーを読んで、TSV を書く前に消す（outDir の中身は本文インデックスに回るので、コピーを残さない）。
    # 暗号化・壊れている・上限を超える・文字の対応表が無いなど読めない PDF は、readPdfFile が例外にする。
    # 大きさの上限は、コピーの前に元の大きさ（メタデータ。元は開かない）で確かめる。
    # maxBytes・limits はテストで上限を小さく差し替えるための引数（既定は pdfFileMaxBytes・newPdfLimits）
    param (
        [string]$sourcePath,
        [string]$outDir,
        [long]$maxBytes = ${pdfFileMaxBytes},
        [hashtable]$limits = $null
    )

    if ([System.IO.FileInfo]::new((toLongPath $sourcePath)).Length -gt $maxBytes) {
        throw "ファイルサイズが大きすぎるため更新できません。"
    }
    $copyPath = Join-Path $outDir "source.copy"
    $removeError = $null
    try {
        copyFileShared $sourcePath $copyPath
        $pages = readPdfFile $copyPath $maxBytes $limits
    } finally {
        try {
            if (Test-Path -LiteralPath (toLongPath $copyPath)) {
                Remove-Item -LiteralPath (toLongPath $copyPath) -Force -ErrorAction Stop
            }
        } catch {
            $removeError = $_.Exception.Message
        }
    }
    if ($removeError) {
        throw "作業領域のコピーを消せませんでした: $removeError"
    }
    $units = [ordered]@{}
    for ($i = 0; $i -lt $pages.Count; $i++) {
        addUnitLines $units ("ページ{0:D3}" -f ($i + 1)) ($pages[$i] -split "`n")
    }
    return (writeUnits $units $outDir)
}
# TSV のインデックスへの取り込みと、作業フォルダ・外したフォルダのインデックスの後始末。

function publishTsv {
    # 作業フォルダのTSVを、そのファイルのインデックスのフォルダへ移動する。
    # 途中で強制終了されても一部のシートだけのインデックスが残らないよう、
    # 出力用のフォルダ（work\publish\<PID>）に集めてからフォルダごと入れ替える（publishIndexFiles）
    param (
        [string]$bookDir
    )

    publishIndexFiles $tmpDir $bookDir (Join-Path $workspace.PublishDir ([System.IO.Path]::GetFileName($bookDir)))
}

function clearTmpDir {
    # 作業フォルダ直下のファイルを消す。作業フォルダそのものがリンク（ジャンクション・シンボリックリンク）のときは、
    # 先のファイルを消さないよう、何も消さずにログに出す
    if (testPathIsLink $tmpDir) {
        writeIndexerLog "    作業フォルダがリンク（ジャンクション・シンボリックリンク）のため、中のファイルを消しませんでした: ${tmpDir}" "Yellow"
        return
    }
    Get-ChildItem -LiteralPath (toLongPath $tmpDir) -File | Remove-Item -Force
}

function removeEmptyDir {
    # フォルダが空のときだけ、再帰しない削除で消す。中にほかのプロセスのフォルダなどが残っている・
    # フォルダが既に無いときは、何もせずそのままにする。
    # リンク（ジャンクション・シンボリックリンク）は、リンク自体を外さないよう、先が空でも消さない
    # （利用者が tmp や出力用のフォルダの親をリンクにした構成を、そのまま使えるようにするため）
    param (
        [string]$dir
    )
    if (testPathIsLink $dir) {
        return
    }
    try {
        [System.IO.Directory]::Delete($dir, $false)
    } catch {
        # 空でない・既に無い・アクセス権が無い（共有フォルダで他の利用者のフォルダなど）
    }
}

function removeTmpDir {
    # 作業フォルダ（work\tmp\<PC の鍵>\<PID>）と出力用のフォルダ（work\publish\<PID>）を削除する。終了時に呼ぶ。
    # ${tmpDir} が決まっていなくても（置けなかった・決める前）、出力用のフォルダは消す
    # （$workspace.PublishDir は ${tmpDir} が置けないときも作られるため）
    foreach ($dir in @(${tmpDir}, $workspace.PublishDir) | Where-Object { $_ }) {
        try {
            removeDirectoryRetry $dir
        } catch {
            writeIndexerLog "    作業フォルダを削除できませんでした: ${dir}（$($_.Exception.Message)）" "Yellow"
        }
    }
    # 空になった tmp\<PC の鍵>・tmp も消す（ワークスペースの tmp を使えたときだけ。
    # ほかのプロセスのフォルダが残っているときは消えない）
    if (${tmpDir} -and ${tmpDir}.StartsWith($workspace.TmpRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
        removeEmptyDir (Split-Path ${tmpDir} -Parent)
        removeEmptyDir $workspace.TmpRoot
    }
}

function removeStaleTmpDirs {
    # 強制終了などで残った、ほかの（終了済みの）プロセスの作業フォルダ
    # （ワークスペースの tmp\<PC の鍵>\<PID>・work\publish\<PID>・前の版までの %TEMP%\tebunko\<PID>）を削除する。
    # 空になった親（tmp\<PC の鍵>・publish・${legacyTmpParent}。tmp\<PC の鍵> はさらに tmp 自体も）も消す
    # tmp\<PC の鍵> の途中にリンク（ジャンクション・シンボリックリンク）があるときは、先のフォルダを消さないよう、片付けない
    $keyDir = Split-Path (getWorkspaceTmpDir $workspace) -Parent
    foreach ($parent in @($keyDir, (Split-Path $workspace.PublishDir -Parent), ${legacyTmpParent})) {
        if (($parent -eq $keyDir) -and (testPathHasLink $workspace.TmpRoot $keyDir)) {
            writeIndexerLog "    作業領域の途中にリンク（ジャンクション・シンボリックリンク）があるため、残った作業フォルダを片付けませんでした: ${keyDir}" "Yellow"
            continue
        }
        removeStaleProcessDirs $parent
        removeEmptyDir $parent
    }
    removeEmptyDir $workspace.TmpRoot
}

function newDirectoryReplacingExisting {
    # フォルダを作る。同じ名前（前の残り・先に置かれたリンク）が既にあれば、リンクは辿らずに消してから作り直す。
    # 作ったものがリンクでなければ $true（置けた）、リンクのまま残った（消せなかった）ときは $false
    param (
        [string]$dir
    )

    try {
        removeDirectoryRetry $dir
    } catch {
        # 消せなくても、下の確かめでリンクが残っていなければ、そのまま使う
    }
    [System.IO.Directory]::CreateDirectory($dir) | Out-Null
    return !(testPathIsLink $dir)
}

function initTmpDir {
    # インデックス作成の始めに、取り込みの作業フォルダの片付けと用意をまとめて行う: @{ Dir; Reason（置けなかったときだけ） }
    #   1. 強制終了などで残った、ほかの（終了済みの）プロセスの作業フォルダを片付ける（決めた場所を巻き込まないよう、場所を決める前に行う）
    #   2. selectTmpDir で置き場所を決める
    #   3. 置けたら、フォルダを作って tmp・tmp\<PC の鍵>・<PID> に NotContentIndexed を付ける
    #   4. 置けなければ（Dir が空）、フォルダは作らず、理由と「取り込みをすべてスキップする」ことをログに 1 行書く
    #      （どのファイルも中間 TSV などをこのフォルダに作るため、テキストファイルを含めすべての取り込みが対象になる）
    #      （1 ファイルごとのスキップは invokeIngestTask が取り込みの失敗として記録する）
    removeStaleTmpDirs
    $selected = selectTmpDir $workspace
    if (!$selected.Dir) {
        writeIndexerLog "$(getTmpDirUnavailableMessage $selected.Reason)取り込みをすべてスキップします。" "Yellow"
        return $selected
    }
    # 作業領域（tmp\<PC の鍵>\<PID>）の途中にリンク（ジャンクション・シンボリックリンク）があれば、先に書かないよう置けない扱いにする
    # （tmp そのものは見ない。利用者が tmp を別の場所へのリンクにした構成も、今までどおり使える）。
    # 同じ名前（前のプロセスの残り・先に置かれたもの）が既にあれば、リンクは辿らずに消してから作り直す
    $placed = $false
    if (!(testPathHasLink $workspace.TmpRoot (Split-Path $selected.Dir -Parent))) {
        $placed = newDirectoryReplacingExisting $selected.Dir
    }
    if (!$placed) {
        $unavailable = @{ Dir = ""; Reason = "Link" }
        writeIndexerLog "$(getTmpDirUnavailableMessage $unavailable.Reason)取り込みをすべてスキップします。" "Yellow"
        return $unavailable
    }
    foreach ($dir in @($workspace.TmpRoot, (Split-Path $selected.Dir -Parent), $selected.Dir)) {
        [void](setNotContentIndexed $dir)
    }
    return $selected
}

function newWorkerTmpDir {
    # 取り込みのスレッドの作業フォルダ（parentDir\w<番号>）を作り、パスを返す。
    # 親（parentDir。司令のスレッドの作業フォルダ）に NotContentIndexed が付いていれば、同じ属性を付ける。
    # 親が無い（置けなかった）ときは、何も作らず空文字を返す
    param (
        [string]$parentDir,
        [int]$number
    )

    if (!$parentDir) {
        return ""
    }
    if (testPathIsLink $parentDir) {
        writeIndexerLog "    作業フォルダがリンク（ジャンクション・シンボリックリンク）のため、取り込みの作業フォルダを置けません: ${parentDir}" "Yellow"
        return ""
    }
    $dir = Join-Path $parentDir "w$number"
    if (!(newDirectoryReplacingExisting $dir)) {
        return ""
    }
    if (testNotContentIndexed $parentDir) {
        [void](setNotContentIndexed $dir)
    }
    return $dir
}

function removeStaleProcessDirs {
    # プロセスIDの名前のフォルダのうち、そのプロセスが既に終わっているものを削除する
    param (
        [string]$parent
    )

    if (!(Test-Path -LiteralPath $parent)) {
        return
    }
    foreach ($dir in @(Get-ChildItem -LiteralPath $parent -Directory | Where-Object { $_.Name -match "^\d{1,9}$" -and [int]$_.Name -ne $PID })) {
        if (Get-Process -Id ([int]$dir.Name) -ErrorAction SilentlyContinue) {
            continue  # 実行中のインデックス作成（またはPIDを再利用した別のプロセス）のものは残す
        }
        try {
            # 中に長いパスがあっても消え、中のリンクの先は消さない。使用中などで消せなければ 1 回だけ試して次回に回す
            removeDirectoryRetry $dir.FullName 1
        } catch {
            # 使用中・リンクかどうか確かめられないフォルダがあるなどで削除できなければ、原因をログに出して次回に回す
            writeIndexerLog "    終了したプロセスの作業フォルダを削除できませんでした: $($dir.FullName)（$($_.Exception.Message)）" "Yellow"
        }
    }
}

function findDroppedIndexes {
    # 前回の取り込み一覧にあって、今回のクロール対象フォルダに無いインデックス（設定から外れたもの）を返す。見つけるだけで、消さない
    # （消すかどうかは利用者が確認ダイアログで決める。removeDroppedFolders）。チェックを外しただけのフォルダは、今回の一覧にあるため含まない
    param (
        [object[]]$folders,          # assignIndexNames の結果
        [object[]]$previousFolders   # readStatusFile の Folders
    )

    # インデックス名で比べる。フォルダを移動して登録し直した場合は、同じ名前を引き継ぐため含めない（assignIndexNames）
    $current = @($folders | ForEach-Object { $_.Name })
    return @($previousFolders | Where-Object { $_ -and $_.Name -and $current -notcontains $_.Name })
}

function getDroppedStatusRows {
    # 消さずに残す外れたインデックスの、前回の取り込み一覧の行（次の回にまた見つけられるよう、書き直す一覧に残す）
    param (
        [object[]]$dropped,
        $previousRows  # readStatusFile の Rows（相対パス → 行）
    )

    $result = New-Object System.Collections.Generic.List[object]
    if ($null -eq $previousRows) {
        return $result.ToArray()
    }
    foreach ($item in @($dropped | Where-Object { $_ })) {
        $prefix = "$($item.Name)\"
        foreach ($key in @($previousRows.Keys)) {
            if ($key.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) {
                $result.Add($previousRows[$key])
            }
        }
    }
    return $result.ToArray()
}

function writeStatusKeepingDropped {
    # 取り込み一覧を書く。消さずに残す外れたインデックスのフォルダの行と各行も、前回のまま足して書く（次の回にまた見つけられるように）
    param (
        $ledger,
        [object[]]$folders,      # 今回のクロール対象フォルダ
        [object[]]$rows,         # 今回の各行
        [object[]]$keptDropped,  # 消さずに残す外れたインデックス
        $previousRows            # readStatusFile の Rows（前回の行）
    )

    $ledger.WriteStatus((@($folders) + @($keptDropped)), (@($rows) + @(getDroppedStatusRows $keptDropped $previousRows)))
}

function removeDroppedFolders {
    # 設定から外れたインデックス（findDroppedIndexes の結果。work\content_index\<インデックス名>）を削除する。
    # 利用者が確認ダイアログで［更新を開始］を押した回でだけ呼ぶ
    param (
        [object[]]$dropped,
        $ws = $workspace             # 対象のワークスペース（テストが差し替える）
    )

    foreach ($previous in @($dropped | Where-Object { $_ })) {
        $dir = Join-Path $ws.IndexDir $previous.Name
        if (Test-Path -LiteralPath $dir) {
            # 中に長いパス（260文字超）のTSVがあっても削除でき、中のリンク（ジャンクション・シンボリックリンク）の先は消さない
            removeDirectoryRetry $dir
        }
        writeIndexerLog "クロール対象から削除されたフォルダ（$($previous.Path)）のインデックスを削除しました。"
    }
}

# インデックス作成の本体（invokeIndexer）。画面を使わない起動口（indexer.ps1）と、画面のインデクサのスレッド（IndexingSession）が呼ぶ。
# 設計は docs/design/indexing/parallel.md、docs/design/structure/threads.md「画面とインデクサの受け渡し」。
#
# ・司令のスレッド（invokeIndexer を呼んだスレッド）が、クロール・確認・取り込み一覧・本文インデックスのファイルとシステムインデックスの書き出しを行う。
#   Office の COM には触らない
# ・1 ファイルの取り込み（Office で開いて TSV にする）は、取り込みのスレッド（STA）が行う。スレッドごとに自分の Office を持つ。
#   スレッドの数が 0 のときは、司令のスレッドで取り込む（テストで、途中に割り込むため）
# ・画面とのやり取りは受け渡しの口（newIndexerChannel）で行う。表示内容は indexing_log.txt に書く

# Excel・Word・PowerPoint を利用者に渡したとき・渡すか決められず持ち続けるときのログ（indexing_log.txt）への 1 行。
# office_app.ps1 の handOverApp・keepUndecidedApp が呼ぶ
${officeHandOverNotice} = {
    param ($name, $shown)
    if ($null -eq $shown) {
        # shown が $null: ファイルの一覧を読めず、利用者のファイルがあるか分からない。終了させずに持ち続け、後で読み直す
        writeIndexerLog "${name} のファイルの一覧を読めなかったため、終了させずに残しています（あとで読み直します）" "Yellow"
    } elseif ($shown) {
        writeIndexerLog "開かれたファイルがあるため ${name} を利用者に渡しました"
    } else {
        writeIndexerLog "開かれたファイルがあるため ${name} を利用者に渡しましたが、窓や設定を戻しきれませんでした（終了させずに残しています）" "Yellow"
    }
}

# 取り込みのスレッドで動かすスクリプト。自分のレーンの列（tasks）から 1 ファイルずつ取り出して取り込み、結果を results に入れる。
# Office のレーン（Excel・Word・PowerPoint）は STA で、そのアプリを 1 つ持つ。読み取りのレーンは Office を持たない。
# 列が閉じられたら（CompleteAdding）、Office を終了して終わる
${ingestWorkerScript} = {
    param ($settings, $tasks, $results, $number)
    $ErrorActionPreference = "Stop"
    # indexerLib の部品（Prelude）は addIngestTask が、この param ブロックのあとにつなぐ（joinWorkerScript）
    # 置き場所は司令のスレッドと同じにする（読み込み直すと設定から決め直してしまうため）。一時フォルダはスレッドごとに分ける。
    # 部品を読み込んだのと同じスコープ（取り込みのスレッドでは global）に置く
    $own = [Workspace]::new($settings.WorkDir)
    $own.PublishDir = Join-Path $settings.PublishDir "w$number"
    setCallerWorkspace $own
    Set-Variable -Name tmpDir -Value (newWorkerTmpDir $settings.TmpDir $number)
    Set-Variable -Name tmpDirReason -Value $settings.TmpDirReason
    [System.IO.Directory]::CreateDirectory($workspace.PublishDir) | Out-Null
    $script:officePidSink = $settings.OfficePids
    $script:officeRecordDir = $settings.OfficeRecordDir
    $script:officeOwnDir = resolveOwnDir $tmpDir
    $script:onOfficeHandOver = ${officeHandOverNotice}
    $script:officeUnavailable = ($settings.Lane -eq ${laneReader})
    [System.Threading.Thread]::CurrentThread.Priority = [System.Threading.ThreadPriority]::BelowNormal

    # レーンの状態（制限時間を過ぎても利用者が使っている PowerPoint を止めずに諦めたか）。司令と共有する
    $script:laneState = $settings.LaneState
    if (!$script:officeUnavailable) {
        $script:officeWatchdog.State.Abandon = $settings.LaneState
        if ($settings.UserOfficePids) {
            $script:officeWatchdog.State.Users = $settings.UserOfficePids
        }
        $script:officeWatchdog.Start()
    }
    try {
        runIngestWorker $tasks $results $settings.FileTimeoutMinutes $settings.RestartInterval
    } finally {
        if (!$script:officeUnavailable) {
            $script:officeWatchdog.Stop()
            # 利用者が使っている PowerPoint を諦めたレーンは、終了させない（開いているファイルの保存されていない変更を失わせないため）
            if (!$settings.LaneState.Abandoned) {
                stopAllApps
                # 渡し切れずに持ち続けているアプリは、ここで上限まで仕上げ直す（中止・画面を閉じるときは待たない）
                waitKeptApps ({ [bool]$settings.Channel.Stop }.GetNewClosure())
            }
        }
    }
}

# 司令が並びの先を見る件数（空いているレーン向けのファイルを先に渡すため）。大きくすると、本文インデックスのファイルの書き出しが遅れるフォルダが増える
${ingestLookAhead} = 200

function runIngestWorker {
    # 取り込みのスレッドの繰り返し（ingestWorkerScript が呼ぶ）。列から 1 件ずつ取り込み、結果を results に入れる。
    # Office を持つスレッドは、決まった数を取り込むたびに Office を起動し直す
    param (
        $tasks,
        $results,
        [int]$fileTimeoutMinutes,
        [int]$restartInterval
    )

    $done = 0
    foreach ($task in $tasks.GetConsumingEnumerable()) {
        $result = invokeIngestTask $task $fileTimeoutMinutes
        $results.Add($result)
        if ($result.Postponed) {
            # 後回し（利用者のPowerPointが起動していて使えなかった）は、取り込んだ件数に数えない
            # （件数が変わらないまま後回しが続いたときに、起動し直しを早めないため）
            continue
        }
        $done++
        if (!$script:officeUnavailable -and ($result.TimedOut -or ($done % $restartInterval) -eq 0)) {
            # 制限時間を過ぎて強制終了したアプリは使えないため、すべて終了して次に必要になったときに起動し直す
            stopAllApps
        }
    }
}

function getIngestWorkerCount {
    # 読み取りのスレッド（Office を使わずに読むファイル）の数を決める。requested が 0 以上ならその数
    # （0 は取り込みのスレッドを使わず、司令のスレッドで取り込む）、負なら設定（ingestThreads）、設定が 0 ならコア数から決める。
    # 取り込むファイルの数より多くはしない
    param (
        [int]$requested,
        [int]$total,
        [int]$configured = 0,
        [int]$processors = [Environment]::ProcessorCount
    )

    $count = if ($requested -ge 0) {
        $requested
    } elseif ($configured -gt 0) {
        [Math]::Min($configured, 4)
    } else {
        getWorkerCount 4 $processors
    }
    return [Math]::Max(0, [Math]::Min($count, $total))
}

function getIngestLaneCapacity {
    # レーンに同時に渡しておく数。Office のレーンは取り込み中の 1 件と次の 1 件、読み取りのレーンはスレッドの数の 2 倍
    param (
        [string]$lane,
        [int]$readers
    )

    if ($lane -eq ${laneReader}) {
        return [Math]::Max(1, $readers) * 2
    }
    return 2
}

function testLaneAbandoned {
    # このレーンが、制限時間を過ぎても利用者が使っている PowerPoint を止めずに諦めたものか（取り込みのスレッドの $script:laneState）
    $state = $script:laneState
    return ($null -ne $state -and [bool]$state.Abandoned)
}

function invokeIngestTask {
    # 1 ファイルを取り込み、結果 @{ RelPath; Ok; Reroute; TsvCount; Message; TimedOut; ExtractVersion; Log } を返す（例外は投げない）。
    # 取り込みのスレッド、またはスレッドの数が 0 のときは司令のスレッドで動く。表示内容は Log に貯め、司令がログに書く
    param (
        [hashtable]$task,
        [int]$fileTimeoutMinutes
    )

    # Reroute: Office を使わずに読めなかった（中身が旧形式・パスワード付き）。司令が Word・PowerPoint のレーンに回し直す
    # Postponed: 利用者のPowerPointが起動していて使えなかった。司令が「未取り込み」のまま次回に回す
    $result = @{ RelPath = $task.RelPath; Ok = $false; Reroute = $false; Postponed = $false; TsvCount = 0; Message = ""; TimedOut = $false; ExtractVersion = ""; Log = "" }
    if (!$tmpDir) {
        # 取り込みの作業フォルダを置けない（selectTmpDir の Brackets・TooLong）ときは、
        # どのファイルも中間 TSV などをこのフォルダに作るため、テキストファイルを含めこのファイルの取り込みをスキップし、取り込みの失敗として記録する
        $result.Message = "$(getTmpDirUnavailableMessage $tmpDirReason)このファイルの取り込みをスキップしました。"
        return $result
    }
    if (testLaneAbandoned) {
        # 利用者が使っている PowerPoint を諦めたレーン。取り込まず、後回しにする（司令は結果を受け取らずに後回しにしている）
        $result.Postponed = $true
        return $result
    }
    $log = New-Object System.IO.StringWriter
    $previousLog = $script:indexerLog
    $script:indexerLog = $log
    try {
        clearTmpDir
        $script:officeWatchdog.State.TimedOut = $false
        $script:officeWatchdog.State.Deadline = (Get-Date).AddMinutes($fileTimeoutMinutes)
        try {
            $result.TsvCount = ingestFile $task.SourcePath
        } finally {
            $script:officeWatchdog.State.Deadline = [datetime]::MaxValue
        }
        if (testLaneAbandoned) {
            # 戻ってきたときには、司令がこのファイルを後回しにしている。書き出さない
            # （司令が同じフォルダを書き換えるのと重ならないようにし、取り込み一覧・インデックスを変えない）
            $result.Postponed = $true
            return $result
        }
        publishTsv (getBookDir $task.RelPath)
        $result.ExtractVersion = [string](getExtractVersion $task.RelPath)
        $result.Ok = $true
    } catch {
        $base = $_.Exception.GetBaseException()
        if (testLaneAbandoned) {
            # 諦めたレーンで、利用者の PowerPoint が閉じられるなどして戻ってきた。失敗にも、アプリの終了にもしない
            $result.Postponed = $true
            return $result
        }
        if (isOfficeRequiredException $_.Exception) {
            $result.Reroute = $true
            return $result
        }
        if (isOfficeAppInUseException $_.Exception) {
            # getApp が投げた例外。$script:apps に入っていないため stopApp は呼ばない
            $result.Postponed = $true
            return $result
        }
        # .docx・.pptx を直接読んでサイズの上限を超えたとき（ZipSizeLimitException）は、原因を調べられるよう
        # 部品名・大きさ・部品ごとか合計かをインデックス作成のログに書く。画面・取り込み一覧の
        # $result.Message は今までどおり簡潔な文言のまま（describeIngestError がそのまま通す）
        writeZipSizeLimitLog $base
        $message = describeIngestError $_.Exception
        if ($script:officeWatchdog.State.TimedOut) {
            $message = "${fileTimeoutMinutes} 分以内に更新が終わらなかったため中止しました（Officeアプリを強制終了しました）"
        }
        $result.Message = $message
        # アプリが不安定になっている可能性があるため終了する（次に必要になったときに起動し直す）。
        # 暗号化の判定でOfficeにまだ触れていない失敗（throwProtectionFailure）は、終了させない
        # （IRM・パスワード付きのファイルが並んでも、そのたびにOfficeを起動し直さないため）
        if (!$script:officeUnavailable -and !$base.Data.Contains("OfficeUntouched")) {
            try { stopApp (getAppName $task.RelPath) } catch {}
        }
    } finally {
        # Excel・Word・PowerPoint で利用者が開いたファイルがあれば、閉じずに利用者に渡す（次のファイルは新しいアプリで取り込む。PowerPoint は後回しになる）
        $appName = getAppName $task.RelPath
        if (!$script:officeUnavailable -and $appName -and !(testLaneAbandoned)) {
            try { [void](handOverForeignApp $appName) } catch {}
        }
        $result.TimedOut = [bool]$script:officeWatchdog.State.TimedOut
        $script:indexerLog = $previousLog
        $result.Log = $log.ToString()
    }
    return $result
}

function newIngestPool {
    # 取り込みのスレッドの入れ物を作る。スレッドは、そのレーンのファイルを初めて渡すときに始める（addIngestTask）。
    # 渡すファイルが無いレーンは、スレッドも Office も作らない。@{ Queues; Results; Workers; Readers; Settings; Count }
    param (
        [int]$readers,
        [hashtable]$settings
    )

    $queues = @{}
    $laneStates = @{}
    foreach ($lane in ${laneExcel}, ${laneWord}, ${lanePowerPoint}, ${laneReader}) {
        $queues[$lane] = New-Object 'System.Collections.Concurrent.BlockingCollection[hashtable]'
        # Abandoned: 制限時間を過ぎても利用者が使っている PowerPoint を止めずに、このレーンを諦めた（取り込みのスレッドの監視が立てる）。
        # Handled: 司令が、取り込み中だったファイルの後回しを済ませた
        $laneStates[$lane] = [hashtable]::Synchronized(@{ Abandoned = $false; Handled = $false })
    }
    return @{
        Queues   = $queues
        LaneStates = $laneStates
        Results  = New-Object 'System.Collections.Concurrent.BlockingCollection[hashtable]'
        Workers  = New-Object System.Collections.Generic.List[hashtable]
        Readers  = $readers
        Settings = $settings
        Started  = @{}
    }
}

function addIngestTask {
    # レーンの列にファイルを渡す。そのレーンのスレッドがまだ無ければ始める
    # （Office のレーンは STA のスレッド 1 つ、読み取りのレーンは MTA のスレッドを読み取りの数だけ）
    param (
        [hashtable]$pool,
        [string]$lane,
        [hashtable]$task
    )

    if (!$pool.Started.ContainsKey($lane)) {
        $pool.Started[$lane] = $true
        $count = if ($lane -eq ${laneReader}) { $pool.Readers } else { 1 }
        for ($i = 0; $i -lt $count; $i++) {
            $settings = $pool.Settings.Clone()
            $settings.Lane = $lane
            $settings.LaneState = $pool.LaneStates[$lane]
            $runspace = [runspacefactory]::CreateRunspace($settings.Lib.State)
            # Office の COM は、作ったスレッドから呼ぶ（STA）。読み取りのスレッドは COM を使わない（MTA）
            $runspace.ApartmentState = if ($lane -eq ${laneReader}) { [System.Threading.ApartmentState]::MTA } else { [System.Threading.ApartmentState]::STA }
            $runspace.ThreadOptions = [System.Management.Automation.Runspaces.PSThreadOptions]::ReuseThread
            $runspace.Open()
            $ps = [powershell]::Create()
            $ps.Runspace = $runspace
            $number = $pool.Workers.Count + 1
            $joined = if ($settings.Lib.Prelude) { joinWorkerScript $settings.Lib.Prelude ${ingestWorkerScript}.ToString() } else { ${ingestWorkerScript}.ToString() }
            [void]$ps.AddScript($joined).AddArgument($settings).AddArgument($pool.Queues[$lane]).AddArgument($pool.Results).AddArgument($number)
            $pool.Workers.Add(@{ PowerShell = $ps; Runspace = $runspace; Handle = $ps.BeginInvoke(); Ended = $false; Lane = $lane })
        }
    }
    $pool.Queues[$lane].Add($task)
}

function getUnhandledAbandonedLanes {
    # 諦めた（Abandoned）のに、司令がまだ後回しを済ませていない（Handled でない）レーンの名前の並び。取り込みのスレッドが無いレーンは含まない
    param (
        [hashtable]$pool
    )

    return @($pool.Started.Keys | Where-Object { $pool.LaneStates[$_].Abandoned -and !$pool.LaneStates[$_].Handled })
}

function receiveIngestResult {
    # 取り込みのスレッドの結果を 1 つ受け取る。スレッドが途中で止まっていたら（読み込めない等）、その理由で例外にする。
    # 諦めたレーンがあって司令が後回しを済ませていないときは、結果を待たずに $null を返す
    param (
        [hashtable]$pool
    )

    $result = $null
    while (!$pool.Results.TryTake([ref]$result, 500)) {
        if (@(getUnhandledAbandonedLanes $pool).Count -gt 0) {
            # 制限時間を過ぎても利用者が使っている PowerPoint を止めずに諦めたレーンがある。戻らない結果を待たずに、司令に後回しをさせる
            return $null
        }
        foreach ($worker in $pool.Workers) {
            if ($worker.Ended -or !$worker.Handle.IsCompleted -or $pool.LaneStates[$worker.Lane].Abandoned) {
                continue
            }
            $worker.Ended = $true
            $reason = "取り込みのスレッドが止まりました。"
            try {
                [void]$worker.PowerShell.EndInvoke($worker.Handle)
            } catch {
                $exception = $_.Exception
                while ($exception.InnerException) {
                    $exception = $exception.InnerException
                }
                $reason = "取り込みのスレッドが止まりました：$($exception.Message)"
            }
            throw $reason
        }
    }
    return $result
}

function stopIngestWorkers {
    # 取り込みのスレッドに終わりを伝え、取り込み中のファイルが終わるのを待ってから片づける（Office のスレッドは Office を終了してから終わる）
    param (
        [hashtable]$pool
    )

    foreach ($queue in $pool.Queues.Values) {
        $queue.CompleteAdding()
    }
    $abandoned = $false
    foreach ($worker in $pool.Workers) {
        if ($pool.LaneStates[$worker.Lane].Abandoned -and !$worker.Handle.IsCompleted) {
            # 諦めたレーンのスレッドは、固まった PowerPoint の呼び出しから戻らないことがある。待たず、止める依頼（BeginStop）だけを出す。
            # PowerShell・ランスペースと列は Dispose しない（Dispose は動いている間は止まるのを待つ）。後片付けはプロセスの終わりに任せる
            try { [void]$worker.PowerShell.BeginStop($null, $null) } catch {}
            $worker.Ended = $true
            $abandoned = $true
            continue
        }
        if (!$worker.Ended) {
            try {
                [void]$worker.PowerShell.EndInvoke($worker.Handle)
            } catch {
            }
            $worker.Ended = $true
        }
        $worker.PowerShell.Dispose()
        $worker.Runspace.Dispose()
    }
    if (!$abandoned) {
        foreach ($queue in $pool.Queues.Values) {
            $queue.Dispose()
        }
        $pool.Results.Dispose()
    }
}

function invokeIndexer {
    # インデックスを作成し、終了コード（0 = 完了 / 1 = 続けられないエラー / 2 = 中止（確認で取りやめた場合を含む））を返す。
    # 終了コード・エラーの内容は受け渡しの口（channel）にも入れる（ExitCode は最後に入れる。画面は ExitCode が入ったら終わったとみなす）
    param (
        $channel
    )

    $script:indexerChannel = $channel
    $exitCode = 1
    $mutex = $null
    try {
        # 既定のワークスペースにほかのファイルが置いてあれば、インデックスのファイルと混ざるため作成しない。
        # 空でないフォルダにログを書かないよう、ログを開く前に確かめる（画面は起動する前に同じ確認をする）
        $workspaceBlock = getWorkspaceBlockMessage
        if ($workspaceBlock) {
            if ($script:settingsRecovery) {
                writeIndexerLog (getSettingsRecoveryMessage $script:settingsRecovery) "Yellow"
                $script:settingsRecovery = ""
            }
            writeIndexerLog $workspaceBlock "Red"
            $channel.Error = $workspaceBlock
            $exitCode = 1
        } else {
            # 同じ work に対してインデックス作成を 2 つ動かすと、取り込み一覧・インデックスが食い違うため 1 つだけ動かす。
            # 画面と indexer.ps1 の両方から動かせるため、鍵は work のパスから作る。ログに触る前に確かめる
            $mutex = newAppMutex "indexer" $workspace.Dir
            if (!$mutex.Acquired) {
                throw "ほかのインデックス作成が実行中です。インデックス作成が終わってから実行してください。"
            }
            [System.IO.Directory]::CreateDirectory($workspace.Dir) | Out-Null
            # 鍵を取れた後にだけ、前回の記録を残す（取れなかったときはほかのインデックス作成の記録に触らない）
            [void](rotateLogFile $workspace.IndexingLogFile 0)
            $writer = New-Object System.IO.StreamWriter($workspace.IndexingLogFile, $false, ${utf8Bom})
            $writer.AutoFlush = $true
            $script:indexerLog = $writer
            try {
                # 先頭に版と環境を書く（画面なしで動かしたときにコンソールへ出さないよう writeIndexerLog は使わない）。書けなくても続ける
                foreach ($headerLine in @(getToolDiagnosticHeader)) {
                    $writer.WriteLine($headerLine)
                }
            } catch {}
            if ($script:settingsRecovery) {
                # 画面なしで起動したとき、起動口が壊れた設定ファイルを退避している。ログの先頭に知らせる
                writeIndexerLog (getSettingsRecoveryMessage $script:settingsRecovery) "Yellow"
                $script:settingsRecovery = ""
            }
            # 途中の処理が出力した値が混ざらないよう、最後の値（return した終了コード）を使う
            $exitCode = [int]@(invokeIndexerBody $channel)[-1]
        }
    } catch {
        # 続けられないエラー。画面に伝える
        $message = $_.Exception.Message
        writeIndexerLog "＜エラー＞"
        writeIndexerLog $message "Red"
        $channel.Error = $message
        $exitCode = 1
    } finally {
        if ($script:indexerLog) {
            try { $script:indexerLog.Dispose() } catch {}
            $script:indexerLog = $null
        }
        if ($mutex) {
            if ($mutex.Acquired) {
                try { $mutex.Mutex.ReleaseMutex() } catch {}
            }
            $mutex.Mutex.Dispose()
        }
        $script:indexerChannel = $null
        $channel.ExitCode = $exitCode
    }
    return $exitCode
}

function invokeIndexerBody {
    # invokeIndexer の本体（鍵を取り、ログを開いた後）。終了コードを返す。続けられないエラーは例外にする。
    # 取り込み一覧・取り込み中のファイル・今回の失敗と消えた行は StatusLedger（$ledger）、
    # 本文インデックスへの書き出し待ちは PendingPublish（$pending）、進み具合・画面の確認待ちは IndexingReporter（$reporter）にまとめる。
    # 3 つは互いを呼ばず、ここ（司令）がつなぐ（docs/design/structure/classes.md「クラスのつなぎ方」）
    param (
        $channel
    )

    $ledger = [StatusLedger]::new($workspace)
    $pending = [PendingPublish]::new()
    $reporter = [IndexingReporter]::new($channel)

    # 書き出し待ちのフォルダを本文インデックスへまとめる（書き出しは司令であるここが呼ぶ。PendingPublish は決めて返すだけ）。
    # -All は、取り込み中・まだ渡していない数を見ずに、書き出し待ちのフォルダをすべて書き出す（クロールの前後・インデックス作成の終わり）
    function flushPending {
        param ([switch]$All)

        $flush = if ($All) { $pending.TakeAll() } else { $pending.TakeFlushable() }
        if ($flush.Count -eq 0) {
            return
        }
        try {
            [void](publishIndexFolders $flush)
        } catch {
            writeIndexerLog "    インデックスをまとめられませんでした（次のインデックス作成でまとめ直します）: $($_.Exception.Message)" "Yellow"
        }
    }

    # 利用者が使っている PowerPoint のために取り込めなかったファイルを、失敗として記録する（件数は呼び出す側が数える）。
    # 取り込み一覧の行は「未取り込み」のまま、理由を「エラー」列に書く（「失敗」にすると、次の更新で飛ばされるため）。
    # 前回の行があれば、TSV 数・取り込み日時・抽出版は前回のまま残す（インデックスは変えていない）
    function recordUserPowerPointPostponed {
        param ([int]$number, $row, [string]$reason)

        $relPath = [string]$row.相対パス
        $old = $null
        if ($previous.TryGetValue($relPath, [ref]$old) -and $old) {
            $row.TSV数 = $old.TSV数
            $row.取り込み日時 = $old.取り込み日時
            $row.抽出版 = $old.抽出版
        }
        $row.状態 = ${stateNew}
        $row.エラー = $reason
        $ledger.AddFailure($relPath, $reason)
        writeIndexerLog ("[{0}/{1}] {2}" -f $number, $total, $relPath)
        writeIndexerLog "    取り込めませんでした（次の更新で取り込みます）: $reason" "Yellow"
    }
    # 取り込み中のファイルを、取り込み中から外して残す（書き出し待ちを済ませ、失敗として記録する。releaseLane: レーンの取り込み中の数も減らす）
    function postponeInflightForUser {
        param ([string]$relKey, [string]$reason, [switch]$releaseLane)

        $lost = $inflight[$relKey]
        [void]$inflight.Remove($relKey)
        if ($releaseLane) {
            $laneBusy[$lost.Lane] = $laneBusy[$lost.Lane] - 1
        }
        $pending.Complete($lost.Folder)
        recordUserPowerPointPostponed $lost.Number $lost.Row $reason
    }

    $reporter.Progress(${indexingPhaseCrawl}, 0, 0, 0, "インデックス作成の準備をしています…")

    $restartInterval = 100  # Officeアプリを再起動する間隔（取り込みのスレッドごとのファイル数）。メモリ肥大化対策（再起動 1 回で約 2 秒かかるため、間隔を詰めすぎない）
    $fileTimeoutMinutes = ${ingestFileTimeoutMinutes}  # 1ファイルの取り込みの制限時間（分）。超えたらOfficeアプリを強制終了し、そのファイルは失敗とする
    $approvalTimeoutMinutes = 60  # 画面の返事を待つ制限時間（分）。画面が返事をしない場合に待ち続けないよう打ち切る
    $interruptLimit = 2       # 取り込み中に続けて強制終了した回数がこれに達したファイルは、失敗として以降スキップする
    $failureListLimit = 50    # 終了時に失敗したファイルと原因を表示する最大件数（残りは取り込み一覧で確認する）
    $cloudListLimit = 50      # クラウドにだけあるため残したファイルを、ログに 1 件ずつ書く最大件数（残りは「ほか N 件」にする）

    $targetFolders = @(getTargetFolders)
    if ($targetFolders.Count -eq 0) {
        throw "クロール対象フォルダがありません。画面でクロール対象フォルダを追加してください。"
    }
    if (@($targetFolders | Where-Object { $_.Enabled }).Count -eq 0) {
        throw "チェックの付いたクロール対象フォルダがありません。画面で取り込むフォルダにチェックを付けてください。"
    }

    # 前の版のインデックス（index\）が見つかれば知らせ、取り込み直しを始めるときは前の版のシステムインデックスを片付ける。
    # content_index\ を作る前に行う（片付けに失敗したら content_index\ を作らずに終わる）
    $legacyState = getLegacyIndexState $workspace.Dir
    $legacyMessage = getLegacyIndexMessage $workspace.Dir $legacyState.HasLegacyIndex
    if ($legacyMessage) {
        writeIndexerLog $legacyMessage "Yellow"
    }
    if (testLegacyCleanupNeeded $legacyState) {
        writeIndexerLog "前の版のインデックス（高速検索用）を片付けています…"
        $cleanup = clearLegacySystemIndex $workspace.Dir
        if (!$cleanup.Ok) {
            throw "前の版のインデックス（高速検索用）を片付けられませんでした（$($cleanup.Reason)）。tebunko の画面やエクスプローラーで開いていれば閉じてから、もう一度インデックス作成を行ってください。"
        }
    }

    [System.IO.Directory]::CreateDirectory($workspace.IndexDir) | Out-Null
    # 前の版から続けて使うワークスペース・別のドライブへ写したワークスペース・取り込んだワークスペースもここで付く
    # （継ぐかどうかに頼らず、ここで一度だけ content_index 全体に付ける。入れた直後にはそれぞれの場所でも付ける）。
    # 根フォルダに未だ付いていない回（主に初回）は下をすべてたどるため時間がかかるので、先に 1 行残しておく
    writeIndexerLog "content_index を Windows Search の対象から外しています…"
    $nci = setNotContentIndexed $workspace.IndexDir -Recurse
    if (!$nci.Ok) {
        writeIndexerLog "content_index を Windows Search の対象から外せませんでした（$($nci.Reason)）。高速検索が効くまで時間がかかることがあります。" "Yellow"
    }
    $selected = initTmpDir
    $script:tmpDir = $selected.Dir
    $script:tmpDirReason = $selected.Reason
    [System.IO.Directory]::CreateDirectory($workspace.PublishDir) | Out-Null

    # クロール対象フォルダごとにインデックス名（work\content_index 直下のフォルダ名）を決める。前回と同じフォルダは同じ名前を使う
    $status = $ledger.ReadStatus()
    $planner = [IngestPlanner]::new(@{
        Unchecked = ${planKindUnchecked}; Missing = ${planKindMissing}; Dropped = ${planKindDropped}; StateFailed = ${stateFailed}
    })
    $catalog = [IndexCatalog]::new($workspace, ${settingsFile}, $ledger)
    $planner.AssignNames($targetFolders, $status)
    $folders = $planner.Folders
    $previous = $planner.Previous
    # 設定から外れたインデックスは、ここでは消さない。確認ダイアログに「削除予定」として出し、［更新を開始］が押されたときだけ消す
    $dropped = $planner.Dropped
    # 前回のインデックス作成が途中で止まり、本文インデックスのファイルに入れていない TSV（元のファイルごとのフォルダ）が残っていれば、先に入れる
    $leftover = findIndexFoldersWithBooks $workspace.IndexDir
    if ($leftover.Count -gt 0) {
        writeIndexerLog "集約ファイルに入れていないインデックス（$($leftover.Count) フォルダ）をまとめています…"
        $reporter.Progress(${indexingPhaseCrawl}, 0, 0, 0, "集約ファイルに入れていないインデックスをまとめています…")
        foreach ($folder in $leftover) {
            $pending.MarkFolder($folder)
        }
        flushPending -All
    }

    # 新しく割り当てたインデックス名を設定に保存する
    $planner.SaveNames($targetFolders, { param($assigned) $catalog.StoreAssignedNames($assigned) }.GetNewClosure())
    $folders = $planner.Folders

    writeIndexerLog "出力先フォルダ: $($workspace.IndexDir)"
    writeIndexerLog ""
    writeIndexerLog "クロールしています..."
    # 取り込み一覧の「済」に対してインデックス（TSV）が残っているかを調べるため、今あるTSVの数を数えておく
    # （利用者が work\content_index を直接削除した場合に、「済」のまま検索できなくなるのを防ぐ）
    $reporter.Progress(${indexingPhaseCrawl}, 0, 0, 0, "更新済みのインデックスを確認しています…")
    $indexCounts = getIndexTsvCounts
    if ($null -eq $indexCounts) {
        writeIndexerLog "  インデックスのフォルダを調べられないため、インデックスが残っているかの確認は行いません。" "Yellow"
    }
    # 選んだインデックスだけを更新するとき（OnlyNames）。選ばなかったインデックスは、この回では一切触らない
    # （取り込み一覧の行は前回のまま・確認の表に出さない・失敗の一覧に加えない）
    if (@($channel.OnlyNames).Count -gt 0) {
        $channel.OnlySkipped = @($planner.SelectOnly([string[]]@($channel.OnlyNames)))
        if ($planner.Only.Selected.Count -eq 0) {
            throw "選んだインデックスに、更新できるものがありません。"
        }
    }
    # クロールして、取り込む順番・画面の確認に出す件数・取り込み一覧に書く行を組み立てる
    $crawlPhase = ${indexingPhaseCrawl}
    $onCrawlFolder = { param ($target) $reporter.Progress($crawlPhase, 0, 0, 0, "[$($target.Name)] の対象ファイルを探しています… $($target.Path)") }.GetNewClosure()
    $planner.Crawl($indexCounts, $onCrawlFolder)
    foreach ($removedPath in $planner.RemovedPaths) {
        $pending.Add($removedPath, $true)
    }
    $rows = $planner.Rows
    $targets = $planner.Targets
    $failed = $planner.Failed
    $plan = $planner.Plan
    # クラウドにだけあるファイル（取り込むかは確認の後に決める）
    $cloudAll = $planner.Cloud
    # 消さなかったインデックス（取りやめ・画面なしの実行）は、取り込み一覧に前回のまま残す（次の回にまた見つけて確認に出すため）
    $keptDropped = $dropped

    # 画面から始めた場合は、数えた件数を画面に出して、取り込むかどうかの返事を待つ。
    # 「更新不要」かどうかも、この件数を見て画面が知らせる（取り込み対象が 0 件でも、前回失敗の再取り込みを選べる）
    $retryTargets = [bool]$channel.RetryFailed
    $includeCloud = [bool]$channel.IncludeCloud
    if ($channel.ConfirmTargets) {
        $answer = $reporter.WaitForApproval(${indexingPhaseConfirm}, $plan.ToArray(), $targets.Count, $failed.Count, $approvalTimeoutMinutes)
        if ($null -eq $answer) {
            # 取りやめ。取り込み対象にした行は前回の記録のまま（一覧に無かったファイルは記録しない）にする。
            # 取り込み一覧自体は書き直す（無くなったファイルの削除を反映する必要があるため）
            $keep = $planner.KeepForCancel()
            writeIndexerLog ""
            writeIndexerLog "画面で取りやめたため、取り込みません。（取り込み一覧は前回のままです）" "Yellow"
            writeStatusKeepingDropped $ledger $folders $keep $keptDropped $previous
            writeSourceFolderFile $folders
            $reporter.Progress(${indexingPhaseFinish}, 0, 0, 0, "インデックス作成を取りやめました")
            removeTmpDir
            return 2
        }
        $retryTargets = $answer.RetryFailed
        $includeCloud = [bool]$answer.IncludeCloud
        removeDroppedFolders $dropped
        $keptDropped = @()
    } else {
        foreach ($item in $dropped) {
            writeIndexerLog "設定に無いインデックス（$($item.Name): $($item.Path)）は削除せずに残しました。画面の［すべて更新］で確認して削除できます。" "Yellow"
        }
    }

    # クラウドにだけあるファイル: ダウンロードして取り込むと選ばれたものだけ取り込み、あとは前回のまま残す
    # （取り込み一覧の行は createTargetList が前回の行にしてある。次のインデックス作成で、また確かめる）
    $cloudSplit = splitCloudItems $cloudAll $retryTargets $includeCloud
    if ($cloudSplit.Included.Count -gt 0) {
        $includedPaths = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($item in $cloudSplit.Included) {
            [void]$includedPaths.Add($item.RelPath)
        }
        $rebuilt = New-Object System.Collections.Generic.List[object]
        foreach ($row in $rows) {
            if (!$includedPaths.Contains($row.相対パス)) {
                $rebuilt.Add($row)
            }
        }
        $rows = $rebuilt
        writeIndexerLog ""
        writeIndexerLog "クラウドにだけあるファイル $($cloudSplit.Included.Count) 件は、ダウンロードして取り込みます。"
        foreach ($item in $cloudSplit.Included) {
            $rows.Add($item.Row)
            $targets.Add($item.Row)
        }
    }
    # 前回失敗したファイルを再取り込みしない（チェックなし）なら、クラウドにあるかどうかに関係なく残すため、クラウドのせいで残した件数には数えない
    $cloudSkippedItems = @($cloudSplit.Skipped | Where-Object { $retryTargets -or -not $_.Failed })
    $cloudSkipped = $cloudSkippedItems.Count
    $channel.CloudSkipped = $cloudSkipped
    if ($cloudSkipped -gt 0) {
        writeIndexerLog ""
        writeIndexerLog "クラウドにだけあるファイル $cloudSkipped 件は、ダウンロードせずに残します。（次のインデックス作成でも確かめます）" "Yellow"
        foreach ($group in ($cloudSkippedItems | Group-Object { ([string]$_.RelPath).Split("\")[0] })) {
            writeIndexerLog "  [$($group.Name)] $($group.Count) 件"
        }
        $listed = 0
        foreach ($item in $cloudSkippedItems) {
            # 大きいフォルダでは毎回この件数ぶん出るため、先頭の $cloudListLimit 件だけ書き、残りは件数にする
            if ($listed -lt $cloudListLimit) {
                writeIndexerLog "    $($item.RelPath)"
                $listed++
            }
            if ($item.PendingOld) {
                # 前回未完了のまま残っている取り込み途中のインデックスは、使えないため消す（一覧にも行を残さない）
                removeBookDir (getBookDir $item.RelPath)
                $pending.Add($item.RelPath, $true)
            }
        }
        if ($cloudSkipped -gt $listed) {
            writeIndexerLog "    ほか $($cloudSkipped - $listed) 件"
        }
    }

    $planner.ApplyFailed($retryTargets)
    # 前回、取り込み中に強制終了したファイルは最後に回す（続けて $interruptLimit 回強制終了したファイルは失敗とする）。
    # 最後に回したファイルは、取り込みを始めるまで記録を残す（その前にまた止まっても、回数が分かるように）
    $planner.ApplyInterrupted(@($ledger.ReadIngestingFiles()), $interruptLimit)
    $carried = $planner.Carried
    $ledger.WriteIngestingFiles(@($carried.Keys | ForEach-Object { @{ RelPath = $_; Count = $carried[$_] } }))
    $reporter.Progress(${indexingPhaseCrawl}, 0, $targets.Count, 0, "更新の記録を書き出しています…")
    writeStatusKeepingDropped $ledger $folders $rows.ToArray() $keptDropped $previous
    # インデックスのフォルダごと別の場所・PCへコピーしても元のファイルの場所が分かるよう、インデックス名とクロール対象フォルダの対応を置く
    writeSourceFolderFile $folders

    # インデックス名 → クロール対象フォルダ
    $folderByName = $planner.FolderByName()

    if ($targets.Count -eq 0) {
        writeIndexerLog ""
        if ($cloudSkipped -eq 0) {
            writeIndexerLog "取り込みが必要なファイルはありません。（一覧: $(Split-Path $workspace.StatusFile -Leaf)）" "Green"
        } else {
            writeIndexerLog "取り込めるファイルはありません。（一覧: $(Split-Path $workspace.StatusFile -Leaf)）" "Green"
        }
        # 元のファイルが無くなったフォルダは、本文インデックスのファイルから外す
        flushPending -All
        # 取り込むファイルが無くても、システムインデックスがまだ無いフォルダ（この版に上げた直後など）は作る
        $reporter.Progress(${indexingPhaseFinish}, 0, 0, 0, "システムインデックス（高速検索用）を確かめています…")
        try {
            [void](updateSystemIndexes -shouldStop { $channel.Stop })
        } catch {
            writeIndexerLog "システムインデックスを作れませんでした（次のインデックス作成で作り直します）: $($_.Exception.Message)" "Yellow"
        }
        $reporter.Progress(${indexingPhaseFinish}, 0, 0, 0, $(if ($cloudSkipped -eq 0) { "更新が必要なファイルはありませんでした" } else { "クラウドにだけあるファイルは、ダウンロードせずに残しました" }))
        removeTmpDir
        return 0
    }

    $total = $targets.Count
    $readers = getIngestWorkerCount $channel.Workers $total ([int](readSettings).ingestThreads)
    writeIndexerLog ""
    if ($readers -gt 0) {
        writeIndexerLog "$total 件のファイルを取り込みます。（Excel・Word・PowerPoint はそれぞれ 1 つずつ、Office を使わずに読むファイルは $readers 個のスレッドで並べて取り込みます。1ファイルの取り込みに ${fileTimeoutMinutes} 分以上かかった場合は、そのファイルを失敗として次のファイルへ進みます）"
    } else {
        writeIndexerLog "$total 件のファイルを取り込みます。（1ファイルの取り込みに ${fileTimeoutMinutes} 分以上かかった場合は、そのファイルを失敗として次のファイルへ進みます）"
    }

    $successCount = 0
    $postponedCount = 0 # 利用者のPowerPointのために取り込めなかった件数（失敗の件数に含む。一覧は「未取り込み」のまま次回に回す。終わりの案内で、再取り込みの選択が要る失敗と分ける）
    $stopped = $false
    # 今回失敗したファイル（$ledger.Failures。@{ RelPath; Message } の並び）・
    # 取り込みの直前に元のファイルが無くなっていた相対パス（$ledger.DroppedRows。取り込み一覧から除く）は StatusLedger が持つ
    $folderLost = ""  # インデックス作成中に見えなくなったクロール対象フォルダ（見つかったら中止する）
    $remaining = 0
    # 取り込み中のファイル: 相対パス → @{ Row; Count; Folder; Number; Lane; Task }
    $inflight = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
    # フォルダごとの取り込み中の数と、まだ渡していない数（どちらも 0 になったら本文インデックスのファイルに書き出す）は $pending が持つ
    # レーンごとの取り込み中の数（レーンに渡せる数は ingestLaneCapacity）
    $laneBusy = @{}
    $lanes = New-Object string[] $total
    $bookFolders = New-Object string[] $total
    $dispatched = New-Object bool[] $total
    $undispatched = $total
    for ($i = 0; $i -lt $total; $i++) {
        $lanes[$i] = getIngestLane $targets[$i].相対パス
        $bookFolders[$i] = [System.IO.Path]::GetDirectoryName((getBookDir $targets[$i].相対パス))
        $pending.AddPending($bookFolders[$i])
    }
    # 起動した Office の PID の記録を置く場所（開始時のワークスペースから決め、取り込みのスレッドへ文字列で渡す。途中でワークスペースが変わっても、書く所と消す所が食い違わない）
    $officeRecordDir = getOfficePidDir $workspace
    $pool = $null
    $inlineResult = $null
    $currentPath = ""  # 最後に取り込みのスレッドに渡したファイル（画面に「取り込み中のファイル」として出す）
    $next = 0          # まだ渡していない最初のファイル

    try {
        if ($readers -gt 0) {
            $pool = newIngestPool $readers @{
                Lib = (getPartLoad indexerLib)
                WorkDir = $workspace.Dir; TmpDir = ${tmpDir}; TmpDirReason = ${tmpDirReason}; PublishDir = $workspace.PublishDir
                FileTimeoutMinutes = $fileTimeoutMinutes; RestartInterval = $restartInterval; OfficePids = $channel.OfficePids
                UserOfficePids = $channel.UserOfficePids
                OfficeRecordDir = $officeRecordDir; Channel = $channel
            }
        } else {
            $script:officePidSink = $channel.OfficePids
            $script:officeRecordDir = $officeRecordDir
            $script:officeOwnDir = resolveOwnDir ${tmpDir}
            $script:onOfficeHandOver = ${officeHandOverNotice}
            # 司令のスレッドで取り込むときは、利用者が使っている PowerPoint を止めないだけ（諦めるレーンが無いため Abandon は渡さない）
            $script:officeWatchdog.State.Users = $channel.UserOfficePids
            $script:officeWatchdog.Start()
        }

        while ($true) {
            # 制限時間を過ぎても利用者が使っている PowerPoint を止めずに諦めたレーンは、取り込み中だったファイルを後回しにする
            # （固まった呼び出しは戻らないことがあるため、結果を待たない。戻ってきた結果は捨てる）
            if ($pool) {
                foreach ($abandonedLane in @(getUnhandledAbandonedLanes $pool)) {
                    $pool.LaneStates[$abandonedLane].Handled = $true
                    foreach ($relKey in @($inflight.Keys)) {
                        if ($inflight[$relKey].Lane -ne $abandonedLane) {
                            continue
                        }
                        postponeInflightForUser $relKey ${postponedReasonInUse} -releaseLane
                        $postponedCount++
                    }
                    $ledger.WriteIngestingFiles((getIngestingEntries $inflight $carried))
                    $reporter.Progress(${indexingPhaseIngest}, ($successCount + $ledger.Failures.Count), ($total - $successCount - $ledger.Failures.Count), $ledger.Failures.Count, $currentPath)
                    flushPending
                }
            }
            # 空いているレーンに、次のファイルを渡す。並びの先（ingestLookAhead 件まで）も見て、空いているレーン向けのものを先に渡す
            # （Excel のファイルが続いても、Office を使わずに読むファイルを待たせない）
            if (!$stopped -and !$folderLost -and $undispatched -gt 0 -and $channel.Stop) {
                # 画面から中止を求められたら、次のファイルを渡さずに終える（残りは「未取り込み」のまま、次回取り込みする）
                $stopped = $true
                $remaining = $undispatched
                writeIndexerLog ""
                writeIndexerLog "中止の要求を受けたため、インデックス作成を中止します。（残り ${remaining} 件は次回取り込みします）" "Yellow"
            }
            $limit = [Math]::Min($total, $next + ${ingestLookAhead})
            for ($i = $next; !$stopped -and !$folderLost -and $i -lt $limit; $i++) {
                if ($dispatched[$i]) {
                    continue
                }
                $lane = $lanes[$i]
                if ($pool -and $pool.LaneStates[$lane].Abandoned) {
                    # 諦めたレーンのファイルは、渡さずに「未取り込み」のまま残す
                    $dispatched[$i] = $true
                    $undispatched--
                    $pending.Skip($bookFolders[$i])
                    $postponedCount++
                    recordUserPowerPointPostponed ($i + 1) $targets[$i] ${postponedReasonInUse}
                    $reporter.Progress(${indexingPhaseIngest}, ($successCount + $ledger.Failures.Count), ($total - $successCount - $ledger.Failures.Count), $ledger.Failures.Count, $currentPath)
                    continue
                }
                if ($pool) {
                    if ([int]$laneBusy[$lane] -ge (getIngestLaneCapacity $lane $readers)) {
                        continue
                    }
                } elseif ($inflight.Count -ge 1) {
                    break
                }
                $row = $targets[$i]
                $relPath = $row.相対パス
                $bookFolder = $bookFolders[$i]
                $parts = splitIndexRelPath $relPath
                $sourceFolder = $folderByName[$parts.Name]
                $sourcePath = Join-Path $sourceFolder $parts.Rest

                # 取り込み対象を調べてから取り込むまでの間に、元のファイルが移動・削除されることがある。
                # 「失敗」として記録すると、再取り込みを選ぶまで残ってしまうため、無くなったファイルは一覧・インデックスから除く
                if (![System.IO.File]::Exists((toLongPath $sourcePath))) {
                    if (!(Test-Path -LiteralPath $sourceFolder -PathType Container)) {
                        # クロール対象フォルダごと見えなくなった（ネットワークの切断・USBメモリの取り外し等）。
                        # 残りのファイルをすべて失敗にしないよう、「未取り込み」のまま中止する（次回、続きから取り込める）
                        $folderLost = $sourceFolder
                        $remaining = $undispatched
                        break
                    }
                    $dispatched[$i] = $true
                    $undispatched--
                    $pending.Skip($bookFolder)
                    writeIndexerLog ("[{0}/{1}] {2}" -f ($i + 1), $total, $relPath)
                    writeIndexerLog "    元のファイルが無くなったため、取り込まずに一覧から除きます。（移動・削除・名前変更された）" "Yellow"
                    removeBookDir (getBookDir $relPath)
                    $pending.Add($relPath, $true)
                    $ledger.AddDropped($relPath)
                    continue
                }

                # 強制終了したときに、どのファイルの取り込み中に止まったか次回分かるよう記録する
                $count = 1
                if ($carried.ContainsKey($relPath)) {
                    $count = $carried[$relPath] + 1
                    [void]$carried.Remove($relPath)
                }
                $task = @{ RelPath = $relPath; SourcePath = $sourcePath }
                $dispatched[$i] = $true
                $undispatched--
                $inflight[$relPath] = @{ Row = $row; Count = $count; Folder = $bookFolder; Number = $i + 1; Lane = $lane; Task = $task }
                $pending.Dispatch($bookFolder)
                $laneBusy[$lane] = [int]$laneBusy[$lane] + 1
                $ledger.WriteIngestingFiles((getIngestingEntries $inflight $carried))
                # 画面はこの 1 行から進み具合を作る（取り込み一覧は読まない）
                $currentPath = $relPath
                $reporter.Progress(${indexingPhaseIngest}, ($successCount + $ledger.Failures.Count), ($total - $successCount - $ledger.Failures.Count), $ledger.Failures.Count, $currentPath)
                if ($pool) {
                    addIngestTask $pool $lane $task
                } else {
                    $inlineResult = invokeIngestTask $task $fileTimeoutMinutes
                }
            }
            while ($next -lt $total -and $dispatched[$next]) {
                $next++
            }
            if ($inflight.Count -eq 0) {
                if ($stopped -or $folderLost -or $undispatched -eq 0) {
                    break
                }
                continue
            }

            # 取り込みの結果を 1 つ受け取って記録する
            if ($pool) {
                $result = receiveIngestResult $pool
            } else {
                $result = $inlineResult
                $inlineResult = $null
            }
            if ($null -eq $result) {
                # 諦めたレーンがある。ループの先頭で後回しにする
                continue
            }
            $entry = $null
            if (!$inflight.TryGetValue($result.RelPath, [ref]$entry)) {
                # 諦めたレーンのスレッドが、後回しにしたあとで返した結果。捨てる
                continue
            }
            if ($result.Reroute) {
                # Office を使わずに読めなかった（中身が旧形式・パスワード付き）。Word・PowerPoint のレーンに回し直す
                # （取り込み中のまま。中止を求められていても最後まで取り込む）
                $laneBusy[$entry.Lane] = $laneBusy[$entry.Lane] - 1
                $entry.Lane = getOfficeLane $result.RelPath
                if ($pool.LaneStates[$entry.Lane].Abandoned) {
                    # 回し先が諦めたレーンのときは、渡さずに後回しにする
                    postponeInflightForUser $result.RelPath ${postponedReasonInUse}
                    $postponedCount++
                    $ledger.WriteIngestingFiles((getIngestingEntries $inflight $carried))
                    flushPending
                    continue
                }
                $laneBusy[$entry.Lane] = [int]$laneBusy[$entry.Lane] + 1
                addIngestTask $pool $entry.Lane $entry.Task
                continue
            }
            if ($result.Postponed) {
                # 利用者のPowerPointが起動していて使えなかった。失敗として理由を見せ、取り込み一覧は「未取り込み」のまま残して次回のインデックス作成で取り込む
                # （インデックスは変えない。$ledger.AddRow・$pending.Add はしない）
                [void]$inflight.Remove($result.RelPath)
                $laneBusy[$entry.Lane] = $laneBusy[$entry.Lane] - 1
                $pending.Complete($entry.Folder)
                $postponedCount++
                # 諦めたレーンのスレッドが返した後回しは「使っている方がいた」、始めから起動していたときは「起動していた」
                $postponedReason = if ($pool -and $pool.LaneStates[$entry.Lane].Abandoned) { ${postponedReasonInUse} } else { ${postponedReasonRunning} }
                recordUserPowerPointPostponed $entry.Number $entry.Row $postponedReason
                $ledger.WriteIngestingFiles((getIngestingEntries $inflight $carried))
                $reporter.Progress(${indexingPhaseIngest}, ($successCount + $ledger.Failures.Count), ($total - $successCount - $ledger.Failures.Count), $ledger.Failures.Count, $currentPath)
                flushPending
                continue
            }
            [void]$inflight.Remove($result.RelPath)
            $laneBusy[$entry.Lane] = $laneBusy[$entry.Lane] - 1
            $row = $entry.Row
            writeIndexerLog ("[{0}/{1}] {2}" -f $entry.Number, $total, $result.RelPath)
            foreach ($line in ($result.Log -split "\r?\n")) {
                if ($line) {
                    writeIndexerLog $line
                }
            }
            if ($result.Ok) {
                $pending.Add($result.RelPath, $false)
                # 高速検索: このフォルダの システムインデックスを作り直すまで、検索ではこのフォルダを必ず照合させる
                if (!(markSystemIndexChanged @([System.IO.Path]::GetDirectoryName($result.RelPath)))) {
                    writeIndexerLog "    システムインデックスの状態を書き込めませんでした（インデックス作成の終わりに作り直します）。" "Yellow"
                }
                writeIndexerLog "    TSV $($result.TsvCount) 件を作成しました。"
                $row.状態 = ${stateDone}
                $row.TSV数 = [string]$result.TsvCount
                $row.エラー = ""
                $row.抽出版 = $result.ExtractVersion
                $successCount++
            } else {
                writeIndexerLog "    取り込みに失敗しました: $($result.Message)" "Red"
                $row.状態 = ${stateFailed}
                $row.TSV数 = ""
                $row.エラー = $result.Message
                $row.抽出版 = ""
                $ledger.AddFailure($result.RelPath, $result.Message)
            }

            # 中断しても結果が残るよう、1件ごとに取り込み一覧へ追記する（最後に1ファイル1行にまとめ直す）
            $row.取り込み日時 = formatFileTime (Get-Date)
            $ledger.AddRow($row)
            $ledger.WriteIngestingFiles((getIngestingEntries $inflight $carried))
            $pending.Complete($entry.Folder)
            $reporter.Progress(${indexingPhaseIngest}, ($successCount + $ledger.Failures.Count), ($total - $successCount - $ledger.Failures.Count), $ledger.Failures.Count, $currentPath)

            if (!$pool -and ($result.TimedOut -or (($successCount + $ledger.Failures.Count) % $restartInterval) -eq 0)) {
                # 制限時間を過ぎて強制終了したアプリは使えないため、すべて終了して次に必要になったときに起動し直す
                stopAllApps
            }
            # 取り込みが揃ったフォルダ（取り込み中が無く、まだ渡していないファイルも無い）を、本文インデックスのファイルに書き出す
            flushPending
        }
    } finally {
        # 中止・続けられないエラーの場合もここは実行される。
        # 後片付けも数十秒かかることがあるため、何をしているかを画面に伝える（進み具合の数はそのまま残す）
        # 画面は「成功 = 処理済み - 失敗」と出すため、取り込まなかった（元ファイルが無くなった）分は数に入れない
        $processed = $successCount + $ledger.Failures.Count
        $reporter.Progress(${indexingPhaseFinish}, $processed, 0, $ledger.Failures.Count, "Officeアプリを終了しています…")
        if ($pool) {
            stopIngestWorkers $pool
        } else {
            $script:officeWatchdog.Stop()
            stopAllApps
            waitKeptApps ({ [bool]$channel.Stop }.GetNewClosure())
        }
        $script:officePidSink = $null
        $script:officeRecordDir = $null
        $script:officeOwnDir = $null
        $script:onOfficeHandOver = $null
        removeTmpDir
        $ledger.RemoveIngestingFile()
        # 取り込んだ TSV は、中止したときも残さず本文インデックスのファイルに入れる（残すとインデックスの容量が倍になる）
        $reporter.Progress(${indexingPhaseFinish}, $processed, 0, $ledger.Failures.Count, "インデックスをまとめています…")
        flushPending -All
        $reporter.Progress(${indexingPhaseFinish}, $processed, 0, $ledger.Failures.Count, "更新の記録を書き直しています…")
        # 取り込みの直前に無くなっていたファイルの行は除く（次回の検索でも見つからず、インデックスも削除済み）
        writeStatusKeepingDropped $ledger $folders @($rows | Where-Object { $_ -and !$ledger.DroppedRows.Contains([string]$_.相対パス) }) $keptDropped $previous
        # 初めて取り込んだインデックスは、最初に書き出した時点ではまだフォルダが無いため、ここでもう一度書く
        # （work\content_index\<インデックス名>\source_folder.txt。インデックス 1 個だけをコピーしても元のファイルの場所が分かる）
        writeSourceFolderFile $folders
        # 高速検索用の システムインデックスを作り直す。中止したとき・フォルダが見えなくなったときは作らない
        # （作り直していないフォルダは反映待ちのままのため、検索ではそのフォルダを照合する）
        if (!$stopped -and !$folderLost) {
            $reporter.Progress(${indexingPhaseFinish}, $processed, 0, $ledger.Failures.Count, "システムインデックス（高速検索用）を作っています…")
            try {
                [void](updateSystemIndexes -shouldStop { $channel.Stop })
            } catch {
                writeIndexerLog "システムインデックスを作れませんでした（次のインデックス作成で作り直します）: $($_.Exception.Message)" "Yellow"
            }
        }
        # 画面が終わり方（成功・失敗の件数）を読めるよう、進み具合は消さずに最後の状態を残す
        $reporter.Progress(${indexingPhaseFinish}, $processed, $remaining, $ledger.Failures.Count, "")
    }

    if ($folderLost) {
        # クロール対象フォルダが見えなくなった場合は、続けられないエラーとして画面に知らせる（残りは未取り込みのまま）
        $message = "クロール対象フォルダが見つからなくなったため、インデックス作成を中止しました: ${folderLost}" +
            "（残り ${remaining} 件は取り込まずに残しました。フォルダを使えるようにしてから、もう一度更新してください）"
        writeIndexerLog ""
        writeIndexerLog $message "Red"
        $channel.Error = $message
        return 1
    }

    writeIndexerLog ""
    if ($stopped) {
        writeIndexerLog "インデックス作成を中止しました。（成功: ${successCount} 件 / 失敗: $($ledger.Failures.Count) 件）" "Yellow"
    } else {
        writeIndexerLog "インデックス作成が完了しました。（成功: ${successCount} 件 / 失敗: $($ledger.Failures.Count) 件）" "Green"
    }
    if ($ledger.DroppedRows.Count -gt 0) {
        writeIndexerLog "取り込みの直前に元のファイルが無くなった $($ledger.DroppedRows.Count) 件は、取り込まずに一覧から除きました。" "Yellow"
    }
    writeIndexerLog "各ファイルの状態・更新日時は $(Split-Path $workspace.StatusFile -Leaf) で確認できます。"
    if ($ledger.Failures.Count -gt 0) {
        # インデックス作成中の表示は流れて見えなくなるため、失敗したファイルと原因を最後にまとめて表示する
        writeIndexerLog ""
        writeIndexerLog "＜取り込みに失敗したファイルと原因＞" "Yellow"
        foreach ($failure in @($ledger.Failures | Select-Object -First $failureListLimit)) {
            writeIndexerLog "  $($failure.RelPath)"
            writeIndexerLog "    → $($failure.Message)" "Red"
        }
        if ($ledger.Failures.Count -gt $failureListLimit) {
            writeIndexerLog "  ほか $($ledger.Failures.Count - $failureListLimit) 件（原因は一覧の「エラー」列）"
        }
        writeIndexerLog ""
        if ($ledger.Failures.Count -gt $postponedCount) {
            writeIndexerLog "失敗したファイルは、画面で「失敗分も再取り込みする」を選んで取り込むと再取り込みします。" "Yellow"
        }
        if ($postponedCount -gt 0) {
            # 一覧の状態は「未取り込み」のため、PowerPoint を閉じてからの次の更新で選ばなくても取り込む
            writeIndexerLog "PowerPoint のために取り込めなかった ${postponedCount} 件は、PowerPoint を閉じてからもう一度更新すると、そのまま取り込みます。" "Yellow"
        }
    }

    if ($stopped) {
        return 2
    }
    return 0
}

function getIngestingEntries {
    # 取り込み中のファイルの記録（writeIngestingFiles に渡す形）。取り込み中のものと、最後に回してまだ始めていないもの
    param (
        $inflight,
        $carried
    )

    $entries = New-Object System.Collections.Generic.List[hashtable]
    foreach ($key in $inflight.Keys) {
        $entries.Add(@{ RelPath = $key; Count = $inflight[$key].Count })
    }
    foreach ($key in $carried.Keys) {
        $entries.Add(@{ RelPath = $key; Count = $carried[$key] })
    }
    return , $entries.ToArray()
}


# インデクサ（indexer.ps1）の本体。indexer.ps1 が読み込んで呼ぶ（引数はそのまま転送する）。
# 流れは docs/design/indexing/flow.md、スレッドの分け方は docs/design/structure/threads.md。

function invokeIndexerMain {
    # 画面なしで起動したとき（$Channel が無い）は、壊れた設定ファイルを退避して既定の設定で続ける
    # （知らせは invokeIndexer がログを開いた直後に出す）。画面から -Channel 付きで動くときは、画面が起動時に退避済み
    param (
        [switch]$RetryFailed,
        $Channel = $null
    )

    $script:settingsRecovery = ""
    if ($null -eq $Channel) {
        $script:settingsRecovery = repairBrokenSettings
    }

    $ErrorActionPreference = "Stop"
    initWorkspace

    if ($null -eq $Channel) {
        $Channel = newIndexerChannel -retryFailed ([bool]$RetryFailed) -includeCloud ((readCloudFiles) -eq ${cloudFilesDownload})
        $script:indexerEcho = $true
    }
    # 途中の処理が出力した値が混ざらないよう、最後の値（終了コード）を使う
    return [int]@(invokeIndexer $Channel)[-1]
}
@@'@

# ---- BODY-START (above: parts embedded for other threads) ----
# 起動そのものに失敗したときの知らせの文言（判断層。画面・WPF に触らない）。
# 記録に書く内容と、メッセージボックスに出す文を決める。出す・書くのは startup_error.ps1。
# 制限言語モードでも読み込めるよう、.NET のメソッドを呼ばない。

# ツールのフォルダの startup_error.txt に書く記録の 1 件分（app_host.ps1 を読み込む前の失敗用）
function getStartupErrorDetail {
    param (
        $err,
        [string]$languageMode,
        [string]$timestamp
    )

    return "==== $timestamp 起動・実行中 ====`r`nLanguageMode: $languageMode`r`n$($err.Exception.Message)`r`n$($err.InvocationInfo.PositionMessage)`r`n`r`n"
}

# メッセージボックスの本文。記録できたファイルがあれば、そのファイル名を添える
function getStartupErrorMessage {
    param (
        [string]$message,
        [string]$recordFile
    )

    $suffix = if ($recordFile) { "`n`n詳しい内容は $(Split-Path -Leaf $recordFile) に残しています。" } else { "" }
    return "予期しないエラーが発生しました。`n${message}${suffix}"
}
# 起動そのものに失敗したとき（Add-Type・読み込み・画面の組み立てで例外）の知らせ方。
# gui.ps1 が try で囲み、失敗したら reportStartupFailure を呼んで終了コードを受け取る。
# app_host.ps1 を読み込む前（writeErrorLog がまだ使えない）に起きた失敗にも対応するため、
# 文言は startup_error_view.ps1（gui.ps1 が先に読み込む）。gui.ps1 の読み込みの一番最初（Add-Type より前）に、startup_error_view.ps1 に続けてここを読み込む。

${appTitle} = "tebunko"

# 画面で起きた予期しないエラーの記録先（gui.ps1 が setGuiErrorLogSource で登録し、app_host.ps1 の writeErrorLog が使う）。今のワークスペースの中に置く。
# startGui を抜けた後（gui.ps1 の外側の catch）でも使えるよう、スクリプト直下に置く。ワークスペースが決まる前は $null を返す
function getToolGuiErrorLogFile {
    if ($null -eq $script:workspace) {
        return $null
    }
    return $script:workspace.GuiErrorLogFile
}

# gui_error_log.txt の先頭（プロセスごとの最初の記録の前）に書く版と環境の見出し（行の配列）。gui.ps1 が登録し、app_host.ps1 の writeErrorLog が使う
function getToolGuiErrorLogHeader {
    return getToolDiagnosticHeader
}

# 実際に書けた記録のファイルだけを返す（writeErrorLog は書けなくても例外を出さないため）
function getExistingRecordFile {
    param (
        [string]$path
    )

    if ($path -and (Test-Path -LiteralPath $path)) {
        return $path
    }
    return $null
}

# writeErrorLog がまだ使えない（app_host.ps1 を読み込む前）ときに起きた失敗を、ツールのフォルダの startup_error.txt に追記する
# （置き場所は tebunko.bat と同じ。docs/safety/disclosure.md「起動に失敗したときの知らせ（tebunko.bat）」）。
# 制限言語モードでも動くよう、コマンドレットだけで書く（.NET のメソッドを呼ばない）。
# 置き場所はツールのフォルダの直下だけ。書けなければ記録を残さず $null を返す（そのときはメッセージボックスにファイル名を添えない）
function writeStartupErrorFile {
    param (
        [string]$text,
        [string]$toolDir = ${rootDir}   # ツールのフォルダ（gui.ps1 が先に paths.ps1 を読み込む）。テストで差し替える
    )


    $candidate = $null
    try {
        $candidate = Join-Path $toolDir "startup_error.txt"
        try {
            # 1 MB 以上なら前回の分に回す（溜まり続けないように）。移せなくても記録は書く
            if ((Get-Item -LiteralPath $candidate -ErrorAction Stop).Length -ge 1MB) {
                # 元を先に別の名前へ移す（元を移せないとき、-Force が前回の分を先に消すため）。移せたら前回の分に重ねる。重ねられなければ元の名前に戻す
                $moving = Join-Path $toolDir "startup_error_moving.txt"
                Move-Item -LiteralPath $candidate -Destination $moving -Force -ErrorAction Stop
                try {
                    Move-Item -LiteralPath $moving -Destination (Join-Path $toolDir "startup_error_previous.txt") -Force -ErrorAction Stop
                } catch {
                    Move-Item -LiteralPath $moving -Destination $candidate -ErrorAction SilentlyContinue
                }
            }
        } catch {
        }
        Add-Content -LiteralPath $candidate -Value $text -Encoding UTF8 -ErrorAction Stop
        return $candidate
    } catch {
        return $null
    }
}

# 起動そのものに失敗したときの知らせ。画面を閉じ（起動中の表示が残っていれば）、記録してメッセージボックスで知らせる。
# 戻り値は終了コード（gui.ps1 が exit に渡す）。メッセージボックスも出せない（制限言語モード・WPF が読めない）ときは、
# 元の例外を投げ直す（tebunko.bat の catch か、tebunko.exe のエラー出力が受けて知らせる）
function reportStartupFailure {
    param (
        $err
    )

    $recordFile = $null
    # 記録できる状態（app_host.ps1 の読み込み後で、writeErrorLog が使える）なら今までどおり gui_error_log.txt に、無ければツールのフォルダの startup_error.txt に記録する（書き込めなければ記録は残らない）
    if (Get-Command writeErrorLog -ErrorAction SilentlyContinue) {
        writeErrorLog "起動・実行中" $err
        $recordFile = getGuiErrorLogFile
        $recordFile = getExistingRecordFile $recordFile
    } else {
        $detail = getStartupErrorDetail $err ([string]$ExecutionContext.SessionState.LanguageMode) (Get-Date -Format 'yyyy-MM-dd HH:mm:ss')
        $recordFile = writeStartupErrorFile $detail
    }
    if (Get-Command closeSplash -ErrorAction SilentlyContinue) {
        closeSplash
    }
    try {
        [System.Windows.MessageBox]::Show((getStartupErrorMessage $err.Exception.Message $recordFile), ${appTitle}, "OK", "Error") | Out-Null
        return 1
    } catch {
        throw $err
    }
}

# tebunko の画面以外の部品の読み込み口。
# 画面（gui）・インデクサ・テスト・画面が起こす別スレッドから dot-source して使う。読み込む順に意味がある。
# 共通基盤（どのツールからも使う部品）の読み込み口。
# ツール側は、このファイルを dot-source すれば共通基盤がそろう。読み込む順に意味がある。
# フォルダ構成の基本（どのツールからも使う）。

# このファイルは scripts\shared\core\ に置く。3 つ上がリポジトリ直下になる（zip 版）。
# 単一 .ps1 版（展開せずに動く試験版。設計は docs/design/structure/single-script.md）は、
# scripts\ の下の階層が無いため、${bundledScriptPath}（結合の道具が入れる、自分自身のパス）があれば
# その .ps1 自身の置き場所を根フォルダとする
${pathsBundled} = Get-Variable -Name bundledScriptPath -ErrorAction SilentlyContinue
${rootDir} = if ($null -ne ${pathsBundled} -and ${pathsBundled}.Value) {
    Split-Path -Parent ${pathsBundled}.Value
} else {
    [System.IO.Path]::GetFullPath("${tebunkoRoot}\..\..\..")
}
Remove-Variable -Name pathsBundled -ErrorAction SilentlyContinue
# データ（設定ファイル・work）の置き場所は data_dir.ps1 で決める（ツールのフォルダに書き込めないことがあるため）

${utf8Bom} = New-Object System.Text.UTF8Encoding($true)
# ファイルの読み書き（行ファイル・原子的な書き込み・長いパス・排他）。


# ---- パスの状態（見つかった・見つからない・接続できない・その他） ----
#
# Test-Path・File.Exists・Directory.Exists は、届かない共有でも多くの場合に例外を出さず $false を返す
# （「見つからない」と区別できない）。getPathState は、例外を投げる呼び出し（File.GetAttributes）で調べる。

${pathStateFound}       = "Found"
${pathStateMissing}     = "Missing"
${pathStateUnreachable} = "Unreachable"
${pathStateOther}       = "Other"

# 接続できない（届かない共有・ネットワークの問題）を表す Win32 のエラー番号
# ERROR_BAD_NETPATH(53)・ERROR_BAD_NET_NAME(67)・ERROR_NETNAME_DELETED(64)・ERROR_SEM_TIMEOUT(121)・
# ERROR_NETWORK_UNREACHABLE(1231)・ERROR_HOST_UNREACHABLE(1232)・ERROR_NO_NET_OR_BAD_PATH(1222)
${unreachableWin32Codes} = @(53, 67, 64, 121, 1231, 1232, 1222)

# ---- クラウドにだけあるファイル（OneDrive・SharePoint などのオンデマンド） ----
#
# 一覧（Get-ChildItem）が返す属性だけで見分ける。ファイルを開かないので、ダウンロードは起きない。
#   RECALL_ON_DATA_ACCESS(0x400000)・RECALL_ON_OPEN(0x40000)・OFFLINE(0x1000) のどれかが付いていれば、
#   中身は手元に無い（開くとダウンロードされる）。
#   PINNED(0x80000)・UNPINNED(0x100000)・ReparsePoint だけでは、クラウドにだけあるとは言えない。

${attributeRecallOnDataAccess} = 0x400000
${attributeRecallOnOpen}       = 0x40000
${attributeOffline}            = 0x1000

function testCloudOnlyAttributes {
    # ファイルの属性（数値）が、中身が手元に無い（クラウドにだけある）ことを表すとき $true
    param (
        [int]$attributes
    )

    $mask = ${attributeRecallOnDataAccess} -bor ${attributeRecallOnOpen} -bor ${attributeOffline}
    return (($attributes -band $mask) -ne 0)
}

function readListFile {
    # 1行1件のファイルを読み込む（空行を除く）。ファイルが無ければ空配列。
    # 読めない（ほかが書き込み中など）ときは例外にする。呼び出し側の $ErrorActionPreference が既定の Continue でも
    # 空の一覧と取り違えないよう -ErrorAction Stop を付ける
    param (
        [string]$path
    )

    if (!(Test-Path -LiteralPath $path)) {
        return @()
    }
    return @(Get-Content -LiteralPath $path -Encoding UTF8 -ErrorAction Stop | Where-Object { $_.Trim() -ne "" })
}

function writeListFile {
    param (
        [string]$path,
        [string[]]$lines
    )

    if ($null -eq $lines) {
        $lines = [string[]]@()
    }
    [System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($path)) | Out-Null
    [System.IO.File]::WriteAllLines($path, $lines, ${utf8Bom})
}

function formatFileTime {
    # 取り込み一覧に記録する日時の書式（秒まで）。更新の有無はこの文字列で比べる
    param (
        [datetime]$time
    )

    return $time.ToString("yyyy/MM/dd HH:mm:ss", [System.Globalization.CultureInfo]::InvariantCulture)
}

function writeTextLinesAtomic {
    # 途中で中断してもファイルが壊れないよう、一時ファイルに書いてから置き換える
    param (
        [string]$path,
        [object[]]$lines,
        [System.Text.Encoding]$encoding = ${utf8Bom}  # 文字コード（既定は BOM 付き UTF-8）
    )

    [System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($path)) | Out-Null
    $tmpPath = "${path}.tmp"
    [System.IO.File]::WriteAllLines($tmpPath, [string[]]@($lines), $encoding)
    # 書いた直後のファイルは、ウイルス対策ソフト等が一時的に掴んでいて置き換えられないことがあるため、少し待って数回試す
    for ($i = 1; $true; $i++) {
        try {
            if (Test-Path -LiteralPath $path) {
                # $null は空文字列として渡されて例外になるため、[NullString]::Value（バックアップを作らない）を渡す
                [System.IO.File]::Replace($tmpPath, $path, [NullString]::Value)
            } else {
                [System.IO.File]::Move($tmpPath, $path)
            }
            return
        } catch {
            if ($i -ge 5) {
                throw
            }
            Start-Sleep -Milliseconds 200
        }
    }
}

function toSafeFileName {
    # ファイル名に使えない文字を全角に変換
    param (
        [string]$name
    )

    $name = $name.Replace(">", "＞")
    $name = $name.Replace("<", "＜")
    $name = $name.Replace("\", "￥")
    $name = $name.Replace("*", "＊")
    $name = $name.Replace('"', '”')
    $name = $name.Replace(":", "：")
    $name = $name.Replace("?", "？")
    $name = $name.Replace("|", "｜")
    $name = $name.Replace("/", "／")

    return $name
}


${maxFileNameLength} = 255  # Windows のファイル名（パスの区切りの間の1つ）の上限


function toLongPath {
    # パスの先頭に \\?\ を付け、260文字を超えるパスもファイル操作（System.IO・-LiteralPath）で扱えるようにする。
    # ネットワークのパス（\\server\share\…）は \\?\UNC\server\share\… にする。付いていればそのまま返す。
    # Join-Path は \\?\ 付きのパスを扱えないため、パスを組み立てた後、ファイル操作に渡す直前に使う
    param (
        [string]$path
    )

    if (!$path -or $path.StartsWith("\\?\")) {
        return $path
    }
    $path = $path.Replace("/", "\")
    if ($path.StartsWith("\\")) {
        return "\\?\UNC\" + $path.Substring(2)
    }
    return "\\?\" + $path
}

function copyFileShared {
    # 元のファイルに影響を出さずにコピーする（インデックス作成は、元のファイルでなくこのコピーを読んで行う）。
    # 書き込み中のファイルも、読み取りだけで開いてコピーできる（書きかけの中身が入ることは、直接読む場合と同じ）。
    # 排他で開かれたファイルはコピーできず、取り込みの失敗になる。
    # File.Copy は元のファイルをほかのアプリの書き込みを拒否して開くため、コピーの間は利用者が上書き保存できず、
    # 利用者がファイルを開いて編集中だとコピーできないことがある。
    # ここでは読み取りだけで開き、ほかのアプリの読み書き・削除・名前変更を妨げない。
    # コピー先は通常の属性（読み取り専用などを付けない）で作り、既にあれば上書きする
    param (
        [string]$sourcePath,
        [string]$destPath
    )

    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $source = New-Object System.IO.FileStream((toLongPath $sourcePath), [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    try {
        $dest = New-Object System.IO.FileStream((toLongPath $destPath), [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
        try {
            $source.CopyTo($dest, 1MB)
        } finally {
            $dest.Dispose()
        }
    } finally {
        $source.Dispose()
    }
}

function fromLongPath {
    # toLongPath で付けた \\?\ を外し、通常のパスに戻す（Get-ChildItem の FullName 等から相対パスを求めるため）
    param (
        [string]$path
    )

    if ($path.StartsWith("\\?\UNC\")) {
        return "\\" + $path.Substring(8)
    }
    if ($path.StartsWith("\\?\")) {
        return $path.Substring(4)
    }
    return $path
}

function trimTrailingSeparator {
    # パスの末尾の \ と / を落とす（リンクの判定・削除の入口で使う。念のため、末尾の区切りでリンクの先を見ることが無いようにする）。
    # 途中の区切りは変えない（\\?\ で始まらないパスの / は、あとで toLongPath が \ にそろえる。\\?\ で始まるパスの / はそのまま）。
    # 落とした結果が空か : で終わるパス（C:\ ・ \\?\C:\ ・ \ ・ / ）と、\\?\ だけのパスは、そのまま返す。
    # それ以外は、UNC の根（\\server\share\）や \\?\Volume{...}\ も、末尾を落とす
    param (
        [string]$path
    )

    if (!$path) {
        return $path
    }
    $trimmed = $path.TrimEnd([char[]]@("\", "/"))
    if (!$trimmed -or $trimmed.EndsWith(":") -or $trimmed -eq "\\?") {
        return $path
    }
    return $trimmed
}

function setNotContentIndexed {
    # フォルダ（またはファイル）に「内容のインデックスを作成しない」属性（NotContentIndexed）を付ける。
    # 既に付いているものには付け直さない（Changed に数えない）ので、ほかの属性（読み取り専用など）は変えない。
    #   Recurse 無し: path 自身と、フォルダなら直下のファイルに付ける（下のフォルダには付けない）
    #   Recurse あり: path 自身と、下のすべてのフォルダ・ファイルに付ける
    # Recurse でフォルダを渡したときは、根フォルダの属性を下より先に確かめる。既に付いていれば
    # （前回すべて付け終えて根に付けたということなので）下はたどらず、GetAttributes 1 回だけで終える。
    # 根の属性は、下をすべて付け終えて成功したときにだけ最後に付ける（列挙・付与の途中で失敗した回は
    # 根に付けない。次回もう一度下からたどり直せるようにするため）。
    # 1件ずつの失敗（アクセス拒否など）も、列挙そのものの失敗（無いパス・列挙の途中で読めなくなったフォルダなど）も
    # 例外にせず、@{ Ok; Changed; Reason }（最初に見つかった理由を Reason に）を返す。
    # 呼び出し元（インデックス作成）は、Ok が $false でも処理を止めず、ログに 1 行残すだけにする
    param (
        [string]$path,
        [switch]$Recurse
    )

    $flag = [System.IO.FileAttributes]::NotContentIndexed
    $state = getPathState $path
    if ($state.State -ne ${pathStateFound}) {
        $reason = if ($state.Message) { $state.Message } else { "パスが見つかりません（${path}）" }
        return @{ Ok = $false; Changed = 0; Reason = $reason }
    }

    $long = toLongPath $path
    $deferRoot = [bool]($Recurse -and $state.IsDirectory)
    if ($deferRoot) {
        try {
            $rootAttrs = [System.IO.File]::GetAttributes($long)
        } catch {
            return @{ Ok = $false; Changed = 0; Reason = $_.Exception.Message }
        }
        if ($rootAttrs -band $flag) {
            return @{ Ok = $true; Changed = 0; Reason = "" }
        }
    }

    # 先に対象（path 自身と、必要なら中身）をすべて列挙してから属性を付ける。deferRoot のときは
    # 根自身をここでは含めず、下だけを集める（根は下がすべて終わったあとに付ける）。
    # 列挙そのものが例外になったら（途中で消えた・読めないフォルダがあるなど）、途中まで集めた分は捨てて Ok=$false にする
    $items = New-Object System.Collections.Generic.List[object]
    if (!$deferRoot) {
        $items.Add(@{ Path = $path; IsDirectory = $state.IsDirectory })
    }
    try {
        if ($state.IsDirectory) {
            $dirInfo = New-Object System.IO.DirectoryInfo $long
            if ($Recurse) {
                foreach ($entry in $dirInfo.EnumerateFileSystemInfos("*", [System.IO.SearchOption]::AllDirectories)) {
                    $items.Add(@{ Path = (fromLongPath $entry.FullName); IsDirectory = ($entry -is [System.IO.DirectoryInfo]) })
                }
            } else {
                foreach ($file in $dirInfo.EnumerateFiles("*", [System.IO.SearchOption]::TopDirectoryOnly)) {
                    $items.Add(@{ Path = (fromLongPath $file.FullName); IsDirectory = $false })
                }
            }
        }
    } catch {
        return @{ Ok = $false; Changed = 0; Reason = $_.Exception.Message }
    }

    $changed = 0
    $ok = $true
    $reason = ""
    foreach ($item in $items) {
        try {
            # フォルダ・ファイルどちらも [System.IO.File]::Get/SetAttributes で扱う（Directory クラスには同名のメソッドが無い）
            $itemLong = toLongPath $item.Path
            $attrs = [System.IO.File]::GetAttributes($itemLong)
            if ($attrs -band $flag) {
                continue
            }
            [System.IO.File]::SetAttributes($itemLong, ($attrs -bor $flag))
            $changed++
        } catch {
            $ok = $false
            if (!$reason) {
                $reason = $_.Exception.Message
            }
        }
    }

    if ($deferRoot -and $ok) {
        try {
            [System.IO.File]::SetAttributes($long, ($rootAttrs -bor $flag))
            $changed++
        } catch {
            $ok = $false
            if (!$reason) {
                $reason = $_.Exception.Message
            }
        }
    }

    return @{ Ok = $ok; Changed = $changed; Reason = $reason }
}

function testNotContentIndexed {
    # path に「内容のインデックスを作成しない」属性（NotContentIndexed）が付いているかを返す。
    # 属性を確かめられなければ（パスが無い・アクセスできないなど）例外にせず $false を返す
    param (
        [string]$path
    )

    try {
        $attrs = [System.IO.File]::GetAttributes((toLongPath $path))
        return [bool]($attrs -band [System.IO.FileAttributes]::NotContentIndexed)
    } catch {
        return $false
    }
}

function removeDirectoryRetry {
    # フォルダを中身ごと削除する。ウイルス対策ソフト・エクスプローラーが一時的に掴んでいることがあるため、少し待って数回試す
    param (
        [string]$path,
        [int]$tries = 3,
        [int]$waitMilliseconds = 200
    )

    # 中に長いパス（260文字超）のファイルがあっても削除できるよう \\?\ 付きで削除する
    $longPath = toLongPath $path
    for ($i = 1; $true; $i++) {
        if (![System.IO.Directory]::Exists($longPath)) {
            return
        }
        try {
            # リンク（ジャンクション・シンボリックリンク）は辿らず、リンクそのものだけを外す（removeTreeNoFollow）。
            # 消せなければ例外になり、catch で試し直す
            removeTreeNoFollow $longPath
            return
        } catch {
            if ($i -ge $tries) {
                throw
            }
            Start-Sleep -Milliseconds $waitMilliseconds
        }
    }
}

function getLinkKind {
    # item（Get-Item・Get-ChildItem・DirectoryInfo などが返す FileSystemInfo）の種類を返す。
    #   Link    … ジャンクション・シンボリックリンク（属性に ReparsePoint が付き、LinkType がそのどちらか）
    #   Unknown … 属性が読めない、またはフォルダなのに ReparsePoint が付き LinkType がジャンクション・シンボリックリンクと確かめられない
    #             （OneDrive のオンデマンドの置き場のフォルダなど）。リンクかどうか分からないので、辿らず、消しもしない
    #   Plain   … それ以外（ReparsePoint の付いたファイルは、辿るものが無いので Plain）
    # 先に属性の ReparsePoint を見て、付いているときだけ LinkType を読む（多くのファイルで余計な問い合わせをしない）。
    # 5.1 ではプロパティを読んだときの例外は $null になる（catch に届かない）ため、$null を読めなかったものとして扱う
    param (
        $item
    )

    $attributes = $item.Attributes
    if ($null -eq $attributes) {
        return "Unknown"
    }
    if (!($attributes -band [System.IO.FileAttributes]::ReparsePoint)) {
        return "Plain"
    }
    $linkType = [string]$item.LinkType
    if ($linkType -eq "Junction" -or $linkType -eq "SymbolicLink") {
        return "Link"
    }
    if ($attributes -band [System.IO.FileAttributes]::Directory) {
        return "Unknown"
    }
    return "Plain"
}

function testLinkItem {
    # item が、辿ってはいけないもの（getLinkKind が Link か Unknown）なら $true
    param (
        $item
    )

    return ((getLinkKind $item) -ne "Plain")
}

function testPathIsLink {
    # path そのもの（途中の階層は見ない）がジャンクション・シンボリックリンクなら $true。
    # 無い・空のパスは $false（まだ作っていない）。属性が読めない、リンクかどうか確かめられないフォルダ（getLinkKind が Unknown）のときは $true（辿らない側に倒す）
    param (
        [string]$path
    )

    if (!$path) {
        return $false
    }
    $long = toLongPath (trimTrailingSeparator $path)
    try {
        $attributes = [System.IO.File]::GetAttributes($long)
    } catch [System.IO.FileNotFoundException] {
        return $false
    } catch [System.IO.DirectoryNotFoundException] {
        return $false
    } catch {
        return $true
    }
    if (!($attributes -band [System.IO.FileAttributes]::ReparsePoint)) {
        return $false
    }
    if ($attributes -band [System.IO.FileAttributes]::Directory) {
        return (testLinkItem (New-Object System.IO.DirectoryInfo $long))
    }
    return (testLinkItem (New-Object System.IO.FileInfo $long))
}

function testPathHasLink {
    # base の下の path まで、途中の各階層（path を含み、base とそれより上は含まない）に、リンクがあれば $true。
    # 利用者が選んだ置き場（base）そのものが別の場所へのリンクでも、構成を変えずに使えるよう、base は見ない。
    # path が base と同じなら $false。base の下になければ、確かめられないので $true
    param (
        [string]$base,
        [string]$path
    )

    try {
        $baseFull = [System.IO.Path]::GetFullPath((fromLongPath $base)).TrimEnd("\")
        $pathFull = [System.IO.Path]::GetFullPath((fromLongPath $path)).TrimEnd("\")
    } catch {
        return $true
    }
    if ($pathFull.Equals($baseFull, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $false
    }
    if (!$pathFull.StartsWith("$baseFull\", [System.StringComparison]::OrdinalIgnoreCase)) {
        return $true
    }
    $current = $baseFull
    foreach ($name in $pathFull.Substring($baseFull.Length + 1).Split("\")) {
        $current = "$current\$name"
        if (testPathIsLink $current) {
            return $true
        }
        if (!(Test-Path -LiteralPath (toLongPath $current))) {
            return $false  # ここから先はまだ無い
        }
    }
    return $false
}

function removeEntryOnly {
    # ファイル 1 つ・リンク（ジャンクション・シンボリックリンク）1 つ・空のフォルダ 1 つ（item は FileSystemInfo）を、そのものだけ消す。
    # リンクの先は消さない。読み取り専用の属性は外してから消す
    param (
        [System.IO.FileSystemInfo]$item
    )

    $path = $item.FullName
    $attributes = $item.Attributes
    if ($attributes -band [System.IO.FileAttributes]::ReadOnly) {
        # 読み取り専用だけを外す（ほかの属性は変えない）
        [System.IO.File]::SetAttributes($path, ($attributes -band (-bnot [System.IO.FileAttributes]::ReadOnly)))
    }
    if ($item -is [System.IO.DirectoryInfo]) {
        [System.IO.Directory]::Delete($path, $false)
    } else {
        [System.IO.File]::Delete($path)
    }
}

function removeTreeNoFollow {
    # フォルダを中身ごと削除する。ジャンクション・シンボリックリンクは辿らず、リンクそのものだけを外す（先は消さない）。
    # path そのものがリンクなら、そのリンクだけを外す。フォルダが無ければ何もしない。
    # 先に全体を数える（リンクは辿らない）。リンクかどうか確かめられないフォルダ（getLinkKind が Unknown）が 1 つでもあれば、
    # 降りず、何も消さずに例外にする。何も消さないと言えるのは、この数える段で見つけた Unknown のときだけ。
    # そのあとで、ファイル・リンク・フォルダ（下から順）を消す。
    # 降りる直前と、フォルダのファイルを消す直前に、そのフォルダがリンクでないかを確かめ直す。
    # 数えたあとにフォルダがリンクに替わっていたら例外にする。それまでに消した分は戻らない。
    # 消す直前に確かめ直すのは、そのフォルダ自身だけ。上の階層が途中で替わったときは見つけられない。
    # 読み取り専用の属性は外して消す（Remove-Item -Force と同じ働き）。消せなければ例外にする
    param (
        [string]$path
    )

    $long = toLongPath (trimTrailingSeparator $path)
    if (![System.IO.Directory]::Exists($long)) {
        return
    }
    $filesByDirectory = New-Object 'System.Collections.Generic.Dictionary[string,System.Collections.Generic.List[string]]'
    $links = New-Object System.Collections.Generic.List[string]
    $directories = New-Object System.Collections.Generic.List[string]
    $pending = New-Object System.Collections.Generic.Stack[string]
    $pending.Push($long)
    while ($pending.Count -gt 0) {
        $current = New-Object System.IO.DirectoryInfo ($pending.Pop())
        $currentKind = getLinkKind $current
        if ($currentKind -eq "Unknown") {
            throw "リンクかどうか確かめられないフォルダのため、消しませんでした: $(fromLongPath $current.FullName)"
        }
        if ($currentKind -eq "Link") {
            $links.Add($current.FullName)
            continue
        }
        $directories.Add($current.FullName)
        $filesByDirectory[$current.FullName] = New-Object System.Collections.Generic.List[string]
        foreach ($entry in @($current.EnumerateFileSystemInfos("*", [System.IO.SearchOption]::TopDirectoryOnly))) {
            if ($entry -isnot [System.IO.DirectoryInfo]) {
                $filesByDirectory[$current.FullName].Add($entry.FullName)
            } elseif ((getLinkKind $entry) -eq "Link") {
                $links.Add($entry.FullName)
            } else {
                # 確かめられないもの（Unknown）も積む。降りる直前の確かめで例外にする（列挙の途中では投げない）
                $pending.Push($entry.FullName)
            }
        }
    }
    foreach ($directory in $directories) {
        if ((getLinkKind (New-Object System.IO.DirectoryInfo $directory)) -ne "Plain") {
            throw "数えたあとでリンクに替わったフォルダのため、中のファイルを消しませんでした: $(fromLongPath $directory)"
        }
        foreach ($file in $filesByDirectory[$directory]) {
            removeEntryOnly (New-Object System.IO.FileInfo $file)
        }
    }
    foreach ($link in $links) {
        removeEntryOnly (New-Object System.IO.DirectoryInfo $link)
    }
    for ($i = $directories.Count - 1; $i -ge 0; $i--) {
        removeEntryOnly (New-Object System.IO.DirectoryInfo $directories[$i])
    }
}

function moveDirectoryRetry {
    # フォルダを移動する。removeDirectoryRetry と同じ理由（ウイルス対策ソフト・エクスプローラーが、
    # 作ったばかり・書いたばかりのフォルダを一時的に掴んでいることがある）で、待つ時間を倍にしながら数回試す
    # （削除より、掴まれている時間が長くかかることがあるため、既定の回数・最初の待ち時間を大きくしている）
    param (
        [string]$source,
        [string]$destination,
        [int]$tries = 5,
        [int]$waitMilliseconds = 200
    )

    $longSource = toLongPath $source
    $longDestination = toLongPath $destination
    $wait = $waitMilliseconds
    for ($i = 1; $true; $i++) {
        try {
            [System.IO.Directory]::Move($longSource, $longDestination)
            return
        } catch {
            if ($i -ge $tries) {
                throw
            }
            Start-Sleep -Milliseconds $wait
            $wait *= 2
        }
    }
}

function testAnyEntry {
    # 列挙（[System.IO.Directory]::EnumerateFiles などの結果）に、predicate が $true を返すもの（省略したら何でも）が
    # 1 つでもあるか。見つけたところで列挙をやめ、列挙子を必ず Dispose する。
    # foreach を break・return・throw で途中で抜けると列挙子が Dispose されず、調べていた下のフォルダを開いたまま残る。
    # GC されるまで、そのフォルダと上のフォルダを移動・削除できなくなる（Directory.Move がアクセス拒否になる）ため、
    # 途中でやめる列挙はこの関数を通す
    param (
        [System.Collections.IEnumerable]$entries,
        [scriptblock]$predicate
    )

    $enumerator = $entries.GetEnumerator()
    try {
        while ($enumerator.MoveNext()) {
            if ($null -eq $predicate -or (& $predicate $enumerator.Current)) {
                return $true
            }
        }
        return $false
    } finally {
        if ($enumerator -is [System.IDisposable]) {
            $enumerator.Dispose()
        }
    }
}

function selectFirstEntries {
    # 列挙（[System.IO.Directory]::EnumerateFileSystemEntries などの結果）の先頭から count 件までを配列にして返す。
    # count 件で列挙をやめ、列挙子を必ず Dispose する（testAnyEntry と同じ理由。Select-Object -First で途中でやめる形にしない）
    param (
        [System.Collections.IEnumerable]$entries,
        [int]$count
    )

    $list = New-Object System.Collections.Generic.List[object]
    $enumerator = $entries.GetEnumerator()
    try {
        while ($list.Count -lt $count -and $enumerator.MoveNext()) {
            $list.Add($enumerator.Current)
        }
    } finally {
        if ($enumerator -is [System.IDisposable]) {
            $enumerator.Dispose()
        }
    }
    return , $list.ToArray()
}

function getFolderKey {
    # フォルダのパスから、名前付きミューテックス・イベントの名前に使う鍵（16 進 64 文字）を作る。大文字と小文字は区別しない。
    # 安全性のためではなく、パスを名前に使える長さと文字にするためのハッシュ。
    # FIPS 準拠の実装（SHA256CryptoServiceProvider）を使う。MD5 や SHA256Managed は、
    # FIPS モードを有効にした Windows では作るときに例外になり、起動できなくなるため
    param (
        [string]$dir
    )

    $sha = New-Object System.Security.Cryptography.SHA256CryptoServiceProvider
    try {
        return [BitConverter]::ToString($sha.ComputeHash([System.Text.Encoding]::UTF8.GetBytes($dir.ToLowerInvariant()))).Replace("-", "")
    } finally {
        $sha.Dispose()
    }
}

function newAppMutex {
    # 同じツール（配置フォルダ）の処理を二重に動かさないための名前付きミューテックスを作り、@{ Mutex; Acquired } を返す。
    # Acquired が $false なら、ほかで実行中。プロセスが終われば解放されるため、強制終了されても残らない
    #   name: 処理の種類（"gui" = 画面、"indexer" = インデックス作成）
    param (
        [string]$name,
        [string]$dir = ${rootDir}
    )

    $key = getFolderKey $dir
    $createdNew = $false
    $mutex = New-Object System.Threading.Mutex($true, "Local\${appId}_${name}_${key}", [ref]$createdNew)
    return @{ Mutex = $mutex; Acquired = $createdNew }
}

function getPathErrorKind {
    # File.GetAttributes などが投げた例外（PowerShell から呼ぶと MethodInvocationException に包まれる）を、
    # 見つからない（FileNotFoundException・DirectoryNotFoundException）・接続できない（Win32 のエラー番号）・
    # その他（アクセス拒否・ログオンの失敗など上のどれにも当たらないもの）に分ける。純粋な関数（例外を受け取って値を返すだけ）
    param (
        $exception  # System.Exception（MethodInvocationException でもそのままでもよい）
    )

    $inner = $exception
    while ($inner -is [System.Management.Automation.MethodInvocationException] -and $null -ne $inner.InnerException) {
        $inner = $inner.InnerException
    }
    if ($inner -is [System.IO.FileNotFoundException] -or $inner -is [System.IO.DirectoryNotFoundException]) {
        return ${pathStateMissing}
    }
    $code = $inner.HResult -band 0xFFFF
    if (${unreachableWin32Codes} -contains $code) {
        return ${pathStateUnreachable}
    }
    return ${pathStateOther}
}

function getPathState {
    # パスの状態を、例外を投げる呼び出し（File.GetAttributes）で調べる。260 文字を超えるパスも扱えるよう \\?\ を付けて渡す。
    # 返すもの: @{ State（上の定数）; IsDirectory; Message（見つかったとき以外の例外の文面） }
    param (
        [string]$path
    )

    try {
        $attributes = [System.IO.File]::GetAttributes((toLongPath $path))
        return @{ State = ${pathStateFound}; IsDirectory = [bool]($attributes -band [System.IO.FileAttributes]::Directory); Message = "" }
    } catch {
        return @{ State = (getPathErrorKind $_.Exception); IsDirectory = $false; Message = $_.Exception.Message }
    }
}

function invokeWithNamedMutex {
    # 名前付きミューテックスを取って action を実行し、action の出力を返す（終わったら必ず手放す）。
    # 同じスレッドの入れ子は通す（ミューテックスは同じスレッドなら再び取れる）。
    # timeoutMilliseconds を過ぎても取れなければ、「排他の待ちが時間切れになりました」の例外にする。
    # 前の持ち主が手放さずに終わっていた（abandoned）ときは、取れたものとして続ける
    #   mutexName: ミューテックスの名前（呼ぶ側が決める。同じ名前どうしで排他する）。
    #   action から呼び出し元の変数を参照できるよう、この関数の変数の名前は目立つものにしてある（name・key・path などは使わない）
    param (
        [string]$mutexName,
        [int]$timeoutMilliseconds,
        [scriptblock]$action
    )

    $mutex = New-Object System.Threading.Mutex($false, $mutexName)
    try {
        $acquired = $false
        try {
            $acquired = $mutex.WaitOne($timeoutMilliseconds)
        } catch {
            # PowerShell では MethodInvocationException に包まれて届く。abandoned でも所有は移っている
            $inner = $_.Exception
            while ($null -ne $inner -and $inner -isnot [System.Threading.AbandonedMutexException]) {
                $inner = $inner.InnerException
            }
            if ($null -eq $inner) {
                throw
            }
            $acquired = $true
        }
        if (!$acquired) {
            throw "排他の待ちが時間切れになりました（${timeoutMilliseconds} ミリ秒。${mutexName}）。ほかの処理が終わってからやり直してください。"
        }
        try {
            & $action
        } finally {
            $mutex.ReleaseMutex()
        }
    } finally {
        $mutex.Dispose()
    }
}

# スレッドのプール（WorkerPool）。ランスペースと PowerShell のインスタンスを使い回し、仕事のたびに作って捨てない。
# 設計は docs/design/structure/threads.md「寿命」、docs/design/structure/classes.md「クラスと関数の使い分け」。
#
# WorkerPool は、作ったランスペースのスレッドだけから呼ぶ（PowerShell 5.1 のクラスのメソッドは、クラスを定義したランスペースで動くため）。
# 仕事のスクリプトは文字列で渡す（スクリプトブロックのまま渡すと、作ったランスペースに結び付いたまま別のスレッドで動いてしまう）。

function newWorkerState {
    # プールの各スレッドに読み込む関数・値だけを入れた InitialSessionState を作る
    # （lib.ps1 全体を読み込むと、スレッドを用意するだけで時間がかかるため）
    param (
        [string[]]$functions = @(),
        [string[]]$variables = @()
    )

    $state = [System.Management.Automation.Runspaces.InitialSessionState]::CreateDefault2()
    foreach ($name in $functions) {
        $state.Commands.Add([System.Management.Automation.Runspaces.SessionStateFunctionEntry]::new($name, (Get-Command $name -CommandType Function).Definition))
    }
    foreach ($name in $variables) {
        $state.Variables.Add([System.Management.Automation.Runspaces.SessionStateVariableEntry]::new($name, (Get-Variable $name -ValueOnly), ""))
    }
    return $state
}

function joinWorkerScript {
    # 部品の読み込み（Prelude）を、本体のスクリプト（script）につなぐ。呼び出し側の書き換えをせず、
    # 意味を変えない形でつなぐため、挿入する場所は本体の構文解析で決める:
    #   param ブロックがあればその直後、続けて最初の文が `$ErrorActionPreference = "Stop"` ならそのあとにも進める
    #   （部品が読めないときにスレッドを終える今の動きを保つため。tests/shared/core/worker_pool.Tests.ps1 が確かめる）。
    # Prelude は、同じランスペースで仕事のたびに呼ばれても 1 回だけ実行する（$global:workerPreludeDone で守る。
    # ランスペースを使い回さない呼び出し元でも害はない）
    param (
        [string]$prelude,
        [string]$script
    )

    $tokens = $null
    $errors = $null
    $ast = [System.Management.Automation.Language.Parser]::ParseInput($script, [ref]$tokens, [ref]$errors)
    if ($errors.Count -gt 0) {
        throw "joinWorkerScript: つなぐ本体の構文エラーです: $($errors[0].Message)"
    }
    $insertAt = if ($ast.ParamBlock) { $ast.ParamBlock.Extent.EndOffset } else { 0 }
    $statements = @($ast.EndBlock.Statements)
    if ($statements.Count -gt 0 -and $statements[0].Extent.Text -match '^\$ErrorActionPreference\s*=\s*"Stop"$') {
        $insertAt = $statements[0].Extent.EndOffset
    }
    $head = $script.Substring(0, $insertAt)
    $tail = $script.Substring($insertAt)
    $guarded = "`r`nif (!`$global:workerPreludeDone) {`r`n$prelude`r`n`$global:workerPreludeDone = `$true`r`n}"
    return "$head$guarded$tail"
}

function getWorkerCount {
    # プールのスレッドの数の既定（画面のために 1 コアを残す。1～max）
    param (
        [int]$max = 4,
        [int]$processors = [Environment]::ProcessorCount
    )

    return [Math]::Max(1, [Math]::Min($processors - 1, $max))
}

class WorkerPool {
    # スレッドの数
    [int]$Size
    # 各スレッドの優先度（Normal・BelowNormal など）。仕事を始めるたびに、そのスレッドに設定する
    [string]$Priority
    # 各スレッドで、最初の仕事の前に 1 回だけ実行するスクリプト（lib.ps1 の読み込みなど）。ランスペースの全体（global）で実行する
    [string]$Prelude = ""
    hidden [System.Management.Automation.Runspaces.RunspacePool]$Pool
    # 使い終わって空いている PowerShell のインスタンス
    hidden [System.Collections.Generic.Stack[powershell]]$Idle

    WorkerPool([int]$size, [System.Management.Automation.Runspaces.InitialSessionState]$state, [System.Management.Automation.Host.PSHost]$hostUi, [string]$priority) {
        $this.Size = [Math]::Max(1, $size)
        $this.Priority = [string][System.Threading.ThreadPriority]$priority
        $this.Idle = New-Object 'System.Collections.Generic.Stack[powershell]'
        # host は省けない（$null は受け付けない）。渡されなければ、このランスペースのものを使う
        if ($null -eq $hostUi) {
            $hostUi = Get-Host
        }
        $this.Pool = [runspacefactory]::CreateRunspacePool(1, $this.Size, $state, $hostUi)
        # 既定では仕事のたびに新しいスレッドを作る。ランスペースごとに 1 つのスレッドを使い続ける
        $this.Pool.ThreadOptions = [System.Management.Automation.Runspaces.PSThreadOptions]::ReuseThread
        $this.Pool.Open()
    }

    [hashtable] Submit([string]$script, [object[]]$arguments) {
        # 仕事を 1 つ始め、@{ PowerShell; Handle } を返す（Receive・Cancel に渡す）
        if ($null -eq $this.Pool) {
            throw "WorkerPool は閉じています。"
        }
        if ($this.Idle.Count -gt 0) {
            $ps = $this.Idle.Pop()
        } else {
            $ps = [powershell]::Create()
            $ps.RunspacePool = $this.Pool
        }
        # 優先度を設定してから仕事のスクリプトを呼ぶ（AddStatement で文を分けると、引数付きのスクリプトが終わらなくなるため、1 つのスクリプトにする）
        $text = "[System.Threading.Thread]::CurrentThread.Priority = '$($this.Priority)'`r`n"
        $body = "& {`r`n$script`r`n} @args"
        if ($this.Prelude) {
            # if の中は新しいスコープにならないため、prelude で読み込んだ関数はランスペースに残り、次の仕事でも使える
            $body = joinWorkerScript $this.Prelude $body
        }
        [void]$ps.AddScript("$text$body")
        foreach ($argument in $arguments) {
            [void]$ps.AddArgument($argument)
        }
        return @{ PowerShell = $ps; Handle = $ps.BeginInvoke() }
    }

    [object] Receive([hashtable]$job) {
        # 仕事の終わりを待って出力を返す。PowerShell のインスタンスは次の仕事に使い回す。仕事の例外はそのまま投げる
        $ps = $job.PowerShell
        try {
            $output = $ps.EndInvoke($job.Handle)
        } catch {
            $ps.Dispose()
            throw
        }
        $ps.Commands.Clear()
        $ps.Streams.ClearStreams()
        $this.Idle.Push($ps)
        # クラスのメソッドは戻り値を展開しない（PSDataCollection のまま返る）
        return $output
    }

    [void] Cancel([hashtable]$job) {
        # 仕事を止めて捨てる（止めたインスタンスは使い回さない）
        try {
            $job.PowerShell.Stop()
        } catch {
        }
        $job.PowerShell.Dispose()
    }

    [void] Close() {
        # スレッドを止めて片づける。何度呼んでもよい
        while ($this.Idle.Count -gt 0) {
            $this.Idle.Pop().Dispose()
        }
        if ($this.Pool) {
            $this.Pool.Dispose()
            $this.Pool = $null
        }
    }
}

class BackgroundQueue {
    # 画面から頼まれる短い仕事（プレビューの読み込み・状態の読み直し・プロセスの一覧など）を、使い回すスレッドで実行する。
    # 各スレッドでは、最初の仕事の前に 1 回だけ prelude（lib.ps1 の読み込みなど）を実行する（仕事のたびに読み込まない）。
    # 終わった仕事は Poll（画面のタイマー）で受け取り、画面のスレッドで onDone { param($output, $errorText) } を呼ぶ。
    # 画面のスレッドだけから呼ぶ
    hidden [WorkerPool]$Pool
    hidden [System.Collections.Generic.List[hashtable]]$Jobs

    BackgroundQueue([int]$size, [hashtable]$load, [System.Management.Automation.Host.PSHost]$hostUi) {
        # load は部品の読み込み口が返す @{ State; Prelude }。呼び出し元が Prelude に続けて
        # 呼びたい文を足したいときは、渡す前に $load.Prelude を書き換える
        $this.Jobs = New-Object 'System.Collections.Generic.List[hashtable]'
        $this.Pool = [WorkerPool]::new($size, $load.State, $hostUi, "Normal")
        $this.Pool.Prelude = $load.Prelude
    }

    [void] Post([string]$script, [object[]]$arguments, [scriptblock]$onDone) {
        # 仕事を 1 つ始める（スレッドが空いていなければ、空くのを待ってから始まる）
        $job = $this.Pool.Submit($script, $arguments)
        $job.OnDone = $onDone
        $this.Jobs.Add($job)
    }

    [int] Poll() {
        # 終わった仕事の onDone を呼び、まだ終わっていない仕事の数を返す
        foreach ($job in $this.Jobs.ToArray()) {
            if (!$job.Handle.IsCompleted) {
                continue
            }
            [void]$this.Jobs.Remove($job)
            $output = $null
            $errorText = $null
            try {
                if ($job.PowerShell.Streams.Error.Count -gt 0) {
                    $errorText = $job.PowerShell.Streams.Error[0].ToString()
                }
                $output = $this.Pool.Receive($job)
            } catch {
                # EndInvoke の呼び出しの例外に包まれているため、仕事が投げた元の例外の文面にする
                $exception = $_.Exception
                while ($exception.InnerException) {
                    $exception = $exception.InnerException
                }
                $errorText = $exception.Message
            }
            if ($job.OnDone) {
                & $job.OnDone $output $errorText
            }
        }
        return $this.Jobs.Count
    }

    [void] Close() {
        # 終わっていない仕事を止め、スレッドを片づける。何度呼んでもよい
        foreach ($job in $this.Jobs.ToArray()) {
            $this.Pool.Cancel($job)
        }
        $this.Jobs.Clear()
        $this.Pool.Close()
    }

    [void] Abandon() {
        # 画面を閉じるときだけに使う。Close と違い、止まった仕事（OS の呼び出しで戻らない届かない共有など）を待たずに戻る。
        # 終わった仕事は Close と同じく片づける（待たされないため）。終わっていない仕事には止める依頼（BeginStop）だけを出し、
        # その PowerShell のインスタンスと、この列のプール（RunspacePool）は Dispose しない
        # （PowerShell.Dispose() は動いている間は中で Stop を呼んで待ち、RunspacePool.Dispose() も止まったランスペースを待つため）。
        # 後始末はプロセスの終わりに任せる
        foreach ($job in $this.Jobs.ToArray()) {
            if ($job.Handle.IsCompleted) {
                try {
                    [void]$this.Pool.Receive($job)
                } catch {
                }
            } else {
                try {
                    [void]$job.PowerShell.BeginStop($null, $null)
                } catch {
                }
            }
        }
        $this.Jobs.Clear()
    }
}
# データ（設定ファイル）の置き場所の既定（どのツールからも使う）。
# ツールのフォルダに書き込めればそこに置く。書き込めないとき（Program Files・読み取り専用の共有フォルダに置いたとき）は、
# ツールが渡した逃げ先に置く（逃げ先はツールが決める。tebunko は既定のワークスペース）。
# work の置き場所は、ツールの側で決める（tebunko は設定の workspaceFolder）。

function testWritableFolder {
    # フォルダにファイルを作れるか。試しに作ったファイルは閉じると消える（DeleteOnClose）。フォルダが無ければ $false
    param (
        [string]$dir
    )

    if ([string]::IsNullOrWhiteSpace($dir) -or -not [System.IO.Directory]::Exists($dir)) {
        return $false
    }
    $probe = Join-Path $dir (".tebunko_write_test_" + [guid]::NewGuid().ToString("N") + ".tmp")
    try {
        $stream = New-Object System.IO.FileStream($probe, [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write,
            [System.IO.FileShare]::None, 1, [System.IO.FileOptions]::DeleteOnClose)
        $stream.Dispose()
        return $true
    } catch {
        return $false
    }
}

function getDataDir {
    # 設定ファイルを置くフォルダを返す。ツールのフォルダに書き込めればそれ、書き込めなければ渡された逃げ先。
    # 逃げ先の既定値は持たない（shared はツールの既定の置き場所を知らない）
    param (
        [string]$root = ${rootDir},
        [Parameter(Mandatory = $true)]
        [string]$fallbackDir
    )

    if (testWritableFolder $root) {
        return $root
    }
    return $fallbackDir
}

# TSV とセルの文字列を扱う（判断層。ファイルに触らない）。

# インデックスのTSVで、セル内改行の代わりに使う文字（U+2028 LINE SEPARATOR）。
# TSVの1行 = Excelの1行を保つため、セル内改行はこの文字に置き換えて保存し、検索結果の出力時に改行へ戻す
${cellNewLine} = [string][char]0x2028

function replaceCellNewLine {
    # ダブルクォートで囲まれた1セル内の改行（LF・CR・CRLF）を、セル内改行を表す文字に置き換える
    param (
        [string]$inputString
    )

    # "" はクォート内のダブルクォートのエスケープだが、"…" "…" の2つに分けてマッチしても結果は同じ
    return [regex]::Replace($inputString, '"[^"]*"', { param($m) $m.Value -replace "\r\n|\r|\n", ${cellNewLine} })
}

function formatTsv {
    # Excelが出力したTSVを、1行目 = Excelの1行目、1列目 = A列 となるように整形する。
    # Excelは使用範囲（UsedRange）の左上のセルから出力するため、その行・列番号を firstRow・firstColumn に渡す。
    # セル内改行は置き換え、行末の空セルと末尾の空行は取り除く（途中の空行は行番号を保つため残す）。
    # 空白以外の文字が無ければ空文字を返す
    param (
        [string]$content,
        [int]$firstRow = 1,
        [int]$firstColumn = 1
    )

    $content = replaceCellNewLine $content
    $columnPadding = "`t" * ($firstColumn - 1)

    $lines = New-Object System.Collections.Generic.List[string]
    for ($i = 1; $i -lt $firstRow; $i++) {
        $lines.Add("")
    }
    foreach ($line in ($content -split "\r?\n")) {
        $lines.Add(($columnPadding + $line).TrimEnd("`t"))
    }
    while ($lines.Count -gt 0 -and $lines[$lines.Count - 1].Trim() -eq "") {
        $lines.RemoveAt($lines.Count - 1)
    }

    return ($lines -join "`r`n")
}

function countTsvFields {
    # TSVの1行をExcelに貼り付けたときのセル数を返す。
    # Excelと同じく、" で始まるセルは閉じる " までを1セルとする（中のタブ・改行は区切りとしない）
    param (
        [string]$line
    )

    # 先頭にタブを足し、どのセルも「タブ＋中身」で数える（^ を使うと、先頭の空のセルの後のタブを読み飛ばして1セル少なくなる）
    return [regex]::Matches("`t${line}", '\t(?:"(?:[^"]|"")*"[^\t]*|[^\t]*)').Count
}

function toColumnName {
    # 列番号を列名に変換する（1 → A、27 → AA）
    param (
        [int]$number
    )

    $name = ""
    while ($number -gt 0) {
        $number--
        $name = [string][char](65 + ($number % 26)) + $name
        $number = [math]::Floor($number / 26)
    }
    return $name
}


function splitTsvCells {
    # TSVの1行をセルに分ける。" で始まるセルは閉じる " までを1セルとし、囲みの " を外して "" を " に戻す（countTsvFields と同じ区切り方）
    param (
        [string]$line
    )

    $cells = New-Object System.Collections.Generic.List[string]
    foreach ($match in [regex]::Matches("`t${line}", '\t(?:"(?:[^"]|"")*"[^\t]*|[^\t]*)')) {
        $cell = $match.Value.Substring(1)
        if ($cell -match '^"(?<inner>(?:[^"]|"")*)"(?<rest>.*)$') {
            $cell = $Matches.inner.Replace('""', '"') + $Matches.rest
        }
        $cells.Add($cell)
    }
    return , $cells.ToArray()
}

function testTextTrimmed {
    # 文字が枠に入りきらず、省略（…）で切れているか。実際の幅（枠の ActualWidth）より、要る幅（文字を 1 行で出すのに要る幅）が
    # 誤差より大きいときだけ $true。幅 0 以下（まだ配置されていない・隠れている）は切れていないものとして $false。
    # 測る側（画面層）は幅を渡すだけで、切れているかの判定はここで決める
    param (
        [double]$actualWidth,
        [double]$requiredWidth,
        [double]$tolerance = 0.5   # 測り方による小数の誤差（これ以下の超過は切れていないとみなす）
    )

    if ($actualWidth -le 0) {
        return $false
    }
    return (($requiredWidth - $actualWidth) -gt $tolerance)
}

# テキストファイル（.txt など）の対象の拡張子・文字コードの判定・読み込み。
# 文字コードの判定（バイト列 → 文字コードまたはバイナリ）は、画面にもファイルにも触らない判断層の関数にする。
# ファイルを開いて読む関数（readTextFile）だけが状態層（ファイルに触る）。

# 既定のアプリで開く、取り込み対象のテキストファイルの拡張子（小文字）。
# 足す・減らすと tests\meta\safety.Tests.ps1 が固定の一覧で確かめる
${textOpenExtensions} = @(
    ".txt", ".csv", ".tsv", ".md", ".log", ".json", ".xml",
    ".c", ".h", ".cpp", ".cc", ".cxx", ".hpp", ".cs", ".java", ".kt", ".kts",
    ".go", ".rs", ".swift", ".scala", ".dart", ".vb", ".bas", ".pas", ".asm",
    ".m", ".r", ".jl", ".hs", ".ex", ".exs", ".erl", ".clj", ".groovy", ".lua",
    ".py", ".rb", ".pl", ".php", ".psm1", ".psd1", ".jsx", ".tsx", ".mjs", ".vue",
    ".sql", ".yaml", ".yml", ".toml", ".ini", ".cfg", ".conf", ".properties",
    ".gradle", ".cmake", ".proto", ".graphql", ".tf",
    ".html", ".htm", ".css", ".scss", ".less", ".rst", ".tex", ".diff", ".patch"
)

# 実行・登録が既定の動作になるため、既定のアプリではなくメモ帳で開く、取り込み対象のテキストファイルの拡張子（小文字）。
# ${textOpenExtensions} と合わせて ${textExtensions} になる。足す・減らすと tests\meta\safety.Tests.ps1 が固定の一覧で確かめる
${textNotepadExtensions} = @(".bat", ".cmd", ".ps1", ".vbs", ".js", ".reg", ".sh")

# 取り込み対象にするテキストファイルの拡張子（小文字。上の 2 つを合わせたもの）
${textExtensions} = @(${textOpenExtensions}) + @(${textNotepadExtensions})

# 元のファイルがこの大きさ（バイト）を超えたら、読まずに失敗にする
${textFileMaxBytes} = 10MB

# BOM の無い UTF-16 の判定に使う閾値（docs/design/indexing/text.md）。
#   先頭 ${textUtf16SampleBytes} バイト（偶数バイトに切り詰める）を 2 バイトずつの組として数え、
#   偶数の位置・奇数の位置のどちらかの NUL の割合が ${textUtf16NulRatioThreshold} 以上で、
#   もう片方が「多い側 ÷ ${textUtf16NulSkewDivisor}」以下なら UTF-16 と判定する
${textUtf16SampleBytes}      = 64KB
${textUtf16NulRatioThreshold} = 0.2
${textUtf16NulSkewDivisor}    = 10

# NUL の無い BOM 無し UTF-16（日本語だけの文章）の判定に使う閾値（docs/design/indexing/text.md）。
#   先頭 ${textUtf16SampleBytes} バイトを UTF-16 として読み、ひらがな・カタカナが ${textJpUtf16KanaRatio} 以上あり、
#   日本語の文章に出る文字（ASCII・句読点・かな・漢字・全角）以外が ${textJpUtf16OtherRatio} 以下なら UTF-16 と判定する
${textJpUtf16MinBytes}   = 8
${textJpUtf16KanaRatio}  = 0.2
${textJpUtf16OtherRatio} = 0.05

# 7 ビットだけ（ASCII の範囲）のバイト列は、ひらがなの UTF-16 と ASCII の文字列の見分けが付きにくいため、
# UTF-16 とみなすかなの割合をもっと高く求める
${textJpUtf16AsciiKanaRatio} = 0.9

# Shift_JIS として読めたとき、半角カナが「ASCII 以外の文字」のこの割合を超えると、半角カナの並びとして自然かを確かめる
# （濁点・半濁点が付けられるカナの後にしか来ないか。GBK・Big5 などを Shift_JIS として読むと崩れる）。
# EUC-JP としても読めるときは、この割合を超える側を EUC-JP とする
${textLegacyHalfKanaRatio} = 0.3

# 半角カナの数えは、読んだ結果の先頭からこの文字数だけ見る（大きなファイルで遅くならないため）
${textLegacySampleChars} = 32768

function testTextExtension {
    # ファイル名（またはパス）の拡張子が、取り込み対象のテキストの拡張子か（大文字・小文字を区別しない）
    param (
        [string]$path
    )

    $extension = [System.IO.Path]::GetExtension($path).ToLowerInvariant()
    return (${textExtensions} -contains $extension)
}

function testTextOpenWithNotepad {
    # ファイル名（またはパス）の拡張子が、既定のアプリではなくメモ帳で開くテキストの拡張子か（大文字・小文字を区別しない）。
    # .bat・.ps1・.js など、既定のアプリで開くと実行・登録になる拡張子がこちら
    param (
        [string]$path
    )

    $extension = [System.IO.Path]::GetExtension($path).ToLowerInvariant()
    return (${textNotepadExtensions} -contains $extension)
}

function getStrictUtf8Encoding {
    # 不正なバイト列（UTF-8として読めない並び）で例外にする UTF-8 のデコーダー（BOM は付けない）
    return [System.Text.Encoding]::GetEncoding("utf-8",
        [System.Text.EncoderExceptionFallback]::new(), [System.Text.DecoderExceptionFallback]::new())
}

function testTextPlausible {
    # 読んだ結果の文字列が、テキストとして自然か。制御文字（TAB・LF・FF・CR 以外）・私用領域・置き換え文字（U+FFFD）を含めば偽。
    # バイナリを Shift_JIS・EUC-JP などとして読んでしまったものを見分ける（Shift_JIS の外字（F040～F9FC）は私用領域に読まれるため偽になる）
    param (
        [string]$text
    )

    return (-not [regex]::IsMatch($text, '[\x00-\x08\x0B\x0E-\x1F\x7F-\x9F\uE000-\uF8FF\uFFFD]'))
}

function tryDecodeStrict {
    # コードページで読めないバイト列があれば $null、読めれば文字列
    param (
        [byte[]]$bytes,
        [int]$codePage
    )

    try {
        $encoding = [System.Text.Encoding]::GetEncoding($codePage,
            [System.Text.EncoderExceptionFallback]::new(), [System.Text.DecoderExceptionFallback]::new())
        return $encoding.GetString($bytes)
    } catch [System.Text.DecoderFallbackException] {
        return $null
    } catch [System.ArgumentException] {
        return $null
    }
}

function detectJapaneseUtf16WithoutNul {
    # NUL の無い（または NUL が改行の分しか無い）BOM 無し UTF-16（日本語だけの文章）の判定。
    # ひらがな・カタカナ・漢字は NUL を含まない。LE・BE の片方だけが日本語の文章として自然なときにその文字コードを返す。
    # 両方・どちらも当たらなければ $null。7 ビットだけのバイト列は、かなの割合をもっと高く求める（${textJpUtf16AsciiKanaRatio}）
    param (
        [byte[]]$bytes
    )

    $sampleLength = [Math]::Min($bytes.Length, [int]${textUtf16SampleBytes})
    $sampleLength -= ($sampleLength % 2)
    if ($sampleLength -lt ${textJpUtf16MinBytes}) { return $null }

    $ascii = $true
    for ($i = 0; $i -lt $sampleLength; $i++) {
        if ($bytes[$i] -ge 0x80) { $ascii = $false; break }
    }
    $kanaRatio = if ($ascii) { ${textJpUtf16AsciiKanaRatio} } else { ${textJpUtf16KanaRatio} }

    $found = @()
    foreach ($candidate in @(@("UTF16LE", [System.Text.Encoding]::Unicode), @("UTF16BE", [System.Text.Encoding]::BigEndianUnicode))) {
        $text = $candidate[1].GetString($bytes, 0, $sampleLength)
        $kana = [regex]::Matches($text, '[\u3040-\u30FF]').Count
        $other = [regex]::Matches($text, '[^\u0009\u000A\u000D -~\u3000-\u30FF\u4E00-\u9FFF\uFF00-\uFFEF]').Count
        if ($kana -ge ($text.Length * $kanaRatio) -and $other -le ($text.Length * ${textJpUtf16OtherRatio})) {
            $found += $candidate[0]
        }
    }
    if ($found.Count -eq 1) { return $found[0] }
    return $null
}

function getIso2022JpVerdict {
    # ISO-2022-JP（JIS）かの判定。戻り値: "yes" / "broken" / "none"
    #   yes: 7 ビットだけで、漢字への切り替え（ESC $ B・ESC $ @）を含み、ESC の並びがすべて規格のもの（ESC ( B・ESC ( J・ESC ( I を含む）
    #   broken: 漢字への切り替えを含むが、8 ビットのバイトや規格外の ESC の並びがある（JIS のつもりの壊れたもの。UTF-8 として読むと化けるので取り込まない）
    #   none: ESC が無い、または漢字への切り替えが無い（ESC ( B だけ・ESC [ などの端末の制御の並び）
    param (
        [byte[]]$bytes
    )

    if ([Array]::IndexOf($bytes, [byte]0x1B) -lt 0) { return "none" }
    # 1 バイトを 1 文字に読み（Latin-1）、正規表現で確かめる（バイトを 1 つずつ回さない。色つきのログなど ESC が多いだけのファイルを速く抜ける）
    $latin1 = [System.Text.Encoding]::GetEncoding(28591).GetString($bytes)
    if (-not [regex]::IsMatch($latin1, '\x1B\$[B@]')) { return "none" }
    # 規格外の ESC の並び（末尾で切れたものを含む）か、8 ビットのバイトがあれば、壊れたもの
    $broken = [regex]::IsMatch($latin1, '\x1B(?!\$[B@]|\([BJI])') -or [regex]::IsMatch($latin1, '[\x80-\xFF]')
    if ($broken) { return "broken" }
    return "yes"
}

function testHalfWidthKanaNatural {
    # 半角カナを多く含む文字列が、半角カナの並びとして自然か。濁点（ﾞ）・半濁点（ﾟ）は、付けられるカナ
    # （ｦ ｳ ｶ～ﾄ ﾊ～ﾎ ﾜ。半濁点は ﾊ～ﾎ）の直後にしか来ない。GBK・Big5 などを Shift_JIS として読むと崩れる
    param (
        [string]$text
    )

    if ([regex]::IsMatch($text, '(?<![\uFF66\uFF73\uFF76-\uFF84\uFF8A-\uFF8E\uFF9C])\uFF9E')) { return $false }
    if ([regex]::IsMatch($text, '(?<![\uFF8A-\uFF8E])\uFF9F')) { return $false }
    return $true
}

function detectLegacyJapaneseEncoding {
    # UTF-8 として読めなかった NUL の無いバイト列が、Shift_JIS か EUC-JP か。決められなければ $null（取り込まない）。
    #   Shift_JIS: コードページ 932 として不正なバイト列が無く、制御文字などが出ない。半角カナが多い（${textLegacyHalfKanaRatio} 超）ときは、
    #              半角カナの並びとして自然（testHalfWidthKanaNatural）なものだけ
    #   EUC-JP: コードページ 51932 として不正なバイト列が無く、制御文字などが出ず、ひらがな・カタカナを含む
    #           （かなの無い漢字だけの文章は、GBK・EUC-KR と構造が同じで見分けが付かない）
    #   両方に当たるときは、Shift_JIS として読むと半角カナばかりになる（EUC-JP のかなの見え方）なら EUC-JP、そうでなければあいまいなので $null
    param (
        [byte[]]$bytes
    )

    $sjis = tryDecodeStrict $bytes 932
    $sjisOk = $false
    $sjisHalfKanaHeavy = $false
    if ($null -ne $sjis -and (testTextPlausible $sjis)) {
        # 半角カナの数えは、最初の ASCII 以外の文字から一定の長さだけ（先頭が長い ASCII だけの行でも判定が変わらないように）
        $first = [regex]::Match($sjis, '[^\u0000-\u007F]').Index
        $sample = if ($sjis.Length - $first -gt ${textLegacySampleChars}) { $sjis.Substring($first, [int]${textLegacySampleChars}) } else { $sjis.Substring($first) }
        $nonAscii = [regex]::Matches($sample, '[^\u0000-\u007F]').Count
        $halfKana = [regex]::Matches($sample, '[\uFF61-\uFF9F]').Count
        $sjisHalfKanaHeavy = ($halfKana -gt ($nonAscii * ${textLegacyHalfKanaRatio}))
        $sjisOk = (-not $sjisHalfKanaHeavy) -or (testHalfWidthKanaNatural $sjis)
    }

    $euc = tryDecodeStrict $bytes 51932
    $eucOk = ($null -ne $euc -and (testTextPlausible $euc) -and [regex]::IsMatch($euc, '[\u3040-\u30FF]'))

    if ($sjisOk -and -not $eucOk) { return "ShiftJIS" }
    if ($eucOk -and -not $sjisOk) { return "EUCJP" }
    if ($eucOk -and $sjisOk -and $sjisHalfKanaHeavy) { return "EUCJP" }
    return $null
}

function detectTextEncoding {
    # バイト列だけから文字コードを判定する（ファイルに触らない）。
    # 順に確かめる: BOM → NUL の偏り（BOM の無い UTF-16）→ NUL の無い日本語の UTF-16 → NUL を含むか（バイナリ） →
    #   ISO-2022-JP → UTF-8 として正しく読めるか → Shift_JIS・EUC-JP。判定できないもの（バイナリ・UTF-32・GBK など）は $null を返す
    #   戻り値: "UTF8" / "UTF16LE" / "UTF16BE" / "ShiftJIS" / "EUCJP" / "ISO2022JP" / $null（取り込まない）
    param (
        [byte[]]$bytes
    )

    if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF) {
        return "UTF8"
    }
    # UTF-32 の BOM は UTF-16LE の BOM（FF FE）と同じ並びで始まるため、先に確かめて取り込まない
    if ($bytes.Length -ge 4 -and (
            ($bytes[0] -eq 0xFF -and $bytes[1] -eq 0xFE -and $bytes[2] -eq 0 -and $bytes[3] -eq 0) -or
            ($bytes[0] -eq 0 -and $bytes[1] -eq 0 -and $bytes[2] -eq 0xFE -and $bytes[3] -eq 0xFF))) {
        return $null
    }
    if ($bytes.Length -ge 2 -and $bytes[0] -eq 0xFF -and $bytes[1] -eq 0xFE) {
        return "UTF16LE"
    }
    if ($bytes.Length -ge 2 -and $bytes[0] -eq 0xFE -and $bytes[1] -eq 0xFF) {
        return "UTF16BE"
    }

    $sampleLength = [Math]::Min($bytes.Length, [int]${textUtf16SampleBytes})
    $sampleLength -= ($sampleLength % 2)
    if ($sampleLength -gt 0) {
        $even = 0  # 偶数の位置（0, 2, …）の NUL の数
        $odd = 0   # 奇数の位置（1, 3, …）の NUL の数
        for ($i = 0; $i -lt $sampleLength; $i++) {
            if ($bytes[$i] -eq 0) {
                if (($i % 2) -eq 0) { $even++ } else { $odd++ }
            }
        }
        $n = $sampleLength / 2
        if ($odd -ge ($n * ${textUtf16NulRatioThreshold}) -and $even -le ($odd / ${textUtf16NulSkewDivisor})) {
            return "UTF16LE"
        }
        if ($even -ge ($n * ${textUtf16NulRatioThreshold}) -and $odd -le ($even / ${textUtf16NulSkewDivisor})) {
            return "UTF16BE"
        }
        if ($even -gt 0 -or $odd -gt 0) {
            # NUL が 20% に届かない。改行（CRLF）や全角スペース・「一」など下位バイトが 00 の文字だけが NUL の
            # 日本語の UTF-16 かを確かめる（偶数・奇数の両側に NUL があってよい）。それ以外はバイナリ（UTF-32 もここ）
            return (detectJapaneseUtf16WithoutNul $bytes)
        }
    }

    $utf16 = detectJapaneseUtf16WithoutNul $bytes
    if ($null -ne $utf16) { return $utf16 }

    # ここまでで BOM の無い UTF-16 とは判定できなかった。NUL（0x00）をファイル全体のどこかに含むものはバイナリとみなす
    if ([Array]::IndexOf($bytes, [byte]0) -ge 0) { return $null }

    $iso = getIso2022JpVerdict $bytes
    if ($iso -eq "yes") { return "ISO2022JP" }
    if ($iso -eq "broken") { return $null }

    if ($null -ne (tryDecodeStrict $bytes 65001)) {
        return "UTF8"
    }
    return (detectLegacyJapaneseEncoding $bytes)
}

function decodeTextBytes {
    # detectTextEncoding が返した文字コードで、バイト列を文字列にする（BOM は取り除く）
    param (
        [byte[]]$bytes,
        [string]$encodingName
    )

    switch ($encodingName) {
        "UTF8" {
            $offset = if ($bytes.Length -ge 3 -and $bytes[0] -eq 0xEF -and $bytes[1] -eq 0xBB -and $bytes[2] -eq 0xBF) { 3 } else { 0 }
            return (getStrictUtf8Encoding).GetString($bytes, $offset, $bytes.Length - $offset)
        }
        "UTF16LE" {
            $offset = if ($bytes.Length -ge 2 -and $bytes[0] -eq 0xFF -and $bytes[1] -eq 0xFE) { 2 } else { 0 }
            return [System.Text.Encoding]::Unicode.GetString($bytes, $offset, $bytes.Length - $offset)
        }
        "UTF16BE" {
            $offset = if ($bytes.Length -ge 2 -and $bytes[0] -eq 0xFE -and $bytes[1] -eq 0xFF) { 2 } else { 0 }
            return [System.Text.Encoding]::BigEndianUnicode.GetString($bytes, $offset, $bytes.Length - $offset)
        }
        "ShiftJIS" {
            return [System.Text.Encoding]::GetEncoding(932).GetString($bytes)
        }
        "EUCJP" {
            return [System.Text.Encoding]::GetEncoding(51932).GetString($bytes)
        }
        "ISO2022JP" {
            return [System.Text.Encoding]::GetEncoding(50221).GetString($bytes)
        }
    }
    throw "不明な文字コードです（${encodingName}）。"
}

function splitTextLines {
    # 文字列を行に分ける（CRLF・LF・CR のどれでも1行。StreamReader.ReadLine と同じ分け方）。
    # 途中の空の行は残し、行末の空白は取り除き（TrimEnd）、末尾の空の行は捨てる
    param (
        [string]$text
    )

    $lines = New-Object System.Collections.Generic.List[string]
    $reader = New-Object System.IO.StringReader($text)
    try {
        $line = $reader.ReadLine()
        while ($null -ne $line) {
            $lines.Add($line.TrimEnd())
            $line = $reader.ReadLine()
        }
    } finally {
        $reader.Dispose()
    }
    while ($lines.Count -gt 0 -and $lines[$lines.Count - 1] -eq "") {
        $lines.RemoveAt($lines.Count - 1)
    }
    return , $lines.ToArray()
}

function readTextFile {
    # テキストファイルを読み、行の並び（splitTextLines と同じ形）にして返す。
    # 元のファイルは読み取りだけで開く（共有は copyFileShared と同じ ReadWrite|Delete）。インデックス作成は、作業領域のコピーをこれで読む。
    # 大きさの上限を超える・バイナリと判定したときは、取り込み一覧・ログにそのまま出す文言で例外にする。
    # maxBytes はテストで上限を小さく差し替えるための引数（既定は textFileMaxBytes）
    param (
        [string]$path,
        [long]$maxBytes = ${textFileMaxBytes}
    )

    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $stream = [System.IO.FileStream]::new((toLongPath $path), [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    try {
        if ($stream.Length -gt $maxBytes) {
            throw "ファイルサイズが大きすぎるため更新できません。"
        }
        $bytes = New-Object byte[] ([int]$stream.Length)
        $read = 0
        while ($read -lt $bytes.Length) {
            $n = $stream.Read($bytes, $read, $bytes.Length - $read)
            if ($n -eq 0) { break }
            $read += $n
        }
    } finally {
        $stream.Dispose()
    }

    $encodingName = detectTextEncoding $bytes
    if ($null -eq $encodingName) {
        throw "テキストファイルではないため更新できません。"
    }
    return (splitTextLines (decodeTextBytes $bytes $encodingName))
}

# PDF の暗号化（標準のセキュリティハンドラー）を、空の利用者パスワードで復号する部品。PowerShell だけで書く（外の部品・Office を使わない）。
# 画面にもファイルにも触らない。pdf_file.ps1 の readPdfPages が、ストリームを取り出すときに使う。
#   読む    : AES-256（V5・R5・R6）。開くのに利用者パスワードが要らない（空のパスワードで鍵が作れて、/U の検証用のハッシュと合う）PDF だけ。
#   読まない: パスワードが要る PDF、AES-256 以外（RC4 40・128 ビット、AES-128 など。鍵の計算に MD5 が要り、FIPS 準拠を強制した機械で使えないため、
#             自前でも書かない。パスワードが要るかどうかも判定せず、必ず「方式に対応していない」にする）。例外にする（そのファイルだけ失敗）。
# 復号するのはストリームだけ（内容・フォントの対応表・オブジェクトのストリーム）。文字列は、読む内容がストリームの中にあるため復号しない。
# 使うのは SHA-2 と AES だけで、FIPS でも使える *CryptoServiceProvider の型を使う（SHA256Managed・AesManaged は FIPS で例外になる）。
# 鍵・途中の値は、例外の文にも記録にも出さない。壊れた辞書は、決まった長さの確かめと、R6 の繰り返しの上限（300 回。仕様では最大でも 288 回で終わる）で止める。
# 例外の文言は「PDF」で始める（readPdfPages は、それ以外の例外を「壊れている」に言い換える）。

# R6 の鍵の計算の繰り返しの上限（仕様では最後のバイトで終わる。最大でも 64 + 224 = 288 回で必ず終わる）
${pdfCryptR6MaxRounds} = 300

# 対応していない方式の例外の文
${pdfCryptUnsupported} = "PDFの暗号化の方式に対応していないため読めません。"

function joinPdfCryptBytes {
    # バイト列を順につなげる
    param (
        [object[]]$parts
    )

    $ms = [System.IO.MemoryStream]::new()
    foreach ($part in $parts) {
        if ($null -eq $part) { continue }
        $bytes = [byte[]]$part
        $ms.Write($bytes, 0, $bytes.Length)
    }
    return , $ms.ToArray()
}

function getPdfSha {
    # SHA-256・384・512
    param (
        [int]$bits,
        [byte[]]$data
    )

    if ($bits -eq 256) { $hash = New-Object System.Security.Cryptography.SHA256CryptoServiceProvider }
    elseif ($bits -eq 384) { $hash = New-Object System.Security.Cryptography.SHA384CryptoServiceProvider }
    else { $hash = New-Object System.Security.Cryptography.SHA512CryptoServiceProvider }
    try {
        return , $hash.ComputeHash($data)
    } finally {
        $hash.Dispose()
    }
}

function invokePdfAesCbc {
    # AES-CBC（詰め物なし。data は 16 の倍数）
    param (
        [byte[]]$key,
        [byte[]]$iv,
        [byte[]]$data,
        [bool]$encrypt
    )

    $aes = New-Object System.Security.Cryptography.AesCryptoServiceProvider
    try {
        $aes.Mode = [System.Security.Cryptography.CipherMode]::CBC
        $aes.Padding = [System.Security.Cryptography.PaddingMode]::None
        $aes.Key = $key
        $aes.IV = $iv
        if ($encrypt) { $transform = $aes.CreateEncryptor() } else { $transform = $aes.CreateDecryptor() }
        try {
            return , $transform.TransformFinalBlock($data, 0, $data.Length)
        } finally {
            $transform.Dispose()
        }
    } finally {
        $aes.Dispose()
    }
}

function getPdfCryptHashR56 {
    # R5・R6 の利用者パスワードのハッシュ（PDF 2.0 の Algorithm 2.B。R5 は SHA-256 の 1 回だけ）。32 バイトを返す
    param (
        [int]$revision,
        [byte[]]$passBytes,
        [byte[]]$salt,
        [byte[]]$userData
    )

    $k = getPdfSha 256 (joinPdfCryptBytes @($passBytes, $salt, $userData))
    if ($revision -lt 6) { return , $k }
    $round = 0
    do {
        $unit = joinPdfCryptBytes @($passBytes, $k, $userData)
        $repeated = New-Object byte[] ($unit.Length * 64)
        for ($j = 0; $j -lt 64; $j++) {
            [Array]::Copy($unit, 0, $repeated, $j * $unit.Length, $unit.Length)
        }
        $aesKey = New-Object byte[] 16
        $aesIv = New-Object byte[] 16
        [Array]::Copy($k, 0, $aesKey, 0, 16)
        [Array]::Copy($k, 16, $aesIv, 0, 16)
        $e = invokePdfAesCbc $aesKey $aesIv $repeated $true
        # 先頭 16 バイトを 1 つの大きな数とみなして 3 で割った余り（256 を 3 で割ると 1 余るので、バイトの和の余りと同じ）
        $sum = 0
        for ($j = 0; $j -lt 16; $j++) { $sum += $e[$j] }
        $k = getPdfSha (256 + 128 * ($sum % 3)) $e
        $round++
    } while (($round -lt 64 -or $e[$e.Length - 1] -gt $round - 32) -and $round -lt ${pdfCryptR6MaxRounds})
    $result = New-Object byte[] 32
    [Array]::Copy($k, 0, $result, 0, 32)
    return , $result
}

function getPdfStringBytes {
    # PDF の文字列（@{PdfType="str"}）をバイト列にする。文字列でなければ $null
    param (
        $value
    )

    if ($value -is [hashtable] -and $value.ContainsKey("PdfType") -and $value["PdfType"] -eq "str") {
        return , (${pdfLatin1}.GetBytes([string]$value["V"]))
    }
    return $null
}

function getPdfSlice {
    # バイト列の一部を新しい配列に写す
    param (
        [byte[]]$bytes,
        [int]$offset,
        [int]$length
    )

    $out = New-Object byte[] $length
    [Array]::Copy($bytes, $offset, $out, 0, $length)
    return , $out
}

function getPdfKeyR56 {
    # R5・R6 のファイルの鍵を、空の利用者パスワードで作る。/U の検証用のハッシュと合わなければ「パスワードが必要」の例外。
    # userBytes は /U（48 バイト以上）、userExtra は /UE（32 バイト以上）
    param (
        [int]$revision,
        [byte[]]$userBytes,
        [byte[]]$userExtra
    )

    $empty = New-Object byte[] 0
    $check = getPdfCryptHashR56 $revision $empty (getPdfSlice $userBytes 32 8) $empty
    $same = $true
    for ($i = 0; $i -lt 32; $i++) { if ($check[$i] -ne $userBytes[$i]) { $same = $false } }
    if (-not $same) { throw "PDFにパスワードが必要なため読めません。" }
    $intermediate = getPdfCryptHashR56 $revision $empty (getPdfSlice $userBytes 40 8) $empty
    return , (invokePdfAesCbc $intermediate (New-Object byte[] 16) (getPdfSlice $userExtra 0 32) $false)
}

function getPdfCryptMethod {
    # 暗号化フィルター（CF の項目）の方式を返す。AES-256（/AESV3）は AESV3、/None と /Identity は復号しない（None）。
    # それ以外は、対応しない方式として例外にする
    param (
        [hashtable]$doc,
        $cf,
        [string]$name
    )

    if ($name -ceq "/Identity") { return "None" }
    if (-not (testPdfDict $cf) -or $name.Length -lt 2) {
        throw ${pdfCryptUnsupported}
    }
    $filter = resolvePdf $doc $cf[$name.Substring(1)]
    if (-not (testPdfDict $filter)) {
        throw ${pdfCryptUnsupported}
    }
    $cfm = resolvePdf $doc $filter["CFM"]
    if ($cfm -ceq "/None") { return "None" }
    if ($cfm -ceq "/AESV3") { return "AESV3" }
    throw ${pdfCryptUnsupported}
}

function newPdfCrypt {
    # Encrypt の辞書（解決済み）から、空の利用者パスワードで鍵を作り、/U と照らして合えば復号の設定を返す。
    # 返す値: @{ Key; StmMethod; Cf }。AES-256（V5・R5・R6）だけを読む。
    # パスワードが要る（空のパスワードが /U と合わない）・対応しない方式・辞書が壊れているときは、そのファイルだけ例外にする
    param (
        [hashtable]$doc,
        [hashtable]$enc
    )

    if ((resolvePdf $doc $enc["Filter"]) -cne "/Standard") { throw ${pdfCryptUnsupported} }
    $v = resolvePdf $doc $enc["V"]
    $r = resolvePdf $doc $enc["R"]
    if ($v -isnot [double] -or $r -isnot [double]) { throw ${pdfCryptUnsupported} }
    if ($v -ne 5.0 -or ($r -ne 5.0 -and $r -ne 6.0)) { throw ${pdfCryptUnsupported} }
    $r = [int]$r

    # 復号の方式（ストリーム）
    $cf = resolvePdf $doc $enc["CF"]
    $stmName = resolvePdf $doc $enc["StmF"]
    if ($null -eq $stmName) { $stmName = "/Identity" }
    if ($stmName -isnot [string]) { throw ${pdfCryptUnsupported} }
    $method = getPdfCryptMethod $doc $cf $stmName

    $userBytes = getPdfStringBytes (resolvePdf $doc $enc["U"])
    $userExtra = getPdfStringBytes (resolvePdf $doc $enc["UE"])
    if ($null -eq $userBytes -or $userBytes.Length -lt 48 -or $null -eq $userExtra -or $userExtra.Length -lt 32) {
        throw "PDFの暗号化の情報が壊れているため読めません。"
    }
    $key = getPdfKeyR56 $r $userBytes $userExtra
    return @{ Key = $key; StmMethod = $method; Cf = $cf }
}

function getPdfStreamCryptMethod {
    # ストリーム 1 つの復号の方式（AESV3・None）を返す。相互参照のストリームは暗号化されない。
    # ストリームごとの /Crypt フィルターがあれば、その名前の方式（/Identity は復号しない）にする
    param (
        [hashtable]$doc,
        [hashtable]$stream
    )

    $crypt = $doc.Crypt
    $dict = $stream.Dict
    if ((resolvePdf $doc $dict["Type"]) -ceq "/XRef") { return "None" }
    $filters = resolvePdf $doc $dict["Filter"]
    if ($null -ne $filters) {
        $filterList = @($filters)
        $paramsList = @(resolvePdf $doc $dict["DecodeParms"])
        for ($i = 0; $i -lt $filterList.Count; $i++) {
            if ((resolvePdf $doc $filterList[$i]) -ceq "/Crypt") {
                $name = "/Identity"
                if ($i -lt $paramsList.Count) {
                    $params = resolvePdf $doc $paramsList[$i]
                    if ((testPdfDict $params) -and $null -ne (resolvePdf $doc $params["Name"])) { $name = resolvePdf $doc $params["Name"] }
                }
                if ($name -isnot [string]) { throw ${pdfCryptUnsupported} }
                return (getPdfCryptMethod $doc $crypt.Cf $name)
            }
        }
    }
    return $crypt.StmMethod
}

function unprotectPdfData {
    # ストリームの中身（圧縮を戻す前）を復号する。AES-256 はファイルの鍵をそのまま使う
    param (
        [hashtable]$crypt,
        [string]$method,
        [byte[]]$data
    )

    if ($method -ceq "None") { return , $data }
    # AES-CBC。先頭 16 バイトが初期ベクトル、最後に PKCS#7 の詰め物
    if ($data.Length -eq 0) { return , $data }
    if ($data.Length -lt 32 -or $data.Length % 16 -ne 0) {
        throw "PDFの暗号化されたデータが壊れているため読めません。"
    }
    $plain = invokePdfAesCbc $crypt.Key (getPdfSlice $data 0 16) (getPdfSlice $data 16 ($data.Length - 16)) $false
    $pad = $plain[$plain.Length - 1]
    if ($pad -lt 1 -or $pad -gt 16) {
        throw "PDFの暗号化されたデータが壊れているため読めません。"
    }
    return , (getPdfSlice $plain 0 ($plain.Length - $pad))
}

# PDF ファイルの対象の拡張子・文字の読み取り。PowerShell だけで読む（外の部品・Office を使わない）。
# バイト列 → ページごとの文字列（readPdfPages）は、画面にもファイルにも触らない判断層の関数にする。
# ファイルを開いて読む関数（readPdfFile）だけが状態層（ファイルに触る）。
# 読む範囲と上限は docs/design/indexing/pdf.md、細工した PDF から身を守ることは docs/safety/checks.md。
#   読む    : 相互参照の表・相互参照のストリーム（オブジェクトのストリーム）、圧縮なし・FlateDecode、
#             文字の命令 Tj・TJ・'・"、行送り Td・TD・T*・Tm・TL（縦の位置が変わったときに行を分ける。ET では分けない）、
#             フォントの ToUnicode、ToUnicode の無い単純フォント（WinAnsi 相当）
#   暗号化   : 空の利用者パスワードで開ける PDF は復号して読む（pdf_crypt.ps1）。パスワードが要るもの・未対応の方式は例外にする。
#   読まない: FlateDecode 以外の圧縮、ToUnicode の無い複合フォント（CID）、壊れた相互参照（修復しない）。例外にする。
#             Form XObject（Do）・注釈・フォーム・しおりの文字は例外にせず、読み飛ばす
# 例外の文言は「PDF」で始める（readPdfPages は、それ以外の例外を「壊れている」に言い換える）。

# 取り込み対象にする PDF の拡張子（小文字）。足す・減らすと tests\meta\safety.Tests.ps1 が固定の一覧で確かめる
${pdfExtensions} = @(".pdf")

# 元のファイルがこの大きさ（バイト）を超えたら、読まずに失敗にする
${pdfFileMaxBytes} = 100MB
# 1 ファイルの解凍後の合計がこの大きさ（バイト）を超えたら、失敗にする（圧縮爆弾）
${pdfInflatedMaxBytes} = 100MB
# 相互参照のオブジェクトの数の上限
${pdfObjectMaxCount} = 1000000
# ページツリー・間接参照・配列や辞書の入れ子の深さの上限
${pdfNestMaxDepth} = 64
# ページ数の上限
${pdfPageMaxCount} = 10000
# TJ の数値がこの値以下（1/1000 文字幅。負の向きが右への詰め）で、前後の文字がどちらも半角のときだけ空白を入れる
${pdfGapThreshold} = -250
# 文字の対応表（ToUnicode）の項目の、1 ファイルの合計の上限
${pdfMapMaxEntries} = 1000000
# たどる相互参照（Prev・XRefStm）の数の上限
${pdfXrefMaxCount} = 1000
# ストリームの終わりを探して読み進める文字数の合計の上限（ファイルの大きさの何倍まで）。
# /Length の合わないストリームが順や逆順に並ぶだけなら、探す量は約 1 倍に収まる。その余裕を見て 4 倍にする
${pdfSearchMaxRatio} = 4
# 同じ行とみなす縦位置の差（ポイント）の上限
${pdfLineTolerance} = 1.0

${pdfLatin1} = [System.Text.Encoding]::GetEncoding(28591)
${pdfWinAnsi} = [System.Text.Encoding]::GetEncoding(1252)
${pdfDelimiters} = [char[]]@(0, 9, 10, 12, 13, 32, '(', ')', '<', '>', '[', ']', '{', '}', '/', '%')
${pdfStringStops} = [char[]]@('(', ')', '\')
# readPdfPageText の字句の切り出し用の正規表現。部品は 1 か所で定義し、2 つの正規表現をここから組み立てる。
# 区切り・空白は ${pdfDelimiters} と同じ（テストが全コードで確かめる）。実行時のコンパイル（RegexOptions.Compiled）は使わない。
${pdfRegexSpace} = '[\x00-\x20]*'
${pdfRegexNotStart} = '\x00-\x20()<>\[\]{}/%'
${pdfRegexRest} = '[^\x00\x09\x0A\x0C\x0D\x20()<>\[\]{}/%]'
${pdfRegexWord} = "[^${pdfRegexNotStart}]${pdfRegexRest}*"
${pdfRegexName} = "/${pdfRegexRest}*"
${pdfRegexString} = '\([^()\\]*\)'
# ページの内容で、文字の位置や文字列に効く命令（' と " は英字で始まらないので、正規表現には要らない）。readPdfPageText の分岐と同じであることをテストが確かめる
${pdfTextOpNames} = [string[]]@("Tj", "TJ", "Tf", "BT", "Td", "TD", "TL", "T*", "Tm", "BI")
${pdfRegexTextOps} = (@(${pdfTextOpNames} | ForEach-Object { [regex]::Escape($_) }) -join "|")
# 空白を飛ばして、(1) 数値・キーワード、または (2) 名前・入れ子もエスケープも無い文字列・<< >> [ ] { } を 1 つ取る。
# コメント・16 進の文字列・入れ子やエスケープのある文字列・単独の < > ) は取らない（readPdfToken の 1 文字ずつ進める道に任せる）
${pdfTokenRegex} = [regex]::new("\G(?>${pdfRegexSpace})(?:(${pdfRegexWord})|(${pdfRegexName}|${pdfRegexString}|<<|>>|[\[\]{}]))")
# ページの内容の読み取り用。字句の取り方は pdfTokenRegex と同じで、先頭に「読み飛ばす並び」を足してある（グループ 1。語は 2、それ以外は 3）。
# 読み飛ばす並び = 数・名前・単純な文字列などの引数が最大 16 個並び、文字に効かない命令（英字で始まる語で、pdfTextOpNames 以外）で終わる。
# 命令を読むと数・名前・文字列は捨てられるので、飛ばしても結果は変わらない。文字に効く命令の前の引数は要るので、並びの終わりが文字に効かない命令のときだけ飛ばす。
# 並びの個数に上限があるのは、引数が延々と続く内容で、試みのたびに最後まで走って遅くなる（字句の数の 2 乗）のを防ぐため。上限より長い並びは 1 字句ずつ読む（結果は同じ）。
# 配列・辞書・コメント・入れ子の文字列を含むところは、ここに合わず 1 字句ずつ読む。
${pdfRegexArgStart} = "[^${pdfRegexNotStart}A-Za-z'`"]"
${pdfRegexArg} = "(?:${pdfRegexArgStart}${pdfRegexRest}*|${pdfRegexName}|${pdfRegexString})"
${pdfRegexSkip} = "(?>(?>${pdfRegexSpace})${pdfRegexArg}){0,16}(?>${pdfRegexSpace})(?!(?:${pdfRegexTextOps})(?!${pdfRegexRest}))[A-Za-z]${pdfRegexRest}*"
${pdfPageRegex} = [regex]::new("\G(?:(${pdfRegexSkip})|(?>${pdfRegexSpace})(?:(${pdfRegexWord})|(${pdfRegexName}|${pdfRegexString}|<<|>>|[\[\]{}])))")

function testPdfExtension {
    # ファイル名（またはパス）の拡張子が、取り込み対象の PDF の拡張子か（大文字・小文字を区別しない）
    param (
        [string]$path
    )

    $extension = [System.IO.Path]::GetExtension($path).ToLowerInvariant()
    return (${pdfExtensions} -contains $extension)
}

function newPdfLimits {
    # 読み取りの上限。既定は上の値。テストで小さく差し替えるための引数
    param (
        [long]$maxInflated = ${pdfInflatedMaxBytes},
        [int]$maxObjects = ${pdfObjectMaxCount},
        [int]$maxDepth = ${pdfNestMaxDepth},
        [int]$maxPages = ${pdfPageMaxCount},
        [int]$maxMapEntries = ${pdfMapMaxEntries},
        [int]$maxXref = ${pdfXrefMaxCount},
        [double]$maxSearchRatio = ${pdfSearchMaxRatio}
    )

    return @{
        MaxInflated = $maxInflated; MaxObjects = $maxObjects; MaxDepth = $maxDepth; MaxPages = $maxPages
        MaxMapEntries = $maxMapEntries; MaxXref = $maxXref; MaxSearchRatio = $maxSearchRatio
    }
}

function newPdfLexer {
    param (
        [string]$text,
        [int]$position = 0
    )

    return @{ S = $text; P = $position; K = "" }
}

function readPdfToken {
    # 字句を 1 つ読んで値を返す。種類は $st.K に入る:
    #   num（数値。double）/ name（先頭の / を除いた名前）/ str（文字列。丸括弧・16 進。1 バイト 1 文字の文字列）/
    #   kw（キーワード・演算子）/ [ / ] / << / >> / eof
    # 文字列全体に正規表現を当てず、1 文字ずつ進める（壊れた入力で後戻りが増えて固まらないため）
    param (
        [hashtable]$st
    )

    $s = $st.S
    $n = $s.Length
    $p = $st.P
    while ($true) {
        while ($p -lt $n -and [int]$s[$p] -le 32) { $p++ }
        if ($p -ge $n) {
            $st.P = $p
            $st.K = "eof"
            return $null
        }
        $c = $s[$p]
        if ($c -eq '%') {
            $e = $s.IndexOfAny([char[]]@([char]10, [char]13), $p)
            if ($e -lt 0) { $p = $n } else { $p = $e }
            continue
        }
        if ($c -eq '/') {
            $e = $s.IndexOfAny(${pdfDelimiters}, $p + 1)
            if ($e -lt 0) { $e = $n }
            $name = $s.Substring($p + 1, $e - $p - 1)
            if ($name.Contains("#")) {
                # 名前の # の戻しは readPdfPageText の字句の取り方と同じ。変えるときは 2 か所をそろえる
                $name = [regex]::Replace($name, '#([0-9A-Fa-f]{2})', { param($m) [string][char][Convert]::ToInt32($m.Groups[1].Value, 16) })
            }
            $st.P = $e
            $st.K = "name"
            return $name
        }
        if ($c -eq '(') {
            $sb = [System.Text.StringBuilder]::new()
            $nest = 1
            $p++
            while ($p -lt $n) {
                $q = $s.IndexOfAny(${pdfStringStops}, $p)
                if ($q -lt 0) {
                    [void]$sb.Append($s, $p, $n - $p)
                    $p = $n
                    break
                }
                [void]$sb.Append($s, $p, $q - $p)
                $ch = $s[$q]
                if ($ch -eq '(') {
                    $nest++
                    [void]$sb.Append('(')
                    $p = $q + 1
                } elseif ($ch -eq ')') {
                    $nest--
                    $p = $q + 1
                    if ($nest -eq 0) { break }
                    [void]$sb.Append(')')
                } else {
                    $q++
                    if ($q -ge $n) { $p = $n; break }
                    $e = $s[$q]
                    $p = $q + 1
                    if ($e -ceq 'n') { [void]$sb.Append([char]10) }
                    elseif ($e -ceq 'r') { [void]$sb.Append([char]13) }
                    elseif ($e -ceq 't') { [void]$sb.Append([char]9) }
                    elseif ($e -ceq 'b') { [void]$sb.Append([char]8) }
                    elseif ($e -ceq 'f') { [void]$sb.Append([char]12) }
                    elseif ($e -ge '0' -and $e -le '7') {
                        $value = [int]$e - 48
                        $digits = 1
                        while ($digits -lt 3 -and $p -lt $n -and $s[$p] -ge '0' -and $s[$p] -le '7') {
                            $value = $value * 8 + ([int]$s[$p] - 48)
                            $p++
                            $digits++
                        }
                        [void]$sb.Append([char]($value -band 255))
                    } elseif ($e -eq "`r") {
                        if ($p -lt $n -and $s[$p] -eq "`n") { $p++ }
                    } elseif ($e -eq "`n") {
                        # 行の継続（何も入れない）
                    } else {
                        [void]$sb.Append($e)
                    }
                }
            }
            $st.P = $p
            $st.K = "str"
            return $sb.ToString()
        }
        if ($c -eq '<') {
            if ($p + 1 -lt $n -and $s[$p + 1] -eq '<') {
                $st.P = $p + 2
                $st.K = "<<"
                return $null
            }
            $e = $s.IndexOf('>', $p + 1)
            if ($e -lt 0) { $e = $n }
            $hex = $s.Substring($p + 1, $e - $p - 1) -replace '[^0-9A-Fa-f]', ''
            if ($hex.Length % 2 -eq 1) { $hex += "0" }
            $sb = [System.Text.StringBuilder]::new()
            for ($i = 0; $i -lt $hex.Length; $i += 2) {
                [void]$sb.Append([char][Convert]::ToInt32($hex.Substring($i, 2), 16))
            }
            $st.P = [Math]::Min($e + 1, $n)
            $st.K = "str"
            return $sb.ToString()
        }
        if ($c -eq '>') {
            if ($p + 1 -lt $n -and $s[$p + 1] -eq '>') {
                $st.P = $p + 2
                $st.K = ">>"
                return $null
            }
            $p++
            continue
        }
        if ($c -eq '[') { $st.P = $p + 1; $st.K = "["; return $null }
        if ($c -eq ']') { $st.P = $p + 1; $st.K = "]"; return $null }
        if ($c -eq ')' ) { $p++; continue }
        if ($c -eq '{' -or $c -eq '}') { $st.P = $p + 1; $st.K = "kw"; return [string]$c }

        $e = $s.IndexOfAny(${pdfDelimiters}, $p)
        if ($e -lt 0) { $e = $n }
        $token = $s.Substring($p, $e - $p)
        $st.P = $e
        $d = 0.0
        if (($c -ge '0' -and $c -le '9') -or $c -eq '-' -or $c -eq '+' -or $c -eq '.') {
            # 数の判定は readPdfPageText の字句の取り方（2 か所）と同じ。変えるときは 3 か所をそろえる
            if ([double]::TryParse($token, [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$d) -and -not [double]::IsInfinity($d) -and -not [double]::IsNaN($d)) {
                $st.K = "num"
                return $d
            }
        }
        $st.K = "kw"
        return $token
    }
}

function readPdfValue {
    # 値（数値・名前 "/名前"・文字列 @{PdfType="str"}・配列 List・辞書 Hashtable・間接参照 @{PdfType="ref"; N}・真偽・null）を 1 つ読む。
    # 読み終わったあと $st.K が ] / >> / eof なら、値でなく終わりの印を読んだ（戻り値は $null）
    param (
        [hashtable]$doc,
        [hashtable]$st,
        [int]$depth,
        [bool]$allowRef = $true
    )

    if ($depth -gt $doc.Limits.MaxDepth) {
        throw "PDFの入れ子が深すぎるため読めません。"
    }
    $v = readPdfToken $st
    $kind = $st.K
    if ($kind -eq "num") {
        if ($allowRef -and $v -ge 0 -and $v -le 2147483647 -and $v -eq [Math]::Floor($v)) {
            $save = $st.P
            $g = readPdfToken $st
            if ($st.K -eq "num" -and $g -ge 0 -and $g -eq [Math]::Floor($g)) {
                $r = readPdfToken $st
                if ($st.K -eq "kw" -and $r -ceq "R") {
                    $st.K = "val"
                    return @{ PdfType = "ref"; N = [int]$v }
                }
            }
            $st.P = $save
            $st.K = "num"
        }
        return $v
    }
    if ($kind -eq "name") { return "/$v" }
    if ($kind -eq "str") { return @{ PdfType = "str"; V = $v } }
    if ($kind -eq "[") {
        $list = [System.Collections.Generic.List[object]]::new()
        while ($true) {
            $item = readPdfValue $doc $st ($depth + 1) $allowRef
            if ($st.K -eq "]" -or $st.K -eq "eof" -or $st.K -eq ">>") { break }
            if ($list.Count -ge $doc.Limits.MaxObjects) {
                throw "PDFの配列の要素の数が上限を超えるため読めません。"
            }
            $list.Add($item)
        }
        $st.K = "val"
        return , $list
    }
    if ($kind -eq "<<") {
        $dict = [System.Collections.Hashtable]::new()
        while ($true) {
            $key = readPdfToken $st
            if ($st.K -eq ">>" -or $st.K -eq "eof") { break }
            if ($st.K -ne "name") { continue }
            $item = readPdfValue $doc $st ($depth + 1) $allowRef
            if ($st.K -eq ">>" -or $st.K -eq "eof") { break }
            $dict[$key] = $item
            if ($dict.Count -gt $doc.Limits.MaxObjects) {
                throw "PDFの辞書の項目の数が上限を超えるため読めません。"
            }
        }
        $st.K = "val"
        return , $dict
    }
    if ($kind -eq "kw") {
        if ($v -ceq "true") { return $true }
        if ($v -ceq "false") { return $false }
        return $null
    }
    return $null
}

function testPdfRef {
    param ($v)
    return ($v -is [hashtable] -and $v.ContainsKey("PdfType") -and $v["PdfType"] -eq "ref")
}

function testPdfStream {
    param ($v)
    return ($v -is [hashtable] -and $v.ContainsKey("PdfType") -and $v["PdfType"] -eq "stream")
}

function testPdfDict {
    param ($v)
    return ($v -is [System.Collections.Hashtable] -and -not $v.ContainsKey("PdfType"))
}

function resolvePdf {
    # 間接参照をたどって値を返す（たどる回数に上限。循環は例外）
    param (
        [hashtable]$doc,
        $v
    )

    $count = 0
    while (testPdfRef $v) {
        $count++
        if ($count -gt $doc.Limits.MaxDepth) {
            throw "PDFの参照が循環しているため読めません。"
        }
        $v = getPdfObject $doc $v["N"]
    }
    return $v
}

function getPdfObject {
    # 番号のオブジェクトを読んで返す（読んだものは控える）。相互参照に無い・解放済みは $null。
    # 読んでいる最中に同じ番号を読もうとしたら（循環）、例外にする
    param (
        [hashtable]$doc,
        [int]$num
    )

    if ($doc.Cache.ContainsKey($num)) { return $doc.Cache[$num] }
    if (-not $doc.Xref.ContainsKey($num)) { return $null }
    $entry = $doc.Xref[$num]
    if ($entry.Type -eq 0) { return $null }
    if ($doc.Loading.ContainsKey($num)) {
        throw "PDFの参照が循環しているため読めません。"
    }
    if ($doc.Loading.Count -ge $doc.Limits.MaxDepth) {
        throw "PDFの参照が深すぎるため読めません。"
    }
    $doc.Loading[$num] = $true
    try {
        if ($entry.Type -eq 1) {
            $value = readPdfIndirectAt $doc $entry.Offset $num
        } else {
            $value = readPdfFromObjectStream $doc $entry.Stream $entry.Index $num
        }
    } finally {
        $doc.Loading.Remove($num)
    }
    $doc.Cache[$num] = $value
    return $value
}

function readPdfIndirectAt {
    # オフセットにある "N G obj ... endobj" を読む。ストリームなら @{PdfType="stream"; Dict; Start; Length} を返す。
    # expected が 0 以上なら、番号が合うことも確かめる
    param (
        [hashtable]$doc,
        [long]$offset,
        [int]$expected
    )

    $text = $doc.Text
    if ($offset -lt 0 -or $offset -ge $text.Length) {
        throw "PDFの相互参照がファイルの外を指しているため読めません。"
    }
    $st = newPdfLexer $text ([int]$offset)
    $a = readPdfToken $st
    $aKind = $st.K
    $gen = readPdfToken $st
    $c = readPdfToken $st
    if ($aKind -ne "num" -or $st.K -ne "kw" -or $c -cne "obj") {
        throw "PDFのオブジェクトが見つからないため読めません。"
    }
    if ($expected -ge 0 -and [int]$a -ne $expected) {
        throw "PDFのオブジェクトの番号が相互参照と合わないため読めません。"
    }
    $value = readPdfValue $doc $st 0
    if (-not (testPdfDict $value)) { return $value }

    $save = $st.P
    $t = readPdfToken $st
    if ($st.K -ne "kw" -or $t -cne "stream") { return $value }
    $start = $st.P
    if ($start -lt $text.Length -and $text[$start] -eq "`r") { $start++ }
    if ($start -lt $text.Length -and $text[$start] -eq "`n") { $start++ }
    $length = -1
    $declared = resolvePdf $doc $value["Length"]
    if ($declared -is [double] -and $declared -ge 0 -and $start + $declared -le $text.Length) {
        $after = [int]($start + $declared)
        $skip = 0
        while ($skip -lt 4 -and $after + $skip -lt $text.Length -and [int]$text[$after + $skip] -le 32) { $skip++ }
        if ([string]::CompareOrdinal($text, $after + $skip, "endstream", 0, 9) -eq 0) { $length = [int]$declared }
    }
    if ($length -lt 0) {
        # 長さが合わないストリームが多くても、同じ範囲を何度も探さないよう、直前に見つけた位置を使い回す
        # [From, At) には "endstream" の始まりが無い。前より手前から探すときは、手前の分だけ探して無ければ At を使う
        $found = $doc.EndSearch
        if ($start -ge $found.From -and $start -le $found.At) {
            $end = $found.At
        } elseif ($start -lt $found.From -and $found.At -ge $found.From) {
            $span = [Math]::Min($found.From - $start + 8, $text.Length - $start)
            $end = $text.IndexOf("endstream", $start, $span, [StringComparison]::Ordinal)
            if ($end -lt 0 -or $end -ge $found.From) {
                $doc.Searched += $span
                $end = $found.At
            } else {
                $doc.Searched += $end - $start
            }
            $found.From = $start
            $found.At = $end
        } else {
            $end = $text.IndexOf("endstream", $start, [StringComparison]::Ordinal)
            if ($end -lt 0) {
                throw "PDFのストリームの終わりが無いため読めません。"
            }
            $doc.Searched += $end - $start
            $found.From = $start
            $found.At = $end
        }
        if ($doc.Searched -gt $doc.Limits.MaxSearchRatio * $text.Length) {
            throw "PDFのストリームの終わりを探す量が上限を超えるため読めません。"
        }
        $length = $end - $start
        if ($length -gt 0 -and $text[$start + $length - 1] -eq "`n") { $length-- }
        if ($length -gt 0 -and $text[$start + $length - 1] -eq "`r") { $length-- }
    }
    return @{ PdfType = "stream"; Dict = $value; Start = $start; Length = $length; Num = [int]$a }
}

function expandPdfFlate {
    # zlib の先頭 2 バイトを飛ばして DeflateStream で解凍する。解凍後の合計が上限を超えたら例外
    param (
        [hashtable]$doc,
        [byte[]]$data
    )

    if ($data.Length -lt 3) {
        throw "PDFの圧縮されたデータが壊れているため読めません。"
    }
    $source = [System.IO.MemoryStream]::new($data, 2, $data.Length - 2)
    $deflate = [System.IO.Compression.DeflateStream]::new($source, [System.IO.Compression.CompressionMode]::Decompress)
    $output = [System.IO.MemoryStream]::new()
    $buffer = New-Object byte[] 65536
    try {
        while ($true) {
            $read = $deflate.Read($buffer, 0, $buffer.Length)
            if ($read -le 0) { break }
            $doc.Inflated += $read
            if ($doc.Inflated -gt $doc.Limits.MaxInflated) {
                throw "PDFの解凍後の大きさが上限を超えるため読めません。"
            }
            $output.Write($buffer, 0, $read)
        }
        return , $output.ToArray()
    } finally {
        $deflate.Dispose()
        $source.Dispose()
        $output.Dispose()
    }
}

function undoPdfPredictor {
    # FlateDecode の Predictor（PNG の 10～15）を戻す。TIFF（2）は読まない
    param (
        [byte[]]$data,
        $params
    )

    $predictor = 1
    if ((testPdfDict $params) -and $params.ContainsKey("Predictor")) { $predictor = [int]$params["Predictor"] }
    if ($predictor -le 1) { return , $data }
    if ($predictor -lt 10) {
        throw "PDFの未対応の圧縮のため読めません。"
    }
    $columns = 1
    $colors = 1
    $bits = 8
    if ($params.ContainsKey("Columns")) { $columns = [int]$params["Columns"] }
    if ($params.ContainsKey("Colors")) { $colors = [int]$params["Colors"] }
    if ($params.ContainsKey("BitsPerComponent")) { $bits = [int]$params["BitsPerComponent"] }
    $rowLength = [int][Math]::Ceiling($columns * $colors * $bits / 8.0)
    $bpp = [Math]::Max(1, [int][Math]::Ceiling($colors * $bits / 8.0))
    if ($rowLength -le 0) {
        throw "PDFの圧縮の指定が壊れているため読めません。"
    }
    $rows = [int][Math]::Floor($data.Length / ($rowLength + 1))
    $out = New-Object byte[] ($rows * $rowLength)
    for ($r = 0; $r -lt $rows; $r++) {
        $src = $r * ($rowLength + 1)
        $type = $data[$src]
        $dst = $r * $rowLength
        $prev = $dst - $rowLength
        for ($i = 0; $i -lt $rowLength; $i++) {
            $x = [int]$data[$src + 1 + $i]
            $left = 0
            if ($i -ge $bpp) { $left = [int]$out[$dst + $i - $bpp] }
            $up = 0
            if ($r -gt 0) { $up = [int]$out[$prev + $i] }
            $upLeft = 0
            if ($r -gt 0 -and $i -ge $bpp) { $upLeft = [int]$out[$prev + $i - $bpp] }
            if ($type -eq 0) { $v = $x }
            elseif ($type -eq 1) { $v = $x + $left }
            elseif ($type -eq 2) { $v = $x + $up }
            elseif ($type -eq 3) { $v = $x + [int][Math]::Floor(($left + $up) / 2) }
            elseif ($type -eq 4) {
                $pp = $left + $up - $upLeft
                $pa = [Math]::Abs($pp - $left)
                $pb = [Math]::Abs($pp - $up)
                $pc = [Math]::Abs($pp - $upLeft)
                if ($pa -le $pb -and $pa -le $pc) { $pred = $left } elseif ($pb -le $pc) { $pred = $up } else { $pred = $upLeft }
                $v = $x + $pred
            } else {
                throw "PDFの圧縮のデータが壊れているため読めません。"
            }
            $out[$dst + $i] = [byte]($v -band 255)
        }
    }
    return , $out
}

function getPdfStreamBytes {
    # ストリームの中身を、圧縮を戻して返す（圧縮なし・FlateDecode だけ。ほかは例外）
    param (
        [hashtable]$doc,
        [hashtable]$stream
    )

    $dict = $stream.Dict
    $filters = resolvePdf $doc $dict["Filter"]
    # 取り出す前の大きさも、圧縮の有無にかかわらず合計に数える（同じストリームを何度も参照されても増え続けないように）
    $doc.Inflated += $stream.Length
    if ($doc.Inflated -gt $doc.Limits.MaxInflated) {
        throw "PDFの解凍後の大きさが上限を超えるため読めません。"
    }
    $data = New-Object byte[] $stream.Length
    [Array]::Copy($doc.Bytes, $stream.Start, $data, 0, $stream.Length)
    if ($null -ne $doc.Crypt -and $stream.ContainsKey("Num")) {
        # 暗号化された PDF は、圧縮を戻す前に復号する
        $method = getPdfStreamCryptMethod $doc $stream
        $data = unprotectPdfData $doc.Crypt $method $data
    }
    if ($null -eq $filters) { return , $data }
    $filterList = @($filters)
    $paramsValue = resolvePdf $doc $dict["DecodeParms"]
    $paramsList = @($paramsValue)
    for ($i = 0; $i -lt $filterList.Count; $i++) {
        $name = resolvePdf $doc $filterList[$i]
        if ($name -ceq "/Crypt") {
            continue
        } elseif ($name -ceq "/FlateDecode" -or $name -ceq "/Fl") {
            $data = expandPdfFlate $doc $data
            $params = $null
            if ($i -lt $paramsList.Count) { $params = resolvePdf $doc $paramsList[$i] }
            $data = undoPdfPredictor $data $params
        } else {
            throw "PDFの未対応の圧縮のため読めません。"
        }
    }
    return , $data
}

function readPdfFromObjectStream {
    # オブジェクトのストリームの中の、番号のオブジェクトを読む
    param (
        [hashtable]$doc,
        [int]$streamNum,
        [int]$index,
        [int]$num
    )

    if (-not $doc.ObjStreams.ContainsKey($streamNum)) {
        $stream = getPdfObject $doc $streamNum
        if (-not (testPdfStream $stream)) {
            throw "PDFのオブジェクトのストリームが読めないため読めません。"
        }
        $bytes = getPdfStreamBytes $doc $stream
        $text = ${pdfLatin1}.GetString($bytes)
        $count = [int](resolvePdf $doc $stream.Dict["N"])
        $first = [int](resolvePdf $doc $stream.Dict["First"])
        if ($count -lt 0 -or $count -gt $doc.Limits.MaxObjects) {
            throw "PDFのオブジェクトの数が上限を超えるため読めません。"
        }
        # 見出しは 1 件に 4 文字（"1 0 "）以上要る。中身より多い件数は、確保する前に断る
        if ($count -gt [Math]::Floor($text.Length / 4)) {
            throw "PDFのオブジェクトのストリームの件数が中身と合わないため読めません。"
        }
        $st = newPdfLexer $text 0
        $numbers = New-Object int[] $count
        $offsets = New-Object int[] $count
        for ($i = 0; $i -lt $count; $i++) {
            $token = readPdfToken $st
            if ($st.K -ne "num") { throw "PDFのオブジェクトのストリームの見出しが読めないため読めません。" }
            $numbers[$i] = [int]$token
            $token = readPdfToken $st
            if ($st.K -ne "num") { throw "PDFのオブジェクトのストリームの見出しが読めないため読めません。" }
            $offsets[$i] = [int]$token
        }
        $doc.ObjStreams[$streamNum] = @{ Text = $text; First = $first; Numbers = $numbers; Offsets = $offsets }
    }
    $info = $doc.ObjStreams[$streamNum]
    $position = -1
    if ($index -ge 0 -and $index -lt $info.Numbers.Length -and $info.Numbers[$index] -eq $num) {
        $position = $index
    } else {
        # 位置は細工できるため、番号から位置への辞書を 1 度だけ作って引く（毎回先頭から探すと、件数の 2 乗の比較になる）
        if (-not $info.ContainsKey("Positions")) {
            $positions = @{}
            for ($i = 0; $i -lt $info.Numbers.Length; $i++) {
                if (-not $positions.ContainsKey($info.Numbers[$i])) { $positions[$info.Numbers[$i]] = $i }
            }
            $info.Positions = $positions
        }
        $position = if ($info.Positions.ContainsKey([int]$num)) { $info.Positions[[int]$num] } else { -1 }
    }
    if ($position -lt 0) { return $null }
    $st = newPdfLexer $info.Text ($info.First + $info.Offsets[$position])
    return (readPdfValue $doc $st 0)
}

function addPdfXrefEntry {
    param (
        [hashtable]$doc,
        [long]$num,
        [hashtable]$entry
    )

    # 同じ番号を繰り返しても増えないので、読んだ行の総数も数える
    $doc.XrefRows += 1
    if ($doc.XrefRows -gt $doc.Limits.MaxObjects) {
        throw "PDFのオブジェクトの数が上限を超えるため読めません。"
    }
    if ($num -lt 0 -or $num -gt 2147483647) { return }
    if (-not $doc.Xref.ContainsKey([int]$num)) {
        $doc.Xref[[int]$num] = $entry
        if ($doc.Xref.Count -gt $doc.Limits.MaxObjects) {
            throw "PDFのオブジェクトの数が上限を超えるため読めません。"
        }
    } elseif ($doc.Hybrid -and $doc.Xref[[int]$num].Type -eq 0 -and $entry.Type -ne 0) {
        $doc.Xref[[int]$num] = $entry
    }
}

function readPdfXref {
    # オフセットにある相互参照（表または相互参照のストリーム）を読み、前の相互参照（Prev・XRefStm）も順にたどる。
    # 新しいものが先に入る。暗号化（Encrypt）の辞書の場所と ID は doc に覚える。ファイルの外を指す・循環・数が上限を超えるのは例外。
    # 入れ子の呼び出しにせず、待ちの積み上げで読む（Prev が長く続いても呼び出しが深くならない）
    param (
        [hashtable]$doc,
        [long]$offset
    )

    $pending = [System.Collections.Generic.Stack[object]]::new()
    $pending.Push(@{ Offset = $offset; Hybrid = $false })
    while ($pending.Count -gt 0) {
        if ($doc.Visited.Count -ge $doc.Limits.MaxXref) {
            throw "PDFの相互参照の数が上限を超えるため読めません。"
        }
        $job = $pending.Pop()
        $next = readPdfXrefSection $doc $job.Offset $job.Hybrid
        # 先に XRefStm、次に Prev の順に読む（Prev を先に積む）
        if ($next.Prev -ge 0) { $pending.Push(@{ Offset = $next.Prev; Hybrid = $false }) }
        if ($next.Stm -ge 0) { $pending.Push(@{ Offset = $next.Stm; Hybrid = $true }) }
    }
}

function readPdfXrefSection {
    # 相互参照 1 つ分を読み、次に読む位置 @{ Stm; Prev }（無ければ -1）を返す。
    # hybrid（XRefStm で読むもの）は、表で「解放済み」とされた番号を上書きする（旧い読み手から隠すための作り）
    param (
        [hashtable]$doc,
        [long]$offset,
        [bool]$hybrid = $false
    )

    $doc.Hybrid = $hybrid

    $text = $doc.Text
    if ($offset -lt 0 -or $offset -ge $text.Length) {
        throw "PDFの相互参照がファイルの外を指しているため読めません。"
    }
    if ($doc.Visited.ContainsKey($offset)) {
        throw "PDFの相互参照が循環しているため読めません。"
    }
    $doc.Visited[$offset] = $true
    $p = [int]$offset
    while ($p -lt $text.Length -and [int]$text[$p] -le 32) { $p++ }
    $max = $doc.Limits.MaxObjects
    if ([string]::CompareOrdinal($text, $p, "xref", 0, 4) -eq 0) {
        $st = newPdfLexer $text ($p + 4)
        while ($true) {
            $a = readPdfToken $st
            if ($st.K -eq "kw" -and $a -ceq "trailer") { break }
            if ($st.K -ne "num") {
                throw "PDFの相互参照の表が読めないため読めません。"
            }
            $first = [long]$a
            $count = readPdfToken $st
            if ($st.K -ne "num" -or $count -lt 0 -or $count -gt $max) {
                throw "PDFの相互参照の表が読めない、またはオブジェクトの数が上限を超えるため読めません。"
            }
            $pp = $st.P
            for ($k = 0; $k -lt $count; $k++) {
                while ($pp -lt $text.Length -and [int]$text[$pp] -le 32) { $pp++ }
                $entryOffset = 0L
                $kind = ""
                if ($pp + 17 -lt $text.Length -and $text[$pp + 10] -eq " " -and $text[$pp + 16] -eq " " -and
                    [long]::TryParse($text.Substring($pp, 10), [ref]$entryOffset)) {
                    $kind = [string]$text[$pp + 17]
                    $pp += 18
                } else {
                    $st.P = $pp
                    $o = readPdfToken $st
                    $okO = ($st.K -eq "num")
                    [void](readPdfToken $st)
                    $t = readPdfToken $st
                    if (-not $okO -or $st.K -ne "kw") {
                        throw "PDFの相互参照の表が読めないため読めません。"
                    }
                    $entryOffset = [long]$o
                    $kind = [string]$t
                    $pp = $st.P
                }
                if ($kind -ceq "n" -and $entryOffset -gt 0) {
                    addPdfXrefEntry $doc ($first + $k) @{ Type = 1; Offset = $entryOffset }
                } else {
                    addPdfXrefEntry $doc ($first + $k) @{ Type = 0 }
                }
            }
            $st.P = $pp
        }
        $trailer = readPdfValue $doc $st 0
    } else {
        $stream = readPdfIndirectAt $doc $p -1
        if (-not (testPdfStream $stream) -or $stream.Dict["Type"] -cne "/XRef") {
            throw "PDFの相互参照が読めないため読めません。"
        }
        $trailer = $stream.Dict
        $data = getPdfStreamBytes $doc $stream
        $w = @(resolvePdf $doc $trailer["W"])
        if ($w.Count -ne 3) {
            throw "PDFの相互参照のストリームが壊れているため読めません。"
        }
        $w0 = [int]$w[0]
        $w1 = [int]$w[1]
        $w2 = [int]$w[2]
        if ($w0 -lt 0 -or $w1 -lt 0 -or $w2 -lt 0 -or $w0 -gt 8 -or $w1 -gt 8 -or $w2 -gt 8 -or ($w0 + $w1 + $w2) -eq 0) {
            throw "PDFの相互参照のストリームが壊れているため読めません。"
        }
        $rowLength = $w0 + $w1 + $w2
        $index = resolvePdf $doc $trailer["Index"]
        if ($null -eq $index) {
            $index = @(0, [int](resolvePdf $doc $trailer["Size"]))
        }
        $index = @($index)
        $pos = 0
        for ($g = 0; $g + 1 -lt $index.Count; $g += 2) {
            $first = [long]$index[$g]
            $count = [long]$index[$g + 1]
            if ($count -lt 0 -or $count -gt $max) {
                throw "PDFのオブジェクトの数が上限を超えるため読めません。"
            }
            for ($k = 0; $k -lt $count; $k++) {
                if ($pos + $rowLength -gt $data.Length) {
                    throw "PDFの相互参照のストリームが壊れているため読めません。"
                }
                $type = 1L
                if ($w0 -gt 0) {
                    $type = 0L
                    for ($j = 0; $j -lt $w0; $j++) { $type = $type * 256 + $data[$pos + $j] }
                }
                $f2 = 0L
                for ($j = 0; $j -lt $w1; $j++) { $f2 = $f2 * 256 + $data[$pos + $w0 + $j] }
                $f3 = 0L
                for ($j = 0; $j -lt $w2; $j++) { $f3 = $f3 * 256 + $data[$pos + $w0 + $w1 + $j] }
                $pos += $rowLength
                if ($type -eq 1) {
                    addPdfXrefEntry $doc ($first + $k) @{ Type = 1; Offset = $f2 }
                } elseif ($type -eq 2) {
                    addPdfXrefEntry $doc ($first + $k) @{ Type = 2; Stream = [int]$f2; Index = [int]$f3 }
                } else {
                    addPdfXrefEntry $doc ($first + $k) @{ Type = 0 }
                }
            }
        }
    }

    if (-not (testPdfDict $trailer)) {
        throw "PDFの相互参照のあとの情報が読めないため読めません。"
    }
    if ($trailer.ContainsKey("Encrypt") -and $null -eq $doc.EncryptEntry) {
        # 新しい方のトレーラーを使う。辞書は、相互参照がそろってから読む（readPdfPagesCore）
        $doc.EncryptEntry = $trailer["Encrypt"]
    }
    if ($null -eq $doc.Root -and $trailer.ContainsKey("Root")) {
        $doc.Root = $trailer["Root"]
    }
    $next = @{ Stm = -1L; Prev = -1L }
    if ($trailer.ContainsKey("XRefStm")) { $next.Stm = [long]$trailer["XRefStm"] }
    if ($trailer.ContainsKey("Prev")) { $next.Prev = [long]$trailer["Prev"] }
    return $next
}

function addPdfMapEntries {
    # 文字の対応表の項目を数え、1 ファイルの合計が上限を超えたら例外にする（doc が無いときは数えない）
    param (
        $doc,
        [long]$count
    )

    if ($null -eq $doc) { return }
    $doc.MapEntries += $count
    if ($doc.MapEntries -gt $doc.Limits.MaxMapEntries) {
        throw "PDFの文字の対応表が大きすぎるため読めません。"
    }
}

function readPdfToUnicode {
    # ToUnicode の CMap から、文字コード → 文字列の表 Map（キーは int）と、文字コードのバイト数 Width（0 は指定なし）を返す
    param (
        [string]$text,
        [hashtable]$doc = $null
    )

    $map = @{}
    $width = 0
    $st = newPdfLexer $text 0
    $utf16 = [System.Text.Encoding]::BigEndianUnicode
    while ($true) {
        $t = readPdfToken $st
        if ($st.K -eq "eof") { break }
        if ($st.K -ne "kw") { continue }
        if ($t -ceq "begincodespacerange") {
            while ($true) {
                $lo = readPdfToken $st
                if ($st.K -ne "str") { break }
                [void](readPdfToken $st)
                if ($width -eq 0 -and $lo.Length -ge 1 -and $lo.Length -le 2) { $width = $lo.Length }
            }
        } elseif ($t -ceq "beginbfchar") {
            while ($true) {
                $src = readPdfToken $st
                if ($st.K -ne "str") { break }
                $dst = readPdfToken $st
                if ($st.K -ne "str") { break }
                if ($src.Length -eq 0 -or $src.Length -gt 3) { continue }
                addPdfMapEntries $doc 1
                $map[(convertPdfCode $src)] = convertPdfUtf16 $dst $utf16
            }
        } elseif ($t -ceq "beginbfrange") {
            while ($true) {
                $lo = readPdfToken $st
                if ($st.K -ne "str") { break }
                $hi = readPdfToken $st
                if ($st.K -ne "str") { break }
                $dst = readPdfToken $st
                $kind = $st.K
                if ($lo.Length -eq 0 -or $lo.Length -gt 3 -or $hi.Length -eq 0 -or $hi.Length -gt 3) {
                    if ($kind -eq "[") {
                        while ($true) { [void](readPdfToken $st); if ($st.K -eq "]" -or $st.K -eq "eof") { break } }
                    }
                    continue
                }
                $from = convertPdfCode $lo
                $to = [Math]::Min((convertPdfCode $hi), $from + 65535)
                if ($kind -eq "str") {
                    $base = convertPdfUtf16 $dst $utf16
                    if ($base.Length -eq 0) { continue }
                    if ($to -ge $from) { addPdfMapEntries $doc ($to - $from + 1) }
                    $head = $base.Substring(0, $base.Length - 1)
                    $lastCode = [int]$base[$base.Length - 1]
                    for ($c = $from; $c -le $to; $c++) {
                        $map[[int]$c] = $head + [char](($lastCode + $c - $from) -band 65535)
                    }
                } elseif ($kind -eq "[") {
                    $c = $from
                    while ($true) {
                        $item = readPdfToken $st
                        if ($st.K -ne "str") { break }
                        if ($c -le $to) {
                            addPdfMapEntries $doc 1
                            $map[[int]$c] = convertPdfUtf16 $item $utf16
                        }
                        $c++
                    }
                }
            }
        }
    }
    return @{ Map = $map; Width = $width }
}

function convertPdfCode {
    # 1 バイト 1 文字の文字列を、ビッグエンディアンの文字コード（int）にする（3 バイトまで）
    param (
        [string]$s
    )

    $code = 0
    foreach ($ch in $s.ToCharArray()) { $code = $code * 256 + [int]$ch }
    return [int]$code
}

function convertPdfUtf16 {
    # 1 バイト 1 文字の文字列（UTF-16BE のバイト列）を文字列にする。奇数バイトのときは 1 バイトずつ文字にする
    param (
        [string]$s,
        $utf16
    )

    if ($s.Length % 2 -eq 1) { return $s }
    return $utf16.GetString(${pdfLatin1}.GetBytes($s))
}

function newPdfFont {
    # フォントの辞書から、文字列を文字にする規則 @{ Width; Map; NoMap } を作る。
    # ToUnicode があればそれを使う。無い単純フォントは WinAnsi 相当（Windows-1252）。無い複合フォント（CID）は NoMap（使ったときに例外）
    param (
        [hashtable]$doc,
        $dict
    )

    $font = @{ Width = 1; Map = $null; NoMap = $false }
    if (-not (testPdfDict $dict)) { return $font }
    $isComposite = ($dict["Subtype"] -ceq "/Type0")
    if ($isComposite) { $font.Width = 2 }
    $toUnicodeRef = $dict["ToUnicode"]
    $toUnicode = resolvePdf $doc $toUnicodeRef
    if (testPdfStream $toUnicode) {
        # 同じ ToUnicode を使うフォントが多くても、1 度だけ読む（番号ごとに控える）
        $key = $null
        if (testPdfRef $toUnicodeRef) { $key = $toUnicodeRef["N"] }
        if ($null -ne $key -and $doc.CMaps.ContainsKey($key)) {
            $cmap = $doc.CMaps[$key]
        } else {
            $bytes = getPdfStreamBytes $doc $toUnicode
            $cmap = readPdfToUnicode (${pdfLatin1}.GetString($bytes)) $doc
            if ($null -ne $key) { $doc.CMaps[$key] = $cmap }
        }
        $font.Map = $cmap.Map
        if ($cmap.Width -gt 0) { $font.Width = $cmap.Width }
    } elseif ($isComposite) {
        $font.NoMap = $true
    }
    return $font
}

function convertPdfStringToText {
    # 文字列（1 バイト 1 文字）を、フォントの規則で文字列にする
    param (
        $font,
        [string]$s
    )

    if ($null -ne $font -and $font.NoMap) {
        throw "PDFの文字の対応表が無いため読めません。"
    }
    if ($null -eq $font -or $null -eq $font.Map) {
        return ${pdfWinAnsi}.GetString(${pdfLatin1}.GetBytes($s))
    }
    $map = $font.Map
    $width = $font.Width
    $sb = [System.Text.StringBuilder]::new()
    for ($i = 0; $i -lt $s.Length; $i += $width) {
        if ($width -eq 2) {
            if ($i + 1 -ge $s.Length) { break }
            $code = [int]$s[$i] * 256 + [int]$s[$i + 1]
        } else {
            $code = [int]$s[$i]
        }
        if ($map.ContainsKey($code)) {
            [void]$sb.Append($map[$code])
        } elseif ($width -eq 1) {
            [void]$sb.Append(${pdfWinAnsi}.GetString([byte[]]@($code)))
        }
    }
    return $sb.ToString()
}

function testPdfHalfWidth {
    # 半角の文字か（ラテン文字の範囲）。TJ の詰めに空白を入れるかの判断に使う
    param (
        [char]$c
    )

    return ([int]$c -le 0x24F)
}

function getPdfGlyphCount {
    # 文字列が表す字形（フォントの 1 コード）の数。1 コードが 2 文字になる対応（合字）でも 1 と数える
    param (
        $font,
        [string]$s
    )

    if ($null -eq $font -or $null -eq $font.Map -or $font.Width -ne 2) { return $s.Length }
    return [int][Math]::Ceiling($s.Length / 2)
}

function addPdfText {
    # ページの文字に文字列を足す。詰め（Gap）が付いていて、前後の文字がどちらも半角のときだけ空白を入れる
    param (
        [hashtable]$ts,
        [string]$text,
        [int]$glyphs = 1
    )

    if ($text.Length -eq 0) { return }
    # 縦位置が前に出した文字と違うときだけ行を分ける（BT～ET で分かれていても、同じ縦位置なら同じ行）
    if ($ts.HasOut -and [Math]::Abs($ts.Y - $ts.OutY) -gt ${pdfLineTolerance}) {
        breakPdfLine $ts
    }
    $ts.HasOut = $true
    $ts.OutY = $ts.Y
    $ts.Run += $glyphs
    $sb = $ts.Sb
    if ($ts.Gap -and $sb.Length -gt 0) {
        $last = $sb[$sb.Length - 1]
        if ($last -ne "`n" -and $last -ne " " -and (testPdfHalfWidth $last) -and (testPdfHalfWidth $text[0]) -and $text[0] -ne " ") {
            [void]$sb.Append(" ")
        }
    }
    $ts.Gap = $false
    [void]$sb.Append($text)
}

function breakPdfLine {
    param (
        [hashtable]$ts
    )

    $sb = $ts.Sb
    if ($sb.Length -gt 0 -and $sb[$sb.Length - 1] -ne "`n") {
        [void]$sb.Append("`n")
    }
    $ts.Gap = $false
}

function readPdfPageText {
    # ページの内容（文字の命令）から文字列を作る。行送りは改行にする。
    # fontDict は フォント名 → フォント（辞書または参照）の辞書（無ければ $null）
    param (
        [hashtable]$doc,
        [string]$content,
        $fontDict
    )

    # Y は今の文字の縦位置（行の行列の y）、OutY は最後に出した文字の縦位置、Leading は行送り（TL）
    $ts = @{ Sb = [System.Text.StringBuilder]::new(); Gap = $false; Y = 0.0; OutY = 0.0; HasOut = $false; Leading = 0.0; Scale = 1.0; Run = 0 }
    # 字句は、関数を呼ばずに、位置指定の正規表現（トークンの切り出しは readPdfToken と同じ規則）でその場で切り出す。
    # 取れないもの（入れ子やエスケープのある文字列・16 進の文字列・コメントなど）だけ readPdfToken に任せる（$st.P で位置を渡す）
    $st = newPdfLexer $content 0
    $pos = 0
    $len = $content.Length
    $re = ${pdfPageRegex}
    $reTok = ${pdfTokenRegex}
    $emptyMatch = [System.Text.RegularExpressions.Match]::Empty
    $nums = [System.Collections.Generic.List[double]]::new()
    $lastStr = $null
    $lastName = $null
    $lastArray = $null
    $font = $null
    $fontSize = 0.0
    while ($true) {
        $m = if ($pos -lt $len) { $re.Match($content, $pos) } else { $emptyMatch }
        if ($m.Success) {
            $g = $m.Groups[1]
            if ($g.Success) {
                # 文字に効かない命令までの並びを、まとめて飛ばす
                $pos = $g.Index + $g.Length
                $nums.Clear()
                $lastStr = $null
                $lastName = $null
                $lastArray = $null
                continue
            }
            $g = $m.Groups[2]
            if ($g.Success) {
                $t = $g.Value
                $pos = $g.Index + $g.Length
                $kind = "kw"
                $c = $t[0]
                if (($c -ge '0' -and $c -le '9') -or $c -eq '-' -or $c -eq '+' -or $c -eq '.') {
                    $d = 0.0
                    # 数の判定は readPdfToken と、TJ の配列の中の取り方と同じ。変えるときは 3 か所をそろえる
                    if ([double]::TryParse($t, [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$d) -and -not [double]::IsInfinity($d) -and -not [double]::IsNaN($d)) {
                        $t = $d
                        $kind = "num"
                    }
                }
            } else {
                $g = $m.Groups[3]
                $t = $g.Value
                $pos = $g.Index + $g.Length
                $c = $t[0]
                if ($c -eq '/') {
                    $kind = "name"
                    $t = $t.Substring(1)
                    if ($t.Contains("#")) {
                        # 名前の # の戻しは readPdfToken と同じ。変えるときは 2 か所をそろえる
                        $t = [regex]::Replace($t, '#([0-9A-Fa-f]{2})', { param($m) [string][char][Convert]::ToInt32($m.Groups[1].Value, 16) })
                    }
                } elseif ($c -eq '(') {
                    $kind = "str"
                    $t = $t.Substring(1, $t.Length - 2)
                } elseif ($c -eq '[') { $kind = "["
                } elseif ($c -eq ']') { $kind = "]"
                } elseif ($c -eq '<') { $kind = "<<"
                } elseif ($c -eq '>') { $kind = ">>"
                } else { $kind = "kw" }
            }
        } else {
            $st.P = $pos
            $t = readPdfToken $st
            $kind = $st.K
            $pos = $st.P
        }
        if ($kind -eq "eof") { break }
        if ($kind -eq "num") {
            if ($nums.Count -ge 64) { $nums.Clear() }
            $nums.Add($t)
            continue
        }
        if ($kind -eq "name") { $lastName = $t; continue }
        if ($kind -eq "str") { $lastStr = $t; continue }
        if ($kind -eq "[") {
            $items = [System.Collections.Generic.List[object]]::new()
            while ($true) {
                $m = if ($pos -lt $len) { $reTok.Match($content, $pos) } else { $emptyMatch }
                if ($m.Success) {
                    $g = $m.Groups[1]
                    if ($g.Success) {
                        $pos = $g.Index + $g.Length
                        $c = $g.Value[0]
                        if (($c -ge '0' -and $c -le '9') -or $c -eq '-' -or $c -eq '+' -or $c -eq '.') {
                            $d = 0.0
                            # 数の判定は readPdfToken と、readPdfPageText の最初の字句の取り方と同じ。変えるときは 3 か所をそろえる
                            if ([double]::TryParse($g.Value, [System.Globalization.NumberStyles]::Float, [System.Globalization.CultureInfo]::InvariantCulture, [ref]$d) -and -not [double]::IsInfinity($d) -and -not [double]::IsNaN($d)) {
                                $items.Add($d)
                            }
                        }
                    } else {
                        $g = $m.Groups[2]
                        $pos = $g.Index + $g.Length
                        $c = $g.Value[0]
                        if ($c -eq '(') { $items.Add($g.Value.Substring(1, $g.Value.Length - 2)) }
                        elseif ($c -eq ']') { break }
                    }
                } else {
                    $st.P = $pos
                    $item = readPdfToken $st
                    $pos = $st.P
                    if ($st.K -eq "]" -or $st.K -eq "eof") { break }
                    if ($st.K -eq "num" -or $st.K -eq "str") { $items.Add($item) }
                }
            }
            $lastArray = $items
            continue
        }
        if ($kind -eq "<<") {
            $nest = 1
            $st.P = $pos
            while ($nest -gt 0) {
                [void](readPdfToken $st)
                if ($st.K -eq "<<") { $nest++ } elseif ($st.K -eq ">>") { $nest-- } elseif ($st.K -eq "eof") { break }
            }
            $pos = $st.P
            continue
        }
        if ($kind -ne "kw") { continue }

        if ($t -ceq "Tj") {
            if ($null -ne $lastStr) { addPdfText $ts (convertPdfStringToText $font $lastStr) (getPdfGlyphCount $font $lastStr) }
        } elseif ($t -ceq "TJ") {
            if ($null -ne $lastArray) {
                foreach ($item in $lastArray) {
                    if ($item -is [string]) {
                        addPdfText $ts (convertPdfStringToText $font $item) (getPdfGlyphCount $font $item)
                    } elseif ($item -le ${pdfGapThreshold}) {
                        $ts.Gap = $true
                    }
                }
            }
        } elseif ($t -ceq "'" -or $t -ceq '"') {
            $ts.Y -= $ts.Leading * $ts.Scale
            $ts.Run = 0
            breakPdfLine $ts
            if ($null -ne $lastStr) { addPdfText $ts (convertPdfStringToText $font $lastStr) (getPdfGlyphCount $font $lastStr) }
        } elseif ($t -ceq "Tf") {
            $fontSize = if ($nums.Count -ge 1) { [Math]::Abs($nums[$nums.Count - 1]) } else { 0.0 }
            $font = $null
            if ($null -ne $lastName -and (testPdfDict $fontDict) -and $fontDict.ContainsKey($lastName)) {
                $font = getPdfFont $doc $fontDict[$lastName]
            }
        } elseif ($t -ceq "BT") {
            # テキストの行列は BT で初期化される（縦位置は 0 から）
            $ts.Y = 0.0
            $ts.Scale = 1.0
            $ts.Run = 0
        } elseif ($t -ceq "Td" -or $t -ceq "TD") {
            if ($nums.Count -ge 2) {
                # 縦の動きは、Tm の拡大（d）を掛けた値にする（`12 0 0 12 x y Tm` のあとの `0 -1 TD` は 12 ポイント動く）
                $ts.Y += $nums[1] * $ts.Scale
                if ($t -ceq "TD") { $ts.Leading = - $nums[1] }
                # 横にだけ動いたときは詰め。縦に動いたときは、次の文字を出すときに行を分ける。
                # 1 文字ずつ Td で並べる PDF（Chromium など）の文字を離さないよう、直前の Td 以降に出した文字が 1 文字以下で、
                # 前向きに 1 em より小さい動きは詰めにしない（空白は文字として入っている）。2 文字以上の語の後ろは空白でつなぐ
                $joined = ($fontSize -gt 0 -and $nums[0] -gt 0 -and $nums[0] -lt $fontSize -and $ts.Run -le 1)
                if ($nums[0] -ne 0 -and -not $joined) { $ts.Gap = $true }
                $ts.Run = 0
            }
        } elseif ($t -ceq "TL") {
            if ($nums.Count -ge 1) { $ts.Leading = $nums[0] }
        } elseif ($t -ceq "T*") {
            $ts.Y -= $ts.Leading * $ts.Scale
            $ts.Run = 0
            breakPdfLine $ts
        } elseif ($t -ceq "Tm") {
            if ($nums.Count -ge 6) {
                $ts.Y = $nums[5]
                # 上下を反転した行列（d が負）は、縦の動きの向きも反転するので、d の符号を残す
                $ts.Scale = [Math]::Sqrt($nums[2] * $nums[2] + $nums[3] * $nums[3])
                if ($nums[3] -lt 0) { $ts.Scale = -$ts.Scale }
                $ts.Run = 0
                $ts.Gap = $true
            }
        } elseif ($t -ceq "BI") {
            # 画像の中身（バイナリ）は読まない。ID から EI までを飛ばす
            $idPos = $content.IndexOf("ID", $pos, [StringComparison]::Ordinal)
            if ($idPos -lt 0) { break }
            $scan = $idPos + 2
            $endPos = -1
            while ($true) {
                $found = $content.IndexOf("EI", $scan, [StringComparison]::Ordinal)
                if ($found -lt 0) { break }
                $beforeOk = ($found -eq 0 -or [int]$content[$found - 1] -le 32)
                $afterOk = ($found + 2 -ge $content.Length -or [int]$content[$found + 2] -le 32)
                if ($beforeOk -and $afterOk) { $endPos = $found + 2; break }
                $scan = $found + 2
            }
            if ($endPos -lt 0) { break }
            $pos = $endPos
        }
        $nums.Clear()
        $lastStr = $null
        $lastName = $null
        $lastArray = $null
    }
    return ([regex]::Replace($ts.Sb.ToString(), '[\x00-\x09\x0B-\x1F\x7F]', " ")).TrimEnd("`n")
}

function getPdfFont {
    # フォント（辞書または参照）の規則を返す。参照のものは番号ごとに控える
    param (
        [hashtable]$doc,
        $ref
    )

    if (testPdfRef $ref) {
        $num = $ref["N"]
        if (-not $doc.Fonts.ContainsKey($num)) {
            $doc.Fonts[$num] = newPdfFont $doc (resolvePdf $doc $ref)
        }
        return $doc.Fonts[$num]
    }
    return (newPdfFont $doc $ref)
}

function walkPdfPages {
    # ページツリーをたどり、ページ（@{ Dict; Resources }）を順に pages に足す。
    # 同じノードを 2 度たどる（循環）・深すぎる・ページが多すぎるときは例外
    param (
        [hashtable]$doc,
        $node,
        $inheritedResources,
        [int]$depth,
        $pages
    )

    if ($depth -gt $doc.Limits.MaxDepth) {
        throw "PDFのページの入れ子が深すぎるため読めません。"
    }
    if (testPdfRef $node) {
        if ($doc.SeenNodes.ContainsKey($node["N"])) {
            throw "PDFのページの並びが循環しているため読めません。"
        }
        $doc.SeenNodes[$node["N"]] = $true
    }
    $dict = resolvePdf $doc $node
    if (-not (testPdfDict $dict)) { return }
    $resources = $inheritedResources
    if ($dict.ContainsKey("Resources")) { $resources = $dict["Resources"] }
    if ($dict.ContainsKey("Kids")) {
        $kids = resolvePdf $doc $dict["Kids"]
        foreach ($kid in @($kids)) {
            walkPdfPages $doc $kid $resources ($depth + 1) $pages
        }
        return
    }
    if ($pages.Count -ge $doc.Limits.MaxPages) {
        throw "PDFのページ数が上限を超えるため読めません。"
    }
    $pages.Add(@{ Dict = $dict; Resources = $resources })
}

function readPdfPages {
    # PDF のバイト列から、ページごとの文字列（行は改行で区切る。文字の無いページは空）の配列を返す。
    # 読めない PDF（パスワードが要る・暗号化の方式が未対応・壊れている・上限を超える・読まない圧縮・文字の対応表が無い）は、「PDF」で始まる日本語の例外にする
    param (
        [byte[]]$bytes,
        [hashtable]$limits = $null
    )

    if ($null -eq $limits) { $limits = newPdfLimits }
    try {
        return , (readPdfPagesCore $bytes $limits)
    } catch {
        $message = $_.Exception.Message
        if ($message.StartsWith("PDF")) {
            throw $message
        }
        throw "PDFが壊れているため読めません。"
    }
}

function readPdfPagesCore {
    param (
        [byte[]]$bytes,
        [hashtable]$limits
    )

    $text = ${pdfLatin1}.GetString($bytes)
    if ($text.IndexOf("%PDF-", 0, [Math]::Min(1024, $text.Length), [StringComparison]::Ordinal) -lt 0) {
        throw "PDFではないか、壊れているため読めません。"
    }
    $doc = @{
        Bytes = $bytes; Text = $text; Limits = $limits
        Xref = @{}; Cache = @{}; Loading = @{}; ObjStreams = @{}; Fonts = @{}; Visited = @{}; SeenNodes = @{}
        Inflated = [long]0; XrefRows = [long]0; Searched = [long]0; Root = $null; EndSearch = @{ From = 1; At = 0 }; Hybrid = $false; CMaps = @{}; MapEntries = [long]0
        Crypt = $null; EncryptEntry = $null
    }
    $start = $text.LastIndexOf("startxref", [StringComparison]::Ordinal)
    if ($start -lt 0) {
        throw "PDFの相互参照が見つからないため読めません。"
    }
    $st = newPdfLexer $text ($start + 9)
    $offset = readPdfToken $st
    if ($st.K -ne "num") {
        throw "PDFの相互参照の位置が読めないため読めません。"
    }
    readPdfXref $doc ([long]$offset)
    if ($null -ne $doc.EncryptEntry) {
        $enc = resolvePdf $doc $doc.EncryptEntry
        if (-not (testPdfDict $enc)) {
            throw "PDFの暗号化の情報が壊れているため読めません。"
        }
        $doc.Crypt = newPdfCrypt $doc $enc
    }

    $root = resolvePdf $doc $doc.Root
    if (-not (testPdfDict $root)) {
        throw "PDFの文書の入り口が見つからないため読めません。"
    }
    $pages = [System.Collections.Generic.List[object]]::new()
    walkPdfPages $doc $root["Pages"] $null 0 $pages

    $result = New-Object string[] $pages.Count
    for ($i = 0; $i -lt $pages.Count; $i++) {
        $page = $pages[$i]
        $contents = resolvePdf $doc $page.Dict["Contents"]
        $buffer = [System.IO.MemoryStream]::new()
        foreach ($item in @($contents)) {
            $stream = resolvePdf $doc $item
            if (testPdfStream $stream) {
                $data = getPdfStreamBytes $doc $stream
                $buffer.Write($data, 0, $data.Length)
                $buffer.WriteByte(10)
            }
        }
        $resources = resolvePdf $doc $page.Resources
        $fontDict = $null
        if (testPdfDict $resources) { $fontDict = resolvePdf $doc $resources["Font"] }
        $result[$i] = readPdfPageText $doc (${pdfLatin1}.GetString($buffer.ToArray())) $fontDict
    }
    return , $result
}

function readPdfFile {
    # PDF ファイルを読み、ページごとの文字列の配列を返す（readPdfPages）。
    # 大きさが maxBytes を超えるときは読まずに例外にする
    param (
        [string]$path,
        [long]$maxBytes = ${pdfFileMaxBytes},
        [hashtable]$limits = $null
    )

    if ([System.IO.FileInfo]::new((toLongPath $path)).Length -gt $maxBytes) {
        throw "ファイルサイズが大きすぎるため更新できません。"
    }
    $bytes = [System.IO.File]::ReadAllBytes((toLongPath $path))
    return , (readPdfPages $bytes $limits)
}

# TSV のファイルの読み書き（状態層）。整形の中身（formatTsv）は text.ps1（判断層）。

function prettyTsv {
    # Excelが出力したTSV（UTF-16）を整形してUTF-8で保存する。内容が空なら保存せず $false を返す
    #   firstRow, firstColumn: Excelが出力した範囲の左上のセルの行・列番号
    param (
        [string]$inputFilePath,
        [string]$outputFilePath,
        [int]$firstRow = 1,
        [int]$firstColumn = 1
    )

    $content = formatTsv ([System.IO.File]::ReadAllText((toLongPath $inputFilePath))) $firstRow $firstColumn
    if ($content -eq "") {
        return $false
    }

    [System.IO.File]::WriteAllText((toLongPath $outputFilePath), "${content}`r`n", ${utf8Bom})
    return $true
}

# フォルダのパス（正規化・同一判定・ドライブ・フォルダ選択の開始フォルダ）。

function normalizeFolderPath {
    # フォルダパスを1つの書き方にそろえる（書き方の違いで同じフォルダを別のフォルダとみなさないため）。
    #   ・前後の空白・" を取り除く
    #   ・環境変数（%USERPROFILE% など）を展開する
    #   ・/ を \ にそろえ、長いパス用の \\?\ ・ \\?\UNC\ を外す（ファイル操作に渡す直前に toLongPath で付け直す）
    #   ・重なった \ ・ . ・ .. を解決する
    #   ・相対パスはツールのフォルダ（$rootDir）からとみなして絶対パスにする
    #   ・末尾の \ を取り除く（ドライブ直下は "D:\" のまま。UNC の共有直下は "\\server\share"）
    # パスとして解釈できない場合（* ? を含む・共有名の無い \\server など）は、書かれたとおりに扱う
    param (
        [string]$path
    )

    $path = $path.Trim().Trim('"').Trim()
    if ($path -eq "") {
        return ""
    }
    if ($path.IndexOf("%") -ge 0) {
        $path = [System.Environment]::ExpandEnvironmentVariables($path).Trim()
    }
    $path = (fromLongPath ($path.Replace("/", "\"))).TrimEnd("\")
    if ($path -eq "") {
        return ""
    }
    # ドライブ名だけ（"D:"）はドライブ直下とする。
    # GetFullPath はそのドライブの「現在のフォルダ」を返すことがあるため、先に決める
    if ($path -match "^[A-Za-z]:$") {
        return "${path}\"
    }
    try {
        if (![System.IO.Path]::IsPathRooted($path)) {
            # 相対パスはツールのフォルダからとみなす
            $path = [System.IO.Path]::GetFullPath([System.IO.Path]::Combine(${rootDir}, $path)).TrimEnd("\")
        } elseif ($path -match "^[A-Za-z]:\\" -or $path.StartsWith("\\")) {
            $path = [System.IO.Path]::GetFullPath($path).TrimEnd("\")
        }
        # \ ひとつで始まるパス（"\server\share"）は、書き間違えた UNC パスのことが多いため、
        # 今のドライブのパスに直さず、書かれたとおりに扱う
    } catch {
        # パスとして解釈できない場合は、書かれたとおりに扱う（存在しないフォルダとして扱われる）
    }
    if ($path -match "^[A-Za-z]:$") {
        return "${path}\"
    }
    return $path
}

function getPathUnderFolder {
    # path が folder 自身か folder の下なら、folder からの相対パス（folder 自身は ""）を返す。
    # folder の下でなければ $null（大文字・小文字は区別しない）。
    # パスの文字数で切り出すと、書き方が少し違うだけ（末尾の \ ・\\?\ 付きなど）で取り違えるため、この関数を通す
    param (
        [string]$path,
        [string]$folder
    )

    $folder = $folder.TrimEnd("\")
    $path = $path.TrimEnd("\")
    if ($folder -eq "" -or $path -eq "") {
        return $null
    }
    if ($path.Equals($folder, [System.StringComparison]::OrdinalIgnoreCase)) {
        return ""
    }
    if ($path.StartsWith("${folder}\", [System.StringComparison]::OrdinalIgnoreCase)) {
        return $path.Substring($folder.Length + 1)
    }
    return $null
}


# ドライブ文字の割り当て先（ネットワークドライブ）は CIM で調べる（getDriveTargets 参照）。
# ※以前は Win32 API（QueryDosDevice）で subst も解決していたが、実行時コンパイル（csc.exe）を無くすため CIM に変更した。

${driveTargets} = $null


function testAnyNetworkPath {
    # 一覧の中にネットワークのパスが 1 つでもあるか（インデックスの一覧・設定にネットワークのパスがあるときだけ、
    # 起動時にドライブの割り当てを裏の列で照会するために使う）
    param (
        [string[]]$paths
    )

    foreach ($path in $paths) {
        if (testNetworkPath $path) {
            return $true
        }
    }
    return $false
}

function setDriveTargets {
    # getDriveTargets のキャッシュを外から設定する。ネットワークを調べる列で照会した結果を、
    # 画面のスレッドのキャッシュに入れるために使う（画面のスレッドで CIM を照会しないようにする）
    param (
        $targets
    )

    ${script:driveTargets} = $targets
}

function getDriveTargets {
    # ドライブ文字（"Z:"）→ 割り当て先（ネットワークドライブは "\\server\share"）を返す。
    # 同じプロセスでは1回だけ調べる（インデックス作成・検索の途中で割り当てが変わることは想定しない）。
    # subst で割り当てたドライブは解決しない（CIM で取れないため。実運用ではネットワークドライブが主）。
    if ($null -ne ${script:driveTargets}) {
        return ${script:driveTargets}
    }
    $map = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::OrdinalIgnoreCase)
    try {
        # DriveType=4 はネットワークドライブ。DeviceID="Z:"、ProviderName="\\server\share"
        foreach ($d in @(Get-CimInstance -ClassName Win32_LogicalDisk -Filter "DriveType=4" -ErrorAction SilentlyContinue)) {
            if ($d.ProviderName) {
                $map[$d.DeviceID] = $d.ProviderName.TrimEnd("\")
            }
        }
    } catch {
        # 調べられない環境では別名なしとする（パスを書かれたとおりに使う）
    }
    ${script:driveTargets} = $map
    return $map
}

function getFolderPathAliases {
    # 同じ場所を指す別の書き方を、path 自身を先頭にして返す（ドライブの割り当てをたどる）。
    # ファイルサーバーのフォルダは、ネットワークドライブ（Z:\…）と UNC パス（\\server\share\…）のどちらでも書けるため、
    # 設定に書いた書き方と、インデックスに記録した書き方が違っても同じフォルダと分かるようにする。
    #   Z: が \\server\share のネットワークドライブのとき
    #     "Z:\見積"             → @("Z:\見積", "\\server\share\見積")
    #     "\\server\share\見積" → @("\\server\share\見積", "Z:\見積")
    param (
        [string]$path,
        $drives = (getDriveTargets)  # ドライブ文字 → 割り当て先（テストで差し替える）
    )

    $result = New-Object System.Collections.Generic.List[string]
    $result.Add($path)
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    [void]$seen.Add($path.TrimEnd("\"))

    foreach ($entry in $drives.GetEnumerator()) {
        $alias = $null
        # ドライブ文字 → 割り当て先
        $rest = getPathUnderFolder $path $entry.Key
        if ($null -ne $rest) {
            $alias = if ($rest -eq "") { $entry.Value } else { joinSourcePath $entry.Value $rest }
        } else {
            # 割り当て先 → ドライブ文字
            $rest = getPathUnderFolder $path $entry.Value
            if ($null -ne $rest) {
                $alias = if ($rest -eq "") { "$($entry.Key)\" } else { joinSourcePath "$($entry.Key)\" $rest }
            }
        }
        if ($alias -and $seen.Add($alias.TrimEnd("\"))) {
            $result.Add($alias)
        }
    }
    return $result.ToArray()
}

function testSameFolder {
    # 2つのパスが同じフォルダを指すか（末尾の \ ・大文字と小文字の違いと、ネットワークドライブ・subst の割り当てをたどる）
    param (
        [string]$a,
        [string]$b,
        $drives = $null  # ドライブ文字 → 割り当て先（テストで差し替える。$null は getDriveTargets）
    )

    $target = $b.TrimEnd("\")
    # 書き方どおりに同じなら、ドライブの割り当て（CIM。初回は 0.2 秒以上、切断されたネットワークドライブがあるとさらにかかる）を調べない
    if ($a.TrimEnd("\").Equals($target, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $true
    }
    if ($null -eq $drives) {
        # getDriveTargets（CIM）が返す別名はネットワークドライブ⇔UNCの組しか無いため、
        # どちらかがローカル（ネットワークでない）なら、別名を調べても一致しえない。CIM を照会しない
        if (!(testNetworkPath $a) -or !(testNetworkPath $b)) {
            return $false
        }
        $drives = getDriveTargets
    }
    foreach ($alias in @(getFolderPathAliases $a $drives)) {
        if ($alias.TrimEnd("\").Equals($target, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $true
        }
    }
    return $false
}

function testFolderUnder {
    # path が folder 自身か folder の下のフォルダかを返す（testSameFolder と同じく、書き方の違い・ドライブの割り当てをたどる）。
    # クロール対象フォルダが入れ子になると、同じファイルが2つのインデックスに入り、検索結果にも二重に出るため、その確認に使う
    param (
        [string]$path,
        [string]$folder,
        $drives = $null  # ドライブ文字 → 割り当て先（テストで差し替える。$null は getDriveTargets）
    )

    if ($path -eq "" -or $folder -eq "") {
        return $false
    }
    # 書き方どおりに下にあれば、ドライブの割り当て（CIM）を調べない
    if ($null -ne (getPathUnderFolder $path $folder)) {
        return $true
    }
    if ($null -eq $drives) {
        # testSameFolder と同じ理由で、どちらかがローカルなら CIM を照会しない
        if (!(testNetworkPath $path) -or !(testNetworkPath $folder)) {
            return $false
        }
        $drives = getDriveTargets
    }
    foreach ($alias in @(getFolderPathAliases $path $drives)) {
        if ($null -ne (getPathUnderFolder $alias $folder)) {
            return $true
        }
    }
    return $false
}

function testNetworkPath {
    # パス（normalizeFolderPath 済み）がネットワークの場所を指すかを、共有に接続せずに見分ける。
    #   \\server\share\… ・\\?\UNC\… は UNC（ネットワーク）。
    #   \\?\C:\…（toLongPath の形）・\\.\… は \\ で始まるが UNC ではないため、ドライブ文字として扱う。
    #   ドライブ文字なら DriveInfo.DriveType を見る（GetDriveType は共有に接続しない）。
    #   Fixed・Removable・CDRom・Ram だけをローカルとし、Network と、切断したドライブがそう見えることのある
    #   NoRootDirectory・Unknown は、安全な側に倒してネットワークとする
    #   driveType: ドライブの種類を引く関数（テストで差し替える）。既定は実際の DriveInfo
    param (
        [string]$path,
        [scriptblock]$driveType = { param ($drive) ([System.IO.DriveInfo]$drive).DriveType }
    )

    if ($path -eq "") {
        return $false
    }
    $p = $path.Replace("/", "\")
    if ($p.StartsWith("\\?\UNC\")) {
        return $true
    }
    $rest = $p
    if ($p.StartsWith("\\?\") -or $p.StartsWith("\\.\")) {
        $rest = $p.Substring(4)
    } elseif ($p.StartsWith("\\")) {
        return $true  # \\server\share\…（UNC）
    }
    if ($rest -notmatch "^[A-Za-z]:") {
        return $false  # ドライブ文字が無い（相対パスなど）はローカルとみなす
    }
    $drive = "$($rest.Substring(0, 1)):\"
    try {
        $type = & $driveType $drive
    } catch {
        return $true  # 調べられなければ安全な側（ネットワーク）に倒す
    }
    return $type -notin @([System.IO.DriveType]::Fixed, [System.IO.DriveType]::Removable, [System.IO.DriveType]::CDRom, [System.IO.DriveType]::Ram)
}

function testLocalDrivePath {
    # パス（normalizeFolderPath 済み）が「ドライブ文字で始まり、ネットワークでない」= ローカルのドライブと分かるかを返す。
    # 共有に接続せずに見分ける。UNC・デバイス名の形（\.\UNC\… など）・相対パス・空は偽（testNetworkPath は
    # \.\ をドライブ文字の形として見るため、それだけではデバイス名の形を見分けられない）
    #   driveType: testNetworkPath と同じ（テストで差し替える）
    param (
        [string]$path,
        [scriptblock]$driveType = { param ($drive) ([System.IO.DriveInfo]$drive).DriveType }
    )

    return ($path -match '^[A-Za-z]:\\') -and !(testNetworkPath $path $driveType)
}


# ---- フォルダ選択の開始フォルダ ----


function getExistingAncestorFolder {
    # folder が今もあればそのまま、無ければその上の今もあるフォルダを返す（フォルダ選択を開く場所）。どこにも無ければ空。
    #   skipNetwork: $true なら、ネットワークのパスは調べずに空を返す（画面のスレッドで届かない共有に触らないため）
    param (
        [string]$folder,
        [bool]$skipNetwork = $false
    )

    if ($skipNetwork -and (testNetworkPath $folder)) {
        return ""
    }
    $dir = $folder
    while ($dir) {
        if (Test-Path -LiteralPath (toLongPath $dir) -PathType Container) {
            return $dir
        }
        $dir = Split-Path $dir -Parent
    }
    return ""
}


function getFolderLeafName {
    # フォルダ名（ドライブ直下はドライブ名、UNC の共有直下は共有名）を返す
    param (
        [string]$folderPath
    )

    $path = $folderPath.TrimEnd("\")
    $leaf = [System.IO.Path]::GetFileName($path)
    if ($leaf -eq "") {
        $leaf = $path.TrimEnd(":")
    }
    return $leaf
}

# 配布物の版の記録（VERSION.txt）の読み取り（状態層）。
# 中身は BOM 付き UTF-8・CRLF の2行（1行目: タグ名 / 2行目: コミットの SHA）。
# tools/new_version_text.ps1 が作り、tools/new_release_package.ps1（zip）・tools/new_installer.ps1（インストーラー）が書き込む。
# 作業ツリー（git のチェックアウト）には無く、配布物にだけある。
#
# 単一 .ps1 版（展開せずに動く試験版）は VERSION.txt を持てないため、結合の道具（tools/new_single_script.ps1）が
# 版の文字列を ${bundledVersion}（@{ Tag; Sha }）としてこのファイルより前に埋める。あればファイルを読まずそれを返す

function readVersionFile {
    # ファイルが無い・読めない・形が違うときは $null。あれば @{ Tag; Sha }
    param (
        [string]$path
    )

    $bundled = Get-Variable -Name bundledVersion -ErrorAction SilentlyContinue
    if ($null -ne $bundled) {
        return $bundled.Value
    }

    if (!(Test-Path -LiteralPath $path)) {
        return $null
    }
    try {
        $lines = [System.IO.File]::ReadAllLines($path)
    } catch {
        return $null
    }
    if ($lines.Count -ne 2) {
        return $null
    }
    if ($lines[0] -notmatch '^[A-Za-z0-9._-]+$' -or $lines[1] -notmatch '^[0-9a-f]{40}$') {
        return $null
    }
    return @{ Tag = $lines[0]; Sha = $lines[1] }
}

function resolveGitRef {
    # git のリファレンス（refs/heads/main など）が指すコミットの SHA を返す。無ければ空文字。
    # ファイルを読むだけ（外部プロセスの git は起動しない）。loose（refs\ の下のファイル）を先に見て、無ければ packed-refs を見る。
    #   dirs: 探すフォルダ（worktree の gitdir・共通の gitdir の順）
    param (
        [string]$ref,
        [string[]]$dirs
    )

    if ($ref -notmatch '^refs/[A-Za-z0-9._/-]+$' -or $ref.Contains("..")) {
        return ""
    }
    foreach ($dir in $dirs) {
        $loose = Join-Path $dir ($ref.Replace("/", "\"))
        if (Test-Path -LiteralPath $loose -PathType Leaf) {
            $text = ([System.IO.File]::ReadAllText($loose)).Trim()
            if ($text -match '^[0-9a-f]{40}$') {
                return $text
            }
        }
    }
    foreach ($dir in $dirs) {
        $refListFile = Join-Path $dir "packed-refs"
        if (!(Test-Path -LiteralPath $refListFile -PathType Leaf)) {
            continue
        }
        foreach ($line in [System.IO.File]::ReadAllLines($refListFile)) {
            if ($line -match '^([0-9a-f]{40}) (\S+)$' -and $Matches[2] -ceq $ref) {
                return $Matches[1]
            }
        }
    }
    return ""
}

function readDevVersion {
    # 配布物でない（VERSION.txt が無い）ときの版の手がかりを、作業ツリーの .git のファイルだけから読む。
    # 外部プロセス（git）は起動せず、ファイルを読むだけ。.git が無い・読めない・形が違うときは $null。
    # 返すもの: @{ Tag; AtHead; Sha }
    #   Sha    : HEAD のコミット（分からなければ空）
    #   Tag    : リリースのタグ（v<数>.<数>.<数>）。HEAD のコミットに付いたタグがあればそれ（複数なら版の並びで最も新しい）、
    #            無ければ全タグのうち版の並びで最も新しいもの（無ければ空）
    #   AtHead : Tag が HEAD のコミットに付いているか
    # 「最も新しいタグ」は版の並びで決める。.git のファイルだけでは、タグが HEAD の祖先かどうかは分からず、
    # 別のブランチのタグを拾うことがある（目安の表示のため、それでよい）。
    # 注釈付きタグは、packed-refs の ^ の行（指す先のコミット）で HEAD と照らす。refs\tags の下に置かれた注釈付きタグは、
    # タグの実体を読まないと指す先が分からないため、HEAD に付いた印にはならない（版の並びの比べには使う）。
    # worktree は .git がファイル（gitdir: <パス>）で、HEAD は gitdir に、タグ・packed-refs は commondir（共通の gitdir）にある
    param (
        [string]$rootDir
    )

    try {
        $dotGit = Join-Path $rootDir ".git"
        $gitDir = ""
        if (Test-Path -LiteralPath $dotGit -PathType Container) {
            $gitDir = $dotGit
        } elseif (Test-Path -LiteralPath $dotGit -PathType Leaf) {
            $first = [System.IO.File]::ReadAllLines($dotGit) | Select-Object -First 1
            if ($first -notmatch '^gitdir:\s*(.+)$') {
                return $null
            }
            $target = $Matches[1].Trim()
            if (![System.IO.Path]::IsPathRooted($target)) {
                $target = Join-Path $rootDir $target
            }
            $gitDir = [System.IO.Path]::GetFullPath($target)
        }
        if (!$gitDir -or !(Test-Path -LiteralPath $gitDir -PathType Container)) {
            return $null
        }
        $commonDir = $gitDir
        $commonFile = Join-Path $gitDir "commondir"
        if (Test-Path -LiteralPath $commonFile -PathType Leaf) {
            $common = ([System.IO.File]::ReadAllText($commonFile)).Trim()
            if ($common) {
                $commonDir = [System.IO.Path]::GetFullPath($(if ([System.IO.Path]::IsPathRooted($common)) { $common } else { Join-Path $gitDir $common }))
            }
        }

        # HEAD のコミット
        $sha = ""
        $headFile = Join-Path $gitDir "HEAD"
        if (Test-Path -LiteralPath $headFile -PathType Leaf) {
            $head = ([System.IO.File]::ReadAllLines($headFile) | Select-Object -First 1)
            if ($head -match '^ref:\s*(\S+)$') {
                $sha = resolveGitRef $Matches[1] @($gitDir, $commonDir)
            } elseif ($head -match '^[0-9a-f]{40}$') {
                $sha = $head
            }
        }

        # タグ（名前 → @{ Commit }）。packed-refs（注釈付きタグは次の行の ^ が指す先）を読み、loose のタグで上書きする
        $tags = @{}
        $refListFile = Join-Path $commonDir "packed-refs"
        if (Test-Path -LiteralPath $refListFile -PathType Leaf) {
            $last = ""
            foreach ($line in [System.IO.File]::ReadAllLines($refListFile)) {
                if ($line -match '^([0-9a-f]{40}) refs/tags/(v\d+\.\d+\.\d+)$') {
                    $last = $Matches[2]
                    $tags[$last] = $Matches[1]
                } elseif ($line -match '^\^([0-9a-f]{40})$' -and $last) {
                    $tags[$last] = $Matches[1]
                } else {
                    $last = ""
                }
            }
        }
        $tagsDir = Join-Path $commonDir "refs\tags"
        if (Test-Path -LiteralPath $tagsDir -PathType Container) {
            foreach ($file in @(Get-ChildItem -LiteralPath $tagsDir -File)) {
                if ($file.Name -match '^v\d+\.\d+\.\d+$') {
                    $text = ([System.IO.File]::ReadAllText($file.FullName)).Trim()
                    if ($text -match '^[0-9a-f]{40}$') {
                        $tags[$file.Name] = $text
                    }
                }
            }
        }

        $atHead = ""
        $latest = ""
        foreach ($name in @($tags.Keys)) {
            $isNewer = { param($a, $b) (-not $b) -or ([version]$a.Substring(1)) -gt ([version]$b.Substring(1)) }
            if (& $isNewer $name $latest) {
                $latest = $name
            }
            if ($sha -and $tags[$name] -eq $sha -and (& $isNewer $name $atHead)) {
                $atHead = $name
            }
        }
        if ($atHead) {
            return @{ Tag = $atHead; AtHead = $true; Sha = $sha }
        }
        if (!$latest -and !$sha) {
            return $null
        }
        return @{ Tag = $latest; AtHead = $false; Sha = $sha }
    } catch {
        return $null
    }
}

# 診断情報（ログの先頭の見出し）の組み立て（判断層）。
# ファイル・レジストリ・画面に触らない。調べる側は diagnostics.ps1 の getEnvironmentInfo。
# 利用者名・コンピューター名・ドメイン・パス・ネットワークの情報は、見出しに書かない。

function getVersionLabel {
    # readVersionFile の結果から、版・コミットの表示を決める: @{ Version; Commit（出さないときは空） }
    #   versionInfo: readVersionFile の戻り値（$null なら開発中に git から直接起動したときの表示にする）
    #   devInfo: readDevVersion の戻り値（versionInfo が $null のときだけ使う。タグ・コミットを添える。省くと「開発版」だけ）
    #     HEAD にタグがある: 開発版（v0.5.0・d79f898）/ 無い: 開発版（v0.5.0 より後・d79f898）/ コミットだけ: 開発版（d79f898）
    param (
        $versionInfo,
        $devInfo = $null
    )

    if ($null -eq $versionInfo) {
        $parts = @()
        if ($null -ne $devInfo) {
            $sha = if ($devInfo.Sha) { ([string]$devInfo.Sha).Substring(0, [Math]::Min(7, ([string]$devInfo.Sha).Length)) } else { "" }
            if ($devInfo.Tag) {
                $parts += $(if ($devInfo.AtHead) { [string]$devInfo.Tag } else { "$($devInfo.Tag) より後" })
            }
            if ($sha) {
                $parts += $sha
            }
        }
        if ($parts.Count -eq 0) {
            return @{ Version = "開発版"; Commit = "" }
        }
        return @{ Version = "開発版（$($parts -join '・')）"; Commit = "" }
    }
    return @{ Version = $versionInfo.Tag; Commit = $versionInfo.Sha.Substring(0, 7) }
}

function getOfficeKind {
    # 見つかった Office の実行ファイルのパスから、形態とビット数を決める: @{ Kind = "Click-to-Run" / "MSI"; Bits = 64 / 32 }
    #   programFiles64: 64 ビット側の Program Files / programFilesX86: x86 側の Program Files
    param (
        [string]$exePath,
        [string]$programFiles64,
        [string]$programFilesX86
    )

    $kind = "MSI"
    if ($exePath -match '(?i)\\root\\Office\d+\\') {
        $kind = "Click-to-Run"
    }
    $bits = 64
    if ($programFilesX86 -and $exePath.StartsWith($programFilesX86.TrimEnd("\") + "\", [System.StringComparison]::OrdinalIgnoreCase)) {
        $bits = 32
    }
    return @{ Kind = $kind; Bits = $bits }
}

function hideUserProfile {
    # 文字列の中の利用者のプロファイルのフォルダ（C:\Users\<利用者名>）を %USERPROFILE% に置き換える（大文字小文字は区別しない）。
    # 名前の前方だけが同じ別のフォルダ（末尾に文字が続く名前）は置き換えない
    param (
        [string]$text,
        [string]$profileDir
    )

    if (-not $text -or -not $profileDir) {
        return $text
    }
    $pattern = [regex]::Escape($profileDir.TrimEnd("\")) + '(?![\w.\-])'
    return [regex]::Replace($text, $pattern, '%USERPROFILE%', [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
}

function formatDiagnosticHeader {
    # ログの先頭に書く見出しの行（配列）を返す
    #   toolName: ツールの名前 / versionInfo: readVersionFile の結果 / envInfo: getEnvironmentInfo の結果 / now: 日時（DateTimeOffset）
    param (
        [string]$toolName,
        $versionInfo,
        $envInfo,
        [System.DateTimeOffset]$now,
        $devInfo = $null   # readDevVersion の結果（versionInfo が $null のとき、版にタグ・コミットを添える）
    )

    $unknown = "不明"
    $orUnknown = { param($value) if ($value) { [string]$value } else { $unknown } }
    $label = getVersionLabel $versionInfo $devInfo
    $versionText = $label.Version
    if ($label.Commit) {
        $versionText = "$($label.Version) ($($label.Commit))"
    }
    $bitsText = { param($is64) if ($null -eq $is64) { $unknown } elseif ($is64) { "64 ビット" } else { "32 ビット" } }

    $officeText = "見つからない"
    $officeItems = @($envInfo.Office)
    if ($null -eq $envInfo.Office) {
        $officeText = $unknown
    } elseif ($officeItems.Count -gt 0) {
        $officeText = (@($officeItems | ForEach-Object {
            "$($_.Name) $(& $orUnknown $_.Version) $($_.Kind) $($_.Bits) ビット"
        })) -join " / "
    }

    return @(
        "==== $toolName の診断情報 ===="
        "日時: $($now.ToString('yyyy-MM-dd HH:mm:ss zzz'))"
        "$toolName の版: $versionText"
        "OS: Windows $(& $orUnknown $envInfo.OsVersion)（ntoskrnl $(& $orUnknown $envInfo.OsFileVersion)・$(& $bitsText $envInfo.Os64)）"
        "PowerShell: $(& $orUnknown $envInfo.PsVersion)（$(& $bitsText $envInfo.Ps64)・$(& $orUnknown $envInfo.LanguageMode)）"
        "Office: $officeText"
        "表示言語: $(& $orUnknown $envInfo.UICulture)"
        "===="
    )
}

# 診断情報の収集と、ログの世代の入れ替え（状態層）。
# レジストリ・WMI・COM は使わず、Office も起動しない。ファイルの版情報と .NET・PowerShell の値だけを読む。
# 見出しの文面は diagnostics_view.ps1。

function getEnvironmentInfo {
    # OS・PowerShell・Office の情報を返す。調べられない項目は $null
    $info = @{ OsVersion = $null; OsFileVersion = $null; Os64 = $null; PsVersion = $null; Ps64 = $null; LanguageMode = $null; UICulture = $null; Office = @() }
    try { $info.OsVersion = [Environment]::OSVersion.Version.ToString() } catch {}
    try { $info.Os64 = [Environment]::Is64BitOperatingSystem } catch {}
    try { $info.Ps64 = [Environment]::Is64BitProcess } catch {}
    try { $info.PsVersion = $PSVersionTable.PSVersion.ToString() } catch {}
    try { $info.LanguageMode = [string]$ExecutionContext.SessionState.LanguageMode } catch {}
    try { $info.UICulture = [System.Globalization.CultureInfo]::CurrentUICulture.Name } catch {}
    try {
        $kernel = [System.Diagnostics.FileVersionInfo]::GetVersionInfo("$env:SystemRoot\System32\ntoskrnl.exe")
        $info.OsFileVersion = "$($kernel.FileMajorPart).$($kernel.FileMinorPart).$($kernel.FileBuildPart).$($kernel.FilePrivatePart)"
    } catch {}
    try {
        $info.Office = @(findOfficeApps -os64 ($info.Os64 -ne $false))
    } catch {
        $info.Office = $null   # 調べられなかった（見出しでは「不明」。「見つからない」とは区別する）
    }
    return $info
}

function findOfficeApps {
    # 決まった場所にある Office の実行ファイル（EXCEL.EXE・WINWORD.EXE・POWERPNT.EXE）を探し、@{ Name; Version; Kind; Bits } の配列を返す。
    # Program Files は、Windows のあるドライブ（$env:SystemRoot のドライブ）の決まった名前のフォルダとする
    # （環境変数 ProgramFiles は 32 ビットの PowerShell で x86 側を指し、安全性の検査も SystemRoot 以外の環境変数を許さないため）
    #   programFiles64 / programFilesX86: 探す 2 つの場所（省略すると Windows のあるドライブの決まった名前。テストでは別の場所を渡す）
    #   os64: 64 ビットの Windows か。32 ビットなら programFiles64 の場所を 32 ビット版の置き場として扱う
    # 調べている途中で例外になったら、そのまま投げる（呼び出し側が「不明」にする）
    param (
        [string]$programFiles64,
        [string]$programFilesX86,
        [bool]$os64 = $true
    )

    if (-not $programFiles64 -and -not $programFilesX86) {
        $systemDrive = [System.IO.Path]::GetPathRoot($env:SystemRoot)
        if (-not $systemDrive) {
            throw "Windows のあるドライブを取れない"   # 調べ損ね（見つからないとは別）
        }
        $programFiles64 = Join-Path $systemDrive "Program Files"
        $programFilesX86 = Join-Path $systemDrive "Program Files (x86)"
    }
    $x86Root = $programFilesX86
    if (-not $os64) {
        $x86Root = $programFiles64
    }
    $subDirs = @("Microsoft Office\root\Office16", "Microsoft Office\Office16", "Microsoft Office\Office15")
    $apps = @(@("Excel", "EXCEL.EXE"), @("Word", "WINWORD.EXE"), @("PowerPoint", "POWERPNT.EXE"))
    $found = New-Object System.Collections.Generic.List[object]
    foreach ($app in $apps) {
        $hit = $null
        foreach ($base in @($programFiles64, $programFilesX86)) {
            if (-not $base -or $hit) { continue }
            foreach ($sub in $subDirs) {
                $candidate = Join-Path (Join-Path $base $sub) $app[1]
                if (Test-Path -LiteralPath $candidate -PathType Leaf) {
                    $hit = $candidate
                    break
                }
            }
        }
        if ($hit) {
            $kind = getOfficeKind $hit $programFiles64 $x86Root
            $version = $null
            try { $version = [System.Diagnostics.FileVersionInfo]::GetVersionInfo($hit).FileVersion } catch {}
            $found.Add(@{ Name = $app[0]; Version = $version; Kind = $kind.Kind; Bits = $kind.Bits })
        }
    }
    return $found.ToArray()
}

function getPreviousLogPath {
    # ログの前回の分の名前（<名前>_previous<拡張子>）。同じフォルダに置く
    param (
        [string]$path
    )

    $dir = [System.IO.Path]::GetDirectoryName($path)
    $name = [System.IO.Path]::GetFileNameWithoutExtension($path) + "_previous" + [System.IO.Path]::GetExtension($path)
    return (Join-Path $dir $name)
}

function rotateLogFile {
    # path が maxBytes 以上なら、前回の分（getPreviousLogPath。あれば上書き）に移す。0 はいつも移す。
    # 移したら $true。元が無い・上限未満・移せない（読み取り専用・開いたまま）は $false（例外は出さない）
    param (
        [string]$path,
        [long]$maxBytes
    )

    try {
        if (-not [System.IO.File]::Exists($path)) {
            return $false
        }
        if ($maxBytes -gt 0 -and (New-Object System.IO.FileInfo($path)).Length -lt $maxBytes) {
            return $false
        }
        $previous = getPreviousLogPath $path
        if ([System.IO.File]::Exists($previous)) {
            # 移せない（前回の分が読み取り専用・元が開いたまま・置き場所が対応しない）ときは失敗し、今のログは失わない。
            # 複写で逃げないのは、移せないあいだ書くたびに全量を複写することになるため
            [System.IO.File]::Replace($path, $previous, [NullString]::Value)
        } else {
            [System.IO.File]::Move($path, $previous)
        }
        return $true
    } catch {
        return $false
    }
}

# 取り込み対象にする Office ファイルの拡張子。

# 取り込み対象にする Office ファイルの拡張子（小文字）。
# インデクサ（indexer.ps1）の対象の判定で使う
${officeExtensions} = @(
    ".xlsx", ".xlsm", ".xls", ".xlsb",
    ".docx", ".docm", ".doc",
    ".pptx", ".pptm", ".ppt"
)

# このツールが起動した Excel・Word・PowerPoint の PID の記録と、実行中の Office の一覧・強制終了。
# 止めてよいのは「記録があり、記録と今のプロセスが合うもの」だけ。記録の無いもの（利用者・ほかのアプリのもの）は一覧に出ても止める対象にしない。

# ----------------------------------------------------------------------------
# 検索・Officeプロセス・画面（gui.ps1）で共有する処理
# ----------------------------------------------------------------------------

# 強制終了の対象: プロセス名 → 表示名
${officeProcessNames} = [ordered]@{ EXCEL = "Excel"; WINWORD = "Word"; POWERPNT = "PowerPoint" }

# 書きかけの記録（*.tmp）をこの時間より古ければ消す（書いている最中のものを消さないため）
${officeRecordTmpMaxAge} = [TimeSpan]::FromHours(1)

function getOfficeStartTicks {
    # プロセスの起動時刻（UTC の Ticks）。読めない（管理者として動いているなど）ときは $null
    param (
        $process
    )

    try {
        return [long]$process.StartTime.ToUniversalTime().Ticks
    } catch {
        return $null
    }
}

function testOfficeProcessHasWindow {
    # process に見えている窓があるか（Process.MainWindowHandle が 0 でない）。COM を使わず、相手のプロセスにメッセージも送らないため、固まったプロセスにも戻ってくる。
    # 利用者がそのプロセスを使っているかの見分けに使う（インデックス作成はファイルを窓無しで開くので、自分の取り込みだけなら窓は無い）。
    # 値を取り直してから見る（取り直さないと、前に読んだ値のままになる）。読めない（終わっているなど）ときは $false
    param (
        $process
    )

    try {
        try { $process.Refresh() } catch {}
        $handle = $process.MainWindowHandle
        return ($handle -is [IntPtr] -and $handle -ne [IntPtr]::Zero)
    } catch {
        return $false
    }
}

function compareOfficeProcess {
    # process を、控えたとき（プロセス名・起動時刻）と比べる。"Same"（同じ）・"Different"（別のプロセス）・"Unknown"（分からない）を返す。
    # 先に Handle を読んでプロセスのハンドルを開く（Process が持ち続けるので、このあと同じ process で Kill() するまで、その PID は別のプロセスに使われない）。
    # ハンドルが開けない・控えた起動時刻が無い（$null・0）・今の起動時刻が読めないときは "Unknown"（止めない）。名前か起動時刻が違えば "Different"
    param (
        $process,
        [string]$processName,
        $startTicks
    )

    try {
        if ($null -eq $process.Handle) {
            return "Unknown"
        }
        if ($process.ProcessName -ne $processName) {
            return "Different"
        }
    } catch {
        return "Unknown"
    }
    if ($null -eq $startTicks -or [long]$startTicks -le 0) {
        return "Unknown"
    }
    $actual = getOfficeStartTicks $process
    if ($null -eq $actual) {
        return "Unknown"
    }
    return $(if ([long]$actual -eq [long]$startTicks) { "Same" } else { "Different" })
}

function isSameOfficeProcess {
    # process が、控えたときと同じプロセス（プロセス名と起動時刻が同じ）か。止める前に必ず通す（PID が別のプロセスに使い回されていないかの確認）。
    # 同じと言えるときだけ $true。違う・分からないときは $false（止めない）。比べ方は compareOfficeProcess
    param (
        $process,
        [string]$processName,
        $startTicks
    )

    return ((compareOfficeProcess $process $processName $startTicks) -eq "Same")
}

# ----------------------------------------------------------------------------
# 記録（<ワークスペース>\office_pids\<PC の鍵>\<PID>.txt）
# 1 行・タブ区切り: <プロセス名> <起動時刻の Ticks> <持ち主の PID> <持ち主の起動時刻の Ticks>
# ----------------------------------------------------------------------------

function addOfficeRecord {
    # 起動した Office の記録を 1 つ書く。書けたら $true。場所が空・書けない（共有に届かない・権限が無い）ときは $false（呼ぶ側は取り込みを続ける）。
    # 持ち主は、省けばこのプロセス（記録を書いたプロセス）。書きかけを読ませないよう、.tmp に書いてから名前を変える
    param (
        [string]$dir,
        [int]$id,
        [string]$processName,
        [long]$startTicks,
        [int]$ownerId = 0,
        [long]$ownerStartTicks = 0
    )

    if (!$dir -or $startTicks -le 0) {
        return $false
    }
    $tmp = Join-Path $dir "$id.tmp"
    try {
        if ($ownerId -le 0) {
            $self = [System.Diagnostics.Process]::GetCurrentProcess()
            $ownerId = $self.Id
            $ticks = getOfficeStartTicks $self
            $ownerStartTicks = $(if ($null -ne $ticks) { $ticks } else { 0 })
        }
        [void][System.IO.Directory]::CreateDirectory($dir)
        [System.IO.File]::WriteAllText($tmp, "$processName`t$startTicks`t$ownerId`t$ownerStartTicks", (New-Object System.Text.UTF8Encoding($false)))
        $final = Join-Path $dir "$id.txt"
        [System.IO.File]::Delete($final)
        [System.IO.File]::Move($tmp, $final)
        return $true
    } catch {
        try { [System.IO.File]::Delete($tmp) } catch {}
        return $false
    }
}

function removeOfficeRecord {
    # PID の記録を消す。ファイルが無い・消せないときも失敗にしない（消せなければ次の起動の確認で、PID が無いものとして消える）
    param (
        [string]$dir,
        [int]$id
    )

    if (!$dir) {
        return
    }
    try {
        [System.IO.File]::Delete((Join-Path $dir "$id.txt"))
    } catch {}
}

function readOfficeRecords {
    # 記録を読み、今のプロセスと照らし合わせて @{ Id; ProcessName; StartTicks; OwnerId; OwnerStartTicks; Owned } の配列を返す。
    # Owned: PID があり、名前が同じで、起動時刻が読めて同じ（記録を書いたときのプロセスのまま）。
    # 次のものは、PID が別のプロセスのものになった・無くなった記録なので消す: PID のプロセスが無い・名前が違う・起動時刻が読めて違う。
    # 起動時刻が読めないときは Owned にせず、消しもしない。形の違う記録は使わず、消さない。古い .tmp（書きかけの残り）は消す。
    # フォルダが無い・読めないときは空の配列
    param (
        [string]$dir
    )

    $result = New-Object System.Collections.Generic.List[object]
    if (!$dir) {
        return $result.ToArray()
    }
    try {
        foreach ($tmp in [System.IO.Directory]::GetFiles($dir, "*.tmp")) {
            try {
                if ([System.IO.Path]::GetExtension($tmp) -eq ".tmp" -and
                    ([datetime]::UtcNow - [System.IO.File]::GetLastWriteTimeUtc($tmp)) -gt ${officeRecordTmpMaxAge}) {
                    [System.IO.File]::Delete($tmp)
                }
            } catch {}
        }
        $files = [System.IO.Directory]::GetFiles($dir, "*.txt")
    } catch {
        return $result.ToArray()
    }
    foreach ($file in $files) {
        $id = 0
        $startTicks = [long]0
        $ownerId = 0
        $ownerTicks = [long]0
        try {
            if ([System.IO.Path]::GetExtension($file) -ne ".txt") { continue }
            $fields = ([System.IO.File]::ReadAllText($file).Trim() -split "`t")
            if (!([int]::TryParse([System.IO.Path]::GetFileNameWithoutExtension($file), [ref]$id) -and $id -gt 0 -and $fields.Count -eq 4 -and
                    ${officeProcessNames}.Contains($fields[0]) -and [long]::TryParse($fields[1], [ref]$startTicks) -and $startTicks -gt 0 -and
                    [int]::TryParse($fields[2], [ref]$ownerId) -and [long]::TryParse($fields[3], [ref]$ownerTicks))) {
                continue
            }
        } catch {
            continue
        }
        $process = Get-Process -Id $id -ErrorAction SilentlyContinue
        $owned = $false
        if ($null -eq $process -or $process.ProcessName -ne $fields[0]) {
            removeOfficeRecord $dir $id
            continue
        }
        $actual = getOfficeStartTicks $process
        if ($null -ne $actual) {
            if ($actual -ne $startTicks) {
                removeOfficeRecord $dir $id
                continue
            }
            $owned = $true
        }
        $result.Add([pscustomobject]@{
            Id = $id; ProcessName = $fields[0]; StartTicks = $startTicks; OwnerId = $ownerId; OwnerStartTicks = $ownerTicks; Owned = $owned
        })
    }
    return $result.ToArray()
}

function getOfficeRecordOwner {
    # 記録を書いたプロセス（持ち主）の今の状態: Self（この画面のプロセス）・Other（生きているほかのプロセス）・Gone（もういない）。
    # 持ち主の起動時刻が読めない・記録に無いときは、生きていれば安全な側（Other）にする
    param (
        $record,
        [int]$selfId,
        [long]$selfStartTicks
    )

    if ($record.OwnerId -eq $selfId -and $record.OwnerStartTicks -eq $selfStartTicks) {
        return "Self"
    }
    $owner = Get-Process -Id $record.OwnerId -ErrorAction SilentlyContinue
    if ($null -eq $owner) {
        return "Gone"
    }
    $actual = getOfficeStartTicks $owner
    if ($null -ne $actual -and $record.OwnerStartTicks -gt 0 -and $actual -ne $record.OwnerStartTicks) {
        return "Gone"
    }
    return "Other"
}

# ----------------------------------------------------------------------------
# 一覧と強制終了
# ----------------------------------------------------------------------------

function getOfficeProcesses {
    # 自分のセッションで実行中の Excel・Word・PowerPoint を返す。各要素:
    #   Id・ProcessName・AppName・StartTime（読めなければ $null）・
    #   HasWindow（MainWindowHandle が 0 でない）・
    #   Owned（recordDir の記録があり、記録と今のプロセスの PID・名前・起動時刻が合う。recordDir が空なら常に $false）・
    #   Owner（Owned のとき、記録を書いたプロセスの状態 Self・Other・Gone。Owned でなければ空）
    # 残り物（止めてよいもの）の選び出しは判断層（getLeftoverPrompt）が行う。ここは材料を返すだけ。
    # recordDir を読むため、画面のスレッドでは呼ばない（startJob の中で呼ぶ）。
    # selfId・selfStartTicks は、この画面のプロセスの PID と起動時刻（省けば今のプロセス。テストで差し替える）
    param (
        [string]$recordDir = "",
        [int]$selfId = 0,
        [long]$selfStartTicks = 0
    )

    $current = [System.Diagnostics.Process]::GetCurrentProcess()
    if ($selfId -le 0) {
        $selfId = $current.Id
        $ticks = getOfficeStartTicks $current
        $selfStartTicks = $(if ($null -ne $ticks) { $ticks } else { 0 })
    }
    $records = @{}
    foreach ($record in @(readOfficeRecords $recordDir)) {
        $records[[int]$record.Id] = $record
    }

    $result = New-Object System.Collections.Generic.List[object]
    foreach ($process in @(Get-Process -Name @(${officeProcessNames}.Keys) -ErrorAction SilentlyContinue |
            Where-Object { $_.SessionId -eq $current.SessionId })) {
        $startTime = $null
        try {
            $startTime = $process.StartTime
        } catch {
            # 権限の無いプロセスは起動時刻を取得できない
        }
        $record = $records[[int]$process.Id]
        $owned = ($null -ne $record -and $record.Owned -and $record.ProcessName -eq $process.ProcessName)
        $result.Add([pscustomobject]@{
            Id          = $process.Id
            ProcessName = $process.ProcessName
            AppName     = ${officeProcessNames}[$process.ProcessName]
            StartTime   = $startTime
            HasWindow   = (testOfficeProcessHasWindow $process)
            Owned       = $owned
            Owner       = $(if ($owned) { getOfficeRecordOwner $record $selfId $selfStartTicks } else { "" })
        })
    }
    return $result.ToArray()
}

function stopOfficeProcesses {
    # 指定したプロセスを保存せずに終了し、@{ Id; Stopped; Status; Reason } の配列を返す。
    # targets は getOfficeProcesses の要素（Id・ProcessName・StartTime）。止める直前に、PID が今も同じプロセスか（名前・起動時刻）を照らし直す。
    #   Status: Stopped（止めた）・Changed（名前か起動時刻が違う・読めない・Office の名前でない。止めない）・
    #           Gone（もう無い。止めた扱いにも失敗にもしない）・Failed（止めようとして失敗）
    #   Reason: Changed のときは「PID <N> は確認の後に別のプロセスに変わったため、終了しませんでした。」、Failed のときは例外のメッセージ。それ以外は空
    # recordDir があれば、止めた・もう無いものの記録を消す。プロセスの強制終了は、ここの Stop-Process の 1 か所だけ（tests/meta/safety.Tests.ps1。止める前に isSameOfficeProcess を通す）
    param (
        [object[]]$targets,
        [string]$recordDir = ""
    )

    $results = New-Object System.Collections.Generic.List[object]
    foreach ($target in $targets) {
        $id = [int]$target.Id
        $process = Get-Process -Id $id -ErrorAction SilentlyContinue
        if ($null -eq $process) {
            removeOfficeRecord $recordDir $id
            $results.Add(@{ Id = $id; Stopped = $false; Status = "Gone"; Reason = "" })
            continue
        }
        $expected = $null
        try { $expected = [long]$target.StartTime.ToUniversalTime().Ticks } catch {}
        if (!${officeProcessNames}.Contains([string]$target.ProcessName) -or -not (isSameOfficeProcess $process ([string]$target.ProcessName) $expected)) {
            $results.Add(@{ Id = $id; Stopped = $false; Status = "Changed"; Reason = "PID $id は確認の後に別のプロセスに変わったため、終了しませんでした。" })
            continue
        }
        try {
            Stop-Process -Id $id -Force -ErrorAction Stop
            removeOfficeRecord $recordDir $id
            $results.Add(@{ Id = $id; Stopped = $true; Status = "Stopped"; Reason = "" })
        } catch {
            $results.Add(@{ Id = $id; Stopped = $false; Status = "Failed"; Reason = $_.Exception.Message })
        }
    }
    return $results.ToArray()
}

# 暗号化されたファイルの種類を、開かずに見分ける（判断層）。ファイル・COM・Officeには触らない。
# 入力は「先頭バイト列」と「複合ドキュメント形式（CFB）のディレクトリのエントリ名の配列（CFBでなければ $null）」だけ。
# 実際にファイルを読むのは状態層（office_protection.ps1）。
#
# 種類（getOfficeProtectionKind の戻り値）:
#   Zip      : 新形式（.docx 等）。ふつうに読む
#   Password : パスワード付き（新形式）。Word・PowerPoint は Office を使わずに失敗にする（Excel は今のまま Office に任せる）
#   Rights   : IRM・秘密度ラベルの暗号化。Office で開かない（ライセンス取得・サインイン画面を防ぐ）
#   Legacy   : 旧形式（.doc / .xls / .ppt）など、権限保護と分からないCFB。今と同じ（Officeで開く。ダミーのパスワードで失敗）
#   Text     : 空・RTF・HTML・UTF-8・UTF-16（BOM）など、NULを含まないテキストらしい内容。今と同じ（Officeで開く）
#   Unknown  : 上のどれでもない（先頭4KBにNULを含む）バイナリ。透過暗号化の製品の暗号文の見込みがある。
#              守りを付けてOfficeで開く予備を使う（extract_office.ps1 がアプリごとに切り替える）

${zipSignature}      = [byte[]](0x50, 0x4B, 0x03, 0x04)
${compoundSignature} = [byte[]](0xD0, 0xCF, 0x11, 0xE0, 0xA1, 0xB1, 0x1A, 0xE1)

# 権限保護（IRM・秘密度ラベル）を示すCFBのエントリ名（[MS-OFFCRYPTO] IRMDS）。
#   新形式: DataSpaceInfo配下の DRMEncryptedDataSpace・TransformInfo配下の DRMEncryptedTransform
#   旧形式: 保護された中身の \x09DRMContent（必須）と、\x09DRMDataSpace・\x09DRMTransform
#           （任意で \x09DRMViewerContent・\x09LZXDRMDataSpace・\x09LZXTransform）
${rightsProtectedEntryNames} = @(
    "DRMEncryptedDataSpace", "DRMEncryptedTransform",
    ([char]9 + "DRMContent"), ([char]9 + "DRMDataSpace"), ([char]9 + "DRMTransform"),
    ([char]9 + "DRMViewerContent"), ([char]9 + "LZXDRMDataSpace"), ([char]9 + "LZXTransform")
)
# パスワード保護（ECMA-376 標準・アジャイル暗号化）を示すCFBのエントリ名
${passwordProtectedEntryNames} = @("StrongEncryptionDataSpace", "EncryptionInfo")
# データスペース（新形式のパスワード・権限保護が共通で使うストレージ）の名前
${dataSpacesStorageName} = ([char]6 + "DataSpaces")

function testsByteSignature {
    # $bytes の先頭が $signature と一致するか。
    # 判断層はファイルを開けないため、office_reader.ps1 の isZipFile・isCompoundFile が読むのと同じ印を、
    # 既に読んである先頭バイト列（$bytes）の側で比べる（ファイルを開き直さない）
    param (
        [byte[]]$bytes,
        [byte[]]$signature
    )

    if ($null -eq $bytes -or $bytes.Length -lt $signature.Length) {
        return $false
    }
    for ($i = 0; $i -lt $signature.Length; $i++) {
        if ($bytes[$i] -ne $signature[$i]) {
            return $false
        }
    }
    return $true
}

function testsUnicodeTextBom {
    # UTF-16（Excelのテキスト保存・多くのUnicodeテキストエディタ）の先頭のBOM（FF FE）かどうか
    param (
        [byte[]]$bytes
    )

    return ($null -ne $bytes -and $bytes.Length -ge 2 -and $bytes[0] -eq 0xFF -and $bytes[1] -eq 0xFE)
}

function getOfficeProtectionKind {
    # 先頭バイト列とCFBのエントリ名（CFBでなければ $null）から、暗号化の種類を返す
    param (
        [byte[]]$head,
        [string[]]$cfbNames
    )

    if ($null -eq $head -or $head.Length -eq 0) {
        return "Text"
    }
    if (testsByteSignature $head ${zipSignature}) {
        return "Zip"
    }
    if (testsByteSignature $head ${compoundSignature}) {
        $names = @($cfbNames)
        if (@($names | Where-Object { ${rightsProtectedEntryNames} -contains $_ }).Count -gt 0) {
            return "Rights"
        }
        $hasDataSpaces = ($names -contains ${dataSpacesStorageName})
        $hasPasswordNames = (@($names | Where-Object { ${passwordProtectedEntryNames} -contains $_ }).Count -gt 0)
        if ($hasDataSpaces -and !$hasPasswordNames) {
            # データスペースはあるが、名前を1つも取りこぼした場合。安全側（Officeで開かない）に倒す
            return "Rights"
        }
        if ($hasPasswordNames) {
            return "Password"
        }
        return "Legacy"
    }

    # ZIPでもCFBでもない。先頭4KBにNUL（0x00）を含む（UTF-16のBOMで始まるものを除く）＝形式の分からないバイナリ。
    # 空・RTF（`{\rtf`）・HTML・UTF-8・UTF-16（BOM）は、いずれもNULを含まないテキストのため「Text」になる
    if (testsUnicodeTextBom $head) {
        return "Text"
    }
    if (@($head) -contains [byte]0) {
        return "Unknown"
    }
    return "Text"
}

function getProtectionFailureText {
    # 種類ごとの、取り込み一覧のエラー列に出す短い文言。文言が無い種類（Zip・Legacy・Text）は $null
    param (
        [string]$kind
    )

    switch ($kind) {
        "Password" { return "読み取りパスワードが設定されているため開けません（パスワード付きのファイルは更新できません）" }
        "Rights"   { return "IRM・秘密度ラベルで暗号化されているため更新できません。" }
        "Unknown"  { return "暗号化されているか壊れているため更新できません。" }
        default    { return $null }
    }
}

# Officeが保存した一時ファイル（変換した.docx・.pptx、Excelのテキスト保存）まで、透過暗号化の製品が
# 暗号化した場合の文言。ふつうのファイルでも起こりうるため、すべてのOfficeの出力でこの確認を行う
${officeOutputEncryptedMessage} = "ファイルを暗号化する製品が一時ファイルを暗号化したため更新できません。"

function testOfficeOutput {
    # Officeが保存した出力の先頭バイト列が、期待する形（Zip・UnicodeText）かどうか
    param (
        [byte[]]$head,
        [string]$expectedKind
    )

    if ($expectedKind -eq "Zip") {
        return (testsByteSignature $head ${zipSignature})
    }
    if ($expectedKind -eq "UnicodeText") {
        return (testsUnicodeTextBom $head)
    }
    return $false
}

# Workbook.FileFormat が、テキスト・HTML・CSVとして取り込まれた印の値（xlCSV=6・xlTextMac=19・xlTextWindows=20・
# xlTextMSDOS=21・xlCSVMac=22・xlCSVWindows=23・xlCSVMSDOS=24・xlUnicodeText=42・xlHtml=44・xlCSVUTF8=62・
# xlCurrentPlatformText=-4158）
${excelTextLikeFileFormats} = @(6, 19, 20, 21, 22, 23, 24, 42, 44, 62, -4158)

function testWorkbookFormat {
    # Workbook.FileFormat が、テキスト・HTML・CSVとして取り込まれた印でないか（「形式の分からないバイナリ」のときだけ確かめる。
    # 中身がHTML・CSV等の「Text」の種類のブックには当てない。当てると本来読めているものまで失敗になる）
    param (
        $fileFormat
    )

    return (${excelTextLikeFileFormats} -notcontains $fileFormat)
}

function getWordOpenFormat {
    # 拡張子に合う WdOpenFormat の値。「形式の分からないバイナリ」をWordで開くときだけ渡し、自動判定に任せない
    # （wdOpenFormatDocument=1・wdOpenFormatTemplate=2・wdOpenFormatXMLDocument=9・
    #   wdOpenFormatXMLDocumentMacroEnabled=10・wdOpenFormatXMLTemplate=11・wdOpenFormatAuto=0）
    param (
        [string]$extension
    )

    switch ($extension.ToLowerInvariant()) {
        ".doc"  { return 1 }
        ".dot"  { return 2 }
        ".docx" { return 9 }
        ".docm" { return 10 }
        ".dotx" { return 11 }
        ".dotm" { return 11 }
        default { return 0 }
    }
}

# 暗号化されたファイルの見分け（状態層）: ファイルの先頭バイト列と、複合ドキュメント形式（CFB。[MS-CFB]）の
# ディレクトリのエントリ名を読み、判断層（office_protection_view.ps1）に渡す。
# ファイルを読むだけで、Office・COMには触らない（getOfficeFileProtection を extract_office.ps1 が呼ぶ）。
#
# 壊れたCFB（FATの鎖が輪になる・範囲外のセクター・ディレクトリが途中で切れる）でも例外を出さず、
# 決まった時間で戻る（読める範囲まで返す。ヘッダーさえ読めなければ $null）。
# ディレクトリのエントリ名だけが目的のため、ミニFAT・ストリームの中身は読まない。

${cfbHeadLength}      = 4096          # 先頭バイト列の読み取り量（判断層の判定に使う分）
${cfbFreeSect}        = [uint32]0xFFFFFFFFL
${cfbEndOfChain}      = [uint32]0xFFFFFFFEL
${cfbFatSect}         = [uint32]0xFFFFFFFDL
${cfbDifSect}         = [uint32]0xFFFFFFFCL
${cfbMaxChainSectors} = 200000         # FAT・ディレクトリの鎖をたどる上限（壊れたファイルで止まらないため）

function readFileHead {
    # ファイルの先頭（既定は4096バイト）を読む。開けない・読めなければ空の配列
    param (
        [string]$path,
        [int]$length = ${cfbHeadLength}
    )

    try {
        $stream = [System.IO.File]::OpenRead((toLongPath $path))
    } catch {
        return [byte[]]@()
    }
    try {
        $buffer = New-Object byte[] $length
        $read = $stream.Read($buffer, 0, $length)
        if ($read -eq $length) {
            return $buffer
        }
        $head = New-Object byte[] ([Math]::Max($read, 0))
        if ($read -gt 0) {
            [System.Array]::Copy($buffer, $head, $read)
        }
        return $head
    } catch {
        return [byte[]]@()
    } finally {
        $stream.Dispose()
    }
}

function readUInt32LE {
    # 範囲外なら FREESECT（鎖の終わりと同じ扱いにする安全な既定値）を返す
    param (
        [byte[]]$bytes,
        [int]$offset
    )

    if ($null -eq $bytes -or $offset -lt 0 -or ($offset + 4) -gt $bytes.Length) {
        return ${cfbFreeSect}
    }
    return [System.BitConverter]::ToUInt32($bytes, $offset)
}

function readCfbSector {
    # セクター番号（0起点）1つ分のバイト列。範囲外・読めなければ $null
    param (
        $stream,
        [double]$sectorSize,
        [long]$fileLength,
        [uint32]$secId
    )

    if ($secId -eq ${cfbFreeSect} -or $secId -eq ${cfbEndOfChain} -or $secId -eq ${cfbFatSect} -or $secId -eq ${cfbDifSect}) {
        return $null
    }
    $offset = [int64]$sectorSize * ([int64]$secId + 1)
    if ($offset -lt 0 -or ($offset + $sectorSize) -gt $fileLength) {
        return $null
    }
    try {
        [void]$stream.Seek($offset, [System.IO.SeekOrigin]::Begin)
        $buffer = New-Object byte[] ([int]$sectorSize)
        if ($stream.Read($buffer, 0, [int]$sectorSize) -ne [int]$sectorSize) {
            return $null
        }
        return $buffer
    } catch {
        return $null
    }
}

function getCfbFatSectorIds {
    # FATセクターの並び（順番が、その並びのk番目が担当するセクター番号の範囲を決める索引）を返す。
    # DIFAT（ヘッダーの109件 + DIFATセクターの鎖）だけをたどり、FATセクターの中身はまだ読まない
    # （中身は、ディレクトリの鎖をたどるときに要る分だけ readCfbFatEntry が読む）
    param (
        $stream,
        [byte[]]$header,
        [double]$sectorSize,
        [long]$fileLength
    )

    $entriesPerSector = [int]($sectorSize / 4)
    $fatSectorIds = New-Object 'System.Collections.Generic.List[uint32]'
    for ($i = 0; $i -lt 109; $i++) {
        $value = readUInt32LE $header (76 + $i * 4)
        if ($value -ne ${cfbFreeSect}) {
            $fatSectorIds.Add($value)
        }
    }

    $difatSec = readUInt32LE $header 68
    $seenDifat = New-Object 'System.Collections.Generic.HashSet[uint32]'
    $steps = 0
    while ($difatSec -ne ${cfbEndOfChain} -and $difatSec -ne ${cfbFreeSect} -and $steps -lt ${cfbMaxChainSectors} -and $seenDifat.Add($difatSec)) {
        $buffer = readCfbSector $stream $sectorSize $fileLength $difatSec
        if ($null -eq $buffer) {
            break
        }
        $entriesInSector = $entriesPerSector - 1
        for ($i = 0; $i -lt $entriesInSector; $i++) {
            $value = readUInt32LE $buffer ($i * 4)
            if ($value -ne ${cfbFreeSect}) {
                $fatSectorIds.Add($value)
            }
        }
        $difatSec = readUInt32LE $buffer ($entriesInSector * 4)
        $steps++
    }
    return $fatSectorIds
}

function readCfbFatEntry {
    # セクター番号1つ分の、FATの次のセクター番号を返す。
    # そのセクター番号を持つFATセクター（$fatSectorIds の何番目か）だけを読み、$fatCache に貯めて使い回す
    # （旧形式のふつうのファイルでもディレクトリの判定のたびに動くため、FAT全体を毎回読まない）
    param (
        $stream,
        [double]$sectorSize,
        [long]$fileLength,
        [System.Collections.Generic.List[uint32]]$fatSectorIds,
        [System.Collections.Generic.Dictionary[int, byte[]]]$fatCache,
        [uint32]$secId
    )

    $entriesPerSector = [int]($sectorSize / 4)
    $position = [int]([Math]::Floor([double]$secId / $entriesPerSector))
    if ($position -lt 0 -or $position -ge $fatSectorIds.Count) {
        return ${cfbFreeSect}
    }
    if (!$fatCache.ContainsKey($position)) {
        $fatCache[$position] = readCfbSector $stream $sectorSize $fileLength $fatSectorIds[$position]
    }
    $buffer = $fatCache[$position]
    if ($null -eq $buffer) {
        return ${cfbFreeSect}
    }
    $offset = ([int]($secId % $entriesPerSector)) * 4
    return readUInt32LE $buffer $offset
}

function readCfbDirectoryEntryNames {
    # ディレクトリ（ルート・ストレージ・ストリーム）のエントリ名を、鎖をたどって集める
    param (
        $stream,
        [double]$sectorSize,
        [long]$fileLength,
        [System.Collections.Generic.List[uint32]]$fatSectorIds,
        [uint32]$firstDirSector
    )

    $names = New-Object 'System.Collections.Generic.List[string]'
    $entriesPerSector = [int]($sectorSize / 128)
    $fatCache = New-Object 'System.Collections.Generic.Dictionary[int, byte[]]'
    $seen = New-Object 'System.Collections.Generic.HashSet[uint32]'
    $sec = $firstDirSector
    $steps = 0
    while ($sec -ne ${cfbEndOfChain} -and $sec -ne ${cfbFreeSect} -and $steps -lt ${cfbMaxChainSectors} -and $seen.Add($sec)) {
        $buffer = readCfbSector $stream $sectorSize $fileLength $sec
        if ($null -eq $buffer) {
            break
        }
        for ($i = 0; $i -lt $entriesPerSector; $i++) {
            $entryOffset = $i * 128
            $nameLength = [System.BitConverter]::ToUInt16($buffer, $entryOffset + 64)
            if ($nameLength -ge 2 -and $nameLength -le 64) {
                $name = [System.Text.Encoding]::Unicode.GetString($buffer, $entryOffset, $nameLength - 2)
                if ($name -ne "") {
                    $names.Add($name)
                }
            }
        }
        $sec = readCfbFatEntry $stream $sectorSize $fileLength $fatSectorIds $fatCache $sec
        $steps++
    }
    return $names
}

function readCompoundEntryNames {
    # CFBのディレクトリのエントリ名の配列を返す。CFBでない・読めない・壊れている場合は $null
    # （判断層は $null を、権限保護と分からない「旧形式」として扱う）
    param (
        [string]$path
    )

    try {
        $stream = [System.IO.File]::OpenRead((toLongPath $path))
    } catch {
        return $null
    }
    try {
        $fileLength = $stream.Length
        if ($fileLength -lt 512) {
            return $null
        }
        $header = New-Object byte[] 512
        if ($stream.Read($header, 0, 512) -ne 512) {
            return $null
        }
        $signature = [byte[]](0xD0, 0xCF, 0x11, 0xE0, 0xA1, 0xB1, 0x1A, 0xE1)
        for ($i = 0; $i -lt 8; $i++) {
            if ($header[$i] -ne $signature[$i]) {
                return $null
            }
        }

        $sectorShift = [System.BitConverter]::ToUInt16($header, 30)
        if ($sectorShift -ne 9 -and $sectorShift -ne 12) {
            return $null
        }
        $sectorSize = [double][Math]::Pow(2, $sectorShift)
        $firstDirSector = readUInt32LE $header 48

        $fatSectorIds = getCfbFatSectorIds $stream $header $sectorSize $fileLength
        return @(readCfbDirectoryEntryNames $stream $sectorSize $fileLength $fatSectorIds $firstDirSector)
    } catch {
        return $null
    } finally {
        $stream.Dispose()
    }
}

function getOfficeFileProtection {
    # ファイルを読み、暗号化の種類（getOfficeProtectionKind の戻り値）を返す
    param (
        [string]$path
    )

    $head = readFileHead $path
    $cfbNames = readCompoundEntryNames $path
    return getOfficeProtectionKind $head $cfbNames
}

# 設定を先に読み込む（ワークスペースは設定の workspaceFolder で決まる。paths.ps1 の initWorkspace を
# 起動口（startGui・invokeIndexerMain）が壊れた設定ファイルの退避の後に呼んで決める）
# tebunko のログの先頭に書く見出しと、インデックス作成のログの書き口（状態層）。shared/ がツールの名前を知らないよう、名前はここで渡す。

function getToolDiagnosticHeader {
    # 見出しの行（配列）。版は配布物の VERSION.txt（無ければ開発版。.git のファイルから分かるタグとコミットを添える）
    $version = readVersionFile "${rootDir}\VERSION.txt"
    $devInfo = if ($null -eq $version) { readDevVersion ${rootDir} } else { $null }
    return formatDiagnosticHeader "tebunko" $version (getEnvironmentInfo) ([System.DateTimeOffset]::Now) $devInfo
}

# インデックス作成のログ（invokeIndexer が開く TextWriter。取り込みのスレッドでは 1 ファイル分を貯める StringWriter）
$script:indexerLog = $null
# ログをコンソールにも出すか（画面を使わずに indexer.ps1 を実行したとき）
$script:indexerEcho = $false

function writeIndexerLog {
    # インデックス作成の表示内容をログ（indexing_log.txt）に書く。color はコンソールに出すときの色
    param (
        [string]$text = "",
        [string]$color = ""
    )

    if ($null -ne $script:indexerLog) {
        try {
            $script:indexerLog.WriteLine($text)
        } catch {
            # ログのためだけの書き込みのため、書けなくてもインデックス作成は続ける
        }
    }
    if ($script:indexerEcho) {
        if ($color) {
            Write-Host $text -ForegroundColor $color
        } else {
            Write-Host $text
        }
    }
}

# setting.config の読み書き（tebunko の設定）。

# ツールの ID（多重起動の防止・ミューテックスの名前に使う）。
# 起動口（gui.ps1・indexer.ps1）が lib.ps1 より先に、このファイルだけを読み込んで設定を確かめる（repairBrokenSettings）ため、ここで決める
${appId} = "tebunko"

function getDefaultWorkDir {
    # 既定のワークスペース（%USERPROFILE%\Documents\tebunko_ws）。高速検索のため、Windows Search の索引の対象になる場所に置く。
    # OneDrive にリダイレクトされた「ドキュメント」ではなく、プロファイルの直下の Documents を使う（インデックスが同期でクラウドに上がらないように）
    # 環境変数 TEBUNKO_DEFAULT_WORKSPACE に絶対パスが入っていれば、それを既定のワークスペースにする（開発・確かめ用。
    # テストや実機の確かめが、利用者の既定のワークスペースに触れないようにするための差し替えの口）。入っているのに絶対パスでなければ、
    # 黙って既定のワークスペースに戻らないよう例外にする。引数 profileDir を渡したときは、環境変数を見ない
    param (
        [string]$profileDir = [System.Environment]::GetFolderPath("UserProfile")
    )

    $override = $env:TEBUNKO_DEFAULT_WORKSPACE
    if (!$PSBoundParameters.ContainsKey("profileDir") -and ![string]::IsNullOrWhiteSpace($override)) {
        $override = $override.Trim()
        # ドライブ直下だけ（C:\）やサーバー名だけ（\\server\）は、末尾の区切りを削ると別の意味になるため受け付けない
        if ($override -notmatch '^([A-Za-z]:[\\/]+[^\\/]|\\\\[^\\/]+[\\/]+[^\\/])') {
            throw "TEBUNKO_DEFAULT_WORKSPACE はフォルダまで含めた絶対パスで指定してください: $override"
        }
        return $override.TrimEnd("\", "/")
    }

    return Join-Path $profileDir "Documents\tebunko_ws"
}

function getSettingsFilePath {
    # 設定ファイルのパス。ツールのフォルダに書き込めればそこ、書き込めないとき（Program Files・読み取り専用の共有フォルダ）は
    # 既定のワークスペースの直下に置く（shared\core\data_dir.ps1 の getDataDir）。設定はワークスペースの場所を読む前に見つかる必要があるため、
    # ワークスペースを別の場所に移しても、設定は既定のワークスペースに残る
    param (
        [string]$root,
        [string]$defaultWorkDir
    )

    return Join-Path (getDataDir $root $defaultWorkDir) "setting.config"
}

# 設定ファイル（画面が読み書きする。インデクサはクロール対象フォルダと work の置き場所を読む）。内容は JSON。
# ツールのフォルダに書き込めないときは、既定のワークスペースの直下に置く
${settingsFile} = getSettingsFilePath ${rootDir} (getDefaultWorkDir)

function testSettingsFileName {
    # 設定ファイルと、それに付いてできるファイルの名前か（setting.config・保存の途中で止まると残る setting.config.tmp・
    # 壊れた設定の退避 setting.config.broken-<日時>（同じ名前があれば -2・-3… が付く））。
    # 既定のワークスペースの空の判定では、これらを tebunko のファイルとして数えない
    param (
        [string]$name
    )

    $base = [regex]::Escape([System.IO.Path]::GetFileName(${settingsFile}))
    return [bool]($name -imatch "^${base}(\.tmp|\.broken-\d{8}-\d{6}(-\d+)?)?$")
}

# 検索結果から元のファイルを開くときの開き方（設定 openMode の値）
${openModeNormal}   = "normal"    # そのまま開く（編集する）
${openModeReadOnly} = "readOnly"  # 読み取り専用で開く（誤って上書きしない）
${openModeNew}      = "new"       # 新規（元のファイルを基にした無題の文書）で開く。元のファイルを占有しない
${openModes}        = @(${openModeNormal}, ${openModeReadOnly}, ${openModeNew})

# インデックス作成で、クラウドにだけあるファイル（OneDrive・SharePoint のオンデマンド）をどうするか（設定 cloudFiles の値）
${cloudFilesAsk}      = "ask"       # ダウンロードせずに残す（確認の画面で、ダウンロードして取り込むかを選べる）
${cloudFilesDownload} = "download"  # 確認なしでダウンロードして取り込む
${cloudFilesModes}    = @(${cloudFilesAsk}, ${cloudFilesDownload})

# 検索の対象にするファイルの種類（検索バーのチップ。設定ファイルの fileKinds の値）
${fileKindNames} = @("excel", "word", "powerpoint", "text", "pdf")

function newSettings {
    # 設定の既定値。設定ファイル（JSON）のキーと同じ
    return [ordered]@{
        targetFolders      = @()      # クロール対象フォルダ: @{ name（インデックス名）; path（今フォルダが置かれている場所）; enabled }（記載順。enabled が false は登録のみで取り込まない）
        indexSources       = @()      # 取り込まないインデックスの元のフォルダ: @{ name; path }（別のPC・場所で作ったインデックスを検索するとき）
        searchExcludes     = @()      # 画面の検索対象ツリーでチェックを外したフォルダ: @{ path（フルパス）; subfolders（false はフォルダ直下のファイルだけ） }
        fileKinds          = @()      # 検索の対象にするファイルの種類（excel・word・powerpoint・text の配列。キーが無い・空ならすべて。readFileKinds）
        useRegex           = $false   # 検索ワードを正規表現として扱う
        caseSensitive      = $false   # 英字の大文字と小文字を区別する
        includeShapes      = $true    # 図形（テキストボックス等）の文字も検索する（場所 "<元の場所>[図形]"。index_name.ps1 の objectPlacePattern）
        includeComments    = $true    # コメントも検索する（場所 "<元の場所>[コメント]"）
        openMode           = ${openModeNormal}  # 検索結果の元のファイルの開き方: 通常（編集する）/ 読み取り専用 / 新規（元のファイルを基にした無題の文書。占有しない）
        workspaceFolder    = ""       # ワークスペース（インデックス・取り込み一覧・ログを置くフォルダ）。空なら既定（%USERPROFILE%\Documents\tebunko_ws。getDefaultWorkDir）
        cloudFiles         = ${cloudFilesAsk}  # クラウドにだけあるファイルの扱い: ask（ダウンロードせずに残す。確認の画面で選べる）/ download（ダウンロードして取り込む）。知らない値は ask（readCloudFiles）
        ingestThreads      = 0        # Office を使わずに読むファイル（.docx・.pptx など）の読み取りのスレッドの数（1～4。0 はコア数から決める。getIngestWorkerCount）。Excel・Word・PowerPoint は種類ごとに 1 つ
    }
}

function readSettings {
    # 設定を newSettings と同じ形で返す。記載の無い項目は既定値。設定ファイルが無ければ既定値
    param (
        [string]$path = ${settingsFile}
    )

    $settings = newSettings
    if (!(Test-Path -LiteralPath $path)) {
        return $settings
    }

    # ロック・共有違反などの読み込みの失敗（IOException）は、壊れているのではないため、そのまま例外にする
    $json = [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8)
    if ($json.Trim() -eq "") {
        return $settings
    }
    try {
        $data = ConvertFrom-Json $json
    } catch {
        # JSON として読めない（壊れている）ときは FormatException にする。ファイルは動かさない（退避は repairBrokenSettings が行う）
        throw (New-Object System.FormatException("$([System.IO.Path]::GetFileName($path)) を読み込めません。（$($_.Exception.Message)）"))
    }
    # 中身が null だけなら、空のファイルと同じく既定値（配列・数値だけのときと同じ扱い）
    if ($null -eq $data) {
        return $settings
    }
    foreach ($key in @($settings.Keys)) {
        $property = $data.PSObject.Properties[$key]
        if ($null -eq $property -or $null -eq $property.Value) {
            continue
        }
        if ($settings[$key] -is [array]) {
            $settings[$key] = @($property.Value | Where-Object { $null -ne $_ })
        } elseif ($settings[$key] -is [string]) {
            $settings[$key] = [string]$property.Value
        } elseif ($settings[$key] -is [int]) {
            # 数値。手で書き換えて数値にできないときは既定値
            $number = 0
            if ([int]::TryParse([string]$property.Value, [ref]$number)) {
                $settings[$key] = $number
            }
        } else {
            $settings[$key] = toSettingBool $property.Value $settings[$key]
        }
    }
    return $settings
}

function repairBrokenSettings {
    # 設定ファイルが JSON として読めないとき（ConvertFrom-Json の失敗だけ。空・null だけのファイルは今までどおり既定値で読むため対象外）、
    # 元の中身のまま setting.config.broken-<yyyyMMdd-HHmmss> に移し（同じ名前があれば -2・-3… を付けて、前の退避を上書きしない）、移したパスを返す。
    # 移すと設定ファイルが無くなり、既定値で起動できる。壊れていない・無いときは何もせず空文字を返す。
    # 移せなかったときは例外にする（壊れたファイルを残したまま既定値で上書きしないため）。
    # readSettings はファイルを動かさない。起動口（gui.ps1・indexer.ps1）が、起動の時に 1 回だけ呼ぶ
    param (
        [string]$path = ${settingsFile}
    )

    return invokeSettingsLocked -path $path -action {
        if (!(Test-Path -LiteralPath $path)) {
            return ""
        }
        $json = [System.IO.File]::ReadAllText($path, [System.Text.Encoding]::UTF8)
        if ($json.Trim() -eq "") {
            return ""
        }
        try {
            $null = ConvertFrom-Json $json
            return ""
        } catch {
            # 壊れている。下で退避する
        }

        $brokenBase = "${path}.broken-" + (Get-Date).ToString("yyyyMMdd-HHmmss")
        $brokenPath = $brokenBase
        $serial = 2
        while (Test-Path -LiteralPath $brokenPath) {
            $brokenPath = "${brokenBase}-${serial}"
            $serial++
        }
        try {
            [System.IO.File]::Move($path, $brokenPath)
        } catch {
            throw "$([System.IO.Path]::GetFileName($path)) が壊れているため退避しようとしましたが、移せませんでした。tebunko を使っているほかのプログラム（ウイルス対策ソフトなど）を確かめてください。（$($_.Exception.Message)）"
        }
        return $brokenPath
    }
}

function getSettingsRecoveryMessage {
    # 壊れた設定ファイルを退避して既定の設定で起動したときの知らせの文言（画面の起動時・画面なしのインデクサで共通）。
    # brokenPath は repairBrokenSettings が返した、退避したファイルのパス
    param (
        [string]$brokenPath
    )

    return "設定ファイルが壊れていたため、既定の設定で起動しました。ワークスペースの場所・登録したフォルダなども既定に戻っています。`n元に戻すには、tebunko を閉じてから、退避したファイル（${brokenPath}）を直して setting.config に置き換え、開き直してください。"
}

function toSettingBool {
    # 設定ファイルの真偽値を読む。手で書き換えた "false" などの文字列は [bool] にすると $true になるため、
    # 文字列は true / false として読み、読めなければ既定値（default）にする
    param (
        $value,
        [bool]$default
    )

    if ($value -is [string]) {
        $parsed = $false
        if ([bool]::TryParse($value.Trim(), [ref]$parsed)) {
            return $parsed
        }
        return $default
    }
    return [bool]$value
}

function writeSettings {
    param (
        $settings,
        [string]$path = ${settingsFile}
    )

    # 書き込みの途中で止まっても設定ファイルが壊れないよう、一時ファイルに書いてから置き換える（BOM なし UTF-8）
    writeTextLinesAtomic $path @((ConvertTo-Json -InputObject $settings -Depth 5)) (New-Object System.Text.UTF8Encoding($false))
}

function invokeSettingsLocked {
    # 設定ファイルの「読む → 変える → 書く」の一続きを、ほかの画面・インデクサ（別のプロセスも）と同時に行わないよう、
    # 設定ファイルごとの名前付きミューテックスの中で action を実行する（同じスレッドの入れ子は通す）。
    # action の出力を返す。5 秒待っても取れなければ例外（invokeWithNamedMutex）
    param (
        [string]$path,
        [scriptblock]$action,
        [int]$timeoutMilliseconds = 5000
    )

    $lockKey = getFolderKey ([System.IO.Path]::GetFullPath($path))
    return invokeWithNamedMutex "Local\${appId}_settings_${lockKey}" $timeoutMilliseconds $action
}

function updateSettings {
    # 設定ファイルを読み直して key の値だけを変えて保存する（ほかの項目は、ほかの画面・処理が保存した内容を保つ）
    param (
        [string]$key,
        $value,
        [string]$path = ${settingsFile}
    )

    invokeSettingsLocked -path $path -action {
        $settings = readSettings $path
        $settings[$key] = $value
        writeSettings $settings $path
    }
}

function getTargetFolders {
    # クロール対象フォルダの一覧（記載順）を返す: @{ Name; Path; Enabled }。
    #   Name   : インデックス名（work\index 直下のフォルダ名）。インデックスの「名前」で、フォルダの置き場所（Path）とは分けて持つ。
    #            Path を書き換えても Name が同じなら同じインデックスとして扱う（取り込み直さない）。空なら取り込み時に割り当てる（assignIndexNames）
    #   Path   : そのフォルダが今置かれている場所
    #   Enabled: false はチェックなし（登録のみで取り込まない）
    # 同じフォルダ・同じ名前は最初のものだけ使う（名前の重複は、2 つ目以降を空にして割り当て直す）。
    # 書き方が違うだけで同じフォルダを指す場合（ネットワークドライブと UNC パスなど）も同じフォルダとみなす
    param (
        [string]$path = ${settingsFile}
    )

    $folders = New-Object System.Collections.Generic.List[object]
    $seenPath = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $seenName = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($item in @((readSettings $path).targetFolders)) {
        $folder = normalizeFolderPath ([string]$item.path)
        if ($folder -eq "" -or -not $seenPath.Add($folder)) {
            continue
        }
        if (@($folders | Where-Object { testSameFolder $_.Path $folder }).Count -gt 0) {
            continue
        }
        $name = toSafeFileName ([string]$item.name).Trim()
        if ($name -ne "" -and -not $seenName.Add($name)) {
            $name = ""
        }
        $folders.Add([pscustomobject]@{ Name = $name; Path = $folder; Enabled = ($item.enabled -ne $false) })
    }
    return $folders.ToArray()
}

function writeTargetFolders {
    # クロール対象フォルダの一覧（@{ Name; Path; Enabled } の配列）を保存する
    param (
        [object[]]$folders,
        [string]$path = ${settingsFile}
    )

    updateSettings "targetFolders" ([object[]]@($folders | Where-Object { $_ } | ForEach-Object {
        [pscustomobject]@{ name = [string]$_.Name; path = $_.Path; enabled = [bool]$_.Enabled }
    })) $path
}

function mergeAssignedIndexNames {
    # 今の設定のクロール対象フォルダ（current。getTargetFolders の形）に、インデクサ・画面が割り当てたインデックス名（assigned。
    # assignIndexNames の結果）を反映した一覧を返す。インデクサが始めに読んだ一覧を丸ごと書き戻すと、その間の画面での変更を消すため、
    # 書き戻す直前に読み直した一覧へ、割り当てた名前だけを足す。
    # 突き合わせる鍵はパス（大文字と小文字は区別しない）。名前は、今の一覧で名前が空の項目にだけ付ける。
    # 同じ名前をほかの項目が使っていれば付けない（空のまま。次の機会に割り当て直す）
    param (
        [object[]]$current,
        [object[]]$assigned
    )

    $assignedNames = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($item in @($assigned | Where-Object { $_ -and $_.Name })) {
        $assignedNames[[string]$item.Path] = [string]$item.Name
    }
    $used = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($item in @($current | Where-Object { $_ -and $_.Name })) {
        [void]$used.Add([string]$item.Name)
    }

    $result = New-Object System.Collections.Generic.List[object]
    foreach ($item in @($current | Where-Object { $_ })) {
        $name = [string]$item.Name
        if ($name -eq "" -and $assignedNames.ContainsKey([string]$item.Path) -and $used.Add($assignedNames[[string]$item.Path])) {
            $name = $assignedNames[[string]$item.Path]
        }
        $result.Add([pscustomobject]@{ Name = $name; Path = $item.Path; Enabled = $item.Enabled })
    }
    return $result.ToArray()
}

function saveAssignedIndexNames {
    # 割り当てたインデックス名（assigned。assignIndexNames の結果）を設定に保存し、保存した一覧（@{ Name; Path; Enabled }）を返す。
    # 設定を読み直し（ほかの画面・インデクサの変更を保つ）、mergeAssignedIndexNames で名前だけを足して書く（読む → 書くを排他の中で行う）。
    # 名前を付けられなかった項目（同じ名前をほかの項目が使っている・ほかが先に名前を付けた）は、返す一覧でも設定のとおり（空か、先に付いた名前）
    param (
        [object[]]$assigned,
        [string]$path = ${settingsFile}
    )

    return invokeSettingsLocked -path $path -action {
        $merged = @(mergeAssignedIndexNames @(getTargetFolders $path) $assigned)
        writeTargetFolders $merged $path
        return $merged
    }
}

function readIndexSources {
    # 取り込まないインデックスの元のフォルダ（indexSources）を @{ Name; Path } の配列で返す。
    # 別の PC・場所で作ったインデックスを検索するとき、そのインデックス名の元のフォルダを覚えておくために使う
    param (
        [string]$path = ${settingsFile}
    )

    $items = New-Object System.Collections.Generic.List[object]
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($item in @((readSettings $path).indexSources)) {
        $name = ([string]$item.name).Trim()
        $folder = normalizeFolderPath ([string]$item.path)
        if ($name -eq "" -or $folder -eq "" -or -not $seen.Add($name)) {
            continue
        }
        $items.Add([pscustomobject]@{ Name = $name; Path = $folder })
    }
    return $items.ToArray()
}

function writeIndexSources {
    param (
        [object[]]$sources,
        [string]$path = ${settingsFile}
    )

    updateSettings "indexSources" ([object[]]@($sources | Where-Object { $_ } | ForEach-Object {
        [pscustomobject]@{ name = $_.Name; path = $_.Path }
    })) $path
}

function setIndexSourceFolder {
    # インデックス名に対する元のフォルダ（今そのフォルダが置かれている場所）を設定に記録する。
    # クロール対象フォルダにある名前ならそのパスを書き換え、無ければ indexSources に記録する。
    # 「名前」と「置き場所」を分けて持つため、フォルダを移した場合もこの 1 か所を書き換えるだけで済む
    param (
        [string]$name,
        [string]$folder,
        [string]$path = ${settingsFile}
    )

    # 名前は文字の並びそのもの（大文字・小文字だけ区別しない）で比べる。-eq はカルチャに従い、ソフトハイフンなどを無視して
    # 別の名前（利用者自身の対象フォルダ）に一致してしまう。前後の空白（全角空白を含む）がある名前は、読み込み（readIndexSources）で
    # 前後を削るため同じ名前として読み戻せない。記録しない（確認の判定と食い違わせない）
    $name = [string]$name
    $folder = normalizeFolderPath $folder
    if (!(testSourceNameRecordable $name) -or $folder -eq "") {
        return
    }

    invokeSettingsLocked -path $path -action {
        $same = { param ($other) [string]::Equals([string]$other, $name, [System.StringComparison]::OrdinalIgnoreCase) }
        $targets = @(getTargetFolders $path)
        if (@($targets | Where-Object { & $same $_.Name }).Count -gt 0) {
            writeTargetFolders @($targets | ForEach-Object {
                if (& $same $_.Name) { [pscustomobject]@{ Name = $_.Name; Path = $folder; Enabled = $_.Enabled } } else { $_ }
            }) $path
            return
        }

        $sources = @(@(readIndexSources $path | Where-Object { !(& $same $_.Name) }) + @([pscustomobject]@{ Name = $name; Path = $folder }))
        writeIndexSources $sources $path
    }
}

${searchOptionKeys} = [ordered]@{
    UseRegex = "useRegex"; CaseSensitive = "caseSensitive"
    IncludeShapes = "includeShapes"; IncludeComments = "includeComments"
}


function readSearchOption {
    # 画面の検索オプションを @{ UseRegex; CaseSensitive; IncludeShapes; IncludeComments } で返す。
    # 設定が無ければ、文字どおり・大文字と小文字を区別しない・図形とコメントも検索する（検索するファイルの種類は readFileKinds）
    param (
        [string]$path = ${settingsFile}
    )

    $settings = readSettings $path
    $option = @{}
    foreach ($name in ${searchOptionKeys}.Keys) {
        $option[$name] = $settings[${searchOptionKeys}[$name]]
    }
    return $option
}

function writeSearchOption {
    # 画面の検索オプションを保存する。option（readSearchOption と同じ形）にある項目だけを変える
    param (
        [hashtable]$option,
        [string]$path = ${settingsFile}
    )

    invokeSettingsLocked -path $path -action {
        $settings = readSettings $path
        foreach ($name in ${searchOptionKeys}.Keys) {
            if ($option.ContainsKey($name)) {
                $settings[${searchOptionKeys}[$name]] = $option[$name]
            }
        }
        writeSettings $settings $path
    }
}

function readFileKinds {
    # 検索の対象にするファイルの種類（${fileKindNames} の値）を、${fileKindNames} の順の配列で返す。
    # キーが無い・空・知らない値だけのときは、すべての種類（絞り込まない）
    param (
        [string]$path = ${settingsFile}
    )

    $chosen = @(@((readSettings $path).fileKinds) | ForEach-Object { ([string]$_).Trim().ToLowerInvariant() })
    $kinds = @(${fileKindNames} | Where-Object { $chosen -contains $_ })
    if ($kinds.Count -eq 0) {
        return @(${fileKindNames})
    }
    return $kinds
}

function writeFileKinds {
    # 検索の対象にするファイルの種類を保存する。知らない値は捨てる（すべての種類を選んでいるときは空で保存する）。
    # 1 つも選んでいないときは保存しない（空は「すべて」の意味で保存の形を変えないため、前に保存した種類のまま）
    param (
        [object[]]$kinds,
        [string]$path = ${settingsFile}
    )

    $chosen = @(${fileKindNames} | Where-Object { @($kinds) -contains $_ })
    if ($chosen.Count -eq 0) {
        return
    }
    if ($chosen.Count -eq ${fileKindNames}.Count) {
        $chosen = @()
    }
    updateSettings "fileKinds" ([object[]]$chosen) $path
}

function readOpenMode {
    # 元のファイルの開き方（${openModes} のいずれか）を返す。設定が無い・知らない値なら「通常」
    param (
        [string]$path = ${settingsFile}
    )

    $mode = (readSettings $path).openMode
    if (${openModes} -contains $mode) {
        return $mode
    }
    return ${openModeNormal}
}

function writeOpenMode {
    param (
        [string]$mode,
        [string]$path = ${settingsFile}
    )

    updateSettings "openMode" $mode $path
}

function readCloudFiles {
    # クラウドにだけあるファイルの扱い（${cloudFilesModes} のいずれか）を返す。設定が無い・知らない値なら ask
    param (
        [string]$path = ${settingsFile}
    )

    $mode = (readSettings $path).cloudFiles
    if (${cloudFilesModes} -contains $mode) {
        return $mode
    }
    return ${cloudFilesAsk}
}

function writeCloudFiles {
    param (
        [string]$mode,
        [string]$path = ${settingsFile}
    )

    updateSettings "cloudFiles" $mode $path
}

# 既定のワークスペースが空でないときの文言（画面の［既定に戻す］・起動時、インデクサで共通）
function getDefaultWorkspaceError {
    param (
        [string]$folder
    )

    return "「${folder}」は空のフォルダではありません。ワークスペースには別の空のフォルダを選んでください（［設定］の［変更…］）。"
}

function testDefaultWorkspace {
    # 既定のワークスペースを使えるか: @{ Usable; Folder; Message }。
    # 使える: 無い（使うときに作る）・空（設定ファイルと、それに付いてできるファイルだけの場合を含む）・前から使っているワークスペース（content_index・前の版の index・ingest_status.tsv がある）。
    # それ以外（ほかのファイルが置いてある）は、インデックスのファイルと混ざるため使わせない
    param (
        [string]$folder = (getDefaultWorkDir)
    )

    $result = @{ Usable = $true; Folder = $folder; Message = "" }
    # 既定の場所がネットワークにある（プロファイルが共有にある・環境変数 TEBUNKO_DEFAULT_WORKSPACE が UNC のパス）ときは、
    # 画面のスレッドで中身を数えない（届かないと止まる）。確かめず、使えるものとして扱う
    if (testNetworkPath $folder) {
        return $result
    }
    if (![System.IO.Directory]::Exists($folder)) {
        return $result
    }
    # 設定ファイルと、それに付いてできるファイルは数えない（既定のワークスペースは、書き込めないときの設定ファイルの置き場所でもある）
    $names = @(foreach ($entry in (selectFirstEntries ([System.IO.Directory]::EnumerateFileSystemEntries($folder)) 1000)) {
        $name = [System.IO.Path]::GetFileName($entry)
        if (-not (testSettingsFileName $name)) { $name }
    })
    if ($names.Count -eq 0 -or ($names -contains "content_index") -or ($names -contains "index") -or ($names -contains [System.IO.Path]::GetFileName($workspace.StatusFile))) {
        return $result
    }
    $result.Usable = $false
    $result.Message = getDefaultWorkspaceError $folder
    return $result
}

function getWorkspaceBlockMessage {
    # 今のワークスペースが既定の場所で、そこにほかのファイルが置いてあるなら、その文言（使えるなら空）。
    # インデックスのファイルと混ざるため、インデックス作成を始めず、［設定］で別のフォルダを選んでもらう
    param (
        [string]$current = $workspace.Dir,
        [string]$defaultDir = (getDefaultWorkDir)
    )

    if (!(testSameFolder $current $defaultDir)) {
        return ""
    }
    return (testDefaultWorkspace $defaultDir).Message
}

function getWorkDir {
    # work の置き場所を返す。設定 workspaceFolder が空なら既定（getDefaultWorkDir）。
    # 手で書いた相対パスは、設定ファイルのフォルダからとみなす
    param (
        [string]$path = ${settingsFile}
    )

    $folder = ([string](readSettings $path).workspaceFolder).Trim()
    if ($folder -eq "") {
        return getDefaultWorkDir
    }
    $folder = [System.Environment]::ExpandEnvironmentVariables($folder)
    return [System.IO.Path]::GetFullPath([System.IO.Path]::Combine([System.IO.Path]::GetDirectoryName($path), $folder)).TrimEnd("\")
}

function writeWorkspaceFolder {
    # work の置き場所を保存する。既定の場所なら空にする（ツールのフォルダを移しても既定のまま付いてくるように）
    param (
        [string]$folder,
        [string]$path = ${settingsFile}
    )

    $folder = ([string]$folder).Trim().TrimEnd("\")
    if ($folder -ne "" -and (testSameFolder $folder (getDefaultWorkDir))) {
        $folder = ""
    }
    updateSettings "workspaceFolder" $folder $path
}

# 検索対象ツリーでチェックを外したフォルダ（設定の searchExcludes）の読み書きと、「フォルダとその下」の比較。
# インデックスの改名・削除（IndexCatalog）、ワークスペースの切り替え（WorkspaceMover）、検索対象ツリーの保存が、同じ部品を通す。
# 設定の読み書きは settings.ps1（invokeSettingsLocked・readSettings・updateSettings）を使う。

function testFolderOrUnder {
    # path が folder そのもの、または folder の下にあるかを返す（フォルダとその下の比較は、ここだけで行う）。
    # 大文字・小文字は区別しない（序数の比較。NTFS と同じ扱いで、文化による同一視はしない）。
    # folder の末尾の \ は無いものとして比べ、"<folder>\" で始まるものだけを「下」にする（Sales の下に Sales2 は入らない）。
    # folder が空なら、どれも含まない
    param (
        [string]$path,
        [string]$folder
    )

    $folder = ([string]$folder).TrimEnd("\")
    if ($folder -eq "" -or $null -eq $path) {
        return $false
    }
    return $path.Equals($folder, [System.StringComparison]::OrdinalIgnoreCase) -or
        $path.StartsWith($folder + "\", [System.StringComparison]::OrdinalIgnoreCase)
}

function readSearchExcludes {
    # 画面の検索対象ツリーでチェックを外したフォルダを @{ Path; Subfolders } の配列で返す（設定が無ければ空 = すべて検索する）。
    #   Subfolders: $true はフォルダ以下すべて、$false はフォルダ直下のファイルだけを外す
    param (
        [string]$path = ${settingsFile}
    )

    $result = New-Object System.Collections.Generic.List[object]
    foreach ($item in @((readSettings $path).searchExcludes)) {
        $folder = ([string]$item.path).Trim().TrimEnd("\")
        if ($folder -eq "") {
            continue
        }
        $subfolders = if ($null -eq $item.subfolders) { $true } else { toSettingBool $item.subfolders $true }
        $result.Add([pscustomobject]@{ Path = $folder; Subfolders = $subfolders })
    }
    return $result.ToArray()
}

function writeSearchExcludes {
    # 検索対象ツリーでチェックを外したフォルダ（@{ Path; Subfolders } の配列）を保存する
    param (
        [object[]]$excludes,
        [string]$path = ${settingsFile}
    )

    updateSettings "searchExcludes" ([object[]]@($excludes | Where-Object { $_ -and $_.Path } | ForEach-Object {
        [ordered]@{ path = [string]$_.Path; subfolders = [bool]$_.Subfolders }
    })) $path
}

function removeSearchExcludesUnder {
    # 検索対象ツリーでチェックを外した記録のうち、folder（インデックスのフォルダ）とその下のものを消す（比較は testFolderOrUnder）。
    # 記録は利便性のための一時的な情報のため、消せなくても例外にしない（インデックスの改名・削除は止めない）。
    # 消す記録が無ければ設定ファイルは書き換えない
    param (
        [string]$folder,
        [string]$path = ${settingsFile}
    )

    $folder = ([string]$folder).Trim().TrimEnd("\")
    if ($folder -eq "") {
        return
    }

    try {
        invokeSettingsLocked -path $path -action {
            $excludes = @(readSearchExcludes $path)
            $kept = @($excludes | Where-Object { -not (testFolderOrUnder $_.Path $folder) })
            if ($kept.Count -lt $excludes.Count) {
                writeSearchExcludes $kept $path
            }
        } | Out-Null
    } catch {
    }
}

function moveSearchExcludes {
    # 検索対象ツリーでチェックを外したフォルダ（searchExcludes。インデックスの下のフルパス）のうち、
    # ワークスペース from の index の下のものを、to の index の下に付け替えて保存する。付け替えた数を返す
    param (
        [string]$from,
        [string]$to,
        [string]$path = ${settingsFile}
    )

    $fromIndex = ([Workspace]::new($from.TrimEnd("\"))).IndexDir
    $toIndex = ([Workspace]::new($to.TrimEnd("\"))).IndexDir
    return invokeSettingsLocked -path $path -action {
        $count = 0
        $excludes = @(readSearchExcludes $path | ForEach-Object {
            $folder = $_.Path
            if (testFolderOrUnder $folder $fromIndex) {
                $folder = $toIndex + $folder.Substring($fromIndex.Length)
                $count++
            }
            [pscustomobject]@{ Path = $folder; Subfolders = $_.Subfolders }
        })
        if ($count -gt 0) {
            writeSearchExcludes $excludes $path
        }
        return $count
    }
}

# ワークスペース（インデックス・取り込み一覧・ログを置くフォルダ）の中の、tebunko が使うファイルの場所。
# 場所はフォルダ（Dir）から組み立てるだけで、設定は読まない。どのフォルダを使うかは設定の workspaceFolder で決まる（settings.ps1 の getWorkDir）。
# 今のワークスペースは paths.ps1 の ${workspace} に置く。別のスレッドへは Dir（文字列）を渡し、そこで作り直す。
# Workspace のメソッドは場所を組み立てるだけなので、.NET の型だけを使う（クラスのメソッドからスクリプトの関数は呼べるが、
# $script: 変数は呼び出し元によって見える範囲が違うため、クラスの本体では読まない。docs/design/structure/classes.md）

class Workspace {
    [string]$Dir
    [string]$IndexDir
    # 前の版（content_index・system_index に名前をそろえる前）が使っていた本文インデックスのフォルダ。
    # 新しい版はここを読まず、消しもしない（前の版のしるしの調べ・知らせ・［設定］で「移す」「消して最初から」の対象にするために持つ）
    [string]$LegacyIndexDir
    # システムインデックス（本文インデックスの 2-gram を書いた txt。index と同じ相対パスの構成。Windows Search に索引させる）と、その状態
    [string]$SystemIndexDir
    [string]$SystemIndexStateFile
    # 取り込んだTSVをインデックスに入れる直前に集めるフォルダ（publishIndexFiles）。
    # フォルダごと入れ替えるため、インデックスと同じドライブ（ワークスペースの中）に置く。
    # 検索対象に入らないよう index の外にする。インデックス作成を同時に複数実行しても混ざらないよう、プロセスごとに分ける
    [string]$PublishDir
    # 取り込み一覧・出力（自動生成）
    [string]$StatusFile
    [string]$IngestingFile  # 取り込み中のファイル。強制終了で残っていれば、そのファイルの取り込み中に止まった
    [string]$ResultFile
    # インデックス作成の記録。画面とインデクサの受け渡しはメモリ上で行う（indexer_state.ps1 の newIndexerChannel）
    [string]$IndexingLogFile  # インデクサの表示内容の記録（実行ごとに上書き）
    [string]$GuiErrorLogFile  # 画面で起きた予期しないエラーの記録（追記。原因を後から追えるようにする。1 MB で下の前回の分に回す）
    [string]$IndexingLogPreviousFile  # 前回のインデックス作成の記録（インデックス作成を始めるとき、今の記録をここへ移す）
    [string]$GuiErrorLogPreviousFile  # 画面エラーの記録の前回の分（1 MB を超えたとき、今の記録をここへ移す）
    # 取り込みの作業フォルダの置き場所（下は <PC の鍵>\<PID>\w<番号> と分かれる。selectTmpDir・getWorkspaceTmpDir）。
    # 前の版までの %TEMP%\tebunko\<PID> の代わりに、ワークスペースの中に置く（共有フォルダでも 1 か所にまとまる）
    [string]$TmpRoot
    # このツールが起動した Office の PID の記録の置き場所（下は <PC の鍵>\<PID>.txt と分かれる。getOfficePidDir・shared/office/office_process.ps1）。
    # 画面を起動したとき、前回残った Office を確認して止めるために使う。tmp の下には置かない（tmp は片付けで消える場所で、記録は画面ごと落ちた後に読むため）
    [string]$OfficePidRoot

    Workspace([string]$dir) {
        $this.Dir = $dir
        $this.IndexDir = "$dir\content_index"
        $this.LegacyIndexDir = "$dir\index"
        $this.SystemIndexDir = "$dir\system_index"
        $this.SystemIndexStateFile = "$dir\system_index_state.tsv"
        $this.PublishDir = "$dir\publish\$([System.Diagnostics.Process]::GetCurrentProcess().Id)"
        $this.StatusFile = "$dir\ingest_status.tsv"
        $this.IngestingFile = "$dir\ingesting.txt"
        $this.ResultFile = "$dir\search_results.txt"
        $this.IndexingLogFile = "$dir\indexing_log.txt"
        $this.GuiErrorLogFile = "$dir\gui_error_log.txt"
        $this.IndexingLogPreviousFile = "$dir\indexing_log_previous.txt"
        $this.GuiErrorLogPreviousFile = "$dir\gui_error_log_previous.txt"
        $this.TmpRoot = "$dir\tmp"
        $this.OfficePidRoot = "$dir\office_pids"
    }

    # ワークスペースを移すときに移すもの（tebunko が作るファイル・フォルダ）。利用者のほかのファイルは含めない。
    # 取り込みの出力（publish）はプロセスごとのフォルダ（PublishDir）の親を移す。
    # LegacyIndexDir は、あれば前の版のワークスペースとして tebunko のものと扱う（あるものだけが WorkspaceMover.ListEntries で拾われる）
    [string[]] Entries() {
        return @($this.IndexDir, $this.LegacyIndexDir, $this.SystemIndexDir, $this.SystemIndexStateFile, $this.StatusFile, $this.IngestingFile,
            $this.ResultFile, $this.IndexingLogFile, $this.GuiErrorLogFile,
            $this.IndexingLogPreviousFile, $this.GuiErrorLogPreviousFile, [System.IO.Path]::GetDirectoryName($this.PublishDir), $this.TmpRoot, $this.OfficePidRoot)
    }
}

# 前の版（content_index・system_index に名前をそろえる前）が system_index に置いていた txt の名前の型。
# 新しい版は system_index.txt を使うため、前の版の txt を見つける・片付けるためだけに使う（読み書きの形式は変えない）
${legacySystemIndexPattern} = "システムインデックス*.txt"

function getMachineKey {
    # この PC を識別する短い鍵（getFolderKey の先頭 8 文字）。
    # 共有フォルダのワークスペースを複数の PC から使うとき、一時フォルダを PC ごとに分けるために使う（getWorkspaceTmpDir）
    return (getFolderKey ([Environment]::MachineName)).Substring(0, 8)
}

function getOfficePidDir {
    # 起動した Office の PID の記録を置くフォルダ（$workspace.OfficePidRoot\<PC の鍵>）を返す。文字列を組み立てるだけで、ファイルには触らない。
    # 共有のワークスペースで、ほかの PC の PID と混ざらないよう PC ごとに分ける
    param (
        [Workspace]$workspace
    )

    return Join-Path $workspace.OfficePidRoot (getMachineKey)
}

function getWorkspaceJobQueue {
    # ネットワークの場所に触るかもしれない startJob の列を決める唯一の関数。
    # paths（ワークスペース・インデックスのフォルダ・元のフォルダ・記録の置き場所など）の中に 1 つでもネットワークの場所があれば、
    # 届かない共有で待たされても他の仕事を巻き込まない専用の列（"network"）、無ければ既定の列（"default"）
    param (
        [string[]]$paths
    )

    return $(if (testAnyNetworkPath $paths) { "network" } else { "default" })
}

function assertWorkspaceReachable {
    # インデックスの削除・名前の変更の裏の仕事の先頭で呼ぶ。ワークスペース（のインデックスのフォルダ）に届かないとき、
    # 例外にする（届かないのに「何もせず成功」にして、設定だけ変えてしまわないため）。無いこと（まだインデックスを作っていない）は例外にしない
    param (
        [string]$dir
    )

    $state = getPathState $dir
    if ($state.State -eq ${pathStateUnreachable}) {
        throw "ワークスペースに接続できません：${dir}"
    }
    if ($state.State -eq ${pathStateOther}) {
        throw "ワークスペースを確かめられません：$($state.Message)"
    }
}

function getWorkspaceTmpDir {
    # 取り込みの作業フォルダの候補（$workspace.TmpRoot\<PC の鍵>\<PID>）を返す。副作用は無い（selectTmpDir が使う）
    param (
        [Workspace]$workspace
    )

    return Join-Path $workspace.TmpRoot (Join-Path (getMachineKey) $PID)
}

function selectTmpDir {
    # 取り込みの作業フォルダの置き場所を決める: @{ Dir; Reason（置けないときだけ） }
    #   候補: getWorkspaceTmpDir（ワークスペースの tmp\ の下）
    #   候補のパスに [ ] があれば、置けない（Dir = ""、Reason = Brackets）。Excel は [ ] を含むパスに保存できないため
    #   候補の長さ + 取り込みのスレッドが下に作る最も長い名前の分（${tmpNameReserve}）が $excelMaxPath 以上でも、
    #     置けない（Dir = ""、Reason = TooLong）。Office は長すぎるパスを開けないため
    #   一時ファイルもワークスペースの下にしか置かない（%TEMP% には逃がさない）。
    #   置けないときは、呼び出し側（initTmpDir）が取り込みをすべてスキップする
    #   （どのファイルも中間 TSV などをこのフォルダに作るため、テキストファイルを含めすべての取り込みが対象になる）
    #   どちらでもなければ候補のまま（Reason = ""）
    param (
        [Workspace]$workspace
    )

    $candidate = getWorkspaceTmpDir $workspace
    if ($candidate.IndexOfAny([char[]]@("[", "]")) -ge 0) {
        return @{ Dir = ""; Reason = "Brackets" }
    }
    if (($candidate.Length + ${tmpNameReserve}) -ge $excelMaxPath) {
        return @{ Dir = ""; Reason = "TooLong" }
    }
    return @{ Dir = $candidate; Reason = "" }
}

function getTmpDirUnavailableMessage {
    # 取り込みの作業フォルダを置けない理由（selectTmpDir の Reason）を、利用者向けの1文にする。
    # initTmpDir のログと、invokeIngestTask が1ファイルごとに書くエラーの両方で使う
    param (
        [string]$reason
    )

    if ($reason -eq "Brackets") {
        return "ワークスペースのパスに [ ]（角かっこ）が含まれるため、更新の作業フォルダを置けません。"
    }
    if ($reason -eq "TooLong") {
        return "ワークスペースのパスが長すぎるため、更新の作業フォルダを置けません。"
    }
    if ($reason -eq "Link") {
        return "ワークスペースの作業領域の途中にリンク（ジャンクション・シンボリックリンク）があるため、更新の作業フォルダを置けません。"
    }
    return "更新の作業フォルダを置けません。"
}

function getLegacyIndexState {
    # 前の版のワークスペース（dir）の状態を返す: @{ HasLegacyIndex; ContentEmpty; HasLegacySystemIndex }
    #   HasLegacyIndex       : 前の版の index\ があり、直下のどれかのフォルダに legacySourceFolderFileName（元のフォルダ.txt）がある（前の版のしるし）。
    #                          index\ があるだけでは、利用者が選んだフォルダにたまたま index があるときと区別できないため、しるしとしない
    #   ContentEmpty         : content_index\ が無いか、下のフォルダを含めてファイルが 1 つも無い
    #   HasLegacySystemIndex : system_index\ の下に前の名前の txt（システムインデックス*.txt）がある。
    #                          ContentEmpty のときだけ調べる（片付けの条件にしか使わないため）
    param (
        [string]$dir
    )

    $ws = [Workspace]::new($dir)
    # 見つけたところで列挙をやめるため、testAnyEntry で調べる（foreach を break で抜けると、調べていたフォルダを
    # 掴んだまま残り、続くインポートの上書きで content_index\<名前> を移動できなくなる）
    $hasLegacyIndex = $false
    $longLegacy = toLongPath $ws.LegacyIndexDir
    if ([System.IO.Directory]::Exists($longLegacy)) {
        $hasLegacyIndex = testAnyEntry ([System.IO.Directory]::EnumerateDirectories($longLegacy)) {
            param ($sub)
            [System.IO.File]::Exists("$sub\${legacySourceFolderFileName}")
        }
    }

    $contentEmpty = $true
    $longContent = toLongPath $ws.IndexDir
    if ([System.IO.Directory]::Exists($longContent)) {
        $contentEmpty = !(testAnyEntry ([System.IO.Directory]::EnumerateFiles($longContent, "*", [System.IO.SearchOption]::AllDirectories)))
    }

    $hasLegacySystemIndex = $false
    if ($contentEmpty) {
        $longSystem = toLongPath $ws.SystemIndexDir
        if ([System.IO.Directory]::Exists($longSystem)) {
            $hasLegacySystemIndex = testAnyEntry ([System.IO.Directory]::EnumerateFiles($longSystem, ${legacySystemIndexPattern}, [System.IO.SearchOption]::AllDirectories))
        }
    }

    return @{ HasLegacyIndex = $hasLegacyIndex; ContentEmpty = $contentEmpty; HasLegacySystemIndex = $hasLegacySystemIndex }
}

function testLegacyCleanupNeeded {
    # 取り込み直しを始めるときに、前の版のシステムインデックスを片付けるかどうか（getLegacyIndexState の結果から決まる）。
    # content_index\ が空で、かつ、前の版のしるしがあるか、system_index\ に前の名前の txt が残っているときに片付ける
    # （取り込み直す前に利用者が index\ を消していても、前の名前の txt を残さないため）
    param (
        $state
    )

    return ($state.ContentEmpty -and ($state.HasLegacyIndex -or $state.HasLegacySystemIndex))
}

function getLegacyIndexMessage {
    # 前の版のワークスペース（index\。しるしあり）が見つかったときの知らせ。しるしが無ければ空
    param (
        [string]$dir,
        [bool]$hasLegacyIndex
    )

    if (!$hasLegacyIndex) {
        return ""
    }
    $legacyDir = [Workspace]::new($dir).LegacyIndexDir
    return "前の版のインデックス（「${legacyDir}」）は、この版では使えません。［すべて更新］で、元のファイルをすべて更新し直します。" +
        "更新し直した後、「${legacyDir}」フォルダは削除してかまいません。"
}

function clearLegacySystemIndex {
    # 前の版のシステムインデックス（system_index\ と、システムインデックスの状態ファイルの中身）を片付ける: @{ Ok; Reason（失敗のときだけ） }
    # 片付けの順番: (1) updateSystemIndexState の排他の中で、状態ファイルの中身を空にする（ファイルは消さない。
    #     画面の検索（fast_search.ps1）やインデックスの削除（index_store.ps1）が同じ排他で書き換えるため、
    #     消した直後に前のキーを書き戻されないようにする）。
    # (2) system_index\ を removeDirectoryRetry で消す（Windows Search が txt を一時的に開くことがあるため）。
    # どちらかに失敗したら Ok = $false（途中で止まっても、次に呼べば同じ状態から続けられる）
    param (
        [string]$dir
    )

    $ws = [Workspace]::new($dir)
    $cleared = updateSystemIndexState {
        param ($state)
        $state.Covered.Clear()
        $state.Pending.Clear()
        $state.Excluded.Clear()
    } $ws.SystemIndexStateFile
    if (!$cleared) {
        return @{ Ok = $false; Reason = "システムインデックスの状態ファイル（$([System.IO.Path]::GetFileName($ws.SystemIndexStateFile))）を開けませんでした" }
    }
    try {
        removeDirectoryRetry $ws.SystemIndexDir
    } catch {
        return @{ Ok = $false; Reason = $_.Exception.Message }
    }
    return @{ Ok = $true; Reason = "" }
}

function newWorkspace {
    # ワークスペースの場所（Dir。文字列）から Workspace を作る。クラスの本体は別のクラスの型を書かないため、クラスから作るときはこれを呼ぶ
    param (
        [string]$dir
    )

    return [Workspace]::new($dir)
}

# ワークスペースの切り替え（中身を移す・消して最初からやり直す・選んだ先のインデックスを使う・searchExcludes の付け替え・保存・失敗したら戻す）。
# 画面（ui\settings\settings.ps1 の applyWorkspace・startWorkspaceMove）は、確かめて利用者に選ばせたあと ChangeWorkspace を呼び、結果を出して画面を切り替えるだけにする。
# ListEntries などの確かめは画面のスレッドで、ChangeWorkspace は裏のスレッド（startWorkspaceMove の startJob）で使う。切り替えの前に、画面は本文インデックスのファイルを読んでいる検索を止める（移せないため）。
#
# クラスの本体では $script: 変数・ほかのクラスの型・呼び出し元の変数を使わない（docs/design/structure/classes.md）。
# 設定ファイルの場所はコンストラクタで受け取る。ワークスペースの中の場所は Workspace（workspace.ps1）から組み立てる。
# searchExcludes の付け替えは、IndexCatalog と同じ部品（search_excludes.ps1 の moveSearchExcludes）を通す。
# メソッドの中のローカル変数は、プロパティと大文字・小文字だけの違いにしない
class WorkspaceMover {
    hidden [string]$SettingsPath

    WorkspaceMover([string]$settingsPath) {
        $this.SettingsPath = $settingsPath
    }

    [string[]] ListEntries([string]$dir) {
        # ワークスペース dir にある、tebunko のファイル・フォルダ（Workspace.Entries のうち、あるもの）のフルパスを返す
        return @((newWorkspace $dir).Entries() | Where-Object {
            $long = toLongPath $_
            [System.IO.Directory]::Exists($long) -or [System.IO.File]::Exists($long)
        })
    }

    [string[]] Conflicts([string]$from, [string]$to) {
        # ワークスペース from の中身を to へ移すとき、to に同じ名前が既にあるもの（移せないもの）の名前を返す
        return @($this.ListEntries($from) | ForEach-Object { [System.IO.Path]::GetFileName($_) } | Where-Object {
            $long = toLongPath (Join-Path $to $_)
            [System.IO.Directory]::Exists($long) -or [System.IO.File]::Exists($long)
        })
    }

    [hashtable] ChangeWorkspace([string]$mode, [string]$from, [string]$to) {
        # ワークスペースを from から to に変える（設定に保存する）。mode:
        #   "use"   … to にあるインデックスを使う。from の中身は移さず、インデックスの一覧を to のものにする
        #   "move"  … from の中身を to へ移す
        #   "reset" … to の tebunko のファイル・フォルダを消してから、from の中身を移す
        # 戻り値: @{ Ok; Stage（失敗した段階。"remove"・"move"）; Message（失敗の理由）; Targets（"use" で使うインデックスの数）; Count（"move"・"reset" で移した数）}。
        # 失敗したときは設定を変えない（移せなかったら、移した分は from に戻してある）
        if ($mode -eq "use") {
            # 共有されたワークスペースなどを使う。今の中身は移さず、インデックスの一覧をこのワークスペースのものにする
            $targets = $this.UseTargets($to)
            writeWorkspaceFolder $to $this.SettingsPath
            return @{ Ok = $true; Stage = ""; Message = ""; Targets = $targets; Count = 0 }
        }
        if ($mode -eq "reset") {
            try {
                [void]$this.RemoveEntries($to)
            } catch {
                return @{ Ok = $false; Stage = "remove"; Message = $_.Exception.Message; Targets = 0; Count = 0 }
            }
        }
        try {
            $count = $this.MoveEntries($from, $to)
        } catch {
            return @{ Ok = $false; Stage = "move"; Message = $_.Exception.Message; Targets = 0; Count = 0 }
        }
        # 検索対象ツリーでチェックを外したフォルダも、移した先のインデックスに付け替える
        [void](moveSearchExcludes $from $to $this.SettingsPath)
        writeWorkspaceFolder $to $this.SettingsPath
        return @{ Ok = $true; Stage = ""; Message = ""; Targets = 0; Count = $count }
    }

    [int] MoveEntries([string]$from, [string]$to) {
        # ワークスペース from の中身（tebunko のファイル・フォルダ）を to へ移し、移した数を返す。ほかのファイルは移さない。
        # to に同じ名前があれば、何も移さずに例外にする。途中で移せなかったら、移した分を from へ戻してから例外にする
        # （どちらかのワークスペースに中身がそろった状態にし、半分ずつに分かれたままにしない）
        $conflicts = @($this.Conflicts($from, $to))
        if ($conflicts.Count -gt 0) {
            throw "「${to}」には、すでに $($conflicts -join '、') があります。空のフォルダを選んでください。"
        }
        $entries = @($this.ListEntries($from))
        [System.IO.Directory]::CreateDirectory((toLongPath $to)) | Out-Null
        $moved = New-Object System.Collections.Generic.List[string]
        try {
            foreach ($source in $entries) {
                $this.MoveEntry($source, (Join-Path $to ([System.IO.Path]::GetFileName($source))))
                $moved.Add($source)
            }
        } catch {
            $reason = $_.Exception.Message
            for ($i = $moved.Count - 1; $i -ge 0; $i--) {
                try {
                    $this.MoveEntry((Join-Path $to ([System.IO.Path]::GetFileName($moved[$i]))), $moved[$i])
                } catch {
                    # 戻せなかったものは、移した先に残る（例外のメッセージで両方の場所を伝える）
                }
            }
            throw "ワークスペースの中身を「${to}」へ移せませんでした（${reason}）。ファイルを開いているアプリを閉じてから、もう一度変えてください。中身は「${from}」に残しています。"
        }
        return $moved.Count
    }

    [int] RemoveEntries([string]$dir) {
        # ワークスペース dir の tebunko のファイル・フォルダ（Workspace.Entries）を削除し、削除した数を返す。ほかのファイルは消さない。
        # ワークスペースに選んだフォルダのインデックスを使わず、消して最初からやり直すときに使う
        $entries = @($this.ListEntries($dir))
        foreach ($entry in $entries) {
            $long = toLongPath $entry
            if ([System.IO.Directory]::Exists($long)) {
                removeDirectoryRetry $entry
            } else {
                [System.IO.File]::Delete($long)
            }
        }
        return $entries.Count
    }

    [int] UseTargets([string]$dir) {
        # ワークスペース dir の取り込み一覧にあるクロール対象フォルダを、インデックスの一覧（設定の targetFolders）にし、その数を返す。
        # ほかの人が作ったワークスペースを使うとき、一覧をそのワークスペースに合わせる（合わせないままインデックス作成をすると、
        # 一覧に無いインデックスは、インデックス更新の確認に「削除予定」として出る。findDroppedIndexes）。取り込み一覧が無ければ一覧は変えない
        $map = getIndexNameMap (newWorkspace $dir.TrimEnd("\")).StatusFile
        if ($map.Count -eq 0) {
            return 0
        }
        writeTargetFolders @($map.Keys | ForEach-Object { [pscustomobject]@{ Name = $_; Path = $map[$_]; Enabled = $true } }) $this.SettingsPath
        return $map.Count
    }

    hidden [void] MoveEntry([string]$source, [string]$dest) {
        # ファイル・フォルダを 1 つ移す。同じドライブならそのまま移し、別のドライブのフォルダは写してから元を消す
        # （Directory.Move は別のドライブへ移せないため）。写している途中で失敗したら、写した分を消して例外にする
        $longSource = toLongPath $source
        $longDest = toLongPath $dest
        if (![System.IO.Directory]::Exists($longSource)) {
            # File.Move は別のドライブへも移せる
            [System.IO.File]::Move($longSource, $longDest)
            return
        }
        if ([System.IO.Path]::GetPathRoot($source) -eq [System.IO.Path]::GetPathRoot($dest)) {
            [System.IO.Directory]::Move($longSource, $longDest)
            return
        }
        try {
            $this.CopyTree($longSource, $longDest)
        } catch {
            removeDirectoryRetry $dest
            throw
        }
        removeDirectoryRetry $source
    }

    hidden [void] CopyTree([string]$source, [string]$dest) {
        # フォルダを中身ごと写す（\\?\ 付きのパスを受け取る）
        [System.IO.Directory]::CreateDirectory($dest) | Out-Null
        foreach ($file in [System.IO.Directory]::GetFiles($source)) {
            [System.IO.File]::Copy($file, [System.IO.Path]::Combine($dest, [System.IO.Path]::GetFileName($file)))
        }
        foreach ($sub in [System.IO.Directory]::GetDirectories($source)) {
            $this.CopyTree($sub, [System.IO.Path]::Combine($dest, [System.IO.Path]::GetFileName($sub)))
        }
    }
}

# ［新規で開く］のためのコピー（テキスト・PDF など、「新規」の開き方が無い種類のファイル）の作成と片付け（状態層）。
# コピーは $workspace.TmpRoot\<PC の鍵>\open_copy\<12 桁の文字>\<元の名前>（コピー yyyyMMdd-HHmm）.<拡張子> に置く（getOpenCopyDir・getOpenCopyName）。
# 片付けは GUI の起動時にだけ行い、1 日より古いものを消す（開いているコピーは消せずに残る。閉じるときには消さない）。
# 作る・消すときは、置き場所がワークスペースの TmpRoot\<PC の鍵>\open_copy そのものであり、リンク（ジャンクション・シンボリックリンク）で
# 外へつながっていないことを確かめてから行う（testOpenCopyDir）。

# open_copy の置き場所の名前（片付けが、消してよい場所かを見るときにも使う）
${openCopyDirName} = "open_copy"
# 開くためのコピーを残す日数（これより古いものを起動時に消す）
${openCopyKeepDays} = 1

function getOpenCopyDir {
    # 開くためのコピーを置くフォルダ（$workspace.TmpRoot\<PC の鍵>\open_copy）を返す。文字列を組み立てるだけで、ファイルには触らない。
    # 取り込みの作業フォルダ（<PC の鍵>\<PID>）と同じ親の下に置くが、名前が数字でないため、取り込みの片付け（removeStaleProcessDirs）は触らない
    param (
        [Workspace]$workspace
    )

    return Join-Path $workspace.TmpRoot (Join-Path (getMachineKey) ${openCopyDirName})
}

function testOpenCopyReparsePoint {
    # path がリンク（ReparsePoint）か。無いパスは $false（まだ作っていない）。属性が読めないなど、確かめられないときは $true（辿らない側に倒す）
    param (
        [string]$path
    )

    try {
        $attributes = [System.IO.File]::GetAttributes((toLongPath $path))
    } catch [System.IO.FileNotFoundException] {
        return $false
    } catch [System.IO.DirectoryNotFoundException] {
        return $false
    } catch {
        return $true
    }
    return [bool]($attributes -band [System.IO.FileAttributes]::ReparsePoint)
}

function testOpenCopyDir {
    # copyDir が、open_copy の置き場所として使ってよいものか。コピーの作成・片付けは、これが真のときだけ行う。
    #   絶対パス（ドライブ付き・UNC）で、途中に .. や余計な区切りを含まず、tmpRoot\<PC の鍵>\open_copy と一致すること
    #   copyDir・その親（<PC の鍵>）・その親（tmpRoot）が、リンク（ReparsePoint）でないこと（まだ無ければ問題にしない）
    # 空・ドライブの直下・相対パス・別の場所の open_copy・リンクの先は $false
    param (
        [string]$copyDir,
        [string]$tmpRoot
    )

    if (!$copyDir -or !$copyDir.Trim() -or !$tmpRoot -or !$tmpRoot.Trim()) {
        return $false
    }
    $trimmed = $copyDir.TrimEnd([char]92, [char]47)
    if ($trimmed -notmatch '^([A-Za-z]:\\|\\\\[^\\])' -or $tmpRoot -notmatch '^([A-Za-z]:\\|\\\\[^\\])') {
        return $false
    }
    try {
        $full = [System.IO.Path]::GetFullPath($trimmed)
        $expected = [System.IO.Path]::GetFullPath((Join-Path (Join-Path $tmpRoot (getMachineKey)) ${openCopyDirName}))
    } catch {
        return $false
    }
    if (![string]::Equals($trimmed, $full, [System.StringComparison]::OrdinalIgnoreCase) -or
        ![string]::Equals($full, $expected.TrimEnd([char]92), [System.StringComparison]::OrdinalIgnoreCase)) {
        return $false
    }
    $keyDir = [System.IO.Path]::GetDirectoryName($full)
    foreach ($checked in @($full, $keyDir, [System.IO.Path]::GetDirectoryName($keyDir))) {
        if (testOpenCopyReparsePoint $checked) {
            return $false
        }
    }
    return $true
}

function getOpenCopyName {
    # 開くためのコピーの名前 <元の名前>（コピー yyyyMMdd-HHmm）.<拡張子>（コピーだと分かる名前にする）。
    # パスの区切りが紛れていても、ファイル名だけを使う。名前が空なら空文字。
    # 同じ名前のコピーが重ならないよう、置く場所は copySourceForOpen が 1 回ごとに別のフォルダにする
    param (
        [string]$book,
        [datetime]$now = (Get-Date)
    )

    $leaf = [System.IO.Path]::GetFileName(([string]$book).TrimEnd('.', ' ').Replace("/", "\"))
    if (!$leaf) {
        return ""
    }
    $extension = [System.IO.Path]::GetExtension($leaf)
    $baseName = $leaf.Substring(0, $leaf.Length - $extension.Length)
    $stamp = $now.ToString("yyyyMMdd-HHmm", [System.Globalization.CultureInfo]::InvariantCulture)
    return "${baseName}（コピー ${stamp}）${extension}"
}

function getOpenCopyBlocker {
    # コピーを作らずに断る理由（ファイルには触らない）。作れるなら空文字。
    #   NoName  … 名前が空
    #   TooLong … コピーのパスが長すぎる（260 文字の制限）
    # 名前に [ ] を含んでも断らない（コピーも開くのも、パスをそのまま（リテラルで）扱う）
    param (
        [string]$book,
        [string]$copyDir,
        [datetime]$now = (Get-Date)
    )

    $name = getOpenCopyName $book $now
    if (!$name) {
        return "NoName"
    }
    # <copyDir>\<12 桁>\<名前>
    if ($copyDir.TrimEnd([char]92).Length + 1 + 12 + 1 + $name.Length -ge 259) {
        return "TooLong"
    }
    return ""
}

function copySourceForOpen {
    # 元のファイルのコピーを copyDir の下に作る（元のファイルは変えない）。@{ Path; Reason } を返す。
    #   作れたとき: Path = コピーのパス、Reason = ""
    #   作れなかったとき: Path = ""、Reason = Place（置き場所の確かめで断った）・NoName／TooLong（getOpenCopyBlocker の結果）・Failed（作る・書くのに失敗した）
    # 同じ名前のコピーが重ならないよう、1 回ごとに別のフォルダ（copyDir\<12 桁の文字>）に置く。名前は getOpenCopyName。
    param (
        [string]$sourcePath,
        [string]$book,
        [string]$copyDir,
        [string]$tmpRoot,
        [datetime]$now = (Get-Date)
    )

    if (!(testOpenCopyDir $copyDir $tmpRoot)) {
        return @{ Path = ""; Reason = "Place" }
    }
    $blocker = getOpenCopyBlocker $book $copyDir $now
    if ($blocker) {
        return @{ Path = ""; Reason = $blocker }
    }
    $name = getOpenCopyName $book $now
    $dir = Join-Path $copyDir ([guid]::NewGuid().ToString("N").Substring(0, 12))
    $destPath = Join-Path $dir $name
    try {
        [System.IO.Directory]::CreateDirectory((toLongPath $dir)) | Out-Null
        copyFileShared $sourcePath $destPath
    } catch {
        return @{ Path = ""; Reason = "Failed" }
    }
    return @{ Path = $destPath; Reason = "" }
}

function getOpenCopyLatestTime {
    # 1 つ下のフォルダの「最後に使った日時」。フォルダの作成・更新と、中のファイルの更新のうち新しいもの
    # （編集して保存したコピーを、作ってから 1 日たったからといってすぐ消さないため）
    param (
        [System.IO.DirectoryInfo]$folder
    )

    $latest = $folder.CreationTime
    if ($folder.LastWriteTime -gt $latest) {
        $latest = $folder.LastWriteTime
    }
    foreach ($copy in @(Get-ChildItem -LiteralPath $folder.FullName -File -Force)) {
        if ($copy.LastWriteTime -gt $latest) {
            $latest = $copy.LastWriteTime
        }
    }
    return $latest
}

function clearOldOpenCopies {
    # copyDir の下の、最後に使ってから keepDays 日より古いコピー（1 つ下のフォルダごと）を消し、消したフォルダの数を返す。
    # 最後に使った日時は getOpenCopyLatestTime。現在より先の日時（時計のずれ）は新しい扱いになり、消さずに残る（消さない側に倒す）。
    # 消すのは open_copy の 1 つ下のフォルダの中のファイルだけ（testOpenCopyDir が偽なら何もしない。フォルダごとに消す直前にも確かめ、偽になっていればそこで止める）。
    # リンク（ジャンクション・シンボリックリンク）は辿らず、使用中で消せないコピーは残す。再帰の削除は使わない
    param (
        [string]$copyDir,
        [string]$tmpRoot,
        [datetime]$now = (Get-Date),
        [int]$keepDays = ${openCopyKeepDays}
    )

    if (!(testOpenCopyDir $copyDir $tmpRoot) -or !(Test-Path -LiteralPath $copyDir -PathType Container)) {
        return 0
    }
    $limit = $now.AddDays(-$keepDays)
    $prefix = $copyDir.TrimEnd([char]92) + "\"
    $cleared = 0
    foreach ($old in @(Get-ChildItem -LiteralPath $copyDir -Directory -Force)) {
        if ($old.Attributes -band [System.IO.FileAttributes]::ReparsePoint) {
            continue
        }
        if (!$old.FullName.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase) -or (getOpenCopyLatestTime $old) -ge $limit) {
            continue
        }
        # 確かめてから消すまでの間に置き場所がリンクに替わっていないか、フォルダごとに消す直前にもう一度確かめる
        if (!(testOpenCopyDir $copyDir $tmpRoot)) {
            break
        }
        # 消すフォルダ自身も、列挙してから消すまでの間にリンクに替わっていないかを確かめる（リンクなら辿らない）
        if (testOpenCopyReparsePoint $old.FullName) {
            continue
        }
        foreach ($copy in @(Get-ChildItem -LiteralPath $old.FullName -File -Force)) {
            if ($copy.Attributes -band [System.IO.FileAttributes]::ReparsePoint) {
                continue
            }
            try {
                [System.IO.File]::SetAttributes((toLongPath $copy.FullName), [System.IO.FileAttributes]::Normal)
                [System.IO.File]::Delete((toLongPath $copy.FullName))
            } catch {
                # 開いているコピーは残す（次の起動で消す）
            }
        }
        try {
            [System.IO.Directory]::Delete((toLongPath $old.FullName), $false)
            $cleared++
        } catch {
            # 中にコピーが残っている（開いている）・既に無い
        }
    }
    return $cleared
}

# 部品（lib・indexerLib）の読み込み先をまとめる。
# zip 版は scripts 配下の実際のファイルを dot-source し、単一 .ps1 版（展開せずに動く試験版）は
# 埋め込んだ部品の文字列（${bundledParts}）を関数（importTebunkoPart）としてランスペースに登録する。
# 設計は docs/design/structure/single-script.md・docs/design/structure/classes.md「クラスのつなぎ方」。
#
# 画面だけのクラス（SearchTarget・IndexNode など、ui\ 配下）は ${bundledParts} に含まれない。背景の
# スレッド・別のランスペースがこの部品だけを読み込んでも、画面のクラスを二重にコンパイルしない
# （PowerShell 5.1 は class を構文解析の時点でそのランスペースの型として登録するため、同じ名前の class を
# 別のランスペースでもう一度解析すると、型が別物になり画面のスレッドとキャストできなくなる）。
#
# 単一 .ps1 版かどうかは、先頭で定義する変数 ${bundledParts} の有無だけで決める
# （結合の道具 tools/new_single_script.ps1 が作る）。
# 別スレッド・別ランスペースで部品を読み込むところは、パスの文字列やソースを直接組み立てず、必ずここを通す。

function getPartLoad {
    # 戻り値は @{ State = <InitialSessionState>; Prelude = <部品を読み込む 1 行の文字列> }。
    # 呼び出し側は、この State でランスペース（または WorkerPool）を作り、Prelude を本体の前につないで
    # （shared\core\worker_pool.ps1 の joinWorkerScript）動かす。
    #
    # zip 版: State はただの既定値、Prelude はそのファイルを dot-source する 1 行。
    # 単一 .ps1 版: State に、埋め込んだ部品の文字列を本体に持つ関数 importTebunkoPart を登録し、
    #   Prelude はその関数を呼ぶだけの 1 行（". importTebunkoPart"）。関数の本体は、その State で
    #   ランスペースを作ったときに 1 回だけ構文解析される
    param (
        [ValidateSet("lib", "indexerLib")]
        [string]$name,
        # 部品を読み込んだあとに続けて呼ぶ文（例: initWorkspace）。空なら足さない
        [string]$then = ""
    )

    $state = [System.Management.Automation.Runspaces.InitialSessionState]::CreateDefault2()
    $bundled = Get-Variable -Name bundledParts -ErrorAction SilentlyContinue
    if ($null -ne $bundled -and $bundled.Value) {
        $body = $bundled.Value[$name]
        if ($null -eq $body) {
            throw "単一 .ps1 版に ${name} の部品が入っていません。"
        }
        $entry = New-Object System.Management.Automation.Runspaces.SessionStateFunctionEntry("importTebunkoPart", $body)
        $state.Commands.Add($entry)
        # 部品の中（version.ps1 の readVersionFile など）が ${bundledScriptPath}・${bundledVersion} を見るため、
        # 呼び出したスレッドの値をそのまま渡す（bundledParts も渡す。取り込みのスレッドの中でもう一度 getPartLoad を呼ぶため）
        foreach ($varName in "bundledParts", "bundledScriptPath", "bundledVersion") {
            $variable = Get-Variable -Name $varName -ErrorAction SilentlyContinue
            if ($null -ne $variable) {
                $variableEntry = New-Object System.Management.Automation.Runspaces.SessionStateVariableEntry($varName, $variable.Value, "")
                $state.Variables.Add($variableEntry)
            }
        }
        $prelude = ". importTebunkoPart"
        if ($then) { $prelude = "$prelude; $then" }
        return @{ State = $state; Prelude = $prelude }
    }

    # indexerLib は、取り込みのスレッド・インデクサの司令のスレッドの両方から使うため、
    # 関数（indexer_lib.ps1）と、呼び出す口（invokeIndexerMain・indexer_main.ps1）をまとめて読み込む
    $paths = switch ($name) {
        "lib" { @("${tebunkoRoot}\..\lib.ps1") }
        "indexerLib" { @("${tebunkoRoot}\..\indexer\indexer_lib.ps1", "${tebunkoRoot}\..\indexer\indexer_main.ps1") }
    }
    $prelude = ($paths | ForEach-Object {
        # 一重引用符の文字（' と、PowerShell が同じ引用符として扱う U+2018・U+2019・U+201A・U+201B）は、重ねて文字列の中に入れる
        $resolved = [regex]::Replace([System.Management.Automation.WildcardPattern]::Escape([System.IO.Path]::GetFullPath($_).Replace('`', '``')), "(['\u2018\u2019\u201A\u201B])", '$1$1')
        ". '$resolved'"
    }) -join "; "
    if ($then) { $prelude = "$prelude; $then" }
    return @{ State = $state; Prelude = $prelude }
}

# tebunko が使うファイルの場所と、そこに書く値の定義。

# 取り込みの作業フォルダ（本体はワークスペースの tmp\ の下。index_migrate.ps1 の initTmpDir が
# インデックス作成の始めに selectTmpDir で決めて入れる）。決めるまでの既定値は空。
# 置けなかったとき（パスに [ ] がある・長すぎる）も空のまま（どのファイルも中間 TSV などをこのフォルダに作るため、
# テキストファイルを含めすべての取り込みをスキップする。%TEMP% には逃がさない）
${tmpDir} = ""
# ${tmpDir} を置けなかった理由（selectTmpDir の Reason）。置けたときは空
${tmpDirReason} = ""

# 前の版（%TEMP%\tebunko\<PID> に一時ファイルを置いていた版）が残した作業フォルダの片付け専用。
# 今の版はここには書き込まない（removeStaleTmpDirs が、強制終了などで残った前の版のフォルダを消すためだけに使う）
${legacyTmpParent} = Join-Path ([System.IO.Path]::GetTempPath()) "tebunko"

# Excelで開けるパスの長さの目安（古い版の上限）。作業フォルダの候補がこれ以上ならワークスペースの tmp\ を諦める
$excelMaxPath = 218
# 取り込みのスレッドが作業フォルダの下に作る、最も長いファイル名の分（"\w999\converted.pptx"）。
# selectTmpDir で、この分を足しても $excelMaxPath を超えないかを見る
${tmpNameReserve} = "\w999\converted.pptx".Length

# ワークスペース（インデックス・取り込み一覧・ログ・取り込みの出力の置き場所。中の場所は workspace.ps1 の Workspace）。
# setting.config の workspaceFolder で変えられる。空なら既定（settings.ps1 の getWorkDir）。
# 読み込んだとき（スクリプトの読み込み時）には決めず、起動口（startGui・invokeIndexerMain）が
# 壊れた設定ファイルの退避の後に呼ぶ（単一 .ps1 版は setting.config を読む前に読み込みだけ先に済ませるため）
function initWorkspace {
    ${script:workspace} = [Workspace]::new((getWorkDir))
}

# 取り込みのスレッドが、司令のスレッドから受け取った場所（Workspace）を、呼んだスクリプトのスコープに置く。
# $workspace を決めるのはこのファイルだけにするため、取り込みのスレッドのスクリプトからもここを呼ぶ
# （取り込みのスレッドでは、呼んだスコープは global。部品を読み込んだのと同じスコープになる）
function setCallerWorkspace {
    param (
        $value
    )

    Set-Variable -Name workspace -Value $value -Scope 1
}

# インデックスのフォルダに置く、インデックス名とクロール対象フォルダの対応（インデクサが作成する）。
# インデックスのフォルダごと別の場所・PCへコピーしても、検索結果から元のファイルの場所が分かるようにする。
# 拡張子を .tsv にすると検索対象になるため .txt にする
${sourceFolderFileName} = "source_folder.txt"

# 前の版(ワークスペースのファイル名を英語化する前)の元のフォルダの記録。
# getLegacyIndexState が旧版の index\ フォルダを見分けるためだけに使う。読み取り専用。
${legacySourceFolderFileName} = "元のフォルダ.txt"

# インデックス作成の進み具合の段階（writeIndexingProgress の phase）
${indexingPhaseCrawl}   = "クロール"  # 取り込み対象のファイルを探している（件数はまだ分からない）
${indexingPhaseConfirm} = "確認"      # 取り込み対象を数え終え、画面で取り込むかどうかを選ぶのを待っている
${indexingPhaseIngest}  = "取り込み"  # 1ファイルずつ取り込んでいる
${indexingPhaseFinish}  = "仕上げ"    # 後片付け（Officeアプリの終了・取り込み一覧の書き直し）

# 取り込み予定（newIngestPlanRow）の列と、インデックスごとの区分
${ingestPlanColumns} = @("インデックス名", "元のフォルダ", "区分", "ファイル数", "取り込み対象", "新規", "更新あり", "前回未完了", "インデックスなし", "前回失敗", "クラウド", "クラウド失敗", "クラウド容量", "クラウド失敗容量")
${planKindIngest}    = "取り込み"      # チェックが付いていて元のフォルダも見つかった（数えた結果を出す）
${planKindUnchecked} = "チェックなし"  # チェックが外れているため数えていない
${planKindMissing}   = "フォルダなし"  # 元のフォルダが見つからないため数えていない
${planKindDropped}   = "削除予定"      # 設定から外れたインデックス（確認で［更新を開始］が押されたときだけ消す）

# 取り込み一覧の列と状態
${statusColumns}   = @("相対パス", "更新日時", "サイズ", "状態", "TSV数", "取り込み日時", "エラー", "抽出版")
${statusFolderKey} = "クロール対象フォルダ"
${stateNew}    = "未取り込み"
${stateDone}   = "済"
${stateFailed} = "失敗"

# 取り込み一覧（status ファイル）の読み書き（状態層）。列と状態の定義は paths.ps1。

function newStatusRow {
    # 取り込み一覧の1行（1ファイル）を作る
    param (
        [string]$relPath,
        [string]$updated = "",
        [string]$size = "",
        [string]$state = ${stateNew},
        [string]$tsvCount = "",
        [string]$ingested = "",
        [string]$errorMessage = "",
        [string]$extractVersion = ""
    )

    return [pscustomobject]@{
        相対パス = $relPath
        更新日時 = $updated
        サイズ   = $size
        状態     = $state
        TSV数    = $tsvCount
        取り込み日時 = $ingested
        エラー   = $errorMessage
        抽出版   = $extractVersion
    }
}

# 1行1件を保つため、タブ・改行はスペースにする（この文字を含む値だけ置き換える）
${statusLineBreaks} = [char[]]@("`t", "`r", "`n")


function toStatusLine {
    # 取り込み一覧の1行を文字列にする（1件ずつの追記用。addStatusRow）。
    # エラーメッセージ等のタブ・改行は、1行1件を保つためスペースにする。
    # 数万行をまとめて書き出す writeStatusFile では、同じ整形をその場に展開している（関数の呼び出しだけで
    # 5万行あたり数秒かかるため）。整形を変えるときは両方を直す（テストで同じ結果になることを確かめている）
    param (
        $row
    )

    $errorText = [string]$row.エラー
    if ($errorText.IndexOfAny(${statusLineBreaks}) -ge 0) {
        $errorText = $errorText -replace "[\t\r\n]+", " "
    }
    return [string]::Join("`t", @(
        [string]$row.相対パス, [string]$row.更新日時, [string]$row.サイズ, [string]$row.状態,
        [string]$row.TSV数, [string]$row.取り込み日時, $errorText, [string]$row.抽出版))
}

function readStatusFile {
    # 取り込み一覧を読み込み、@{ Folders; Rows } を返す。ファイルが無ければ空。
    #   Folders: クロール対象フォルダ @{ Path; Name（インデックス名） } の配列
    #   Rows   : 相対パス（"インデックス名\フォルダからの相対パス"。大文字・小文字を区別しない）→ 行
    # インデックス作成中は1件ごとに行を追記するため、同じ相対パスの行は後の行を優先する。列数の合わない行（書き込み途中で中断した行など）は無視する
    param (
        [string]$path = $workspace.StatusFile
    )

    $rows = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
    $folders = New-Object System.Collections.Generic.List[object]
    $result = @{ Folders = $folders; Rows = $rows }
    if (!(Test-Path -LiteralPath $path)) {
        return $result
    }

    # インデックス作成中に画面などから読んでも、インデクサの追記・置き換えを妨げないよう共有を許して開く
    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $stream = New-Object System.IO.FileStream($path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    $reader = New-Object System.IO.StreamReader($stream, ${utf8Bom})
    try {
        $lines = $reader.ReadToEnd() -split "\r?\n"
    } finally {
        $reader.Dispose()
    }

    $columnCount = ${statusColumns}.Count
    foreach ($line in $lines) {
        $fields = $line.Split("`t")
        if ($fields[0] -eq ${statusFolderKey} -and $fields.Count -eq 3) {
            $folders.Add([pscustomobject]@{ Path = $fields[1]; Name = $fields[2] })
            continue
        }
        if ($fields.Count -ne $columnCount -or $fields[0] -eq "" -or $fields[0] -eq ${statusColumns}[0]) {
            continue
        }
        # 数万行を読むため、1行ごとの関数呼び出し（newStatusRow）は使わずにその場で作る（列は $statusColumns と同じ）
        $rows[$fields[0]] = [pscustomobject]@{
            相対パス = $fields[0]
            更新日時 = $fields[1]
            サイズ   = $fields[2]
            状態     = $fields[3]
            TSV数    = $fields[4]
            取り込み日時 = $fields[5]
            エラー   = $fields[6]
            抽出版   = $fields[7]
        }
    }
    return $result
}

function writeStatusFile {
    # 取り込み一覧を書き出す（1ファイル1行）。途中で中断しても壊れないよう、一時ファイルに書いてから置き換える
    #   folders: クロール対象フォルダ @{ Path; Name } の配列。"クロール対象フォルダ<TAB>パス<TAB>インデックス名" の行にする
    param (
        [object[]]$folders,
        [object[]]$rows,
        [string]$path = $workspace.StatusFile
    )

    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($folder in @($folders | Where-Object { $_ })) {
        $lines.Add("${statusFolderKey}`t$($folder.Path)`t$($folder.Name)")
    }
    $lines.Add((${statusColumns} -join "`t"))
    # 数万行を書き出すため、1行ごとの関数呼び出し（toStatusLine）・パイプライン（Where-Object）は使わない
    # （5万行で約 10 秒 → 約 0.2 秒。この間はインデックス作成の進み具合が止まって見えるため速くする）
    foreach ($row in $rows) {
        if ($null -eq $row) {
            continue
        }
        $errorText = [string]$row.エラー
        if ($errorText.IndexOfAny(${statusLineBreaks}) -ge 0) {
            $errorText = $errorText -replace "[\t\r\n]+", " "
        }
        $lines.Add([string]::Join("`t", @(
            [string]$row.相対パス, [string]$row.更新日時, [string]$row.サイズ, [string]$row.状態,
            [string]$row.TSV数, [string]$row.取り込み日時, $errorText, [string]$row.抽出版)))
    }

    writeTextLinesAtomic $path $lines
}

function getIndexNameMap {
    # 取り込み一覧に記録したインデックス名 → クロール対象フォルダのパス（大文字・小文字を区別しない）。
    # クロール対象フォルダの行は先頭にあるため、見出し行まで読んで打ち切る（取り込み一覧が大きくても時間がかからないように）
    param (
        [string]$path = $workspace.StatusFile
    )

    $map = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::OrdinalIgnoreCase)
    if (!(Test-Path -LiteralPath $path)) {
        return , $map
    }
    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $stream = New-Object System.IO.FileStream($path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    $reader = New-Object System.IO.StreamReader($stream, ${utf8Bom})
    try {
        $header = ${statusColumns} -join "`t"
        while ($null -ne ($line = $reader.ReadLine())) {
            if ($line -eq $header) {
                break
            }
            $fields = $line.Split("`t")
            if ($fields[0] -eq ${statusFolderKey} -and $fields.Count -eq 3 -and $fields[2]) {
                $map[$fields[2]] = $fields[1]
            }
        }
    } finally {
        $reader.Dispose()
    }
    return , $map
}

# インデックス名に対する元のフォルダを記録できるかの判断（判断層。ファイルに触らない）。

function testSourceNameRecordable {
    # インデックス名に対する元のフォルダを設定に記録できる名前か。空の名前と、前後に空白（全角空白・NBSP・タブを含む）がある名前は、
    # 設定を読み戻すとき前後の空白が削られて同じ名前にならない（確かめ済みにならない）ため記録しない。
    # 状態層（setIndexSourceFolder）の入口の条件と、画面の文言（記録されないときは毎回確かめる）で同じ判断を使う。
    # 文字数で比べる（-ne はカルチャに従う）
    param (
        [string]$name
    )

    $trimmed = $name.Trim()
    return $trimmed.Length -gt 0 -and $trimmed.Length -eq $name.Length
}

# インデックス名と TSV のファイル名の決め方（判断層。ファイルに触らない）。

function newIndexName {
    # クロール対象フォルダのインデックス名（work\index 直下のフォルダ名）を作る。
    # フォルダ名（ドライブ直下はドライブ名）を使い、usedNames と重複すれば「名前(2)」「名前(3)」…とする
    param (
        [string]$folderPath,
        $usedNames = $null  # HashSet[string]・配列・1 個の文字列・$null のいずれでもよい
    )

    $base = toSafeFileName (getFolderLeafName $folderPath)
    if ($base -eq "") {
        $base = "フォルダ"
    }

    # 呼び出し側から $null や文字列の配列で渡されても落ちないよう、ここで集合に直す（大文字・小文字は区別しない）
    $used = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    # 集合が 1 要素の配列に入って渡されても（@(関数) で受けた場合など）、中身を 1 つずつ取り出す
    foreach ($entry in @($usedNames)) {
        foreach ($usedName in @($entry)) {
            if ($usedName) {
                [void]$used.Add([string]$usedName)
            }
        }
    }

    $name = $base
    for ($i = 2; $used.Contains($name); $i++) {
        # 長いフォルダ名に (2) を付けるとファイル名の上限を超えてフォルダを作れないため、上限に収まるよう名前を切り詰める
        $suffix = "(${i})"
        $name = $base.Substring(0, [Math]::Min($base.Length, ${maxFileNameLength} - $suffix.Length)) + $suffix
    }
    return $name
}

function assignIndexNames {
    # クロール対象フォルダ（getTargetFolders）にインデックス名を割り当て、@{ Path; Enabled; Name } の配列を返す。
    # インデックス名は設定に持つ（getTargetFolders の Name）。フォルダの置き場所（Path）を書き換えても名前は変わらないため、
    # フォルダを移しても同じインデックスとして扱える（インデックスを作り直さない）。
    # 名前が無い場合（新しく追加したフォルダ）は、前回の取り込み一覧の同じパスの名前を使い、
    # それも無ければフォルダ名から重複しない名前を作る
    param (
        [object[]]$targetFolders,
        [object[]]$previousFolders  # readStatusFile の Folders（@{ Path; Name }）
    )

    $previousNames = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($folder in @($previousFolders | Where-Object { $_ -and $_.Name })) {
        $previousNames[$folder.Path] = $folder.Name
    }

    # 設定にある名前・前回の名前は使わない（別のフォルダに同じ名前を付けてインデックスを取り違えないため）
    $used = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($name in $previousNames.Values) {
        [void]$used.Add($name)
    }
    foreach ($folder in @($targetFolders | Where-Object { $_ -and $_.Name })) {
        [void]$used.Add($folder.Name)
    }

    $result = New-Object System.Collections.Generic.List[object]
    foreach ($folder in @($targetFolders | Where-Object { $_ })) {
        $name = [string]$folder.Name
        if ($name -eq "") {
            if ($previousNames.ContainsKey($folder.Path)) {
                $name = $previousNames[$folder.Path]
            } else {
                $name = newIndexName $folder.Path $used
            }
            [void]$used.Add($name)
        }
        $result.Add([pscustomobject]@{ Path = $folder.Path; Enabled = $folder.Enabled; Name = $name })
    }
    return $result.ToArray()
}

function splitIndexRelPath {
    # work\index からの相対パスを、先頭のインデックス名と残り（クロール対象フォルダからの相対パス）に分ける: @{ Name; Rest }
    # （String.Split([char], 2) は .NET Framework では Split(params char[]) になり、2 も区切り文字とみなされるため使わない）
    param (
        [string]$relPath
    )

    $i = $relPath.IndexOf("\")
    if ($i -lt 0) {
        return @{ Name = $relPath; Rest = "" }
    }
    return @{ Name = $relPath.Substring(0, $i); Rest = $relPath.Substring($i + 1) }
}


# Windows で使えないファイル名（インデックス名に使えるかの判定に使う）
${reservedFileNames} = @("CON", "PRN", "AUX", "NUL") +
    @(1..9 | ForEach-Object { "COM$_" }) + @(1..9 | ForEach-Object { "LPT$_" })


function testIndexName {
    # インデックス名（work\index 直下のフォルダ名）として使えるかを調べ、使えない理由を返す（使えれば空文字列）。
    #   usedNames: ほかのインデックスが使っている名前（大文字・小文字を区別しない）
    param (
        [string]$name,
        [object[]]$usedNames = @()
    )

    $name = [string]$name
    if ($name -eq "") {
        return "名前を入力してください。"
    }
    if ($name -ne $name.Trim()) {
        return "名前の前後に空白は使えません。"
    }
    if ($name.Length -gt ${maxFileNameLength}) {
        return "名前が長すぎます（${maxFileNameLength} 文字まで）。"
    }
    if (@([System.IO.Path]::GetInvalidFileNameChars() | Where-Object { $name.IndexOf($_) -ge 0 }).Count -gt 0) {
        return "名前に使えない文字が含まれています（\ / : * ? " + [char]34 + " < > | と制御文字）。"
    }
    if ($name.EndsWith(".")) {
        return "名前の最後に . は使えません。"
    }
    if (${reservedFileNames} -contains $name.Split(".")[0].ToUpperInvariant()) {
        return "「${name}」は Windows で使えない名前です。"
    }
    foreach ($used in @($usedNames)) {
        if ([string]::Equals([string]$used, $name, [System.StringComparison]::OrdinalIgnoreCase)) {
            return "「${name}」は、ほかのインデックスが使っています。別の名前を付けてください。"
        }
    }
    return ""
}

function encodeIndexPlace {
    # インデックスのTSVのファイル名に入れる場所（シート名・ページ・スライド）を符号化する。
    # ファイル名に使えない文字・制御文字と、_・符号化に使う % を "%XX"（16進数）にする（decodeIndexPlace で元に戻す）。
    #   ・全角に置き換えると `a"b` と `a”b` が同じファイル名になり、後のシートで上書きされるため、元に戻せる形にする
    param (
        [string]$place
    )

    return [regex]::Replace($place, '[\x00-\x1F"%*/:<>?\\_|]', { param($m) '%{0:X2}' -f [int][char]$m.Value })
}

function decodeIndexPlace {
    # encodeIndexPlace で符号化した場所を元に戻す（encodeIndexPlace が作る "%XX" だけを戻す）
    param (
        [string]$place
    )

    # 符号化した文字が無ければそのまま返す（検索のたびに全TSVの名前を分解するため、置換の呼び出しを省く）
    if ($place.IndexOf("%") -lt 0) {
        return $place
    }
    return [regex]::Replace($place, '%(?:[01][0-9A-F]|2[25AF]|3[ACEF]|5[CF]|7C)', { param($m) [string][char][Convert]::ToInt32($m.Value.Substring(1), 16) })
}

# 決まった場所（ページ・スライド・ヘッダー/フッター・脚注・文書・本文）は、ファイル名を ASCII の固定名にする。
# 符号化した場所（encodeIndexPlace）には "_" が出ないため（"_" は "%5F" にする）、固定名に "_" を使っても
# シート名由来のファイル名と重ならない（convertIndexFileNameToPlace で戻すときの手掛かりにする）。
function convertPlaceBaseToFixedFileName {
    # 場所の元の部分（種類を除いた部分）を、決まったASCIIのファイル名にする（当てはまらなければ空文字列）。
    #   数字はそのまま桁を写す（int にしない。"001" は "001" のまま）
    param (
        [string]$base
    )

    if ($base -match '^ページ(\d+)$') { return "page_$($Matches[1])" }
    if ($base -match '^スライド(\d+)（非表示）$') { return "slide_$($Matches[1])_hidden" }
    if ($base -match '^スライド(\d+)_ノート$') { return "slide_$($Matches[1])_notes" }
    if ($base -match '^スライド(\d+)$') { return "slide_$($Matches[1])" }
    if ($base -eq "ヘッダー・フッター") { return "header_footer" }
    if ($base -eq "脚注") { return "doc_footnotes" }
    if ($base -eq "文書") { return "doc_whole" }
    if ($base -eq "本文") { return "doc_body" }
    return ""
}

function convertFixedFileNameToPlaceBase {
    # convertPlaceBaseToFixedFileName の逆変換（当てはまらなければ空文字列）
    param (
        [string]$fileBase
    )

    if ($fileBase -match '^page_(\d+)$') { return "ページ$($Matches[1])" }
    if ($fileBase -match '^slide_(\d+)_hidden$') { return "スライド$($Matches[1])（非表示）" }
    if ($fileBase -match '^slide_(\d+)_notes$') { return "スライド$($Matches[1])_ノート" }
    if ($fileBase -match '^slide_(\d+)$') { return "スライド$($Matches[1])" }
    if ($fileBase -eq "header_footer") { return "ヘッダー・フッター" }
    if ($fileBase -eq "doc_footnotes") { return "脚注" }
    if ($fileBase -eq "doc_whole") { return "文書" }
    if ($fileBase -eq "doc_body") { return "本文" }
    return ""
}

function toIndexFileName {
    # インデックスのTSVのファイル名 "<場所>.tsv" を返す。
    #   ・決まった場所（ページ・スライド・ヘッダー/フッター・脚注・文書・本文）は ASCII の固定名にする
    #   ・それ以外（Excelのシート名）は encodeIndexPlace で符号化する
    #   ・図形・コメント・ヘッダー・フッター・埋め込みは、末尾に英語の種類 "[shape]" "[comment]" "[header_footer]" "[embed<N>]" を付ける（placeKindFileNames）
    # 元のファイル名はフォルダ名（= 元のファイル名そのもの）にするため、ファイル名には入れない。
    # ファイル名の上限（255文字）は長いパスの対応（toLongPath）でも超えられないため、超える場合は分かるメッセージで例外にする
    param (
        [string]$place
    )

    $split = splitObjectPlace $place
    $fixedName = convertPlaceBaseToFixedFileName $split.Base
    $base = if ($fixedName) { $fixedName } else { encodeIndexPlace $split.Base }
    $suffix = if ($split.Kind) { "[$(${placeKindFileNames}[$split.Kind])$(if ($split.Number -gt 0) { $split.Number })]" } else { "" }
    $name = "{0}{1}.tsv" -f $base, $suffix
    if ($name.Length -gt ${maxFileNameLength}) {
        throw "インデックスのファイル名が長すぎるため保存できません（$($name.Length) 文字。上限 ${maxFileNameLength} 文字）: ${name}"
    }
    return $name
}

function convertIndexFileNameToPlace {
    # toIndexFileName の逆変換。ファイル名（拡張子 .tsv を除いたもの）から場所を復元する。
    #   戻す順番: (1) 末尾の "[shape]"・"[comment]"・"[header_footer]"・"[embed<N>]"（placeKindFileNames の値）を外す →
    #             (2) 残りに "_" があれば固定の場所の表で戻し、無ければ decodeIndexPlace で戻す →
    #             (3) (1) で外した種類を日本語（[図形]・[コメント]・[ヘッダー・フッター]・[埋め込み<N>]）で付け直す
    param (
        [string]$fileNameWithoutExtension
    )

    $kind = ""
    $body = $fileNameWithoutExtension
    $fileKindAlternation = (${placeKindFileNames}.Values | ForEach-Object { [regex]::Escape($_) }) -join "|"
    if ($fileNameWithoutExtension -match "^(?<base>.+)\[(?<kind>$fileKindAlternation)(?<number>${objectPlaceNumberPattern})?\]`$") {
        $kindName = $Matches.kind
        $kind = (${placeKindFileNames}.GetEnumerator() | Where-Object { $_.Value -eq $kindName } | Select-Object -First 1).Key
        # 番号は埋め込みにだけ付く（ほかの種類に付いた名前は、この関数が作らない形のため戻さない）
        if (($kind -eq ${placeKindEmbed}) -eq [bool]$Matches.number) {
            $body = $Matches.base
            if ($Matches.number) { $kind = "${kind}$($Matches.number)" }
        } else {
            $kind = ""
        }
    }

    if ($body.IndexOf("_") -ge 0) {
        $base = convertFixedFileNameToPlaceBase $body
    } else {
        $base = decodeIndexPlace $body
    }

    if ($kind) { return "$base[$kind]" }
    return $base
}


# 図形・コメントなど、本文（セル・段落）以外の文字の場所は "<元の場所>[<種類>]" とする。
# 元の場所は、Excel ではシート名（例: "売上[図形]"。office_reader.ps1 の readXlsxObjectUnits）。
# Word はページ、PowerPoint はスライドを元の場所にする（例: "ページ003[コメント]" "スライド002[図形]"）。
# Excel のシート名には [ ] を使えず、Word・PowerPoint の場所（ページNNN・スライドNNN 等）にも付かないため、ふつうの場所と重ならない。
# 種類ごとに、検索に含めるかを画面で選べる（search_query.ps1 の newPlaceExclude）。
# 種類を足すときは、ここ（placeKindFileNames にも足す）と書き出す側（office_reader.ps1）をそろえる。検索の除外・画面の判定の正規表現は newObjectPlaceKindPattern が表から組み立てる
${placeKindShape}   = "図形"      # 図形・テキストボックス・WordArt・SmartArt・グラフ（PowerPoint のテキストボックス・図形はスライドの本文）
${placeKindComment} = "コメント"  # コメント（メモ・スレッド形式のコメント）
${placeKindHeaderFooter} = "ヘッダー・フッター"  # Excel のヘッダー・フッター（Word・PowerPoint の "ヘッダー・フッター" は場所の名前で、種類ではない）。いつも検索する（除外の選択肢は無い）
${placeKindEmbed}   = "埋め込み"  # Word・PowerPoint に埋め込んだ Office のファイル（.xlsx・.docx・.pptx など）の中の文字。場所は "<元の場所>[埋め込み<N>]"（N は 1 ファイルの中の通し番号。ほかの種類と違い、番号が付く）。図形と一緒に検索の有無を切り替える

# 種類ごとの、TSVのファイル名に付ける英語の名前（toIndexFileName・convertIndexFileNameToPlace で使う）。
# 番号の付く種類（埋め込み）のファイル名は "[embed<N>]"
${placeKindFileNames} = @{ ${placeKindShape} = "shape"; ${placeKindComment} = "comment"; ${placeKindHeaderFooter} = "header_footer"; ${placeKindEmbed} = "embed" }

# ${objectPlacePattern} の種類の選択肢は ${placeKindFileNames} のキーから組み立てる（足し忘れを防ぐ）。
# 番号の付く種類（埋め込み）は選択肢に入れず、番号（先頭が 0 でない数字）を付けた形だけを別に当てる
# （"[埋め込み]"・"[埋め込み01]" はふつうの場所とする）
${objectPlaceKindAlternation} = (${placeKindFileNames}.Keys | Where-Object { $_ -ne ${placeKindEmbed} } | ForEach-Object { [regex]::Escape($_) }) -join "|"
${objectPlaceNumberPattern} = "[1-9][0-9]{0,8}"
${objectPlacePattern} = "^(?<base>.*)\[(?:(?<kind>${objectPlaceKindAlternation})|(?<numberedKind>$([regex]::Escape(${placeKindEmbed})))(?<number>${objectPlaceNumberPattern}))\]$"


function newObjectPlaceKindPattern {
    # 場所の末尾の種類だけを当てる正規表現の文字列を、${placeKindFileNames} の表から組み立てる。
    # 検索から外す場所（search_query.ps1 の newPlaceExclude）と画面の判定（ui/search/result_types.ps1 の HitRow.ObjectPlaceRegex）が使う。
    #   例（全部）: \[(?:図形|コメント|ヘッダー・フッター|埋め込み[1-9][0-9]{0,8})\]$（選択肢の並びは表の順による）
    # kinds: 当てる種類の名前の並び（省略または空は全部）。番号の付く種類（埋め込み）は番号の形を付けて当てる
    param (
        [string[]]$kinds = @()
    )

    if ($kinds.Count -eq 0) {
        $kinds = @(${placeKindFileNames}.Keys)
    }
    $alternatives = foreach ($kind in $kinds) {
        if ($kind -eq ${placeKindEmbed}) { "$([regex]::Escape($kind))${objectPlaceNumberPattern}" } else { [regex]::Escape($kind) }
    }
    return "\[(?:$(@($alternatives) -join '|'))\]`$"
}


function splitObjectPlace {
    # 場所を @{ Base（元の場所）; Kind（種類。ふつうの場所は空）; Number（埋め込みの番号。ほかは 0） } に分ける。
    #   例: "売上[図形]" → @{ Base = "売上"; Kind = "図形"; Number = 0 } / "ページ001" → @{ Base = "ページ001"; Kind = ""; Number = 0 }
    #       "ページ003[埋め込み2]" → @{ Base = "ページ003"; Kind = "埋め込み"; Number = 2 }
    param (
        [string]$place
    )

    if ($place -match ${objectPlacePattern}) {
        if ($Matches.numberedKind) {
            return @{ Base = $Matches.base; Kind = $Matches.numberedKind; Number = [int]$Matches.number }
        }
        return @{ Base = $Matches.base; Kind = $Matches.kind; Number = 0 }
    }
    return @{ Base = $place; Kind = ""; Number = 0 }
}


function describePlace {
    # 場所ごとの表記と「種別」を @{ Place; Kind } で返す（TSV の名前は変えず、表示だけを変える）。
    # 画面の見出しの要約・検索結果ファイル・コピーに使う。表の「場所」の列は、これにセル番地を足した describeHitPlace を使う
    #   Excel      : "売上" → [シート]売上・セル / "売上[図形]" → [シート]売上・図形 / "売上[コメント]" → [シート]売上・コメント
    #                / "売上[ヘッダー・フッター]" → [シート]売上・ヘッダー・フッター
    #   Word       : "ページ003" → 3 ページ（目安）・本文（ページは保存時の区切りから数えた目安のため）/ "脚注" → 脚注・本文
    #   PowerPoint : "スライド002（非表示）" → スライド 2（非表示）・本文 / "スライド002_ノート" → スライド 2・ノート
    #   テキスト   : "本文" → 空・本文（場所は 1 つだけのため、表の「場所」の列は describeHitPlace の "N 行目" だけで足りる）
    # 種別は、図形・コメントなら場所の種類の名前そのまま（検索条件の［図形も検索］［コメントも検索］と同じ言葉）。
    # 埋め込みは番号を付けた "埋め込み 1"（場所は元の場所のページ・スライドの表記のまま）
    param (
        [string]$book,
        [string]$place
    )

    if (testTextExtension $book) {
        return @{ Place = ""; Kind = "本文" }
    }

    $split = splitObjectPlace $place
    $base = $split.Base
    $kind = $split.Kind
    if ($split.Number -gt 0) { $kind = "$kind $($split.Number)" }

    if ($book -match '\.xls[a-z]?$') {
        return @{ Place = "[シート]$base"; Kind = $(if ($kind) { $kind } else { "セル" }) }
    }
    if ($base -eq "") {
        return @{ Place = ""; Kind = $(if ($kind) { $kind } else { "本文" }) }
    }
    if ($base -match '^ページ(\d+)$') {
        if (testPdfExtension $book) {
            return @{ Place = "$([int]$Matches[1]) ページ"; Kind = $(if ($kind) { $kind } else { "本文" }) }
        }
        return @{ Place = "$([int]$Matches[1]) ページ（目安）"; Kind = $(if ($kind) { $kind } else { "本文" }) }
    }
    if ($base -match '^スライド(\d+)_ノート$') {
        return @{ Place = "スライド $([int]$Matches[1])"; Kind = $(if ($kind) { $kind } else { "ノート" }) }
    }
    if ($base -match '^スライド(\d+)(（非表示）)?$') {
        return @{ Place = "スライド $([int]$Matches[1])$($Matches[2])"; Kind = $(if ($kind) { $kind } else { "本文" }) }
    }
    # ヘッダー・フッター・脚注など、番号の無い場所
    return @{ Place = $base; Kind = $(if ($kind) { $kind } else { "本文" }) }
}


function describeHitPlace {
    # 結果の表の「場所」の列とプレビューの題に出す、行ごとの場所の表記を返す（場所ごとの表記にセル番地を足したもの）。
    # Excel だけ足す（Word・PowerPoint は場所ごとと同じ）。テキストは行番号だけ（"N 行目"）を返す（場所は 1 つしかないため）。
    #   セル             : [シート]売上!B12 / 1 行に複数のセルが一致 [シート]売上!B12 ほか 2 / セル番地が求まらないとき [シート]売上 12 行目
    #   図形・コメント   : [シート]売上!D5 / セル番地が求まらないとき [シート]売上（行番号は通し番号のため出さない）
    #   ヘッダー・フッター: [シート]売上（行にセル番地が無く、matchCell が空のため）
    #   テキスト         : 12 行目
    param (
        [string]$place,
        [bool]$isExcel,
        [bool]$isObjectPlace,
        [string]$matchCell,
        [int]$matchCount,
        [int]$lineNumber,
        [bool]$isText = $false
    )

    if ($isText) { return "$lineNumber 行目" }
    if (-not $isExcel) { return $place }
    if ($isObjectPlace) {
        if ($matchCell) { return "$place!$matchCell" }
        return $place
    }
    if (-not $matchCell) { return "$place $lineNumber 行目" }
    if ($matchCount -gt 1) { return "$place!$matchCell ほか $($matchCount - 1)" }
    return "$place!$matchCell"
}


# インデックスの「元のファイル名のフォルダ」と分かる名前（Office・テキスト・PDF の拡張子で終わる）
${indexBookDirPattern} = "\.(?:xls|doc|ppt)[a-z]?$|(?:$(((${textExtensions} + ${pdfExtensions}) | ForEach-Object { [regex]::Escape($_) }) -join '|'))$"

# インデックス（work\index 配下）の作成・集計・改名・削除。

function testStatusRowFailed {
    # 取り込み一覧の行を「失敗」として数えるか。状態が「失敗」の行と、「未取り込み」で理由（エラー）が書いてある行
    # （利用者の PowerPoint のために取り込めなかったファイル。次の更新で取り込むため状態は「未取り込み」のまま）
    param (
        $row
    )

    $state = [string]$row.状態
    return ($state -eq ${stateFailed}) -or ($state -eq ${stateNew} -and [string]$row.エラー -ne "")
}

function getIndexStats {
    # 取り込み一覧の行をインデックス名ごとに集計する（画面のインデックス一覧に出す件数・最終更新）:
    #   インデックス名（大文字・小文字を区別しない）→ @{ Total; Done; Pending; Failed; LastIngested（"yyyy/MM/dd HH:mm:ss"。無ければ空） }
    # rows は readStatusFile の Rows（相対パス → 行）。取り込み一覧を読み直さずに済むよう、読み込み済みの行を受け取る
    param (
        $rows
    )

    $stats = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
    if ($null -eq $rows) {
        return , $stats
    }
    foreach ($entry in $rows.GetEnumerator()) {
        $name = (splitIndexRelPath $entry.Key).Name
        if ($name -eq "") {
            continue
        }
        if (!$stats.ContainsKey($name)) {
            $stats[$name] = @{ Total = 0; Done = 0; Pending = 0; Failed = 0; LastIngested = "" }
        }
        $stat = $stats[$name]
        $stat.Total++
        $state = [string]$entry.Value.状態
        if ($state -eq ${stateDone}) {
            $stat.Done++
        } elseif (testStatusRowFailed $entry.Value) {
            $stat.Failed++
        } elseif ($state -eq ${stateNew}) {
            $stat.Pending++
        }
        # 取り込み日時は "yyyy/MM/dd HH:mm:ss" のため、文字列のまま比べて新しい方を残せる
        $ingested = [string]$entry.Value.取り込み日時
        if ($ingested -gt $stat.LastIngested) {
            $stat.LastIngested = $ingested
        }
    }
    return , $stats
}

function removeSystemIndexOfWorkspace {
    # インデックスのフォルダ（dir = <ワークスペース>\index）と同じワークスペースの system_index から、インデックス name の分を消す。
    # 消せなくても（状態ファイルがほかに開かれている等）インデックスの操作は続ける。次のインデックス作成で整理される
    param (
        [string]$name,
        [string]$dir
    )

    $owner = [Workspace]::new([System.IO.Path]::GetDirectoryName($dir.TrimEnd("\")))
    try {
        [void](removeSystemIndexOf $name $owner.SystemIndexDir $owner.SystemIndexStateFile)
    } catch {
    }
}

function getSearchIndexes {
    # インデックスの一覧（getSearchIndexData の Indexes）。引数は getSearchIndexData と同じ
    param (
        [string]$dir = $workspace.IndexDir,
        [string]$statusPath = $workspace.StatusFile,
        [string]$settingsPath = ${settingsFile}
    )

    return @((getSearchIndexData $dir $statusPath $settingsPath).Indexes)
}

function getSearchIndexData {
    # @{ Root（dir のフルパス）; Sources（インデックス名 → 元のフォルダ。getSourceFolderMap の結果）; Indexes } を返す。
    # Indexes はインデックスの一覧（work\index 直下のフォルダ 1 つがインデックス 1 つ）で、
    # @{ Name（インデックス名）; Path（インデックスのフォルダのフルパス）; SourcePath（元のフォルダ。分からなければ ""） } の配列で返す。
    # 並びは［インデックス管理］の一覧（targetFolders）と同じにし、その一覧に無いもの
    # （別の場所・PC から work\index にコピーしたインデックスなど）は名前順で後ろに付ける
    param (
        [string]$dir = $workspace.IndexDir,
        [string]$statusPath = $workspace.StatusFile,
        [string]$settingsPath = ${settingsFile}
    )

    if (!(Test-Path -LiteralPath $dir -PathType Container)) {
        return @{ Root = $dir; Indexes = @(); Sources = @{} }
    }
    $root = (Resolve-Path -LiteralPath $dir).ProviderPath.TrimEnd("\")
    $sources = getSourceFolderMap $root $statusPath $settingsPath

    # ［インデックス管理］の一覧の順番（インデックス名 → 何番目か）
    $order = New-Object 'System.Collections.Generic.Dictionary[string,int]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($folder in @(getTargetFolders $settingsPath | Where-Object { $_.Name })) {
        if (!$order.ContainsKey($folder.Name)) {
            $order[$folder.Name] = $order.Count
        }
    }

    $indexes = New-Object System.Collections.Generic.List[object]
    foreach ($sub in @(Get-ChildItem -LiteralPath (toLongPath $root) -Directory -ErrorAction SilentlyContinue)) {
        $name = $sub.Name
        $path = (fromLongPath $sub.FullName)
        if (!$sources.ContainsKey($name)) {
            # 取り込み一覧にも設定にも無いインデックス（別の場所・PC からコピーしたものなど）は、
            # そのフォルダの中の source_folder.txt から元のフォルダを読む
            $own = readSourceFolderFile $path
            if ($own.ContainsKey($name)) {
                $sources[$name] = $own[$name]
            }
        }
        $indexes.Add([pscustomobject]@{
            Name       = $name
            Path       = $path
            SourcePath = $(if ($sources.ContainsKey($name)) { $sources[$name] } else { "" })
            Order      = $(if ($order.ContainsKey($name)) { $order[$name] } else { [int]::MaxValue })
        })
    }
    $sorted = @($indexes | Sort-Object Order, Name | ForEach-Object {
        [pscustomobject]@{ Name = $_.Name; Path = $_.Path; SourcePath = $_.SourcePath }
    })
    return @{ Root = $root; Indexes = $sorted; Sources = $sources }
}


# インデックスのフォルダが壊れている（0 バイトのTSVがある）ことを表す件数。testIndexComplete は取り込み直す
${indexBrokenCount} = -1


function getContentIndexKeyOf {
    # getIndexTsvCounts の本文インデックスのファイルのキー（「<インデックスのフォルダからのフォルダ>\content_index.<拡張子>」）を返す
    param (
        [string]$relDir,
        [string]$extension
    )

    $name = "${contentIndexFileNamePrefix}.$extension"
    if ($relDir) { return "$relDir\$name" }
    return $name
}

function getIndexTsvCounts {
    # インデックスのフォルダの中のフォルダごとのTSVの数を返す（取り込み一覧の「済」と、インデックスの実体が合っているかの確認に使う）:
    #   インデックスのフォルダからの相対パス（大文字・小文字を区別しない）→ そのフォルダの直下のTSVの数
    #   本文インデックスのファイル（content_index.<拡張子>.<番号>.tsv）は、「<フォルダ>\content_index.<拡張子>」 → 1（どれかが 0 バイトなら ${indexBrokenCount}）
    # 元のファイル1つにつき1フォルダ（<ファイル名.xlsx>\<場所>.tsv）のため、キーは取り込み一覧の相対パスと同じになる。
    # 0 バイトのTSVがあるフォルダは ${indexBrokenCount}（-1）にする。
    # 空のシート・ページは保存しない（prettyTsv / writeUnits）ため、0 バイトのTSVは書き込みの途中で
    # 電源が落ちた場合などに限られ、そのままでは検索しても中身が出てこない。
    # 列挙できないとき（アクセス権が無い等）は $null を返す（呼び出し元は確認しない）
    param (
        [string]$dir = $workspace.IndexDir
    )

    $counts = New-Object 'System.Collections.Generic.Dictionary[string,int]' ([System.StringComparer]::OrdinalIgnoreCase)
    $root = toLongPath ([string]$dir).TrimEnd("\")
    if (!$root -or ![System.IO.Directory]::Exists($root)) {
        return , $counts
    }

    # 1ファイルずつ調べると件数の分だけ時間がかかるため、フォルダ・TSVをそれぞれ1回ずつ列挙して数える
    # （大きさは列挙のときに分かるため、1件ずつ調べる必要は無い）
    $prefix = $root.Length + 1
    try {
        # 内容が空のファイル（TSV 0 件）はフォルダだけが残るため、フォルダも 0 件として数える
        foreach ($sub in [System.IO.Directory]::EnumerateDirectories($root, "*", [System.IO.SearchOption]::AllDirectories)) {
            $counts[$sub.Substring($prefix)] = 0
        }
        foreach ($file in (New-Object System.IO.DirectoryInfo($root)).EnumerateFiles("*.tsv", [System.IO.SearchOption]::AllDirectories)) {
            $contentIndexInfo = readContentIndexFileName $file.Name
            if ($null -ne $contentIndexInfo) {
                # 本文インデックスのファイル（content_index.<拡張子>.<番号>.tsv）は、番号を除いた「<フォルダ>\content_index.<拡張子>」をキーにする
                # （testIndexComplete が拡張子ごとに見る）。どれか 1 つでも 0 バイトなら壊れているとする
                $contentIndexDir = if ($file.DirectoryName.Length -ge $prefix) { $file.DirectoryName.Substring($prefix) } else { "" }
                $key = getContentIndexKeyOf $contentIndexDir $contentIndexInfo.Extension
                $current = 0
                if ($file.Length -eq 0 -or ($counts.TryGetValue($key, [ref]$current) -and $current -eq ${indexBrokenCount})) {
                    $counts[$key] = ${indexBrokenCount}
                } else {
                    $counts[$key] = 1
                }
                continue
            }
            $parent = [System.IO.Path]::GetDirectoryName($file.FullName)
            if ($parent.Length -lt $prefix) {
                continue  # インデックスのフォルダの直下のTSVは、どのファイルのものか分からないため数えない
            }
            $key = $parent.Substring($prefix)
            $count = 0
            if (!$counts.TryGetValue($key, [ref]$count)) {
                $count = 0
            }
            if ($file.Length -eq 0 -or $count -eq ${indexBrokenCount}) {
                $counts[$key] = ${indexBrokenCount}
            } else {
                $counts[$key] = $count + 1
            }
        }
    } catch {
        return $null
    }
    return , $counts
}

function testIndexComplete {
    # 取り込み一覧の行（状態が「済」）に対して、インデックスの実体がそろっているかを返す。
    # 利用者が work\content_index のフォルダ・ファイルを直接削除した場合に、「済」のまま検索できなくなるのを防ぐ。
    # 元のファイルの中身は、フォルダの本文インデックスのファイル（content_index.<拡張子>.tsv）か、本文インデックスのファイルに入れる前の TSV
    # （<ファイル名.xlsx>\<場所>.tsv。インデックス作成が途中で止まったとき）のどちらかにある
    #   row    : 取り込み一覧の行（TSV数 を使う）
    #   relPath: 取り込み一覧の相対パス（= インデックスのフォルダからの相対パス）
    #   counts : getIndexTsvCounts の結果（$null なら確認せず、そろっているものとして扱う）
    param (
        $row,
        [string]$relPath,
        $counts
    )

    if ($null -eq $counts -or $null -eq $row) {
        return $true
    }
    # 本文インデックスのファイル: そのフォルダ・その拡張子の本文インデックスのファイルがあれば、そろっているものとする
    # （本文インデックスのファイルの中の元のファイルごとの場所の数は、中身を読まないと分からないため数えない）
    $contentIndexRel = getContentIndexKeyOf ([string][System.IO.Path]::GetDirectoryName($relPath)) (getContentIndexExtension $relPath)
    $contentIndexCount = 0
    if ($counts.TryGetValue($contentIndexRel, [ref]$contentIndexCount) -and $contentIndexCount -ne ${indexBrokenCount}) {
        return $true
    }
    $expected = 0
    if (-not [int]::TryParse([string]$row.TSV数, [ref]$expected)) {
        return $true  # TSVの数を記録していない行は確認できない
    }
    $actual = 0
    if (-not $counts.TryGetValue($relPath, [ref]$actual)) {
        return $false  # 本文インデックスのファイルも、元のファイルごとのフォルダも無い
    }
    if ($actual -eq ${indexBrokenCount}) {
        return $false  # 0 バイトのTSVがある（書き込みの途中で電源が落ちた場合など）
    }
    # 余分なTSVがあっても（利用者が置いた等）取り込み直さない。足りない場合だけ作り直す
    return ($actual -ge $expected)
}

function publishIndexFiles {
    # 取り込んで作ったTSV（fromDir の直下）を、その元のファイルのインデックスのフォルダ（bookDir）に入れる。
    # 作りかけのインデックスを残さないよう、いったん stagingDir に集めてから bookDir ごと入れ替える。
    # 途中で強制終了されても、bookDir は「前回のまま」か「今回の分がそろった状態」のどちらかになる
    # （1件ずつ bookDir へ移すと、途中で止まったときに一部のシートだけのインデックスが残り、検索で気付けない）。
    # 以前のインデックスはフォルダごと置き換える（シートの削除・名前変更に追従するため）
    param (
        [string]$fromDir,
        [string]$bookDir,
        [string]$stagingDir
    )

    removeDirectoryRetry $stagingDir
    [System.IO.Directory]::CreateDirectory((toLongPath $stagingDir)) | Out-Null
    foreach ($file in @(Get-ChildItem -LiteralPath (toLongPath $fromDir) -Filter "*.tsv" -File)) {
        [System.IO.File]::Move($file.FullName, (toLongPath (Join-Path $stagingDir $file.Name)))
    }

    removeDirectoryRetry $bookDir
    [System.IO.Directory]::CreateDirectory((toLongPath ([System.IO.Path]::GetDirectoryName($bookDir)))) | Out-Null
    try {
        [System.IO.Directory]::Move((toLongPath $stagingDir), (toLongPath $bookDir))
    } catch [System.IO.IOException] {
        # work を別のドライブへのリンクにしている場合など、フォルダごとは移せないときは1件ずつ移す
        [System.IO.Directory]::CreateDirectory((toLongPath $bookDir)) | Out-Null
        foreach ($file in @(Get-ChildItem -LiteralPath (toLongPath $stagingDir) -Filter "*.tsv" -File)) {
            [System.IO.File]::Move($file.FullName, (toLongPath (Join-Path $bookDir $file.Name)))
        }
        removeDirectoryRetry $stagingDir
    }
    # bookDir はワークスペースの中（同じドライブ）の一時フォルダから Move で入れるため、親（content_index\）の
    # NotContentIndexed 属性を継がない。ここで、入れた分（フォルダと直下の TSV）だけに付ける
    [void](setNotContentIndexed $bookDir)
}

# 検索用の本文インデックスのファイル（フォルダ 1 つ・元のファイルの拡張子 1 つにつき、大きさで分けて 1 つ以上。content_index.xlsx.001.tsv など）の形式（判断層）。
# ファイル（元のファイル）ごと・場所（シート・ページ・スライドなど）ごとに、メタ情報の行と今の TSV の中身を並べる。
#
#   <RS> 版=1
#   <RS> ファイル名=(株)山田商事_見積書.xlsx
#   <RS> 種類=Excel
#   <RS> シート=見積
#   <RS> 対象=本文
#   品名→数量→単価        ← 今の TSV の中身そのまま（→ はタブ）。この行が 1 行目
#
# ・メタ情報の行は「RS（U+001E）、半角スペース、キー=値」。1 行に 1 項目。
#   ファイル名= で新しいファイル、シート= ページ= スライド= 部分= で新しい場所が始まる。知らないキーは読み飛ばす
# ・中身には U+001C～U+001F を入れない（書くときに取り除く）ため、行の先頭が RS ならメタ情報の行
# ・改行は LF にそろえる。行の分け方は StreamReader.ReadLine と同じ（CRLF・LF・CR）にし、行番号を変えない
# ・文字コードは UTF-16LE（BOM 付き。content_index_store.ps1 が読み書きする）
# ・Excel の図形・コメントの行は「セル番地 + タブ + 文字」の形。検索は区切りのタブ（最初のタブ）より後だけを照合する（CellPrefixed。content_index_search.ps1）

# 本文インデックスのファイルの名前は「content_index.<元のファイルの拡張子（小文字）>.<番号（3 桁以上）>.tsv」（content_index.xlsx.001.tsv など）。
# 1 つの本文インデックスのファイルが contentIndexFileMaxBytes 以上になったら、それ以上ブックを足さず、次の番号の本文インデックスのファイルに足す
# 先頭の語（content_index）は 1 か所の定数にする（index_store.ps1 の getContentIndexKeyOf も使う）
${contentIndexFileNamePrefix} = "content_index"
${contentIndexFilePattern} = "${contentIndexFileNamePrefix}.*.tsv"
${contentIndexFileNamePattern} = "^${contentIndexFileNamePrefix}\.(?<ext>[^.]+)\.(?<part>\d{3,})\.tsv$"
${contentIndexFileMaxBytes} = 4MB
${contentIndexVersion} = 1
${contentIndexMark} = [char]0x1E

# 場所のまとまりを始めるキー
${contentIndexPlaceKeys} = @("シート", "ページ", "スライド", "部分")


function getContentIndexFileKind {
    # 元のファイル名から種類（Excel・Word・PowerPoint・テキスト・PDF）を返す。分からなければ空
    param (
        [string]$book
    )

    if ($book -match '\.xls[a-z]?$') { return "Excel" }
    if ($book -match '\.doc[a-z]?$') { return "Word" }
    if ($book -match '\.ppt[a-z]?$') { return "PowerPoint" }
    if (testTextExtension $book) { return "テキスト" }
    if (testPdfExtension $book) { return "PDF" }
    return ""
}

function getContentIndexExtension {
    # 元のファイル名から、本文インデックスのファイルを分ける拡張子（小文字・先頭の . なし）を返す
    param (
        [string]$book
    )

    return [System.IO.Path]::GetExtension($book).TrimStart(".").ToLowerInvariant()
}


function getContentIndexFileName {
    # 拡張子・番号の本文インデックスのファイルの名前（content_index.xlsx.001.tsv など）を返す
    param (
        [string]$extension,
        [int]$part = 1
    )

    return "${contentIndexFileNamePrefix}.{0}.{1:D3}.tsv" -f $extension, $part
}


function readContentIndexFileName {
    # 本文インデックスのファイルの名前から @{ Extension; Part } を返す。本文インデックスのファイルの名前でなければ $null
    param (
        [string]$name
    )

    if ($name -match ${contentIndexFileNamePattern}) {
        return @{ Extension = $Matches.ext.ToLowerInvariant(); Part = [int]$Matches.part }
    }
    return $null
}


function splitContentIndexBooksByExtension {
    # 元のファイルの並びを、拡張子ごとの並び（[ordered] 拡張子 → 並び。拡張子は現れた順）に分ける。各並びの中の順は変えない
    param (
        $books
    )

    $groups = [ordered]@{}
    foreach ($book in $books) {
        $extension = getContentIndexExtension ([string]$book.Name)
        if (!$groups.Contains($extension)) {
            $groups[$extension] = New-Object System.Collections.Generic.List[object]
        }
        $groups[$extension].Add($book)
    }
    return $groups
}


function encodeContentIndexValue {
    # メタ情報の値を 1 行に収まる形にする。制御文字（タブを除く）と % を "%XX" にする（decodeContentIndexValue で戻す）
    param (
        [string]$value
    )

    if ($value -notmatch '[\x00-\x08\x0A-\x1F%]') {
        return $value
    }
    return [regex]::Replace($value, '[\x00-\x08\x0A-\x1F%]', { param($m) '%{0:X2}' -f [int][char]$m.Value })
}


function decodeContentIndexValue {
    # encodeContentIndexValue で符号化した値を戻す
    param (
        [string]$value
    )

    if ($value.IndexOf("%") -lt 0) {
        return $value
    }
    return [regex]::Replace($value, '%(?:[01][0-9A-F]|25)', { param($m) [string][char][Convert]::ToInt32($m.Value.Substring(1), 16) })
}


function convertPlaceToContentIndexMeta {
    # 今の場所の名前（TSV のファイル名。"見積[図形]"・"ページ001"・"スライド002（非表示）"・"スライド001_ノート" など）を、
    # 場所のメタ情報（[ordered] キー → 値）にする。convertContentIndexMetaToPlace で必ず元の名前に戻る形にし、
    # 分けられない名前は「部分=名前そのまま・対象=本文」にする
    param (
        [string]$book,
        [string]$place
    )

    $split = splitObjectPlace $place
    $target = if ($split.Kind) { $split.Kind } else { "本文" }
    $meta = [ordered]@{}
    switch (getContentIndexFileKind $book) {
        "Excel" {
            $meta["シート"] = $split.Base
            $meta["対象"] = $target
        }
        "Word" {
            if ($split.Base -match '^ページ(\d+)$') {
                $meta["ページ"] = [string][int]$Matches[1]
            } else {
                $meta["部分"] = $split.Base
            }
            $meta["対象"] = $target
        }
        "PowerPoint" {
            if (!$split.Kind -and $split.Base -match '^スライド(\d+)_ノート$') {
                $meta["スライド"] = [string][int]$Matches[1]
                $meta["対象"] = "ノート"
            } elseif ($split.Base -match '^スライド(\d+)(（非表示）)?$') {
                $meta["スライド"] = [string][int]$Matches[1]
                $meta["対象"] = $target
                if ($Matches[2]) { $meta["非表示"] = "はい" }
            } else {
                $meta["部分"] = $split.Base
                $meta["対象"] = $target
            }
        }
        default {
            $meta["部分"] = $split.Base
            $meta["対象"] = $target
        }
    }
    if ($split.Number -gt 0) {
        # 埋め込みの番号（"ページ003[埋め込み2]" → 対象=埋め込み・埋め込み=2。場所を始めるキーではない）
        $meta["埋め込み"] = [string]$split.Number
    }
    if ((convertContentIndexMetaToPlace $meta) -cne $place) {
        # 番号の桁が違う（"ページ1"）など、組み立て直すと同じ名前にならないものは、名前をそのまま持つ
        $meta = [ordered]@{ "部分" = $place; "対象" = "本文" }
    }
    return $meta
}


function convertContentIndexMetaToPlace {
    # 場所のメタ情報から、今の場所の名前（画面の表示・図形とコメントの除外・元のファイルを開く処理が使う形）を組み立てる
    param (
        $meta
    )

    $target = [string]$meta["対象"]
    $suffix = if ($target -eq ${placeKindShape} -or $target -eq ${placeKindComment} -or $target -eq ${placeKindHeaderFooter}) { "[$target]" } else { "" }
    if ($target -eq ${placeKindEmbed} -and $meta.Contains("埋め込み")) {
        $suffix = "[$target$([string]$meta["埋め込み"])]"
    }
    if ($meta.Contains("シート")) {
        return [string]$meta["シート"] + $suffix
    }
    if ($meta.Contains("ページ")) {
        return ("ページ{0:D3}" -f [int]$meta["ページ"]) + $suffix
    }
    if ($meta.Contains("スライド")) {
        $base = "スライド{0:D3}" -f [int]$meta["スライド"]
        if ($target -eq "ノート") {
            return "${base}_ノート"
        }
        if ($meta["非表示"] -eq "はい") {
            $base += "（非表示）"
        }
        return $base + $suffix
    }
    if ($target -eq "本文") {
        return [string]$meta["部分"]
    }
    return [string]$meta["部分"] + $suffix
}


function convertToContentIndexBody {
    # TSV の中身を、本文インデックスのファイルに入れる形（LF 区切り・末尾に LF・U+001C～U+001F を除く）にする。
    # 行の分け方は StreamReader.ReadLine と同じ（CRLF・LF・CR で分け、末尾の改行の後ろは行にしない）。中身が空なら空を返す
    param (
        [string]$text
    )

    if ($text.Length -eq 0) {
        return ""
    }
    $body = $text.Replace("`r`n", "`n").Replace("`r", "`n")
    if ($body.IndexOfAny([char[]]@([char]0x1C, [char]0x1D, [char]0x1E, [char]0x1F)) -ge 0) {
        $body = [regex]::Replace($body, '[\x1C-\x1F]', "")
    }
    if ($body.EndsWith("`n")) {
        return $body
    }
    return $body + "`n"
}


function convertBookToContentIndexBlock {
    # 元のファイル 1 つの中身から、本文インデックスのファイルに入れるまとまり（「ファイル名=」の行から最後の行まで）の文字列を作る。
    #   book: @{ Name（元のファイル名）; Places（@{ Place（今の場所の名前）; Text（TSV の中身） } の並び） }
    #         または @{ Name; Block }（前の本文インデックスのファイルから取り出したまとまり。そのまま返す）
    param (
        $book
    )

    if ($null -ne $book.Block) {
        return [string]$book.Block
    }
    $mark = [string]${contentIndexMark}
    $name = [string]$book.Name
    $sb = New-Object System.Text.StringBuilder
    [void]$sb.Append("$mark ファイル名=").Append((encodeContentIndexValue $name)).Append("`n")
    $kind = getContentIndexFileKind $name
    if ($kind) {
        [void]$sb.Append("$mark 種類=$kind`n")
    }
    foreach ($place in $book.Places) {
        $meta = convertPlaceToContentIndexMeta $name ([string]$place.Place)
        foreach ($key in $meta.Keys) {
            [void]$sb.Append("$mark ").Append($key).Append("=").Append((encodeContentIndexValue ([string]$meta[$key]))).Append("`n")
        }
        [void]$sb.Append((convertToContentIndexBody ([string]$place.Text)))
    }
    return $sb.ToString()
}


function convertToContentIndexText {
    # 元のファイルの並びから、本文インデックスのファイルの文字列を作る（この順に書く）。
    #   books: convertBookToContentIndexBlock に渡せるもの（@{ Name; Places } か @{ Name; Block }）の並び
    param (
        $books
    )

    $sb = New-Object System.Text.StringBuilder
    [void]$sb.Append("$([string]${contentIndexMark}) 版=${contentIndexVersion}`n")
    foreach ($book in $books) {
        [void]$sb.Append((convertBookToContentIndexBlock $book))
    }
    return $sb.ToString()
}


function planContentIndexParts {
    # フォルダ 1 つの、拡張子ごと・番号ごとの本文インデックスのファイルに、どの元のファイルを入れるかを決める。
    #   parts  : 前の本文インデックスのファイルの並び。@{ Extension; Part; Books（@{ Name; Block } の並び。ファイルの中の順） }
    #   books  : 足す・入れ替える元のファイル（@{ Name; Block }）。元のファイル名の順に足す
    #   remove : 外す元のファイル名
    #   maxBytes: この大きさ（UTF-16 のバイト数）以上の本文インデックスのファイルには、もう足さない
    # 決め方:
    #   ・入れ替える元のファイルは、今入っている本文インデックスのファイルの同じ位置で入れ替える（ほかの本文インデックスのファイルへ移さない）
    #   ・外す元のファイルは、入っている本文インデックスのファイルから外す
    #   ・新しい元のファイルは、その拡張子の最後の番号の本文インデックスのファイルが maxBytes 未満ならそこに、以上なら次の番号の新しい本文インデックスのファイルに足す
    #   ・1 つの元のファイルは 2 つの本文インデックスのファイルにまたがらない（1 つで maxBytes を超えても、その 1 つで 1 つの本文インデックスのファイルにする）
    # @{ Extension; Part; Books; Changed（書き直しが要る） } の並び（拡張子・番号の順）を返す。
    # 元のファイルが無くなった本文インデックスのファイルは、Books が空で Changed が $true（消す）
    param (
        $parts,
        $books,
        [string[]]$remove = @(),
        [long]$maxBytes = ${contentIndexFileMaxBytes}
    )

    $removeSet = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($name in $remove) { [void]$removeSet.Add($name) }
    $replace = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($book in $books) { $replace[[string]$book.Name] = $book }

    $plan = New-Object System.Collections.Generic.List[hashtable]
    foreach ($part in @($parts | Sort-Object { $_.Extension }, { $_.Part })) {
        $kept = New-Object System.Collections.Generic.List[object]
        $changed = $false
        foreach ($book in $part.Books) {
            $name = [string]$book.Name
            if ($removeSet.Contains($name)) {
                $changed = $true
            } elseif ($replace.ContainsKey($name)) {
                $kept.Add($replace[$name])
                [void]$replace.Remove($name)
                $changed = $true
            } else {
                $kept.Add($book)
            }
        }
        $plan.Add(@{ Extension = [string]$part.Extension; Part = [int]$part.Part; Books = $kept; Changed = $changed })
    }

    # 新しい元のファイル（どの本文インデックスのファイルにも無かったもの）を、元のファイル名の順に足す
    foreach ($book in @($replace.Values | Sort-Object { [string]$_.Name })) {
        $extension = getContentIndexExtension ([string]$book.Name)
        $last = $null
        foreach ($p in $plan) {
            if ($p.Extension -eq $extension -and ($null -eq $last -or $p.Part -gt $last.Part)) { $last = $p }
        }
        if ($null -eq $last -or (measureContentIndexPartBytes $last.Books) -ge $maxBytes) {
            $number = if ($null -eq $last) { 1 } else { $last.Part + 1 }
            $last = @{ Extension = $extension; Part = $number; Books = (New-Object System.Collections.Generic.List[object]); Changed = $true }
            $plan.Add($last)
        }
        $last.Books.Add($book)
        $last.Changed = $true
    }
    return , @($plan | Sort-Object { $_.Extension }, { $_.Part })
}


function measureContentIndexPartBytes {
    # 本文インデックスのファイルの大きさ（UTF-16 のバイト数。BOM と版の行を含む）を、元のファイルのまとまり（@{ Name; Block }）の並びから求める
    param (
        $books
    )

    $chars = 1 + ("$([string]${contentIndexMark}) 版=${contentIndexVersion}`n").Length
    foreach ($book in $books) {
        $chars += ([string]$book.Block).Length
    }
    return [long]$chars * 2
}

function testContentIndexCellPrefixed {
    # 場所の行が「セル番地 + 区切りのタブ + 文字」の形か（Excel の図形・コメント）を返す。検索は、この形の行では区切りのタブより後だけを照合する
    param (
        [string]$book,
        $meta
    )

    $target = [string]$meta["対象"]
    return ((getContentIndexFileKind $book) -eq "Excel") -and ($target -eq ${placeKindShape} -or $target -eq ${placeKindComment})
}


function readContentIndexPlaces {
    # 本文インデックスのファイルの文字列を読み、場所ごとの @{ Book; Location（今の場所の名前）; CellPrefixed（行の先頭がセル番地と区切りのタブか）; Start（中身の先頭の位置）; End（中身の終わりの次の位置） }
    # を先頭から順に返す。版が分からないときは例外にする
    param (
        [string]$text
    )

    $places = New-Object System.Collections.Generic.List[hashtable]
    $mark = ${contentIndexMark}
    $placeKeys = ${contentIndexPlaceKeys}
    $book = ""
    $current = $null
    $meta = $null
    $versionSeen = $false
    $pos = $text.IndexOf($mark)
    while ($pos -ge 0) {
        $lineEnd = $text.IndexOf([char]10, $pos)
        if ($lineEnd -lt 0) { $lineEnd = $text.Length }
        $line = $text.Substring($pos + 2, [Math]::Max(0, $lineEnd - $pos - 2))
        $eq = $line.IndexOf("=")
        if ($eq -gt 0) {
            $key = $line.Substring(0, $eq)
            $value = decodeContentIndexValue $line.Substring($eq + 1)
            if ($key -eq "版") {
                if ($value -ne [string]${contentIndexVersion}) {
                    throw "集約ファイルの版が違います（$value）"
                }
                $versionSeen = $true
            } elseif ($key -eq "ファイル名" -or $placeKeys -contains $key) {
                if ($current) {
                    $current.End = $pos
                    $current.Location = convertContentIndexMetaToPlace $meta
                    $current.CellPrefixed = testContentIndexCellPrefixed $current.Book $meta
                    $places.Add($current)
                    $current = $null
                }
                if ($key -eq "ファイル名") {
                    $book = $value
                } else {
                    $meta = [ordered]@{ $key = $value }
                    $current = @{ Book = $book; Location = ""; CellPrefixed = $false; Start = $lineEnd + 1; End = $lineEnd + 1 }
                }
            } elseif ($current) {
                $meta[$key] = $value
                $current.Start = $lineEnd + 1
            }
        }
        $pos = if ($lineEnd -lt $text.Length) { $text.IndexOf($mark, $lineEnd + 1) } else { -1 }
    }
    if ($current) {
        $current.End = $text.Length
        $current.Location = convertContentIndexMetaToPlace $meta
        $current.CellPrefixed = testContentIndexCellPrefixed $current.Book $meta
        $places.Add($current)
    }
    if (!$versionSeen -and $text.Length -gt 0) {
        throw "集約ファイルの版がありません"
    }
    return , $places
}


function splitContentIndexTextByBook {
    # 本文インデックスのファイルの文字列を、元のファイルごとのまとまり（@{ Name; Block }。Block は「ファイル名=」の行から次の「ファイル名=」の行の前まで）
    # に分けて先頭から順に返す（元のファイルを入れ替えるとき、変わらないファイルをそのまま写すため）。版が違えば例外にする
    param (
        [string]$text
    )

    $books = New-Object System.Collections.Generic.List[hashtable]
    if ($text.Length -eq 0) {
        return , $books
    }
    $head = "$([string]${contentIndexMark}) ファイル名="
    $versionLine = "$([string]${contentIndexMark}) 版="
    $firstEnd = $text.IndexOf([char]10)
    if (!$text.StartsWith($versionLine, [System.StringComparison]::Ordinal) -or $firstEnd -lt 0 -or $text.Substring($versionLine.Length, $firstEnd - $versionLine.Length) -ne [string]${contentIndexVersion}) {
        throw "集約ファイルの版が違います"
    }
    $pos = $text.IndexOf("`n$head", [System.StringComparison]::Ordinal)
    while ($pos -ge 0) {
        $start = $pos + 1
        $lineEnd = $text.IndexOf([char]10, $start)
        $name = decodeContentIndexValue $text.Substring($start + $head.Length, $lineEnd - $start - $head.Length)
        $next = $text.IndexOf("`n$head", $lineEnd, [System.StringComparison]::Ordinal)
        $end = if ($next -ge 0) { $next + 1 } else { $text.Length }
        $books.Add(@{ Name = $name; Block = $text.Substring($start, $end - $start) })
        $pos = $next
    }
    return , $books
}


function getContentIndexBodyText {
    # 本文インデックスのファイルの文字列から、メタ情報の行（先頭が RS の行）を除いた中身だけを返す（システムインデックスの語を作るため。
    # メタ情報の「ファイル名」「シート」などの語が入ると、その語で探したときにどのフォルダも候補になってしまう）
    param (
        [string]$text
    )

    if ($text.IndexOf([char]0x1E) -lt 0) {
        return $text
    }
    return [regex]::Replace($text, "(?m)^\x1E[^\n]*\n?", "")
}
# ［検索］の検索対象ツリーのデータ集め（状態層。画面に触らない）。
# ワークスペースのフォルダを読むので、届かないネットワークのワークスペースでは、画面のスレッドでなく裏の列（network）から呼ぶ。
# 画面（ui\index_tree.ps1・ui\index\index_types.ps1 の IndexNode）は、この結果を受け取って組み立てるだけにする。

function testIndexBookName {
    # 元のファイルごとのフォルダと分かる拡張子か。Office は拡張子の形（.xls・.doc・.ppt で始まり 4～5 文字）で見分け、
    # テキストは対象の拡張子の一覧（shared\core\text_file.ps1 の testTextExtension。一覧はそこにだけある）で見分ける
    param (
        [string]$name
    )

    $ext = [System.IO.Path]::GetExtension($name).ToLowerInvariant()
    if ($ext.Length -ge 4 -and $ext.Length -le 5 -and
        ($ext.StartsWith(".xls") -or $ext.StartsWith(".doc") -or $ext.StartsWith(".ppt"))) {
        return $true
    }
    return ((testTextExtension $name) -or (testPdfExtension $name))
}

function testIndexBookDirPath {
    # 元のファイルごとのフォルダ（本文インデックスにする前の TSV・中身が空のファイルのフォルダ）か。名前が .xlsx などで終わる本物のフォルダと
    # 区別するため、サブフォルダも本文インデックスのファイル（content_index.*.tsv）も無いことも見る（content_index_store.ps1 の testIndexBookDir と同じ判定）
    param (
        [string]$dir
    )

    if (-not (testIndexBookName ([System.IO.Path]::GetFileName($dir.TrimEnd('\'))))) {
        return $false
    }
    try {
        # 列挙子（Enumerate*）を途中で抜けると、GC まで調べたフォルダを掴んだまま残り、インポートの上書きで
        # content_index\<名前> を移動できなくなる。直下だけなので配列（Get*）で受ける（ここの関数はどれも同じ）
        $long = toLongPath $dir
        if ([System.IO.Directory]::GetDirectories($long).Length -gt 0) { return $false }
        if ([System.IO.Directory]::GetFiles($long, ${contentIndexFilePattern}).Length -gt 0) { return $false }
        return $true
    } catch {
        return $false
    }
}

function testIndexFolderHasSubfolders {
    # インデックスのフォルダの直下に、本のフォルダでないサブフォルダがあるか
    param (
        [string]$dir
    )

    try {
        foreach ($sub in [System.IO.Directory]::GetDirectories((toLongPath $dir))) {
            if (-not (testIndexBookDirPath $sub)) { return $true }
        }
        return $false
    } catch {
        return $false
    }
}

function testIndexFolderHasFiles {
    # インデックスのフォルダの直下に、ファイル（本文インデックスのファイル・本文インデックスにする前の TSV）があるか
    param (
        [string]$dir
    )

    try {
        # 本文インデックスのファイル（content_index.<拡張子>.tsv。content_index_format.ps1 の contentIndexFilePattern）か、本文インデックスにする前の TSV があれば、フォルダ直下にファイルがある
        $long = toLongPath $dir
        if ([System.IO.Directory]::GetFiles($long, ${contentIndexFilePattern}).Length -gt 0) { return $true }
        foreach ($sub in [System.IO.Directory]::GetDirectories($long)) {
            if (-not (testIndexBookDirPath $sub)) { continue }
            if ([System.IO.Directory]::GetFiles($sub, "*.tsv").Length -gt 0) { return $true }
        }
        return $false
    } catch {
        return $false
    }
}

function getIndexFolderChildren {
    # インデックスのフォルダ（dir）の子を @{ HasFiles; Folders = @(@{ Name; HasSubfolders }); Error } で返す。
    # Folders は本のフォルダを除いた名前順。読めなかったときは Error に文面を入れ、Folders は空にする
    param (
        [string]$dir
    )

    $names = New-Object System.Collections.Generic.List[string]
    try {
        foreach ($sub in [System.IO.Directory]::GetDirectories((toLongPath $dir))) {
            if (testIndexBookDirPath $sub) { continue }
            $names.Add([System.IO.Path]::GetFileName($sub))
        }
    } catch {
        return @{ HasFiles = $false; Folders = @(); Error = $_.Exception.Message }
    }
    $names.Sort([System.StringComparer]::CurrentCultureIgnoreCase)
    $folders = @($names | ForEach-Object {
        @{ Name = $_; HasSubfolders = (testIndexFolderHasSubfolders (Join-Path $dir $_)) }
    })
    return @{ HasFiles = (testIndexFolderHasFiles $dir); Folders = $folders; Error = "" }
}

function getIndexTreeData {
    # 検索対象ツリーの材料を集める。
    #   dir: インデックスのフォルダ（work\index）  paths: 展開していたフォルダ・チェックを外したフォルダ（インデックスの根から先祖すべての子も返す）
    # 返すもの: @{ State（getPathState の State）; Message; Root; Sources（getSourceFolderMap の結果）;
    #   Indexes = @(@{ Name; SourcePath; Exists; HasSubfolders }); Children = @{ <フォルダ> = getIndexFolderChildren の結果 } }
    # インデックスのフォルダに接続できない・その他のときは、列挙せずに State と文面だけを返す
    # （Test-Path が $false を返して「インデックスが無い」と取り違えないため）
    param (
        [string]$dir,
        [string]$statusPath,
        [string]$settingsPath,
        [string[]]$paths = @()
    )

    $result = @{ State = ${pathStateMissing}; Message = ""; Root = $dir; Sources = @{}; Indexes = @(); Children = @{} }
    $state = getPathState $dir
    if ($state.State -ne ${pathStateFound}) {
        $result.State = $state.State
        $result.Message = $state.Message
        return $result
    }
    $result.State = ${pathStateFound}

    $data = getSearchIndexData $dir $statusPath $settingsPath
    $root = [string]$data.Root
    $result.Root = $root
    $result.Sources = $data.Sources
    $indexes = New-Object System.Collections.Generic.List[object]
    foreach ($index in @($data.Indexes)) {
        $path = "$root\$($index.Name)"
        $exists = [System.IO.Directory]::Exists((toLongPath $path))
        $indexes.Add(@{
            Name          = $index.Name
            SourcePath    = $(if ($index.SourcePath) { [string]$index.SourcePath } else { "" })
            Exists        = $exists
            HasSubfolders = ($exists -and (testIndexFolderHasSubfolders $path))
        })
    }
    $result.Indexes = $indexes.ToArray()

    # 先祖すべての子を入れる（深い階層の展開・除外を戻すため）
    foreach ($index in $indexes) {
        if (-not $index.Exists) { continue }
        $indexRoot = "$root\$($index.Name)"
        foreach ($target in @($paths)) {
            $target = ([string]$target).TrimEnd("\")
            $isRoot = $target.Equals($indexRoot, [System.StringComparison]::OrdinalIgnoreCase)
            if (-not $isRoot -and -not $target.StartsWith("$indexRoot\", [System.StringComparison]::OrdinalIgnoreCase)) { continue }
            $segments = @($target.Substring($indexRoot.Length).Split([char[]]@("\"), [System.StringSplitOptions]::RemoveEmptyEntries))
            $current = $indexRoot
            for ($i = 0; $i -le $segments.Count; $i++) {
                if (-not $result.Children.ContainsKey($current)) {
                    $result.Children[$current] = getIndexFolderChildren $current
                }
                if ($i -ge $segments.Count) { break }
                $next = $segments[$i]
                $known = $result.Children[$current]
                if (-not (@($known.Folders) | Where-Object { $_.Name -ieq $next })) { break }
                $current = "$current\$next"
            }
        }
    }
    return $result
}

# 検索用の本文インデックスのファイル（content_index_format.ps1）の読み書き（状態層）。
# 本文インデックスのファイルは work\content_index の中のフォルダごと・元のファイルの拡張子ごとに、大きさで分けて置く（content_index.xlsx.001.tsv など）。UTF-16LE（BOM 付き）で書く
# （UTF-8 より文字列への変換が速い。日本語が多いと大きさはほとんど変わらない）。

function writeContentIndexFile {
    # 本文インデックスのファイルを書く。一時ファイル（<名前>.tmp）に書き終えてから置き換えるため、途中で止まっても前のファイルが残る
    param (
        [string]$path,
        [string]$text
    )

    $longPath = toLongPath $path
    $tmp = "$longPath.tmp"
    [System.IO.File]::WriteAllText($tmp, $text, [System.Text.UnicodeEncoding]::new($false, $true))
    if ([System.IO.File]::Exists($longPath)) {
        # 3 つ目の引数（控え）に $null を渡すと PowerShell が空の文字列にして例外になるため、NullString を渡す
        [System.IO.File]::Replace($tmp, $longPath, [NullString]::Value)
    } else {
        [System.IO.File]::Move($tmp, $longPath)
    }
}


function readContentIndexText {
    # 本文インデックスのファイルを文字列で読む（インデックス作成中の置き換えと同時に読めるよう、共有モードは ReadWrite|Delete）
    param (
        [string]$path
    )

    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $stream = [System.IO.FileStream]::new((toLongPath $path), [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    $reader = [System.IO.StreamReader]::new($stream, [System.Text.Encoding]::Unicode, $true)
    try {
        return $reader.ReadToEnd()
    } finally {
        $reader.Dispose()
    }
}


function readContentIndexRange {
    # 本文インデックスのファイル（UTF-16LE・BOM 付き）の、文字の位置 start（含む）から end（含まない）までを start から数えて、
    # firstLine 行目の先頭（firstLine が 1 以下なら start）から lines 個目の改行までを文字列で返す（それより前の行は持たない）。
    # BOM が無い（UTF-16LE でない）ときは $null（呼び出し側が全体を読む）。
    # checkpoints（ハッシュテーブル）を渡すと、通った 200 行ごとの行の先頭（行の番号 → 文字の位置）を足す
    # （start の行の番号が baseLine。次に読むとき、目当ての行の手前の位置から読めるようにする）
    param (
        [string]$path,
        [int]$start,
        [int]$end,
        [int]$firstLine,
        [int]$lines,
        [int]$baseLine = 1,
        $checkpoints = $null
    )

    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $stream = [System.IO.FileStream]::new((toLongPath $path), [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    try {
        $bom = New-Object byte[] 2
        if ($stream.Read($bom, 0, 2) -ne 2 -or $bom[0] -ne 0xFF -or $bom[1] -ne 0xFE) { return $null }
        [void]$stream.Seek(2L + 2L * $start, [System.IO.SeekOrigin]::Begin)
        $reader = [System.IO.StreamReader]::new($stream, [System.Text.UnicodeEncoding]::new($false, $false), $false)
        $builder = New-Object System.Text.StringBuilder
        $buffer = New-Object char[] 65536
        $remaining = $end - $start
        $newlines = 0
        $skip = [Math]::Max(0, $firstLine - 1)
        $started = ($skip -eq 0)
        while ($remaining -gt 0 -and $newlines -lt $lines) {
            $consumed = ($end - $start) - $remaining
            $got = $reader.Read($buffer, 0, [Math]::Min($buffer.Length, $remaining))
            if ($got -le 0) { break }
            $keepFrom = if ($started) { 0 } else { -1 }
            $from = 0
            while ($from -lt $got) {
                $found = [Array]::IndexOf($buffer, [char]10, $from, $got - $from)
                if ($found -lt 0) { break }
                $newlines++
                $from = $found + 1
                if ($null -ne $checkpoints) {
                    $nextLine = $baseLine + $newlines
                    if (($nextLine - 1) % 200 -eq 0) { $checkpoints[$nextLine] = $start + $consumed + $from }
                }
                if (!$started -and $newlines -eq $skip) { $started = $true; $keepFrom = $from }
            }
            # 読み飛ばす行のチャンクは捨てる（行数だけ数える）
            if ($keepFrom -ge 0 -and $keepFrom -lt $got) { [void]$builder.Append($buffer, $keepFrom, $got - $keepFrom) }
            $remaining -= $got
        }
        return $builder.ToString()
    } finally {
        $stream.Dispose()
    }
}


function testIndexBookDir {
    # インデックスの中のフォルダが、元のファイルごとのフォルダ（<ファイル名.xlsx>\<場所>.tsv。本文インデックスのファイルに入れる前の TSV の置き場所）か。
    # 名前だけでは、名前が .xlsx などで終わる本物のフォルダ（元のフォルダの名前をそのまま使う）と区別できないため、中身も見る:
    #   ・名前が Office・テキストの拡張子で終わる（indexBookDirPattern）
    #   ・サブフォルダも本文インデックスのファイル（content_index.<拡張子>.tsv）も無い
    #   ・withTsv なら、TSV が 1 つ以上ある（取り込んだが中身が空のファイルのフォルダは、本文インデックスのファイルに入れるものが無い）
    # 読めないフォルダは $false（本文インデックスのファイルに入れる・消す対象にしない）
    param (
        [string]$dir,
        [bool]$withTsv = $true
    )

    if ([System.IO.Path]::GetFileName($dir.TrimEnd("\")) -notmatch ${indexBookDirPattern}) {
        return $false
    }
    $long = toLongPath $dir
    try {
        # 途中で戻っても、調べたフォルダを掴んだまま残さない（testAnyEntry・配列で受ける GetFiles）
        if (testAnyEntry ([System.IO.Directory]::EnumerateDirectories($long))) {
            return $false
        }
        $hasTsv = $false
        foreach ($file in [System.IO.Directory]::GetFiles($long, "*.tsv")) {
            if ([System.IO.Path]::GetFileName($file) -like ${contentIndexFilePattern}) {
                return $false
            }
            $hasTsv = $true
        }
        return ($hasTsv -or !$withTsv)
    } catch {
        return $false
    }
}

function getIndexFolderBooks {
    # 今の形式のインデックスのフォルダ 1 つ（直下の <ファイル名.xlsx>\<場所>.tsv）から、本文インデックスのファイルに入れる元のファイルの並びを作る。
    # 並びは今の検索結果と同じ順（前の名前の付け方（フォルダのパス + encodeIndexPlace 場所 + ".tsv"）で並べたときと同じ順に
    # なるよう、実際のファイル名（英語の固定名・符号化したシート名）から場所を戻し、その前の名前の付け方の文字列を並べ替えの鍵にする）。
    # @{ Name; Places（@{ Place; Path } の並び） } の並びを返す
    param (
        [string]$folder
    )

    $longDir = toLongPath $folder
    $entries = New-Object System.Collections.Generic.List[hashtable]
    $keys = New-Object System.Collections.Generic.List[string]
    foreach ($sub in [System.IO.Directory]::EnumerateDirectories($longDir)) {
        if (!(testIndexBookDir $sub)) {
            continue
        }
        $name = [System.IO.Path]::GetFileName($sub)
        foreach ($path in [System.IO.Directory]::GetFiles($sub, "*.tsv", [System.IO.SearchOption]::TopDirectoryOnly)) {
            # 長いパス（\\?\ 付き）は [System.IO.Path]::GetDirectoryName で崩れることがあるため、
            # ここで分かっている $sub・$name をそのまま使い、$path から作り直さない。
            $place = convertIndexFileNameToPlace ([System.IO.Path]::GetFileNameWithoutExtension($path))
            $legacyName = "{0}.tsv" -f (encodeIndexPlace $place)
            # Join-Path は \\?\ 付きの長いパスで「drive」が null というエラーになるため、
            # プロバイダーを介さない [System.IO.Path]::Combine で組み立てる。
            $key = [System.IO.Path]::Combine($sub, $legacyName)
            $entries.Add(@{ Name = $name; Place = $place; Path = $path })
            $keys.Add($key)
        }
    }
    $keyArray = $keys.ToArray()
    $entryArray = $entries.ToArray()
    [System.Array]::Sort($keyArray, $entryArray, [System.StringComparer]::CurrentCultureIgnoreCase)

    $books = New-Object System.Collections.Generic.List[hashtable]
    $current = $null
    foreach ($entry in $entryArray) {
        if (!$current -or $current.Name -ne $entry.Name) {
            $current = @{ Name = $entry.Name; Places = New-Object System.Collections.Generic.List[hashtable] }
            $books.Add($current)
        }
        $current.Places.Add(@{ Place = $entry.Place; Path = $entry.Path })
    }
    return , $books
}


function convertFolderToContentIndex {
    # 今の形式のインデックスのフォルダ 1 つ（直下の <ファイル名.xlsx>\<場所>.tsv）から、拡張子ごと・番号ごとの本文インデックスのファイル
    # （destFolder\content_index.xlsx.001.tsv など）を書く。destFolder に前の本文インデックスのファイルがあれば、それとまぜる（planContentIndexParts）:
    #   ・TSV のある元のファイルは、TSV の中身で入れ替える（前の本文インデックスのファイルに無ければ、最後の番号の本文インデックスのファイルに足す。
    #     contentIndexFileMaxBytes 以上なら次の番号の本文インデックスのファイルを作る）
    #   ・removeBooks に挙げた元のファイルは外す（元のファイルが無くなった）
    #   ・それ以外の元のファイルは、前の本文インデックスのファイルのまま。変わらない本文インデックスのファイルは書き直さない
    # 元のファイルが無くなった本文インデックスのファイルは消す。removeTsv なら、本文インデックスのファイルを書き終えた後に、
    # 読み込んだ元のファイルのフォルダ（TSV）を消す（TSV は一時的な置き場で、残すとインデックスの容量が倍になるため）。
    # 書き終える前に止まっても、TSV か前の本文インデックスのファイルのどちらかに中身が残る。
    # @{ Books; Tsv; Chars; Files（本文インデックスのファイルの数）; Written（書き直した数）;
    #    Texts（そのフォルダのすべての本文インデックスのファイルの中身。システムインデックスを読み直さずに作るため） } を返す
    param (
        [string]$folder,
        [string]$destFolder,
        [string[]]$removeBooks = @(),
        [bool]$removeTsv = $false,
        [long]$maxBytes = ${contentIndexFileMaxBytes}
    )

    $books = getIndexFolderBooks $folder
    $tsvCount = 0
    $newBooks = New-Object System.Collections.Generic.List[hashtable]
    foreach ($book in $books) {
        foreach ($place in $book.Places) {
            $place.Text = [System.IO.File]::ReadAllText($place.Path)
            $tsvCount++
        }
        $newBooks.Add(@{ Name = $book.Name; Block = (convertBookToContentIndexBlock $book) })
    }
    $longDest = toLongPath $destFolder
    # 前の本文インデックスのファイル（番号の付いた名前のもの）を読む
    $parts = New-Object System.Collections.Generic.List[hashtable]
    $oldTexts = @{}
    if ([System.IO.Directory]::Exists($longDest)) {
        foreach ($old in [System.IO.Directory]::GetFiles($longDest, ${contentIndexFilePattern})) {
            $info = readContentIndexFileName ([System.IO.Path]::GetFileName($old))
            if ($null -eq $info) { continue }
            $text = readContentIndexText $old
            $oldTexts[(getContentIndexFileName $info.Extension $info.Part)] = $text
            $parts.Add(@{ Extension = $info.Extension; Part = $info.Part; Books = (splitContentIndexTextByBook $text) })
        }
    }

    $plan = planContentIndexParts $parts $newBooks $removeBooks $maxBytes
    $texts = New-Object System.Collections.Generic.List[string]
    $bookTotal = 0
    $written = 0
    $chars = 0L
    foreach ($part in $plan) {
        $name = getContentIndexFileName $part.Extension $part.Part
        $path = Join-Path $destFolder $name
        if ($part.Books.Count -eq 0) {
            if ([System.IO.File]::Exists((toLongPath $path))) { [System.IO.File]::Delete((toLongPath $path)) }
            continue
        }
        if ($part.Changed) {
            [void][System.IO.Directory]::CreateDirectory($longDest)
            $text = convertToContentIndexText $part.Books
            writeContentIndexFile $path $text
            $written++
        } else {
            $text = $oldTexts[$name]
        }
        $texts.Add($text)
        $bookTotal += $part.Books.Count
        $chars += $text.Length
    }
    if ($removeTsv) {
        foreach ($book in $books) {
            $bookDir = [System.IO.Path]::GetDirectoryName($book.Places[0].Path)
            removeDirectoryRetry $bookDir
        }
    }
    return @{ Books = $bookTotal; Tsv = $tsvCount; Chars = $chars; Files = $texts.Count; Written = $written; Texts = [string[]]$texts.ToArray() }
}

function updateFolderContentIndex {
    # インデックスのフォルダ 1 つで、置かれた TSV（追加・更新した元のファイル）を本文インデックスのファイルに入れ、TSV を消す。
    # removeBooks に挙げた元のファイル（無くなったもの）は本文インデックスのファイルから外す
    param (
        [string]$folder,
        [string[]]$removeBooks = @()
    )

    return convertFolderToContentIndex $folder $folder $removeBooks $true
}

function findContentIndexFiles {
    # インデックスのフォルダ以下の本文インデックスのファイルを列挙し、フォルダの順・フォルダの中は名前の順に並べて返す。
    #   root   : インデックスのフォルダ（相対パスの基準）
    #   relPath: その中のフォルダ（空は root 自身）
    #   recurse: $false なら、そのフォルダの本文インデックスのファイルだけ
    # 各要素は @{ Path（\\?\ 付き）; Root; RelDir（root からのフォルダ）; RelPath; Ticks; Size }
    param (
        [string]$root,
        [string]$relPath = "",
        [bool]$recurse = $true
    )

    $root = $root.TrimEnd("\")
    $relPath = $relPath.Trim("\")
    $dir = if ($relPath) { "${root}\${relPath}" } else { $root }
    $longDir = toLongPath $dir
    if (![System.IO.Directory]::Exists($longDir)) {
        return , @()
    }
    $option = if ($recurse) { [System.IO.SearchOption]::AllDirectories } else { [System.IO.SearchOption]::TopDirectoryOnly }
    $found = [System.IO.DirectoryInfo]::new($longDir).GetFiles(${contentIndexFilePattern}, $option)
    $plainDir = fromLongPath $longDir
    $list = New-Object System.Collections.Generic.List[hashtable]
    foreach ($file in $found) {
        $full = $plainDir + $file.FullName.Substring($longDir.Length)
        $rel = $full.Substring($root.Length + 1)
        $list.Add(@{
            Path = $file.FullName; Root = $root; RelPath = $rel
            RelDir = [string][System.IO.Path]::GetDirectoryName($rel)
            Ticks = $file.LastWriteTimeUtc.Ticks; Size = $file.Length
        })
    }
    # フォルダの順、フォルダの中は本文インデックスのファイルの名前の順（現在のカルチャ・大文字と小文字を区別しない）
    $items = [hashtable[]]@($list | Sort-Object @{ Expression = { $_.RelDir } }, @{ Expression = { [System.IO.Path]::GetFileName($_.RelPath) } })
    return , $items
}


function findIndexFoldersWithBooks {
    # インデックスのフォルダ以下で、元のファイルごとのフォルダ（<ファイル名.xlsx>。本文インデックスのファイルに入れる前の TSV）が
    # 直下にあるフォルダを返す（インデックス作成が途中で止まったとき）。root 自身も含む
    param (
        [string]$root
    )

    $found = New-Object System.Collections.Generic.List[string]
    $longRoot = toLongPath $root.TrimEnd("\")
    if (![System.IO.Directory]::Exists($longRoot)) {
        return , $found.ToArray()
    }
    $dirs = @($longRoot) + @([System.IO.Directory]::GetDirectories($longRoot, "*", [System.IO.SearchOption]::AllDirectories))
    foreach ($dir in $dirs) {
        if ($dir -ne $longRoot -and (testIndexBookDir $dir $false)) { continue }
        if (testAnyEntry ([System.IO.Directory]::EnumerateDirectories($dir)) { param ($sub) testIndexBookDir $sub }) {
            $found.Add((fromLongPath $dir))
        }
    }
    return , $found.ToArray()
}


function publishIndexFolders {
    # インデックス作成で TSV を置いた・元のファイルが無くなったフォルダを、まとめて書き出す。フォルダごとに次を続けて行う:
    #   1. 本文インデックスのファイルを書く（前の本文インデックスのファイルとまぜ、無くなった元のファイルは外す）
    #   2. 元のファイルごとのフォルダの TSV を消す
    #   3. 書いた本文インデックスのファイルの中身から、そのフォルダのシステムインデックスの txt を作る（読み直さない）
    # txt の状態（反映待ち）はまとめて状態ファイルに書く。書き出したフォルダの数を返す。
    #   pending: フォルダ（フルパス）→ 無くなった元のファイル名の集まり
    param (
        $pending,
        [string]$indexRoot = $workspace.IndexDir,
        [string]$systemRoot = $workspace.SystemIndexDir,
        [string]$statePath = $workspace.SystemIndexStateFile
    )

    $results = New-Object System.Collections.Generic.List[hashtable]
    foreach ($folder in @($pending.Keys)) {
        $contentIndexFile = updateFolderContentIndex $folder ([string[]]@($pending[$folder]))
        # 書いた本文インデックスのファイルは、フォルダごとに書いた直後にここで NotContentIndexed を付ける（件数が多いため失敗してもログに出さない）
        [void](setNotContentIndexed $folder)
        $results.Add((writeSystemIndexFolder $folder $indexRoot $systemRoot $contentIndexFile.Texts))
    }
    if ($results.Count -gt 0) {
        $saved = updateSystemIndexState { param ($state) setSystemIndexResults $state $results.ToArray() } $statePath
        if (!$saved) {
            writeIndexerLog "システムインデックスの状態を書き込めませんでした（インデックス作成の終わりに作り直します）。" "Yellow"
        }
    }
    return $results.Count
}


function readContentIndexLines {
    # 本文インデックスのファイルの中の、元のファイル book・場所 location の firstLine 行目から count 行を返す（画面の選択行のプレビュー。
    # 行の数え方は検索と同じ）。戻り値は @{ Rows = @{ LineNumber; Line } の配列; End = 頼んだ数より少なく返ったか（場所の終わりまで読んだ）; Marks = 更新した控え }。
    # cache（検索のキャッシュ）に同じ本文インデックスのファイルの内容があれば、ファイルを読み直さない。読めない・見つからなければ Rows は空・End は $true。
    #
    # marks は、繰り返し読むときに先頭から読み飛ばさないための控え（@{ Path; Ticks; Size; Places; Checkpoints }。
    # ファイルのパス・更新日時・大きさが同じ間だけ使う）。呼び出し側が引数で渡し、戻り値の Marks で受け取る
    # （読み足しは別の runspace で動くため、$script: には置かない。渡された控えは書き換えず、新しいものを返す）。
    # Places は場所の一覧、Checkpoints は場所ごと（Book と Location をタブでつないだ名前）の、200 行ごとの行の先頭の位置（行の番号 → 文字の位置）
    param (
        [string]$path,
        [string]$book,
        [string]$location,
        [int]$firstLine,
        [int]$count,
        $cache = $null,
        $marks = $null
    )

    $first = [Math]::Max(1, $firstLine)
    $last = $first + $count - 1
    if ($count -le 0) { return @{ Rows = @(); End = $false; Marks = $marks } }
    $nothing = @{ Rows = @(); End = $true; Marks = $marks }
    $text = $null
    $places = $null
    $longPath = toLongPath $path
    $entry = $null
    if ($null -ne $cache -and $cache.Texts.TryGetValue($longPath, [ref]$entry) -and $entry.Count -ge 4) {
        $info = [System.IO.FileInfo]::new($longPath)
        if ($info.Exists -and $entry[0] -eq $info.LastWriteTimeUtc.Ticks -and $entry[1] -eq $info.Length) {
            $text = $entry[2]
            $places = $entry[3]
        }
    }
    $isRange = $false
    $newMarks = $marks
    $checkpoints = $null
    $allCheckpoints = $null
    $placeKey = "$book`t$location"
    try {
        if ($null -eq $text) {
            # キャッシュに無いときは、ファイルの全体を文字列にしない。控えがあれば、その場所の目当ての行の手前の位置から必要な行までだけを読む
            # （続けて読むたびに、全体を読み直さず、場所の先頭からも読み飛ばさない）
            $info = [System.IO.FileInfo]::new($longPath)
            if (!$info.Exists) { return $nothing }
            if ($null -ne $marks -and $marks.Path -eq $longPath -and $marks.Ticks -eq $info.LastWriteTimeUtc.Ticks -and $marks.Size -eq $info.Length) {
                $places = $marks.Places
                $allCheckpoints = $(if ($null -ne $marks.Checkpoints) { $marks.Checkpoints.Clone() } else { @{} })
                $found = $false
                foreach ($place in $places) {
                    if ($place.Book -ne $book -or $place.Location -ne $location) { continue }
                    $found = $true
                    # 位置は場所ごとに控える（行の番号が同じでも、別の場所の位置は使わない）
                    $checkpoints = $(if ($allCheckpoints.ContainsKey($placeKey)) { $allCheckpoints[$placeKey].Clone() } else { @{} })
                    $allCheckpoints[$placeKey] = $checkpoints
                    $base = 1
                    $startPosition = $place.Start
                    foreach ($key in $checkpoints.Keys) {
                        if ($key -le $first -and $key -gt $base) { $base = $key; $startPosition = $checkpoints[$key] }
                    }
                    $text = readContentIndexRange $path $startPosition $place.End ($first - $base + 1) ($last - $base + 1) $base $checkpoints
                    break
                }
                # 控えが今のファイルのものなら、無い場所はファイルを読まずに空
                if (!$found) { return $nothing }
                if ($null -ne $text) {
                    # 読んでいる間にファイルが置き換わっていたら、古い位置で読んだ行は使わず、全体を読み直す
                    $again = [System.IO.FileInfo]::new($longPath)
                    if ($again.Exists -and $again.LastWriteTimeUtc.Ticks -eq $info.LastWriteTimeUtc.Ticks -and $again.Length -eq $info.Length) { $isRange = $true } else { $text = $null }
                }
            }
            if ($null -eq $text) {
                $text = readContentIndexText $path
                $places = readContentIndexPlaces $text
                $checkpoints = @{}
                $allCheckpoints = @{ $placeKey = $checkpoints }
            }
            $newMarks = @{ Path = $longPath; Ticks = $info.LastWriteTimeUtc.Ticks; Size = $info.Length; Places = $places; Checkpoints = $allCheckpoints }
        }
    } catch [System.IO.IOException] {
        return $nothing
    } catch [System.UnauthorizedAccessException] {
        return $nothing
    }
    $rows = New-Object System.Collections.Generic.List[psobject]
    $isTextBook = (getContentIndexFileKind $book) -eq "テキスト"
    foreach ($place in $places) {
        if ($place.Book -ne $book -or $place.Location -ne $location) { continue }
        # 範囲だけ読んだときは、text の先頭が $first 行目の先頭
        $number = if ($isRange) { $first - 1 } else { 0 }
        $placeEnd = if ($isRange) { $text.Length } else { [Math]::Min($place.End, $text.Length) }
        $pos = if ($isRange) { 0 } else { $place.Start }
        # ファイルの全体を読んだときは、通った 200 行ごとの行の先頭を控える（範囲を読んだときは readContentIndexRange が控える）
        $record = !$isRange -and $null -ne $checkpoints
        while ($pos -lt $placeEnd) {
            $n = $text.IndexOf([char]10, $pos, $placeEnd - $pos)
            if ($n -lt 0) { $n = $placeEnd }
            $number++
            if ($record -and $number -gt 1 -and ($number - 1) % 200 -eq 0) { $checkpoints[$number] = $pos }
            if ($number -gt $last) { break }
            if ($number -ge $first) {
                $line = $text.Substring($pos, $n - $pos)
                if ($isTextBook) {
                    # 前後の行はどこが一致したかが分からないため、先頭から切る
                    $line = truncateHitLine $line -1
                }
                $rows.Add([pscustomobject]@{ LineNumber = $number; Line = $line })
            }
            $pos = $n + 1
        }
        break
    }
    return @{ Rows = $rows.ToArray(); End = ($rows.Count -lt $count); Marks = $newMarks }
}


# システムインデックス（system_index の txt）と、その状態ファイル（system_index_state.tsv）の読み書き（状態層）。
# txt は index の中のフォルダ 1 つにつき 1 つ（分けたときは複数）で、index と同じ相対パスの system_index の中に置く。
# 中身は、そのフォルダ直下の本文インデックスのファイル（content_index.<拡張子>.tsv）と、インデックス作成の途中で残った、直下のブックのフォルダ（<ファイル名.xlsx>）の中の TSV から作る（search_gram.ps1）。
# 本文インデックスのファイルのメタ情報の行は除く（getContentIndexBodyText）。

function getSystemIndexFolderTsvPaths {
    # index の中のフォルダ 1 つの、システムインデックスの元になるファイル（直下の本文インデックスのファイル・TSV と、直下のブックのフォルダの中の TSV。\\?\ 付き）。
    # 検索対象のツリーで「フォルダ直下のファイル」を選んだときと同じ範囲（getContentIndexFiles の Recurse = $false）
    param (
        [string]$folder
    )

    $long = toLongPath $folder
    $paths = New-Object System.Collections.Generic.List[string]
    if (![System.IO.Directory]::Exists($long)) {
        return , $paths.ToArray()
    }
    $paths.AddRange([System.IO.Directory]::GetFiles($long, "*.tsv"))
    foreach ($sub in [System.IO.Directory]::GetDirectories($long)) {
        if (testIndexBookDir $sub) {
            $paths.AddRange([System.IO.Directory]::GetFiles($sub, "*.tsv"))
        }
    }
    return , $paths.ToArray()
}

function writeSystemIndexFolder {
    # index の中のフォルダ 1 つについて、system_index の txt を作り直す。
    # @{ Rel（index からの相対パス）; Files（@{ Rel（system_index からの txt の相対パス）; Ticks（更新日時。UTC の Ticks） } の配列）;
    #    Excluded（パスが長すぎて作らなかった） } を返す。本文インデックスのファイル・TSV が無くなったフォルダは txt を消して Files を空で返す
    #   texts: そのフォルダの本文インデックスのファイルの中身（インデックス作成で書いたばかりのもの）。渡せばファイルを読み直さない
    param (
        [string]$folder,
        [string]$indexRoot,
        [string]$systemRoot,
        [string[]]$texts = $null
    )

    $rel = $folder.Substring($indexRoot.TrimEnd("\").Length).Trim("\")
    $outDir = "$($systemRoot.TrimEnd('\'))\$rel"
    $longOut = toLongPath $outDir
    $result = @{ Rel = $rel; Files = @(); Excluded = $false }

    # 前の txt（分けた数が変わることもあるため、すべて）を消す
    if ([System.IO.Directory]::Exists($longOut)) {
        foreach ($old in [System.IO.Directory]::GetFiles($longOut, "$([System.IO.Path]::GetFileNameWithoutExtension(${systemIndexFileName}))*.txt")) {
            [System.IO.File]::Delete($old)
        }
    }
    $set = New-Object 'System.Collections.Generic.HashSet[uint32]'
    if ($null -ne $texts) {
        if ($texts.Count -eq 0) {
            return $result
        }
        foreach ($text in $texts) {
            addTextGrams $set (getContentIndexBodyText $text)
        }
    } else {
        $tsvPaths = getSystemIndexFolderTsvPaths $folder
        if ($tsvPaths.Count -eq 0) {
            return $result
        }
        foreach ($path in $tsvPaths) {
            $text = [System.IO.File]::ReadAllText($path)
            if ([System.IO.Path]::GetFileName($path) -like ${contentIndexFilePattern}) {
                $text = getContentIndexBodyText $text
            }
            addTextGrams $set $text
        }
    }
    $values = New-Object 'uint32[]' $set.Count
    $set.CopyTo($values)
    [Array]::Sort($values)
    $parts = getGramPartCount $values.Length
    if (!(testSystemIndexPath $outDir $parts)) {
        $result.Excluded = $true
        return $result
    }

    [System.IO.Directory]::CreateDirectory($longOut) | Out-Null
    $perPart = [int][Math]::Ceiling($values.Length / $parts)
    $names = getSystemIndexFileNames $parts
    $files = New-Object System.Collections.Generic.List[hashtable]
    for ($p = 0; $p -lt $parts; $p++) {
        $start = $p * $perPart
        $text = convertToGramText $values $start ([Math]::Min($perPart, $values.Length - $start))
        $path = "$longOut\$($names[$p])"
        [System.IO.File]::WriteAllText($path, $text, [System.Text.Encoding]::ASCII)
        $files.Add(@{ Rel = "$rel\$($names[$p])"; Ticks = [System.IO.File]::GetLastWriteTimeUtc($path).Ticks })
    }
    $result.Files = $files.ToArray()
    return $result
}

# txt をまとめて作るときのスレッドの数の上限（物理メモリ 8GB の PC で 4 スレッドのときにメモリが足りなくなったことがあるため）
${systemIndexWorkerMax} = 4

function writeSystemIndexFolders {
    # index の中のフォルダの txt を、まとめて作り直す（並列）。writeSystemIndexFolder の結果の配列を返す。
    #   shouldStop: $true を返すと、始めていない分を作らずに止める（作った分だけを返す）
    param (
        [string[]]$folders,
        [string]$indexRoot,
        [string]$systemRoot,
        [int]$workers = 0,
        [scriptblock]$shouldStop = $null
    )

    $results = New-Object System.Collections.Generic.List[hashtable]
    if ($folders.Count -eq 0) {
        return , $results.ToArray()
    }
    if ($workers -le 0) {
        $workers = [Math]::Min([Environment]::ProcessorCount, ${systemIndexWorkerMax})
    }
    $workers = [Math]::Min($workers, $folders.Count)
    if ($workers -le 1) {
        foreach ($folder in $folders) {
            if ($shouldStop -and (& $shouldStop)) {
                break
            }
            $results.Add((writeSystemIndexFolder $folder $indexRoot $systemRoot))
        }
        return , $results.ToArray()
    }

    # 各スレッドには必要な関数・値だけを読み込む（lib.ps1 全体を読み込むと、スレッドを用意するだけで時間がかかるため）。
    # インデックス作成の処理のため、スレッドの優先度を下げる（画面・検索を先に動かす。docs/design/structure/threads.md「スレッドの一覧」）
    $state = newWorkerState @("writeSystemIndexFolder", "getSystemIndexFolderTsvPaths", "addTextGrams", "convertToGramText",
        "getGramPartCount", "getSystemIndexFileNames", "testSystemIndexPath", "toLongPath", "getContentIndexBodyText", "testIndexBookDir", "testAnyEntry") `
        @("systemIndexFileName", "systemIndexPartBytes", "systemIndexPathMax", "indexBookDirPattern", "contentIndexFilePattern")
    $pool = [WorkerPool]::new($workers, $state, $Host, "BelowNormal")
    $pending = New-Object System.Collections.Generic.Queue[hashtable]
    $jobScript = {
        param ($folder, $indexRoot, $systemRoot)
        # 別スレッドは既定では .NET の例外で止まらず、書けなかった txt を作ったものとして返してしまう。例外で止めて呼び出し元に伝える
        $ErrorActionPreference = "Stop"
        @{ Result = writeSystemIndexFolder $folder $indexRoot $systemRoot }
    }.ToString()
    try {
        $next = 0
        while ($next -lt $folders.Count -or $pending.Count -gt 0) {
            # スレッド数の 2 倍まで先に始めておき、終わった順ではなく始めた順に受け取る
            while ($pending.Count -lt $workers * 2 -and $next -lt $folders.Count) {
                if ($shouldStop -and (& $shouldStop)) {
                    $next = $folders.Count
                    break
                }
                $pending.Enqueue($pool.Submit($jobScript, @($folders[$next], $indexRoot, $systemRoot)))
                $next++
            }
            if ($pending.Count -eq 0) {
                break
            }
            $output = $pool.Receive($pending.Dequeue())
            if ($output.Count -gt 0) {
                $results.Add($output[0].Result)
            }
        }
    } finally {
        foreach ($job in $pending) {
            $pool.Cancel($job)
        }
        $pool.Close()
    }
    return , $results.ToArray()
}

function readSystemIndexState {
    # 状態ファイルを読む（convertFromSystemIndexState の形）。無ければ空。
    # 書き込み中などで読めなければ $null（高速検索を使わず、すべてを照合する）
    param (
        [string]$path = $workspace.SystemIndexStateFile
    )

    if (![System.IO.File]::Exists($path)) {
        return newSystemIndexState
    }
    for ($i = 1; $i -le 10; $i++) {
        try {
            $stream = [System.IO.FileStream]::new($path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read)
            try {
                $reader = [System.IO.StreamReader]::new($stream, [System.Text.Encoding]::UTF8, $true)
                return convertFromSystemIndexState ($reader.ReadToEnd() -split "\r?\n")
            } finally {
                $stream.Dispose()
            }
        } catch [System.IO.IOException] {
            Start-Sleep -Milliseconds 100
        }
    }
    return $null
}

function updateSystemIndexState {
    # 状態ファイルを排他で開き、change（{ param($state) }）で書き換えて保存する。
    # インデクサ（取り込み）と画面（検索のたびの整理）が同時に書かないよう、開いている間はほかから開けない。
    # 開けなければ少し待って数回試し、それでも開けなければ $false を返す（書き換えは次の機会に回る）
    param (
        [scriptblock]$change,
        [string]$path = $workspace.SystemIndexStateFile
    )

    [System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($path)) | Out-Null
    $stream = $null
    for ($i = 1; $i -le 20 -and $null -eq $stream; $i++) {
        try {
            $stream = [System.IO.FileStream]::new($path, [System.IO.FileMode]::OpenOrCreate, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None)
        } catch [System.IO.IOException] {
            Start-Sleep -Milliseconds 100
        }
    }
    if ($null -eq $stream) {
        return $false
    }
    try {
        $reader = [System.IO.StreamReader]::new($stream, [System.Text.Encoding]::UTF8, $true, 4096, $true)
        $state = convertFromSystemIndexState ($reader.ReadToEnd() -split "\r?\n")
        $reader.Dispose()
        & $change $state
        $bytes = ${utf8Bom}.GetPreamble() + ${utf8Bom}.GetBytes(((convertToSystemIndexState $state) -join "`r`n") + "`r`n")
        $stream.SetLength(0)
        $stream.Write($bytes, 0, $bytes.Length)
    } finally {
        $stream.Dispose()
    }
    return $true
}

function removeSystemIndexEntries {
    # 状態から、相対パス rel のフォルダ（とその中）の行を消す。indexName を渡したら、そのインデックスの「対応済み」も消す
    param (
        $state,
        [string]$rel,
        [string]$indexName = ""
    )

    foreach ($key in @($state.Pending.Keys)) {
        if ($key.StartsWith("$rel\", [System.StringComparison]::OrdinalIgnoreCase)) {
            [void]$state.Pending.Remove($key)
        }
    }
    foreach ($key in @($state.Excluded)) {
        if ($key.Equals($rel, [System.StringComparison]::OrdinalIgnoreCase) -or $key.StartsWith("$rel\", [System.StringComparison]::OrdinalIgnoreCase)) {
            [void]$state.Excluded.Remove($key)
        }
    }
    if ($indexName) {
        [void]$state.Covered.Remove($indexName)
    }
}

function setSystemIndexResults {
    # writeSystemIndexFolder の結果を状態に書く（フォルダの前の行は消して、作った txt を反映待ちにする）
    param (
        $state,
        [object[]]$results
    )

    foreach ($result in $results) {
        # フォルダ直下の txt の行だけを消す（サブフォルダの行は、サブフォルダの結果で書き換わる）
        foreach ($key in @($state.Pending.Keys)) {
            if ([System.IO.Path]::GetDirectoryName($key) -eq $result.Rel) {
                [void]$state.Pending.Remove($key)
            }
        }
        [void]$state.Excluded.Remove($result.Rel)
        foreach ($file in $result.Files) {
            $state.Pending[$file.Rel] = $file.Ticks
        }
        if ($result.Excluded) {
            [void]$state.Excluded.Add($result.Rel)
        }
    }
}

function markSystemIndexChanged {
    # TSV を入れ替えたフォルダを「反映待ち（日時は 0）」にする（txt を作り直すまで、そのフォルダは .NET で照合させる）。
    # 0 は txt の更新日時とも Windows Search の DateModified とも一致しないため、前の txt が索引されていても反映済みにならない
    # （今の日時にすると、txt を書いたのと同じ秒の中では一致して、反映済みと取り違える）
    param (
        [string[]]$rels,
        [string]$path = $workspace.SystemIndexStateFile
    )

    return updateSystemIndexState {
        param ($state)
        foreach ($rel in $rels) {
            $state.Pending["$rel\${systemIndexFileName}"] = 0
        }
    } $path
}

function getSystemIndexStaleFolders {
    # txt の作り直しが要る index の中のフォルダ（フルパス）を返す。
    #   txt が無い・TSV より古い・状態が「反映待ち」なのに txt の更新日時と合わない（取り込みの途中で止まった）もの
    param (
        [string]$indexRoot,
        [string]$systemRoot,
        $state
    )

    $stale = New-Object System.Collections.Generic.List[string]
    $longRoot = toLongPath $indexRoot
    if (![System.IO.Directory]::Exists($longRoot)) {
        return , $stale.ToArray()
    }
    $rootLength = $indexRoot.TrimEnd("\").Length
    foreach ($longDir in [System.IO.Directory]::EnumerateDirectories($longRoot, "*", [System.IO.SearchOption]::AllDirectories)) {
        # 元のファイルごとのフォルダ（本文インデックスにする前の TSV・中身が空のファイル）は、親のフォルダの txt に入る
        if (testIndexBookDir $longDir $false) {
            continue
        }
        $folder = fromLongPath $longDir
        $rel = $folder.Substring($rootLength).Trim("\")
        if ($state.Excluded.Contains($rel)) {
            continue
        }
        $tsvPaths = getSystemIndexFolderTsvPaths $folder
        $txtDir = toLongPath "$($systemRoot.TrimEnd('\'))\$rel"
        $txts = if ([System.IO.Directory]::Exists($txtDir)) { @([System.IO.Directory]::GetFiles($txtDir, "$([System.IO.Path]::GetFileNameWithoutExtension(${systemIndexFileName}))*.txt")) } else { @() }
        if ($tsvPaths.Count -eq 0) {
            if ($txts.Count -gt 0) {
                $stale.Add($folder)   # TSV が無くなった（txt を消す）
            }
            continue
        }
        if ($txts.Count -eq 0) {
            $stale.Add($folder)
            continue
        }
        $oldest = ($txts | ForEach-Object { [System.IO.File]::GetLastWriteTimeUtc($_) } | Measure-Object -Minimum).Minimum
        $newestTsv = ($tsvPaths | ForEach-Object { [System.IO.File]::GetLastWriteTimeUtc($_) } | Measure-Object -Maximum).Maximum
        $marked = $state.Pending.ContainsKey("$rel\${systemIndexFileName}") -and
            $state.Pending["$rel\${systemIndexFileName}"] -ne [System.IO.File]::GetLastWriteTimeUtc("$txtDir\${systemIndexFileName}").Ticks
        if ($newestTsv -gt $oldest -or $marked) {
            $stale.Add($folder)
        }
    }
    return , $stale.ToArray()
}

function updateSystemIndexes {
    # インデックス作成の終わりに、システムインデックスの作り直しが要るフォルダをまとめて作り直し、状態ファイルに書く。
    # すべてのフォルダの txt がそろったインデックスは「対応済み」にする（対応済みでないインデックスは、高速検索でもすべてを照合する）。
    # 利用者の作業の邪魔にならないよう、作るスレッドの優先度を下げる（writeSystemIndexFolders）。shouldStop が $true を返せば、始めていない分は作らない。
    # 作り直したフォルダの数と、作り終えていないインデックスの数を @{ Built; Unfinished } で返す
    param (
        [string]$indexRoot = $workspace.IndexDir,
        [string]$systemRoot = $workspace.SystemIndexDir,
        [string]$statePath = $workspace.SystemIndexStateFile,
        [scriptblock]$shouldStop = $null
    )

    $state = readSystemIndexState $statePath
    if ($null -eq $state) {
        writeIndexerLog "システムインデックスの状態を読めないため、作り直しは次のインデックス作成に回します。" "Yellow"
        return @{ Built = 0; Unfinished = -1 }
    }
    # 無くなったインデックス（設定から外した・画面で削除した）の txt と状態の行を消す
    $names = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    if ([System.IO.Directory]::Exists((toLongPath $indexRoot))) {
        foreach ($dir in [System.IO.Directory]::GetDirectories((toLongPath $indexRoot))) {
            [void]$names.Add([System.IO.Path]::GetFileName($dir))
        }
    }
    $gone = New-Object System.Collections.Generic.List[string]
    if ([System.IO.Directory]::Exists((toLongPath $systemRoot))) {
        foreach ($dir in [System.IO.Directory]::GetDirectories((toLongPath $systemRoot))) {
            $gone.Add([System.IO.Path]::GetFileName($dir))
        }
    }
    $gone.AddRange([string[]]@($state.Covered))
    foreach ($name in ($gone | Sort-Object -Unique)) {
        if (!$names.Contains($name)) {
            [void](removeSystemIndexOf $name $systemRoot $statePath)
            [void]$state.Covered.Remove($name)
        }
    }

    $stale = getSystemIndexStaleFolders $indexRoot $systemRoot $state
    $results = @()
    if ($stale.Count -gt 0) {
        writeIndexerLog "システムインデックス（高速検索用）を作っています…（$($stale.Count) フォルダ）"
        $results = writeSystemIndexFolders $stale $indexRoot $systemRoot 0 $shouldStop

    }
    # 作り終えていないフォルダがあるインデックスは、対応済みにしない
    $built = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($result in $results) {
        [void]$built.Add($result.Rel)
    }
    $unfinished = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    $rootLength = $indexRoot.TrimEnd("\").Length
    foreach ($folder in $stale) {
        $rel = $folder.Substring($rootLength).Trim("\")
        if (!$built.Contains($rel)) {
            [void]$unfinished.Add((getIndexNameOfRelPath $rel))
        }
    }
    $saved = updateSystemIndexState {
        param ($current)
        setSystemIndexResults $current $results
        foreach ($name in $names) {
            if ($unfinished.Contains($name)) {
                [void]$current.Covered.Remove($name)
            } else {
                [void]$current.Covered.Add($name)
            }
        }
    } $statePath
    if (!$saved) {
        writeIndexerLog "システムインデックスの状態を書き込めなかったため、次のインデックス作成で作り直します。" "Yellow"
    } elseif ($unfinished.Count -gt 0) {
        writeIndexerLog "中止したため、システムインデックスの一部（$($stale.Count - $built.Count) フォルダ）は次のインデックス作成で作ります。" "Yellow"
    }
    return @{ Built = $built.Count; Unfinished = $unfinished.Count }
}

function removeSystemIndexOf {
    # インデックス（または index の中のフォルダ）を消したとき、system_index の同じフォルダと状態の行を消す
    param (
        [string]$rel,
        [string]$systemRoot = $workspace.SystemIndexDir,
        [string]$path = $workspace.SystemIndexStateFile
    )

    $dir = toLongPath "$($systemRoot.TrimEnd('\'))\$rel"
    if ([System.IO.Directory]::Exists($dir)) {
        removeDirectoryRetry "$($systemRoot.TrimEnd('\'))\$rel"
    }
    $name = getIndexNameOfRelPath $rel
    $indexName = if ($name -eq $rel) { $name } else { "" }
    return updateSystemIndexState { param ($state) removeSystemIndexEntries $state $rel $indexName } $path
}

# インデックス作成の状態（取り込み一覧・取り込み中のファイル）の読み書きと、画面とインデクサの受け渡しの口・ログ。

# 1ファイルの取り込みの制限時間（分）。超えたらOfficeアプリを強制終了し、そのファイルは失敗とする（クラウドからのダウンロードも含む。確認の文言も同じ値を使う）
${ingestFileTimeoutMinutes} = 10

function describeIngestError {
    # 取り込みで発生した例外から、取り込み一覧のエラー列・画面に表示する失敗の理由を返す。
    # Officeアプリのメッセージは分かりにくい（パスワード付きでも「入力したパスワードが間違っています」等）ため、
    # よくある原因は「原因（詳細: 元のメッセージ）」の形に言い換える
    param (
        [System.Exception]$exception
    )

    # メソッド呼び出しの例外（「"7" 個の引数を指定して "Open" を呼び出し中に例外が発生しました」等）は、中の例外が本来の理由
    $base = $exception.GetBaseException()
    $message = ($base.Message -replace "\s+", " ").Trim()
    $code = "{0:X8}" -f $base.HResult
    if ($message -eq "") {
        $message = "エラーコード 0x${code}"
    }

    # スクリプト自身が throw したメッセージは、利用者向けに書いてあるためそのまま使う
    if ($base.GetType() -eq [System.Management.Automation.RuntimeException]) {
        return $message
    }

    if ($message -match "パスワード|password") {
        # 元のメッセージ（パスワードが間違っています等）は、パスワードを入力していない利用者には誤解を招くため付けない
        return "読み取りパスワードが設定されているため開けません（パスワード付きのファイルは更新できません）"
    }

    $cause = $null
    if ($base -is [System.IO.FileNotFoundException] -or $base -is [System.IO.DirectoryNotFoundException]) {
        $cause = "ファイルが見つかりません（更新中に移動・削除・名前変更された可能性があります）"
    } elseif ($base -is [System.UnauthorizedAccessException] -or $code -eq "80070005") {
        $cause = "ファイルを読むアクセス権がありません"
    } elseif ($base -is [System.IO.PathTooLongException]) {
        $cause = "パスが長すぎるため読めません"
    } elseif ($base -is [System.OutOfMemoryException]) {
        # 巨大なシート（テキストにして約 1GB 超）は、整形（prettyTsv）で一度に読み込めずメモリ不足になる
        $cause = "シート・文書が大きすぎて更新できません（メモリが不足しました）"
    } elseif (@("80070020", "80070021") -contains $code) {
        # 共有違反・ロック違反
        $cause = "ほかのアプリ・利用者がファイルを使用中のため読めません（ファイルを閉じてから再度更新してください）"
    } elseif (@("80040154", "80080005", "800401F3") -contains $code) {
        # クラス未登録・サーバーの起動失敗・ProgID 不正
        $cause = "Officeアプリ（Excel・Word・PowerPoint）を起動できませんでした（インストール・ライセンス認証の状態を確認してください）"
    } elseif (@("800706BA", "800706BE", "80010105", "80010108") -contains $code) {
        # RPC サーバーを利用できない・呼び出し失敗・サーバーで例外・切断
        $cause = "Officeアプリが異常終了したか、内部でエラーが発生しました（ファイルが壊れている、または大きすぎる可能性があります）"
    } elseif (@("80010001", "8001010A") -contains $code) {
        # 呼び出しの拒否・処理中のため後で再試行
        $cause = "Officeアプリが応答しませんでした（Officeアプリでダイアログを表示中などの可能性があります）"
    } elseif ($base -is [System.IO.InvalidDataException] -or $base -is [System.Xml.XmlException] -or
              $message -match "ファイル形式|破損|壊れ|corrupt|file format") {
        $cause = "ファイルが壊れているか、拡張子と中身の形式が一致していません"
    }

    if ($cause) {
        return "${cause}（詳細: ${message}）"
    }
    return $message
}

function addStatusRow {
    # 取り込み一覧の末尾に1行追記する（readStatusFile では後の行が優先される）
    param (
        $row,
        [string]$path = $workspace.StatusFile
    )

    [System.IO.File]::AppendAllText($path, "$(toStatusLine $row)`r`n", ${utf8Bom})
}

function readIngestingFiles {
    # 取り込み中のファイルの記録を読み、@{ RelPath = 相対パス; Count = 続けて取り込みを始めて終わらなかった回数 } の配列を返す。
    # 取り込みを複数のスレッドで行うため、1 行に 1 ファイル。記録が無ければ空。壊れた行は読み飛ばす
    param (
        [string]$path = $workspace.IngestingFile
    )

    $result = New-Object System.Collections.Generic.List[hashtable]
    foreach ($line in @(readListFile $path)) {
        $fields = $line.Split("`t")
        $count = 0
        if ($fields.Count -ne 2 -or -not [int]::TryParse($fields[0], [ref]$count) -or $count -lt 1 -or $fields[1] -eq "") {
            continue
        }
        $result.Add(@{ RelPath = $fields[1]; Count = $count })
    }
    return , $result.ToArray()
}

function writeIngestingFiles {
    # 取り込み中のファイル（@{ RelPath; Count } の並び）を "回数<TAB>相対パス" で記録する。無ければ記録を消す
    param (
        [object[]]$entries,
        [string]$path = $workspace.IngestingFile
    )

    $lines = @($entries | Where-Object { $_ } | ForEach-Object { "$($_.Count)`t$($_.RelPath)" })
    if ($lines.Count -eq 0) {
        removeIngestingFile $path
        return
    }
    writeListFile $path $lines
}

function removeIngestingFile {
    param (
        [string]$path = $workspace.IngestingFile
    )

    if (Test-Path -LiteralPath $path) {
        Remove-Item -LiteralPath $path -Force
    }
}

# ----------------------------------------------------------------------------
# 画面（または indexer.ps1）とインデクサの受け渡しの口（docs/design/structure/threads.md「画面とインデクサの受け渡し」）
# ----------------------------------------------------------------------------

function newIndexerChannel {
    # 受け渡しの口を作る。画面とインデクサのスレッドの両方から読み書きするため Synchronized にする。
    #   画面が書く      : RetryFailed・IncludeCloud（クラウドにだけあるファイルもダウンロードして取り込むか）・ConfirmTargets・Workers（取り込みのスレッドの数。0 は司令のスレッドで取り込む、-1 は設定・コア数から決める）・Stop・Answer・
    #                     OnlyNames（更新するインデックス名の配列。空なら、チェックの付いたものすべて）
    #   インデクサが書く: Progress（readIndexingProgress の形）・Plan（取り込み予定）・Error・ExitCode（0 完了 / 1 エラー / 2 中止）・
    #                     CloudSkipped（クラウドにだけあるため、ダウンロードせずに残した件数）・
    #                     OnlySkipped（OnlyNames のうち、更新できなかった名前の @{ Name; Reason } の配列）
    #   OfficePids: インデックス作成が起動した Office の PID → @{ ProcessName; StartTicks }（閉じるときに止まらなければ、名前と起動時刻が合う PID だけを止める）
    #   UserOfficePids: 取り込み中に見える窓があった（利用者が使った）PowerPoint の PID → @{ ProcessName; StartTicks }（制限時間を過ぎても、閉じるときも止めない）
    param (
        [bool]$retryFailed = $false,
        [bool]$confirmTargets = $false,
        [int]$workers = -1,
        [string[]]$onlyNames = @(),
        [bool]$includeCloud = $false
    )

    return [hashtable]::Synchronized(@{
        RetryFailed = $retryFailed; IncludeCloud = $includeCloud; ConfirmTargets = $confirmTargets; Workers = $workers
        OnlyNames = @($onlyNames | Where-Object { $_ }); OnlySkipped = @()
        Progress = $null; Stop = $false
        Plan = $null; Answer = $null; Answered = New-Object System.Threading.ManualResetEvent($false)
        Error = ""; ExitCode = $null; CloudSkipped = 0
        OfficePids = New-Object 'System.Collections.Concurrent.ConcurrentDictionary[int,object]'
        UserOfficePids = New-Object 'System.Collections.Concurrent.ConcurrentDictionary[int,object]'
    })
}

# いま動いているインデックス作成の受け渡しの口（invokeIndexer が入れる。$null なら進み具合を伝えない）
$script:indexerChannel = $null

function writeIndexingProgress {
    # インデックス作成の進み具合を受け渡しの口に入れる（画面が 1 秒ごとに読む）
    param (
        [string]$phase,
        [int]$processed = 0,
        [int]$remaining = 0,
        [int]$failed = 0,
        [string]$detail = "",
        $channel = $script:indexerChannel
    )

    if ($null -ne $channel) {
        $channel.Progress = @{ Phase = $phase; Processed = $processed; Remaining = $remaining; Failed = $failed; Detail = ($detail -replace "[\t\r\n]+", " ") }
    }
}

function readIndexingProgress {
    # インデックス作成の進み具合（@{ Phase; Processed; Remaining; Failed; Detail }）を返す。まだ無ければ $null
    param (
        $channel
    )

    if ($null -eq $channel) {
        return $null
    }
    return $channel.Progress
}

function requestIndexingStop {
    # 中止を求める。取り込みはファイルの切れ目で止まる。確認を待っていれば、取りやめの返事にする
    param (
        $channel
    )

    $channel.Stop = $true
    [void]$channel.Answered.Set()
}

function answerIndexingPlan {
    # 確認の返事を返す。取り込む → @{ RetryFailed; IncludeCloud } ／ 取りやめ → $null
    param (
        $channel,
        $answer
    )

    $channel.Answer = $answer
    if ($null -eq $answer) {
        $channel.Stop = $true
    }
    [void]$channel.Answered.Set()
}

function testIndexerRunning {
    # この work でインデックス作成が動いているか（画面のスレッド・画面を使わない indexer.ps1 のどちらでも）。
    # インデックス作成が持つ鍵（newAppMutex "indexer"）を取れるかで調べ、取れたらすぐ放す
    param (
        [string]$dir = $workspace.Dir
    )

    $mutex = newAppMutex "indexer" $dir
    try {
        return !$mutex.Acquired
    } finally {
        if ($mutex.Acquired) {
            $mutex.Mutex.ReleaseMutex()
        }
        $mutex.Mutex.Dispose()
    }
}

function writeZipSizeLimitLog {
    # .docx・.pptx・.xlsx の部品がサイズの上限を超えたときの詳細をログに書く（画面には出さない）。
    # 原因を調べられるよう、部品名・大きさ・部品ごとか合計かはここだけに書く。
    # 呼び出し元（extract_office.ps1・indexer_run.ps1・office_reader.ps1 のグラフ・SmartArt 読み取り）は、
    # 捕まえた例外をそのまま渡せばよい。ZipSizeLimitException かどうかはここで確かめ、違えば何もしない
    # （param の型を [ZipSizeLimitException] にしないのは、indexer_state.ps1 が office_reader.ps1 より先に
    # 読み込まれ、その時点ではクラスがまだ無いため）
    param (
        [System.Exception]$exception
    )

    if ($exception -isnot [ZipSizeLimitException]) {
        return
    }

    $kindText = switch ($exception.LimitKind) { "Total" { "1ファイルの合計" } "Output" { "埋め込みから出す文字の合計" } default { "部品ごと" } }
    $mb = [math]::Round($exception.MeasuredBytes / 1MB, 1)
    writeIndexerLog "    サイズの上限（${kindText}）を超えました: $($exception.PartName)（$($exception.MeasuredBytes) バイト、約${mb}MB）" "Yellow"
}

function newIngestPlanRow {
    # 取り込み予定（インデックス1件分）の行を作る
    param (
        [string]$name,
        [string]$path,
        [string]$kind = ${planKindIngest},
        [int]$total = 0,    # 見つかった Office ファイルの数
        [int]$targets = 0,  # 今回取り込むファイルの数（新規＋更新あり＋前回未完了＋インデックスなし）
        [int]$new = 0,
        [int]$updated = 0,
        [int]$pending = 0,
        [int]$lost = 0,     # インデックス（TSV）が無くなった・壊れているため取り込み直す
        [int]$failed = 0,   # 前回失敗し、その後更新されていない（再取り込みするかは画面で選ぶ）
        [int]$cloud = 0,        # クラウドにだけあるため、取り込み対象に数えていないファイル（新規・更新あり・前回未完了など）
        [int]$cloudFailed = 0,  # クラウドにだけあり、前回失敗したファイル
        [long]$cloudBytes = 0,  # クラウドにだけあり、取り込み対象のファイルの合計サイズ（バイト）
        [long]$cloudFailedBytes = 0  # クラウドにだけあり、前回失敗したファイルの合計サイズ（バイト）
    )

    return [pscustomobject]@{
        インデックス名 = $name
        元のフォルダ   = $path
        区分           = $kind
        ファイル数     = $total
        取り込み対象       = $targets
        新規           = $new
        更新あり       = $updated
        前回未完了     = $pending
        インデックスなし   = $lost
        前回失敗       = $failed
        クラウド       = $cloud
        クラウド失敗   = $cloudFailed
        クラウド容量   = $cloudBytes
        クラウド失敗容量 = $cloudFailedBytes
    }
}

function readStatusLines {
    # 取り込み一覧を1行ずつ読む（インデックス作成中でも読めるよう共有を許して開く）。ファイルが無ければ空
    param (
        [string]$path = $workspace.StatusFile
    )

    if (!(Test-Path -LiteralPath $path)) {
        return @()
    }
    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $stream = New-Object System.IO.FileStream($path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    $reader = New-Object System.IO.StreamReader($stream, ${utf8Bom})
    try {
        $text = $reader.ReadToEnd()
    } finally {
        $reader.Dispose()
    }
    return @($text -split "\r?\n" | Where-Object { $_ -ne "" })
}

function renameStatusIndexName {
    # 取り込み一覧に記録したインデックス名を書き換える（クロール対象フォルダの行と、各行の相対パスの先頭）。
    # 行の順序と内容をそのまま保つため、行ごとに書き換えて置き換える
    param (
        [string]$oldName,
        [string]$newName,
        [string]$path = $workspace.StatusFile
    )

    $lines = @(readStatusLines $path)
    if ($lines.Count -eq 0) {
        return
    }

    $result = New-Object System.Collections.Generic.List[string]
    foreach ($line in $lines) {
        $fields = $line.Split("`t")
        if ($fields[0] -eq ${statusFolderKey} -and $fields.Count -eq 3 -and [string]::Equals($fields[2], $oldName, [System.StringComparison]::OrdinalIgnoreCase)) {
            $fields[2] = $newName
            $result.Add($fields -join "`t")
            continue
        }
        if ($fields.Count -eq ${statusColumns}.Count -and $fields[0] -ne "") {
            $split = splitIndexRelPath $fields[0]
            if ($split.Rest -ne "" -and [string]::Equals($split.Name, $oldName, [System.StringComparison]::OrdinalIgnoreCase)) {
                $fields[0] = "${newName}\$($split.Rest)"
                $result.Add($fields -join "`t")
                continue
            }
        }
        $result.Add($line)
    }
    writeTextLinesAtomic $path $result
}

function removeStatusIndexName {
    # 取り込み一覧から、あるインデックスの記録（クロール対象フォルダの行と、そのインデックスの各行）を取り除く
    param (
        [string]$name,
        [string]$path = $workspace.StatusFile
    )

    $lines = @(readStatusLines $path)
    if ($lines.Count -eq 0) {
        return
    }

    $result = New-Object System.Collections.Generic.List[string]
    foreach ($line in $lines) {
        $fields = $line.Split("`t")
        if ($fields[0] -eq ${statusFolderKey} -and $fields.Count -eq 3 -and [string]::Equals($fields[2], $name, [System.StringComparison]::OrdinalIgnoreCase)) {
            continue
        }
        if ($fields.Count -eq ${statusColumns}.Count -and $fields[0] -ne "") {
            $split = splitIndexRelPath $fields[0]
            if ($split.Rest -ne "" -and [string]::Equals($split.Name, $name, [System.StringComparison]::OrdinalIgnoreCase)) {
                continue
            }
        }
        $result.Add($line)
    }
    writeTextLinesAtomic $path $result
}

function getIndexingState {
    # 取り込み一覧からインデックス作成の状態を返す:
    #   @{ Exists; Folders（クロール対象フォルダ @{ Path; Name } の配列）; Total; Pending（未取り込み）; Failed; Done; IngestedSince（since 以降に取り込んだ件数）; Updated（取り込み一覧の更新日時）;
    #      FailedRows（失敗したファイルの行。取り込み日時の新しい順）; IndexStats（インデックス名ごとの集計。getIndexStats） }
    param (
        [datetime]$since = [datetime]::MaxValue,
        [string]$path = $workspace.StatusFile
    )

    $state = @{ Exists = $false; Folders = @(); Total = 0; Pending = 0; Failed = 0; Done = 0; IngestedSince = 0; Updated = $null; FailedRows = @(); IndexStats = (getIndexStats $null) }
    if (!(Test-Path -LiteralPath $path)) {
        return $state
    }

    $state.Exists = $true
    $state.Updated = (Get-Item -LiteralPath $path).LastWriteTime
    $status = readStatusFile $path
    $state.Folders = $status.Folders.ToArray()
    $state.Total = $status.Rows.Count
    $state.IndexStats = getIndexStats $status.Rows
    # since を指定しないとき（画面の集計）は、行ごとの日時の解析（数万行では数秒かかる）を省く
    $countSince = ($since -ne [datetime]::MaxValue)
    $sinceSecond = if ($countSince) { $since.AddTicks(-($since.Ticks % [timespan]::TicksPerSecond)) } else { $since }
    $failedRows = New-Object System.Collections.Generic.List[object]
    foreach ($row in $status.Rows.Values) {
        if (testStatusRowFailed $row) {
            $state.Failed++
            $failedRows.Add($row)
        } elseif ($row.状態 -eq ${stateNew}) {
            $state.Pending++
        } elseif ($row.状態 -eq ${stateDone}) {
            $state.Done++
        }

        $ingested = [datetime]::MinValue
        if ($countSince -and $row.取り込み日時 -and [datetime]::TryParseExact($row.取り込み日時, "yyyy/MM/dd HH:mm:ss", [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::None, [ref]$ingested) -and $ingested -ge $sinceSecond) {
            $state.IngestedSince++
        }
    }
    # 取り込み日時は "yyyy/MM/dd HH:mm:ss" のため、文字列の順で新しい順に並ぶ
    $state.FailedRows = @($failedRows | Sort-Object -Property @{ Expression = { [string]$_.取り込み日時 }; Descending = $true }, @{ Expression = { $_.相対パス } })
    return $state
}

# 取り込み一覧・取り込み中のファイルの読み書きと、今回の取り込みでの失敗・元ファイルが無くなった行の記録をまとめる（StatusLedger）。
# 列と状態の定義（core/paths.ps1 の ${statusColumns} など）は判断層（indexer_decide.ps1）・index_store.ps1 なども読むため、
# 今の場所（paths.ps1 の変数）のまま動かさない（docs/design/structure/classes.md）。
# 保存先（取り込み一覧・取り込み中のファイル）は、コンストラクタで受け取った $workspace（Workspace のインスタンス。
# 場所を暗黙に使わないため、メソッドの中で ${workspace} を読まない）の StatusFile・IngestingFile から決める
class StatusLedger {
    hidden $Workspace
    # 今回の取り込みで失敗したファイル（@{ RelPath; Message } の並び）
    [System.Collections.Generic.List[object]]$Failures
    # 取り込みの直前に元のファイルが無くなっていた相対パス（取り込み一覧から除く）
    [System.Collections.Generic.HashSet[string]]$DroppedRows

    StatusLedger($workspace) {
        $this.Workspace = $workspace
        $this.Failures = New-Object System.Collections.Generic.List[object]
        $this.DroppedRows = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    }

    [hashtable] ReadStatus() {
        # 取り込み一覧を読み込む（readStatusFile と同じ形。@{ Folders; Rows }）
        return readStatusFile $this.Workspace.StatusFile
    }

    [void] WriteStatus($folders, $rows) {
        # 取り込み一覧を書き出す（1ファイル1行）
        writeStatusFile $folders $rows $this.Workspace.StatusFile
    }

    [void] AddRow($row) {
        # 取り込み一覧の末尾に1行追記する
        addStatusRow $row $this.Workspace.StatusFile
    }

    [object[]] ReadIngestingFiles() {
        # 取り込み中のファイルの記録を読む（@{ RelPath; Count } の並び）
        return readIngestingFiles $this.Workspace.IngestingFile
    }

    [void] WriteIngestingFiles([object[]]$entries) {
        # 取り込み中のファイルの記録を書く（無ければ記録を消す）
        writeIngestingFiles $entries $this.Workspace.IngestingFile
    }

    [void] RemoveIngestingFile() {
        removeIngestingFile $this.Workspace.IngestingFile
    }

    [void] RenameIndexName([string]$oldName, [string]$newName) {
        # 取り込み一覧に記録したインデックス名を書き換える（クロール対象フォルダの行と、各行の相対パスの先頭）
        renameStatusIndexName $oldName $newName $this.Workspace.StatusFile
    }

    [void] RemoveIndexName([string]$name) {
        # 取り込み一覧から、あるインデックスの記録（クロール対象フォルダの行と、そのインデックスの各行）を取り除く
        removeStatusIndexName $name $this.Workspace.StatusFile
    }

    [void] AddFailure([string]$relPath, [string]$message) {
        # 今回の取り込みで失敗したファイルを記録する
        $this.Failures.Add(@{ RelPath = $relPath; Message = $message })
    }

    [void] AddDropped([string]$relPath) {
        # 取り込みの直前に元のファイルが無くなっていた（取り込み一覧・インデックスから除く）ファイルを記録する
        [void]$this.DroppedRows.Add($relPath)
    }
}

# インデックスの改名・削除・名前の割り当て・一覧と元のフォルダの記録の保存。
# インデックス 1 つの情報は複数の保存先に分かれて置かれている: 設定の targetFolders、取り込み一覧、インデックスのフォルダ（content_index\<名前>）と
# 元のフォルダの記録（source_folder.txt）、設定の searchExcludes、システムインデックス（system_index）。
# このクラスは、改名・削除でそれらを書き換える手順と順番、途中で失敗したときの扱い（止める・残す）だけを持つ。一覧（targetFolders）と元のフォルダの記録の書き直しは、画面が SaveTargets・WriteSourceFile（改名では RenameIndexWithSource）で呼ぶ。保存先の形式は知らず、
# 保存先ごとの読み書きは既存の関数（searchExcludes は core\search_excludes.ps1）と、作る側から渡された StatusLedger に任せる。
# 画面は呼んで結果を出すだけにする（画面の手順をここに引き寄せる）。
#
# クラスの本体では $script: 変数・ほかのクラスの型・呼び出し元の変数を使わない（docs/design/structure/classes.md）。
# 場所は、コンストラクタで受け取る workspace（Workspace のインスタンス）と設定ファイルの場所で決める。
# 取り込み一覧は ledger（StatusLedger のインスタンス。作る側が作って渡す）を通して書く。
# 別のスレッドへはインスタンスを渡さず、ワークスペースの場所（文字列）を渡して newIndexCatalog で作り直す。
# メソッドの中のローカル変数は、プロパティと大文字・小文字だけの違いにしない
class IndexCatalog {
    hidden $Workspace
    hidden [string]$SettingsPath
    hidden $Ledger

    IndexCatalog($workspace, [string]$settingsPath, $ledger) {
        $this.Workspace = $workspace
        $this.SettingsPath = $settingsPath
        $this.Ledger = $ledger
    }

    [void] AssertReachable() {
        # インデックスの削除・名前の変更の裏の仕事の先頭で呼ぶ。ワークスペースに届かないときは例外にする
        # （届かないのに「何もせず成功」にして、設定だけ変えてしまわないため）
        assertWorkspaceReachable $this.Workspace.IndexDir
    }

    [void] RenameIndex([string]$oldName, [string]$newName) {
        # インデックス名を変える（画面の詳細の名前の欄）。インデックスのフォルダ（content_index\<名前>）を改名し、
        # 取り込み一覧の記録も書き換えるため、名前を変えてもインデックスは作り直さない。
        # インデックス作成中は呼ばない（画面はインデックス作成中この操作を無効にする）。
        # フォルダの改名か取り込み一覧の書き換えに失敗したら例外にする（システムインデックスと searchExcludes の整理は、失敗しても止めない）
        $dir = $this.Workspace.IndexDir
        # 大文字・小文字だけの変更も改名するため、同じ名前かは大文字・小文字を区別して比べる（-ceq）
        if ($oldName -eq "" -or $newName -eq "" -or $oldName -ceq $newName) {
            return
        }

        $from = Join-Path $dir $oldName
        $to   = Join-Path $dir $newName
        if (Test-Path -LiteralPath $from -PathType Container) {
            if ([string]::Equals($oldName, $newName, [System.StringComparison]::OrdinalIgnoreCase)) {
                # 大文字・小文字だけを変える場合は、そのままでは改名できないため一時名を経由する
                $tmp = Join-Path $dir "${oldName}_rename_$([System.Diagnostics.Process]::GetCurrentProcess().Id)"
                [System.IO.Directory]::Move((toLongPath $from), (toLongPath $tmp))
                [System.IO.Directory]::Move((toLongPath $tmp), (toLongPath $to))
            } else {
                if (Test-Path -LiteralPath $to) {
                    throw "「${newName}」のフォルダが既にあるため、名前を変えられません: ${to}"
                }
                [System.IO.Directory]::Move((toLongPath $from), (toLongPath $to))
            }
        }
        $this.Ledger.RenameIndexName($oldName, $newName)
        # 高速検索の システムインデックス（同じワークスペースの system_index）は古い名前の分を消す。次のインデックス作成で作り直す
        removeSystemIndexOfWorkspace $oldName $dir
        # 外したフォルダの記録（searchExcludes）は旧名・新名の下のものを消す（付け替えず、検索対象に戻す）
        removeSearchExcludesUnder $from $this.SettingsPath
        removeSearchExcludesUnder $to $this.SettingsPath
    }

    [hashtable] RenameIndexWithSource([string]$oldName, [string]$newName, $folders) {
        # 名前を変え（RenameIndex）、続けて元のフォルダの記録（source_folder.txt）を書き直す。
        # 書き直しに失敗しても、改名は済んでいるので改名の失敗にはしない。書けなかった理由を SourceFolderError で返す（成功なら空）。
        # 改名の失敗は、RenameIndex の例外のまま呼び出し元へ出る
        $this.RenameIndex($oldName, $newName)
        $sourceError = ""
        try {
            $this.WriteSourceFile($folders)
        } catch {
            $sourceError = $_.Exception.Message
        }
        return @{ SourceFolderError = $sourceError }
    }

    [void] RemoveIndex([string]$name) {
        # インデックスを削除する（画面の［削除］）。インデックスのフォルダ（content_index\<名前>）と、取り込み一覧の記録を削除する。
        # インデックス作成中は呼ばない（画面はインデックス作成中この操作を無効にする）。
        # フォルダを消せなければ例外にして、取り込み一覧の記録は残す
        $dir = $this.Workspace.IndexDir
        if ($name -eq "") {
            return
        }
        $target = Join-Path $dir $name
        if (Test-Path -LiteralPath $target -PathType Container) {
            # 中に長いパス（260文字超）のTSVがあっても削除でき、中のリンク（ジャンクション・シンボリックリンク）の先は消さない
            # （removeDirectoryRetry）。消せなければ例外にして、取り込み一覧の記録を残す（フォルダが残ったまま記録だけ消えないように）
            removeDirectoryRetry $target
        }
        $this.Ledger.RemoveIndexName($name)
        removeSystemIndexOfWorkspace $name $dir
        # 外したフォルダの記録（searchExcludes）も消す
        removeSearchExcludesUnder $target $this.SettingsPath
    }

    [object[]] RemoveIndexes([string[]]$names) {
        # 選んだインデックスをまとめて削除する（画面の［削除］）。1 つずつ RemoveIndex を呼び、途中で 1 つ失敗しても残りを続ける。
        # 戻り値は名前ごとの結果の配列（@{ Name; Ok; Reason }）。Reason は失敗したときの理由（成功なら ""）。
        # 画面のスレッドでは呼ばず、別スレッドの仕事の中で呼ぶ
        $results = New-Object System.Collections.Generic.List[object]
        foreach ($name in @($names)) {
            if ([string]::IsNullOrEmpty($name)) {
                $results.Add([pscustomobject]@{ Name = [string]$name; Ok = $false; Reason = "インデックス名が空です" })
                continue
            }
            try {
                $this.RemoveIndex($name)
                $results.Add([pscustomobject]@{ Name = $name; Ok = $true; Reason = "" })
            } catch {
                $results.Add([pscustomobject]@{ Name = $name; Ok = $false; Reason = $_.Exception.Message })
            }
        }
        return $results.ToArray()
    }

    [object[]] AssignAndSaveNames($folders) {
        # 名前の決まっていないインデックス（設定ファイルを直接書き換えた場合など）に名前を割り当てて、設定に保存する。保存した一覧を返す。
        # 取り込み一覧の読み込みは排他の外で済ませ、設定の読み直しと書き込みだけを saveAssignedIndexNames が排他の中で行う
        $status = $this.Ledger.ReadStatus()
        $assigned = @(assignIndexNames $folders $status.Folders)
        return @(saveAssignedIndexNames $assigned $this.SettingsPath)
    }

    [object[]] StoreAssignedNames($assigned) {
        # 割り当てた名前（assignIndexNames の結果）を設定に保存し、保存した一覧（@{ Name; Path; Enabled }）を返す。
        # インデクサが、司令のスレッドで作ったこのクラスの経由で名前を保存する
        return @(saveAssignedIndexNames $assigned $this.SettingsPath)
    }

    [void] SaveTargets($folders) {
        # インデックスの一覧（@{ Name; Path; Enabled } の配列）を設定に書く
        writeTargetFolders $folders $this.SettingsPath
    }

    [void] WriteSourceFile($folders) {
        # インデックスのフォルダの source_folder.txt を、一覧（@{ Name; Path } の配列）に合わせて書き直す（インデックスが無いフォルダには書かない）
        writeSourceFolderFile $folders $this.Workspace.IndexDir
    }
}

function newIndexCatalog {
    # ワークスペースの場所（Dir。文字列）から IndexCatalog を作る。取り込み一覧を書く StatusLedger もここで作って渡す。
    # 画面のスレッドでも、別のスレッドの仕事の中でも使う（スレッドをまたいでインスタンスを渡さず、場所を渡して作り直すため）
    param (
        [string]$workspaceDir,
        [string]$settingsPath = ${settingsFile}
    )

    $target = [Workspace]::new($workspaceDir)
    return [IndexCatalog]::new($target, $settingsPath, [StatusLedger]::new($target))
}

# 1 ファイルを取り込み直すかどうかの判断（差分取り込みの要）。
# ファイルにも画面にも触らないため、そのままテストできる（tests\tebunko\indexer\indexer_decide.Tests.ps1）。

# 読み取る内容（抽出版）。読み取る場所を増やしたら、その形式の版を上げる。
# 前の版で取り込んだファイルは、更新が無くても取り込み直す（取り込み一覧の「抽出版」。空は 1）
#   2: Excel（.xlsx / .xlsm）の図形・コメントを読む。
#      Word・PowerPoint のコメント・SmartArt・グラフを読み、Word のテキストボックスを本文から図形に分ける
#      （Word・PowerPoint は旧形式も新形式に変換してから読むため、.doc / .ppt も上げる）
#   3: Excel のグラフ・SmartArt（表示のグラフシートを含む）を読む。
#      グラフの読み方を、タイトル・軸ラベル・系列名だけにし、項目名は読まないようにする
#      （.xlsx / .xlsm はグラフ・SmartArt を読むようになった分で 3。.docx / .docm / .pptx / .pptm は
#      項目名を読まなくなった分だけ上げる。.doc / .ppt はこのアイテムでは上げない）
#   4: Excel（.xlsx / .xlsm）のヘッダー・フッター（表示のワークシート・グラフシート）を読む。
#   4（.docx / .docm / .doc / .pptx / .pptm）: Word・PowerPoint に埋め込んだ Office のファイル（Word 文書・Excel ブック・
#      PowerPoint）の中の文字を、"ページNNN[埋め込みN]"・"スライドNNN[埋め込みN]" として読む
#      （.doc は Word が新形式に変換した後も埋め込みが残るため上げる。.ppt は変換後に埋め込みが残らないため上げない）。
${extractVersions} = @{
    ".xlsx" = 4; ".xlsm" = 4
    ".docx" = 4; ".docm" = 4; ".doc" = 4
    ".pptx" = 4; ".pptm" = 4; ".ppt" = 2
}

function getExtractVersion {
    # ファイルの形式（拡張子）の今の抽出版を返す
    param (
        [string]$path
    )

    $version = ${extractVersions}[[System.IO.Path]::GetExtension($path).ToLowerInvariant()]
    return $(if ($null -eq $version) { 1 } else { $version })
}

function testExtractOutdated {
    # 取り込み一覧の行が、今の抽出版より前の版で取り込んだものか
    param (
        $row
    )

    $version = 1
    if ($row.抽出版) {
        [void][int]::TryParse([string]$row.抽出版, [ref]$version)
    }
    return ($version -lt (getExtractVersion $row.相対パス))
}

function getIngestDecision {
    # 前回の取り込み一覧の行と、いまのファイルの更新日時・サイズから、取り込むかどうかと、その理由を返す。
    #   Ingest: 取り込むか / Reason: done（取り込み済み）・failed（前回失敗。再取り込みするかは呼び出し元が決める）・
    #            new（一覧に無い）・updated（更新された）・pending（前回未完了）・lost（インデックスが無い・壊れている）・
    #            outdated（前の抽出版で取り込んだ）
    param (
        $old,                 # 前回の取り込み一覧の行（無ければ $null）
        [string]$updated,     # いまのファイルの更新日時（formatFileTime）
        [string]$size,        # いまのファイルのサイズ（文字列）
        [bool]$indexComplete  # インデックス（TSV）がそろっているか（状態が「済」のときだけ意味がある）
    )

    # 前回と更新日時・サイズが同じで、前回「未取り込み」で終わっていなければ、同じファイルとみなす
    $sameFile = ($old -and $old.更新日時 -eq $updated -and $old.サイズ -eq $size -and $old.状態 -ne ${stateNew})
    # 取り込み済みでも、インデックス（TSV）が無くなっていれば取り込み直す。
    # 一覧だけを見ると「済」のままになり、検索しても出てこない状態が続くため
    $lostIndex = ($sameFile -and $old.状態 -eq ${stateDone} -and -not $indexComplete)

    if ($sameFile -and -not $lostIndex) {
        if ($old.状態 -eq ${stateFailed}) {
            return @{ Ingest = $false; Reason = "failed" }
        }
        if (testExtractOutdated $old) {
            return @{ Ingest = $true; Reason = "outdated" }
        }
        return @{ Ingest = $false; Reason = "done" }
    }
    if ($lostIndex) {
        return @{ Ingest = $true; Reason = "lost" }
    }
    if ($null -eq $old) {
        return @{ Ingest = $true; Reason = "new" }
    }
    if ($old.状態 -eq ${stateNew}) {
        return @{ Ingest = $true; Reason = "pending" }
    }
    return @{ Ingest = $true; Reason = "updated" }
}

# 利用者が使っている PowerPoint のために取り込めなかったファイルの理由（取り込み一覧の「エラー」列と、更新に失敗したファイルの一覧に出す。
# 状態は「未取り込み」のまま残すので、閉じてからの次の更新で、再取り込みを選ばなくても取り込む）
${postponedReasonRunning} = "PowerPoint が起動していたため取り込めませんでした。PowerPoint を閉じてから、もう一度更新してください。"
${postponedReasonInUse}   = "PowerPoint を使っている方がいたため取り込めませんでした。PowerPoint を保存して閉じてから、もう一度更新してください。"

# 取り込みのレーン（docs/design/indexing/parallel.md）。Office のレーンはアプリごとに 1 つのスレッドで、そのアプリを 1 つ持つ。
# 読み取りのレーンは Office を使わず、ZIP の中の XML を直接読む（複数のスレッド）
${laneExcel}      = "Excel"
${laneWord}       = "Word"
${lanePowerPoint} = "PowerPoint"
${laneReader}     = "Reader"

function getIngestLane {
    # 取り込むファイルのレーンを拡張子で決める。Excel はセルの表示値を読むため、すべて Excel のレーン。
    # Word・PowerPoint は、旧形式（.doc / .ppt）だけ Office のレーン、新形式は読み取りのレーン
    # （中身が旧形式・パスワード付きと分かったら、読み取りのスレッドが Office のレーンに回し直す。getOfficeLane）。
    # テキストの拡張子（.txt 等）と PDF（.pdf）は、どの分岐にも当たらないため既定の読み取りのレーンになる（Office を使わずに読むため）
    param (
        [string]$relPath
    )

    switch -Regex ([System.IO.Path]::GetExtension($relPath).ToLowerInvariant()) {
        "^\.xls"   { return ${laneExcel} }
        "^\.doc$"  { return ${laneWord} }
        "^\.ppt$"  { return ${lanePowerPoint} }
    }
    return ${laneReader}
}

function getOfficeLane {
    # 読み取りのスレッドが Office が要ると返したファイルの、回し先の Office のレーン
    param (
        [string]$relPath
    )

    if ([System.IO.Path]::GetExtension($relPath).ToLowerInvariant().StartsWith(".ppt")) {
        return ${lanePowerPoint}
    }
    return ${laneWord}
}
function splitCloudItems {
    # クラウドにだけあるファイルの一覧を、取り込むものと、ダウンロードせずに残すものに分ける。
    #   取り込む: 「ダウンロードして取り込む」が選ばれていて、取り込み対象のもの（Failed が $false）。
    #            前回失敗したもの（Failed が $true）は、「前回失敗したものも取り込み直す」も選ばれているときだけ
    #   items の各要素は createTargetList が返す Cloud の要素（Failed: 前回失敗したファイルか）
    param (
        $items,
        [bool]$retryFailed,
        [bool]$includeCloud
    )

    $included = New-Object System.Collections.Generic.List[object]
    $skipped = New-Object System.Collections.Generic.List[object]
    # List[object] を @() に渡すと PowerShell 5.1 で落ちることがあるため、そのまま回す
    foreach ($item in $items) {
        if ($includeCloud -and ((-not $item.Failed) -or $retryFailed)) {
            $included.Add($item)
        }
        else {
            $skipped.Add($item)
        }
    }
    return @{ Included = $included; Skipped = $skipped }
}

# 画面のインデックス作成 1 回分（IndexingSession）。インデクサの司令のスレッドを作り、indexer.ps1 を受け渡しの口（newIndexerChannel）付きで実行する。
# 設計は docs/design/structure/threads.md「スレッドの一覧」「画面とインデクサの受け渡し」、docs/design/structure/closing.md「閉じるときの順番」。
#
# IndexingSession は画面のスレッドだけから呼ぶ（PowerShell 5.1 のクラスのメソッドは、定義したランスペースで動くため）。
# 画面とインデクサのやり取りは、すべて受け渡しの口で行う（中止・確認の返事・進み具合・終了コード）

# インデクサの司令のスレッドで動かすスクリプト。インデックス作成の処理のため、スレッドの優先度を下げる。
# indexerLib の部品（Prelude）は IndexingSession のコンストラクタが、この本体の param ブロックの
# あとにつなぐ（joinWorkerScript）。invokeIndexerMain は indexer\indexer_main.ps1 の関数
${indexingSessionScript} = {
    param ($channel)
    [System.Threading.Thread]::CurrentThread.Priority = [System.Threading.ThreadPriority]::BelowNormal
    invokeIndexerMain -Channel $channel
}

class IndexingSession {
    # 受け渡しの口
    [hashtable]$Channel
    # 始めた時刻
    [datetime]$Started
    hidden [System.Management.Automation.Runspaces.Runspace]$Runspace
    hidden [powershell]$PowerShell
    hidden [System.IAsyncResult]$Handle

    IndexingSession([string]$script, [hashtable]$indexerLoad, [hashtable]$channel) {
        $this.Channel = $channel
        $this.Started = Get-Date
        # 司令のスレッドは COM に触らないため MTA（Office は取り込みのスレッド（STA）が扱う）
        $this.Runspace = [runspacefactory]::CreateRunspace($indexerLoad.State)
        $this.Runspace.ApartmentState = [System.Threading.ApartmentState]::MTA
        $this.Runspace.Open()
        $this.PowerShell = [powershell]::Create()
        $this.PowerShell.Runspace = $this.Runspace
        $joined = if ($indexerLoad.Prelude) { joinWorkerScript $indexerLoad.Prelude $script } else { $script }
        [void]$this.PowerShell.AddScript($joined).AddArgument($channel)
        $this.Handle = $this.PowerShell.BeginInvoke()
    }

    [bool] IsRunning() {
        return $null -ne $this.PowerShell -and !$this.Handle.IsCompleted
    }

    [void] Stop() {
        # 中止を求める（取り込み中のファイルが終わったところで止まる。確認を待っていれば取りやめる）
        $this.Channel.Stop = $true
        [void]$this.Channel.Answered.Set()
    }

    [bool] Wait([int]$milliseconds) {
        # 終わるのを待つ。終わっていれば $true
        if ($null -eq $this.PowerShell) {
            return $true
        }
        return $this.Handle.AsyncWaitHandle.WaitOne($milliseconds)
    }

    [int] GetExitCode() {
        # 終了コード（0 完了 / 1 エラー / 2 中止）。インデクサが終了コードを入れずに止まったとき（読み込めない等）は 1
        if ($null -ne $this.Channel.ExitCode) {
            return [int]$this.Channel.ExitCode
        }
        return 1
    }

    [string] GetError() {
        # 続けられないエラーの内容。インデクサが入れていなければ、スレッドが止まった理由
        if ($this.Channel.Error) {
            return [string]$this.Channel.Error
        }
        $this.Collect()
        return $this.Failure
    }

    [int] GetCloudSkipped() {
        # クラウドにだけあるため、ダウンロードせずに残した件数。無ければ 0
        if ($null -ne $this.Channel.CloudSkipped) {
            return [int]$this.Channel.CloudSkipped
        }
        return 0
    }

    hidden [string]$Failure = ""
    hidden [bool]$Ended = $false

    hidden [void] Collect() {
        # 終わったスレッドの結果を受け取り、止まった理由（例外・エラー）を Failure に残す（1 回だけ）
        if ($this.Ended -or $null -eq $this.PowerShell -or !$this.Handle.IsCompleted) {
            return
        }
        $this.Ended = $true
        try {
            [void]$this.PowerShell.EndInvoke($this.Handle)
            if ($this.PowerShell.Streams.Error.Count -gt 0) {
                $this.Failure = $this.PowerShell.Streams.Error[0].ToString()
            }
        } catch {
            $exception = $_.Exception
            while ($exception.InnerException) {
                $exception = $exception.InnerException
            }
            $this.Failure = $exception.Message
        }
    }

    [int] KillOffice() {
        # インデックス作成が起動して PID を記録した Office だけを止め、止めた数を返す（閉じるときに終わらない場合の最後の手段）
        $count = 0
        foreach ($id in @($this.Channel.OfficePids.Keys)) {
            try {
                $process = [System.Diagnostics.Process]::GetProcessById($id)
                # 終了済みで ID が別のプロセスに使われている場合に備え、記録したプロセス名と起動時刻が同じか確かめる
                $entry = $this.Channel.OfficePids[$id]
                if (isSameOfficeProcess $process $entry.ProcessName $entry.StartTicks) {
                    # 利用者が使っている（取り込み中に見える窓があった）PowerPoint は止めない
                    $mark = $null
                    if ($this.Channel.UserOfficePids.TryGetValue($id, [ref]$mark) -and $mark.StartTicks -eq $entry.StartTicks) {
                        continue
                    }
                    # 今、見える窓があるプロセスも止めない（アプリを問わない。取り込みのプロセスは窓を出さない）
                    if (testOfficeProcessHasWindow $process) {
                        continue
                    }
                    $process.Kill()
                    $count++
                }
            } catch {
            }
        }
        return $count
    }

    [void] Close() {
        # スレッドを片づける。終わっていなければ中止を求めて待つ（呼ぶ側が終わるのを待ってから呼ぶ）。何度呼んでもよい
        if ($null -eq $this.PowerShell) {
            return
        }
        if (!$this.Handle.IsCompleted) {
            $this.Stop()
            if (!$this.Wait(5000)) {
                try {
                    $this.PowerShell.Stop()
                } catch {
                }
            }
        }
        $this.Collect()
        $this.PowerShell.Dispose()
        $this.PowerShell = $null
        $this.Runspace.Dispose()
        $this.Runspace = $null
    }
}

function newIndexingSession {
    # インデックス作成を始める（画面の［すべて更新］）。終わったら Close を呼ぶ
    param (
        [hashtable]$channel
    )

    $indexerLoad = getPartLoad indexerLib
    return [IndexingSession]::new(${indexingSessionScript}.ToString(), $indexerLoad, $channel)
}

# 検索の条件（正規表現・対象ファイル）の組み立て（判断層。ファイルに触らない）。

function isValidRegex {
    # 正規表現として正しいか
    param (
        [string]$pattern
    )

    try {
        [void][regex]::new($pattern)
        return $true
    } catch {
        return $false
    }
}


# 1行の照合にかけてよい時間。正規表現によっては終わらなくなるため、超えたら検索を止める
${regexTimeout} = [timespan]::FromSeconds(5)

function getRegexScanMode {
    # 正規表現を TSV の全文（改行は LF にそろえ、^ $ は行の先頭・末尾に一致させる）にかけてよいかを返す。
    # 1 行ずつ PowerShell で照合すると遅いため、全文への照合（.NET の中で走る）で済ませられる場合を見分ける。
    #   "lines" : 一致は必ず 1 行の中に収まり、行の外の文字を見ない。全文での一致の位置から、ヒットした行が分かる
    #   "filter": 行をまたいで一致することはあるが、1 行で一致するなら全文でも必ず一致する。
    #             全文で一致しない TSV は読み飛ばせる（一致した TSV は 1 行ずつ照合し直す）
    #   "scan"  : 全文では 1 行と結果が変わりうる（\A \z、否定の先読み・後読み、(?i) 等）。1 行ずつ照合する
    # 判定は安全側に倒す（分からない書き方は "filter" か "scan"）。検索結果は照合のしかたによらず同じになる
    param (
        [string]$pattern
    )

    $lines = $true
    $inClass = $false
    $classStart = 0
    $length = $pattern.Length
    for ($i = 0; $i -lt $length; $i++) {
        $c = $pattern[$i]
        if ($c -eq '\') {
            $i++
            if ($i -ge $length) {
                return "scan"
            }
            $e = $pattern[$i]
            if ("AzZG".IndexOf($e) -ge 0) {
                return "scan"   # 文字列の先頭・末尾は、1 行と全文とで位置が違う
            }
            if ("sWDpPnrxuc0123456789".IndexOf($e) -ge 0) {
                $lines = $false  # 改行にも一致しうる（\s \W \D \p{..} \n \x0A \u000A \cJ 8 進数・後方参照）
            }
            if ($inClass -and $i + 1 -lt $length -and $pattern[$i + 1] -eq '-') {
                $lines = $false  # エスケープから始まる範囲（[\t-z] 等）は改行を含みうる
            }
            continue
        }
        if ([int]$c -lt 0x20) {
            $lines = $false      # 制御文字をそのまま含む（改行・タブから始まる範囲など）
        }
        if ($inClass) {
            if ($c -eq ']' -and $i -gt $classStart) {
                $inClass = $false
            }
            continue
        }
        if ($c -eq '[') {
            $inClass = $true
            if ($i + 1 -lt $length -and $pattern[$i + 1] -eq '^') {
                $lines = $false  # 否定の文字クラスは改行に一致する
                $i++
            }
            $classStart = $i + 1  # 先頭の ] は文字として扱われる
            continue
        }
        if ($c -eq '(' -and $i + 1 -lt $length -and $pattern[$i + 1] -eq '?') {
            $rest = $pattern.Substring($i + 2)
            if ($rest.StartsWith(":") -or $rest.StartsWith(">")) {
                continue
            }
            if ($rest.StartsWith("=") -or $rest.StartsWith("<=")) {
                $lines = $false  # 肯定の先読み・後読みは行の外（改行）を見る。全文で一致が増えるだけなので "filter" にはできる
                continue
            }
            if ($rest -match "^(<[A-Za-z_]|'[A-Za-z_])") {
                continue         # 名前付きグループ
            }
            return "scan"        # 否定の先読み・後読み、(?i) 等のオプション、条件分岐、コメント
        }
    }
    if ($lines) {
        return "lines"
    }
    return "filter"
}


function newSearchRegex {
    # 検索条件から、検索と一致箇所の強調で使う正規表現を作る（画面の検索と結果の表示で共通）。
    #   simpleMatch  : $true ならワードを文字どおりに探す。$false なら正規表現として探し、正規表現として不正なら文字どおりに探す
    #   caseSensitive: 英字の大文字・小文字を区別する（既定は区別しない）
    # @{ Regex; SimpleMatch（実際に文字どおり探すか）; TextRegex; ScanMode } を返す。
    #   TextRegex: TSV の全文にかける正規表現（Regex に Multiline を足したもの。^ $ が行の先頭・末尾に一致する）
    #   ScanMode : TextRegex を全文にかけてよいか（getRegexScanMode）
    param (
        [string]$word,
        [bool]$simpleMatch = $true,
        [bool]$caseSensitive = $false
    )

    if (!$simpleMatch -and !(isValidRegex $word)) {
        $simpleMatch = $true
    }
    $pattern = if ($simpleMatch) { [regex]::Escape($word) } else { $word }
    # CultureInvariant: 大文字・小文字を区別しないときの照合が、区別する場合と同程度に速くなる（日本語の照合結果は変わらない）
    $options = [System.Text.RegularExpressions.RegexOptions]::CultureInvariant
    if (!$caseSensitive) {
        $options = $options -bor [System.Text.RegularExpressions.RegexOptions]::IgnoreCase
    }
    $textOptions = $options -bor [System.Text.RegularExpressions.RegexOptions]::Multiline
    return @{
        Regex       = New-Object System.Text.RegularExpressions.Regex($pattern, $options, ${regexTimeout})
        SimpleMatch = $simpleMatch
        TextRegex   = New-Object System.Text.RegularExpressions.Regex($pattern, $textOptions, ${regexTimeout})
        ScanMode    = getRegexScanMode $pattern
    }
}

function newPlaceExclude {
    # 検索から外す場所（図形・コメント）の正規表現を返す。どちらも検索するなら $null。
    # 場所の名前は "<元の場所>[<種類>]"（index_name.ps1 の objectPlacePattern）。Excel・Word・PowerPoint で共通
    param (
        [bool]$includeShapes = $true,
        [bool]$includeComments = $true
    )

    $kinds = @()
    # 埋め込み（"[埋め込み<N>]"）は図形と一緒に切り替える（検索の選択肢を増やさない）
    if (!$includeShapes) { $kinds += ${placeKindShape}; $kinds += ${placeKindEmbed} }
    if (!$includeComments) { $kinds += ${placeKindComment} }
    if ($kinds.Count -eq 0) {
        return $null
    }
    return [regex]::new((newObjectPlaceKindPattern -kinds $kinds))
}

# テキストのヒットの行・プレビューの前後の行を切る長さ（文字）と、一致の位置から遡る長さ（文字）。
# 1 行が数 MB になりうる .json・.xml・.log の描画で画面が固まらないよう、取り込みでは切らず、表示・出力の直前だけ切る
${hitLineMaxChars} = 1000
${hitLineBeforeMatchChars} = 200

function truncateHitLine {
    # 長い行（テキストのヒットの行・前後の行）を、一致の位置を中心に hitLineMaxChars 文字に切る。
    # 一致の位置（matchIndex。行の中の位置。分からなければ -1）の hitLineBeforeMatchChars 文字前から hitLineMaxChars 文字を取り、
    # 省いた側に "…" を付ける。hitLineMaxChars 以下ならそのまま返す
    param (
        [string]$line,
        [int]$matchIndex = -1
    )

    if ($line.Length -le ${hitLineMaxChars}) {
        return $line
    }
    $start = if ($matchIndex -lt 0) { 0 } else { [Math]::Max(0, $matchIndex - ${hitLineBeforeMatchChars}) }
    $end = [Math]::Min($line.Length, $start + ${hitLineMaxChars})
    $result = $line.Substring($start, $end - $start)
    if ($start -gt 0) { $result = "…" + $result }
    if ($end -lt $line.Length) { $result = $result + "…" }
    return $result
}

function getFileKindExtensions {
    # 検索バーのチップの種類（excel・word・powerpoint・text・pdf）ごとの拡張子（小文字）を返す。知らない種類は空
    param (
        [string]$kind
    )

    switch ($kind) {
        "excel" { return @(${officeExtensions} | Where-Object { $_ -like ".xl*" }) }
        "word" { return @(${officeExtensions} | Where-Object { $_ -like ".do*" }) }
        "powerpoint" { return @(${officeExtensions} | Where-Object { $_ -like ".pp*" }) }
        "text" { return @(${textExtensions}) }
        "pdf" { return @(${pdfExtensions}) }
    }
    return @()
}

function newFileKindFilter {
    # 選んだ種類（readFileKinds の値）から、対象ファイルの条件（newFileFilter に渡す文字列。"*.xlsx;*.xls" の形）を作る。
    # すべての種類を選んでいる・空・知らない種類だけのときは空（絞り込まない）
    param (
        [object[]]$kinds
    )

    $chosen = @(${fileKindNames} | Where-Object { @($kinds) -contains $_ })
    if ($chosen.Count -eq 0 -or $chosen.Count -eq ${fileKindNames}.Count) {
        return ""
    }
    return (@($chosen | ForEach-Object { getFileKindExtensions $_ } | ForEach-Object { "*$_" }) -join ";")
}

function newFileFilter {
    # 対象ファイルの指定（例: "*.xlsx;見積*;!*old*"）を、元のファイル名に対する正規表現 @{ Include; Exclude } にする（無い側は $null）。
    #   ; で区切る（全角の ； も可）。! で始まるものは除外。* は任意の文字列、? は任意の1文字。大文字・小文字を区別しない
    #   * も ? も無いものは部分一致（「見積」は「*見積*」）
    param (
        [string]$filter
    )

    $include = New-Object System.Collections.Generic.List[string]
    $exclude = New-Object System.Collections.Generic.List[string]
    foreach ($item in ([string]$filter).Split([char[]]";；")) {
        $item = $item.Trim()
        $list = $include
        if ($item.StartsWith("!") -or $item.StartsWith("！")) {
            $list = $exclude
            $item = $item.Substring(1).Trim()
        }
        if ($item -eq "") {
            continue
        }
        if ($item.IndexOfAny([char[]]"*?") -lt 0) {
            $item = "*${item}*"
        }
        $list.Add("^" + [regex]::Escape($item).Replace("\*", ".*").Replace("\?", ".") + "$")
    }

    $options = [System.Text.RegularExpressions.RegexOptions]::IgnoreCase -bor [System.Text.RegularExpressions.RegexOptions]::CultureInvariant
    $result = @{ Include = $null; Exclude = $null }
    if ($include.Count -gt 0) {
        $result.Include = New-Object System.Text.RegularExpressions.Regex(($include -join "|"), $options)
    }
    if ($exclude.Count -gt 0) {
        $result.Exclude = New-Object System.Text.RegularExpressions.Regex(($exclude -join "|"), $options)
    }
    return $result
}

# 高速検索（Windows Search で検索語を含みうるフォルダを先に絞る）の決まり（判断層。ファイルにも画面にも触らない）。
# システムインデックス（system_index の txt）は、文字の 2-gram を英数字の語にしたものを空白区切りで書く。
# Windows Search は語単位でしか一致を取らないため、本文をそのまま索引させると語の途中からの一致を落とすが、
# 2-gram の語なら、ワードを含む本文の txt には、ワードのすべての 2-gram が必ず入っている。

# システムインデックスの名前（置き場所は paths.ps1 の $workspace.SystemIndexDir）
${systemIndexFileName}      = "system_index.txt"
${systemIndexFileLike}      = "system[_]index%"      # 問い合わせの LIKE（分けたものも含む）。LIKE の _ は任意の1文字のため [_] と書く
${systemIndexSplitLike}     = "system[_]index[_]%"   # 分けたもの（system_index_1.txt …）だけ

# 1 つの txt の大きさの上限（これを超えたら語の範囲で分ける。実測では 16MB までは末尾まで索引された）
${systemIndexPartBytes} = 8MB
# txt のパスの長さの上限（これ以上は作らず、そのフォルダは .NET で照合する。Windows Search が長いパスを索引しないおそれがあるため）
${systemIndexPathMax} = 240
# 1 回の問い合わせに使う語の数の上限（多いときは均等に間引く。間引いても候補が増えるだけで漏れない）
${searchGramMax} = 16

# 状態ファイルの行の種別
${systemIndexCovered}  = "対応済み"   # インデックスのすべてのフォルダに txt がある（または対象外として記録した）
${systemIndexPending}  = "反映待ち"   # txt を書いた（値は txt の更新日時。UTC の Ticks）
${systemIndexExcluded} = "対象外"     # txt を作らなかったフォルダ（常に .NET で照合する）

function convertToGramToken {
    # 2 文字（小文字にしたもの）を語にする: x ＋ UTF-16LE の 4 バイトの 16 進（例: "ニタ" → xcb30bf30）
    param (
        [string]$pair
    )

    return "x" + [System.BitConverter]::ToString([System.Text.Encoding]::Unicode.GetBytes($pair)).Replace("-", "").ToLowerInvariant()
}

function getSearchGrams {
    # 検索語から、問い合わせに使う語を返す（重複なし・最大 searchGramMax 個）。
    # 空白で区切り、2 文字以上の部分の隣り合う 2 文字を語にする。語が無ければ空（高速検索は使えない）
    param (
        [string]$word
    )

    $grams = New-Object System.Collections.Generic.List[string]
    $seen = New-Object System.Collections.Generic.HashSet[string]
    foreach ($part in ([string]$word).ToLowerInvariant() -split "[\s\u2028]+") {
        for ($i = 0; $i -lt $part.Length - 1; $i++) {
            $token = convertToGramToken $part.Substring($i, 2)
            if ($seen.Add($token)) {
                $grams.Add($token)
            }
        }
    }
    if ($grams.Count -le ${searchGramMax}) {
        return , $grams.ToArray()
    }
    # 均等に間引く（先頭と末尾は残す）
    $picked = New-Object System.Collections.Generic.List[string]
    for ($k = 0; $k -lt ${searchGramMax}; $k++) {
        $picked.Add($grams[[int][Math]::Round($k * ($grams.Count - 1) / (${searchGramMax} - 1))])
    }
    return , $picked.ToArray()
}

function testFastSearchUsable {
    # 高速検索を使えるか（画面の「使用可 / 使用不可」）。
    #   available: Windows Search を開けて、system_index が索引の対象（windows_search.ps1 の testWindowsSearch）
    param (
        [bool]$available,
        [bool]$useRegex,
        [string]$word
    )

    return ($available -and !$useRegex -and (getSearchGrams $word).Count -gt 0)
}

function addTextGrams {
    # 本文の 2-gram を、語の値（uint32。UTF-16LE の 2 文字をそのまま 4 バイトの整数にしたもの）として set に足す。
    # 1 文字ずつ PowerShell で回すと遅いため、char[] を uint32[] に写して .NET の HashSet で重複を除く。
    # 空白を含む 2-gram も入るが、問い合わせには使わないため害は無い（除く方が遅い）
    param (
        [System.Collections.Generic.HashSet[uint32]]$set,
        [string]$text
    )

    $chars = $text.ToLowerInvariant().ToCharArray()
    $even = $chars.Length -shr 1
    $odd = ($chars.Length - 1) -shr 1
    if ($even -gt 0) {
        $u0 = New-Object 'uint32[]' $even
        [System.Buffer]::BlockCopy($chars, 0, $u0, 0, $even * 4)
        $set.UnionWith($u0)
    }
    if ($odd -gt 0) {
        # 1 文字ずらした並びは、2 バイトずらして写せば作れる
        $u1 = New-Object 'uint32[]' $odd
        [System.Buffer]::BlockCopy($chars, 2, $u1, 0, $odd * 4)
        $set.UnionWith($u1)
    }
}

function convertToGramText {
    # 語の値（昇順に並べたもの）の start から count 個を、txt に書く文字列にする（x ＋ 16 進 8 桁を空白区切り）
    param (
        [uint32[]]$values,
        [int]$start = 0,
        [int]$count = -1
    )

    if ($count -lt 0) {
        $count = $values.Length - $start
    }
    if ($count -le 0) {
        return ""
    }
    $bytes = New-Object 'byte[]' ($count * 4)
    [System.Buffer]::BlockCopy($values, $start * 4, $bytes, 0, $count * 4)
    $hex = [System.BitConverter]::ToString($bytes).Replace("-", "").ToLowerInvariant()
    return [regex]::Replace($hex, "(.{8})", 'x$1 ')
}

function getGramPartCount {
    # 語の数から、txt をいくつに分けるかを返す（1 語は "x" ＋ 8 桁 ＋ 空白の 10 バイト）
    param (
        [int]$count,
        [long]$partBytes = ${systemIndexPartBytes}
    )

    $perPart = [Math]::Max(1, [int][Math]::Floor($partBytes / 10))
    return [Math]::Max(1, [int][Math]::Ceiling($count / $perPart))
}

function getSystemIndexFileNames {
    # txt の名前（分けないときは 1 つ。分けるときは system_index_1.txt …）
    param (
        [int]$parts
    )

    if ($parts -le 1) {
        return , @(${systemIndexFileName})
    }
    $base = [System.IO.Path]::GetFileNameWithoutExtension(${systemIndexFileName})
    return , @(1..$parts | ForEach-Object { "${base}_$_.txt" })
}

function testSystemIndexPath {
    # txt のパスが長すぎないか（分けたときは最も長い名前で判定する）
    param (
        [string]$folder,
        [int]$parts = 1
    )

    $longest = @(getSystemIndexFileNames $parts | Sort-Object Length -Descending)[0]
    return ("$folder\$longest").Length -lt ${systemIndexPathMax}
}

function convertFolderRoot {
    # フォルダのパスの先頭（fromRoot）を toRoot に置き換える（system_index と index は同じ相対パスの構成）。
    # fromRoot の外のパスは $null
    param (
        [string]$path,
        [string]$fromRoot,
        [string]$toRoot
    )

    $from = $fromRoot.TrimEnd("\")
    if ($path.Equals($from, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $toRoot.TrimEnd("\")
    }
    if ($path.StartsWith("$from\", [System.StringComparison]::OrdinalIgnoreCase)) {
        return $toRoot.TrimEnd("\") + $path.Substring($from.Length)
    }
    return $null
}

function getRelativePath {
    # root からの相対パス（root の外・root そのものは $null）
    param (
        [string]$path,
        [string]$root
    )

    $base = $root.TrimEnd("\")
    if ($path.StartsWith("$base\", [System.StringComparison]::OrdinalIgnoreCase) -and $path.Length -gt $base.Length + 1) {
        return $path.Substring($base.Length + 1)
    }
    return $null
}

function convertItemUrl {
    # Windows Search の System.ItemUrl（file:C:/…）をパスにする。% は符号化されていないため URL として戻さない
    param (
        [string]$url
    )

    return $url.Substring($url.IndexOf(":") + 1).Replace("/", "\")
}

function convertToScopeUrl {
    # SCOPE に書く URL（file:C:/…）。SQL の文字列に入れるため ' は重ねる
    param (
        [string]$path
    )

    return ("file:" + $path.TrimEnd("\").Replace("\", "/")).Replace("'", "''")
}

function newSystemIndexQuery {
    # 候補の txt（分けていないもの）を探す問い合わせ
    param (
        [string]$scopeDir,
        [string[]]$grams
    )

    $condition = ($grams | ForEach-Object { "`"$_`"" }) -join " AND "
    return "SELECT System.ItemUrl FROM SystemIndex WHERE SCOPE='$(convertToScopeUrl $scopeDir)' AND System.FileName = '${systemIndexFileName}' AND CONTAINS(System.Search.Contents, '$condition')"
}

function newSystemIndexSplitQuery {
    # 分けた txt から、語を 1 つ含むものを探す問い合わせ（分けた txt は AND で 1 回に問えないため語ごとに問う）
    param (
        [string]$scopeDir,
        [string]$gram
    )

    return "SELECT System.ItemUrl FROM SystemIndex WHERE SCOPE='$(convertToScopeUrl $scopeDir)' AND System.FileName LIKE '${systemIndexSplitLike}' AND CONTAINS(System.Search.Contents, '`"$gram`"')"
}

function newSystemIndexStateQuery {
    # 反映の判定に使う値（GatherTime・DateModified）を取る問い合わせ
    param (
        [string]$scopeDir
    )

    return "SELECT System.ItemUrl, System.Search.GatherTime, System.DateModified FROM SystemIndex WHERE SCOPE='$(convertToScopeUrl $scopeDir)' AND System.FileName LIKE '${systemIndexFileLike}'"
}

function testSystemIndexReflected {
    # txt が Windows Search に反映済みか: 本文を読み終えた（GatherTime がある）かつ、今の版を索引した
    # （DateModified が txt の更新日時を秒で切り捨てた値と同じ。Windows Search は秒未満を切り捨てて持つ）
    param (
        $gatherTime,
        $dateModified,
        [long]$fileTicksUtc
    )

    if ($null -eq $gatherTime -or $gatherTime -is [System.DBNull] -or $null -eq $dateModified -or $dateModified -is [System.DBNull]) {
        return $false
    }
    return ([datetime]$dateModified).Ticks -eq ($fileTicksUtc - ($fileTicksUtc % [timespan]::TicksPerSecond))
}

function testFolderInTarget {
    # フォルダ（TSV のフォルダ）が検索対象に入るか。recurse が $false なら対象フォルダそのものだけ
    param (
        [string]$folder,
        [string]$targetDir,
        [bool]$recurse
    )

    $target = $targetDir.TrimEnd("\")
    if ($folder.Equals($target, [System.StringComparison]::OrdinalIgnoreCase)) {
        return $true
    }
    return ($recurse -and $folder.StartsWith("$target\", [System.StringComparison]::OrdinalIgnoreCase))
}

function convertFromSystemIndexState {
    # 状態ファイルの行を読む（パスは system_index からの相対パス）。形の違う行は無視する。
    #   Covered : 対応済みのインデックス名 / Pending: txt の相対パス → 書いた日時（Ticks）/ Excluded: 対象外のフォルダの相対パス
    param (
        [string[]]$lines
    )

    $state = newSystemIndexState
    foreach ($line in $lines) {
        $cells = ([string]$line).Split("`t")
        if ($cells.Count -lt 2 -or $cells[1] -eq "") {
            continue
        }
        switch ($cells[0]) {
            ${systemIndexCovered} { [void]$state.Covered.Add($cells[1]) }
            ${systemIndexExcluded} { [void]$state.Excluded.Add($cells[1]) }
            ${systemIndexPending} {
                $ticks = 0L
                if ($cells.Count -ge 3 -and [long]::TryParse($cells[2], [ref]$ticks)) {
                    $state.Pending[$cells[1]] = $ticks
                }
            }
        }
    }
    return $state
}

function newSystemIndexState {
    # 空の状態
    return @{
        Covered  = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
        Pending  = New-Object 'System.Collections.Generic.Dictionary[string,long]' ([System.StringComparer]::OrdinalIgnoreCase)
        Excluded = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    }
}

function convertToSystemIndexState {
    # 状態を状態ファイルの行にする（対応済み・対象外・反映待ちの順。それぞれ名前順）
    param (
        $state
    )

    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($name in ($state.Covered | Sort-Object)) {
        $lines.Add("${systemIndexCovered}`t$name`t")
    }
    foreach ($rel in ($state.Excluded | Sort-Object)) {
        $lines.Add("${systemIndexExcluded}`t$rel`t")
    }
    foreach ($rel in ($state.Pending.Keys | Sort-Object)) {
        $lines.Add("${systemIndexPending}`t$rel`t$($state.Pending[$rel])")
    }
    return , $lines.ToArray()
}

function getIndexNameOfRelPath {
    # system_index（index）からの相対パスの先頭（インデックス名）
    param (
        [string]$relPath
    )

    return ([string]$relPath).Split("\")[0]
}

# Windows Search への問い合わせ（OLE DB の Search.CollatorDSO）。読み取り（SELECT）だけを送る。
# 管理者権限は要らない。Windows Search のサービスが止まっている・ポリシーで無効なときは開けない（高速検索を使わない）。

function openWindowsSearch {
    # Windows Search への接続を開く。開けなければ $null
    try {
        $connection = New-Object System.Data.OleDb.OleDbConnection "Provider=Search.CollatorDSO;Extended Properties='Application=Windows';"
        $connection.Open()
        return $connection
    } catch {
        return $null
    }
}

function invokeWindowsSearch {
    # 問い合わせを実行し、行（object[]）の一覧を返す。SELECT 以外は送らない
    param (
        $connection,
        [string]$sql,
        [int]$timeoutSeconds = 10
    )

    if ($sql -notmatch "^\s*SELECT\s") {
        throw "Windows Search へは SELECT だけを送る: $sql"
    }
    $command = $connection.CreateCommand()
    $command.CommandText = $sql
    $command.CommandTimeout = $timeoutSeconds
    $rows = New-Object 'System.Collections.Generic.List[object[]]'
    $reader = $command.ExecuteReader()
    try {
        while ($reader.Read()) {
            $values = New-Object object[] $reader.FieldCount
            [void]$reader.GetValues($values)
            $rows.Add($values)
        }
    } finally {
        $reader.Dispose()
        $command.Dispose()
    }
    return , $rows
}

function getWindowsSearchState {
    # 高速検索に使えるかと、使えない理由。次のどれかの文字列を返す（画面の文言は ui/index/index_list_view.ps1 の getFastSearchRowView）。
    #   NoFolder     : system_index のフォルダが無い（インデックスを作っていない・ワークスペースが違う）
    #   NoConnection : Windows Search を開けない、または問い合わせに失敗した（時間切れを含む）
    #   NotInScope   : system_index が 0 件で、ワークスペースの中も 1 件も索引されていない（索引の対象外とみなす）
    #   NotYet       : system_index が 0 件だが、ワークスペースの中のほかのものは索引されている（対象だが、まだ索引されていないとみなす）
    #   Ok           : system_index が 1 件以上索引されている（フォルダ自体が SystemIndex に入っている）
    # 管理者権限なしに索引の対象の一覧を読む方法が無いため、NotInScope と NotYet はワークスペースの中の様子で見分ける。
    #   workspaceDir: 空なら、systemRoot の 1 つ上（ワークスペース）
    #   connection  : 開いた接続。$null なら自分で開いて閉じる（渡したら呼び出し側が閉じる）
    param (
        [string]$systemRoot = $workspace.SystemIndexDir,
        [string]$workspaceDir = "",
        $connection = $null
    )

    if (![System.IO.Directory]::Exists((toLongPath $systemRoot))) {
        return "NoFolder"
    }
    if (!$workspaceDir) {
        $workspaceDir = [System.IO.Path]::GetDirectoryName($systemRoot.TrimEnd("\"))
    }
    $own = $null -eq $connection
    if ($own) {
        $connection = openWindowsSearch
        if ($null -eq $connection) {
            return "NoConnection"
        }
    }
    try {
        $rows = invokeWindowsSearch $connection "SELECT TOP 1 System.ItemUrl FROM SystemIndex WHERE SCOPE='$(convertToScopeUrl $systemRoot)'"
        if ($rows.Count -gt 0) {
            return "Ok"
        }
        $rows = invokeWindowsSearch $connection "SELECT TOP 1 System.ItemUrl FROM SystemIndex WHERE SCOPE='$(convertToScopeUrl $workspaceDir)'"
        return $(if ($rows.Count -gt 0) { "NotYet" } else { "NotInScope" })
    } catch {
        return "NoConnection"
    } finally {
        if ($own) {
            $connection.Dispose()
        }
    }
}

function testWindowsSearch {
    # 高速検索に使えるか: Windows Search を開けて、system_index が索引の対象か（getWindowsSearchState が Ok）
    param (
        [string]$systemRoot = $workspace.SystemIndexDir
    )

    return (getWindowsSearchState $systemRoot) -eq "Ok"
}

function testTsvIndexedByWindowsSearch {
    # 本文インデックス（index の TSV）が Windows Search に索引されているか（利用者が対象から外していないか）。
    # 外していなくても結果は正しいが、txt の索引が遅くなるため、画面で案内を出すのに使う
    #   connection: 開いた接続。$null なら自分で開いて閉じる（渡したら呼び出し側が閉じる）
    param (
        [string]$indexRoot = $workspace.IndexDir,
        $connection = $null
    )

    $own = $null -eq $connection
    if ($own) {
        $connection = openWindowsSearch
        if ($null -eq $connection) {
            return $false
        }
    }
    try {
        $rows = invokeWindowsSearch $connection "SELECT TOP 1 System.ItemUrl FROM SystemIndex WHERE SCOPE='$(convertToScopeUrl $indexRoot)' AND System.FileExtension = '.tsv'"
        return $rows.Count -gt 0
    } catch {
        return $false
    } finally {
        if ($own) {
            $connection.Dispose()
        }
    }
}

# 高速検索: Windows Search で検索語を含みうるフォルダを先に絞り、照合する本文インデックスのファイルを集める（状態層）。
# 集めた本文インデックスのファイルは、今までどおり searchContentIndex で照合する。結果（行・行番号・順番）は、すべてを照合したときと同じになる:
#   反映済みの システムインデックスには、そのフォルダの本文インデックスのファイルのすべての 2-gram が入っていて、検索語の語はその一部のため、
#   当たる本文インデックスのファイルのフォルダは必ず候補に入る。反映済みでない・対象外・対応済みでないものは、候補に関係なく照合する。

function getReflectedSystemIndexEntries {
    # 状態ファイルの反映待ちの行を、Windows Search の索引と照らして、反映済みになったものとまだのものに分ける。
    # @{ Reflected（反映済みになった行の相対パス）; Unreflected（まだ反映されていない行があるフォルダの相対パス） } を返す。
    # 反映待ちが無ければ、Windows Search には問い合わせない。問い合わせに失敗したら例外のまま投げる
    #   ask: { param($sql) 行（object[]）の一覧 }（呼び出し元の $query・$connection を見る。& で呼ぶと呼び出し元の変数が見える）
    param (
        $state,
        [string]$systemRootPath,
        [scriptblock]$ask
    )

    $reflected = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    $unreflected = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
    if ($state.Pending.Count -gt 0) {
        foreach ($row in (& $ask (newSystemIndexStateQuery $systemRootPath))) {
            $rel = getRelativePath (convertItemUrl ([string]$row[0])) $systemRootPath
            if ($rel -and $state.Pending.ContainsKey($rel) -and (testSystemIndexReflected $row[1] $row[2] $state.Pending[$rel])) {
                [void]$reflected.Add($rel)
            }
        }
        foreach ($rel in $state.Pending.Keys) {
            if (!$reflected.Contains($rel)) {
                [void]$unreflected.Add([System.IO.Path]::GetDirectoryName($rel))
            }
        }
    }
    return @{ Reflected = $reflected; Unreflected = $unreflected }
}

function getFastSearchContentIndexFiles {
    # 高速検索で照合する本文インデックスのファイルを、getContentIndexFiles と同じ形（@{ Folders; ContentIndexFiles }）に Fast（@{ Candidates; Unreflected }）を足して返す。
    # 高速検索を使えないとき（検索語から語を作れない・状態ファイルを読めない・Windows Search に問い合わせられない）は $null
    # （呼び出し側が getContentIndexFiles ですべての本文インデックスのファイルを集める）。
    #   folders: getContentIndexFiles と同じ（文字列、または @{ Root; RelPath; Recurse }）
    #   query  : { param($sql) 行（object[]）の一覧 }。$null なら Windows Search を開いて問い合わせる（テストで差し替える）
    param (
        [string]$word,
        [object[]]$folders,
        [scriptblock]$query = $null,
        [string]$indexRoot = $workspace.IndexDir,
        [string]$systemRoot = $workspace.SystemIndexDir,
        [string]$statePath = $workspace.SystemIndexStateFile,
        [scriptblock]$onProgress = $null
    )

    $grams = getSearchGrams $word
    if ($grams.Count -eq 0) {
        return $null
    }
    $state = readSystemIndexState $statePath
    if ($null -eq $state) {
        return $null
    }
    $connection = $null
    if ($null -eq $query) {
        $connection = openWindowsSearch
        if ($null -eq $connection) {
            return $null
        }
    }
    # 問い合わせ（差し替えが無ければ開いた接続で）。& で呼ぶと、この関数の $query・$connection が見える
    $ask = {
        param ($sql)
        if ($query) { & $query $sql } else { invokeWindowsSearch $connection $sql }
    }

    $indexRootPath = $indexRoot.TrimEnd("\")
    $systemRootPath = $systemRoot.TrimEnd("\")
    $targets = New-Object System.Collections.Generic.List[object]
    $candidates = 0
    try {
        # 反映の判定（状態ファイルに反映待ちがあるものだけ。反映済みになった行は、この後で状態から消す）
        $entries = getReflectedSystemIndexEntries $state $systemRootPath $ask
        $reflected = $entries.Reflected
        $unreflected = $entries.Unreflected

        foreach ($folder in $folders) {
            if ($folder -is [string]) {
                $folder = @{ Root = $folder; RelPath = ""; Recurse = $true }
            }
            $root = ([string]$folder.Root).TrimEnd("\")
            $relPath = ([string]$folder.RelPath).Trim("\")
            $targetDir = if ($relPath) { "$root\$relPath" } else { $root }
            # 別の場所のインデックス・インデックス全体・対応済みでないインデックス・無いフォルダは、今までどおりすべてを列挙する
            if (!$root.Equals($indexRootPath, [System.StringComparison]::OrdinalIgnoreCase) -or $relPath -eq "" -or
                !$state.Covered.Contains((getIndexNameOfRelPath $relPath)) -or ![System.IO.Directory]::Exists((toLongPath $targetDir))) {
                $targets.Add($folder)
                continue
            }
            $found = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
            $scopeDir = "$systemRootPath\$relPath"
            if ([System.IO.Directory]::Exists((toLongPath $scopeDir))) {
                foreach ($row in (& $ask (newSystemIndexQuery $scopeDir $grams))) {
                    $rel = getRelativePath ([System.IO.Path]::GetDirectoryName((convertItemUrl ([string]$row[0])))) $systemRootPath
                    if ($rel) { [void]$found.Add($rel) }
                }
                # 分けた txt は、語ごとに問い合わせ、すべての語がどれかの部分で見つかったフォルダを候補にする
                $split = $null
                foreach ($gram in $grams) {
                    $hit = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
                    foreach ($row in (& $ask (newSystemIndexSplitQuery $scopeDir $gram))) {
                        $rel = getRelativePath ([System.IO.Path]::GetDirectoryName((convertItemUrl ([string]$row[0])))) $systemRootPath
                        if ($rel) { [void]$hit.Add($rel) }
                    }
                    if ($null -eq $split) { $split = $hit } else { $split.IntersectWith($hit) }
                    if ($split.Count -eq 0) { break }
                }
                if ($split) { $found.UnionWith($split) }
            }
            $candidates += $found.Count
            $found.UnionWith($unreflected)
            $found.UnionWith($state.Excluded)
            foreach ($rel in $found) {
                $dir = "$indexRootPath\$rel"
                if ((testFolderInTarget $dir $targetDir ([bool]$folder.Recurse)) -and [System.IO.Directory]::Exists((toLongPath $dir))) {
                    $targets.Add(@{ Root = $indexRootPath; RelPath = $rel; Recurse = $false })
                }
            }
        }
    } catch {
        return $null
    } finally {
        if ($connection) {
            $connection.Dispose()
        }
    }

    $index = getContentIndexFiles $targets.ToArray() $onProgress
    if ($reflected.Count -gt 0) {
        # 反映済みになった行を消す（txt が書き直されて日時が変わった行は残す）。書けなくても検索は続ける。
        # 書き換えの中から見る値は、updateSystemIndexState の変数と名前が重ならないようにする（呼び出し先の $state が見えてしまう）
        $readTicks = $state.Pending
        [void](updateSystemIndexState {
            param ($current)
            foreach ($rel in $reflected) {
                if ($current.Pending.ContainsKey($rel) -and $current.Pending[$rel] -eq $readTicks[$rel]) {
                    [void]$current.Pending.Remove($rel)
                }
            }
        } $statePath)
    }
    $index.Fast = @{ Candidates = $candidates; Unreflected = $unreflected.Count }
    return $index
}

function getSystemIndexProgress {
    # システムインデックス（高速検索用の txt）が Windows Search にどこまで反映されたかを数える。画面が「確かめるとき」だけ呼ぶ（検索では呼ばない）。
    # @{ Folders; Waiting; ContentIndexed; ByIndex } を返す。状態ファイルを読めない・Windows Search に問い合わせられないときは $null。
    #   Folders       : txt があるフォルダと、状態ファイルの反映待ちのフォルダを合わせた数（分けた txt は 1 つのフォルダに数える）
    #   Waiting       : 反映待ちのうち、Windows Search でまだ反映済みでないフォルダの数（getFastSearchContentIndexFiles と同じ判定）
    #   ContentIndexed: 本文インデックス（index の TSV）も Windows Search に索引されているか（反映が遅い理由の案内に使う）
    #   ByIndex       : インデックス名（system_index からの相対パスの先頭のフォルダ名） → @{ Folders; Waiting } の辞書（OrdinalIgnoreCase）
    #   query         : getFastSearchContentIndexFiles と同じ。$null なら Windows Search を開いて問い合わせる（テストで差し替える）
    #   connection    : 開いた接続（渡したら呼び出し側が閉じる）。$null なら query が無いときだけ自分で開いて閉じる
    param (
        [scriptblock]$query = $null,
        [string]$indexRoot = $workspace.IndexDir,
        [string]$systemRoot = $workspace.SystemIndexDir,
        [string]$statePath = $workspace.SystemIndexStateFile,
        $connection = $null
    )

    $state = readSystemIndexState $statePath
    if ($null -eq $state) {
        return $null
    }
    $own = $false
    if ($null -eq $query -and $null -eq $connection) {
        $connection = openWindowsSearch
        if ($null -eq $connection) {
            return $null
        }
        $own = $true
    }
    # 問い合わせ（差し替えが無ければ開いた接続で）。& で呼ぶと、この関数の $query・$connection が見える
    $ask = {
        param ($sql)
        if ($query) { & $query $sql } else { invokeWindowsSearch $connection $sql }
    }

    $systemRootPath = $systemRoot.TrimEnd("\")
    try {
        $entries = getReflectedSystemIndexEntries $state $systemRootPath $ask
        $folders = New-Object System.Collections.Generic.HashSet[string] ([System.StringComparer]::OrdinalIgnoreCase)
        $longRoot = toLongPath $systemRootPath
        if ([System.IO.Directory]::Exists($longRoot)) {
            $pattern = "$([System.IO.Path]::GetFileNameWithoutExtension(${systemIndexFileName}))*.txt"
            foreach ($file in [System.IO.Directory]::EnumerateFiles($longRoot, $pattern, [System.IO.SearchOption]::AllDirectories)) {
                $rel = getRelativePath (fromLongPath ([System.IO.Path]::GetDirectoryName($file))) $systemRootPath
                if ($rel) { [void]$folders.Add($rel) }
            }
        }
        foreach ($key in $state.Pending.Keys) {
            [void]$folders.Add([System.IO.Path]::GetDirectoryName($key))
        }
        $contentIndexed = testTsvIndexedByWindowsSearch $indexRoot $connection
    } catch {
        return $null
    } finally {
        if ($own) {
            $connection.Dispose()
        }
    }
    $byIndex = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($rel in $folders) {
        $name = $rel.Split([char[]]"\")[0]
        if (!$byIndex.ContainsKey($name)) {
            $byIndex[$name] = @{ Folders = 0; Waiting = 0 }
        }
        $byIndex[$name].Folders++
    }
    foreach ($rel in $entries.Unreflected) {
        $name = $rel.Split([char[]]"\")[0]
        if ($byIndex.ContainsKey($name)) {
            $byIndex[$name].Waiting++
        }
    }
    return @{ Folders = $folders.Count; Waiting = $entries.Unreflected.Count; ContentIndexed = $contentIndexed; ByIndex = $byIndex }
}

# 検索結果の組み立て・書き出しと、インデックスの有無・件数（検索そのものは content_index_search.ps1）。

function toResultLine {
    # 検索結果1件を "ファイル名<TAB>場所<TAB>種別<TAB>行番号<TAB>該当行" に整形する。場所・種別は場所ごとの表記（describePlace。画面の見出しの要約と同じ）。
    # Excelに貼り付けたとき、該当行の各セルが元の列の順（5列目 = A列）に並ぶようにする
    param (
        [string]$book,
        [string]$location,
        [int]$lineNumber,
        [string]$line
    )

    if ($book -match "\.xls[a-z]?$") {
        # セル内改行を戻す（改行を含むセルは " で囲まれているため、貼り付けても1セルのまま）
        $line = $line.Replace(${cellNewLine}, "`n")
    } else {
        # Word・PowerPointの行（段落、または表の1行をタブ区切りにしたもの）は " で囲まれていない。
        # Excelは " で始まるセルを囲みの " と解釈して後続がずれるため、そのセルだけ " で囲む
        $line = @($line.Split("`t") | ForEach-Object {
            if ($_.StartsWith('"')) { '"' + $_.Replace('"', '""') + '"' } else { $_ }
        }) -join "`t"
    }
    # 場所（シート名）にタブ・改行が入っていると、列・行が分かれてしまうためスペースにする
    # （Excelのシート名はタブ・改行を含められる）
    $described = describePlace $book $location
    $place = [regex]::Replace($described.Place, '[\x00-\x1F]', " ")
    return "${book}`t${place}`t$($described.Kind)`t${lineNumber}`t${line}"
}

function toResultHeader {
    # 検索結果の見出し行 "ファイル名<TAB>場所<TAB>種別<TAB>行<TAB>A<TAB>B…" を返す（列名は columnCount 列分）
    param (
        [int]$columnCount
    )

    $names = New-Object System.Collections.Generic.List[string]
    $names.AddRange([string[]]@("ファイル名", "場所", "種別", "行"))
    for ($i = 1; $i -le $columnCount; $i++) {
        $names.Add((toColumnName $i))
    }
    return ($names -join "`t")
}


# 検索で読んだ本文インデックスのファイルの内容を残しておく量の上限（文字数。1 文字 2 バイトのため約 128MB）
${searchCacheMaxChars} = 64000000

function newTsvTextCache {
    # 検索で読んだ本文インデックスのファイルの内容を、次の検索で使い回すための入れ物を作る（画面が 1 つ持ち、検索のたびに searchContentIndex に渡す）。
    # 2 回目以降の検索ではファイルを開かない。更新日時・サイズが列挙したときと違う本文インデックスのファイル（書き直した等）は読み直す。
    # 並列検索の各スレッドから使うため、中身は ConcurrentDictionary。
    #   Texts: 本文インデックスのファイルの \\?\ 付きのパス → @(更新日時（UTC の Ticks）, サイズ, 内容, 場所の一覧, 最後に使った世代) / Chars: 残している文字数 / MaxChars: 上限
    #   Generation: 今の世代（検索 1 回ごとに trimTsvTextCache が 1 つ進める）
    param (
        [long]$maxChars = ${searchCacheMaxChars}
    )

    return @{
        Texts      = New-Object 'System.Collections.Concurrent.ConcurrentDictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
        Chars      = [long[]]::new(1)
        MaxChars   = $maxChars
        Generation = [long[]]::new(1)
    }
}

# 検索の後、キャッシュがこの割合を超えていたら、空きを作る（次の検索で新しく読んだものが入るように）
${searchCacheKeepRatio} = 0.9

function trimTsvTextCache {
    # 検索 1 回の後に呼ぶ（検索の司令のスレッド）。上限の keepRatio を超えていたら、今の世代で使わなかったものを、
    # 古い世代から追い出す（消した本文インデックスのファイル・検索しなくなったフォルダの分）。今の世代で使ったものは残す
    # （毎回同じ本文インデックスのファイルを順に読むため、使った順だけで追い出すと、上限より大きいインデックスでは何も残らない）。
    # 最後に世代を 1 つ進める。追い出した数を返す
    param (
        $cache,
        [double]$keepRatio = ${searchCacheKeepRatio}
    )

    $removed = 0
    [System.Threading.Monitor]::Enter($cache)
    try {
        $current = $cache.Generation[0]
        $limit = [long]($cache.MaxChars * $keepRatio)
        if ($cache.Chars[0] -gt $limit) {
            $old = @($cache.Texts.GetEnumerator() | Where-Object { $_.Value[4] -lt $current } | Sort-Object { $_.Value[4] })
            foreach ($item in $old) {
                if ($cache.Chars[0] -le $limit) {
                    break
                }
                $entry = $null
                if ($cache.Texts.TryRemove($item.Key, [ref]$entry)) {
                    $cache.Chars[0] -= $entry[2].Length
                    $removed++
                }
            }
        }
        $cache.Generation[0] = $current + 1
    } finally {
        [System.Threading.Monitor]::Exit($cache)
    }
    return $removed
}

function newSearchRequest {
    # 検索の要求 1 つを作る（画面が作り、検索の司令のスレッド（SearchService）が invokeSearchRequest で実行する）。
    # 画面と司令のスレッドの両方から読み書きするため、Synchronized の hashtable にする。
    #   画面が書く: 検索条件・Stop（取り消し）
    #   司令が書く: Queue（ヒット）・Done / Total / IndexTotal / Scanned（進み具合）・Folders・FastUsed / FastAvailable・Truncated / Cancelled / Error・Finished
    #   workDir: 高速検索で使うワークスペース（司令のスレッドは lib.ps1 を読み込んだときのワークスペースを覚えているため、画面から渡す）
    param (
        [string]$word,
        [bool]$simpleMatch,
        $folders,
        [int]$limit,
        [hashtable]$option = @{},
        [bool]$useFast = $false,
        [string]$workDir = $workspace.Dir
    )

    return [hashtable]::Synchronized(@{
        Word = $word; SimpleMatch = $simpleMatch; Folders = $folders; Limit = $limit; WorkDir = $workDir
        CaseSensitive = [bool]$option.CaseSensitive; FileFilter = (newFileKindFilter $option.FileKinds)
        IncludeShapes = ($option.IncludeShapes -ne $false); IncludeComments = ($option.IncludeComments -ne $false)
        UseFast = $useFast; FastUsed = $false; FastAvailable = $null
        Queue = New-Object 'System.Collections.Concurrent.ConcurrentQueue[object]'
        Stop = $false; Finished = $false; Done = 0; Total = -1; IndexTotal = -1; Scanned = 0
        Truncated = $false; Cancelled = $false; Error = $null
    })
}

function invokeSearchRequest {
    # 検索の要求（newSearchRequest）を実行し、ヒットと進み具合を要求に少しずつ入れる。最後に Finished を立てる。
    # 例外は投げずに Error に入れる。始める前に取り消されていたら（次の要求が来た等）、何もせずに Cancelled にする。
    #   pool : 照合のプール（newContentIndexWorkerPool）。$null なら searchContentIndex が必要なときだけ作る
    #   cache: 読んだ本文インデックスのファイルの内容の入れ物（newTsvTextCache）
    param (
        [hashtable]$request,
        $pool = $null,
        $cache = $null
    )

    try {
        if ($request.Stop) {
            $request.Cancelled = $true
            return
        }
        $word = $request.Word
        $folders = $request.Folders
        # 高速検索が使えるなら、Windows Search で検索語を含みうるフォルダを先に絞る（使えなければ $null で、すべてを集める）
        $index = $null
        if ($request.UseFast) {
            $own = [Workspace]::new($request.WorkDir)
            $request.FastAvailable = testWindowsSearch $own.SystemIndexDir
            if ($request.FastAvailable) {
                $index = getFastSearchContentIndexFiles $word $folders -indexRoot $own.IndexDir -systemRoot $own.SystemIndexDir -statePath $own.SystemIndexStateFile `
                    -onProgress { param ($count) $request.Scanned = $count }
            }
        }
        $request.FastUsed = ($null -ne $index)
        if ($null -eq $index) {
            # 途中の件数を画面に伝える（止まって見えないように）
            $index = getContentIndexFiles $folders { param ($count) $request.Scanned = $count }
        }
        $request.Folders = $index.Folders
        $request.Total = $index.ContentIndexFiles.Count
        $request.IndexTotal = $index.ContentIndexFiles.Count
        $result = searchContentIndex $word $index.ContentIndexFiles $request.SimpleMatch $request.Limit -caseSensitive $request.CaseSensitive `
            -fileFilter $request.FileFilter -cache $cache -includeShapes $request.IncludeShapes -includeComments $request.IncludeComments -pool $pool `
            -onProgress {
            param ($done, $total, $newHits)
            foreach ($hit in $newHits) {
                $request.Queue.Enqueue($hit)
            }
            $request.Total = $total
            $request.Done = $done
        } -shouldStop { $request.Stop }
        $request.Total = $result.Total
        $request.Truncated = $result.Truncated
        $request.Cancelled = $result.Cancelled
    } catch {
        $request.Error = $_.Exception.Message
    } finally {
        $request.Finished = $true
    }
}

function testIndexExists {
    # 検索対象インデックスに本文インデックスのファイルが1件でもあるか（最初の1件が見つかった時点で打ち切る）
    param (
        [string[]]$folders = @($workspace.IndexDir)
    )

    foreach ($dir in $folders) {
        if (!(Test-Path -LiteralPath $dir -PathType Container)) {
            continue
        }
        try {
            # 1 件見つけたらやめる。列挙子を閉じずに戻ると content_index の下のフォルダを掴んだまま残り、
            # 続くインポートの上書きで移動できなくなるため testAnyEntry を通す
            if (testAnyEntry ([System.IO.Directory]::EnumerateFiles((toLongPath (Resolve-Path -LiteralPath $dir).ProviderPath), ${contentIndexFilePattern}, [System.IO.SearchOption]::AllDirectories))) {
                return $true
            }
        } catch {
            # アクセスできないフォルダがある場合は、件数を数える方で判定する
            if (@(Get-ChildItem -LiteralPath $dir -Filter ${contentIndexFilePattern} -File -Recurse -ErrorAction SilentlyContinue).Count -gt 0) {
                return $true
            }
        }
    }
    return $false
}

function getIndexSummary {
    # 検索対象インデックスの本文インデックスのファイルの件数と最新の更新日時を返す: @{ Count; LastWrite（無ければ $null）; Missing（存在しないフォルダ） }
    param (
        [string[]]$folders = @($workspace.IndexDir)
    )

    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $summary = @{ Count = 0; LastWrite = $null; Missing = @() }
    foreach ($dir in $folders) {
        if (!(Test-Path -LiteralPath $dir -PathType Container)) {
            $summary.Missing += $dir
            continue
        }
        $longDir = toLongPath (Resolve-Path -LiteralPath $dir).ProviderPath
        # アクセスできないフォルダがあると .NET の列挙は途中で止まるため、そのときは Get-ChildItem で数える（読めるものだけ）
        try {
            $found = [System.IO.DirectoryInfo]::new($longDir).GetFiles(${contentIndexFilePattern}, [System.IO.SearchOption]::AllDirectories)
        } catch {
            $found = @(Get-ChildItem -LiteralPath $longDir -Filter ${contentIndexFilePattern} -File -Recurse -ErrorAction SilentlyContinue)
        }
        foreach ($file in $found) {
            if (!$seen.Add($file.FullName)) {
                continue
            }
            $summary.Count++
            if ($null -eq $summary.LastWrite -or $file.LastWriteTime -gt $summary.LastWrite) {
                $summary.LastWrite = $file.LastWriteTime
            }
        }
    }
    return $summary
}

function toSearchResultLines {
    # 検索結果を検索結果ファイルの形式にし、@{ Header（見出し行）; Lines } を返す（画面のファイル出力・コピーで共通）。
    # Excelに貼り付けたときに元のセル位置が分かるよう、行番号（TSVの行番号 = Excelの行番号）を付け、
    # 見出しには該当行の最大セル数分の列名（A, B, C…）を付ける
    param (
        [object[]]$hits
    )

    $lines = New-Object System.Collections.Generic.List[string]
    $columnCount = 0
    foreach ($hit in $hits) {
        # ファイル名の前に、クロール対象フォルダからの相対フォルダを付ける
        $line = toResultLine $hit.Book $hit.Location $hit.LineNumber $hit.Line
        if ($hit.RelDir) {
            $line = "$($hit.RelDir)\${line}"
        }
        $lines.Add($line)
        $columnCount = [math]::Max($columnCount, (countTsvFields $line) - 4)  # ファイル名・場所・種別・行番号の4列を除く
    }
    return @{ Header = (toResultHeader $columnCount); Lines = $lines }
}

function writeSearchResult {
    # 1ワード分の検索結果を検索結果ファイルに書き出す
    param (
        [System.IO.TextWriter]$writer,
        [string]$word,
        [object[]]$hits
    )

    $result = toSearchResultLines $hits
    $writer.WriteLine("【検索文字列　${word}】 $($result.Lines.Count) 件")
    $writer.WriteLine($result.Header)
    foreach ($line in $result.Lines) {
        $writer.WriteLine($line)
    }
    $writer.WriteLine("")
}

# 検索用の本文インデックスのファイル（content_index_format.ps1）を検索する。
# 本文インデックスのファイルの全文に 1 回照合し、一致しないファイルは飛ばす。一致したら、位置から場所と行を求める。
# 照合のしかた（lines・filter・scan。search_query.ps1 の getRegexScanMode）で、全文への照合と 1 行ずつの照合の結果を同じにする。
# Excel の図形・コメントの行は「セル番地 + タブ + 文字」の形のため、区切りのタブより後から始まる一致だけをヒットにする（セル番地だけの一致を除く）。

function testCellPrefixedHit {
    # セル番地 + 区切りのタブ + 文字 の行で、区切りのタブ（最初のタブ）より後から始まる一致があるか。文字の中のタブは文字として扱う。
    # 開始位置つきの照合なので、後読みは前の文字（区切りのタブ）も見える。区切りのタブが無い行は一致なし
    param (
        [regex]$regex,
        [string]$line
    )

    $tab = $line.IndexOf([char]9)
    return ($tab -ge 0) -and $regex.IsMatch($line, $tab + 1)
}


function searchContentIndexFiles {
    # contentIndexFiles の start から count 件の本文インデックスのファイルを読み、regex に一致する行を PSCustomObject で返す（1 行に複数一致しても 1 件）。
    # max 以上（max+1 件目）が見つかった時点で打ち切る（負は上限なし）。読めないファイルは飛ばす。
    #   include / exclude: 元のファイル名の条件（$null は条件なし） / excludePlace: 除く場所（図形・コメント）
    #   cache: newTsvTextCache。更新日時・大きさが同じなら、前に読んだ内容と場所の一覧を使う
    # 照合が時間切れ（RegexMatchTimeoutException）なら、そのまま呼び出し元へ伝える
    param (
        $contentIndexFiles,
        [int]$start,
        [int]$count,
        [regex]$regex,
        [int]$max,
        [regex]$textRegex = $null,
        [string]$scanMode = "scan",
        $cache = $null,
        [regex]$include = $null,
        [regex]$exclude = $null,
        [regex]$excludePlace = $null
    )

    # 並列検索の別スレッドでも動くよう、コマンドレットは使わない
    $hits = [System.Collections.Generic.List[psobject]]::new()
    $end = [Math]::Min($contentIndexFiles.Count, $start + $count)
    $lf = [char]10
    $mark = [char]0x1E
    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $mode = if ($null -eq $textRegex) { "scan" } else { $scanMode }
    for ($i = $start; $i -lt $end; $i++) {
        $contentIndexFile = $contentIndexFiles[$i]
        $text = $null
        $places = $null
        $cached = $false
        if ($null -ne $cache) {
            $entry = $null
            if ($cache.Texts.TryGetValue($contentIndexFile.Path, [ref]$entry) -and $entry[0] -eq $contentIndexFile.Ticks -and $entry[1] -eq $contentIndexFile.Size) {
                $text = $entry[2]
                $places = $entry[3]
                $cached = $true
                # この検索で使ったことを残す（trimTsvTextCache は、使われていない古いものから追い出す）
                $entry[4] = $cache.Generation[0]
            }
        }
        if ($null -eq $text) {
            try {
                $stream = [System.IO.FileStream]::new($contentIndexFile.Path, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
                $reader = [System.IO.StreamReader]::new($stream, [System.Text.Encoding]::Unicode, $true)
                try { $text = $reader.ReadToEnd() } finally { $reader.Dispose() }
            } catch [System.IO.IOException] {
                continue
            } catch [System.UnauthorizedAccessException] {
                continue
            }
        }
        # 一致しなければ、場所の一覧も作らずに次へ（場所の一覧は、一致したときか、キャッシュに入れるときだけ作る）。
        # 全文への照合が時間切れなら、このファイルは 1 行ずつ照合する
        $contentIndexMode = $mode
        $matched = $true
        if ($contentIndexMode -ne "scan") {
            try {
                $matched = $textRegex.IsMatch($text)
            } catch [System.Text.RegularExpressions.RegexMatchTimeoutException] {
                $contentIndexMode = "scan"
            }
        }
        if ($null -eq $places -and ($matched -or $null -ne $cache)) {
            $places = readContentIndexPlaces $text
        }
        if ($null -ne $cache -and !$cached) {
            [System.Threading.Monitor]::Enter($cache)
            try {
                $old = $null
                if ($cache.Texts.TryRemove($contentIndexFile.Path, [ref]$old)) {
                    $cache.Chars[0] -= $old[2].Length
                }
                if ($cache.Chars[0] + $text.Length -le $cache.MaxChars) {
                    $cache.Texts[$contentIndexFile.Path] = [object[]]@($contentIndexFile.Ticks, $contentIndexFile.Size, $text, $places, $cache.Generation[0])
                    $cache.Chars[0] += $text.Length
                }
            } finally {
                [System.Threading.Monitor]::Exit($cache)
            }
        }
        if (!$matched) { continue }

        $before = $hits.Count
        $lineMode = $contentIndexMode -eq "lines"
        if ($lineMode) {
            try {
                $length = $text.Length
                $p = 0            # 今の場所（places の番号）
                $number = 0       # 今の場所で、pos までに数えた行の数
                $pos = -1         # 行を数え終えた位置（-1 は場所が変わったので数え直し）
                $lastP = -1       # 直前に判定した場所の番号（isTextBook を場所が変わったときだけ判定し直す）
                $isTextBook = $false
                $m = $textRegex.Match($text)
                while ($m.Success) {
                    $index = $m.Index
                    if ($index -ge $length) { break }
                    $lineStart = if ($index -eq 0) { 0 } else { $text.LastIndexOf($lf, $index - 1) + 1 }
                    $lineEnd = $text.IndexOf($lf, $index)
                    if ($lineEnd -lt 0) { $lineEnd = $length }
                    if ($lineStart -lt $length -and $text[$lineStart] -eq $mark) {
                        # メタ情報の行（ファイル名・場所の名前）の中の一致は捨てる
                        if ($lineEnd -ge $length) { break }
                        $m = $textRegex.Match($text, $lineEnd + 1)
                        continue
                    }
                    while ($p -lt $places.Count -and $places[$p].End -le $lineStart) { $p++; $pos = -1 }
                    if ($p -ge $places.Count) { break }
                    $place = $places[$p]
                    if ($p -ne $lastP) {
                        $isTextBook = ((getContentIndexFileKind $place.Book) -eq "テキスト")
                        $lastP = $p
                    }
                    $skip = ($include -and !$include.IsMatch($place.Book)) -or ($exclude -and $exclude.IsMatch($place.Book)) -or
                        ($excludePlace -and $excludePlace.IsMatch($place.Location))
                    if ($skip) {
                        if ($place.End -ge $length) { break }
                        $m = $textRegex.Match($text, $place.End)
                        continue
                    }
                    if ($pos -lt 0) { $pos = $place.Start; $number = 1 }
                    # 前に数えた位置から行の先頭までの改行を数える（Substring を作らない）
                    while ($pos -lt $lineStart) {
                        $n = $text.IndexOf($lf, $pos, $lineStart - $pos)
                        if ($n -lt 0) { break }
                        $number++
                        $pos = $n + 1
                    }
                    $pos = $lineStart
                    $line = $text.Substring($lineStart, $lineEnd - $lineStart)
                    if ($place.CellPrefixed -and !(testCellPrefixedHit $regex $line)) {
                        # セル番地だけに一致した行はヒットにしない（行番号の数え方は崩さない）
                        if ($lineEnd -ge $length) { break }
                        $m = $textRegex.Match($text, $lineEnd + 1)
                        continue
                    }
                    if ($isTextBook) {
                        $line = truncateHitLine $line ($index - $lineStart)
                    }
                    $hits.Add([pscustomobject]@{
                        Root = $contentIndexFile.Root; RelPath = $contentIndexFile.RelPath; RelDir = $contentIndexFile.RelDir; FileName = $place.Book
                        Book = $place.Book; Location = $place.Location; LineNumber = $number; Line = $line
                    })
                    if ($max -ge 0 -and $hits.Count -gt $max) { return , $hits }
                    if ($lineEnd -ge $length) { break }
                    $m = $textRegex.Match($text, $lineEnd + 1)
                }
                continue
            } catch [System.Text.RegularExpressions.RegexMatchTimeoutException] {
                # 全文への照合が時間切れなら、1 行ずつ照合し直す
                if ($hits.Count -gt $before) { $hits.RemoveRange($before, $hits.Count - $before) }
            }
        }
        # filter・scan（と lines の時間切れ）: 場所ごとに 1 行ずつ照合する
        foreach ($place in $places) {
            if ($include -and !$include.IsMatch($place.Book)) { continue }
            if ($exclude -and $exclude.IsMatch($place.Book)) { continue }
            if ($excludePlace -and $excludePlace.IsMatch($place.Location)) { continue }
            $isTextBook = ((getContentIndexFileKind $place.Book) -eq "テキスト")
            $number = 0
            $pos = $place.Start
            while ($pos -lt $place.End) {
                $n = $text.IndexOf($lf, $pos, $place.End - $pos)
                if ($n -lt 0) { $n = $place.End }
                $number++
                $line = $text.Substring($pos, $n - $pos)
                $pos = $n + 1
                $lineMatch = $regex.Match($line)
                if (!$lineMatch.Success) { continue }
                if ($place.CellPrefixed -and !(testCellPrefixedHit $regex $line)) { continue }
                if ($isTextBook) {
                    $line = truncateHitLine $line $lineMatch.Index
                }
                $hits.Add([pscustomobject]@{
                    Root = $contentIndexFile.Root; RelPath = $contentIndexFile.RelPath; RelDir = $contentIndexFile.RelDir; FileName = $place.Book
                    Book = $place.Book; Location = $place.Location; LineNumber = $number; Line = $line
                })
                if ($max -ge 0 -and $hits.Count -gt $max) { return , $hits }
            }
        }
    }
    return , $hits
}


# 本文インデックスのファイルの検索で、1 つのスレッドにまとめて渡す大きさの目安（バイト）
${contentIndexTaskBytes} = 16MB

# 本文インデックスのファイルの検索の各スレッドで動かすスクリプト。@{ Hits; Timeout } を返す
${contentIndexWorkerScript} = {
    param ($contentIndexFiles, $start, $count, $regex, $max, $textRegex, $scanMode, $cache, $include, $exclude, $excludePlace)
    try {
        $hits = searchContentIndexFiles $contentIndexFiles $start $count $regex $max $textRegex $scanMode $cache $include $exclude $excludePlace
        @{ Hits = $hits; Timeout = $false }
    } catch {
        if ($_.Exception -is [System.Text.RegularExpressions.RegexMatchTimeoutException] -or
            $_.Exception.InnerException -is [System.Text.RegularExpressions.RegexMatchTimeoutException]) {
            @{ Hits = $null; Timeout = $true }
        } else {
            throw
        }
    }
}


function newContentIndexWorkerPool {
    # 本文インデックスのファイルの照合のプール（WorkerPool）を作る。各スレッドには照合に要る関数と値だけを読み込む。
    # 利用者が結果を待つ処理のため、優先度は下げない（docs/design/structure/threads.md「スレッドの一覧」）
    param (
        [int]$workers = (getWorkerCount)
    )

    $state = newWorkerState @("searchContentIndexFiles", "testCellPrefixedHit", "readContentIndexPlaces", "testContentIndexCellPrefixed", "convertContentIndexMetaToPlace", "decodeContentIndexValue", "getContentIndexFileKind", "testTextExtension", "testPdfExtension", "truncateHitLine") `
        @("contentIndexMark", "contentIndexVersion", "contentIndexPlaceKeys", "placeKindShape", "placeKindComment", "placeKindHeaderFooter", "placeKindEmbed", "textExtensions", "pdfExtensions", "hitLineMaxChars", "hitLineBeforeMatchChars")
    return [WorkerPool]::new($workers, $state, $Host, "Normal")
}


function splitContentIndexTasks {
    # 本文インデックスのファイルの並びを、1 つのスレッドに渡す単位（@{ Start; Count }）に分ける（合計がおよそ contentIndexTaskBytes になるまでまとめる）
    param (
        $contentIndexFiles,
        [long]$taskBytes = ${contentIndexTaskBytes}
    )

    $tasks = New-Object System.Collections.Generic.List[hashtable]
    $start = 0
    $bytes = 0L
    for ($i = 0; $i -lt $contentIndexFiles.Count; $i++) {
        $bytes += [long]$contentIndexFiles[$i].Size
        if ($bytes -ge $taskBytes -or $i -eq $contentIndexFiles.Count - 1) {
            $tasks.Add(@{ Start = $start; Count = $i - $start + 1 })
            $start = $i + 1
            $bytes = 0L
        }
    }
    return , $tasks
}


function searchContentIndex {
    # 本文インデックスのファイルをワードで検索し、ヒットした行を返す（画面の検索処理）。
    #   contentIndexFiles        : findContentIndexFiles・getContentIndexFiles の結果
    #   simpleMatch  : $true なら文字どおりに検索する。$false なら正規表現として検索し、正規表現として不正なら文字どおりに検索する
    #   limit        : 件数の上限（0 は上限なし）。超えたら打ち切る
    #   shouldStop   : $true を返すと中止する
    #   caseSensitive: 英字の大文字・小文字を区別する（newSearchRegex）
    #   fileFilter   : 対象ファイル（newFileFilter）。元のファイル名が一致しないものは検索しない
    #   workerCount  : 並列に検索するスレッドの数（0 は CPU のコア数から決める。最大 4）
    #   cache        : 読んだ本文インデックスのファイルの内容を次の検索で使い回す入れ物（newTsvTextCache。$null は使い回さない）
    #   includeShapes / includeComments: 図形・コメントの場所（"<シート名>[図形]" 等）も検索する（newPlaceExclude）
    #   taskBytes    : 1 つのスレッドにまとめて渡す大きさの目安（バイト）
    #   onProgress   : 1 つの作業を照合するたびに呼ぶ { param($done, $total, $newHits) }（done・total は本文インデックスのファイルの数）
    #   pool         : 照合に使うプール（newContentIndexWorkerPool。検索の司令が使い回す）。$null なら、並列にするときだけ作って最後に閉じる
    # @{ Hits; SimpleMatch（実際に文字どおり検索したか）; Total（本文インデックスのファイルの数）; Truncated; Cancelled } を返す。
    # Hits の各要素は PSCustomObject（Root; RelPath（本文インデックスのファイル）; RelDir; FileName; Book; Location; LineNumber; Line）
    param (
        [string]$word,
        $contentIndexFiles,
        [bool]$simpleMatch = $false,
        [int]$limit = 0,
        [scriptblock]$shouldStop = $null,
        [bool]$caseSensitive = $false,
        [string]$fileFilter = "",
        [int]$workerCount = 0,
        $cache = $null,
        [bool]$includeShapes = $true,
        [bool]$includeComments = $true,
        [long]$taskBytes = ${contentIndexTaskBytes},
        [scriptblock]$onProgress = $null,
        $pool = $null
    )

    $search = newSearchRegex $word $simpleMatch $caseSensitive
    $filter = newFileFilter $fileFilter
    $excludePlace = newPlaceExclude $includeShapes $includeComments
    $hits = New-Object System.Collections.Generic.List[psobject]
    $result = @{ Hits = $hits; SimpleMatch = $search.SimpleMatch; Total = $contentIndexFiles.Count; Truncated = $false; Cancelled = $false }
    $timeoutMessage = "正規表現の照合に時間がかかりすぎるため、検索を中止しました。正規表現を見直してください。"
    $tasks = splitContentIndexTasks $contentIndexFiles $taskBytes
    $workers = if ($pool) { $pool.Size } elseif ($workerCount -gt 0) { $workerCount } else { getWorkerCount }
    if ($tasks.Count -lt 2) { $workers = 1 }

    $ownPool = $null
    $pending = New-Object System.Collections.Generic.Queue[hashtable]
    try {
        if ($workers -le 1) {
            $pool = $null
        } elseif ($null -eq $pool) {
            $ownPool = newContentIndexWorkerPool $workers
            $pool = $ownPool
        }
        $next = 0
        while ($next -lt $tasks.Count -or $pending.Count -gt 0) {
            if ($shouldStop -and (& $shouldStop)) {
                $result.Cancelled = $true
                break
            }
            if ($pool) {
                while ($pending.Count -lt $workers * 2 -and $next -lt $tasks.Count) {
                    $max = if ($limit -gt 0) { $limit - $hits.Count } else { -1 }
                    $task = $tasks[$next]
                    $job = $pool.Submit(${contentIndexWorkerScript}.ToString(), @($contentIndexFiles, $task.Start, $task.Count, $search.Regex, $max, $search.TextRegex,
                            $search.ScanMode, $cache, $filter.Include, $filter.Exclude, $excludePlace))
                    $job.Done = $task.Start + $task.Count
                    $pending.Enqueue($job)
                    $next++
                }
                $output = $pool.Receive($pending.Dequeue())
                if ($output[0].Timeout) { throw $timeoutMessage }
                $newHits = $output[0].Hits
                $done = $job.Done
            } else {
                $task = $tasks[$next]
                $next++
                $done = $task.Start + $task.Count
                $max = if ($limit -gt 0) { $limit - $hits.Count } else { -1 }
                try {
                    $newHits = searchContentIndexFiles $contentIndexFiles $task.Start $task.Count $search.Regex $max $search.TextRegex $search.ScanMode $cache $filter.Include $filter.Exclude $excludePlace
                } catch [System.Text.RegularExpressions.RegexMatchTimeoutException] {
                    throw $timeoutMessage
                }
            }
            $max = if ($limit -gt 0) { $limit - $hits.Count } else { -1 }
            if ($max -ge 0 -and $newHits.Count -gt $max) {
                $newHits.RemoveRange($max, $newHits.Count - $max)
                $result.Truncated = $true
            }
            $hits.AddRange($newHits)
            if ($onProgress) {
                & $onProgress $done $contentIndexFiles.Count $newHits
            }
            if ($result.Truncated) { break }
        }
    } finally {
        foreach ($job in $pending) {
            $pool.Cancel($job)
        }
        if ($ownPool) { $ownPool.Close() }
    }
    return $result
}


function getContentIndexFiles {
    # 検索対象の本文インデックスのファイルを集め、@{ Folders; ContentIndexFiles } を返す。
    #   folders: 検索対象インデックスのフォルダ（文字列。フォルダ以下すべて）、または
    #            @{ Root（インデックスのフォルダ）; RelPath（その中のフォルダ。空は Root 自身）; Recurse（$false は直下のファイルだけ） }
    #   Folders: フォルダごとの @{ Path; Root（フルパス）; Exists; Count }
    #   ContentIndexFiles  : findContentIndexFiles の結果をつないだもの（入れ子のフォルダを選んでも重複しない）
    #   onProgress: 数えた件数を知らせる { param($count) }
    param (
        [object[]]$folders = @($workspace.IndexDir),
        [scriptblock]$onProgress = $null
    )

    $folderInfo = New-Object System.Collections.Generic.List[object]
    $contentIndexFiles = New-Object System.Collections.Generic.List[hashtable]
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($target in $folders) {
        if ($target -is [string]) {
            $target = @{ Root = $target; RelPath = ""; Recurse = $true }
        }
        $relPath = ([string]$target.RelPath).Trim("\")
        $dir = if ($relPath) { "$(([string]$target.Root).TrimEnd('\'))\${relPath}" } else { [string]$target.Root }
        if (!(Test-Path -LiteralPath $target.Root -PathType Container) -or ![System.IO.Directory]::Exists((toLongPath $dir))) {
            $folderInfo.Add(@{ Path = $dir; Root = ""; Exists = $false; Count = 0 })
            continue
        }
        $root = (Resolve-Path -LiteralPath $target.Root).ProviderPath.TrimEnd("\")
        $found = findContentIndexFiles $root $relPath ([bool]$target.Recurse)
        $folderInfo.Add(@{ Path = $dir; Root = $root; Exists = $true; Count = $found.Count })
        foreach ($contentIndexFile in $found) {
            if ($seen.Add($contentIndexFile.Path)) { $contentIndexFiles.Add($contentIndexFile) }
        }
        if ($onProgress) { & $onProgress $contentIndexFiles.Count }
    }
    # フォルダの順、フォルダの中は名前の順（findContentIndexFiles と同じ）。検索対象を複数選んだときも順が崩れないよう並べ直す
    $sorted = [hashtable[]]@($contentIndexFiles | Sort-Object @{ Expression = { $_.Root } }, @{ Expression = { $_.RelDir } }, @{ Expression = { [System.IO.Path]::GetFileName($_.RelPath) } })
    return @{ Folders = $folderInfo.ToArray(); ContentIndexFiles = $sorted }
}
# 検索の司令のスレッド（SearchService）。画面を開いている間 1 つだけ動かし、検索の要求（newSearchRequest）を順に実行する。
# lib.ps1 の読み込みと照合のプールの用意は、スレッドを始めたときに 1 回だけ行う（検索のたびに行わない）。
# 設計は docs/design/structure/threads.md「スレッドの一覧」「寿命」。
#
# SearchService は画面のスレッドだけから呼ぶ（PowerShell 5.1 のクラスのメソッドは、定義したランスペースで動くため）。
# スレッドをまたいで使う要求は、Synchronized の hashtable（newSearchRequest）にする。

# 司令のスレッドで動かすスクリプト。要求の列が閉じられる（Close）まで、要求を 1 つずつ実行する。
# lib の部品（Prelude）は SearchService.Start が、この param ブロックのあとにつなぐ（joinWorkerScript）
${searchServiceScript} = {
    param ($requests, $cache, $workers)
    # 読み込めなければスレッドを終える（画面は IsRunning・GetFailure で知り、次の要求で作り直す）
    $ErrorActionPreference = "Stop"
    initWorkspace
    $ErrorActionPreference = "Continue"
    $pool = if ($workers -gt 1) { newContentIndexWorkerPool $workers } else { $null }
    try {
        foreach ($request in $requests.GetConsumingEnumerable()) {
            invokeSearchRequest $request $pool $cache
            if ($cache) {
                [void](trimTsvTextCache $cache)
            }
        }
    } finally {
        if ($pool) {
            $pool.Close()
        }
    }
}

# 閉じるときに、実行中の検索が止まるのを待つ時間（ミリ秒）。過ぎたらスレッドを止める
${searchServiceCloseMilliseconds} = 5000

class SearchService {
    # 照合のプールのスレッドの数
    [int]$Workers
    hidden [string]$Script
    hidden [hashtable]$LibLoad
    hidden $Cache
    hidden [int]$CloseMilliseconds
    hidden [System.Collections.Concurrent.BlockingCollection[hashtable]]$Requests
    hidden [System.Management.Automation.Runspaces.Runspace]$Runspace
    hidden [powershell]$PowerShell
    hidden [System.IAsyncResult]$Handle
    # いま実行している（最後に渡した）要求
    hidden [hashtable]$Current

    SearchService([string]$script, [hashtable]$libLoad, $cache, [int]$workers, [int]$closeMilliseconds) {
        $this.Script = $script
        $this.LibLoad = $libLoad
        $this.Cache = $cache
        $this.Workers = [Math]::Max(1, $workers)
        $this.CloseMilliseconds = $closeMilliseconds
        $this.Start()
    }

    hidden [void] Start() {
        $this.Requests = New-Object 'System.Collections.Concurrent.BlockingCollection[hashtable]'
        $rs = [runspacefactory]::CreateRunspace($this.LibLoad.State)
        $rs.Open()
        $ps = [powershell]::Create()
        $ps.Runspace = $rs
        $joined = if ($this.LibLoad.Prelude) { joinWorkerScript $this.LibLoad.Prelude $this.Script } else { $this.Script }
        [void]$ps.AddScript($joined).AddArgument($this.Requests).AddArgument($this.Cache).AddArgument($this.Workers)
        $this.Runspace = $rs
        $this.PowerShell = $ps
        $this.Handle = $ps.BeginInvoke()
    }

    [bool] IsRunning() {
        # 司令のスレッドが動いているか（lib.ps1 を読み込めなかった等で止まっていれば $false）
        return $null -ne $this.PowerShell -and !$this.Handle.IsCompleted
    }

    [string] GetFailure() {
        # 司令のスレッドが止まっていれば、その理由（無ければ空）
        if ($null -eq $this.PowerShell -or !$this.Handle.IsCompleted) {
            return ""
        }
        if ($this.PowerShell.Streams.Error.Count -gt 0) {
            return $this.PowerShell.Streams.Error[0].ToString()
        }
        return "検索のスレッドが止まりました。"
    }

    [hashtable] Request([hashtable]$request) {
        # 要求を渡す。実行中の要求は取り消す（次の要求が先に始まる）。司令のスレッドが止まっていれば作り直す
        $this.Cancel()
        if (!$this.IsRunning()) {
            $this.Shutdown()
            $this.Start()
        }
        $this.Current = $request
        $this.Requests.Add($request)
        return $request
    }

    [void] Cancel() {
        # 実行中の要求を取り消す（照合の作業の切れ目で止まる）
        if ($this.Current) {
            $this.Current.Stop = $true
        }
    }

    [void] Close() {
        # 検索を取り消し、司令のスレッドと照合のプールを片づける。何度呼んでもよい
        $this.Cancel()
        $this.Shutdown()
        $this.Current = $null
    }

    hidden [void] Shutdown() {
        if ($this.Requests) {
            $this.Requests.CompleteAdding()
        }
        if ($this.PowerShell) {
            if (!$this.Handle.AsyncWaitHandle.WaitOne($this.CloseMilliseconds)) {
                try {
                    $this.PowerShell.Stop()
                } catch {
                }
            }
            $this.PowerShell.Dispose()
            $this.PowerShell = $null
        }
        if ($this.Runspace) {
            $this.Runspace.Dispose()
            $this.Runspace = $null
        }
        if ($this.Requests) {
            $this.Requests.Dispose()
            $this.Requests = $null
        }
    }
}

function newSearchService {
    # 検索の司令のスレッドを始める（画面を開いたときに 1 回）。閉じるときは Close を呼ぶ
    param (
        $cache = $null,
        [int]$workers = (getWorkerCount)
    )

    $libLoad = getPartLoad lib
    return [SearchService]::new(${searchServiceScript}.ToString(), $libLoad, $cache, $workers, ${searchServiceCloseMilliseconds})
}

# 検索結果から元のファイルの場所を求める（source_folder.txt の読み書きを含む）。

function writeSourceFolderFile {
    # 各インデックスのフォルダに、インデックス名とクロール対象フォルダの対応（source_folder.txt）を書き出す。
    # 1行目は説明、2行目は "インデックス名<TAB>クロール対象フォルダ"。
    # インデックス1件につき1ファイルのため、<インデックス名> のフォルダだけを別の PC・場所へコピーしても
    # 元のファイルの場所が分かる（work\index ごとコピーした場合は readSourceFolderFile が各フォルダを読む）
    param (
        [object[]]$folders,  # assignIndexNames の結果（@{ Path; Name }）
        [string]$dir = $workspace.IndexDir
    )

    $header = "# 検索結果から元のファイルを開くときに使う、インデックス名とクロール対象フォルダの対応です（インデックス作成のたびに作り直します）"
    $items = @($folders | Where-Object { $_ -and $_.Name })
    foreach ($folder in $items) {
        # インデックスのフォルダがまだ無い（1件も取り込んでいない）場合は作らない
        $indexPath = Join-Path $dir $folder.Name
        if (Test-Path -LiteralPath (toLongPath $indexPath) -PathType Container) {
            $sourceFilePath = Join-Path $indexPath ${sourceFolderFileName}
            writeListFile $sourceFilePath @($header, "$($folder.Name)`t$($folder.Path)")
            # 画面（インデックス一覧の保存）からも呼ばれるため、書いたファイルだけに付ける（件数が多いため失敗してもログに出さない）
            [void](setNotContentIndexed $sourceFilePath)
        }
    }
}

function readSourceFolderFile {
    # インデックスのフォルダ（dir）直下の source_folder.txt を読み、インデックス名 → クロール対象フォルダ を返す
    # （大文字・小文字を区別しない）。ファイルが無ければ空。
    # ファイルは各インデックスのフォルダ（work\index\<インデックス名>）に置くため、dir にはそのフォルダを渡す。
    # dir の下を探し回らないのは、インデックスのフォルダの下が元のファイル1つにつき1フォルダ（数万個）になるため
    param (
        [string]$dir
    )

    $map = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($line in @(readListFile (Join-Path $dir ${sourceFolderFileName}))) {
        $fields = $line.Split("`t")
        if ($fields.Count -eq 2 -and $fields[0] -ne "" -and $fields[1] -ne "") {
            $map[$fields[0]] = $fields[1]
        }
    }
    return , $map
}

function getSourceFolderMap {
    # インデックスのフォルダ（dir）の インデックス名 → 元のフォルダ（今そのフォルダが置かれている場所）を返す。
    # 次の順に読み、後のもので上書きする（後のものが優先）:
    #   1. dir 直下の source_folder.txt … インデックスを作ったときの場所。インデックスをコピーしても付いてくる
    #   2. 既定のインデックス（work\index）なら取り込み一覧の記録
    #   3. 設定のインデックス名に対する場所（targetFolders・indexSources）… 利用者が指定した「今の場所」のため最も優先する
    param (
        [string]$dir,
        [string]$statusPath = $workspace.StatusFile,
        [string]$settingsPath = ${settingsFile},
        [string]$indexDir = $workspace.IndexDir
    )

    $map = readSourceFolderFile $dir
    if ((Test-Path -LiteralPath $indexDir -PathType Container) -and
        (testSameFolder $dir (Resolve-Path -LiteralPath $indexDir).ProviderPath)) {
        foreach ($entry in (getIndexNameMap $statusPath).GetEnumerator()) {
            $map[$entry.Key] = $entry.Value
        }
    }
    foreach ($folder in @(getTargetFolders $settingsPath | Where-Object { $_.Name })) {
        $map[$folder.Name] = $folder.Path
    }
    foreach ($source in @(readIndexSources $settingsPath)) {
        $map[$source.Name] = $source.Path
    }
    return , $map
}

function joinSourcePath {
    # フォルダ・相対フォルダ（空でも可）・ファイル名をつなぐ（ドライブ直下 "D:\" でも \ が重ならないようにする）
    param (
        [string]$folder,
        [string]$rest,
        [string]$name = ""
    )

    $path = $folder.TrimEnd("\")
    foreach ($part in @($rest, $name)) {
        if ($part) {
            $path += "\$part"
        }
    }
    return $path
}

function findSourceLocationInMaps {
    # 検索結果の元のファイルの場所を、キャッシュ（maps）だけで求める。ファイルは読まない。
    # 返すもの: @{ Resolved; Location; Pending }
    #   Resolved: 場所が決まったか。$false なら、Pending のフォルダの対応（getSourceFolderMap）を maps に足してから、もう一度呼ぶ
    #   Location: @{ Name（インデックス名）; Folder（元のフォルダ）; Rest（その下の相対フォルダ）; Known }。元のフォルダが分からなければ Known = $false・Folder = ""
    #             （Name は返すため、フォルダを選んでもらえば設定に記録できる）
    # インデックスのフォルダ（Root）の下は "インデックス名\相対フォルダ" のため、インデックス名から元のフォルダを引く。
    # 検索対象にインデックス名のフォルダ（…\index\<インデックス名>）を直接指定した場合は、親フォルダの記録を使う。
    param (
        $hit,
        [hashtable]$maps = @{}
    )

    $root = ([string]$hit.Root).TrimEnd("\")
    $relDir = [string]$hit.RelDir
    $candidates = New-Object System.Collections.Generic.List[object]
    if ($relDir) {
        $parts = splitIndexRelPath $relDir
        $candidates.Add(@{ Dir = $root; Name = $parts.Name; Rest = $parts.Rest })
        # インデックスのフォルダの中の記録（<インデックス名> のフォルダだけを別の場所へコピーした場合）
        $candidates.Add(@{ Dir = (Join-Path $root $parts.Name); Name = $parts.Name; Rest = $parts.Rest })
    }
    # 検索対象にインデックス名のフォルダ（…\index\<インデックス名>）を直接指定した場合。
    # そのフォルダ自身の記録を先に見て、無ければ親フォルダの記録を見る
    $leaf = Split-Path $root -Leaf
    $candidates.Add(@{ Dir = $root; Name = $leaf; Rest = $relDir })
    $parent = Split-Path $root -Parent
    if ($parent) {
        $candidates.Add(@{ Dir = $parent; Name = $leaf; Rest = $relDir })
    }

    foreach ($candidate in $candidates) {
        if (!$maps.ContainsKey($candidate.Dir)) {
            return @{ Resolved = $false; Location = $null; Pending = $candidate.Dir }
        }
        $map = $maps[$candidate.Dir]
        if ($map.ContainsKey($candidate.Name)) {
            return @{ Resolved = $true; Location = @{ Name = $candidate.Name; Folder = $map[$candidate.Name]; Rest = $candidate.Rest; Known = $true }; Pending = "" }
        }
    }

    # 分からない場合も、インデックス名と、その下の相対フォルダは分かる（検索対象にインデックス名のフォルダを直接指定した場合は Rest がすべて）
    if ($candidates.Count -gt 0) {
        $unknown = @{ Name = $candidates[0].Name; Folder = ""; Rest = $candidates[0].Rest; Known = $false }
    } else {
        $unknown = @{ Name = (Split-Path $root -Leaf); Folder = ""; Rest = ""; Known = $false }
    }
    return @{ Resolved = $true; Location = $unknown; Pending = "" }
}

function getSourceLocation {
    # 検索結果の元のファイルの場所を @{ Name; Folder; Rest; Known } で返す（findSourceLocationInMaps と同じ）。
    # キャッシュに無いフォルダの対応は、読んで maps に足す
    #   maps: フォルダ → getSourceFolderMap の結果 のキャッシュ（読んだ結果を追加する）
    param (
        $hit,
        [hashtable]$maps = @{}
    )

    while ($true) {
        $found = findSourceLocationInMaps $hit $maps
        if ($found.Resolved) {
            return $found.Location
        }
        $maps[$found.Pending] = getSourceFolderMap $found.Pending
    }
}

function readSourceLocation {
    # getSourceLocation の、裏のスレッドから呼ぶ版。$workspace・設定の場所に頼らず、場所を引数で受ける。
    # maps は書き換えず、複製に足して返す: @{ Location; Maps }（呼んだ側が Maps をキャッシュに足す）
    param (
        $hit,
        [hashtable]$maps,
        [string]$statusPath,
        [string]$settingsPath,
        [string]$indexDir
    )

    $copy = $maps.Clone()
    while ($true) {
        $found = findSourceLocationInMaps $hit $copy
        if ($found.Resolved) {
            return @{ Location = $found.Location; Maps = $copy }
        }
        $copy[$found.Pending] = getSourceFolderMap $found.Pending $statusPath $settingsPath $indexDir
    }
}

function findMovedSource {
    # 元のファイルが見つからないとき、選んでもらったフォルダ（picked）の中から探す。
    # picked は元のフォルダ（インデックスのルート）に当たるフォルダでも、その下のどのフォルダ（ファイルのあるフォルダなど）に当たるフォルダでもよい。
    # 上の階層に当たるとみなす方から順に試し、見つかれば @{ Path（見つかったファイル）; Root（元のフォルダに当たるフォルダ。遡れなければ ""） }、
    # 見つからなければ $null を返す。Root を設定に記録すれば（setIndexSourceFolder）、同じインデックスのほかのファイルも開ける
    param (
        [string]$picked,
        [string]$rest,
        [string]$book
    )

    $picked = normalizeFolderPath $picked
    $segments = [string[]]@($rest.Split([char[]]@("\"), [System.StringSplitOptions]::RemoveEmptyEntries))
    for ($skip = 0; $skip -le $segments.Count; $skip++) {
        # 先頭の skip 個のフォルダは picked より上、残りは picked の下にあるとみなす
        $below = [string]::Join("\", $segments, $skip, $segments.Count - $skip)
        $candidate = joinSourcePath $picked $below $book
        if (Test-Path -LiteralPath (toLongPath $candidate) -PathType Leaf) {
            # 選んだフォルダは「元のフォルダ＋先頭 skip 個のフォルダ」に当たるため、skip 個上が元のフォルダに当たる
            $root = $picked
            for ($i = 0; $i -lt $skip -and $root; $i++) {
                $root = Split-Path $root -Parent
            }
            return @{ Path = $candidate; Root = [string]$root }
        }
    }
    return $null
}

function findSourceFileState {
    # 元のファイルを確かめる（getPathState を使う。Test-Path のまま移さない。届かない共有では例外を出さずに
    # $false を返すことがあり、「見つからない」と区別できないため）。ネットワークのパスなら裏のスレッドから呼ぶ想定。
    #   location: getSourceLocation の結果（Folder・Rest・Name を使う。Known は呼ぶ側で見て、$false ならこの関数を呼ばない）
    #   book: 元のファイル名
    #   drives: ドライブの割り当て（テストで差し替える・裏のスレッドでは省いてその場で照会させる）。
    #           ローカルのパスには別名が無いため、ローカルのときはここまで来ない（getDriveTargets を呼ばない）
    # 返すもの: @{ State（Found・Missing・Unreachable・Other）; Path; Alias; Initial; Message }
    #   State=Found: Path に見つかった場所（別名で見つかったときは Alias にその新しい元のフォルダ）
    #   State=Missing: Initial にフォルダ選択の開始フォルダ（無ければ空）
    #   State=Unreachable・Other: Message に例外の文面（接続できない・その他は、上のフォルダも別名も調べない）
    param (
        $location,
        [string]$book,
        $drives = $null
    )

    $path = joinSourcePath $location.Folder $location.Rest $book
    $state = getPathState $path
    if ($state.State -eq ${pathStateFound}) {
        return @{ State = ${pathStateFound}; Path = $path }
    }
    if ($state.State -ne ${pathStateMissing}) {
        return @{ State = $state.State; Message = $state.Message }
    }
    if (testNetworkPath $location.Folder) {
        if ($null -eq $drives) {
            $drives = getDriveTargets
        }
        foreach ($alias in @(getFolderPathAliases $location.Folder $drives | Select-Object -Skip 1)) {
            $candidate = joinSourcePath $alias $location.Rest $book
            if ((getPathState $candidate).State -eq ${pathStateFound}) {
                return @{ State = ${pathStateFound}; Path = $candidate; Alias = $alias }
            }
        }
    }
    return @{ State = ${pathStateMissing}; Initial = (getExistingAncestorFolder $path) }
}

function resolveSourcePath {
    # 検索結果の元のファイルのパスを返す（ファイルがあるかは確かめない）。元のフォルダが分からなければ $null
    #   maps: getSourceLocation のキャッシュ
    param (
        $hit,
        [hashtable]$maps = @{}
    )

    $location = getSourceLocation $hit $maps
    if (!$location.Known) {
        return $null
    }
    return (joinSourcePath $location.Folder $location.Rest $hit.Book)
}

function getConfirmedSourceNames {
    # 利用者が元のフォルダを決めている（確かめ済みの）インデックス名を返す: @{ Confirmed; Crawled }
    #   Confirmed: 設定の targetFolders と indexSources の名前（元のフォルダの記録が設定にあるもの）
    #   Crawled  : そのうち targetFolders の名前（このワークスペースで自分が作ったインデックス）
    # この外のインデックス（content_index\ に手でコピーしたもの）の元のフォルダは、source_folder.txt を書いた人が決めたもの。
    # 設定は小さいローカルのファイルのため、呼ぶたびに読む（キャッシュしない）
    param (
        [string]$settingsPath = ${settingsFile}
    )

    $crawled = @(getTargetFolders $settingsPath | Where-Object { $_.Name } | ForEach-Object { [string]$_.Name })
    $confirmed = @($crawled) + @(readIndexSources $settingsPath | ForEach-Object { [string]$_.Name })
    return @{ Confirmed = [string[]]$confirmed; Crawled = [string[]]$crawled }
}

# インデックスのエクスポート・インポートの判断（目録の確かめ・zip のエントリー名の安全性・名前の決め方）。
# 画面に触らず、ファイルにも触らない（判断層）。

# 目録（tebunko-index.json）の形式
${indexArchiveFormat}            = "tebunko-index"
${indexArchiveFormatVersion}     = 1  # この版が読める形式の版（本文インデックスのファイルの形・zip の中の配置・目録・取り込み一覧の列を変えたら上げる）
${indexArchiveManifestFileName}  = "tebunko-index.json"
${indexArchiveStatusEntryName}   = "ingest_status.tsv"
${indexArchiveMaxManifestBytes}  = 64MB   # 目録（tebunko-index.json）自体の大きさの上限（zip bomb 対策）
${indexArchiveFreeSpaceMargin}   = 1GB    # インポートに求める空き容量の余裕（目録の合計 + この量）

# 同じ名前のインデックスがあったときの扱い（importIndex・getImportIndexName に渡す）
${importCollisionRename}    = "Rename"
${importCollisionOverwrite} = "Overwrite"
${importCollisionCancel}    = "Cancel"


function testPathSegments {
    # 区切り文字で分けたパスの各区切り（segments）が、ファイル名として安全に使えるかを調べ、
    # 使えない理由を返す（使えれば空文字列）。zip のエントリー名（/ 区切り）・取り込み一覧の相対パス（\ 区切り）の
    # どちらからも呼べる、区切り文字に依らない共通の確かめ
    param (
        [string[]]$segments
    )

    foreach ($segment in $segments) {
        if ($segment -eq "" -or $segment -eq "." -or $segment -eq "..") {
            return "使えない区切り（空・.・..）が含まれています。"
        }
        if ($segment.Length -gt ${maxFileNameLength}) {
            return "1 つの区切りが長すぎます（${maxFileNameLength} 文字まで）。"
        }
        if (@([System.IO.Path]::GetInvalidFileNameChars() | Where-Object { $segment.IndexOf($_) -ge 0 }).Count -gt 0) {
            return "使えない文字が含まれています。"
        }
        if ($segment.EndsWith(".") -or $segment.EndsWith(" ")) {
            return "区切りの最後に . や空白は使えません。"
        }
        if (${reservedFileNames} -contains $segment.Split(".")[0].ToUpperInvariant()) {
            return "Windows で使えない名前（$segment）が含まれています。"
        }
    }
    return ""
}


function testIndexArchiveEntryPath {
    # zip のエントリー名（/ 区切り）が、展開先のパスとして安全かを調べ、使えない理由を返す（使えれば空文字列）。
    # \ 区切り・絶対パス（/ 始まり・ドライブ文字・UNC）は、どれも展開先のパスの外に出るおそれがあるため受け付けない（zip slip 対策）
    param (
        [string]$path
    )

    if ($path -eq "") {
        return "エントリーの名前が空です。"
    }
    if ($path.IndexOf("\") -ge 0) {
        return "エントリーの名前に \ が含まれています（/ 区切りにしてください）: ${path}"
    }
    if ($path.StartsWith("/")) {
        return "エントリーの名前が / で始まっています: ${path}"
    }
    if ($path -match "^[A-Za-z]:") {
        return "エントリーの名前がドライブ文字で始まっています: ${path}"
    }
    $reason = testPathSegments ($path.Split("/"))
    if ($reason) {
        return "エントリー「${path}」の名前が使えません（${reason}）"
    }
    return ""
}


function testIndexArchiveEntryLocation {
    # zip のエントリー名（testIndexArchiveEntryPath を通ったもの）が、持ち出すファイルの置き場所として
    # 許されているか（ingest_status.tsv、または content_index/ の下の本文インデックスのファイルの名前の型）を返す
    param (
        [string]$path
    )

    if ($path -ceq ${indexArchiveStatusEntryName}) {
        return $true
    }
    if (!$path.StartsWith("content_index/", [System.StringComparison]::Ordinal)) {
        return $false
    }
    $name = $path.Substring("content_index/".Length)
    if ($name -eq "") {
        return $false
    }
    $lastSlash = $name.LastIndexOf("/")
    $fileName = if ($lastSlash -ge 0) { $name.Substring($lastSlash + 1) } else { $name }
    return ($null -ne (readContentIndexFileName $fileName))
}


function getManifestSourceFolder {
    # 目録の sourceFolder を返す。絶対パス・UNC でない、または制御文字を含むときは空（呼ぶ側に指定させる）
    param (
        $manifest
    )

    $folder = [string]$manifest.sourceFolder
    if ($folder -eq "") {
        return ""
    }
    if ($folder.IndexOfAny([char[]]@(0..31)) -ge 0) {
        return ""
    }
    if ($folder -notmatch "^[A-Za-z]:\\" -and !$folder.StartsWith("\\")) {
        return ""
    }
    return $folder
}


function testIndexArchiveManifest {
    # 目録（ConvertFrom-Json の結果。読めなければ $null）と、zip の中の全エントリー名（目録自身を含む）・
    # 目録エントリーの展開後の大きさから、この zip をインポートしてよいかを調べ、使えない理由を返す（使えれば空文字列）。
    # 1 つでも受け付けない点があればインポート全体を止めるため、最初に見つかった理由だけを返す
    param (
        $manifest,
        [string[]]$entryNames,
        [long]$manifestBytes
    )

    if ($manifestBytes -gt ${indexArchiveMaxManifestBytes}) {
        return "目録（${indexArchiveManifestFileName}）が大きすぎます。"
    }
    if ($null -eq $manifest) {
        return "tebunko のインデックスの zip ではない、または壊れています（目録を読めません）。"
    }
    if ([string]$manifest.format -ne ${indexArchiveFormat}) {
        return "tebunko のインデックスの zip ではない、または壊れています（形式が違います）。"
    }
    $version = 0
    if (-not [int]::TryParse([string]$manifest.formatVersion, [ref]$version) -or $version -lt 1) {
        return "tebunko のインデックスの zip ではない、または壊れています（形式の版が読めません）。"
    }
    if ($version -gt ${indexArchiveFormatVersion}) {
        return "新しい版の tebunko で作られたインデックスのため、この版では読み込めません。"
    }

    $nameReason = testIndexName ([string]$manifest.indexName) @()
    if ($nameReason) {
        return "目録のインデックス名が使えません（${nameReason}）"
    }

    # zip の中に同じ名前のエントリーが 2 つあれば止める（ZipArchive は許すため、ここで数える）
    $seenEntries = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($entryName in $entryNames) {
        if (!$seenEntries.Add($entryName)) {
            return "zip の中に同じ名前のエントリーが 2 つあります: ${entryName}"
        }
    }

    $fileMap = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($file in @($manifest.files | Where-Object { $_ })) {
        $path = [string]$file.path
        $reason = testIndexArchiveEntryPath $path
        if ($reason) {
            return $reason
        }
        if (!(testIndexArchiveEntryLocation $path)) {
            return "目録に、許されない場所のエントリーがあります: ${path}"
        }
        if ($fileMap.ContainsKey($path)) {
            return "目録に同じパスが 2 つあります: ${path}"
        }
        $size = [long]0
        if (-not [long]::TryParse([string]$file.size, [ref]$size) -or $size -lt 0) {
            return "目録のファイルの大きさが読めません: ${path}"
        }
        if ([string]$file.sha256 -eq "") {
            return "目録のファイルの SHA-256 がありません: ${path}"
        }
        $fileMap[$path] = $file
    }
    if (!$fileMap.ContainsKey(${indexArchiveStatusEntryName})) {
        return "目録に ${indexArchiveStatusEntryName} がありません。"
    }

    # zip の中のエントリー（目録自身を除く）が、すべて目録にあるか。目録にあるのに zip に無いものが無いか
    $zipEntries = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($entryName in $entryNames) {
        if ($entryName -ieq ${indexArchiveManifestFileName}) {
            continue
        }
        [void]$zipEntries.Add($entryName)
        if (!$fileMap.ContainsKey($entryName)) {
            return "目録に無いエントリーが zip にあります: ${entryName}"
        }
    }
    foreach ($path in $fileMap.Keys) {
        if (!$zipEntries.Contains($path)) {
            return "目録にあるのに zip に無いエントリーがあります: ${path}"
        }
    }

    return ""
}


function testImportedStatusRelPath {
    # ingest_status.tsv の1行の相対パス（\ 区切り。インデックス名は付いていない）が安全に使えるかを返す（使えれば空文字列）
    param (
        [string]$relPath
    )

    if ($relPath -eq "") {
        return "相対パスが空です。"
    }
    return (testPathSegments ($relPath.Split("\")))
}


function testImportedStatusRow {
    # ingest_status.tsv の1行（列は statusColumns と同じ）が受け付けられるかを返す（使えれば空文字列）
    param (
        [string]$line
    )

    $fields = $line.Split("`t")
    if ($fields.Count -ne ${statusColumns}.Count) {
        return "列の数が違います。"
    }
    if (@(${stateNew}, ${stateDone}, ${stateFailed}) -notcontains $fields[3]) {
        return "状態の値（$($fields[3])）が違います。"
    }
    return (testImportedStatusRelPath $fields[0])
}


function testImportedStatusLines {
    # ingest_status.tsv 全体（見出し行 + データ行）が受け付けられるかを返す（使えれば空文字列）。
    # 見出しが違う・列や状態や相対パスがおかしい行がある・同じ相対パスが2つある、のいずれかで止める
    param (
        [string[]]$lines
    )

    if ($lines.Count -eq 0 -or $lines[0] -ne (${statusColumns} -join "`t")) {
        return "ingest_status.tsv の見出しが違います。"
    }
    $seen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    for ($i = 1; $i -lt $lines.Count; $i++) {
        $line = $lines[$i]
        if ($line -eq "") {
            continue
        }
        $reason = testImportedStatusRow $line
        if ($reason) {
            return "ingest_status.tsv の $($i + 1) 行目が読めません（${reason}）"
        }
        $relPath = $line.Split("`t")[0]
        if (!$seen.Add($relPath)) {
            return "ingest_status.tsv に同じ相対パスが 2 つあります: ${relPath}"
        }
    }
    return ""
}


function getIndexFolderConflict {
    # 元のフォルダが、ほかのクロール対象のインデックスと重なるかを調べ、直してほしい内容を返す（問題なければ空文字列）。
    # 画面の追加と詳細欄の編集（testIndexEditInput）とインポート（importIndex）の両方が使う、1 つの決まり。
    # 同じフォルダは、getTargetFolders が 2 つ目以降を読まないため設定に残らない。入れ子のフォルダは、
    # 同じファイルが 2 つのインデックスに入り、取り込みも検索結果も二重になる
    param (
        [string]$folder,   # 正規化済みの元のフォルダ
        $others            # 比べる相手（Name・Path を持つ行。置き換える・編集中の行は呼び出し側で外しておく）
    )

    foreach ($other in @($others)) {
        if (testSameFolder $other.Path $folder) {
            return "「${folder}」のインデックス [$($other.Name)] が既にあります。"
        }
        if (testFolderUnder $folder $other.Path) {
            return "「${folder}」は、インデックス [$($other.Name)]（$($other.Path)）の中のフォルダです。" +
                "同じファイルが二重にインデックスに入るため、登録できません。検索する範囲を絞るときは［検索］の検索対象で外してください。"
        }
        if (testFolderUnder $other.Path $folder) {
            return "「${folder}」の中には、インデックス [$($other.Name)]（$($other.Path)）があります。" +
                "同じファイルが二重にインデックスに入るため、登録できません。まとめるときは、先に [$($other.Name)] を削除してください。"
        }
    }
    return ""
}


function getImportIndexName {
    # 同じ名前のインデックスがあったときの扱い（collisionMode）から、インポートで使う名前を決める。
    #   Rename    : usedNames と重ならない名前にする（今の newIndexName の決まり「名前(2)」「名前(3)」…）
    #   Overwrite : suggestedName のまま（そのインデックスを置き換える）
    #   Cancel    : 何もしない（$null）
    param (
        [string]$suggestedName,
        $usedNames = @(),
        [string]$collisionMode
    )

    if ($collisionMode -eq ${importCollisionCancel}) {
        return $null
    }
    if ($collisionMode -eq ${importCollisionOverwrite}) {
        return $suggestedName
    }
    return (newIndexName $suggestedName $usedNames)
}


function getExportFileName {
    # エクスポートの既定のファイル名（"<インデックス名>_インデックス_<yyyyMMdd>.zip"）を返す。
    # usedNames（保存先フォルダに既にあるファイル名）と重なれば "(2)" "(3)" … を付ける
    param (
        [string]$indexName,
        $usedNames = @(),
        [datetime]$now = (Get-Date)
    )

    $base = "$(toSafeFileName $indexName)_インデックス_$($now.ToString('yyyyMMdd'))"
    $used = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($usedName in @($usedNames)) {
        if ($usedName) {
            [void]$used.Add([string]$usedName)
        }
    }
    $name = "${base}.zip"
    for ($i = 2; $used.Contains($name); $i++) {
        $name = "${base}(${i}).zip"
    }
    return $name
}

# インデックスのエクスポート・インポート（状態層。zip の読み書き・ワークスペースの書き換え）。
# 画面にも利用者にも問い合わせない（画面なしで呼べる形にする）。安全性の確かめは index_archive_rules.ps1（判断層）で行う。

# System.IO.Compression.ZipFile・ZipArchive は既定では読み込まれていないアセンブリにあるため、ここで読み込む
Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem

function getBytesSha256 {
    # バイト列の SHA-256（16進64文字）を返す
    param (
        [byte[]]$bytes
    )

    $sha = New-Object System.Security.Cryptography.SHA256CryptoServiceProvider
    try {
        return [BitConverter]::ToString($sha.ComputeHash($bytes)).Replace("-", "")
    } finally {
        $sha.Dispose()
    }
}

function writeArchiveBytes {
    # バイト列を zip の1エントリーとして書く
    param (
        $archive,
        [string]$entryPath,
        [byte[]]$bytes
    )

    $entry = $archive.CreateEntry($entryPath, [System.IO.Compression.CompressionLevel]::Optimal)
    $stream = $entry.Open()
    try {
        $stream.Write($bytes, 0, $bytes.Length)
    } finally {
        $stream.Dispose()
    }
}

function writeArchiveFile {
    # ファイルを1つ、ストリームで zip の1エントリーに写す（メモリに全体を読まない）。
    # 写しながら SHA-256 を計算し、@{ Size; Sha256 } を返す
    param (
        $archive,
        [string]$entryPath,
        [string]$sourcePath
    )

    $entry = $archive.CreateEntry($entryPath, [System.IO.Compression.CompressionLevel]::Optimal)
    $share = [System.IO.FileShare]::ReadWrite -bor [System.IO.FileShare]::Delete
    $source = New-Object System.IO.FileStream((toLongPath $sourcePath), [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, $share)
    $sha = New-Object System.Security.Cryptography.SHA256CryptoServiceProvider
    try {
        $size = $source.Length
        $entryStream = $entry.Open()
        try {
            $crypto = New-Object System.Security.Cryptography.CryptoStream($entryStream, $sha, [System.Security.Cryptography.CryptoStreamMode]::Write)
            try {
                $source.CopyTo($crypto)
                $crypto.FlushFinalBlock()
            } finally {
                $crypto.Dispose()
            }
        } finally {
            $entryStream.Dispose()
        }
        return @{ Size = $size; Sha256 = [BitConverter]::ToString($sha.Hash).Replace("-", "") }
    } finally {
        $source.Dispose()
        $sha.Dispose()
    }
}

function exportIndex {
    # 1 つのインデックスを 1 つの zip に書き出す: @{ Name; Path; Files; Bytes }。画面にも利用者にも問い合わせない。
    # インデックス作成のロックを取れなければ例外（ほかで実行中）
    param (
        [string]$name,
        [string]$destPath,
        $ws = $workspace,
        [string]$settingsPath = ${settingsFile}
    )

    $lock = newAppMutex "indexer" $ws.Dir
    if (!$lock.Acquired) {
        $lock.Mutex.Dispose()
        throw "更新中はエクスポートできません。更新が終わってからやり直してください。"
    }
    try {
        return (exportIndexCore $name $destPath $ws $settingsPath)
    } finally {
        $lock.Mutex.ReleaseMutex()
        $lock.Mutex.Dispose()
    }
}

function exportIndexToFolder {
    # 1 つのインデックスを、書き出し先のフォルダの中の zip に書き出す（ファイル名は getExportFileName で決め、
    # フォルダに同じ名前があれば番号を付ける）。書き出し先のフォルダが無ければ例外。戻り値は exportIndex と同じ。
    # 届かないネットワークのフォルダで止まりうるので、画面のスレッドでは呼ばず、別スレッドの仕事の中で呼ぶ
    param (
        [string]$name,
        [string]$folder,
        $ws = $workspace,
        [string]$settingsPath = ${settingsFile}
    )

    if (!(Test-Path -LiteralPath (toLongPath $folder) -PathType Container)) {
        throw "書き出し先のフォルダが見つかりません：$folder"
    }
    $used = @(Get-ChildItem -LiteralPath (toLongPath $folder) -File -ErrorAction SilentlyContinue | ForEach-Object { $_.Name })
    $destPath = Join-Path $folder (getExportFileName $name $used)
    return (exportIndex $name $destPath $ws $settingsPath)
}

function exportIndexes {
    # 選んだインデックスを、書き出し先のフォルダの中の zip にまとめて書き出す（インデックス 1 つにつき zip 1 つ）。
    # 1 つずつ exportIndexToFolder を呼び、途中で 1 つ失敗しても残りを続ける。
    # 戻り値は名前ごとの結果の配列（@{ Name; Ok; Reason; Path }）。Reason は失敗したときの理由（成功なら ""）、Path は書き出した zip（失敗なら ""）。
    # 画面のスレッドでは呼ばず、別スレッドの仕事の中で呼ぶ
    param (
        [string[]]$names,
        [string]$destination,
        $ws = $workspace,
        [string]$settingsPath = ${settingsFile}
    )

    $results = New-Object System.Collections.Generic.List[object]
    foreach ($name in @($names)) {
        try {
            $exported = exportIndexToFolder $name $destination $ws $settingsPath
            $results.Add([pscustomobject]@{ Name = $name; Ok = $true; Reason = ""; Path = $exported.Path })
        } catch {
            $results.Add([pscustomobject]@{ Name = $name; Ok = $false; Reason = $_.Exception.Message; Path = "" })
        }
    }
    return , $results.ToArray()
}

function getIndexExportSize {
    # エクスポートする前に、選んだインデックスが zip に入れる本文インデックスのファイル（*.tsv）の大きさの合計を数える。
    # 戻り値: @{ Bytes（合計のバイト数）; Missing（インデックスのフォルダが無かった名前の配列）}。
    # 数えるのは zip に入る元のファイルの大きさで、zip にした後の大きさではない。
    # 画面のスレッドでは呼ばず、別スレッドの仕事の中で呼ぶ
    param (
        [string[]]$names,
        $ws = $workspace
    )

    $bytes = [long]0
    $missing = New-Object System.Collections.Generic.List[string]
    foreach ($name in @($names)) {
        $indexDir = Join-Path $ws.IndexDir $name
        if (!(Test-Path -LiteralPath (toLongPath $indexDir) -PathType Container)) {
            $missing.Add($name)
            continue
        }
        foreach ($file in [System.IO.Directory]::GetFiles((toLongPath $indexDir), "*.tsv", [System.IO.SearchOption]::AllDirectories)) {
            $bytes += ([System.IO.FileInfo]::new($file)).Length
        }
    }
    return @{ Bytes = $bytes; Missing = $missing.ToArray() }
}

function exportIndexCore {
    param (
        [string]$name,
        [string]$destPath,
        $ws,
        [string]$settingsPath
    )

    $indexDir = Join-Path $ws.IndexDir $name
    if (!(Test-Path -LiteralPath (toLongPath $indexDir) -PathType Container)) {
        throw "インデックス [${name}] が見つかりません。"
    }
    $status = readStatusFile $ws.StatusFile
    if (@($status.Folders | Where-Object { [string]::Equals([string]$_.Name, $name, [System.StringComparison]::OrdinalIgnoreCase) }).Count -eq 0) {
        throw "取り込み一覧に、インデックス [${name}] の記録がありません。"
    }

    # 入れる前の TSV（本文インデックスのファイル以外の *.tsv）が残っていれば、途中で止まったインデックスとして止める
    $longIndexDir = toLongPath $indexDir
    $prefixLength = $indexDir.TrimEnd("\").Length + 1
    $contentIndexFiles = New-Object System.Collections.Generic.List[string]
    # 途中で throw して抜けても下のフォルダを掴んだまま残らないよう、列挙子（EnumerateFiles）でなく配列（GetFiles）で受ける
    foreach ($file in [System.IO.Directory]::GetFiles($longIndexDir, "*.tsv", [System.IO.SearchOption]::AllDirectories)) {
        $rel = (fromLongPath $file).Substring($prefixLength)
        $fileName = [System.IO.Path]::GetFileName($rel)
        if ($null -eq (readContentIndexFileName $fileName)) {
            throw "更新を最後まで行ってからエクスポートしてください（更新の途中のファイルが残っています: ${rel}）。"
        }
        $contentIndexFiles.Add($rel)
    }

    # 取り込み一覧のうち、このインデックスの行だけを抜き出し、相対パスの先頭の "<名前>\" を外す
    $prefix = "$name\"
    $rows = New-Object System.Collections.Generic.List[string]
    $rows.Add((${statusColumns} -join "`t"))
    foreach ($entry in $status.Rows.GetEnumerator()) {
        if ($entry.Key.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) {
            $row = $entry.Value
            $stripped = [pscustomobject]@{
                相対パス = $entry.Key.Substring($prefix.Length); 更新日時 = $row.更新日時; サイズ = $row.サイズ; 状態 = $row.状態
                TSV数 = $row.TSV数; 取り込み日時 = $row.取り込み日時; エラー = $row.エラー; 抽出版 = $row.抽出版
            }
            $rows.Add((toStatusLine $stripped))
        }
    }
    $statusText = [string]::Join("`r`n", $rows) + "`r`n"

    $tmpPath = "${destPath}.tmp"
    [System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName($tmpPath)) | Out-Null
    if (Test-Path -LiteralPath $tmpPath) {
        Remove-Item -LiteralPath $tmpPath -Force
    }

    try {
        $manifestFiles = New-Object System.Collections.Generic.List[object]
        $totalBytes = [long]0
        $archive = [System.IO.Compression.ZipFile]::Open($tmpPath, [System.IO.Compression.ZipArchiveMode]::Create, [System.Text.Encoding]::UTF8)
        try {
            $statusBytes = ${utf8Bom}.GetBytes($statusText)
            writeArchiveBytes $archive ${indexArchiveStatusEntryName} $statusBytes
            $manifestFiles.Add([ordered]@{ path = ${indexArchiveStatusEntryName}; size = [long]$statusBytes.Length; sha256 = (getBytesSha256 $statusBytes) })
            $totalBytes += $statusBytes.Length

            foreach ($rel in $contentIndexFiles) {
                $entryPath = "content_index/" + $rel.Replace("\", "/")
                $written = writeArchiveFile $archive $entryPath (Join-Path $indexDir $rel)
                $manifestFiles.Add([ordered]@{ path = $entryPath; size = [long]$written.Size; sha256 = $written.Sha256 })
                $totalBytes += $written.Size
            }

            $sourceFolder = ""
            $ownFile = readSourceFolderFile $indexDir
            if ($ownFile.ContainsKey($name)) {
                $sourceFolder = $ownFile[$name]
            } else {
                $sourceMap = getSourceFolderMap $ws.IndexDir $ws.StatusFile $settingsPath
                if ($sourceMap.ContainsKey($name)) {
                    $sourceFolder = $sourceMap[$name]
                }
            }
            $version = readVersionFile (Join-Path ${rootDir} "VERSION.txt")
            $manifest = [ordered]@{
                format        = ${indexArchiveFormat}
                formatVersion = ${indexArchiveFormatVersion}
                appVersion    = $(if ($version) { $version.Tag } else { "" })
                exportedAt    = (Get-Date).ToString("yyyy-MM-ddTHH:mm:sszzz")
                indexName     = $name
                sourceFolder  = $sourceFolder
                files         = $manifestFiles.ToArray()
            }
            $manifestJson = ConvertTo-Json -InputObject $manifest -Depth 5
            writeArchiveBytes $archive ${indexArchiveManifestFileName} ((New-Object System.Text.UTF8Encoding($false)).GetBytes($manifestJson))
        } finally {
            $archive.Dispose()
        }
    } catch {
        if (Test-Path -LiteralPath $tmpPath) {
            Remove-Item -LiteralPath $tmpPath -Force -ErrorAction SilentlyContinue
        }
        throw
    }
    try {
        if (Test-Path -LiteralPath $destPath) {
            Remove-Item -LiteralPath $destPath -Force
        }
        [System.IO.File]::Move((toLongPath $tmpPath), (toLongPath $destPath))
    } catch {
        if (Test-Path -LiteralPath $tmpPath) {
            Remove-Item -LiteralPath $tmpPath -Force -ErrorAction SilentlyContinue
        }
        throw
    }
    return @{ Name = $name; Path = $destPath; Files = $manifestFiles.Count; Bytes = $totalBytes }
}

function openIndexArchive {
    # zip を開き、目録（testIndexArchiveManifest）を確かめる。確かめられなければ、開いたアーカイブを閉じて例外にする。
    # 返すもの: @{ Archive; Manifest }（呼んだ側が Archive.Dispose() を行う）
    param (
        [string]$zipPath
    )

    try {
        $archive = [System.IO.Compression.ZipFile]::Open($zipPath, [System.IO.Compression.ZipArchiveMode]::Read, [System.Text.Encoding]::UTF8)
    } catch {
        throw "tebunko のインデックスの zip ではない、または壊れています（$($_.Exception.Message)）。"
    }
    try {
        $entryNames = @($archive.Entries | ForEach-Object { $_.FullName })
        $manifestEntry = $archive.Entries | Where-Object { $_.FullName -ceq ${indexArchiveManifestFileName} } | Select-Object -First 1
        $manifest = $null
        $manifestBytes = [long]0
        if ($null -ne $manifestEntry) {
            $manifestBytes = $manifestEntry.Length
            if ($manifestBytes -le ${indexArchiveMaxManifestBytes}) {
                $reader = New-Object System.IO.StreamReader($manifestEntry.Open(), [System.Text.Encoding]::UTF8)
                try {
                    $json = $reader.ReadToEnd()
                } finally {
                    $reader.Dispose()
                }
                try {
                    $manifest = ConvertFrom-Json $json
                } catch {
                    $manifest = $null
                }
            }
        }
        $reason = testIndexArchiveManifest $manifest $entryNames $manifestBytes
        if ($reason) {
            throw $reason
        }
        return @{ Archive = $archive; Manifest = $manifest }
    } catch {
        $archive.Dispose()
        throw
    }
}

function readIndexArchiveInfo {
    # 目録だけを読んで確かめる（インポートせずに、画面が既定の名前・元のフォルダ・合計の大きさを出すために使う）。
    # 返すもの: @{ IndexName; SourceFolder; Files; Bytes; FormatVersion; AppVersion; ExportedAt（目録の exportedAt のまま。無ければ空） }
    param (
        [string]$zipPath
    )

    $opened = openIndexArchive $zipPath
    try {
        $manifest = $opened.Manifest
        $bytes = [long]0
        foreach ($file in @($manifest.files)) {
            $bytes += [long]$file.size
        }
        return @{
            IndexName     = [string]$manifest.indexName
            SourceFolder  = (getManifestSourceFolder $manifest)
            Files         = @($manifest.files).Count
            Bytes         = $bytes
            FormatVersion = [int]$manifest.formatVersion
            AppVersion    = [string]$manifest.appVersion
            ExportedAt    = [string]$manifest.exportedAt
        }
    } finally {
        $opened.Archive.Dispose()
    }
}

function getImportArchiveInfo {
    # readIndexArchiveInfo の結果に、元のフォルダがこの PC にあるか（SourceExists）を足して返す（インポートの裏の仕事で使う）。
    # 目録の元のフォルダは zip の送り手が自由に書けるため、ネットワークの場所なら接続せず（Test-Path を呼ばず）$null（分からない）にする。
    # 利用者が元のフォルダを見て確かめる前に、サインイン情報が相手のサーバーへ送られないようにするため
    param (
        [string]$zipPath
    )

    $info = readIndexArchiveInfo $zipPath
    $exists = $false
    try {
        $folder = normalizeFolderPath ([string]$info.SourceFolder)
        if (testLocalDrivePath $folder) {
            $exists = [bool](Test-Path -LiteralPath $folder -PathType Container)
        } elseif ($folder) {
            # ローカルのドライブと分かるときだけ調べる。ネットワークの場所や、デバイス名の形（\\.\UNC\・\\.\GLOBALROOT\ など）は
            # 調べず「分からない」にする
            $exists = $null
        }
    } catch {
        # 使えない文字を含むなど。無いものとして扱う
    }
    $info.SourceExists = $exists
    return $info
}

function getImportUsedIndexNames {
    # 今使われているインデックス名（設定の targetFolders・indexSources、content_index\ 直下のフォルダ、
    # 取り込み一覧のクロール対象フォルダの行）を集めて返す（大文字・小文字を区別しない集合）
    param (
        $ws,
        [string]$settingsPath
    )

    $names = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($folder in @(getTargetFolders $settingsPath)) {
        if ($folder.Name) {
            [void]$names.Add($folder.Name)
        }
    }
    foreach ($source in @(readIndexSources $settingsPath)) {
        if ($source.Name) {
            [void]$names.Add($source.Name)
        }
    }
    if (Test-Path -LiteralPath (toLongPath $ws.IndexDir) -PathType Container) {
        foreach ($dir in [System.IO.Directory]::GetDirectories((toLongPath $ws.IndexDir))) {
            [void]$names.Add([System.IO.Path]::GetFileName($dir))
        }
    }
    foreach ($folder in (readStatusFile $ws.StatusFile).Folders.ToArray()) {
        if ($folder.Name) {
            [void]$names.Add($folder.Name)
        }
    }
    return , $names
}

function extractArchiveEntryToFile {
    # zip のエントリーを、目録の大きさ（expectedSize）を超えないようストリームで写す。
    # 書き終えたら大きさと SHA-256 を比べ、違えば例外にする（写したファイルは呼び出し側が消す）
    param (
        $entry,
        [long]$expectedSize,
        [string]$expectedSha256,
        [string]$destPath
    )

    [System.IO.Directory]::CreateDirectory([System.IO.Path]::GetDirectoryName((toLongPath $destPath))) | Out-Null
    $source = $entry.Open()
    $sha = New-Object System.Security.Cryptography.SHA256CryptoServiceProvider
    $total = [long]0
    try {
        $dest = New-Object System.IO.FileStream((toLongPath $destPath), [System.IO.FileMode]::Create, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
        try {
            $buffer = New-Object byte[] 1MB
            while ($true) {
                $read = $source.Read($buffer, 0, $buffer.Length)
                if ($read -le 0) {
                    break
                }
                $total += $read
                if ($total -gt $expectedSize) {
                    throw "エントリー「$($entry.FullName)」が目録の大きさより大きく展開されました。"
                }
                [void]$sha.TransformBlock($buffer, 0, $read, $buffer, 0)
                $dest.Write($buffer, 0, $read)
            }
        } finally {
            $dest.Dispose()
        }
        [void]$sha.TransformFinalBlock([byte[]]@(), 0, 0)
        $actualHash = [BitConverter]::ToString($sha.Hash).Replace("-", "")
    } finally {
        $source.Dispose()
        $sha.Dispose()
    }
    if ($total -ne $expectedSize -or $actualHash -ne $expectedSha256) {
        throw "エントリー「$($entry.FullName)」の大きさか内容が目録と違います。"
    }
}

function getWorkspaceFreeSpace {
    # root（ドライブのルート）の空き容量（バイト）を返す。UNC（\\server\share）など、ドライブとして扱えず調べられないときは $null
    # （調べられないだけでインポートを止めない。呼び出し側が確かめを飛ばす）
    param (
        [string]$root
    )

    try {
        return ([System.IO.DriveInfo]$root).AvailableFreeSpace
    } catch {
        return $null
    }
}

function importIndex {
    # zip から 1 つのインデックスをインポートする: @{ Name; SourcePath; Enabled; Files; Bytes; Warnings }。
    # collisionMode（Rename・Overwrite・Cancel）が Cancel なら $null を返す（ワークスペースは変えない）。
    # name・sourceFolder を省くと目録の値を使う。インデックス作成のロックを取れなければ例外
    param (
        [string]$zipPath,
        [string]$collisionMode,
        [string]$name = "",
        [string]$sourceFolder = "",
        $ws = $workspace,
        [string]$settingsPath = ${settingsFile},
        [scriptblock]$getFreeSpace = { param ($root) getWorkspaceFreeSpace $root }
    )

    $lock = newAppMutex "indexer" $ws.Dir
    if (!$lock.Acquired) {
        $lock.Mutex.Dispose()
        throw "更新中はインポートできません。更新が終わってからやり直してください。"
    }
    try {
        return (importIndexCore $zipPath $collisionMode $name $sourceFolder $ws $settingsPath $getFreeSpace)
    } finally {
        $lock.Mutex.ReleaseMutex()
        $lock.Mutex.Dispose()
    }
}

function testImportFreeSpace {
    # 空き容量が「目録の合計 + 余裕」に足りなければ、理由を返す（足りていれば空文字列）。
    # 空き容量を調べられないとき（getFreeSpace が $null を返す・例外になる。UNC のワークスペースなど）は確かめない
    param (
        [long]$totalBytes,
        [string]$root,
        [scriptblock]$getFreeSpace
    )

    $freeSpace = $null
    try {
        $freeSpace = & $getFreeSpace $root
    } catch {
    }
    if ($null -eq $freeSpace) {
        return ""
    }
    $needed = $totalBytes + ${indexArchiveFreeSpaceMargin}
    if ($freeSpace -lt $needed) {
        return "保存先の空き容量が足りません（必要 約 $([Math]::Ceiling($needed / 1MB)) MB）。"
    }
    return ""
}

function expandImportArchive {
    # 7. 目録にあるエントリーを作業フォルダ（<workDir>\new）に展開する（目録のパスからだけ作る。エントリーの名前からは作らない）。
    # 書き込む前に、大きさと SHA-256 を目録と比べる。source_folder.txt もここで作る。
    # 返すもの: @{ NewDir; Rows }（Rows は取り込み一覧に足す行。相対パスの先頭にインデックス名を付けたもの）。
    # 途中で失敗したら、作業フォルダを消して例外にする
    param (
        $archive,
        $fileEntries,
        [string]$workDir,
        [string]$finalName,
        [string]$folder
    )

    $newDir = Join-Path $workDir "new"
    removeDirectoryRetry $workDir
    [System.IO.Directory]::CreateDirectory((toLongPath $newDir)) | Out-Null
    try {
        $statusTmpPath = Join-Path $workDir ${indexArchiveStatusEntryName}
        $statusLines = $null
        foreach ($file in $fileEntries) {
            $path = [string]$file.path
            $entry = $archive.GetEntry($path)
            if ($null -eq $entry) {
                throw "目録にあるのに zip に無いエントリーがあります: ${path}"
            }
            $size = [long]$file.size
            $sha256 = [string]$file.sha256
            if ($path -ceq ${indexArchiveStatusEntryName}) {
                extractArchiveEntryToFile $entry $size $sha256 $statusTmpPath
                $bytes = [System.IO.File]::ReadAllBytes((toLongPath $statusTmpPath))
                $text = ${utf8Bom}.GetString($bytes)
                $statusLines = @($text -split "\r?\n" | Where-Object { $_ -ne "" })
                $reason = testImportedStatusLines $statusLines
                if ($reason) {
                    throw "ingest_status.tsv を読み込めません（${reason}）"
                }
            } else {
                $rel = $path.Substring("content_index/".Length).Replace("/", "\")
                extractArchiveEntryToFile $entry $size $sha256 (Join-Path $newDir $rel)
            }
        }
        if ($null -eq $statusLines) {
            throw "目録に ${indexArchiveStatusEntryName} がありません。"
        }

        $rows = New-Object System.Collections.Generic.List[object]
        foreach ($line in @($statusLines | Select-Object -Skip 1)) {
            $fields = $line.Split("`t")
            $rows.Add((newStatusRow "${finalName}\$($fields[0])" $fields[1] $fields[2] $fields[3] $fields[4] $fields[5] $fields[6] $fields[7]))
        }

        $header = "# 検索結果から元のファイルを開くときに使う、インデックス名とクロール対象フォルダの対応です（インデックス作成のたびに作り直します）"
        writeListFile (Join-Path $newDir ${sourceFolderFileName}) @($header, "${finalName}`t${folder}")
        return @{ NewDir = $newDir; Rows = $rows.ToArray() }
    } catch {
        removeDirectoryRetry $workDir
        throw
    }
}

function restoreImportedSettings {
    # registerImportedIndexInSettings で変える前の内容（before）に、設定の 3 つの項目（クロール対象・検索だけのインデックス・検索から外したフォルダ）を戻す。
    # ほかの項目には触らない
    param (
        $before,
        [string]$settingsPath
    )

    invokeSettingsLocked -path $settingsPath -action {
        writeTargetFolders $before.Targets $settingsPath
        if ($before.SourcesChanged) {
            writeIndexSources $before.Sources $settingsPath
        }
        if ($before.ExcludesChanged) {
            writeSearchExcludes $before.Excludes $settingsPath
        }
    } | Out-Null
}

function registerImportedIndexInSettings {
    # 8. 設定にインデックスを登録する（クロール対象に名前と元のフォルダを入れる。同じ名前があれば置き換え、同じ名前の検索だけのインデックスは外す。
    # 上書きなら、前のインデックスの検索から外したフォルダの記録も消す）。
    # 途中で失敗したら、変える前に戻して例外にする。成功したら、戻すための @{ Targets; Sources; Excludes; SourcesChanged; ExcludesChanged } を返す
    param (
        [string]$finalName,
        [string]$folder,
        [bool]$overwrite,
        [string]$indexDir,
        [string]$settingsPath
    )

    $before = invokeSettingsLocked -path $settingsPath -action {
        return @{
            Targets = @(getTargetFolders $settingsPath); Sources = @(readIndexSources $settingsPath)
            Excludes = @(readSearchExcludes $settingsPath); SourcesChanged = $false; ExcludesChanged = $false
        }
    }
    try {
        invokeSettingsLocked -path $settingsPath -action {
            $enabled = [System.IO.Directory]::Exists((toLongPath $folder))
            $entry = [pscustomobject]@{ Name = $finalName; Path = $folder; Enabled = $enabled }
            $targets = New-Object System.Collections.Generic.List[object]
            $found = $false
            foreach ($target in $before.Targets) {
                if ($target.Name -ieq $finalName) {
                    $targets.Add($entry)
                    $found = $true
                } else {
                    $targets.Add($target)
                }
            }
            if (!$found) {
                $targets.Add($entry)
            }
            writeTargetFolders $targets.ToArray() $settingsPath
            if (@($before.Sources | Where-Object { $_.Name -ieq $finalName }).Count -gt 0) {
                $before.SourcesChanged = $true
                writeIndexSources @($before.Sources | Where-Object { $_.Name -ine $finalName }) $settingsPath
            }
            if ($overwrite) {
                $before.ExcludesChanged = $true
                [void](removeSearchExcludesUnder $indexDir $settingsPath)
            }
        } | Out-Null
    } catch {
        restoreImportedSettings $before $settingsPath
        throw
    }
    return $before
}

function swapInImportedIndexDir {
    # 9. content_index\<名前> を展開したフォルダ（newDir）に入れ替える。前のフォルダは previous に退避する。
    # 失敗したら、退避したフォルダを戻して例外にする。成功したら、戻すための @{ TargetDir; PreviousDir; HadPrevious } を返す
    param (
        [string]$newDir,
        [string]$targetDir,
        [string]$previousDir,
        [string]$indexRoot
    )

    # ウイルス対策ソフトが、作ったばかり・書いたばかりのフォルダ（$targetDir は前の取り込みで、$newDir はこの
    # インポートの展開で、それぞれ書いたばかり）を一時的に掴んでいることがあるため、moveDirectoryRetry で試し直す
    # （removeDirectoryRetry と同じ理由。docs/design/index-data/format.md「インポート」を参照）
    $hadPrevious = Test-Path -LiteralPath (toLongPath $targetDir) -PathType Container
    if ($hadPrevious) {
        moveDirectoryRetry $targetDir $previousDir
    }
    try {
        [System.IO.Directory]::CreateDirectory((toLongPath $indexRoot)) | Out-Null
        moveDirectoryRetry $newDir $targetDir
    } catch {
        if ($hadPrevious) {
            moveDirectoryRetry $previousDir $targetDir
        }
        throw
    }
    return @{ TargetDir = $targetDir; PreviousDir = $previousDir; HadPrevious = $hadPrevious }
}

function restoreSwappedIndexDir {
    # swapInImportedIndexDir で入れ替えたフォルダを、入れ替える前に戻す（入れたものを消し、退避した前のフォルダを戻す）
    param (
        $swap
    )

    removeDirectoryRetry $swap.TargetDir
    if ($swap.HadPrevious) {
        moveDirectoryRetry $swap.PreviousDir $swap.TargetDir
    }
}

function rewriteStatusForImport {
    # 10. 取り込み一覧を書き直す（このインデックスの前のクロール対象フォルダの行と各行を消し、新しい行を足す）。
    # ほかのインデックスの行は残す。見出しの行を含め、インデクサが書くのと同じ形（writeStatusFile）で書く
    param (
        [string]$statusPath,
        [string]$finalName,
        [string]$folder,
        $importedRows
    )

    $status = readStatusFile $statusPath
    $folders = New-Object System.Collections.Generic.List[object]
    foreach ($other in $status.Folders) {
        if (![string]::Equals($other.Name, $finalName, [System.StringComparison]::OrdinalIgnoreCase)) {
            $folders.Add($other)
        }
    }
    $folders.Add([pscustomobject]@{ Path = $folder; Name = $finalName })

    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($row in $status.Rows.Values) {
        if (![string]::Equals((splitIndexRelPath $row.相対パス).Name, $finalName, [System.StringComparison]::OrdinalIgnoreCase)) {
            $rows.Add($row)
        }
    }
    foreach ($row in $importedRows) {
        $rows.Add($row)
    }
    writeStatusFile $folders.ToArray() $rows.ToArray() $statusPath
}

function importIndexCore {
    param (
        [string]$zipPath,
        [string]$collisionMode,
        [string]$name,
        [string]$sourceFolder,
        $ws,
        [string]$settingsPath,
        [scriptblock]$getFreeSpace
    )

    # 前の版のワークスペース（index\ あり・content_index\ が空）を、取り込み直しを始めるときと同じ手順で片付ける。
    # content_index\ にこのインポートの分を足す前に行う（片付けに失敗したら、以降は行わない）
    $legacyState = getLegacyIndexState $ws.Dir
    if (testLegacyCleanupNeeded $legacyState) {
        $cleanup = clearLegacySystemIndex $ws.Dir
        if (!$cleanup.Ok) {
            throw "前の版のインデックス（高速検索用）を片付けられませんでした（$($cleanup.Reason)）。tebunko の画面やエクスプローラーで開いていれば閉じてから、もう一度インポートしてください。"
        }
    }

    $opened = openIndexArchive $zipPath
    $archive = $opened.Archive
    try {
        $manifest = $opened.Manifest
        $suggestedName = if ($name) { $name } else { [string]$manifest.indexName }
        # 集合を返す関数なので、@() で包まない（包むと集合が 1 要素の配列になり、newIndexName が名前を突き合わせられず、
        # 「別名」でも同じ名前のインデックスを上書きしてしまう）
        $usedNames = getImportUsedIndexNames $ws $settingsPath
        $finalName = getImportIndexName $suggestedName $usedNames $collisionMode
        if ($null -eq $finalName) {
            return $null
        }
        $nameReason = testIndexName $finalName @()
        if ($nameReason) {
            throw $nameReason
        }
        $overwrite = ($collisionMode -eq ${importCollisionOverwrite})

        $folder = if ($sourceFolder) { normalizeFolderPath $sourceFolder } else { getManifestSourceFolder $manifest }
        if ($folder -eq "") {
            throw "元のフォルダを指定してください。"
        }

        $totalBytes = [long]0
        $fileEntries = @($manifest.files)
        foreach ($file in $fileEntries) {
            $totalBytes += [long]$file.size
        }
        $spaceReason = testImportFreeSpace $totalBytes ([System.IO.Path]::GetPathRoot($ws.Dir)) $getFreeSpace
        if ($spaceReason) {
            throw $spaceReason
        }

        # 同じ元のフォルダが、別の名前のクロール対象フォルダに既にある・入れ子になっていれば止める（getTargetFolders は同じフォルダの 2 つ目以降を読まないため、
        # 登録しても設定に残らず、次のインデックス作成の確認に、このインデックスが「削除予定」として出る。画面の追加・編集と同じ getIndexFolderConflict の決まり）。
        # 検索だけのインデックス（indexSources）の元のフォルダと同じなら、止めずに知らせる
        $conflict = getIndexFolderConflict $folder @(getTargetFolders $settingsPath | Where-Object { $_.Name -ine $finalName })
        if ($conflict -ne "") {
            throw $conflict
        }
        $warnings = New-Object System.Collections.Generic.List[string]
        foreach ($other in @(readIndexSources $settingsPath | Where-Object { $_.Name -ine $finalName })) {
            if (testSameFolder $other.Path $folder) {
                $warnings.Add("元のフォルダ「${folder}」は、インデックス [$($other.Name)] としても登録されています。")
                break
            }
        }

        $workDir = Join-Path $ws.PublishDir "import"
        $expanded = expandImportArchive $archive $fileEntries $workDir $finalName $folder
        $targetIndexDir = Join-Path $ws.IndexDir $finalName
        try {
            $before = registerImportedIndexInSettings $finalName $folder $overwrite $targetIndexDir $settingsPath
            try {
                $swap = swapInImportedIndexDir $expanded.NewDir $targetIndexDir (Join-Path $workDir "previous") $ws.IndexDir
                # Directory.Move で入れたフォルダは、work\content_index の NotContentIndexed を受け継がない。
                # 根に付いたあとの -Recurse は中へ降りないため（publish.md）、入れた直後に付ける（失敗しても止めない）
                setNotContentIndexed $targetIndexDir -Recurse | Out-Null
                try {
                    rewriteStatusForImport $ws.StatusFile $finalName $folder $expanded.Rows
                } catch {
                    restoreSwappedIndexDir $swap
                    throw
                }
            } catch {
                restoreImportedSettings $before $settingsPath
                throw
            }
        } catch {
            removeDirectoryRetry $workDir
            throw
        }

        # 11. 上書きなら、前のシステムインデックスを消す（消せなくても続ける。次のインデックス作成で整理される）
        if ($overwrite) {
            removeSystemIndexOfWorkspace $finalName $ws.IndexDir
        }
        # 12. 作業フォルダを消す
        removeDirectoryRetry $workDir

        return @{
            Name = $finalName; SourcePath = $folder; Enabled = [System.IO.Directory]::Exists((toLongPath $folder))
            Files = $fileEntries.Count; Bytes = $totalBytes; Warnings = $warnings.ToArray()
        }
    } finally {
        $archive.Dispose()
    }
}

# インデックス作成の部品の読み込み口。indexer.ps1 と、取り込みのスレッド（indexer_run.ps1 の ingestWorkerScript）が dot-source する。
# 画面は読み込まない（インデックス作成は、画面のインデクサのスレッドが indexer.ps1 を実行して行う）

# Word（.docx / .docm）・PowerPoint（.pptx / .pptm）のファイルと、Excel（.xlsx / .xlsm）の図形・コメントからテキストを読み出す。
# ファイルはZIP（Office Open XML）として直接読むため、Word・PowerPoint・Excelは使わない。
# インデクサ・テストから dot-source して使う。共通の部品（shared.ps1）を先に読み込んでおくこと。
#
# 読み出した結果は「場所 → 行の一覧」の順序付き辞書（ユニット）で返す。
#   Word      : ページ001, ページ001[図形], ページ001[コメント], ページ001[埋め込み1], ページ002, ..., ヘッダー・フッター, 脚注
#   PowerPoint: スライド001, スライド001[図形], スライド001[コメント], スライド001[埋め込み1], スライド001_ノート, スライド002（非表示）, ..., ヘッダー・フッター
#   Excel     : <シート名>[図形]（グラフ・SmartArt の文字を含む。表示のグラフシートも含む）, <シート名>[コメント],
#              <シート名>[ヘッダー・フッター]（セルの値はインデクサが Excel で読む）
# 1行は段落1つ、または表の1行（セルをタブ区切り）。図形・コメントの場所は図形・コメント1つ
# （Word・PowerPoint は文字だけ、Excel は "<セル番地><TAB><文字>"）。
# 埋め込みの場所は、埋め込んだ Office のファイル（Office Open XML）1 つの中の文字をまとめたもの
# （office_embedded.ps1。[埋め込み<N>] の N は 1 ファイルの中の通し番号）。

Add-Type -AssemblyName System.IO.Compression
Add-Type -AssemblyName System.IO.Compression.FileSystem

${nsWord}    = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
${nsDrawing} = "http://schemas.openxmlformats.org/drawingml/2006/main"
${nsPresent} = "http://schemas.openxmlformats.org/presentationml/2006/main"
${nsCompat}  = "http://schemas.openxmlformats.org/markup-compatibility/2006"
${nsRel}     = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"
${nsPkgRel}  = "http://schemas.openxmlformats.org/package/2006/relationships"
${nsDiagram} = "http://schemas.openxmlformats.org/drawingml/2006/diagram"
${nsChart}   = "http://schemas.openxmlformats.org/drawingml/2006/chart"
${nsOffice}  = "urn:schemas-microsoft-com:office:office"

# PowerPointで読み飛ばすプレースホルダー（スライド番号・日付・ヘッダー・フッター・スライド画像）
${skipPlaceholderTypes} = @("sldNum", "dt", "hdr", "ftr", "sldImg")

# ZIPの部品（ファイル）1つの展開後の大きさと、1ファイルの合計（readDocxUnits・readPptxUnits・
# readXlsxObjectUnitsがファイルを開くたびに0から数える）の上限。どちらもバイト（entry.Lengthと同じ単位）。
# ZIP爆弾（小さく圧縮した巨大な部品）・部品を大量に並べたファイルでメモリを使い切るのを防ぐ（readZipEntry）。
# setting.config には出さない定数（値を変えたい場合は docs/design/indexing/known-issues.md を参照）。
# $script: の変数は読み取りのスレッド（runspace）ごとに別になる。ファイルの合計はスレッドごとに独立して
# 数えたいので都合がよい（テストから一時的に値を変えるときは、この $script: を直接上書きする）
$script:zipPartMaxBytes = 100MB
$script:zipTotalMaxBytes = 300MB
# シートの部品を流れで読む（readXlsxSheetHeaderFooter）ときの、展開後の大きさ（バイト）の上限。流れ読みは文字列にしない
# のでメモリを使わず、かかるのは時間だけ。シートは sheetData が大きく、実在のブックでも部品の上限（100MB）を超えうる
# ため、部品の上限より大きい別の値にする（超えたシートは、そのシートのヘッダー・フッターだけ読めなかった扱い）。
# 1ファイルの合計（zipTotalMaxBytes）には数えないので、シートごとに最大この大きさまで読む
$script:zipSheetStreamMaxBytes = 1000MB
# 1ファイルの合計（バイト）。readZipEntry が確保する大きさ（entry.Length）を足していく
$script:zipTotalReadBytes = 0

# サイズの上限を超えた（ZIP爆弾・巨大なXML等の見込み）ときに投げる、利用者向けの短い文言。
# 画面には部品ごとか合計かの区別・部品名・大きさを出さない（分かると悪用のヒントになるため）。
# 原因を調べられるよう、部品名・大きさ・部品ごとか合計かはインデックス作成のログにだけ書く。
# shared/ はツール（インデックス作成のログ）を知らないため、ここでは書かず、
# ZipSizeLimitException のプロパティで呼び出し元（tebunko/indexer）に伝える
$script:zipTooLargeMessage = "ファイルサイズが大きすぎるため更新できません。"

class ZipSizeLimitException : System.Exception {
    # .Message は今までどおり利用者向けの簡潔な文言のまま（$script:zipTooLargeMessage）。
    # 部品名・大きさ・部品ごとか合計かは、ここのプロパティにだけ持ち、呼び出し元がインデックス作成のログに書く
    [string]$PartName     # ZIP内のパス（例: "word/document.xml"）
    [long]$MeasuredBytes  # 超えたと分かった時点の大きさ（バイト）。偽りのヘッダーのときは、実際の大きさまでは分からないため、検出できた時点の値
    [string]$LimitKind    # "Part"（部品ごとの上限。偽りのヘッダーを含む）または "Total"（1ファイルの合計の上限）

    ZipSizeLimitException([string]$message, [string]$partName, [long]$measuredBytes, [string]$limitKind) : base($message) {
        $this.PartName = $partName
        $this.MeasuredBytes = $measuredBytes
        $this.LimitKind = $limitKind
    }
}

function isZipFile {
    # ファイルの先頭がZIPのシグネチャ（PK\x03\x04）かどうか。
    # パスワード付きのOfficeファイルや旧形式は、拡張子が .docx 等でもZIPではない
    param (
        [string]$path
    )

    $stream = [System.IO.File]::OpenRead((toLongPath $path))
    try {
        $head = New-Object byte[] 4
        $read = $stream.Read($head, 0, 4)
        return ($read -eq 4 -and $head[0] -eq 0x50 -and $head[1] -eq 0x4B -and $head[2] -eq 0x03 -and $head[3] -eq 0x04)
    } finally {
        $stream.Dispose()
    }
}

function isCompoundFile {
    # ファイルの先頭が複合ドキュメント形式（旧形式の .doc / .ppt、パスワード付きのOfficeファイル）のシグネチャかどうか
    param (
        [string]$path
    )

    $signature = [byte[]](0xD0, 0xCF, 0x11, 0xE0, 0xA1, 0xB1, 0x1A, 0xE1)
    $stream = [System.IO.File]::OpenRead((toLongPath $path))
    try {
        $head = New-Object byte[] 8
        if ($stream.Read($head, 0, 8) -ne 8) {
            return $false
        }
        for ($i = 0; $i -lt 8; $i++) {
            if ($head[$i] -ne $signature[$i]) {
                return $false
            }
        }
        return $true
    } finally {
        $stream.Dispose()
    }
}

# 読み取りのスレッド（runspace）ごとに使い回す、部品の読み取り用の入れ物。大きな部品を読むときに、
# 部品の大きさぶんの配列を毎回確保しない（ラージオブジェクトヒープに乗らない大きさ（85,000 バイト
# 未満。既定 32768 バイト）にとどめ、GC の負担を減らす）
$script:zipReadBufferSize = 32768
$script:zipReadBuffer = $null

function checkZipEntrySize {
    # 部品の展開後の大きさ（entry.Length）を、部品ごとの上限（zipPartMaxBytes）と1ファイルの合計の上限
    # （zipTotalMaxBytes）に照らして数え、超えれば ZipSizeLimitException にする。超えなければ大きさを返す
    # （readZipEntry・readZipEntryBytes が、読む前に呼ぶ。合計は「確保する大きさ」で数える）
    param (
        [System.IO.Compression.ZipArchiveEntry]$entry,
        [string]$entryName
    )

    $length = $entry.Length
    if ($length -gt $script:zipPartMaxBytes) {
        throw [ZipSizeLimitException]::new($script:zipTooLargeMessage, $entryName, $length, "Part")
    }
    $script:zipTotalReadBytes += $length
    if ($script:zipTotalReadBytes -gt $script:zipTotalMaxBytes) {
        throw [ZipSizeLimitException]::new($script:zipTooLargeMessage, $entryName, $script:zipTotalReadBytes, "Total")
    }
    return $length
}

function readZipEntryBytes {
    # ZIP内のファイルをバイト列で返す。無ければ $null（埋め込んだファイルを読むときに使う。ふつうの部品は readZipEntry）。
    # 大きさの数え方と上限は readZipEntry と同じ。バイト列は申告の大きさ（entry.Length。上限の範囲内）だけ確保し、
    # 読み終えたあとにもう 1 バイト読めたら、中身がヘッダーより長い（偽りのヘッダー）として部品ごとの上限の超過にする
    param (
        [System.IO.Compression.ZipArchive]$zip,
        [string]$entryName
    )

    $entry = $zip.GetEntry($entryName)
    if ($null -eq $entry) {
        return $null
    }

    $length = checkZipEntrySize $entry $entryName
    $bytes = New-Object byte[] ([int]$length)
    $filled = 0
    $stream = $entry.Open()
    try {
        while ($filled -lt $length) {
            $read = $stream.Read($bytes, $filled, [int]($length - $filled))
            if ($read -le 0) {
                break
            }
            $filled += $read
        }
        if ($filled -eq $length -and $stream.ReadByte() -ge 0) {
            throw [ZipSizeLimitException]::new($script:zipTooLargeMessage, $entryName, $length + 1, "Part")
        }
    } finally {
        $stream.Dispose()
    }
    if ($filled -lt $length) {
        $shortBytes = New-Object byte[] $filled
        [System.Array]::Copy($bytes, $shortBytes, $filled)
        $bytes = $shortBytes
    }
    return , $bytes
}

function readZipEntry {
    # ZIP内のファイルを文字列で返す。無ければ $null。
    #
    # 展開後の大きさ（entry.Length。中央ディレクトリの値）が部品ごとの上限（zipPartMaxBytes）を超える、
    # または1ファイルの合計（zipTotalReadBytes）が合計の上限（zipTotalMaxBytes）を超えると例外にする。
    # 合計は、実際に読んだ量ではなく「確保する大きさ」（entry.Length）で、読む前に数える
    # （ヘッダーの大きさを偽って中身を小さくした部品を並べても、合計の上限で打ち切るため）。
    #
    # entry.Length の値は、細工して実際より小さく書き換えられる（偽りのヘッダー）。これを見つけるため、
    # 実際に読む量を Length + 1 バイトまでに絞る（入れ物は小さく使い回し、1回ごとの Stream.Read の
    # 要求バイト数を「残り（Length + 1 - 既読量）」で頭打ちにする）。既読量が Length + 1 バイトに届いたら、
    # 中身がヘッダーより長いと分かるので、そこで止めて例外にする。展開はここで必ず止まり、
    # 上限のバイト数を超えて進まない（部品の大きさぶんの配列は作らない）。
    #
    # 読んだバイト列は、今までの StreamReader（UTF-8を指定し、BOMを見て文字コードを決める）と同じ規則で
    # 文字列にする（BOM付きUTF-8・UTF-16 LE/BEを見分け、無ければUTF-8）。入れ物（$script:zipReadBuffer）に
    # 入った分だけ Decoder で文字に直し、StringBuilder に積む（文字の境界がまたがっても Decoder が覚える）
    param (
        [System.IO.Compression.ZipArchive]$zip,
        [string]$entryName
    )

    $entry = $zip.GetEntry($entryName)
    if ($null -eq $entry) {
        return $null
    }

    $length = checkZipEntrySize $entry $entryName

    if ($null -eq $script:zipReadBuffer) {
        # BOM の見分けに先頭 3 バイトが要るため、3 より小さくしない
        $script:zipReadBuffer = New-Object byte[] ([Math]::Max(3, $script:zipReadBufferSize))
    }
    $buffer = $script:zipReadBuffer
    $budget = $length + 1  # 偽りのヘッダーを見つけるため、読む量はこれより増やさない
    $totalRead = 0L
    $sb = New-Object System.Text.StringBuilder  # 容量は渡さない（申告の大きさぶんを先に確保しないため）
    $decoder = $null
    $charBuffer = $null
    $first = $true

    $stream = $entry.Open()
    try {
        while ($totalRead -lt $budget) {
            $want = [Math]::Min($buffer.Length, [long]($budget - $totalRead))
            $filled = 0
            $endOfStream = $false
            while ($filled -lt $want) {
                $read = $stream.Read($buffer, $filled, [int]($want - $filled))
                if ($read -le 0) {
                    $endOfStream = $true
                    break
                }
                $filled += $read
            }
            $totalRead += $filled
            if ($totalRead -gt $length) {
                # 中身がヘッダーの値より長い（偽りのヘッダー）。実際の大きさは分からないため、検出できた時点の値を記録する
                throw [ZipSizeLimitException]::new($script:zipTooLargeMessage, $entryName, $totalRead, "Part")
            }

            $byteOffset = 0
            if ($first) {
                $first = $false
                $encoding = [System.Text.Encoding]::UTF8
                if ($filled -ge 3 -and $buffer[0] -eq 0xEF -and $buffer[1] -eq 0xBB -and $buffer[2] -eq 0xBF) {
                    $byteOffset = 3
                } elseif ($filled -ge 2 -and $buffer[0] -eq 0xFF -and $buffer[1] -eq 0xFE) {
                    $encoding = [System.Text.Encoding]::Unicode
                    $byteOffset = 2
                } elseif ($filled -ge 2 -and $buffer[0] -eq 0xFE -and $buffer[1] -eq 0xFF) {
                    $encoding = [System.Text.Encoding]::BigEndianUnicode
                    $byteOffset = 2
                }
                $decoder = $encoding.GetDecoder()
                $charBuffer = New-Object char[] ($encoding.GetMaxCharCount($buffer.Length))
            }
            $byteCount = $filled - $byteOffset
            if ($byteCount -gt 0) {
                $charCount = $decoder.GetChars($buffer, $byteOffset, $byteCount, $charBuffer, 0, $false)
                if ($charCount -gt 0) {
                    [void]$sb.Append($charBuffer, 0, $charCount)
                }
            }
            if ($endOfStream) {
                break
            }
        }
        if ($null -ne $decoder) {
            # 最後にDecoderの中に残っている分（サロゲートペアの前半など）を吐き出させる
            $charCount = $decoder.GetChars([byte[]]@(), 0, 0, $charBuffer, 0, $true)
            if ($charCount -gt 0) {
                [void]$sb.Append($charBuffer, 0, $charCount)
            }
        }
    } finally {
        $stream.Dispose()
    }

    return $sb.ToString()
}

function resolveZipPath {
    # リレーションシップの Target（相対パス）を、ZIP内のパスに変換する
    param (
        [string]$baseDir,   # 例: "ppt/slides"
        [string]$target     # 例: "../notesSlides/notesSlide1.xml"
    )

    if ($target.StartsWith("/")) {
        return $target.TrimStart("/")
    }

    $parts = New-Object System.Collections.Generic.List[string]
    foreach ($part in (("$baseDir/$target") -split "/")) {
        if ($part -eq "..") {
            if ($parts.Count -gt 0) { $parts.RemoveAt($parts.Count - 1) }
        } elseif ($part -ne "" -and $part -ne ".") {
            $parts.Add($part)
        }
    }
    return ($parts -join "/")
}

function newXmlDocument {
    # XML文字列から XmlDocument を作る。既存の New-Object + LoadXml と同じ挙動
    # （文字の検査はせず、余白は詰める）にしつつ、DTD（<!DOCTYPE ...>）の処理を禁止する。
    # DTDの実体参照を入れ子にして膨張させる攻撃（billion laughs）を防ぐため
    # （readXmlLines と同じ禁止を、LoadXmlを使うすべての呼び出し元にも揃える）
    param (
        [string]$xml
    )

    $settings = New-Object System.Xml.XmlReaderSettings
    $settings.DtdProcessing = [System.Xml.DtdProcessing]::Prohibit
    $settings.XmlResolver = $null
    $settings.CheckCharacters = $false
    $reader = [System.Xml.XmlReader]::Create((New-Object System.IO.StringReader($xml)), $settings)
    try {
        $doc = New-Object System.Xml.XmlDocument
        $doc.PreserveWhitespace = $false
        $doc.Load($reader)
        return , $doc  # XmlDocument は IEnumerable なので、, を付けないとパイプラインで展開される
    } finally {
        $reader.Dispose()
    }
}

function readRelationships {
    # .rels ファイルを読み、Id → @{ Type; Target（ZIP内のパス） } の辞書を返す
    param (
        [System.IO.Compression.ZipArchive]$zip,
        [string]$partName   # 例: "ppt/slides/slide1.xml"
    )

    $dir = [System.IO.Path]::GetDirectoryName($partName).Replace("\", "/")
    $relsName = "$dir/_rels/$([System.IO.Path]::GetFileName($partName)).rels"

    $result = @{}
    $xml = readZipEntry $zip $relsName
    if ($null -eq $xml) {
        return $result
    }

    $doc = newXmlDocument $xml
    foreach ($rel in $doc.GetElementsByTagName("Relationship", ${nsPkgRel})) {
        if ($rel.GetAttribute("TargetMode") -eq "External") {
            continue
        }
        $result[$rel.GetAttribute("Id")] = @{
            Type   = $rel.GetAttribute("Type")
            Target = resolveZipPath $dir $rel.GetAttribute("Target")
        }
    }
    return $result
}

function readXmlLines {
    # WordprocessingML / DrawingML のXMLから、段落・表の行ごとのテキストを文書順に返す。
    # 戻り値: @{ Page = ページ番号; Text = テキスト } の配列
    #
    # ・表の1行はセルをタブ区切りにして1行とする（セル内の複数段落はスペース区切り）
    # ・テキストボックス内の段落は、それぞれ1行とする
    # ・互換用の代替表示（mc:Fallback）は、同じ内容が重複するため読まない
    # ・ページは、手動の改ページ・段落前で改ページ・セクション区切り（連続以外）で数える。
    #   $pageMode = "rendered" の場合は、Wordが保存時に記録したページ区切り（lastRenderedPageBreak）でも数える。
    #   ただし手動の改ページ等の直後（本文が出る前）の lastRenderedPageBreak は同じ区切りなので数えない
    #   （Wordは手動の改ページの後に lastRenderedPageBreak を記録する場合としない場合がある）
    #   $pageMode = "none" の場合はページを数えない（PowerPoint）
    # ・PowerPoint: $onlyPlaceholders を指定すると、その種類のプレースホルダー（例: "ftr"）のテキストだけを読む。
    #   指定しない場合は、スライド番号・日付・ヘッダー・フッター・スライド画像のプレースホルダーを読まない
    # ・$objects（リスト）を渡すと、本文以外の文字の在りかを、ページ付きでそこに集める（渡さなければ今までどおり）:
    #     @{ Kind = "shape";   Page; Text }   Word のテキストボックス・図形内の文字（本文の行には入れない。段落はスペースでつなぐ）
    #     @{ Kind = "diagram"; Page; RelId }  SmartArt（dgm:relIds の r:dm。データはリレーションシップの先）
    #     @{ Kind = "chart";   Page; RelId }  グラフ（c:chart の r:id）
    #     @{ Kind = "comment"; Page; Id }     コメントの参照（w:commentReference の w:id）
    #     @{ Kind = "embed";   Page; RelId }  埋め込んだファイル（Word は o:OLEObject（Type="Embed"）・w:objectEmbed、
    #                                         PowerPoint は p:oleObj の r:id。リレーションシップの先は呼び出し元が読む）
    param (
        [string]$xml,
        [string]$ns,
        [string]$pageMode = "none",
        [string[]]$onlyPlaceholders = $null,
        [System.Collections.Generic.List[object]]$objects = $null
    )

    # 要素・テキストごとに呼ぶため、PowerShell で遅い書き方（スクリプトブロックの呼び出し・switch・型名の解決・
    # PSCustomObject の作成）を避けている（段落 3,000 の文書で約 2 秒かかっていた）。出力は以前と同じ
    $lines = New-Object System.Collections.Generic.List[object]
    # 開いている段落（p）・表の行（tr）・セル（tc）。種類ごとに積み、最も内側は末尾（XmlReader は開始と終了の対応を保証する）
    $pFrames = New-Object System.Collections.Generic.List[hashtable]
    $trFrames = New-Object System.Collections.Generic.List[hashtable]
    $tcFrames = New-Object System.Collections.Generic.List[hashtable]
    $page = 1
    $breakPending = $false  # 手動の改ページ等の後、まだ本文が出ていない
    $inText = $false
    $inSectPr = $false
    $skipShapeText = $false
    # 開いているテキストボックス（$objects を渡したときだけ使う）。TcBase は開いた時点のセルの数（テキストボックスの外のセル）
    $collect = ($null -ne $objects)
    $boxFrames = New-Object System.Collections.Generic.List[hashtable]

    $elementType = [System.Xml.XmlNodeType]::Element
    $endElementType = [System.Xml.XmlNodeType]::EndElement
    $textType = [System.Xml.XmlNodeType]::Text
    $significantWhitespaceType = [System.Xml.XmlNodeType]::SignificantWhitespace
    $whitespaceType = [System.Xml.XmlNodeType]::Whitespace
    $cdataType = [System.Xml.XmlNodeType]::CDATA
    $onlyMode = ($null -ne $onlyPlaceholders)

    $settings = New-Object System.Xml.XmlReaderSettings
    $settings.DtdProcessing = [System.Xml.DtdProcessing]::Prohibit
    $reader = [System.Xml.XmlReader]::Create((New-Object System.IO.StringReader($xml)), $settings)
    try {
        $hasNode = $reader.Read()
        while ($hasNode) {
            $nodeType = $reader.NodeType

            if ($nodeType -eq $elementType) {
                $name = $reader.LocalName
                $uri = $reader.NamespaceURI
                $isEmpty = $reader.IsEmptyElement

                # 読み飛ばす要素（Skip() で次の要素に進むため、Read() はしない）
                $skip = $false
                if ($uri -eq ${nsCompat} -and $name -eq "Fallback") {
                    $skip = $true
                } elseif ($uri -eq ${nsWord} -and $name -eq "moveFrom") {
                    $skip = $true  # 変更履歴の移動元（移動先と重複する）
                } elseif ($uri -eq ${nsPresent} -and $name -eq "txBody" -and $skipShapeText) {
                    $skip = $true
                } elseif ($uri -eq ${nsPresent} -and $name -eq "graphicFrame" -and $onlyMode) {
                    $skip = $true  # 表など（プレースホルダーではない）
                } elseif ($uri -eq $ns -and $name -eq "rPr" -and -not $isEmpty) {
                    $skip = $true  # 文字の書式（テキストを含まない。1 文字ごとに付くことも多く、読むだけで時間がかかる）
                }
                if ($skip) {
                    $reader.Skip()
                    $hasNode = -not $reader.EOF
                    continue
                }

                if ($uri -eq $ns) {
                    if ($name -eq "p") {
                        if (-not $isEmpty) {
                            $pFrames.Add(@{ Text = (New-Object System.Text.StringBuilder); Page = $null; BreakAfter = $false })
                        }
                    } elseif ($name -eq "tr") {
                        if (-not $isEmpty) {
                            $trFrames.Add(@{ Cells = (New-Object System.Collections.Generic.List[string]); Page = $null })
                        }
                    } elseif ($name -eq "tc") {
                        if ($isEmpty) {
                            if ($trFrames.Count -gt 0) { $trFrames[$trFrames.Count - 1].Cells.Add("") }
                        } else {
                            $tcFrames.Add(@{ Text = (New-Object System.Text.StringBuilder); Page = $null })
                        }
                    } elseif ($name -eq "t") {
                        $inText = -not $isEmpty
                    } elseif ($name -eq "tab" -or $name -eq "cr" -or $name -eq "noBreakHyphen") {
                        if ($pFrames.Count -gt 0) {
                            [void]$pFrames[$pFrames.Count - 1].Text.Append($(if ($name -eq "noBreakHyphen") { "-" } else { " " }))
                        }
                    } elseif ($name -eq "br") {
                        $breakType = $reader.GetAttribute("type", $ns)
                        if ($breakType -ne "page" -and $breakType -ne "column") {
                            if ($pFrames.Count -gt 0) {
                                [void]$pFrames[$pFrames.Count - 1].Text.Append(" ")
                            }
                        } elseif ($pageMode -ne "none" -and $breakType -eq "page") {
                            $page++
                            $breakPending = $true
                        }
                    } elseif ($name -eq "lastRenderedPageBreak") {
                        if ($pageMode -eq "rendered") {
                            if ($breakPending) {
                                $breakPending = $false
                            } else {
                                $page++
                            }
                        }
                    } elseif ($name -eq "pageBreakBefore") {
                        if ($pageMode -ne "none" -and $reader.GetAttribute("val", $ns) -notin @("0", "false", "off")) {
                            $page++
                            $breakPending = $true
                        }
                    } elseif ($name -eq "sectPr") {
                        # 段落内のセクション区切り: 既定（次のページから開始）なら、段落の後で改ページ
                        if ($pageMode -ne "none" -and $pFrames.Count -gt 0) {
                            $inSectPr = -not $isEmpty
                            $pFrames[$pFrames.Count - 1].BreakAfter = $true
                        }
                    } elseif ($name -eq "type") {
                        if ($inSectPr -and $reader.GetAttribute("val", $ns) -eq "continuous") {
                            if ($pFrames.Count -gt 0) { $pFrames[$pFrames.Count - 1].BreakAfter = $false }
                        }
                    } elseif ($collect -and $name -eq "txbxContent") {
                        if (-not $isEmpty) {
                            $boxFrames.Add(@{ Lines = (New-Object System.Collections.Generic.List[string]); Page = $page; TcBase = $tcFrames.Count })
                        }
                    } elseif ($collect -and $name -eq "commentReference") {
                        $objects.Add(@{ Kind = "comment"; Page = $page; Id = $reader.GetAttribute("id", $ns) })
                    } elseif ($collect -and $name -eq "objectEmbed") {
                        $objects.Add(@{ Kind = "embed"; Page = $page; RelId = $reader.GetAttribute("id", ${nsRel}) })
                    }
                } elseif ($collect -and $uri -eq ${nsOffice} -and $name -eq "OLEObject") {
                    if ($reader.GetAttribute("Type") -eq "Embed") {
                        $objects.Add(@{ Kind = "embed"; Page = $page; RelId = $reader.GetAttribute("id", ${nsRel}) })
                    }
                } elseif ($collect -and $uri -eq ${nsDiagram} -and $name -eq "relIds") {
                    $objects.Add(@{ Kind = "diagram"; Page = $page; RelId = $reader.GetAttribute("dm", ${nsRel}) })
                } elseif ($collect -and $uri -eq ${nsChart} -and $name -eq "chart") {
                    $objects.Add(@{ Kind = "chart"; Page = $page; RelId = $reader.GetAttribute("id", ${nsRel}) })
                } elseif ($uri -eq ${nsPresent}) {
                    if ($name -eq "sp") {
                        $skipShapeText = $onlyMode
                    } elseif ($name -eq "ph") {
                        if ($onlyMode) {
                            $skipShapeText = ($reader.GetAttribute("type") -notin $onlyPlaceholders)
                        } else {
                            $skipShapeText = ($reader.GetAttribute("type") -in ${skipPlaceholderTypes})
                        }
                    } elseif ($collect -and $name -eq "oleObj") {
                        $objects.Add(@{ Kind = "embed"; Page = $page; RelId = $reader.GetAttribute("id", ${nsRel}) })
                    }
                }
            } elseif ($nodeType -eq $endElementType) {
                if ($reader.NamespaceURI -eq $ns) {
                    $name = $reader.LocalName
                    # 段落・表の行が終わったら、テキストを親のセルに追加する。セルの中でなければ1行として出力する
                    $text = $null
                    if ($name -eq "t") {
                        $inText = $false
                    } elseif ($name -eq "sectPr") {
                        $inSectPr = $false
                    } elseif ($name -eq "p") {
                        $p = $pFrames[$pFrames.Count - 1]
                        $pFrames.RemoveAt($pFrames.Count - 1)
                        $text = $p.Text.ToString().Trim()
                        $textPage = $p.Page
                        $separator = " "
                        if ($p.BreakAfter) {
                            $page++
                            $breakPending = $true
                        }
                    } elseif ($name -eq "tc") {
                        $cell = $tcFrames[$tcFrames.Count - 1]
                        $tcFrames.RemoveAt($tcFrames.Count - 1)
                        if ($trFrames.Count -gt 0) {
                            $row = $trFrames[$trFrames.Count - 1]
                            $row.Cells.Add($cell.Text.ToString())
                            if ($null -eq $row.Page) {
                                $row.Page = $cell.Page
                            }
                        }
                    } elseif ($name -eq "tr") {
                        $row = $trFrames[$trFrames.Count - 1]
                        $trFrames.RemoveAt($trFrames.Count - 1)
                        # 入れ子の表の行は、外側のセルの中ではスペース区切りにする（テキストボックスの外のセルは数えない）
                        $cellBase = $(if ($boxFrames.Count -gt 0) { $boxFrames[$boxFrames.Count - 1].TcBase } else { 0 })
                        $text = ($row.Cells -join $(if ($tcFrames.Count -gt $cellBase) { " " } else { "`t" })).TrimEnd()
                        $textPage = $(if ($null -ne $row.Page) { $row.Page } else { $page })
                        $separator = " "
                    } elseif ($name -eq "txbxContent" -and $boxFrames.Count -gt 0) {
                        # テキストボックスが終わったら、段落をスペースでつないで図形 1 つにする
                        $box = $boxFrames[$boxFrames.Count - 1]
                        $boxFrames.RemoveAt($boxFrames.Count - 1)
                        if ($box.Lines.Count -gt 0) {
                            $objects.Add(@{ Kind = "shape"; Page = $box.Page; Text = ($box.Lines -join " ") })
                        }
                    }
                    if ($text) {
                        # テキストボックスの中（その中のセルは除く）なら、テキストボックスの行にする
                        $box = $null
                        if ($boxFrames.Count -gt 0 -and $tcFrames.Count -le $boxFrames[$boxFrames.Count - 1].TcBase) {
                            $box = $boxFrames[$boxFrames.Count - 1]
                        }
                        if ($box) {
                            $box.Lines.Add($text)
                        } elseif ($tcFrames.Count -gt 0) {
                            $cell = $tcFrames[$tcFrames.Count - 1]
                            if ($cell.Text.Length -gt 0) {
                                [void]$cell.Text.Append($separator)
                            }
                            [void]$cell.Text.Append($text)
                            if ($null -eq $cell.Page) {
                                $cell.Page = $textPage
                            }
                        } else {
                            $lines.Add([pscustomobject]@{ Page = $textPage; Text = $text })
                        }
                    }
                }
            } elseif ($inText -and ($nodeType -eq $textType -or $nodeType -eq $significantWhitespaceType -or
                                    $nodeType -eq $whitespaceType -or $nodeType -eq $cdataType)) {
                if ($pFrames.Count -gt 0) {
                    $p = $pFrames[$pFrames.Count - 1]
                    if ($null -eq $p.Page) {
                        $p.Page = $page
                    }
                    $value = $reader.Value
                    [void]$p.Text.Append($value.Replace("`t", " ").Replace("`r", " ").Replace("`n", " "))
                    if ($value.Trim() -ne "") {
                        $breakPending = $false
                    }
                }
            }

            $hasNode = $reader.Read()
        }
    } finally {
        $reader.Dispose()
    }

    return $lines.ToArray()
}

function addUnitLines {
    # ユニット（順序付き辞書）に行を追加する
    param (
        [System.Collections.Specialized.OrderedDictionary]$units,
        [string]$unitName,
        [string[]]$lines
    )

    if (-not $units.Contains($unitName)) {
        $units[$unitName] = New-Object System.Collections.Generic.List[string]
    }
    foreach ($line in $lines) {
        $units[$unitName].Add($line)
    }
}

function readDiagramText {
    # SmartArt のデータ（diagrams/dataN.xml）の文字を、スペースでつないで 1 つにする。
    # 同じ文字の描画用（diagrams/drawingN.xml）は、重複するため読まない
    param (
        [string]$xml
    )

    return (@(readXmlLines $xml ${nsDrawing} | ForEach-Object { $_.Text }) -join " ")
}

function readChartTxText {
    # c:tx（グラフのタイトル・軸ラベル・系列名で使う、文字を持つ要素）の文字を返す。
    # セル参照（c:strRef/c:strCache/c:pt/c:v）と直値（c:v）の両方を読む。c:rich（a:p）は呼び出し元が別に読む
    param (
        [System.Xml.XmlElement]$parent
    )

    $found = New-Object System.Collections.Generic.List[string]
    foreach ($child in $parent.ChildNodes) {
        if ($child.LocalName -ne "tx") {
            continue
        }
        foreach ($v in $child.GetElementsByTagName("v", ${nsChart})) {
            $text = $v.InnerText.Trim()
            if ($text -ne "") { $found.Add($text) }
        }
        break
    }
    return $found
}

function readChartText {
    # グラフ（charts/chartN.xml）の文字（タイトル・軸ラベル・系列名）を、スペースでつないで 1 つにする。
    # 項目名（横軸の項目。c:cat。点の数だけある）と数値（c:val）は読まない。同じ文字は 1 回だけにする。
    # 系列（c:ser）とタイトル・軸（c:title）の数だけ調べるため、項目の点数が多いグラフでも遅くならない
    param (
        [string]$xml
    )

    $texts = New-Object System.Collections.Generic.List[string]
    $seen = New-Object System.Collections.Generic.HashSet[string]
    # タイトル・軸ラベル（c:rich の a:p。手で直したデータラベルの文字も同じ形のため、ここで読む）
    foreach ($line in (readXmlLines $xml ${nsDrawing})) {
        if ($seen.Add($line.Text)) { $texts.Add($line.Text) }
    }
    $doc = newXmlDocument $xml
    # タイトル・軸ラベルのうち、セル参照の文字（c:title/c:tx/c:strRef/c:strCache/c:pt/c:v。直値の c:rich は上で読み済み）
    foreach ($title in $doc.GetElementsByTagName("title", ${nsChart})) {
        foreach ($text in (readChartTxText $title)) {
            if ($seen.Add($text)) { $texts.Add($text) }
        }
    }
    # 系列名（c:ser/c:tx の文字。セル参照なら c:strRef/c:strCache/c:pt/c:v、直値なら c:v）
    foreach ($ser in $doc.GetElementsByTagName("ser", ${nsChart})) {
        foreach ($text in (readChartTxText $ser)) {
            if ($seen.Add($text)) { $texts.Add($text) }
        }
    }
    return ($texts -join " ")
}

function readObjectText {
    # readXmlLines が集めた SmartArt・グラフの参照（RelId）から、その文字を返す（読めなければ空）
    param (
        [System.IO.Compression.ZipArchive]$zip,
        [hashtable]$rels,   # readRelationships の結果
        $object
    )

    $rel = $rels[[string]$object.RelId]
    if ($null -eq $rel) {
        return ""
    }
    $xml = readZipEntry $zip $rel.Target
    if ($null -eq $xml) {
        return ""
    }
    if ($object.Kind -eq "diagram") {
        return (readDiagramText $xml)
    }
    return (readChartText $xml)
}

function readWordComments {
    # Word のコメント（word/comments.xml）を、w:id → 文字（段落をスペースでつなぐ）の辞書で返す。
    # 返信も別のコメント（別の w:id）として入っている。作成者名は読まない
    param (
        [string]$xml
    )

    $comments = @{}
    if (-not $xml) {
        return $comments  # コメントが無い（[string] の引数は $null を空文字にする）
    }
    $doc = newXmlDocument $xml
    foreach ($comment in $doc.GetElementsByTagName("comment", ${nsWord})) {
        $text = @(readXmlLines $comment.OuterXml ${nsWord} | ForEach-Object { $_.Text }) -join " "
        if ($text -ne "") {
            $comments[$comment.GetAttribute("id", ${nsWord})] = $text
        }
    }
    return $comments
}

function readSlideComments {
    # PowerPoint のスライドのコメントを、コメント・返信ごとの文字の配列で返す（作成者名は読まない）。
    #   旧形式（ppt/comments/commentN.xml）: p:cm の p:text
    #   新形式（ppt/comments/modernComment_*.xml）: p188:cm の p188:txBody と、返信（p188:reply）の p188:txBody
    param (
        [string]$xml
    )

    $texts = New-Object System.Collections.Generic.List[string]
    $doc = newXmlDocument $xml
    foreach ($cm in @($doc.SelectNodes("//*") | Where-Object { $_.LocalName -eq "cm" })) {
        if ($cm.NamespaceURI -eq ${nsPresent}) {
            $body = @($cm.ChildNodes | Where-Object { $_.LocalName -eq "text" })
            if ($body.Count -gt 0 -and $body[0].InnerText.Trim() -ne "") { $texts.Add($body[0].InnerText.Trim()) }
            continue
        }
        # 新形式: XML では返信の一覧（replyLst）が本文（txBody）より前にあるため、本文を先に出してから返信を出す
        $bodies = @($cm.ChildNodes | Where-Object { $_.LocalName -eq "txBody" })
        foreach ($reply in @($cm.ChildNodes | Where-Object { $_.LocalName -eq "replyLst" } | ForEach-Object { $_.ChildNodes } | Where-Object { $_.LocalName -eq "reply" })) {
            $bodies += @($reply.ChildNodes | Where-Object { $_.LocalName -eq "txBody" })
        }
        foreach ($body in $bodies) {
            $text = @(readXmlLines $body.OuterXml ${nsDrawing} | ForEach-Object { $_.Text }) -join " "
            if ($text -ne "") { $texts.Add($text) }
        }
    }
    return $texts.ToArray()
}

function readDocxUnits {
    # Word（.docx / .docm）のテキストを、ページ・ヘッダー/フッター・脚注ごとに返す。
    # 本文のテキストボックス・図形内の文字と SmartArt・グラフの文字は "ページNNN[図形]"、
    # コメントは "ページNNN[コメント]"（コメントを付けた所のページ）に分ける（1 行は図形・コメント 1 つ）。
    # 埋め込んだ Office のファイルの文字は "ページNNN[埋め込み<N>]"（N は 1 ファイルの中の、参照の順の通し番号。
    # 読まなかったものは欠番。office_embedded.ps1）。
    # $failures・$sizeFailures を渡すと、読めなかった埋め込みの部品の名前と、大きさの上限の例外を追加する
    # （呼び出し元がインデックス作成のログに書く。shared/ はツールを知らないため、ここでは書かない）。
    # ファイルを開き、合計（zipTotalReadBytes）を 0 から数え直して、閉じる。読む本体は readDocxUnitsFromZip
    param (
        [string]$path,
        [System.Collections.Generic.List[string]]$failures = $null,
        [System.Collections.Generic.List[object]]$sizeFailures = $null
    )

    $script:zipTotalReadBytes = 0  # このファイル1つ分の、readZipEntryが読む合計（zipTotalMaxBytes）を0から数え直す
    $zip = [System.IO.Compression.ZipFile]::OpenRead((toLongPath $path))
    try {
        return (readDocxUnitsFromZip $zip $true $failures $sizeFailures)
    } finally {
        $zip.Dispose()
    }
}

function readDocxUnitsFromZip {
    # 開いた Word の ZipArchive から、readDocxUnits と同じユニットを返す（開く・閉じる・合計の数え直しはしない）。
    # $readEmbeds が $false なら埋め込みは読まない（埋め込みの中の Word 文書を読むとき。深さは 1 段まで）
    param (
        [System.IO.Compression.ZipArchive]$zip,
        [bool]$readEmbeds,
        [System.Collections.Generic.List[string]]$failures = $null,
        [System.Collections.Generic.List[object]]$sizeFailures = $null
    )

    $units = New-Object System.Collections.Specialized.OrderedDictionary
    $body = readZipEntry $zip "word/document.xml"
    if ($null -eq $body) {
        throw "Word文書の本文（word/document.xml）がありません。"
    }

    # Wordで保存されたファイルには、保存時点のページ区切りが記録されている。無ければ手動の改ページで数える
    $pageMode = $(if ($body.Contains("lastRenderedPageBreak")) { "rendered" } else { "explicit" })
    # 本文は行数が多いため、1行ずつ addUnitLines を呼ばずにページのユニットへ入れる（結果は addUnitLines と同じ）
    $lastPage = $null
    $pageLines = $null
    $objects = New-Object System.Collections.Generic.List[object]
    foreach ($line in (readXmlLines $body ${nsWord} $pageMode $null $objects)) {
        if ($null -eq $pageLines -or $line.Page -ne $lastPage) {
            $unitName = "ページ{0:D3}" -f $line.Page
            if (-not $units.Contains($unitName)) {
                $units[$unitName] = New-Object System.Collections.Generic.List[string]
            }
            $pageLines = $units[$unitName]
            $lastPage = $line.Page
        }
        $pageLines.Add($line.Text)
    }

    # 本文の XML の文字列は、ここから先で使わない。埋め込みを読む前に放す（同時に持つメモリを抑える）
    $body = $null

    # 図形（テキストボックス・SmartArt・グラフ）・コメント・埋め込み。文書の中の順に、そのページの場所へ入れる
    $rels = readRelationships $zip "word/document.xml"
    $comments = readWordComments (readZipEntry $zip "word/comments.xml")
    $usedComments = New-Object System.Collections.Generic.HashSet[string]
    $embedState = newEmbeddedState
    foreach ($object in $objects) {
        $base = "ページ{0:D3}" -f $object.Page
        if ($object.Kind -eq "shape") {
            addUnitLines $units "${base}[図形]" @($object.Text)
        } elseif ($object.Kind -eq "comment") {
            $id = [string]$object.Id
            if ($comments.ContainsKey($id) -and $usedComments.Add($id)) {
                addUnitLines $units "${base}[コメント]" @($comments[$id])
            }
        } elseif ($object.Kind -eq "embed") {
            if ($readEmbeds) {
                $embedded = readEmbeddedObjectLines $zip $rels $object $embedState $failures $sizeFailures
                if ($null -ne $embedded -and $embedded.Lines.Count -gt 0) {
                    addUnitLines $units "${base}[埋め込み$($embedded.Number)]" $embedded.Lines
                }
            }
        } else {
            $text = readObjectText $zip $rels $object
            if ($text -ne "") {
                addUnitLines $units "${base}[図形]" @($text)
            }
        }
    }
    # 本文に参照の無いコメント（ヘッダー・脚注に付けたものなど）は、場所が分からないため "文書[コメント]" にまとめる
    foreach ($id in @($comments.Keys | Sort-Object { $n = 0; [void][int]::TryParse($_, [ref]$n); $n })) {
        if (-not $usedComments.Contains($id)) {
            addUnitLines $units "文書[コメント]" @($comments[$id])
        }
    }

    # ヘッダー・フッター（セクションごとに同じ内容が並ぶため、重複は除く）
    $seen = New-Object System.Collections.Generic.HashSet[string]
    $parts = @($zip.Entries | Where-Object { $_.FullName -match "^word/(header|footer)\d*\.xml$" } |
        Sort-Object { $_.FullName -notmatch "/header" }, FullName)  # ヘッダー → フッターの順
    foreach ($part in $parts) {
        foreach ($line in (readXmlLines (readZipEntry $zip $part.FullName) ${nsWord})) {
            if ($seen.Add($line.Text)) {
                addUnitLines $units "ヘッダー・フッター" @($line.Text)
            }
        }
    }

    # 脚注・文末脚注
    foreach ($partName in @("word/footnotes.xml", "word/endnotes.xml")) {
        $xml = readZipEntry $zip $partName
        if ($null -ne $xml) {
            addUnitLines $units "脚注" @(readXmlLines $xml ${nsWord} | ForEach-Object { $_.Text })
        }
    }

    return $units
}

function readPptxUnits {
    # PowerPoint（.pptx / .pptm）のテキストを、スライド・ノートごと（スライドの表示順）と、
    # スライドのフッター（全スライド分をまとめ、重複を除く）に分けて返す。
    # 埋め込んだ Office のファイルの文字は "スライドNNN[埋め込み<N>]"（N は 1 ファイルの中の、参照の順の通し番号。
    # 読まなかったものは欠番。office_embedded.ps1）。
    # $failures・$sizeFailures の意味と、ファイルの開閉・合計の数え直しは readDocxUnits と同じ。読む本体は readPptxUnitsFromZip
    param (
        [string]$path,
        [System.Collections.Generic.List[string]]$failures = $null,
        [System.Collections.Generic.List[object]]$sizeFailures = $null
    )

    $script:zipTotalReadBytes = 0  # このファイル1つ分の、readZipEntryが読む合計（zipTotalMaxBytes）を0から数え直す
    $zip = [System.IO.Compression.ZipFile]::OpenRead((toLongPath $path))
    try {
        return (readPptxUnitsFromZip $zip $true $failures $sizeFailures)
    } finally {
        $zip.Dispose()
    }
}

function readPptxUnitsFromZip {
    # 開いた PowerPoint の ZipArchive から、readPptxUnits と同じユニットを返す（開く・閉じる・合計の数え直しはしない）。
    # $readEmbeds が $false なら埋め込みは読まない（埋め込みの中の PowerPoint を読むとき。深さは 1 段まで）
    param (
        [System.IO.Compression.ZipArchive]$zip,
        [bool]$readEmbeds,
        [System.Collections.Generic.List[string]]$failures = $null,
        [System.Collections.Generic.List[object]]$sizeFailures = $null
    )

    $units = New-Object System.Collections.Specialized.OrderedDictionary
    $footers = New-Object System.Collections.Generic.List[string]
    $seenFooters = New-Object System.Collections.Generic.HashSet[string]
    $embedState = newEmbeddedState
    $presentationXml = readZipEntry $zip "ppt/presentation.xml"
    if ($null -eq $presentationXml) {
        throw "PowerPointのプレゼンテーション情報（ppt/presentation.xml）がありません。"
    }
    $presentation = newXmlDocument $presentationXml
    $presentationRels = readRelationships $zip "ppt/presentation.xml"

    # スライドの表示順は sldIdLst の順（ファイル名の番号とは一致しないことがある）
    $number = 0
    foreach ($slideId in $presentation.GetElementsByTagName("sldId", ${nsPresent})) {
        $number++
        $rel = $presentationRels[$slideId.GetAttribute("id", ${nsRel})]
        if ($null -eq $rel) {
            continue
        }

        $slideXml = readZipEntry $zip $rel.Target
        if ($null -eq $slideXml) {
            continue
        }

        $unitName = "スライド{0:D3}" -f $number
        if ($slideXml -match '^[\s\S]{0,2000}?<p:sld\b[^>]*\sshow="(0|false)"') {
            $unitName += "（非表示）"
        }
        # テキストボックス・図形の文字はスライドの本文にする（スライドの文字はほとんどが図形のため）。
        # SmartArt・グラフの文字は "スライドNNN[図形]"、コメントは "スライドNNN[コメント]" に分ける
        $objects = New-Object System.Collections.Generic.List[object]
        addUnitLines $units $unitName @(readXmlLines $slideXml ${nsDrawing} "none" $null $objects | ForEach-Object { $_.Text })
        $slideRels = readRelationships $zip $rel.Target
        foreach ($object in $objects) {
            if ($object.Kind -eq "embed") {
                continue  # 埋め込みは、スライドの文字をすべて読んだあとに読む（下）
            }
            $text = readObjectText $zip $slideRels $object
            if ($text -ne "") {
                addUnitLines $units "${unitName}[図形]" @($text)
            }
        }
        foreach ($slideRel in $slideRels.Values) {
            if ($slideRel.Type -like "*/comments") {
                $commentsXml = readZipEntry $zip $slideRel.Target
                if ($null -ne $commentsXml) {
                    addUnitLines $units "${unitName}[コメント]" @(readSlideComments $commentsXml)
                }
            }
        }

        # スライドのフッター（各スライドに同じ内容が並ぶため、重複は除く）
        foreach ($line in (readXmlLines $slideXml ${nsDrawing} "none" @("ftr"))) {
            if ($seenFooters.Add($line.Text)) {
                $footers.Add($line.Text)
            }
        }

        # 発表者ノート
        foreach ($slideRel in $slideRels.Values) {
            if ($slideRel.Type -like "*/notesSlide") {
                $notesXml = readZipEntry $zip $slideRel.Target
                if ($null -ne $notesXml) {
                    addUnitLines $units ("スライド{0:D3}_ノート" -f $number) @(readXmlLines $notesXml ${nsDrawing} | ForEach-Object { $_.Text })
                }
            }
        }

        # 埋め込んだファイル（スライドの中の XML の順）。スライドの XML の文字列は、ここから先で使わない
        # ので、埋め込みを読む前に放す（同時に持つメモリを抑える）
        $slideXml = $null
        if ($readEmbeds) {
            foreach ($object in @($objects | Where-Object { $_.Kind -eq "embed" })) {
                $embedded = readEmbeddedObjectLines $zip $slideRels $object $embedState $failures $sizeFailures
                if ($null -ne $embedded -and $embedded.Lines.Count -gt 0) {
                    addUnitLines $units "${unitName}[埋め込み$($embedded.Number)]" $embedded.Lines
                }
            }
        }
    }

    if ($footers.Count -gt 0) {
        addUnitLines $units "ヘッダー・フッター" $footers.ToArray()
    }

    return $units
}

function toObjectCellText {
    # 図形・コメントの文字を、Excel のテキスト保存と同じ形の 1 セルにする。
    # 改行はセル内改行（$cellNewLine）にし、改行・" ・タブを含むときは " で囲む（中の " は "" にする）
    param (
        [string[]]$lines
    )

    $text = ($lines -join "`n").Trim()
    if ($text.IndexOfAny([char[]]@('"', "`t", "`r", "`n")) -lt 0) {
        return $text
    }
    $text = ($text -replace "\r\n|\r|\n", ${cellNewLine}).Replace('"', '""')
    return "`"$text`""
}

function readXlsxShapeRows {
    # 図形（xl/drawings/drawingN.xml）ごとの文字を @{ Row; Column; Text } の配列で返す。
    # 行・列は図形の左上のセル（1 から数える）。グループ化した図形は、まとめて 1 つの図形とする。
    # $zip・$drawingPath（この図形の部品自身の ZIP 内のパス）を渡すと、グラフ（c:chart）・SmartArt（dgm:relIds）の
    # 参照も解決し、テキストボックスの段落 → グラフ・SmartArt の文字（XML の順）の順に 1 つの図形（1 行）にする。
    # リレーションシップ（_rels）は、参照が 1 つ以上あるときだけ読む。
    # 参照の先・リレーションシップが無い、部品が読めない（XML が壊れているなど）ときは、そのグラフ・SmartArt だけを
    # 空にして続ける（同じ図形の中のほかの文字、ほかの図形は出す）。$failures を渡すと、読めなかった部品の名前を追加する。
    # サイズの上限（ZipSizeLimitException）で読めなかったときは、原因を調べられるよう、その例外自体を
    # $sizeFailures に追加する（呼び出し元がインデックス作成のログに部品名・大きさ・部品ごとか合計かを書く）
    param (
        [string]$xml,
        [System.IO.Compression.ZipArchive]$zip = $null,
        [string]$drawingPath = $null,
        [System.Collections.Generic.List[string]]$failures = $null,
        [System.Collections.Generic.List[object]]$sizeFailures = $null
    )

    $nsSheetDrawing = "http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing"
    $doc = newXmlDocument $xml
    $rows = New-Object System.Collections.Generic.List[object]
    $rels = $null  # この図形の部品（drawingN.xml）自身のリレーションシップ。参照が1つ以上あるときだけ読む
    foreach ($anchor in @($doc.DocumentElement.SelectNodes("//*")) | Where-Object {
            $_.NamespaceURI -eq $nsSheetDrawing -and $_.LocalName -in @("twoCellAnchor", "oneCellAnchor", "absoluteAnchor") }) {
        # 互換用の代替表示（mc:Fallback）の中は、mc:Choice と同じ図形なので読まない
        $inFallback = $false
        for ($node = $anchor.ParentNode; $null -ne $node; $node = $node.ParentNode) {
            if ($node.NamespaceURI -eq ${nsCompat} -and $node.LocalName -eq "Fallback") {
                $inFallback = $true
                break
            }
        }
        if ($inFallback) {
            continue
        }

        $objects = New-Object System.Collections.Generic.List[object]
        $lines = New-Object System.Collections.Generic.List[string]
        foreach ($line in (readXmlLines $anchor.OuterXml ${nsDrawing} "none" $null $objects)) {
            $lines.Add($line.Text)
        }
        # グラフ（c:chart）・SmartArt（dgm:relIds）の文字を、テキストボックスの段落の後、XML の順に並べる
        foreach ($object in @($objects | Where-Object { $_.Kind -eq "chart" -or $_.Kind -eq "diagram" })) {
            $text = ""
            try {
                # リレーションシップ自体（drawingN.xml.rels）が壊れていても、この図形だけを空にしてほかは捨てない
                if ($null -eq $rels) {
                    $rels = $(if ($zip -and $drawingPath) { readRelationships $zip $drawingPath } else { @{} })
                }
                $text = readObjectText $zip $rels $object
            } catch {
                if ($null -ne $sizeFailures -and $_.Exception -is [ZipSizeLimitException]) {
                    # サイズの上限を超えたときは、例外自体を渡す（部品名は例外の PartName に入っている）
                    $sizeFailures.Add($_.Exception)
                }
                if ($null -ne $failures) {
                    if ($null -eq $rels -and $drawingPath) {
                        # リレーションシップ自体（drawingN.xml.rels）が読めなかった場合は、図形の部品の名前を記録する
                        # （$object.RelId だけでは、どの部品が壊れているのか分からないため）
                        $failures.Add($drawingPath)
                    } else {
                        $rel = $(if ($rels) { $rels[[string]$object.RelId] } else { $null })
                        $failures.Add($(if ($rel) { $rel.Target } else { [string]$object.RelId }))
                    }
                }
            }
            if ($text -ne "") {
                $lines.Add($text)
            }
        }
        if ($lines.Count -eq 0) {
            continue
        }
        # 位置をセルで持たない図形（absoluteAnchor）は A1 とする
        $row = 1
        $column = 1
        $from = $anchor.GetElementsByTagName("from", $nsSheetDrawing)
        if ($from.Count -gt 0) {
            $row = 1 + [int]$from[0].GetElementsByTagName("row", $nsSheetDrawing)[0].InnerText
            $column = 1 + [int]$from[0].GetElementsByTagName("col", $nsSheetDrawing)[0].InnerText
        }
        $rows.Add(@{ Row = $row; Column = $column; Text = (toObjectCellText $lines.ToArray()) })
    }
    return $rows.ToArray()
}

function readXlsxCommentRows {
    # コメント（メモ。xl/commentsN.xml）とスレッド形式のコメント（xl/threadedComments/*.xml）の文字を、
    # セル番地 → 文字の辞書で返す。スレッド形式のコメントがあるセルは、その文字（返信を含む）を使う
    # （同じセルのメモには、古い版の Excel 向けの案内文とコメントが入っているため）
    param (
        [string]$commentsXml,
        [string[]]$threadedXmls
    )

    $nsSheet = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
    $nsThreaded = "http://schemas.microsoft.com/office/spreadsheetml/2018/threadedcomments"
    $result = [ordered]@{}

    foreach ($xml in @($threadedXmls | Where-Object { $_ })) {
        $doc = newXmlDocument $xml
        foreach ($comment in $doc.GetElementsByTagName("threadedComment", $nsThreaded)) {
            $ref = $comment.GetAttribute("ref")
            $text = @($comment.GetElementsByTagName("text", $nsThreaded) | ForEach-Object { $_.InnerText }) -join "`n"
            if (-not $ref -or $text.Trim() -eq "") {
                continue
            }
            if ($result.Contains($ref)) {
                $result[$ref] += "`n" + $text
            } else {
                $result[$ref] = $text
            }
        }
    }

    if ($commentsXml) {
        $doc = newXmlDocument $commentsXml
        foreach ($comment in $doc.GetElementsByTagName("comment", $nsSheet)) {
            $ref = $comment.GetAttribute("ref")
            if (-not $ref -or $result.Contains($ref)) {
                continue
            }
            # ふりがな（rPh）は読まない
            $text = @($comment.GetElementsByTagName("t", $nsSheet) | Where-Object { $_.ParentNode.LocalName -ne "rPh" } |
                ForEach-Object { $_.InnerText }) -join ""
            if ($text.Trim() -ne "") {
                $result[$ref] = $text
            }
        }
    }
    return $result
}

function getCellPosition {
    # セル番地（例: "AB12"）を @(行, 列) にする。読めなければ @(0, 0)
    param (
        [string]$ref
    )

    $m = [regex]::Match($ref, '^\$?([A-Za-z]+)\$?(\d+)$')
    if (-not $m.Success) {
        return @(0, 0)
    }
    $column = 0
    foreach ($ch in $m.Groups[1].Value.ToUpperInvariant().ToCharArray()) {
        $column = $column * 26 + ([int]$ch - [int][char]"A" + 1)
    }
    return @([int]$m.Groups[2].Value, $column)
}

function addSortedShapeLines {
    # 図形の一覧を、上の行から（同じ行は左から、同じセルは XML の順に）並べてユニットに加える。
    # Sort-Object は同じキーの順を保たない（インデックス作成のたびに順が変わる）ため、XML の順もキーにする
    param (
        [System.Collections.Specialized.OrderedDictionary]$units,
        [string]$unitName,
        [System.Collections.Generic.List[object]]$shapes
    )

    for ($i = 0; $i -lt $shapes.Count; $i++) {
        $shapes[$i].Order = $i
    }
    $lines = @($shapes | Sort-Object { $_.Row }, { $_.Column }, { $_.Order } |
        ForEach-Object { "$(toColumnName $_.Column)$($_.Row)`t$($_.Text)" })
    if ($lines.Count -gt 0) {
        addUnitLines $units $unitName $lines
    }
}

function getHeaderFooterLines {
    # Excel のヘッダー・フッターの書式コード付きの文字（例: "&L社外秘&C&"ＭＳ ゴシック,太字"&12見出し&R&P / &N ページ"）を、
    # 検索する行の一覧にする。左（&L）・中央（&C。区切りが無い先頭も中央）・右（&R）の順で、1 区分の 1 段落が 1 行。
    # 印刷時に決まる値（&P ページ・&N 総ページ・&D 日付・&T 時刻・&Z パス・&F ファイル名・&A シート名・&G 画像）と、
    # 書式（フォント・大きさ・色・&B &I &U &E &S &X &Y &O &H）は文字にしない。&& は & 1 文字。知らない & の続きはそのまま残す。
    # タブはスペースにして前後の空白を落とし、空の行は出さない。1 行ずつ toObjectCellText を通す
    # （Excel の行は " で囲んだセルを外す前提のため）
    param (
        [string]$code
    )

    $sections = @{ L = New-Object System.Text.StringBuilder; C = New-Object System.Text.StringBuilder; R = New-Object System.Text.StringBuilder }
    $current = $sections["C"]
    $length = $code.Length
    $i = 0
    while ($i -lt $length) {
        $ch = $code[$i]
        if ($ch -ne '&' -or $i + 1 -ge $length) {
            [void]$current.Append($ch)
            $i++
            continue
        }
        $next = $code[$i + 1]
        if ($next -eq '&') {
            [void]$current.Append('&')
            $i += 2
        } elseif ($next -cin @('L', 'C', 'R')) {
            $current = $sections[[string]$next]
            $i += 2
        } elseif ($next -ceq 'P') {
            # &P+1 &P-1（ページ番号の加減）の数字も取り除く
            $m = [regex]::Match($code.Substring($i), '^&P(?:[+-]\d+)?')
            $i += $m.Length
        } elseif ($next -cin @('N', 'D', 'T', 'Z', 'F', 'A', 'G', 'B', 'I', 'U', 'E', 'S', 'X', 'Y', 'O', 'H')) {
            $i += 2
        } elseif ($next -eq '"') {
            $close = $code.IndexOf('"', $i + 2)
            if ($close -lt 0) {
                [void]$current.Append('&')
                $i++
            } else {
                $i = $close + 1
            }
        } elseif ($next -ceq 'K') {
            $m = [regex]::Match($code.Substring($i), '^&K(?:[0-9A-Fa-f]{6}|[0-9]{2}[+-][0-9]{3})')
            if ($m.Success) {
                $i += $m.Length
            } else {
                [void]$current.Append('&')
                $i++
            }
        } elseif ($next -ge [char]'0' -and $next -le [char]'9') {
            $m = [regex]::Match($code.Substring($i), '^&\d{1,3}')
            $i += $m.Length
        } else {
            [void]$current.Append('&')
            $i++
        }
    }

    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($key in @("L", "C", "R")) {
        foreach ($part in ($sections[$key].ToString() -split "\r\n|\r|\n")) {
            $text = $part.Replace("`t", " ").Trim()
            if ($text -ne "") {
                $lines.Add((toObjectCellText @($text)))
            }
        }
    }
    return $lines.ToArray()
}

function readXlsxHeaderFooterLines {
    # シート（ワークシート・グラフシート）の XML（XmlReader）から、ヘッダー・フッターの検索する行を返す。
    # 並びは ヘッダー → フッター、それぞれ 先頭ページ（differentFirst のとき）→ 奇数（通常）ページ →
    # 偶数ページ（differentOddEven のとき）。同じ文字の行は 1 回だけ。
    # sheetData（セルの値。大きいシートでは数百 MB になる）は読まずに飛ばし、headerFooter を読んだら終わる
    param (
        [System.Xml.XmlReader]$reader
    )

    $nsSheet = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
    $texts = @{}
    $differentFirst = $false
    $differentOddEven = $false
    $hasNode = $reader.Read()
    while ($hasNode) {
        if ($reader.NodeType -eq [System.Xml.XmlNodeType]::Element -and $reader.NamespaceURI -eq $nsSheet) {
            if ($reader.LocalName -eq "sheetData") {
                $reader.Skip()
                $hasNode = -not $reader.EOF
                continue
            }
            if ($reader.LocalName -eq "headerFooter") {
                $differentFirst = $reader.GetAttribute("differentFirst") -in @("1", "true")
                $differentOddEven = $reader.GetAttribute("differentOddEven") -in @("1", "true")
                $sub = $reader.ReadSubtree()
                try {
                    $sub.Read() | Out-Null  # headerFooter 自身
                    $hasChild = $sub.Read()
                    while ($hasChild) {
                        if ($sub.NodeType -eq [System.Xml.XmlNodeType]::Element -and $sub.Depth -eq 1 -and $sub.NamespaceURI -eq $nsSheet) {
                            $childName = $sub.LocalName  # 読んだ後は位置が進むため、先に控える
                            $texts[$childName] = $sub.ReadElementContentAsString()
                            $hasChild = -not $sub.EOF
                        } else {
                            $hasChild = $sub.Read()
                        }
                    }
                } finally {
                    $sub.Dispose()
                }
                break
            }
        }
        $hasNode = $reader.Read()
    }

    $names = New-Object System.Collections.Generic.List[string]
    foreach ($kind in @("Header", "Footer")) {
        if ($differentFirst) { $names.Add("first$kind") }
        $names.Add("odd$kind")
        if ($differentOddEven) { $names.Add("even$kind") }
    }
    $lines = New-Object System.Collections.Generic.List[string]
    $seen = New-Object System.Collections.Generic.HashSet[string]
    foreach ($name in $names) {
        if (-not $texts.ContainsKey($name)) {
            continue
        }
        foreach ($line in (getHeaderFooterLines $texts[$name])) {
            if ($seen.Add($line)) { $lines.Add($line) }
        }
    }
    return $lines.ToArray()
}

function readXlsxSheetHeaderFooter {
    # ZIP の中のシートの部品（$entryName）か、読み込み済みの文字列（$xml。グラフシート）から、
    # ヘッダー・フッターの行を返す。読めない（XML が壊れているなど）ときは空にし、$failures に部品の名前を足す
    param (
        [System.IO.Compression.ZipArchive]$zip,
        [string]$entryName,
        [string]$xml = $null,
        [System.Collections.Generic.List[string]]$failures = $null
    )

    $settings = New-Object System.Xml.XmlReaderSettings
    $settings.DtdProcessing = [System.Xml.DtdProcessing]::Prohibit
    # シートの部品は sheetData が大きいため、文字列にせず流れで読む（readZipEntry は使わない）。
    # 代わりに、申告の大きさ（entry.Length）が上限（zipSheetStreamMaxBytes）を超える部品は開かずに読めなかった扱いにする。
    # MaxCharactersInDocument は、申告を偽った部品（実際は大きいのに小さく申告）を打ち切る守り（XmlException → 読めなかった扱い）
    $settings.MaxCharactersInDocument = $script:zipSheetStreamMaxBytes
    $stream = $null
    $reader = $null
    try {
        if ($xml) {
            $reader = [System.Xml.XmlReader]::Create((New-Object System.IO.StringReader($xml)), $settings)
        } else {
            $entry = $zip.GetEntry($entryName)
            if ($null -eq $entry) {
                return @()
            }
            if ($entry.Length -gt $script:zipSheetStreamMaxBytes) {
                # 申告の大きさが流れ読みの上限を超える（開かずに読めなかった扱いにし、理由をログに出せるようにする）
                if ($null -ne $failures) {
                    $failures.Add("$entryName（流れ読みの上限 $([long]($script:zipSheetStreamMaxBytes / 1MB))MB を超えています）")
                }
                return @()
            }
            $stream = $entry.Open()
            $reader = [System.Xml.XmlReader]::Create($stream, $settings)
        }
        return @(readXlsxHeaderFooterLines $reader)
    } catch {
        if ($null -ne $failures) {
            if ($_.Exception.Message -like "*MaxCharactersInDocument*") {
                $failures.Add("$entryName（流れ読みの上限 $([long]($script:zipSheetStreamMaxBytes / 1MB))MB を超えています）")
            } else {
                $failures.Add($entryName)
            }
        }
        return @()
    } finally {
        if ($null -ne $reader) { $reader.Dispose() }
        if ($null -ne $stream) { $stream.Dispose() }
    }
}

function readXlsxObjectUnits {
    # Excel（.xlsx / .xlsm）の表示シート・表示のグラフシートにある図形（テキストボックス・グループ・WordArt・
    # グラフ・SmartArt を含む）・コメント・ヘッダー／フッターの文字を、"<シート名>[図形]" "<シート名>[コメント]"
    # "<シート名>[ヘッダー・フッター]" の場所ごとに返す（シート名には [ ] を使えないため、実在のシートと重ならない）。
    # 図形・コメントの 1 行は "<セル番地><TAB><文字>"。セル番地は図形の左上・コメントのセルで、シートの上の行から順に並べる。
    # ヘッダー・フッターの 1 行は文字だけ（セル番地は無い。getHeaderFooterLines・readXlsxHeaderFooterLines）。
    # セルの値は Excel のテキスト保存で読むため、ここでは読まない。
    # ZIP の中身が Excel のブック（xl/workbook.xml）でなければ（.xlsb など）、何も返さない。
    # $failures を渡すと、読めなかったグラフ・SmartArt の部品の名前を追加する（呼び出し元でログに書く。
    # shared/ はツールを知らないため、ここでは書かない）。
    # $sizeFailures を渡すと、サイズの上限（ZipSizeLimitException）で読めなかったグラフ・SmartArt の
    # 例外自体を追加する（呼び出し元が部品名・大きさ・部品ごとか合計かをログに書く）
    param (
        [string]$path,
        [System.Collections.Generic.List[string]]$failures = $null,
        [System.Collections.Generic.List[object]]$sizeFailures = $null
    )

    $script:zipTotalReadBytes = 0  # このファイル1つ分の、readZipEntryが読む合計（zipTotalMaxBytes）を0から数え直す
    $units = New-Object System.Collections.Specialized.OrderedDictionary
    $nsSheet = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
    $zip = [System.IO.Compression.ZipFile]::OpenRead((toLongPath $path))
    try {
        $workbookXml = readZipEntry $zip "xl/workbook.xml"
        if ($null -eq $workbookXml) {
            return $units
        }
        $workbook = newXmlDocument $workbookXml
        $workbookRels = readRelationships $zip "xl/workbook.xml"

        foreach ($sheet in $workbook.GetElementsByTagName("sheet", $nsSheet)) {
            # 非表示（hidden）・完全に非表示（veryHidden）のシートは、セルと同じく読まない
            if ($sheet.GetAttribute("state") -in @("hidden", "veryHidden")) {
                continue
            }
            $rel = $workbookRels[$sheet.GetAttribute("id", ${nsRel})]
            if ($null -eq $rel) {
                continue
            }
            $sheetName = $sheet.GetAttribute("name")

            if ($rel.Type -like "*/chartsheet") {
                # 表示のグラフシート: グラフ自体を absoluteAnchor で置いた図形の部品を、通常のシートと同じ形で読む。
                # 位置をセルで持たないため、セル番地は今の決まりどおり A1 になる
                $chartsheetXml = readZipEntry $zip $rel.Target
                if ($null -eq $chartsheetXml) {
                    continue
                }
                $shapes = New-Object System.Collections.Generic.List[object]
                foreach ($csRel in (readRelationships $zip $rel.Target).Values) {
                    if ($csRel.Type -notlike "*/drawing") {
                        continue
                    }
                    $xml = readZipEntry $zip $csRel.Target
                    if ($null -ne $xml) {
                        $shapes.AddRange([object[]]@(readXlsxShapeRows $xml $zip $csRel.Target $failures $sizeFailures))
                    }
                }
                addSortedShapeLines $units "${sheetName}[図形]" $shapes
                $headerFooter = @(readXlsxSheetHeaderFooter $zip $rel.Target $chartsheetXml $failures)
                if ($headerFooter.Count -gt 0) {
                    addUnitLines $units "${sheetName}[ヘッダー・フッター]" $headerFooter
                }
                continue
            }
            if ($rel.Type -notlike "*/worksheet") {
                continue  # ダイアログシートなど
            }

            $shapes = New-Object System.Collections.Generic.List[object]
            $commentsXml = $null
            $threadedXmls = New-Object System.Collections.Generic.List[string]
            foreach ($sheetRel in (readRelationships $zip $rel.Target).Values) {
                # 要る 3 種類だけ読む（埋め込み・背景の画像など、関係のない大きな部品でサイズの上限に当たらないように）
                if ($sheetRel.Type -notlike "*/drawing" -and $sheetRel.Type -notlike "*/comments" -and $sheetRel.Type -notlike "*/threadedComment") {
                    continue
                }
                $xml = readZipEntry $zip $sheetRel.Target
                if ($null -eq $xml) {
                    continue
                }
                if ($sheetRel.Type -like "*/drawing") {
                    $shapes.AddRange([object[]]@(readXlsxShapeRows $xml $zip $sheetRel.Target $failures $sizeFailures))
                } elseif ($sheetRel.Type -like "*/comments") {
                    $commentsXml = $xml
                } elseif ($sheetRel.Type -like "*/threadedComment") {
                    $threadedXmls.Add($xml)
                }
            }
            addSortedShapeLines $units "${sheetName}[図形]" $shapes

            $comments = readXlsxCommentRows $commentsXml $threadedXmls.ToArray()
            $lines = @($comments.Keys | Sort-Object { (getCellPosition $_)[0] }, { (getCellPosition $_)[1] } |
                ForEach-Object { "$($_.Replace('$', ''))`t$(toObjectCellText @($comments[$_] -split "\r\n|\r|\n"))" })
            if ($lines.Count -gt 0) {
                addUnitLines $units "${sheetName}[コメント]" $lines
            }

            $headerFooter = @(readXlsxSheetHeaderFooter $zip $rel.Target $null $failures)
            if ($headerFooter.Count -gt 0) {
                addUnitLines $units "${sheetName}[ヘッダー・フッター]" $headerFooter
            }
        }
    } finally {
        $zip.Dispose()
    }
    return $units
}

function writeUnits {
    # ユニットごとに "<場所>.tsv" を出力し、出力したファイル数を返す（空のユニットは出力しない）。
    # 元のファイル名は、出力先のフォルダ名（インデクサが作業フォルダから移すときのフォルダ）になる
    param (
        [System.Collections.Specialized.OrderedDictionary]$units,
        [string]$outDir
    )

    $count = 0
    foreach ($unitName in $units.Keys) {
        $lines = New-Object System.Collections.Generic.List[string]
        foreach ($line in $units[$unitName]) {
            $line = $line.TrimEnd()
            if ($line -ne "") {
                $lines.Add($line)
            }
        }
        if ($lines.Count -eq 0) {
            continue
        }

        $path = Join-Path $outDir (toIndexFileName $unitName)
        [System.IO.File]::WriteAllLines((toLongPath $path), $lines, ${utf8Bom})
        $count++
    }
    return $count
}

# Word・PowerPoint に埋め込んだ Office のファイル（Office Open XML。Word 文書・Excel ブック・PowerPoint）の中の文字を読み出す。
# 埋め込んだファイルは、親のファイルの ZIP の中の 1 つの部品（word/embeddings/*.xlsx など。リレーションシップの種類が package）で、
# それ自体が ZIP になっている。部品をバイト列で読み（readZipEntryBytes。部品ごと・1ファイルの合計の上限は親と同じに数える）、
# メモリ上で開いて読む。ファイルには書き出さない。埋め込んだブックのシートも同じ readZipEntryBytes で読むため、
# 申告の大きさを偽ったシートも、親と同じく部品ごとの上限（zipPartMaxBytes）で打ち切り、シートの大きさは合計に数える
# office_reader.ps1 を先に読み込んでおくこと（readDocxUnits・readPptxUnits が readEmbeddedObjectLines を呼ぶ）。
#
# ・形式は、拡張子や名前ではなく中身で決める（xl/workbook.xml があれば Excel、word/document.xml があれば Word、
#   ppt/presentation.xml があれば PowerPoint）。ZIP でない・どれにも当たらないものは読まない（失敗にもしない）
# ・Excel のブックは、表示のシートの文字のセル（共有文字列・インライン文字列・数式の文字の結果）を、行ごとに
#   タブ区切りの 1 行にして返す。表示の範囲に限らず、ほかの表示のシートも読む（非表示・完全に非表示のシートは読まない）
# ・Word・PowerPoint は、中の全ユニットの行を順に並べて返す（埋め込みの中の埋め込みは読まない。深さは 1 段まで）
# ・同じ部品を指す参照（代替表示と本体など）は 1 回だけ読む。N は 1 ファイルの中の、参照の順の通し番号
#   （番号は読む前に振るため、読めなかったものは欠番になる）
# ・出す量にも上限がある。共有文字列は 1 つを多数のセルが参照でき、数 KB の埋め込みから巨大な行ができるため、
#   読んだ入力の大きさとは別に、出す行の文字数（共有文字列を解いた後・参照のたびに数える）を 1 ファイル（親）の中の
#   全埋め込みで合計し、embeddedOutputMaxChars を超えたらその埋め込みを読まない（ZipSizeLimitException の LimitKind が Output）

# 1 ファイル（親の Word・PowerPoint）の全埋め込みから出す、行の文字数の合計の上限（文字）。
# $script: の変数は読み取りのスレッド（runspace）ごとに別になる（テストから一時的に値を変えるときは、この変数を直接上書きする）
$script:embeddedOutputMaxChars = 32MB

function newEmbeddedState {
    # 1 ファイル（親の Word・PowerPoint）の埋め込みを数える状態を返す（通し番号・読んだ部品の名前・出した文字数の合計）
    return @{ Next = 1; Seen = (New-Object System.Collections.Generic.HashSet[string]); OutputChars = 0L }
}

function addEmbeddedOutputChars {
    # 埋め込みから出す行の文字数を合計に足し、上限（embeddedOutputMaxChars）を超えたら ZipSizeLimitException（Output）にする。
    # $state が $null のときは数えない
    param (
        [hashtable]$state,
        [long]$chars
    )

    if ($null -eq $state) {
        return
    }
    $state.OutputChars += $chars
    if ($state.OutputChars -gt $script:embeddedOutputMaxChars) {
        throw [ZipSizeLimitException]::new($script:zipTooLargeMessage, "(埋め込みから出す文字)", $state.OutputChars, "Output")
    }
}

function readXlsxSharedStrings {
    # 共有文字列（xl/sharedStrings.xml）を、番号の順の配列で返す。読み仮名（rPh）は含めない。無ければ空
    param (
        [System.IO.Compression.ZipArchive]$zip
    )

    $xml = readZipEntry $zip "xl/sharedStrings.xml"
    $strings = New-Object System.Collections.Generic.List[string]
    if (-not $xml) {
        return $strings.ToArray()
    }

    $settings = New-Object System.Xml.XmlReaderSettings
    $settings.DtdProcessing = [System.Xml.DtdProcessing]::Prohibit
    $reader = [System.Xml.XmlReader]::Create((New-Object System.IO.StringReader($xml)), $settings)
    try {
        $sb = New-Object System.Text.StringBuilder
        $inT = $false
        $inPhonetic = $false
        while ($reader.Read()) {
            $type = $reader.NodeType
            if ($type -eq [System.Xml.XmlNodeType]::Element) {
                $name = $reader.LocalName
                if ($name -eq "si") {
                    [void]$sb.Clear()
                    if ($reader.IsEmptyElement) { $strings.Add("") }
                } elseif ($name -eq "rPh") {
                    $inPhonetic = -not $reader.IsEmptyElement
                } elseif ($name -eq "t") {
                    $inT = -not $reader.IsEmptyElement
                }
            } elseif ($type -eq [System.Xml.XmlNodeType]::EndElement) {
                $name = $reader.LocalName
                if ($name -eq "si") {
                    $strings.Add($sb.ToString())
                } elseif ($name -eq "rPh") {
                    $inPhonetic = $false
                } elseif ($name -eq "t") {
                    $inT = $false
                }
            } elseif ($inT -and -not $inPhonetic) {
                if ($type -eq [System.Xml.XmlNodeType]::Text -or $type -eq [System.Xml.XmlNodeType]::SignificantWhitespace -or
                    $type -eq [System.Xml.XmlNodeType]::Whitespace -or $type -eq [System.Xml.XmlNodeType]::CDATA) {
                    [void]$sb.Append($reader.Value)
                }
            }
        }
    } finally {
        $reader.Dispose()
    }
    return $strings.ToArray()
}

function readXlsxSheetCellLines {
    # シートの部品（xl/worksheets/sheetN.xml）を流れで読み、文字のセルを行ごとにタブ区切りにして返す。
    # 文字のセルの文字数は、共有文字列を解いたあとで、参照のたびに $state の合計に足す（上限を超えたら例外。addEmbeddedOutputChars）
    param (
        [System.IO.Stream]$stream,
        [string[]]$sharedStrings,
        [hashtable]$state = $null
    )

    $settings = New-Object System.Xml.XmlReaderSettings
    $settings.DtdProcessing = [System.Xml.DtdProcessing]::Prohibit
    $settings.MaxCharactersInDocument = $script:zipPartMaxBytes
    $reader = [System.Xml.XmlReader]::Create($stream, $settings)
    $lines = New-Object System.Collections.Generic.List[string]
    try {
        $rowCells = New-Object System.Collections.Generic.List[string]
        $cellType = $null
        $valueText = New-Object System.Text.StringBuilder
        $inlineText = New-Object System.Text.StringBuilder
        $inValue = $false
        $inInline = $false
        $inT = $false
        $inPhonetic = $false
        while ($reader.Read()) {
            $type = $reader.NodeType
            if ($type -eq [System.Xml.XmlNodeType]::Element) {
                $name = $reader.LocalName
                $isEmpty = $reader.IsEmptyElement
                if ($name -eq "row") {
                    $rowCells.Clear()
                } elseif ($name -eq "c") {
                    $cellType = $reader.GetAttribute("t")
                    [void]$valueText.Clear()
                    [void]$inlineText.Clear()
                } elseif ($name -eq "v") {
                    $inValue = -not $isEmpty
                } elseif ($name -eq "is") {
                    $inInline = -not $isEmpty
                } elseif ($name -eq "rPh") {
                    $inPhonetic = -not $isEmpty
                } elseif ($name -eq "t") {
                    $inT = -not $isEmpty
                }
            } elseif ($type -eq [System.Xml.XmlNodeType]::EndElement) {
                $name = $reader.LocalName
                if ($name -eq "v") {
                    $inValue = $false
                } elseif ($name -eq "is") {
                    $inInline = $false
                } elseif ($name -eq "rPh") {
                    $inPhonetic = $false
                } elseif ($name -eq "t") {
                    $inT = $false
                } elseif ($name -eq "c") {
                    $text = $null
                    if ($cellType -eq "s") {
                        $index = 0
                        if ([int]::TryParse($valueText.ToString().Trim(), [ref]$index) -and $index -ge 0 -and $index -lt $sharedStrings.Count) {
                            $text = $sharedStrings[$index]
                        }
                    } elseif ($cellType -eq "inlineStr") {
                        $text = $inlineText.ToString()
                    } elseif ($cellType -eq "str") {
                        $text = $valueText.ToString()
                    }
                    if ($null -ne $text) {
                        addEmbeddedOutputChars $state ($text.Length + 1)
                        $text = ($text -replace "[\r\n\t]+", " ").Trim()
                        if ($text -ne "") {
                            $rowCells.Add($text)
                        }
                    }
                } elseif ($name -eq "row") {
                    if ($rowCells.Count -gt 0) {
                        $lines.Add(($rowCells -join "`t"))
                    }
                    $rowCells.Clear()
                }
            } elseif ($type -eq [System.Xml.XmlNodeType]::Text -or $type -eq [System.Xml.XmlNodeType]::SignificantWhitespace -or
                $type -eq [System.Xml.XmlNodeType]::Whitespace -or $type -eq [System.Xml.XmlNodeType]::CDATA) {
                if ($inValue) {
                    [void]$valueText.Append($reader.Value)
                } elseif ($inInline -and $inT -and -not $inPhonetic) {
                    [void]$inlineText.Append($reader.Value)
                }
            }
        }
    } finally {
        $reader.Dispose()
    }
    return $lines.ToArray()
}

function readXlsxCellLines {
    # 開いたブック（ZipArchive）の、表示のワークシートの文字のセルを、シートの順・行の順に並べた行の配列で返す
    # （数値・日付・空のセルは読まない）。シートの部品は readZipEntryBytes でバイト列に読む（部品ごとの上限・
    # 1 ファイルの合計の上限は親と同じ。申告を偽ったシートは、部品ごとの上限の超過として例外になる）。
    # 出す文字数は $state の合計に数え、上限を超えたら例外にする
    param (
        [System.IO.Compression.ZipArchive]$zip,
        [hashtable]$state = $null
    )

    $lines = New-Object System.Collections.Generic.List[string]
    $workbookXml = readZipEntry $zip "xl/workbook.xml"
    if ($null -eq $workbookXml) {
        return $lines.ToArray()
    }
    $workbook = newXmlDocument $workbookXml
    $workbookRels = readRelationships $zip "xl/workbook.xml"
    $nsSheet = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"

    $sharedStrings = $null
    foreach ($sheet in $workbook.GetElementsByTagName("sheet", $nsSheet)) {
        if ($sheet.GetAttribute("state") -in @("hidden", "veryHidden")) {
            continue
        }
        $rel = $workbookRels[$sheet.GetAttribute("id", ${nsRel})]
        if ($null -eq $rel -or $rel.Type -notlike "*/worksheet") {
            continue
        }
        $bytes = readZipEntryBytes $zip $rel.Target
        if ($null -eq $bytes) {
            continue
        }
        if ($null -eq $sharedStrings) {
            $sharedStrings = @(readXlsxSharedStrings $zip)
        }
        $stream = New-Object System.IO.MemoryStream (, $bytes)
        try {
            $lines.AddRange([string[]]@(readXlsxSheetCellLines $stream $sharedStrings $state))
        } finally {
            $stream.Dispose()
        }
    }
    return $lines.ToArray()
}

function readEmbeddedPackageLines {
    # 埋め込んだファイルのバイト列から、文字の行を返す（形式は中身で決める。読めない形式は空）
    param (
        [byte[]]$bytes,
        [hashtable]$state = $null,
        [System.Collections.Generic.List[string]]$failures = $null,
        [System.Collections.Generic.List[object]]$sizeFailures = $null
    )

    $lines = New-Object System.Collections.Generic.List[string]
    # ZIP の先頭の印（PK 03 04）。ZIP でなければ（古い形式の OLE など）読まない
    if ($bytes.Length -lt 4 -or $bytes[0] -ne 0x50 -or $bytes[1] -ne 0x4B -or $bytes[2] -ne 3 -or $bytes[3] -ne 4) {
        return $lines.ToArray()
    }

    $memory = New-Object System.IO.MemoryStream (, $bytes)
    $inner = $null
    try {
        $inner = New-Object System.IO.Compression.ZipArchive ($memory, [System.IO.Compression.ZipArchiveMode]::Read, $false)
        if ($null -ne $inner.GetEntry("xl/workbook.xml")) {
            $lines.AddRange([string[]]@(readXlsxCellLines $inner $state))
        } else {
            $units = $null
            if ($null -ne $inner.GetEntry("word/document.xml")) {
                $units = readDocxUnitsFromZip $inner $false $failures $sizeFailures
            } elseif ($null -ne $inner.GetEntry("ppt/presentation.xml")) {
                $units = readPptxUnitsFromZip $inner $false $failures $sizeFailures
            }
            if ($null -ne $units) {
                foreach ($unitName in $units.Keys) {
                    foreach ($line in $units[$unitName]) {
                        addEmbeddedOutputChars $state ($line.Length + 1)
                        $lines.Add($line)
                    }
                }
            }
        }
    } finally {
        if ($null -ne $inner) { $inner.Dispose() }
        $memory.Dispose()
    }
    return $lines.ToArray()
}

function readEmbeddedObjectLines {
    # readXmlLines が集めた埋め込み（Kind が embed）の参照から、埋め込んだファイルの文字を返す。
    # 戻り値: @{ Number = 通し番号; Lines = 行の配列 }。読まない（参照の先が無い・埋め込んだファイルではない・
    # 読んだことのある部品・読めない）ときは $null。
    #
    # 読めないとき: 部品ごとの上限・出す量の上限（ZipSizeLimitException の LimitKind が Part・Output）・壊れた XML・壊れた ZIP など
    # 何かの例外は、その埋め込みだけを読まなかった扱いにし、$failures に部品の名前、大きさの上限なら $sizeFailures に例外を
    # 追加して続ける（ほかの埋め込み・親の文字は出す。埋め込み 1 つで親のファイルの取り込みを失敗にしない）。
    # 投げ直すのは、1 ファイルの合計の上限（LimitKind が Total。ファイル全体の上限）と、中止・停止・メモリ不足の例外
    param (
        [System.IO.Compression.ZipArchive]$zip,
        [hashtable]$rels,   # readRelationships の結果
        $object,
        [hashtable]$state,  # newEmbeddedState の結果
        [System.Collections.Generic.List[string]]$failures = $null,
        [System.Collections.Generic.List[object]]$sizeFailures = $null
    )

    $rel = $rels[[string]$object.RelId]
    if ($null -eq $rel -or $rel.Type -notlike "*/package") {
        return $null
    }
    if (-not $state.Seen.Add([string]$rel.Target)) {
        return $null
    }
    $number = $state.Next
    $state.Next = $number + 1
    $outputBefore = $state.OutputChars  # 読めなかった埋め込みが出しかけた分は、合計から戻す（あとの埋め込みを巻き込まない）

    try {
        $bytes = readZipEntryBytes $zip $rel.Target
        if ($null -eq $bytes) {
            return $null
        }
        $lines = @(readEmbeddedPackageLines $bytes $state $failures $sizeFailures)
    } catch {
        $exception = $_.Exception
        # .NET のメソッド（XmlReader.Read など）の例外は、MethodInvocationException に包まれて届く
        while ($exception -is [System.Management.Automation.MethodInvocationException] -and $null -ne $exception.InnerException) {
            $exception = $exception.InnerException
        }
        $isSize = ($exception -is [ZipSizeLimitException])
        if ($isSize -and $exception.LimitKind -eq "Total") {
            throw
        }
        if ($exception -is [System.OperationCanceledException] -or $exception -is [System.Management.Automation.PipelineStoppedException] -or
            $exception -is [System.OutOfMemoryException]) {
            throw
        }
        $state.OutputChars = $outputBefore
        if ($isSize -and $null -ne $sizeFailures) {
            $sizeFailures.Add($exception)
        }
        if ($null -ne $failures) {
            $failures.Add([string]$rel.Target)
        }
        return $null
    }
    return @{ Number = $number; Lines = $lines }
}

# Officeアプリ（Excel・Word・PowerPoint）の起動・終了と、1ファイルの制限時間の監視。
# COM を使う処理だけをまとめる。使う側が dot-source する（shared.ps1 では読み込まない）。

# ----------------------------------------------------------------------------
# Officeアプリ（Excel・Word・PowerPoint）の起動・終了
# ----------------------------------------------------------------------------

# 起動中のアプリ: 名前 → @{ Com; Pid; Shared }
$script:apps = @{}

# ExitWait: Quit の後、終わるのを待つ時間（ミリ秒）。過ぎたら強制終了する（quitApp）。
#   Excel は抽出で取り出したCOMオブジェクトが解放されきらないため、インデクサが動いている間は Quit しても終わらず、
#   待ちの上限まで待ってから強制終了していた（実測: 毎回 5 秒待って強制終了）。待つだけ無駄なため短くする。
#   GC で解放を促して自分で終わらせる方法は、インデクサの終了が COM の解放待ちで約 60 秒止まることがあった（実測 25 回中 1～2 回）ため採らない
# 利用者に渡すときの、アプリごとの違い（handOverForeignApp・restoreHandedOverApp）:
#   Items      : 開いているファイルの一覧を持つ、アプリのプロパティの名前（Workbooks・Documents・Presentations）
#   Close      : 自分のファイルを保存せずに閉じる処理（引数は 1 つのファイル）
#   Restore    : 渡すときに戻す設定。getApp が変える設定は、ここに全部ある（テストで確かめる）。Required は戻らないと渡し切れない設定、
#                Optional は戻ればよい設定、ShowWindow は窓を出すか（Visible を真にする行は restoreHandedOverApp の中の 1 か所だけ）
#   WindowCheck: ファイルの一覧を読めないとき、見える窓があるかで利用者のものかを判断するか
#                （Word は自分で窓を隠しているため窓では判断できない。読めなければ渡しも終了もせず、持ち続けて後で読み直す）
#   GuardUserWindow: 取り込み中に、見える窓が一度でもあったプロセス（利用者がファイルを開いた）を、制限時間を過ぎても強制終了しない（OfficeWatchdog）。
#                （PowerPoint だけ。Excel・Word は、非表示のプロセスで利用者のファイルを開いたときに窓が見えるかを確かめていないため対象にしない）
$appInfo = @{
    Excel      = @{
        ProgId = "Excel.Application"; Process = "EXCEL"; ExitWait = 1000
        Items = "Workbooks"; Close = { param ($item) $item.Close($false) }
        Restore = @{
            Required = @(@("DisplayAlerts", $true), @("UserControl", $true))
            Optional = @(@("EnableEvents", $true), @("ScreenUpdating", $true), @("AskToUpdateLinks", $true), @("AutomationSecurity", 1))
            ShowWindow = $true
        }
        WindowCheck = $true
    }
    Word       = @{
        ProgId = "Word.Application"; Process = "WINWORD"; ExitWait = 5000
        Items = "Documents"; Close = { param ($item) $item.Close(0) }  # wdDoNotSaveChanges
        Restore = @{
            Required = @(,@("DisplayAlerts", -1))  # wdAlertsAll
            Optional = @(,@("AutomationSecurity", 1))
            ShowWindow = $true
        }
        WindowCheck = $false
    }
    # SingleInstance: 1つのセッションに1つのプロセスしか持てないアプリ（PowerPointだけ）。
    # 既に起動している（利用者が開いている）ときは、接続せずに使わない（下の getApp）
    PowerPoint = @{
        ProgId = "PowerPoint.Application"; Process = "POWERPNT"; ExitWait = 5000; SingleInstance = $true
        Items = "Presentations"; Close = { param ($item) $item.Close() }
        Restore = @{
            Required = @(,@("DisplayAlerts", 2))  # ppAlertsAll
            Optional = @(,@("AutomationSecurity", 1))
            ShowWindow = $false
        }
        WindowCheck = $true
        GuardUserWindow = $true
    }
}

# SingleInstance のアプリが、既に自分のセッションで起動している（利用者が使用中の）ときに投げる例外の文言。
# 呼ぶ側は "<アプリ名>${officeAppInUseMessage}" の形で使う。Reroute（extract_office.ps1 の officeRequiredMessage・
# OperationCanceledException）と取り違えないよう、型（InvalidOperationException）でも区別する
${officeAppInUseMessage} = " が起動しているため、更新に使用できません"

# 起動した Office のプロセスの優先度は下げない（Normal のまま）。利用者がダブルクリックしたファイルがインデックス作成の Excel・Word で開くことがあり、
# PowerPoint は 1 つのプロセスしか持てないため、利用者とプロセスを共有しないと確実には言えない。利用者の操作を遅くしないよう、
# 優先度を下げるのは、利用者と共有しないインデックス作成のスレッドだけにする（docs/design/structure/threads.md「スレッドの一覧」）
# 起動したアプリの PID を入れる入れ物（ConcurrentDictionary[int,object]。値は @{ ProcessName; StartTicks }。$null なら入れない）。
# 画面が閉じるときに、インデックス作成が起動した Office を、プロセス名と起動時刻を照らしてから止めるために使う
$script:officePidSink = $null
# 起動した Office の PID の記録を置くフォルダ（<ワークスペース>\office_pids\<PC の鍵>。$null なら書かない）。
# shared はツールを知らないため、使う側（インデックス作成）が場所を決めて入れる（office_process.ps1 の addOfficeRecord・removeOfficeRecord）。
# 記録は、次に画面を起動したときに、残った Office を確認して止めるために使う（書けなくても取り込みは続ける。その Office は止める対象にならない）
$script:officeRecordDir = $null
# 自分が開くファイルの置き場（インデックス作成の作業領域の一時フォルダ。$null なら、開いているファイルをすべて利用者のものとみなす）。
# 使う側が入れる。置き場の外のファイルが Excel・Word・PowerPoint に開かれたら、利用者が開いたファイルとして扱う（getForeignWorkbookCount・handOverApp）
$script:officeOwnDir = $null
# Excel・Word・PowerPoint を利用者に渡そうとしたときに呼ぶ処理（スクリプトブロック。引数はアプリ名と、渡し切れたか（戻しきれたか。$null は、渡すか決められず持ち続ける）。呼ぶ変数が $null なら何もしない）。ログを書く使う側が入れる
$script:onOfficeHandOver = $null
# 渡そうとして戻しきれなかったアプリ（COM の参照を放さずに持ち続ける）
$script:officeKeptApps = @()
# 渡し切れずに持ち続けたアプリを仕上げ直して待つ、取り込みのスレッドの終わりの上限（秒）と間隔（ミリ秒）
$script:officeKeptWaitSeconds = 30
$script:officeKeptWaitStep = 500

function resolveLongName {
    # 8.3 の短い名前（TEST~1 など）を含むパスを長い名前にする。読めなければ $null
    param ([string]$path)

    try {
        return (Get-Item -LiteralPath $path -ErrorAction Stop).FullName
    } catch {
        return $null
    }
}

function resolveOwnDir {
    # 自分が開くブックの置き場（一時フォルダ）を、比べる形にする。短い名前を長くできなければ、そのまま使う。
    # 置き場が決まっていなければ $null（そのときは開いたブックをすべて利用者のものと数える）
    param ([string]$dir)

    if (-not $dir) {
        return $null
    }
    $long = resolveLongName $dir
    return $(if ($long) { $long } else { $dir })
}

function isUnderDir {
    # path が dir の下にあるか。両方を正規化し、dir は区切りで終わる形にして、大文字小文字を区別せずに前置で比べる
    # （tmp と tmp2 を取り違えない）。正規化できない（URL など）ときは、下に無いものとする
    param ([string]$path, [string]$dir)

    try {
        $full = [System.IO.Path]::GetFullPath($path)
        $base = [System.IO.Path]::GetFullPath($dir).TrimEnd('\') + '\'
        return $full.StartsWith($base, [System.StringComparison]::OrdinalIgnoreCase)
    } catch {
        return $false
    }
}

function getWorkbookSplit {
    # アプリで開いているファイル（Excel のブック・Word の文書・PowerPoint のプレゼンテーション）を、自分が開いたもの（置き場の下）と
    # 利用者が開いたもの（外）に分ける。@{ Own; Foreign }
    # 開いたファイルの FullName を控えて照合する方法は、失敗の途中で Open が戻らなかったファイルを控えられないため採らない。
    # 短い名前（~ を含む）は長い名前にしてから比べる。読めなければ、置き場の下と確かめられないので利用者のものと数える
    # （データを失わない側。自分のものは置き場の下にあり、読める）
    param ($com, [string]$name)

    $own = New-Object System.Collections.ArrayList
    $foreign = New-Object System.Collections.ArrayList
    $workbooks = $com.($appInfo[$name].Items)
    try {
        foreach ($book in @($workbooks)) {
            if ($null -eq $book) { continue }
            $full = [string]$book.FullName
            if ($full.Contains('~')) {
                $full = resolveLongName $full
            }
            if ($full -and $script:officeOwnDir -and (isUnderDir $full $script:officeOwnDir)) {
                [void]$own.Add($book)
            } else {
                [void]$foreign.Add($book)
            }
        }
    } finally {
        try { releaseComObject $workbooks } catch {}
    }
    return @{ Own = $own; Foreign = $foreign }
}

function releaseWorkbookSplit {
    # getWorkbookSplit で取り出したファイルの参照を放す（残すとアプリが終わらなくなる）
    param ($split)

    foreach ($book in @($split.Own) + @($split.Foreign)) { try { releaseComObject $book } catch {} }
}

function getForeignWorkbookCount {
    # アプリで利用者が開いたファイル（置き場の外）の数。読めない（COM の例外）ときは -1（分からない。handOverForeignApp が判断する）
    param ($com, [string]$name)

    try {
        $split = getWorkbookSplit $com $name
        $count = @($split.Foreign).Count
        # 取り出したファイルの参照を残すとアプリが終わらなくなるため、数えたら放す
        releaseWorkbookSplit $split
        return $count
    } catch {
        return -1
    }
}

function testProcessHasWindow {
    # 起動で控えた PID のプロセスに、見える窓があるか。PID だけを見る（窓を中身で探さない）。控えていなければ（0）偽
    param ([int]$processId, [string]$processName)

    if ($processId -le 0) {
        return $false
    }
    $process = Get-Process -Id $processId -ErrorAction SilentlyContinue
    return [bool]($process -and $process.ProcessName -eq $processName -and $process.MainWindowHandle -ne 0)
}

function testProcessExists {
    # 指定した PID に、指定した名前のプロセスがあるか。PID と名前だけを見る
    param ([int]$processId, [string]$processName)

    $process = Get-Process -Id $processId -ErrorAction SilentlyContinue
    return [bool]($process -and $process.ProcessName -eq $processName)
}

function getMonotonicMilliseconds {
    # 経過時間の計測用の、戻らない時計（ミリ秒）
    return [long]([System.Diagnostics.Stopwatch]::GetTimestamp() * 1000 / [System.Diagnostics.Stopwatch]::Frequency)
}

function getOwnSessionProcessIds {
    # 自分のセッションで動いている、指定した名前のプロセスのIDの一覧。
    # ほかのセッション（同じPCの別の利用者・別の作業フォルダの tebunko 等）のプロセスは、自分のものと取り違えないため数えない
    param (
        [string]$processName,
        [int]$sessionId
    )

    return @(Get-Process -Name $processName -ErrorAction SilentlyContinue |
        Where-Object { $_.SessionId -eq $sessionId } | ForEach-Object { $_.Id })
}

function getApp {
    # アプリのCOMオブジェクトを返す。起動していなければ起動する。
    # SingleInstance のアプリ（PowerPoint）が既に自分のセッションで起動しているときは、新しいプロセスができず
    # 利用者のアプリに接続することになるため、接続せずに例外を投げる（呼ぶ側は後回しにする）
    param (
        [string]$name
    )

    if (-not $script:apps.ContainsKey($name)) {
        $info = $appInfo[$name]
        $sessionId = [System.Diagnostics.Process]::GetCurrentProcess().SessionId

        if ($info.SingleInstance -and (getOwnSessionProcessIds $info.Process $sessionId).Count -gt 0) {
            throw (New-Object System.InvalidOperationException "${name}${officeAppInUseMessage}")
        }

        # 終了できなかった場合に強制終了するため、新しく起動したプロセスのIDを控えておく
        $before = getOwnSessionProcessIds $info.Process $sessionId
        $com = New-Object -ComObject $info.ProgId
        $after = getOwnSessionProcessIds $info.Process $sessionId
        $newIds = @($after | Where-Object { $before -notcontains $_ })

        if ($info.SingleInstance -and $newIds.Count -eq 0) {
            # 事前の確認から New-Object の間に、利用者が先にアプリを起動した（先に接続した）。
            # DisplayAlerts・AutomationSecurity などの設定を変える前に解放し、利用者のアプリに触らない
            try { releaseComObject $com } catch {}
            throw (New-Object System.InvalidOperationException "${name}${officeAppInUseMessage}")
        }
        # 起動時刻を控える。止める前に、控えたときと同じプロセスか照らすために使う（isSameOfficeProcess）。読めなければ $null（止める対象にならない）
        $startTicks = $null
        if ($newIds.Count -eq 1) {
            $started = Get-Process -Id ([int]$newIds[0]) -ErrorAction SilentlyContinue
            if ($started -and $started.ProcessName -eq $info.Process) {
                $startTicks = getOfficeStartTicks $started
            }
        }
        if ($newIds.Count -eq 1 -and $script:officePidSink) {
            $script:officePidSink[[int]$newIds[0]] = @{ ProcessName = $info.Process; StartTicks = $startTicks }
        }
        if ($newIds.Count -eq 1 -and $script:officeRecordDir -and $null -ne $startTicks) {
            # 起動時刻が読めたときだけ記録する（読めなければ、残っても止める対象にならない）
            [void](addOfficeRecord $script:officeRecordDir ([int]$newIds[0]) $info.Process $startTicks)
        }

        switch ($name) {
            "Excel" {
                $com.Visible = $false
                $com.DisplayAlerts = $false
                $com.EnableEvents = $false
                $com.ScreenUpdating = $false
                $com.AskToUpdateLinks = $false
            }
            "Word" {
                $com.Visible = $false
                $com.DisplayAlerts = 0  # wdAlertsNone
            }
            "PowerPoint" {
                # PowerPointはウィンドウを隠せないため、ファイルをウィンドウ無しで開く（Visible は変更しない）
                $com.DisplayAlerts = 1  # ppAlertsNone
            }
        }
        $com.AutomationSecurity = 3  # msoAutomationSecurityForceDisable（マクロ無効）

        # Excel・Word は起動中のアプリに接続することがある（新しいプロセスができない場合。PowerPoint は上で防いでいるため
        # ここには来ない）。その場合は利用者のものなので終了させない
        $script:apps[$name] = @{
            Com         = $com
            Pid         = $(if ($newIds.Count -eq 1) { $newIds[0] } else { 0 })
            ProcessName = $info.Process
            StartTicks  = $startTicks
            Shared      = ($newIds.Count -eq 0)
            GuardWindow = [bool]$info.GuardUserWindow
        }
        $script:officeWatchdog.UpdateWatchedPids($script:apps)
    }
    return $script:apps[$name].Com
}

function restoreHandedOverApp {
    # 渡すアプリに対して、(0) 自分が開いたファイル（置き場の下と確かめられたもの）を保存せずに閉じる (1) 必須の設定（$appInfo の Restore.Required と、窓を出すアプリは Visible）
    # (2) 任意の設定を戻す。state に済んだものを控えるので、何度呼んでも済んだものはやり直さない。全部済んだら $true
    # tries: 必須の設定をやり直す回数（失敗したときだけ間を置く）。利用者のファイルは閉じない
    param ($state, [int]$tries = 1)

    $com = $state.Com
    $info = $appInfo[$state.Name]
    if (-not $state.BooksClosed) {
        try {
            $books = getWorkbookSplit $com $state.Name
            # 前の回の一覧の参照は、取り直した一覧に置き換える前に放す
            if ($state.Books) {
                releaseWorkbookSplit $state.Books
            }
            $closeFailed = $false
            foreach ($book in $books.Own) {
                try { & $info.Close $book } catch { $closeFailed = $true }
            }
            $state.Books = $books
            # 閉じられなかったものが 1 つでもあれば、立てない（次回に一覧を取り直す。閉じたものは一覧から消えるので二重には閉じない）
            $state.BooksClosed = (-not $closeFailed)
        } catch {}
    }
    # 窓・UserControl・DisplayAlerts が戻らないまま参照を放すと、Excel が保存の確認なしに終わりうるため、成功を確かめる
    $required = @($info.Restore.Required)
    if ($info.Restore.ShowWindow) { $required += , @("Visible", $true) }
    $optional = @($info.Restore.Optional)
    for ($try = 0; $try -lt $tries; $try++) {
        $left = @($required | Where-Object { -not $state.Done[$_[0]] })
        if ($left.Count -eq 0) { break }
        if ($try -gt 0) { Start-Sleep -Milliseconds 200 }
        foreach ($setting in $left) {
            try { $com.($setting[0]) = $setting[1]; $state.Done[$setting[0]] = $true } catch {}
        }
    }
    foreach ($setting in @($optional | Where-Object { -not $state.Done[$_[0]] })) {
        try { $com.($setting[0]) = $setting[1]; $state.Done[$setting[0]] = $true } catch {}
    }
    return [bool]($state.BooksClosed -and (@($required + $optional | Where-Object { -not $state.Done[$_[0]] }).Count -eq 0))
}

function releaseHandedOverApp {
    # このスレッドが持つ COM を解放しきる。WaitForPendingFinalizers は長く止まることがあるため使わない
    param ($state)

    try {
        if ($state.Books) {
            releaseWorkbookSplit $state.Books
        }
        releaseComObject $state.Com
        [GC]::Collect()
    } catch {}
}

function untrackApp {
    # アプリを (a) 見張りの対象から外す (b) 一括終了の対象から外す (c) 残り物の確認の記録から消す。誰も止めなくなる。それぞれ、ほかが失敗しても行う
    param ([string]$name, $app)

    try { $script:apps.Remove($name) } catch {}
    try { $script:officeWatchdog.UpdateWatchedPids($script:apps) } catch {}
    try {
        if ($app.Pid -and $script:officePidSink) {
            $removed = $null
            [void]$script:officePidSink.TryRemove([int]$app.Pid, [ref]$removed)
        }
    } catch {}
    try {
        if ($app.Pid -and $script:officeRecordDir) {
            removeOfficeRecord $script:officeRecordDir ([int]$app.Pid)
        }
    } catch {}
}

function keepUndecidedApp {
    # ファイルの一覧が読めず、利用者のファイルがあるか分からないアプリ（窓で判断できない Word）を、終了させず・渡さず、持ち続ける。
    # 利用者のファイルがあるかもしれないので、誰も止めない（untrackApp）。retryKeptApps が一覧を読み直し、利用者のファイルがあれば渡し、
    # 自分のファイルだけなら終了させる
    param ([string]$name)

    $app = $script:apps[$name]
    untrackApp $name $app
    $script:officeKeptApps += , @{ Name = $name; Com = $app.Com; Pid = [int]$app.Pid; StartTicks = $app.StartTicks; BooksClosed = $false; Books = $null; Done = @{}; Undecided = $true }
    if ($script:onOfficeHandOver) {
        # 渡したかどうかがまだ決まっていない（$null）ことを知らせる
        try { & $script:onOfficeHandOver $name $null } catch {}
    }
}

function quitApp {
    # アプリを終了させる。Quit し、COM の参照を放し、控えた PID のプロセス（名前も合うもの）が終わるのを待つ。
    # GC::WaitForPendingFinalizers() は COM の解放待ちで長時間（約 60 秒）止まることがあるため使わず、
    # 待ち時間（ExitWait）を過ぎても終わらなければ PID を指定して強制終了する（名前では止めない）。終わったと確かめられたら $true。
    # 待つ前・止める前に、控えたプロセスと同じか（名前・起動時刻）を照らす（isSameOfficeProcess）。起動時刻が違えば、控えたプロセスはもう終わっているので $true
    # （別のプロセスを待たず、止めない）。起動時刻が読めない・控えていないときは、止めず待たずに $false（記録を残し、次の起動の確認に任せる）
    param ([string]$name, $com, [int]$processId, $startTicks = $null)

    try { $com.Quit() } catch {}
    try { releaseComObject $com } catch {}
    if ($processId -le 0) {
        return $true
    }
    $process = Get-Process -Id $processId -ErrorAction SilentlyContinue
    if ($null -eq $process -or $process.ProcessName -ne $appInfo[$name].Process) {
        return $true
    }
    if (-not (isSameOfficeProcess $process $appInfo[$name].Process $startTicks)) {
        # Quit の直後に自分で終わったものは、終わったとして返す。起動時刻が違えば控えたプロセスは終わっている。分からないときは $false
        try { if ($process.HasExited) { return $true } } catch {}
        return ((compareOfficeProcess $process $appInfo[$name].Process $startTicks) -eq "Different")
    }
    $wait = $appInfo[$name].ExitWait
    if ($process.WaitForExit($wait)) {
        return $true
    }
    # 終了処理中のプロセスは Kill() が「アクセス拒否」で失敗することがあるが、そのまま終了するため無視する
    try { $process.Kill() } catch {}
    # 強制終了は非同期のため、同じ上限で終わるのを待つ。それでも残った場合は、次の getApp が
    # 利用者のものとみなして後回しにする（安全な側に倒れる）
    return [bool]$process.WaitForExit($wait)
}

function quitKeptApp {
    # 自分のファイルだけだと分かった、持ち続けたアプリを終了させる（quitApp）
    param ($state)

    [void](quitApp $state.Name $state.Com $state.Pid $state.StartTicks)
}

function handOverApp {
    # 起動したアプリ（Excel・Word・PowerPoint）を、利用者に渡す。Quit も強制終了もしない（利用者のファイルを閉じない）。渡したアプリはもう使わない。
    # 見張り・終了時の一括終了・次の起動の残り物の確認のどれからも外すので、誰も止めない。
    # Shared のアプリ（利用者のアプリに接続したもの）には当てない（止めず、設定も変えない）
    param ([string]$name)

    $app = $script:apps[$name]
    if ($null -eq $app -or $app.Shared) {
        return $false
    }
    untrackApp $name $app

    # 自分のファイルを閉じる・設定を戻す・窓を出す、を全部通して初めて「渡した」。通らなければ、持ち続けて後で設定し直す
    $state = @{ Name = $name; Com = $app.Com; Pid = [int]$app.Pid; StartTicks = $app.StartTicks; BooksClosed = $false; Books = $null; Done = @{} }
    $ok = restoreHandedOverApp $state 3
    if ($ok) {
        releaseHandedOverApp $state
    } else {
        # 戻しきれなかったアプリは、参照を放すと終わるおそれがあるため、放さずに持ち続ける（止めも強制終了もしない）。
        # retryKeptApps と waitKeptApps が設定し直す。取り込みのスレッドが終わるまでに通らなければ、参照が切れる
        $script:officeKeptApps += , $state
    }

    if ($script:onOfficeHandOver) {
        try { & $script:onOfficeHandOver $name $ok } catch {}
    }
    return $ok
}

function retryKeptApps {
    # 渡し切れずに持ち続けているアプリをもう一度仕上げる（済んでいないものだけ）。全部通れば参照を放して「渡した」ログを書く。待たない。
    # 控えた PID のプロセスが（その名前で）もう無ければ、利用者が先に終えたので、参照だけ放して一覧から外す（PID と名前だけを見る。窓は探さない。止めない）
    if (@($script:officeKeptApps).Count -eq 0) {
        return
    }
    $remaining = @()
    foreach ($kept in @($script:officeKeptApps)) {
        if ($kept.Pid -gt 0 -and -not (testProcessExists ([int]$kept.Pid) $appInfo[$kept.Name].Process)) {
            releaseHandedOverApp $kept
            continue
        }
        if ($kept.Undecided) {
            # 利用者のファイルがあるか、一覧を読み直す。まだ読めなければ、そのまま持ち続ける
            $foreignCount = getForeignWorkbookCount $kept.Com $kept.Name
            if ($foreignCount -lt 0) {
                $remaining += , $kept
                continue
            }
            if ($foreignCount -eq 0) {
                quitKeptApp $kept
                continue
            }
            $kept.Undecided = $false
        }
        if (restoreHandedOverApp $kept 1) {
            releaseHandedOverApp $kept
            if ($script:onOfficeHandOver) {
                try { & $script:onOfficeHandOver $kept.Name $true } catch {}
            }
        } else {
            $remaining += , $kept
        }
    }
    $script:officeKeptApps = $remaining
}

function waitKeptApps {
    # 取り込みのスレッドの終わりに限り、持ち続けているアプリを、間を置いて上限まで仕上げ直す。持ち続けが無ければ待たない。
    # shouldStop が真を返したら（中止・画面を閉じる）次の刻みで抜ける。上限に届かなかったものは、そのまま持ち続け（スレッドが終わると参照が切れる）
    param ([scriptblock]$shouldStop = { $false })

    $started = getMonotonicMilliseconds
    while (@($script:officeKeptApps).Count -gt 0) {
        retryKeptApps
        if (@($script:officeKeptApps).Count -eq 0 -or ((getMonotonicMilliseconds) - $started) -ge ($script:officeKeptWaitSeconds * 1000) -or (& $shouldStop)) {
            break
        }
        Start-Sleep -Milliseconds $script:officeKeptWaitStep
    }
}

function handOverForeignApp {
    # 起動したアプリ（Excel・Word・PowerPoint）に利用者が開いたファイルがあれば、利用者に渡して $true を返す。無ければ何もせず $false
    param ([string]$name)

    # 前に戻しきれなかったアプリがあれば、ここで仕上げ直す
    retryKeptApps
    $app = $script:apps[$name]
    if ($null -eq $app -or $app.Shared) {
        return $false
    }
    $count = getForeignWorkbookCount $app.Com $name
    if ($count -eq 0) {
        # 利用者のファイルが今は無い（開いて閉じた）なら、利用者が使った印を消す。印が残ると、
        # 次のファイルで固まっても止められず、窓の無い固まったアプリが残るため（また窓が見えれば、見張りが印を付け直す）
        if ($app.Pid -and $script:officeWatchdog.State.Users) {
            $removed = $null
            [void]$script:officeWatchdog.State.Users.TryRemove([int]$app.Pid, [ref]$removed)
        }
        return $false
    }
    # ファイルの一覧を読めない（COM が呼び出しを拒んだ。利用者が操作中のことがある）ときは、
    #   窓で判断できるアプリ（Excel・PowerPoint）: 見える窓があれば利用者が使っているとみなして渡し、無ければ何もしない（今までどおり終了させる）
    #   窓で判断できないアプリ（Word。自分で窓を隠している）: 渡しも終了もさせず、持ち続けて後で一覧を読み直す（空の窓を出さず、データも失わない）
    if ($count -lt 0) {
        if ($appInfo[$name].WindowCheck) {
            if (-not (testProcessHasWindow ([int]$app.Pid) $appInfo[$name].Process)) { return $false }
        } else {
            keepUndecidedApp $name
            return $true
        }
    }
    [void](handOverApp $name)
    return $true
}

function stopApp {
    param (
        [string]$name
    )

    $app = $script:apps[$name]
    if ($null -eq $app) {
        return
    }
    # インデックス作成中に利用者が同じアプリでファイルを開いた場合は、閉じずに利用者に渡す（自分のファイルだけなら、下で終了させる）
    if (handOverForeignApp $name) {
        return
    }
    $script:apps.Remove($name)
    $script:officeWatchdog.UpdateWatchedPids($script:apps)

    # 利用者のアプリに接続したもの（Shared）は、終了させず、参照だけ放す。利用者に渡したものとして、記録も消す
    if ($app.Shared) {
        try { releaseComObject $app.Com } catch {}
        $exited = $true
    } else {
        $exited = quitApp $name $app.Com $app.Pid $app.StartTicks
    }
    # 記録は、プロセスが終わったと確かめてから消す。終わらなければ残す（次の起動の確認に任せる）
    if ($app.Pid -and $script:officeRecordDir -and $exited) {
        removeOfficeRecord $script:officeRecordDir ([int]$app.Pid)
    }
    if ($app.Pid -and $script:officePidSink) {
        $removed = $null
        [void]$script:officePidSink.TryRemove([int]$app.Pid, [ref]$removed)
    }
}

function stopAllApps {
    retryKeptApps
    # 1つのアプリの終了に失敗しても、残りのアプリは終了させる
    foreach ($name in @($script:apps.Keys)) {
        try {
            stopApp $name
        } catch {
            Write-Host "    ${name} の終了に失敗しました: $($_.Exception.Message)" -ForegroundColor Yellow
        }
    }
}

function getAppName {
    # 拡張子から、抽出に使うアプリの名前を返す
    param (
        [string]$path
    )

    switch -Regex ([System.IO.Path]::GetExtension($path).ToLower()) {
        "^\.xls" { return "Excel" }
        "^\.doc" { return "Word" }
        "^\.ppt" { return "PowerPoint" }
    }
    return $null
}

function releaseComObject($object) {
    if ($null -ne $object) {
        [void][System.Runtime.InteropServices.Marshal]::ReleaseComObject($object)
    }
}

# ----------------------------------------------------------------------------
# 1ファイルの制限時間の監視
# ----------------------------------------------------------------------------

function getWatchdogVerdict {
    # 見張りが、控えたプロセス 1 つをどうするかを決める。'Skip'（何もしない）／'Spare'（期限を過ぎたが、利用者が使ったので止めない）／'Kill'（期限を過ぎたので止める）
    # entry: @{ Id; StartTicks; GuardWindow }、hasWindow: 今、窓が見えるか、users: 「利用者が使った」印（PID → @{ StartTicks }。窓が見えたらここに入れる）、due: 制限時間を過ぎたか
    # 印は、起動時刻が同じものだけを有効とする（PID が使い回されたプロセスを守らない）
    param ($entry, [bool]$hasWindow, $users, [bool]$due)

    if ($entry.GuardWindow) {
        if ($hasWindow) {
            $users[[int]$entry.Id] = @{ ProcessName = $entry.ProcessName; StartTicks = $entry.StartTicks }
        }
        $mark = $null
        if ($users.TryGetValue([int]$entry.Id, [ref]$mark) -and $mark.StartTicks -eq $entry.StartTicks) {
            if ($due) { return 'Spare' }
            return 'Skip'
        }
    }
    if ($due) { return 'Kill' }
    return 'Skip'
}

# 取り込み中のCOM呼び出しは応答が無いと戻らず、Ctrl+C も効かないため、別スレッドで制限時間を監視する。
# 制限時間を過ぎたら、自分で起動したOfficeアプリを強制終了する（COM呼び出しが例外で戻り、そのファイルは失敗になる）。
# スレッド（ランスペース）ごとに 1 つ持つ（下の $script:officeWatchdog）。見張りのスレッド（[PowerShell]::Create() の別のランスペース）へは、
# クラスではなく State（[hashtable]::Synchronized）を渡す。
class OfficeWatchdog {
    # 見張りのスレッドと共有する値。
    #   Deadline: 取り込み中のファイルの制限時刻（取り込み中でなければ MaxValue）
    #   Pids    : 強制終了してよいプロセス（自分で起動したOfficeアプリ）。@{ Id; ProcessName; StartTicks } の配列。止める前に起動時刻を照らす
    #   TimedOut: 制限時間を過ぎて強制終了した
    #   Stop    : 見張りのスレッドに終わりを伝える
    #   Users   : 取り込み中に、見える窓が一度でもあったプロセス（利用者が使った印）。PID → @{ ProcessName; StartTicks }（ConcurrentDictionary）。
    #             印のあるプロセスは、制限時間を過ぎても強制終了しない。画面を閉じるときの KillOffice と共有するため、使う側が入れ替える
    #   Abandon : 印のあるプロセスを止めずに、制限時間を過ぎたレーンを諦めたと、司令に伝える入れ物（Synchronized な @{ Abandoned }）。
    #             取り込みのスレッドが入れる。無ければ（司令のスレッドで取り込むとき）止めないだけにする
    #   WindowProbe: 窓があるかを見分ける関数の名前（既定は testOfficeProcessHasWindow。テストで差し替える）
    [hashtable]$State
    # 強制終了してよいプロセスの名前（Officeアプリ）
    [string[]]$ProcessNames
    hidden $Thread

    OfficeWatchdog([string[]]$processNames) {
        $this.State = [hashtable]::Synchronized(@{
            Deadline = [datetime]::MaxValue; Pids = @(); TimedOut = $false; Stop = $false
            Users = (New-Object 'System.Collections.Concurrent.ConcurrentDictionary[int,object]'); Abandon = $null
            WindowProbe = 'testOfficeProcessHasWindow'
        })
        $this.ProcessNames = $processNames
        $this.Thread = $null
    }

    [void] UpdateWatchedPids([hashtable]$apps) {
        # 強制終了してよいプロセスIDを、起動中のアプリのうち自分で起動したものにする（利用者のアプリは終了させない）
        $previous = @($this.State.Pids)
        $this.State.Pids = @($apps.Values | Where-Object { -not $_.Shared -and $_.Pid } |
            ForEach-Object { @{ Id = [int]$_.Pid; ProcessName = $_.ProcessName; StartTicks = $_.StartTicks; GuardWindow = [bool]$_.GuardWindow } })
        # 見張りから外れたプロセス（終わった・利用者に渡した）と、同じ PID でも起動時刻が違うもの（PID が使い回された）の「利用者が使った」印は消す
        # （古い印で、別のプロセスを止めなくならないように）。ほかのレーンの印は、自分が見張ったことのある PID だけを対象にして消さない
        foreach ($old in $previous) {
            $now = @($this.State.Pids | Where-Object { $_.Id -eq $old.Id })
            if ($now.Count -eq 0 -or $now[0].StartTicks -ne $old.StartTicks) {
                $removed = $null
                [void]$this.State.Users.TryRemove([int]$old.Id, [ref]$removed)
            }
        }
        foreach ($entry in @($this.State.Pids)) {
            $mark = $null
            if ($this.State.Users.TryGetValue([int]$entry.Id, [ref]$mark) -and $mark.StartTicks -ne $entry.StartTicks) {
                $removed = $null
                [void]$this.State.Users.TryRemove([int]$entry.Id, [ref]$removed)
            }
        }
    }

    [void] Start() {
        # 見張りは別のランスペースで動くので、照合の関数の定義を渡す（式を書き写さない。worker_pool.ps1 と同じ InitialSessionState の形）
        $sessionState = [System.Management.Automation.Runspaces.InitialSessionState]::CreateDefault2()
        $functionNames = @('isSameOfficeProcess', 'compareOfficeProcess', 'getOfficeStartTicks', 'testOfficeProcessHasWindow', 'getWatchdogVerdict')
        if ($this.State.WindowProbe -and $functionNames -notcontains [string]$this.State.WindowProbe) {
            $functionNames += [string]$this.State.WindowProbe
        }
        foreach ($name in $functionNames) {
            $sessionState.Commands.Add([System.Management.Automation.Runspaces.SessionStateFunctionEntry]::new($name, (Get-Command $name -CommandType Function).Definition))
        }
        $runspace = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace($sessionState)
        $runspace.Open()
        $ps = [PowerShell]::Create()
        $ps.Runspace = $runspace
        [void]$ps.AddScript({
            param($watch, [string[]]$processNames)
            while (-not $watch.Stop) {
                Start-Sleep -Milliseconds 500
                $deadline = $watch.Deadline
                if ($deadline -eq [datetime]::MaxValue) {
                    continue
                }
                $due = ([datetime]::Now -ge $deadline)
                # 取り込み中は毎回、窓のあるプロセスに「利用者が使った」印を残す（固まったプロセスの窓は、約 5 秒で別のプロセスのゴースト窓に差し替わって
                # 見えなくなるので、制限時間を過ぎたときに見るだけでは足りない。固まる前に見た窓を、固まった後の判断に使う）。
                # 制限時間を過ぎたとき、印のあるプロセスは止めず、止めた分だけを targets に集める
                $spared = $false
                $targets = New-Object System.Collections.Generic.List[object]
                foreach ($entry in @($watch.Pids)) {
                    # 期限の前に見るのは、窓を見張るアプリ（PowerPoint）だけ（ほかは期限を過ぎてから見る）
                    if (-not $due -and -not $entry.GuardWindow) {
                        continue
                    }
                    $process = $null
                    $keep = $false
                    try {
                        # 終了済みでIDが別のプロセスに再利用されている場合に備え、Officeアプリであること、控えたときと同じプロセスであること（名前・起動時刻）を確かめる
                        $process = [System.Diagnostics.Process]::GetProcessById([int]$entry.Id)
                        if ((isSameOfficeProcess $process $entry.ProcessName $entry.StartTicks) -and $processNames -contains $process.ProcessName) {
                            $hasWindow = $false
                            if ($entry.GuardWindow) {
                                $hasWindow = [bool](& $watch.WindowProbe $process)
                            }
                            $verdict = getWatchdogVerdict $entry $hasWindow $watch.Users $due
                            if ($verdict -eq 'Spare') {
                                $spared = $true
                            } elseif ($verdict -eq 'Kill') {
                                $targets.Add(@{ Entry = $entry; Process = $process })
                                $keep = $true
                            }
                        }
                    } catch {
                    } finally {
                        if ($null -ne $process -and -not $keep) {
                            try { $process.Dispose() } catch {}
                        }
                    }
                }
                if (-not $due) {
                    continue
                }
                $watch.Deadline = [datetime]::MaxValue
                if ($spared -and $null -ne $watch.Abandon) {
                    $watch.Abandon.Abandoned = $true
                }
                if ($targets.Count -gt 0 -or -not $spared) {
                    $watch.TimedOut = $true
                }
                foreach ($target in $targets) {
                    try {
                        if (isSameOfficeProcess $target.Process $target.Entry.ProcessName $target.Entry.StartTicks) {
                            $target.Process.Kill()
                        }
                    } catch {
                    } finally {
                        try { $target.Process.Dispose() } catch {}
                    }
                }
            }
        }).AddArgument($this.State).AddArgument($this.ProcessNames)
        $this.Thread = @{ PowerShell = $ps; Runspace = $runspace; Handle = $ps.BeginInvoke() }
    }

    [void] Stop() {
        if ($null -eq $this.Thread) {
            return
        }
        $this.State.Stop = $true
        try { [void]$this.Thread.PowerShell.EndInvoke($this.Thread.Handle) } catch {}
        $this.Thread.PowerShell.Dispose()
        $this.Thread.Runspace.Dispose()
        $this.Thread = $null
    }

    [bool] IsRunning() {
        return ($null -ne $this.Thread)
    }
}

$script:officeWatchdog = [OfficeWatchdog]::new([string[]]@($appInfo.Values | ForEach-Object { $_.Process }))

# 取り込んだ・元のファイルが無くなったフォルダを、本文インデックスに書き出してよいかを決める（PendingPublish）。
# フォルダごとの取り込み中の数（Busy）とまだ渡していない数（Pending）を数え、どちらも 0 になったフォルダを
# 書き出してよいフォルダとして返す（TakeFlushable）。取り込みの前に無くなったフォルダ（Skip）・後回し（Complete。
# 成功・失敗と同じ扱い）も、この数に反映する。書き出し（publishIndexFolders）は司令（invokeIndexerBody）が呼ぶ。

class PendingPublish {
    # フォルダ（フルパス）→ そのフォルダで無くなった元のファイル名の集まり。まだ書き出していないもの
    hidden [System.Collections.Generic.Dictionary[string,object]]$Folders
    # フォルダごとの、取り込み中の数（Busy）・まだ渡していない数（Pending）。どちらも 0 で書き出してよい
    hidden [System.Collections.Generic.Dictionary[string,int]]$Busy
    hidden [System.Collections.Generic.Dictionary[string,int]]$Pending

    PendingPublish() {
        $this.Folders = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
        $this.Busy = New-Object 'System.Collections.Generic.Dictionary[string,int]' ([System.StringComparer]::OrdinalIgnoreCase)
        $this.Pending = New-Object 'System.Collections.Generic.Dictionary[string,int]' ([System.StringComparer]::OrdinalIgnoreCase)
    }

    [void] MarkFolder([string]$folder) {
        # 前回のインデックス作成で本文インデックスに入れていないフォルダを、書き出し待ちにする（無くなったファイルの記録は無し）
        if (!$this.Folders.ContainsKey($folder)) {
            $this.Folders[$folder] = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
        }
    }

    [void] Add([string]$relPath, [bool]$removed) {
        # 取り込んだ・無くなった元のファイルのフォルダを、書き出し待ちにする
        $folder = [System.IO.Path]::GetDirectoryName((getBookDir $relPath))
        if (!$this.Folders.ContainsKey($folder)) {
            $this.Folders[$folder] = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
        }
        if ($removed) {
            [void]$this.Folders[$folder].Add([System.IO.Path]::GetFileName($relPath))
        }
    }

    [void] AddPending([string]$folder) {
        # 取り込み対象を数えるとき、そのファイルの分だけ「まだ渡していない数」を1つ足す
        $this.Pending[$folder] = [int]$this.Pending[$folder] + 1
    }

    [void] Dispatch([string]$folder) {
        # ファイルを1つ、取り込みのスレッド（または司令のスレッド）に渡す（渡していない→取り込み中）
        $this.Pending[$folder] = [int]$this.Pending[$folder] - 1
        $this.Busy[$folder] = [int]$this.Busy[$folder] + 1
    }

    [void] Skip([string]$folder) {
        # ファイルを1つ、渡さずに済ませる（取り込みの直前に元のファイルが無くなった等。取り込み中にはしない）
        $this.Pending[$folder] = [int]$this.Pending[$folder] - 1
    }

    [void] Complete([string]$folder) {
        # 取り込み中のファイルが1つ終わる（成功・失敗・後回しのどれでも）
        $this.Busy[$folder] = [int]$this.Busy[$folder] - 1
    }

    [System.Collections.Generic.Dictionary[string,object]] TakeFlushable() {
        # 取り込み中・まだ渡していないファイルがどちらも無いフォルダを取り出し、書き出し待ちから外して返す
        $keep = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($folder in @($this.Busy.Keys | Where-Object { $this.Busy[$_] -gt 0 })) {
            [void]$keep.Add($folder)
        }
        foreach ($folder in @($this.Pending.Keys | Where-Object { $this.Pending[$_] -gt 0 })) {
            [void]$keep.Add($folder)
        }
        return $this.take($keep)
    }

    [System.Collections.Generic.Dictionary[string,object]] TakeAll() {
        # 取り込み中・まだ渡していない数を見ずに、書き出し待ちのフォルダをすべて取り出す
        # （インデックス作成の終わり。中止・続けられないエラーでも、取り込んだ分は残さず書き出す）
        return $this.take((New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)))
    }

    hidden [System.Collections.Generic.Dictionary[string,object]] take($keep) {
        $flush = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($folder in @($this.Folders.Keys)) {
            if (!$keep.Contains($folder)) {
                $flush[$folder] = $this.Folders[$folder]
                [void]$this.Folders.Remove($folder)
            }
        }
        return $flush
    }
}

# インデックス作成の司令のスレッドの進み具合と、画面の確認待ちをまとめる（IndexingReporter）。
# 受け渡しの口（newIndexerChannel。hashtable のまま）を持ち、進み具合を書く（writeIndexingProgress を呼ぶ）・
# 画面の確認を待つ（waitForIndexingApproval だった処理をメソッドにした）。
# ログ（writeIndexerLog・$script:indexerLog）は部品として別に残し、ここには入れない（docs/design/structure/classes.md）。
# クラスの本体では $script: 変数を直接読まない（docs/design/structure/classes.md「クラスと関数の使い分け」）ため、
# インデックス作成の段階（${indexingPhase*}）は呼び出し元（司令）から引数で受け取る

class IndexingReporter {
    # 受け渡しの口（画面とやり取りする hashtable。newIndexerChannel）
    $Channel

    IndexingReporter($channel) {
        $this.Channel = $channel
    }

    [void] Progress([string]$phase, [int]$processed, [int]$remaining, [int]$failed, [string]$detail) {
        # インデックス作成の進み具合を受け渡しの口に書く（画面が 1 秒ごとに読む）
        writeIndexingProgress $phase $processed $remaining $failed $detail $this.Channel
    }

    [object] WaitForApproval([string]$phase, $plan, [int]$targetCount, [int]$failedCount, [int]$timeoutMinutes) {
        # 取り込み対象の件数を画面に渡し、［更新を開始］か［キャンセル］の返事を待つ。
        #   取り込む → @{ RetryFailed; IncludeCloud } / 取りやめ（中止を求められた場合を含む） → $null
        # 画面が返事をしないまま待ち続けないよう、timeoutMinutes で打ち切って取りやめる。
        # ローカル変数はプロパティ名 Channel と大文字・小文字だけの違いにしない（$ch にする。PowerShell のクラスは
        # 同名（大文字・小文字を区別しない）のローカル変数への代入をプロパティへの代入と見なし、$this. を要求してエラーになる）
        $ch = $this.Channel
        [void]$ch.Answered.Reset()
        $ch.Answer = $null
        $ch.Plan = @($plan)
        writeIndexingProgress $phase 0 $targetCount $failedCount "更新する内容を画面で確認しています…" $ch
        writeIndexerLog ""
        writeIndexerLog "取り込み対象を画面に表示しました。［更新を開始］が押されるまで待ちます。（${timeoutMinutes} 分待っても返事が無ければ取りやめます）"

        try {
            if (!$ch.Answered.WaitOne([TimeSpan]::FromMinutes($timeoutMinutes))) {
                writeIndexerLog "画面からの返事が ${timeoutMinutes} 分ありませんでした。インデックス作成を取りやめます。" "Yellow"
                return $null
            }
            if ($ch.Stop) {
                return $null
            }
            return $ch.Answer
        } finally {
            $ch.Plan = $null
        }
    }
}

# クロール（どのファイルを取り込むかを数え、画面の返事を待つ）。

# 取り込み対象の拡張子（Office は shared\office\office_files.ps1、テキストは shared\core\text_file.ps1、PDF は shared\core\pdf_file.ps1）
$targetExtensions = @(${officeExtensions}) + @(${textExtensions}) + @(${pdfExtensions})

# tebunko が作ったファイルを、名前だけで見分けるパターン（テキストの拡張子のものだけに当たる。どこにあっても外す）。
#   ・今の版の本文インデックス（content_index.xlsx.001.tsv 等。contentIndexFileNamePattern と同じ組み立て）
#   ・前の版（名前をそろえる前）の本文インデックスのファイル（content.xlsx.001.tsv 等）
#   ・システムインデックス（今の版 system_index*.txt・前の版 システムインデックス*.txt。search_gram.ps1 の systemIndexFileName・
#     workspace.ps1 の legacySystemIndexPattern と同じ組み立て）
${tebunkoOwnFileNamePatterns} = @(
    "${contentIndexFileNamePrefix}.*.tsv",
    "content.*.tsv",
    "$([System.IO.Path]::GetFileNameWithoutExtension(${systemIndexFileName}))*.txt",
    ${legacySystemIndexPattern}
)

function testTebunkoOwnFileName {
    # ファイル名（拡張子を含む）が、上のパターンのどれかに当たるか
    param (
        [string]$name
    )

    foreach ($pattern in ${tebunkoOwnFileNamePatterns}) {
        if ($name -like $pattern) {
            return $true
        }
    }
    return $false
}

# ----------------------------------------------------------------------------
# 取り込み対象
# ----------------------------------------------------------------------------

function selectOnlyNames {
    # 選んだインデックス名（onlyNames）を、名前を割り当て済みのクロール対象フォルダ（folders）に当てはめる。
    # 戻り値: @{ Selected（今回更新する名前の集合。大文字・小文字を区別しない）; Skipped（更新できない名前の @{ Name; Reason } の配列） }
    # 更新できないのは、設定に無い名前と、チェックが付いていない名前（チェックを付けるのは画面側）
    param (
        [object[]]$folders,
        [string[]]$onlyNames
    )

    $selected = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $skipped = New-Object System.Collections.Generic.List[object]
    foreach ($name in @($onlyNames | Where-Object { $_ })) {
        $folder = @($folders | Where-Object { $_.Name -eq $name }) | Select-Object -First 1
        if (!$folder) {
            $skipped.Add([pscustomobject]@{ Name = $name; Reason = "設定にありません" })
        } elseif (!$folder.Enabled) {
            $skipped.Add([pscustomobject]@{ Name = $name; Reason = "チェックが付いていません" })
        } else {
            [void]$selected.Add($name)
        }
    }
    return @{ Selected = $selected; Skipped = $skipped.ToArray() }
}

function getBookDir {
    # 取り込み対象のファイルの相対パスから、そのファイルのインデックスを入れるフォルダを返す。
    # 相対パスの最後は元のファイル名のため、インデックスフォルダと相対パスをつなぐとフォルダ名になる
    #   例: "営業\2024\A社.xlsx" → "work\index\営業\2024\A社.xlsx"（この中に "明細.tsv" 等を入れる）
    param (
        [string]$relPath
    )

    return (Join-Path $workspace.IndexDir $relPath)
}

function removeBookDir {
    # そのファイルのインデックスのフォルダを削除する（元のファイルが無くなったとき・取り込み直すとき）。
    # ウイルス対策ソフト・エクスプローラーが一時的に掴んでいることがあるため、少し待って数回試す
    param (
        [string]$bookDir
    )

    removeDirectoryRetry $bookDir
}

function getTebunkoExcludeDirs {
    # 除外するフォルダ（tebunko が作ったワークスペース）の一覧を返す。
    #   ・今のワークスペース（$workspace.Entries()。content_index・前の版の index・system_index・取り込み一覧 等）
    #   ・スキャンで見つけたファイルの中に取り込み一覧（$workspace.StatusFile と同じ名前）があれば、
    #     そのフォルダをほかのワークスペースとみなし、その Entries() も外す
    #     （以前の既定の場所・切り替える前のワークスペース・ほかの人のワークスペースを、テキストの拡張子（.tsv 等）で拾わないため）
    param (
        [object[]]$scannedFiles
    )

    $statusFileName = [System.IO.Path]::GetFileName($workspace.StatusFile)
    $dirs = New-Object System.Collections.Generic.List[string]
    $dirs.AddRange([string[]]$workspace.Entries())
    foreach ($file in $scannedFiles) {
        if ($file.Name -eq $statusFileName) {
            $otherDir = [System.IO.Path]::GetDirectoryName((fromLongPath $file.FullName))
            $dirs.AddRange([string[]]([Workspace]::new($otherDir).Entries()))
        }
    }
    return @($dirs | Where-Object { $_ } | Select-Object -Unique)
}

function testUnderAnyDir {
    # \\?\ 付きのフルパス（またはそのもの）が、dirs（\\?\ の付かない通常のパス）のどれかの下・そのものかを返す。
    #   dirPrefixes: dirs を toLongPath して末尾の \ を外したもの（呼び出し側で 1 回だけ作り、ファイルごとに作り直さない）
    param (
        [string]$fullName,
        [string[]]$dirPrefixes
    )

    foreach ($prefix in $dirPrefixes) {
        if ($fullName.Equals($prefix, [System.StringComparison]::OrdinalIgnoreCase) -or
            $fullName.StartsWith("$prefix\", [System.StringComparison]::OrdinalIgnoreCase)) {
            return $true
        }
    }
    return $false
}

function findTargetFiles {
    # クロール対象フォルダ配下の、取り込み対象（Office・テキストの拡張子）のファイルを検索し、
    # @{ Root; Files; HasError（アクセスできないフォルダがあった） } を返す。
    # Root は実際に列挙したフォルダ（\\?\ の付かない通常のパス）。相対パスはこの Root から求める
    # （設定に書かれたパスは、末尾の \ ・ドライブ文字と UNC パスなど書き方が違うことがあるため、文字数で切り出さない）。
    # tebunko が作ったファイル（getTebunkoExcludeDirs のフォルダの下・名前で分かるファイル）は対象に含めない
    param (
        [string]$targetFolder
    )

    # \\?\ を付けないと、パスが約248文字を超えるフォルダの中を検索できない（アクセスできないフォルダ扱いになる）。
    # 見つかったファイルの FullName は \\?\ 付きになる（fromLongPath で戻す）
    $scanErrors = $null
    $root = (Resolve-Path -LiteralPath $targetFolder).ProviderPath
    $scanned = @(Get-ChildItem -LiteralPath (toLongPath $root) -Recurse -File -ErrorAction SilentlyContinue -ErrorVariable scanErrors |
        Where-Object { ($targetExtensions -contains $_.Extension.ToLower()) -and -not $_.Name.StartsWith('~$') })

    # 除外するフォルダの \\?\ 付きの前方一致の文字列を先に作る（ファイルごとにドライブの割り当てをたどる処理は呼ばない）。
    # このクロール対象フォルダの外にあるものは、どのファイルにも当たらないため先に落とす（比べる数を減らす）
    $longRootPrefix = (toLongPath $root).TrimEnd("\")
    $excludeDirPrefixes = @(getTebunkoExcludeDirs $scanned | ForEach-Object { (toLongPath $_).TrimEnd("\") } | Where-Object {
        $_.Equals($longRootPrefix, [System.StringComparison]::OrdinalIgnoreCase) -or $_.StartsWith("$longRootPrefix\", [System.StringComparison]::OrdinalIgnoreCase)
    })
    $files = @($scanned | Where-Object {
        if ($excludeDirPrefixes.Count -gt 0 -and (testUnderAnyDir $_.FullName $excludeDirPrefixes)) { return $false }
        # 名前で分かる tebunko のファイル（content_index.*.tsv 等）は、テキストの拡張子にしか当たらないため、それだけ調べる
        if ((testTextExtension $_.Name) -and (testTebunkoOwnFileName $_.Name)) { return $false }
        return $true
    })

    return @{ Root = $root; Files = $files; HasError = (@($scanErrors).Count -gt 0) }
}

function createTargetList {
    # クロール対象フォルダを1つ検索して取り込み一覧の行を作り直し、次を返す。
    #   Rows   : 全ファイルの行 / Targets: 取り込む行 / Failed: 前回失敗し、更新の無い行
    #   Cloud  : 取り込む（または前回失敗した）ファイルのうち、クラウドにだけあるもの（OneDrive 等のオンデマンド）。
    #            開くとダウンロードされるため Targets・Failed には入れず、呼び出し元が取り込むかを決める。
    #            各要素は @{ RelPath; Row（取り込むときの行）; Old; Failed; Length; PendingOld }。
    #            Rows には前回の行をそのまま入れる（前回の行が無い・前回未完了のときは入れない）
    #   Plan   : 画面の確認に出す件数（newIngestPlanRow。取り込み予定.tsv の1行）
    #   Removed: 元のファイルが無くなったファイルの相対パス（呼び出し元が本文インデックスのファイルから外す）
    # 行の相対パスは "インデックス名\フォルダからの相対パス"（= work\index からの相対パス）とする。
    # ・前回の一覧と更新日時・サイズが同じで取り込み済み（済）のファイルは取り込まない
    # ・取り込み済みでも、インデックス（TSV）が無くなっていれば取り込み直す（利用者が work\index を直接削除した場合など）
    # ・元ファイルが無くなったファイルは、インデックスを削除して一覧から除く（アクセスできないフォルダがあった場合は除かない）
    param (
        $folder,   # @{ Path; Name }
        $previous, # readStatusFile の Rows（相対パス → 行）
        $counts    # getIndexTsvCounts の結果（インデックスの実体。$null なら確認しない）
    )

    $prefix = "$($folder.Name)\"
    $scan = findTargetFiles $folder.Path
    $rows = New-Object System.Collections.Generic.List[object]
    $targets = New-Object System.Collections.Generic.List[object]
    $failed = New-Object System.Collections.Generic.List[object]
    $cloud = New-Object System.Collections.Generic.List[object]
    # 取り込み予定に出す、クラウドにだけあるファイルの件数と容量（取り込みの対象と、前回失敗を分けて、下のループで足す）
    $cloudCount = 0
    $cloudFailedCount = 0
    [long]$cloudBytes = 0
    [long]$cloudFailedBytes = 0
    $found = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    $count = @{ Done = 0; New = 0; Updated = 0; Pending = 0; Lost = 0 }

    # 列挙したファイルの FullName は、\\?\ 付きの Root で始まる。ファイルが多いと1件ずつの関数呼び出しだけで
    # 時間がかかるため、その場合は先頭を切り落として相対パスにする（それ以外は getPathUnderFolder で求める）
    $longRoot = (toLongPath $scan.Root).TrimEnd("\") + "\"
    foreach ($file in $scan.Files) {
        $fullName = $file.FullName
        if ($fullName.Length -gt $longRoot.Length -and $fullName.StartsWith($longRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
            $relative = $fullName.Substring($longRoot.Length)
        } else {
            $relative = getPathUnderFolder (fromLongPath $fullName) $scan.Root
        }
        if ($null -eq $relative -or $relative -eq "") {
            $relative = $file.Name  # 通常は起こらない（$scan.Root の下を列挙している）
        }
        $relPath = $prefix + $relative
        [void]$found.Add($relPath)
        $updated = formatFileTime $file.LastWriteTime
        $size = [string]$file.Length

        $old = $null
        [void]$previous.TryGetValue($relPath, [ref]$old)

        # 取り込むかどうかの判断は indexer_decide.ps1（テストしやすいように分けてある）
        # インデックス（TSV）の有無は、前回と同じファイルで「済」のときだけ調べる（取り込み直すものには要らない）
        $indexComplete = $true
        if ($old -and $old.状態 -eq ${stateDone} -and $old.更新日時 -eq $updated -and $old.サイズ -eq $size) {
            $indexComplete = [bool](testIndexComplete $old $relPath $counts)
        }
        $decision = getIngestDecision $old $updated $size $indexComplete

        # 読む必要があるファイル（取り込む・前回失敗）だけ、クラウドにだけあるかを調べる。
        # 属性は一覧が返したものを見るだけで、ファイルは開かない（ダウンロードは起きない）
        if (($decision.Ingest -or $decision.Reason -eq "failed") -and (testCloudOnlyAttributes ([int]$file.Attributes))) {
            $isFailed = (-not $decision.Ingest)
            $pendingOld = [bool]($old -and $old.状態 -eq ${stateNew})
            if ($isFailed) {
                $cloudFailedCount++
                $cloudFailedBytes += [long]$file.Length
            } else {
                $cloudCount++
                $cloudBytes += [long]$file.Length
            }
            $cloud.Add(@{
                RelPath    = $relPath
                Row        = $(if ($isFailed) { $old } else { newStatusRow $relPath $updated $size ${stateNew} })
                Old        = $old
                Failed     = $isFailed
                Length     = [long]$file.Length
                PendingOld = $pendingOld
            })
            # 取り込まないときは前回の行を残す（前回の行が無い・前回未完了なら、行を作らない）
            if ($old -and -not $pendingOld) {
                $rows.Add($old)
            }
            continue
        }

        if (-not $decision.Ingest) {
            # 更新なし。失敗したファイルを再取り込みするかは呼び出し元で決める
            $row = $old
            if ($decision.Reason -eq "failed") {
                $failed.Add($row)
            } else {
                $count.Done++
            }
        } else {
            $row = newStatusRow $relPath $updated $size ${stateNew}
            $targets.Add($row)
            switch ($decision.Reason) {
                "lost"    { $count.Lost++ }
                "new"     { $count.New++ }
                "pending" { $count.Pending++ }
                default   { $count.Updated++ }  # updated と outdated（前の抽出版で取り込んだ。画面では更新ありと同じに扱う）
            }
        }
        $rows.Add($row)
    }

    $removed = New-Object System.Collections.Generic.List[string]
    foreach ($relPath in @($previous.Keys)) {
        if (!$relPath.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase) -or $found.Contains($relPath)) {
            continue
        }
        if ($scan.HasError) {
            $rows.Add($previous[$relPath])
            continue
        }
        removeBookDir (getBookDir $relPath)
        $removed.Add($relPath)
    }

    $detail = "取り込み済み {0} 件 / 新規 {1} 件 / 更新あり {2} 件 / 前回未完了 {3} 件 / 前回失敗 {4} 件" -f
        $count.Done, $count.New, $count.Updated, $count.Pending, $failed.Count
    if ($count.Lost -gt 0) {
        # インデックスを直接削除された場合など。ふだんは 0 件のため、あるときだけ表示する
        $detail += " / インデックスが無い・壊れている $($count.Lost) 件"
    }
    if ($cloud.Count -gt 0) {
        $detail += " / クラウドにだけある $($cloud.Count) 件"
    }
    writeIndexerLog ("  [{0}] 対象ファイル {1} 件（{2}）" -f $folder.Name, $scan.Files.Count, $detail)
    if ($count.Lost -gt 0) {
        writeIndexerLog "    インデックス（TSV）が無くなった・壊れている $($count.Lost) 件は取り込み直します。（インデックスを直接削除した・0 バイトのTSVが残っている）" "Yellow"
    }
    if ($removed.Count -gt 0) {
        writeIndexerLog "    元ファイルが無くなった $($removed.Count) 件は、インデックスから除きます。"
    }
    if ($scan.HasError) {
        writeIndexerLog "    アクセスできないフォルダがあったため、元ファイルが無くなったかどうかの確認は行いませんでした。" "Yellow"
    }

    $plan = newIngestPlanRow $folder.Name $folder.Path ${planKindIngest} $scan.Files.Count $targets.Count `
        $count.New $count.Updated $count.Pending $count.Lost $failed.Count `
        $cloudCount $cloudFailedCount $cloudBytes $cloudFailedBytes
    return @{ Rows = $rows; Targets = $targets; Failed = $failed; Cloud = $cloud; Plan = $plan; Removed = $removed.ToArray() }
}

# ----------------------------------------------------------------------------
# 取り込む順番を決める（IngestPlanner）
# ----------------------------------------------------------------------------

# インデックス作成の司令（invokeIndexerBody）の前半。クロール対象フォルダにインデックス名を割り当て、クロールして、
# 取り込む順番（Targets）・画面に出す件数（Plan）・取り込み一覧に書く行（Rows）を組み立てる。
# 取り込み直すかの判断は indexer_decide.ps1（判断層）の関数を、createTargetList 経由でそのまま呼ぶ。
# 進み具合・画面の確認・取り込み一覧の読み書きは持たない（IndexingReporter・StatusLedger を司令がつなぐ）。
# クラスの本体では $script: 変数を読まない決まり（docs/design/structure/classes.md。テストと本番で読める範囲が違うため）なので、
# 計画の種類・状態の値は kinds（Unchecked・Missing・Dropped・StateFailed の 4 つ。足りなければ例外）、
# 名前の保存は、司令が渡す save（割り当てた名前を設定に保存し、保存した一覧を返すスクリプトブロック。IndexCatalog.StoreAssignedNames）に任せる。
# メソッドは次の順に呼ぶ: AssignNames → SaveNames → SelectOnly（選んだときだけ）→ Crawl →
#   KeepForCancel（取りやめるとき）か ApplyFailed → ApplyInterrupted → FolderByName。Crawl は AssignNames より前なら例外にする。
# メソッドの中のローカル変数は、プロパティと大文字・小文字だけの違いにしない
class IngestPlanner {
    # 名前を割り当てたクロール対象フォルダ（@{ Path; Name; Enabled } の並び）
    [object[]]$Folders
    # 前回の取り込み一覧の行（相対パス → 行）
    $Previous
    # 設定から外れたインデックス（findDroppedIndexes の結果）
    [object[]]$Dropped
    # 選んだインデックスだけを更新するときの当てはめ（selectOnlyNames の結果。選ばなければ $null）
    $Only
    # 全ファイルの行・取り込む行・前回失敗し更新の無い行・クラウドにだけあるファイル・画面の確認に出す件数
    [System.Collections.Generic.List[object]]$Rows
    [System.Collections.Generic.List[object]]$Targets
    [System.Collections.Generic.List[object]]$Failed
    # クラウドにだけあるファイル（createTargetList の Cloud。取り込むかは確認の後に司令が決める）
    [System.Collections.Generic.List[object]]$Cloud
    [System.Collections.Generic.List[object]]$Plan
    # 元のファイルが無くなったファイルの相対パス（司令が本文インデックスのファイルから外す）
    [System.Collections.Generic.List[string]]$RemovedPaths
    # 前回、取り込み中に強制終了して最後に回したファイル（相対パス → 回数）
    $Carried
    hidden $Kinds

    IngestPlanner([hashtable]$kinds) {
        foreach ($key in @("Unchecked", "Missing", "Dropped", "StateFailed")) {
            if (-not $kinds.ContainsKey($key) -or $null -eq $kinds[$key]) {
                throw "IngestPlanner: kinds に $key がありません"
            }
        }
        $this.Kinds = $kinds
        $this.Rows = New-Object System.Collections.Generic.List[object]
        $this.Targets = New-Object System.Collections.Generic.List[object]
        $this.Failed = New-Object System.Collections.Generic.List[object]
        $this.Cloud = New-Object System.Collections.Generic.List[object]
        $this.Plan = New-Object System.Collections.Generic.List[object]
        $this.RemovedPaths = New-Object System.Collections.Generic.List[string]
        $this.Carried = New-Object 'System.Collections.Generic.Dictionary[string,int]' ([System.StringComparer]::OrdinalIgnoreCase)
    }

    [void] AssignNames($targetFolders, $status) {
        # クロール対象フォルダごとにインデックス名（work\content_index 直下のフォルダ名）を決める。前回と同じフォルダは同じ名前を使う。
        # status: 取り込み一覧（StatusLedger の ReadStatus。@{ Folders; Rows }）。
        # 設定から外れたインデックスは、ここでは消さない（確認ダイアログに「削除予定」として出す）
        $this.Folders = @(assignIndexNames $targetFolders $status.Folders)
        $this.Previous = $status.Rows
        $this.Dropped = @(findDroppedIndexes $this.Folders $status.Folders)
    }

    [void] SaveNames($targetFolders, [scriptblock]$save) {
        # 新しく割り当てたインデックス名を設定に保存する（インデックスの「名前」と「置き場所」を設定で分けて持つため。
        # 名前が設定にあれば、フォルダを移してパスを書き換えても同じインデックスとして扱える）
        if (@($targetFolders | Where-Object { -not $_.Name }).Count -eq 0) {
            return
        }
        # 保存した一覧（読み直して名前だけを足したもの）の名前で続ける。この間に画面で外した・名前を付けられなかったフォルダは、今回は取り込まない
        $saved = @(& $save $this.Folders)
        $this.Folders = @($saved | Where-Object {
            $savedPath = $_.Path
            $_.Name -and @($targetFolders | Where-Object { $_.Path -eq $savedPath }).Count -gt 0
        })
        writeIndexerLog "インデックス名を設定に保存しました: $((@($this.Folders | ForEach-Object { $_.Name }) -join '、'))"
    }

    [object[]] SelectOnly([string[]]$onlyNames) {
        # 選んだインデックスだけを更新するとき。選ばなかったインデックスは、この回では一切触らない
        # （取り込み一覧の行は前回のまま・確認の表に出さない・失敗の一覧に加えない）。
        # 更新できない名前（@{ Name; Reason } の並び）を返す。更新できるものが 1 つも無いかは Only.Selected.Count で見る
        $this.Only = selectOnlyNames $this.Folders $onlyNames
        foreach ($skip in $this.Only.Skipped) {
            writeIndexerLog "  [$($skip.Name)] 更新できません（$($skip.Reason)）" "Yellow"
        }
        return @($this.Only.Skipped)
    }

    [void] Crawl($indexCounts, [scriptblock]$onFolder) {
        # クロール対象フォルダを順に検索して、Rows・Targets・Failed・Plan・RemovedPaths を組み立てる。
        # onFolder: フォルダを検索する直前に呼ぶ（司令が進み具合を画面に出す。$null なら何もしない）
        if ($null -eq $this.Folders) {
            throw "IngestPlanner: Crawl の前に AssignNames を呼んでください"
        }
        foreach ($folder in $this.Folders) {
            if ($null -ne $this.Only -and !$this.Only.Selected.Contains([string]$folder.Name)) {
                # 選ばなかったインデックス（下で前回の結果をそのまま残す）
            } elseif (-not $folder.Enabled) {
                writeIndexerLog "  [$($folder.Name)] $($folder.Path) … チェックなしのため取り込みません（インデックスはそのまま残します）"
                $this.Plan.Add((newIngestPlanRow $folder.Name $folder.Path $this.Kinds.Unchecked))
            } elseif (!(Test-Path -LiteralPath $folder.Path -PathType Container)) {
                writeIndexerLog "  [$($folder.Name)] $($folder.Path) … フォルダが見つからないため取り込みません" "Yellow"
                $this.Plan.Add((newIngestPlanRow $folder.Name $folder.Path $this.Kinds.Missing))
            } else {
                writeIndexerLog "  [$($folder.Name)] $($folder.Path)"
                if ($null -ne $onFolder) {
                    $null = & $onFolder $folder
                }
                $list = createTargetList $folder $this.Previous $indexCounts
                $this.Rows.AddRange($list.Rows)
                $this.Targets.AddRange($list.Targets)
                $this.Failed.AddRange($list.Failed)
                $this.Cloud.AddRange($list.Cloud)
                $this.Plan.Add($list.Plan)
                $this.RemovedPaths.AddRange([string[]]@($list.Removed))
                continue
            }

            # 取り込まないフォルダは前回の結果をそのまま残す
            $prefix = "$($folder.Name)\"
            foreach ($key in @($this.Previous.Keys)) {
                if ($key.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) {
                    $this.Rows.Add($this.Previous[$key])
                }
            }
        }

        foreach ($item in $this.Dropped) {
            $this.Plan.Add((newIngestPlanRow $item.Name $item.Path $this.Kinds.Dropped))
        }
    }

    [object[]] KeepForCancel() {
        # 画面で取りやめたときに書く取り込み一覧の行。1件も取り込んでいないため、取り込み対象にした行は前回の記録のまま
        # （一覧に無かったファイルは記録しない）にする。「未取り込み」で記録すると、次回［すべて更新］が［続きから再開］になり、
        # 中断したように見えるため
        $targetPaths = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($row in $this.Targets) {
            [void]$targetPaths.Add($row.相対パス)
        }
        $keep = New-Object System.Collections.Generic.List[object]
        # クラウドにだけあって前回未完了のファイルは、取り込み一覧に前回の行を残す（取りやめでは何も消さない）
        foreach ($item in $this.Cloud) {
            if ($item.PendingOld) {
                $keep.Add($item.Old)
            }
        }
        foreach ($row in $this.Rows) {
            if (!$targetPaths.Contains($row.相対パス)) {
                $keep.Add($row)
                continue
            }
            $old = $null
            if ($this.Previous.TryGetValue($row.相対パス, [ref]$old)) {
                $keep.Add($old)
            }
        }
        return $keep.ToArray()
    }

    [void] ApplyFailed([bool]$retry) {
        # 前回取り込みに失敗し、その後更新されていないファイルを、取り込み直す（retry）か、スキップするかを決める
        if ($this.Failed.Count -eq 0) {
            return
        }
        writeIndexerLog ""
        if ($retry) {
            writeIndexerLog "前回取り込みに失敗し、その後更新されていないファイル $($this.Failed.Count) 件も再取り込みします。"
            $this.Targets.AddRange($this.Failed)
        } else {
            writeIndexerLog "前回取り込みに失敗し、その後更新されていないファイル $($this.Failed.Count) 件はスキップします。（パスワード付きなど）"
        }
    }

    [void] ApplyInterrupted([object[]]$entries, [int]$interruptLimit) {
        # 前回、取り込み中に強制終了した（ウィンドウを閉じた・PCが停止した等）ファイルは、同じファイルで止まり続けないよう最後に回す。
        # 続けて interruptLimit 回強制終了したファイルは、応答しなくなるファイルとみなして失敗とする。
        # 最後に回したファイルは Carried に残す（取り込みを始めるまで記録を残し、その前にまた止まっても回数が分かるように）。
        # entries: StatusLedger の ReadIngestingFiles（@{ RelPath; Count } の並び）
        foreach ($entry in $entries) {
            $hit = @($this.Targets | Where-Object { $_.相対パス -eq $entry.RelPath }) | Select-Object -First 1
            if (!$hit) {
                continue
            }
            [void]$this.Targets.Remove($hit)
            if ($entry.Count -ge $interruptLimit) {
                $hit.状態 = $this.Kinds.StateFailed
                $hit.TSV数 = ""
                $hit.取り込み日時 = formatFileTime (Get-Date)
                $hit.エラー = "更新中に $($entry.Count) 回続けて強制終了されたため、更新を中止しました（Officeアプリが応答しなくなる可能性があります）"
                writeIndexerLog ""
                writeIndexerLog "取り込み中に $($entry.Count) 回続けて強制終了したファイルは、失敗としてスキップします: $($hit.相対パス)" "Yellow"
            } else {
                $this.Targets.Add($hit)
                $this.Carried[$hit.相対パス] = $entry.Count
                writeIndexerLog ""
                writeIndexerLog "前回、取り込み中に強制終了したファイルは最後に取り込みます: $($hit.相対パス)" "Yellow"
            }
        }
    }

    [object] FolderByName() {
        # インデックス名 → クロール対象フォルダ
        $byName = New-Object 'System.Collections.Generic.Dictionary[string,string]' ([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($folder in $this.Folders) {
            $byName[$folder.Name] = $folder.Path.TrimEnd("\")
        }
        return $byName
    }
}

# 1ファイルから文字を抽出して TSV に書き出す（Excel のセルは COM、Excel の図形・コメントと Word・PowerPoint はファイルを直接読む）。
# $excelMaxPath（Excelで開けるパスの長さの目安）は paths.ps1 で定義する（selectTmpDir でも使うため）

$excelExtraCells = 1000000  # 使用範囲がデータの範囲よりこのセル数以上広いシートは、データの範囲だけを一時シートにコピーしてから書き出す

# ----------------------------------------------------------------------------
# 暗号化されたファイルの扱い（office_protection.ps1・office_protection_view.ps1）
# ----------------------------------------------------------------------------

# 「形式の分からないバイナリ」（透過暗号化の製品の暗号文の見込み）をOfficeで開く予備を、アプリごとに使うかどうか。
# 実機で数秒以内に例外にならない・ダイアログが出るアプリは $false にする（docs/design/indexing/known-issues.md）
${officeFallbackEnabled} = @{ Word = $true; Excel = $true; PowerPoint = $true }

function testOfficeFallbackEnabled {
    param (
        [string]$appName
    )

    return [bool]${officeFallbackEnabled}[$appName]
}

function throwProtectionFailure {
    # 暗号化の判定で、Officeにまだ一度も触れていない状態の失敗にする。
    # invokeIngestTask（indexer_run.ps1）が、この印（Data の OfficeUntouched）を見て stopApp を呼ばずに済ませる
    # （IRM・パスワード付きのファイルが並んでも、そのたびにOfficeを起動し直さないため）
    param (
        [string]$message
    )

    $exception = New-Object System.Management.Automation.RuntimeException($message)
    $exception.Data["OfficeUntouched"] = $true
    throw $exception
}

function isOfficeRequiredException {
    # invokeIngestTask（indexer_run.ps1）と見分け方をそろえる（重複させない）
    param (
        [System.Exception]$exception
    )

    $base = $exception.GetBaseException()
    return ($base -is [System.OperationCanceledException] -and $base.Message -eq ${officeRequiredMessage})
}

function isOfficeAppInUseException {
    # invokeIngestTask（indexer_run.ps1）と見分け方をそろえる（重複させない）
    param (
        [System.Exception]$exception
    )

    $base = $exception.GetBaseException()
    return ($base -is [System.InvalidOperationException] -and $base.Message.EndsWith(${officeAppInUseMessage}))
}

function isPassthroughIngestException {
    # 見張りの時間切れ・「Officeが要る」・「利用者のOfficeが使用中」の例外は、暗号化の失敗として包み直さずそのまま通す
    param (
        [System.Exception]$exception
    )

    if ($script:officeWatchdog.State.TimedOut) {
        return $true
    }
    if (isOfficeRequiredException $exception) {
        return $true
    }
    if (isOfficeAppInUseException $exception) {
        return $true
    }
    return $false
}

function failProtectionCheck {
    # 暗号化の判定で、Officeを開く前に作業フォルダのコピーを消してから失敗にする（throwProtectionFailure）
    param (
        [string]$copyPath,
        [string]$message
    )

    Remove-Item -LiteralPath $copyPath -Force
    throwProtectionFailure $message
}

function logProtectionKind {
    # 暗号化の判定の結果をインデックス作成ログに書く（Password・Rights・Unknownだけ。旧形式・ふつうのテキストは書かない）
    param (
        [string]$kind
    )

    if ($kind -eq "Password" -or $kind -eq "Rights" -or $kind -eq "Unknown") {
        writeIndexerLog "    暗号化の判定: $kind" "Yellow"
    }
}

# ----------------------------------------------------------------------------
# 抽出
# ----------------------------------------------------------------------------

function copyDataRangeToTempSheet {
    # 使用範囲（UsedRange）が実際のデータよりずっと広いシートのために、データのある範囲だけを
    # 同じブックの一時シートへ同じ位置でコピーし、その一時シートを返す。縮める必要が無い・できない場合は $null を返す。
    #
    # 最終行・右端のセルに書式だけが残っていると使用範囲がシート全体になり、Excelのテキスト保存が
    # 空セルのタブだけで数GBを書き出して制限時間も超える（実測: 10分で6GB、終わらない）。
    # 元のシートの行・列は削除しない（そこを参照する数式が #REF! になり、ほかのシートの表示値まで変わるため）。
    param (
        $workbook,
        $worksheet
    )

    $usedRange = $worksheet.UsedRange
    try {
        $firstRow = $usedRange.Row
        $firstColumn = $usedRange.Column
        $usedLastRow = $firstRow + $usedRange.Rows.Count - 1
        $usedLastColumn = $firstColumn + $usedRange.Columns.Count - 1
    } finally {
        releaseComObject $usedRange
    }

    # 使用範囲そのものが縮める基準より狭ければ、データの範囲を探すまでもない（ほとんどのシート）。
    # 大きいシートでは Find に時間がかかるため、シートごとに呼ばないようにする
    $usedCells = [double]($usedLastRow - $firstRow + 1) * ($usedLastColumn - $firstColumn + 1)
    if ($usedCells -lt $excelExtraCells) {
        return $null
    }

    # 値・数式のある最後の行・列を探す（書式だけのセルには当たらない）。
    # 引数: What, After, LookIn（-4123 = xlFormulas）, LookAt, SearchOrder（1 = xlByRows / 2 = xlByColumns）, SearchDirection（2 = xlPrevious）
    $topLeft = $worksheet.Range("A1")
    $cells = $worksheet.Cells
    try {
        $found = $cells.Find("*", $topLeft, -4123, [Type]::Missing, 1, 2)
        $dataLastRow = if ($found) { $found.Row } else { 0 }
        $found = $cells.Find("*", $topLeft, -4123, [Type]::Missing, 2, 2)
        $dataLastColumn = if ($found) { $found.Column } else { 0 }
    } finally {
        releaseComObject $cells
        releaseComObject $topLeft
    }

    # 値のあるセルが無い（書式だけのシート）場合は、そのまま書き出して空のTSVとして扱う
    if ($dataLastRow -lt $firstRow -or $dataLastColumn -lt $firstColumn) {
        return $null
    }

    # セル数は int を超えるため double で数える（シート全体は約 172 億セル）
    $dataCells = [double]($dataLastRow - $firstRow + 1) * ($dataLastColumn - $firstColumn + 1)
    if (($usedCells - $dataCells) -lt $excelExtraCells) {
        return $null
    }

    # 数式の参照先がずれないよう、コピー先は元と同じ位置（行・列）にする
    $temp = $null
    try {
        $temp = $workbook.Worksheets.Add()
        $source = $worksheet.Range($worksheet.Cells.Item($firstRow, $firstColumn), $worksheet.Cells.Item($dataLastRow, $dataLastColumn))
        try {
            [void]$source.Copy($temp.Cells.Item($firstRow, $firstColumn))
        } finally {
            releaseComObject $source
        }
        return $temp
    } catch {
        # ブックの構成が保護されている場合など。元のシートをそのまま書き出す（時間切れで失敗することがある）
        writeIndexerLog "    $($worksheet.Name) の使用範囲を縮められませんでした: $($_.Exception.Message)" "Yellow"
        if ($temp) {
            $temp.Delete()
            releaseComObject $temp
        }
        return $null
    }
}

function extractWorkbook {
    # Excelファイルをシートごとに作業フォルダへTSV出力し、出力したシート数を返す
    param (
        [string]$sourcePath
    )

    $bookName = [System.IO.Path]::GetFileName($sourcePath)

    # 元のファイルに影響を出さないよう、作業フォルダにコピーしてからコピーを開く
    # （Excelで開いている間、元のファイルを利用者が上書き保存・移動できなくなるのを防ぐ。長いパスのファイルも開ける）。
    # ファイル名を参照する数式（CELL("filename") 等）の表示値が変わらないよう、コピーは元と同じファイル名にする。
    # 作業フォルダ＋ファイル名が長すぎてExcelで開けない場合だけ、短い名前にする。
    # コピーはブックを閉じた後に削除する（開けずに例外になった場合は、次のファイルの取り込み前・終了時に作業フォルダごと空にする）
    $copyPath = Join-Path $tmpDir $bookName
    if ($copyPath.Length -ge $excelMaxPath) {
        $copyPath = Join-Path $tmpDir ("source" + [System.IO.Path]::GetExtension($sourcePath))
    }
    copyFileShared $sourcePath $copyPath
    $openPath = $copyPath

    # 図形・コメントの文字は、テキスト保存には出ないため、新形式（ZIP）のブックを直接読む（Excel より速い）。
    # 旧形式（.xls）・パスワード付きのブックは ZIP ではないため読まない。
    # 読めなくてもセルの値は取り込めるため、インデックス作成ログに記録して続ける
    $objectUnits = $null
    $protection = $null
    if (isZipFile $copyPath) {
        $chartFailures = New-Object System.Collections.Generic.List[string]
        $chartSizeFailures = New-Object System.Collections.Generic.List[object]
        try {
            $objectUnits = readXlsxObjectUnits $copyPath $chartFailures $chartSizeFailures
        } catch {
            # サイズの上限を超えたとき（ZipSizeLimitException）は、原因を調べられるよう部品名・大きさ・
            # 部品ごとか合計かをインデックス作成のログに書く。画面には出さない（悪用のヒントになるため）
            writeZipSizeLimitLog $_.Exception
            writeIndexerLog "    図形・コメントを読み取れませんでした: $($_.Exception.Message)" "Yellow"
        }
        # 1つのグラフ・SmartArt・シートのヘッダー/フッターが読めなくても、そこだけを空にしてほかは読む（readXlsxObjectUnits）。
        # shared/ はツールを知らないため、読めなかった部品の名前・サイズの上限の詳細をここでログに書く
        foreach ($sizeFailure in $chartSizeFailures) {
            writeZipSizeLimitLog $sizeFailure
        }
        foreach ($failure in $chartFailures) {
            writeIndexerLog "    一部を読み取れませんでした: $failure" "Yellow"
        }
    } else {
        # IRM・秘密度ラベルの暗号化は、Excelを起動せずに失敗にする（サインイン画面を防ぐ）。
        # パスワード付き（既定のパスワードで暗号化されたブックを含む）は、今までどおりExcelに任せる。
        # 「形式の分からないバイナリ」（透過暗号化の製品の暗号文の見込み）は、アプリごとの切り替えが $false なら
        # Excelを起動せずに失敗にする
        $protection = getOfficeFileProtection $copyPath
        logProtectionKind $protection
        if ($protection -eq "Rights") {
            failProtectionCheck $copyPath (getProtectionFailureText "Rights")
        }
        if ($protection -eq "Unknown" -and !(testOfficeFallbackEnabled "Excel")) {
            failProtectionCheck $copyPath (getProtectionFailureText "Unknown")
        }
    }

    # 読み取り専用・リンク更新なしで開く。
    # パスワード付きのファイルは、ダイアログを出さずにエラーとするためダミーのパスワードを渡す。
    # 「形式の分からないバイナリ」で開けなかったときは、元の例外をログに書いて文言を言い換える
    # （見張りの時間切れ・「Officeが要る」・「利用者のOfficeが使用中」の例外はそのまま通す）
    $workbooks = (getApp "Excel").Workbooks
    try {
        try {
            $wb = $workbooks.Open($openPath, 0, $true, [Type]::Missing, "dummy", "dummy", $true)
        } catch {
            if ($protection -ne "Unknown" -or (isPassthroughIngestException $_.Exception)) {
                throw
            }
            writeIndexerLog "    予備の読み取りに失敗しました: $(describeIngestError $_.Exception)" "Yellow"
            throw (getProtectionFailureText "Unknown")
        }
    } finally {
        releaseComObject $workbooks
    }

    # 「形式の分からないバイナリ」は、開けた後のブックの形式（テキスト・HTML・CSVでない）も確かめる。
    # ほかの種類（HTML の .xls など）には当てない（本来読めているものまで失敗にしないため）
    if ($protection -eq "Unknown" -and !(testWorkbookFormat $wb.FileFormat)) {
        $wb.Close($false)
        releaseComObject $wb
        Remove-Item -LiteralPath $copyPath -Force
        throw (getProtectionFailureText "Unknown")
    }

    $sheets = New-Object System.Collections.Generic.List[object]
    try {
        $worksheets = $wb.Worksheets
        foreach ($ws in @($worksheets)) {
            try {
                # 非表示シートは除外（-1 = xlSheetVisible。0 = 非表示、2 = 完全に非表示）
                if ($ws.Visible -ne -1) {
                    continue
                }

                # Excelは [ ] を含むパスに保存できないため、一時ファイル名で保存し、整形時にリネームする
                $tmpPath = Join-Path $tmpDir ("sheet{0}.tmp" -f $ws.Index)
                $tsvPath = Join-Path $tmpDir (toIndexFileName $ws.Name)

                # 使用範囲が実際のデータよりずっと広いシートは、データの範囲だけを一時シートにコピーしてから書き出す
                $temp = copyDataRangeToTempSheet $wb $ws
                $target = if ($temp) { $temp } else { $ws }
                try {
                    # Excelは使用範囲（UsedRange）の左上のセルから出力するため、整形時にA1からの位置に戻せるよう控えておく。
                    # 一時シートは書式だけのセルが無く、元のシートより使用範囲が狭いことがあるため、書き出すシートから取る
                    $usedRange = $target.UsedRange
                    try {
                        $firstRow = $usedRange.Row
                        $firstColumn = $usedRange.Column
                    } finally {
                        releaseComObject $usedRange
                    }

                    [void]$target.Activate()
                    [void]$target.SaveAs($tmpPath, 42)  # 42 = xlUnicodeText
                } finally {
                    if ($temp) {
                        # 一時シートは、次のシートの Index がずれないようすぐ削除する（ブックは保存せずに閉じる）
                        $temp.Delete()
                        releaseComObject $temp
                    }
                }
                $sheets.Add(@($tmpPath, $tsvPath, $firstRow, $firstColumn))
            } finally {
                releaseComObject $ws
            }
        }
        releaseComObject $worksheets
    } finally {
        # 保存したファイルはブックを閉じるまでロックされている
        $wb.Close($false)
        releaseComObject $wb
        Remove-Item -LiteralPath $copyPath -Force
    }

    $count = 0
    foreach ($sheet in $sheets) {
        # 透過暗号化の製品が、Excelの保存したこの一時ファイルまで暗号化していないかを確かめる。
        # ブックを閉じた後（このループ）でないと、保存したファイルはExcelがロックしていて読めない
        if (!(testOfficeOutput (readFileHead $sheet[0]) "UnicodeText")) {
            throw ${officeOutputEncryptedMessage}
        }
        if (prettyTsv $sheet[0] $sheet[1] $sheet[2] $sheet[3]) {
            $count++
        }
        Remove-Item -LiteralPath $sheet[0] -Force
    }
    if ($null -ne $objectUnits) {
        $count += writeUnits $objectUnits $tmpDir
    }
    return $count
}

function extractWithWord {
    # Wordで開き、.docx 形式で保存する（旧形式 .doc 等を読めるようにするため）。
    # $format を渡すと、自動判定に任せずその形式で開く（「形式の分からないバイナリ」を開くときだけ使う。
    # 文字コードを選ぶダイアログや、暗号文をテキストとして読むことを防ぐ）
    param (
        [string]$sourcePath,
        [string]$destPath,
        $format = [Type]::Missing
    )

    # 読み取り専用で開く。パスワード付きのファイルは、ダイアログを出さずにエラーとするためダミーのパスワードを渡す
    #   引数: FileName, ConfirmConversions, ReadOnly, AddToRecentFiles, PasswordDocument, PasswordTemplate,
    #         Revert, WritePasswordDocument, WritePasswordTemplate, Format, Encoding, Visible
    $documents = (getApp "Word").Documents
    try {
        $doc = $documents.Open($sourcePath, $false, $true, $false, "dummy", "dummy", $false, "dummy", "dummy", $format, [Type]::Missing, $false)
    } finally {
        releaseComObject $documents
    }

    try {
        # 保存時のページ区切り（ページ番号の目安）を正しく記録させるため、ページ割りを確定させてから保存する
        $doc.Repaginate()
        [void]$doc.SaveAs2($destPath, 12)  # 12 = wdFormatXMLDocument（.docx）
    } finally {
        $doc.Close(0)
        releaseComObject $doc
    }
}

function extractWithPowerPoint {
    # PowerPointで開き、.pptx 形式で保存する（旧形式 .ppt 等を読めるようにするため）
    param (
        [string]$sourcePath,
        [string]$destPath
    )

    # 読み取り専用・ウィンドウ無しで開く。
    # ファイル名の後ろに "::<パスワード>::" を付けると、パスワード付きのファイルはダイアログを出さずにエラーになる
    $presentations = (getApp "PowerPoint").Presentations
    try {
        $pres = $presentations.Open("${sourcePath}::dummy::", -1, 0, 0)  # ReadOnly, Untitled = False, WithWindow = False
    } finally {
        releaseComObject $presentations
    }

    try {
        [void]$pres.SaveAs($destPath, 24)  # 24 = ppSaveAsOpenXMLPresentation（.pptx）
    } finally {
        $pres.Close()
        releaseComObject $pres
    }
}

# 読み取りのスレッド（Office を持たない）なら $true。Office が要るファイルは「Office が要る」の例外にする
$script:officeUnavailable = $false
# Office が要るときの例外の文言（invokeIngestTask が見分けて、司令に回し直しを頼む）
${officeRequiredMessage} = "このファイルの更新には Word・PowerPoint が要ります。"

function extractWithOffice {
    # Word・PowerPointどちらかで新形式に変換する（呼び分けをまとめる）。
    # $wordFormat を渡すと、Wordはその形式に固定して開く（「形式の分からないバイナリ」のときだけ渡す）
    param (
        [bool]$isWord,
        [string]$copyPath,
        [string]$readPath,
        $wordFormat = [Type]::Missing
    )

    if ($isWord) {
        extractWithWord $copyPath $readPath $wordFormat
    } else {
        extractWithPowerPoint $copyPath $readPath
    }
}

function verifyOfficeOutputIsZip {
    # Officeが保存した出力（$readPath）の先頭がZIPかを確かめる。
    # 透過暗号化の製品がこの一時ファイルまで暗号化していないか（ふつうのファイルでも起こりうる）
    param (
        [string]$readPath
    )

    if (!(testOfficeOutput (readFileHead $readPath) "Zip")) {
        throw ${officeOutputEncryptedMessage}
    }
}

function extractDocument {
    # Word・PowerPointのファイルを場所（ページ・スライド）ごとに作業フォルダへTSV出力し、出力した数を返す
    param (
        [string]$sourcePath
    )

    $isWord = ((getAppName $sourcePath) -eq "Word")
    $appName = $(if ($isWord) { "Word" } else { "PowerPoint" })

    # 元のファイルに影響を出さないよう、作業フォルダにコピーしてからコピーを読む（読んでいる間も、利用者が上書き保存・移動できる）。
    # 新形式（ZIP）はコピーをそのまま読む。
    # 旧形式・パスワード付き・拡張子と中身が異なるファイルは、Word・PowerPointで新形式に変換してから読む
    $copyPath = Join-Path $tmpDir ("source" + [System.IO.Path]::GetExtension($sourcePath))
    $readPath = $copyPath
    $workFiles = @($copyPath)
    try {
        copyFileShared $sourcePath $copyPath
        if (!(isZipFile $copyPath)) {
            $protection = getOfficeFileProtection $copyPath
            logProtectionKind $protection

            # パスワード付き（新形式）・IRM・秘密度ラベルの暗号化は、Office を使わずに失敗にする
            # （Word・PowerPointはサインイン画面が出ないようにするため。Excelは別処理で今のまま）
            if ($protection -eq "Password" -or $protection -eq "Rights") {
                throwProtectionFailure (getProtectionFailureText $protection)
            }

            if ($protection -eq "Unknown") {
                # 「形式の分からないバイナリ」（透過暗号化の製品の暗号文の見込み）。
                # アプリごとの切り替えが $false なら、Officeを使わずに失敗にする
                if (!(testOfficeFallbackEnabled $appName)) {
                    throwProtectionFailure (getProtectionFailureText "Unknown")
                }
                # 読み取りのスレッド（Office を持たない）では、Office のレーンに回す
                if ($script:officeUnavailable) {
                    throw (New-Object System.OperationCanceledException ${officeRequiredMessage})
                }

                # 拡張子は元のまま変えない（付け替えると、Wordが文字コードを尋ねる・PowerPointがアウトラインとして
                # 開くことがあるため）。Wordは形式を拡張子に合わせて固定し、自動判定に任せない
                $readPath = Join-Path $tmpDir $(if ($isWord) { "converted.docx" } else { "converted.pptx" })
                $workFiles = @($copyPath, $readPath)
                $wordFormat = getWordOpenFormat ([System.IO.Path]::GetExtension($copyPath))
                try {
                    extractWithOffice $isWord $copyPath $readPath $wordFormat
                } catch {
                    if (isPassthroughIngestException $_.Exception) {
                        throw
                    }
                    writeIndexerLog "    予備の読み取りに失敗しました: $(describeIngestError $_.Exception)" "Yellow"
                    throw (getProtectionFailureText "Unknown")
                }
                verifyOfficeOutputIsZip $readPath
            } else {
                # Legacy（旧形式・権限保護と分からないCFB）・Text（空・RTF・HTML・UTF-8・UTF-16等）は今と同じ

                # PowerPointは、プレゼンテーションではないファイル（中身がテキスト等）もアウトラインとして開き、
                # 文字化けした内容になるため、旧形式（複合ドキュメント形式）でなければ取り込まない。
                # Wordはテキスト・HTML・RTFも正しく読めるため、そのまま Word で開く
                if (!$isWord -and !(isCompoundFile $copyPath)) {
                    throw "ファイルが壊れているか、PowerPointのファイルではありません（新形式（ZIP）でも旧形式でもない内容です）。"
                }

                # 読み取りのスレッド（Office を持たない）では、Office のレーンに回す（indexer_run.ps1 の runIngestWorker・invokeIngestTask）
                if ($script:officeUnavailable) {
                    throw (New-Object System.OperationCanceledException ${officeRequiredMessage})
                }

                # Word・PowerPointは拡張子と中身が異なるファイル（中身が .doc の .docx 等）を開けないため、
                # コピーに旧形式の拡張子を付け直してから開く
                if ($isWord) {
                    $legacyPath = Join-Path $tmpDir "source.doc"
                    $readPath = Join-Path $tmpDir "converted.docx"
                } else {
                    $legacyPath = Join-Path $tmpDir "source.ppt"
                    $readPath = Join-Path $tmpDir "converted.pptx"
                }
                if ($legacyPath -ne $copyPath) {
                    [System.IO.File]::Move($copyPath, $legacyPath)
                    $copyPath = $legacyPath
                }
                $workFiles = @($copyPath, $readPath)

                extractWithOffice $isWord $copyPath $readPath
                verifyOfficeOutputIsZip $readPath
            }
        }

        # 埋め込んだファイルが読めなくても、その埋め込みだけを読まずに続ける（readDocxUnits・readPptxUnits）。
        # shared/ はツールを知らないため、読めなかった部品の名前・サイズの上限の詳細をここでログに書く
        $embedFailures = New-Object System.Collections.Generic.List[string]
        $embedSizeFailures = New-Object System.Collections.Generic.List[object]
        if ($isWord) {
            $units = readDocxUnits $readPath $embedFailures $embedSizeFailures
        } else {
            $units = readPptxUnits $readPath $embedFailures $embedSizeFailures
        }
        foreach ($sizeFailure in $embedSizeFailures) {
            writeZipSizeLimitLog $sizeFailure
        }
        foreach ($failure in $embedFailures) {
            writeIndexerLog "    埋め込みを読み取れませんでした: $failure" "Yellow"
        }
    } finally {
        foreach ($path in $workFiles) {
            if (Test-Path -LiteralPath $path) {
                Remove-Item -LiteralPath $path -Force
            }
        }
    }

    return (writeUnits $units $tmpDir)
}

function ingestFile {
    # 1ファイルを取り込み、作成したTSVの数を返す。
    # テキストの拡張子（textExtensions）・PDF の拡張子（pdfExtensions）は Office を使わず読み取りのレーンで取り込む（extract_text.ps1・extract_pdf.ps1）
    param (
        [string]$sourcePath
    )

    if (testTextExtension $sourcePath) {
        return (extractTextFile $sourcePath $tmpDir)
    }
    if (testPdfExtension $sourcePath) {
        return (extractPdfFile $sourcePath $tmpDir)
    }
    if ((getAppName $sourcePath) -eq "Excel") {
        return (extractWorkbook $sourcePath)
    }
    return (extractDocument $sourcePath)
}

# 1ファイル（テキスト）から行を読み、場所「本文」のTSVに書き出す。

function extractTextFile {
    # テキストファイル 1 つを読み、場所「本文」の TSV 1 つを outDir に書き出す（本文インデックスに 種類=テキスト・部分=本文・対象=本文 で載る）。
    # 出力した TSV の数（0 か 1）を返す。空のファイル・空の行だけのファイルは 0（次のインデックス作成で取り込み直さない）。
    # 元のファイルには影響を出さないため、読み取りだけ・共有モードで outDir に source.copy へコピーし（名前は .tsv にならない固定の名前。消せずに残っても TSV として公開されない）（copyFileShared）、コピーを読んで、
    # TSV を書く前に消す（outDir の中身は本文インデックスに回るので、コピーを残さない）。強制終了で残ったコピーは作業フォルダごと片付けられる。
    # 大きさの上限は、コピーの前に元の大きさ（メタデータ。元は開かない）で確かめる。コピーを読むときの確かめ（readTextFile）は、コピー中に大きくなった場合の保険。
    # バイナリの判定は readTextFile（shared\core\text_file.ps1）が例外にする。
    # maxBytes はテストで上限を小さく差し替えるための引数（既定は textFileMaxBytes）
    param (
        [string]$sourcePath,
        [string]$outDir,
        [long]$maxBytes = ${textFileMaxBytes}
    )

    if ([System.IO.FileInfo]::new((toLongPath $sourcePath)).Length -gt $maxBytes) {
        throw "ファイルサイズが大きすぎるため更新できません。"
    }
    $copyPath = Join-Path $outDir "source.copy"
    $removeError = $null
    try {
        copyFileShared $sourcePath $copyPath
        $lines = readTextFile $copyPath $maxBytes
    } finally {
        try {
            if (Test-Path -LiteralPath (toLongPath $copyPath)) {
                Remove-Item -LiteralPath (toLongPath $copyPath) -Force -ErrorAction Stop
            }
        } catch {
            $removeError = $_.Exception.Message
        }
    }
    if ($removeError) {
        throw "作業領域のコピーを消せませんでした: $removeError"
    }
    if ($lines.Count -eq 0) {
        return 0
    }
    $path = Join-Path $outDir (toIndexFileName "本文")
    [System.IO.File]::WriteAllLines((toLongPath $path), $lines, ${utf8Bom})
    return 1
}

# 1ファイル（PDF）からページごとの文字を読み、場所「ページN」のTSVに書き出す。

function extractPdfFile {
    # PDF ファイル 1 つを読み、ページごとの TSV（"ページ001" など）を outDir に書き出す（本文インデックスに 種類=PDF で載る）。
    # 出力した TSV の数を返す。文字の無いページは出さず、文字の無い PDF（画像だけ）は 0（次のインデックス作成で取り込み直さない）。
    # 元のファイルには影響を出さないため、extractTextFile と同じく、読み取りだけ・共有モードで outDir に source.copy へコピーし（copyFileShared）、
    # コピーを読んで、TSV を書く前に消す（outDir の中身は本文インデックスに回るので、コピーを残さない）。
    # 暗号化・壊れている・上限を超える・文字の対応表が無いなど読めない PDF は、readPdfFile が例外にする。
    # 大きさの上限は、コピーの前に元の大きさ（メタデータ。元は開かない）で確かめる。
    # maxBytes・limits はテストで上限を小さく差し替えるための引数（既定は pdfFileMaxBytes・newPdfLimits）
    param (
        [string]$sourcePath,
        [string]$outDir,
        [long]$maxBytes = ${pdfFileMaxBytes},
        [hashtable]$limits = $null
    )

    if ([System.IO.FileInfo]::new((toLongPath $sourcePath)).Length -gt $maxBytes) {
        throw "ファイルサイズが大きすぎるため更新できません。"
    }
    $copyPath = Join-Path $outDir "source.copy"
    $removeError = $null
    try {
        copyFileShared $sourcePath $copyPath
        $pages = readPdfFile $copyPath $maxBytes $limits
    } finally {
        try {
            if (Test-Path -LiteralPath (toLongPath $copyPath)) {
                Remove-Item -LiteralPath (toLongPath $copyPath) -Force -ErrorAction Stop
            }
        } catch {
            $removeError = $_.Exception.Message
        }
    }
    if ($removeError) {
        throw "作業領域のコピーを消せませんでした: $removeError"
    }
    $units = [ordered]@{}
    for ($i = 0; $i -lt $pages.Count; $i++) {
        addUnitLines $units ("ページ{0:D3}" -f ($i + 1)) ($pages[$i] -split "`n")
    }
    return (writeUnits $units $outDir)
}
# TSV のインデックスへの取り込みと、作業フォルダ・外したフォルダのインデックスの後始末。

function publishTsv {
    # 作業フォルダのTSVを、そのファイルのインデックスのフォルダへ移動する。
    # 途中で強制終了されても一部のシートだけのインデックスが残らないよう、
    # 出力用のフォルダ（work\publish\<PID>）に集めてからフォルダごと入れ替える（publishIndexFiles）
    param (
        [string]$bookDir
    )

    publishIndexFiles $tmpDir $bookDir (Join-Path $workspace.PublishDir ([System.IO.Path]::GetFileName($bookDir)))
}

function clearTmpDir {
    # 作業フォルダ直下のファイルを消す。作業フォルダそのものがリンク（ジャンクション・シンボリックリンク）のときは、
    # 先のファイルを消さないよう、何も消さずにログに出す
    if (testPathIsLink $tmpDir) {
        writeIndexerLog "    作業フォルダがリンク（ジャンクション・シンボリックリンク）のため、中のファイルを消しませんでした: ${tmpDir}" "Yellow"
        return
    }
    Get-ChildItem -LiteralPath (toLongPath $tmpDir) -File | Remove-Item -Force
}

function removeEmptyDir {
    # フォルダが空のときだけ、再帰しない削除で消す。中にほかのプロセスのフォルダなどが残っている・
    # フォルダが既に無いときは、何もせずそのままにする。
    # リンク（ジャンクション・シンボリックリンク）は、リンク自体を外さないよう、先が空でも消さない
    # （利用者が tmp や出力用のフォルダの親をリンクにした構成を、そのまま使えるようにするため）
    param (
        [string]$dir
    )
    if (testPathIsLink $dir) {
        return
    }
    try {
        [System.IO.Directory]::Delete($dir, $false)
    } catch {
        # 空でない・既に無い・アクセス権が無い（共有フォルダで他の利用者のフォルダなど）
    }
}

function removeTmpDir {
    # 作業フォルダ（work\tmp\<PC の鍵>\<PID>）と出力用のフォルダ（work\publish\<PID>）を削除する。終了時に呼ぶ。
    # ${tmpDir} が決まっていなくても（置けなかった・決める前）、出力用のフォルダは消す
    # （$workspace.PublishDir は ${tmpDir} が置けないときも作られるため）
    foreach ($dir in @(${tmpDir}, $workspace.PublishDir) | Where-Object { $_ }) {
        try {
            removeDirectoryRetry $dir
        } catch {
            writeIndexerLog "    作業フォルダを削除できませんでした: ${dir}（$($_.Exception.Message)）" "Yellow"
        }
    }
    # 空になった tmp\<PC の鍵>・tmp も消す（ワークスペースの tmp を使えたときだけ。
    # ほかのプロセスのフォルダが残っているときは消えない）
    if (${tmpDir} -and ${tmpDir}.StartsWith($workspace.TmpRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
        removeEmptyDir (Split-Path ${tmpDir} -Parent)
        removeEmptyDir $workspace.TmpRoot
    }
}

function removeStaleTmpDirs {
    # 強制終了などで残った、ほかの（終了済みの）プロセスの作業フォルダ
    # （ワークスペースの tmp\<PC の鍵>\<PID>・work\publish\<PID>・前の版までの %TEMP%\tebunko\<PID>）を削除する。
    # 空になった親（tmp\<PC の鍵>・publish・${legacyTmpParent}。tmp\<PC の鍵> はさらに tmp 自体も）も消す
    # tmp\<PC の鍵> の途中にリンク（ジャンクション・シンボリックリンク）があるときは、先のフォルダを消さないよう、片付けない
    $keyDir = Split-Path (getWorkspaceTmpDir $workspace) -Parent
    foreach ($parent in @($keyDir, (Split-Path $workspace.PublishDir -Parent), ${legacyTmpParent})) {
        if (($parent -eq $keyDir) -and (testPathHasLink $workspace.TmpRoot $keyDir)) {
            writeIndexerLog "    作業領域の途中にリンク（ジャンクション・シンボリックリンク）があるため、残った作業フォルダを片付けませんでした: ${keyDir}" "Yellow"
            continue
        }
        removeStaleProcessDirs $parent
        removeEmptyDir $parent
    }
    removeEmptyDir $workspace.TmpRoot
}

function newDirectoryReplacingExisting {
    # フォルダを作る。同じ名前（前の残り・先に置かれたリンク）が既にあれば、リンクは辿らずに消してから作り直す。
    # 作ったものがリンクでなければ $true（置けた）、リンクのまま残った（消せなかった）ときは $false
    param (
        [string]$dir
    )

    try {
        removeDirectoryRetry $dir
    } catch {
        # 消せなくても、下の確かめでリンクが残っていなければ、そのまま使う
    }
    [System.IO.Directory]::CreateDirectory($dir) | Out-Null
    return !(testPathIsLink $dir)
}

function initTmpDir {
    # インデックス作成の始めに、取り込みの作業フォルダの片付けと用意をまとめて行う: @{ Dir; Reason（置けなかったときだけ） }
    #   1. 強制終了などで残った、ほかの（終了済みの）プロセスの作業フォルダを片付ける（決めた場所を巻き込まないよう、場所を決める前に行う）
    #   2. selectTmpDir で置き場所を決める
    #   3. 置けたら、フォルダを作って tmp・tmp\<PC の鍵>・<PID> に NotContentIndexed を付ける
    #   4. 置けなければ（Dir が空）、フォルダは作らず、理由と「取り込みをすべてスキップする」ことをログに 1 行書く
    #      （どのファイルも中間 TSV などをこのフォルダに作るため、テキストファイルを含めすべての取り込みが対象になる）
    #      （1 ファイルごとのスキップは invokeIngestTask が取り込みの失敗として記録する）
    removeStaleTmpDirs
    $selected = selectTmpDir $workspace
    if (!$selected.Dir) {
        writeIndexerLog "$(getTmpDirUnavailableMessage $selected.Reason)取り込みをすべてスキップします。" "Yellow"
        return $selected
    }
    # 作業領域（tmp\<PC の鍵>\<PID>）の途中にリンク（ジャンクション・シンボリックリンク）があれば、先に書かないよう置けない扱いにする
    # （tmp そのものは見ない。利用者が tmp を別の場所へのリンクにした構成も、今までどおり使える）。
    # 同じ名前（前のプロセスの残り・先に置かれたもの）が既にあれば、リンクは辿らずに消してから作り直す
    $placed = $false
    if (!(testPathHasLink $workspace.TmpRoot (Split-Path $selected.Dir -Parent))) {
        $placed = newDirectoryReplacingExisting $selected.Dir
    }
    if (!$placed) {
        $unavailable = @{ Dir = ""; Reason = "Link" }
        writeIndexerLog "$(getTmpDirUnavailableMessage $unavailable.Reason)取り込みをすべてスキップします。" "Yellow"
        return $unavailable
    }
    foreach ($dir in @($workspace.TmpRoot, (Split-Path $selected.Dir -Parent), $selected.Dir)) {
        [void](setNotContentIndexed $dir)
    }
    return $selected
}

function newWorkerTmpDir {
    # 取り込みのスレッドの作業フォルダ（parentDir\w<番号>）を作り、パスを返す。
    # 親（parentDir。司令のスレッドの作業フォルダ）に NotContentIndexed が付いていれば、同じ属性を付ける。
    # 親が無い（置けなかった）ときは、何も作らず空文字を返す
    param (
        [string]$parentDir,
        [int]$number
    )

    if (!$parentDir) {
        return ""
    }
    if (testPathIsLink $parentDir) {
        writeIndexerLog "    作業フォルダがリンク（ジャンクション・シンボリックリンク）のため、取り込みの作業フォルダを置けません: ${parentDir}" "Yellow"
        return ""
    }
    $dir = Join-Path $parentDir "w$number"
    if (!(newDirectoryReplacingExisting $dir)) {
        return ""
    }
    if (testNotContentIndexed $parentDir) {
        [void](setNotContentIndexed $dir)
    }
    return $dir
}

function removeStaleProcessDirs {
    # プロセスIDの名前のフォルダのうち、そのプロセスが既に終わっているものを削除する
    param (
        [string]$parent
    )

    if (!(Test-Path -LiteralPath $parent)) {
        return
    }
    foreach ($dir in @(Get-ChildItem -LiteralPath $parent -Directory | Where-Object { $_.Name -match "^\d{1,9}$" -and [int]$_.Name -ne $PID })) {
        if (Get-Process -Id ([int]$dir.Name) -ErrorAction SilentlyContinue) {
            continue  # 実行中のインデックス作成（またはPIDを再利用した別のプロセス）のものは残す
        }
        try {
            # 中に長いパスがあっても消え、中のリンクの先は消さない。使用中などで消せなければ 1 回だけ試して次回に回す
            removeDirectoryRetry $dir.FullName 1
        } catch {
            # 使用中・リンクかどうか確かめられないフォルダがあるなどで削除できなければ、原因をログに出して次回に回す
            writeIndexerLog "    終了したプロセスの作業フォルダを削除できませんでした: $($dir.FullName)（$($_.Exception.Message)）" "Yellow"
        }
    }
}

function findDroppedIndexes {
    # 前回の取り込み一覧にあって、今回のクロール対象フォルダに無いインデックス（設定から外れたもの）を返す。見つけるだけで、消さない
    # （消すかどうかは利用者が確認ダイアログで決める。removeDroppedFolders）。チェックを外しただけのフォルダは、今回の一覧にあるため含まない
    param (
        [object[]]$folders,          # assignIndexNames の結果
        [object[]]$previousFolders   # readStatusFile の Folders
    )

    # インデックス名で比べる。フォルダを移動して登録し直した場合は、同じ名前を引き継ぐため含めない（assignIndexNames）
    $current = @($folders | ForEach-Object { $_.Name })
    return @($previousFolders | Where-Object { $_ -and $_.Name -and $current -notcontains $_.Name })
}

function getDroppedStatusRows {
    # 消さずに残す外れたインデックスの、前回の取り込み一覧の行（次の回にまた見つけられるよう、書き直す一覧に残す）
    param (
        [object[]]$dropped,
        $previousRows  # readStatusFile の Rows（相対パス → 行）
    )

    $result = New-Object System.Collections.Generic.List[object]
    if ($null -eq $previousRows) {
        return $result.ToArray()
    }
    foreach ($item in @($dropped | Where-Object { $_ })) {
        $prefix = "$($item.Name)\"
        foreach ($key in @($previousRows.Keys)) {
            if ($key.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)) {
                $result.Add($previousRows[$key])
            }
        }
    }
    return $result.ToArray()
}

function writeStatusKeepingDropped {
    # 取り込み一覧を書く。消さずに残す外れたインデックスのフォルダの行と各行も、前回のまま足して書く（次の回にまた見つけられるように）
    param (
        $ledger,
        [object[]]$folders,      # 今回のクロール対象フォルダ
        [object[]]$rows,         # 今回の各行
        [object[]]$keptDropped,  # 消さずに残す外れたインデックス
        $previousRows            # readStatusFile の Rows（前回の行）
    )

    $ledger.WriteStatus((@($folders) + @($keptDropped)), (@($rows) + @(getDroppedStatusRows $keptDropped $previousRows)))
}

function removeDroppedFolders {
    # 設定から外れたインデックス（findDroppedIndexes の結果。work\content_index\<インデックス名>）を削除する。
    # 利用者が確認ダイアログで［更新を開始］を押した回でだけ呼ぶ
    param (
        [object[]]$dropped,
        $ws = $workspace             # 対象のワークスペース（テストが差し替える）
    )

    foreach ($previous in @($dropped | Where-Object { $_ })) {
        $dir = Join-Path $ws.IndexDir $previous.Name
        if (Test-Path -LiteralPath $dir) {
            # 中に長いパス（260文字超）のTSVがあっても削除でき、中のリンク（ジャンクション・シンボリックリンク）の先は消さない
            removeDirectoryRetry $dir
        }
        writeIndexerLog "クロール対象から削除されたフォルダ（$($previous.Path)）のインデックスを削除しました。"
    }
}

# インデックス作成の本体（invokeIndexer）。画面を使わない起動口（indexer.ps1）と、画面のインデクサのスレッド（IndexingSession）が呼ぶ。
# 設計は docs/design/indexing/parallel.md、docs/design/structure/threads.md「画面とインデクサの受け渡し」。
#
# ・司令のスレッド（invokeIndexer を呼んだスレッド）が、クロール・確認・取り込み一覧・本文インデックスのファイルとシステムインデックスの書き出しを行う。
#   Office の COM には触らない
# ・1 ファイルの取り込み（Office で開いて TSV にする）は、取り込みのスレッド（STA）が行う。スレッドごとに自分の Office を持つ。
#   スレッドの数が 0 のときは、司令のスレッドで取り込む（テストで、途中に割り込むため）
# ・画面とのやり取りは受け渡しの口（newIndexerChannel）で行う。表示内容は indexing_log.txt に書く

# Excel・Word・PowerPoint を利用者に渡したとき・渡すか決められず持ち続けるときのログ（indexing_log.txt）への 1 行。
# office_app.ps1 の handOverApp・keepUndecidedApp が呼ぶ
${officeHandOverNotice} = {
    param ($name, $shown)
    if ($null -eq $shown) {
        # shown が $null: ファイルの一覧を読めず、利用者のファイルがあるか分からない。終了させずに持ち続け、後で読み直す
        writeIndexerLog "${name} のファイルの一覧を読めなかったため、終了させずに残しています（あとで読み直します）" "Yellow"
    } elseif ($shown) {
        writeIndexerLog "開かれたファイルがあるため ${name} を利用者に渡しました"
    } else {
        writeIndexerLog "開かれたファイルがあるため ${name} を利用者に渡しましたが、窓や設定を戻しきれませんでした（終了させずに残しています）" "Yellow"
    }
}

# 取り込みのスレッドで動かすスクリプト。自分のレーンの列（tasks）から 1 ファイルずつ取り出して取り込み、結果を results に入れる。
# Office のレーン（Excel・Word・PowerPoint）は STA で、そのアプリを 1 つ持つ。読み取りのレーンは Office を持たない。
# 列が閉じられたら（CompleteAdding）、Office を終了して終わる
${ingestWorkerScript} = {
    param ($settings, $tasks, $results, $number)
    $ErrorActionPreference = "Stop"
    # indexerLib の部品（Prelude）は addIngestTask が、この param ブロックのあとにつなぐ（joinWorkerScript）
    # 置き場所は司令のスレッドと同じにする（読み込み直すと設定から決め直してしまうため）。一時フォルダはスレッドごとに分ける。
    # 部品を読み込んだのと同じスコープ（取り込みのスレッドでは global）に置く
    $own = [Workspace]::new($settings.WorkDir)
    $own.PublishDir = Join-Path $settings.PublishDir "w$number"
    setCallerWorkspace $own
    Set-Variable -Name tmpDir -Value (newWorkerTmpDir $settings.TmpDir $number)
    Set-Variable -Name tmpDirReason -Value $settings.TmpDirReason
    [System.IO.Directory]::CreateDirectory($workspace.PublishDir) | Out-Null
    $script:officePidSink = $settings.OfficePids
    $script:officeRecordDir = $settings.OfficeRecordDir
    $script:officeOwnDir = resolveOwnDir $tmpDir
    $script:onOfficeHandOver = ${officeHandOverNotice}
    $script:officeUnavailable = ($settings.Lane -eq ${laneReader})
    [System.Threading.Thread]::CurrentThread.Priority = [System.Threading.ThreadPriority]::BelowNormal

    # レーンの状態（制限時間を過ぎても利用者が使っている PowerPoint を止めずに諦めたか）。司令と共有する
    $script:laneState = $settings.LaneState
    if (!$script:officeUnavailable) {
        $script:officeWatchdog.State.Abandon = $settings.LaneState
        if ($settings.UserOfficePids) {
            $script:officeWatchdog.State.Users = $settings.UserOfficePids
        }
        $script:officeWatchdog.Start()
    }
    try {
        runIngestWorker $tasks $results $settings.FileTimeoutMinutes $settings.RestartInterval
    } finally {
        if (!$script:officeUnavailable) {
            $script:officeWatchdog.Stop()
            # 利用者が使っている PowerPoint を諦めたレーンは、終了させない（開いているファイルの保存されていない変更を失わせないため）
            if (!$settings.LaneState.Abandoned) {
                stopAllApps
                # 渡し切れずに持ち続けているアプリは、ここで上限まで仕上げ直す（中止・画面を閉じるときは待たない）
                waitKeptApps ({ [bool]$settings.Channel.Stop }.GetNewClosure())
            }
        }
    }
}

# 司令が並びの先を見る件数（空いているレーン向けのファイルを先に渡すため）。大きくすると、本文インデックスのファイルの書き出しが遅れるフォルダが増える
${ingestLookAhead} = 200

function runIngestWorker {
    # 取り込みのスレッドの繰り返し（ingestWorkerScript が呼ぶ）。列から 1 件ずつ取り込み、結果を results に入れる。
    # Office を持つスレッドは、決まった数を取り込むたびに Office を起動し直す
    param (
        $tasks,
        $results,
        [int]$fileTimeoutMinutes,
        [int]$restartInterval
    )

    $done = 0
    foreach ($task in $tasks.GetConsumingEnumerable()) {
        $result = invokeIngestTask $task $fileTimeoutMinutes
        $results.Add($result)
        if ($result.Postponed) {
            # 後回し（利用者のPowerPointが起動していて使えなかった）は、取り込んだ件数に数えない
            # （件数が変わらないまま後回しが続いたときに、起動し直しを早めないため）
            continue
        }
        $done++
        if (!$script:officeUnavailable -and ($result.TimedOut -or ($done % $restartInterval) -eq 0)) {
            # 制限時間を過ぎて強制終了したアプリは使えないため、すべて終了して次に必要になったときに起動し直す
            stopAllApps
        }
    }
}

function getIngestWorkerCount {
    # 読み取りのスレッド（Office を使わずに読むファイル）の数を決める。requested が 0 以上ならその数
    # （0 は取り込みのスレッドを使わず、司令のスレッドで取り込む）、負なら設定（ingestThreads）、設定が 0 ならコア数から決める。
    # 取り込むファイルの数より多くはしない
    param (
        [int]$requested,
        [int]$total,
        [int]$configured = 0,
        [int]$processors = [Environment]::ProcessorCount
    )

    $count = if ($requested -ge 0) {
        $requested
    } elseif ($configured -gt 0) {
        [Math]::Min($configured, 4)
    } else {
        getWorkerCount 4 $processors
    }
    return [Math]::Max(0, [Math]::Min($count, $total))
}

function getIngestLaneCapacity {
    # レーンに同時に渡しておく数。Office のレーンは取り込み中の 1 件と次の 1 件、読み取りのレーンはスレッドの数の 2 倍
    param (
        [string]$lane,
        [int]$readers
    )

    if ($lane -eq ${laneReader}) {
        return [Math]::Max(1, $readers) * 2
    }
    return 2
}

function testLaneAbandoned {
    # このレーンが、制限時間を過ぎても利用者が使っている PowerPoint を止めずに諦めたものか（取り込みのスレッドの $script:laneState）
    $state = $script:laneState
    return ($null -ne $state -and [bool]$state.Abandoned)
}

function invokeIngestTask {
    # 1 ファイルを取り込み、結果 @{ RelPath; Ok; Reroute; TsvCount; Message; TimedOut; ExtractVersion; Log } を返す（例外は投げない）。
    # 取り込みのスレッド、またはスレッドの数が 0 のときは司令のスレッドで動く。表示内容は Log に貯め、司令がログに書く
    param (
        [hashtable]$task,
        [int]$fileTimeoutMinutes
    )

    # Reroute: Office を使わずに読めなかった（中身が旧形式・パスワード付き）。司令が Word・PowerPoint のレーンに回し直す
    # Postponed: 利用者のPowerPointが起動していて使えなかった。司令が「未取り込み」のまま次回に回す
    $result = @{ RelPath = $task.RelPath; Ok = $false; Reroute = $false; Postponed = $false; TsvCount = 0; Message = ""; TimedOut = $false; ExtractVersion = ""; Log = "" }
    if (!$tmpDir) {
        # 取り込みの作業フォルダを置けない（selectTmpDir の Brackets・TooLong）ときは、
        # どのファイルも中間 TSV などをこのフォルダに作るため、テキストファイルを含めこのファイルの取り込みをスキップし、取り込みの失敗として記録する
        $result.Message = "$(getTmpDirUnavailableMessage $tmpDirReason)このファイルの取り込みをスキップしました。"
        return $result
    }
    if (testLaneAbandoned) {
        # 利用者が使っている PowerPoint を諦めたレーン。取り込まず、後回しにする（司令は結果を受け取らずに後回しにしている）
        $result.Postponed = $true
        return $result
    }
    $log = New-Object System.IO.StringWriter
    $previousLog = $script:indexerLog
    $script:indexerLog = $log
    try {
        clearTmpDir
        $script:officeWatchdog.State.TimedOut = $false
        $script:officeWatchdog.State.Deadline = (Get-Date).AddMinutes($fileTimeoutMinutes)
        try {
            $result.TsvCount = ingestFile $task.SourcePath
        } finally {
            $script:officeWatchdog.State.Deadline = [datetime]::MaxValue
        }
        if (testLaneAbandoned) {
            # 戻ってきたときには、司令がこのファイルを後回しにしている。書き出さない
            # （司令が同じフォルダを書き換えるのと重ならないようにし、取り込み一覧・インデックスを変えない）
            $result.Postponed = $true
            return $result
        }
        publishTsv (getBookDir $task.RelPath)
        $result.ExtractVersion = [string](getExtractVersion $task.RelPath)
        $result.Ok = $true
    } catch {
        $base = $_.Exception.GetBaseException()
        if (testLaneAbandoned) {
            # 諦めたレーンで、利用者の PowerPoint が閉じられるなどして戻ってきた。失敗にも、アプリの終了にもしない
            $result.Postponed = $true
            return $result
        }
        if (isOfficeRequiredException $_.Exception) {
            $result.Reroute = $true
            return $result
        }
        if (isOfficeAppInUseException $_.Exception) {
            # getApp が投げた例外。$script:apps に入っていないため stopApp は呼ばない
            $result.Postponed = $true
            return $result
        }
        # .docx・.pptx を直接読んでサイズの上限を超えたとき（ZipSizeLimitException）は、原因を調べられるよう
        # 部品名・大きさ・部品ごとか合計かをインデックス作成のログに書く。画面・取り込み一覧の
        # $result.Message は今までどおり簡潔な文言のまま（describeIngestError がそのまま通す）
        writeZipSizeLimitLog $base
        $message = describeIngestError $_.Exception
        if ($script:officeWatchdog.State.TimedOut) {
            $message = "${fileTimeoutMinutes} 分以内に更新が終わらなかったため中止しました（Officeアプリを強制終了しました）"
        }
        $result.Message = $message
        # アプリが不安定になっている可能性があるため終了する（次に必要になったときに起動し直す）。
        # 暗号化の判定でOfficeにまだ触れていない失敗（throwProtectionFailure）は、終了させない
        # （IRM・パスワード付きのファイルが並んでも、そのたびにOfficeを起動し直さないため）
        if (!$script:officeUnavailable -and !$base.Data.Contains("OfficeUntouched")) {
            try { stopApp (getAppName $task.RelPath) } catch {}
        }
    } finally {
        # Excel・Word・PowerPoint で利用者が開いたファイルがあれば、閉じずに利用者に渡す（次のファイルは新しいアプリで取り込む。PowerPoint は後回しになる）
        $appName = getAppName $task.RelPath
        if (!$script:officeUnavailable -and $appName -and !(testLaneAbandoned)) {
            try { [void](handOverForeignApp $appName) } catch {}
        }
        $result.TimedOut = [bool]$script:officeWatchdog.State.TimedOut
        $script:indexerLog = $previousLog
        $result.Log = $log.ToString()
    }
    return $result
}

function newIngestPool {
    # 取り込みのスレッドの入れ物を作る。スレッドは、そのレーンのファイルを初めて渡すときに始める（addIngestTask）。
    # 渡すファイルが無いレーンは、スレッドも Office も作らない。@{ Queues; Results; Workers; Readers; Settings; Count }
    param (
        [int]$readers,
        [hashtable]$settings
    )

    $queues = @{}
    $laneStates = @{}
    foreach ($lane in ${laneExcel}, ${laneWord}, ${lanePowerPoint}, ${laneReader}) {
        $queues[$lane] = New-Object 'System.Collections.Concurrent.BlockingCollection[hashtable]'
        # Abandoned: 制限時間を過ぎても利用者が使っている PowerPoint を止めずに、このレーンを諦めた（取り込みのスレッドの監視が立てる）。
        # Handled: 司令が、取り込み中だったファイルの後回しを済ませた
        $laneStates[$lane] = [hashtable]::Synchronized(@{ Abandoned = $false; Handled = $false })
    }
    return @{
        Queues   = $queues
        LaneStates = $laneStates
        Results  = New-Object 'System.Collections.Concurrent.BlockingCollection[hashtable]'
        Workers  = New-Object System.Collections.Generic.List[hashtable]
        Readers  = $readers
        Settings = $settings
        Started  = @{}
    }
}

function addIngestTask {
    # レーンの列にファイルを渡す。そのレーンのスレッドがまだ無ければ始める
    # （Office のレーンは STA のスレッド 1 つ、読み取りのレーンは MTA のスレッドを読み取りの数だけ）
    param (
        [hashtable]$pool,
        [string]$lane,
        [hashtable]$task
    )

    if (!$pool.Started.ContainsKey($lane)) {
        $pool.Started[$lane] = $true
        $count = if ($lane -eq ${laneReader}) { $pool.Readers } else { 1 }
        for ($i = 0; $i -lt $count; $i++) {
            $settings = $pool.Settings.Clone()
            $settings.Lane = $lane
            $settings.LaneState = $pool.LaneStates[$lane]
            $runspace = [runspacefactory]::CreateRunspace($settings.Lib.State)
            # Office の COM は、作ったスレッドから呼ぶ（STA）。読み取りのスレッドは COM を使わない（MTA）
            $runspace.ApartmentState = if ($lane -eq ${laneReader}) { [System.Threading.ApartmentState]::MTA } else { [System.Threading.ApartmentState]::STA }
            $runspace.ThreadOptions = [System.Management.Automation.Runspaces.PSThreadOptions]::ReuseThread
            $runspace.Open()
            $ps = [powershell]::Create()
            $ps.Runspace = $runspace
            $number = $pool.Workers.Count + 1
            $joined = if ($settings.Lib.Prelude) { joinWorkerScript $settings.Lib.Prelude ${ingestWorkerScript}.ToString() } else { ${ingestWorkerScript}.ToString() }
            [void]$ps.AddScript($joined).AddArgument($settings).AddArgument($pool.Queues[$lane]).AddArgument($pool.Results).AddArgument($number)
            $pool.Workers.Add(@{ PowerShell = $ps; Runspace = $runspace; Handle = $ps.BeginInvoke(); Ended = $false; Lane = $lane })
        }
    }
    $pool.Queues[$lane].Add($task)
}

function getUnhandledAbandonedLanes {
    # 諦めた（Abandoned）のに、司令がまだ後回しを済ませていない（Handled でない）レーンの名前の並び。取り込みのスレッドが無いレーンは含まない
    param (
        [hashtable]$pool
    )

    return @($pool.Started.Keys | Where-Object { $pool.LaneStates[$_].Abandoned -and !$pool.LaneStates[$_].Handled })
}

function receiveIngestResult {
    # 取り込みのスレッドの結果を 1 つ受け取る。スレッドが途中で止まっていたら（読み込めない等）、その理由で例外にする。
    # 諦めたレーンがあって司令が後回しを済ませていないときは、結果を待たずに $null を返す
    param (
        [hashtable]$pool
    )

    $result = $null
    while (!$pool.Results.TryTake([ref]$result, 500)) {
        if (@(getUnhandledAbandonedLanes $pool).Count -gt 0) {
            # 制限時間を過ぎても利用者が使っている PowerPoint を止めずに諦めたレーンがある。戻らない結果を待たずに、司令に後回しをさせる
            return $null
        }
        foreach ($worker in $pool.Workers) {
            if ($worker.Ended -or !$worker.Handle.IsCompleted -or $pool.LaneStates[$worker.Lane].Abandoned) {
                continue
            }
            $worker.Ended = $true
            $reason = "取り込みのスレッドが止まりました。"
            try {
                [void]$worker.PowerShell.EndInvoke($worker.Handle)
            } catch {
                $exception = $_.Exception
                while ($exception.InnerException) {
                    $exception = $exception.InnerException
                }
                $reason = "取り込みのスレッドが止まりました：$($exception.Message)"
            }
            throw $reason
        }
    }
    return $result
}

function stopIngestWorkers {
    # 取り込みのスレッドに終わりを伝え、取り込み中のファイルが終わるのを待ってから片づける（Office のスレッドは Office を終了してから終わる）
    param (
        [hashtable]$pool
    )

    foreach ($queue in $pool.Queues.Values) {
        $queue.CompleteAdding()
    }
    $abandoned = $false
    foreach ($worker in $pool.Workers) {
        if ($pool.LaneStates[$worker.Lane].Abandoned -and !$worker.Handle.IsCompleted) {
            # 諦めたレーンのスレッドは、固まった PowerPoint の呼び出しから戻らないことがある。待たず、止める依頼（BeginStop）だけを出す。
            # PowerShell・ランスペースと列は Dispose しない（Dispose は動いている間は止まるのを待つ）。後片付けはプロセスの終わりに任せる
            try { [void]$worker.PowerShell.BeginStop($null, $null) } catch {}
            $worker.Ended = $true
            $abandoned = $true
            continue
        }
        if (!$worker.Ended) {
            try {
                [void]$worker.PowerShell.EndInvoke($worker.Handle)
            } catch {
            }
            $worker.Ended = $true
        }
        $worker.PowerShell.Dispose()
        $worker.Runspace.Dispose()
    }
    if (!$abandoned) {
        foreach ($queue in $pool.Queues.Values) {
            $queue.Dispose()
        }
        $pool.Results.Dispose()
    }
}

function invokeIndexer {
    # インデックスを作成し、終了コード（0 = 完了 / 1 = 続けられないエラー / 2 = 中止（確認で取りやめた場合を含む））を返す。
    # 終了コード・エラーの内容は受け渡しの口（channel）にも入れる（ExitCode は最後に入れる。画面は ExitCode が入ったら終わったとみなす）
    param (
        $channel
    )

    $script:indexerChannel = $channel
    $exitCode = 1
    $mutex = $null
    try {
        # 既定のワークスペースにほかのファイルが置いてあれば、インデックスのファイルと混ざるため作成しない。
        # 空でないフォルダにログを書かないよう、ログを開く前に確かめる（画面は起動する前に同じ確認をする）
        $workspaceBlock = getWorkspaceBlockMessage
        if ($workspaceBlock) {
            if ($script:settingsRecovery) {
                writeIndexerLog (getSettingsRecoveryMessage $script:settingsRecovery) "Yellow"
                $script:settingsRecovery = ""
            }
            writeIndexerLog $workspaceBlock "Red"
            $channel.Error = $workspaceBlock
            $exitCode = 1
        } else {
            # 同じ work に対してインデックス作成を 2 つ動かすと、取り込み一覧・インデックスが食い違うため 1 つだけ動かす。
            # 画面と indexer.ps1 の両方から動かせるため、鍵は work のパスから作る。ログに触る前に確かめる
            $mutex = newAppMutex "indexer" $workspace.Dir
            if (!$mutex.Acquired) {
                throw "ほかのインデックス作成が実行中です。インデックス作成が終わってから実行してください。"
            }
            [System.IO.Directory]::CreateDirectory($workspace.Dir) | Out-Null
            # 鍵を取れた後にだけ、前回の記録を残す（取れなかったときはほかのインデックス作成の記録に触らない）
            [void](rotateLogFile $workspace.IndexingLogFile 0)
            $writer = New-Object System.IO.StreamWriter($workspace.IndexingLogFile, $false, ${utf8Bom})
            $writer.AutoFlush = $true
            $script:indexerLog = $writer
            try {
                # 先頭に版と環境を書く（画面なしで動かしたときにコンソールへ出さないよう writeIndexerLog は使わない）。書けなくても続ける
                foreach ($headerLine in @(getToolDiagnosticHeader)) {
                    $writer.WriteLine($headerLine)
                }
            } catch {}
            if ($script:settingsRecovery) {
                # 画面なしで起動したとき、起動口が壊れた設定ファイルを退避している。ログの先頭に知らせる
                writeIndexerLog (getSettingsRecoveryMessage $script:settingsRecovery) "Yellow"
                $script:settingsRecovery = ""
            }
            # 途中の処理が出力した値が混ざらないよう、最後の値（return した終了コード）を使う
            $exitCode = [int]@(invokeIndexerBody $channel)[-1]
        }
    } catch {
        # 続けられないエラー。画面に伝える
        $message = $_.Exception.Message
        writeIndexerLog "＜エラー＞"
        writeIndexerLog $message "Red"
        $channel.Error = $message
        $exitCode = 1
    } finally {
        if ($script:indexerLog) {
            try { $script:indexerLog.Dispose() } catch {}
            $script:indexerLog = $null
        }
        if ($mutex) {
            if ($mutex.Acquired) {
                try { $mutex.Mutex.ReleaseMutex() } catch {}
            }
            $mutex.Mutex.Dispose()
        }
        $script:indexerChannel = $null
        $channel.ExitCode = $exitCode
    }
    return $exitCode
}

function invokeIndexerBody {
    # invokeIndexer の本体（鍵を取り、ログを開いた後）。終了コードを返す。続けられないエラーは例外にする。
    # 取り込み一覧・取り込み中のファイル・今回の失敗と消えた行は StatusLedger（$ledger）、
    # 本文インデックスへの書き出し待ちは PendingPublish（$pending）、進み具合・画面の確認待ちは IndexingReporter（$reporter）にまとめる。
    # 3 つは互いを呼ばず、ここ（司令）がつなぐ（docs/design/structure/classes.md「クラスのつなぎ方」）
    param (
        $channel
    )

    $ledger = [StatusLedger]::new($workspace)
    $pending = [PendingPublish]::new()
    $reporter = [IndexingReporter]::new($channel)

    # 書き出し待ちのフォルダを本文インデックスへまとめる（書き出しは司令であるここが呼ぶ。PendingPublish は決めて返すだけ）。
    # -All は、取り込み中・まだ渡していない数を見ずに、書き出し待ちのフォルダをすべて書き出す（クロールの前後・インデックス作成の終わり）
    function flushPending {
        param ([switch]$All)

        $flush = if ($All) { $pending.TakeAll() } else { $pending.TakeFlushable() }
        if ($flush.Count -eq 0) {
            return
        }
        try {
            [void](publishIndexFolders $flush)
        } catch {
            writeIndexerLog "    インデックスをまとめられませんでした（次のインデックス作成でまとめ直します）: $($_.Exception.Message)" "Yellow"
        }
    }

    # 利用者が使っている PowerPoint のために取り込めなかったファイルを、失敗として記録する（件数は呼び出す側が数える）。
    # 取り込み一覧の行は「未取り込み」のまま、理由を「エラー」列に書く（「失敗」にすると、次の更新で飛ばされるため）。
    # 前回の行があれば、TSV 数・取り込み日時・抽出版は前回のまま残す（インデックスは変えていない）
    function recordUserPowerPointPostponed {
        param ([int]$number, $row, [string]$reason)

        $relPath = [string]$row.相対パス
        $old = $null
        if ($previous.TryGetValue($relPath, [ref]$old) -and $old) {
            $row.TSV数 = $old.TSV数
            $row.取り込み日時 = $old.取り込み日時
            $row.抽出版 = $old.抽出版
        }
        $row.状態 = ${stateNew}
        $row.エラー = $reason
        $ledger.AddFailure($relPath, $reason)
        writeIndexerLog ("[{0}/{1}] {2}" -f $number, $total, $relPath)
        writeIndexerLog "    取り込めませんでした（次の更新で取り込みます）: $reason" "Yellow"
    }
    # 取り込み中のファイルを、取り込み中から外して残す（書き出し待ちを済ませ、失敗として記録する。releaseLane: レーンの取り込み中の数も減らす）
    function postponeInflightForUser {
        param ([string]$relKey, [string]$reason, [switch]$releaseLane)

        $lost = $inflight[$relKey]
        [void]$inflight.Remove($relKey)
        if ($releaseLane) {
            $laneBusy[$lost.Lane] = $laneBusy[$lost.Lane] - 1
        }
        $pending.Complete($lost.Folder)
        recordUserPowerPointPostponed $lost.Number $lost.Row $reason
    }

    $reporter.Progress(${indexingPhaseCrawl}, 0, 0, 0, "インデックス作成の準備をしています…")

    $restartInterval = 100  # Officeアプリを再起動する間隔（取り込みのスレッドごとのファイル数）。メモリ肥大化対策（再起動 1 回で約 2 秒かかるため、間隔を詰めすぎない）
    $fileTimeoutMinutes = ${ingestFileTimeoutMinutes}  # 1ファイルの取り込みの制限時間（分）。超えたらOfficeアプリを強制終了し、そのファイルは失敗とする
    $approvalTimeoutMinutes = 60  # 画面の返事を待つ制限時間（分）。画面が返事をしない場合に待ち続けないよう打ち切る
    $interruptLimit = 2       # 取り込み中に続けて強制終了した回数がこれに達したファイルは、失敗として以降スキップする
    $failureListLimit = 50    # 終了時に失敗したファイルと原因を表示する最大件数（残りは取り込み一覧で確認する）
    $cloudListLimit = 50      # クラウドにだけあるため残したファイルを、ログに 1 件ずつ書く最大件数（残りは「ほか N 件」にする）

    $targetFolders = @(getTargetFolders)
    if ($targetFolders.Count -eq 0) {
        throw "クロール対象フォルダがありません。画面でクロール対象フォルダを追加してください。"
    }
    if (@($targetFolders | Where-Object { $_.Enabled }).Count -eq 0) {
        throw "チェックの付いたクロール対象フォルダがありません。画面で取り込むフォルダにチェックを付けてください。"
    }

    # 前の版のインデックス（index\）が見つかれば知らせ、取り込み直しを始めるときは前の版のシステムインデックスを片付ける。
    # content_index\ を作る前に行う（片付けに失敗したら content_index\ を作らずに終わる）
    $legacyState = getLegacyIndexState $workspace.Dir
    $legacyMessage = getLegacyIndexMessage $workspace.Dir $legacyState.HasLegacyIndex
    if ($legacyMessage) {
        writeIndexerLog $legacyMessage "Yellow"
    }
    if (testLegacyCleanupNeeded $legacyState) {
        writeIndexerLog "前の版のインデックス（高速検索用）を片付けています…"
        $cleanup = clearLegacySystemIndex $workspace.Dir
        if (!$cleanup.Ok) {
            throw "前の版のインデックス（高速検索用）を片付けられませんでした（$($cleanup.Reason)）。tebunko の画面やエクスプローラーで開いていれば閉じてから、もう一度インデックス作成を行ってください。"
        }
    }

    [System.IO.Directory]::CreateDirectory($workspace.IndexDir) | Out-Null
    # 前の版から続けて使うワークスペース・別のドライブへ写したワークスペース・取り込んだワークスペースもここで付く
    # （継ぐかどうかに頼らず、ここで一度だけ content_index 全体に付ける。入れた直後にはそれぞれの場所でも付ける）。
    # 根フォルダに未だ付いていない回（主に初回）は下をすべてたどるため時間がかかるので、先に 1 行残しておく
    writeIndexerLog "content_index を Windows Search の対象から外しています…"
    $nci = setNotContentIndexed $workspace.IndexDir -Recurse
    if (!$nci.Ok) {
        writeIndexerLog "content_index を Windows Search の対象から外せませんでした（$($nci.Reason)）。高速検索が効くまで時間がかかることがあります。" "Yellow"
    }
    $selected = initTmpDir
    $script:tmpDir = $selected.Dir
    $script:tmpDirReason = $selected.Reason
    [System.IO.Directory]::CreateDirectory($workspace.PublishDir) | Out-Null

    # クロール対象フォルダごとにインデックス名（work\content_index 直下のフォルダ名）を決める。前回と同じフォルダは同じ名前を使う
    $status = $ledger.ReadStatus()
    $planner = [IngestPlanner]::new(@{
        Unchecked = ${planKindUnchecked}; Missing = ${planKindMissing}; Dropped = ${planKindDropped}; StateFailed = ${stateFailed}
    })
    $catalog = [IndexCatalog]::new($workspace, ${settingsFile}, $ledger)
    $planner.AssignNames($targetFolders, $status)
    $folders = $planner.Folders
    $previous = $planner.Previous
    # 設定から外れたインデックスは、ここでは消さない。確認ダイアログに「削除予定」として出し、［更新を開始］が押されたときだけ消す
    $dropped = $planner.Dropped
    # 前回のインデックス作成が途中で止まり、本文インデックスのファイルに入れていない TSV（元のファイルごとのフォルダ）が残っていれば、先に入れる
    $leftover = findIndexFoldersWithBooks $workspace.IndexDir
    if ($leftover.Count -gt 0) {
        writeIndexerLog "集約ファイルに入れていないインデックス（$($leftover.Count) フォルダ）をまとめています…"
        $reporter.Progress(${indexingPhaseCrawl}, 0, 0, 0, "集約ファイルに入れていないインデックスをまとめています…")
        foreach ($folder in $leftover) {
            $pending.MarkFolder($folder)
        }
        flushPending -All
    }

    # 新しく割り当てたインデックス名を設定に保存する
    $planner.SaveNames($targetFolders, { param($assigned) $catalog.StoreAssignedNames($assigned) }.GetNewClosure())
    $folders = $planner.Folders

    writeIndexerLog "出力先フォルダ: $($workspace.IndexDir)"
    writeIndexerLog ""
    writeIndexerLog "クロールしています..."
    # 取り込み一覧の「済」に対してインデックス（TSV）が残っているかを調べるため、今あるTSVの数を数えておく
    # （利用者が work\content_index を直接削除した場合に、「済」のまま検索できなくなるのを防ぐ）
    $reporter.Progress(${indexingPhaseCrawl}, 0, 0, 0, "更新済みのインデックスを確認しています…")
    $indexCounts = getIndexTsvCounts
    if ($null -eq $indexCounts) {
        writeIndexerLog "  インデックスのフォルダを調べられないため、インデックスが残っているかの確認は行いません。" "Yellow"
    }
    # 選んだインデックスだけを更新するとき（OnlyNames）。選ばなかったインデックスは、この回では一切触らない
    # （取り込み一覧の行は前回のまま・確認の表に出さない・失敗の一覧に加えない）
    if (@($channel.OnlyNames).Count -gt 0) {
        $channel.OnlySkipped = @($planner.SelectOnly([string[]]@($channel.OnlyNames)))
        if ($planner.Only.Selected.Count -eq 0) {
            throw "選んだインデックスに、更新できるものがありません。"
        }
    }
    # クロールして、取り込む順番・画面の確認に出す件数・取り込み一覧に書く行を組み立てる
    $crawlPhase = ${indexingPhaseCrawl}
    $onCrawlFolder = { param ($target) $reporter.Progress($crawlPhase, 0, 0, 0, "[$($target.Name)] の対象ファイルを探しています… $($target.Path)") }.GetNewClosure()
    $planner.Crawl($indexCounts, $onCrawlFolder)
    foreach ($removedPath in $planner.RemovedPaths) {
        $pending.Add($removedPath, $true)
    }
    $rows = $planner.Rows
    $targets = $planner.Targets
    $failed = $planner.Failed
    $plan = $planner.Plan
    # クラウドにだけあるファイル（取り込むかは確認の後に決める）
    $cloudAll = $planner.Cloud
    # 消さなかったインデックス（取りやめ・画面なしの実行）は、取り込み一覧に前回のまま残す（次の回にまた見つけて確認に出すため）
    $keptDropped = $dropped

    # 画面から始めた場合は、数えた件数を画面に出して、取り込むかどうかの返事を待つ。
    # 「更新不要」かどうかも、この件数を見て画面が知らせる（取り込み対象が 0 件でも、前回失敗の再取り込みを選べる）
    $retryTargets = [bool]$channel.RetryFailed
    $includeCloud = [bool]$channel.IncludeCloud
    if ($channel.ConfirmTargets) {
        $answer = $reporter.WaitForApproval(${indexingPhaseConfirm}, $plan.ToArray(), $targets.Count, $failed.Count, $approvalTimeoutMinutes)
        if ($null -eq $answer) {
            # 取りやめ。取り込み対象にした行は前回の記録のまま（一覧に無かったファイルは記録しない）にする。
            # 取り込み一覧自体は書き直す（無くなったファイルの削除を反映する必要があるため）
            $keep = $planner.KeepForCancel()
            writeIndexerLog ""
            writeIndexerLog "画面で取りやめたため、取り込みません。（取り込み一覧は前回のままです）" "Yellow"
            writeStatusKeepingDropped $ledger $folders $keep $keptDropped $previous
            writeSourceFolderFile $folders
            $reporter.Progress(${indexingPhaseFinish}, 0, 0, 0, "インデックス作成を取りやめました")
            removeTmpDir
            return 2
        }
        $retryTargets = $answer.RetryFailed
        $includeCloud = [bool]$answer.IncludeCloud
        removeDroppedFolders $dropped
        $keptDropped = @()
    } else {
        foreach ($item in $dropped) {
            writeIndexerLog "設定に無いインデックス（$($item.Name): $($item.Path)）は削除せずに残しました。画面の［すべて更新］で確認して削除できます。" "Yellow"
        }
    }

    # クラウドにだけあるファイル: ダウンロードして取り込むと選ばれたものだけ取り込み、あとは前回のまま残す
    # （取り込み一覧の行は createTargetList が前回の行にしてある。次のインデックス作成で、また確かめる）
    $cloudSplit = splitCloudItems $cloudAll $retryTargets $includeCloud
    if ($cloudSplit.Included.Count -gt 0) {
        $includedPaths = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
        foreach ($item in $cloudSplit.Included) {
            [void]$includedPaths.Add($item.RelPath)
        }
        $rebuilt = New-Object System.Collections.Generic.List[object]
        foreach ($row in $rows) {
            if (!$includedPaths.Contains($row.相対パス)) {
                $rebuilt.Add($row)
            }
        }
        $rows = $rebuilt
        writeIndexerLog ""
        writeIndexerLog "クラウドにだけあるファイル $($cloudSplit.Included.Count) 件は、ダウンロードして取り込みます。"
        foreach ($item in $cloudSplit.Included) {
            $rows.Add($item.Row)
            $targets.Add($item.Row)
        }
    }
    # 前回失敗したファイルを再取り込みしない（チェックなし）なら、クラウドにあるかどうかに関係なく残すため、クラウドのせいで残した件数には数えない
    $cloudSkippedItems = @($cloudSplit.Skipped | Where-Object { $retryTargets -or -not $_.Failed })
    $cloudSkipped = $cloudSkippedItems.Count
    $channel.CloudSkipped = $cloudSkipped
    if ($cloudSkipped -gt 0) {
        writeIndexerLog ""
        writeIndexerLog "クラウドにだけあるファイル $cloudSkipped 件は、ダウンロードせずに残します。（次のインデックス作成でも確かめます）" "Yellow"
        foreach ($group in ($cloudSkippedItems | Group-Object { ([string]$_.RelPath).Split("\")[0] })) {
            writeIndexerLog "  [$($group.Name)] $($group.Count) 件"
        }
        $listed = 0
        foreach ($item in $cloudSkippedItems) {
            # 大きいフォルダでは毎回この件数ぶん出るため、先頭の $cloudListLimit 件だけ書き、残りは件数にする
            if ($listed -lt $cloudListLimit) {
                writeIndexerLog "    $($item.RelPath)"
                $listed++
            }
            if ($item.PendingOld) {
                # 前回未完了のまま残っている取り込み途中のインデックスは、使えないため消す（一覧にも行を残さない）
                removeBookDir (getBookDir $item.RelPath)
                $pending.Add($item.RelPath, $true)
            }
        }
        if ($cloudSkipped -gt $listed) {
            writeIndexerLog "    ほか $($cloudSkipped - $listed) 件"
        }
    }

    $planner.ApplyFailed($retryTargets)
    # 前回、取り込み中に強制終了したファイルは最後に回す（続けて $interruptLimit 回強制終了したファイルは失敗とする）。
    # 最後に回したファイルは、取り込みを始めるまで記録を残す（その前にまた止まっても、回数が分かるように）
    $planner.ApplyInterrupted(@($ledger.ReadIngestingFiles()), $interruptLimit)
    $carried = $planner.Carried
    $ledger.WriteIngestingFiles(@($carried.Keys | ForEach-Object { @{ RelPath = $_; Count = $carried[$_] } }))
    $reporter.Progress(${indexingPhaseCrawl}, 0, $targets.Count, 0, "更新の記録を書き出しています…")
    writeStatusKeepingDropped $ledger $folders $rows.ToArray() $keptDropped $previous
    # インデックスのフォルダごと別の場所・PCへコピーしても元のファイルの場所が分かるよう、インデックス名とクロール対象フォルダの対応を置く
    writeSourceFolderFile $folders

    # インデックス名 → クロール対象フォルダ
    $folderByName = $planner.FolderByName()

    if ($targets.Count -eq 0) {
        writeIndexerLog ""
        if ($cloudSkipped -eq 0) {
            writeIndexerLog "取り込みが必要なファイルはありません。（一覧: $(Split-Path $workspace.StatusFile -Leaf)）" "Green"
        } else {
            writeIndexerLog "取り込めるファイルはありません。（一覧: $(Split-Path $workspace.StatusFile -Leaf)）" "Green"
        }
        # 元のファイルが無くなったフォルダは、本文インデックスのファイルから外す
        flushPending -All
        # 取り込むファイルが無くても、システムインデックスがまだ無いフォルダ（この版に上げた直後など）は作る
        $reporter.Progress(${indexingPhaseFinish}, 0, 0, 0, "システムインデックス（高速検索用）を確かめています…")
        try {
            [void](updateSystemIndexes -shouldStop { $channel.Stop })
        } catch {
            writeIndexerLog "システムインデックスを作れませんでした（次のインデックス作成で作り直します）: $($_.Exception.Message)" "Yellow"
        }
        $reporter.Progress(${indexingPhaseFinish}, 0, 0, 0, $(if ($cloudSkipped -eq 0) { "更新が必要なファイルはありませんでした" } else { "クラウドにだけあるファイルは、ダウンロードせずに残しました" }))
        removeTmpDir
        return 0
    }

    $total = $targets.Count
    $readers = getIngestWorkerCount $channel.Workers $total ([int](readSettings).ingestThreads)
    writeIndexerLog ""
    if ($readers -gt 0) {
        writeIndexerLog "$total 件のファイルを取り込みます。（Excel・Word・PowerPoint はそれぞれ 1 つずつ、Office を使わずに読むファイルは $readers 個のスレッドで並べて取り込みます。1ファイルの取り込みに ${fileTimeoutMinutes} 分以上かかった場合は、そのファイルを失敗として次のファイルへ進みます）"
    } else {
        writeIndexerLog "$total 件のファイルを取り込みます。（1ファイルの取り込みに ${fileTimeoutMinutes} 分以上かかった場合は、そのファイルを失敗として次のファイルへ進みます）"
    }

    $successCount = 0
    $postponedCount = 0 # 利用者のPowerPointのために取り込めなかった件数（失敗の件数に含む。一覧は「未取り込み」のまま次回に回す。終わりの案内で、再取り込みの選択が要る失敗と分ける）
    $stopped = $false
    # 今回失敗したファイル（$ledger.Failures。@{ RelPath; Message } の並び）・
    # 取り込みの直前に元のファイルが無くなっていた相対パス（$ledger.DroppedRows。取り込み一覧から除く）は StatusLedger が持つ
    $folderLost = ""  # インデックス作成中に見えなくなったクロール対象フォルダ（見つかったら中止する）
    $remaining = 0
    # 取り込み中のファイル: 相対パス → @{ Row; Count; Folder; Number; Lane; Task }
    $inflight = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)
    # フォルダごとの取り込み中の数と、まだ渡していない数（どちらも 0 になったら本文インデックスのファイルに書き出す）は $pending が持つ
    # レーンごとの取り込み中の数（レーンに渡せる数は ingestLaneCapacity）
    $laneBusy = @{}
    $lanes = New-Object string[] $total
    $bookFolders = New-Object string[] $total
    $dispatched = New-Object bool[] $total
    $undispatched = $total
    for ($i = 0; $i -lt $total; $i++) {
        $lanes[$i] = getIngestLane $targets[$i].相対パス
        $bookFolders[$i] = [System.IO.Path]::GetDirectoryName((getBookDir $targets[$i].相対パス))
        $pending.AddPending($bookFolders[$i])
    }
    # 起動した Office の PID の記録を置く場所（開始時のワークスペースから決め、取り込みのスレッドへ文字列で渡す。途中でワークスペースが変わっても、書く所と消す所が食い違わない）
    $officeRecordDir = getOfficePidDir $workspace
    $pool = $null
    $inlineResult = $null
    $currentPath = ""  # 最後に取り込みのスレッドに渡したファイル（画面に「取り込み中のファイル」として出す）
    $next = 0          # まだ渡していない最初のファイル

    try {
        if ($readers -gt 0) {
            $pool = newIngestPool $readers @{
                Lib = (getPartLoad indexerLib)
                WorkDir = $workspace.Dir; TmpDir = ${tmpDir}; TmpDirReason = ${tmpDirReason}; PublishDir = $workspace.PublishDir
                FileTimeoutMinutes = $fileTimeoutMinutes; RestartInterval = $restartInterval; OfficePids = $channel.OfficePids
                UserOfficePids = $channel.UserOfficePids
                OfficeRecordDir = $officeRecordDir; Channel = $channel
            }
        } else {
            $script:officePidSink = $channel.OfficePids
            $script:officeRecordDir = $officeRecordDir
            $script:officeOwnDir = resolveOwnDir ${tmpDir}
            $script:onOfficeHandOver = ${officeHandOverNotice}
            # 司令のスレッドで取り込むときは、利用者が使っている PowerPoint を止めないだけ（諦めるレーンが無いため Abandon は渡さない）
            $script:officeWatchdog.State.Users = $channel.UserOfficePids
            $script:officeWatchdog.Start()
        }

        while ($true) {
            # 制限時間を過ぎても利用者が使っている PowerPoint を止めずに諦めたレーンは、取り込み中だったファイルを後回しにする
            # （固まった呼び出しは戻らないことがあるため、結果を待たない。戻ってきた結果は捨てる）
            if ($pool) {
                foreach ($abandonedLane in @(getUnhandledAbandonedLanes $pool)) {
                    $pool.LaneStates[$abandonedLane].Handled = $true
                    foreach ($relKey in @($inflight.Keys)) {
                        if ($inflight[$relKey].Lane -ne $abandonedLane) {
                            continue
                        }
                        postponeInflightForUser $relKey ${postponedReasonInUse} -releaseLane
                        $postponedCount++
                    }
                    $ledger.WriteIngestingFiles((getIngestingEntries $inflight $carried))
                    $reporter.Progress(${indexingPhaseIngest}, ($successCount + $ledger.Failures.Count), ($total - $successCount - $ledger.Failures.Count), $ledger.Failures.Count, $currentPath)
                    flushPending
                }
            }
            # 空いているレーンに、次のファイルを渡す。並びの先（ingestLookAhead 件まで）も見て、空いているレーン向けのものを先に渡す
            # （Excel のファイルが続いても、Office を使わずに読むファイルを待たせない）
            if (!$stopped -and !$folderLost -and $undispatched -gt 0 -and $channel.Stop) {
                # 画面から中止を求められたら、次のファイルを渡さずに終える（残りは「未取り込み」のまま、次回取り込みする）
                $stopped = $true
                $remaining = $undispatched
                writeIndexerLog ""
                writeIndexerLog "中止の要求を受けたため、インデックス作成を中止します。（残り ${remaining} 件は次回取り込みします）" "Yellow"
            }
            $limit = [Math]::Min($total, $next + ${ingestLookAhead})
            for ($i = $next; !$stopped -and !$folderLost -and $i -lt $limit; $i++) {
                if ($dispatched[$i]) {
                    continue
                }
                $lane = $lanes[$i]
                if ($pool -and $pool.LaneStates[$lane].Abandoned) {
                    # 諦めたレーンのファイルは、渡さずに「未取り込み」のまま残す
                    $dispatched[$i] = $true
                    $undispatched--
                    $pending.Skip($bookFolders[$i])
                    $postponedCount++
                    recordUserPowerPointPostponed ($i + 1) $targets[$i] ${postponedReasonInUse}
                    $reporter.Progress(${indexingPhaseIngest}, ($successCount + $ledger.Failures.Count), ($total - $successCount - $ledger.Failures.Count), $ledger.Failures.Count, $currentPath)
                    continue
                }
                if ($pool) {
                    if ([int]$laneBusy[$lane] -ge (getIngestLaneCapacity $lane $readers)) {
                        continue
                    }
                } elseif ($inflight.Count -ge 1) {
                    break
                }
                $row = $targets[$i]
                $relPath = $row.相対パス
                $bookFolder = $bookFolders[$i]
                $parts = splitIndexRelPath $relPath
                $sourceFolder = $folderByName[$parts.Name]
                $sourcePath = Join-Path $sourceFolder $parts.Rest

                # 取り込み対象を調べてから取り込むまでの間に、元のファイルが移動・削除されることがある。
                # 「失敗」として記録すると、再取り込みを選ぶまで残ってしまうため、無くなったファイルは一覧・インデックスから除く
                if (![System.IO.File]::Exists((toLongPath $sourcePath))) {
                    if (!(Test-Path -LiteralPath $sourceFolder -PathType Container)) {
                        # クロール対象フォルダごと見えなくなった（ネットワークの切断・USBメモリの取り外し等）。
                        # 残りのファイルをすべて失敗にしないよう、「未取り込み」のまま中止する（次回、続きから取り込める）
                        $folderLost = $sourceFolder
                        $remaining = $undispatched
                        break
                    }
                    $dispatched[$i] = $true
                    $undispatched--
                    $pending.Skip($bookFolder)
                    writeIndexerLog ("[{0}/{1}] {2}" -f ($i + 1), $total, $relPath)
                    writeIndexerLog "    元のファイルが無くなったため、取り込まずに一覧から除きます。（移動・削除・名前変更された）" "Yellow"
                    removeBookDir (getBookDir $relPath)
                    $pending.Add($relPath, $true)
                    $ledger.AddDropped($relPath)
                    continue
                }

                # 強制終了したときに、どのファイルの取り込み中に止まったか次回分かるよう記録する
                $count = 1
                if ($carried.ContainsKey($relPath)) {
                    $count = $carried[$relPath] + 1
                    [void]$carried.Remove($relPath)
                }
                $task = @{ RelPath = $relPath; SourcePath = $sourcePath }
                $dispatched[$i] = $true
                $undispatched--
                $inflight[$relPath] = @{ Row = $row; Count = $count; Folder = $bookFolder; Number = $i + 1; Lane = $lane; Task = $task }
                $pending.Dispatch($bookFolder)
                $laneBusy[$lane] = [int]$laneBusy[$lane] + 1
                $ledger.WriteIngestingFiles((getIngestingEntries $inflight $carried))
                # 画面はこの 1 行から進み具合を作る（取り込み一覧は読まない）
                $currentPath = $relPath
                $reporter.Progress(${indexingPhaseIngest}, ($successCount + $ledger.Failures.Count), ($total - $successCount - $ledger.Failures.Count), $ledger.Failures.Count, $currentPath)
                if ($pool) {
                    addIngestTask $pool $lane $task
                } else {
                    $inlineResult = invokeIngestTask $task $fileTimeoutMinutes
                }
            }
            while ($next -lt $total -and $dispatched[$next]) {
                $next++
            }
            if ($inflight.Count -eq 0) {
                if ($stopped -or $folderLost -or $undispatched -eq 0) {
                    break
                }
                continue
            }

            # 取り込みの結果を 1 つ受け取って記録する
            if ($pool) {
                $result = receiveIngestResult $pool
            } else {
                $result = $inlineResult
                $inlineResult = $null
            }
            if ($null -eq $result) {
                # 諦めたレーンがある。ループの先頭で後回しにする
                continue
            }
            $entry = $null
            if (!$inflight.TryGetValue($result.RelPath, [ref]$entry)) {
                # 諦めたレーンのスレッドが、後回しにしたあとで返した結果。捨てる
                continue
            }
            if ($result.Reroute) {
                # Office を使わずに読めなかった（中身が旧形式・パスワード付き）。Word・PowerPoint のレーンに回し直す
                # （取り込み中のまま。中止を求められていても最後まで取り込む）
                $laneBusy[$entry.Lane] = $laneBusy[$entry.Lane] - 1
                $entry.Lane = getOfficeLane $result.RelPath
                if ($pool.LaneStates[$entry.Lane].Abandoned) {
                    # 回し先が諦めたレーンのときは、渡さずに後回しにする
                    postponeInflightForUser $result.RelPath ${postponedReasonInUse}
                    $postponedCount++
                    $ledger.WriteIngestingFiles((getIngestingEntries $inflight $carried))
                    flushPending
                    continue
                }
                $laneBusy[$entry.Lane] = [int]$laneBusy[$entry.Lane] + 1
                addIngestTask $pool $entry.Lane $entry.Task
                continue
            }
            if ($result.Postponed) {
                # 利用者のPowerPointが起動していて使えなかった。失敗として理由を見せ、取り込み一覧は「未取り込み」のまま残して次回のインデックス作成で取り込む
                # （インデックスは変えない。$ledger.AddRow・$pending.Add はしない）
                [void]$inflight.Remove($result.RelPath)
                $laneBusy[$entry.Lane] = $laneBusy[$entry.Lane] - 1
                $pending.Complete($entry.Folder)
                $postponedCount++
                # 諦めたレーンのスレッドが返した後回しは「使っている方がいた」、始めから起動していたときは「起動していた」
                $postponedReason = if ($pool -and $pool.LaneStates[$entry.Lane].Abandoned) { ${postponedReasonInUse} } else { ${postponedReasonRunning} }
                recordUserPowerPointPostponed $entry.Number $entry.Row $postponedReason
                $ledger.WriteIngestingFiles((getIngestingEntries $inflight $carried))
                $reporter.Progress(${indexingPhaseIngest}, ($successCount + $ledger.Failures.Count), ($total - $successCount - $ledger.Failures.Count), $ledger.Failures.Count, $currentPath)
                flushPending
                continue
            }
            [void]$inflight.Remove($result.RelPath)
            $laneBusy[$entry.Lane] = $laneBusy[$entry.Lane] - 1
            $row = $entry.Row
            writeIndexerLog ("[{0}/{1}] {2}" -f $entry.Number, $total, $result.RelPath)
            foreach ($line in ($result.Log -split "\r?\n")) {
                if ($line) {
                    writeIndexerLog $line
                }
            }
            if ($result.Ok) {
                $pending.Add($result.RelPath, $false)
                # 高速検索: このフォルダの システムインデックスを作り直すまで、検索ではこのフォルダを必ず照合させる
                if (!(markSystemIndexChanged @([System.IO.Path]::GetDirectoryName($result.RelPath)))) {
                    writeIndexerLog "    システムインデックスの状態を書き込めませんでした（インデックス作成の終わりに作り直します）。" "Yellow"
                }
                writeIndexerLog "    TSV $($result.TsvCount) 件を作成しました。"
                $row.状態 = ${stateDone}
                $row.TSV数 = [string]$result.TsvCount
                $row.エラー = ""
                $row.抽出版 = $result.ExtractVersion
                $successCount++
            } else {
                writeIndexerLog "    取り込みに失敗しました: $($result.Message)" "Red"
                $row.状態 = ${stateFailed}
                $row.TSV数 = ""
                $row.エラー = $result.Message
                $row.抽出版 = ""
                $ledger.AddFailure($result.RelPath, $result.Message)
            }

            # 中断しても結果が残るよう、1件ごとに取り込み一覧へ追記する（最後に1ファイル1行にまとめ直す）
            $row.取り込み日時 = formatFileTime (Get-Date)
            $ledger.AddRow($row)
            $ledger.WriteIngestingFiles((getIngestingEntries $inflight $carried))
            $pending.Complete($entry.Folder)
            $reporter.Progress(${indexingPhaseIngest}, ($successCount + $ledger.Failures.Count), ($total - $successCount - $ledger.Failures.Count), $ledger.Failures.Count, $currentPath)

            if (!$pool -and ($result.TimedOut -or (($successCount + $ledger.Failures.Count) % $restartInterval) -eq 0)) {
                # 制限時間を過ぎて強制終了したアプリは使えないため、すべて終了して次に必要になったときに起動し直す
                stopAllApps
            }
            # 取り込みが揃ったフォルダ（取り込み中が無く、まだ渡していないファイルも無い）を、本文インデックスのファイルに書き出す
            flushPending
        }
    } finally {
        # 中止・続けられないエラーの場合もここは実行される。
        # 後片付けも数十秒かかることがあるため、何をしているかを画面に伝える（進み具合の数はそのまま残す）
        # 画面は「成功 = 処理済み - 失敗」と出すため、取り込まなかった（元ファイルが無くなった）分は数に入れない
        $processed = $successCount + $ledger.Failures.Count
        $reporter.Progress(${indexingPhaseFinish}, $processed, 0, $ledger.Failures.Count, "Officeアプリを終了しています…")
        if ($pool) {
            stopIngestWorkers $pool
        } else {
            $script:officeWatchdog.Stop()
            stopAllApps
            waitKeptApps ({ [bool]$channel.Stop }.GetNewClosure())
        }
        $script:officePidSink = $null
        $script:officeRecordDir = $null
        $script:officeOwnDir = $null
        $script:onOfficeHandOver = $null
        removeTmpDir
        $ledger.RemoveIngestingFile()
        # 取り込んだ TSV は、中止したときも残さず本文インデックスのファイルに入れる（残すとインデックスの容量が倍になる）
        $reporter.Progress(${indexingPhaseFinish}, $processed, 0, $ledger.Failures.Count, "インデックスをまとめています…")
        flushPending -All
        $reporter.Progress(${indexingPhaseFinish}, $processed, 0, $ledger.Failures.Count, "更新の記録を書き直しています…")
        # 取り込みの直前に無くなっていたファイルの行は除く（次回の検索でも見つからず、インデックスも削除済み）
        writeStatusKeepingDropped $ledger $folders @($rows | Where-Object { $_ -and !$ledger.DroppedRows.Contains([string]$_.相対パス) }) $keptDropped $previous
        # 初めて取り込んだインデックスは、最初に書き出した時点ではまだフォルダが無いため、ここでもう一度書く
        # （work\content_index\<インデックス名>\source_folder.txt。インデックス 1 個だけをコピーしても元のファイルの場所が分かる）
        writeSourceFolderFile $folders
        # 高速検索用の システムインデックスを作り直す。中止したとき・フォルダが見えなくなったときは作らない
        # （作り直していないフォルダは反映待ちのままのため、検索ではそのフォルダを照合する）
        if (!$stopped -and !$folderLost) {
            $reporter.Progress(${indexingPhaseFinish}, $processed, 0, $ledger.Failures.Count, "システムインデックス（高速検索用）を作っています…")
            try {
                [void](updateSystemIndexes -shouldStop { $channel.Stop })
            } catch {
                writeIndexerLog "システムインデックスを作れませんでした（次のインデックス作成で作り直します）: $($_.Exception.Message)" "Yellow"
            }
        }
        # 画面が終わり方（成功・失敗の件数）を読めるよう、進み具合は消さずに最後の状態を残す
        $reporter.Progress(${indexingPhaseFinish}, $processed, $remaining, $ledger.Failures.Count, "")
    }

    if ($folderLost) {
        # クロール対象フォルダが見えなくなった場合は、続けられないエラーとして画面に知らせる（残りは未取り込みのまま）
        $message = "クロール対象フォルダが見つからなくなったため、インデックス作成を中止しました: ${folderLost}" +
            "（残り ${remaining} 件は取り込まずに残しました。フォルダを使えるようにしてから、もう一度更新してください）"
        writeIndexerLog ""
        writeIndexerLog $message "Red"
        $channel.Error = $message
        return 1
    }

    writeIndexerLog ""
    if ($stopped) {
        writeIndexerLog "インデックス作成を中止しました。（成功: ${successCount} 件 / 失敗: $($ledger.Failures.Count) 件）" "Yellow"
    } else {
        writeIndexerLog "インデックス作成が完了しました。（成功: ${successCount} 件 / 失敗: $($ledger.Failures.Count) 件）" "Green"
    }
    if ($ledger.DroppedRows.Count -gt 0) {
        writeIndexerLog "取り込みの直前に元のファイルが無くなった $($ledger.DroppedRows.Count) 件は、取り込まずに一覧から除きました。" "Yellow"
    }
    writeIndexerLog "各ファイルの状態・更新日時は $(Split-Path $workspace.StatusFile -Leaf) で確認できます。"
    if ($ledger.Failures.Count -gt 0) {
        # インデックス作成中の表示は流れて見えなくなるため、失敗したファイルと原因を最後にまとめて表示する
        writeIndexerLog ""
        writeIndexerLog "＜取り込みに失敗したファイルと原因＞" "Yellow"
        foreach ($failure in @($ledger.Failures | Select-Object -First $failureListLimit)) {
            writeIndexerLog "  $($failure.RelPath)"
            writeIndexerLog "    → $($failure.Message)" "Red"
        }
        if ($ledger.Failures.Count -gt $failureListLimit) {
            writeIndexerLog "  ほか $($ledger.Failures.Count - $failureListLimit) 件（原因は一覧の「エラー」列）"
        }
        writeIndexerLog ""
        if ($ledger.Failures.Count -gt $postponedCount) {
            writeIndexerLog "失敗したファイルは、画面で「失敗分も再取り込みする」を選んで取り込むと再取り込みします。" "Yellow"
        }
        if ($postponedCount -gt 0) {
            # 一覧の状態は「未取り込み」のため、PowerPoint を閉じてからの次の更新で選ばなくても取り込む
            writeIndexerLog "PowerPoint のために取り込めなかった ${postponedCount} 件は、PowerPoint を閉じてからもう一度更新すると、そのまま取り込みます。" "Yellow"
        }
    }

    if ($stopped) {
        return 2
    }
    return 0
}

function getIngestingEntries {
    # 取り込み中のファイルの記録（writeIngestingFiles に渡す形）。取り込み中のものと、最後に回してまだ始めていないもの
    param (
        $inflight,
        $carried
    )

    $entries = New-Object System.Collections.Generic.List[hashtable]
    foreach ($key in $inflight.Keys) {
        $entries.Add(@{ RelPath = $key; Count = $inflight[$key].Count })
    }
    foreach ($key in $carried.Keys) {
        $entries.Add(@{ RelPath = $key; Count = $carried[$key] })
    }
    return , $entries.ToArray()
}


# インデクサ（indexer.ps1）の本体。indexer.ps1 が読み込んで呼ぶ（引数はそのまま転送する）。
# 流れは docs/design/indexing/flow.md、スレッドの分け方は docs/design/structure/threads.md。

function invokeIndexerMain {
    # 画面なしで起動したとき（$Channel が無い）は、壊れた設定ファイルを退避して既定の設定で続ける
    # （知らせは invokeIndexer がログを開いた直後に出す）。画面から -Channel 付きで動くときは、画面が起動時に退避済み
    param (
        [switch]$RetryFailed,
        $Channel = $null
    )

    $script:settingsRecovery = ""
    if ($null -eq $Channel) {
        $script:settingsRecovery = repairBrokenSettings
    }

    $ErrorActionPreference = "Stop"
    initWorkspace

    if ($null -eq $Channel) {
        $Channel = newIndexerChannel -retryFailed ([bool]$RetryFailed) -includeCloud ((readCloudFiles) -eq ${cloudFilesDownload})
        $script:indexerEcho = $true
    }
    # 途中の処理が出力した値が混ざらないよう、最後の値（終了コード）を使う
    return [int]@(invokeIndexer $Channel)[-1]
}

if ($Part -eq "indexer") {





exit (invokeIndexerMain -RetryFailed:$RetryFailed -Channel $Channel)

}
# 画面（WPF）の起動口。
#
# ［インデックス管理］［検索］［設定］の 3 タブ。画面の定義は xaml\tebunko.xaml。
# インデックス作成は indexer.ps1 をウィンドウを出さずに起動して進み具合を表示し、検索は画面内で行う。
#
# このファイルは起動口。画面の中身は ui\gui_main.ps1（startGui）と、そこから読み込む ui\ 配下・..\shared\ui\ 配下に分けてある。
# 起動そのものに失敗したとき（Add-Type・読み込み・画面の組み立てで例外）は、ui\startup_error.ps1 の reportStartupFailure が知らせる。

# 読み込みの行は、相手のパスを [WildcardPattern]::Escape に通す（フォルダ名の [ ] がパターンとして読まれないように）。Escape はバッククォートをエスケープしないので、先に二重にする。
# これは Windows PowerShell 5.1 だけを対象にした書き方（PowerShell 7 以降の Escape はバッククォートも扱うので、二重になる）
# 起動の失敗の記録（startup_error.txt）はツールのフォルダ（${rootDir}）に書く。その前に、どこで失敗しても書けるよう、先にパスの定義だけを読み込む




try {
    Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase, System.Windows.Forms

    # ---- 起動中の表示 ----
    # スクリプトの読み込みに数秒かかるため、先に小さなウィンドウ（xaml\splash.xaml）を出して、起動していることを知らせる。
    # 画面（$window）を描き終わったら閉じる（ContentRendered）。多重起動の判定より前に出すため、2 つ目の起動でも一瞬出る
# 起動中の表示（xaml\splash.xaml）。
# スクリプトの読み込みに数秒かかるため、小さなウィンドウを出して起動していることを知らせる。
# 画面（$window）を描き終わったら closeSplash で閉じる（ContentRendered）。
# 読み込みの間は画面のスレッドが塞がるため、区切りごとに stepSplash で描画と入力の処理を進める（応答なしにしない）。

$script:splash = $null

# XAML の中身を文字列で返す。
# shared/ui/app_host.ps1（getXamlText）はこの時点でまだ読み込んでいない（早く出すため）ので、
# 単一 .ps1 かどうかの見分け方（${bundledXaml}）だけをここでも行う
function getSplashXamlText {
    param (
        [string]$path
    )

    $bundled = Get-Variable -Name bundledXaml -ErrorAction SilentlyContinue
    # shared/ui/app_host.ps1 の getXamlText と同じく GetFullPath で正規化してから探す（鍵の決め方をそろえる）
    $fullPath = [System.IO.Path]::GetFullPath($path)
    if ($null -ne $bundled -and $bundled.Value -and $bundled.Value.ContainsKey($fullPath)) {
        return $bundled.Value[$fullPath]
    }
    return [System.IO.File]::ReadAllText($path, (New-Object System.Text.UTF8Encoding($true)))
}

# 出せなくても起動は続ける（$null を返す）。
# iconXamlPath は、アイコン（ベクターの絵。xaml\app_icon.xaml）の XAML
function showSplash {
    param (
        [string]$path,
        [string]$iconXamlPath = ""
    )

    try {
        $text = getSplashXamlText $path
        # 配列は ,（単項）で 1 つの引数として渡す。付けないと New-Object が要素ごとの引数に展開して失敗し、下の catch で黙って握りつぶされる
        $stream = New-Object System.IO.MemoryStream -ArgumentList (,[System.Text.Encoding]::UTF8.GetBytes($text))
        try {
            $script:splash = [System.Windows.Markup.XamlReader]::Load($stream)
        } finally {
            $stream.Dispose()
        }
        setSplashIcon $script:splash $iconXamlPath
        $script:splash.Show()
    } catch {
        $script:splash = $null
    }
    return $script:splash
}

# アイコンは飾りなので、読めなくても何もしない
function setSplashIcon {
    param (
        $window,
        [string]$iconXamlPath
    )

    if (-not $iconXamlPath) {
        return
    }
    try {
        $stream = New-Object System.IO.MemoryStream -ArgumentList (,[System.Text.Encoding]::UTF8.GetBytes((getSplashXamlText $iconXamlPath)))
        try {
            $icon = [System.Windows.Markup.XamlReader]::Load($stream)
        } finally {
            $stream.Dispose()
        }
        $window.FindName("SplashIcon").Source = $icon
    } catch {
        $null = $_
    }
}

function stepSplash {
    param (
        [int]$percent
    )

    if ($null -eq $script:splash) {
        return
    }
    $script:splash.FindName("SplashProgress").Value = $percent
    # 自分のスレッドの Dispatcher に優先度 Background の空の仕事を渡し、それより優先度の高い描画・入力を先に処理させる
    $script:splash.Dispatcher.Invoke([action]{ }, [System.Windows.Threading.DispatcherPriority]::Background)
}

function closeSplash {
    if ($null -ne $script:splash) {
        $script:splash.Close()
        $script:splash = $null
    }
}

    $script:splash = showSplash "${tebunkoRoot}\xaml\splash.xaml" "${tebunkoRoot}\xaml\app_icon.xaml"
    stepSplash 5

    # zip 展開で付く Mark-of-the-Web（外部由来の印）を、scripts 配下から消す。印が残っていると
    # RemoteSigned でスクリプトの読み込みがブロックされるため。通常は tebunko.bat が起動前に消すが、
    # ショートカットから直接起動したときや、あとでファイルを差し替えたときのために、ここでも消しておく。
    # （この gui.ps1 自身が印付きだと、この行に来る前にブロックされる。その場合は tebunko.bat から起動する）
    # 単一 .ps1 版（${bundledScriptPath} あり）ではしない。動き始めた後に自分の印を消しても起動には効かず、
    # EDR からは防御の回避に見えるため
    if ($null -eq (Get-Variable -Name bundledScriptPath -ErrorAction SilentlyContinue)) {
        try {
            Get-ChildItem -LiteralPath (Split-Path ${tebunkoRoot} -Parent) -Recurse -File -ErrorAction SilentlyContinue | Unblock-File -ErrorAction SilentlyContinue
        } catch { }
    }




    stepSplash 40

# 画面で使う型のうち、どのツールからも使うもの。
# 継承元になるため、ほかの型より先に読み込む。

# ---- 画面で使う型（PowerShell class。実行時コンパイル（csc.exe）を出さないため C# から移した） ----
# INotifyPropertyChanged は NotifyBase を継承して実装する（PS class はプロパティのセッターに
# ロジックを書けないため、値を変える側が Set*/Raise を呼ぶ）。HitRow は件数が多いので生成時は生データだけ持ち、
# 表示用（強調セグメント・セル解析）は画面に見えた行だけ Prepare() で作る（LoadingRow から呼ぶ）。

class NotifyBase : System.ComponentModel.INotifyPropertyChanged {
    hidden [System.ComponentModel.PropertyChangedEventHandler] $handler
    # 既定のコンストラクタを明示する。Windows PowerShell 5.1 では、メソッドを持ち、コンストラクタも初期値付きのフィールドも無いクラスを
    # Set-PSDebug -Trace の最中に作ると ArgumentOutOfRangeException になる（テストのカバレッジの計測がトレースを使う）。
    # 継承するクラスも同じ形なら、それぞれ明示する（tests\meta\classes.Tests.ps1 が確かめる）
    NotifyBase() {}
    [void] add_PropertyChanged([System.ComponentModel.PropertyChangedEventHandler]$h) { $this.handler = [Delegate]::Combine($this.handler, $h) }
    [void] remove_PropertyChanged([System.ComponentModel.PropertyChangedEventHandler]$h) { $this.handler = [Delegate]::Remove($this.handler, $h) }
    [void] Raise([string]$name) { if ($this.handler) { $this.handler.Invoke($this, (New-Object System.ComponentModel.PropertyChangedEventArgs $name)) } }
}

# 確認ダイアログ（showConfirm）に並べる「実行するとこうなります」の 1 行
class ConfirmFact {
    [string]$Mark          # Kept 残る・Gone 消える・Next 続けて起きること・! 注意（画面では Lucide のアイコンにする）
    [object]$MarkBrush
    [string]$Title         # 何がどうなるか（利用者から見える言葉で書く）
    [string]$Detail = ""   # 具体的な場所・件数など（空なら行ごと出さない）
}

# tebunko の画面で使う型: 検索結果とプレビュー。
# shared\ui\types.ps1 を先に読み込んでおくこと（NotifyBase を継承する）。lib.ps1（index_name.ps1）も先に読み込んでおくこと（HitRow.ObjectPlaceRegex の値を作る）。
# Preview* と HitRow は互いを参照するため、同じファイルに置く。

class Segment {
    [string]$Text
    [bool]$IsHit

    Segment() {}

    # 表示する行ごとに作るため、ハッシュテーブルからの変換（[Segment]@{ … }）より速いコンストラクタで作る
    Segment([string]$text, [bool]$isHit) {
        $this.Text = $text
        $this.IsHit = $isHit
    }
}

# 選択行のプレビューの列。見出しと各行のセルが同じものを参照し、幅を変えると列全体に反映する。
# セルは Width に OneWay バインド。幅の変更は SetWidth（見出しのドラッグから呼ぶ）で行う
class PreviewColumn : NotifyBase {
    static [double] $MinWidth = 24   # ドラッグで狭くできる下限
    static [int] $WidthStamp = 0     # どれかの列の幅が SetWidth で変わるたびに増える（PreviewTable.Prefix の作り直しの判断）
    [string]$Label
    [double]$Width
    PreviewColumn() {}   # 既定のコンストラクタを明示する（理由は shared\ui\types.ps1 の NotifyBase）
    [void] SetWidth([double]$value) {
        $newWidth = [Math]::Max([PreviewColumn]::MinWidth, $value)
        if ($this.Width -eq $newWidth) { return }
        $this.Width = $newWidth
        [PreviewColumn]::WidthStamp++
        $this.Raise("Width")
    }
}

# 選択行のプレビューのセル1つ（IsSelected はコピーのために選んだ範囲）
class PreviewCell : NotifyBase {
    [string]$Text        # セルの値そのまま（コピーに使う）
    [string]$Display     # 画面に出す文字列（長すぎるセルは切り詰める）
    [string]$ToolTip
    [PreviewColumn]$Column
    [bool]$IsHit
    [int]$LineNumber     # 元のファイルの場所の中の行の番号（行を前後に足し・捨てても、選んだ範囲がずれない）
    [int]$ColumnIndex
    [bool]$IsSelected
    PreviewCell() {}   # 既定のコンストラクタを明示する（理由は shared\ui\types.ps1 の NotifyBase）
    [void] SetSelected([bool]$value) {
        if ($this.IsSelected -eq $value) { return }
        $this.IsSelected = $value
        $this.Raise("IsSelected")
    }
}

# 選択行のプレビューの、見えている列の範囲（表の全部の行が同じものを持つ）。First・Last は見えている最初と最後の列
# （左右の余白の列を含む。0 から）、LeftSpace・RightSpace はその左右の、作らない列の幅の合計。
# 行の左右の空きの幅がこれに束ねてあり、範囲が変わると、見えている行すべての空きが一度に変わる
class PreviewWindow : NotifyBase {
    [int]$First
    [int]$Last = -1
    [double]$LeftSpace
    [double]$RightSpace
    PreviewWindow() {}   # 既定のコンストラクタを明示する（理由は shared\ui\types.ps1 の NotifyBase）
    [void] SetSpaces([double]$left, [double]$right) {
        if ($this.LeftSpace -ne $left) { $this.LeftSpace = $left; $this.Raise("LeftSpace") }
        if ($this.RightSpace -ne $right) { $this.RightSpace = $right; $this.Raise("RightSpace") }
    }
}

# 選択行のプレビューの1行。「読み込み中…」などを出す行（IsMessage）は、行番号・セルを持たず、選択・コピーの対象にしない。
# 行の全部のセルの値は Texts に持ち、画面に出すセル（Cells）は、見えている列の範囲（Window）の分だけを、見えている行について作る
class PreviewRow : NotifyBase {
    [string]$Number
    [int]$LineNumber     # 元のファイルの場所の中の行の番号（メッセージの行は 0）
    [bool]$IsHitRow
    [bool]$IsMessage
    [string]$Message
    [System.Collections.Generic.List[string]]$Texts   # 行の全部のセルの値（TSV から切り出したまま）
    [PreviewWindow]$Window
    [int]$CellsVersion = -1   # Cells を作ったときの範囲の版（-1 は未作成）
    [System.Collections.Generic.List[PreviewCell]]$Cells = [System.Collections.Generic.List[PreviewCell]]::new()
    PreviewRow() {}   # 既定のコンストラクタを明示する（理由は shared\ui\types.ps1 の NotifyBase）
    [void] SetCells([System.Collections.Generic.List[PreviewCell]]$cells, [int]$version) {
        $this.Cells = $cells
        $this.CellsVersion = $version
        $this.Raise("Cells")
    }
}

# 選択行のプレビュー。HitOffset・HitWidth は選択行で最初に一致したセルの左端と幅（横スクロール用）。
# Rows は前後に足し・捨てられる集まり（行の仮想化で見えている所だけ要素を作る）。読んでいる所の端には、
# 読み込み中・読めなかったことを出すメッセージの行（UpMessage・DownMessage）を置く
class PreviewTable {
    [System.Collections.Generic.List[PreviewColumn]]$Columns
    [System.Collections.ObjectModel.ObservableCollection[PreviewRow]]$Rows
    [double]$HitOffset
    [double]$HitWidth
    [PreviewWindow]$Window = [PreviewWindow]::new()
    [int]$WindowVersion       # 見えている列の範囲が変わるたびに増える（行のセルを作り直すかの判断）
    [HitRow]$Owner            # 行のセルを作る（一致の印に、検索の語を使うため）
    hidden [double[]]$widthSums              # Prefix() が作った累積
    hidden [int]$prefixCount = -1            # 累積を作ったときの列の数
    hidden [int]$prefixStamp = -1            # 累積を作ったときの PreviewColumn.WidthStamp
    hidden [System.Collections.Generic.List[PreviewRow]]$built = [System.Collections.Generic.List[PreviewRow]]::new()   # セルを作ってある行
    [bool]$IsExcel   # Excel の表か（Excel 以外は列が 1 つで、幅を枠いっぱいにする。preview.ps1 の fitPreviewWidth）
    # 読み足し（preview.ps1）の状態。TopDone・BottomDone はその向きにもう行が無い（または読めなかった）こと。
    # Marks は readContentIndexLines の控え（続きを、先頭から読み飛ばさず読むため）
    [bool]$TopDone
    [bool]$BottomDone
    $Marks
    [int]$Request             # この表を作った読み込みの番号（読み足しの結果が、この表のものかを見分ける）
    [PreviewRow]$UpMessage
    [PreviewRow]$DownMessage

    # 行の集まりの中の、メッセージの行を除いた行（本物の行）の数・最初と最後の行の番号（無ければ 0）
    [int] LeadCount() { return $(if ($null -ne $this.UpMessage) { 1 } else { 0 }) }
    [int] DataCount() {
        return $this.Rows.Count - $this.LeadCount() - $(if ($null -ne $this.DownMessage) { 1 } else { 0 })
    }
    [int] FirstLine() {
        if ($this.DataCount() -le 0) { return 0 }
        return $this.Rows[$this.LeadCount()].LineNumber
    }
    [int] LastLine() {
        if ($this.DataCount() -le 0) { return 0 }
        return $this.Rows[$this.LeadCount() + $this.DataCount() - 1].LineNumber
    }

    # side（"up"・"down"）の端にメッセージの行を出す（あれば置き換える）
    [void] ShowMessage([string]$side, [string]$text) {
        $this.HideMessage($side)
        $message = [PreviewRow]::new()
        $message.IsMessage = $true
        $message.Message = $text
        if ($side -eq "up") {
            $this.Rows.Insert(0, $message)
            $this.UpMessage = $message
        } else {
            $this.Rows.Add($message)
            $this.DownMessage = $message
        }
    }

    [void] HideMessage([string]$side) {
        if ($side -eq "up" -and $null -ne $this.UpMessage) {
            [void]$this.Rows.Remove($this.UpMessage)
            $this.UpMessage = $null
        } elseif ($side -eq "down" -and $null -ne $this.DownMessage) {
            [void]$this.Rows.Remove($this.DownMessage)
            $this.DownMessage = $null
        }
    }

    # 読み足した行を、side（"up"・"down"）の端（メッセージの行の内側）に足す。rows は行の番号の順
    [void] InsertRows([string]$side, [System.Collections.Generic.List[PreviewRow]]$rows) {
        if ($side -eq "up") {
            $at = $this.LeadCount()
            foreach ($row in $rows) { $this.Rows.Insert($at++, $row) }
        } else {
            $at = $this.Rows.Count - $(if ($null -ne $this.DownMessage) { 1 } else { 0 })
            foreach ($row in $rows) { $this.Rows.Insert($at++, $row) }
        }
    }

    # 持つ行を減らすために、side（"top"・"bottom"）の端から本物の行を count 行捨てる。
    # 捨てた行を含む範囲を選んでいたら、選択を外す
    [void] TrimRows([string]$side, [int]$count) {
        $count = [Math]::Min($count, $this.DataCount())
        if ($count -le 0) { return }
        $from = $(if ($side -eq "top") { $this.LeadCount() } else { $this.LeadCount() + $this.DataCount() - $count })
        $low = $this.Rows[$from].LineNumber
        $high = $this.Rows[$from + $count - 1].LineNumber
        for ($i = 0; $i -lt $count; $i++) {
            [void]$this.built.Remove($this.Rows[$from])
            $this.Rows.RemoveAt($from)
        }
        if ($this.anchorRow -ge 0) {
            $selectedFrom = [Math]::Min($this.anchorRow, $this.focusRow)
            $selectedTo = [Math]::Max($this.anchorRow, $this.focusRow)
            if ($selectedTo -ge $low -and $selectedFrom -le $high) { $this.ClearSelection() }
        }
    }

    hidden [int]$anchorRow = -1
    hidden [int]$anchorColumn = -1
    hidden [int]$focusRow = -1
    hidden [int]$focusColumn = -1

    [bool] HasSelection() { return $this.anchorRow -ge 0 }

    [void] Select([PreviewCell]$cell, [bool]$extend) {
        if ($null -eq $cell) { return }
        if (-not $extend -or $this.anchorRow -lt 0) {
            $this.anchorRow = $cell.LineNumber
            $this.anchorColumn = $cell.ColumnIndex
        }
        $this.focusRow = $cell.LineNumber
        $this.focusColumn = $cell.ColumnIndex
        $this.ApplySelection()
    }

    [void] SelectRow([PreviewCell]$cell) {
        if ($null -eq $cell) { return }
        $this.SelectLine($cell.LineNumber)
    }

    # 行番号が lineNumber の行を、全部の列を選ぶ
    [void] SelectLine([int]$lineNumber) {
        if ($this.Columns.Count -eq 0) { return }
        $this.anchorRow = $lineNumber
        $this.focusRow = $lineNumber
        $this.anchorColumn = 0
        $this.focusColumn = $this.Columns.Count - 1
        $this.ApplySelection()
    }

    # 選んでいる範囲の、一番上の行の番号（選んでいなければ 0）
    [int] SelectedFirstLine() {
        if ($this.anchorRow -lt 0) { return 0 }
        return [Math]::Min($this.anchorRow, $this.focusRow)
    }

    # 行番号 lineNumber・列 columnIndex のセルが、選んでいる範囲の中か
    [bool] IsInSelection([int]$lineNumber, [int]$columnIndex) {
        return $this.anchorRow -ge 0 -and
            $lineNumber -ge [Math]::Min($this.anchorRow, $this.focusRow) -and $lineNumber -le [Math]::Max($this.anchorRow, $this.focusRow) -and
            $columnIndex -ge [Math]::Min($this.anchorColumn, $this.focusColumn) -and $columnIndex -le [Math]::Max($this.anchorColumn, $this.focusColumn)
    }

    [void] ClearSelection() {
        $this.anchorRow = -1; $this.anchorColumn = -1; $this.focusRow = -1; $this.focusColumn = -1
        $this.ApplySelection()
    }

    # 作ってあるセル（見えている範囲）の選択の印を、選んでいる範囲に合わせる。見えていないセルは、作るときに合わせる
    hidden [void] ApplySelection() {
        foreach ($row in $this.built) {
            foreach ($cell in $row.Cells) {
                $cell.SetSelected($this.IsInSelection($cell.LineNumber, $cell.ColumnIndex))
            }
        }
    }

    # 列の幅の累積（getPreviewColumnWindow に渡す。prefix[i] は先頭から i 列分の幅の合計で、長さは列の数 + 1）。
    # 列が増える・SetWidth で幅が変わるまでは、前に作ったものを使い回す
    [double[]] Prefix() {
        $count = $this.Columns.Count
        if ($this.prefixCount -eq $count -and $this.prefixStamp -eq [PreviewColumn]::WidthStamp) { return $this.widthSums }
        $sums = New-Object 'double[]' ($count + 1)
        $total = 0.0
        for ($i = 0; $i -lt $count; $i++) {
            $total += $this.Columns[$i].Width
            $sums[$i + 1] = $total
        }
        $this.widthSums = $sums
        $this.prefixCount = $count
        $this.prefixStamp = [PreviewColumn]::WidthStamp
        return $sums
    }

    # 見えている列の範囲（first～last）と、その左右の空きの幅を決める。範囲が変わったら、作ってあるセルは古い範囲のものなので捨てる
    # （EnsureCells が、見えている行について今の範囲で作り直す）。範囲が変わったら $true
    [bool] SetWindow([int]$first, [int]$last, [double]$left, [double]$right) {
        $this.Window.SetSpaces($left, $right)
        if ($first -eq $this.Window.First -and $last -eq $this.Window.Last) { return $false }
        $this.Window.First = $first
        $this.Window.Last = $last
        $this.WindowVersion++
        foreach ($row in $this.built) { $row.SetCells([System.Collections.Generic.List[PreviewCell]]::new(), -1) }
        $this.built.Clear()
        return $true
    }

    # 見えている列の範囲の列（列見出しに出す）
    [PreviewColumn[]] WindowColumns() {
        $last = [Math]::Min($this.Window.Last, $this.Columns.Count - 1)
        if ($last -lt $this.Window.First) { return @() }
        return $this.Columns.GetRange($this.Window.First, $last - $this.Window.First + 1).ToArray()
    }

    # 行の集まりの中の firstIndex～lastIndex の行（メッセージの行を除く）に、今の範囲のセルが無ければ作る。
    # 範囲の外の行のセルは捨てる（作ったセルの数が、見えている範囲の分に収まるように）
    [void] EnsureCells([int]$firstIndex, [int]$lastIndex) {
        $lead = $this.LeadCount()
        $firstIndex = [Math]::Max($lead, $firstIndex)
        $lastIndex = [Math]::Min($lead + $this.DataCount() - 1, $lastIndex)
        if ($lastIndex -lt $firstIndex) { return }
        $low = $this.Rows[$firstIndex].LineNumber
        $high = $this.Rows[$lastIndex].LineNumber
        for ($i = $this.built.Count - 1; $i -ge 0; $i--) {
            $row = $this.built[$i]
            if ($row.LineNumber -lt $low -or $row.LineNumber -gt $high) {
                $row.SetCells([System.Collections.Generic.List[PreviewCell]]::new(), -1)
                $this.built.RemoveAt($i)
            }
        }
        for ($i = $firstIndex; $i -le $lastIndex; $i++) {
            $row = $this.Rows[$i]
            if ($row.CellsVersion -eq $this.WindowVersion) { continue }
            $this.Owner.BuildCells($this, $row)
            $this.built.Add($row)
        }
    }

    [string] GetSelectionText() {
        if ($this.anchorRow -lt 0) { return "" }
        $rowFrom = [Math]::Min($this.anchorRow, $this.focusRow); $rowTo = [Math]::Max($this.anchorRow, $this.focusRow)
        $columnFrom = [Math]::Min($this.anchorColumn, $this.focusColumn); $columnTo = [Math]::Max($this.anchorColumn, $this.focusColumn)
        if ($rowFrom -eq $rowTo -and $columnFrom -eq $columnTo) {
            return $this.CellText($rowFrom, $columnFrom)
        }
        $text = [System.Text.StringBuilder]::new()
        $first = $true
        foreach ($row in $this.Rows) {
            if ($row.IsMessage -or $row.LineNumber -lt $rowFrom -or $row.LineNumber -gt $rowTo) { continue }
            if (!$first) { [void]$text.Append("`r`n") }
            $first = $false
            for ($c = $columnFrom; $c -le $columnTo; $c++) {
                if ($c -gt $columnFrom) { [void]$text.Append("`t") }
                $cellText = $(if ($c -lt $row.Texts.Count) { $row.Texts[$c].Replace([HitRow]::CellNewLine, "`n") } else { "" })
                [void]$text.Append([PreviewTable]::QuoteForExcel($cellText))
            }
        }
        return $text.ToString()
    }

    [int] SelectedCount() {
        if ($this.anchorRow -lt 0) { return 0 }
        return ([Math]::Abs($this.anchorRow - $this.focusRow) + 1) * ([Math]::Abs($this.anchorColumn - $this.focusColumn) + 1)
    }

    hidden [string] CellText([int]$lineNumber, [int]$columnIndex) {
        foreach ($row in $this.Rows) {
            if ($row.IsMessage -or $row.LineNumber -ne $lineNumber) { continue }
            if ($columnIndex -ge 0 -and $columnIndex -lt $row.Texts.Count) { return $row.Texts[$columnIndex].Replace([HitRow]::CellNewLine, "`n") }
            return ""
        }
        return ""
    }

    static [string] QuoteForExcel([string]$text) {
        if ($text.IndexOf("`n") -lt 0 -and $text.IndexOf("`t") -lt 0 -and $text.IndexOf('"') -lt 0) { return $text }
        return '"' + $text.Replace('"', '""') + '"'
    }
}

# 検索結果の、元のファイル 1 つ分（結果の表の見出しの行）。検索のヒットは生のまま Hits に持ち、表の行（HitRow）は
# 開いたとき・絞り込み・並べ替え・出力のときに初めて作って Rows に入れる。開いているときだけ、見出しの下に表の行として並べる（result_list.ps1）。
# 文言（AppKind・LocationText）は画面側で判断層（search\result_list_view.ps1）の関数から作って入れる
class FileGroup : NotifyBase {
    [bool]$IsFileHeader = $true   # 結果の表で見出しの形にする（search/result_list.xaml の FileHeaderRow）
    [int]$Order                   # 見つかった順（並べ替えで同じ値のときの順）
    [string]$Book
    [string]$RelDir
    [string]$FullPath
    [string]$AppKind        # Excel / Word / PowerPoint（アイコンの色と文字を決める。どれでもなければ空）
    [string]$LocationText   # ヒットした場所の要約（「[シート]4月 ほか 2 か所」。読み上げに使う）
    [string]$LocationPrefix # 見出しの右端の件数の前に付ける場所（「[シート]4月 ほか 2 か所 ・ 」）。場所が 1 か所だけのときは空（行の「場所」列と重なるため）
    [bool]$IsExpanded       # 見出しの下にヒットした行を並べるか（検索した直後は閉じている）
    [int]$ShownCount        # 見出しに出す件数（絞り込みに合うヒットの数）
    # 検索のヒット（searchContentIndex の結果そのまま。見つかった順）
    [System.Collections.Generic.List[object]]$Hits = [System.Collections.Generic.List[object]]::new()
    # 作った表の行（Hits の先頭から順に作る。並べ替えたらその順）と、そのうち絞り込みに合う行
    [System.Collections.Generic.List[object]]$Rows = [System.Collections.Generic.List[object]]::new()
    [System.Collections.Generic.List[object]]$ShownRows = [System.Collections.Generic.List[object]]::new()
    # 結果の表での状態（result_list.ps1 が使う）。InView は見出しを表に入れたか、DisplayedCount は見出しの下に入れた行の数
    [bool]$InView
    [int]$DisplayedCount
    hidden [System.Collections.Generic.HashSet[string]]$locations = [System.Collections.Generic.HashSet[string]]::new()
    hidden [System.Collections.Generic.List[string]]$labels = [System.Collections.Generic.List[string]]::new()

    # ヒットした場所（結果の「場所」そのまま）を記録する。初めての場所なら $true
    # （呼び出し側が表記を AddLabel で足し、LocationText を作り直す。ヒットごとに表記を作らないため）
    [bool] AddLocation([string]$location) {
        return $this.locations.Add($location)
    }

    # 場所の表記を足す（図形・コメントは元の場所と同じ表記になるため、同じ表記は 1 つにする）。足したら $true
    [bool] AddLabel([string]$label) {
        if ($this.labels.Contains($label)) { return $false }
        $this.labels.Add($label)
        return $true
    }

    [string[]] GetLocations() {
        return $this.labels.ToArray()
    }

    [void] SetLocationText([string]$text) {
        $this.LocationText = $text
        $this.Raise("LocationText")
    }

    [void] SetLocationText([string]$text, [string]$prefix) {
        $this.LocationPrefix = $prefix
        $this.Raise("LocationPrefix")
        $this.SetLocationText($text)
    }

    [void] SetExpanded([bool]$value) {
        if ($this.IsExpanded -eq $value) { return }
        $this.IsExpanded = $value
        $this.Raise("IsExpanded")
    }

    [void] SetCount([int]$count) {
        if ($this.ShownCount -eq $count) { return }
        $this.ShownCount = $count
        $this.Raise("ShownCount")
    }
}

# 検索結果の1行。生成時は生データのみ。表示用（DisplayLine・Segments・MatchCell・MatchCount）は Prepare() で作る（可視行だけ）。
# 表示用の各項目は Prepare() 後に PropertyChanged を出す（LoadingRow より前にバインドされても更新されるように）
class HitRow : NotifyBase {
    static [regex] $CellRegex  = [regex]::new("\t(?:`"(?:[^`"]|`"`")*`"[^\t]*|[^\t]*)")
    static [regex] $QuoteRegex = [regex]::new("^`"((?:[^`"]|`"`")*)`"(.*)`$", [System.Text.RegularExpressions.RegexOptions]::Singleline)
    static [regex] $ExcelRegex = [regex]::new("\.xls[a-z]?`$", [System.Text.RegularExpressions.RegexOptions]::IgnoreCase)
    # 図形・コメントの場所 "<元の場所>[<種類>]"。クラスからはスクリプトの関数が見えないため、値はクラスの定義の後で入れる（newObjectPlaceKindPattern）。
    # Excel の図形・コメントの 1 行は "<セル番地><TAB><文字>"。ヘッダー・フッターの 1 行は文字だけ（セル番地が無い）
    static [regex] $ObjectPlaceRegex
    static [regex] $CelllessPlaceRegex = [regex]::new("\[ヘッダー・フッター\]`$")
    static [char] $CellNewLine = [char]0x2028   # TSV のセル内改行（shared\core\text.ps1 の cellNewLine）
    static [int] $LeadLength = 40
    static [int] $MaxDisplay = 600
    static [double] $NumberWidth = 44
    static [double] $MinCellWidth = 48
    static [double] $MaxCellWidth = 260
    static [double] $MaxParagraphWidth = 640
    static [int] $WidthSampleRows = 10   # 列の幅を決めるために、選択行の前後何行のセルを測るか
    static [int] $MaxCellChars = 300
    static [int] $MaxToolTipChars = 1000
    static [int] $MaxWidthChars = 100

    [string]$IndexName
    [string]$Root
    [string]$RelPath
    [string]$RelDir
    [string]$FileName
    [string]$Book
    [string]$Location
    [string]$PlaceText    # 場所ごとの表記（describePlace。例: [シート]売上）。生成した側が入れる
    [string]$PlaceDisplay # 表の「場所」の列の表記（describeHitPlace。例: [シート]売上!B12）。画面に出るとき SetPlaceDisplay で入れる
    [string]$Kind         # 画面の「種別」（セル・図形・コメント・本文・ノート）
    [int]$LineNumber
    [string]$Line
    [bool]$IsExcel
    [bool]$IsText          # テキストの拡張子（.txt 等）の行か（describeHitPlace・open_source.ps1 が使う。呼び出し側が入れる）
    [bool]$IsObjectPlace
    [bool]$IsCelllessPlace  # 行にセル番地が無い場所（ヘッダー・フッター）か（$IsObjectPlace の一種）
    [string]$MatchCell
    [int]$MatchCount        # 1 行のうち一致したセルの数（Excel のセルの行だけ。図形・コメントは 0 か 1）
    [string]$DisplayLine
    [System.Collections.Generic.List[Segment]]$Segments
    [bool]$Prepared
    [bool]$IsFileHeader     # 常に $false（結果の表で、見出しの行と区別する）
    [int]$Order             # そのファイルの中で見つかった順（並べ替えで同じ値のときの順）
    [FileGroup]$FileGroup   # 元のファイルの見出し（同じファイルの行で共有する）

    hidden [string]$word
    hidden [regex]$pattern

    HitRow() {}   # 既定のコンストラクタを明示する（理由は shared\ui\types.ps1 の NotifyBase）

    # 生成（検索ヒットごと。生データの代入のみ＝軽い）
    static [HitRow] Create([string]$indexName, [string]$root, [string]$relPath, [string]$relDir, [string]$fileName,
                           [string]$book, [string]$location, [int]$lineNumber, [string]$line, [string]$word, [regex]$pattern) {
        $row = [HitRow]::new()
        $row.IndexName = $indexName
        $row.Root = $root
        $row.RelPath = $relPath
        $row.RelDir = $(if ($null -eq $relDir) { "" } else { $relDir })
        $row.FileName = $fileName
        $row.Book = $book
        $row.Location = $location
        $row.LineNumber = $lineNumber
        $row.Line = $(if ($null -eq $line) { "" } else { $line })
        $row.word = $word
        $row.pattern = $pattern
        $row.IsExcel = [HitRow]::ExcelRegex.IsMatch($(if ($null -eq $book) { "" } else { $book }))
        $row.IsObjectPlace = [HitRow]::ObjectPlaceRegex.IsMatch($(if ($null -eq $location) { "" } else { $location }))
        $row.IsCelllessPlace = [HitRow]::CelllessPlaceRegex.IsMatch($(if ($null -eq $location) { "" } else { $location }))
        return $row
    }

    # 表示用（強調セグメント・DisplayLine・セル番地・一致したセルの数）を作る。可視行になったときに1回だけ呼ぶ（LoadingRow）
    [void] Prepare() {
        if ($this.Prepared) { return }
        $this.Prepared = $true
        $text = $this.ShownText()
        $this.DisplayLine = [HitRow]::ToDisplay($text)
        $this.Segments = $this.BuildSegments($text)
        $this.SetMatchCell()
        $this.Raise("DisplayLine"); $this.Raise("Segments"); $this.Raise("MatchCell"); $this.Raise("MatchCount")
    }

    hidden [void] SetMatchCell() {
        $this.MatchCell = ""
        $this.MatchCount = 0
        if (-not $this.IsExcel) { return }
        $cells = [HitRow]::SplitCells($this.Line, $true)
        if ($this.IsObjectPlace) {
            # Excel の図形・コメントの行は、先頭のセルが図形の左上・コメントのセルの番地
            $hit = $false
            foreach ($cell in $cells) { if ([HitRow]::HasMatch($cell, $this.word, $this.pattern)) { $hit = $true; break } }
            # ヘッダー・フッターの行は文字だけでセル番地が無い（MatchCell は空のまま。場所は [シート]<名前> になる）
            if ($hit -and $cells.Count -gt 0 -and -not $this.IsCelllessPlace) { $this.MatchCell = $cells[0] }
            $this.MatchCount = $(if ($hit) { 1 } else { 0 })
            return
        }
        $count = 0
        for ($i = 0; $i -lt $cells.Count; $i++) {
            if (-not [HitRow]::HasMatch($cells[$i], $this.word, $this.pattern)) { continue }
            if ($count -eq 0) { $this.MatchCell = [HitRow]::ColumnName($i + 1) + $this.LineNumber }
            $count++
        }
        $this.MatchCount = $count
    }

    # 表の「場所」の列に出す文字を入れる（describeHitPlace の結果）。画面に出るとき 1 回入れる
    [void] SetPlaceDisplay([string]$value) {
        if ($this.PlaceDisplay -eq $value) { return }
        $this.PlaceDisplay = $value
        $this.Raise("PlaceDisplay")
    }

    # 絞り込み。生データ（相対フォルダ・元ファイル名・場所・種別・生の行）での部分一致。行番号は列に出さないため対象にしない（大文字小文字を区別しない）。
    # ※以前は表示用（セル番地・タブ表示）も対象にしていたが、遅延生成のため生データのみを対象にした。
    [bool] Contains([string]$text) {
        $ci = [System.StringComparison]::CurrentCultureIgnoreCase
        if ($this.RelDir.IndexOf($text, $ci) -ge 0) { return $true }
        if (("" + $this.Book).IndexOf($text, $ci) -ge 0) { return $true }
        if (("" + $this.Location).IndexOf($text, $ci) -ge 0) { return $true }
        if (("" + $this.PlaceText).IndexOf($text, $ci) -ge 0) { return $true }
        if (("" + $this.Kind).IndexOf($text, $ci) -ge 0) { return $true }
        if ($this.Line.IndexOf($text, $ci) -ge 0) { return $true }
        return $false
    }

    static [string] ToDisplay([string]$text) {
        if ($null -eq $text) { return "" }
        return $text.Replace("`t", " │ ").Replace([HitRow]::CellNewLine, [char]0x21b5)
    }

    # FindMatches が 1 件以上返すか（一致の一覧を作らずに調べる。表示する行ごとにセルの数だけ呼ぶため）
    static [bool] HasMatch([string]$text, [string]$word, [regex]$pattern) {
        if ([string]::IsNullOrEmpty($text)) { return $false }
        if ($null -ne $pattern) {
            $m = $pattern.Match($text)
            while ($m.Success) {
                if ($m.Length -gt 0) { return $true }
                $m = $m.NextMatch()
            }
            return $false
        }
        if ([string]::IsNullOrEmpty($word)) { return $false }
        return $text.IndexOf($word, [System.StringComparison]::CurrentCultureIgnoreCase) -ge 0
    }

    static [System.Collections.Generic.List[int[]]] FindMatches([string]$text, [string]$word, [regex]$pattern) {
        $list = [System.Collections.Generic.List[int[]]]::new()
        if ([string]::IsNullOrEmpty($text)) { return $list }
        if ($null -ne $pattern) {
            foreach ($m in $pattern.Matches($text)) { if ($m.Length -gt 0) { $list.Add(@($m.Index, $m.Length)) } }
        } elseif (-not [string]::IsNullOrEmpty($word)) {
            $i = 0
            while ($i -lt $text.Length) {
                $i = $text.IndexOf($word, $i, [System.StringComparison]::CurrentCultureIgnoreCase)
                if ($i -lt 0) { break }
                $list.Add(@($i, $word.Length)); $i += [Math]::Max(1, $word.Length)
            }
        }
        return $list
    }

    # 「該当行」列に出す文字。Excel の図形・コメントの行は、先頭のセル番地を「場所」列に出すため除き、
    # 囲みの " を外した文字にする（"納期は<改行>別途" → 納期は<改行>別途）。ほかは TSV の行のまま
    hidden [string] ShownText() {
        if (-not ($this.IsExcel -and $this.IsObjectPlace)) { return $this.Line }
        $cells = [HitRow]::SplitCells($this.Line, $true)
        if ($this.IsCelllessPlace) { return ($cells -join "`t") }
        if ($cells.Count -lt 2) { return $this.Line }
        return ($cells.GetRange(1, $cells.Count - 1) -join "`t")
    }

    hidden [System.Collections.Generic.List[Segment]] BuildSegments([string]$line) {
        $segs = [System.Collections.Generic.List[Segment]]::new()
        $pos = 0; $shown = 0
        foreach ($m in [HitRow]::FindMatches($line, $this.word, $this.pattern)) {
            if ($m[0] -lt $pos) { continue }
            if ($m[0] + $m[1] -gt $line.Length) { break }
            $before = $line.Substring($pos, $m[0] - $pos)
            if ($segs.Count -eq 0 -and $before.Length -gt [HitRow]::LeadLength) {
                $before = [char]0x2026 + $before.Substring($before.Length - [HitRow]::LeadLength)
            }
            if ($before.Length -gt 0) { $segs.Add([Segment]::new([HitRow]::ToDisplay($before), $false)) }
            $segs.Add([Segment]::new([HitRow]::ToDisplay($line.Substring($m[0], $m[1])), $true))
            $shown += $before.Length + $m[1]
            $pos = $m[0] + $m[1]
            if ($shown -gt [HitRow]::MaxDisplay) { break }
        }
        if ($pos -lt $line.Length) {
            $rest = $line.Substring($pos)
            if ($rest.Length -gt [HitRow]::MaxDisplay) { $rest = $rest.Substring(0, [HitRow]::MaxDisplay) + [char]0x2026 }
            $segs.Add([Segment]::new([HitRow]::ToDisplay($rest), $false))
        }
        return $segs
    }

    static [System.Collections.Generic.List[string]] SplitCells([string]$line, [bool]$isExcel) {
        $cells = [System.Collections.Generic.List[string]]::new()
        $src = $(if ($null -eq $line) { "" } else { $line })
        if (-not $isExcel) { $cells.AddRange($src.Split([char]9)); return $cells }
        foreach ($m in [HitRow]::CellRegex.Matches("`t" + $src)) {
            $cell = $m.Value.Substring(1)
            $q = [HitRow]::QuoteRegex.Match($cell)
            if ($q.Success) { $cell = $q.Groups[1].Value.Replace('""', '"') + $q.Groups[2].Value }
            $cells.Add($cell)
        }
        return $cells
    }

    # 選択行のプレビュー（前後の行をセルに分けた表）を作る。numbers・lines は readContentIndexLines の結果。
    # 列は全部の列を持つ。画面に出すセルは作らない（見えている範囲を SetWindow で決め、EnsureCells で作る）。
    # 列の幅は、列見出しの文字と、選択行の前後 WidthSampleRows 行のセルから決める（全部の行・列は測らない）
    [PreviewTable] BuildPreview([int[]]$numbers, [string[]]$lines) {
        if ($null -eq $numbers -or $null -eq $lines -or $numbers.Length -eq 0 -or $numbers.Length -ne $lines.Length) {
            $numbers = @($this.LineNumber)
            $lines = @($this.Line)
        }
        $rowTexts = [System.Collections.Generic.List[System.Collections.Generic.List[string]]]::new()
        $columnCount = 0
        foreach ($ln in $lines) {
            $cells = [HitRow]::SplitCells($ln, $this.IsExcel)
            $rowTexts.Add($cells)
            $columnCount = [Math]::Max($columnCount, $cells.Count)
        }

        $hitColumn = -1
        for ($r = 0; $r -lt $rowTexts.Count -and $hitColumn -lt 0; $r++) {
            if ($numbers[$r] -ne $this.LineNumber) { continue }
            for ($c = 0; $c -lt $rowTexts[$r].Count; $c++) {
                if ([HitRow]::HasMatch($rowTexts[$r][$c], $this.word, $this.pattern)) { $hitColumn = $c; break }
            }
        }

        $table = [PreviewTable]::new()
        $table.Owner = $this
        $table.Columns = [System.Collections.Generic.List[PreviewColumn]]::new()
        $table.Rows = [System.Collections.ObjectModel.ObservableCollection[PreviewRow]]::new()
        $table.HitOffset = 0
        $table.HitWidth = 0
        $table.IsExcel = $this.IsExcel
        $sample = [System.Collections.Generic.List[System.Collections.Generic.List[string]]]::new()
        for ($r = 0; $r -lt $rowTexts.Count; $r++) {
            if ([Math]::Abs($numbers[$r] - $this.LineNumber) -le [HitRow]::WidthSampleRows) { $sample.Add($rowTexts[$r]) }
        }
        $this.AddColumns($table, $columnCount, $sample)

        foreach ($row in $this.MakeRows($table, $numbers, $rowTexts)) { $table.Rows.Add($row) }
        if ($hitColumn -ge 0) {
            $left = [HitRow]::NumberWidth
            for ($c = 0; $c -lt $hitColumn; $c++) { $left += $table.Columns[$c].Width }
            $table.HitOffset = $left
            $table.HitWidth = $table.Columns[$hitColumn].Width
        }
        $table.TopDone = ($numbers.Length -gt 0 -and $numbers[0] -le 1)
        # 見えている範囲が決まるまでは、行の右の空きに全部の列の幅を入れておく（横にスクロールできる広さにする）
        $total = 0.0
        foreach ($column in $table.Columns) { $total += $column.Width }
        $table.Window.SetSpaces(0, $total)
        return $table
    }

    # 読み足した行（numbers・lines は readContentIndexLines の結果）から、表の行を作る。
    # それまでより多い列がある行は、列を右に足す（足した列の幅は、この行のセルから決める。前からある列の幅は変えない）
    [System.Collections.Generic.List[PreviewRow]] BuildPreviewRows([PreviewTable]$table, [int[]]$numbers, [string[]]$lines) {
        $rowTexts = [System.Collections.Generic.List[System.Collections.Generic.List[string]]]::new()
        $columnCount = 0
        foreach ($ln in $lines) {
            $cells = [HitRow]::SplitCells($ln, $this.IsExcel)
            $rowTexts.Add($cells)
            $columnCount = [Math]::Max($columnCount, $cells.Count)
        }
        if ($columnCount -gt $table.Columns.Count) {
            $sample = [System.Collections.Generic.List[System.Collections.Generic.List[string]]]::new()
            for ($r = 0; $r -lt $rowTexts.Count -and $sample.Count -lt 2 * [HitRow]::WidthSampleRows; $r++) { $sample.Add($rowTexts[$r]) }
            $this.AddColumns($table, $columnCount, $sample)
        }
        return $this.MakeRows($table, $numbers, $rowTexts)
    }

    # table の列を columnCount 列まで増やす。足す列の幅は、列見出しの文字と sample の行のセルから決める
    hidden [void] AddColumns([PreviewTable]$table, [int]$columnCount, $sample) {
        $maxWidth = $(if ($this.IsExcel) { [HitRow]::MaxCellWidth } else { [HitRow]::MaxParagraphWidth })
        for ($c = $table.Columns.Count; $c -lt $columnCount; $c++) {
            $width = [HitRow]::TextWidth($this.ColumnLabel($c + 1))
            foreach ($cells in $sample) {
                if ($c -lt $cells.Count) { $width = [Math]::Max($width, [HitRow]::CellWidth($cells[$c])) }
            }
            $col = [PreviewColumn]::new()
            $col.Label = $this.ColumnLabel($c + 1)
            $col.Width = [Math]::Min($maxWidth, [Math]::Max([HitRow]::MinCellWidth, $width))
            $table.Columns.Add($col)
        }
    }

    hidden [System.Collections.Generic.List[PreviewRow]] MakeRows([PreviewTable]$table, [int[]]$numbers, $rowTexts) {
        $rows = [System.Collections.Generic.List[PreviewRow]]::new()
        for ($r = 0; $r -lt $rowTexts.Count; $r++) {
            $row = [PreviewRow]::new()
            $row.Number = $numbers[$r].ToString()
            $row.LineNumber = $numbers[$r]
            $row.IsHitRow = $numbers[$r] -eq $this.LineNumber
            $row.Texts = $rowTexts[$r]
            $row.Window = $table.Window
            $rows.Add($row)
        }
        return $rows
    }

    # 行 row の、見えている列の範囲（table.Window）のセルを作って、行に入れる（PreviewTable.EnsureCells から呼ぶ）
    [void] BuildCells([PreviewTable]$table, [PreviewRow]$row) {
        $cells = [System.Collections.Generic.List[PreviewCell]]::new()
        $last = [Math]::Min($table.Window.Last, $table.Columns.Count - 1)
        for ($c = $table.Window.First; $c -le $last; $c++) {
            $raw = $(if ($c -lt $row.Texts.Count) { $row.Texts[$c] } else { "" })
            $text = $raw.Replace([HitRow]::CellNewLine, "`n")
            $pc = [PreviewCell]::new()
            $pc.Text = $text
            $pc.Display = [HitRow]::Shorten($text, [HitRow]::MaxCellChars)
            $pc.ToolTip = $(if ($text.Length -gt 0) { [HitRow]::Shorten($text, [HitRow]::MaxToolTipChars) } else { $null })
            $pc.Column = $table.Columns[$c]
            $pc.IsHit = [HitRow]::HasMatch($raw, $this.word, $this.pattern)
            $pc.LineNumber = $row.LineNumber
            $pc.ColumnIndex = $c
            $pc.IsSelected = $table.IsInSelection($row.LineNumber, $c)
            $cells.Add($pc)
        }
        $row.SetCells($cells, $table.WindowVersion)
    }

    static [double] CellWidth([string]$cell) {
        if ([string]::IsNullOrEmpty($cell)) { return [HitRow]::TextWidth("") }
        $width = 0.0
        foreach ($line in $(if ($null -eq $cell) { "" } else { $cell }).Split(@([HitRow]::CellNewLine, "`n"))) {
            $seg = $(if ($line.Length -gt [HitRow]::MaxWidthChars) { $line.Substring(0, [HitRow]::MaxWidthChars) } else { $line })
            $width = [Math]::Max($width, [HitRow]::TextWidth($seg))
            if ($width -ge [HitRow]::MaxParagraphWidth) { break }
        }
        return $width
    }

    static [string] Shorten([string]$text, [int]$max) {
        if ($null -eq $text -or $text.Length -le $max) { return $text }
        return $text.Substring(0, $max) + [char]0x2026
    }

    hidden [string] ColumnLabel([int]$number) {
        if ($this.IsExcel -and $this.IsCelllessPlace -and $number -eq 1) { return "文字" }
        if ($this.IsExcel -and $this.IsObjectPlace) {
            return $(switch ($number) { 1 { "セル" } 2 { "文字" } default { $number.ToString() } })
        }
        return $(if ($this.IsExcel) { [HitRow]::ColumnName($number) } else { $number.ToString() })
    }

    static [double] TextWidth([string]$text) {
        $width = 14.0
        foreach ($ch in $(if ($null -eq $text) { "" } else { $text }).ToCharArray()) {
            $code = [int]$ch
            $width += $(if ($code -lt 0x0100 -or ($code -ge 0xFF61 -and $code -le 0xFF9F)) { 7 } else { 12 })
        }
        return $width
    }

    static [string] ColumnName([int]$number) {
        $name = ""
        while ($number -gt 0) {
            $number--
            $name = [char]([int][char]'A' + $number % 26) + $name
            $number = [int][Math]::Floor($number / 26)   # [int] だけでは四捨五入になる（26 → "AZ"）
        }
        return $name
    }
}

# index_name.ps1 の newObjectPlaceKindPattern を使うため、lib.ps1 を先に読み込んでおくこと
[HitRow]::ObjectPlaceRegex = [regex]::new((newObjectPlaceKindPattern))

# tebunko の画面で使う型: 検索対象とそのツリー。
# shared\ui\types.ps1 を先に読み込んでおくこと（NotifyBase を継承する）。

# 検索対象の1件（tebunko\search\content_index_search.ps1 の getContentIndexFiles に渡す）
class SearchTarget {
    [string]$Root
    [string]$RelPath
    [bool]$Recurse
}

# 検索対象から外したフォルダ（tebunko\core\settings.ps1 の readSearchExcludes / writeSearchExcludes と同じ項目）
class SearchExclude {
    [string]$Path
    [bool]$Subfolders
}

# 検索対象インデックスのツリーの1項目。3状態チェック（true/false/null）は子・親の状態から決まる。
# チェックはツリーのチェックボックスの Click で Toggle() を呼んで変える（TwoWay バインドはしない）
class IndexNode : NotifyBase {
    [string]$Name
    [string]$Root
    [string]$RelPath
    [bool]$IsFiles
    [bool]$IsPlaceholder
    [bool]$Exists
    [string]$SourcePath
    [string]$ToolTip
    [IndexNode]$Parent
    [System.Collections.ObjectModel.ObservableCollection[IndexNode]]$Children

    [Nullable[bool]]$IsChecked = $true   # チェックボックスは OneWay バインド。変更は Toggle/SetChecked で行う
    [bool]$IsExpanded                    # TreeViewItem.IsExpanded は OneWay。展開は Expanded イベント/SetExpanded で読み込む
    [bool]$IsLoading                     # 裏で子を読み込んでいる間（ネットワークのとき）
    hidden [bool]$loaded

    IndexNode([IndexNode]$parent, [string]$name, [string]$root, [string]$relPath, [bool]$isFiles) {
        $this.Parent = $parent
        $this.Name = $name
        $this.Root = $root
        $this.RelPath = $relPath
        $this.IsFiles = $isFiles
        $this.Exists = $true
        $this.Children = New-Object System.Collections.ObjectModel.ObservableCollection[IndexNode]
        if ($null -ne $parent) { $this.IsChecked = ($parent.IsChecked -ne $false) }
    }

    # 根（インデックス 1 件）を作る。フォルダの有無・サブフォルダの有無は呼ぶ側が集めて渡す（ここではファイルに触らない）
    static [IndexNode] CreateRoot([string]$root, [string]$name, [string]$relPath, [string]$sourcePath, [bool]$exists, [bool]$hasSubfolders) {
        $node = [IndexNode]::new($null, $name, $root, $relPath, $false)
        $node.SourcePath = $sourcePath
        $dir = $node.FullPath()
        $node.Exists = $exists
        # [string] の引数・プロパティは $null を "" にするため、元のフォルダが分からないことは空で判定する
        $node.ToolTip = $(if (-not [string]::IsNullOrEmpty($sourcePath)) { "元のフォルダ：" + $sourcePath + "`nインデックス：" + $dir } else { $dir })
        if (-not $node.Exists) { $node.ToolTip += "`n（フォルダが見つかりません。検索時はスキップします）" }
        if ($node.Exists -and $hasSubfolders) { $node.Children.Add([IndexNode]::NewPlaceholder($node)) } else { $node.loaded = $true }
        return $node
    }

    [string] FullPath() {
        return $(if ($this.RelPath -eq "") { $this.Root } else { $this.Root.TrimEnd('\') + "\" + $this.RelPath })
    }

    # 展開の状態を変える（プログラムから）。子の読み込みは呼ぶ側が行う（NeedsLoad・ApplyChildren）
    [void] SetExpanded([bool]$value) {
        if ($this.IsExpanded -eq $value) { return }
        $this.IsExpanded = $value
        $this.Raise("IsExpanded")
    }

    [void] SetChecked([bool]$value) {
        $this.SetTree($value)
        if ($null -ne $this.Parent) { $this.Parent.UpdateFromChildren() }
    }

    [void] Toggle() { $this.SetChecked($this.IsChecked -ne $true) }

    hidden [void] SetTree([bool]$value) {
        $this.SetState($value)
        foreach ($child in $this.Children) { if (-not $child.IsPlaceholder) { $child.SetTree($value) } }
    }

    hidden [void] SetState([Nullable[bool]]$value) {
        if ($this.IsChecked -eq $value) { return }
        $this.IsChecked = $value
        $this.Raise("IsChecked")
    }

    hidden [void] UpdateFromChildren() {
        $any = $false
        [Nullable[bool]]$state = $null
        foreach ($child in $this.Children) {
            if ($child.IsPlaceholder) { continue }
            if (-not $any) { $state = $child.IsChecked; $any = $true }
            elseif ($state -ne $child.IsChecked) { $state = $null; break }
        }
        if (-not $any) { return }
        $this.SetState($state)
        if ($null -ne $this.Parent) { $this.Parent.UpdateFromChildren() }
    }

    # 子をまだ読み込んでいないか（読み込み前の子はプレースホルダーだけ）。読み込み中（IsLoading）の間も読み込み前
    [bool] NeedsLoad() {
        return (-not $this.loaded -and -not $this.IsFiles -and -not $this.IsPlaceholder -and $this.Exists)
    }

    # 読み込んだ子（getIndexFolderChildren の結果）を入れる。1 回だけ入れる（ここではファイルに触らない）
    [void] ApplyChildren($data) {
        if ($this.loaded -or $this.IsFiles -or $this.IsPlaceholder) { return }
        $this.loaded = $true
        $this.IsLoading = $false
        $this.Children.Clear()
        if (-not $this.Exists) { return }
        $dir = $this.FullPath()
        $names = @($data.Folders)
        if ($names.Count -gt 0 -and $data.HasFiles) {
            $files = [IndexNode]::new($this, "（このフォルダ直下のファイル）", $this.Root, $this.RelPath, $true)
            $files.ToolTip = "サブフォルダを除く、" + $(if (-not [string]::IsNullOrEmpty($this.SourcePath)) { $this.SourcePath } else { $dir }) + " の直下のファイル"
            $this.Children.Add($files)
        }
        foreach ($folder in $names) {
            $n = [string]$folder.Name
            $childRel = $(if ($this.RelPath -eq "") { $n } else { $this.RelPath + "\" + $n })
            $child = [IndexNode]::new($this, $n, $this.Root, $childRel, $false)
            if (-not [string]::IsNullOrEmpty($this.SourcePath)) { $child.SourcePath = $this.SourcePath.TrimEnd('\') + "\" + $n }
            $child.ToolTip = $(if (-not [string]::IsNullOrEmpty($child.SourcePath)) { "元のフォルダ：" + $child.SourcePath } else { $child.FullPath() })
            if ($folder.HasSubfolders) { $child.Children.Add([IndexNode]::NewPlaceholder($child)) } else { $child.loaded = $true }
            $this.Children.Add($child)
        }
    }

    [IndexNode] Find([string]$path) {
        if ($this.IsFiles -or $this.IsPlaceholder) { return $null }
        $full = $this.FullPath().TrimEnd('\')
        $path = $path.TrimEnd('\')
        if ([string]::Equals($path, $full, [System.StringComparison]::OrdinalIgnoreCase)) { return $this }
        if (-not $path.StartsWith($full + "\", [System.StringComparison]::OrdinalIgnoreCase)) { return $null }
        # 読み込み前の子はたどらない（ファイルに触らない。読み込みは呼ぶ側が先に済ませる）
        foreach ($child in $this.Children) {
            $found = $child.Find($path)
            if ($null -ne $found) { return $found }
        }
        return $null
    }

    [void] ApplyExclude([string]$path, [bool]$subfolders) {
        $node = $this.Find($path)
        if ($null -eq $node) { return }
        if (-not $subfolders) {
            foreach ($child in $node.Children) {
                if ($child.IsFiles) { $child.SetChecked($false); return }
            }
            if ($node.Children.Count -gt 0) { return }
        }
        $node.SetChecked($false)
    }

    [void] AddTargets([System.Collections.Generic.List[SearchTarget]]$targets) {
        if ($this.IsPlaceholder -or $this.IsChecked -eq $false) { return }
        if ($this.IsChecked -eq $true) {
            $targets.Add([SearchTarget]@{ Root = $this.Root; RelPath = $this.RelPath; Recurse = (-not $this.IsFiles) })
            return
        }
        foreach ($child in $this.Children) { $child.AddTargets($targets) }
    }

    [void] AddExcludes([System.Collections.Generic.List[SearchExclude]]$excludes) {
        if ($this.IsPlaceholder -or $this.IsChecked -eq $true) { return }
        if ($this.IsChecked -eq $false) {
            $excludes.Add([SearchExclude]@{ Path = $this.FullPath(); Subfolders = (-not $this.IsFiles) })
            return
        }
        foreach ($child in $this.Children) { $child.AddExcludes($excludes) }
    }

    [void] AddExpanded([System.Collections.Generic.List[string]]$paths) {
        if ($this.IsFiles -or $this.IsPlaceholder) { return }
        if ($this.IsExpanded) { $paths.Add($this.FullPath()) }
        foreach ($child in $this.Children) { $child.AddExpanded($paths) }
    }

    static [IndexNode] NewPlaceholder([IndexNode]$parent) {
        $node = [IndexNode]::new($parent, "読み込み中…", $parent.Root, $parent.RelPath, $false)
        $node.IsPlaceholder = $true
        return $node
    }
}

# tebunko の画面で使う型: ［インデックス管理］の一覧・詳細・失敗した行。
# shared\ui\types.ps1 を先に読み込んでおくこと（NotifyBase を継承する）。

# ［インデックス管理］の取り込みに失敗したファイル1件
class FailRow {
    [string]$RelPath
    [string]$Reason
    [string]$IngestedText
    [string]$SourcePath
}

# インデックスの詳細のパネルの値の 1 行（getIndexDetailView）
class DetailRow {
    [string]$Label
    [string]$Value
}

# インデックス更新の確認ダイアログに出すインデックス 1 件（取り込み予定.tsv の 1 行）
class PlanRow {
    [string]$Name
    [string]$Path
    [string]$TotalText    # 対象ファイル数（"1,243"。数えない行は "－"）
    [string]$StatusText   # ステータスのバッジの文言（"要更新" / "最新" / "対象外" / "フォルダなし"）
    [string]$Level        # バッジの色（Wait / Ok / None / Ng）
    [string]$DetailText   # バッジの ToolTip（更新するファイルの内訳）
}

# ［インデックス管理］のインデックス一覧 1 件。プログラムから変えたときに画面へ反映するため通知する。
# 行のチェックの TwoWay バインドは値の往復に使い、保存はチェックボックスの Click で行う（PS class はセッターにロジックを書けないため）
class FolderItem : NotifyBase {
    [string]$Name          # インデックス名（work\index 直下のフォルダ名）
    [string]$Path
    [bool]$Enabled         # 設定の enabled（［すべて更新］で更新する対象か。画面にチェックは出さない）
    [bool]$Checked         # 一覧のチェック（一時の選択。保存しない。［アクション ▼］・行の操作の対象）
    [string]$StatusText
    [object]$StatusBrush
    [string]$FileCountText
    [string]$FileCountToolTip
    [string]$LastIngestedText
    [bool]$StatusChecked   # フォルダの有無を調べ終えたか（別スレッドで調べる。refreshFolderStatus）
    [bool]$FolderExists    # 調べた結果、フォルダがあったか
    # 一覧の「ステータス」列（本文の取り込みの状態。getIndexRowView）。色は XAML で Level から選ぶ（Ok/Wait/Ng/Run/None）
    [string]$IndexText = "－"
    [string]$IndexToolTip
    [string]$IndexLevel = "None"
    [double]$IndexPercent = 0   # 更新中のバッジの下の棒の長さ（0～100）
    [string]$IndexSub = ""   # ステータスのバッジの下の補足（途中で止まったときの「残り N 件」。無ければ空）
    # 一覧の「高速検索」列（システムインデックスの反映の状態。getFastSearchRowView）
    [string]$FastText = "確認中…"
    [string]$FastToolTip
    [string]$FastLevel = "None"   # Ok / Wait / Warn（使えない。注意の色）/ None
    [string[]]$FastSteps = @()    # 使えないときの対処の手順（詳細に箇条で出す）
    # 一覧の行の右端のボタン（getIndexRowActions）。RowAction は Update / Stop / None
    [string]$RowAction = "Update"
    [bool]$RowUpdateEnabled = $false

    FolderItem() {}   # 既定のコンストラクタを明示する（理由は shared\ui\types.ps1 の NotifyBase）

    [void] SetEnabled([bool]$value) { if ($this.Enabled -ne $value) { $this.Enabled = $value; $this.Raise("Enabled") } }
    [void] SetRowChecked([bool]$value) { if ($this.Checked -ne $value) { $this.Checked = $value; $this.Raise("Checked") } }
    [void] SetName([string]$value) { if ($this.Name -ne $value) { $this.Name = $value; $this.Raise("Name") } }
    [void] SetPath([string]$value) { if ($this.Path -ne $value) { $this.Path = $value; $this.Raise("Path") } }
    [void] SetStatus([string]$text, [object]$brush) { $this.StatusText = $text; $this.StatusBrush = $brush; $this.Raise("StatusText"); $this.Raise("StatusBrush") }
    [void] SetStats([string]$countText, [string]$toolTip, [string]$lastIngested) {
        $this.FileCountText = $countText; $this.FileCountToolTip = $toolTip; $this.LastIngestedText = $lastIngested
        $this.Raise("FileCountText"); $this.Raise("FileCountToolTip"); $this.Raise("LastIngestedText")
    }
    [void] SetIndexState([string]$text, [string]$toolTip, [string]$level, [string]$sub, [double]$percent) {
        $this.IndexText = $text; $this.IndexToolTip = $toolTip; $this.IndexLevel = $level; $this.IndexSub = $sub; $this.IndexPercent = $percent
        $this.Raise("IndexText"); $this.Raise("IndexToolTip"); $this.Raise("IndexLevel"); $this.Raise("IndexSub"); $this.Raise("IndexPercent")
    }
    [void] SetRowActions([string]$action, [bool]$updateEnabled) {
        $this.RowAction = $action; $this.RowUpdateEnabled = $updateEnabled
        $this.Raise("RowAction"); $this.Raise("RowUpdateEnabled")
    }
    [void] SetFast([string]$text, [string]$toolTip, [string]$level) {
        $this.FastText = $text; $this.FastToolTip = $toolTip; $this.FastLevel = $level; $this.FastSteps = @()
        $this.Raise("FastText"); $this.Raise("FastToolTip"); $this.Raise("FastLevel"); $this.Raise("FastSteps")
    }
    [void] SetFast([string]$text, [string]$toolTip, [string]$level, [string[]]$steps) {
        $this.FastText = $text; $this.FastToolTip = $toolTip; $this.FastLevel = $level; $this.FastSteps = $steps
        $this.Raise("FastText"); $this.Raise("FastToolTip"); $this.Raise("FastLevel"); $this.Raise("FastSteps")
    }
}

# 画面の土台（XAML の読み込み・見た目の共通定義・エラーの記録）。
# 使う側が themeFile・iconXamlFile を定義し、エラーの記録先を返す式と、記録の先頭に書く見出しの行を返す式を
# setGuiErrorLogSource で登録しておくこと（見出しが無くても記録は書く）。

# 見た目の共通定義を読み込む（画面自体は XAML の MergedDictionaries で読み込む）
function loadTheme {
    if ($null -eq ${script:theme}) {
        ${script:theme} = loadXaml ${themeFile}
    }
    return ${script:theme}
}

# XAML の中身を文字列で返す。単一 .ps1 版（展開せずに動く試験版。結合の道具 tools/new_single_script.ps1 が
# xaml の中身を ${bundledXaml}[<このファイルを指す絶対パス>] に埋め込む）はそこから返し、
# 無ければ（zip 版）ファイルから読む。
# 探す前に GetFullPath で正規化する（".." を含む書き方でも、結合の道具が埋めた鍵と一致させるため。
# ファイルが実在しなくても使える＝単一 .ps1 版で theme.xaml が無くても引ける）
function getXamlText {
    param (
        [string]$path
    )

    $bundled = Get-Variable -Name bundledXaml -ErrorAction SilentlyContinue
    if ($null -ne $bundled -and $bundled.Value) {
        $full = [System.IO.Path]::GetFullPath($path)
        if ($bundled.Value.ContainsKey($full)) {
            return $bundled.Value[$full]
        }
    }
    return [System.IO.File]::ReadAllText($path, (New-Object System.Text.UTF8Encoding($true)))
}

# <ResourceDictionary Source="..." /> を、そのファイルの中身（ResourceDictionary の子要素）に差し替える。
# XamlReader に渡す前に XML としてテキストで組み立て直すことで、BaseUri（System.Windows.Application が無いと
# 相対パスを解決できない）に頼らずに済む。単一 .ps1 版で xaml がファイルとして存在しなくても働く
function inlineMergedDictionaries {
    param (
        [System.Xml.XmlDocument]$xml,
        [string]$basePath
    )

    foreach ($node in @($xml.SelectNodes("//*[local-name()='ResourceDictionary' and @Source]"))) {
        # GetFullPath は実在しないファイルでも正規化できる（Resolve-Path と違い、単一 .ps1 版で theme.xaml が
        # 実在しなくても働く）
        $refPath = [System.IO.Path]::GetFullPath((Join-Path (Split-Path -Parent $basePath) $node.Attributes["Source"].Value))
        $refXml = New-Object System.Xml.XmlDocument
        $refXml.LoadXml((getXamlText $refPath))
        inlineMergedDictionaries $refXml $refPath
        $replacement = $xml.CreateElement($node.LocalName, $node.NamespaceURI)
        foreach ($attribute in @($refXml.DocumentElement.Attributes)) {
            if ($attribute.Prefix -eq "xmlns" -or $attribute.Name -eq "xmlns") {
                continue
            }
            [void]$replacement.SetAttribute($attribute.Name, $attribute.NamespaceURI, $attribute.Value)
        }
        foreach ($child in @($refXml.DocumentElement.ChildNodes)) {
            [void]$replacement.AppendChild($xml.ImportNode($child, $true))
        }
        [void]$node.ParentNode.ReplaceChild($replacement, $node)
    }
}

# XAML を読み込む（Window・タブ・ダイアログの中身）。theme.xaml への参照は、読み込む前にテキストで差し替える
function loadXaml {
    param (
        [string]$path
    )

    $xml = New-Object System.Xml.XmlDocument
    $xml.LoadXml((getXamlText $path))
    inlineMergedDictionaries $xml $path

    $stream = New-Object System.IO.MemoryStream
    $xml.Save($stream)
    $stream.Position = 0
    try {
        $loaded = [System.Windows.Markup.XamlReader]::Load($stream)
    } finally {
        $stream.Dispose()
    }

    # 画面の既定のフォント（Font.Body）。XAML のルートが FontFamily="{DynamicResource Font.Body}" で使う。
    # フォントはコードで 1 か所（newAppFontFamily）から入れる。展開した版でも単一 .ps1 版でも同じ値になる
    if ($loaded -is [System.Windows.FrameworkElement]) {
        # 型を明示する（PowerShell のラッパーのまま入れると、DynamicResource が文字列として解決して失敗する）
        $loaded.Resources["Font.Body"] = [System.Windows.Media.FontFamily](newAppFontFamily)
    }
    return $loaded
}

# 画面の既定のフォント。欧文は Segoe UI、日本語など足りない文字は Yu Gothic UI（無ければ Meiryo UI）で表す。
# どれも Windows に入っているので、展開した版も単一 .ps1 版も同じになる（フォントは同梱しない）
function newAppFontFamily {
    return New-Object System.Windows.Media.FontFamily -ArgumentList "Segoe UI, Yu Gothic UI, Meiryo UI"
}

function loadWindow {
    param (
        [string]$path
    )

    $loaded = loadXaml $path

    # 窓のアイコン（タイトルバー・タスクバー）は、ベクターの絵（loadAppIcon）を渡す。
    # WPF が窓のアイコンの大きさ（倍率に応じた大きさ）に描き直す。アイコンが読めなくても画面は開けるようにする。
    $icon = loadAppIcon
    if ($null -ne $icon) {
        $loaded.Icon = $icon
    }

    return $loaded
}

# 画面のアイコン（ベクターの絵。xaml\app_icon.xaml。元データは docs\images\logo.svg）を読み込む。読めなければ $null。
# 窓（loadWindow）・バージョン情報など、アイコンを出す所が同じ 1 つを使う（凍結して共有する）
function loadAppIcon {
    if ($null -eq ${script:appIcon}) {
        try {
            $icon = loadXaml ${iconXamlFile}
            $icon.Freeze()
            ${script:appIcon} = $icon
        } catch {
            return $null
        }
    }
    return ${script:appIcon}
}

# 表のセルなど、コードから色を付ける箇所。色は theme.xaml のトークンから取り、画面と食い違わないようにする
function themeBrush {
    param (
        [string]$key
    )

    return (loadTheme)[$key]
}

# 画面エラーの記録の上限（これ以上になったら前回の分に回す）
${guiErrorLogMaxBytes} = 1MB
# 見出しを最後に書いた記録先（writeErrorLog が、最初の記録・記録先の変更で見出しを書くために覚える）
${script:errorLogHeaderPath} = $null
# 使う側が登録する、記録先を返す式と見出しの行を返す式（setGuiErrorLogSource）
${script:errorLogFileSource} = $null
${script:errorLogHeaderSource} = $null

function setGuiErrorLogSource {
    # 記録先（file）と記録の先頭の見出し（header。行の配列）を返す式を登録する（gui.ps1 が app_host.ps1 を読み込んだ直後に呼ぶ）
    param (
        [scriptblock]$file,
        [scriptblock]$header
    )

    ${script:errorLogFileSource} = $file
    ${script:errorLogHeaderSource} = $header
}

# エラーの記録先。登録が無い（まだ決まっていない）ときは $null を返す
function getGuiErrorLogFile {
    if ($null -eq ${script:errorLogFileSource}) {
        return $null
    }
    return (& ${script:errorLogFileSource})
}

# 記録の先頭に書く見出しの行。登録が無いときは例外を投げる（writeErrorLog は、見出しを作れなくても記録は書く）
function getGuiErrorLogHeader {
    if ($null -eq ${script:errorLogHeaderSource}) {
        throw "getGuiErrorLogHeader: setGuiErrorLogSource で登録されていない"
    }
    return (& ${script:errorLogHeaderSource})
}

# 予期しないエラーを getGuiErrorLogFile のファイルに残す。画面に出したメッセージだけでは、
# どこで起きたのかが後から分からないため（利用者に見せるのは従来どおりメッセージだけ）
function writeErrorLog {
    param (
        [string]$context,
        [System.Management.Automation.ErrorRecord]$record
    )

    try {
        $path = getGuiErrorLogFile
        $dir = Split-Path -Parent $path
        if (-not (Test-Path -LiteralPath $dir)) {
            [void][System.IO.Directory]::CreateDirectory($dir)
        }
        # 1 MB 以上なら前回の分（gui_error_log_previous.txt）に回す。合わせておよそ 2 MB で止まる
        try { [void](rotateLogFile $path ${guiErrorLogMaxBytes}) } catch {}
        # 見出し（版と環境）は、このプロセスで最初の記録・記録先が変わった（ワークスペースの切り替え）・ファイルが無かった（回した直後）ときに書く。
        # 見出しを作れなくても記録は書く（起動中は getGuiErrorLogHeader がまだ読み込まれていないことがある）
        $headerText = ""
        if (${script:errorLogHeaderPath} -ne $path -or -not [System.IO.File]::Exists($path)) {
            try {
                $headerText = (@(getGuiErrorLogHeader) -join "`r`n") + "`r`n`r`n"
                ${script:errorLogHeaderPath} = $path
            } catch {
                $headerText = ""
            }
        }
        $body = @(
            "==== $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') ${context} ===="
            "$($record.Exception.GetType().FullName): $($record.Exception.Message)"
            "$($record.InvocationInfo.PositionMessage)"
            "$($record.ScriptStackTrace)"
            if ($record.Exception.InnerException) { "内側: $($record.Exception.InnerException)" }
            ""
        ) -join "`r`n"
        $text = $headerText + $body
        [System.IO.File]::AppendAllText($path, $text, (New-Object System.Text.UTF8Encoding($true)))
    } catch {
        # 記録できなくても、画面の動作は止めない
    }
}

    setGuiErrorLogSource { getToolGuiErrorLogFile } { getToolGuiErrorLogHeader }
# 文字が省略（…）で切れているときだけ、全文をツールチップで見せる（画面層）。
# 切れているかの判定は shared\core\text.ps1 の testTextTrimmed。ここは TextBlock の幅を測って渡すだけで、このツール固有の文言は持たない。
# ToolTip には全文を入れておき、開く直前（ToolTipOpening）に測って、切れていなければ e.Handled = $true にして開かない。

function testTextBlockTrimmed {
    # TextBlock が今の幅で文字を省略しているか。要る幅は、同じ書体・大きさで折り返さずに並べたときの幅
    param (
        [System.Windows.Controls.TextBlock]$textBlock
    )

    $text = [string]$textBlock.Text
    if ($text -eq "" -or $textBlock.ActualWidth -le 0) {
        return $false
    }
    $typeface = New-Object System.Windows.Media.Typeface($textBlock.FontFamily, $textBlock.FontStyle, $textBlock.FontWeight, $textBlock.FontStretch)
    $dpi = [System.Windows.Media.VisualTreeHelper]::GetDpi($textBlock).PixelsPerDip
    $formatted = New-Object System.Windows.Media.FormattedText($text, [System.Globalization.CultureInfo]::CurrentUICulture,
        [System.Windows.FlowDirection]::LeftToRight, $typeface, $textBlock.FontSize, [System.Windows.Media.Brushes]::Black, $dpi)
    return (testTextTrimmed $textBlock.ActualWidth $formatted.WidthIncludingTrailingWhitespace)
}

function addTrimmedToolTip {
    # TextBlock に、切れているときだけ開くツールチップ（全文）を付ける。Text が変わっても、開く直前の中身を使う。
    # DataGrid などの行の中の TextBlock は、行の Loaded で渡して付ける（addTrimmedToolTip $cell）
    param (
        [System.Windows.Controls.TextBlock]$textBlock
    )

    $textBlock.ToolTip = [string]$textBlock.Text
    $textBlock.Add_ToolTipOpening({
        param ($sender, $e)
        $sender.ToolTip = [string]$sender.Text
        if (!(testTextBlockTrimmed $sender)) {
            $e.Handled = $true
        }
    })
}

function addTrimmedToolTipToRows {
    # 行の Loaded（DataGridRow など）で、その行の中の Tag が tag の TextBlock に addTrimmedToolTip を付ける（付けたら Tag を「<tag>Set」にして、二重に付けない）。
    # Loaded のハンドラは行の Tag に tag を入れてそこから読む（GetNewClosure にすると画面の関数が見えなくなるため）。
    # 行の Tag を印に使うので、ほかの用途で Tag を使う行には使えない。Tag が tag の行には何もしない（呼び直されても、ハンドラが重ならず、行ごとに 1 回だけ付く）
    param (
        [System.Windows.FrameworkElement]$row,
        [string]$tag
    )

    if ($row.Tag -eq $tag) {
        return
    }
    $row.Tag = $tag
    $row.Add_Loaded({
        param ($sender, $e)
        $tag = [string]$sender.Tag
        safe {
            $stack = New-Object System.Collections.Generic.Stack[System.Windows.DependencyObject]
            $stack.Push($sender)
            while ($stack.Count -gt 0) {
                $node = $stack.Pop()
                for ($i = 0; $i -lt [System.Windows.Media.VisualTreeHelper]::GetChildrenCount($node); $i++) {
                    $child = [System.Windows.Media.VisualTreeHelper]::GetChild($node, $i)
                    if ($child -is [System.Windows.Controls.TextBlock] -and $child.Tag -eq $tag) {
                        addTrimmedToolTip $child
                        $child.Tag = "${tag}Set"
                    }
                    $stack.Push($child)
                }
            }
        }
    })
}

    stepSplash 50

# 画面（WPF）の本体。gui.ps1（起動口）が、起動中の表示・Add-Type・Unblock-File・部品の読み込みを終えた後に呼ぶ。
#
# ui\ 配下のファイルは $PSScriptRoot を使わない（ここは tebunko\ui\ に置くため、$PSScriptRoot は ui\ を指してしまう）。
# tebunko\ のパスが要るときは、呼び出し元（gui.ps1）から渡された $TebunkoDir を使う。
#
# startGui は順に呼ぶだけにする。中身は ui\shell\ の下のファイルに分け、startGui の中で読み込む
# （$ui・$window・startGui のローカル変数・$script: の変数をそのまま見られるように、関数にせず dot-source する）。
# 画面を足すときは、領域の表（shell\regions.ps1）と読み込みの表（shell\screens.ps1）に行を足す。

function startGui {
    param (
        [string]$TebunkoDir
    )

    # 検索・画面の裏の仕事も同じプロセスのスレッドで動くため、画面を止める重い GC（全体の GC）をなるべく後回しにする
    # （docs/design/structure/closing.md「GC とメモリ」）
    [System.Runtime.GCSettings]::LatencyMode = [System.Runtime.GCLatencyMode]::SustainedLowLatency

    ${searchLimit} = 10000
    ${previewFirstLines}    = 50   # 行を選んだときに、プレビューへ最初に出す選択行の前後の行数（それぞれ）
    ${previewReadAheadLines} = 20  # 見えている行が、読んである範囲の端からこの行数以内に近づいたら、その向きに読み足す
    ${previewChunkLines}    = 200  # 1 回に読み足す行数（持つ行が上限を超えたとき、遠い側から捨てる行数も同じ）
    ${previewMaxRows}       = 3000 # プレビューに持つ行の上限（超えたら、見ている所から遠い側を捨てる）
    ${previewColumnMargin}  = 3    # 見えている列の左右に、先に作っておく列の数（横にスクロールするたびにセルを作り直さないため）
    ${previewCellRowMargin} = 10   # 見えている行の上下に、先にセルを作っておく行の数
    ${backgroundWorkers} = 2  # startJob のスレッドの数

    # 画面定義（XAML）とアイコンの置き場所
    ${xamlDir}       = "$TebunkoDir\xaml"
    ${sharedXamlDir} = "$TebunkoDir\..\shared\xaml"
    ${iconXamlFile}  = "${xamlDir}\app_icon.xaml"  # 窓・バージョン情報に出すアイコン（ベクターの絵）
    # アイコンは Window.Icon（loadWindow）でタイトルバー・タスクバーに出る。.ico（tebunko.ico）は画面では使わず、
    # インストーラー・ショートカットなど Windows が .ico しか受け付けない所だけで使う。
    # ※以前は SetAppId（P/Invoke）でタスクバーのボタンを PowerShell と分けていたが、
    #   実行時コンパイル（csc.exe）を無くすため廃止した（アイコン自体は Window.Icon で出るため残る）。
    ${themeFile} = "${sharedXamlDir}\theme.xaml"  # 画面の見た目（色・文字・コントロールの形）の共通定義

    # ---- 多重起動の防止（ツールの配置フォルダごと） ----
    #
    # すでに開いているときは、その画面のウィンドウを前面に出して終わる（もう一度起動するのは、
    # たいてい「開いたつもりのウィンドウが他のウィンドウの裏にある」ときのため）。
    # 知らせるのは名前付きイベントで行う。ここは C# の型をコンパイルする前のため、.NET の機能だけを使う。

    $instanceKey = getFolderKey ${rootDir}
    $mutexName = "Local\${appId}_gui_" + $instanceKey
    $activateName = "Local\${appId}_gui_activate_" + $instanceKey
    $createdNew = $false
    $mutex = New-Object System.Threading.Mutex($true, $mutexName, [ref]$createdNew)
    if (!$createdNew) {
        $running = $null
        if ([System.Threading.EventWaitHandle]::TryOpenExisting($activateName, [ref]$running)) {
            [void]$running.Set()
            $running.Close()
            exit
        }
        # 以前の版の画面が開いている等で知らせられないときだけ、メッセージを出す
        closeSplash
        [System.Windows.MessageBox]::Show("すでに開いています。", ${appTitle}, "OK", "Information") | Out-Null
        exit
    }
    $activateEvent = New-Object System.Threading.EventWaitHandle($false, [System.Threading.EventResetMode]::AutoReset, $activateName)

    # 壊れた設定ファイルの退避と、ワークスペースの決定
# startGui の一部: 壊れた設定ファイルの退避と、ワークスペースの決定。startGui の中で読み込む。

    # ---- 壊れた設定ファイルの退避 ----
    # setting.config が JSON として読めないときは、別の名前に退避して既定の設定で起動する（画面が出てから知らせる。$script:settingsRecovery）。
    # 退避するのは、ここ（多重起動でない最初の起動）だけ。ほかの読み込みは、壊れたファイルを動かさずに例外にする（readSettings）
    $script:settingsRecovery = repairBrokenSettings
    # ワークスペース（setting.config の workspaceFolder）は、壊れた設定ファイルの退避の後に決める
    initWorkspace
    stepSplash 40


    $ErrorActionPreference = "Stop"

    # ウィンドウと、領域ごとの部品の対応表（$ui）
    $window = loadWindow "${xamlDir}\tebunko.xaml"
    stepSplash 55
    $ui = @{}
# startGui の一部: 窓の領域の表（$regions）と、x:Name の対応表（$ui）。startGui の中で読み込む（$window・${xamlDir} と、呼ぶ側が作る $ui を使う）。
# 画面（領域）を足すときは、ここに行を足す。

    # 窓の中身は領域ごとのファイルに分けてある（xaml\<画面>\<領域>.xaml）。読み込んで差す口に入れ、x:Name の対応表（$ui）を作る。
    # 別ファイルから読み込んだ中身は、そのファイルごとに名前を持つため、$window.FindName では見つからない。
    # 領域ごとに FindName する（名前の一覧も領域ごとに分けておく）。
    # 領域の表: File = xaml\ からの相対パス、Slot = 差す口（窓の x:Name）、Screen = 画面の名前（Slot が ContentHost のものだけ。
    # 画面の中身は $script:screenContents に持ち、selectScreen が選んだものを ContentHost に差す）、Names = 使う x:Name
    # 知らせの帯の部品（shell\notice_banner.xaml）の名前。3 か所に差す（下の表で Prefix を付けて持つ）
    $noticeBannerNames = @("NoticePanel", "NoticeIcon", "NoticeText", "NoticeButton", "NoticeClose")
    $regions = @(
        @{ File = "shell\nav.xaml"; Slot = "NavHost"; Names = @(
            "NavList", "SearchTab", "IndexTab", "SettingsTab", "IndexTabBadge", "NavPaneHost", "AboutLink") }
        @{ File = "shell\status_bar.xaml"; Slot = "StatusBarHost"; Names = @("StatusText", "IndexingStatusText", "IndexFooterFolders", "IndexFooterFiles") }
        @{ File = "index\index.xaml"; Slot = "ContentHost"; Screen = "IndexTab"; Names = @(
            "IndexListHost", "IndexDetailHost", "IndexDetailRow", "IndexSplitter",
            "IndexingProgressPanel", "IndexingBannerIcon", "IndexingProgressText", "IndexingProgressEta", "IndexingProgress",
            "IndexingProgressDetail", "IndexingStopButton", "IndexingResumeButton", "IndexingSearchButton", "IndexingBannerClose",
            "IndexNoticeHost") }
        @{ File = "index\index_list.xaml"; Slot = "IndexListHost"; Names = @(
            "IndexGrid", "IndexGridPlaceholder", "NewIndexButton", "ActionsButton", "ActionsMenu", "ActionUpdate", "ActionExport", "ActionImport", "ActionDelete", "SelectionCountText", "SelectAllCheckBox", "IndexingButton", "IndexingHint", "StatusColumnHeader",
            "IndexRowMenu", "RowMenuUpdate", "RowMenuOpenFolder", "RemoveIndexButton", "ExportIndexButton") }
        @{ File = "index\index_detail.xaml"; Slot = "IndexDetailHost"; Names = @(
            "IndexDetailTitle", "IndexSummaryText",
            "IndexDetailRows", "IndexDetailFastPanel", "IndexDetailFastText", "IndexDetailFastBar",
            "FailedPanel", "FailedHeading", "FailedGrid") }
        @{ File = "search\search.xaml"; Slot = "ContentHost"; Screen = "SearchTab"; Names = @(
            "SearchBarHost", "ResultListHost", "PreviewHost", "DetailRow", "PreviewSplitter", "ResultEmptyState", "GoIndexTabButton",
            "SearchNoticeHost") }
        @{ File = "shell\notice_banner.xaml"; Slot = "SearchNoticeHost"; Prefix = "Search"; Margin = @(-16, -12, -16, 8); Names = $noticeBannerNames }
        @{ File = "shell\notice_banner.xaml"; Slot = "IndexNoticeHost"; Prefix = "Index"; Names = $noticeBannerNames }
        @{ File = "shell\notice_banner.xaml"; Slot = "WorkspaceNoticeHost"; Prefix = "Workspace"; Names = $noticeBannerNames }
        @{ File = "search\search_bar.xaml"; Slot = "SearchBarHost"; Names = @(
            "WordBox", "SearchButton", "RegexCheck", "CaseCheck", "ShapeCheck", "CommentCheck", "ScopeButton",
            "ConditionsPanel", "ConditionsSpacer", "FastSearchSlot", "KindChipExcel", "KindChipWord", "KindChipPowerPoint", "KindChipText", "KindChipPdf",
            "WordPlaceholder", "WordErrorRing", "FastBadge", "FastBadgeIcon", "FastBadgeInfo", "FastSearchText",
            "BalloonLayer", "SearchKindBalloon", "SearchKindBalloonText", "RegexBalloon", "RegexBalloonText") }
        @{ File = "search\target_tree.xaml"; Slot = "NavPaneHost"; Names = @(
            "IndexTree", "CheckAllIndexButton", "UncheckAllIndexButton", "TargetCountText") }
        @{ File = "search\result_list.xaml"; Slot = "ResultListHost"; Names = @(
            "SummaryText", "SearchProgress", "FilterBox", "FilterPlaceholder", "ExpandAllButton", "CollapseAllButton", "ExportButton",
            "ResultGrid", "NoHitText",
            "ResultMenu", "MenuOpen", "MenuOpenReadOnly", "MenuOpenNew", "MenuOpenFolder", "MenuCopy", "MenuCopyPath", "MenuToggleGroup") }
        @{ File = "search\preview.xaml"; Slot = "PreviewHost"; Names = @(
            "DetailPanel", "DetailTitle", "OpenButton", "OpenMenuButton", "MenuOpenModeNormal", "MenuOpenModeNew", "MenuOpenModeReadOnly", "OpenFolderButton",
            "PreviewHeaderScroll", "PreviewHeaderPanel", "PreviewHeader", "PreviewRows",
            "PreviewPlaceholder", "PreviewMenu", "MenuPreviewOpen", "MenuPreviewCopy", "MenuPreviewCopyRow") }
        @{ File = "settings\settings.xaml"; Slot = "ContentHost"; Screen = "SettingsTab"; Names = @(
            "WorkspaceBox", "WorkspaceInputError", "WorkspaceNote", "WorkspaceCaution", "WorkspaceHowTo", "ChangeWorkspaceButton", "ResetWorkspaceButton", "SettingsFileText", "SettingsFileNote") }
    )

    foreach ($name in @("NavHost", "ContentHost", "StatusBarHost", "ScrimOverlay",
            "WorkspaceNoticeHost")) {
        $ui[$name] = $window.FindName($name)
    }
    $script:screenContents = @{}
    foreach ($region in $regions) {
        $content = loadXaml "${xamlDir}\$($region.File)"
        if ($region.Slot -eq "ContentHost") {
            $script:screenContents[$region.Screen] = $content
        } else {
            $ui[$region.Slot].Content = $content
        }
        foreach ($name in $region.Names) {
            # 同じ部品（知らせの帯）を何か所かに差すものは、Prefix を付けた名前で持つ
            $key = "$($region.Prefix)$name"
            $ui[$key] = $content.FindName($name)
            if ($region.Prefix) {
                [System.Windows.Automation.AutomationProperties]::SetAutomationId($ui[$key], $key)
            }
        }
        if ($region.Margin) {
            $content.Margin = [System.Windows.Thickness]::new($region.Margin[0], $region.Margin[1], $region.Margin[2], $region.Margin[3])
        }
        stepSplash 70
    }
    # プレビューの行の入れ物（PreviewRows）は、行の仮想化のために、自分のテンプレートの中にスクロール（PreviewScroll）を持つ。
    # テンプレートの中の名前は上の FindName では取れないので、テンプレートを作ってから取る
    [void]$ui.PreviewRows.ApplyTemplate()
    $ui.PreviewScroll = $ui.PreviewRows.Template.FindName("PreviewScroll", $ui.PreviewRows)
    $taskbar = $window.TaskbarItemInfo


    ${okBrush}   = themeBrush "Ok"
    ${warnBrush} = themeBrush "Warn"
    ${ngBrush}   = themeBrush "Danger.Text"
    ${infoBrush} = themeBrush "Accent"
    ${grayBrush} = themeBrush "Ink.Muted"

    # 起動時の読み込み（loadStartupData）が済んだか。済むまでは、画面の切り替え・ウィンドウの前面化で読み直さない
    # （起動時の画面を選んだとき・ウィンドウを出したときにも呼ばれ、同じ読み込みが重なるため）。画面の読み込みの前に決める
    $script:startupLoaded = $false

    # 画面の中身（それぞれのファイルにイベントの登録まで入っている。$ui を作った後に読み込む）
# startGui の一部: 共通の画面部品の読み込みと、画面の裏の仕事のスレッド。startGui の中で読み込む。
# $ui を作った後に読み込む。screens.ps1 より前。

# メッセージの画面（showMessage・確認・エラーの知らせ）の、種類・ボタン・文の分け方（判断層。画面に触らない）。
# 画面に出す部分は shell.ps1。ここは「どの種類にどのアイコンと色を使うか」「どのボタンをどう並べるか」を決める。

# 種類ごとの印。Kind は共通の呼び名、Label は読み上げ・画面の確認に使う日本語の名前、Icon は theme.xaml の Geometry の名前、Brush は色の名前（Icon が空のときは印を出さない）。
# showMessage の icon 引数（MessageBoxImage の名前）と、確認・エラーの形から決める
function getMessageLook {
    param (
        [string]$icon
    )

    switch -Regex ($icon) {
        "^(Error|Stop|Hand)$"           { return @{ Kind = "Error";    Label = "エラー";   Icon = "Icon.CircleAlert";         Brush = "Danger.Text" } }
        "^(Warning|Exclamation)$"       { return @{ Kind = "Warning";  Label = "警告";     Icon = "Icon.TriangleAlert";       Brush = "Warn" } }
        "^Question$"                    { return @{ Kind = "Question"; Label = "確認";     Icon = "Icon.CircleQuestionMark";  Brush = "Accent" } }
        "^(Information|Asterisk)$"      { return @{ Kind = "Info";     Label = "お知らせ"; Icon = "Icon.Info";                Brush = "Accent" } }
        default                         { return @{ Kind = "None";     Label = "";         Icon = "";                         Brush = "" } }
    }
}

# ボタンの並び。左から右へ。Result は showMessage の戻り値（MessageBoxResult の名前）。
# 既定のボタン（Enter）は default で決める（None なら最初のボタン）。Cancel は Esc で押されるボタン。Primary は主なボタン（塗りつぶし）
function getMessageButtons {
    param (
        [string]$buttons = "OK",
        [string]$default = "None"
    )

    $specs = @(switch ($buttons) {
        "OKCancel"    { @(@{ Text = "OK"; Result = "OK" }, @{ Text = "キャンセル"; Result = "Cancel" }) }
        "YesNo"       { @(@{ Text = "はい"; Result = "Yes" }, @{ Text = "いいえ"; Result = "No" }) }
        "YesNoCancel" { @(@{ Text = "はい"; Result = "Yes" }, @{ Text = "いいえ"; Result = "No" }, @{ Text = "キャンセル"; Result = "Cancel" }) }
        default       { @(@{ Text = "OK"; Result = "OK" }) }
    })
    $defaultResult = if (@($specs | Where-Object { $_.Result -eq $default }).Count -gt 0) { $default } else { $specs[0].Result }
    $result = @()
    foreach ($spec in $specs) {
        $isDefault = ($spec.Result -eq $defaultResult)
        $result += , @{
            Text = $spec.Text
            Result = $spec.Result
            IsDefault = $isDefault
            Primary = $isDefault
            # OK だけなら Esc でも閉じる。取りやめがあるものは、その取りやめで閉じる。はい・いいえだけのものは Esc では閉じない（OS 標準と同じ）
            IsCancel = ($spec.Result -eq "Cancel") -or ($buttons -eq "OK")
        }
    }
    return , $result
}

# ×や Alt+F4 で閉じたときの戻り値（OS 標準のメッセージボックスと同じ）
function getMessageCloseResult {
    param (
        [string]$buttons = "OK"
    )

    switch ($buttons) {
        "OK"       { return "OK" }
        "YesNo"    { return "No" }
        default    { return "Cancel" }
    }
}

# 文を、見出し（最初の段落）と補足・詳しい内容に分ける。段落の区切りは空行。文言そのものは変えない。
# 補足が長い（4 行を超える・240 字を超える）ときは、選べる・スクロールできる詳細の枠に回す
function getMessageParts {
    param (
        [string]$message
    )

    $text = ([string]$message) -replace "`r`n", "`n"
    $index = $text.IndexOf("`n`n")
    if ($index -lt 0) {
        return @{ Heading = $text; Hint = ""; Detail = "" }
    }
    $heading = $text.Substring(0, $index)
    $rest = $text.Substring($index + 2).Trim("`n")
    if ($rest.Length -gt 240 -or @($rest -split "`n").Count -gt 4) {
        return @{ Heading = $heading; Hint = ""; Detail = $rest }
    }
    return @{ Heading = $heading; Hint = $rest; Detail = "" }
}

# 画面の共通部品（状態表示・メッセージ・確認ダイアログ・タイマー・別スレッド）。
# メッセージ（showMessage）・確認（showConfirm）・エラーの知らせ（showErrorDialog）は、同じ窓（dialog_confirm.xaml）で出す。

function setStatus {
    param (
        [string]$text
    )

    $ui.StatusText.Text = $text
}

function showMessage {
    # お知らせ・警告・誤り・確認のメッセージ。確認（showConfirm）・エラー（showErrorDialog）と同じ自前の画面で出す
    # （枠・題・余白・ボタンの形・種類ごとのアイコンと色は同じ。種類とボタンの決め方は message_view.ps1）。
    #   buttons: OK・OKCancel・YesNo・YesNoCancel ／ icon: Information・Warning・Error・Question・None ／ default: 最初に Enter で押すボタンの戻り値の名前
    # 戻り値は [System.Windows.MessageBoxResult]（OK・Yes・No・Cancel）。OS 標準の MessageBox.Show と同じ
    param (
        [string]$message,
        [string]$buttons = "OK",
        [string]$icon = "Information",
        [string]$default = "None",
        [System.Windows.Window]$owner = $window  # ダイアログを開いているときは、そのダイアログを親にする
    )

    # 自前の画面を出せないとき（別のスレッドから呼ばれた・親の窓が閉じかけている・画面の定義が読めない等）も、知らせること自体は止めない。
    # ここで例外が出ると、元のエラーが別のエラーに化けて分からなくなるため、記録だけ残して OS 標準のメッセージボックスで出す
    try {
        return showMessageDialog $message $buttons $icon $default $owner
    } catch {
        writeErrorLog "メッセージを自前の画面で表示できませんでした" $_
    }
    if ($null -ne $owner) {
        try {
            return [System.Windows.MessageBox]::Show($owner, $message, ${appTitle}, $buttons, $icon, $default)
        } catch {
            writeErrorLog "メッセージを親付きで表示できませんでした" $_
        }
    }
    return [System.Windows.MessageBox]::Show($message, ${appTitle}, $buttons, $icon, $default)
}

function setDialogLook {
    # メッセージの画面の見出しの左のアイコン。種類（getMessageLook）のアイコンと色にする。アイコンが無い種類は隠す
    param (
        $dialog,
        [hashtable]$look
    )

    $mark = $dialog.FindName("HeadingIcon")
    $host_ = $dialog.FindName("HeadingIconHost")
    if ($look.Icon -eq "") {
        $host_.Visibility = "Collapsed"
        return
    }
    $mark.Data = $dialog.FindResource($look.Icon)
    [System.Windows.Automation.AutomationProperties]::SetName($host_, $look.Label)  # 読み上げの名前（お知らせ・警告・エラー・確認）
    $mark.Stroke = $dialog.FindResource($look.Brush)
    $host_.Visibility = "Visible"
}

function showMessageDialog {
    param (
        [string]$message,
        [string]$buttons,
        [string]$icon,
        [string]$default,
        [System.Windows.Window]$owner
    )

    $dialog = loadWindow "${sharedXamlDir}\dialog_confirm.xaml"
    $dialog.Title = ${appTitle}
    $dialog.Width = getConfirmWidth "normal"
    if ($null -ne $owner) {
        $dialog.Owner = $owner
    } else {
        $dialog.WindowStartupLocation = "CenterScreen"
    }
    setDialogLook $dialog (getMessageLook $icon)
    $parts = getMessageParts $message
    $dialog.FindName("HeadingText").Text = $parts.Heading
    if ($parts.Hint -ne "") {
        $hint = $dialog.FindName("HintText")
        $hint.Text = $parts.Hint
        $hint.Visibility = "Visible"
    }
    if ($parts.Detail -ne "") {
        $dialog.FindName("DetailText").Text = $parts.Detail
        $dialog.FindName("DetailBox").Visibility = "Visible"
    }
    $panel = $dialog.FindName("ButtonPanel")
    $chosen = @{ Value = getMessageCloseResult $buttons }  # ボタンの Click から書き換えるため、入れ物ごとクロージャに渡す
    $onClick = {
        param ($sender, $e)
        $chosen.Value = $sender.Tag
        $dialog.DialogResult = $true
    }.GetNewClosure()
    $focusTarget = $null
    foreach ($spec in (getMessageButtons $buttons $default)) {
        $button = New-Object System.Windows.Controls.Button
        $button.Content = $spec.Text
        $button.Tag = $spec.Result
        $button.IsDefault = $spec.IsDefault
        $button.IsCancel = $spec.IsCancel
        if ($spec.Primary) {
            $button.Style = $dialog.FindResource("Primary")
            $focusTarget = $button
        }
        $button.Add_Click($onClick)
        $panel.Children.Add($button) | Out-Null
    }
    $dialog.Add_ContentRendered({ if ($null -ne $focusTarget) { $focusTarget.Focus() | Out-Null } }.GetNewClosure())
    $null = showOwnedDialog $dialog
    return [System.Windows.MessageBoxResult]$chosen.Value
}

# 確認ダイアログに並べる「実行するとこうなります」の 1 行を作る
function factKept { param ([string]$title, [string]$detail = "") [ConfirmFact]@{ Mark = "Kept"; MarkBrush = ${okBrush};   Title = $title; Detail = $detail } }

function factGone { param ([string]$title, [string]$detail = "") [ConfirmFact]@{ Mark = "Gone"; MarkBrush = ${ngBrush};   Title = $title; Detail = $detail } }

function factNext { param ([string]$title, [string]$detail = "") [ConfirmFact]@{ Mark = "Next"; MarkBrush = ${infoBrush}; Title = $title; Detail = $detail } }

function factWarn { param ([string]$title, [string]$detail = "") [ConfirmFact]@{ Mark = "!"; MarkBrush = ${warnBrush}; Title = $title; Detail = $detail } }

# 確認ダイアログの形。呼び出し側が form を指定しなければ、選択肢から決める
#   choice: 選択肢が 2 つ以上（［キャンセル］の右に選択肢のボタンを横に並べる）、danger: 1 つで Danger、normal: それ以外
function getConfirmForm {
    param (
        [object[]]$choices,
        [string]$form = ""
    )

    if ($form -ne "") {
        return $form
    }
    if (@($choices).Count -gt 1) {
        return "choice"
    }
    if (@($choices).Count -eq 1 -and [bool]@($choices)[0].Danger) {
        return "danger"
    }
    return "normal"
}

# 形ごとの窓の幅。選択肢のボタンを並べる choice は広く、ほかは 520
function getConfirmWidth {
    param (
        [string]$form
    )

    switch ($form) {
        "choice" { return 620 }
        default  { return 520 }
    }
}

# 暗幕にする部品（窓いっぱいに掛ける Border）。shared/ はツールの部品の名前を知らないので、起動側が渡す
$script:dialogScrim = $null
$script:dialogDepth = 0  # いま開いているダイアログ（showOwnedDialog）の数

function setDialogScrim {
    param (
        $scrim
    )

    $script:dialogScrim = $scrim
}

function showOwnedDialog {
    # 本体の窓を親にするダイアログを出す。出している間は、本体の上に暗幕を掛ける（閉じる・例外のときも外す）。
    # 戻り値は ShowDialog の戻り値（DialogResult）
    param (
        $dialog
    )

    # ダイアログの上にさらにダイアログ（メッセージなど）を重ねるときは、中のほうが閉じても暗幕は外さない（外側のダイアログがまだ開いている）
    enterDialogScrim
    try {
        return $dialog.ShowDialog()
    } finally {
        leaveDialogScrim
    }
}

function enterDialogScrim {
    # ダイアログを 1 つ開くときに、暗幕を掛ける（開いている数を 1 つ増やす）。showOwnedDialog と showWaitDialog が使う
    $script:dialogDepth++
    if ($null -ne $script:dialogScrim) {
        $script:dialogScrim.Visibility = "Visible"
    }
}

function leaveDialogScrim {
    # ダイアログを 1 つ閉じるときに、数を 1 つ減らす。開いているものが無くなったときだけ暗幕を外す
    $script:dialogDepth--
    if ($null -ne $script:dialogScrim -and $script:dialogDepth -le 0) {
        $script:dialogScrim.Visibility = "Collapsed"
    }
}

function showWaitDialog {
    # 待つ間のダイアログ（進み具合の棒・秒読みつき）を、閉じずに出す。showOwnedDialog と同じく本体の窓を親にして暗幕を掛けるが、
    # ShowDialog でなく Show で出すので、呼び出し側の処理は止まらない。利用者は閉じられず、呼び出し側が closeWaitDialog で閉じる。
    # 戻り値の入れ物を updateWaitDialog・closeWaitDialog に渡す。
    #   buttonText: 押せないボタンの文字。空なら出さない
    #   indeterminate: 件数が分からない（流れる棒）。false なら value（0 から 1）で出す
    param (
        [string]$heading,
        [string]$description = "",
        [string]$countdown = "",
        [string]$buttonText = "",
        [bool]$indeterminate = $true,
        [double]$value = 0,
        [string]$title = "",
        [System.Windows.Window]$owner = $window
    )

    $dialog = loadWindow "${sharedXamlDir}\dialog_wait.xaml"
    if ($title -ne "") {
        $dialog.Title = $title
    }
    $dialog.Owner = $owner
    $handle = @{ Dialog = $dialog; Open = $true }
    foreach ($name in @("HeadingText", "DescriptionText", "WaitBar", "CountdownText", "WaitButton")) {
        $handle[$name] = $dialog.FindName($name)
    }
    $handle.HeadingText.Text = $heading
    $dialog.Add_Closing({
        param ($sender, $e)
        if ($handle.Open) {
            $e.Cancel = $true  # 待つ間は閉じさせない（Alt+F4 でも）
        }
    }.GetNewClosure())
    updateWaitDialog $handle @{ Description = $description; Countdown = $countdown; ButtonText = $buttonText; Indeterminate = $indeterminate; Value = $value }
    enterDialogScrim
    try {
        $dialog.Show()
    } catch {
        $handle.Open = $false
        leaveDialogScrim
        throw
    }
    return $handle
}

function updateWaitDialog {
    # 待つ間のダイアログの中身を書き換える。content に入れたキー（Heading・Description・Countdown・ButtonText・Indeterminate・Value）だけ変える。
    # 説明・秒読み・ボタンは、空の文字にすると隠す
    param (
        $handle,
        [hashtable]$content
    )

    if ($null -eq $handle -or !$handle.Open) {
        return
    }
    if ($content.ContainsKey("Heading")) {
        $handle.HeadingText.Text = [string]$content.Heading
    }
    if ($content.ContainsKey("Description")) {
        $handle.DescriptionText.Text = [string]$content.Description
        $handle.DescriptionText.Visibility = if ([string]$content.Description -ne "") { "Visible" } else { "Collapsed" }
    }
    if ($content.ContainsKey("Countdown")) {
        $handle.CountdownText.Text = [string]$content.Countdown
        $handle.CountdownText.Visibility = if ([string]$content.Countdown -ne "") { "Visible" } else { "Collapsed" }
    }
    if ($content.ContainsKey("ButtonText")) {
        $handle.WaitButton.Content = [string]$content.ButtonText
        $handle.WaitButton.Visibility = if ([string]$content.ButtonText -ne "") { "Visible" } else { "Collapsed" }
    }
    if ($content.ContainsKey("Indeterminate")) {
        $handle.WaitBar.IsIndeterminate = [bool]$content.Indeterminate
    }
    if ($content.ContainsKey("Value")) {
        $handle.WaitBar.Value = [double]$content.Value
    }
}

function closeWaitDialog {
    # 待つ間のダイアログを閉じ、暗幕を外す（開いているものが残っていれば、外側が閉じるまで残す）。
    # 本体の窓を閉じるときは、これを先に呼ぶ（待つ間のダイアログ → 暗幕 → 本体の窓の順）。もう閉じていれば何もしない
    param (
        $handle
    )

    if ($null -eq $handle -or !$handle.Open) {
        return
    }
    $handle.Open = $false
    try {
        $handle.Dialog.Close()
    } finally {
        leaveDialogScrim
    }
}

function showConfirm {
    # 確認ダイアログ。「見出し（何をするか）」「こうなります（何が消えて何が残るか）」「選択肢のボタン」で、
    # 文章を読まなくても押す前に結果が分かるようにする。選んだ Value を返す（キャンセル・閉じるは $null）。
    #   choices: @{ Text = "削除する"; Value = "delete"; Danger = $true; Careful = $true } の配列
    #            ［キャンセル］の右に横に並べる。最後の 1 つが主なボタン（Danger は赤）。ほかは枠だけのボタン
    #            Danger・Careful は、うっかり Enter で進まないようキャンセルを既定にする
    #   facts:   factGone / factKept / factNext で作った行
    #   hint:    読まなくても操作できる補足（別のやり方の案内など。見出しの下に淡く出す）
    #   detail:  詳しい内容（エラーの文面など）。枠の中に、選べる文字で出す
    #   title:   窓の題（OS のタイトルバー）。既定はアプリ名
    #   form:    normal・danger・choice。省略すると選択肢から決める（getConfirmForm）。幅と、danger の赤い印・赤い実行ボタンが変わる
    param (
        [string]$heading,
        [object[]]$choices,
        [object[]]$facts = @(),
        [string]$hint = "",
        [string]$detail = "",
        [string]$cancelText = "キャンセル",
        [string]$title = "",
        [string]$form = "",
        [System.Windows.Window]$owner = $window
    )

    $form = getConfirmForm $choices $form
    $dialog = loadWindow "${sharedXamlDir}\dialog_confirm.xaml"
    $dialog.Title = if ($title -ne "") { $title } else { ${appTitle} }
    $dialog.Width = getConfirmWidth $form
    $dialog.Owner = $owner
    $ctrl = @{}
    foreach ($name in @("HeadingIcon", "HeadingText", "FactsPanel", "FactsList", "DetailBox", "DetailText", "HintText", "ButtonPanel")) {
        $ctrl[$name] = $dialog.FindName($name)
    }
    $chosen = @{ Value = $null }  # ボタンの Click から書き換えるため、入れ物ごとクロージャに渡す

    $ctrl.HeadingText.Text = $heading
    # 見出しの左のアイコン。取り消せない操作（danger）は誤りと同じ赤い「!」、ほかの確認は「?」（種類は message_view.ps1）
    setDialogLook $dialog (getMessageLook $(if ($form -eq "danger") { "Error" } else { "Question" }))
    if ($facts.Count -gt 0) {
        $ctrl.FactsList.ItemsSource = $facts
        $ctrl.FactsPanel.Visibility = "Visible"
    }
    if ($detail -ne "") {
        $ctrl.DetailText.Text = $detail
        $ctrl.DetailBox.Visibility = "Visible"
    }
    if ($hint -ne "") {
        $ctrl.HintText.Text = $hint
        $ctrl.HintText.Visibility = "Visible"
    }

    $onChoice = {
        param ($sender, $e)
        $chosen.Value = $sender.Tag
        $dialog.DialogResult = $true
    }.GetNewClosure()
    $focusTarget = $null
    $cautious = $false
    $cancel = New-Object System.Windows.Controls.Button
    $cancel.Content = $cancelText
    $cancel.IsCancel = $true
    $ctrl.ButtonPanel.Children.Add($cancel) | Out-Null  # ［キャンセル］は選択肢のボタンの左
    for ($i = 0; $i -lt @($choices).Count; $i++) {
        $choice = @($choices)[$i]
        $button = New-Object System.Windows.Controls.Button
        $button.Tag = $choice.Value
        $button.Add_Click($onChoice)
        $button.Content = $choice.Text
        $isMain = ($i -eq @($choices).Count - 1)
        if ($isMain) {
            $button.Style = $dialog.FindResource($(if ($choice.Danger) { "Danger.Filled" } else { "Primary" }))
            $cautious = [bool]$choice.Danger -or [bool]$choice.Careful
            $button.IsDefault = !$cautious -and @($choices).Count -eq 1
        }
        $ctrl.ButtonPanel.Children.Add($button) | Out-Null
        if ($null -eq $focusTarget) {
            $focusTarget = $button
        }
    }
    if ($cautious -or @($choices).Count -gt 1) {
        # 消す操作・選択肢が複数の操作は、うっかり Enter で進まないようキャンセルを既定にする
        $cancel.IsDefault = $true
        $focusTarget = $cancel
    }

    $dialog.Add_ContentRendered({ $focusTarget.Focus() | Out-Null }.GetNewClosure())
    $null = showOwnedDialog $dialog
    return $chosen.Value
}

function showErrorDialog {
    # エラーの知らせ。見出し・エラーの文面・［内容をコピー］［ログを開く］［閉じる］。
    # logFile を渡さないときは［ログを開く］を出さない（開く先が無いため）
    param (
        [string]$heading,
        [string]$detail,
        [string]$logFile = "",
        [System.Windows.Window]$owner = $window
    )

    $dialog = loadWindow "${sharedXamlDir}\dialog_confirm.xaml"
    $dialog.Title = "エラー"
    $dialog.Width = getConfirmWidth "error"
    if ($null -ne $owner) {
        $dialog.Owner = $owner
    }
    setDialogLook $dialog (getMessageLook "Error")
    $dialog.FindName("HeadingText").Text = $heading
    $dialog.FindName("DetailText").Text = $detail
    $dialog.FindName("DetailBox").Visibility = "Visible"
    $panel = $dialog.FindName("ButtonPanel")

    $copy = New-Object System.Windows.Controls.Button
    $copy.Content = "内容をコピー"
    $copy.Add_Click({
        try {
            [System.Windows.Clipboard]::SetText($detail)
        } catch {
            # クリップボードを他が使っているときは、あきらめる（もう一度押せる）
        }
    }.GetNewClosure())
    $panel.Children.Add($copy) | Out-Null
    if ($logFile -ne "") {
        $open = New-Object System.Windows.Controls.Button
        $open.Content = "ログを開く"
        $open.Add_Click({
            if (Test-Path -LiteralPath $logFile) {
                Start-Process -FilePath "$env:SystemRoot\System32\notepad.exe" -ArgumentList "`"$logFile`""
            }
        }.GetNewClosure())
        $panel.Children.Add($open) | Out-Null
    }
    $close = New-Object System.Windows.Controls.Button
    $close.Content = "閉じる"
    $close.Style = $dialog.FindResource("Primary")
    $close.IsDefault = $true
    $close.IsCancel = $true
    $panel.Children.Add($close) | Out-Null
    $null = showOwnedDialog $dialog
}

# 予期しない例外を繰り返し知らせないための、同じ例外の見分け（型・メッセージ・発生場所）と抑え方の状態。
# registerUnhandledErrorHandler から reportUnexpectedError を呼ぶときだけ効かせる（safe・Closing の呼び出しは見ない）
$script:unhandledErrorTable = [ordered]@{}
${maxUnhandledErrorKeys} = 100  # メッセージにパスなどが入ると際限なく増えるため、古いものから消す
$script:unhandledDialogShowing = $false
# 時刻の取得はここから行う（テストで差し替えて、60 秒の判定を進められるようにする）
$script:reportUnexpectedErrorNow = { Get-Date }

function reportUnexpectedError {
    # 予期しない例外を記録・ステータス・ダイアログで知らせる（内容・順は今までの safe の catch と同じ）。
    # -unhandled のときだけ、同じ例外（型・メッセージ・発生場所が同じ）の繰り返しを抑える。
    #   ダイアログ：画面を開いている間に 1 回だけ出す。別の例外でも、ダイアログを出している間は重ねない
    #   記録：60 秒に 1 回まで。飛ばした間の回数を、次に記録するときに添える
    param (
        [string]$context,
        [System.Management.Automation.ErrorRecord]$record,
        [switch]$unhandled
    )

    $message = $record.Exception.Message
    $logContext = $context
    $skipLog = $false
    $skipDialog = $false
    $entry = $null

    if ($unhandled) {
        $key = "$($record.Exception.GetType().FullName)|$message|$($record.InvocationInfo.PositionMessage)"
        if (!$script:unhandledErrorTable.Contains($key)) {
            if ($script:unhandledErrorTable.Count -ge ${maxUnhandledErrorKeys}) {
                $script:unhandledErrorTable.Remove(@($script:unhandledErrorTable.Keys)[0])
            }
            $script:unhandledErrorTable[$key] = @{ DialogShown = $false; LastLogged = $null; Skipped = 0 }
        }
        $entry = $script:unhandledErrorTable[$key]

        $now = & $script:reportUnexpectedErrorNow
        if ($null -eq $entry.LastLogged -or ($now - $entry.LastLogged).TotalSeconds -ge 60) {
            if ($entry.Skipped -gt 0) {
                $logContext = "${context}（前の記録の後に同じ例外が$($entry.Skipped)回起きました）"
            }
            $entry.LastLogged = $now
            $entry.Skipped = 0
        } else {
            $entry.Skipped++
            $skipLog = $true
        }
        $skipDialog = $entry.DialogShown -or $script:unhandledDialogShowing
    }

    if (!$skipLog) {
        writeErrorLog $logContext $record
    }
    setStatus "エラーが発生しました：$message"
    if ($skipDialog) {
        return
    }
    $heading = "予期しないエラーが起きました。"
    $logFile = getGuiErrorLogFile
    if ($unhandled) {
        $entry.DialogShown = $true
        $script:unhandledDialogShowing = $true
        try {
            showErrorDialog $heading "$($record.Exception.GetType().FullName): $message" $logFile
        } finally {
            $script:unhandledDialogShowing = $false
        }
        return
    }
    showErrorDialog $heading "$($record.Exception.GetType().FullName): $message" $logFile
}

function registerUnhandledErrorHandler {
    # 画面のスレッドの Dispatcher で捕まえていない例外を受け、画面を落とさず reportUnexpectedError で知らせる。
    # 登録した処理（デリゲート）を返す（テストで Remove_UnhandledException するため）
    param (
        [System.Windows.Threading.Dispatcher]$dispatcher
    )

    $handler = {
        param ($sender, $e)
        $e.Handled = $true
        try {
            $exception = $e.Exception
            # WPF がハンドラーを Delegate.DynamicInvoke で呼ぶ経路では、これに包まれて届く
            while ($exception -is [System.Reflection.TargetInvocationException] -and $exception.InnerException) {
                $exception = $exception.InnerException
            }
            if ($exception -is [System.Management.Automation.IContainsErrorRecord]) {
                # PowerShell のスクリプトブロックが投げた例外は、元の ErrorRecord をそのまま使う
                $record = $exception.ErrorRecord
            } else {
                # WPF が投げた .NET の例外には ErrorRecord が無いため、記録に残せるよう作る
                $record = New-Object System.Management.Automation.ErrorRecord(
                    $exception, $exception.GetType().FullName, ([System.Management.Automation.ErrorCategory]::NotSpecified), $null)
            }
            reportUnexpectedError "画面の操作中" $record -unhandled
        } catch {
            # 知らせる処理そのものが失敗しても、画面は落とさない
        }
    }
    $dispatcher.Add_UnhandledException($handler)
    return $handler
}

function safe {
    # イベント処理で例外が起きても画面を落とさず、内容を表示する
    param (
        [scriptblock]$block
    )

    try {
        & $block
    } catch {
        reportUnexpectedError "画面の操作中" $_
    }
}

function newTimer {
    param (
        [int]$milliseconds,
        [scriptblock]$onTick
    )

    $timer = New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval = [TimeSpan]::FromMilliseconds($milliseconds)
    $timer.Add_Tick($onTick)
    return $timer
}

function formatTime {
    # 当日なら HH:mm、それ以前は M/d HH:mm
    param (
        $time
    )

    if ($null -eq $time) {
        return ""
    }
    if ($time.Date -eq (Get-Date).Date) {
        return $time.ToString("H:mm")
    }
    return $time.ToString("M/d H:mm")
}

# ---- 別スレッドの処理（インデックスの件数など） ----

# 仕事を受けるスレッド（BackgroundQueue）は、読み込み口（gui_main.ps1）が setBackgroundQueue で渡す。
# 仕事のスクリプトでは、そのツールの関数（lib.ps1）をそのまま使える（スレッドを始めたときに 1 回だけ読み込む）
$script:backgroundQueue = $null

function setBackgroundQueue {
    # 既定の仕事の列を登録する（gui_main.ps1 が起動時に 1 回呼ぶ）
    param ($queue)
    $script:backgroundQueue = $queue
}

# ネットワークのパスだけを調べる専用の列。届かない共有で止まっても、プレビュー・状態の読み直し（$script:backgroundQueue）が
# 待たされないようにする。初めて使うときにだけ作る（ネットワークのパスが無い利用者には、スレッドも lib.ps1 の読み込みも増えない）。
# 列を作る式（BackgroundQueue の生成）は gui.ps1 が持ち、setNetworkQueueFactory で渡す
# （shared/ が tebunko/gui.ps1 の変数に直接頼らないようにするため）。
$script:networkQueue = $null
$script:networkQueueFactory = $null

function setNetworkQueueFactory {
    # ネットワークを調べる列を作る式を登録する（gui.ps1 が起動時に 1 回呼ぶ）
    param ([scriptblock]$factory)
    $script:networkQueueFactory = $factory
}

function ensureNetworkQueue {
    # ネットワークを調べる列を、初めて使うときだけ作って返す。両方のスレッドを空の仕事で温める
    # （1 回目の［開く］が冷えたスレッドに当たって lib.ps1 の読み込みを待たないようにする）
    if ($null -ne $script:networkQueue) {
        return $script:networkQueue
    }
    if ($null -eq $script:networkQueueFactory) {
        throw "ensureNetworkQueue: setNetworkQueueFactory が呼ばれていない"
    }
    $script:networkQueue = & $script:networkQueueFactory
    # 温める回数は、作った列自身のスレッドの数から取る（gui.ps1 の ${backgroundWorkers} に頼らない。
    # 無いと 0 回になって黙って温めないままになるため）
    for ($i = 0; $i -lt $script:networkQueue.Pool.Size; $i++) {
        $script:networkQueue.Post('$null', @(), $null)
    }
    $script:jobTimer.Start()
    return $script:networkQueue
}

function startJob {
    # scriptBlock を別スレッドで実行し、終わったら画面のスレッドで onDone { param($output, $errorText) } を呼ぶ。
    #   queue: "default"（既定。今までの列）・"network"（届かない共有を調べる専用の列。無ければここで作る）
    param (
        [scriptblock]$scriptBlock,
        [object[]]$arguments,
        [scriptblock]$onDone,
        [string]$queue = "default"
    )

    $target = if ($queue -eq "network") { ensureNetworkQueue } else { $script:backgroundQueue }
    $target.Post($scriptBlock.ToString(), $arguments, $onDone)
    $script:jobTimer.Start()
}

# 終わった仕事を受け取る間隔。プレビューの読み込みも通るため短くする（両方の列に仕事が無ければ止める）
$script:jobTimer = newTimer 50 {
    safe {
        $pending = $script:backgroundQueue.Poll()
        if ($null -ne $script:networkQueue) {
            $pending += $script:networkQueue.Poll()
        }
        if ($pending -eq 0) {
            $script:jobTimer.Stop()
        }
    }
}
# DataGrid の共通の部品（画面層）。このツール固有の名前・文言は持たない。

function getDataGridRowAt {
    # マウスの下（またはイベントの発生元）の行（DataGridRow）。列見出し・スクロールバー・行の外（余白）では $null
    param (
        $source
    )

    $element = $source
    while ($element -and $element -isnot [System.Windows.Controls.DataGridRow]) {
        if ($element -is [System.Windows.Controls.Primitives.DataGridColumnHeader] -or $element -is [System.Windows.Controls.Primitives.ScrollBar]) {
            return $null
        }
        $element = $(if ($element -is [System.Windows.Media.Visual]) { [System.Windows.Media.VisualTreeHelper]::GetParent($element) } else { $null })
    }
    return $element
}

    setDialogScrim $ui.ScrimOverlay
    # safe で包んでいない処理（PreviewKeyDown・Closing・活性化のタイマーなど）が
    # 投げた例外や、XAML の描画中に WPF が投げる例外を、画面のスレッドの Dispatcher で受ける
    [void](registerUnhandledErrorHandler $window.Dispatcher)
    # 画面から頼む短い仕事（startJob）のスレッド。長い仕事（件数の数え上げ等）の間もプレビューが待たないよう 2 つにする。
    # 各スレッドは最初の仕事の前に lib.ps1 を 1 回だけ読み込み、ワークスペースを決める
    # （docs/design/structure/threads.md「スレッドの一覧」）。
    # 列を作る式は 1 か所にまとめ、既定の列はここで作り、ネットワークの列は shell.ps1 に式（factory）だけ渡して
    # 初めて使うときに作らせる（届かない共有が無い利用者には、スレッドも lib.ps1 の読み込みも増えない）
    $backgroundLoad = getPartLoad lib -then "initWorkspace"
    $newBackgroundQueue = { [BackgroundQueue]::new(${backgroundWorkers}, $backgroundLoad, $Host) }
    setBackgroundQueue (& $newBackgroundQueue)
    setNetworkQueueFactory $newBackgroundQueue

# startGui の一部: 画面の中身の読み込みの表。startGui の中で読み込む（読み込むファイルにイベントの登録まで入っている）。
# 画面を足すときは、ここに読み込みの行を足す。services.ps1 の後に読み込む。

# フォルダ選択（Windows 標準のダイアログ）と、フォルダのドラッグ＆ドロップ。

${folderPickOption} = [uint32]0x20                  # FOS_PICKFOLDERS（ファイルではなくフォルダを選ぶ）
${folderPickCanceled} = [int]0x800704C7             # HRESULT_FROM_WIN32(ERROR_CANCELLED)（［キャンセル］で閉じた）
${folderPickFileName} = "フォルダーの選択"          # 予備のダイアログのファイル名の欄に入れておく名前

function selectFolder {
    # Windows 標準のエクスプローラー形式のダイアログでフォルダを選んでもらい、選んだフォルダを返す（キャンセルなら $null）。
    #   description はタイトルバーに出す。initialPath が無ければ、その上の今もあるフォルダから開く
    #   （ネットワークのパスは、画面のスレッドで有無を調べない。knownExisting が $true のときだけ、
    #    調べずにそのまま開始フォルダにする。それ以外は OS の既定の場所で開く）。
    #   knownExisting: initialPath が今もあると分かっているとき（直前の refreshFolderStatus の結果など）に $true にする。
    # ※エクスプローラー形式のダイアログ（COM の IFileOpenDialog）をフォルダ選択で開くには、
    #   インターフェースの定義が要る。自分で定義すると実行時コンパイル（csc.exe）が要るため（12.2）、
    #   WinForms（読み込み済み）が内部に持つ定義 FileDialogNative+IFileDialog をリフレクションで呼ぶ。
    #   内部の型（NonPublic）を呼ぶのはここだけ（tests\meta\safety.Tests.ps1 が確かめる）。
    #   内部の型が使えないとき（.NET の変更など）は、同じ見た目のファイルを開くダイアログで、フォルダの中に入って選んでもらう。
    param (
        [string]$description,
        [string]$initialPath,
        [System.Windows.Window]$owner = $window,
        [bool]$knownExisting = $false
    )

    $normalized = normalizeFolderPath $initialPath
    $start = if ($knownExisting -and $normalized -ne "") { $normalized } else { getExistingAncestorFolder $normalized $true }
    $hwnd = [IntPtr]::Zero
    if ($owner) {
        $hwnd = (New-Object System.Windows.Interop.WindowInteropHelper $owner).Handle
    }
    try {
        return showFolderPicker $description $start $hwnd
    } catch {
        writeErrorLog "フォルダ選択（標準のフォルダ選択を開けないため、ファイルを開くダイアログで選んでもらう）" $_
    }
    return showFolderByFileDialog $description $start $hwnd
}

function showFolderPicker {
    # エクスプローラー形式のダイアログ（IFileOpenDialog をフォルダ選択にしたもの）。開けなければ例外を投げる
    param (
        [string]$description,
        [string]$start,
        [IntPtr]$hwnd
    )

    $flags = [System.Reflection.BindingFlags]"Instance,Public,NonPublic"
    $fileDialogType = [System.Windows.Forms.FileDialog]
    $assembly = $fileDialogType.Assembly
    $nativeType = $assembly.GetType("System.Windows.Forms.FileDialogNative+IFileDialog", $true)
    $itemType = $assembly.GetType("System.Windows.Forms.FileDialogNative+IShellItem", $true)
    $nameType = $assembly.GetType("System.Windows.Forms.FileDialogNative+SIGDN", $true)

    $dialog = New-Object System.Windows.Forms.OpenFileDialog
    $dialog.Title = $description
    $dialog.InitialDirectory = $start

    $path = ""
    $native = $fileDialogType.GetMethod("CreateVistaDialog", $flags).Invoke($dialog, $null)
    try {
        # タイトル・開始フォルダなどを WinForms に設定させ、フォルダ選択の指定を足す
        $fileDialogType.GetMethod("OnBeforeVistaDialog", $flags).Invoke($dialog, @($native)) | Out-Null
        $options = [uint32]$fileDialogType.GetMethod("get_Options", $flags).Invoke($dialog, $null)
        $nativeType.GetMethod("SetOptions").Invoke($native, @($options -bor ${folderPickOption})) | Out-Null
        $hr = [int]$nativeType.GetMethod("Show").Invoke($native, @($hwnd))
        if ($hr -eq ${folderPickCanceled}) {
            return $null
        }
        if ($hr -ne 0) {
            throw "フォルダ選択のダイアログがエラーを返しました（0x$($hr.ToString('X8'))）"
        }
        # 選んだフォルダ（IShellItem）のファイルシステムのパス（SIGDN_FILESYSPATH）を読む。
        # out 引数は、渡した配列の同じ位置に入って戻る
        $resultArgs = [object[]]@($null)
        $nativeType.GetMethod("GetResult").Invoke($native, $resultArgs) | Out-Null
        $item = $resultArgs[0]
        try {
            $nameArgs = [object[]]@([Enum]::Parse($nameType, "SIGDN_FILESYSPATH"), $null)
            $itemType.GetMethod("GetDisplayName").Invoke($item, $nameArgs) | Out-Null
            $path = normalizeFolderPath ([string]$nameArgs[1])
        } finally {
            [System.Runtime.InteropServices.Marshal]::ReleaseComObject($item) | Out-Null
        }
    } finally {
        [System.Runtime.InteropServices.Marshal]::ReleaseComObject($native) | Out-Null
    }
    if ($path -eq "") {
        return $null
    }
    return $path
}

function showFolderByFileDialog {
    # 予備のフォルダ選択（標準のフォルダ選択を開けないときに使う）。見た目は同じエクスプローラー形式で、
    # 公開の API だけを使う。ファイルは出さず、選びたいフォルダの中に入って［開く］を押してもらう
    param (
        [string]$description,
        [string]$start,
        [IntPtr]$hwnd
    )

    $dialog = New-Object System.Windows.Forms.OpenFileDialog
    $dialog.Title = "$description（フォルダの中に入って［開く］を押してください）"
    $dialog.InitialDirectory = $start
    $dialog.FileName = ${folderPickFileName}
    $dialog.Filter = "フォルダー|*.tebunko-folder"   # どのファイルにも当たらない条件にして、フォルダだけを出す
    $dialog.CheckFileExists = $false
    $dialog.ValidateNames = $false
    $dialog.AddExtension = $false
    $ownerWindow = New-Object System.Windows.Forms.NativeWindow
    if ($hwnd -ne [IntPtr]::Zero) {
        $ownerWindow.AssignHandle($hwnd)
    }
    try {
        $result = $dialog.ShowDialog($ownerWindow)
    } finally {
        $ownerWindow.ReleaseHandle()
        $dialog.Dispose()
    }
    if ($result -ne [System.Windows.Forms.DialogResult]::OK) {
        return $null
    }
    return normalizeFolderPath ([System.IO.Path]::GetDirectoryName($dialog.FileName))
}

function selectZipFile {
    # インデックスのエクスポートの zip を選んでもらう（Windows 標準のファイルを開くダイアログ）。選んだファイルを返す（キャンセルは $null）
    param (
        [string]$description,
        [System.Windows.Window]$owner = $window
    )

    $dialog = New-Object System.Windows.Forms.OpenFileDialog
    $dialog.Title = $description
    $dialog.Filter = "インデックスの zip (*.zip)|*.zip|すべてのファイル (*.*)|*.*"
    $dialog.CheckFileExists = $true
    $hwnd = [IntPtr]::Zero
    if ($owner) {
        $hwnd = (New-Object System.Windows.Interop.WindowInteropHelper $owner).Handle
    }
    $ownerWindow = New-Object System.Windows.Forms.NativeWindow
    if ($hwnd -ne [IntPtr]::Zero) {
        $ownerWindow.AssignHandle($hwnd)
    }
    try {
        $result = $dialog.ShowDialog($ownerWindow)
    } finally {
        $ownerWindow.ReleaseHandle()
        $dialog.Dispose()
    }
    if ($result -ne [System.Windows.Forms.DialogResult]::OK) {
        return $null
    }
    return $dialog.FileName
}

function getDroppedFolders {
    param (
        [System.Windows.DragEventArgs]$e
    )

    if (!$e.Data.GetDataPresent([System.Windows.DataFormats]::FileDrop)) {
        return @()
    }
    return @($e.Data.GetData([System.Windows.DataFormats]::FileDrop) | Where-Object { Test-Path -LiteralPath $_ -PathType Container })
}

function onFolderDragOver {
    param ($sender, [System.Windows.DragEventArgs]$e)

    $e.Effects = if ((getDroppedFolders $e).Count -gt 0) { "Copy" } else { "None" }
    $e.Handled = $true
}

# ［インデックス管理］タブの判断: 一覧・選択・ボタンの可否・状態の文言・高速検索の列。
# 画面に触らないため、そのままテストできる（tests\tebunko\ui\index\index_list_view.Tests.ps1）。

function getUsedIndexNames {
    # 一覧のインデックス名の集合（大文字・小文字を区別しない）。except に渡した行の名前は含めない
    param (
        $items,
        $except = $null
    )

    $used = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::OrdinalIgnoreCase)
    foreach ($item in $items) {
        if ($item -ne $except -and $item.Name) {
            [void]$used.Add($item.Name)
        }
    }
    # HashSet をそのまま return すると PowerShell が中身を展開してしまい（0 件なら $null、1 件なら文字列）、
    # 受け取った側の .Contains が落ちる・部分一致になる。, を付けて集合のまま返す
    return , $used
}

function getIndexNavBadge {
    # ナビの［インデックス管理］の横に出す小さな印。更新中は「● N%」（割合が分からないうちは「●」）、
    # 中断中は「中断」、更新に失敗したファイルがあるときは「失敗」。どれでもなければ出さない（Text が空）。
    # Kind は色の種類（Run = 更新中 / Warn = 注意）
    param (
        [bool]$indexing,
        [double]$ratio,     # 更新の進み（0～1。分からないときは負の値）
        [int]$pending,      # まだ更新していないファイルの数
        [int]$failed        # 更新に失敗したファイルの数
    )

    if ($indexing) {
        $text = if ($ratio -ge 0) { "● {0}%" -f [int][Math]::Floor([Math]::Min($ratio, 1.0) * 100) } else { "●" }
        return @{ Text = $text; Kind = "Run"; ToolTip = "インデックスを更新しています" }
    }
    if ($pending -gt 0) {
        return @{ Text = "中断"; Kind = "Warn"; ToolTip = "更新が途中で止まっています（残り ${pending} 件）" }
    }
    if ($failed -gt 0) {
        return @{ Text = "失敗"; Kind = "Warn"; ToolTip = "更新に失敗したファイルがあります" }
    }
    return @{ Text = ""; Kind = ""; ToolTip = "" }
}

function getIndexAddedStatus {
    # インデックスを追加したときのステータス。フォルダの有無によらず同じ文言にする（有無は一覧の列で分かる）
    param (
        [string]$name
    )

    return "インデックス [${name}] を追加しました。［すべて更新］を押すと中身を更新します"
}

function getFailedFileCheckingStatus {
    # 取り込みに失敗したファイルのダブルクリックで、元のファイルを確かめている間のステータス
    param (
        [string]$path
    )

    return "元のファイルを確かめています…：${path}"
}

function getFailedFileUnreachableStatus {
    # 同じ操作で、接続できないと分かったときのステータス（見つからないときとは別の文言）
    param (
        [string]$path
    )

    return "元のフォルダに接続できません：${path}"
}

function getFailedFileOtherStatus {
    # 同じ操作で、接続できる・できないのどちらでもない理由（アクセス拒否・一覧に無いネットワークのエラーなど）で
    # 確かめられなかったときのステータス。フォルダをたどらず、文言だけ出す
    param (
        [string]$message
    )

    return "元のファイルを確かめられませんでした：${message}"
}

function getIndexNamingStatus {
    # 名前の決まっていないインデックスに名前を付けている間（ネットワークのワークスペースでは裏で行う）のステータス
    return "インデックス名を決めています…（共有フォルダに接続できないときは、しばらくかかります）"
}

function getIndexNamingFailedStatus {
    # インデックス名を決められなかったときのステータス
    param (
        [string]$errorText
    )

    return "インデックス名を決められませんでした：${errorText}"
}

function getIndexTabButtonsEnabled {
    # 排他（getIndexJobBlocker の結果）と、一覧で選んでいる行の有無から、［インデックス管理］の各ボタンの可否を返す。
    #   New/Edit/Remove/ChangeFolder: ［＋ フォルダを追加］・詳細の名前とフォルダパスの欄（Edit。欄で直接直す）・［削除］・フォルダパスの［変更…］（Edit と同じ）/ Export/Import: ［エクスポート…］［インポート…］
    # 名前とフォルダパスの欄・［削除］［エクスポート…］は、1 件選んでいるときだけ有効
    # （［すべて更新］は updateIndexingButton が、［設定］の［変更…］は押したときに testWorkspaceChangeable が、
    # 同じ getIndexJobBlocker の結果で止める）
    param (
        [string]$blocker,
        [bool]$hasSelection
    )

    $free = ($blocker -eq "")
    return @{
        New = $free; Edit = ($free -and $hasSelection); Remove = ($free -and $hasSelection)
        ChangeFolder = ($free -and $hasSelection)
        Export = ($free -and $hasSelection); Import = $free
    }
}

function getIndexStatusHelpText {
    # 一覧の「ステータス」列の見出しのツールヒント（状態の名前と意味。行のバッジの名前と同じ言葉を使う）
    return @(
        "検索の準備の状態です。"
        "・最新: 検索できます"
        "・要更新: 前回の更新のあとにファイルが変わっています"
        "・更新中: 更新しています"
        "・警告: 読み取れないファイルがあります（それ以外のファイルは検索できます）"
        "・エラー: フォルダが見つかりません"
        "・未作成: まだ更新していません"
    )
}

function getIndexCheckedItems {
    # 一覧でチェックを付けている行（［アクション ▼］の対象・「N 件を選択中」の数・全選択の状態の元）。
    # チェックは一時の選択で、保存しない（初めは全部外れ。設定の enabled とは別のもの）
    param (
        [object[]]$items
    )

    return @($items | Where-Object { $null -ne $_ -and $_.Checked })
}

function getIndexSelectionView {
    # 一覧の見出しの全選択と、見出しの横の「N / M 件を選択中」。@{ CountText; AllChecked }
    #   AllChecked: すべて選んでいれば $true、1 件も選んでいなければ $false、一部だけなら $null（横棒）
    param (
        [int]$total,    # 一覧の件数
        [int]$checked   # チェックを付けている件数
    )

    $countText = if ($checked -ge 1) { "{0:#,0} / {1:#,0} 件を選択中" -f $checked, $total } else { "" }
    $all = if ($total -eq 0 -or $checked -eq 0) { $false } elseif ($checked -ge $total) { $true } else { $null }
    return @{ CountText = $countText; AllChecked = $all }
}

function getIndexActionsEnabled {
    # ［アクション ▼］のメニューの項目の可否。@{ Update; Export; Import; Delete }
    # ［インポート…］は選ばなくても使える。［更新］［エクスポート…］［削除…］は 1 件以上チェックしていると使える（2 件以上はまとめて行う）。
    # 動いている処理があれば（blocker は getIndexJobBlocker の結果）、すべて使えない
    param (
        [string]$blocker,
        [int]$checked
    )

    $free = ($blocker -eq "")
    return @{
        Update = ($free -and $checked -ge 1)
        Export = ($free -and $checked -ge 1)
        Import = $free
        Delete = ($free -and $checked -ge 1)
    }
}

function getIndexRowMenuEnabled {
    # 行の右クリックのメニューの項目の可否。@{ Update; OpenFolder; Export; Delete }。対象は押した行（右クリックした行を選んでから開く）
    #   Update: 行の右端の［更新］と同じ判断（getIndexRowActions）。更新中の行・動いている処理があるときは使えない（失敗のある警告の行は使える）
    #   Export/Delete: 1 件に効く判断（getIndexTabButtonsEnabled）。OpenFolder: 動いている処理があっても使える（元のフォルダの場所があれば）
    # 行が無いとき（hasRow が false）は、すべて使えない
    param (
        [string]$blocker,
        [bool]$hasRow,
        [string]$level,       # 押した行の getIndexRowView の Level
        [bool]$hasPath        # 押した行の元のフォルダの場所があるか
    )

    $rowAction = getIndexRowActions $level $blocker
    $buttons = getIndexTabButtonsEnabled $blocker $hasRow
    return @{
        Update = ($hasRow -and $rowAction.Action -eq "Update" -and $rowAction.UpdateEnabled)
        OpenFolder = ($hasRow -and $hasPath)
        Export = $buttons.Export
        Delete = $buttons.Remove
    }
}

function getIndexSourceFolderStatus {
    # ［元のフォルダを開く］で、フォルダの場所を確かめた結果のステータス。kind は Empty（記録が無い）/ Checking / Missing / Unreachable / Other
    param (
        [string]$kind,
        [string]$path,
        [string]$message = ""
    )

    switch ($kind) {
        "Empty" { return "元のフォルダの場所が分かりません（元のフォルダの記録がありません）" }
        "Checking" { return "元のフォルダを確かめています…：${path}" }
        "Missing" { return "元のフォルダが見つかりません（移動・削除された可能性があります）：${path}" }
        "Unreachable" { return getFailedFileUnreachableStatus $path }
        default { return "元のフォルダを確かめられませんでした：${message}" }
    }
}

function getIndexSourceFolderKind {
    # ［元のフォルダを開く］で getPathState が返した結果を、次にすることに分ける。
    # Open（フォルダが見つかった。エクスプローラーで開く）/ Unreachable / Other / Missing（見つからない。ファイルだったときも）。
    # Open 以外は、そのまま getIndexSourceFolderStatus の kind に渡す
    param (
        $state
    )

    if ($state.State -eq ${pathStateFound}) {
        return $(if ($state.IsDirectory) { "Open" } else { "Missing" })
    }
    switch ($state.State) {
        ${pathStateUnreachable} { return "Unreachable" }
        ${pathStateOther} { return "Other" }
        default { return "Missing" }
    }
}

function getIndexRowActions {
    # 一覧の行の右端のボタン。@{ Action（Update / Stop / None）; UpdateEnabled }
    # 更新中の行には［中止］（回ごと止める）、エラー（Ng）の行には何も出さず（場所は空けておく）、ほかの行（失敗のある警告の行を含む）には［更新］を出す。
    # ［更新］は、動いている処理があれば（blocker は getIndexJobBlocker の結果）使えない（更新中はほかの行も押せない）
    param (
        [string]$level,           # getIndexRowView の Level
        [string]$blocker,
        [bool]$exporting = $false # エクスポート中の行か（止められないので、［中止］も［更新］も出さない）
    )

    if ($exporting) {
        return @{ Action = "None"; UpdateEnabled = $false }
    }
    $action = switch ($level) { "Run" { "Stop" } "Ng" { "None" } default { "Update" } }
    return @{ Action = $action; UpdateEnabled = ($blocker -eq "") }
}

function selectFailedRowsForIndex {
    # 「更新に失敗したファイル」に出す行を、詳細に出しているインデックスの分だけにする。
    # indexName が空（行を選んでいない・2 件以上にチェックしている）ときは、全部をそのまま返す。
    # 失敗の行の相対パス（work\index からの相対）の先頭の名前が、indexName と同じ（大文字・小文字は区別しない）ものだけを残す。
    # 前方一致では絞らない（「営業」で「営業部」の行を拾わない）
    param (
        [object[]]$failedRows,  # getIndexingState の FailedRows（相対パスを持つ行）
        [string]$indexName
    )

    $rows = @($failedRows | Where-Object { $null -ne $_ })
    if (!$indexName) { return $rows }
    $prefix = $indexName + "\"
    return @($rows | Where-Object { ([string]$_.相対パス).StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase) })
}

function getIndexRowView {
    # 一覧の「ステータス」列（本文の更新の状態）の文言・補足・ツールヒント・色の区分を返す。@{ Text; Sub; ToolTip; Level }
    #   Text は状態の名前だけ（数字を含めない）。Sub は、バッジの右に小さく出す補足（更新中の「45%」、途中で止まったときの「残り N 件」。無ければ空文字列）
    #   stat     : getIndexStats のそのインデックスの値（Total; Done; Pending; Failed）。無ければ $null
    #   indexing : インデックス作成中か
    #   enabled  : 設定の enabled（［すべて更新］で更新する対象か。画面にチェックは出さない）
    #   ratio    : 更新全体の進み（0～1。分からないときは負の値）。更新中の補足に「45%」と出し、棒の長さにする
    #   inRound  : 今の回で更新するインデックスか（選んだものだけの回では、選ばなかった行は $false）
    #   exporting: エクスポートで書き出している最中の行か（バッジは「エクスポート中」。更新中と同じ Run の色。棒は出さない）
    # 返す値の Percent は棒の長さ（0～100）。更新中でなければ 0
    param (
        $stat,
        [bool]$indexing = $false,
        [bool]$enabled = $true,
        [double]$ratio = -1.0,
        [bool]$inRound = $true,
        [bool]$exporting = $false
    )

    if ($exporting) {
        return @{ Text = "エクスポート中"; Sub = ""; Level = "Run"; Percent = 0; ToolTip = "インデックスを zip に書き出しています。終わるまで、ほかの操作はできません。" }
    }
    $notice = if (!$enabled) { "設定で［すべて更新］の対象から外れています（インデックスは残っています。行の［更新］で更新できます）。" } else { "" }
    if ($indexing -and $enabled -and $inRound) {
        $percent = if ($ratio -ge 0) { [int][Math]::Floor([Math]::Min($ratio, 1.0) * 100) } else { 0 }
        $sub = if ($ratio -ge 0) { "${percent}%" } else { "" }
        return @{ Text = "更新中"; Sub = $sub; Level = "Run"; Percent = $percent; ToolTip = "インデックスを更新しています。終わると状態を表示します。" }
    }
    if ($null -eq $stat -or $stat.Total -eq 0) {
        return @{ Text = "未作成"; Sub = ""; Level = "None"; ToolTip = addIndexRowNotice "まだ更新していません。［すべて更新］か、行の［更新］で作ります。" $notice }
    }
    if ($stat.Pending -ge 1) {
        return @{ Text = "要更新"; Sub = "残り $($stat.Pending) 件"; Level = "Wait"; ToolTip = addIndexRowNotice "未更新 $($stat.Pending) 件です。次の更新で続きから更新します。" $notice }
    }
    if ($stat.Failed -ge 1) {
        return @{ Text = "警告"; Sub = ""; Level = "Warn"; ToolTip = addIndexRowNotice "失敗 $($stat.Failed) 件です。原因は下の「更新に失敗したファイル」で見られます。失敗したファイル以外は検索できます。" $notice }
    }
    return @{ Text = "最新"; Sub = ""; Level = "Ok"; ToolTip = addIndexRowNotice "更新済み $($stat.Total) 件です。" $notice }
}

function getIndexFooterView {
    # 一覧の下の帯の文言。@{ Folders; Files }
    param (
        [int]$folderCount,
        [int]$fileTotal
    )

    return @{
        Folders = "登録済み: {0:#,0} フォルダ" -f $folderCount
        Files = "合計: {0:#,0} ファイル" -f $fileTotal
    }
}

function addIndexRowNotice {
    # getIndexRowView のツールヒントに、［すべて更新］の対象から外れているときの案内を改行で足す（無ければそのまま）
    param ([string]$text, [string]$notice)

    if ($notice -eq "") {
        return $text
    }
    return "${text}`n${notice}"
}

function getFastSearchRowView {
    # 一覧の「高速検索」列（システムインデックスが Windows Search にどこまで反映されたか）の
    # 文言・ツールヒント・色の区分・対処の手順を返す。@{ Text; ToolTip; Level; Steps }
    # 使えないとき（不可）の Level は Warn（失敗の赤でなく注意の色）。Steps は詳細に出す対処の手順の短い箇条（無ければ空）
    #   reason     : getWindowsSearchState の値（NoFolder; NoConnection; NotInScope; NotYet; Ok）。$null ならまだ確かめていない
    #   progress   : getSystemIndexProgress の値（$null なら読めなかった・問い合わせに失敗した）
    #   name       : インデックス名（progress.ByIndex を引く）
    #   hasContent : そのインデックスの getIndexStats の Done が 1 以上か
    #   checkedAt  : 最後に確かめ終えた時刻（DateTime。$null ならまだ）
    #   indexing   : インデックス作成中か。作成中に hasContent が真へ変わっても（高速検索の確かめは
    #                作成中は走らないため）、前の確かめの結果（NoFolder など）から「不可」にしない
    param (
        $reason,
        $progress,
        [string]$name,
        [bool]$hasContent = $false,
        $checkedAt = $null,
        [bool]$indexing = $false
    )

    if ($null -eq $reason) {
        return @{ Text = "確認中…"; Level = "None"; ToolTip = "Windows Search の状態を確かめています。" }
    }
    if ($reason -eq "NoFolder" -and !$hasContent) {
        return @{ Text = "－"; Level = "None"; ToolTip = (addFastSearchCheckedAt "まだ作っていません。更新が終わると状態を表示します。" $checkedAt) }
    }
    if ($reason -eq "NoConnection") {
        return newFastSearchRowResult "不可" "Warn" @("Windows Search に接続できません。") $true $checkedAt $progress @(
            "Windows Search のサービスが動いているかを確かめてください。")
    }
    if ($reason -eq "NotInScope") {
        return newFastSearchRowResult "不可" "Warn" @("ワークスペースが Windows Search の索引の対象外です。") $true $checkedAt $progress @(
            "スタートで「インデックスのオプション」と入力して開きます。",
            "ワークスペースの system_index を対象に加えます。",
            "管理者の権限が要る PC では、PC の管理者に頼みます。")
    }
    if (($reason -eq "Ok" -or $reason -eq "NotYet") -and $null -eq $progress) {
        return @{ Text = "－"; Level = "None"; ToolTip = (addFastSearchCheckedAt "反映の進み具合を確かめられませんでした。画面を前に出し直すと、もう一度確かめます。" $checkedAt) }
    }
    $entry = $null
    if ($progress -and $progress.ByIndex -and $progress.ByIndex.ContainsKey($name)) {
        $entry = $progress.ByIndex[$name]
    }
    if ($null -eq $entry -or $entry.Folders -eq 0) {
        if ($hasContent -and $indexing) {
            return @{ Text = "－"; Level = "None"; ToolTip = (addFastSearchCheckedAt "更新中です。終わると状態を表示します。" $checkedAt) }
        }
        if ($hasContent) {
            return newFastSearchRowResult "不可" "Warn" @("このインデックスには高速検索用のデータがありません。") $false $checkedAt $null
        }
        return @{ Text = "－"; Level = "None"; ToolTip = (addFastSearchCheckedAt "まだ作っていません。更新が終わると状態を表示します。" $checkedAt) }
    }
    if ($reason -eq "NotYet") {
        return newFastSearchRowResult "反映待ち" "Wait" @("Windows Search がまだ索引していません。対象に入っていれば、待つと使えるようになります（対象外のときは［インデックスのオプション］で加えてください）。") $true $checkedAt $progress
    }
    # ここから reason は Ok
    if ($entry.Waiting -eq $entry.Folders) {
        return newFastSearchRowResult "反映待ち" "Wait" @("反映済み 0 / $($entry.Folders) フォルダです。Windows Search が索引すると反映中 N% に進みます。") $true $checkedAt $progress
    }
    if ($entry.Waiting -ge 1) {
        $percent = [Math]::Floor((($entry.Folders - $entry.Waiting) / [double]$entry.Folders) * 100)
        if ($percent -eq 0) { $percent = 1 }
        return newFastSearchRowResult "反映中 ${percent}%" "Wait" @("反映済み $($entry.Folders - $entry.Waiting) / $($entry.Folders) フォルダです（反映待ち $($entry.Waiting)）。反映済みのフォルダは高速検索で、反映待ちのフォルダはふつうの検索で調べます。") $true $checkedAt $progress
    }
    return @{
        Text = "可"; Level = "Ok"
        ToolTip = addFastSearchCheckedAt "反映済み $($entry.Folders) / $($entry.Folders) フォルダです。高速検索に使えます。" $checkedAt
    }
}

function newFastSearchRowResult {
    # getFastSearchRowView の共通の組み立て: 理由の行＋（使っても結果は同じという注記）＋ ContentIndexed の案内＋最終確認
    # steps は対処の手順（ツールヒントでは理由の次の行に並べ、詳細では理由と別の箇条にする）
    param ([string]$text, [string]$level, [string[]]$lines, [bool]$withUsageNotice, $checkedAt, $progress, [string[]]$steps = @())

    $all = New-Object 'System.Collections.Generic.List[string]'
    foreach ($line in $lines) { [void]$all.Add($line) }
    foreach ($step in $steps) { [void]$all.Add($step) }
    if ($withUsageNotice) {
        [void]$all.Add("使えなくても検索の結果は同じで、時間だけが違います。")
        if ($progress -and $progress.ContentIndexed) {
            [void]$all.Add("content_index が Windows Search の対象から自動で外れませんでした。対象から外すと反映が早くなります。")
        }
    }
    $tooltip = addFastSearchCheckedAt ($all -join "`n") $checkedAt
    return @{ Text = $text; Level = $level; ToolTip = $tooltip; Steps = @($steps) }
}

function addFastSearchCheckedAt {
    # ツールヒントの最後に「最終確認 HH:mm」を足す（checkedAt が無ければそのまま）
    param ([string]$text, $checkedAt)

    if ($null -eq $checkedAt) {
        return $text
    }
    return "${text}`n最終確認 $($checkedAt.ToString('HH:mm'))"
}

# ［インデックス管理］タブの判断: 追加・改名・削除と、その仕事の間の排他・閉じるときの判断。
# 画面に触らないため、そのままテストできる（tests\tebunko\ui\index\index_edit_view.Tests.ps1）。

function getIndexStoreJobStatus {
    # インデックスの削除・名前の変更を別スレッドで始めたときのステータス
    param (
        [string]$kind,      # "delete"（削除）か "rename"（名前の変更）
        [string]$name,
        [string]$newName
    )

    if ($kind -eq "rename") {
        return "インデックス [${name}] の名前を [${newName}] に変えています…（共有フォルダでは少し時間がかかります）"
    }
    return "インデックス [${name}] を削除しています…（件数によっては少し時間がかかります）"
}

function getIndexStoreJobFailedStatus {
    # 削除・名前の変更が失敗したときのステータス
    param (
        [string]$kind,
        [string]$name,
        [string]$errorText
    )

    $operation = if ($kind -eq "rename") { "名前の変更" } else { "削除" }
    return "インデックス [${name}] の${operation}に失敗しました：${errorText}"
}

function getBulkDeleteErrorStatus {
    # 削除が失敗した（1 件の削除の失敗と、複数削除が裏の仕事ごと失敗した場合。ワークスペースに届かないなど）ときのステータスと帯の文
    param (
        [string]$errorText
    )

    return "削除に失敗しました：${errorText}"
}

function getBulkDeleteFailedStatus {
    # 複数削除で、閉じるのを待っていて結果のダイアログを出さないときに、失敗があったことをステータスに残す文
    param (
        [int]$failedCount
    )

    return "${failedCount} 件のインデックスは削除できませんでした"
}

function getIndexStoreSourceFolderError {
    # 名前の変更の裏の仕事の戻り値（@{ SourceFolderError }）から、元のフォルダの記録を書けなかった理由を取り出す（書けたなら ""）
    param (
        $output
    )

    foreach ($item in @($output)) {
        if ($item -is [hashtable] -and $item.ContainsKey("SourceFolderError")) {
            return [string]$item.SourceFolderError
        }
    }
    return ""
}

function getIndexJobCloseAction {
    # インデックスの削除・名前の変更の途中で画面を閉じようとしたときの動き。
    #   "wait"    … 閉じずに、終わるまで待って閉じる（1 回目。閉じると設定への反映が抜けて、設定とインデックスのフォルダの名前が食い違うため）
    #   "confirm" … 待っている間にもう一度閉じようとした。待たずに閉じてよいかを確かめる
    #   "proceed" … 仕事が無い。ふつうの閉じ方に進む
    #   "waitMove" … ワークスペースを移している途中。閉じずに、移し終わるまで待って閉じる（途中で止めると移動元と移動先に分かれるため、確認は出さない）
    param (
        [bool]$indexBusy,
        [bool]$alreadyAsked,
        [bool]$workspaceMoving = $false
    )

    if ($workspaceMoving) {
        return "waitMove"
    }
    if (!$indexBusy) {
        return "proceed"
    }
    if ($alreadyAsked) {
        return "confirm"
    }
    return "wait"
}

function getIndexJobCloseConfirm {
    # 待っている間にもう一度閉じようとしたときの確認（showConfirm に渡す文言）
    return @{
        Title      = "変更の途中です"
        Heading    = "インデックスの変更の途中です。閉じますか？"
        Hint       = "いま閉じると、設定とインデックスのフォルダの名前が食い違うことがあります。終わるまで待てば、自動で閉じます。"
        CloseText  = "待たずに閉じる"
        CloseValue = "close"
        CancelText = "終わるまで待つ"
    }
}

function getIndexJobCloseAfterConfirm {
    # 確認から戻ったときの動き（"close" か "stay"）。聞いている間に仕事が終わったなら、答えにかかわらず閉じる
    # （終わったときの「終わったら閉じる」は、確認の間は動かさないため）
    param (
        [string]$answer,
        [bool]$indexBusy
    )

    if (!$indexBusy -or $answer -eq (getIndexJobCloseConfirm).CloseValue) {
        return "close"
    }
    return "stay"
}

function getIndexJobClosingStatus {
    # 削除・名前の変更の途中で閉じようとして、待っているときのステータス
    return "インデックスの変更が終わってから閉じます…（待たずに閉じるには、もう一度閉じる操作をします）"
}

function getWorkspaceMoveClosingStatus {
    # ワークスペースを移している途中で閉じようとして、待っているときのステータス
    return "ワークスペースを移し終わってから閉じます…"
}

function getSourceFolderFileFailedStatus {
    # 元のフォルダの記録（source_folder.txt）を書き直せなかったときのステータス
    param (
        [string]$errorText
    )

    return "元のフォルダの記録を書き直せませんでした：${errorText}"
}

function getIndexJobBlocker {
    # インデックス作成・削除・エクスポート・インポート・ワークスペースの変更は互いに排他（画面の可否の表）。
    # 動いているものがあれば、その名前を返す（無ければ空文字列。空なら操作してよい）
    param (
        [bool]$isIndexing,   # インデックス作成中
        [bool]$indexBusy,    # 前のインデックスの削除・名前の変更中
        [bool]$archiveBusy,  # エクスポート・インポート中
        [bool]$namingBusy = $false,  # ネットワークのワークスペースで、インデックスの名前を裏で決めている間（一覧はまだ空。この間に保存すると、ほかのインデックスが設定から消える）
        [bool]$workspaceMoving = $false   # ワークスペースの中身を移している間（別スレッド。移動元と移動先の両方を使っている）
    )

    if ($workspaceMoving) {
        return "ワークスペースの移動中"
    }
    if ($isIndexing) {
        return "インデックス作成中"
    }
    if ($namingBusy) {
        return "インデックス名の決定中"
    }
    if ($indexBusy) {
        return "削除・名前の変更中"
    }
    if ($archiveBusy) {
        return "エクスポート・インポート中"
    }
    return ""
}

function testIndexReadAllowed {
    # インデックス・設定を読む操作（検索を始める・F5 で読み直す・窓を前に出したときの読み直し）をしてよいか。
    # ワークスペースの中身を移している間は、移動元と移動先の両方を移す側が使っているため、キー操作でも始めない
    param (
        [bool]$workspaceMoving = $false
    )

    return -not $workspaceMoving
}

function testMainContentOperable {
    # ナビと中身（画面）の操作を受け付けてよいか。ワークスペースの中身を移している間は受け付けない
    # （マウスもキーも、設定・インデックス・検索の入口のどれからも書き込み・読み込みを始めさせない。待つ間のダイアログ自身は別の窓なので影響しない）
    param (
        [bool]$workspaceMoving = $false
    )

    return -not $workspaceMoving
}

function getIndexJobBlockedMessage {
    # 排他で操作をできないときのメッセージ（blocker は getIndexJobBlocker の結果。空なら空文字列）
    param (
        [string]$blocker,
        [string]$operation   # "追加" "編集" "削除" "エクスポート" "インポート" "ワークスペースの変更"
    )

    if ($blocker -eq "") {
        return ""
    }
    if ($operation -eq "ワークスペースの変更") {
        if ($blocker -eq "ワークスペースの移動中") {
            return "ワークスペースを移している間は、もう一度変えられません。終わるまでお待ちください。"
        }
        if ($blocker -eq "インデックス作成中") {
            return "更新中はワークスペースを変えられません。更新が終わるまでお待ちください（［中止］で止められます）。"
        }
        if ($blocker -eq "削除・名前の変更中") {
            return "前のインデックスの削除・名前の変更が終わるまでお待ちください。"
        }
        if ($blocker -eq "インデックス名の決定中") {
            return "インデックスの一覧を読み込んでいます。終わるまでお待ちください。"
        }
        return "エクスポート・インポートが終わるまでお待ちください。"
    }
    if ($blocker -eq "インデックス作成中") {
        return "更新中はインデックスを${operation}できません。更新が終わるまでお待ちください（［中止］で止められます）。"
    }
    return "${blocker}は${operation}できません。終わるまでお待ちください。"
}

function getIndexDeleteConfirmMessage {
    # インデックスを削除する確認の文。@{ Heading; Body }（showConfirm の heading と hint に渡す）
    #   1 件: 「営業」のインデックスを削除しますか？
    #   2 件以上: 選んだ N 件のインデックスを削除しますか？ ／ 名前を 3 つまで並べ、4 つ目からは「ほか N 件」にまとめる
    # 空の名前は数えない
    param (
        [string[]]$names
    )

    $names = @($names | Where-Object { $_ })
    $note = "元のファイルは削除されません。"
    if ($names.Count -le 1) {
        $name = if ($names.Count -eq 1) { $names[0] } else { "" }
        return @{ Heading = "「${name}」のインデックスを削除しますか？"; Body = $note }
    }
    $shown = @($names | Select-Object -First 3 | ForEach-Object { "「$_」" }) -join ""
    $others = $names.Count - 3
    $list = if ($others -ge 1) { "${shown}ほか {0:#,0} 件" -f $others } else { $shown }
    return @{
        Heading = "選んだ {0:#,0} 件のインデックスを削除しますか？" -f $names.Count
        Body = "${list}を削除します。${note}"
    }
}

function getIndexBulkResultView {
    # まとめてのエクスポート・削除の終わりに出す文言（仮）。results は 1 件ごとの @{ Name; Ok; Reason }
    #   operation: "エクスポート" / "削除"
    # @{ Status（ステータスバーの 1 行）; HasFailure; FailureHeading; FailureDetail（失敗した名前と理由の一覧）}
    param (
        [string]$operation,
        [object[]]$results
    )

    $results = @($results | Where-Object { $null -ne $_ })
    $failed = @($results | Where-Object { !$_.Ok })
    $okCount = $results.Count - $failed.Count
    if ($failed.Count -eq 0) {
        return @{ Status = "${okCount} 件のインデックスを${operation}しました"; HasFailure = $false; FailureHeading = ""; FailureDetail = "" }
    }
    return @{
        Status = "${operation}: ${okCount} 件成功・$($failed.Count) 件失敗"
        HasFailure = $true
        FailureHeading = "$($failed.Count) 件のインデックスを${operation}できませんでした（残りは終わっています）。"
        FailureDetail = ($failed | ForEach-Object { "「$($_.Name)」: $($_.Reason)" }) -join "`n"
    }
}

function testIndexEditInput {
    # 追加と詳細欄の編集の入力を調べ、直してほしい内容を返す（問題なければ空文字列）
    param (
        [string]$path,   # 入力された元のフォルダ
        [string]$name,   # 入力されたインデックス名
        $items,          # 今の一覧（Name・Path を持つ行）
        $current = $null # 編集中の行（重複の判定から外す）
    )

    $folder = normalizeFolderPath $path
    if ($folder -eq "") {
        return "元のフォルダを指定してください。"
    }
    $conflict = getIndexFolderConflict $folder @($items | Where-Object { $_ -ne $current })
    if ($conflict -ne "") {
        return $conflict
    }
    # @(getUsedIndexNames ...) と直接書くと集合が 1 要素の配列に入るだけなので、変数に受けてから配列にする
    $usedNames = getUsedIndexNames $items $current
    return (testIndexName $name.Trim() @($usedNames))
}

# ［インデックス管理］タブの判断: 詳細欄。
# 画面に触らないため、そのままテストできる（tests\tebunko\ui\index\index_detail_view.Tests.ps1）。

function getIndexDetailItem {
    # 詳細欄に出す行（詳細の名前・フォルダパスの欄と［変更…］、右クリックの［削除］［エクスポート…］の対象も同じ行。［アクション ▼］は別で、［更新］［エクスポート…］［削除…］はチェックの行、［インポート…］はチェックが要らない。可否は getIndexActionsEnabled が決める）。押した行があればそれ、
    # 無くてチェックが 1 件だけならその行、それ以外は $null。詳細を出す所と可否・対象を決める所で、この 1 つを使う
    param (
        [object]$selectedItem,   # 一覧で押した行（無ければ $null）
        [object[]]$checkedItems  # getIndexCheckedItems の結果
    )

    if ($null -ne $selectedItem) { return $selectedItem }
    $checked = @($checkedItems | Where-Object { $null -ne $_ })
    if ($checked.Count -eq 1) { return $checked[0] }
    return $null
}

function getIndexDetailMultiCount {
    # 詳細欄を「N 件を選択中」にするときの N（そうしないときは 0）。2 件以上チェックしているときだけ、その件数を返す。
    # 0 件・1 件のときは 0（詳細欄は押した行のまま）
    param (
        [int]$checked
    )

    if ($checked -ge 2) { return $checked }
    return 0
}

function getIndexDetailRowPlan {
    # 詳細の行の高さをどうするか。1 件も無いとき（empty）は詳細と境目を畳み（Hide）、1 件以上になったら戻す（Show）。
    # 空かどうかが変わっていないとき（別の行を選んだだけ）は何もしない（Keep）。境目をドラッグして変えた高さを、選び直しで戻さないため。
    # wasEmpty は前回の空かどうか（まだ一度も決めていなければ $null）。
    param (
        $wasEmpty,
        [bool]$empty
    )

    if ($null -ne $wasEmpty -and [bool]$wasEmpty -eq $empty) { return "Keep" }
    if ($empty) { return "Hide" }
    return "Show"
}

function getIndexDetailEditDecision {
    # 詳細の「基本設定」の名前・フォルダパスの欄を確定するときの判断。@{ Action; Message; Name; Path }
    #   Action: None（変わっていない）/ Invalid（直してほしい。Message に理由）/ Apply（Name・Path で反映する）
    # 名前は前後の空白を除き、フォルダパスは normalizeFolderPath で整えてから比べる（大文字・小文字だけの違いは名前の変更として扱う）
    param (
        [string]$name,
        [string]$path,
        $item,            # 直している行（Name・Path を持つ）
        $items            # 今の一覧
    )

    $newName = $name.Trim()
    $newPath = normalizeFolderPath $path
    if ($newName -ceq $item.Name -and $newPath -eq $item.Path) {
        return @{ Action = "None"; Message = ""; Name = $item.Name; Path = $item.Path }
    }
    $message = testIndexEditInput $path $newName $items $item
    if ($message -ne "") {
        return @{ Action = "Invalid"; Message = $message; Name = $item.Name; Path = $item.Path }
    }
    return @{ Action = "Apply"; Message = ""; Name = $newName; Path = $newPath }
}

function getIndexDetailView {
    # インデックスの詳細のパネルに出す内容を返す。1 つ選んでいるときだけ中身を出す
    # （何も選んでいない・複数のときは見出しだけ。一覧の下の合計は別の部品）。
    #   items         : 選んでいる行。@{ Name; Path; Enabled; FolderStatus; FolderMissing（元のフォルダが無いと分かったか）; FolderChecked（有無を調べ終えたか。$false のときだけ「確認中」。省くと調べ終えたものとする）; IndexText; IndexLevel; IndexSub; FileCountText;
    #                   LastIngestedText; FastText; FastLevel; FastToolTip; FastSteps; FastCheckedText }
    #   fastEntry     : getSystemIndexProgress の ByIndex のそのインデックスの値（@{ Folders; Waiting }）。無ければ $null
    #   multiCount    : 2 以上なら、詳細は出さず「N 件を選択中」と案内だけにする（getIndexDetailMultiCount）
    #   running       : 更新の進み具合（@{ Ratio; Processed; Total; Failed; Eta; Current }）。更新中の行の「インデックス」の箱に出す。無ければ $null
    # 戻り値: @{ Title; Selected; Name; Path; FolderStatus; FolderBrush（フォルダの状態の文の色のキー。ある = Ok／無い = Danger.Text／確認中・何も出さない = Ink.Muted）;
    #            FolderIcon（文の左に出すアイコン。ある = Check／無い = Close／確認中・何も出さない = 空。theme.xaml の Icon.<名前>）; Badge（@{ Text; Level }）; Updated; Count;
    #            Rows（右の「インデックス情報」の @{ Label; Value } の配列）; RowsKey;
    #            Fast（@{ Shown（反映の進みの棒を出すか）; Value（0～1）; Text; State; Level; Reason; Steps（対処の手順の箇条）; Checked; Note }）;
    #            Multi（複数を選んでいるか）; Hint（Multi のときの案内）;
    #            Run（@{ Shown（更新中の棒・件数・ファイル名を出すか）; Value（0～1）; CountText; FileText }）;
    #            Error・ErrorHint（元のフォルダが無いときの理由と直し方。無ければ空。バッジは「エラー」の Ng になる） }
    #   RowsKey は左右の表の中身から作る文字列。同じなら画面は行を置き直さない（高速検索の進みだけが変わったとき）
    param (
        [object[]]$items,
        $fastEntry = $null,
        [int]$multiCount = 0,
        $running = $null
    )

    $noRun = @{ Shown = $false; Value = 0.0; CountText = ""; FileText = "" }
    $emptyFast = @{ Shown = $false; Value = 0.0; Text = ""; State = ""; Level = "None"; Reason = ""; Steps = @(); Checked = ""; Note = "" }
    $none = @{
        Title = "インデックスの状態"; Selected = $false; Name = ""; Path = ""; FolderStatus = ""; FolderMissing = $false; FolderBrush = "Ink.Muted"; FolderIcon = ""
        Badge = @{ Text = ""; Level = "None" }; Updated = ""; Count = ""; Rows = @(); RowsKey = ""; Fast = $emptyFast
        Multi = $false; Hint = ""; Run = $noRun; Error = ""; ErrorHint = ""
    }
    if ($multiCount -ge 2) {
        $multi = $none.Clone()
        $multi.Title = "{0:#,0} 件を選択中" -f $multiCount
        $multi.Multi = $true
        $multi.Hint = "1 件だけ選ぶと、ここに詳細を表示します。"
        return $multi
    }
    $selected = @($items | Where-Object { $null -ne $_ })
    if ($selected.Count -ne 1) {
        return $none
    }
    $item = $selected[0]

    $hasCount = $item.FileCountText -and $item.FileCountText -ne "－"
    $count = if ($hasCount) { "$($item.FileCountText) ファイル" } else { "まだ更新していません" }
    $updated = if ($item.LastIngestedText) { "最終更新 $($item.LastIngestedText)" } else { "" }

    $rows = New-Object 'System.Collections.Generic.List[object]'
    [void]$rows.Add(@{ Label = "対象ファイル数"; Value = $(if ($hasCount) { "$($item.FileCountText) ファイル" } else { "－" }) })
    [void]$rows.Add(@{ Label = "最終更新"; Value = $(if ($item.LastIngestedText) { [string]$item.LastIngestedText } else { "－" }) })

    $fast = @{ Shown = $false; Value = 0.0; Text = ""; State = [string]$item.FastText; Level = [string]$item.FastLevel; Reason = ""; Steps = @(); Checked = [string]$item.FastCheckedText; Note = "" }
    if ($item.FastLevel -eq "Warn" -and $item.FastToolTip) {
        $fast.Reason = ([string]$item.FastToolTip -split "`n")[0]
        $fast.Steps = @($item.FastSteps)
    }
    if ($null -ne $fastEntry -and $fastEntry.Folders -gt 0) {
        $done = [Math]::Max(0, [Math]::Min([int]$fastEntry.Folders, [int]$fastEntry.Folders - [int]$fastEntry.Waiting))
        $fast.Shown = $true
        $fast.Value = $done / [double]$fastEntry.Folders
        $fast.Text = "反映済み $done / $($fastEntry.Folders) フォルダ"
        if ($done -lt [int]$fastEntry.Folders) {
            $fast.Note = "反映待ちのフォルダは通常の検索で調べます。検索結果は変わりませんが、時間がかかります。"
        }
    }
    $run = $noRun
    if ($item.IndexLevel -eq "Run") {
        $run = @{ Shown = $true; Value = 0.0; CountText = ""; FileText = "" }
        if ($null -ne $running) {
            $parts = New-Object 'System.Collections.Generic.List[string]'
            if ([int]$running.Total -gt 0) {
                $counts = "{0:#,0} / {1:#,0} 件" -f [int]$running.Processed, [int]$running.Total
                if ([int]$running.Failed -gt 0) {
                    $counts += "（失敗 {0:#,0} 件）" -f [int]$running.Failed
                }
                [void]$parts.Add($counts)
            }
            if ($running.Eta) {
                [void]$parts.Add([string]$running.Eta)
            }
            $run.Value = [Math]::Max(0.0, [Math]::Min(1.0, [double]$running.Ratio))
            $run.CountText = $parts -join "・"
            $run.FileText = if ($running.Current) { "読み取り中のファイル：$($running.Current)" } else { "" }
        }
    }
    # 元のフォルダが見つからないとき（更新中は更新の表示を優先する）は、バッジを「エラー」にして、理由と直し方を出す
    $badge = @{ Text = [string]$item.IndexText; Level = [string]$item.IndexLevel; Sub = [string]$item.IndexSub }
    $errorText = ""
    $errorHint = ""
    if ($item.FolderMissing -and $item.IndexLevel -ne "Run") {
        $badge = @{ Text = "エラー"; Level = "Ng"; Sub = "" }
        $errorText = "フォルダが見つかりません。"
        $errorHint = "フォルダが移動・削除されたか、ネットワークにつながっていない可能性があります。`nフォルダパスの［変更…］でフォルダを選び直してください。"
    }
    $folderBrush = if ($item.FolderMissing) { "Danger.Text" } elseif ($item.FolderChecked -eq $false) { "Ink.Muted" } else { "Ok" }
    $folderIcon = if ($item.FolderMissing) { "Close" } elseif ($item.FolderChecked -eq $false -or !$item.FolderStatus) { "" } else { "Check" }
    $fixed = @(
        $item.Name, $item.Path, $item.FolderStatus, $folderBrush, $folderIcon, $badge.Text, $badge.Level, $badge.Sub, $updated, $count
        $fast.State, $fast.Level, $fast.Reason, (@($fast.Steps) -join "|"), $fast.Checked
    ) -join "`t"
    $rowsKey = $fixed + "`n" + (@($rows | ForEach-Object { "$($_.Label)`t$($_.Value)" }) -join "`n")
    return @{
        Title = "$($item.Name) - 詳細"; Selected = $true; Name = [string]$item.Name; Path = [string]$item.Path
        FolderStatus = [string]$item.FolderStatus; FolderMissing = [bool]$item.FolderMissing; FolderBrush = $folderBrush; FolderIcon = $folderIcon
        Badge = $badge
        Updated = $updated; Count = $count; Rows = $rows.ToArray(); RowsKey = $rowsKey; Fast = $fast
        Multi = $false; Hint = ""; Run = $run; Error = $errorText; ErrorHint = $errorHint
    }
}

# ［インデックス管理］タブの判断: エクスポート・インポート。
# 画面に触らないため、そのままテストできる（tests\tebunko\ui\index\index_archive_view.Tests.ps1）。

function getIndexArchiveCancelledStatus {
    # エクスポート・インポートのダイアログを取りやめたときのステータス
    param (
        [string]$operation   # "エクスポート" / "インポート"
    )

    return "${operation}を取りやめました"
}

function getImportResultStatus {
    # インポートの結果（importIndex の戻り値）から、ステータスに出す文言を返す。
    # Warnings（同じ元のフォルダが別の名前で既に登録されている等）と、高速検索が次の更新の後に効くことを添える
    param (
        $result
    )

    $text = "インデックス [$($result.Name)] をインポートしました（$($result.Files) ファイル）。" +
        "高速検索は次の更新の後に効きます。"
    foreach ($warning in @($result.Warnings)) {
        $text += " ${warning}"
    }
    return $text
}

function testIndexExportInput {
    # エクスポートのダイアログの入力を調べ、直してほしい内容を返す（問題なければ空文字列）。
    # 書き出し先のフォルダが今あるかは、ここでは調べない（画面のスレッドでネットワークのパスを調べないため。書き出す仕事の中で調べる）
    param (
        [string]$folder   # 入力された書き出し先のフォルダ
    )

    if ((normalizeFolderPath $folder) -eq "") {
        return "書き出し先のフォルダを指定してください。"
    }
    return ""
}

function getIndexExportNotice {
    # エクスポートのダイアログの案内文（対象の名前・大きさは getIndexExportHeader の枠に出す）
    return "別の PC・ワークスペースでインポートして使えます。"
}

function formatArchiveSize {
    # 大きさを "94.0 MB" の形にする（0.1 MB に満たなくても 0.1 MB。区切りの記号は環境によらず "."）
    param ([long]$bytes)

    $mb = [Math]::Max(0.1, [Math]::Round($bytes / 1MB, 1))
    return ($mb.ToString("0.0", [System.Globalization.CultureInfo]::InvariantCulture) + " MB")
}

function getIndexExportMissingText {
    # エクスポートする大きさを数えている間に、対象のインデックスが無くなっていたときのステータス
    return "対象のインデックスが見つかりません"
}

function getIndexExportHeader {
    # エクスポートのダイアログの上の枠（対象・大きさ・zip の名前）と注意。
    #   items: 書き出すインデックス（Name と FileCountText（"2,530"。無ければ "－" か空）を持つ行）。1 件でも 2 件以上でもよい
    # 戻り値: @{ Title（1 件は名前、2 件以上は「N 件のインデックス」）; Size（「2,530 ファイル」。大きさを数え終えていれば「2,530 ファイル・94.0 MB」。数が分からなければ空）;
    #            FileText（書き出し先の下の「<名前>_インデックス_<yyyyMMdd>.zip として保存します」）; Caution }
    param (
        [object[]]$items,
        [datetime]$now = (Get-Date),
        [long]$bytes = -1   # 数え終えた zip に入る大きさ。省略（負）なら大きさは出さない
    )

    $items = @($items | Where-Object { $null -ne $_ })
    $total = 0
    $known = $false
    foreach ($item in $items) {
        $parsed = 0
        if ([int]::TryParse((([string]$item.FileCountText) -replace ",", ""), [ref]$parsed)) {
            $total += $parsed
            $known = $true
        }
    }
    $size = if ($known) { "{0:#,0} ファイル" -f $total } else { "" }
    if ($known -and $bytes -ge 0) {
        $size += "・" + (formatArchiveSize $bytes)
    }
    if ($items.Count -eq 1) {
        $title = [string]$items[0].Name
        $fileText = "$(getExportFileName $title @() $now) として保存します"
    } else {
        $title = "{0:#,0} 件のインデックス" -f $items.Count
        $fileText = "インデックスごとに <名前>_インデックス_$($now.ToString('yyyyMMdd')).zip として保存します"
    }
    return @{
        Title = $title; Size = $size; FileText = $fileText
        Caution = "このファイルには、元のファイルの本文と元のフォルダの場所が含まれます。元のファイルと同じように取り扱ってください。"
    }
}

function getIndexImportHeader {
    # インポートのダイアログの上の枠（zip の中身）。
    # 戻り値: @{ Name; Exported（「エクスポートした日時 2026/09/27 10:00」。分からなければ空）; Size（「2,530 ファイル・56.6 MB・v0.3.0」。版が無ければ版は省く） }
    param (
        $info   # readIndexArchiveInfo の結果
    )

    $exported = ""
    $at = [datetimeoffset]::MinValue
    if ($info.ExportedAt -and [datetimeoffset]::TryParse([string]$info.ExportedAt, [ref]$at)) {
        $exported = "エクスポートした日時 " + $at.LocalDateTime.ToString("yyyy/MM/dd HH:mm", [System.Globalization.CultureInfo]::InvariantCulture)
    }
    $parts = New-Object 'System.Collections.Generic.List[string]'
    [void]$parts.Add(("{0:#,0} ファイル" -f [int]$info.Files))
    [void]$parts.Add((formatArchiveSize ([long]$info.Bytes)))
    $version = ([string]$info.AppVersion).Trim().TrimStart("v", "V")
    if ($version) {
        [void]$parts.Add("v${version}")
    }
    return @{ Name = [string]$info.IndexName; Exported = $exported; Size = ($parts -join "・") }
}

function getImportSourceCheckText {
    # インポートの「元のフォルダ」の下に出す 1 行（文言と色の区分）。@{ Text; Kind }。Kind は Ok / Warn / Ng / None（None は何も出さない）。
    #   folder : 入力された元のフォルダ
    #   exists : フォルダがあるか（$true / $false。調べていない・分からないときは $null）。画面のスレッドでは調べない
    #   others : 重なりを比べる相手（Name・Path を持つ行。取り込む名前と同じ名前の行は呼び出し側で外す）
    param (
        [string]$folder,
        $exists = $null,
        $others = @()
    )

    $normalized = normalizeFolderPath $folder
    if ($normalized -eq "") {
        return @{ Text = ""; Kind = "None" }
    }
    foreach ($other in @($others)) {
        if ((testSameFolder $other.Path $normalized) -or (testFolderUnder $normalized $other.Path) -or (testFolderUnder $other.Path $normalized)) {
            return @{ Text = "「$($other.Name)」の元のフォルダと重なっています"; Kind = "Ng" }
        }
    }
    if ($exists -eq $true) {
        return @{ Text = "見つかりました"; Kind = "Ok" }
    }
    if ($exists -eq $false) {
        return @{ Text = "元のフォルダがこの PC に見つかりません。検索はできますが、元のフォルダを設定するまで更新できません。"; Kind = "Warn" }
    }
    return @{ Text = ""; Kind = "None" }
}

function getImportCollisionChoiceView {
    # インポートのダイアログの頭に出す、同じ名前のときの選び方（［別の名前にする］／［置き換える］）の表示。
    #   name     : 名前の欄の今の値
    #   zipName  : zip の中のインデックスの名前
    #   usedNames: getUsedIndexNames の結果
    #   mode     : 利用者が選んでいる方（Rename か Overwrite。既定は Rename）
    # 出すのは、名前の欄が今の一覧にある名前のとき、または zip の名前が一覧にあって名前の欄が別の名前の候補のまま（初めの状態）のとき。
    # 名前の欄を手で一覧に無い名前にしたら隠す。
    # 置き換える相手（TargetName）は、名前の欄が一覧にある名前ならその名前、そうでなければ zip の名前。
    # Mode は、置き換える相手が名前の欄で決まっている（名前の欄が一覧にある名前の）ときだけ Overwrite になれる。
    # 名前の欄が一覧に無い名前なら、選んでいても Rename（重ならないので別の名前の扱いと同じ）。
    # Danger は［インポート］を危険の型（赤）にするか（Mode が Overwrite のとき）。Notice は置き換えるときに添える一文。
    # Candidate は［別の名前にする］を選んだときに名前の欄へ入れる候補、OverwriteName は［置き換える］を選んだときの名前の欄の値
    param (
        [string]$name,
        [string]$zipName,
        $usedNames = $null,
        [string]$mode = ${importCollisionRename}
    )

    $trimmed = $name.Trim()
    $candidate = getImportSuggestedName $zipName $usedNames
    $nameCollides = $trimmed -ne "" -and (testImportNameCollision $trimmed $usedNames)
    $zipCollides = testImportNameCollision $zipName $usedNames
    $visible = $nameCollides -or ($zipCollides -and $trimmed -ieq $candidate)
    $effective = if ($nameCollides -and $mode -eq ${importCollisionOverwrite}) { ${importCollisionOverwrite} } else { ${importCollisionRename} }
    $target = if ($nameCollides) { $trimmed } else { $zipName }
    return @{
        Visible       = $visible
        Mode          = $effective
        Danger        = ($effective -eq ${importCollisionOverwrite})
        Heading       = if ($visible) { "同じ名前のインデックス [${target}] があります" } else { "" }
        RenameText    = "別の名前にする"
        OverwriteText = "置き換える"
        Notice        = if ($visible -and $effective -eq ${importCollisionOverwrite}) { "今のインデックス [${target}] は、インポートするもので置き換わります。" } else { "" }
        TargetName    = $target
        Candidate     = $candidate
        OverwriteName = $target
    }
}

function testIndexImportInput {
    # インポートのダイアログの入力を調べ、直してほしい内容を返す（問題なければ空文字列）。
    # 名前が既にあるインデックスと重なることは断らない（別の名前にするか置き換えるかの選びに回す。getImportCollisionChoiceView）。
    # 元のフォルダは、追加と詳細欄の編集と同じ決まり（getIndexFolderConflict）で調べる。同じ名前の行は上書きで置き換わる
    # （別名なら残る）ため、ここでは比べる相手から外す（別名で入れて重なったときは、インポートの側で止める）
    param (
        [string]$folder,   # 入力された元のフォルダ
        [string]$name,     # 入力されたインデックス名
        $items = @()       # 今の一覧（Name・Path を持つ行）
    )

    $normalized = normalizeFolderPath $folder
    if ($normalized -eq "") {
        return "元のフォルダを指定してください。"
    }
    $nameMessage = testIndexName $name.Trim() @()
    if ($nameMessage -ne "") {
        return $nameMessage
    }
    return (getIndexFolderConflict $normalized @($items | Where-Object { $_.Name -ine $name.Trim() }))
}

function getImportSuggestedName {
    # インポートのダイアログに初めに入れる名前。zip の名前が今の一覧に無ければそのまま、あれば「名前(2)」…にする。
    # usedNames は getUsedIndexNames の結果（集合。@(...) に入った 1 要素の配列でも、配列でもよい）
    param (
        [string]$indexName,
        $usedNames = $null
    )

    if (testImportNameCollision $indexName $usedNames) {
        return (newIndexName $indexName $usedNames)
    }
    return $indexName
}

function testImportNameCollision {
    # 入力された名前が今の一覧にあり、別の名前にするか置き換えるかの選びが要るか（大文字・小文字は区別しない）
    param (
        [string]$name,
        $usedNames = $null   # getUsedIndexNames の結果（集合・配列・文字列・$null。入れ子の集合でもよい）
    )

    foreach ($entry in @($usedNames)) {
        foreach ($used in @($entry)) {
            if ($used -and $used -ieq $name) {
                return $true
            }
        }
    }
    return $false
}

function getIndexImportNotice {
    # インポートのダイアログの説明
    # 中身（名前・日時・ファイル数・大きさ・版）は getIndexImportHeader の枠に出す
    return "名前と、元のフォルダの場所を変えられます。"
}

# インデックス更新の確認ダイアログ・進み具合に出す文言の決定。
# 画面に触らないため、そのままテストできる（tests\tebunko\ui\indexing_view.Tests.ps1）。
#
# 色は Level（Ok / Wait / Ng / Run / None）で返し、実際の色は theme.xaml の Badge.* から引く（画面側）。

function newPlanViewRows {
    # 更新の予定（取り込み予定.tsv の行）を、確認のダイアログに出す形にする。
    # 行は Name・Path・TotalText（対象ファイル数）・StatusText（バッジの文言）・Level（バッジの色。Wait / Ok / None / Ng）・DetailText（バッジの ToolTip）
    #   onlyNames: 選んだものだけの回のインデックス名（空なら全部）。選ばなかったものは出さない（「対象外」とも出さない）
    param (
        $plan,  # readIngestPlan の結果
        [string[]]$onlyNames = @()
    )

    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($item in @($plan)) {
        # 空の配列を渡すと @($plan) に $null が 1 つ入るため、ここで外す
        if ($null -eq $item) { continue }
        if (@($onlyNames).Count -gt 0 -and $item.区分 -ne ${planKindDropped} -and @($onlyNames) -notcontains [string]$item.インデックス名) { continue }
        $row = @{ Name = $item.インデックス名; Path = $item.元のフォルダ }
        if ($item.区分 -eq ${planKindDropped}) {
            # 選んだものだけの回でも出す（［更新を開始］で消えるため、利用者に見せずに消さない）
            $row.TotalText = "－"
            $row.StatusText = "削除予定"
            $row.Level = "Ng"
            $row.DetailText = "設定に無いため、［更新を開始］でこのインデックスを削除します"
        } elseif ($item.区分 -eq ${planKindUnchecked}) {
            $row.TotalText = "－"
            $row.StatusText = "対象外"
            $row.Level = "None"
            $row.DetailText = "設定で［すべて更新］の対象から外れているため更新しません（インデックスはそのまま残します）"
        } elseif ($item.区分 -eq ${planKindMissing}) {
            $row.TotalText = "－"
            $row.StatusText = "フォルダなし"
            $row.Level = "Ng"
            $row.DetailText = "元のフォルダが見つかりません（詳細のフォルダパスで場所を変えられます）"
        } else {
            $row.TotalText = "{0:#,0}" -f $item.ファイル数
            # 0 件の内訳は出さない（ふだんは「新規」「更新あり」だけになる）
            $parts = New-Object System.Collections.Generic.List[string]
            foreach ($pair in @(
                    @("新規", $item.新規),
                    @("更新あり", $item.更新あり),
                    @("前回未完了", $item.前回未完了),
                    @("インデックスが無い・壊れている", $item.インデックスなし),
                    @("前回失敗", $item.前回失敗),
                    @("クラウドにだけある", ($item.クラウド + $item.クラウド失敗)))) {
                if ($pair[1] -gt 0) {
                    $parts.Add("$($pair[0]) $('{0:#,0}' -f $pair[1]) 件")
                }
            }
            if ($item.取り込み対象 -gt 0) {
                $row.StatusText = "要更新"
                $row.Level = "Wait"
                $row.DetailText = "更新するファイル {0:#,0} 件（{1}）" -f $item.取り込み対象, ($parts -join " / ")
            } elseif ($item.クラウド -gt 0) {
                # 取り込み対象は無いが、クラウドにだけあるため残すファイルがある。「最新」とは言わず、注意の色で出す
                # （クラウドにだけある前回失敗は、更新し直す指定が無ければ取り込み対象にならない。手元の前回失敗と同じく「最新」のまま内訳に出す）
                $row.StatusText = "要確認"
                $row.Level = "Wait"
                $row.DetailText = $parts -join " / "
            } else {
                $row.StatusText = "最新"
                $row.Level = "Ok"
                $row.DetailText = if ($parts.Count -gt 0) { $parts -join " / " } else { "すべて最新です" }
            }
        }
        $rows.Add($row)
    }
    return , $rows.ToArray()
}

function getIndexingSkippedView {
    # 選んだものだけの回で、更新できなかった名前（インデクサの OnlySkipped。@{ Name; Reason } の配列）を知らせる文言。
    # 無ければ $null。@{ Heading; Detail }
    param (
        [object[]]$skipped
    )

    $skipped = @($skipped | Where-Object { $null -ne $_ })
    if ($skipped.Count -eq 0) { return $null }
    return @{
        Heading = "{0:#,0} 件のインデックスは更新できませんでした。" -f $skipped.Count
        Detail = ($skipped | ForEach-Object { "「$($_.Name)」: $($_.Reason)" }) -join "`n"
    }
}

function getIndexingCurrentName {
    # 取り込み中のファイル（<インデックス名>\<相対パス>）から、インデックス名を取り出す。取れなければ空文字列
    param (
        [string]$current
    )

    $index = $current.IndexOf("\")
    if ($index -lt 1) { return "" }
    return $current.Substring(0, $index)
}

function getIndexingBannerLevel {
    # 更新が終わった帯の色の種類（info/warn/ok/ng のうち、ここでは warn か ok）。
    # 注意が要る終わり方（更新そのものができなかった・中止・取りやめ・失敗したファイルがある）は橙の warn、
    # 失敗なく終わったときだけ緑の ok。赤（ng）は、使えない状態（ワークスペースが使えないなど）にだけ使う
    param (
        [int]$exitCode,  # インデクサの終了コード（0 完了、1 続けられないエラー、2 中止・取りやめ）
        [int]$failed     # 失敗したファイルの件数
    )

    if ($exitCode -ne 0) { return "warn" }
    if ($failed -gt 0) { return "warn" }
    return "ok"
}

function getIndexingBannerBehavior {
    # 帯がいつ消えるか。@{ Closable; AutoCloseSeconds }
    #   Closable: 閉じるボタン（×）を出すか
    #   AutoCloseSeconds: 出してから自動で消すまでの秒数（0 なら自動では消えない）
    # 帯はどの種類でも閉じられる（閉じるボタンを出す）。更新中（run）は、進み具合がステータスバーと行にも出るので閉じてよい。
    # 閉じるのは見せ方だけで、更新は止まらない（止めるのは帯の［中止］か行の［中止］。帯を閉じたあとは行の［中止］）。
    # 自動で消えるのは、残りの無い成功（ok）だけ（数秒）。更新中と、残りがあって更新していないとき（pending が 1 以上。
    # 内部では resume として扱う）は、［続きから再開］を載せているので、消さずに残す。それ以外（warn・info・ng）も閉じるまで残る
    param (
        [string]$level,  # run / ok / info / warn / ng
        [int]$pending = 0  # 取り込みの残りの件数
    )

    if ($level -ne "run" -and $pending -gt 0) { $level = "resume" }
    switch ($level) {
        { $_ -in @("run", "resume") } { return @{ Closable = $true; AutoCloseSeconds = 0 } }
        "ok" { return @{ Closable = $true; AutoCloseSeconds = 8 } }
        default { return @{ Closable = $true; AutoCloseSeconds = 0 } }
    }
}

function getIndexingResumeBannerDecision {
    # 更新の集計を読み直したときの、帯の扱い。@{ Action; Dismissed; CanResume }
    #   Action: Show（中断の帯を出す）/ Text（出ている中断の帯の文だけ直す）/ Retime（終わりの帯の自動で消える時計を決め直す）/
    #           Hide（出ている中断の帯を消す）/ None（何もしない）
    #   CanResume: 残りがあり、いま更新していない（［続きから再開］を出せる）か
    #   Dismissed: 次に持ち越す「利用者が閉じた」印。残りが無くなる・更新を始めると戻す（閉じたあとの読み直しでは出し直さない）
    param (
        [int]$pending,             # 取り込みの残りの件数
        [bool]$indexing,           # いま更新しているか
        [bool]$panelVisible,       # 帯が出ているか
        [string]$kind,             # 出ている帯の種類（running / interrupted / done / 空）
        $dismissed = $false,       # 利用者が閉じた印（まだ一度も決めていないと $null）
        [string]$level = "",       # 出ている帯の level（getIndexingBannerBehavior に渡す）
        [int]$currentAutoClose = 0 # いま掛けている自動で消えるまでの秒数
    )

    $dismissed = [bool]$dismissed
    $canResume = ($pending -gt 0) -and !$indexing
    if (!$canResume) { $dismissed = $false }
    $action = "None"
    if ($canResume -and !$panelVisible -and !$dismissed) {
        $action = "Show"
    } elseif ($canResume -and $kind -eq "interrupted") {
        $action = "Text"
    } elseif ($kind -eq "done" -and $panelVisible) {
        # 終わりの帯（完了・中止）は、出した時点の古い集計で時計を決めている。残りの有無が変わって秒数が違うときだけ決め直す
        $pendingNow = if ($canResume) { $pending } else { 0 }
        $seconds = [int](getIndexingBannerBehavior $level $pendingNow).AutoCloseSeconds
        if ($seconds -ne $currentAutoClose) { $action = "Retime" }
    } elseif (!$canResume -and $kind -eq "interrupted") {
        $action = "Hide"
    }
    return @{ Action = $action; Dismissed = $dismissed; CanResume = $canResume }
}

function getIndexingEndText {
    # インデックス作成が完了した（終了コード 0）ときの、進み具合の見出しと説明（@{ Text; Detail }）を返す。
    # 利用者のPowerPointのために取り込めなかったファイルは、失敗の件数に入っている
    param (
        [int]$success,
        [int]$failed,
        [int]$cloudSkipped = 0  # クラウドにだけあるため、ダウンロードせずに残した件数
    )

    $cloudText = if ($cloudSkipped -gt 0) { "クラウドにだけあるファイル {0:#,0} 件は、ダウンロードせずに残しました（次のインデックス作成でも確かめます）。" -f $cloudSkipped } else { "" }
    $processed = $success + $failed
    if ($processed -gt 0) {
        $counts = "成功 ${success} 件 / 失敗 ${failed} 件"
        $parts = New-Object System.Collections.Generic.List[string]
        if ($failed -gt 0) {
            $parts.Add("失敗したファイルと原因は「更新に失敗したファイル」の一覧で確認できます。")
        }
        if ($cloudText) {
            $parts.Add($cloudText)
        }
        return @{ Text = "更新が終わりました（${counts}）"; Detail = ($parts -join " ") }
    }
    if ($cloudSkipped -gt 0) {
        return @{ Text = $cloudText; Detail = "" }
    }
    return @{ Text = "更新が必要なファイルはありませんでした"; Detail = "" }
}

function getIndexingStateText {
    # ボタンの上の一言（取り込み一覧の「未取り込み」の残り件数から。中断でも後回しでも同じ状態のため見分けない）。
    # インデックス作成中は出さない（そのときは別の一言をボタンの下に出す）
    param (
        [int]$pending,
        [bool]$indexing
    )

    if ($pending -gt 0 -and !$indexing) {
        return "更新を中断しました（残り ${pending} 件）"
    }
    return ""
}

function getWorkspaceCheckingStatus {
    # インデックス作成を始める前に、ネットワークのワークスペースを確かめている間のステータス
    return "ワークスペースを確かめています…（共有フォルダに接続できないときは、しばらくかかります）"
}

function getWorkspaceUnreachableStatus {
    # ネットワークのワークスペースに接続できず、インデックス作成を始めなかったときのステータス
    param (
        [string]$dir
    )

    return "ワークスペースに接続できません：${dir}"
}

function getReingestConfirm {
    # ［すべて更新］の確かめ。前の版のしるしがあり content_index\ が空のときだけ確かめの文言を返し、
    # ほかの 3 通り（しるしが無い・空でない）では確かめを出さない（空を返す）
    param (
        [bool]$hasLegacyIndex,
        [bool]$contentEmpty
    )

    if ($hasLegacyIndex -and $contentEmpty) {
        return "前の版のインデックスは使えないため、元のファイルをすべて更新し直します。ファイルが多いと時間がかかります。始めますか？"
    }
    return ""
}

function testIndexingPlanSelected {
    # 確認に数える行か。選んだものだけの回（onlyNames）では、選んだインデックスの行だけ。
    # 取り込み予定は、選ばなかったインデックスの行も含むことがあるため、画面側の確認で絞る
    param (
        $item,
        [string[]]$onlyNames = @()
    )

    if ($null -eq $item) { return $false }
    $names = @($onlyNames)
    return ($names.Count -eq 0 -or $names -contains [string]$item.インデックス名)
}

function getIndexingConfirmFolderCount {
    # 確認の合計に出す「更新するフォルダの数」。取り込む対象（失敗分を含めるなら前回失敗も）が 1 件以上あるフォルダだけを数える
    param (
        [object[]]$plan,    # readIngestPlan の結果
        [bool]$retryFailed, # 失敗分も更新し直すか
        [bool]$includeCloud = $false,  # クラウドにだけあるファイルもダウンロードして取り込むか
        [string[]]$onlyNames = @()     # 選んだものだけの回のインデックス名（空なら全部）
    )

    $folders = 0
    foreach ($item in @($plan)) {
        if (-not (testIndexingPlanSelected $item $onlyNames) -or $item.区分 -ne ${planKindIngest}) { continue }
        $count = [int]$item.取り込み対象
        if ($retryFailed) { $count += [int]$item.前回失敗 }
        if ($includeCloud) {
            $count += [int]$item.クラウド
            if ($retryFailed) { $count += [int]$item.クラウド失敗 }
        }
        if ($count -gt 0) { $folders++ }
    }
    return $folders
}

function getIndexingDroppedCount {
    # 確認に出す「削除予定」（設定から外れたインデックス）の数。選んだものだけの回でも数える
    param (
        [object[]]$plan  # readIngestPlan の結果
    )

    return @(@($plan) | Where-Object { $null -ne $_ -and $_.区分 -eq ${planKindDropped} }).Count
}

function isIndexingConfirmNothing {
    # 確認に出すものが何も無いか（更新するファイルも、前回の失敗も、削除予定も無い）。真なら閉じるだけのダイアログにする。
    # 削除予定があるのに閉じるだけにすると、閉じることが承認扱いになり、見せたまま消してしまう
    param (
        [int]$targets,  # 更新対象のファイル数
        [int]$failed,   # 前回失敗したファイル数
        [int]$dropped,  # 削除予定のインデックスの数（getIndexingDroppedCount）
        [int]$cloud = 0 # クラウドにだけあるファイル数（1 件でもあれば、ダウンロードして取り込むかを選べるよう、閉じるだけにしない）
    )

    return ($targets -eq 0 -and $failed -eq 0 -and $dropped -eq 0 -and $cloud -eq 0)
}

function getIndexingConfirmIntro {
    # 確認の説明文。削除予定があるときだけ、消すことが分かる一文を返す（無ければ空文字列。ふだんは何も出さない）
    param (
        [int]$dropped = 0  # 削除予定のインデックスの数（getIndexingDroppedCount）
    )

    if ($dropped -gt 0) {
        return "［更新を開始］を押すと、設定に無いインデックスも削除します。"
    }
    return ""
}

function getIndexingConfirmText {
    # 「失敗分も更新し直す」のチェックに合わせた、合計の文言と主ボタンの文言
    param (
        [int]$targets,      # 更新対象のファイル数
        [int]$failed,       # 前回失敗したファイル数
        [bool]$retryFailed, # 失敗分も更新し直すか
        [int]$folders = 0,  # 更新するフォルダの数（失敗分を含めるかは呼び出し側で数える）
        [int]$dropped = 0,  # 削除予定のインデックスの数（getIndexingDroppedCount）
        [int]$cloud = 0,    # クラウドにだけあるファイル数（getIndexingCloudView。取り込み対象には数えていない）
        [bool]$includeCloud = $false  # クラウドにだけあるファイルもダウンロードして取り込むか
    )

    $total = $targets
    if ($retryFailed) {
        $total += $failed
    }
    if ($includeCloud) {
        $total += $cloud
    }
    $droppedText = if ($dropped -gt 0) { "設定に無いインデックス {0:#,0} 件を削除します。" -f $dropped } else { "" }
    $cloudText = if ($cloud -gt 0 -and -not $includeCloud) { "クラウドにだけあるファイル {0:#,0} 件は、ダウンロードせずに残します。" -f $cloud } else { "" }
    $tail = (@($droppedText, $cloudText) | Where-Object { $_ }) -join " "
    if ($total -gt 0) {
        return @{ Total = $total; Text = ("更新対象: {0:#,0} フォルダ / {1:#,0} ファイル（最新のフォルダは更新しません）" -f $folders, $total) + $(if ($tail) { " " + $tail } else { "" }); Button = "更新を開始" }
    }
    if ($dropped -gt 0) {
        return @{ Total = 0; Text = "更新が必要なファイルはありません。" + $tail; Button = "更新を開始" }
    }
    if ($cloud -gt 0) {
        # 閉じるだけにしない（［更新を開始］で、クラウドにだけあるため残すファイルの扱いを進める。取りやめは［キャンセル］）
        return @{ Total = 0; Text = "更新が必要なファイルはありません。" + $cloudText; Button = "更新を開始" }
    }
    return @{ Total = 0; Text = "更新が必要なファイルはありません（すべて最新です）。"; Button = "閉じる" }
}

# ---- クラウドにだけあるファイル（OneDrive・SharePoint のオンデマンド） ----

function formatCloudSize {
    # 合計サイズの書き方。KB・MB・GB のどれかで、小数点以下 1 桁（"約 12.3 MB"）。1 KB に満たなければ "1 KB 未満"
    param (
        [long]$bytes
    )

    $culture = [System.Globalization.CultureInfo]::InvariantCulture
    if ($bytes -lt 1KB) { return "1 KB 未満" }
    # 小数点以下 1 桁に丸めて 1024 になるとき（1 MB の直前など）は、次の単位で書く（"約 1024.0 KB" にしない）
    $units = @("KB", "MB", "GB")
    $value = [double]$bytes / 1KB
    $index = 0
    while ($index -lt 2 -and [math]::Round($value, 1, [System.MidpointRounding]::AwayFromZero) -ge 1024) {
        $value = $value / 1024
        $index++
    }
    return "約 " + $value.ToString("0.0", $culture) + " " + $units[$index]
}

function getIndexingCloudView {
    # 確認に出す、クラウドにだけあるファイルの件数と合計サイズ（@{ Count; Bytes }）。
    # 前回失敗したファイルは、「失敗分も更新し直す」を選んだときだけ数える（選ばなければ、クラウドに関係なく取り込まないため）
    param (
        [object[]]$plan,    # readIngestPlan の結果
        [bool]$retryFailed,
        [string[]]$onlyNames = @()  # 選んだものだけの回のインデックス名。取り込み予定には選ばなかった行も含まれるため、ここで絞る
    )

    $count = 0
    [long]$bytes = 0
    foreach ($item in @($plan)) {
        if (-not (testIndexingPlanSelected $item $onlyNames) -or $item.区分 -ne ${planKindIngest}) { continue }
        $count += [int]$item.クラウド
        $bytes += [long]$item.クラウド容量
        if ($retryFailed) {
            $count += [int]$item.クラウド失敗
            $bytes += [long]$item.クラウド失敗容量
        }
    }
    return @{ Count = $count; Bytes = $bytes }
}

function getIndexingCloudWarning {
    # 確認に出す、クラウドにだけあるファイルの注意書き
    param (
        [int]$count,
        [long]$bytes
    )

    return ("クラウドにだけあるファイル {0:#,0} 件（合計 {1}）は、既定ではダウンロードせずに残します。取り込むと、そのすべてをこの PC にダウンロードします。登録するフォルダを、要るものだけに絞ることをおすすめします。" -f $count, (formatCloudSize $bytes))
}

function getIndexingCloudCheckText {
    param (
        [int]$count
    )

    return ("クラウドにだけあるファイル {0:#,0} 件もダウンロードして取り込む" -f $count)
}

${indexingCloudRememberText} = "次からこの確認を出さずにダウンロードする"

function getIndexingCloudConfirmView {
    # ダウンロードして取り込む前の、2 度目の確認の文言（showConfirm に渡す）
    param (
        [int]$count,
        [long]$bytes,
        [int]$timeoutMinutes  # 1 ファイルの制限時間（分。インデクサの ${ingestFileTimeoutMinutes}）
    )

    return @{
        Heading = ("{0:#,0} 件（合計 {1}）をダウンロードして取り込みますか？" -f $count, (formatCloudSize $bytes))
        Facts = @(
            "ダウンロードの間、ネットワークの帯域とこの PC のディスクの空きを使います。"
            "ダウンロードしたファイルは、OneDrive の［空き容量を増やす］を行うまで、この PC に残ります。"
            "ダウンロードも含めて 1 ファイルが ${timeoutMinutes} 分以内に終わらなければ、そのファイルは失敗になります。失敗したファイルは、手元に落としてから取り込み直してください。"
        )
        Choices = @(@{ Text = "ダウンロードして取り込む"; Value = "download" })
        CancelText = "キャンセル"
    }
}

function testIndexingCloudNeedsConfirm {
    # ダウンロードして取り込むときに、2 度目の確認を出すか。設定がすでに download（確認を出さない）なら出さない
    param (
        [bool]$cloudChecked,
        [string]$savedMode
    )

    return ($cloudChecked -and $savedMode -ne ${cloudFilesDownload})
}

function getIndexingCloudSavedMode {
    # 開始するときに設定へ保存する値。両方のチェックが付いていれば download、それ以外は ask
    param (
        [bool]$cloudChecked,
        [bool]$rememberChecked
    )

    if ($cloudChecked -and $rememberChecked) {
        return ${cloudFilesDownload}
    }
    return ${cloudFilesAsk}
}

function getIndexingCloudModeToSave {
    # 開始するときに設定の cloudFiles へ書く値。書かないとき（クラウドの欄を出していない・今の設定と同じ）は $null
    param (
        [bool]$cloudVisible,    # クラウドの欄を出したか（getIndexingConfirmView の CloudVisible）
        [bool]$cloudChecked,    # ダウンロードして取り込むを選んだか（同 Include）
        [bool]$rememberChecked,
        [string]$savedMode      # 開くときに読んだ cloudFiles
    )

    if (-not $cloudVisible) { return $null }
    $mode = getIndexingCloudSavedMode $cloudChecked $rememberChecked
    if ($mode -eq $savedMode) { return $null }
    return $mode
}

function getIndexingConfirmView {
    # 確認のダイアログの、チェックの値で変わる表示をまとめて決める。画面は結果を当てるだけにする。
    # クラウドの欄は、そのときの「失敗分も更新し直す」の値で数えたクラウドの件数が 1 件以上のときだけ出す
    # （クラウドにだけある前回失敗は、更新し直すを選んだときだけ数える）。件数が 0 なら、クラウドのチェックは付いていないものとして扱う。
    param (
        [object[]]$plan,          # readIngestPlan の結果
        [string[]]$onlyNames = @(),
        [bool]$retryChecked = $false,
        [bool]$cloudChecked = $false
    )

    $targets = 0
    $failed = 0       # 前回失敗（手元にある）
    $cloudFailed = 0  # 前回失敗（クラウドにだけある）
    foreach ($item in @($plan)) {
        if (-not (testIndexingPlanSelected $item $onlyNames) -or $item.区分 -ne ${planKindIngest}) { continue }
        $targets += [int]$item.取り込み対象
        $failed += [int]$item.前回失敗
        $cloudFailed += [int]$item.クラウド失敗
    }
    $dropped = getIndexingDroppedCount $plan

    $retryVisible = (($failed + $cloudFailed) -gt 0)
    $retry = ($retryChecked -and $retryVisible)
    $retryText = "前回更新に失敗し、その後変わっていないファイル {0:#,0} 件も更新し直す（パスワード付きなど）" -f ($failed + $cloudFailed)
    if ($cloudFailed -gt 0) {
        $retryText += "。うちクラウドにだけある {0:#,0} 件は、ダウンロードして取り込むを選んだときだけ" -f $cloudFailed
    }

    $cloud = getIndexingCloudView $plan $retry $onlyNames
    $cloudVisible = ($cloud.Count -gt 0)
    $include = ($cloudChecked -and $cloudVisible)
    $cloudAll = getIndexingCloudView $plan $true $onlyNames
    $folders = getIndexingConfirmFolderCount $plan $retry $include $onlyNames

    return @{
        Targets        = $targets
        Failed         = $failed
        Dropped        = $dropped
        Nothing        = (isIndexingConfirmNothing $targets ($failed + $cloudFailed) $dropped $cloudAll.Count)
        RetryVisible   = $retryVisible
        RetryText      = $retryText
        Retry          = $retry
        Cloud          = $cloud
        CloudVisible   = $cloudVisible
        Include        = $include
        CloudWarn      = $(if ($cloudVisible) { getIndexingCloudWarning $cloud.Count $cloud.Bytes } else { "" })
        CloudCheckText = $(if ($cloudVisible) { getIndexingCloudCheckText $cloud.Count } else { "" })
        Confirm        = (getIndexingConfirmText $targets $failed $retry $folders $dropped $cloud.Count $include)
    }
}

# 待つ間のダイアログ（shared\ui\shell.ps1 の showWaitDialog）に出す文言・秒読み・進み具合の棒の値の決定。
# 画面に触らないため、そのままテストできる（tests\tebunko\ui\wait_view.Tests.ps1）。

function getWaitDialogView {
    # 場面ごとの見出し・説明・押せないボタンの文字を返す。@{ Heading; Description; ButtonText }
    #   Stopping:  ［中止］を押したあと、読み取り中のファイルが終わるまで
    #   CloseWait: 窓を閉じるときに、インデックス作成が止まるまで（強制終了の秒読みつき）
    #   Moving:    ワークスペースの中身を移す間
    #   MovingClose: ワークスペースを移す間に窓を閉じようとしたとき（移し終わってから閉じる。秒読みは出さない）
    param (
        [string]$kind
    )

    switch ($kind) {
        "Stopping" {
            return @{ Heading = "中止しています…"; Description = "読み取り中のファイルが終わるまでお待ちください。"; ButtonText = "" }
        }
        "CloseWait" {
            return @{ Heading = "中止しています…"; Description = "読み取り中のファイルが終わると、画面を閉じます。"; ButtonText = "閉じない" }
        }
        "Moving" {
            return @{ Heading = "ワークスペースを移しています…"; Description = "中身の量によっては時間がかかります。終わるまでお待ちください。"; ButtonText = "" }
        }
        "MovingClose" {
            return @{ Heading = "ワークスペースを移しています…"; Description = "移し終わると、画面を閉じます。"; ButtonText = "" }
        }
        default {
            throw "待つ間のダイアログの場面が不明です: $kind"
        }
    }
}

function getForceCloseCountdownText {
    # 強制終了までの残りの秒から、秒読みの 1 行を作る。端数は切り上げ、0 秒より小さいときは 0 にする
    param (
        [double]$secondsLeft
    )

    $seconds = [int][Math]::Max(0, [Math]::Ceiling($secondsLeft))
    return "あと $seconds 秒で強制終了します"
}

function getWaitProgressValue {
    # 処理した件数と総数から、進み具合の棒の値を決める。@{ Indeterminate; Value }
    # 総数が 0 以下（まだ数え終わっていない・不明）のときは流れる棒（不確定）。分かるときは 0 から 1 の割合（1 を超えない）
    param (
        [double]$processed,
        [double]$total
    )

    if ($total -le 0) {
        return @{ Indeterminate = $true; Value = 0.0 }
    }
    $ratio = [Math]::Min(1.0, [Math]::Max(0.0, $processed / $total))
    return @{ Indeterminate = $false; Value = $ratio }
}

# 検索バー（検索ワード・種類のチップ・ファイル内の対象・検索ボタン）の判断（判断層）。
# 画面に触らないため、そのままテストできる（tests\tebunko\ui\search\search_bar_view.Tests.ps1）。

function describeSearchOption {
    # 既定から変えた検索条件を「大文字・小文字を区別・種類：Excel・テキスト」のように返す（無ければ空）
    param (
        [hashtable]$option
    )

    $items = @()
    if ($option.CaseSensitive) {
        $items += "大文字・小文字を区別"
    }
    $kindText = describeFileKinds $option.FileKinds
    if ($kindText -ne "") {
        $items += "種類：$kindText"
    }
    # 既定はどちらも検索する（項目が無い古い形の条件も、検索するものとみなす）
    if ($option.ContainsKey("IncludeShapes") -and -not $option.IncludeShapes) {
        $items += "図形を除く"
    }
    if ($option.ContainsKey("IncludeComments") -and -not $option.IncludeComments) {
        $items += "コメントを除く"
    }
    return ($items -join "・")
}

function getFileKindLabel {
    # 種類（excel・word・powerpoint・text・pdf）のチップに出す名前。知らない種類は空
    param (
        [string]$kind
    )

    switch ($kind) {
        "excel" { return "Excel" }
        "word" { return "Word" }
        "powerpoint" { return "PowerPoint" }
        "text" { return "テキスト" }
        "pdf" { return "PDF" }
    }
    return ""
}

function toggleFileKind {
    # チップを押したあとの、選ばれている種類（${fileKindNames} の順）を返す。
    # 全部外してよい（空は「1 つも選んでいない」。検索を始めるときに getSearchKindBalloonText が知らせる）
    param (
        [object[]]$kinds,
        [string]$kind
    )

    $current = @(${fileKindNames} | Where-Object { @($kinds) -contains $_ })
    if (${fileKindNames} -notcontains $kind) {
        return $current
    }
    if ($current -contains $kind) {
        return @($current | Where-Object { $_ -ne $kind })
    }
    return @(${fileKindNames} | Where-Object { $current -contains $_ -or $_ -eq $kind })
}

function getSearchKindBalloonText {
    # 検索を始められない理由（種類のチップを 1 つも選んでいないとき）を知らせる吹き出しの文。
    # 始められるときは $null（吹き出しを出さない）
    param (
        [object[]]$kinds
    )

    $chosen = @(${fileKindNames} | Where-Object { @($kinds) -contains $_ })
    if ($chosen.Count -eq 0) {
        return "種類を 1 つ以上選んでください"
    }
    return $null
}

function describeFileKinds {
    # 絞り込んでいる種類を「Excel・テキスト」の形で返す。すべて選んでいる（または空）ときは空
    param (
        [object[]]$kinds
    )

    $chosen = @(${fileKindNames} | Where-Object { @($kinds) -contains $_ })
    if ($chosen.Count -eq 0 -or $chosen.Count -eq ${fileKindNames}.Count) {
        return ""
    }
    return (@($chosen | ForEach-Object { getFileKindLabel $_ }) -join "・")
}

function getNoKindMatchText {
    # 選んだ種類に合うファイルが検索の対象に無いときの文言
    param (
        [object[]]$kinds
    )

    $text = describeFileKinds $kinds
    if ($text -eq "") {
        return "検索できるファイルがありません。"
    }
    return "種類（$text）に合うファイルがありません。"
}

function getTargetCountText {
    # 左の欄の見出し。インデックス（一番上の項目）のうち、すべて選んでいる数 / インデックスの数。無いときは見出しだけ
    param (
        [int]$checked,
        [int]$total
    )

    if ($total -le 0) {
        return "検索対象"
    }
    return "検索対象 $checked / $total"
}

function getWorkspaceUnreachableText {
    # ワークスペースに接続できないときの知らせ（ステータスと、検索対象の欄の文言に使う）
    param (
        [string]$workspaceDir
    )

    return "ワークスペースに接続できません：$workspaceDir"
}

function getWorkspaceCheckingText {
    # ワークスペースが届くかを裏で確かめている間のステータス
    return "ワークスペースを確かめています…"
}

function getTreeFolderFailedText {
    # ツリーのフォルダの子を読み込めなかったときのステータス
    param (
        [string]$folder,
        [string]$reason
    )

    return "フォルダを読み込めませんでした：$folder（$reason）"
}

function getSearchTargetText {
    # 左の欄の見出しのツールチップ（検索対象の詳しい中身）。
    # 優先の順: 読み込み中、接続できない、インデックスが無い、チェックなし、一部、確認中、すべて
    param (
        [bool]$loading,            # 検索対象のツリーを裏で読んでいる最中か
        [string]$connectErrorDir,  # ワークスペースに接続できなかったときのワークスペース（できたなら空）
        [int]$total,               # インデックスの数
        [int]$targetCount,         # 検索対象に選ばれている数
        [bool]$allChecked,         # インデックスがすべてチェックされているか
        [string]$targetsText,      # 選ばれた検索対象の表示（describeSearchTargets）
        $summary                   # 本文インデックスのファイルの集計（Count・LastWrite。まだ数えていなければ $null）
    )

    if ($loading) {
        return "検索対象：読み込んでいます…"
    }
    if ($connectErrorDir) {
        return "検索対象：なし（$(getWorkspaceUnreachableText $connectErrorDir)）"
    }
    if ($total -eq 0) {
        return "［インデックス管理］で作ったインデックスの一覧です"
    }
    if ($targetCount -eq 0) {
        return "検索対象：なし"
    }
    if (!$allChecked) {
        return "検索対象：$targetsText"
    }
    if ($null -eq $summary) {
        return "検索対象：すべて（確認中…）"
    }
    return "検索対象：すべて（集約ファイル $($summary['Count'].ToString('N0')) 件 ・ 最終更新 $(formatTime $summary['LastWrite'])）"
}

function getScopeButtonText {
    # ［ファイル内の対象］ボタンの文言（Text）と、既定から変えているか（Changed）。
    # 既定（図形・コメントも検索）から外したものがあれば「・2 件変更」を付ける
    param (
        [bool]$includeShapes,
        [bool]$includeComments
    )

    $changed = @($includeShapes, $includeComments | Where-Object { !$_ }).Count
    if ($changed -eq 0) {
        return @{ Text = "ファイル内の対象"; Changed = $false }
    }
    return @{ Text = "ファイル内の対象・$changed 件変更"; Changed = $true }
}

function getWordNotice {
    # 正規表現が正しくないときの吹き出しの文（［正規表現］の下に出す。正しいとき・使わないときは空文字列）
    param (
        [string]$word,
        [bool]$useRegex
    )

    if ($useRegex -and $word -ne "" -and !(isValidRegex $word)) {
        return "正規表現が正しくありません"
    }
    return ""
}

function getFastSearchView {
    # 検索ワードの下に出す、高速検索（Windows Search で先に絞る）の使用可否。
    #   available: Windows Search が使えるか（testWindowsSearch）。$null はまだ確かめていない（使えるものとして扱う）
    # Tip は、印にマウスを置いたときのツールチップ。使えるときは印の意味、使えないときは理由と直し方（どの場合も空にしない）。
    # GoToIndex は、印を押すとインデックス管理へ移るか。Windows Search が使えないとき（Tip の［インデックス管理で確認］）だけ。
    # 正規表現・語の長さが理由のときは、検索条件で直せるので移らない
    # 使えない理由は、上から順に最初に当てはまるもの
    param (
        $available,
        [bool]$useRegex,
        [string]$word
    )

    $usable = testFastSearchUsable ($available -ne $false) $useRegex $word
    $tip = "インデックスを使って速く検索します"
    if (!$usable) {
        if ($available -eq $false) {
            $tip = "検索はできますが時間がかかります　［インデックス管理で確認］"
        } elseif ($useRegex) {
            $tip = "正規表現をオフにすると速く検索できます"
        } else {
            $tip = "空白で区切った語のどれかが 2 文字以上のときに使えます"
        }
    }
    return @{ Usable = $usable; Text = if ($usable) { "高速検索：使用可" } else { "高速検索：使用不可" }; Tip = $tip; GoToIndex = (!$usable -and $available -eq $false) }
}

function newSearchButtonState {
    # ［検索］ボタンの文言と、押せるかどうか
    param (
        [bool]$searching,    # 検索中か
        [bool]$stopping,     # 中止を頼んだ後か
        [string]$word,       # 検索ワード
        [bool]$hasIndex,     # 検索できるインデックスがあるか
        [int]$targetCount,   # 検索対象に選ばれている数
        [bool]$wordInvalid,  # 正規表現が正しくないか（getWordNotice が空でないとき）
        [bool]$loading = $false  # 検索対象のツリーを読み込み中か（読み込み中は検索できない）
    )

    if ($searching) {
        return @{ Content = "中止"; Enabled = !$stopping }
    }
    return @{ Content = "検索"; Enabled = ($word -ne "" -and $hasIndex -and $targetCount -gt 0 -and !$wordInvalid -and !$loading) }
}

function getBalloonLeft {
    # 吹き出しの左端。基準の左端にそろえ、右端がはみ出すときは右端に収まるまで左へ寄せる（左は 0 より左へ出さない）。
    #   anchorLeft: 基準の項目の左端、width: 吹き出しの幅、available: 置ける幅、margin: 右端に残す間
    param (
        [double]$anchorLeft,
        [double]$width,
        [double]$available,
        [double]$margin = 8
    )

    $left = [Math]::Min($anchorLeft, $available - $margin - $width)
    return [Math]::Max(0.0, $left)
}

function getConditionFlow {
    # 検索条件の行（種類・チップ・ファイル内の対象・検索条件・高速検索の印）の折り返しを決める。
    # 項目は左から順に並べ、入りきらなくなったら次の行の左端へ落ちる（後ろの項目から落ちる）。
    # 「伸びる空き」は spacerIndex 番の項目の前に置き、その行の余りを全部取る（右の組を右端に寄せる）。
    # widths は各項目の幅（右の間を含む。出していない項目は 0）。available は並べられる幅（右の間を含む）。
    # 返すもの: Lines（行ごとの項目の番号）・SpacerWidth（空きの幅）・LineStarts（各項目が行の先頭か）
    param (
        [double[]]$widths,
        [int]$spacerIndex,
        [double]$available
    )

    $lines = New-Object System.Collections.Generic.List[object]
    $current = New-Object System.Collections.Generic.List[int]
    $sums = New-Object System.Collections.Generic.List[double]
    $sum = 0.0
    $starts = New-Object bool[] $widths.Count
    for ($i = 0; $i -lt $widths.Count; $i++) {
        if ($widths[$i] -le 0) { continue }
        if ($current.Count -gt 0 -and ($sum + $widths[$i]) -gt $available) {
            $lines.Add($current.ToArray())
            $sums.Add($sum)
            $current = New-Object System.Collections.Generic.List[int]
            $sum = 0.0
        }
        if ($current.Count -eq 0) { $starts[$i] = $true }
        $current.Add($i)
        $sum += $widths[$i]
    }
    if ($current.Count -gt 0) {
        $lines.Add($current.ToArray())
        $sums.Add($sum)
    }

    # 空きは、空きの前の最後の項目がある行に置く。その行の余りを取る（取りすぎて折り返さないよう 0.5 だけ残す）
    $spacer = 0.0
    $spacerLine = $null
    for ($line = 0; $line -lt $lines.Count; $line++) {
        $members = @($lines[$line] | Where-Object { $_ -lt $spacerIndex })
        if ($members.Count -gt 0) { $spacerLine = $line }
    }
    if ($null -ne $spacerLine) {
        $spacer = [Math]::Max(0.0, $available - $sums[$spacerLine] - 0.5)
    }
    return @{ Lines = @($lines.ToArray()); SpacerWidth = $spacer; LineStarts = $starts }
}

# 結果の一覧（件数の行・ファイルごとにまとめた表）の判断（判断層）。
# 画面に触らないため、そのままテストできる（tests\tebunko\ui\search\result_list_view.Tests.ps1）。

function getSearchProgressText {
    # 検索中の要約欄
    param (
        [int]$hits
    )

    return "検索中…　該当 $($hits.ToString('N0')) 件"
}

function getSearchSummaryText {
    # 検索が終わったときの要約欄（ヒットがあるとき。秒を渡さなければ時間は付けない）
    param (
        [int]$hits,
        [int]$files,
        [double]$seconds = -1
    )

    $text = "一致 $($hits.ToString('N0')) 件（$($files.ToString('N0')) ファイル）"
    if ($seconds -lt 0) {
        return $text
    }
    return "$text・$($seconds.ToString('0.0')) 秒"
}

function getNoHitText {
    # 検索が 0 件で終わったときの、結果欄の要約と結果の表の空いた所の文（インデックス未作成・種類に合うファイルが無いときは別の文）
    return "一致する結果はありません"
}

function getSearchStatusText {
    # 検索が終わったときのステータスバーの文（0 件もこの形。結果欄の要約には getNoHitText を出す）。
    # 条件（describeSearchOption の結果。無ければ空）があれば、後ろに付ける
    param (
        [string]$word,
        [int]$hits,
        [string]$optionText = ""
    )

    $text = "検索しました：$word $($hits.ToString('N0')) 件"
    if ($optionText -ne "") {
        $text += "　条件：$optionText"
    }
    return $text
}

function getFilteredSummaryText {
    # 結果を絞り込んでいるときの要約欄（全部の件数のうち、いくつ見せているか）
    param (
        [int]$hits,
        [int]$shown
    )

    return "一致 $($hits.ToString('N0')) 件中 $($shown.ToString('N0')) 件を表示"
}

function getAppKind {
    # 元のファイル名の拡張子から、アプリの種類（Excel / Word / PowerPoint / テキスト / PDF。どれでもなければ空）を返す
    param (
        [string]$book
    )

    $extension = [System.IO.Path]::GetExtension($book).ToLowerInvariant()
    if ($extension -match '^\.xls') {
        return "Excel"
    }
    if ($extension -match '^\.doc') {
        return "Word"
    }
    if ($extension -match '^\.ppt') {
        return "PowerPoint"
    }
    if (testTextExtension $book) {
        return "テキスト"
    }
    if (testPdfExtension $book) {
        return "PDF"
    }
    return ""
}

function describeFileLocations {
    # ファイルの中でヒットした場所（見つかった順・重複なし）を、見出しの右端に出す文字列にする。
    # 1 か所ならその場所、2 か所以上なら「[シート]4月 ほか 2 か所」（場所の表記は describePlace）
    param (
        [string[]]$labels
    )

    # 検索中にファイル・場所が増えるたびに呼ぶため、パイプライン（Where-Object）を使わない（1 回 1 ms を超えて検索が遅くなる）
    $first = ""
    $count = 0
    foreach ($label in $labels) {
        if ($label) {
            if ($count -eq 0) {
                $first = $label
            }
            $count++
        }
    }
    if ($count -le 1) {
        return $first
    }
    return "$first ほか $($count - 1) か所"
}

function getFileHeaderLocationPrefix {
    # 見出しの右端（「<場所> ・ N 件」）で、件数の前に付ける場所。場所が 1 か所だけなら、行の「場所」列と同じなので付けない（件数だけにする）。
    # 2 か所以上なら describeFileLocations の文字列に「 ・ 」を付ける
    param (
        [string[]]$labels
    )

    $count = 0
    foreach ($label in $labels) {
        if ($label) { $count++ }
    }
    if ($count -le 1) {
        return ""
    }
    return "$(describeFileLocations $labels) ・ "
}

function getPreviewRowHeight {
    # 結果の表とプレビューの境目。結果が少ないとき（表が内容の高さで足りるとき）は、表を内容の高さまで縮めて、プレビューを広げる。
    #   available: 表とプレビューを合わせた高さ
    #   content  : 表（件数・絞り込みなどの行を含む）が内容に要る高さ。多くて測らないときは $null
    # 表が内容より低くなる（スクロールが要る）ときは、今までどおりの高さ（defaultHeight）にする。表は minResultHeight より低くしない。
    # 表に行がまだ無いとき（起動直後・検索前・0 件）は、内容が空なので広げても使い道が無い。defaultHeight にして、結果の側を大きく保つ
    #   itemCount: 表の行の数（既定は -1 = 行の数を問わない）
    param (
        [double]$available,
        $content,
        [double]$defaultHeight = 180,
        [double]$minResultHeight = 60,
        [int]$itemCount = -1
    )

    if ($null -eq $content -or $itemCount -eq 0) {
        return $defaultHeight
    }
    $height = $available - [double]$content
    if ($height -le $defaultHeight) {
        return $defaultHeight
    }
    return [Math]::Min($height, [Math]::Max($available - $minResultHeight, $defaultHeight))
}

function selectShownRows {
    # 行のうち、絞り込み（空ならすべて）に合うものを、元の順のまま返す
    param (
        $rows,
        [string]$filterText
    )

    $shown = New-Object 'System.Collections.Generic.List[object]'
    foreach ($row in $rows) {
        if ($filterText -eq "" -or $row.Contains($filterText)) {
            $shown.Add($row)
        }
    }
    return , $shown
}

function getResultItems {
    # 結果の表に並べる項目。ファイルごとに見出しを 1 つ置き、開いているファイルだけ、その下に行を並べる。
    # 絞り込みで行が 1 つも残らないファイル（ShownCount が 0）は、見出しも出さない。開いているファイルの行は作ってあること
    param (
        $groups
    )

    $items = New-Object 'System.Collections.Generic.List[object]'
    foreach ($group in $groups) {
        if ($group.ShownCount -eq 0) {
            continue
        }
        $items.Add($group)
        if ($group.IsExpanded) {
            $items.AddRange($group.ShownRows)
        }
    }
    return , $items
}

function getShownHitRows {
    # 絞り込みに合う行を、表の順（閉じているファイルの行も含む）に並べて返す（結果の出力に使う。行はすべて作ってあること）
    param (
        $groups
    )

    $rows = New-Object 'System.Collections.Generic.List[object]'
    foreach ($group in $groups) {
        $rows.AddRange($group.ShownRows)
    }
    return , $rows
}

function prepareHitRow {
    # 画面に出る行の表示用の値（強調セグメント・セル番地・「場所」の列の表記）を作る。作り済みなら何もしない
    param (
        [HitRow]$row
    )

    $row.Prepare()
    if ($row.PlaceDisplay) { return }
    $row.SetPlaceDisplay((describeHitPlace $row.PlaceText $row.IsExcel $row.IsObjectPlace $row.MatchCell $row.MatchCount $row.LineNumber $row.IsText))
}

function sortFileGroups {
    # 列見出しのクリックでの並べ替え。各ファイルの中の行を property の順に並べ替え、
    # ファイルの順は、並べ替えた後の先頭の行の順にする。同じ値のときは見つかった順（Order）
    param (
        $groups,
        [string]$property,
        [bool]$descending
    )

    # 鍵は項目の名前で渡す（スクリプトブロックより速い）。「場所」（Location）は同じ場所の中を行番号の順にする
    # （セル番地の文字の順だと A10 が A9 の前に来るため、番地ではなく行番号で並べる）
    $byValue = @{ Expression = $property; Descending = $descending }
    $byOrder = @{ Expression = "Order"; Descending = $false }
    $rowKeys = if ($property -eq "Location") { @($byValue, @{ Expression = "LineNumber"; Descending = $descending }, $byOrder) } else { @($byValue, $byOrder) }
    foreach ($group in $groups) {
        $sorted = @($group.Rows | Sort-Object $rowKeys)
        $group.Rows.Clear()
        $group.Rows.AddRange([object[]]$sorted)
    }
    $byFirst = @{ Expression = { if ($_.Rows.Count -gt 0) { $_.Rows[0].$property } }; Descending = $descending }
    $sortedGroups = New-Object 'System.Collections.Generic.List[object]'
    $sortedGroups.AddRange([object[]]@($groups | Sort-Object $byFirst, $byOrder))
    return , $sortedGroups
}

function testResultMenuKeepSelection {
    # 結果の行を右クリックしたとき、今の選びを変えずにメニューを出すか。
    # ヒットした行を複数選んでいて、その中の行を右クリックしたときだけ $true（［選んだ行をコピー］のため）。
    # 右クリックした行が選ばれていないとき・見出しのとき・選びに見出しを含むときは $false（右クリックした行だけを選ぶ）。
    #   rowSelected: 右クリックした行が今選ばれているか ／ item: その行の項目 ／ selectedItems: 今の選び
    param (
        [bool]$rowSelected,
        $item,
        $selectedItems
    )

    if (!$rowSelected -or $item -is [FileGroup]) {
        return $false
    }
    return @($selectedItems | Where-Object { $_ -is [FileGroup] }).Count -eq 0
}

function getResultMenuContext {
    # メニューを出す項目（選んでいる項目）から、メニューの種類（"row"・"group"）と、見出しを開いているかを決める
    param (
        $item
    )

    if ($item -is [FileGroup]) {
        return @{ Target = "group"; Expanded = [bool]$item.IsExpanded }
    }
    return @{ Target = "row"; Expanded = $false }
}

function getResultMenuItems {
    # 検索結果の右クリックメニューの並び。
    #   target: "row"（ヒットした行）・"group"（ファイルの見出し）
    #   openMode: 設定の既定の開き方（行のメニューの先頭に太字で出す）
    #   expanded: 見出しの下の行を開いているか（見出しのメニューの開閉の項目の文言を決める）
    #   readOnlySupported: 読み取り専用で開けるファイルか（testReadOnlySupported。Office の形式だけ。偽なら［読み取り専用で開く］を出さない）
    # 返すもの: @{ Id; Header; Bold } の並び。区切りは Id が "separator"。
    # 画面層は、この結果をそのままメニューに並べる（可否や並びを画面層で決めない）
    param (
        [string]$target,
        [string]$openMode = ${openModeNormal},
        [bool]$expanded = $false,
        [bool]$readOnlySupported = $true
    )

    $labels = [ordered]@{
        ${openModeNormal}   = @{ Id = "openNormal";   Header = "開く" }
        ${openModeNew}      = @{ Id = "openNew";      Header = "新規で開く" }
    }
    if ($readOnlySupported) {
        $labels[${openModeReadOnly}] = @{ Id = "openReadOnly"; Header = "読み取り専用で開く" }
    }
    $separator = @{ Id = "separator"; Header = ""; Bold = $false }

    # 先頭は既定の開き方（見出しは読み取り専用。読み取り専用で開けないファイルは通常）。下には、ほかの開き方を
    # ［開く ▼］と同じ順（開く・新規で開く・読み取り専用で開く）で並べる
    $wanted = if ($target -eq "group") { ${openModeReadOnly} } else { $openMode }
    $default = if ($labels.Contains($wanted)) { $wanted } else { ${openModeNormal} }
    $items = @(@{ Id = $labels[$default].Id; Header = $labels[$default].Header; Bold = $true })
    foreach ($mode in $labels.Keys) {
        if ($mode -ne $default) {
            $items += @{ Id = $labels[$mode].Id; Header = $labels[$mode].Header; Bold = $false }
        }
    }
    $items += @{ Id = "openFolder"; Header = "フォルダを開く"; Bold = $false }
    $items += $separator

    if ($target -eq "group") {
        $items += @{ Id = "copyPath"; Header = "ファイルのパスをコピー"; Bold = $false }
        $items += @{ Id = "toggleGroup"; Header = $(if ($expanded) { "この結果を折りたたむ" } else { "この結果を開く" }); Bold = $false }
        return $items
    }
    $items += @{ Id = "copyRows"; Header = "選んだ行をコピー"; Bold = $false }
    $items += @{ Id = "copyPath"; Header = "ファイルのパスをコピー"; Bold = $false }
    return $items
}

# 元のファイルを開くとき（ネットワークにあるときの確認）の文言（判断層）。
# 画面に触らないため、そのままテストできる（tests\tebunko\ui\search\open_source_view.Tests.ps1）。

function getSourceCheckingStatus {
    # 元のファイルの場所を確かめている間のステータス（ネットワークにあるときだけ出す。ローカルはその場で開くため出さない）
    param (
        [string]$path
    )

    return "元のファイルを確かめています…：${path}（共有フォルダに接続できないときは、しばらくかかります）"
}

function getSourceLookingStatus {
    # 元のファイルの場所の記録を読んでいる間のステータス（ネットワークのワークスペースにあるときだけ出す）
    return "パスを調べています…（共有フォルダに接続できないときは、しばらくかかります）"
}

function getSourceLookupFailedStatus {
    # 元のファイルの場所の記録を読めなかったときのステータス
    param (
        [string]$message
    )

    if ($message) {
        return "元のファイルの場所を調べられませんでした：${message}"
    }
    return "元のファイルの場所を調べられませんでした"
}

function getSourceNotFoundStatus {
    # 見つからない・確認で選ばなかったときのステータス
    param (
        [string]$path
    )

    return "元のファイルが見つかりません：${path}"
}

function getSourceUnreachableStatus {
    # 接続できないと分かったときのステータス
    param (
        [string]$folder
    )

    return "元のフォルダに接続できません：${folder}"
}

function getSourceConnectFailureStatus {
    # 接続できない・その他のときの、ダイアログを出した直後のステータス
    param (
        [string]$state,
        [string]$folder,
        [string]$message
    )

    if ($state -eq "Unreachable") {
        return getSourceUnreachableStatus $folder
    }
    return "元のファイルを確かめられませんでした：${message}"
}

function getSourceConnectFailureDialog {
    # 接続できない・その他のときの確認ダイアログの中身。
    #   state: "Unreachable"（接続できない）・"Other"（その他。アクセス拒否・ログオンの失敗など）
    # 返すもの: @{ Heading; Title; Detail; Hint }（Heading はダイアログの見出し、Title・Detail は知らせの1行、Hint は選択肢の説明）
    param (
        [string]$book,
        [string]$state,
        [string]$folder,
        [string]$message
    )

    $heading = "${book} を開けません"
    if ($state -eq "Unreachable") {
        return @{
            Heading = $heading
            Title   = "元のフォルダに接続できません"
            Detail  = $folder
            Hint    = "ネットワーク・VPN の接続を確かめてから、もう一度開いてください"
        }
    }
    return @{
        Heading = $heading
        Title   = "元のファイルを確かめられませんでした"
        Detail  = $message
        Hint    = "アクセスの権限・サインインを確かめてください"
    }
}

# ---- もらったインデックスの元のフォルダを確かめる ----

# マクロ（ファイルの中に仕込まれたプログラム）を持てる形式。もらったインデックスのものは、読み取り専用で開く。
# 取り込みの対象の拡張子（${officeExtensions}）のうち、マクロを持てるものを全部入れる（.xltm・.dotm などは取り込みの対象外のため入れない）
${macroCapableExtensions} = @(".xlsm", ".xlsb", ".xls", ".docm", ".doc", ".pptm", ".ppt")

function testNameInList {
    # name が list のどれかと等しいか。大文字・小文字を区別せず、文字の並びそのもので比べる（OrdinalIgnoreCase。
    # PowerShell の -ieq・-contains はカルチャに従い、ソフトハイフンなどの見えない文字を無視して一致してしまう。
    # 設定の名前の辞書（source_map.ps1）と同じ比べ方にそろえる）
    param (
        [string]$name,
        [string[]]$list = @()
    )

    foreach ($item in @($list)) {
        if ([string]::Equals($item, $name, [System.StringComparison]::OrdinalIgnoreCase)) {
            return $true
        }
    }
    return $false
}

function testSourceReceived {
    # もらったインデックス（このワークスペースで自分が作ったのではないもの）か。名前が分からないときも、もらったものとして扱う。
    #   crawledNames: 自分で作ったインデックスの名前（設定の targetFolders）
    param (
        [string]$name,
        [string[]]$crawledNames = @()
    )

    if ($name -eq "") {
        return $true
    }
    return !(testNameInList $name $crawledNames)
}

function testSourceNeedsConfirm {
    # 元のフォルダに触れる前に、利用者に確かめるかを返す。
    # 元のフォルダが分かっていて（known）、そのインデックス名が確かめ済みの名前（設定の targetFolders・indexSources）に無いとき真。
    # 元のフォルダが分からないときは偽（フォルダを選んでもらう流れに進む）。名前が空のときは、確かめ済みと言えないので毎回確かめる
    param (
        [string]$name,
        [bool]$known,
        [string[]]$confirmedNames = @()
    )

    if (!$known) {
        return $false
    }
    if ($name -eq "") {
        return $true
    }
    return !(testNameInList $name $confirmedNames)
}

function getSourceConfirmDialog {
    # もらったインデックスの元のフォルダを確かめるダイアログの中身。
    #   mayConnect: 元のフォルダがローカルのドライブと分からないか（真なら、接続とサインイン情報について注意を足す）
    #   recordable: 名前を記録できるか（testSourceNameRecordable。偽なら「次からは聞きません」と言わず、毎回確かめると伝える）
    # 返すもの: @{ Heading; Title; Detail; Hint; UseText; PickText }
    param (
        [string]$book,
        [string]$name,
        [string]$folder,
        [bool]$mayConnect,
        [Parameter(Mandatory)][bool]$recordable
    )

    $hint = "［このフォルダを使う］を選ぶと、次からはこのインデックスについて聞きません"
    if (!$recordable) {
        $hint = "このインデックスの名前は記録できないため、［このフォルダを使う］を選んでも、開くたびに確かめます"
    }
    if ($mayConnect) {
        $hint = "開くと、このフォルダに接続し、Windows のサインイン情報が送られることがあります。心当たりのない場所なら、［フォルダを選ぶ］で別のフォルダを選んでください。" + $hint
    }
    return @{
        Heading  = "${book} の元のフォルダを確かめてください"
        Title    = "インデックス [${name}] に書かれた元のフォルダ"
        Detail   = $folder
        Hint     = $hint
        UseText  = "このフォルダを使う"
        PickText = "フォルダを選ぶ"
    }
}

function getSourceConfirmCanceledStatus {
    # 元のフォルダの確認でキャンセルしたときのステータス
    return "開くのをやめました"
}

function getSourceOpenMode {
    # 元のファイルの開き方を決める。もらったインデックス（received）のマクロを持てる形式（${macroCapableExtensions}）は、
    # 開き方が通常・新規でも読み取り専用にする。
    # 返すもの: @{ Mode; Notice; Strict }
    #   Notice: 開けたときに添えて出す知らせ（読み取り専用に替えなかったとき、もう読み取り専用だったときは空）
    #   Strict: 読み取り専用で開けないとき、通常に落とさず開かないこと
    param (
        [string]$book,
        [string]$mode,
        [bool]$received
    )

    # Windows は名前の終わりの . と空白を落として開く（evil.xlsm. は evil.xlsm として開く）ので、落としてから拡張子を見る
    $extension = [System.IO.Path]::GetExtension(([string]$book).TrimEnd('.', ' ')).ToLowerInvariant()
    if (!$received -or !(testNameInList $extension ${macroCapableExtensions})) {
        return @{ Mode = $mode; Notice = ""; Strict = $false }
    }
    $notice = ""
    if ($mode -ne ${openModeReadOnly}) {
        $notice = "もらったインデックスのため、マクロを持てる形式は読み取り専用で開きます"
    }
    return @{ Mode = ${openModeReadOnly}; Notice = $notice; Strict = $true }
}

# 開き方を決めるための、Office の拡張子ごとの種類。取り込みの対象の拡張子（${officeExtensions}）と同じ並び（テストで照らす）。
#   Excel  … COM で開く（新規は Workbooks.Add）
#   Office … Word・PowerPoint。エクスプローラーの動詞（読み取り専用は OpenAsReadOnly、新規は New）で開く
${officeOpenKinds} = @{
    ".xlsx" = "Excel"; ".xlsm" = "Excel"; ".xls" = "Excel"; ".xlsb" = "Excel"
    ".docx" = "Office"; ".docm" = "Office"; ".doc" = "Office"
    ".pptx" = "Office"; ".pptm" = "Office"; ".ppt" = "Office"
}

function getOfficeOpenKind {
    # ファイルの Office の種類（Excel / Office）。Office の形式でなければ空文字。
    # 読み取り専用で開けるか（testReadOnlySupported）・新規で開くやり方（getOpenNewMethod）は、ここで決める
    param (
        [string]$book
    )

    $extension = [System.IO.Path]::GetExtension(([string]$book).TrimEnd('.', ' ')).ToLowerInvariant()
    if ($extension -and ${officeOpenKinds}.ContainsKey($extension)) {
        return ${officeOpenKinds}[$extension]
    }
    return ""
}

function testReadOnlySupported {
    # 読み取り専用で開けるファイルか。Office の形式だけ。
    # テキスト・PDF などは既定のアプリに読み取り専用の開き方が無く、通常と同じ開き方になるため、メニューに出さない
    param (
        [string]$book
    )

    return ((getOfficeOpenKind $book) -ne "")
}

function getOpenNewMethod {
    # ［新規で開く］のやり方を決める。
    #   Excel      … 元のファイルを基にした新しいブック（Workbooks.Add。今までどおり）
    #   Verb       … エクスプローラーの New の動詞（Word・PowerPoint）
    #   Copy       … ほかの種類（テキスト・PDF・そのほか）は、元のファイルのコピーを開く（元のファイルを占有しない）
    param (
        [string]$book
    )

    switch (getOfficeOpenKind $book) {
        "Excel" { return "Excel" }
        "Office" { return "Verb" }
    }
    return "Copy"
}

function getOpenCopyFailedStatus {
    # 開くためのコピーを作れなかったときのステータス。blocker は copySourceForOpen の Reason（空なら、理由を添えない）
    param (
        [string]$path,
        [string]$blocker = ""
    )

    $reason = switch ($blocker) {
        "TooLong" { "ファイル名かフォルダが長すぎるためです。" }
        "Place"   { "コピーの置き場所を確かめられなかったためです。" }
        "Failed"  { "コピーを書き込めなかったためです。" }
        default   { "" }
    }
    return "新規で開くためのコピーを作れませんでした。${reason}元のファイルを開くには［開く］を使ってください：${path}"
}

function getOpenCopyOpenedStatus {
    # コピーを開いたときのステータス。コピーだと分かるよう、コピーのパスと、元のファイルは変わらないことを出す
    #   app: 開いたアプリ（"メモ帳" か空）
    param (
        [string]$path,
        [string]$copyPath,
        [string]$app = ""
    )

    $by = if ($app) { "${app}で" } else { "" }
    return "コピーを${by}新規で開きました（コピー：${copyPath}。保存してもこのコピーに書かれ、元のファイルは変わりません）：${path}"
}

function getSourceReadOnlyFailedStatus {
    # 読み取り専用で開けなかったとき（通常で開くとマクロが動くことがあるため、開かない）のステータス
    param (
        [string]$path
    )

    return "もらったインデックスのファイルは読み取り専用で開けなかったため、開きませんでした。［ファイルのパスをコピー］で場所を調べ、確かめてから開いてください：${path}"
}
function getResultSaveFailedText {
    # 検索結果を search_results.txt に書けなかったときの文（ステータスと検索画面の上の帯に同じ文を出す）
    #   kind: Locked（ほかのアプリが開いている）/ Denied（読み取り専用・書き込み権限が無い。アプリを閉じても直らない）
    param (
        [string]$kind,
        [string]$resultFile
    )

    if ($kind -eq "Denied") {
        return "search_results.txt に書き込む権限がありません（読み取り専用など）。${resultFile} を確かめてから、もう一度出力してください。"
    }
    return "search_results.txt に書き込めません。開いているアプリを閉じてから、もう一度出力してください。"
}

# ［検索］タブのプレビューの判断（選択行を出す位置・読み足し・持つ行の上限・列の幅・短い文字列にする）。
# 画面に触らないため、そのままテストできる（tests\tebunko\ui\preview_view.Tests.ps1）。

function getPreviewTopRow {
    # 選択行をプレビューの上から 3 行目に出すために、一番上に出す行（表の行の番号。0 から）を決める。
    # 選択行の前が 2 行に満たなければ先頭から。選択行が表に無い（-1）ときも先頭から
    param (
        [int]$hitIndex  # 表の中の選択行の番号（無ければ -1）
    )

    return [math]::Max(0, $hitIndex - 2)
}

function getPreviewReadMore {
    # スクロールの位置から、どの向きにどの行を読み足すかを決める。読み足す向きごとに @{ Side; FirstLine; Count } を返す（要らなければ何も返さない。
    # Side は "up"（上。FirstLine から Count 行で、今ある最初の行の直前まで）・"down"（下。今ある最後の行の次から Count 行））。
    # 見えている行が、読んである範囲の端から ahead 行以内に近づいたら、その向きに chunk 行を読み足す。
    # その向きにもう行が無い（done）・その向きを読んでいる途中（loading）ときは頼まない（同じ向きは 1 つずつ）。
    # 上は、1 行目に届くところまでで止める（chunk より少なくなる）
    param (
        [int]$firstVisible,     # 見えている先頭の行の番号（読んである行の中の位置。0 から）
        [int]$lastVisible,      # 見えている最後の行の位置
        [int]$rowCount,         # 読んである行の数
        [int]$firstLine,        # 読んである最初の行の、元のファイルの場所の中の番号（1 から）
        [int]$lastLine,         # 読んである最後の行の番号
        [bool]$topDone,         # 上にもう行が無い（または読めなかった）
        [bool]$bottomDone,
        [bool]$upLoading,       # 上を読んでいる途中
        [bool]$downLoading,
        [int]$ahead = 20,
        [int]$chunk = 200
    )

    if ($rowCount -le 0) { return }
    if (!$topDone -and !$upLoading -and $firstLine -gt 1 -and $firstVisible -le $ahead) {
        $count = [Math]::Min($chunk, $firstLine - 1)
        @{ Side = "up"; FirstLine = $firstLine - $count; Count = $count }
    }
    if (!$bottomDone -and !$downLoading -and ($rowCount - 1 - $lastVisible) -le $ahead) {
        @{ Side = "down"; FirstLine = $lastLine + 1; Count = $chunk }
    }
}

function getPreviewTrim {
    # 持つ行が上限（maxRows）を超えたとき、見ている所から遠い側の端から、どれだけ捨てるかを決める。@{ Side; Count } を返す。
    # Side は "top"（上から捨てる）・"bottom"（下から捨てる）・"none"（捨てない）。1 回に chunk 行ずつ、見えている行は捨てない
    param (
        [int]$firstVisible,     # 見えている先頭の行の位置（読んである行の中。0 から）
        [int]$lastVisible,
        [int]$rowCount,
        [int]$maxRows = 3000,
        [int]$chunk = 200
    )

    if ($rowCount -le $maxRows) { return @{ Side = "none"; Count = 0 } }
    $above = [Math]::Max(0, $firstVisible)
    $below = [Math]::Max(0, $rowCount - 1 - $lastVisible)
    if ($above -gt $below) {
        return @{ Side = "top"; Count = [Math]::Min($chunk, $above) }
    }
    $count = [Math]::Min($chunk, $below)
    if ($count -le 0) { return @{ Side = "none"; Count = 0 } }
    return @{ Side = "bottom"; Count = $count }
}

function getPreviewColumnWindow {
    # 横にスクロールしたとき、画面に見えている列の範囲を決める（見えている列だけセルを作るため）。
    # 戻り値は @{ First; Last; Left; Right }。First・Last は作る最初と最後の列（見えている列の左右に margin 列ずつ足す。0 から。
    # 列が 0 のときは First = 0・Last = -1）、Left・Right は、作らない左の列・右の列の幅の合計。
    # 列の幅は累積（prefix[i] = 先頭から i 列分の幅の合計。長さは列の数 + 1）で受け取り、境目は二分探索で探す
    # （列が非常に多くても、スクロールのたびに列の数だけ繰り返さない。累積は PreviewTable.Prefix が、幅が変わるまで使い回す）
    param (
        [double[]]$prefix,
        [double]$offset,          # 横にスクロールした位置（行番号の列を含む行の左端から）
        [double]$viewportWidth,   # スクロールの見える幅
        [double]$numberWidth,     # 行番号の列の幅
        [int]$margin = 3          # 見えている列の左右に足して作る列の数
    )

    $count = $prefix.Length - 1
    if ($count -le 0) { return @{ First = 0; Last = -1; Left = 0.0; Right = 0.0 } }
    $start = [Math]::Max(0, $offset - $numberWidth)
    $end = $start + [Math]::Max(0, $viewportWidth)
    # 左端が start を超える最初の列（右端 prefix[i + 1] が start より大きい最小の i）
    $low = 0
    $high = $count
    while ($low -lt $high) {
        $mid = [int][Math]::Floor(($low + $high) / 2)
        if ($prefix[$mid + 1] -gt $start) { $high = $mid } else { $low = $mid + 1 }
    }
    if ($low -ge $count) {
        $first = $count - 1
        $last = $count - 1
    } else {
        $first = $low
        # 右端が end に届く最初の列（無ければ最後の列）
        $low = $first
        $high = $count
        while ($low -lt $high) {
            $mid = [int][Math]::Floor(($low + $high) / 2)
            if ($prefix[$mid + 1] -ge $end) { $high = $mid } else { $low = $mid + 1 }
        }
        $last = [Math]::Min($low, $count - 1)
    }
    $first = [Math]::Max(0, $first - $margin)
    $last = [Math]::Min($count - 1, $last + $margin)
    return @{ First = $first; Last = $last; Left = $prefix[$first]; Right = [Math]::Max(0.0, $prefix[$count] - $prefix[$last + 1]) }
}

function getPreviewFillWidth {
    # Excel 以外（Word・PowerPoint・テキスト）のプレビューは列が 1 つ。その幅を、枠の幅いっぱいにする
    # （行番号の列を除いた残り。中身から決めた初めの幅より狭くはしない。枠が狭まれば初めの幅まで戻る）。
    # 枠の幅がまだ分からないとき・列が収まる最小幅に満たないときは初めの幅。
    # 列見出しのドラッグで手で変えた幅（今の幅が、前に合わせた幅と違う）は変えない
    param (
        [double]$viewportWidth,  # プレビューのスクロールの見える幅
        [double]$numberWidth,    # 行番号の列の幅
        [double]$baseWidth,      # 中身から決めた初めの列の幅
        [double]$currentWidth,   # 今の列の幅
        [double]$lastFitWidth,   # 前に合わせた列の幅（初めは初めの幅）
        [double]$minWidth = 24   # これより狭くしない
    )

    if ($currentWidth -ne $lastFitWidth) {
        return $currentWidth
    }
    $fill = $viewportWidth - $numberWidth
    if ($viewportWidth -le 0 -or $fill -lt $minWidth) {
        return $baseWidth
    }
    return [math]::Max($baseWidth, $fill)
}

function toStatusText {
    # ステータスに出す短い文字列（改行・タブはスペースにし、長ければ末尾を省略）
    param (
        [string]$text
    )

    $text = ($text -replace "[`r`n`t]+", " ")
    if ($text.Length -gt 40) {
        return $text.Substring(0, 40) + "…"
    }
    return $text
}

function getPreviewMenuItems {
    # プレビューの右クリックメニューの並び。@{ Id; Header; Bold } の並び（区切りは Id が "separator"）。
    # 先頭は、選んでいる結果の行の場所で元のファイルを開く（ダブルクリックと同じ処理）
    return @(
        @{ Id = "openHere"; Header = "元のファイルのこの場所を開く"; Bold = $true }
        @{ Id = "separator"; Header = ""; Bold = $false }
        @{ Id = "copyCell"; Header = "選んだセルをコピー"; Bold = $false }
        @{ Id = "copyRow"; Header = "この行をコピー"; Bold = $false }
    )
}

# 設定の画面の判断（表示の文言・選んだワークスペースの可否・確認ダイアログの中身）。
# ワークスペースは、インデックス・取り込み一覧・ログを置くフォルダ（$workDir。既定は %USERPROFILE%\Documents\tebunko_ws）。
# 画面に触らないため、そのままテストできる（tests\tebunko\ui\settings\settings_view.Tests.ps1）。

${workspaceSubFolderName} = "workspace"  # 空でないフォルダを選んだとき、中に作るワークスペースのフォルダ名
${workspaceSampleCount}   = 3            # 空でないフォルダの中身の例として出す数

function getWorkspaceView {
    # ワークスペースの表示: @{ Path; Note（既定かどうかの補足）; CanReset（既定の場所でなければ $true。［既定に戻す］を出す） }
    param (
        [string]$workDir,
        [string]$defaultDir
    )

    $isDefault = $workDir.TrimEnd("\").Equals($defaultDir.TrimEnd("\"), [System.StringComparison]::OrdinalIgnoreCase)
    $note = if ($isDefault) { "既定の場所（ドキュメントの tebunko）です。" } else { "既定の場所は「${defaultDir}」です。" }
    return @{ Path = $workDir; Note = $note; CanReset = -not $isDefault }
}

function getWorkspaceCautionTexts {
    # ワークスペースの説明。注意（文字がそのまま入る・更新中は変えられない）を先に、変え方をあとに出す。@{ Caution; HowTo }
    return @{
        Caution = "インデックスには文書の文字がそのまま入ります。アクセス権を絞ったフォルダや、容量のあるドライブを選べます。更新中は変えられません。"
        HowTo   = "空のフォルダを選んでください。変えるとすぐに切り替わり、今のワークスペースの中身（インデックス・ログ）は新しいフォルダへ移します。"
    }
}

function getSettingsFileView {
    # 設定ファイルの場所の表示: @{ Path; Note（ツールのフォルダに置いているか） }
    param (
        [string]$settingsFile,
        [string]$rootDir
    )

    $dir = [System.IO.Path]::GetDirectoryName($settingsFile)
    if ($dir.TrimEnd("\").Equals($rootDir.TrimEnd("\"), [System.StringComparison]::OrdinalIgnoreCase)) {
        return @{ Path = $settingsFile; Note = "ツールのフォルダに置いています。" }
    }
    return @{ Path = $settingsFile; Note = "ツールのフォルダ（${rootDir}）に書き込めないため、既定のワークスペースに置いています。" }
}

function getCountedEntryPaths {
    # ワークスペースに選んだフォルダの中身のうち、「空でない」の数に入れるものを返す。
    # 選んだフォルダが既定のワークスペースのときは、設定ファイルと、それに付いてできるファイル（testSettingsFileName）を数えない
    # （書き込めない場所に置いた tebunko の設定ファイルが、既定のワークスペースの直下にあるため）
    param (
        [string[]]$entryPaths,
        [bool]$isDefaultWorkspace
    )

    if (-not $isDefaultWorkspace) {
        return @($entryPaths)
    }
    return @($entryPaths | Where-Object { -not (testSettingsFileName ([System.IO.Path]::GetFileName($_))) })
}

function testWorkspaceChoice {
    # 選んだフォルダをワークスペースにしてよいかを返す: @{ Kind; Message }
    #   Kind: "same"（今と同じ。何もしない）/ "error"（使えない。Message に理由）/ "ok"
    param (
        [string]$folder,     # 選んだフォルダ
        [string]$current,    # 今のワークスペース
        [bool]$writable,     # 選んだフォルダにファイルを作れるか（testWritableFolder）
        $drives = $null      # ドライブ文字 → 割り当て先（テストで差し替える。$null は getDriveTargets）
    )

    $folder = normalizeFolderPath $folder
    if ($folder -eq "") {
        return @{ Kind = "error"; Message = "フォルダを選んでください。" }
    }
    if (testSameFolder $folder $current $drives) {
        return @{ Kind = "same"; Message = "" }
    }
    # 今のインデックスの中に置くと、ワークスペースの中身がインデックスとして検索される（前の版の index\ が残っている場合も同じ）。
    # フォルダ名は Workspace（core\workspace.ps1）の 1 か所から取る
    $currentWorkspace = [Workspace]::new($current)
    if ((testFolderUnder $folder $currentWorkspace.IndexDir $drives) -or (testFolderUnder $folder $currentWorkspace.LegacyIndexDir $drives)) {
        return @{ Kind = "error"; Message = "「${folder}」は今のインデックスのフォルダの中です。インデックスの外のフォルダを選んでください。" }
    }
    if (-not $writable) {
        return @{ Kind = "error"; Message = "「${folder}」にはファイルを作れません。書き込めるフォルダを選んでください。" }
    }
    return @{ Kind = "ok"; Message = "" }
}

function getWorkspaceInputDecision {
    # 設定のワークスペースの欄に入力したパスを確定するときの判断。@{ Action; Message; Path }
    #   Action: None（変わっていない。欄を今の場所に戻す）/ Invalid（直してほしい。Message に理由）/ Blocked（今は変えられない。Message に理由）/ Apply（Path で、［変更…］で選んだときと同じ確かめ・切り替えに進む）
    # 入力した文字のまま判断し、ドライブ文字で始まるローカルのドライブのパスだけを進める（共有に触れうる整形は、そのあとで行う）。
    # 相対パス・環境変数（%…%）・ネットワークの場所・デバイス名の形（\\.\ \\?\）は受けない
    # （画面のスレッドでネットワークに触らないため。ネットワークは［変更…］で選んでもらう）。
    # フォルダの有無・書き込めるかは、［変更…］で選んだときと同じ testWorkspaceChoice（applyWorkspace）が調べる
    param (
        [string]$text,       # 入力された文字
        [string]$current,    # 今のワークスペース
        $drives = $null,     # ドライブ文字 → 割り当て先（テストで差し替える）
        [scriptblock]$driveType = $null,  # ドライブの種類を引く関数（テストで差し替える。null なら実際のドライブ）
        [string]$blockedMessage = ""      # 今は変えられない理由（更新中など。空なら変えられる）
    )

    $trimmed = $text.Trim().Trim([char]34).Trim()
    if ($trimmed -eq "") {
        return @{ Action = "Invalid"; Message = "ワークスペースにするフォルダのパスを入力してください。"; Path = $current }
    }
    $startMessage = "ドライブ文字から始まるパス（例 D:\tebunko_ws）で入力してください。"
    $networkMessage = "ネットワークの場所（\\サーバー\共有 など）や、つながっていないドライブは、入力では指定できません。［変更…］でフォルダを選んでください。"
    $typed = $trimmed.Replace("/", "\")
    if ($typed.Contains("%")) {
        return @{ Action = "Invalid"; Message = "% を含むパス（環境変数）は入力では指定できません。パスをそのまま入力するか、［変更…］でフォルダを選んでください。"; Path = $current }
    }
    if ($typed.StartsWith("\\?\") -or $typed.StartsWith("\\.\")) {
        return @{ Action = "Invalid"; Message = $startMessage; Path = $current }
    }
    if ($typed.StartsWith("\\")) {
        return @{ Action = "Invalid"; Message = $networkMessage; Path = $current }
    }
    if ($typed -notmatch '^[A-Za-z]:\\') {
        return @{ Action = "Invalid"; Message = $startMessage; Path = $current }
    }
    $isLocal = if ($null -ne $driveType) { testLocalDrivePath $typed $driveType } else { testLocalDrivePath $typed }
    if (!$isLocal) {
        return @{ Action = "Invalid"; Message = $networkMessage; Path = $current }
    }
    # ローカルのドライブと分かってから整形する（短い名前の展開などで共有に触れないため）
    $folder = normalizeFolderPath $typed
    # 予約デバイス名（con・nul など）は、整形でドライブ文字の形でなくなることがある。進めない
    if ($folder -notmatch '^[A-Za-z]:\\') {
        return @{ Action = "Invalid"; Message = "con・nul など、Windows が機器の名前として使う名前は、フォルダの名前にできません。別の名前で入力してください。"; Path = $current }
    }
    if (testSameFolder $folder $current $drives) {
        return @{ Action = "None"; Message = ""; Path = $current }
    }
    if ($blockedMessage -ne "") {
        return @{ Action = "Blocked"; Message = $blockedMessage; Path = $current }
    }
    return @{ Action = "Apply"; Message = ""; Path = $folder }
}

function newWorkspaceConfirm {
    # ワークスペースを変える前の確認ダイアログの中身:
    #   @{ Title; Heading; Facts（@{ Kind = "next" / "kept" / "warn"; Title; Detail } の配列）; Hint; Choices（@{ Text; Value; Danger; Careful } の配列。最後が主なボタン） }
    # ワークスペースには空のフォルダを選んでもらう。空でなければ警告し、中にワークスペースのフォルダを作るか、そのまま使うかを選ばせる。
    # 今のワークスペースの中身（インデックス・取り込み一覧・ログ）は、いつも新しいワークスペースへ移す（WorkspaceMover.ChangeWorkspace）。
    # 選んだフォルダに tebunko のファイル（インデックスなど。ほかの人が共有したワークスペースなど）があれば、それを使うか、消して最初からやるかを選ばせる。
    #   Value: "change"（選んだフォルダにする）/ "sub"（中に workspace を作ってそこにする）/ "asis"（空でないまま使う）/
    #          "use"（中のインデックスを使う。今のワークスペースの中身は移さない）/ "reset"（中のインデックスを消し、今のワークスペースの中身を移す）
    param (
        [string]$folder,       # 選んだフォルダ
        [string]$current,      # 今のワークスペース
        [int]$entryCount,      # 選んだフォルダの中のファイル・フォルダの数（数えた上限で止めてよい）
        [string[]]$sampleNames = @(),  # 中身の例（先頭の数件の名前）
        [bool]$countCapped = $false,   # entryCount が数えた上限（それ以上あるかもしれない）
        [string[]]$workspaceNames = @(), # 中にある tebunko のファイル・フォルダの名前（WorkspaceMover.ListEntries）。あれば、使うか消すかを選ばせる
        [bool]$canMakeSub = $true,     # 中に workspace を作れる（無いか、あっても空）
        [bool]$toDefault = $false      # ［既定に戻す］から（空のときだけ、題と文言が変わる）
    )

    $moveHint = "移動中は、検索とインデックスの更新はできません。"
    if (@($workspaceNames).Count -gt 0) {
        return @{
            Title   = "ワークスペースの変更"
            Heading = "「${folder}」には、すでにインデックスがあります。"
            Facts   = @()
            Hint    = "そのフォルダのインデックスを使うか、今のインデックスを移動するかを選んでください。移動すると、そのフォルダにあるインデックスは削除されます（元に戻せません）。"
            Choices = @(
                @{ Text = "今のインデックスを移動する"; Value = "reset"; Danger = $true; Careful = $true },
                @{ Text = "そのフォルダのインデックスを使う"; Value = "use"; Careful = $false })
        }
    }
    if ($entryCount -le 0) {
        if ($toDefault) {
            return @{
                Title   = "既定の場所に戻す"
                Heading = "インデックスとログを既定の場所「${folder}」へ移動します。"
                Facts   = @()
                Hint    = $moveHint
                Choices = @(@{ Text = "戻す"; Value = "change"; Careful = $false })
            }
        }
        return @{
            Title   = "ワークスペースの変更"
            Heading = "インデックスとログを「${folder}」へ移動します。"
            Facts   = @()
            Hint    = $moveHint
            Choices = @(@{ Text = "移動する"; Value = "change"; Careful = $false })
        }
    }

    $countText = if ($countCapped) { "{0:#,0} 個以上" -f $entryCount } else { "{0:#,0} 個" -f $entryCount }
    $sample = @($sampleNames | Select-Object -First ${workspaceSampleCount}) -join "、"
    if ($entryCount -gt @($sampleNames).Count -or $countCapped) {
        $sample += " など"
    }
    $facts = @(@{ Kind = "warn"; Title = "このフォルダは空ではありません（ファイル・フォルダが ${countText}）"; Detail = $sample })

    $facts += @{ Kind = "next"; Title = "今のインデックス・ログは、新しい場所へ移します"; Detail = "移す前の場所：${current}" }

    # 最後の選択肢が主なボタン（青）になる。うっかり押しやすい「そのまま使う」を先に置く
    $choices = @(@{ Text = "このフォルダのまま使う"; Value = "asis"; Careful = $true })
    $sub = Join-Path $folder ${workspaceSubFolderName}
    if ($canMakeSub) {
        $choices += @{ Text = "中に「${workspaceSubFolderName}」を作って使う"; Value = "sub"; Careful = $false }
        $facts += @{ Kind = "next"; Title = "「中に作って使う」を選ぶと、ワークスペースは次の場所になります"; Detail = $sub }
    }
    return @{
        Title   = "ワークスペースの変更"
        Heading = "選んだフォルダは空ではありません。ワークスペースには空のフォルダを選んでください。"
        Facts   = $facts
        Hint    = "空のフォルダを選び直すときは［キャンセル］を押してください。"
        Choices = $choices
    }
}

function getWorkspaceMoveChange {
    # 裏のスレッドの仕事の戻り値（output）から、WorkspaceMover.ChangeWorkspace の結果（@{ Ok; Stage; Message; Targets; Count }）を取り出す。無ければ $null
    param (
        $output
    )

    $found = $null
    foreach ($item in @($output)) {
        if ($item -is [hashtable] -and $item.ContainsKey("Ok")) {
            $found = $item
        }
    }
    return $found
}

function getWorkspaceMoveOutcome {
    # ワークスペースを移す裏の仕事が終わったときに、画面のスレッドで行うことを決める。画面に触らない。
    #   change: getWorkspaceMoveChange の結果（無い・例外のときは $null）
    #   errorText: 裏のスレッドの例外の文（無ければ空）
    #   closeRequested: 移している間に窓を閉じようとして、終わるのを待っていた（成功のときだけ、終わったら閉じる。失敗のときは閉じずに警告を出す）
    # 戻り値: @{ Ok（移せた）; Warning（失敗のとき、利用者に出す文。成功なら空）; Status（成功のとき switchWorkspace のあとに出すステータス。空なら出さない）; Close（終わったら閉じる） }
    # 成功のときだけ画面を切り替える（Ok）。失敗のときは設定も画面も変えない（WorkspaceMover は失敗したら設定を変えずに戻している）
    param (
        $change,
        [string]$errorText,
        [bool]$closeRequested,
        [string]$mode,
        [string]$folder,
        [string]$previous
    )

    # 失敗のときは閉じない（閉じるのを待っていても、失敗を利用者に伝えるため、画面を残して警告を出す）
    $failed = @{ Ok = $false; Warning = ""; Status = ""; Close = $false }
    # 移せた（設定は書き換え済み）なら、あとの例外の文があっても成功として扱う（設定と画面を食い違わせない）
    $moved = $null -ne $change -and $change.Ok
    if ($errorText -and !$moved) {
        $failed.Warning = "ワークスペースを「${folder}」へ移せませんでした（${errorText}）。今のワークスペースのまま使えます。"
        return $failed
    }
    if ($null -eq $change) {
        $failed.Warning = "ワークスペースを「${folder}」へ移せませんでした。今のワークスペースのまま使えます。"
        return $failed
    }
    if (!$change.Ok) {
        $failed.Warning = if ($change.Stage -eq "remove") {
            "「${folder}」のインデックスを削除できませんでした（$($change.Message)）。ファイルを開いているアプリを閉じてから、もう一度変えてください。"
        } else {
            [string]$change.Message
        }
        return $failed
    }
    $status = ""
    if ($mode -eq "use") {
        $status = "ワークスペースを「${folder}」に変え、そこにあるインデックスを使います（インデックス $($change.Targets) 件。前のワークスペースの中身は「${previous}」に残しています）"
    } elseif ($change.Count -gt 0) {
        $status = "ワークスペースを「${folder}」に変え、中身を移しました（移す前の場所：${previous}）"
    }
    return @{ Ok = $true; Warning = ""; Status = $status; Close = $closeRequested }
}

# 起動時の「前回残った Office の確認」に出す文言と、出すかどうかの判断（判断層）。
# 材料は getOfficeProcesses（shared/office/office_process.ps1）の結果。画面に触らないため、そのままテストできる
# （tests/tebunko/ui/leftover_view.Tests.ps1）。止める処理は stopOfficeProcesses だけが行う。
# 止めてよいのは、このツールが起動した記録があり（Owned）、起動した画面・インデックス作成がもう無く（Owner が Gone）、
# 窓を持たない（HasWindow でない）Office だけ。利用者が開いている Office は、記録が無いか窓があるため、対象にならない。

function selectLeftoverProcesses {
    # getOfficeProcesses の結果から、残り物（確認して止めてよいもの）だけを返す
    param (
        [object[]]$processes
    )

    $result = New-Object System.Collections.Generic.List[object]
    foreach ($process in @($processes)) {
        if ($process.Owned -and $process.Owner -eq "Gone" -and !$process.HasWindow) {
            $result.Add($process)
        }
    }
    return $result.ToArray()
}

function getLeftoverSummary {
    # 「Excel 2 件・Word 1 件」。Excel・Word・PowerPoint の順で、0 件のアプリは出さない
    param (
        [object[]]$targets
    )

    $parts = New-Object System.Collections.Generic.List[string]
    foreach ($name in ${officeProcessNames}.Keys) {
        $count = @($targets | Where-Object { $_.ProcessName -eq $name }).Count
        if ($count -gt 0) {
            $parts.Add("$(${officeProcessNames}[$name]) $count 件")
        }
    }
    return ($parts -join "・")
}

function getLeftoverPrompt {
    # 確認の内容を返す。残り物が無ければ $null。
    #   Targets: 残り物（getOfficeProcesses の要素）  Count: 件数  Summary: 「Excel 2 件・Word 1 件」
    #   Title・Heading・Facts（@{ Kind = "Kept"; Title; Detail } の 2 行）・Hint・Choices（@{ Text; Value }）・CancelText
    #   Details: 一覧の行 @{ AppName; Id; StartTime; TimeText }（StartTime は読めなければ $null。TimeText は「10/04 18:32」。読めなければ「不明」）
    param (
        [object[]]$processes
    )

    $targets = @(selectLeftoverProcesses $processes)
    if ($targets.Count -eq 0) {
        return $null
    }
    $summary = getLeftoverSummary $targets
    $details = New-Object System.Collections.Generic.List[object]
    foreach ($target in $targets) {
        $details.Add(@{ AppName = $target.AppName; Id = $target.Id; StartTime = $target.StartTime; TimeText = (getLeftoverTimeText $target.StartTime) })
    }
    return @{
        Targets    = $targets
        Count      = $targets.Count
        Summary    = $summary
        Title      = "Office の終了"
        Heading    = "前回の更新で起動した Office が $($targets.Count) 件、残ったまま動いています。終了しますか？"
        Facts      = @(
            @{ Kind = "Kept"; Title = "編集中のファイルは閉じません"; Detail = "終了するのは、tebunko がバックグラウンドで起動した ${summary}だけです" }
            @{ Kind = "Kept"; Title = "保存していない作業が失われることはありません"; Detail = "残っているのは、更新のために起動したものです" }
        )
        Hint       = "［今回は終了しない］を選んだときは、次に起動したときにもう一度お聞きします。"
        Choices    = @(@{ Text = "終了する"; Value = "stop" })
        CancelText = "今回は終了しない"
        Details    = $details.ToArray()
    }
}

function getLeftoverTimeText {
    # 一覧の「起動した時刻」。「10/04 18:32」。読めなければ「不明」
    param (
        $startTime
    )

    if ($null -eq $startTime) {
        return "不明"
    }
    try {
        return ([datetime]$startTime).ToString("MM/dd HH:mm")
    } catch {
        return "不明"
    }
}

function getLeftoverDetailToggleText {
    # 一覧の開け閉めのボタンの文字
    param (
        [bool]$open
    )

    return $(if ($open) { "詳細を隠す" } else { "詳細を表示" })
}

function getLeftoverTargets {
    # 確認を出してから止めるまでの間に状況が変わっていないかを照らし直す。
    # shownIds: 確認に出した PID。fresh: 読み直した getOfficeProcesses の結果。
    # 今も残り物であるもののうち、確認に出した PID だけを返す（確認の後に増えたものは、確認していないので止めない）
    param (
        [int[]]$shownIds,
        [object[]]$fresh
    )

    $result = New-Object System.Collections.Generic.List[object]
    foreach ($target in @(selectLeftoverProcesses $fresh)) {
        if (@($shownIds) -contains [int]$target.Id) {
            $result.Add($target)
        }
    }
    return $result.ToArray()
}

function getLeftoverResultText {
    # stopOfficeProcesses の結果（@{ Id; Stopped; Status; Reason }）から、ステータスバーに出す文を作る。
    # 何も止めておらず言うことも無ければ $null（ステータスは変えない）。もう無かったもの（Gone）は数にも理由にも入れない
    param (
        [object[]]$results
    )

    $stopped = 0
    $changed = New-Object System.Collections.Generic.List[string]
    $failed = New-Object System.Collections.Generic.List[string]
    foreach ($item in @($results)) {
        switch ($item.Status) {
            "Stopped" { $stopped++ }
            "Changed" { $changed.Add([string]$item.Id) }
            "Failed" { $failed.Add("PID $($item.Id) を終了できませんでした：$($item.Reason)") }
        }
    }
    $text = ""
    if ($stopped -gt 0) {
        $text += "Office を $stopped 件終了しました。"
    }
    if ($changed.Count -gt 0) {
        $text += "PID $($changed -join "・") は確認の後に別のプロセスに変わったため、終了しませんでした。"
    }
    if ($failed.Count -gt 0) {
        $text += ($failed -join "")
    }
    if ($text -eq "") {
        return $null
    }
    return $text
}

function getLeftoverPromptTiming {
    # 起動時の確認を、今出すか・見送るか・あとで出し直すかを決める。上から見て最初に当てはまったもの。
    #   残り物が 0 件 → Skip
    #   ウィンドウを閉じている途中 → Skip
    #   インデックス作成中（そのインデックス作成の Office を止めないため）→ Skip
    #   起動時のお知らせがまだ閉じていない → Defer（閉じたあとに、もう一度判断する）
    #   ほかのダイアログが開いている → Skip
    #   それ以外 → Show
    param (
        [int]$leftoverCount,
        [bool]$closing,
        [bool]$indexing,
        [bool]$noticesOpen,
        [int]$otherDialogCount
    )

    if ($leftoverCount -le 0 -or $closing -or $indexing) {
        return "Skip"
    }
    if ($noticesOpen) {
        return "Defer"
    }
    if ($otherDialogCount -ge 1) {
        return "Skip"
    }
    return "Show"
}

function getLeftoverFailureText {
    # 起動時の確認・［終了する］のあとの裏の仕事が失敗したとき、ステータスバーに出す文。段階は Check（起動時の確認）か Stop（終了）。
    # 詳しい原因は付けず、利用者が次にすることを示す（残った Office は、次の起動のときにもう一度確認できる）
    param (
        [string]$phase,
        [string]$errorText
    )

    $detail = $(if ([string]::IsNullOrWhiteSpace($errorText)) { "" } else { "（$(($errorText.Trim() -split "`r?`n")[0])）" })
    if ($phase -eq "Stop") {
        return "Office を終了できませんでした$detail。残った Office は、次に tebunko を起動したときにもう一度確認できます。"
    }
    return "前回残った Office を確認できませんでした$detail。"
}

# ---- 写真・画面のテスト用の偽の行 ----
# 写真と画面のテストは、本物の Office を残さずに確認の画面を出すため、場面（環境変数 TEBUNKO_GUI_LEFTOVER_FILE が指す JSON）から
# 偽の行を差し込む。環境変数が無い（ふだんの起動）ときは、必ず本物（getOfficeProcesses・stopOfficeProcesses）を使う。
# 偽の行のときは、終了の処理も偽（結果を作るだけで、プロセスには触れない）。tests/meta/leftover_seam.Tests.ps1 が、この決まりを確かめる。

function getLeftoverSourceMode {
    # 偽の行のファイルが指定されていれば "Fake"、なければ "Real"
    param (
        [string]$fakeFile
    )

    return $(if ([string]::IsNullOrEmpty($fakeFile)) { "Real" } else { "Fake" })
}

function convertLeftoverFakeRows {
    # 偽の行（@{ Id; ProcessName; StartTime; StopStatus }）を getOfficeProcesses の要素の形にする。残り物として扱う（記録あり・持ち主なし・窓なし）。
    # StopStatus は、終了の結果に使う（Stopped・Changed・Gone・Failed。省けば Stopped）
    param (
        [object[]]$rows
    )

    $result = New-Object System.Collections.Generic.List[object]
    foreach ($row in @($rows)) {
        $name = $(if ($row.ProcessName) { [string]$row.ProcessName } else { "EXCEL" })
        $start = $null
        if ($row.StartTime) {
            try { $start = [datetime]$row.StartTime } catch { $start = $null }
        }
        $result.Add([pscustomobject]@{
            Id          = [int]$row.Id
            ProcessName = $name
            AppName     = ${officeProcessNames}[$name]
            StartTime   = $start
            HasWindow   = $false
            Owned       = $true
            Owner       = "Gone"
            StopStatus  = $(if ($row.StopStatus) { [string]$row.StopStatus } else { "Stopped" })
        })
    }
    return $result.ToArray()
}

function getLeftoverFakeStopResults {
    # 偽の行の「終了」の結果。stopOfficeProcesses と同じ形（@{ Id; Stopped; Status; Reason }）。プロセスには触れない
    param (
        [object[]]$targets
    )

    $results = New-Object System.Collections.Generic.List[object]
    foreach ($target in @($targets)) {
        $status = $(if ($target.StopStatus) { [string]$target.StopStatus } else { "Stopped" })
        $reason = ""
        if ($status -eq "Changed") {
            $reason = "PID $($target.Id) は確認の後に別のプロセスに変わったため、終了しませんでした。"
        } elseif ($status -eq "Failed") {
            $reason = "アクセスが拒否されました"
        }
        $results.Add(@{ Id = [int]$target.Id; Stopped = ($status -eq "Stopped"); Status = $status; Reason = $reason })
    }
    return $results.ToArray()
}

