# ナビ（左の欄）の画面の並びと、画面を順に切り替える決まり（判断層）。
# 画面に触らないため、そのままテストできる（tests/tebunko/ui/shell/nav_view.Tests.ps1）。

function getScreenOrder {
    # 画面の名前を、ナビの上から順に並べて返す（Ctrl+Tab で切り替える順でもある）。名前はナビの項目の x:Name
    return @("SearchTab", "IndexTab", "SettingsTab")
}

function getScreenMargin {
    # 画面の中身（ContentHost）の外側の余白（左,上,右,下）。検索の画面は、白い面を窓いっぱいに敷いて帯の線を端まで引くため 0。
    # ほかの画面は、周りに余白を取る
    param (
        [string]$name
    )

    if ($name -eq "SearchTab") {
        return "0,0,0,0"
    }
    return "16,12,16,12"
}

function isScreenName {
    param (
        [string]$name
    )

    return (@(getScreenOrder) -contains $name)
}

function getNextScreen {
    # 今の画面から step 個先（負なら前）の画面の名前。端から先は反対の端に回る。
    # 今の画面が一覧に無いとき（まだ選んでいない）は、進むなら先頭、戻るなら末尾にする
    param (
        [string]$current,
        [int]$step
    )

    $order = @(getScreenOrder)
    $index = [Array]::IndexOf($order, $current)
    if ($index -lt 0) {
        return $(if ($step -ge 0) { $order[0] } else { $order[$order.Count - 1] })
    }
    $next = (($index + $step) % $order.Count + $order.Count) % $order.Count
    return $order[$next]
}

function getShortcutAction {
    # キー操作（PreviewKeyDown）から、窓全体の動きを決める。画面のスレッドの外でも確かめられるよう、
    # キーの名前（Key の ToString）と Ctrl・Shift の有無だけを受ける。返す Action は、
    #   FocusSearchWord（Ctrl+F）・FocusFilter（Ctrl+Shift+F）・SwitchScreen（Ctrl+Tab・Ctrl+Shift+Tab。Screen に切り替え先）・
    #   Refresh（F5）・CancelSearch（Escape）・None（ここでは扱わない）
    param (
        [string]$key,
        [bool]$ctrl,
        [bool]$shift,
        [string]$current
    )

    if ($key -eq "F" -and $ctrl) {
        return @{ Action = $(if ($shift) { "FocusFilter" } else { "FocusSearchWord" }); Screen = "SearchTab" }
    }
    if ($key -eq "Tab" -and $ctrl) {
        return @{ Action = "SwitchScreen"; Screen = (getNextScreen $current $(if ($shift) { -1 } else { 1 })) }
    }
    if ($key -eq "F5") {
        return @{ Action = "Refresh"; Screen = $current }
    }
    if ($key -eq "Escape") {
        return @{ Action = "CancelSearch"; Screen = $current }
    }
    return @{ Action = "None"; Screen = $current }
}

# ステータスバーの更新中の 1 行の文言（判断層）。画面に触らないため、そのままテストできる
# （tests/tebunko/ui/shell/status_bar_view.Tests.ps1）。

function getStatusBarView {
    # ステータスバーの左に出す 1 行を決める。更新中は更新中の行が、いつもの文（直前の操作の結果）に代わる（更新が終われば、いつもの文に戻る）。
    # 長くて切れたときの全文は、画面層が切れているときだけツールチップで見せる（addTrimmedToolTip）。
    #   Source: Indexing（更新中の行）/ Status（直前の操作の結果）/ Empty（出すものが無い）
    param (
        [bool]$indexing,
        [string]$indexingLine,
        [string]$statusText
    )

    if ($indexing) {
        return @{ Source = "Indexing"; Text = $indexingLine }
    }
    if ($statusText) {
        return @{ Source = "Status"; Text = $statusText }
    }
    return @{ Source = "Empty"; Text = "" }
}

function getIndexingStatusLine {
    # 更新中にステータスバーの左に出す 1 行。件数・失敗は更新全体のもの（インデックスごとではない）
    #   例: 更新中: 営業部2025　205 / 455 件（失敗 1 件）・残り約 3 分
    param (
        [string]$name,      # 更新しているインデックスの名前（取れないときは空）
        [int]$processed,
        [int]$total,
        [int]$failed,
        [string]$etaText    # 残り時間の文言（「残り約 3 分」。まだ分からなければ空）
    )

    $head = if ($name) { "更新中: $name" } else { "更新中" }
    if ($total -le 0 -or $processed -le 0) {
        # 1 件も終わっていない間は、件数を出さない
        return "$head　準備しています"
    }
    $text = "$head　$($processed.ToString('N0')) / $($total.ToString('N0')) 件"
    if ($failed -gt 0) {
        $text += "（失敗 $failed 件）"
    }
    if ($etaText) {
        $text += "・$etaText"
    }
    return $text
}

# 画面の上に出す知らせの帯（検索の結果を保存できなかった・インデックスの削除などに失敗した・ワークスペースが使えない）の判断層。
# 画面に触らないため、そのままテストできる（tests/tebunko/ui/shell/notice_banner_view.Tests.ps1）。

function getNoticeBannerView {
    # 帯に出す文言と、色の区分・閉じられるか・自動で消えるか・ボタンを決める。
    #   kind: ResultSaveFailed（検索の結果を保存できなかった。検索の画面の上）/
    #         IndexOpFailed（インデックスの削除、まとめてのエクスポート・削除で失敗があった。インデックス管理の画面の上）/
    #         WorkspaceBlock（ワークスペースが使えない。窓の上）
    #   message: 出す文（複数行なら 1 行につなぎ、全文はツールヒントに出す）。空なら帯を出さない
    # 戻り値: @{ Show; Text; ToolTip; Level（warn / ng。getIndexingBannerBehavior と同じ区分）; Closable; ActionText（ボタンの文言。無ければ空）}
    # どの帯も、閉じるまで（ワークスペースが使えない帯は、使えるようになるまで）残る。自動では消さない
    param (
        [string]$kind,
        [string]$message = ""
    )

    $lines = @(($message -split "`r?`n") | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne "" })
    $show = ($lines.Count -gt 0) -and ($kind -in @("ResultSaveFailed", "IndexOpFailed", "WorkspaceBlock"))
    if (!$show) {
        return @{ Show = $false; Text = ""; ToolTip = ""; Level = "warn"; Closable = $true; ActionText = "" }
    }
    $view = @{
        Show = $true; Text = ($lines -join "  "); ToolTip = ($lines -join "`n")
        Level = "warn"; Closable = $true; ActionText = ""
    }
    if ($kind -eq "WorkspaceBlock") {
        $view.Level = "ng"
        $view.Closable = $false
        $view.ActionText = "設定を開く"
    }
    return $view
}

