$script:fastSearchTimer = newTimer (5 * 60 * 1000) { safe { refreshFastSearchStatus } }

function isIndexing {
    return ($null -ne $script:indexingSession) -and $script:indexingSession.IsRunning()
}

function isIndexingOrPreparing {
    # インデックス作成が動いている、または始める前にワークスペースを確かめている間（startIndexing）。
    # どちらの間も、インデックスの操作・ワークスペースの変更・次のインデックス作成の開始はしない
    return (isIndexing) -or [bool]$script:indexingPreparing
}

function getCurrentIndexJobBlocker {
    # いま動いている処理の名前（getIndexJobBlocker の結果。無ければ空文字列）。画面の状態から集める。
    #   extraIndexing: ほかに「インデックス作成中」とみなすもの（画面を使わずに起動したインデクサなど）
    param (
        [bool]$extraIndexing = $false
    )

    return (getIndexJobBlocker ((isIndexingOrPreparing) -or $extraIndexing) ([bool]$script:indexBusy) ([bool]$script:archiveBusy) ([bool]$script:targetsNaming) ([bool]$script:workspaceMoving))
}

function shouldRefreshFastSearchStatus {
    # 高速検索の列は、前の確かめから 60 秒たっていなければ飛ばす（ウィンドウを前に出すたびに問い合わせない）
    return ($null -eq $script:fastSearchCheckedAt) -or ((Get-Date) - $script:fastSearchCheckedAt).TotalSeconds -ge 60
}

$script:folderCheckRunning = $false
$script:folderCheckAgain = $false

function updateFolderItemStatus {
    # フォルダの有無を調べ直す（別スレッド。refreshFolderStatus）。調べ終えるまでは前の表示のまま（初回は「確認中」）
    param (
        $item
    )

    if (!$item.StatusChecked) {
        $item.SetStatus("… フォルダを確認しています", ${grayBrush})
    }
    updateIndexDetailPanel
    refreshFolderStatus
}

function refreshFolderStatus {
    # 一覧のすべてのフォルダの有無を別スレッドで調べ、表示と［すべて更新］の可否に反映する。
    # 届かないネットワークのフォルダ（VPN の切断・サーバーの停止）では Test-Path が十数秒戻らないため、
    # 画面のスレッドで調べると起動時・画面を前に出すたびに「応答なし」になる（実測 約 17 秒）。
    # 調べている間に呼ばれたら、終わってからもう一度だけ調べる
    if ($script:folderCheckRunning) {
        $script:folderCheckAgain = $true
        return
    }
    $paths = @($script:targetItems | ForEach-Object { [string]$_.Path } | Where-Object { $_ } | Select-Object -Unique)
    if ($paths.Count -eq 0) {
        return
    }
    $script:folderCheckRunning = $true
    $script:folderCheckAgain = $false
    # 届かないネットワークのフォルダが 1 つでもあれば、専用の列（network）を使う。
    # プレビュー等の列（既定。2 スレッド）は、届かない共有の Test-Path で塞がれても待たされないようにする
    $queue = getWorkspaceJobQueue $paths
    startJob {
        param ($paths)
        $result = @{}
        foreach ($path in $paths) {
            # 届かないネットワークのフォルダでは Test-Path が例外（ネットワーク パスが見つかりません）になるため、無いものとする
            $found = $false
            try {
                $found = [bool](Test-Path -LiteralPath $path -PathType Container -ErrorAction Stop)
            } catch {
            }
            $result[$path] = $found
        }
        $result
    } @(, [string[]]$paths) {
        param ($output, $errorText)
        $script:folderCheckRunning = $false
        if ($output -and $output.Count -gt 0) {
            applyFolderStatus $output[0]
        }
        if ($script:folderCheckAgain) {
            refreshFolderStatus
        }
    } $queue
}

function applyFolderStatus {
    # refreshFolderStatus の結果（パス → 有無）を一覧に反映する（調べている間にパスが変わった行はそのまま）
    param (
        $exists
    )

    foreach ($item in $script:targetItems) {
        if (!$exists.ContainsKey([string]$item.Path)) {
            continue
        }
        $item.StatusChecked = $true
        $item.FolderExists = [bool]$exists[[string]$item.Path]
        if ($item.FolderExists) {
            $item.SetStatus("フォルダがあります", ${okBrush})
        } else {
            $item.SetStatus("フォルダが見つかりません", ${ngBrush})
        }
    }
    updateIndexingButton
    updateIndexDetailPanel
}

function refreshFastSearchStatus {
    # 一覧の「高速検索」列を、別スレッドで Windows Search に 1 回問い合わせて確かめ直す（getWindowsSearchState・
    # Reason が Ok・NotYet のときだけ getSystemIndexProgress を同じ接続で）。確かめている間に呼ばれたら、
    # 終わってからもう一度だけ確かめる。確かめている間にワークスペースが変わったら結果を捨てる。
    # インデックス作成中（isIndexing）は、状態ファイルと txt が書き換わっている途中のため確かめない
    # （インデックス作成が終わったとき（finishIndexing）に、別途呼ぶ）
    if (isIndexing) {
        return
    }
    if ($script:fastSearchChecking) {
        $script:fastSearchAgain = $true
        return
    }
    $script:fastSearchChecking = $true
    $script:fastSearchAgain = $false
    $script:fastSearchJobDir = $workspace.Dir
    $script:fastSearchJobGeneration = $script:fastSearchGeneration
    # 届かないネットワークのワークスペースでは、フォルダの有無と同じ専用の列（network）を使う
    $queue = getWorkspaceJobQueue $workspace.Dir
    startJob {
        param ($systemRoot, $indexRoot, $statePath)
        $connection = openWindowsSearch
        try {
            if ($null -eq $connection) {
                return @{ Reason = "NoConnection"; Progress = $null }
            }
            $reason = getWindowsSearchState $systemRoot "" $connection
            $progress = $null
            if ($reason -eq "Ok" -or $reason -eq "NotYet") {
                $progress = getSystemIndexProgress $null $indexRoot $systemRoot $statePath $connection
            }
            @{ Reason = $reason; Progress = $progress }
        } finally {
            if ($connection) {
                $connection.Dispose()
            }
        }
    } @($workspace.SystemIndexDir, $workspace.IndexDir, $workspace.SystemIndexStateFile) {
        param ($output, $errorText)
        $script:fastSearchChecking = $false
        if ($script:fastSearchJobDir -ne $workspace.Dir -or $script:fastSearchJobGeneration -ne $script:fastSearchGeneration) {
            # 確かめている間にワークスペースを変えた、またはインデックス作成が終わって世代が変わった。
            # 古い結果は出さず、確かめ直す
            $script:fastSearchAgain = $true
        } elseif ($output -and $output.Count -gt 0) {
            applyFastSearchStatus $output[0]
        } elseif ($errorText) {
            # 確かめの途中で例外が起きたときも、接続できなかったときと同じ扱いにする（バッジが固まったままにしない）
            applyFastSearchStatus @{ Reason = "NoConnection"; Progress = $null }
        }
        if ($script:fastSearchAgain) {
            refreshFastSearchStatus
        }
    } $queue
}

function applyFastSearchStatus {
    # refreshFastSearchStatus の結果（@{ Reason; Progress }）を覚えて、一覧の「高速検索」列に置き直す
    param (
        $result
    )

    $script:fastSearchReason = $result.Reason
    $script:fastSearchProgress = $result.Progress
    $script:fastSearchCheckedAt = Get-Date
    $script:fastSearchResultDir = $workspace.Dir
    updateFastSearchRows
}

function updateFastSearchRows {
    # 一覧の各行の「高速検索」列を getFastSearchRowView で置き直す（確かめの結果が届いたときと、
    # applyIndexStats で本文の集計が届いたときの両方から呼ぶ。ここでは I/O をせず判断層を呼ぶだけ）。
    # $hasContent は、そのときの getIndexStats の値（Done が 1 以上か）から渡す。
    # isIndexing も渡し、作成中に hasContent が真へ変わっても（高速検索の確かめは作成中は走らない
    # ため）前の確かめの結果のまま「不可」にしない（getFastSearchRowView の indexing 引数）。
    # 覚えている結果が今のワークスペースのものでなければ（切り替えた直後）、古い可否を出さないよう捨てて「確認中…」に戻す
    if ($script:fastSearchResultDir -ne $workspace.Dir) {
        $script:fastSearchReason = $null
        $script:fastSearchProgress = $null
        $script:fastSearchCheckedAt = $null
    }
    $stats = if ($script:indexingState) { $script:indexingState.IndexStats } else { $null }
    $waiting = $false
    foreach ($item in $script:targetItems) {
        $hasContent = $false
        if ($item.Name -and $null -ne $stats -and $stats.ContainsKey($item.Name)) {
            $hasContent = ($stats[$item.Name].Done -ge 1)
        }
        $row = getFastSearchRowView $script:fastSearchReason $script:fastSearchProgress $item.Name $hasContent $script:fastSearchCheckedAt (isIndexing)
        $item.SetFast($row.Text, $row.ToolTip, $row.Level, [string[]]@($row.Steps))
        if ($row.Level -eq "Wait") {
            $waiting = $true
        }
    }
    updateIndexDetailPanel
    if ($waiting) {
        if (!$script:fastSearchTimer.IsEnabled) {
            $script:fastSearchTimer.Start()
        }
    } elseif ($script:fastSearchTimer.IsEnabled) {
        $script:fastSearchTimer.Stop()
    }
}

function newFolderItem {
    param (
        [string]$path,
        [bool]$enabled,
        [string]$name = ""
    )

    $item = New-Object FolderItem
    $item.Name = $name
    $item.Path = $path
    $item.Enabled = $enabled
    $item.FileCountText = "－"
    $item.LastIngestedText = ""
    # フォルダの有無は一覧に加えた後にまとめて調べる（refreshFolderStatus）
    $item.SetStatus("… フォルダを確認しています", ${grayBrush})
    # 行のチェックの保存は、一覧のチェックボックスの Checked・Unchecked（IndexGrid.AddHandler）で行う。
    # PS class のプレーンなプロパティは TwoWay セットで PropertyChanged を出さないため、購読では拾えない。
    return $item
}

function loadTargets {
    # 設定のインデックス一覧を画面の一覧に読み込む。
    # 名前の決まっていないインデックス（設定ファイルを直接書き換えた場合など）には、ここで名前を割り当てて確定する。
    # 一覧・編集・削除はインデックス名で扱うため、画面に出す時点で名前があるようにする（インデクサと同じ assignIndexNames を使う）。
    # 名前を決めるには取り込み一覧（ワークスペースの中）を読む。ワークスペースがネットワークの場所なら裏の列で読み、
    # 終わるまで一覧は空のまま（届かない場所で画面のスレッドが止まらないように）
    $requestBox = $script:targetsLoadRequest
    $requestBox.Value++
    $script:targetsNaming = $false
    # 読み直しても、チェック（一時の選択）は名前で引き継ぐ
    $checkedNames = @(getIndexCheckedItems @($script:targetItems) | ForEach-Object { $_.Name })
    $folders = @(getTargetFolders)
    if (@($folders | Where-Object { $_ -and !$_.Name }).Count -gt 0) {
        if ((getWorkspaceJobQueue $workspace.Dir) -eq "network") {
            $script:targetItems.Clear()
            # 名前が決まって一覧を読み込み直すまで、ほかの操作を止める（空の一覧に保存して、設定のほかのインデックスを消さないため）
            $script:targetsNaming = $true
            try {
                updateIndexListView
                updateIndexingButton
                setStatus (getIndexNamingStatus)
                $requestId = $requestBox.Value
                $finish = ${function:finishTargetsNaming}   # 終わったときの処理は、関数を変数に取って呼ぶ（クロージャからは関数の名前を引けないため）
                startJob {
                    param ($folders, $workspaceDir)
                    # インスタンスは裏のスレッドへ渡せないため、場所から作り直す
                    [void]((newIndexCatalog $workspaceDir).AssignAndSaveNames($folders))
                } @(,$folders + @($workspace.Dir)) {
                    param ($output, $errorText)
                    if ($requestId -ne $requestBox.Value) {
                        # 待っている間にもう一度読み込んだ・ワークスペースを切り替えた。この結果は捨てる
                        return
                    }
                    & $finish $errorText $checkedNames
                }.GetNewClosure() (getWorkspaceJobQueue $workspace.Dir)
            } catch {
                # 裏の仕事を出せなかったときは、印を戻す（残ると、ほかの操作が止まったままになる）
                $script:targetsNaming = $false
                throw
            }
            return
        }
        [void]((newIndexCatalog $workspace.Dir).AssignAndSaveNames($folders))
        $folders = @(getTargetFolders)
    }
    fillTargetItems $folders $checkedNames
}

function finishTargetsNaming {
    # ネットワークのワークスペースで、裏の名前の割り当てが終わったときの処理。保存し直された一覧を読み込む（失敗したら理由を出し、設定のまま）
    param (
        [string]$errorText,
        [string[]]$checkedNames
    )

    $script:targetsNaming = $false
    if ($errorText) {
        setStatus (getIndexNamingFailedStatus $errorText)
    }
    fillTargetItems @(getTargetFolders) $checkedNames
    updateIndexingButton
}

function fillTargetItems {
    # 画面の一覧を folders（@{ Name; Path; Enabled }）の内容に置き換える。checkedNames の名前の行はチェックを付ける
    param (
        [object[]]$folders,
        [string[]]$checkedNames
    )

    $script:loadingTargets = $true
    try {
        $script:targetItems.Clear()
        foreach ($folder in $folders) {
            $newItem = newFolderItem $folder.Path $folder.Enabled $folder.Name
            $newItem.Checked = ($folder.Name -and $checkedNames -contains $folder.Name)
            $script:targetItems.Add($newItem)
        }
        $script:savedTargets = getTargetsKey @(getTargetFolders)
    } finally {
        $script:loadingTargets = $false
    }
    updateIndexListView
    refreshFolderStatus
    refreshFastSearchStatus
}

function saveTargets {
    # 一覧を設定に書く。保存した旨のステータスは出す。-Quiet のときは出さない（更新を始めるときの保存は、更新を始めるか確認で決まるため、文を出さない）
    param ([switch]$Quiet)

    (newIndexCatalog $workspace.Dir).SaveTargets(@($script:targetItems | ForEach-Object { [pscustomobject]@{ Name = $_.Name; Path = $_.Path; Enabled = $_.Enabled } }))
    $script:savedTargets = getTargetsKey @(getTargetFolders)
    if (!$Quiet) {
        setStatus "インデックス一覧を保存しました（$(Get-Date -Format 'H:mm')）"
    }
}

function updateIndexSourceFile {
    # インデックスのフォルダの source_folder.txt を今の一覧に合わせて書き直す。
    # 次のインデックス作成を待たずに、検索結果から元のファイルを開けるようにする（インデックスが無いフォルダには書かない）。
    # 書くのは別スレッドで行う（ワークスペースが届かない共有フォルダにあっても、画面のスレッドが止まらないように）。
    # 書けなかったときはステータスに知らせる
    $folders = @($script:targetItems | Where-Object { $_.Name } | ForEach-Object { [pscustomobject]@{ Name = $_.Name; Path = $_.Path } })
    $dir = [string]$workspace.IndexDir
    startJob {
        param ($folders, $workspaceDir)
        (newIndexCatalog $workspaceDir).WriteSourceFile($folders)
    } @(,$folders + @([string]$workspace.Dir)) {
        param ($output, $errorText)
        if ($errorText) {
            setStatus (getSourceFolderFileFailedStatus $errorText)
        }
    } (getWorkspaceJobQueue $dir)
}

function refreshIndexViews {
    # インデックスを追加・編集・削除した後、検索タブ（検索対象のツリー・件数）も読み直す。
    # 一覧の「高速検索」列も確かめ直す（編集・削除で中身が変わっているため）
    $script:sourceFolderMaps = @{}
    $script:indexSummary = $null
    loadIndexTree
    refreshIndexSummary
    refreshIndexingState
    refreshFastSearchStatus
    updateIndexDetailPanel
}

function refreshIndexViewsKeepingStatus {
    # 失敗の知らせ（$notice）を出したまま、画面を読み直す。ネットワークのワークスペースでは検索対象のツリーが裏で読み直され、
    # 届かないときはその結果がステータスを「接続できません」で上書きするため、その 1 回はステータスを書かせない
    # （接続できない旨は検索対象の欄に出る）。ローカルの読み直しが同じ呼び出しの中で終わる場合のため、読み直したあとにも書く
    param (
        [string]$notice
    )

    $script:indexTreeKeepStatus = $true
    refreshIndexViews
    setStatus $notice
}

function applyIndexStats {
    # 取り込み一覧の集計（getIndexStats）を一覧の各行のファイル数・最終更新・「ステータス」列に反映し、
    # 「高速検索」列も（getIndexStats の Done を使って）置き直す。
    #   indexing: インデックス作成中か（getIndexRowView にそのまま渡す）
    param (
        $stats,
        [bool]$indexing = $false
    )

    foreach ($item in $script:targetItems) {
        $stat = $null
        if ($item.Name -and $null -ne $stats -and $stats.ContainsKey($item.Name)) {
            $stat = $stats[$item.Name]
        }
        if ($null -eq $stat) {
            $item.SetStats("－", "まだ更新していません", "")
        } else {
            $ingested = [datetime]::MinValue
            $lastText = if ($stat.LastIngested -and [datetime]::TryParseExact($stat.LastIngested, "yyyy/MM/dd HH:mm:ss", [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::None, [ref]$ingested)) {
                formatTime $ingested
            } else {
                ""
            }
            $item.SetStats(("{0:#,0}" -f $stat.Total), ("更新済み {0:#,0} 件 ・ 未更新 {1:#,0} 件 ・ 失敗 {2:#,0} 件" -f $stat.Done, $stat.Pending, $stat.Failed), $lastText)
        }
        $row = getIndexRowView $stat $indexing $item.Enabled (getIndexingRatio) (testIndexInRound $item) (testIndexExporting $item)
        $item.SetIndexState($row.Text, $row.ToolTip, $row.Level, $row.Sub, [double]$row.Percent)
        setIndexRowActions $item
    }
    $script:indexFileTotal = 0
    if ($null -ne $stats) {
        foreach ($item in $script:targetItems) {
            if ($item.Name -and $stats.ContainsKey($item.Name)) {
                $script:indexFileTotal += [int]$stats[$item.Name].Total
            }
        }
    }
    updateIndexFooter
    updateFastSearchRows
}

$script:indexFileTotal = 0

function testIndexInRound {
    # 今の回で更新する行か（選んだものだけの回では、選んだ名前の行だけ）
    param ($item)

    return (@($script:indexingOnlyNames).Count -eq 0 -or @($script:indexingOnlyNames) -contains $item.Name)
}

$script:exportingNames = @()  # エクスポートで書き出している最中のインデックスの名前（行のバッジを「エクスポート中」にする）

function testIndexExporting {
    # 行がエクスポートで書き出している最中か
    param ($item)

    return (@($script:exportingNames) -contains [string]$item.Name)
}

function setExportingRows {
    # エクスポートで書き出している最中の名前を置き（空なら終わり）、一覧の行のバッジを置き直す
    param ([string[]]$names)

    $script:exportingNames = @($names | Where-Object { $_ })
    if ($null -ne $script:indexingState) {
        applyIndexStats $script:indexingState.IndexStats (isIndexing)
    }
}

function setIndexRowActions {
    # 行の右端のボタン（［更新］［中止］・何も出さない）を、行の状態（IndexLevel）と動いている処理に合わせる。判断は getIndexRowActions
    param ($item)

    $blocker = getCurrentIndexJobBlocker
    $actions = getIndexRowActions $item.IndexLevel $blocker (testIndexExporting $item)
    $item.SetRowActions($actions.Action, $actions.UpdateEnabled)
}

function updateSelectedIndexes {
    # 選んだインデックス（名前の配列）だけを更新する。行の［更新］と［アクション ▼］の［更新］の共通の入口。
    # 選んだ名前の行を、設定の enabled を true にして取り込み、その回だけの更新を始める（startIndexing）。
    # 動いている処理があるときは始めない（ボタンも使えなくしてある）
    param (
        [string[]]$names
    )

    $names = @($names | Where-Object { $_ })
    if ($names.Count -eq 0 -or (getCurrentIndexJobBlocker) -ne "") {
        return
    }
    startIndexing $names
}

$script:indexSourceRequest = [ref]0  # ［元のフォルダを開く］の確かめの依頼の番号（openFailedFileFolder と同じ理由で [ref] のまま閉じ込める）

function applyIndexSourceFolderState {
    # openIndexSourceFolder の続き（getPathState の結果を画面に反映する）。フォルダが見つかれば、エクスプローラーで開く
    param (
        $state,
        [string]$path
    )

    $kind = getIndexSourceFolderKind $state
    if ($kind -eq "Open") {
        Start-Process -FilePath "explorer.exe" -ArgumentList "`"${path}`""
        return
    }
    setStatus (getIndexSourceFolderStatus $kind $path $state.Message)
}

function openIndexSourceFolder {
    # 行の右クリックの［元のフォルダを開く］。押した行の元のフォルダをエクスプローラーで開く。
    # フォルダが無い・つながらないときは、押したときにステータスバーで知らせる（検索結果の［フォルダを開く］と同じ。無効にはしない）。
    # ネットワークにあれば裏のスレッドで確かめ、画面のスレッドは待たない
    $item = getIndexTargetItem
    if ($null -eq $item) {
        return
    }
    $path = [string]$item.Path
    if (!$path) {
        setStatus (getIndexSourceFolderStatus "Empty" "")
        return
    }
    $requestBox = $script:indexSourceRequest
    $requestBox.Value++
    $requestId = $requestBox.Value
    $applyState = ${function:applyIndexSourceFolderState}
    $apply = {
        param ($state)
        if ($requestId -ne $requestBox.Value) {
            # 待っている間に別の行を開いた。前の依頼は捨てる
            return
        }
        & $applyState $state $path
    }.GetNewClosure()

    if (!(testNetworkPath $path)) {
        & $apply (getPathState $path)
        return
    }
    setStatus (getIndexSourceFolderStatus "Checking" $path)
    $otherState = ${pathStateOther}
    startJob {
        param ($path)
        getPathState $path
    } @($path) {
        param ($output, $errorText)
        if ($errorText) {
            & $apply @{ State = $otherState; IsDirectory = $false; Message = $errorText }
        } else {
            & $apply $output[0]
        }
    }.GetNewClosure() (getWorkspaceJobQueue $path)
}

function updateIndexSelectionView {
    # 見出しの全選択（一部だけなら横棒）と、見出しの横の「N / M 件を選択中」。判断は getIndexSelectionView
    $view = getIndexSelectionView $script:targetItems.Count @(getIndexCheckedItems @($script:targetItems)).Count
    $ui.SelectionCountText.Text = $view.CountText
    $ui.SelectionCountText.Visibility = if ($view.CountText) { "Visible" } else { "Collapsed" }
    $ui.SelectAllCheckBox.IsChecked = $view.AllChecked
    $ui.SelectAllCheckBox.IsEnabled = ($script:targetItems.Count -gt 0)
}

function updateIndexRowsProgress {
    # 更新中の行のバッジ（「更新中」と、右の補足「45%」）と棒を、進み具合に合わせて置き直す（進み具合の更新のたびに呼ぶ）
    $ratio = getIndexingRatio
    foreach ($item in $script:targetItems) {
        if ($item.IndexLevel -eq "Run") {
            $row = getIndexRowView $null $true $item.Enabled $ratio (testIndexInRound $item)
            $item.SetIndexState($row.Text, $row.ToolTip, $row.Level, $row.Sub, [double]$row.Percent)
            setIndexRowActions $item
        }
    }
    updateIndexDetailPanel
}

function updateIndexFooter {
    # 一覧の下の帯。文言は判断層（getIndexFooterView）
    $view = getIndexFooterView $script:targetItems.Count $script:indexFileTotal
    $ui.IndexFooterFolders.Text = $view.Folders
    $ui.IndexFooterFiles.Text = $view.Files
}

function updateIndexListView {
    $empty = ($script:targetItems.Count -eq 0)
    $ui.IndexGridPlaceholder.Visibility = if ($empty) { "Visible" } else { "Collapsed" }
    # 1 件も無いときは、詳細と境目を出さず、案内を画面の中央に出す
    $ui.IndexDetailHost.Visibility = if ($empty) { "Collapsed" } else { "Visible" }
    $ui.IndexSplitter.Visibility = if ($empty) { "Collapsed" } else { "Visible" }
    # 詳細の行の高さは、空かどうかが変わったときだけ動かす（選択を変えるたびに入れ直すと、境目で変えた高さが戻る）。
    # 戻す高さの初めの値は index.xaml の RowDefinition（ここに数を持たない）
    $plan = getIndexDetailRowPlan $script:indexListEmpty $empty
    if ($plan -eq "Hide") {
        $script:indexDetailRowRestore = @{ Height = $ui.IndexDetailRow.Height; MinHeight = $ui.IndexDetailRow.MinHeight }
        $ui.IndexDetailRow.MinHeight = 0
        $ui.IndexDetailRow.Height = [System.Windows.GridLength]::new(0)
    }
    elseif ($plan -eq "Show") {
        if ($null -ne $script:indexDetailRowRestore) {
            $ui.IndexDetailRow.MinHeight = $script:indexDetailRowRestore.MinHeight
            $ui.IndexDetailRow.Height = $script:indexDetailRowRestore.Height
        }
    }
    $script:indexListEmpty = $empty
    updateIndexFooter
    updateIndexSelectionView
    updateIndexingButton
    updateIndexDetailPanel
}

function testIndexOperable {
    # インデックス作成・削除・エクスポート・インポートが動いている間はインデックスの追加・編集・削除・エクスポート・インポートをしない
    # （インデックスのフォルダ・取り込み一覧を使っているため）
    param (
        [string]$operation
    )

    $blocker = getCurrentIndexJobBlocker
    if ($blocker -ne "") {
        showMessage (getIndexJobBlockedMessage $blocker $operation) "OK" "Warning" | Out-Null
        return $false
    }
    return $true
}

# インデックス管理の画面の、インデックスの追加・名前と場所の変更・削除。
# 名前と場所は、詳細欄の「基本設定」の欄で直接直す（commitIndexDetailEdit）。

function addIndexItem {
    # インデックスを一覧に加えて保存する
    param (
        [string]$path,
        [string]$name
    )

    $item = newFolderItem $path $true $name
    $script:targetItems.Add($item)
    refreshFolderStatus
    $ui.IndexGrid.SelectedItem = $item
    $ui.IndexGrid.ScrollIntoView($item)
    saveTargets
    updateIndexSourceFile
    updateIndexListView
    refreshIndexingState
    refreshFastSearchStatus
    # フォルダの有無は refreshFolderStatus（別スレッド）が調べるので、ここでは Test-Path を呼ばない
    # （届かないネットワークのフォルダで画面のスレッドが止まらないようにする）。有無は一覧の列で分かる
    setStatus (getIndexAddedStatus $name)
}

function newIndex {
    # ［＋ フォルダを追加］。フォルダを選び、フォルダ名からインデックス名を決めて一覧に加える（インデックス作成はしない）。
    # 名前は、加えたあとに詳細欄で直せる
    if (!(testIndexOperable "追加")) {
        return
    }
    $path = selectFolder "インデックスにする、Office ファイルのあるフォルダを選んでください" "" $window $false
    if (!$path) {
        return
    }
    $path = normalizeFolderPath $path
    $name = newIndexName $path (getUsedIndexNames $script:targetItems)
    $message = testIndexEditInput $path $name $script:targetItems
    if ($message -ne "") {
        showMessage $message "OK" "Warning" | Out-Null
        return
    }
    addIndexItem $path $name
}

function addIndexForFolder {
    # 一覧へのドラッグ＆ドロップでインデックスを追加する（名前はフォルダ名から自動で決める）
    param (
        [string]$path
    )

    if (!(testIndexOperable "追加")) {
        return
    }
    $path = normalizeFolderPath $path
    if ($path -eq "") {
        return
    }
    foreach ($item in $script:targetItems) {
        # 書き方が違うだけで同じフォルダ（ネットワークドライブと UNC パスなど）も、すでにあるとみなす
        if (testSameFolder $item.Path $path) {
            $ui.IndexGrid.SelectedItem = $item
            setStatus "「$($item.Path)」のインデックス [$($item.Name)] は既にあります"
            return
        }
    }
    addIndexItem $path (newIndexName $path (getUsedIndexNames $script:targetItems))
}

function applyIndexEdit {
    # 編集の結果（@{ Path; Name }）を行に反映して保存する。詳細欄の名前・フォルダパスの確定（commitIndexDetailEdit）が使う。
    # 変わったところが無ければ何もしない。
    # 名前を変えるときは、インデックスのフォルダ（work\index\<名前>）と取り込み一覧の記録の改名を別スレッドで行い、
    # 終わってから行に反映する（ワークスペースが共有フォルダにあると改名に時間がかかる・届かないことがあるため）
    param (
        $item,
        $result
    )

    # 大文字・小文字だけの変更も改名する（-ne は大文字・小文字を区別しないため -cne で比べる）
    $renamed = $result.Name -cne $item.Name
    if (!$renamed -and $result.Path -eq $item.Path) {
        return
    }
    if (!$renamed) {
        completeIndexEdit $item $result
        return
    }

    # 改名と同じ仕事の中で、元のフォルダの記録（source_folder.txt）も新しい名前・場所で書き直す
    $folders = @($script:targetItems | Where-Object { $_.Name } | ForEach-Object {
        if ($_ -eq $item) {
            [pscustomobject]@{ Name = $result.Name; Path = $result.Path }
        } else {
            [pscustomobject]@{ Name = $_.Name; Path = $_.Path }
        }
    })
    $complete = ${function:completeIndexEdit}   # 終わったときの処理は、関数を変数に取って呼ぶ（クロージャからは関数の名前を引けないため）
    startIndexStoreJob "rename" $item.Name $result.Name $folders {
        & $complete $item $result
    }.GetNewClosure()
}

function completeIndexEdit {
    # 編集の結果を行に反映して保存する（名前の変更は、インデックスのフォルダの改名が終わってから呼ぶ）
    param (
        $item,
        $result
    )

    $changes = New-Object System.Collections.Generic.List[string]
    $renamed = $result.Name -cne $item.Name
    if ($renamed) {
        $changes.Add("名前 [$($item.Name)] → [$($result.Name)]")
        $item.SetName($result.Name)
    }
    if ($result.Path -ne $item.Path) {
        $changes.Add("場所 $($item.Path) → $($result.Path)")
        $item.SetPath($result.Path)
        $item.StatusChecked = $false
        updateFolderItemStatus $item
    }

    saveTargets
    if (!$renamed) {
        # 名前を変えたときは、改名の仕事の中で書き直し済み
        updateIndexSourceFile
    }
    refreshIndexViews
    setStatus ("インデックスを変更しました（" + ($changes -join " / ") + "）")
}

function setIndexDetailEditError {
    # 詳細欄の名前・フォルダパスの欄の下に、直してほしい内容を出す（空なら隠す）
    param (
        [string]$message
    )

    $ui.IndexDetailEditError.Text = $message
    $ui.IndexDetailEditError.Visibility = if ($message) { "Visible" } else { "Collapsed" }
}

function restoreIndexDetailEdit {
    # 詳細欄の名前・フォルダパスの欄を、行の今の値に戻す（Esc）
    $item = $script:detailEditItem
    if ($null -eq $item) {
        return
    }
    $ui.IndexDetailName.Text = $item.Name
    $ui.IndexDetailPath.Text = $item.Path
    setIndexDetailEditError ""
}

function commitIndexDetailEdit {
    # 詳細欄の名前・フォルダパスの欄の確定（Enter か、欄から出たとき）。変わっていなければ何もしない。
    # 確かめ（getIndexDetailEditDecision）に通れば、改名・元のフォルダの変更の道（applyIndexEdit）で反映する。
    # 通らないときは、欄の下に理由を出す。欄に残った文字は、Enter のときだけそのままにして直せるようにし、欄から出たときは行の値に戻す
    param (
        [bool]$keepText = $false
    )

    $item = $script:detailEditItem
    if ($null -eq $item -or !$ui.IndexDetailName.IsEnabled) {
        return
    }
    # 更新・削除などが動いている間は反映しない（入力の途中の欄から出たときに割り込まないよう、メッセージは出さず行の値に戻す）
    if ((getCurrentIndexJobBlocker) -ne "") {
        restoreIndexDetailEdit
        return
    }
    $decision = getIndexDetailEditDecision $ui.IndexDetailName.Text $ui.IndexDetailPath.Text $item $script:targetItems
    if ($decision.Action -eq "None") {
        setIndexDetailEditError ""
        return
    }
    if ($decision.Action -eq "Invalid") {
        if (!$keepText) {
            restoreIndexDetailEdit
        }
        setIndexDetailEditError $decision.Message
        return
    }
    setIndexDetailEditError ""
    $ui.IndexDetailName.Text = $decision.Name
    $ui.IndexDetailPath.Text = $decision.Path
    applyIndexEdit $item @{ Path = $decision.Path; Name = $decision.Name }
}

function changeIndexFolder {
    # 詳細のフォルダパスの［変更…］。フォルダを選ぶ画面を出し、選んだ場所をフォルダパスの欄に入れて、欄に直接入力したときと同じ確かめ・同じ反映で変える。
    # 取り消したとき・同じフォルダを選んだときは何も変えない
    $item = getIndexTargetItem
    if ($null -eq $item -or !(testIndexOperable "編集")) {
        return
    }
    $initial = normalizeFolderPath $item.Path
    # 開始フォルダの有無は、直前の refreshFolderStatus の結果がそのまま使えるときだけ調べずに使う
    $knownExisting = $item.StatusChecked -and $item.FolderExists
    $path = selectFolder "インデックスにする、Office ファイルのあるフォルダを選んでください" $initial $window $knownExisting
    if (!$path) {
        return
    }
    $ui.IndexDetailPath.Text = normalizeFolderPath $path
    commitIndexDetailEdit $true
}

function startIndexStoreJob {
    # インデックス（work\index\<名前>）と取り込み一覧の記録の削除・名前の変更を別スレッドで行う。
    # 数万フォルダの削除は数十秒かかることがあり、共有フォルダでは改名にも時間がかかる・届かないことがある。
    # 画面のスレッドで行うと「応答なし」になるため。
    # 終わるまでインデックスの操作・インデックス作成の開始・ワークスペースの変更はできないようにし、何をしているかをステータスに出す
    param (
        [string]$kind,        # "delete"（削除）か "rename"（名前の変更。元のフォルダの記録の書き直しまで行う）
        [string]$name,
        [string]$newName,     # 名前の変更のときの新しい名前
        [object[]]$folders,   # 名前の変更のときに書き直す元のフォルダの記録（@{ Name; Path }）
        [scriptblock]$onDone  # 終わった後に画面のスレッドで行うこと（$script:indexJobName で名前を参照できる）
    )

    $script:indexBusy = $true
    $script:indexJobName = $name
    $script:indexJobOnDone = $onDone
    $script:indexJobKind = $kind
    updateIndexingButton
    setStatus (getIndexStoreJobStatus $kind $name $newName)
    # 裏のスレッドは lib.ps1 を読み込んだときのワークスペースを覚えているため、場所は渡す。
    # 届かない共有フォルダで他の仕事を巻き込んで待たせないよう、ワークスペースの場所で裏の列を選ぶ
    startJob {
        param ($kind, $name, $newName, $folders, $workspaceDir, $settingsPath)
        # インスタンスは裏のスレッドへ渡せないため、場所から作り直す。
        # 届かない場所では、何もせずに成功にしない（設定だけが変わってしまう）。失敗として返す
        $catalog = newIndexCatalog $workspaceDir $settingsPath
        $catalog.AssertReachable()
        if ($kind -eq "rename") {
            # 元のフォルダの記録の書き直しに失敗しても改名は成功で、理由は SourceFolderError で返る
            $catalog.RenameIndexWithSource($name, $newName, $folders)
        } else {
            $catalog.RemoveIndex($name)
        }
    } (@($kind, $name, $newName) + @(,@($folders)) + @($workspace.Dir, ${settingsFile})) {
        param ($output, $errorText)
        $script:indexBusy = $false
        updateIndexingButton
        $name = $script:indexJobName
        if ($errorText) {
            try {
                if ($script:indexJobKind -eq "rename") {
                    # 行にはまだ反映していない。一覧を保存済みの内容に戻す
                    loadTargets
                }
                # 読み直しの結果（届かないときの「接続できません」）で、失敗の知らせが消えないようにする
                $failedText = getIndexStoreJobFailedStatus $script:indexJobKind $name $errorText
                refreshIndexViewsKeepingStatus $failedText
                if ($script:indexJobKind -ne "rename") {
                    # 削除の失敗は、まとめての削除と同じ帯でも知らせる（ステータスと同じ文）
                    showNoticeBanner "IndexNotice" "IndexOpFailed" $failedText
                }
            } finally {
                finishIndexJobClose
            }
            return
        }
        try {
            if ($script:indexJobOnDone) {
                & $script:indexJobOnDone
            }
            if ($script:indexJobKind -ne "rename") {
                # 削除: 一覧からの除去と保存は onDone で済ませてから、画面を読み直す。前の削除の失敗の帯は、成功したので消す
                refreshIndexViews
                hideNoticeBanner "IndexNotice"
            }
            if ($script:indexJobKind -eq "rename") {
                # 改名は済んでいるので、行への反映（上の onDone）は行い、元のフォルダの記録だけ書けなかったことを知らせる
                $sourceFolderError = getIndexStoreSourceFolderError $output
                if ($sourceFolderError -ne "") {
                    setStatus (getSourceFolderFileFailedStatus $sourceFolderError)
                }
            }
        } finally {
            # 後始末が例外になっても、待っていた閉じる操作は必ず進める
            finishIndexJobClose
        }
    } (getWorkspaceJobQueue $workspace.IndexDir)
}

function finishIndexJobClose {
    # 改名・削除の途中で閉じようとして待っていたなら、終わったので閉じる（設定への反映は済んでいる）。
    # 同じ周期で動く残りの仕事の結果が、閉じた窓に届かないよう、閉じるのは画面のスレッドの次の順番にする
    $script:closeAskedDuringIndexJob = $false
    if ($script:closeConfirming) {
        # 「待たずに閉じるか」の確認を出している間（Closing の途中）。ここで Close を呼ぶと窓が壊れるので、確認から戻ったときに閉じる
        return
    }
    if ($script:closeAfterIndexJob) {
        $script:closeAfterIndexJob = $false
        $window.Dispatcher.BeginInvoke([action]{ $window.Close() }) | Out-Null
    }
}

function deleteIndexes {
    # ［削除…］で 2 件以上チェックしているとき。確認は 1 回だけ。1 つ失敗しても残りを続け、終わりに失敗した名前と理由を出す
    param (
        [string[]]$names
    )

    if (!(testIndexOperable "削除")) {
        return
    }
    $confirm = getIndexDeleteConfirmMessage $names
    $answer = showConfirm `
        -title "インデックスの削除" `
        -heading $confirm.Heading `
        -hint $confirm.Body `
        -choices @(@{ Text = "削除する"; Value = "delete"; Danger = $true })
    if ($answer -ne "delete") {
        return
    }

    $script:indexBusy = $true
    $script:indexJobName = ""
    $script:indexJobOnDone = $null
    updateIndexingButton
    setStatus "$($names.Count) 件のインデックスを削除しています…（件数によっては少し時間がかかります）"
    startJob {
        param ($names, $workspaceDir, $settingsPath)
        # インスタンスは裏のスレッドへ渡せないため、場所から作り直す。
        # 届かない場所では、何もせずに成功にしない（設定だけが変わってしまう）。失敗として返す
        $catalog = newIndexCatalog $workspaceDir $settingsPath
        $catalog.AssertReachable()
        $results = $catalog.RemoveIndexes($names)
        , $results
    } @(,$names + @($workspace.Dir, ${settingsFile})) {
        param ($output, $errorText)
        $script:indexBusy = $false
        updateIndexingButton
        try {
            if ($errorText) {
                loadTargets
                $failedText = getBulkDeleteErrorStatus $errorText
                refreshIndexViewsKeepingStatus $failedText
                showNoticeBanner "IndexNotice" "IndexOpFailed" $failedText
                return
            }
            # 消せたものを一覧から外す（失敗したものは残す）
            $results = @($output | ForEach-Object { $_ })
            foreach ($result in $results | Where-Object { $_.Ok }) {
                $item = @($script:targetItems | Where-Object { $_.Name -eq $result.Name })[0]
                if ($item) { $script:targetItems.Remove($item) | Out-Null }
            }
            saveTargets
            updateIndexSourceFile
            updateIndexListView
            refreshIndexViews
            if ($script:closeAfterIndexJob) {
                # 閉じるのを待っているときは、結果のダイアログ（閉じるまで進めない）を出さずに、失敗があればステータスに残して閉じる
                $failed = @($results | Where-Object { !$_.Ok })
                if ($failed.Count -gt 0) {
                    setStatus (getBulkDeleteFailedStatus $failed.Count)
                }
            } else {
                showBulkIndexResult "削除" $results
            }
        } finally {
            finishIndexJobClose
        }
    } (getWorkspaceJobQueue $workspace.IndexDir)
}

function deleteIndex {
    # ［削除］。一覧から削除し、インデックス（work\index\<名前>）と取り込み一覧の記録も削除する
    $item = getIndexTargetItem
    if ($null -eq $item -or !(testIndexOperable "削除")) {
        return
    }

    $confirm = getIndexDeleteConfirmMessage @($item.Name)
    $answer = showConfirm `
        -title "インデックスの削除" `
        -heading $confirm.Heading `
        -hint $confirm.Body `
        -choices @(@{ Text = "削除する"; Value = "delete"; Danger = $true })
    if ($answer -ne "delete") {
        return
    }

    # インデックスの削除（時間がかかることがある）は別スレッドで行う。一覧からの除去と設定の保存は、削除できてから行う
    # （ワークスペースに届かないときは、一覧も設定も変えずに失敗を知らせる）
    # （終わるまでの間に一覧が読み直されると、行は別のオブジェクトになる。名前で探して外す）
    startIndexStoreJob "delete" $item.Name "" @() {
        $removed = @($script:targetItems | Where-Object { $_.Name -eq $script:indexJobName })[0]
        if ($removed) { $script:targetItems.Remove($removed) | Out-Null }
        saveTargets
        updateIndexSourceFile
        updateIndexListView
        setStatus "インデックス [$($script:indexJobName)] を削除しました"
    }
}

# インデックス管理の画面の、インデックスのエクスポート・インポート。

function startIndexArchiveJob {
    # エクスポート・インポートを別スレッドで行う。終わるまでインデックスの操作・インデックス作成の開始・
    # もう一方のエクスポート・インポート・ワークスペースの変更はできないようにする（$script:archiveBusy）。
    # scriptBlock（2 つ目の引数）はこの関数が startJob に渡す、裏で動く仕事。
    # tests/meta/ui_thread_io.Tests.ps1 の getStartJobExcludedRanges が、この 2 つ目の引数を startJob の 1 つ目と同じ扱いで除く
    param (
        [string]$operation,          # "エクスポート" / "インポート"（表示に使う）
        [scriptblock]$scriptBlock,
        [object[]]$arguments,
        [scriptblock]$onSuccess,     # 成功したときに画面のスレッドで行うこと { param($output) }
        [string[]]$paths = @(),      # 仕事が触る、ワークスペースのほかの場所（書き出し先・取り込む zip）。ワークスペースと合わせて、裏の列を選ぶ
        [string]$busyText = ""       # 動いている間のステータス。空なら「<operation>しています…」
    )

    $script:archiveBusy = $true
    $script:archiveJobOperation = $operation
    $script:archiveJobOnSuccess = $onSuccess
    updateIndexingButton
    setStatus $(if ($busyText) { $busyText } else { "${operation}しています…" })
    startJob $scriptBlock $arguments {
        param ($output, $errorText)
        $script:archiveBusy = $false
        setExportingRows @()
        if ($errorText) {
            setStatus "$($script:archiveJobOperation)に失敗しました：${errorText}"
            updateIndexingButton
            return
        }
        if ($output -and $output.Count -gt 0 -and $script:archiveJobOnSuccess) {
            & $script:archiveJobOnSuccess $output[0]
        }
        updateIndexingButton
    } (getWorkspaceJobQueue (@($workspace.Dir) + @($paths)))
}

function showIndexExportDialog {
    # エクスポートのダイアログ。書き出し先のフォルダを返す（キャンセルは $null）
    param (
        [object[]]$items,  # 書き出すインデックス（Name・FileCountText を持つ行）
        [long]$bytes = -1  # 数え終えた zip に入る大きさ（getIndexExportSize）。負なら大きさは出さない
    )

    $dialog = loadWindow "${xamlDir}\dialog_export.xaml"
    $dialog.Owner = $window
    $ctrl = @{}
    foreach ($name in @("ExportButton", "BrowseButton", "ExportPathBox", "IntroText", "ErrorText", "ExportTitleText", "ExportSizeText", "ExportFileText", "CautionText")) {
        $ctrl[$name] = $dialog.FindName($name)
    }
    $header = getIndexExportHeader $items (Get-Date) $bytes
    $ctrl.ExportTitleText.Text = $header.Title
    $ctrl.ExportSizeText.Text = $header.Size
    $ctrl.ExportSizeText.Visibility = if ($header.Size) { "Visible" } else { "Collapsed" }
    $ctrl.ExportFileText.Text = $header.FileText
    $ctrl.CautionText.Text = $header.Caution
    $ctrl.IntroText.Text = getIndexExportNotice
    $ctrl.ExportPathBox.Text = $workspace.Dir

    # ボタンの Click からは script スコープの入れ物を参照する（showIndexImportDialog と同じ理由）
    $script:exportDialog = @{ Window = $dialog; Ctrl = $ctrl }

    $ctrl.BrowseButton.Add_Click({
        safe {
            $d = $script:exportDialog
            $initial = normalizeFolderPath $d.Ctrl.ExportPathBox.Text
            $path = selectFolder "エクスポート先のフォルダを選んでください" $initial $d.Window $false
            if ($path) {
                $d.Ctrl.ExportPathBox.Text = $path
            }
        }
    })
    $ctrl.ExportPathBox.Add_PreviewDragOver({ onFolderDragOver @args })
    $ctrl.ExportPathBox.Add_PreviewDrop({
        param ($sender, $e)
        safe {
            $folders = @(getDroppedFolders $e)
            if ($folders.Count -gt 0) {
                $script:exportDialog.Ctrl.ExportPathBox.Text = $folders[0]
            }
        }
        $e.Handled = $true
    })
    $ctrl.ExportButton.Add_Click({
        safe {
            $d = $script:exportDialog
            $message = testIndexExportInput $d.Ctrl.ExportPathBox.Text
            if ($message -ne "") {
                $d.Ctrl.ErrorText.Text = $message
                $d.Ctrl.ErrorText.Visibility = "Visible"
                return
            }
            $d.Window.DialogResult = $true
        }
    })

    $result = $null
    if ((showOwnedDialog $dialog)) {
        $result = normalizeFolderPath $ctrl.ExportPathBox.Text
    }
    return $result
}

function newExportIndex {
    # ［エクスポート…］。選んだインデックスを 1 つの zip に書き出す
    $item = getIndexTargetItem
    if ($null -eq $item -or !(testIndexOperable "エクスポート")) {
        return
    }
    startExportSizeCount @($item)
}

function startExportSizeCount {
    # エクスポートのダイアログを開く前に、zip に入れる大きさを別スレッドで数える（数える間は archiveBusy で他の操作を止める）。
    # 数え終えたら continueExport がダイアログを開く。対象は script スコープの入れ物に置いて渡す
    # （GetNewClosure() したスクリプトブロックから名前で関数を呼べない環境があるため、閉じ込めない）
    param (
        [object[]]$items   # 書き出すインデックス（Name・FileCountText を持つ行）
    )

    $script:exportPlan = @{ Items = @($items) }
    startIndexArchiveJob "エクスポート" {
        param ($names, $dir)
        $ws = [Workspace]::new($dir)
        getIndexExportSize $names $ws
    } @(,@($items | ForEach-Object { $_.Name }) + @($workspace.Dir)) {
        param ($size)
        continueExport $size
    } @() "エクスポートの大きさを数えています…"
}

function continueExport {
    # startExportSizeCount の続き（大きさを数え終えたところから）。ダイアログで書き出し先を決め、書き出す
    param (
        $size   # getIndexExportSize の結果
    )

    # 大きさを数えている間の文は、ここから先で要らない（ダイアログを開いている間も残さない）
    setStatus ""
    if (@($size.Missing).Count -gt 0) {
        setStatus (getIndexExportMissingText)
        return
    }
    $items = @($script:exportPlan.Items)
    $folder = showIndexExportDialog $items $size.Bytes
    if ($null -eq $folder) {
        setStatus (getIndexArchiveCancelledStatus "エクスポート")
        return
    }
    if ($items.Count -eq 1) {
        $name = $items[0].Name
        setExportingRows @($name)
        # 保存先フォルダの中身を数えるのも別スレッドで行う（届かないネットワークのフォルダで画面が止まらないように）
        startIndexArchiveJob "エクスポート" {
            param ($name, $folder, $dir, $statusPath, $settingsPath)
            $ws = [Workspace]::new($dir)
            exportIndexToFolder $name $folder $ws $settingsPath
        } @($name, $folder, $workspace.Dir, $workspace.StatusFile, ${settingsFile}) {
            param ($result)
            setStatus "インデックス [$($result.Name)] を「$($result.Path)」に書き出しました（$($result.Files) ファイル）"
        }
        return
    }
    $names = @($items | ForEach-Object { $_.Name })
    setExportingRows $names
    startIndexArchiveJob "エクスポート" {
        param ($names, $folder, $dir, $settingsPath)
        $ws = [Workspace]::new($dir)
        $results = exportIndexes -names $names -destination $folder -ws $ws -settingsPath $settingsPath
        , $results
    } @(,$names + @($folder, $workspace.Dir, ${settingsFile})) {
        param ($results)
        showBulkIndexResult "エクスポート" $results
    } @($folder)
}

function showBulkIndexResult {
    # まとめてのエクスポート・削除の終わりに、ステータスバーの 1 行を出し、失敗があれば名前と理由を出す
    param (
        [string]$operation,
        [object[]]$results
    )

    $view = getIndexBulkResultView $operation $results
    setStatus $view.Status
    if ($view.HasFailure) {
        showNoticeBanner "IndexNotice" "IndexOpFailed" "$($view.FailureHeading)`n$($view.FailureDetail)"
    } else {
        hideNoticeBanner "IndexNotice"
    }
}

function newBulkExportIndexes {
    # ［エクスポート…］で 2 件以上チェックしているとき。書き出し先は 1 回だけ選び、1 つ失敗しても残りを続ける
    param (
        [string[]]$names
    )

    if (!(testIndexOperable "エクスポート")) {
        return
    }
    startExportSizeCount @($script:targetItems | Where-Object { $names -contains $_.Name })
}

function showIndexImportDialog {
    # インポートのダイアログ。決めた内容 @{ Path; Name; CollisionMode } を返す（キャンセルは $null）
    param (
        [string]$suggestedName,
        $info   # readIndexArchiveInfo の結果
    )

    $dialog = loadWindow "${xamlDir}\dialog_import.xaml"
    $dialog.Owner = $window
    $dialog.Title = "インデックスのインポート"
    $ctrl = @{}
    foreach ($name in @("ImportButton", "BrowseButton", "FolderBox", "NameBox", "IntroText", "ErrorText", "CollisionPanel", "CollisionHeading", "CollisionNotice", "RenameRadio", "OverwriteRadio",
            "ImportTitleText", "ImportExportedText", "ImportSizeText", "SourceCheckText")) {
        $ctrl[$name] = $dialog.FindName($name)
    }
    $header = getIndexImportHeader $info
    $ctrl.ImportTitleText.Text = $header.Name
    $ctrl.ImportExportedText.Text = $header.Exported
    $ctrl.ImportExportedText.Visibility = if ($header.Exported) { "Visible" } else { "Collapsed" }
    $ctrl.ImportSizeText.Text = $header.Size
    $ctrl.IntroText.Text = getIndexImportNotice
    $ctrl.FolderBox.Text = $info.SourceFolder
    $ctrl.NameBox.Text = $suggestedName

    # ほかのダイアログと同じく、ボタンの Click からは
    # script スコープの入れ物を参照する。GetNewClosure() でこの関数のローカル変数（$ctrl・$dialog）を
    # 取り込むと、tebunko.bat の起動（powershell -Command "...; & gui.ps1"）のように呼び出しが
    # 入れ子になっている実機では、閉じ込めたスクリプトブロックから名前で関数を解決できなくなるため
    # （continueImportIndex で見つかった不具合と同じ原因。docs\design\gui\responsiveness.md の
    # 「画面を固まらせない待たせ方」の注意（PowerShell 5.1）を参照）、ここでは使わない
    # Exists は、フォルダの有無が分かっているパス（正規化して小文字にしたもの → 有無）。画面のスレッドでは調べないので、
    # zip の元のフォルダ（目録を読む別スレッドで調べた info.SourceExists）と、［参照…］で選んだフォルダだけが入る
    $exists = @{}
    if ($null -ne $info.SourceExists) {
        $exists[(normalizeFolderPath $info.SourceFolder).ToLowerInvariant()] = [bool]$info.SourceExists
    }
    # ZipName は zip の中の名前、Mode は同じ名前のときの選び方の今の値（getImportCollisionChoiceView の Mode）
    $script:importDialog = @{ Window = $dialog; Ctrl = $ctrl; Exists = $exists; ZipName = [string]$info.IndexName; Mode = ${importCollisionRename} }

    $ctrl.FolderBox.Add_TextChanged({ safe { updateImportDialogChecks } })
    $ctrl.NameBox.Add_TextChanged({ safe { updateImportDialogChecks } })
    $ctrl.RenameRadio.Add_Checked({ safe { selectImportCollisionMode ${importCollisionRename} } })
    $ctrl.OverwriteRadio.Add_Checked({ safe { selectImportCollisionMode ${importCollisionOverwrite} } })
    $ctrl.BrowseButton.Add_Click({
        safe {
            $d = $script:importDialog
            $initial = normalizeFolderPath $d.Ctrl.FolderBox.Text
            $path = selectFolder "インポートしたインデックスの、今の元のフォルダを選んでください" $initial $d.Window $false
            if ($path) {
                $d.Exists[(normalizeFolderPath $path).ToLowerInvariant()] = $true
                $d.Ctrl.FolderBox.Text = $path
            }
        }
    })
    $ctrl.ImportButton.Add_Click({
        safe {
            $d = $script:importDialog
            $message = testIndexImportInput $d.Ctrl.FolderBox.Text $d.Ctrl.NameBox.Text $script:targetItems
            if ($message -ne "") {
                $d.Ctrl.ErrorText.Text = $message
                $d.Ctrl.ErrorText.Visibility = "Visible"
                return
            }
            $d.Window.DialogResult = $true
        }
    })

    updateImportDialogChecks

    $result = $null
    if ((showOwnedDialog $dialog)) {
        $choice = getImportCollisionChoiceView $ctrl.NameBox.Text $script:importDialog.ZipName (getUsedIndexNames $script:targetItems) $script:importDialog.Mode
        $result = @{ Path = (normalizeFolderPath $ctrl.FolderBox.Text); Name = $ctrl.NameBox.Text.Trim(); CollisionMode = $choice.Mode }
    }
    return $result
}

function updateImportDialogChecks {
    # インポートのダイアログの、元のフォルダの下の 1 行（見つかったか・ほかのインデックスと重なるか）と、名前が重なるときの案内を、
    # 今の入力で出し直す。文言と色の区分は getImportSourceCheckText・getImportCollisionChoiceView
    $d = $script:importDialog
    $ctrl = $d.Ctrl
    $name = $ctrl.NameBox.Text.Trim()
    $key = (normalizeFolderPath $ctrl.FolderBox.Text).ToLowerInvariant()
    $known = if ($d.Exists.ContainsKey($key)) { $d.Exists[$key] } else { $null }
    $check = getImportSourceCheckText $ctrl.FolderBox.Text $known @($script:targetItems | Where-Object { $_.Name -ine $name })
    $brush = switch ($check.Kind) { "Ok" { "Badge.Ok.Text" } "Warn" { "Banner.Warn.Text" } "Ng" { "Badge.Ng.Text" } default { "Ink.Muted" } }
    $ctrl.SourceCheckText.Text = $check.Text
    $ctrl.SourceCheckText.Foreground = themeBrush $brush
    $ctrl.SourceCheckText.Visibility = if ($check.Text) { "Visible" } else { "Collapsed" }
    $choice = getImportCollisionChoiceView $ctrl.NameBox.Text $d.ZipName (getUsedIndexNames $script:targetItems) $d.Mode
    $ctrl.CollisionHeading.Text = $choice.Heading
    $ctrl.CollisionNotice.Text = $choice.Notice
    $ctrl.CollisionNotice.Visibility = if ($choice.Notice) { "Visible" } else { "Collapsed" }
    $ctrl.RenameRadio.Content = $choice.RenameText
    $ctrl.OverwriteRadio.Content = $choice.OverwriteText
    $ctrl.CollisionPanel.Visibility = if ($choice.Visible) { "Visible" } else { "Collapsed" }
    # 名前の欄を手で替えて置き換えられなくなったときは、選び方も別の名前にするに戻す
    # （Mode を先に揃えるので、下の選び直しで selectImportCollisionMode は何もしない）
    $d.Mode = $choice.Mode
    $ctrl.RenameRadio.IsChecked = ($choice.Mode -eq ${importCollisionRename})
    $ctrl.OverwriteRadio.IsChecked = ($choice.Mode -eq ${importCollisionOverwrite})
    $ctrl.ImportButton.Style = $d.Window.FindResource($(if ($choice.Visible -and $choice.Danger) { "Danger.Filled" } else { "Primary" }))
}

function selectImportCollisionMode {
    # 同じ名前のときの選び方を利用者が選んだとき。名前の欄を、別の名前にするなら候補、置き換えるなら置き換える相手の名前にする
    # （updateImportDialogChecks が選び方を揃えたときは、Mode が同じなので何もしない）
    param (
        [string]$mode
    )

    $d = $script:importDialog
    if ($d.Mode -eq $mode) {
        return
    }
    $d.Mode = $mode
    $choice = getImportCollisionChoiceView $d.Ctrl.NameBox.Text $d.ZipName (getUsedIndexNames $script:targetItems) $mode
    $d.Ctrl.NameBox.Text = if ($mode -eq ${importCollisionOverwrite}) { $choice.OverwriteName } else { $choice.Candidate }
    updateImportDialogChecks
}

function newImportIndex {
    # ［インポート…］。zip を選ぶ。目録を読むのは別スレッド（届かないネットワークの zip で画面が止まらないように）
    if (!(testIndexOperable "インポート")) {
        return
    }
    $zipPath = selectZipFile "インポートする zip を選んでください"
    if ($null -eq $zipPath) {
        return
    }

    # onSuccess は別のスレッドの完了を受けて、あとから（別の呼び出しの流れで）実行される。
    # $zipPath（この関数のローカル変数）を参照するため、GetNewClosure() で今の値を取り込む。
    # continueImportIndex は名前のまま呼ばず、openFailedFileFolder と同じく ${function:...} で先に
    # 関数の実体を変数に取り込んでから & で呼ぶ（GetNewClosure() したスクリプトブロックは、
    # tebunko.bat の起動（powershell -Command "...; & gui.ps1"）のように呼び出しが入れ子になっていると、
    # 名前による関数の解決ができないため）
    $continueImport = ${function:continueImportIndex}
    startIndexArchiveJob "インポート" {
        param ($zipPath)
        # 元のフォルダがこの PC にあるか（画面のスレッドで調べないよう、ここで調べる。ネットワークの場所へは接続しない）
        getImportArchiveInfo $zipPath
    } @($zipPath) {
        param ($info)
        & $continueImport $zipPath $info
    }.GetNewClosure() @($zipPath)
}

function continueImportIndex {
    # newImportIndex の続き（目録を読み終えたところから）。名前・元のフォルダを決めて一覧に加える
    param (
        [string]$zipPath,
        $info   # readIndexArchiveInfo の結果
    )

    # @(getUsedIndexNames ...) と直接書くと集合が 1 要素の配列に入るだけで、名前の重なりを見落とす。変数に受けてから使う
    $usedNames = getUsedIndexNames $script:targetItems
    $suggestedName = getImportSuggestedName $info.IndexName $usedNames
    $result = showIndexImportDialog $suggestedName $info
    if ($null -eq $result) {
        setStatus (getIndexArchiveCancelledStatus "インポート")
        return
    }

    $collisionMode = $result.CollisionMode

    startIndexArchiveJob "インポート" {
        param ($zipPath, $collisionMode, $name, $sourceFolder, $dir, $settingsPath)
        $ws = [Workspace]::new($dir)
        importIndex $zipPath $collisionMode $name $sourceFolder $ws $settingsPath
    } @($zipPath, $collisionMode, $result.Name, $result.Path, $workspace.Dir, ${settingsFile}) {
        param ($result)
        if ($null -eq $result) {
            return  # Cancel で置き換えなかった
        }
        # インポートは別スレッドで設定・取り込み一覧を直接書き換えるため、一覧を読み直す（$script:targetItems には無い変更）
        loadTargets
        refreshIndexViews
        setStatus (getImportResultStatus $result)
    } @($zipPath, $result.Path)
}

# インデックス管理の画面の詳細（インデックス作成の開始ボタン・状態・失敗の一覧・状態の合計）。

# 詳細の左右の部品。名前の一覧（shell\regions.ps1）に足さず、読み込んだ中身から取る
foreach ($detailName in @(
        "IndexDetailBody", "IndexDetailName", "IndexDetailPath", "IndexDetailPathButton", "IndexDetailEditError", "IndexDetailFolderStatus", "IndexDetailFolderIcon",
        "IndexDetailBadge", "IndexDetailBadgeText", "IndexDetailBadgeSub", "IndexErrorText", "IndexErrorHintText", "IndexDetailUpdated", "IndexDetailCount",
        "IndexDetailFastBadge", "IndexDetailFastBadgeText", "IndexDetailFastReason", "IndexDetailFastSteps", "IndexDetailFastChecked", "IndexDetailFastNote",
        "IndexingDetailPanel", "IndexingProgressBar", "IndexingCountText", "IndexingFileText", "MultiSelectHintText")) {
    $ui[$detailName] = $ui.IndexDetailHost.Content.FindName($detailName)
}
# 読み取り中のファイルは、「…」で切れているときだけ全文をツールチップで見せる（名前とフォルダパスは入力欄で、欄の中で読める）
addTrimmedToolTip $ui.IndexingFileText

function setIndexBadge {
    # 詳細の状態のバッジの文言と色（一覧の LevelBadge と同じ組み合わせ。level は Ok / Wait / Warn / Ng / Run / None）
    param ($border, $textBlock, [string]$text, [string]$level)

    $kind = if ($level -in @("Ok", "Wait", "Warn", "Ng", "Run")) { $level } else { "None" }
    $border.Background = themeBrush "Badge.${kind}.Bg"
    $border.BorderBrush = themeBrush "Badge.${kind}.Bg"
    $textBlock.Foreground = themeBrush "Badge.${kind}.Text"
    $textBlock.Text = $text
    $border.Visibility = if ($text) { "Visible" } else { "Collapsed" }
}

function setIndexingBanner {
    # 画面の上の帯の色と種類。level は info（更新中）/ warn（中断・中止）/ ok（終わった）/ ng（できなかった）。
    # kind は帯の中身の持ち主（running・interrupted・done）。中断の帯だけは、状態が変わったとき自分で消す
    param ([string]$level, [string]$kind)

    # 地・左端の線（アイコンと［検索する］［続きから再開］［中止］の枠と文字も同じ色）・文字・アイコンの形。見本の 3 状態に合わせ、ng は同じ規則で赤にする
    $looks = @{
        info = @("Badge.Run.Bg", "Accent", "Banner.Info.Text", "Icon.Info")
        warn = @("Warn.Soft", "Warn", "Banner.Warn.Text", "Icon.CircleAlert")
        ok = @("Ok.Soft", "Ok", "Banner.Ok.Text", "Icon.CircleCheck")
        ng = @("Danger.Soft", "Danger.Text", "Banner.Ng.Text", "Icon.CircleAlert")
    }
    $look = $looks[$level]
    if ($null -eq $look) { $look = $looks.info }
    $line = themeBrush $look[1]
    $text = themeBrush $look[2]
    $ui.IndexingProgressPanel.Background = themeBrush $look[0]
    $ui.IndexingProgressPanel.BorderBrush = $line
    $ui.IndexingProgressText.Foreground = $text
    $ui.IndexingProgressDetail.Foreground = $text
    $ui.IndexingBannerIcon.Data = themeBrush $look[3]
    $ui.IndexingBannerIcon.Stroke = $line
    foreach ($button in @($ui.IndexingSearchButton, $ui.IndexingResumeButton, $ui.IndexingStopButton)) {
        $button.BorderBrush = $line
        $button.Foreground = $line
    }
    $ui.IndexingBannerClose.Foreground = $text
    $script:indexingBannerKind = $kind
    $script:indexingBannerDismissed = $false
    $script:indexingBannerLevel = if ($kind -eq "running") { "run" } else { $level }
    setIndexingBannerBehavior
}

function setIndexingBannerBehavior {
    # 閉じるボタンと自動で消える時機（getIndexingBannerBehavior）。残りがあって更新していないときは、閉じられるが自動では消えない
    $pending = if ($script:indexingState -and !(isIndexing)) { [int]$script:indexingState.Pending } else { 0 }
    $behavior = getIndexingBannerBehavior $script:indexingBannerLevel $pending
    $ui.IndexingBannerClose.Visibility = if ($behavior.Closable) { "Visible" } else { "Collapsed" }
    $script:indexingBannerAutoClose = [int]$behavior.AutoCloseSeconds
    $script:indexingBannerTimer.Stop()
    if ($behavior.AutoCloseSeconds -gt 0) {
        $script:indexingBannerTimer.Interval = [TimeSpan]::FromSeconds($behavior.AutoCloseSeconds)
        $script:indexingBannerTimer.Start()
    }
}

function closeIndexingBanner {
    # 帯を閉じる（×と、自動で消える時機）。残りがあるときは、閉じたあとも［続きから再開］の入口（［すべて更新］・行の［更新］・ナビの印）が残る。
    # 帯は、更新を始める・終わる・起動し直すまで出し直さない
    $script:indexingBannerTimer.Stop()
    $ui.IndexingProgressPanel.Visibility = "Collapsed"
    $script:indexingBannerKind = ""
    $script:indexingBannerDismissed = $true
}

function resetIndexingBanner {
    # 帯を初期に戻す（ワークスペースを切り替えたとき）。自動で消える時計も止め、前のワークスペースで閉じた印を持ち越さない
    $script:indexingBannerTimer.Stop()
    $ui.IndexingProgressPanel.Visibility = "Collapsed"
    $script:indexingBannerKind = ""
    $script:indexingBannerDismissed = $false
}

function updateIndexingResume {
    # 中断した更新（残りがあり、いま更新していない）の帯。［続きから再開］を出す。
    # 判断は getIndexingResumeBannerDecision（判断層）。ここは結果を画面に当てるだけ
    $pending = if ($script:indexingState) { [int]$script:indexingState.Pending } else { 0 }
    $decision = getIndexingResumeBannerDecision $pending (isIndexing) ($ui.IndexingProgressPanel.Visibility -eq "Visible") $script:indexingBannerKind $script:indexingBannerDismissed $script:indexingBannerLevel $script:indexingBannerAutoClose
    $script:indexingBannerDismissed = $decision.Dismissed
    $ui.IndexingResumeButton.Visibility = if ($decision.CanResume) { "Visible" } else { "Collapsed" }
    switch ($decision.Action) {
        "Show" {
            setIndexingBanner "warn" "interrupted"
            $ui.IndexingProgressText.Text = getIndexingStateText $pending $false
            $ui.IndexingProgressEta.Text = ""
            $ui.IndexingProgressDetail.Text = ""
            $ui.IndexingProgress.Visibility = "Collapsed"
            $ui.IndexingStopButton.Visibility = "Collapsed"
            $ui.IndexingSearchButton.Visibility = "Collapsed"
            $ui.IndexingProgressPanel.Visibility = "Visible"
        }
        "Text" { $ui.IndexingProgressText.Text = getIndexingStateText $pending $false }
        "Retime" { setIndexingBannerBehavior }
        "Hide" {
            $ui.IndexingProgressPanel.Visibility = "Collapsed"
            $script:indexingBannerKind = ""
        }
    }
}

function updateIndexingButton {
    $ready = $false
    foreach ($item in $script:targetItems) {
        # フォルダの有無は refreshFolderStatus が別スレッドで調べた結果を使う（調べ終えるまではあるものとする）
        if ($item.Enabled -and (!$item.StatusChecked -or $item.FolderExists)) {
            $ready = $true
            break
        }
    }

    $state = $script:indexingState
    if ($script:indexBusy -or $script:archiveBusy -or $script:indexingPreparing -or $script:targetsNaming -or $script:workspaceMoving) {
        # インデックスの削除・名前の変更中・エクスポート・インポート中（別スレッド）・ワークスペースを確かめている間は、インデックス作成もインデックスの操作も始めない
        $ready = $false
    }
    if (isIndexing) {
        $ui.IndexingButton.Content = "更新中…"
        $ui.IndexingButton.IsEnabled = $false
    } else {
        $ui.IndexingButton.Content = "すべて更新"
        $ui.IndexingButton.IsEnabled = $ready
    }

    # ボタンの下の一言は、押せないときの理由と、前回の失敗があるときだけ出す。押すと何が起きるかは、ボタンのツールヒントに書く
    $ui.IndexingButton.ToolTip = if (isIndexing) {
        "更新中も検索できます。やめるときは［中止］を押してください（次に［すべて更新］を押すと続きから再開します）。"
    } else {
        "押すと、何件更新するかを確認してから、新しいファイル・変わったファイルだけを更新します。"
    }
    $hint = ""
    if (!$ready -and !(isIndexing)) {
        $hint = if ($script:targetItems.Count -eq 0) { "フォルダを追加すると更新できます" } else { "更新できるインデックスがありません（行の［更新］で更新できます）。" }
    } elseif ($state -and $state.Failed -gt 0 -and !(isIndexing)) {
        $hint = "前回うまく更新できなかったファイルがあります（原因は、下の「更新に失敗したファイル」で確かめられます）。"
    }
    $ui.IndexingHint.Text = $hint
    $ui.IndexingHint.Visibility = if ($hint) { "Visible" } else { "Collapsed" }

    # インデックスの追加・編集・削除・エクスポート・インポートと、［設定］のワークスペースの［変更…］は互いに排他
    # （getIndexJobBlocker・getIndexTabButtonsEnabled。settings\settings.ps1 の testWorkspaceChangeable も同じ排他を見る）
    $selected = $null -ne (getIndexTargetItem)
    $blocker = getCurrentIndexJobBlocker
    $buttons = getIndexTabButtonsEnabled $blocker $selected
    $ui.NewIndexButton.IsEnabled = $buttons.New
    $ui.IndexDetailPathButton.IsEnabled = $buttons.ChangeFolder
    # 名前とフォルダパスの欄は、動いている処理が無く、1 件選んでいるときだけ直せる
    $ui.IndexDetailName.IsEnabled = $buttons.Edit
    $ui.IndexDetailPath.IsEnabled = $buttons.Edit
    # 行の右クリックのメニュー（対象は押した行。可否は getIndexRowMenuEnabled）
    $pressed = $ui.IndexGrid.SelectedItem
    $menu = getIndexRowMenuEnabled $blocker ($null -ne $pressed) $(if ($pressed) { $pressed.IndexLevel } else { "None" }) ($null -ne $pressed -and [bool]$pressed.Path)
    $ui.RowMenuUpdate.IsEnabled = $menu.Update
    $ui.RowMenuOpenFolder.IsEnabled = $menu.OpenFolder
    $ui.ExportIndexButton.IsEnabled = $menu.Export
    $ui.RemoveIndexButton.IsEnabled = $menu.Delete
    $actions = getIndexActionsEnabled $blocker @(getIndexCheckedItems @($script:targetItems)).Count
    $ui.ActionsButton.IsEnabled = $true
    $ui.ActionUpdate.IsEnabled = $actions.Update
    $ui.ActionExport.IsEnabled = $actions.Export
    $ui.ActionImport.IsEnabled = $actions.Import
    $ui.ActionDelete.IsEnabled = $actions.Delete
    # 行の［更新］も同じ排他（更新中はほかの行の［更新］も押せない）。行ごとのボタンを置き直す
    foreach ($item in $script:targetItems) {
        setIndexRowActions $item
    }
}

function refreshIndexingState {
    # 取り込み一覧の集計は、ファイルが数万行になると数秒～十数秒かかる。
    # 画面のスレッドで行うと、起動時・タブの切り替え時に画面が固まる（応答なしになる）ため別スレッドで数える
    if ($script:stateRunning) {
        $script:stateAgain = $true
        return
    }
    $script:stateRunning = $true
    $script:stateAgain = $false
    $script:stateJobPath = $workspace.StatusFile
    startJob {
        param ($path)
        getIndexingState -path $path
    } @($script:stateJobPath) {
        param ($output, $errorText)
        $script:stateRunning = $false
        if ($script:stateJobPath -ne $workspace.StatusFile) {
            # 集計している間にワークスペースを変えた。前のワークスペースの結果は出さず、読み直す
            $script:stateAgain = $true
        } elseif ($output -and $output.Count -gt 0 -and $output[0]) {
            # インデクサが書き込んでいる瞬間などは、次の機会に読み直す
            applyIndexingState $output[0]
        }
        if ($script:stateAgain) {
            refreshIndexingState
        }
    } (getWorkspaceJobQueue $script:stateJobPath)
}

function getIndexingRatio {
    # 更新全体の進み（0～1）。更新中でない・割合がまだ分からないときは負の値
    if ((isIndexing) -and !$ui.IndexingProgress.IsIndeterminate) {
        return [double]$ui.IndexingProgress.Value
    }
    return -1.0
}

function updateIndexTabBadge {
    # ナビの［インデックス管理］の横の印（更新中の割合・中断・失敗。文言は getIndexNavBadge）
    $state = $script:indexingState
    $pending = if ($state) { [int]$state.Pending } else { 0 }
    $failed = if ($state) { [int]$state.Failed } else { 0 }
    $ratio = getIndexingRatio
    $badge = getIndexNavBadge (isIndexing) $ratio $pending $failed
    $ui.IndexTabBadge.Text = $badge.Text
    $ui.IndexTabBadge.ToolTip = $badge.ToolTip
    $ui.IndexTabBadge.Foreground = if ($badge.Kind -eq "Run") { ${infoBrush} } else { ${warnBrush} }
    $ui.IndexTabBadge.Visibility = if ($badge.Text) { "Visible" } else { "Collapsed" }
}

function applyIndexingState {
    # 集計（別スレッド）の結果を画面に反映する
    param (
        $state  # getIndexingState の結果
    )

    $script:indexingState = $state

    # 失敗したファイルは下の一覧に原因とともに表示する
    applyIndexStats $state.IndexStats (isIndexing)
    updateFailedList $state
    updateIndexSummaryText
    updateIndexingButton
    updateIndexingResume
    updateIndexTabBadge
}

function updateFailedList {
    # 取り込みに失敗したファイルと原因（取り込み一覧のエラー列）を一覧に表示する
    # 詳細に出している行（getIndexTargetItem）があれば、その行のインデックスの失敗だけを出す（無ければ全部）
    param (
        $state  # getIndexingState の結果
    )

    $detailItem = getIndexTargetItem
    $filterName = if ($null -ne $detailItem) { [string]$detailItem.Name } else { "" }
    $script:failedFilterName = $filterName
    $folderPaths = @{}  # インデックス名 → クロール対象フォルダ（大文字・小文字を区別しない）
    foreach ($folder in $state.Folders) {
        if ($folder.Name) {
            $folderPaths[$folder.Name] = $folder.Path
        }
    }

    $rows = New-Object System.Collections.ArrayList
    foreach ($status in (selectFailedRowsForIndex $state.FailedRows $filterName)) {
        $row = New-Object FailRow
        $row.RelPath = $status.相対パス
        $row.Reason = if ($status.エラー) { $status.エラー } else { "（原因は記録されていません）" }
        $ingested = [datetime]::MinValue
        if ([datetime]::TryParseExact([string]$status.取り込み日時, "yyyy/MM/dd HH:mm:ss", [System.Globalization.CultureInfo]::InvariantCulture, [System.Globalization.DateTimeStyles]::None, [ref]$ingested)) {
            $row.IngestedText = formatTime $ingested
        }
        $parts = splitIndexRelPath $status.相対パス
        if ($folderPaths.ContainsKey($parts.Name)) {
            $row.SourcePath = Join-Path $folderPaths[$parts.Name] $parts.Rest
        }
        [void]$rows.Add($row)
    }

    $ui.FailedGrid.ItemsSource = $rows
    $ui.FailedHeading.Text = "更新に失敗したファイル $($rows.Count) 件"
    $ui.FailedPanel.Visibility = if ($rows.Count -gt 0) { "Visible" } else { "Collapsed" }
}

$script:failedFileRequest = [ref]0  # 失敗したファイルを確かめる依頼の番号（find SourceFile の $script:openSourceRequest と同じ理由で [ref] のまま閉じ込める）

function openFailedFileFolder {
    # 失敗したファイルの場所をエクスプローラーで開く（ファイルを選択した状態）。
    # ネットワークにあれば裏のスレッドで確かめ、画面のスレッドは待たない
    $row = $ui.FailedGrid.SelectedItem
    if ($null -eq $row) {
        return
    }
    if (!$row.SourcePath) {
        setStatus "元のファイルの場所が分かりません（元のフォルダの記録がありません）：$($row.RelPath)"
        return
    }
    $path = $row.SourcePath
    $requestBox = $script:failedFileRequest
    $requestBox.Value++
    $requestId = $requestBox.Value
    $applyState = ${function:applyFailedFileState}
    $apply = {
        param ($state, $dirState)
        if ($requestId -ne $requestBox.Value) {
            # 待っている間に別の行を選んだ。前の依頼は捨てる
            return
        }
        & $applyState $state $path $dirState
    }.GetNewClosure()

    if (!(testNetworkPath $path)) {
        $state = getPathState $path
        $dirState = if ($state.State -eq ${pathStateMissing}) { getPathState (Split-Path $path -Parent) } else { $null }
        & $apply $state $dirState
        return
    }
    setStatus (getFailedFileCheckingStatus $path)
    $otherState = ${pathStateOther}
    startJob {
        param ($path)
        # フォルダの有無も、ファイルが無い（Missing）ときだけ、ここ（裏のスレッド）で調べて返す
        # （画面のスレッドで Test-Path すると、届かない共有・一覧に無いネットワークのエラーで止まるおそれがあるため）
        $state = getPathState $path
        $state
        if ($state.State -eq ${pathStateMissing}) {
            getPathState (Split-Path $path -Parent)
        }
    } @($path) {
        param ($output, $errorText)
        if ($errorText) {
            & $apply @{ State = $otherState; Message = $errorText } $null
        } else {
            & $apply $output[0] $output[1]
        }
    }.GetNewClosure() (getWorkspaceJobQueue $path)
}

function applyFailedFileState {
    # openFailedFileFolder の続き（getPathState の結果を画面に反映する）。
    #   dirState: ファイルが無い（Missing）ときだけ渡す、フォルダの getPathState の結果。それ以外は $null
    param (
        $state,
        [string]$path,
        $dirState = $null
    )

    if ($state.State -eq ${pathStateFound} -and !$state.IsDirectory) {
        Start-Process -FilePath "explorer.exe" -ArgumentList "/select,`"${path}`""
        return
    }
    if ($state.State -eq ${pathStateUnreachable}) {
        setStatus (getFailedFileUnreachableStatus $path)
        return
    }
    if ($state.State -eq ${pathStateMissing}) {
        # フォルダが見つかったときだけ、フォルダを開く（有無は裏のスレッドで調べてある）
        if ($dirState -and $dirState.State -eq ${pathStateFound}) {
            Start-Process -FilePath "explorer.exe" -ArgumentList "`"$(Split-Path $path -Parent)`""
            setStatus "ファイルが見つからないため、フォルダを開きました（移動・削除された可能性があります）：${path}"
            return
        }
        setStatus "ファイルが見つかりません（移動・削除された可能性があります）：${path}"
        return
    }
    # その他（Other。アクセス拒否・一覧に無いネットワークのエラーなど）は、フォルダをたどらず文言だけ出す
    setStatus (getFailedFileOtherStatus $state.Message)
}

# 詳細の値の行を最後に置いたときの getIndexDetailView の RowsKey（同じ中身なら行を置き直さない）
$script:detailRowsKey = $null
$script:failedFilterName = ""  # 失敗の一覧を絞っているインデックスの名前（空は全部。updateFailedList が置く）
$script:indexingView = $null  # 詳細の「インデックス」の箱に出す、全体の進み具合（updateIndexingProgress が置く。更新中でなければ $null）

function getIndexTargetItem {
    # 詳細に出している行（名前・フォルダパスの欄と［変更…］、右クリックの［削除］［エクスポート…］の対象・可否もこの行。判定は getIndexDetailItem。［アクション ▼］は別で、可否・対象は getIndexActionsEnabled と、チェックの行が決める）
    return getIndexDetailItem $ui.IndexGrid.SelectedItem @(getIndexCheckedItems @($script:targetItems))
}

function updateIndexDetailPanel {
    # 選んだインデックスの値の行と、高速検索の反映の進み具合を出す（文言の組み立ては getIndexDetailView）。
    # 選びなおしたとき・取り込みの集計や高速検索の確かめが届いたときに呼ぶ
    $selected = @()
    $entry = $null
    $checkedItems = @(getIndexCheckedItems @($script:targetItems))
    $item = getIndexDetailItem $ui.IndexGrid.SelectedItem $checkedItems
    if ($null -ne $item) {
        $checkedText = if ($null -ne $script:fastSearchCheckedAt) { "最終確認 $($script:fastSearchCheckedAt.ToString('HH:mm'))" } else { "" }
        $selected = @(@{
            Name = $item.Name; Path = $item.Path; Enabled = $item.Enabled; FolderStatus = $item.StatusText
            FolderMissing = ($item.StatusChecked -and !$item.FolderExists); FolderChecked = [bool]$item.StatusChecked
            IndexText = $item.IndexText; IndexLevel = $item.IndexLevel; IndexSub = $item.IndexSub; FileCountText = $item.FileCountText
            LastIngestedText = $item.LastIngestedText; FastText = $item.FastText; FastLevel = $item.FastLevel
            FastToolTip = $item.FastToolTip; FastSteps = $item.FastSteps; FastCheckedText = $checkedText
        })
        $progress = $script:fastSearchProgress
        if ($progress -and $progress.ByIndex -and $progress.ByIndex.ContainsKey($item.Name)) {
            $entry = $progress.ByIndex[$item.Name]
        }
    }
    # 選んだインデックスが変わったら、失敗の一覧もそのインデックスの分に書き直す（変わらないときは置き直さない）
    $failedName = if ($null -ne $item) { [string]$item.Name } else { "" }
    if ($null -ne $script:indexingState -and $failedName -ne [string]$script:failedFilterName) {
        updateFailedList $script:indexingState
    }
    $multiCount = getIndexDetailMultiCount $checkedItems.Count
    $view = getIndexDetailView $selected $entry $multiCount $script:indexingView

    $ui.IndexDetailTitle.Text = $view.Title
    $ui.IndexDetailBody.Visibility = if ($view.Selected) { "Visible" } else { "Collapsed" }
    $ui.MultiSelectHintText.Text = $view.Hint
    $ui.MultiSelectHintText.Visibility = if ($view.Multi) { "Visible" } else { "Collapsed" }
    # 更新中の行では、最終更新・件数の代わりに進み具合（棒・件数と残り時間・ファイル名）を出す
    $ui.IndexingDetailPanel.Visibility = if ($view.Run.Shown) { "Visible" } else { "Collapsed" }
    $ui.IndexingProgressBar.Value = $view.Run.Value
    $ui.IndexingCountText.Text = $view.Run.CountText
    $ui.IndexingFileText.Text = $view.Run.FileText
    # 名前・フォルダパスの欄は、直している最中（同じ行で、欄に入力の途中）なら、定期の更新で入力を消さない
    $editing = ($null -ne $item -and [object]::ReferenceEquals($item, $script:detailEditItem) -and
        ($ui.IndexDetailName.IsFocused -or $ui.IndexDetailPath.IsFocused))
    if (!$editing) {
        if (![object]::ReferenceEquals($item, $script:detailEditItem)) {
            setIndexDetailEditError ""
        }
        $script:detailEditItem = $item
        $ui.IndexDetailName.Text = $view.Name
        $ui.IndexDetailPath.Text = $view.Path
    }
    $ui.IndexDetailFolderStatus.Text = $view.FolderStatus
    $ui.IndexDetailFolderStatus.Foreground = themeBrush $view.FolderBrush
    # 文の左のアイコン（Lucide の check・x）。空なら隠す
    if ($view.FolderIcon) {
        $ui.IndexDetailFolderIcon.Data = (loadTheme)["Icon.$($view.FolderIcon)"]
        $ui.IndexDetailFolderIcon.Stroke = themeBrush $view.FolderBrush
        $ui.IndexDetailFolderIcon.Visibility = "Visible"
    } else {
        $ui.IndexDetailFolderIcon.Visibility = "Collapsed"
    }
    setIndexBadge $ui.IndexDetailBadge $ui.IndexDetailBadgeText $view.Badge.Text $view.Badge.Level
    $ui.IndexDetailBadgeSub.Text = if ($view.Selected) { [string]$view.Badge.Sub } else { "" }
    $ui.IndexErrorText.Text = $view.Error
    $ui.IndexErrorText.Visibility = if ($view.Error) { "Visible" } else { "Collapsed" }
    $ui.IndexErrorHintText.Text = $view.ErrorHint
    $ui.IndexErrorHintText.Visibility = if ($view.ErrorHint) { "Visible" } else { "Collapsed" }
    $ui.IndexDetailUpdated.Text = if ($view.Run.Shown) { "" } else { $view.Updated }
    $ui.IndexDetailCount.Text = if ($view.Run.Shown) { "" } else { $view.Count }
    $ui.IndexDetailUpdated.Visibility = if ($ui.IndexDetailUpdated.Text) { "Visible" } else { "Collapsed" }
    $ui.IndexDetailCount.Visibility = if ($ui.IndexDetailCount.Text) { "Visible" } else { "Collapsed" }
    if ($script:detailRowsKey -ne $view.RowsKey -or $null -eq $ui.IndexDetailRows.ItemsSource) {
        $script:detailRowsKey = $view.RowsKey
        $rows = New-Object 'System.Collections.ObjectModel.ObservableCollection[DetailRow]'
        foreach ($row in $view.Rows) {
            $detailRow = New-Object DetailRow
            $detailRow.Label = $row.Label
            $detailRow.Value = $row.Value
            $rows.Add($detailRow)
        }
        $ui.IndexDetailRows.ItemsSource = $rows
    }
    setIndexBadge $ui.IndexDetailFastBadge $ui.IndexDetailFastBadgeText $view.Fast.State $view.Fast.Level
    $ui.IndexDetailFastReason.Text = $view.Fast.Reason
    $ui.IndexDetailFastReason.Visibility = if ($view.Fast.Reason) { "Visible" } else { "Collapsed" }
    $ui.IndexDetailFastSteps.Text = (@($view.Fast.Steps | ForEach-Object { "・$_" }) -join "`n")
    $ui.IndexDetailFastSteps.Visibility = if (@($view.Fast.Steps).Count -gt 0) { "Visible" } else { "Collapsed" }
    $ui.IndexDetailFastPanel.Visibility = if ($view.Fast.Shown) { "Visible" } else { "Collapsed" }
    $ui.IndexDetailFastText.Text = $view.Fast.Text
    $ui.IndexDetailFastBar.Value = $view.Fast.Value
    $ui.IndexDetailFastChecked.Text = $view.Fast.Checked
    $ui.IndexDetailFastNote.Text = $view.Fast.Note
    $ui.IndexDetailFastNote.Visibility = if ($view.Fast.Note) { "Visible" } else { "Collapsed" }
}

function updateIndexSummaryText {
    $summary = $script:indexSummary
    if ($null -eq $summary) {
        $ui.IndexSummaryText.Text = "確認中…"
        return
    }
    if ($summary["Count"] -eq 0) {
        $ui.IndexSummaryText.Text = "まだインデックスがありません。"
        return
    }
    $text = "集約ファイル $($summary['Count'].ToString('N0')) 件 ・ 最終更新 $(formatTime $summary['LastWrite'])"
    $state = $script:indexingState
    if ($state -and $state.Done -gt 0) {
        $text = "更新済み $($state.Done.ToString('N0')) ファイル（$text）"
    }
    $ui.IndexSummaryText.Text = $text
}

function refreshIndexSummary {
    # 本文インデックスのファイルの件数は数えるのに時間がかかることがあるため、別スレッドで数える
    if ($script:summaryRunning) {
        $script:summaryAgain = $true
        return
    }
    $script:summaryRunning = $true
    $script:summaryAgain = $false
    $script:summaryJobDir = $workspace.IndexDir
    startJob {
        param ($folders)
        getIndexSummary $folders
    } @(, @($script:summaryJobDir)) {
        param ($output, $errorText)
        $script:summaryRunning = $false
        if ($script:summaryJobDir -ne $workspace.IndexDir) {
            # 数えている間にワークスペースを変えた。前のワークスペースの件数は出さず、数え直す
            $script:summaryAgain = $true
        } elseif ($output -and $output.Count -gt 0) {
            $script:indexSummary = $output[0]
        }
        updateIndexSummaryText
        updateSearchTarget
        if ($script:summaryAgain) {
            refreshIndexSummary
        }
    } (getWorkspaceJobQueue $script:summaryJobDir)
}

# インデックス管理の画面のイベントの登録（ボタン・一覧の操作・行のメニュー）。

# ステータス列の見出しの説明（文言は index_list_view.ps1 が決める）
$ui.StatusColumnHeader.ToolTip = (getIndexStatusHelpText) -join "`n"
# 帯の閉じるボタンと、帯が自動で消えるときの時計（時間は setIndexingBannerBehavior が決めて動かす）
$script:indexingBannerTimer = newTimer 8000 { safe { closeIndexingBanner } }
$ui.IndexingBannerClose.Add_Click({ safe { closeIndexingBanner } })
$ui.NewIndexButton.Add_Click({ safe { newIndex } })
$ui.IndexEmptyAddButton.Add_Click({ safe { newIndex } })
# 詳細の名前・フォルダパスの欄: Enter か欄から出たときに確定、Esc で取り消す（確かめと反映は commitIndexDetailEdit）
foreach ($editBox in @($ui.IndexDetailName, $ui.IndexDetailPath)) {
    $editBox.Add_KeyDown({
        param ($sender, $e)
        if ($e.Key -eq "Return") {
            safe { commitIndexDetailEdit $true }
            $e.Handled = $true
        } elseif ($e.Key -eq "Escape") {
            safe { restoreIndexDetailEdit }
            $e.Handled = $true
        }
    })
    $editBox.Add_LostFocus({ safe { commitIndexDetailEdit $false } })
    # 欄の中身が行の値に戻ったら、前のエラーの文言を消す
    $editBox.Add_TextChanged({
        safe {
            $edited = $script:detailEditItem
            if ($null -ne $edited -and $ui.IndexDetailName.Text -ceq $edited.Name -and $ui.IndexDetailPath.Text -eq $edited.Path) {
                setIndexDetailEditError ""
            }
        }
    })
}
# 行の右クリックの［更新］は、行の右端の［更新］と同じ処理（押した行だけを更新する）
$ui.RowMenuUpdate.Add_Click({
    safe {
        $item = getIndexTargetItem
        if ($item) { updateSelectedIndexes @($item.Name) }
    }
})
$ui.RowMenuOpenFolder.Add_Click({ safe { openIndexSourceFolder } })
$ui.IndexDetailPathButton.Add_Click({ safe { changeIndexFolder } })
$ui.RemoveIndexButton.Add_Click({ safe { deleteIndex } })
$ui.ExportIndexButton.Add_Click({ safe { newExportIndex } })
# ［アクション ▼］: 押したら、ボタンの下にメニューを開く（項目の可否は updateIndexingButton が決める）
$ui.ActionsButton.Add_Click({
    safe {
        $ui.ActionsMenu.PlacementTarget = $ui.ActionsButton
        $ui.ActionsMenu.Placement = [System.Windows.Controls.Primitives.PlacementMode]::Bottom
        $ui.ActionsMenu.IsOpen = $true
    }
})
$ui.ActionImport.Add_Click({ safe { newImportIndex } })
# ［エクスポート…］［削除…］は、チェックを付けた行に対して動く。1 件なら既存の 1 件ずつの処理（一覧で選んでいる行に効くため、
# その行を選んでから呼ぶ）、2 件以上ならまとめての処理（書き出し先・削除の確認は 1 回）
$ui.ActionExport.Add_Click({
    safe {
        $checked = @(getIndexCheckedItems @($script:targetItems))
        if ($checked.Count -eq 1) {
            $ui.IndexGrid.SelectedItem = $checked[0]
            newExportIndex
        } elseif ($checked.Count -ge 2) {
            newBulkExportIndexes @($checked | ForEach-Object { $_.Name })
        }
    }
})
$ui.ActionDelete.Add_Click({
    safe {
        $checked = @(getIndexCheckedItems @($script:targetItems))
        if ($checked.Count -eq 1) {
            $ui.IndexGrid.SelectedItem = $checked[0]
            deleteIndex
        } elseif ($checked.Count -ge 2) {
            deleteIndexes @($checked | ForEach-Object { $_.Name })
        }
    }
})
# 一覧の名前・パスは、「…」で切れている行だけ全文をツールチップで見せる（行ごとに 1 回だけ、行の Loaded で印の付いた TextBlock に付ける）
$ui.IndexGrid.Add_LoadingRow({
    param ($sender, $e)
    addTrimmedToolTipToRows $e.Row "TrimTip"
})
$ui.ActionUpdate.Add_Click({ safe { updateSelectedIndexes @(getIndexCheckedItems @($script:targetItems) | ForEach-Object { $_.Name }) } })
# 行の［更新］［中止］は行ごとの部品なので、一覧の Click で受ける
$ui.IndexGrid.AddHandler([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent, [System.Windows.RoutedEventHandler]{
    param ($sender, $e)
    safe {
        $button = $e.OriginalSource
        if ($button -isnot [System.Windows.Controls.Button]) {
            return
        }
        if ($button.Tag -eq "RowUpdate" -and $button.DataContext -is [FolderItem]) {
            updateSelectedIndexes @($button.DataContext.Name)
            $e.Handled = $true
        } elseif ($button.Tag -eq "RowStop") {
            stopIndexing
            $e.Handled = $true
        }
    }
})
# 見出しの全選択: 1 件でも付いていないものがあれば全部付け、全部付いていれば全部外す（一部だけのときは付ける側）。
# チェックはその場だけの選びなので、保存しない
$ui.SelectAllCheckBox.Add_Click({
    safe {
        $items = @($script:targetItems)
        $checkedCount = @(getIndexCheckedItems $items).Count
        $value = ($checkedCount -lt $items.Count)
        foreach ($item in $items) {
            $item.SetRowChecked($value)
        }
        updateIndexListView
    }
})
# 行を右クリックしたら、その行を選んでからメニューを開く（選んでいる別の行にメニューが効かないようにする）。
# 行の外（列見出し・余白）では開かない
$ui.IndexGrid.Add_PreviewMouseRightButtonDown({
    param ($sender, $e)
    safe {
        $row = getDataGridRowAt $e.OriginalSource
        if ($row) {
            $ui.IndexGrid.SelectedItem = $row.Item
        }
    }
})
$ui.IndexGrid.Add_ContextMenuOpening({
    param ($sender, $e)
    safe {
        if (!(getDataGridRowAt $e.OriginalSource)) {
            $e.Handled = $true
        }
    }
})
$ui.IndexGrid.Add_SelectionChanged({ safe { updateIndexListView } })
$ui.IndexGrid.Add_KeyDown({
    param ($sender, $e)
    if ($e.Key -eq "Delete") {
        safe { deleteIndex }
    }
})
$ui.IndexGrid.Add_PreviewDragOver({ onFolderDragOver @args })
$ui.IndexGrid.Add_PreviewDrop({
    param ($sender, $e)
    safe {
        foreach ($folder in (getDroppedFolders $e)) {
            addIndexForFolder $folder
        }
    }
    $e.Handled = $true
})

# ［インデックス管理］タブのうち、インデックス作成の開始・中止と進み具合の表示。

# ---- インデックス作成の起動と進み具合 ----

function getIndexingProgress {
    # インデックス作成の進み具合を返す（インデクサが受け渡しの口に入れた進み具合を読む。取り込み一覧は読まない）
    $progress = @{ Scanned = $false; Processed = 0; Failed = 0; Remaining = 0; Current = ""; Detail = ""; Finishing = $false; Confirming = $false }
    $current = $null
    if ($script:indexingSession) {
        $current = readIndexingProgress $script:indexingSession.Channel
    }
    if ($null -eq $current) {
        return $progress
    }

    $progress.Scanned = ($current.Phase -ne ${indexingPhaseCrawl})
    $progress.Confirming = ($current.Phase -eq ${indexingPhaseConfirm})
    $progress.Finishing = ($current.Phase -eq ${indexingPhaseFinish})
    $progress.Processed = $current.Processed
    $progress.Remaining = $current.Remaining
    $progress.Failed = $current.Failed
    $progress.Detail = $current.Detail
    if ($progress.Scanned) {
        $progress.Current = $current.Detail  # 取り込み中のファイルの相対パス
    }
    return $progress
}


function showIndexingPanel {
    setIndexingBanner "info" "running"
    $ui.IndexingProgressPanel.Visibility = "Visible"
    $ui.IndexingProgress.Visibility = "Visible"
    $ui.IndexingProgress.IsIndeterminate = $true
    updateIndexTabBadge
    $ui.IndexingResumeButton.Visibility = "Collapsed"
    $ui.IndexingProgressText.Text = "更新の準備をしています…"
    $ui.IndexingProgressEta.Text = ""
    $ui.IndexingProgressDetail.Text = "更新するファイルを確認しています。"
    $ui.IndexingStopButton.Visibility = "Visible"
    $ui.IndexingStopButton.IsEnabled = $true
    $ui.IndexingSearchButton.Visibility = "Collapsed"
    $taskbar.ProgressState = "Indeterminate"
}

function buildPlanRows {
    # 更新の予定を確認のダイアログの一覧に変える（文言と色の種類は indexing_view.ps1 が決める）
    param (
        $plan  # readIngestPlan の結果
    )

    $rows = New-Object System.Collections.Generic.List[PlanRow]
    # , で包んだ戻り値は、そのまま foreach に渡すと空のときも 1 回まわるため、変数に受けてから回す
    $views = newPlanViewRows $plan $script:indexingOnlyNames
    foreach ($view in $views) {
        $row = [PlanRow]::new()
        $row.Name = $view.Name
        $row.Path = $view.Path
        $row.TotalText = $view.TotalText
        $row.StatusText = $view.StatusText
        $row.Level = $view.Level
        $row.DetailText = $view.DetailText
        $rows.Add($row)
    }
    return , $rows.ToArray()
}
function updateIndexingConfirmTotal {
    # チェックの値に合わせて、合計・主ボタン・チェックボックスの表示を変える（文言と可否は getIndexingConfirmView が決める）
    $d = $script:confirmDialog
    $view = getIndexingConfirmView $d.Plan @($script:indexingOnlyNames) ([bool]$d.Ctrl.RetryCheck.IsChecked) ([bool]$d.Ctrl.CloudCheck.IsChecked)
    $d.View = $view
    $d.Ctrl.TotalText.Text = $view.Confirm.Text
    $d.Ctrl.StartButton.Content = $view.Confirm.Button
    $d.Ctrl.RetryCheck.Visibility = $(if ($view.RetryVisible) { "Visible" } else { "Collapsed" })
    $d.Ctrl.RetryCheck.Content = $view.RetryText
    $cloudVisibility = $(if ($view.CloudVisible) { "Visible" } else { "Collapsed" })
    $d.Ctrl.CloudWarnText.Visibility = $cloudVisibility
    $d.Ctrl.CloudCheck.Visibility = $cloudVisibility
    $d.Ctrl.CloudRememberCheck.Visibility = $cloudVisibility
    $d.Ctrl.CloudWarnText.Text = $view.CloudWarn
    $d.Ctrl.CloudCheck.Content = $view.CloudCheckText
    # 「次から確認を出さない」は、ダウンロードして取り込むを選んだときだけ選べる
    $d.Ctrl.CloudRememberCheck.IsEnabled = $view.Include
}
function showIndexingConfirmDialog {
    # インデックス作成の確認。インデクサが数えた結果（インデックスごとの取り込み対象の件数）を出して、取り込むかどうかを選んでもらう。
    #   取り込む → @{ RetryFailed; IncludeCloud } ／ 取りやめ → $null
    param (
        $plan  # readIngestPlan の結果
    )

    $dialog = loadWindow "${xamlDir}\dialog_indexing_confirm.xaml"
    $dialog.Owner = $window
    $ctrl = @{}
    foreach ($name in @("StartButton", "CancelButton", "RetryCheck", "CloudWarnText", "CloudCheck", "CloudRememberCheck", "TotalText", "NoteText", "IntroText", "PlanGrid")) {
        $ctrl[$name] = $dialog.FindName($name)
    }
    # 設定の cloudFiles は開くときに 1 回だけ読む（開始するとき、変わったときだけ書き戻す）
    $savedCloud = readCloudFiles
    $script:confirmDialog = @{ Window = $dialog; Ctrl = $ctrl; Plan = $plan; SavedCloud = $savedCloud; View = $null; Answer = $null }

    $ctrl.PlanGrid.ItemsSource = buildPlanRows $plan
    $ctrl.IntroText.Text = getIndexingConfirmIntro (getIndexingDroppedCount $plan)
    $ctrl.IntroText.Visibility = if ($ctrl.IntroText.Text) { "Visible" } else { "Collapsed" }
    $ctrl.CloudRememberCheck.Content = ${indexingCloudRememberText}
    if ($savedCloud -eq ${cloudFilesDownload}) {
        # 前回「次から確認を出さずにダウンロードする」を選んだ。チェックを付けておく（欄が出るときに効く）
        $ctrl.CloudCheck.IsChecked = $true
        $ctrl.CloudRememberCheck.IsChecked = $true
    }
    updateIndexingConfirmTotal
    # 削除予定があるときは、取りやめと［更新を開始］を選べるままにする（閉じるだけにすると、見せたまま消してしまう）
    $nothing = [bool]$script:confirmDialog.View.Nothing
    if ($nothing) {
        # 取り込むものが無いときは、閉じるだけ（［キャンセル］との違いが無い）
        $ctrl.CancelButton.Visibility = "Collapsed"
        $ctrl.NoteText.Visibility = "Visible"
        $ctrl.NoteText.Text = "更新日時が変わらないまま中身が変わったファイルは、更新の対象になりません。" +
            "そのインデックスを一から作り直すときは、［削除］してから追加し直してください。"
    }

    $ctrl.RetryCheck.Add_Click({ safe { updateIndexingConfirmTotal } })
    $ctrl.CloudCheck.Add_Click({ safe { updateIndexingConfirmTotal } })
    $ctrl.StartButton.Add_Click({
        safe {
            $d = $script:confirmDialog
            updateIndexingConfirmTotal
            $view = $d.View
            if (testIndexingCloudNeedsConfirm $view.Include $d.SavedCloud) {
                # ダウンロードして取り込む前に、もう一度確かめる。キャンセルなら、この確認に戻る（閉じない）
                $text = getIndexingCloudConfirmView $view.Cloud.Count $view.Cloud.Bytes ${ingestFileTimeoutMinutes}
                $facts = @($text.Facts | ForEach-Object { factWarn $_ })
                $choice = showConfirm -heading $text.Heading -choices $text.Choices -facts $facts -cancelText $text.CancelText -owner $d.Window
                if ($null -eq $choice) {
                    return
                }
            }
            # 開始するときの選び方を、変わったときだけ設定に残す（次から確認を出さずにダウンロードするか）
            $mode = getIndexingCloudModeToSave $view.CloudVisible $view.Include ([bool]$d.Ctrl.CloudRememberCheck.IsChecked) $d.SavedCloud
            if ($null -ne $mode) {
                writeCloudFiles $mode
            }
            $d.Answer = @{ RetryFailed = $view.Retry; IncludeCloud = $view.Include }
            $d.Window.DialogResult = $true
        }
    })
    $null = showOwnedDialog $dialog

    $answer = $script:confirmDialog.Answer
    if ($null -eq $answer -and $nothing) {
        # 取り込むものが無いときは、どう閉じても同じ（インデクサはそのまま終わる）
        $answer = @{ RetryFailed = $false; IncludeCloud = $false }
    }
    $script:confirmDialog = $null
    return $answer
}

function confirmIndexingTargets {
    # インデクサが数え終えて確認を待っている間に、確認のダイアログを1回だけ開いて返事を返す。
    # ダイアログを開いている間も進み具合のタイマーは動くため、開く前に「開いた」ことにしておく
    if ($script:indexingConfirmed) {
        return
    }
    $channel = $script:indexingSession.Channel
    $plan = $channel.Plan
    if ($null -eq $plan) {
        return  # まだ入っていない。次の機会に読む
    }
    $script:indexingConfirmed = $true

    $ui.IndexingProgress.IsIndeterminate = $true
    $ui.IndexingProgressText.Text = "更新する内容を確認してください"
    $ui.IndexingProgressDetail.Text = "更新するインデックスの一覧を表示しています。"
    $answer = showIndexingConfirmDialog $plan
    if ($null -eq $answer) {
        # 取りやめ。インデクサは何も取り込まずに終わる
        $script:indexingCanceledAtConfirm = $true
        $ui.IndexingStopButton.IsEnabled = $false
        $ui.IndexingProgressText.Text = "更新を取りやめています…"
        $ui.IndexingProgressDetail.Text = ""
        answerIndexingPlan $channel $null
        return
    }
    answerIndexingPlan $channel $answer
    # 更新を始めることは新しい操作なので、前の操作の結果の文は消す（取りやめたときは消さない）
    setStatus ""
    $script:indexingRate = $null  # 残り時間の目安は、確認を待っていた時間を含めずに計る
    $ui.IndexingProgressText.Text = "更新を始めています…"
}

function startIndexing {
    # インデックス作成を始める。onlyNames があれば、その名前のインデックスだけの回にする（行の［更新］・メニューの［更新］）。
    # 選んだ行は、設定の enabled を true にして取り込む（確認で取りやめても戻さない）。無ければ今までどおり、enabled の行すべて。
    # ワークスペースがネットワークの場所なら、前の版のインデックスの有無と届くかどうかを裏の列で確かめてから、続きを始める
    # （届かない場所を画面のスレッドで調べると、画面が止まる）。確かめている間は、ほかの操作を止める
    param (
        [string[]]$onlyNames = @()
    )

    if ((isIndexingOrPreparing) -or $script:targetsNaming) {
        return
    }

    # 既定のワークスペースにほかのファイルが置いてあれば、始めずに［設定］で別のフォルダを選んでもらう
    $workspaceBlock = getWorkspaceBlockMessage
    if ($workspaceBlock) {
        showMessage $workspaceBlock "OK" "Warning" | Out-Null
        selectScreen "SettingsTab"
        return
    }

    if ((getWorkspaceJobQueue $workspace.Dir) -ne "network") {
        continueStartIndexing (getLegacyIndexState $workspace.Dir) $onlyNames
        return
    }

    $script:indexingPreparing = $true
    updateIndexingButton
    setStatus (getWorkspaceCheckingStatus)
    $finish = ${function:finishWorkspaceCheck}   # 終わったときの処理は、関数を変数に取って呼ぶ（クロージャからは関数の名前を引けないため）
    startJob {
        param ($dir)
        # 届かない場所は、前の版のインデックスの有無を調べずに知らせる
        if ((getPathState $dir).State -eq ${pathStateUnreachable}) {
            return @{ Unreachable = $true; LegacyState = $null }
        }
        @{ Unreachable = $false; LegacyState = (getLegacyIndexState $dir) }
    } @($workspace.Dir) {
        param ($output, $errorText)
        & $finish $output $errorText $onlyNames
    }.GetNewClosure() (getWorkspaceJobQueue $workspace.Dir)
}

function finishWorkspaceCheck {
    # ネットワークのワークスペースの確かめが終わったときの処理。届いて調べられたら、インデックス作成の続きを始める
    param (
        $output,
        [string]$errorText,
        [string[]]$onlyNames
    )

    $script:indexingPreparing = $false
    updateIndexingButton
    $result = @($output)[0]
    if ($errorText -or $null -eq $result -or $result.Unreachable) {
        setStatus (getWorkspaceUnreachableStatus ([string]$workspace.Dir))
        return
    }
    # 確かめ中の文を消す（以後の確認を断っても、続きを始めても、残さない）
    setStatus ""
    continueStartIndexing $result.LegacyState $onlyNames
}

function continueStartIndexing {
    # startIndexing の続き。前の版のインデックスがあれば確かめ、インデクサを始める
    param (
        $legacyState,        # getLegacyIndexState の結果
        [string[]]$onlyNames
    )

    # 前の版のインデックス（index\）があり、まだ取り込み直していなければ、始める前に確かめる
    $reingestConfirm = getReingestConfirm $legacyState.HasLegacyIndex $legacyState.ContentEmpty
    if ($reingestConfirm) {
        $answer = showConfirm -heading $reingestConfirm -choices @(@{ Text = "更新し直す"; Value = "start" })
        if ($answer -ne "start") {
            return
        }
    }

    $script:indexingOnlyNames = @($onlyNames | Where-Object { $_ })
    foreach ($item in $script:targetItems) {
        if ($script:indexingOnlyNames -contains $item.Name) {
            $item.SetEnabled($true)
        }
    }
    saveTargets -Quiet   # 文は出さない（確認で取りやめたとき、前の操作の結果の代わりに残らないように）
    updateIndexDetailPanel
    # 何件取り込むかは、元のファイルの更新日時とサイズを見ないと分からない。
    # ConfirmTargets にすると、インデクサは数え終えたところで止まって確認の返事（answerIndexingPlan）を待つ。
    # インデクサは画面のプロセスのスレッドで動く（docs/design/structure/threads.md「プロセス」）
    $script:indexingStart = Get-Date
    $script:indexingRate = $null
    $script:indexingEta = ""
    $script:indexingConfirmed = $false
    $script:indexingCanceledAtConfirm = $false
    # 空なら今までどおり（状態層は enabled かつ onlyNames に入るものだけを取り込む）
    $channel = newIndexerChannel -confirmTargets $true -onlyNames $script:indexingOnlyNames
    $script:indexingSession = newIndexingSession $channel

    showIndexingPanel
    updateIndexingButton
    $script:indexingTimer.Start()
}

function stopIndexing {
    if (!(isIndexing)) {
        return
    }
    $answer = showConfirm `
        -title "更新の中止" `
        -heading "インデックスの更新を中止しますか？" `
        -hint "更新したところまでは残ります。あとで続きから再開できます。" `
        -choices @(@{ Text = "中止する"; Value = "stop"; Careful = $true })
    if ($answer -ne "stop") {
        return
    }
    requestIndexingStop $script:indexingSession.Channel
    $ui.IndexingStopButton.IsEnabled = $false
    $ui.IndexingProgressDetail.Text = "中止しています…（読み取り中のファイルが終わるまでお待ちください）"
    showIndexingWait "Stopping"
}

# 中止を待つ間のダイアログ（shared\ui\shell.ps1 の showWaitDialog）。Stopping（［中止］のあと）と CloseWait（閉じるときの待ち）の 1 つだけを出す
$script:indexingWait = $null
$script:indexingWaitKind = ""

function showIndexingWait {
    param (
        [string]$kind
    )

    if ($null -ne $script:indexingWait -and $script:indexingWaitKind -eq $kind) {
        return
    }
    closeIndexingWait
    $view = getWaitDialogView $kind
    $script:indexingWait = showWaitDialog -heading $view.Heading -description $view.Description -buttonText $view.ButtonText
    $script:indexingWaitKind = $kind
}

function updateIndexingWait {
    # 進み具合の棒を書き換える。secondsLeft（強制終了までの残りの秒）を渡したときは、秒読みの 1 行も書き換える
    param (
        $progress,
        [object]$secondsLeft = $null
    )

    if ($null -eq $script:indexingWait) {
        return
    }
    $content = @{}
    if ($null -ne $progress) {
        $bar = getWaitProgressValue $progress.Processed ($progress.Processed + $progress.Remaining)
        $content.Indeterminate = $bar.Indeterminate
        $content.Value = $bar.Value
    }
    if ($null -ne $secondsLeft) {
        $content.Countdown = getForceCloseCountdownText ([double]$secondsLeft)
    }
    updateWaitDialog $script:indexingWait $content
}

function closeIndexingWait {
    $handle = $script:indexingWait
    $script:indexingWait = $null
    $script:indexingWaitKind = ""
    closeWaitDialog $handle
}

function updateIndexingProgress {
    if (!(isIndexing)) {
        finishIndexing
        return
    }

    try {
        $progress = getIndexingProgress
    } catch {
        return
    }
    $stopping = !$ui.IndexingStopButton.IsEnabled

    $total = $progress.Processed + $progress.Remaining
    updateIndexingWait $progress
    if (!$progress.Scanned) {
        # クロールしている間（大きいフォルダ・ネットワーク越しでは数分かかることがある）。
        # 何を見ているかが分かるよう、インデクサが書いた内容をそのまま出す
        $ui.IndexingProgress.IsIndeterminate = $true
        $ui.IndexingProgressText.Text = "更新するファイルを調べています…"
        if (!$stopping) {
            $ui.IndexingProgressDetail.Text = [string]$progress.Detail
        }
        $taskbar.ProgressState = "Indeterminate"
        return
    }
    if ($progress.Confirming) {
        # 数え終えて、画面で取り込むかどうかを選ぶのを待っている（インデクサは返事があるまで止まっている）。
        # 表示は confirmIndexingTargets がダイアログを開く直前に 1 回だけ変える（取りやめの表示を上書きしないため）
        $taskbar.ProgressState = "Paused"
        confirmIndexingTargets
        return
    }
    if ($progress.Finishing) {
        # 後片付け（Officeアプリの終了・取り込み一覧の書き直し）。止まって見えないよう、何をしているかを出す
        $ui.IndexingProgress.IsIndeterminate = $true
        $ui.IndexingProgressText.Text = "更新を終えています…"
        $ui.IndexingProgressDetail.Text = [string]$progress.Detail
        $taskbar.ProgressState = "Indeterminate"
        return
    }
    if ($progress.Processed -eq 0) {
        $ui.IndexingProgress.IsIndeterminate = $true
        $ui.IndexingProgressText.Text = if ($progress.Remaining -gt 0) { "$($progress.Remaining) 件のファイルを更新します" } else { "更新が必要なファイルを確認しています…" }
        if (!$stopping) {
            $ui.IndexingProgressDetail.Text = if ($progress.Current) { "読み取り中のファイル：$($progress.Current)" } else { "" }
        }
        $taskbar.ProgressState = "Indeterminate"
        return
    }

    $ratio = if ($total -gt 0) { $progress.Processed / $total } else { 1 }
    $ui.IndexingProgress.IsIndeterminate = $false
    $ui.IndexingProgress.Value = $ratio
    $taskbar.ProgressState = if ($progress.Failed -gt 0) { "Paused" } else { "Normal" }
    $taskbar.ProgressValue = $ratio
    updateIndexTabBadge
    updateIndexRowsProgress

    $text = "インデックスを更新しています（$($progress.Processed.ToString('N0')) / $($total.ToString('N0')) 件"
    if ($progress.Failed -gt 0) {
        $text += "・失敗 $($progress.Failed) 件"
    }
    $ui.IndexingProgressText.Text = $text + "）"

    # 残り時間の目安（最初の1件が終わってからの速さで計算する）
    $now = Get-Date
    if ($null -eq $script:indexingRate) {
        $script:indexingRate = @{ Time = $now; Processed = $progress.Processed }
    }
    $done = $progress.Processed - $script:indexingRate.Processed
    if ($progress.Remaining -eq 0) {
        $script:indexingEta = ""
    } elseif ($done -gt 0) {
        $seconds = ($now - $script:indexingRate.Time).TotalSeconds / $done * $progress.Remaining
        $script:indexingEta = if ($seconds -lt 60) { "残り 1 分未満" } else { "残り約 $([math]::Ceiling($seconds / 60)) 分" }
    }
    $ui.IndexingProgressEta.Text = $script:indexingEta
    if (!$stopping) {
        $ui.IndexingProgressDetail.Text = if ($progress.Current) { "読み取り中のファイル：$($progress.Current)" } else { "" }
    }
    # 更新中の名前・件数・残り時間は、ここに値で 1 か所だけ持つ（帯・詳細の「インデックス」の箱・ステータスバーが読む）。
    # Name は取り込み中のファイル（<名前>\<相対パス>）のインデックス名。件数は回全体（インデックスごとの件数は無い）
    $script:indexingView = @{
        Name = (getIndexingCurrentName ([string]$progress.Current))
        Ratio = $ratio; Processed = $progress.Processed; Total = $total; Failed = $progress.Failed
        Eta = [string]$script:indexingEta; Current = [string]$progress.Current
    }
    updateIndexDetailPanel
}

function finishIndexing {
    $script:indexingTimer.Stop()
    closeIndexingWait
    $script:indexingView = $null
    $taskbar.ProgressState = "None"
    # インデックス作成完了の通知。以前はタスクバーのボタンを光らせていたが（FlashWindowEx）、P/Invoke は
    # 実行時コンパイル（csc.exe）を無くすため廃止した。完了は帯で分かる。
    $session = $script:indexingSession
    $progress = $null
    try {
        $progress = getIndexingProgress
    } catch {
    }
    $exitCode = $session.GetExitCode()
    $errorText = $session.GetError()
    $onlySkipped = @($session.Channel.OnlySkipped)
    # インデクサのスレッドを片づける（終わっているため待たない）
    $session.Close()
    $script:indexingSession = $null
    $script:indexingOnlyNames = @()
    $script:indexingEta = ""

    $counts = ""
    if ($progress -and $progress.Processed -gt 0) {
        $counts = "成功 $($progress.Processed - $progress.Failed) 件 / 失敗 $($progress.Failed) 件"
        if ($progress.Remaining -gt 0) {
            $counts += " / 残り $($progress.Remaining) 件"
        }
        $ui.IndexingProgress.IsIndeterminate = $false
        $ui.IndexingProgress.Value = $progress.Processed / ($progress.Processed + $progress.Remaining)
    } else {
        $ui.IndexingProgress.IsIndeterminate = $false
        $ui.IndexingProgress.Value = 0
    }

    if ($exitCode -eq 1) {
        # インデックス作成を続けられないエラー（クロール対象フォルダが無い など）
        $message = $errorText.Trim()
        if ($message -eq "") {
            $message = "詳しくはログを確認してください。"
        }
        setIndexingBanner (getIndexingBannerLevel $exitCode 0) "done"
        $ui.IndexingProgressText.Text = "インデックスを更新できませんでした"
        $ui.IndexingProgressDetail.Text = $message
        showMessage "インデックスを更新できませんでした。`n`n$message" "OK" "Error" | Out-Null
    } elseif ($exitCode -eq 2 -and $script:indexingCanceledAtConfirm) {
        # 確認のダイアログで取りやめた（1件も取り込んでいない）
        setIndexingBanner "warn" "done"
        $ui.IndexingProgressText.Text = "更新を取りやめました"
        $ui.IndexingProgressDetail.Text = "更新したファイルはありません。［すべて更新］を押すと、もう一度確認できます。"
    } elseif ($exitCode -eq 2) {
        setIndexingBanner "warn" "done"
        $ui.IndexingProgressText.Text = if ($counts) { "更新を中止しました（$counts）" } else { "更新を中止しました" }
        $ui.IndexingProgressDetail.Text = "次回は続きから再開できます。"
    } else {
        # 完了（後回し・失敗の件数に応じた見出しと説明は判断層（indexing_view.ps1）が決める）
        $success = if ($progress) { $progress.Processed - $progress.Failed } else { 0 }
        $failed = if ($progress) { $progress.Failed } else { 0 }
        setIndexingBanner (getIndexingBannerLevel $exitCode $failed) "done"
        $endText = getIndexingEndText $success $failed $session.GetCloudSkipped()
        $ui.IndexingProgressText.Text = $endText.Text
        $ui.IndexingProgressDetail.Text = $endText.Detail
    }
    $ui.IndexingProgressEta.Text = ""
    $ui.IndexingStopButton.Visibility = "Collapsed"
    $ui.IndexingProgress.Visibility = "Collapsed"
    # 更新中の帯を閉じていても、終わりの知らせは出す
    $ui.IndexingProgressPanel.Visibility = "Visible"
    $skippedView = getIndexingSkippedView $onlySkipped
    if ($skippedView -and $exitCode -ne 1) {
        # メッセージを読んでいる間に成功の帯が消えないよう、時計を止め、閉じたあとから数え直す
        $script:indexingBannerTimer.Stop()
        showMessage "$($skippedView.Heading)`n`n$($skippedView.Detail)" "OK" "Warning" | Out-Null
        setIndexingBannerBehavior
    }
    $ui.IndexingSearchButton.Visibility = if ($exitCode -ne 1) { "Visible" } else { "Collapsed" }

    $script:sourceFolderMaps = @{}
    # 高速検索の列の前の確かめ結果（古い reason）を捨てて「確認中…」に戻す。ここで捨てずに
    # refreshIndexingState を呼ぶと、その集計（本文の取り込みは済んだと分かる）が
    # refreshFastSearchStatus の確かめ直しより先に終わったとき、古い reason のまま
    # updateFastSearchRows が呼ばれ、「不可」が一瞬出てしまう（isIndexing は既に偽になっており、
    # getFastSearchRowView の indexing 引数による作成中ガードが効かないため）。
    # fastSearchResultDir を null にするだけで、updateFastSearchRows 側の「今のワークスペースの結果
    # でなければ捨てる」ガード（index\index_list.ps1・index_detail.ps1）が reason・progress・checkedAt を確認中…に戻してくれる。
    # 世代番号も進め、作成前から走っていた確かめジョブが後から古い結果を届けても捨てて確かめ直すようにする
    $script:fastSearchGeneration++
    $script:fastSearchResultDir = $null
    refreshIndexingState
    refreshIndexSummary
    loadIndexTree  # 新しいインデックス・フォルダをツリーに出す
    refreshFastSearchStatus  # インデックス作成が終わったので、一覧の「高速検索」列を確かめ直す
}

$script:indexingTimer = newTimer 1000 { safe { updateIndexingProgress } }

$ui.FailedGrid.Add_MouseDoubleClick({
    param ($sender, $e)
    # 行の上でのダブルクリックだけを対象にする（列見出し・スクロールバーは除く）
    $element = $e.OriginalSource
    while ($element -and !($element -is [System.Windows.Controls.DataGridRow])) {
        if ($element -is [System.Windows.Controls.Primitives.DataGridColumnHeader] -or $element -is [System.Windows.Controls.Primitives.ScrollBar]) {
            return
        }
        $element = [System.Windows.Media.VisualTreeHelper]::GetParent($element)
    }
    if ($element) {
        safe { openFailedFileFolder }
    }
})
$ui.IndexingButton.Add_Click({ safe { startIndexing } })
$ui.IndexingStopButton.Add_Click({ safe { stopIndexing } })
$ui.IndexingResumeButton.Add_Click({ safe { startIndexing } })
$ui.IndexingSearchButton.Add_Click({ safe { selectScreen "SearchTab" } })

# ［検索］タブの結果の表の中身（ファイルごとの見出しと、開いているファイルの行）。
# 検索のヒットは生のまま、元のファイルの見出し（FileGroup）の Hits に持つ。表の行（HitRow）は、開いたとき・絞り込み・
# 並べ替え・出力・コピーのときに、必要なファイルの分だけ作る（ensureRows）。表（ResultGrid）には見出しと、開いているファイルの行だけを入れる。
# 検索した直後はすべて閉じているので、検索中の処理はヒットをファイルごとに分けるだけで済み、ヒットが多くても速い。
# 並べる項目・絞り込み・並べ替えの判断は search\result_list_view.ps1（getResultItems・selectShownRows・sortFileGroups）。

$script:hitCount = 0             # すべてのヒットの数
$script:fileGroups = New-Object 'System.Collections.Generic.Dictionary[string,object]' ([System.StringComparer]::OrdinalIgnoreCase)  # 元のファイルのフルパス → FileGroup
$script:groupList = New-Object 'System.Collections.Generic.List[object]'    # FileGroup（表の順）
$script:dirtyGroups = New-Object 'System.Collections.Generic.HashSet[object]'  # 検索中にヒットが増えた FileGroup（flushResults で表に反映する）
$script:resultItems = New-Object 'System.Collections.ObjectModel.ObservableCollection[object]'
$script:places = @{}             # 場所の表示（describePlace）を、種類（Excel か）と場所ごとに覚えておく
$script:rowWord = ""             # 表の行の強調に使う検索ワードと正規表現（startSearch が setRowPattern で決める）
$script:rowPattern = $null
$script:expandNew = $false       # 検索中に新しく見つかったファイルを開いておくか（［すべて開く］を押したら $true）
$script:needsRebuild = $false    # 検索中に、表の途中に見出しを差し込む必要ができた（検索の終わりに作り直す）
$script:lastInViewOrder = -1     # 表に出ている見出しのうち、いちばん後に見つかったものの Order（新しい見出しを末尾に足せるかの判定）
$ui.ResultGrid.ItemsSource = $script:resultItems

# 見出しの下の行をこの数より多く出し入れするときは、1 件ずつ入れずに表を作り直す（1 件ずつだと画面の更新が重い）
${rebuildThreshold} = 200

function clearResults {
    # 新しく検索する前に、結果を空にする
    param (
        [string]$word,
        [regex]$pattern
    )

    $script:hitCount = 0
    $script:fileGroups.Clear()
    $script:groupList.Clear()
    $script:dirtyGroups.Clear()
    $script:places = @{}
    $script:rowWord = $word
    $script:rowPattern = $pattern
    $script:expandNew = $false
    $script:needsRebuild = $false
    foreach ($column in $ui.ResultGrid.Columns) {
        $column.SortDirection = $null
    }
    setResultItems (New-Object 'System.Collections.Generic.List[object]')
}

function newFileGroup {
    # 元のファイルの見出し（FileGroup）を作って覚える（key は元のファイルのフルパス）
    param (
        [string]$key,
        [string]$relDir,
        [string]$book
    )

    $group = [FileGroup]::new()
    $group.Order = $script:groupList.Count
    $group.Book = $book
    $group.RelDir = $relDir
    $group.FullPath = $key
    $group.AppKind = getAppKind $book
    $group.IsExpanded = $script:expandNew
    $script:fileGroups[$key] = $group
    $script:groupList.Add($group)
    return $group
}

function getPlace {
    # 場所の表示（describePlace の @{ Place; Kind }）。同じ種類のファイル・場所なら同じなので覚えておく
    param (
        [string]$book,
        [string]$location
    )

    $key = "$([int]($book -match '\.xls[a-z]?$'))|$location"
    $described = $script:places[$key]
    if ($null -eq $described) {
        $described = describePlace $book $location
        $script:places[$key] = $described
    }
    return $described
}

function addFileGroupLocation {
    # 見出しに、そのファイルで初めてヒットした場所（表の「場所」と同じ表記。describePlace）を足し、右端の表記を作り直す
    param (
        [FileGroup]$group,
        [string]$book,
        [string]$location
    )

    if ($group.AddLabel((getPlace $book $location).Place)) {
        $group.SetLocationText((describeFileLocations $group.GetLocations()), (getFileHeaderLocationPrefix $group.GetLocations()))
    }
}

function ensureRows {
    # ファイルのヒットのうち、まだ表の行（HitRow）にしていないものを行にする（絞り込みに合うものは ShownRows にも入れる）
    param (
        [FileGroup]$group
    )

    for ($i = $group.Rows.Count; $i -lt $group.Hits.Count; $i++) {
        $hit = $group.Hits[$i]
        # インデックスのフォルダ（work\index）からの相対パスの先頭がインデックス名（splitIndexRelPath と同じ）
        $relDir = [string]$hit.RelDir
        $cut = $relDir.IndexOf("\")
        $indexName = if ($cut -lt 0) { $relDir } else { $relDir.Substring(0, $cut) }
        $row = [HitRow]::Create($indexName, $hit.Root, $hit.RelPath, $relDir, $hit.FileName,
                $hit.Book, $hit.Location, [int]$hit.LineNumber, $hit.Line, $script:rowWord, $script:rowPattern)
        $described = getPlace $hit.Book $hit.Location
        $row.PlaceText = $described.Place
        $row.Kind = $described.Kind
        $row.IsText = testTextExtension $hit.Book
        $row.Order = $i
        $row.FileGroup = $group
        $group.Rows.Add($row)
        if ($script:filterText -eq "" -or $row.Contains($script:filterText)) {
            $group.ShownRows.Add($row)
        }
    }
}

function ensureAllRows {
    # すべてのファイルのヒットを表の行にする（絞り込み・並べ替え・出力の前）
    foreach ($group in $script:groupList) {
        ensureRows $group
    }
}

function updateGroupCount {
    # 見出しの件数。絞り込んでいなければヒットの数（行を作っていなくても分かる）、絞り込み中は合う行の数
    param (
        [FileGroup]$group
    )

    if ($script:filterText -eq "") {
        $group.SetCount($group.Hits.Count)
    } else {
        $group.SetCount($group.ShownRows.Count)
    }
}

function flushResults {
    param (
        [switch]$SkipPaneHeight
    )

    # 検索中に増えたヒットを表に反映する（pumpSearch が 1 回ごとに呼ぶ）。増えたヒットが無い回は何もしない。
    #   SkipPaneHeight: 表とプレビューの境目を決め直さない（呼んだ側が、あとで 1 回決め直すとき）
    # 新しいファイルは見出しを末尾に足し、開いているファイルは行を作って見出しの下に足す
    if ($script:dirtyGroups.Count -eq 0) {
        return
    }
    foreach ($group in $script:dirtyGroups) {
        if ($script:filterText -ne "" -or $group.IsExpanded) {
            ensureRows $group
        }
        updateGroupCount $group
        if ($group.ShownCount -eq 0) {
            continue
        }
        if (!$group.InView) {
            if ($group.Order -lt $script:lastInViewOrder) {
                # 絞り込みで隠れていたファイルに、あとから合う行が来た。末尾に足すと順が崩れるため、検索の終わりに作り直す
                $script:needsRebuild = $true
                continue
            }
            $script:resultItems.Add($group)
            $group.InView = $true
            $group.DisplayedCount = 0
            $script:lastInViewOrder = $group.Order
        }
        if ($group.IsExpanded -and $group.DisplayedCount -lt $group.ShownRows.Count) {
            insertGroupRows $group
        }
    }
    $script:dirtyGroups.Clear()
    if (!$SkipPaneHeight) {
        updateResultPaneHeight $script:resultItems.Count
    }
}

function insertGroupRows {
    # 開いているファイルの、まだ表に入れていない行を、見出しの下（入れ済みの行の後ろ）に入れる
    param (
        [FileGroup]$group
    )

    $index = $script:resultItems.IndexOf($group) + 1 + $group.DisplayedCount
    for ($i = $group.DisplayedCount; $i -lt $group.ShownRows.Count; $i++) {
        $script:resultItems.Insert($index, $group.ShownRows[$i])
        $index++
    }
    $group.DisplayedCount = $group.ShownRows.Count
}

function setResultItems {
    # 表の中身を items で置き換える（1 件ずつ入れずに、まとめて 1 回で入れ替える）。選んでいた項目が残っていれば選び直す
    param (
        $items
    )

    $selected = $ui.ResultGrid.SelectedItem
    foreach ($group in $script:groupList) {
        $group.InView = $false
        $group.DisplayedCount = 0
    }
    $script:lastInViewOrder = -1
    foreach ($item in $items) {
        if ($item -is [FileGroup]) {
            $item.InView = $true
            if ($item.IsExpanded) {
                $item.DisplayedCount = $item.ShownRows.Count
            }
            $script:lastInViewOrder = [Math]::Max($script:lastInViewOrder, $item.Order)
        }
    }
    $script:resultItems = New-Object 'System.Collections.ObjectModel.ObservableCollection[object]' (, [System.Collections.Generic.List[object]]$items)
    $ui.ResultGrid.ItemsSource = $script:resultItems
    if ($null -ne $selected -and $script:resultItems.Contains($selected)) {
        $ui.ResultGrid.SelectedItem = $selected
        $ui.ResultGrid.ScrollIntoView($selected)
    }
}

function rebuildResults {
    # 見出しの開閉・絞り込み・並べ替えのあとに、表の中身を作り直す（開いているファイルの行は、ここで作る）
    $script:needsRebuild = $false
    foreach ($group in $script:groupList) {
        if ($group.IsExpanded) {
            ensureRows $group
        }
    }
    setResultItems (getResultItems $script:groupList)
    updateResultPaneHeight $script:resultItems.Count
}

function toggleFileGroup {
    # 見出しの下の行を閉じる・開く（開くときに、そのファイルの行を作る）
    param (
        [FileGroup]$group
    )

    if ($group.IsExpanded) {
        $group.SetExpanded($false)
        if ($group.DisplayedCount -gt ${rebuildThreshold}) {
            rebuildResults
            return
        }
        $index = $script:resultItems.IndexOf($group) + 1
        for ($i = 0; $i -lt $group.DisplayedCount; $i++) {
            $script:resultItems.RemoveAt($index)
        }
        $group.DisplayedCount = 0
        updateResultPaneHeight $script:resultItems.Count
    } else {
        $group.SetExpanded($true)
        ensureRows $group
        if ($group.ShownRows.Count -gt ${rebuildThreshold}) {
            rebuildResults
            return
        }
        insertGroupRows $group
        updateResultPaneHeight $script:resultItems.Count
    }
}

function setAllFileGroupsExpanded {
    # ［すべて開く］［すべて折りたたむ］。検索中なら、このあと見つかるファイルも同じにする
    param (
        [bool]$expanded
    )

    $script:expandNew = $expanded
    foreach ($group in $script:groupList) {
        $group.SetExpanded($expanded)
    }
    rebuildResults
}

function applyResultFilter {
    # 絞り込み（空なら解除）を当てて表を作り直す。絞り込むときは、合う行を数えるためにすべての行を作る
    param (
        [string]$filterText
    )

    if ($filterText -ne "") {
        ensureAllRows
    }
    foreach ($group in $script:groupList) {
        $group.ShownRows = selectShownRows $group.Rows $filterText
        updateGroupCount $group
    }
    rebuildResults
}

function sortResults {
    # 列見出しのクリックでの並べ替え（もう一度で逆順）。ファイルの中の行を並べ替え、ファイルの順もそれに合わせる
    param (
        [System.Windows.Controls.DataGridColumn]$column
    )

    $property = $column.SortMemberPath
    if (!$property) {
        return
    }
    $descending = $column.SortDirection -eq [System.ComponentModel.ListSortDirection]::Ascending
    foreach ($other in $ui.ResultGrid.Columns) {
        $other.SortDirection = $null
    }
    $column.SortDirection = if ($descending) { [System.ComponentModel.ListSortDirection]::Descending } else { [System.ComponentModel.ListSortDirection]::Ascending }
    applySort $property $descending
}

function applySort {
    # ファイルの中の行とファイルの順を並べ替え、絞り込みを当て直して表を作り直す（並べ替えには、すべての行を作る）
    param (
        [string]$property,
        [bool]$descending
    )

    ensureAllRows
    $sorted = sortFileGroups $script:groupList $property $descending
    $script:groupList.Clear()
    $script:groupList.AddRange($sorted)
    foreach ($group in $script:groupList) {
        $group.ShownRows = selectShownRows $group.Rows $script:filterText
    }
    rebuildResults
}

function finishResults {
    # 検索の終わりに、表の順を整える。検索中に並べ替えていたら、あとから来た行も含めて並べ直す。
    # 絞り込みで隠れていたファイルに、あとから合う行が来ていたら作り直す
    flushResults -SkipPaneHeight
    $column = $ui.ResultGrid.Columns | Where-Object { $null -ne $_.SortDirection } | Select-Object -First 1
    if ($column) {
        applySort $column.SortMemberPath ($column.SortDirection -eq [System.ComponentModel.ListSortDirection]::Descending)
    } elseif ($script:needsRebuild) {
        rebuildResults
    } else {
        updateResultPaneHeight $script:resultItems.Count
    }
}

function getCurrentHitRow {
    # 選んでいる行。見出しを選んでいるときは、そのファイルの先頭の行（プレビュー・元のファイルを開く・パスのコピーに使う）
    $item = $ui.ResultGrid.SelectedItem
    if ($item -is [FileGroup]) {
        ensureRows $item
        if ($item.ShownRows.Count -gt 0) {
            return $item.ShownRows[0]
        }
        return $null
    }
    return $item
}

function getViewRows {
    # 表示中（絞り込み・並べ替え後）の行。閉じているファイルの行も含む（結果をファイルに出力するときに使う）
    ensureAllRows
    return , (getShownHitRows $script:groupList).ToArray()
}

function getSelectedRows {
    # 選んでいる行を表の順に返す。見出しを選んでいるときは、そのファイルの行（絞り込みに合うもの）をすべて含める
    $selected = New-Object 'System.Collections.Generic.HashSet[object]'
    foreach ($item in $ui.ResultGrid.SelectedItems) {
        [void]$selected.Add($item)
    }
    $rows = New-Object 'System.Collections.Generic.List[object]'
    foreach ($group in $script:groupList) {
        $whole = $selected.Contains($group)
        if ($whole) {
            ensureRows $group
        }
        foreach ($row in $group.ShownRows) {
            if ($whole -or $selected.Contains($row)) {
                $rows.Add($row)
            }
        }
    }
    return , $rows.ToArray()
}

function getShownHitCount {
    # 絞り込みに合う行の数
    $count = 0
    foreach ($group in $script:groupList) {
        $count += $group.ShownCount
    }
    return $count
}
# ---- イベント ----

# 表示用（強調セグメント・DisplayLine・セル番地・「場所」の列の表記）は、行が画面に出るときだけ作る（件数が多くても軽い）。
# HitRow.Prepare は1回だけ実行し、作った値は PropertyChanged で反映する
$ui.ResultGrid.Add_LoadingRow({
    param ($s, $e)
    if ($e.Row.Item -is [HitRow]) { prepareHitRow $e.Row.Item }
})

# 並べ替えは表（DataGrid）に任せず、ファイルごとに行う（任せると見出しと行が混ざって並ぶ）
$ui.ResultGrid.Add_Sorting({
    param ($sender, $e)
    $e.Handled = $true
    safe { sortResults $e.Column }
})

# 見出しの行をクリックすると閉じる・開く（Shift・Ctrl を押しながらのクリックは、複数を選ぶための操作なので切り替えない）。
# MouseLeftButtonUp は押された要素にしか届かない（外側の DataGrid では受け取れない）ため、外側から順に届く
# PreviewMouseUp で受ける。行を選ぶ処理が済んでから表の中身を入れ替えるよう、開閉は画面の処理のあとに行う
$ui.ResultGrid.AddHandler([System.Windows.UIElement]::PreviewMouseUpEvent, [System.Windows.Input.MouseButtonEventHandler] {
    param ($sender, $e)
    # 修飾キーは列挙型の値で比べる（文字列 "None" と比べると、押していなくても真になる）
    if ($e.ChangedButton -ne [System.Windows.Input.MouseButton]::Left -or
            [System.Windows.Input.Keyboard]::Modifiers -ne [System.Windows.Input.ModifierKeys]::None) {
        return
    }
    $element = $e.OriginalSource
    while ($element -and !($element -is [System.Windows.Controls.DataGridRow])) {
        $element = [System.Windows.Media.VisualTreeHelper]::GetParent($element)
    }
    if ($element -and $element.Item -is [FileGroup]) {
        $script:clickedGroup = $element.Item
        [void]$ui.ResultGrid.Dispatcher.BeginInvoke([System.Windows.Threading.DispatcherPriority]::Input, [Action]{
            safe { toggleFileGroup $script:clickedGroup }
        })
    }
}, $true)

$ui.ExpandAllButton.Add_Click({ safe { setAllFileGroupsExpanded $true } })
$ui.CollapseAllButton.Add_Click({ safe { setAllFileGroupsExpanded $false } })

# 検索バー（検索ワード・種類のチップ・ファイル内の対象・検索条件・検索ボタン・高速検索の状態）の画面層。
# 文言と可否の判断は search_bar_view.ps1（テストあり）。検索の実行は search_session.ps1。

# 種類のチップ（${fileKindNames} の値 → ToggleButton）
$script:kindChips = [ordered]@{
    excel = $ui.KindChipExcel; word = $ui.KindChipWord; powerpoint = $ui.KindChipPowerPoint; text = $ui.KindChipText; pdf = $ui.KindChipPdf
}

# 検索ワード（前後の空白を除く）
function getWordText {
    return $ui.WordBox.Text.Trim()
}

function getFileKindsFromUi {
    # チップで選ばれている種類（${fileKindNames} の順）
    return @(${fileKindNames} | Where-Object { $script:kindChips[$_].IsChecked })
}

function setFileKindsToUi {
    param (
        [object[]]$kinds
    )

    foreach ($kind in ${fileKindNames}) {
        $script:kindChips[$kind].IsChecked = (@($kinds) -contains $kind)
    }
}

function getSearchOptionFromUi {
    # 画面の検索条件を readSearchOption と同じ形（と、選んだ種類 FileKinds）で返す
    return @{
        UseRegex        = [bool]$ui.RegexCheck.IsChecked
        CaseSensitive   = [bool]$ui.CaseCheck.IsChecked
        FileKinds       = @(getFileKindsFromUi)
        IncludeShapes   = [bool]$ui.ShapeCheck.IsChecked
        IncludeComments = [bool]$ui.CommentCheck.IsChecked
    }
}

function setSearchOptionToUi {
    param (
        [hashtable]$option
    )

    $ui.RegexCheck.IsChecked = [bool]$option.UseRegex
    $ui.CaseCheck.IsChecked = [bool]$option.CaseSensitive
    $ui.ShapeCheck.IsChecked = [bool]$option.IncludeShapes
    $ui.CommentCheck.IsChecked = [bool]$option.IncludeComments
    updateScopeButton
    setFileKindsToUi (readFileKinds)
}

function updateFastSearchView {
    # 高速検索の使用可否（ワード・［正規表現］を変えたらすぐ、Windows Search が使えるかは確かめたときに変わる）。
    # 使えるときは緑、使えないときは灰色。情報の印（info）は常に出し、ツールチップで印の意味（使えないときは理由と直し方）を知らせる。
    # 印の幅は XAML で固定してあり、ここでは変えない
    $view = getFastSearchView $script:fastAvailable ([bool]$ui.RegexCheck.IsChecked) (getWordText)
    $ui.FastSearchText.Text = $view.Text
    $ui.FastBadge.Tag = if ($view.Usable) { "ok" } else { "off" }
    $ui.FastBadge.ToolTip = $view.Tip
    $script:fastGoToIndex = [bool]$view.GoToIndex
    $ui.FastBadge.Cursor = if ($script:fastGoToIndex) { [System.Windows.Input.Cursors]::Hand } else { [System.Windows.Input.Cursors]::Arrow }
}

function placeSearchBalloon {
    # 吹き出しを、基準の項目の下（5 下）に、左端をそろえて置く。右端がはみ出すときは左へ寄せる（判断は getBalloonLeft）。
    # 吹き出しは高さ 0 の BalloonLayer（Canvas）に置いてあり、検索バーの高さは変わらない
    param (
        $balloon,
        $anchor
    )

    if ($balloon.Visibility -ne "Visible") { return }
    $layer = $ui.BalloonLayer
    try {
        $ui.ConditionsPanel.UpdateLayout()
        $balloon.Measure([System.Windows.Size]::new([double]::PositiveInfinity, [double]::PositiveInfinity))
        $origin = $anchor.TransformToVisual($layer).Transform([System.Windows.Point]::new(0, 0))
    } catch {
        return
    }
    $left = getBalloonLeft $origin.X $balloon.DesiredSize.Width $layer.ActualWidth
    [System.Windows.Controls.Canvas]::SetLeft($balloon, $left)
    [System.Windows.Controls.Canvas]::SetTop($balloon, $origin.Y + $anchor.ActualHeight + 5)
}

function placeSearchBalloons {
    placeSearchBalloon $ui.SearchKindBalloon $ui.KindChipExcel
    placeSearchBalloon $ui.RegexBalloon $ui.RegexCheck
}

function setSearchBalloon {
    # 吹き出しを出す（text が空なら隠す）。新しく出したとき、画面の読み上げに知らせる
    param (
        $balloon,
        $textBlock,
        [string]$text
    )

    if (!$text) {
        $balloon.Visibility = "Collapsed"
        return
    }
    $wasVisible = ($balloon.Visibility -eq "Visible") -and ($textBlock.Text -eq $text)
    # 画面の読み上げに、出たときに読み上げるよう頼む（.NET 4.7.1 以降。無い環境では何もしない）
    try { [System.Windows.Automation.AutomationProperties]::SetLiveSetting($textBlock, [System.Windows.Automation.AutomationLiveSetting]::Assertive) } catch { }
    $textBlock.Text = $text
    $balloon.Visibility = "Visible"
    placeSearchBalloons
    if (!$wasVisible) {
        try {
            $peer = [System.Windows.Automation.Peers.UIElementAutomationPeer]::CreatePeerForElement($textBlock)
            if ($peer) { $peer.RaiseAutomationEvent([System.Windows.Automation.Peers.AutomationEvents]::LiveRegionChanged) }
        } catch { }
    }
}

function setSearchKindBalloon {
    # 種類が 1 つも選ばれていないことを知らせる吹き出し（getSearchKindBalloonText の結果。$null なら隠す）
    param (
        [string]$text
    )

    setSearchBalloon $ui.SearchKindBalloon $ui.SearchKindBalloonText $text
}

function updateScopeButton {
    # ［ファイル内の対象］の文言と、既定から変えているときの線の色
    $view = getScopeButtonText ([bool]$ui.ShapeCheck.IsChecked) ([bool]$ui.CommentCheck.IsChecked)
    $ui.ScopeButton.Content = $view.Text
    $ui.ScopeButton.Tag = if ($view.Changed) { "changed" } else { $null }
}

function checkFastSearchAvailable {
    # Windows Search が使えるか（system_index が索引の対象か）を別スレッドで確かめる（画面を固めないように）
    startJob {
        param ($systemRoot)
        @{ Root = $systemRoot; Available = (testWindowsSearch $systemRoot) }
    } @($workspace.SystemIndexDir) {
        param ($output, $errorText)
        $result = if (!$errorText -and $output.Count -gt 0) { $output[0] } else { $null }
        if ($result -and $result.Root -ne $workspace.SystemIndexDir) {
            # 確かめている間にワークスペースを変えた（切り替えたときに確かめ直している）
            return
        }
        $script:fastAvailable = if ($result) { [bool]$result.Available } else { $false }
        updateFastSearchView
    } (getWorkspaceJobQueue $workspace.SystemIndexDir)
}

function getCurrentWordNotice {
    # いまの検索ワード・［正規表現］の状態での、正規表現の注意（正しくなければ文言、正しければ ""）
    getWordNotice (getWordText) ([bool]$ui.RegexCheck.IsChecked)
}

function updateWordNotice {
    $ui.WordPlaceholder.Visibility = if ($ui.WordBox.Text -eq "") { "Visible" } else { "Collapsed" }
    updateFastSearchView
    # 正規表現が正しくないときは、入力欄の枠を赤くし、［正規表現］の下に吹き出しを出す
    $notice = getCurrentWordNotice
    $ui.WordErrorRing.Visibility = if ($notice -ne "") { "Visible" } else { "Collapsed" }
    setSearchBalloon $ui.RegexBalloon $ui.RegexBalloonText $notice
    updateSearchButton
}

function updateSearchButton {
    $notice = getCurrentWordNotice
    $noIndex = $script:indexSummary -and $script:indexSummary["Count"] -eq 0
    $state = newSearchButtonState ([bool]$script:search) ([bool]($script:search -and $script:search.Shared.Stop)) `
        (getWordText) (!$noIndex) @(getSearchTargets).Count ($notice -ne "") ([bool]$script:indexTreeLoading)
    $ui.SearchButton.Content = $state.Content
    $ui.SearchButton.IsEnabled = $state.Enabled
}

function updateSearchTarget {
    # 左の欄の見出し（選んだ数 / 全部の数）、インデックスが無いときの結果欄の案内。
    # 検索対象の詳しい中身（先頭の数件・本文インデックスのファイルの数・最終更新）は、見出しのツールチップに出す
    $targets = @(getSearchTargets)
    $summary = $script:indexSummary
    $total = @($script:indexRoots).Count
    $checked = @($script:indexRoots | Where-Object { $_.IsChecked -eq $true }).Count
    $ui.TargetCountText.Text = getTargetCountText $checked $total
    $targetsText = if ($targets.Count -gt 0) { describeSearchTargets $targets } else { "" }
    $ui.TargetCountText.ToolTip = getSearchTargetText ([bool]$script:indexTreeLoading) ([string]$script:indexTreeConnectError) `
        $total $targets.Count (isAllIndexChecked) $targetsText $summary
    # インデックスが無いときは、結果の表の代わりに空の状態（［インデックス管理を開く］）を出す。
    # 読み込み中・接続できないときは、「インデックスが無い」とは違うため出さない
    $noIndex = [bool]($summary -and $summary["Count"] -eq 0 -and !$script:indexTreeLoading -and !$script:indexTreeConnectError)
    $ui.ResultEmptyState.Visibility = if ($noIndex) { "Visible" } else { "Collapsed" }
    # 検索できるインデックスが無いときは、高速検索の状態も出さない
    $ui.FastBadge.Visibility = if ($noIndex) { "Collapsed" } else { "Visible" }
    $ui.FastSearchSlot.Visibility = $ui.FastBadge.Visibility
    updateConditionFlow
    updateSearchButton
}

function updateConditionFlow {
    # 検索条件の行の折り返し。判断（getConditionFlow）の結果を、「伸びる空き」の幅に反映する。
    # 並びの幅が変わったとき・高速検索の印を出す／隠したときに呼ぶ
    $panel = $ui.ConditionsPanel
    if ($panel.ActualWidth -le 0) { return }
    $items = @($panel.Children | Where-Object { $_ -ne $ui.ConditionsSpacer })
    # 幅が決まっている項目（Width 指定）は指定の値で数える。出した直後で ActualWidth がまだ 0 でも、正しい幅で計算できる
    $widths = @($items | ForEach-Object {
        if ($_.Visibility -eq "Collapsed") { 0.0 }
        else {
            $width = if ([double]::IsNaN($_.Width)) { $_.ActualWidth } else { $_.Width }
            [double]($width + $_.Margin.Left + $_.Margin.Right)
        }
    })
    # 空きは、［ファイル内の対象］の次（検索条件の前）に置く
    $spacerIndex = $items.IndexOf($ui.CaseCheck)
    $flow = getConditionFlow $widths $spacerIndex $panel.ActualWidth
    if ([Math]::Abs($ui.ConditionsSpacer.Width - $flow.SpacerWidth) -gt 0.1) {
        $ui.ConditionsSpacer.Width = $flow.SpacerWidth
    }
    # 空きの幅が変わると、並びの大きさが同じでも［正規表現］などが横に動く（高速検索の印の出し入れ）。吹き出しもここで置き直す
    placeSearchBalloons
}

# ---- イベント ----
$ui.ConditionsPanel.Add_SizeChanged({ safe { updateConditionFlow } })
# 高速検索が使用不可の印（Windows Search が使えないとき）を押すと、確かめるインデックス管理へ移る（移るかは getFastSearchView の GoToIndex）
$script:fastGoToIndex = $false
$ui.FastBadge.Add_MouseLeftButtonUp({
    if ($script:fastGoToIndex) { safe { selectScreen "IndexTab" } }
})


$ui.WordBox.Add_TextChanged({ safe { updateWordNotice } })
$ui.WordBox.Add_PreviewKeyDown({
    param ($sender, $e)
    if ($e.Key -eq "Return") {
        safe {
            if (!$script:search) {
                startSearch
            }
        }
        $e.Handled = $true
    }
})
$ui.SearchButton.Add_Click({ safe { startSearch } })
$ui.RegexCheck.Add_Click({
    safe {
        writeSearchOption @{ UseRegex = [bool]$ui.RegexCheck.IsChecked }
        updateWordNotice
    }
})
$ui.CaseCheck.Add_Click({ safe { writeSearchOption @{ CaseSensitive = [bool]$ui.CaseCheck.IsChecked } } })
$ui.ShapeCheck.Add_Click({ safe { writeSearchOption @{ IncludeShapes = [bool]$ui.ShapeCheck.IsChecked }; updateScopeButton } })
$ui.CommentCheck.Add_Click({ safe { writeSearchOption @{ IncludeComments = [bool]$ui.CommentCheck.IsChecked }; updateScopeButton } })

# ［ファイル内の対象 ▼］は、押したらボタンの下にメニューを開く
$ui.ScopeButton.Add_Click({
    $menu = $ui.ScopeButton.ContextMenu
    $menu.PlacementTarget = $ui.ScopeButton
    $menu.Placement = [System.Windows.Controls.Primitives.PlacementMode]::Bottom
    $menu.IsOpen = $true
})

# 種類のチップ。押すと ToggleButton が先に入れ替わるため、押す前の状態に戻して、判断（toggleFileKind）の結果を反映する
foreach ($kind in ${fileKindNames}) {
    $chip = $script:kindChips[$kind]
    $chip.Add_Click({
        param ($sender, $e)
        safe {
            $clicked = [string]$sender.Tag
            $before = @(${fileKindNames} | Where-Object { ($script:kindChips[$_].IsChecked) -xor ($_ -eq $clicked) })
            $after = @(toggleFileKind $before $clicked)
            setFileKindsToUi $after
            writeFileKinds $after
            # 吹き出しを出している間は、選び直したらすぐ消す
            if ($ui.SearchKindBalloon.Visibility -eq "Visible") {
                setSearchKindBalloon (getSearchKindBalloonText $after)
            }
        }
    })
}

# 検索の実行（開始・中止・結果の取り込み・終わりの文言）の画面層。検索条件の画面は search_bar.ps1、結果の絞り込みは result_filter.ps1。

# 結果（ヒットした行・ファイルごとの見出し）と表の中身は result_list.ps1
$script:search = $null
$script:lastSearch = $null
$script:sourceFolderMaps = @{}  # インデックスのフォルダ → インデックス名とクロール対象フォルダの対応（getSourceLocation のキャッシュ）
$script:filterText = ""
# 検索で読んだ本文インデックスのファイルの内容（画面を閉じるまで残し、次の検索では更新の無い本文インデックスのファイルをファイルから読まない）
$script:tsvCache = newTsvTextCache
# 検索の司令のスレッド（画面を開いている間 1 つ。閉じるときに gui.ps1 が Close する）
$script:searchService = newSearchService $script:tsvCache
# Windows Search が使えるか（高速検索の使用可否に使う。$null はまだ確かめていない）
$script:fastAvailable = $null

function startSearch {
    if (!(testIndexReadAllowed ([bool]$script:workspaceMoving))) {
        # ワークスペースの中身を移している間は始めない（待つ間のダイアログの裏でも、Enter・F5 は本体に届く）
        return
    }
    if ($script:search) {
        cancelSearch
        return
    }
    $word = getWordText
    if ($word -eq "") {
        setStatus "検索ワードを入力してください。"
        return
    }
    if (getCurrentWordNotice) {
        # 正規表現が正しくない（吹き出しを出している。始めない）
        return
    }
    $kindBalloon = getSearchKindBalloonText (getFileKindsFromUi)
    setSearchKindBalloon $kindBalloon
    if ($kindBalloon) {
        return
    }

    $option = getSearchOptionFromUi
    writeSearchOption $option
    $useRegex = $option.UseRegex
    # 一致箇所の強調にも、検索と同じ正規表現を使う
    $searchRegex = newSearchRegex $word (!$useRegex) $option.CaseSensitive
    $simpleMatch = $searchRegex.SimpleMatch
    $pattern = $searchRegex.Regex

    $ui.FilterBox.Text = ""
    $script:filterText = ""
    clearResults $word $pattern
    clearDetail
    # 検索対象ツリーでチェックしたフォルダだけを検索する（結果の相対パスは、インデックスのフォルダからのまま）
    $folders = @(getSearchTargets)
    if ($folders.Count -eq 0) {
        setStatus "検索するフォルダに、左の「検索対象」でチェックを付けてください。"
        return
    }

    # 新しく検索を始めるため、待っている元のファイルの確認（別の行）は打ち切る
    cancelPendingSourceLookup

    $useFast = (getFastSearchView $script:fastAvailable $useRegex $word).Usable
    $shared = $script:searchService.Request((newSearchRequest $word $simpleMatch $folders ${searchLimit} $option $useFast))
    $script:search = @{
        Shared = $shared
        Word = $word; Pattern = $pattern; SimpleMatch = $simpleMatch; UseRegex = $useRegex; Option = $option; Start = Get-Date
    }

    $ui.SearchProgress.Visibility = "Visible"
    $ui.SearchProgress.IsIndeterminate = $true
    $ui.SummaryText.Text = "検索中…"
    $ui.NoHitText.Visibility = "Collapsed"
    $taskbar.ProgressState = "Indeterminate"
    setStatus "検索しています：${word}"
    updateSearchButton
    $script:searchTimer.Start()
}

function cancelSearch {
    if ($script:search) {
        $script:search.Shared.Stop = $true
        $ui.SummaryText.Text = "中止しています…"
        updateSearchButton
    }
}

function clearSearchView {
    # ワークスペースを変えたとき、前のワークスペースの検索を止め、結果・プレビュー・インデックスの対応を捨てる
    # 待っている元のファイルの確認も打ち切る（前のワークスペースの行は、ここから先は開けない）
    cancelPendingSourceLookup
    $s = $script:search
    if ($s) {
        # 止めた検索のヒットは画面に移さない（司令のスレッドは止まり次第、次の要求に移る）
        $s.Shared.Stop = $true
        $script:search = $null
        $script:searchTimer.Stop()
        $ui.SearchProgress.Visibility = "Collapsed"
        $taskbar.ProgressState = "None"
    }
    $script:lastSearch = $null
    $script:sourceFolderMaps = @{}
    $script:fastAvailable = $null
    $ui.FilterBox.Text = ""
    $script:filterText = ""
    clearResults "" $null
    clearDetail
    $ui.SummaryText.Text = ""
    $ui.NoHitText.Visibility = "Collapsed"
    updateSearchButton
}

function pumpSearch {
    # 検索スレッドの結果を表に移し、進み具合を表示する
    $s = $script:search
    if ($null -eq $s) {
        $script:searchTimer.Stop()
        return
    }
    $shared = $s.Shared
    $hit = $null
    # 1 回に移す量は件数ではなく時間で区切る（件数で区切ると、ヒットが多いときに画面が 0.5 秒以上止まる）
    $elapsed = [System.Diagnostics.Stopwatch]::StartNew()
    while ($elapsed.ElapsedMilliseconds -lt ${searchPumpMilliseconds} -and $shared.Queue.TryDequeue([ref]$hit)) {
        # ヒットは元のファイルの見出しに生のまま貯めるだけにする。表の行（HitRow）は開いたときなどに作り（ensureRows）、
        # 表への反映は、この 1 回の最後に flushResults でまとめて行う。ヒットごとに通る処理なので、
        # 関数は初めてのファイル・場所のときだけ呼ぶ（呼ぶと、そのぶん結果を表に移すのが遅くなる）
        $relDir = [string]$hit.RelDir
        $fileKey = "$($hit.Root)\$relDir\$($hit.Book)"
        $group = $null
        if (!$script:fileGroups.TryGetValue($fileKey, [ref]$group)) {
            $group = newFileGroup $fileKey $relDir $hit.Book
        }
        $group.Hits.Add($hit)
        if ($group.AddLocation($hit.Location)) {
            addFileGroupLocation $group $hit.Book $hit.Location
        }
        [void]$script:dirtyGroups.Add($group)
        $script:hitCount++
    }
    flushResults

    if ($shared.Total -gt 0) {
        $ratio = $shared.Done / $shared.Total
        $ui.SearchProgress.IsIndeterminate = $false
        $ui.SearchProgress.Value = $ratio
        $taskbar.ProgressState = "Normal"
        $taskbar.ProgressValue = $ratio
        if (!$shared.Stop) {
            $ui.SummaryText.Text = getSearchProgressText $script:hitCount
        }
    } elseif ($shared.Total -lt 0 -and !$shared.Stop) {
        # 数え上げの途中。件数が増えていくのが見えれば、止まっていないことが分かる
        $scanned = [int]$shared.Scanned
        $ui.SummaryText.Text = if ($scanned -gt 0) {
            "検索対象のファイルを確認しています…（$($scanned.ToString('N0')) 件）"
        } else {
            "検索対象のファイルを確認しています…"
        }
    }

    if (!$shared.Finished -and !$script:searchService.IsRunning()) {
        # 司令のスレッドが止まった（lib.ps1 を読み込めなかった等）。次の検索で作り直す
        $shared.Error = $script:searchService.GetFailure()
        $shared.Finished = $true
    }
    if ($shared.Finished -and $shared.Queue.IsEmpty) {
        finishSearch
    }
}

function finishSearch {
    $s = $script:search
    $script:search = $null
    $script:searchTimer.Stop()

    $shared = $s.Shared
    $ui.SearchProgress.Visibility = "Collapsed"
    $taskbar.ProgressState = if (isIndexing) { $taskbar.ProgressState } else { "None" }
    $script:lastSearch = $s
    $seconds = ((Get-Date) - $s.Start).TotalSeconds
    updateSearchButton
    finishResults

    if ($shared.Error) {
        $ui.SummaryText.Text = "検索できませんでした"
        setStatus "検索できませんでした：$($shared.Error)"
        return
    }

    $count = $script:hitCount
    $files = $script:fileGroups
    if ($null -ne $shared.FastAvailable) {
        $script:fastAvailable = [bool]$shared.FastAvailable
        updateFastSearchView
    }

    # 高速検索では、候補の無いフォルダの本文インデックスのファイルを集めないため、集めた数が 0 でも「インデックスが無い」とは限らない
    if (!$shared.FastUsed -and $shared.IndexTotal -gt 0 -and $shared.Total -eq 0) {
        $ui.SummaryText.Text = getNoKindMatchText $s.Option.FileKinds
    } elseif (!$shared.FastUsed -and $shared.Total -eq 0) {
        $ui.SummaryText.Text = "インデックスが未作成です"
    } elseif ($count -eq 0) {
        # 0 件は、結果欄の要約と表の空いた所に「一致する結果はありません」を出す（ステータスバーの「検索しました：… 0 件」はそのまま）
        $ui.SummaryText.Text = getNoHitText
        $ui.NoHitText.Text = getNoHitText
        $ui.NoHitText.Visibility = "Visible"
    } else {
        $ui.SummaryText.Text = getSearchSummaryText $count $files.Count $seconds
    }

    $status = getSearchStatusText $s.Word $count (describeSearchOption $s.Option)
    if ($shared.Truncated) {
        # パスの順に検索して打ち切るため、この先のファイルのヒットは結果に出ない。そのことが分かる文面にする
        $status = "$(${searchLimit}.ToString('N0')) 件を超えたため、ここで打ち切りました。この先のファイルは検索していないため、ワード・種類・検索対象で絞り込んでください。"
    } elseif ($shared.Cancelled) {
        $status = "中止しました（$($count.ToString('N0')) 件まで表示）"
    }
    $missing = @($shared.Folders | Where-Object { !$_.Exists } | ForEach-Object { $_.Path })
    if ($missing.Count -gt 0) {
        $status += "　見つからない検索対象フォルダ：$($missing -join '、')"
    }
    if (isIndexing) {
        $status += "　更新中のため、更新の途中のインデックスを検索しています。"
    }
    setStatus $status
}

# 検索結果を表に移す 1 回あたりの時間（ミリ秒）。タイマーの間隔（100 ミリ秒）より短くし、その間も画面が操作できるようにする
${searchPumpMilliseconds} = 60
$script:searchTimer = newTimer 100 { safe { pumpSearch } }

# 結果の一覧の絞り込み（件数の行の「絞り込み」）と、空の状態の［インデックス管理へ］ボタンの画面層。

# ---- 結果の絞り込み ----

function applyFilter {
    $script:filterText = $ui.FilterBox.Text.Trim()
    applyResultFilter $script:filterText
    if ($script:lastSearch -and !$script:search -and $script:hitCount -gt 0) {
        $shown = getShownHitCount
        if ($script:filterText -eq "") {
            finishSummaryText
        } else {
            $ui.SummaryText.Text = getFilteredSummaryText $script:hitCount $shown
        }
    }
}

function finishSummaryText {
    $ui.SummaryText.Text = getSearchSummaryText $script:hitCount $script:fileGroups.Count
}

$script:filterTimer = newTimer 300 {
    $script:filterTimer.Stop()
    safe { applyFilter }
}

# ---- イベント ----

$ui.GoIndexTabButton.Add_Click({ selectScreen "IndexTab" })
$ui.FilterBox.Add_TextChanged({
    $ui.FilterPlaceholder.Visibility = if ($ui.FilterBox.Text -eq "") { "Visible" } else { "Collapsed" }
    $script:filterTimer.Stop()
    $script:filterTimer.Start()
})

# ［検索］タブの、選択した行の前後を表で見せるプレビュー。

# 選択行のプレビューは、↑↓で続けて選択が変わったときは最後の1回だけ読む（巨大なTSVでも操作が重くならないようにする）。
$script:detailTimer = newTimer 120 {
    $script:detailTimer.Stop()
    safe { showDetail }
}
# 読み込みを頼んだプレビューの番号と行（別の行を選んだ後に届いた古い結果を捨てるため）
$script:previewRequest = 0
$script:previewRow = $null
# 最後に読んだ 1 つのファイルの控え（readContentIndexLines の Marks）。次に読むときに渡し、同じファイルなら先頭から読み直さない。
# ファイルのパス・更新日時・大きさが変わったら readContentIndexLines が使わずに作り直す（初めて開くファイルの最初の読みは、ファイル全体を読む）
$script:previewMarks = $null
# 列見出しをドラッグしている間 $true（見えている列の範囲を決め直さない。updatePreviewWindow）
$script:previewDragging = $false

# 表示中の行（getViewRows）・選んでいる行（getSelectedRows）・選んでいる行 1 つ（getCurrentHitRow）は result_list.ps1

function clearDetail {
    # 行を選んでいないときのプレビュー。枠（と高さ）はそのままにし、中身を空にして案内を出す
    $script:previewRequest++   # 読んでいる途中の読み足しの結果は捨てる
    $script:previewDragging = $false
    $script:previewMarks = $null
    $ui.PreviewHeader.ItemsSource = $null
    $ui.PreviewHeaderPanel.DataContext = $null
    $ui.PreviewRows.ItemsSource = $null
    $script:previewTable = $null
    $ui.DetailTitle.Text = ""
    $ui.DetailTitle.ToolTip = $null
    $ui.PreviewHeaderScroll.Visibility = "Collapsed"
    $ui.PreviewPlaceholder.Visibility = "Visible"
    $ui.OpenButton.IsEnabled = $false
    $ui.OpenMenuButton.IsEnabled = $false
    $ui.OpenFolderButton.IsEnabled = $false
}

function showDetail {
    $row = getCurrentHitRow
    if ($null -eq $row) {
        clearDetail
        return
    }
    $ui.PreviewPlaceholder.Visibility = "Collapsed"
    $ui.PreviewHeaderScroll.Visibility = "Visible"
    $ui.OpenButton.IsEnabled = $true
    $ui.OpenMenuButton.IsEnabled = $true
    $ui.OpenFolderButton.IsEnabled = $true
    # 閉じている見出しを選んだときの先頭の行は、まだ画面に出ていない（LoadingRow で Prepare されていない）ため、
    # セル番地（MatchCell）・「場所」の列の表記（PlaceDisplay）が空のままになる。ここで作っておく（作り済みなら何もしない）
    prepareHitRow $row

    # 前後の行を本文インデックスのファイルから読む。最初は選択行の前後に ${previewFirstLines} 行ずつ（高さを変えても読み直さない。
    # 表は行を仮想化して出すので、高さに入る分より多く読んでも重くならず、縦にスクロールして見られる。端に近づいたら読み足す。updatePreviewReadMore）。
    # 検索で読んだ内容があれば使う。読み込みは画面のスレッドでは行わない（キャッシュに無いと本文インデックスのファイル全体を読むため）。
    # 読み終わったら applyDetail で表にする。読んでいる間に別の行を選んだら、古い結果は捨てる（番号で見分ける）
    $script:previewRequest++
    $script:previewRow = $row
    $first = [Math]::Max(1, $row.LineNumber - ${previewFirstLines})
    $count = $row.LineNumber - $first + 1 + ${previewFirstLines}
    startJob {
        param ($id, $path, $book, $location, $first, $count, $cache, $marks)
        $result = readContentIndexLines $path $book $location $first $count $cache $marks
        @{ Id = $id; Context = @($result.Rows); End = $result.End; Marks = $result.Marks }
    } @($script:previewRequest, [System.IO.Path]::Combine($row.Root, $row.RelPath), $row.Book, $row.Location, $first, $count, $script:tsvCache, $script:previewMarks) {
        param ($output, $errorText)
        if ($output -and $output.Count -gt 0 -and $output[0].Id -eq $script:previewRequest) {
            $script:previewMarks = $output[0].Marks
            applyDetail $script:previewRow $output[0].Context $output[0].Marks $output[0].End
        } elseif ($errorText -and $null -ne $script:previewRow) {
            # 読めなければ選択行だけを出す（読み足しもしない）
            applyDetail $script:previewRow @([pscustomobject]@{ LineNumber = $script:previewRow.LineNumber; Line = $script:previewRow.Line }) $null $true -noMore
        }
    }
}

function applyDetail {
    # 読んだ前後の行（readContentIndexLines の結果）でプレビューの表を作る。marks は読み足しに使う控え、
    # end は下にもう行が無いか（読んだ数が頼んだ数より少なかった）。noMore なら、読み足しをしない
    param (
        $row,
        [object[]]$context,
        $marks = $null,
        [bool]$end = $false,
        [switch]$noMore
    )

    if (!$row.Equals((getCurrentHitRow))) {
        return
    }
    $path = if ($row.RelDir) { "$($row.RelDir)\$($row.Book)" } else { $row.Book }
    $table = $row.BuildPreview([int[]]@($context | ForEach-Object { $_.LineNumber }), [string[]]@($context | ForEach-Object { $_.Line }))

    $title = "${path} ・ $($row.PlaceDisplay) ・ $($row.Kind)"
    $ui.DetailTitle.Text = $title
    $ui.DetailTitle.ToolTip = $title

    $table.Marks = $marks
    $table.Request = $script:previewRequest
    $table.BottomDone = $end -or $noMore
    if ($noMore) { $table.TopDone = $true }
    $script:previewTable = $table
    # 見出しをドラッグしている途中で表が替わると、ドラッグ中の部品が木から外れて DragCompleted が届かない。旗を戻して、新しい表の範囲を決める
    $script:previewDragging = $false
    $script:previewBaseWidth = if ($table.Columns.Count -eq 1) { $table.Columns[0].Width } else { 0 }
    $script:previewFitWidth = $script:previewBaseWidth
    # 列は全部の列を持ち、横にスクロールしたとき見えている列の範囲のセルだけを作る（updatePreviewWindow）
    $ui.PreviewHeader.ItemsSource = $null
    $ui.PreviewHeaderPanel.DataContext = $table.Window
    $ui.PreviewRows.ItemsSource = $table.Rows

    # 一致したセルが見えるよう横にスクロールする（左端から見えていればそのまま）。
    # 列の幅は、行を入れて縦のバーが出るかどうかが決まってから（見える幅が定まってから）合わせる
    $ui.PreviewScroll.UpdateLayout()
    fitPreviewWidth
    $offset = 0
    if ($table.HitOffset + $table.HitWidth -gt $ui.PreviewScroll.ViewportWidth) {
        $offset = [math]::Max(0, $table.HitOffset - 120)
    }
    $ui.PreviewScroll.ScrollToHorizontalOffset($offset)
    # 選択行が上から 3 行目に来るよう縦にスクロールする（縦の単位は行。位置は getPreviewTopRow）
    $hitIndex = -1
    for ($i = 0; $i -lt $table.Rows.Count; $i++) {
        if ($table.Rows[$i].IsHitRow) {
            $hitIndex = $i
            break
        }
    }
    $ui.PreviewScroll.ScrollToVerticalOffset((getPreviewTopRow $hitIndex))
    $ui.PreviewScroll.UpdateLayout()
    updatePreviewWindow $offset
    updatePreviewReadMore
}

function updatePreviewWindow {
    # 横の位置・見える幅・列の幅から、見えている列の範囲を決め直す（判断は getPreviewColumnWindow）。
    # 範囲が変わったら、列見出しを入れ替え、見えている行のセルを今の範囲で作り直す。
    # offset は、スクロールした直後でまだ配置が終わっていないときに、行き先の位置を渡す
    param (
        $offset = $null
    )

    $table = $script:previewTable
    if ($null -eq $table -or $table.Columns.Count -eq 0) { return }
    # 列見出しをドラッグしている間は、範囲を決め直さない（見出しを入れ替えると、ドラッグしている見出しの部品が作り直されて途切れる）。
    # 縦にスクロールして見えた行のセルだけ作り、ドラッグが終わったら決め直す
    if ($script:previewDragging) {
        updatePreviewCells
        return
    }
    if ($null -eq $offset) { $offset = $ui.PreviewScroll.HorizontalOffset }
    $window = getPreviewColumnWindow $table.Prefix() $offset $ui.PreviewScroll.ViewportWidth ([HitRow]::NumberWidth) ${previewColumnMargin}
    if ($table.SetWindow($window.First, $window.Last, $window.Left, $window.Right)) {
        $ui.PreviewHeader.ItemsSource = $table.WindowColumns()
    }
    updatePreviewCells
}

function updatePreviewCells {
    # 見えている行（と上下の余白の行）に、今の列の範囲のセルが無ければ作る。縦にスクロールして新しく見えた行・読み足した行のため
    $table = $script:previewTable
    if ($null -eq $table -or $table.DataCount() -le 0) { return }
    $visible = getPreviewVisibleRows
    $lead = $table.LeadCount()
    $table.EnsureCells($lead + $visible.First - ${previewCellRowMargin}, $lead + $visible.Last + ${previewCellRowMargin})
}

function getPreviewVisibleRows {
    # 今見えている本物の行（メッセージの行を除く）の範囲。@{ First; Last }（表の本物の行の中の位置。0 から）
    $table = $script:previewTable
    $scroll = $ui.PreviewScroll
    $lead = $table.LeadCount()
    $last = $table.DataCount() - 1
    $first = [Math]::Max(0, [int][Math]::Floor($scroll.VerticalOffset) - $lead)
    $bottom = [Math]::Min($last, [int][Math]::Ceiling($scroll.VerticalOffset + $scroll.ViewportHeight) - 1 - $lead)
    return @{ First = $first; Last = [Math]::Max($first, $bottom) }
}

function updatePreviewReadMore {
    # スクロールの位置が読んである範囲の端に近づいていたら、その向きに読み足す（判断は getPreviewReadMore）
    $table = $script:previewTable
    if ($null -eq $table -or $null -eq $script:previewRow -or $table.DataCount() -le 0) { return }
    $visible = getPreviewVisibleRows
    # メッセージの行が出ている間は、その向きを読んでいる途中（読めなかったときは、その向きは done）
    $requests = @(getPreviewReadMore $visible.First $visible.Last $table.DataCount() $table.FirstLine() $table.LastLine() `
            $table.TopDone $table.BottomDone ($null -ne $table.UpMessage -and !$table.TopDone) ($null -ne $table.DownMessage -and !$table.BottomDone) `
            ${previewReadAheadLines} ${previewChunkLines})
    foreach ($request in $requests) {
        startReadMore $request
    }
}

function startReadMore {
    # 上または下に行を読み足す。読んでいる間は、その端に「読み込み中…」の行を出す
    param (
        $request
    )

    # 読む行・番号は、読み足す表のもの（行を切り替えている間も、古い表に別の行の番号を混ぜない）
    $table = $script:previewTable
    $row = $table.Owner
    $table.ShowMessage($request.Side, "読み込み中…")
    startJob {
        param ($id, $side, $path, $book, $location, $first, $count, $cache, $marks)
        try {
            $result = readContentIndexLines $path $book $location $first $count $cache $marks
            @{ Id = $id; Side = $side; Failed = $false; First = $first; Rows = @($result.Rows); End = $result.End; Marks = $result.Marks }
        } catch {
            @{ Id = $id; Side = $side; Failed = $true }
        }
    } @($table.Request, $request.Side, [System.IO.Path]::Combine($row.Root, $row.RelPath), $row.Book, $row.Location, $request.FirstLine, $request.Count, $script:tsvCache, $table.Marks) {
        param ($output, $errorText)
        applyReadMore $output $errorText
    }
}

function stopReadMore {
    # 読み足しを読めなかったとき、その向きのメッセージを「読めませんでした」にして、その向きの読み足しをやめる
    param (
        $table,
        [string]$side
    )

    if ($side -eq "up") { $table.TopDone = $true } else { $table.BottomDone = $true }
    $table.ShowMessage($side, "読めませんでした")
}

function applyReadMore {
    # 読み足した行を表に足す（上に足したときは、見ていた行が同じ所に見えたままになるよう縦の位置を直す）。
    # 持つ行が上限を超えたら、見ている所から遠い側を捨てる（判断は getPreviewTrim）
    param (
        $output,
        $errorText
    )

    $table = $script:previewTable
    if ($null -eq $table) { return }
    $result = $(if ($output -and $output.Count -gt 0) { $output[0] } else { $null })
    if ($null -eq $result) {
        # 読み足しの仕事そのものが失敗した（どの向きか分からないので、読んでいる向きすべて）
        foreach ($side in @("up", "down")) {
            if ($null -ne $(if ($side -eq "up") { $table.UpMessage } else { $table.DownMessage })) { stopReadMore $table $side }
        }
        return
    }
    # 別の行を選んで表が替わったあとに届いた古い結果は捨てる（表が持つ番号で見分ける）
    if ($result.Id -ne $table.Request) { return }
    $side = $result.Side
    if ($result.Failed) {
        stopReadMore $table $side
        return
    }
    $scroll = $ui.PreviewScroll
    $oldOffset = [int][Math]::Floor($scroll.VerticalOffset)
    $lead = $table.LeadCount()
    $numbers = [int[]]@($result.Rows | ForEach-Object { $_.LineNumber })
    $lines = [string[]]@($result.Rows | ForEach-Object { $_.Line })
    $rows = $table.Owner.BuildPreviewRows($table, $numbers, $lines)
    $table.Marks = $result.Marks
    $script:previewMarks = $result.Marks
    # 今ある行とつながらない結果（読んでいる間に反対側を捨てたなど）は足さず、また近づいたときに読み直す
    $joins = $rows.Count -gt 0 -and $(if ($side -eq "up") { $rows[$rows.Count - 1].LineNumber -eq $table.FirstLine() - 1 } else { $rows[0].LineNumber -eq $table.LastLine() + 1 })
    $table.HideMessage($side)
    if ($side -eq "up") {
        if ($joins) {
            $table.InsertRows("up", $rows)
            $scroll.UpdateLayout()
            # 見ていた先頭が「読み込み中…」の行のとき（oldOffset < lead）も、その下の行が同じ所に見えるようにする
            $scroll.ScrollToVerticalOffset([Math]::Max(0, $oldOffset - $lead + $rows.Count))
        } else {
            $scroll.ScrollToVerticalOffset([Math]::Max(0, $oldOffset - $lead))
        }
        $scroll.UpdateLayout()
        # つながらなかった結果は、場所の終わりまで読んだ（End）なら、その向きを終わりにする（終わりにしないと、同じ範囲を頼み直し続ける）。
        # 終わりまで読んでいなければ終わりとは言えない（空で返ったときだけ、その向きにもう行が無い）。
        # 下側と違って頼んだ先頭を確かめないのは、上の読みは今ある先頭の直前までを頼むので、End・空になるのは元のファイルが変わった・読めないときだけだから
        if ($rows.Count -eq 0 -or $result.End -or ($joins -and $table.FirstLine() -le 1)) { $table.TopDone = $true }
    } else {
        # 終わりと見るのは、頼んだ先頭の行が（足す前の）下の端の次のままの結果だけ。頼んだあとに下の端が動いた（下を捨てた）古い結果の End・空は、
        # 今の端の下のことではないので信じない（信じると、捨てて戻した終わりの印を立て直し、その先が読めなくなる）
        $fresh = $result.First -eq $table.LastLine() + 1
        if ($joins) { $table.InsertRows("down", $rows) }
        if ($fresh -and ($rows.Count -eq 0 -or $result.End)) { $table.BottomDone = $true }
    }
    # 持つ行が上限を超えたら、遠い側を捨てる
    $visible = getPreviewVisibleRows
    $trim = getPreviewTrim $visible.First $visible.Last $table.DataCount() ${previewMaxRows} ${previewChunkLines}
    if ($trim.Side -ne "none") {
        $offset = [int][Math]::Floor($scroll.VerticalOffset)
        $table.TrimRows($trim.Side, $trim.Count)
        if ($trim.Side -eq "top") {
            $table.TopDone = $false
            $scroll.UpdateLayout()
            $scroll.ScrollToVerticalOffset([Math]::Max(0, $offset - $trim.Count))
            $scroll.UpdateLayout()
        } else {
            $table.BottomDone = $false
        }
    }
    # 読み足した行に列が増えていれば、列の範囲を決め直す（右の空きの幅が変わる）。見えている行のセルも作る
    updatePreviewWindow
    updatePreviewReadMore
}

function fitPreviewWidth {
    # Excel 以外は列が 1 つなので、その幅を枠の幅いっぱいにする（段落は幅いっぱいに折り返して読めるようにする）。
    # 見える幅が変わるたびに呼ぶ（縦のバーの出入り・窓や欄の幅の変更）。幅の決め方は getPreviewFillWidth
    if ($null -eq $script:previewTable -or $script:previewTable.Columns.Count -ne 1 -or $script:previewTable.IsExcel) {
        return
    }
    $column = $script:previewTable.Columns[0]
    $width = getPreviewFillWidth $ui.PreviewScroll.ViewportWidth ([HitRow]::NumberWidth) $script:previewBaseWidth $column.Width $script:previewFitWidth ([PreviewColumn]::MinWidth)
    # 手で変えた幅のときは、今の幅がそのまま返る。そのときは「前に合わせた幅」を変えず、手で変えたことを覚えておく
    if ($width -ne $column.Width) {
        $column.SetWidth($width)
        $script:previewFitWidth = $column.Width
        updatePreviewWindow
    }
}

function getPreviewCell {
    # マウスの下（またはイベントの発生元）のプレビューのセル。セルの上でなければ $null
    param (
        $source
    )

    $element = $source
    while ($element) {
        if ($element -is [System.Windows.FrameworkElement] -and $element.DataContext -is [PreviewCell]) {
            return $element.DataContext
        }
        $element = [System.Windows.Media.VisualTreeHelper]::GetParent($element)
    }
    return $null
}

function copyPreviewSelection {
    # プレビューで選んだセルの値をクリップボードに入れる（1 セルならその値のまま、複数ならタブ区切り）
    if ($null -eq $script:previewTable -or !$script:previewTable.HasSelection()) {
        setStatus "プレビューでコピーするセルをクリックしてください。"
        return
    }
    $text = $script:previewTable.GetSelectionText()
    if ($text -eq "") {
        [System.Windows.Clipboard]::Clear()
    } else {
        [System.Windows.Clipboard]::SetText($text)
    }
    $count = $script:previewTable.SelectedCount()
    if ($count -le 1) {
        setStatus "セルの値をコピーしました：$(toStatusText $text)"
    } else {
        setStatus "${count} 個のセルをコピーしました（Excel に貼り付けると、元の位置に並びます）"
    }
}

$ui.ResultGrid.Add_SelectionChanged({
    # 別の行を選んだときは、一致したセルが見える位置まで横にスクロールし直す
    $script:detailTimer.Stop()
    $script:detailTimer.Start()
})

# 列見出しは行とは別のスクロールに置いている（縦に隠れないようにするため）ので、横位置を行に合わせる
$ui.PreviewScroll.Add_ScrollChanged({
    param ($sender, $e)
    # 横に動いた・見える幅が変わったときは、見えている列の範囲を決め直す（セルは見えている列の分だけ作る）
    if ($e.HorizontalChange -ne 0 -or $e.ViewportWidthChange -ne 0 -or $e.ExtentWidthChange -ne 0) {
        safe { updatePreviewWindow }
    }
    $ui.PreviewHeaderScroll.ScrollToHorizontalOffset($ui.PreviewScroll.HorizontalOffset)
    if ($e.ViewportWidthChange -ne 0) {
        fitPreviewWidth
    }
    # 縦に動いた・行が増減した・見える高さが変わったときは、新しく見えた行のセルを作り、端に近づいていれば読み足す
    if ($e.VerticalChange -ne 0 -or $e.ExtentHeightChange -ne 0 -or $e.ViewportHeightChange -ne 0) {
        safe { updatePreviewCells; updatePreviewReadMore }
    }
})
# 結果の表とプレビューの境目。結果が少ないときは表を内容の高さまで縮めてプレビューを広げる（判断は getPreviewRowHeight）。
# 利用者が境目をドラッグしたら、その高さを優先して、それ以後は自動で変えない
$script:previewHeightDragged = $false
$ui.PreviewSplitter.Add_DragCompleted({
    $script:previewHeightDragged = $true
})

function updateResultPaneHeight {
    # 結果の表の中身が変わった・窓の大きさが変わったあとに、プレビューの高さを決め直す。
    #   itemCount: 表の行の数（多いときは内容を測らない）
    param (
        [int]$itemCount = 0
    )

    if ($script:previewHeightDragged) { return }
    $available = $ui.ResultListHost.ActualHeight + $ui.DetailRow.ActualHeight
    $width = $ui.ResultListHost.ActualWidth
    if ($available -le 0 -or $width -le 0) { return }   # まだ画面に出ていない
    $content = $null
    # 件数が多いと全部の行を測ることになるので、少ないときだけ測る（多いときは表がいっぱいになるので測る必要が無い）
    if ($itemCount -le 40) {
        # 行を足し引きした直後は、表の中身がまだ測り直されていない。先に配置を終えてから測る
        $ui.ResultListHost.UpdateLayout()
        $root = $ui.ResultListHost.Content
        $root.Measure([System.Windows.Size]::new($width, [double]::PositiveInfinity))
        $content = $root.DesiredSize.Height
        $root.InvalidateMeasure()
    }
    $height = getPreviewRowHeight $available $content -itemCount $itemCount
    if ([Math]::Abs($ui.DetailRow.Height.Value - $height) -ge 1) {
        $ui.DetailRow.Height = [System.Windows.GridLength]::new($height)
    }
}

# 窓の大きさが変わったら決め直す（高さが同じなら何もしないので、自分で変えた高さで繰り返さない）
$ui.ResultListHost.Add_SizeChanged({
    safe { updateResultPaneHeight $script:resultItems.Count }
})

# プレビューのセルをクリックすると、その値をコピーできるように選ぶ（Shift＋クリック・ドラッグで範囲、Ctrl+C でコピー）
$script:previewTable = $null
$script:previewBaseWidth = 0
$script:previewFitWidth = 0
$ui.PreviewRows.Add_PreviewMouseLeftButtonDown({
    param ($sender, $e)
    safe {
        $cell = getPreviewCell $e.OriginalSource
        if ($cell -and $script:previewTable) {
            $extend = [System.Windows.Input.Keyboard]::Modifiers -band [System.Windows.Input.ModifierKeys]::Shift
            $script:previewTable.Select($cell, [bool]$extend)
            [void]$ui.PreviewScroll.Focus()
        }
    }
})
$ui.PreviewRows.Add_MouseMove({
    param ($sender, $e)
    if ($e.LeftButton -ne "Pressed") {
        return
    }
    safe {
        $cell = getPreviewCell $e.OriginalSource
        if ($cell -and $script:previewTable) {
            $script:previewTable.Select($cell, $true)
        }
    }
})
$ui.PreviewRows.Add_PreviewMouseRightButtonDown({
    param ($sender, $e)
    safe {
        # 右クリックしたセルが選ばれていなければ、そのセルだけを選ぶ
        $cell = getPreviewCell $e.OriginalSource
        if ($cell -and $script:previewTable -and !$cell.IsSelected) {
            $script:previewTable.Select($cell, $false)
        }
    }
})
$ui.PreviewScroll.Add_PreviewKeyDown({
    param ($sender, $e)
    if ($e.Key -eq "C" -and [System.Windows.Input.Keyboard]::Modifiers -eq "Control") {
        safe { copyPreviewSelection }
        $e.Handled = $true
    }
})
# プレビューが無いとき（結果を選んでいない・読めなかったとき）はメニューを出さない
$ui.PreviewRows.Add_ContextMenuOpening({
    param ($sender, $e)
    safe {
        if ($null -eq $script:previewTable) {
            $e.Handled = $true
            return
        }
        $parts = @{ openHere = $ui.MenuPreviewOpen; copyCell = $ui.MenuPreviewCopy; copyRow = $ui.MenuPreviewCopyRow }
        setContextMenuItems $ui.PreviewMenu (getPreviewMenuItems) $parts
    }
})
$ui.MenuPreviewOpen.Add_Click({ safe { openSource } })
$ui.MenuPreviewCopy.Add_Click({ safe { copyPreviewSelection } })
$ui.MenuPreviewCopyRow.Add_Click({
    safe {
        if ($script:previewTable -and $script:previewTable.HasSelection()) {
            # 選んでいるセルのある行をすべて選んでからコピーする
            $line = $script:previewTable.SelectedFirstLine()
            if ($line -gt 0) {
                $script:previewTable.SelectLine($line)
            }
        }
        copyPreviewSelection
    }
})
# プレビューの列見出しの右端をドラッグすると、その列（PreviewColumn）の幅が変わる（各行のセルも同じ列を参照しているため一緒に変わる）
$ui.PreviewHeader.AddHandler(
    [System.Windows.Controls.Primitives.Thumb]::DragStartedEvent,
    [System.Windows.Controls.Primitives.DragStartedEventHandler] {
        param ($sender, $e)
        $script:previewDragging = $true
    })
$ui.PreviewHeader.AddHandler(
    [System.Windows.Controls.Primitives.Thumb]::DragCompletedEvent,
    [System.Windows.Controls.Primitives.DragCompletedEventHandler] {
        param ($sender, $e)
        safe {
            $script:previewDragging = $false
            updatePreviewWindow   # ドラッグ中に変わった幅で、見えている列の範囲と左右の空きを決め直す
        }
    })
$ui.PreviewHeader.AddHandler(
    [System.Windows.Controls.Primitives.Thumb]::DragDeltaEvent,
    [System.Windows.Controls.Primitives.DragDeltaEventHandler] {
        param ($sender, $e)
        safe {
            $column = $e.OriginalSource.DataContext
            if ($column -is [PreviewColumn]) {
                $column.SetWidth($column.Width + $e.HorizontalChange)
                updatePreviewWindow   # ドラッグ中は範囲を決め直さない（終わったときに決め直す）
            }
        }
    })

# 検索結果から元のファイルを開く・パスをコピーする・結果を書き出す。


# ---- 元のファイルを開く・コピー・出力 ----


$script:openSourceRequest = [ref]0  # 元のファイルを確かめる依頼の番号。増やすたびに前の依頼の結果を捨てる。
# [ref] のまま閉じ込める（スクリプトブロックの中で $script:openSourceRequest を読むと、遠く離れたスレッド・
# タイマーから呼ばれたときに増やす前の値のまま固まって読めることがあるため。tests\tebunko\ui\open_source.Tests.ps1 で確かめている）
$script:openSourcePendingRow = [ref]$null  # 裏のスレッドに依頼を出したままの行（.Value が $null なら待っている依頼は無い）。
# $script:openSourceRequest と同じ理由で [ref] の箱にする。GetNewClosure() の中で
# 「$script:openSourcePendingRow = ...」と書き換えても、閉じ込めた側だけの変数になり元の箱には届かない
# （.Value を書き換えれば、同じ箱を見ている側すべてに届く）。
# 同じ行をもう一度開いても新しい依頼を出さない（届かない共有では、列の 2 つのスレッドが同じ行の依頼で塞がるため）
$script:openSourcePendingPath = [ref]""  # 待っている行を、確かめている間の文言に出すためのパス（もう一度開いたときに出し直す）

# パスのコピーの依頼は、[開く] とは別の番号・箱にする（同じ番号を共有すると、先に出した方の結果が黙って捨てられるため）
$script:copySourceRequest = [ref]0
$script:copySourcePendingRow = [ref]$null

function cancelPendingSourceLookup {
    # 待っている元のファイルの確認を打ち切る（新しく検索を始めたとき・ワークスペースを変えたときに呼ぶ）。
    # 依頼の番号を進めて前の依頼の結果を捨て、待っている行の記録・カーソルを戻す
    $script:openSourceRequest.Value++
    $script:openSourcePendingRow.Value = $null
    $script:copySourceRequest.Value++
    $script:copySourcePendingRow.Value = $null
    $window.Cursor = $null
}

function findSourceLocationAsync {
    # 検索結果の行の元のファイルの場所（getSourceLocation の結果）を求め、onLocation { param($location) } に渡す。
    # キャッシュ（$script:sourceFolderMaps）にあればその場で渡す。無ければ対応を読む必要があり、
    # ネットワークの場所なら裏の列（network）で読み、結果が届くまで画面のスレッドは待たない。ローカルならその場で読む
    #   requestBox・requestId: 呼ぶ側が進めた依頼の番号（待っている間に別の依頼が出たら、この結果は捨てる）
    #   pendingRowBox: 裏に依頼を出している間の行を入れる箱
    param (
        $row,
        [scriptblock]$onLocation,
        $requestBox,
        [int]$requestId,
        $pendingRowBox
    )

    $found = findSourceLocationInMaps $row $script:sourceFolderMaps
    if ($found.Resolved) {
        & $onLocation $found.Location
        return
    }
    if (!(testNetworkPath $found.Pending)) {
        & $onLocation (getSourceLocation $row $script:sourceFolderMaps)
        return
    }

    $pendingRowBox.Value = $row
    $script:openSourcePendingPath.Value = ""
    setStatus (getSourceLookingStatus)
    $window.Cursor = [System.Windows.Input.Cursors]::AppStarting
    # 呼ぶ関数は変数で捕まえてから閉じ込める（クロージャの中では、名前のままでは関数を引けないため）
    $applyLocation = ${function:applySourceLocation}
    $maps = $script:sourceFolderMaps
    $sendMaps = $maps.Clone()
    $statusPath = [string]$workspace.StatusFile
    $settingsPath = [string]${settingsFile}
    $indexDir = [string]$workspace.IndexDir
    startJob {
        param ($row, $maps, $statusPath, $settingsPath, $indexDir)
        readSourceLocation $row $maps $statusPath $settingsPath $indexDir
    } @($row, $sendMaps, $statusPath, $settingsPath, $indexDir) {
        param ($output, $errorText)
        if ($row -eq $pendingRowBox.Value) {
            $pendingRowBox.Value = $null
        }
        if ($requestId -ne $requestBox.Value) {
            # 待っている間に別の行を開いた・新しく検索した・ワークスペースを変えた。前の依頼は捨てる
            return
        }
        & $applyLocation $output $errorText $maps $onLocation
    }.GetNewClosure() (getWorkspaceJobQueue @($found.Pending, $indexDir))
}

function applySourceLocation {
    # findSourceLocationAsync の裏の仕事の結果を反映する。読めたら、読んだ対応をキャッシュ（maps）に足して onLocation を呼ぶ
    param (
        $output,
        $errorText,
        [hashtable]$maps,
        [scriptblock]$onLocation
    )

    $window.Cursor = $null
    if ($errorText -or !$output -or @($output).Count -eq 0) {
        setStatus (getSourceLookupFailedStatus ([string]$errorText))
        return
    }
    $result = @($output)[0]
    foreach ($key in @($result.Maps.Keys)) {
        $maps[$key] = $result.Maps[$key]
    }
    & $onLocation $result.Location
}

function findSourceFile {
    # 元のファイルの場所を確かめ、見つかれば onFound { param($path) } を呼ぶ（見つからない・選ばなかったときは呼ばない）。
    # ネットワークにあるときは裏のスレッドで確かめ、結果が届くまで画面のスレッドは待たない（届かない共有で「応答なし」に
    # しないため）。ローカルならその場で確かめる。待っている間に同じ行をもう一度開いても、新しい依頼は出さない
    # （確かめている間の文言は出し直す。開き方（通常・読み取り専用・フォルダを開く 等）が違っても、同じ行の待ちは 1 つにまとめる）
    param (
        $row,
        [scriptblock]$onFound
    )

    $pendingRowBox = $script:openSourcePendingRow
    if ($row -eq $pendingRowBox.Value) {
        # この行はもう裏のスレッドに依頼済みで、まだ結果が届いていない。確かめている最中であることを出し直す
        $pendingPath = $script:openSourcePendingPath.Value
        setStatus $(if ($pendingPath) { getSourceCheckingStatus $pendingPath } else { getSourceLookingStatus })
        return
    }

    $requestBox = $script:openSourceRequest
    $requestBox.Value++
    $requestId = $requestBox.Value
    $continue = ${function:continueFindSourceFile}
    findSourceLocationAsync $row {
        param ($location)
        & $continue $row $location $requestBox $requestId $pendingRowBox $onFound
    }.GetNewClosure() $requestBox $requestId $pendingRowBox
}

function continueFindSourceFile {
    # findSourceFile の続き。元のファイルの場所（location）が分かったので、ファイルがあるかを確かめる
    param (
        $row,
        $location,
        $requestBox,
        [int]$requestId,
        $pendingRowBox,
        [scriptblock]$onFound
    )

    $book = $row.Book

    # 見つけたときの続きには、パスに加えてインデックスの名前も渡す（もらったインデックスかをキャッシュから引き直さないため）
    $foundInner = $onFound
    $locationName = [string]$location.Name
    $onFound = { param ($path) & $foundInner $path $locationName }.GetNewClosure()

    # 呼ぶ関数は変数で捕まえてから閉じ込める（スクリプトブロックの中で名前のまま呼ぶと、遠く離れたスレッド・
    # タイマーから呼ばれたときに見つからないことがあるため）
    $applyState = ${function:applySourceFileState}
    $apply = {
        param ($state)
        if ($row -eq $pendingRowBox.Value) {
            $pendingRowBox.Value = $null
        }
        if ($requestId -ne $requestBox.Value) {
            # 待っている間に別の行を開いた・新しく検索した・ワークスペースを変えた。前の依頼は捨てる
            return
        }
        & $applyState $state $location $book $onFound
    }.GetNewClosure()

    if (!$location.Known) {
        # 元のフォルダの記録が無い（Folder が空）。row.Root・row.RelDir（インデックスの中の位置）から知らせる
        $relPath = if ($row.RelDir) { "$($row.RelDir)\$book" } else { $book }
        promptSourceMissing $location $book (joinSourcePath $row.Root $row.RelDir $book) $relPath "" $onFound
        return
    }
    if ($requestId -ne $requestBox.Value) {
        # 場所を調べている間に別の行を開いた・新しく検索した・ワークスペースを変えた。前の依頼は捨てる（確認も出さない）
        return
    }
    if (testSourceNeedsConfirm $location.Name $location.Known (getConfirmedSourceNames).Confirmed) {
        # 設定に無い名前（content_index\ に手でコピーしたインデックス）の元のフォルダは、持ち主が書いたもの。
        # 元のフォルダに触れる前（有無の確認・ネットワークへの接続の前）に利用者に確かめる
        $answer = promptSourceConfirm $location $book
        $window.Cursor = $null
        if ($answer -eq "pick") {
            $path = joinSourcePath $location.Folder $location.Rest $book
            $relPath = if ($location.Rest) { "$($location.Rest)\$book" } else { $book }
            promptSourceMissing $location $book $path $relPath "" $onFound -pickFirst
            return
        }
        if ($answer -ne "use") {
            setStatus (getSourceConfirmCanceledStatus)
            return
        }
        if (testSourceNameRecordable ([string]$location.Name)) {
            setIndexSourceFolder $location.Name $location.Folder
        }
        $script:sourceFolderMaps = @{}
    }
    if (!(testNetworkPath (normalizeFolderPath ([string]$location.Folder)))) {
        & $apply (findSourceFileState $location $book)
        return
    }
    $pendingRowBox.Value = $row
    $checkingPath = joinSourcePath $location.Folder $location.Rest $book
    $script:openSourcePendingPath.Value = $checkingPath
    setStatus (getSourceCheckingStatus $checkingPath)
    $window.Cursor = [System.Windows.Input.Cursors]::AppStarting
    # ${pathStateOther} も、外の変数を直に書かず、いったんローカル変数に受けてから閉じ込める（$apply と同じ理由）
    $otherState = ${pathStateOther}
    startJob {
        param ($location, $book)
        findSourceFileState $location $book
    } @($location, $book) {
        param ($output, $errorText)
        if ($errorText) {
            & $apply @{ State = $otherState; Message = $errorText }
        } else {
            & $apply $output[0]
        }
    }.GetNewClosure() (getWorkspaceJobQueue $location.Folder)
}

function applySourceFileState {
    # findSourceFileState（または裏の仕事）の結果を画面に反映する。見つかれば onFound を呼ぶ。
    # 見つからない・接続できない・その他のときは、見つかるまで（またはあきらめるまで）確認・フォルダ選択で進める
    param (
        $state,
        $location,
        [string]$book,
        [scriptblock]$onFound
    )

    $window.Cursor = $null
    if ($state.State -eq ${pathStateFound}) {
        if ($state.Alias -and (testSourceNameRecordable ([string]$location.Name))) {
            setIndexSourceFolder $location.Name $state.Alias
            $script:sourceFolderMaps = @{}
            setStatus "インデックス [$($location.Name)] の元のフォルダを $($state.Alias) に変えました"
        }
        & $onFound $state.Path
        return
    }
    if ($state.State -eq ${pathStateUnreachable} -or $state.State -eq ${pathStateOther}) {
        promptSourceConnectFailure $state $location $book $onFound
        return
    }
    # State=Missing はここまで来た時点で必ず Known（findSourceFileState は Known のときだけ呼ぶ）
    $path = joinSourcePath $location.Folder $location.Rest $book
    $relPath = if ($location.Rest) { "$($location.Rest)\$book" } else { $book }
    promptSourceMissing $location $book $path $relPath ([string]$state.Initial) $onFound
}

function promptSourceConnectFailure {
    # 接続できない・その他のとき。知らせて、［フォルダを選ぶ］を選べば見つからないときと同じ流れに進む
    param (
        $state,
        $location,
        [string]$book,
        [scriptblock]$onFound
    )

    $dialog = getSourceConnectFailureDialog $book $state.State $location.Folder $state.Message
    setStatus (getSourceConnectFailureStatus $state.State $location.Folder $state.Message)
    $answer = showConfirm -title "元のファイルが見つかりません" -heading $dialog.Heading `
        -facts @((factGone $dialog.Title $dialog.Detail), (factNext $dialog.Hint)) `
        -choices @(@{ Text = "フォルダを選ぶ"; Value = "pick" })
    if ($answer -eq "pick") {
        $path = joinSourcePath $location.Folder $location.Rest $book
        $relPath = if ($location.Rest) { "$($location.Rest)\$book" } else { $book }
        promptSourceMissing $location $book $path $relPath "" $onFound
    }
}

function promptSourceConfirm {
    # もらったインデックスの元のフォルダを、使う前に利用者に確かめる。"use"（このフォルダを使う）・"pick"（フォルダを選ぶ）、
    # キャンセルは $null を返す
    param (
        $location,
        [string]$book
    )

    $dialog = getSourceConfirmDialog $book $location.Name $location.Folder (!(testLocalDrivePath (normalizeFolderPath ([string]$location.Folder)))) (testSourceNameRecordable ([string]$location.Name))
    return (showConfirm -title "元のフォルダを確かめてください" -heading $dialog.Heading -hint $dialog.Hint `
        -facts @((factWarn $dialog.Title $dialog.Detail)) `
        -choices @(@{ Text = $dialog.PickText; Value = "pick" }, @{ Text = $dialog.UseText; Value = "use" }))
}

function promptSourceMissing {
    # 見つからない・記録が無いとき、フォルダを選んでもらって探す（見つかるまで繰り返す）。
    # findMovedSource は、選んだ直後のフォルダ（届いている）を調べるため画面のスレッドのままにする。
    #   path: 知らせに出す（記録されていた・見つからなかった）パス
    #   relPath: インデックスの中の相対パス（記録が無いときの知らせに使う）
    #   initial: フォルダ選択の開始フォルダ（findSourceFileState が返した Initial。無ければ空）
    param (
        $location,
        [string]$book,
        [string]$path,
        [string]$relPath,
        [string]$initial,
        [scriptblock]$onFound,
        [switch]$pickFirst   # 最初の「見つかりません」の確認を飛ばして、すぐフォルダ選択から始める
    )

    if ($location.Known) {
        $heading = "元のファイルが見つかりません。フォルダを移動した場合は、移動先のフォルダを選んでください。"
        $hint = "元の場所: $path"
        $description = "「$($location.Folder)」に当たるフォルダ（または $book のあるフォルダ）を選んでください"
    } else {
        $heading = "元のファイルが見つかりません。場所の記録もないため、$book のあるフォルダを選んでください。"
        $hint = "ファイル: $relPath"
        $description = "$book のあるフォルダ（またはインデックス [$($location.Name)] の元のフォルダ）を選んでください"
    }
    $facts = @()
    $skipConfirm = [bool]$pickFirst
    $fromConfirm = [bool]$pickFirst   # 確認で「フォルダを選ぶ」を選んだ直後の選択か（その選択をやめたときは、見つからないのではなく開くのをやめた）
    while ($true) {
        if (!$skipConfirm -and (showConfirm -title "元のファイルが見つかりません" -heading $heading -hint $hint -facts $facts `
                -choices @(@{ Text = "フォルダを選ぶ"; Value = "pick" })) -ne "pick") {
            setStatus (getSourceNotFoundStatus $path)
            return
        }
        $skipConfirm = $false
        $picked = selectFolder $description $initial
        if (!$picked) {
            if ($fromConfirm) {
                setStatus (getSourceConfirmCanceledStatus)
            } else {
                setStatus (getSourceNotFoundStatus $path)
            }
            return
        }
        $fromConfirm = $false

        $found = findMovedSource $picked $location.Rest $book
        if ($found) {
            if ($found.Root -and (testSourceNameRecordable ([string]$location.Name))) {
                setIndexSourceFolder $location.Name $found.Root
                $script:sourceFolderMaps = @{}
                setStatus "インデックス [$($location.Name)] の元のフォルダを $($found.Root) に変えました"
            } else {
                setStatus "開きました：$($found.Path)"
            }
            & $onFound $found.Path
            return
        }
        $facts = @(
            (factGone "選んだフォルダの中にありませんでした" "選んだフォルダ：${picked}`n探したファイル：${relPath}"),
            (factNext "別のフォルダを選んで、もう一度探せます")
        )
        $initial = $picked
    }
}

function openWithShell {
    # ファイルを既定のアプリで開く。開き方（mode）は、エクスプローラーの右クリックメニューと同じ動詞で行う。
    #   読み取り専用 → OpenAsReadOnly、新規 → New（元のファイルを基にした無題の文書。元のファイルを占有しない）
    # その動詞が登録されていない種類のファイルは、そのまま開いて $false を返す
    # （noFallback のときは、そのまま開かずに $false を返す。もらったインデックスのマクロを持てる形式を、通常で開かないため）
    param (
        [string]$path,
        [string]$mode,
        [switch]$noFallback
    )

    $verb = switch ($mode) {
        ${openModeReadOnly} { "OpenAsReadOnly" }
        ${openModeNew}      { "New" }
        default             { $null }
    }
    if ($verb) {
        # Start-Process は [ ] をワイルドカードとして扱うため使わない。
        # ProcessStartInfo.Verbs は New を一覧に含めないため、実行してみて、無ければ例外で分かる
        $info = New-Object System.Diagnostics.ProcessStartInfo($path)
        $info.UseShellExecute = $true
        $info.Verb = $verb
        try {
            [void][System.Diagnostics.Process]::Start($info)
            return $true
        } catch [System.ComponentModel.Win32Exception] {
            # その動詞が登録されていない
        }
    }
    if ($noFallback) {
        return $false
    }
    Invoke-Item -LiteralPath $path
    return (-not $verb)
}

function openWithNotepad {
    # ファイルをメモ帳（固定のパス）で開く。.bat・.ps1・.js など、既定のアプリで開くと実行・登録になる拡張子はこちらを使う
    # （openWithShell・Invoke-Item は使わない。既定のアプリの登録がどうなっていても実行されない）。
    # メモ帳が無い（Windows 11 の「オプション機能」で外された等）・起動できないときは、既定のアプリには戻さずに $false を返す
    param (
        [string]$path
    )

    try {
        Start-Process -FilePath "$env:SystemRoot\System32\notepad.exe" -ArgumentList "`"${path}`""
        return $true
    } catch {
        return $false
    }
}

function setExcelAutomationSecurity {
    # Excel のマクロの扱い（AutomationSecurity）を設定し、前の値を返す。設定できなければ例外のまま外へ出す
    # （マクロが動く設定のまま開かないため。呼ぶ側が、ファイルを開くだけの道に切り替える）
    param (
        $excel,
        [int]$value
    )

    $previous = $excel.AutomationSecurity
    $excel.AutomationSecurity = $value
    return $previous
}

function openInExcel {
    # 表示中の Excel（無ければ新しく起動）でブックを開き、該当シートの該当セルを選択する。
    # 開き方（mode）: 通常 = そのまま開く / 読み取り専用 = ReadOnly で開く /
    #                 新規 = 元のファイルを基にした新しいブック（無題）として開く（元のファイルを占有しない）
    param (
        [string]$path,
        [string]$location,
        [string]$cell,
        [string]$mode = ${openModeNormal}
    )

    $excel = $null
    try {
        $excel = [System.Runtime.InteropServices.Marshal]::GetActiveObject("Excel.Application")
        # インデクサがバックグラウンドで使っている Excel は使わない
        if (!$excel.Visible) {
            $excel = $null
        }
    } catch {
        $excel = $null
    }
    if ($null -eq $excel) {
        $excel = New-Object -ComObject Excel.Application
        $excel.Visible = $true
        $excel.UserControl = $true
    }

    # プログラムから開いたときの Excel の既定はマクロ有効のため、開く間だけ Excel の設定に従う（msoAutomationSecurityByUI = 2。
    # 既定ではマクロを止めて警告する）にし、開き終えたら元の値に戻す（使っていた Excel の設定を変えたままにしない）
    # 設定できなければ例外のまま外へ出し、開かない（マクロが動く設定のまま開かないため。呼ぶ側が、ファイルを開くだけの道に切り替える）
    $previousSecurity = setExcelAutomationSecurity $excel 2
    $book = $null
    try {
        if ($mode -eq ${openModeNew}) {
            # 元のファイルをテンプレートとして新しいブックを作る（読み込んだ後は元のファイルを開いたままにしない）
            $book = $excel.Workbooks.Add($path)
        } else {
            # 既に開いているブックがあれば、そのまま使う（同じブックを二重に開けないため。開き方も既に開いたときのまま）
            foreach ($openBook in $excel.Workbooks) {
                if ($openBook.FullName -eq $path) {
                    $book = $openBook
                    break
                }
            }
            if ($null -eq $book) {
                #   引数: Filename, UpdateLinks, ReadOnly
                $book = $excel.Workbooks.Open($path, [Type]::Missing, ($mode -eq ${openModeReadOnly}))
            }
        }
    } finally {
        try { $excel.AutomationSecurity = $previousSecurity } catch { }
    }
    $book.Activate()

    # 場所はシート名（ワークシート・グラフシートの両方）。名前が同じシートを選ぶ。
    # 以前の版のインデックスは、ファイル名に使えない文字を全角に置き換えてあるため、同じ名前のシートが無ければ
    # 全角に置き換えて一致するシートを選ぶ（`衝突"` と `衝突”` のように、置き換えると重なるシートがあるため、同じ名前を優先する）。
    # `Sheets` はワークシート・グラフシートを表示順のまま 1 つの列で回せるため、同じ名前の一致が
    # 全角に置き換えた一致より先に見つかるよう、両方の種類を 1 回のループで調べる（グラフシートはセルを選べない）。
    # グラフシートかどうかは `Charts` コレクションの名前で判定する（`Sheets` の要素の `Type` は、グラフシートでは
    # 期待どおりの値（xlChart）にならない。実機で確かめると、既定のグラフの種類の値が返ることがある）
    $chartNames = New-Object System.Collections.Generic.HashSet[string]
    foreach ($chart in $book.Charts) { [void]$chartNames.Add($chart.Name) }

    $target = $null
    $sameSafeName = $null
    $isChartSheet = $false
    $sameSafeIsChartSheet = $false
    foreach ($sheet in $book.Sheets) {
        $isChart = $chartNames.Contains($sheet.Name)
        if ($sheet.Name -eq $location) {
            $target = $sheet
            $isChartSheet = $isChart
            break
        }
        if ($null -eq $sameSafeName -and (toSafeFileName $sheet.Name) -eq $location) {
            $sameSafeName = $sheet
            $sameSafeIsChartSheet = $isChart
        }
    }
    if ($null -eq $target -and $null -ne $sameSafeName) {
        $target = $sameSafeName
        $isChartSheet = $sameSafeIsChartSheet
    }
    if ($null -ne $target) {
        $target.Activate()
        if ($cell -and -not $isChartSheet) {
            $target.Range($cell).Select()
        }
    }
    if ($excel.WindowState -eq -4140) {
        # 最小化されていれば元に戻す（xlMinimized → xlNormal）
        $excel.WindowState = -4143
    }
    # Excel は Visible にして前面に出す（P/Invoke の SetForegroundWindow は実行時コンパイル（csc.exe）を無くすため廃止）
    $excel.Visible = $true
    try { $excel.ActiveWindow.Activate() } catch { }
}

function getOpenMode {
    # ダブルクリック・Enter・［開く］での開き方（${openModes} のいずれか。選んでいなければ通常）
    if ($null -ne $script:openMode -and (${openModes} -contains $script:openMode)) {
        return [string]$script:openMode
    }
    return ${openModeNormal}
}

function setOpenMode {
    # 既定の開き方を設定の値に合わせる（起動時。選んだことにはしないため、設定は保存しない）
    param (
        [string]$mode
    )

    $script:openMode = if (${openModes} -contains $mode) { $mode } else { ${openModeNormal} }
}

function setContextMenuItems {
    # 右クリックメニューを、判断層が決めた並び（@{ Id; Header; Bold } の並び）で組み直す。
    # parts は Id → 項目（MenuItem）の表。区切りは Id が "separator"。ここでは並べるだけで、並び・文言・太字は決めない
    param (
        $menu,
        $items,
        $parts
    )

    $menu.Items.Clear()
    foreach ($item in $items) {
        if ($item.Id -eq "separator") {
            [void]$menu.Items.Add((New-Object System.Windows.Controls.Separator))
            continue
        }
        $menuItem = $parts[$item.Id]
        $menuItem.Header = $item.Header
        $menuItem.FontWeight = $(if ($item.Bold) { [System.Windows.FontWeights]::Bold } else { [System.Windows.FontWeights]::Normal })
        [void]$menu.Items.Add($menuItem)
    }
}

function selectResultRowForMenu {
    # 右クリックした行を選んでからメニューを出す（選んでいる別の行にメニューが効かないようにする）。
    # 行（ヒットした行）を複数選んでいて、その中の行を右クリックしたときだけ、選びを変えない（［選んだ行をコピー］のため）。
    # 見出しや、見出しを含む選びのときは、右クリックした行だけを選ぶ。メニューの種類も押したときの対象も、この選びで決まる
    param (
        $row
    )

    if (!(testResultMenuKeepSelection $row.IsSelected $row.Item @($ui.ResultGrid.SelectedItems))) {
        $ui.ResultGrid.SelectedItem = $row.Item
    }
}

function showResultMenu {
    # 結果の右クリックメニューを組み直す。出してよければ $true（行の無い所では $false）。
    # cursorLeft が負のときはキーボードで開いたとき（選んでいる行に出す）
    param (
        $source,
        [double]$cursorLeft
    )

    if ($cursorLeft -ge 0 -and $null -eq (getDataGridRowAt $source)) {
        return $false
    }
    $item = $ui.ResultGrid.SelectedItem
    if ($null -eq $item) {
        return $false
    }

    $context = getResultMenuContext $item
    $parts = @{
        openNormal = $ui.MenuOpen; openNew = $ui.MenuOpenNew; openReadOnly = $ui.MenuOpenReadOnly; openFolder = $ui.MenuOpenFolder
        copyRows = $ui.MenuCopy; copyPath = $ui.MenuCopyPath; toggleGroup = $ui.MenuToggleGroup
    }
    # 読み取り専用で開けるのは Office の形式だけ（それ以外のファイルでは［読み取り専用で開く］を出さない）
    setContextMenuItems $ui.ResultMenu (getResultMenuItems $context.Target (getOpenMode) $context.Expanded (testReadOnlySupported $item.Book)) $parts
    return $true
}

function openSource {
    # 選択行の元のファイルを開く。mode で開き方（通常・読み取り専用・新規）を指定する。
    # 元のファイルがネットワークにあれば、見つかるまで（または見つからない・接続できないと分かるまで）画面のスレッドは待たない
    param (
        [string]$mode = (getOpenMode)
    )

    $row = getCurrentHitRow
    if ($null -eq $row) {
        return
    }
    # 呼ぶ関数は変数で捕まえてから閉じ込める（findSourceFile の $apply と同じ理由）
    $openFound = ${function:openFoundSource}
    findSourceFile $row {
        param ($path, $name)
        & $openFound $path $row $mode $name
    }.GetNewClosure()
}

function finishOpenCopy {
    # 裏の仕事で作った、新規で開くためのコピーを開く（openFoundSource の続き。画面のスレッドで動く）
    #   copyPath: コピーのパス（作れなかったときは空）
    #   reason: 作れなかった理由（copySourceForOpen の Reason）
    param (
        [string]$path,
        [bool]$isText,
        [string]$copyPath,
        [string]$reason = ""
    )

    $window.Cursor = $null
    if (!$copyPath) {
        setStatus (getOpenCopyFailedStatus $path $reason)
        return
    }
    if ($isText -and (testTextOpenWithNotepad $copyPath)) {
        if (openWithNotepad $copyPath) {
            setStatus (getOpenCopyOpenedStatus $path $copyPath "メモ帳")
        } else {
            setStatus "メモ帳で開けませんでした：${path}"
        }
    } else {
        [void](openWithShell $copyPath ${openModeNormal})
        setStatus (getOpenCopyOpenedStatus $path $copyPath)
    }
}

function openFoundSource {
    # findSourceFile が見つけたファイルを開く（openSource の続き）
    param (
        [string]$path,
        $row,
        [string]$mode,
        [string]$indexName = ""   # 元のファイルを見つけたインデックスの名前（findSourceFile が渡す）
    )

    # もらったインデックス（このワークスペースで自分が作ったのではないもの）のマクロを持てる形式は、読み取り専用で開く
    $received = testSourceReceived $indexName @((getConfirmedSourceNames).Crawled)
    $openMode = getSourceOpenMode $path $mode $received
    $mode = $openMode.Mode
    $strict = $openMode.Strict
    $notice = if ($openMode.Notice) { "（$($openMode.Notice)）" } else { "" }

    $how = switch ($mode) {
        ${openModeReadOnly} { "読み取り専用で開きました" }
        ${openModeNew}      { "新規で開きました" }
        default             { "開きました" }
    }
    $fallback = switch ($mode) {
        ${openModeReadOnly} { "読み取り専用で開けなかったため、元のファイルを開きました" }
        default             { "新規で開けなかったため、元のファイルを開きました" }
    }

    if ($mode -eq ${openModeNew} -and (getOpenNewMethod $row.Book) -eq "Copy") {
        # 「新規」の開き方が無い種類（テキスト・PDF・そのほか）は、元のファイルのコピーを作って開く（元のファイルを占有しない）。
        # コピーは、テキストはメモ帳の判断、そのほかは既定のアプリで開く（マクロを持てる形式は Office のため、ここには来ない）
        # コピーはファイルに触るため、裏の仕事で作り、できたら画面のスレッドで開く（元のファイルがネットワークにあっても画面を止めない）
        $copyDir = [string](getOpenCopyDir $workspace)
        $tmpRoot = [string]$workspace.TmpRoot
        $isText = [bool]$row.IsText
        # 名前だけで分かる断りは、コピーの仕事を始める前にステータスで知らせる（長すぎる）
        $blocker = getOpenCopyBlocker $row.Book $copyDir
        if ($blocker) {
            setStatus (getOpenCopyFailedStatus $path $blocker)
            return
        }
        $window.Cursor = [System.Windows.Input.Cursors]::AppStarting
        setStatus "コピーを作っています：${path}"
        # 呼ぶ関数は変数で捕まえてから閉じ込める（遠く離れたスレッド・タイマーから呼ばれても見つかるように）
        $finish = ${function:finishOpenCopy}
        startJob {
            param ($sourcePath, $book, $copyDir, $tmpRoot)
            copySourceForOpen $sourcePath $book $copyDir $tmpRoot
        } @($path, $row.Book, $copyDir, $tmpRoot) {
            param ($output, $errorText)
            $copied = if ($errorText) { @{ Path = ""; Reason = "Failed" } } else { $output[0] }
            & $finish $path $isText ([string]$copied.Path) ([string]$copied.Reason)
        }.GetNewClosure() (getWorkspaceJobQueue @([System.IO.Path]::GetDirectoryName($path), $copyDir))
    } elseif ($row.IsExcel) {
        setStatus "Excel で開いています：${path}"
        $window.Cursor = [System.Windows.Input.Cursors]::Wait
        try {
            # 図形・コメントの場所（"<シート名>[図形]" 等）は、そのシートの図形の左上・コメントのセルを選ぶ
            openInExcel $path (splitObjectPlace $row.Location).Base $row.MatchCell $mode
            setStatus "${how}：${path}${notice}"
        } catch {
            # Excel を操作できない場合（ダイアログを表示中など）は、ファイルを開くだけにする
            if (openWithShell $path $mode -noFallback:$strict) {
                setStatus "${how}（該当セルへの移動はできませんでした）：${path}${notice}"
            } elseif ($strict) {
                setStatus (getSourceReadOnlyFailedStatus $path)
            } else {
                setStatus "${fallback}（該当セルへの移動はできませんでした）：${path}"
            }
        } finally {
            $window.Cursor = $null
        }
    } elseif ($row.IsText) {
        # テキストは既定のアプリに開き方（読み取り専用・新規）の動詞が無いことが多く、毎回「開けなかったため…」と出るのを避けるため、
        # 動詞を試さずにそのまま開く（openWithShell に通常の開き方を渡すと動詞を試さない）。行への移動はしない。
        # .bat・.ps1・.js など、既定のアプリで開くと実行・登録になる拡張子はメモ帳で開く
        if (testTextOpenWithNotepad $path) {
            if (openWithNotepad $path) {
                setStatus "メモ帳で開きました：${path}"
            } else {
                setStatus "メモ帳で開けませんでした：${path}"
            }
        } else {
            [void](openWithShell $path ${openModeNormal})
            setStatus "開きました：${path}"
        }
    } elseif (testPdfExtension $path) {
        # PDF は既定のアプリに開き方（読み取り専用・新規）の動詞が無いことが多く、毎回「開けなかったため…」と出るのを避けるため、
        # 動詞を試さずにそのまま開く。ページへの移動はしない
        [void](openWithShell $path ${openModeNormal})
        setStatus "開きました：${path}"
    } elseif (openWithShell $path $mode -noFallback:$strict) {
        setStatus "${how}：${path}${notice}"
    } elseif ($strict) {
        setStatus (getSourceReadOnlyFailedStatus $path)
    } else {
        setStatus "${fallback}：${path}"
    }
}

function openSourceFolder {
    $row = getCurrentHitRow
    if ($null -eq $row) {
        return
    }
    findSourceFile $row {
        param ($path)
        Start-Process -FilePath "explorer.exe" -ArgumentList "/select,`"${path}`""
    }
}

function copySelectedRows {
    $rows = getSelectedRows
    if ($rows.Count -eq 0) {
        return
    }
    $result = toSearchResultLines $rows
    $text = ((@($result.Header) + $result.Lines.ToArray()) -join "`r`n") + "`r`n"
    [System.Windows.Clipboard]::SetText($text)
    setStatus "$($rows.Count) 行をコピーしました（Excel に貼り付けると、元の列の位置に並びます）"
}

function copySourcePath {
    # 元のファイルのパスをクリップボードに写す。元の場所の対応を読む必要があるときは、ネットワークの場所なら裏で読む
    $row = getCurrentHitRow
    if ($null -eq $row) {
        return
    }
    $requestBox = $script:copySourceRequest
    $requestBox.Value++
    $requestId = $requestBox.Value
    $pendingRowBox = $script:copySourcePendingRow
    $complete = ${function:completeCopySourcePath}
    findSourceLocationAsync $row {
        param ($location)
        & $complete $row $location
    }.GetNewClosure() $requestBox $requestId $pendingRowBox
}

function setClipboardText {
    param (
        [string]$text
    )

    [System.Windows.Clipboard]::SetText($text)
}

function completeCopySourcePath {
    # copySourcePath の続き。場所が分かったので、パスを写す
    param (
        $row,
        $location
    )

    $path = $null
    if ($location.Known) {
        $path = joinSourcePath $location.Folder $location.Rest $row.Book
    }
    if (!$path) {
        # 元のファイルの場所が分からない（インデックスだけを別の PC にコピーした等）ときは、インデックスの中の位置（フォルダ\元のファイル名）を写す
        $path = if ($row.RelDir) { "$($row.RelDir)\$($row.Book)" } else { $row.Book }
    }
    setClipboardText $path
    setStatus "パスをコピーしました：${path}"
}

function exportResults {
    if ($null -eq $script:lastSearch) {
        setStatus "先に検索してください。"
        return
    }
    $rows = getViewRows
    hideNoticeBanner "SearchNotice"
    try {
        [System.IO.Directory]::CreateDirectory($workspace.Dir) | Out-Null
        $writer = New-Object System.IO.StreamWriter($workspace.ResultFile, $false, ${utf8Bom})
        try {
            writeSearchResult $writer $script:lastSearch.Word $rows
        } finally {
            $writer.Close()
        }
    } catch [System.IO.IOException] {
        $message = getResultSaveFailedText "Locked" $workspace.ResultFile
        setStatus $message
        showNoticeBanner "SearchNotice" "ResultSaveFailed" $message
        return
    } catch [System.UnauthorizedAccessException] {
        # 読み取り専用・書き込み権限が無いときは、アプリを閉じても直らないため別の文言にする
        $message = getResultSaveFailedText "Denied" $workspace.ResultFile
        setStatus $message
        showNoticeBanner "SearchNotice" "ResultSaveFailed" $message
        return
    }
    Invoke-Item -LiteralPath $workspace.ResultFile
    if ($rows.Count -lt $script:hitCount) {
        setStatus "絞り込み後の $($rows.Count.ToString('N0')) 件を search_results.txt に出力しました"
    } else {
        setStatus "search_results.txt に出力しました（$($rows.Count.ToString('N0')) 件）"
    }
}

$ui.ResultGrid.Add_MouseDoubleClick({
    param ($sender, $e)
    # 行の上でのダブルクリックだけを対象にする（列見出し・スクロールバーは除く）。
    # 見出しの行は、クリックで閉じる・開く（result_list.ps1）ので、ダブルクリックでは開かない
    $row = getDataGridRowAt $e.OriginalSource
    if ($row -and !($row.Item -is [FileGroup])) {
        safe { openSource }
    }
})
$ui.ResultGrid.Add_PreviewKeyDown({
    param ($sender, $e)
    if ($e.Key -eq "Return") {
        # 見出しの行では閉じる・開く。行では元のファイルを開く
        safe {
            if ($ui.ResultGrid.SelectedItem -is [FileGroup]) {
                toggleFileGroup $ui.ResultGrid.SelectedItem
            } else {
                openSource
            }
        }
        $e.Handled = $true
    } elseif ($e.Key -eq "C" -and [System.Windows.Input.Keyboard]::Modifiers -eq "Control") {
        safe { copySelectedRows }
        $e.Handled = $true
    }
})
