# ［検索］タブの、検索対象インデックスのツリー。


# ---- 検索対象インデックスのツリー ----

$script:indexRoots = New-Object 'System.Collections.ObjectModel.ObservableCollection[object]'
$ui.IndexTree.ItemsSource = $script:indexRoots

$script:indexTreeRequest = @{ Value = 0 }   # ツリーの読み込みの依頼番号（新しい依頼が出たら、前の依頼の結果は捨てる）
$script:indexTreeLoading = $false           # 検索対象のツリーを読み込んでいる最中か（ネットワークのとき、裏で読む間）
$script:indexTreeConnectError = ""          # ワークスペースに接続できなかったときの、そのワークスペース（できたなら空）
$script:indexTreeKeepStatus = $false        # 次に届くツリーの結果で、接続できない旨をステータスに書かない（先に出した失敗の知らせを残す。1 回で戻る）

function loadIndexTree {
    # インデックスの一覧（getIndexTreeData）をツリーに読み込む。一番上の項目がインデックス 1 件で、
    # ［インデックス管理］で作ったインデックスがすべて並ぶ。
    # 保存したチェックなしのフォルダと、読み込み前の展開の状態は戻す。
    # ワークスペースがネットワークの場所のときは、画面のスレッドで読まず、裏の列（network）で読んでから反映する
    $expanded = New-Object 'System.Collections.Generic.List[string]'
    foreach ($node in $script:indexRoots) {
        $node.AddExpanded($expanded)
    }
    $paths = @($expanded.ToArray()) + @(readSearchExcludes | ForEach-Object { [string]$_.Path })

    $requestBox = $script:indexTreeRequest
    $requestBox.Value++
    $requestId = $requestBox.Value
    $dir = $workspace.IndexDir
    $statusPath = $workspace.StatusFile
    $settingsPath = ${settingsFile}
    $expandedPaths = $expanded.ToArray()

    if (!(testNetworkPath $dir)) {
        applyIndexTreeData (getIndexTreeData $dir $statusPath $settingsPath $paths) $expandedPaths
        return
    }

    $script:indexRoots.Clear()
    $script:indexTreeLoading = $true
    $script:indexTreeConnectError = ""
    updateSearchTarget
    $otherState = ${pathStateOther}
    $applyData = ${function:applyIndexTreeData}   # 終わったときの処理は、関数を変数に取って呼ぶ（クロージャからは関数の名前を引けないため）
    startJob {
        param ($dir, $statusPath, $settingsPath, $paths)
        getIndexTreeData $dir $statusPath $settingsPath $paths
    } @($dir, $statusPath, $settingsPath, [string[]]$paths) {
        param ($output, $errorText)
        if ($requestId -ne $requestBox.Value) {
            # 待っている間に、読み込みをやり直した。前の依頼は捨てる
            return
        }
        if ($errorText -or !$output -or $output.Count -eq 0) {
            & $applyData @{ State = $otherState; Message = [string]$errorText } $expandedPaths
        } else {
            & $applyData $output[0] $expandedPaths
        }
    }.GetNewClosure() (getWorkspaceJobQueue $dir)
}

function applyIndexTreeChildren {
    # getIndexTreeData が集めた子（フォルダ → getIndexFolderChildren の結果）を、ノードの下に再帰して入れる
    param (
        [IndexNode]$node,
        [hashtable]$children
    )

    $key = $node.FullPath()
    if (!$children.ContainsKey($key)) {
        return
    }
    if ($node.NeedsLoad()) {
        if ($children[$key].Error) { return }
        $node.ApplyChildren($children[$key])
    }
    foreach ($child in @($node.Children)) {
        if (!$child.IsPlaceholder -and !$child.IsFiles) {
            applyIndexTreeChildren $child $children
        }
    }
}

function applyIndexTreeData {
    # getIndexTreeData の結果をツリーに反映する（読み込み口。画面のスレッドで呼ぶ）。
    # 接続できない・その他のときは、ツリーを空にして、ステータスに知らせる
    param (
        $data,
        [string[]]$expanded = @()
    )

    $keepStatus = [bool]$script:indexTreeKeepStatus
    $script:indexTreeKeepStatus = $false
    $script:indexTreeLoading = $false
    $script:indexTreeConnectError = ""
    $script:indexRoots.Clear()
    if ($data.State -eq ${pathStateUnreachable} -or $data.State -eq ${pathStateOther}) {
        $script:indexTreeConnectError = [string]$workspace.Dir
        if (!$keepStatus) {
            setStatus (getWorkspaceUnreachableText $workspace.Dir)
        }
        updateSearchTarget
        return
    }

    $root = [string]$data.Root
    $script:sourceFolderMaps[$root.TrimEnd("\")] = $data.Sources
    foreach ($index in @($data.Indexes)) {
        $sourcePath = if ($index.SourcePath) { $index.SourcePath } else { $null }
        $node = [IndexNode]::CreateRoot($root, $index.Name, $index.Name, $sourcePath, [bool]$index.Exists, [bool]$index.HasSubfolders)
        applyIndexTreeChildren $node $data.Children
        $script:indexRoots.Add($node)
    }

    foreach ($exclude in @(readSearchExcludes)) {
        foreach ($node in $script:indexRoots) {
            $node.ApplyExclude($exclude.Path, $exclude.Subfolders)
        }
    }
    foreach ($node in $script:indexRoots) {
        foreach ($path in $expanded) {
            $found = $node.Find($path)
            if ($found) {
                $found.SetExpanded($true)
            }
        }
    }
    updateSearchTarget
}

function expandIndexNode {
    # フォルダを展開したときに、子を読み込む。ネットワークの場所なら、裏の列（network）で読む間は「読み込み中…」を出しておく。
    # 読めなかったときは、フォルダを閉じて読み込み前の状態に戻し（「読み込み中…」を見せ続けない。もう一度開けば読み直す）、ステータスに知らせる
    param (
        [IndexNode]$node
    )

    if (!$node.NeedsLoad() -or $node.IsLoading) {
        return
    }
    $dir = $node.FullPath()
    if (!(testNetworkPath $dir)) {
        applyIndexFolderChildren $node (getIndexFolderChildren $dir)
        return
    }

    $node.IsLoading = $true
    $requestBox = $script:indexTreeRequest
    $generation = $requestBox.Value
    $applyChildren = ${function:applyIndexFolderChildren}
    startJob {
        param ($dir)
        getIndexFolderChildren $dir
    } @($dir) {
        param ($output, $errorText)
        $node.IsLoading = $false
        if ($generation -ne $requestBox.Value) {
            # ツリーを読み込み直した。このノードはもう画面に無い
            return
        }
        if ($errorText -or !$output -or $output.Count -eq 0) {
            & $applyChildren $node @{ Error = $(if ($errorText) { [string]$errorText } else { "結果がありません" }) }
            return
        }
        & $applyChildren $node $output[0]
    }.GetNewClosure() (getWorkspaceJobQueue $dir)
}

function applyIndexFolderChildren {
    # expandIndexNode の続き。子を入れる（読めなかったときは、フォルダを閉じて読み込み前に戻し、ステータスに知らせる）
    param (
        [IndexNode]$node,
        $data
    )

    if ($data.Error) {
        $node.SetExpanded($false)
        setStatus (getTreeFolderFailedText $node.Name ([string]$data.Error))
        return
    }
    $node.ApplyChildren($data)
    updateSearchTarget
}

function getSearchTargets {
    # 検索対象ツリーでチェックしたフォルダ（SearchTarget の配列。getContentIndexFiles に渡す）
    $targets = New-Object 'System.Collections.Generic.List[SearchTarget]'
    foreach ($node in $script:indexRoots) {
        $node.AddTargets($targets)
    }
    return $targets.ToArray()
}

function isAllIndexChecked {
    return @($script:indexRoots | Where-Object { $_.IsChecked -ne $true }).Count -eq 0
}

function describeSearchTargets {
    # 検索対象の表示（先頭の 3 件まで）。インデックスのフォルダ（work\index）からの相対パスは
    # 「インデックス名\その下のフォルダ」のため、そのまま表示に使う
    param (
        [object[]]$targets
    )

    $names = @($targets | ForEach-Object {
        $target = $_
        $name = ([string]$target.RelPath).Trim("\")
        if (!$target.Recurse) {
            $name += "（直下のファイル）"
        }
        $name
    })
    if ($names.Count -gt 3) {
        return "$($names[0..2] -join '、') ほか $($names.Count - 3) か所"
    }
    return $names -join "、"
}

function saveSearchExcludes {
    # チェックなしのフォルダを設定に保存する。見つからないインデックスのフォルダ（ネットワークのドライブが切れているなど）の記録は残す
    $excludes = New-Object 'System.Collections.Generic.List[SearchExclude]'
    foreach ($node in $script:indexRoots) {
        $node.AddExcludes($excludes)
    }
    $roots = @($script:indexRoots | Where-Object { $_.Exists } | ForEach-Object { $_.FullPath().TrimEnd("\") })
    $kept = @(readSearchExcludes | Where-Object {
        $path = $_.Path
        @($roots | Where-Object { testFolderOrUnder $path $_ }).Count -eq 0
    })
    writeSearchExcludes (@($kept) + @($excludes.ToArray()))
}

function onIndexTreeChecked {
    saveSearchExcludes
    updateSearchTarget
}

function setAllIndexChecked {
    param (
        [bool]$checked
    )

    foreach ($node in $script:indexRoots) {
        $node.SetChecked($checked)
    }
    onIndexTreeChecked
}

# ツリーのチェックボックスのクリック。チェックは OneWay バインドのため、クリックされたノードの Toggle() で
# 3状態（子・親への伝播）を反映してから保存する（PS class はセッターにロジックを書けないため、ここで行う）
$ui.IndexTree.AddHandler([System.Windows.Controls.Primitives.ButtonBase]::ClickEvent, [System.Windows.RoutedEventHandler] {
    param ($s, $e)
    safe {
        $cb = $e.OriginalSource
        if ($cb -is [System.Windows.Controls.CheckBox] -and $cb.DataContext -is [IndexNode]) {
            $cb.DataContext.Toggle()
            onIndexTreeChecked
        }
    }
})
# フォルダを展開したときに子を読み込む（IsExpanded は OneWay/プレーンなので、ここで expandIndexNode する）
$ui.IndexTree.AddHandler([System.Windows.Controls.TreeViewItem]::ExpandedEvent, [System.Windows.RoutedEventHandler] {
    param ($s, $e)
    safe {
        $node = $e.OriginalSource.DataContext
        if ($node -is [IndexNode]) { expandIndexNode $node }
    }
})
$ui.IndexTree.Add_PreviewKeyDown({
    param ($sender, $e)
    # スペースで選択中のフォルダのチェックを切り替える
    $node = $ui.IndexTree.SelectedItem
    if ($e.Key -eq "Space" -and $node -and !$node.IsPlaceholder) {
        safe {
            $node.Toggle()
            onIndexTreeChecked
        }
        $e.Handled = $true
    }
})
$ui.CheckAllIndexButton.Add_Click({ safe { setAllIndexChecked $true } })
$ui.UncheckAllIndexButton.Add_Click({ safe { setAllIndexChecked $false } })

# ワークスペースの中を調べる処理のうち、起動と切り替えで使うもの。
# ワークスペースが届かないネットワークの場所にあっても画面が止まらないよう、ネットワークの場所なら裏の列（network）で調べる。

$script:legacyIndexMessage = ""               # 前の版のインデックスが見つかったときの知らせ（無ければ空）
$script:legacyIndexRequest = @{ Value = 0 }   # 調べの依頼番号（新しい依頼が出たら、前の依頼の結果は捨てる）

function testStartupIndexExists {
    # 起動時の画面を選ぶために、インデックスがあるかを調べる。
    # ネットワークの場所は、画面のスレッドで調べない（届かないと止まる）。ある前提で［検索］を開き、
    # 中身の有無は［検索］の画面が裏で調べる
    param (
        [string]$dir
    )

    if (testNetworkPath $dir) {
        return $true
    }
    return (testIndexExists)
}

function applyLegacyIndexMessage {
    # 前の版のインデックスの知らせを覚えて、あればステータスに出す（起動時に別の知らせを出しているときは出さない）
    param (
        [string]$message
    )

    $script:legacyIndexMessage = $message
    if ($message -and !$script:workspaceBlock) {
        setStatus $message
    }
}

function refreshLegacyIndexMessage {
    # 今のワークスペースに前の版のインデックスがあるかを調べ、知らせを $script:legacyIndexMessage に入れる。
    # ローカルの場所はこの場で調べる。ネットワークの場所は裏の列で調べ、分かったらステータスに出す
    $dir = [string]$workspace.Dir
    $script:legacyIndexMessage = ""
    $requestBox = $script:legacyIndexRequest
    $requestBox.Value++
    $requestId = $requestBox.Value

    if (!(testNetworkPath $dir)) {
        $script:legacyIndexMessage = getLegacyIndexMessage $dir (getLegacyIndexState $dir).HasLegacyIndex
        return
    }

    $apply = ${function:applyLegacyIndexMessage}   # 終わったときの処理は、関数を変数に取って呼ぶ（クロージャからは関数の名前を引けないため）
    startJob {
        param ($dir)
        getLegacyIndexMessage $dir (getLegacyIndexState $dir).HasLegacyIndex
    } @($dir) {
        param ($output, $errorText)
        if ($requestId -ne $requestBox.Value -or $errorText -or !$output -or $output.Count -eq 0) {
            # 待っている間にワークスペースを切り替えた・調べられなかった。知らせは出さない
            return
        }
        & $apply ([string]$output[0])
    }.GetNewClosure() (getWorkspaceJobQueue $dir)
}

# 設定の画面（ワークスペース・設定ファイルの場所。xaml\settings\settings.xaml）。文言と可否の判定は settings_view.ps1。

${workspaceCountLimit} = 1000      # 選んだフォルダの中身を数える上限（大きなフォルダで待たせない）

function updateSettingsView {
    # ワークスペースと設定ファイルの場所を表示する
    $view = getWorkspaceView $workspace.Dir (getDefaultWorkDir)
    $ui.WorkspaceBox.Text = $view.Path
    $ui.WorkspaceBox.ToolTip = $view.Path  # 長いパスは欄に入りきらないため、全体はツールチップで見せる
    setWorkspaceInputError ""
    $ui.WorkspaceNote.Text = $view.Note
    $caution = getWorkspaceCautionTexts
    $ui.WorkspaceCaution.Text = $caution.Caution
    $ui.WorkspaceHowTo.Text = $caution.HowTo
    $ui.ResetWorkspaceButton.Visibility = if ($view.CanReset) { "Visible" } else { "Collapsed" }

    $file = getSettingsFileView ${settingsFile} ${rootDir}
    $ui.SettingsFileText.Text = $file.Path
    $ui.SettingsFileText.ToolTip = $file.Path
    $ui.SettingsFileNote.Text = $file.Note
}

function testWorkspaceChangeable {
    # インデックス作成中（インデクサが今のワークスペースに書いている。画面を使わずに起動したものも含む）・
    # 前のインデックスの削除中・エクスポート・インポート中（別スレッド。今のワークスペースの content_index・取り込み一覧・設定を使っている）は、
    # ワークスペースを変えない。可否と文言は、インデックス管理の操作と同じ判断層（getIndexJobBlocker・getIndexJobBlockedMessage）で決める
    $blocker = getCurrentIndexJobBlocker (testIndexerRunning)
    if ($blocker -ne "") {
        showMessage (getIndexJobBlockedMessage $blocker "ワークスペースの変更") "OK" "Warning" | Out-Null
        return $false
    }
    return $true
}

function invokeWorkspaceChange {
    # ワークスペースを変える 3 つの入口（［変更…］・［既定に戻す］・欄の入力）を、同時に 1 つしか走らせない。
    # 確認の画面を出している間に、欄から出た知らせやボタンの押下が重なって、確認が 2 枚出たり、古い状態の確かめのまま進んだりしない
    param ([scriptblock]$change)
    if ($script:workspaceCommitting) {
        return
    }
    $script:workspaceCommitting = $true
    try {
        & $change
    } finally {
        $script:workspaceCommitting = $false
    }
}

function chooseWorkspace {
    # ［変更…］。空のフォルダを選んで、ワークスペースにする（空でなければ警告する）
    invokeWorkspaceChange {
        try {
            if (!(testWorkspaceChangeable)) {
                return
            }
            $folder = selectFolder "ワークスペースにする空のフォルダを選んでください。インデックス・ログをここに置きます。" $workspace.Dir
            if ($null -eq $folder) {
                return
            }
            applyWorkspace $folder $true
        } finally {
            # どの終わり方でも、入力途中の文字と知らせを消し、欄を今の場所に戻す（切り替えたときは新しい場所）
            $ui.WorkspaceBox.Text = $workspace.Dir
            setWorkspaceInputError ""
        }
    }
}

function setWorkspaceInputError {
    # ワークスペースの欄の下に、直してほしい内容を出す（空なら隠す）
    param ([string]$message)
    $ui.WorkspaceInputError.Text = $message
    $ui.WorkspaceInputError.Visibility = if ($message) { "Visible" } else { "Collapsed" }
}

function commitWorkspaceInput {
    # 欄に入力したパスを確定する。確かめ・確認・切り替えは、［変更…］で選んだときと同じ applyWorkspace を通す。
    # 直してほしいときは欄の下に理由を出し、欄の文字は直せるように残す（$keepText。Enter のとき）。欄から出たときは今の場所に戻す
    param ([bool]$keepText)
    invokeWorkspaceChange { commitWorkspaceInputCore $keepText }
}

function commitWorkspaceInputCore {
    param ([bool]$keepText)
    $current = $workspace.Dir
    $text = $ui.WorkspaceBox.Text
    if ($text -ceq $current) {
        setWorkspaceInputError ""
        return
    }
    # 更新中などは反映しない（判断層が Blocked で返す。理由は［変更…］と同じ文言）。
    # 欄から出たときは、割り込まないよう、メッセージを出さず今の場所に戻す。Enter のときは、理由を欄の下に出し、入力した文字は残す
    $blocker = getCurrentIndexJobBlocker (testIndexerRunning)
    $blockedMessage = if ($blocker -ne "") { getIndexJobBlockedMessage $blocker "ワークスペースの変更" } else { "" }
    $decision = getWorkspaceInputDecision $text $current $null $null $blockedMessage
    if ($decision.Action -eq "None") {
        $ui.WorkspaceBox.Text = $current
        setWorkspaceInputError ""
        return
    }
    if ($decision.Action -eq "Invalid" -or $decision.Action -eq "Blocked") {
        if ($keepText) {
            setWorkspaceInputError $decision.Message
        } else {
            $ui.WorkspaceBox.Text = $current
            # 直してほしい入力の理由は、欄から出たあとも出しておく。更新中（Blocked）は割り込まないよう、出さない
            setWorkspaceInputError $(if ($decision.Action -eq "Invalid") { $decision.Message } else { "" })
        }
        return
    }
    setWorkspaceInputError ""
    try {
        applyWorkspace $decision.Path $true
    } finally {
        # どの終わり方でも、欄を今の場所に戻す（切り替えたときは updateSettingsView が新しい場所を入れる）
        $ui.WorkspaceBox.Text = $workspace.Dir
    }
}

function resetWorkspace {
    # ［既定に戻す］。既定の場所（ドキュメントの tebunko_ws）に戻す（無ければ作る）。ほかのファイルが置いてあれば戻さない
    invokeWorkspaceChange {
        try {
            if (!(testWorkspaceChangeable)) {
                return
            }
            $folder = getDefaultWorkDir
            $check = testDefaultWorkspace $folder
            if (!$check.Usable) {
                showMessage $check.Message "OK" "Warning" | Out-Null
                return
            }
            try {
                [System.IO.Directory]::CreateDirectory($folder) | Out-Null
            } catch {
                # 作れなければ、書き込めないフォルダとして下の確認で伝える
            }
            applyWorkspace $folder $false
        } finally {
            # どの終わり方でも、入力途中の文字と知らせを消し、欄を今の場所に戻す（切り替えたときは新しい場所）
            $ui.WorkspaceBox.Text = $workspace.Dir
            setWorkspaceInputError ""
        }
    }
}

function getFolderEntrySample {
    # フォルダの中のファイル・フォルダを上限まで数え、先頭の名前を返す: @{ Count; Names; Capped }
    param (
        [string]$folder,
        [bool]$isDefaultWorkspace = $false   # 既定のワークスペースなら、設定ファイルと付いてできるファイルを数えない（getCountedEntryPaths）
    )

    $entries = getCountedEntryPaths (selectFirstEntries ([System.IO.Directory]::EnumerateFileSystemEntries((toLongPath $folder))) ${workspaceCountLimit}) $isDefaultWorkspace
    $count = $entries.Count
    $names = New-Object System.Collections.Generic.List[string]
    for ($i = 0; $i -lt [Math]::Min($count, ${workspaceSampleCount}); $i++) {
        $names.Add([System.IO.Path]::GetFileName($entries[$i]))
    }
    return @{ Count = $count; Names = $names.ToArray(); Capped = ($count -ge ${workspaceCountLimit}) }
}

function applyWorkspace {
    # 確かめてから、今のワークスペースの中身を移してワークスペースを保存し、画面をそのワークスペースに切り替える。
    # 選んだフォルダにインデックスなどがあれば、それを使う（中身は移さない）か、消して最初からやり直す（消してから移す）かを選ばせる
    param (
        [string]$folder,
        [bool]$requireEmpty   # 空のフォルダを求める（［変更…］）。空でなければ警告する
    )

    $check = testWorkspaceChoice $folder $workspace.Dir (testWritableFolder $folder)
    if ($check.Kind -eq "same") {
        setStatus "今と同じワークスペースです"
        return
    }
    if ($check.Kind -eq "error") {
        showMessage $check.Message "OK" "Warning" | Out-Null
        return
    }

    $folder = normalizeFolderPath $folder
    $entries = if ($requireEmpty) { getFolderEntrySample $folder (testSameFolder $folder (getDefaultWorkDir)) } else { @{ Count = 0; Names = @(); Capped = $false } }
    $sub = Join-Path $folder ${workspaceSubFolderName}
    $canMakeSub = -not (Test-Path -LiteralPath $sub) -or
        ((Test-Path -LiteralPath $sub -PathType Container) -and (getFolderEntrySample $sub).Count -eq 0)
    $mover = [WorkspaceMover]::new(${settingsFile})
    $workspaceNames = @($mover.ListEntries($folder) | ForEach-Object { [System.IO.Path]::GetFileName($_) })
    $confirm = newWorkspaceConfirm $folder $workspace.Dir $entries.Count $entries.Names $entries.Capped $workspaceNames $canMakeSub (!$requireEmpty)
    # switch の中の $_ は switch の値になるため、行を変数に受けてから使う
    $facts = @($confirm.Facts | ForEach-Object {
        $fact = $_
        switch ($fact.Kind) {
            "kept"  { factKept $fact.Title $fact.Detail }
            "warn"  { factWarn $fact.Title $fact.Detail }
            default { factNext $fact.Title $fact.Detail }
        }
    })
    $answer = showConfirm -title $confirm.Title -heading $confirm.Heading -facts $facts -hint $confirm.Hint -choices $confirm.Choices
    if ($null -eq $answer) {
        return
    }
    if ($answer -eq "sub") {
        [System.IO.Directory]::CreateDirectory($sub) | Out-Null
        if (-not (testWritableFolder $sub)) {
            showMessage "「${sub}」にはファイルを作れません。書き込めるフォルダを選んでください。" "OK" "Warning" | Out-Null
            return
        }
        $folder = $sub
    }

    # 本文インデックスのファイルを読んでいる検索があると移せないため、先に止める
    clearSearchView
    $previous = $workspace.Dir
    # 共有されたワークスペースなどを使う（use）・消して最初から（reset）・中身を移す（move）。保存まで WorkspaceMover が行う
    $mode = if ($answer -eq "use" -or $answer -eq "reset") { $answer } else { "move" }
    startWorkspaceMove $mode $previous $folder
}

function updateMainContentOperable {
    # 移している間は、ナビと中身を操作できなくする（マウス・Tab・Space など、中身の入口をまとめて止める。窓のキーは shell\window_events.ps1 の PreviewKeyDown）。
    # 終わったら必ず戻す（始められなかったとき・失敗のときも）
    $operable = testMainContentOperable ([bool]$script:workspaceMoving)
    $ui.NavHost.IsEnabled = $operable
    $ui.ContentHost.IsEnabled = $operable
}

function startWorkspaceMove {
    # 中身を移す・消す処理は、量によっては数十秒かかるため、裏のスレッドで行う（画面のスレッドで行うと「応答なし」になる）。
    # 動かしている間は待つ間のダイアログを出し、ほかの操作は止める（$script:workspaceMoving。getIndexJobBlocker が見る）。
    # 終わりの処理は finishWorkspaceMove（画面のスレッド）。閉じるのは、移し終わるまで待つ（shell\closing.ps1 の Closing）
    param (
        [string]$mode,       # "use"・"reset"・"move"（WorkspaceMover.ChangeWorkspace の mode）
        [string]$previous,
        [string]$folder
    )

    $script:workspaceMoving = $true
    $script:closeAfterWorkspaceMove = $false
    try {
        updateMainContentOperable
        updateIndexingButton
        setStatus "ワークスペースを「${folder}」へ移しています…"
        # ダイアログが出せなくても移動は続ける
        try { showIndexingWait "Moving" } catch { }
        # 裏のスレッドは lib.ps1 を読み込んだときの場所を覚えているため、場所は渡す。
        # 移動元と移動先のどちらかがネットワークの場所なら、届かない共有でほかの仕事を待たせない専用の列を使う
        # 終わったときの処理は、あとからタイマーで呼ばれる。この関数のローカル変数（$mode・$previous・$folder）は
        # GetNewClosure() で今の値を取り込み、関数は変数に取って & で呼ぶ（クロージャからは関数の名前を引けないため）
        $finish = ${function:finishWorkspaceMove}
        startJob {
            param ($mode, $previous, $folder, $settingsPath)
            # 届かない場所では、何もせずに成功にしない。失敗として返す（移動元は、使わない "use" のときは調べない）
            if ($mode -ne "use") {
                assertWorkspaceReachable $previous
            }
            assertWorkspaceReachable $folder
            $mover = [WorkspaceMover]::new($settingsPath)
            $mover.ChangeWorkspace($mode, $previous, $folder)
        } @($mode, $previous, $folder, ${settingsFile}) {
            param ($output, $errorText)
            & $finish $mode $previous $folder $output $errorText
        }.GetNewClosure() (getWorkspaceJobQueue @($previous, $folder))
    } catch {
        # 始められなかった。印を戻し、ダイアログを閉じて、元の画面に戻す
        $script:workspaceMoving = $false
        try { updateMainContentOperable } catch { }
        try { closeIndexingWait } catch { }
        try { updateIndexingButton } catch { }
        throw
    }
}

function finishWorkspaceMove {
    # 裏の移動が終わったときの、画面のスレッドでの後始末（成功・失敗とも）。どの終わり方でも、印を下ろしてダイアログを閉じる。
    # 成功のときだけ画面を切り替える。移している間に窓を閉じようとしていたなら、最後に閉じる
    param (
        [string]$mode,
        [string]$previous,
        [string]$folder,
        $output,
        [string]$errorText
    )

    $closeRequested = [bool]$script:closeAfterWorkspaceMove
    $script:workspaceMoving = $false
    $script:closeAfterWorkspaceMove = $false
    try { updateMainContentOperable } catch { }
    $outcome = @{ Ok = $false; Warning = "ワークスペースを移した結果を確かめられませんでした。"; Status = ""; Close = $false }
    try {
        $outcome = getWorkspaceMoveOutcome (getWorkspaceMoveChange $output) $errorText $closeRequested $mode $folder $previous
        try { closeIndexingWait } catch { }
        if ($outcome.Ok) {
            if (!$outcome.Close) {
                switchWorkspace
            }
            if ($outcome.Status -ne "") {
                setStatus $outcome.Status
            }
            return
        }
        $ui.WorkspaceBox.Text = $workspace.Dir
        updateIndexingButton
        # 失敗のときは閉じない（閉じるのを待っていても、失敗を知らせるために画面を残す）
        showMessage $outcome.Warning "OK" "Warning" | Out-Null
    } finally {
        try { closeIndexingWait } catch { }
        if ($outcome.Close) {
            $window.Dispatcher.BeginInvoke([action]{ $window.Close() }) | Out-Null
        }
    }
}

function switchWorkspace {
    # 設定のワークスペースに切り替える。画面は開き直さない。
    # 関数は既定値で $workspace の場所を使い、裏のスレッドには場所を渡しているため、$workspace を差し替えれば新しい場所を使う
    # （docs/design/structure/data.md「ワークスペースの中の場所（Workspace）」）。インデックス作成中・削除中は testWorkspaceChangeable が止めている
    clearSearchView
    initWorkspace
    $script:workspaceBlock = getWorkspaceBlockMessage
    updateWorkspaceBanner
    hideNoticeBanner "SearchNotice"
    hideNoticeBanner "IndexNotice"
    $script:indexingState = $null
    $script:indexSummary = $null
    resetIndexingBanner
    updateSettingsView
    loadWorkspaceViews
    # 前の版のインデックスの知らせ。ネットワークの場所は裏で調べるため、分かったときにステータスへ出す
    refreshLegacyIndexMessage
    if ($script:legacyIndexMessage) {
        setStatus $script:legacyIndexMessage
    } else {
        setStatus "ワークスペースを「$($workspace.Dir)」に切り替えました"
    }
}

# ---- イベント ----

$ui.WorkspaceBox.Add_KeyDown({
    param ($sender, $e)
    if ($e.Key -eq "Return") {
        safe { commitWorkspaceInput $true }
        $e.Handled = $true
    } elseif ($e.Key -eq "Escape") {
        safe { $ui.WorkspaceBox.Text = $workspace.Dir; setWorkspaceInputError "" }
        $e.Handled = $true
    }
})
# 欄から出た知らせの中で確認の画面を出すと、フォーカスを動かした側（操作を送ったもの）が待たされるため、知らせが終わってから確定する
$ui.WorkspaceBox.Add_LostFocus({
    $window.Dispatcher.BeginInvoke([action]{ safe { commitWorkspaceInput $false } }, [System.Windows.Threading.DispatcherPriority]::Background) | Out-Null
})
$ui.ChangeWorkspaceButton.Add_Click({ safe { chooseWorkspace } })
$ui.ResetWorkspaceButton.Add_Click({ safe { resetWorkspace } })

# ナビ下の「バージョン情報」と、そのダイアログ（画面層）。gui.ps1 が読み込む。
# 版・コミットの文字列は起動時に 1 回だけ組み立てる（gui.ps1 の $script:aboutView。ui/about_view.ps1 の getAboutView）。
# ダイアログを開くたびに VERSION.txt を読み直さない。

# ナビ下のリンク（Button の Click は、左クリックとキーボード（Enter・Space）の両方で発生する）
$ui.AboutLink.Add_Click({
    safe { showAboutDialog }
})

function openAboutLink {
    # リンクを既定のブラウザで開く（explorer.exe にアドレスを渡す）。getAboutLinks に載せたアドレス以外は開かない
    param (
        [string]$url
    )

    if (-not (testAboutLinkUrl $url)) {
        return
    }
    Start-Process -FilePath "explorer.exe" -ArgumentList "`"${url}`""
}

function showAboutDialog {
    # 「バージョン情報」ダイアログを開く
    $dialog = loadWindow "${xamlDir}\dialog_about.xaml"
    $dialog.Owner = $window
    $ctrl = @{}
    foreach ($name in @("AppIcon", "VersionText", "CommitText", "LicenseText", "GitHubLink", "ReleasesLink")) {
        $ctrl[$name] = $dialog.FindName($name)
    }
    # リンクは、アドレスをボタンの Tag に持たせる。開くのは getAboutLinks に載せたアドレスだけ（openAboutLink）
    foreach ($link in @(getAboutLinks)) {
        $button = $ctrl[$link.Id]
        $button.Content = $link.Text
        $button.Tag = $link.Url
        $button.ToolTip = $link.Url
        $button.Add_Click({
            param ($sender, $e)
            safe { openAboutLink $sender.Tag }
        })
    }
    $ctrl.LicenseText.Text = (@(getAboutLicenses) -join "`n")
    # ベクターの絵なので、表示の大きさ・画面の倍率が変わってもぼやけない
    $icon = loadAppIcon
    if ($null -ne $icon) {
        $ctrl.AppIcon.Source = $icon
    }
    $ctrl.VersionText.Text = "バージョン $($script:aboutView.Version)"
    if ($script:aboutView.Commit -eq "") {
        $ctrl.CommitText.Visibility = "Collapsed"
    } else {
        $ctrl.CommitText.Text = "|　コミット $($script:aboutView.Commit)"
    }
    [void](showOwnedDialog $dialog)
}

# 起動時の「前回残った Office の確認」の画面（画面層）。gui_main.ps1 が読み込む。
# 文言・出すかどうか・対象の選び方は判断層（leftover_view.ps1）、プロセスの一覧・終了は shared/office/office_process.ps1。
# ここは、それらをつなぎ、確認のダイアログ（dialog_leftover.xaml）とステータスの文を出すだけ。
# 流れ: 起動時の読み込みの終わりに、記録の読み取り（getOfficeProcesses）を裏の仕事で行う → 出す時機を決める（getLeftoverPromptTiming）→
#       確認 → ［終了する］なら、PID を読み直して確認に出したものだけを選び（getLeftoverTargets）、裏の仕事で終了する → ステータスに結果を出す。
# 止めるのは、起動のときに記録した PID の Office だけ（名前で探して止めない）。画面のスレッドでは記録を読まず、プロセスにも触れない。

$script:leftoverNoticesOpen = $false   # 起動時のお知らせ（メッセージボックス）を開いている間は true。閉じたら resumeLeftoverPrompt で決め直す
$script:leftoverPending = $null        # お知らせが閉じるのを待っている、確認に出す予定の残り物（getOfficeProcesses の要素）
$script:leftoverFakeFile = $env:TEBUNKO_GUI_LEFTOVER_FILE   # 写真・画面のテストの場面から偽の行を差し込むときだけ入る（leftover_view.ps1 の「偽の行」）

function startLeftoverCheck {
    # 起動時の読み込みの終わりに呼ぶ。残った Office の記録を裏で読み、確認を出すか決める
    $mode = getLeftoverSourceMode $script:leftoverFakeFile
    startJob {
        param ($recordDir, $fakeFile)
        if ($fakeFile) {
            $parsed = Get-Content -LiteralPath $fakeFile -Raw -Encoding UTF8 | ConvertFrom-Json
            $rows = @($parsed | ForEach-Object { $_ })   # PowerShell 5.1 の ConvertFrom-Json は配列を 1 つの値で返すため、1 段ほどく
            return @{ Processes = $rows }
        }
        return @{ Processes = @(getOfficeProcesses $recordDir) }
    } @((getOfficePidDir $workspace), $(if ($mode -eq "Fake") { $script:leftoverFakeFile } else { "" })) {
        param ($output, $errorText)
        if ($errorText -or $null -eq $output -or $output.Count -eq 0) {
            if ($errorText) { setStatus (getLeftoverFailureText "Check" $errorText) }
            return
        }
        safe {
            $processes = @($output[0].Processes)
            if ((getLeftoverSourceMode $script:leftoverFakeFile) -eq "Fake") {
                $processes = @(convertLeftoverFakeRows $processes)
            }
            decideLeftoverPrompt $processes
        }
    } (getWorkspaceJobQueue $workspace.Dir)
}

function decideLeftoverPrompt {
    # 残り物を確認に出すか、見送るか、お知らせが閉じるまで待つかを決め、出すときは出す
    param (
        [object[]]$processes
    )

    $prompt = getLeftoverPrompt $processes
    $script:leftoverPending = $null
    if ($null -eq $prompt) {
        return
    }
    $closing = [bool]$script:closeWaiting -or [bool]$script:closeReady
    $timing = getLeftoverPromptTiming $prompt.Count $closing (isIndexing) $script:leftoverNoticesOpen @($window.OwnedWindows).Count
    if ($timing -eq "Defer") {
        $script:leftoverPending = $processes
        return
    }
    if ($timing -ne "Show") {
        return
    }
    $answer = showLeftoverDialog $prompt
    if ($answer -ne "stop") {
        return
    }
    stopLeftoverProcesses $prompt
}

function resumeLeftoverPrompt {
    # 起動時のお知らせが閉じたあとに、待っていた確認をもう一度決める
    $pending = $script:leftoverPending
    if ($null -ne $pending) {
        decideLeftoverPrompt $pending
    }
}

function showLeftoverDialog {
    # 確認のダイアログを出す。［終了する］を選べば "stop"、それ以外（今回は終了しない・閉じる）は $null
    param (
        $prompt
    )

    $dialog = loadWindow "${xamlDir}\dialog_leftover.xaml"
    $dialog.Owner = $window
    $dialog.Title = $prompt.Title
    $ctrl = @{}
    foreach ($name in @("HeadingText", "FactsList", "DetailToggleButton", "DetailBox", "DetailList", "HintText", "LeftoverCancelButton", "LeftoverStopButton")) {
        $ctrl[$name] = $dialog.FindName($name)
    }
    $ctrl.HeadingText.Text = $prompt.Heading
    $ctrl.FactsList.ItemsSource = @($prompt.Facts | ForEach-Object { factKept $_.Title $_.Detail })
    $ctrl.DetailList.ItemsSource = @($prompt.Details | ForEach-Object { [pscustomobject]$_ })
    $ctrl.HintText.Text = $prompt.Hint
    $ctrl.LeftoverCancelButton.Content = $prompt.CancelText
    $ctrl.LeftoverStopButton.Content = @($prompt.Choices)[0].Text
    $ctrl.DetailToggleButton.Content = getLeftoverDetailToggleText $false
    $chosen = @{ Value = $null }
    # GetNewClosure() したハンドラは、呼び出しが入れ子だと関数を名前で解決できないため、実体を変数に取り込んで & で呼ぶ
    $getToggleText = ${function:getLeftoverDetailToggleText}
    $ctrl.LeftoverStopButton.Add_Click({
        $chosen.Value = "stop"
        $dialog.DialogResult = $true
    }.GetNewClosure())
    # マウス・キーボードでも UI オートメーションの Toggle でも IsChecked が変わるので、Click ではなく Checked / Unchecked で受ける
    $applyToggle = {
        $open = [bool]$ctrl.DetailToggleButton.IsChecked
        $ctrl.DetailBox.Visibility = $(if ($open) { "Visible" } else { "Collapsed" })
        $ctrl.DetailToggleButton.Content = & $getToggleText $open
    }.GetNewClosure()
    $ctrl.DetailToggleButton.Add_Checked($applyToggle)
    $ctrl.DetailToggleButton.Add_Unchecked($applyToggle)
    # うっかり Enter で終了しないよう、既定は［今回は終了しない］
    $dialog.Add_ContentRendered({ $ctrl.LeftoverCancelButton.Focus() | Out-Null }.GetNewClosure())
    $null = showOwnedDialog $dialog
    return $chosen.Value
}

function stopLeftoverProcesses {
    # ［終了する］のあと。PID を読み直し、確認に出したものだけを終了して、結果をステータスに出す
    param (
        $prompt
    )

    $script:leftoverPrompt = $prompt
    if ((getLeftoverSourceMode $script:leftoverFakeFile) -eq "Fake") {
        # 偽の行は、結果を作るだけ（プロセスには触れない）
        $targets = @(getLeftoverTargets @($prompt.Targets | ForEach-Object { $_.Id }) @($prompt.Targets))
        finishLeftoverStop (getLeftoverFakeStopResults $targets)
        return
    }
    startJob {
        param ($recordDir)
        return @{ Processes = @(getOfficeProcesses $recordDir) }
    } @((getOfficePidDir $workspace)) {
        param ($output, $errorText)
        if ($errorText -or $null -eq $output -or $output.Count -eq 0) {
            if ($errorText) { setStatus (getLeftoverFailureText "Stop" $errorText) }
            return
        }
        safe {
            $shown = @($script:leftoverPrompt.Targets | ForEach-Object { $_.Id })
            $targets = @(getLeftoverTargets $shown @($output[0].Processes))
            if ($targets.Count -eq 0) {
                return
            }
            startJob {
                param ($targets, $recordDir)
                return @{ Results = @(stopOfficeProcesses $targets $recordDir) }
            } @($targets, (getOfficePidDir $workspace)) {
                param ($output, $errorText)
                if ($errorText -or $null -eq $output -or $output.Count -eq 0) {
                    if ($errorText) { setStatus (getLeftoverFailureText "Stop" $errorText) }
                    return
                }
                safe { finishLeftoverStop @($output[0].Results) }
            } (getWorkspaceJobQueue $workspace.Dir)
        }
    } (getWorkspaceJobQueue $workspace.Dir)
}

function finishLeftoverStop {
    # 終了の結果をステータスに出す（言うことが無ければ変えない）
    param (
        [object[]]$results
    )

    $text = getLeftoverResultText $results
    if ($null -ne $text) {
        setStatus $text
    }
}

    stepSplash 90

    # ナビと画面の切り替え（selectScreen・getCurrentScreen）。$script:startupLoaded を決めた後に読み込む
# ナビ（左の欄）と画面の切り替え（画面層）。gui_main.ps1 が読み込む。
# 画面は、ナビの項目（SearchTab・IndexTab・SettingsTab）の名前で呼ぶ。ナビのクリック・キー操作・ほかの画面からの切り替えは、
# すべて selectScreen を通す（ナビの部品から直に中身を差し替えない）。
# 画面の中身は起動のときに読み込んで $script:screenContents に持ち、選んだものを ContentHost に差す。

$script:currentScreen = $null

function getCurrentScreen {
    # いま出している画面の名前（まだ選んでいなければ $null）
    return $script:currentScreen
}

function selectScreen {
    param (
        [string]$name
    )

    if (!(isScreenName $name) -or $script:currentScreen -eq $name) {
        return
    }
    $script:currentScreen = $name
    $ui.ContentHost.Content = $script:screenContents[$name]
    $ui.ContentHost.Margin = getScreenMargin $name
    # 左の欄の検索対象のツリーは、検索の画面のときだけ出す
    $ui.NavPaneHost.Visibility = if ($name -eq "SearchTab") { "Visible" } else { "Collapsed" }
    # 登録のフォルダ数・ファイルの合計は、インデックス管理の画面のときだけ、窓の下のステータスバーに出す
    $ui.IndexFooterFolders.Visibility = if ($name -eq "IndexTab") { "Visible" } else { "Collapsed" }
    $ui.IndexFooterFiles.Visibility = $ui.IndexFooterFolders.Visibility
    if ($ui.NavList.SelectedItem -ne $ui[$name]) {
        $ui.NavList.SelectedItem = $ui[$name]
    }
    # 起動時の読み込み（loadStartupData）が済むまでは、切り替えたときの読み直しをしない
    # （起動時の画面を選んだときにも呼ばれ、同じ読み込みが重なるため）
    if (!$script:startupLoaded) {
        return
    }
    safe {
        if ($name -eq "IndexTab") {
            refreshIndexingState
        }
    }
}

# キー操作の振り分け（getShortcutAction が決めた動作を実行する）。キーを受けたら $true（呼び出し側が Handled にする）、
# 何もしなければ $false を返す。窓の PreviewKeyDown から呼ぶ
function invokeShortcutAction {
    param (
        $action
    )

    switch ($action.Action) {
        "FocusSearchWord" {
            selectScreen $action.Screen
            # 切り替えた直後は、検索の画面がまだ表示の木に入っていないことがあるため、配置を済ませてからフォーカスする
            $ui.ContentHost.UpdateLayout()
            $ui.WordBox.Focus() | Out-Null
            $ui.WordBox.SelectAll()
            return $true
        }
        "FocusFilter" {
            selectScreen $action.Screen
            $ui.ContentHost.UpdateLayout()
            $ui.FilterBox.Focus() | Out-Null
            return $true
        }
        "SwitchScreen" {
            # Ctrl+Tab・Ctrl+Shift+Tab: ナビの項目を順に切り替える
            selectScreen $action.Screen
            return $true
        }
        "Refresh" {
            if (!(testIndexReadAllowed ([bool]$script:workspaceMoving))) {
                return $true
            }
            safe {
                refreshIndexingState
                refreshIndexSummary
                loadIndexTree
            }
            return $true
        }
        "CancelSearch" {
            # 検索中だけ止める（検索中でなければキーを渡す）
            if ($script:search) {
                cancelSearch
                return $true
            }
        }
    }
    return $false
}

$ui.NavList.Add_SelectionChanged({
    param ($sender, $e)
    # 中の項目の選択変更だけを扱う
    $item = $sender.SelectedItem
    if ($null -ne $item) {
        selectScreen $item.Name
    }
})

# ステータスバーの 1 行（画面層）。gui_main.ps1 が読み込む。
# 更新中だけ、左に「更新中: <インデックス名>　205 / 455 件（失敗 1 件）・残り約 3 分」を出し、いつもの文（StatusText）は隠す。
# 件数は更新全体の進み（getIndexingProgress）、残り時間は［インデックス管理］の進み表示と同じ値（$script:indexingView）を読む。
# 何をいつ出すかは判断層（getStatusBarView・getIndexingStatusLine）。文が長くて切れたときは、切れているときだけツールチップで全文を見せる。

addTrimmedToolTip $ui.StatusText
addTrimmedToolTip $ui.IndexingStatusText

function updateIndexingStatusLine {
    $line = ""
    if (isIndexing) {
        # 名前・件数・残り時間は、更新の進みの更新が値で持つ $script:indexingView から読む（最初の進みが来るまでは名前・残り時間なし）
        $view = $script:indexingView
        if ($null -eq $view) {
            $progress = getIndexingProgress
            $view = @{ Name = ""; Processed = $progress.Processed; Total = $progress.Processed + $progress.Remaining; Failed = $progress.Failed; Eta = "" }
        }
        $line = getIndexingStatusLine ([string]$view.Name) $view.Processed $view.Total $view.Failed ([string]$view.Eta)
    }
    $statusView = getStatusBarView (isIndexing) $line ([string]$ui.StatusText.Text)
    if ($statusView.Source -ne "Indexing") {
        $ui.IndexingStatusText.Visibility = "Collapsed"
        $ui.StatusText.Visibility = "Visible"
        return
    }
    $ui.IndexingStatusText.Text = $statusView.Text
    $ui.IndexingStatusText.Visibility = "Visible"
    $ui.StatusText.Visibility = "Hidden"
}

$script:statusLineTimer = newTimer 1000 { safe { updateIndexingStatusLine } }
$script:statusLineTimer.Start()

# 画面の上の知らせの帯（画面層）。gui_main.ps1 が読み込む。
# 検索の画面の上（SearchNotice。結果を保存できなかったとき）・インデックス管理の画面の上（IndexNotice。1 件・まとめての削除と、まとめてのエクスポートの失敗）・
# 窓の上（WorkspaceNotice。ワークスペースが使えないとき）の 3 つ。どれも同じ作りで、部品の名前は <接頭辞>Panel・Icon・Text・Button・Close。
# 文言と色の区分・閉じられるか・ボタンは判断層（getNoticeBannerView）が決め、ここは結果を画面に当てるだけ。

function showNoticeBanner {
    # 帯を出す（message が空なら閉じる）。kind は getNoticeBannerView の種類
    param (
        [string]$prefix,
        [string]$kind,
        [string]$message
    )

    $view = getNoticeBannerView $kind $message
    $panel = $ui["${prefix}Panel"]
    if (!$view.Show) {
        $panel.Visibility = "Collapsed"
        return
    }
    # 地・左端の線・文字・アイコンの色（warn は橙、ng は赤。更新の帯 setIndexingBanner と同じ色）
    $looks = @{
        warn = @("Warn.Soft", "Warn", "Banner.Warn.Text")
        ng = @("Danger.Soft", "Danger.Text", "Banner.Ng.Text")
    }
    $look = $looks[$view.Level]
    $line = themeBrush $look[1]
    $text = themeBrush $look[2]
    $panel.Background = themeBrush $look[0]
    $panel.BorderBrush = $line
    $ui["${prefix}Icon"].Stroke = $line
    $ui["${prefix}Text"].Foreground = $text
    $ui["${prefix}Text"].Text = $view.Text
    $ui["${prefix}Text"].ToolTip = $view.ToolTip
    $ui["${prefix}Close"].Foreground = $text
    $ui["${prefix}Close"].Visibility = if ($view.Closable) { "Visible" } else { "Collapsed" }
    $button = $ui["${prefix}Button"]
    $button.Content = $view.ActionText
    $button.BorderBrush = $line
    $button.Foreground = $line
    $button.Visibility = if ($view.ActionText) { "Visible" } else { "Collapsed" }
    $panel.Visibility = "Visible"
}

function hideNoticeBanner {
    param ([string]$prefix)

    $ui["${prefix}Panel"].Visibility = "Collapsed"
}

function updateWorkspaceBanner {
    # ワークスペースが使えないとき（既定の場所にほかのファイルがある）は窓の上に赤い帯を出し、使えるようになれば消す。
    # 起動時と、ワークスペースを切り替えたときに呼ぶ
    showNoticeBanner "WorkspaceNotice" "WorkspaceBlock" ([string]$script:workspaceBlock)
}

$ui.SearchNoticeClose.Add_Click({ safe { hideNoticeBanner "SearchNotice" } })
$ui.IndexNoticeClose.Add_Click({ safe { hideNoticeBanner "IndexNotice" } })
$ui.WorkspaceNoticeButton.Add_Click({ safe { selectScreen "SettingsTab" } })



    # ウィンドウ全体: イベント・閉じるときの処理・起動時の読み込みとタブ選び・前面化の見張り
# startGui の一部: ウィンドウのイベント（Activated・PreviewKeyDown・Loaded・ContentRendered）。startGui の中で読み込む。

    function onWindowActivated {
        if (!$script:startupLoaded) {
            return
        }
        if (!(testIndexReadAllowed ([bool]$script:workspaceMoving))) {
            return
        }
        safe {
            # クロール対象フォルダがほかの画面で変更されていれば読み直す
            if ((getTargetsKey @(getTargetFolders)) -ne $script:savedTargets) {
                loadTargets
                setStatus "インデックス一覧がほかで変更されたため、読み直しました"
            }
            # フォルダの有無は別スレッドで調べる（届かないネットワークのフォルダで画面が固まらないように）
            refreshFolderStatus
            if (!(isIndexing)) {
                refreshIndexingState
                if (shouldRefreshFastSearchStatus) {
                    refreshFastSearchStatus
                }
            }
            updateSearchTarget
        }
    }

    $window.Add_Activated({ onWindowActivated })

    function onWindowPreviewKeyDown {
        # 窓のキー（Ctrl+Tab・F5・Ctrl+F など）の入口。modifiers は押されている修飾キー（テストでは差し替える）
        param (
            $sender,
            $e,
            $modifiers = [System.Windows.Input.Keyboard]::Modifiers
        )

        $ctrl = ($modifiers -band [System.Windows.Input.ModifierKeys]::Control) -ne 0
        $shift = ($modifiers -band [System.Windows.Input.ModifierKeys]::Shift) -ne 0
        # Alt などが混ざったキーは、これまでどおり扱わない
        $others = $modifiers -band (-bnot ([System.Windows.Input.ModifierKeys]::Control -bor [System.Windows.Input.ModifierKeys]::Shift))
        if ($others -ne 0) { return }
        if (!(testMainContentOperable ([bool]$script:workspaceMoving))) {
            # ワークスペースの中身を移している間は、窓のキー（Ctrl+Tab・F5・Ctrl+F など）を受けない
            $e.Handled = $true
            return
        }
        $action = getShortcutAction ([string]$e.Key) $ctrl $shift (getCurrentScreen)
        if (invokeShortcutAction $action) {
            $e.Handled = $true
        }
    }

    $window.Add_PreviewKeyDown({
        param ($sender, $e)
        onWindowPreviewKeyDown $sender $e
    })

    $window.Add_Loaded({
        safe {
            if ((getCurrentScreen) -eq "SearchTab") {
                $ui.WordBox.Focus() | Out-Null
            }
            # 起動時のお知らせを開いている間は、前回残った Office の確認を出さず、閉じたあとに出す（leftover_dialog.ps1）
            $script:leftoverNoticesOpen = $true
            try {
                if ($script:settingsRecovery) {
                    closeSplash
                    showMessage (getSettingsRecoveryMessage $script:settingsRecovery) "OK" "Warning" | Out-Null
                }
                if ($script:workspaceBlock) {
                    # 知らせを読む間、起動中の表示が裏に残らないように先に閉じる
                    closeSplash
                    showMessage $script:workspaceBlock "OK" "Warning" | Out-Null
                }
            } finally {
                $script:leftoverNoticesOpen = $false
            }
            resumeLeftoverPrompt
        }
    })

    # 画面を描き終わったら、起動中の表示を閉じ、一覧の読み込みと別スレッドでの集計を始める。
    # ウィンドウを出す前に行うと、そのぶん画面が出るのが遅れるため（一覧は読み込むまで空で出る）
    $window.Add_ContentRendered({
        closeSplash
        # 描いた画面が映ってから読み込むよう、描画より優先度の低い Background で行う
        $window.Dispatcher.BeginInvoke([action]{ safe { loadStartupData } }, [System.Windows.Threading.DispatcherPriority]::Background) | Out-Null
    })

# startGui の一部: 閉じるときの処理（closeTimer・enterIndexingStopFlow・Closing）。startGui の中で読み込む。

    # 閉じるときの順番（docs/design/structure/closing.md「閉じるときの順番」）。インデックス作成は画面のプロセスのスレッドで動くため、
    # 止めてから閉じる。止め終わるまで閉じるのを保留し、closeTimer が終わりを待ってから閉じ直す
    $script:closeWaiting = $false   # インデックス作成が止まるのを待っている
    $script:closeDeadline = $null   # これを過ぎたら、インデックス作成が起動した Office を止める
    $script:closeKilled = $false    # Office を止めた
    $script:closeReady = $false     # 待ち終えた（もう聞かずに閉じる）
    $script:closeAskedDuringIndexJob = $false   # インデックスの削除・名前の変更の途中で閉じようとして、終わるのを待った
    $script:closeAfterIndexJob = $false         # 終わったら閉じる（待たずに閉じると決めたら戻す）
    $script:closeConfirming = $false            # 待たずに閉じるかの確認を出している間（この間は仕事が終わっても閉じず、確認から戻ったときに閉じる）
    ${closeWaitSeconds} = 60        # インデックス作成が止まるのを待つ時間。過ぎたら Office を止めて、さらに closeKillWaitSeconds 待つ
    ${closeKillWaitSeconds} = 15

    $script:closeTimer = newTimer 500 {
        safe {
            $now = Get-Date
            $indexing = isIndexing
            if ($indexing) {
                # 待つ間のダイアログの棒と、強制終了までの秒読みを書き換える
                try { updateIndexingWait (getIndexingProgress) ($script:closeDeadline - $now).TotalSeconds } catch { }
            }
            if (!$indexing) {
                $script:closeTimer.Stop()
                $script:closeReady = $true
                try { closeIndexingWait } catch { }   # 待つ間のダイアログ → 暗幕 → 本体の窓の順に閉じる（失敗しても本体は閉じる）
                $window.Close()
            } elseif (!$script:closeKilled -and $now -gt $script:closeDeadline) {
                # 取り込み中の Office が応答しない。インデックス作成が起動した Office だけを PID で止める（COM の呼び出しが戻る）
                $script:closeKilled = $true
                [void]$script:indexingSession.KillOffice()
                $script:closeDeadline = $now.AddSeconds(${closeKillWaitSeconds})
            } elseif ($script:closeKilled -and $now -gt $script:closeDeadline) {
                # それでも止まらない。スレッドは finally で止める
                $script:closeTimer.Stop()
                $script:closeReady = $true
                try { closeIndexingWait } catch { }
                $window.Close()
            }
        }
    }

    function enterIndexingStopFlow {
        # ふだんの「インデックス作成を止めてから閉じる」流れに入る（すでに入っていれば、足りない手順だけ補う）。
        # 1 つずつ try で包み、失敗しても残りを進める（finally の IndexingSession.Close の打ち切りに頼らず、
        # 取り込み中のファイルの区切りで止めるため）。closeDeadline は $null のときだけ決め、
        # 途中の失敗で入り直しても延ばし直さない。closeTimer も動いていなければ動かす（M1: ここが抜けていると、
        # 流れの途中の失敗のあとに closeTimer が動かず、外から止める以外に閉じられなくなる）
        $script:closeWaiting = $true
        try { $script:indexingTimer.Stop() } catch { }
        try { $script:indexingSession.Stop() } catch { }
        try { $ui.IndexingStopButton.IsEnabled = $false } catch { }
        try { $ui.IndexingProgressText.Text = "更新を止めています…" } catch { }
        try { $ui.IndexingProgressDetail.Text = "読み取り中のファイルが終わると、画面を閉じます。" } catch { }
        try { setStatus "更新を止めてから閉じます…" } catch { }
        try {
            if ($null -eq $script:closeDeadline) {
                $script:closeDeadline = (Get-Date).AddSeconds(${closeWaitSeconds})
            }
            if (!$script:closeTimer.IsEnabled) {
                $script:closeTimer.Start()
            }
        } catch { }
        # 待つ間のダイアログは、失敗しても止める流れの邪魔にしない
        try {
            showIndexingWait "CloseWait"
            updateIndexingWait (getIndexingProgress) ($script:closeDeadline - (Get-Date)).TotalSeconds
        } catch { }
    }

    $window.Add_Closing({
        param ($sender, $e)
        if ($script:closeReady) {
            return
        }
        if ($script:closeWaiting) {
            # 止まるのを待っている間に、もう一度閉じようとした
            $e.Cancel = $true
            return
        }
        try {
            # インデックスの削除・名前の変更の途中で閉じると、設定とインデックスのフォルダの名前が食い違う。終わるまで待って閉じる
            $indexJobClose = getIndexJobCloseAction ([bool]$script:indexBusy) ([bool]$script:closeAskedDuringIndexJob) ([bool]$script:workspaceMoving)
            if ($indexJobClose -eq "waitMove") {
                # ワークスペースを移している途中で閉じると、中身が移動元と移動先に分かれる。止めずに、移し終わってから閉じる
                # （終わりの処理 finishWorkspaceMove が閉じる）。待つ間のダイアログの文だけ「終わったら閉じます」に変える
                $script:closeAfterWorkspaceMove = $true
                $e.Cancel = $true
                # 表示の失敗で、閉じるのを止めたことを取り消さない（catch が Cancel を戻すため、ここで握る）
                try { setStatus (getWorkspaceMoveClosingStatus) } catch { }
                try { updateWaitDialog $script:indexingWait @{ Description = (getWaitDialogView "MovingClose").Description } } catch { }
                return
            }
            if ($indexJobClose -eq "wait") {
                $script:closeAskedDuringIndexJob = $true
                $script:closeAfterIndexJob = $true
                $e.Cancel = $true
                setStatus (getIndexJobClosingStatus)
                return
            }
            if ($indexJobClose -eq "confirm") {
                # 待っている間にもう一度閉じようとした。ステータスの 1 行は他の表示で消えて見落とされるため、確かめてから閉じる。
                # 確認はこのハンドラの中のモーダル。その間に仕事が終わっても、ここで閉じずに（閉じ途中の窓に Close を呼ばないよう）、戻ってから決める
                $e.Cancel = $true
                $confirm = getIndexJobCloseConfirm
                $script:closeConfirming = $true
                try {
                    $answer = showConfirm `
                        -title $confirm.Title `
                        -heading $confirm.Heading `
                        -hint $confirm.Hint `
                        -choices @(@{ Text = $confirm.CloseText; Value = $confirm.CloseValue; Danger = $true }) `
                        -cancelText $confirm.CancelText
                } finally {
                    $script:closeConfirming = $false
                }
                if ((getIndexJobCloseAfterConfirm ([string]$answer) ([bool]$script:indexBusy)) -eq "close") {
                    $script:closeAfterIndexJob = $false
                    $script:closeReady = $true
                    $window.Dispatcher.BeginInvoke([action]{ $window.Close() }) | Out-Null
                }
                return
            }
            $script:closeAfterIndexJob = $false
            # インデックス作成は画面のプロセスで動いているため、画面を閉じるときは止める
            if (isIndexing) {
                $answer = showConfirm `
                    -title "更新中です" `
                    -heading "インデックスを更新中です。中止して閉じますか？" `
                    -hint "更新したところまでは残ります。次に起動したときに続きから再開できます。" `
                    -choices @(@{ Text = "中止して閉じる"; Value = "stop"; Careful = $true }) `
                    -cancelText "閉じない"
                $e.Cancel = $true
                if ($answer -ne "stop" -or !(isIndexing)) {
                    if ($answer -eq "stop") {
                        # 聞いている間に終わった
                        $script:closeReady = $true
                        $window.Dispatcher.BeginInvoke([action]{ $window.Close() }) | Out-Null
                    }
                    return
                }
                enterIndexingStopFlow
                return
            }
            if ($script:search) {
                cancelSearch
            }
        } catch {
            # 知らせる処理自体が失敗しても、閉じ方の分岐へは必ず進む（R1）
            try { reportUnexpectedError "画面を閉じる途中" $_ } catch { }
            $stillIndexing = $true
            try {
                $stillIndexing = isIndexing
            } catch {
                # isIndexing 自体が失敗したときは、安全な側（止める流れ）に倒す
                $stillIndexing = $true
            }
            if (!$stillIndexing -and !$script:closeWaiting) {
                # インデックス作成中でなく、まだ止める流れにも入っていなければ、閉じるのを止めない
                $e.Cancel = $false
                return
            }
            # 確認のダイアログは出し直さない。すでに流れの途中（closeWaiting が立っている）で
            # 失敗したときも、抜けている手順（closeTimer が動いていないなど）を補う
            $e.Cancel = $true
            enterIndexingStopFlow
        }
    })

# startGui の一部: 起動時の読み込み（loadWorkspaceViews・loadStartupData）と、起動時のタブ選びなど。startGui の中で読み込む。

    function loadWorkspaceViews {
        # ワークスペースの中身（インデックスの一覧・取り込みの状態・検索対象のツリー・件数）を画面に読み込む。
        # 起動したとき（loadStartupData）と、設定の画面でワークスペースを変えたとき（settings\settings.ps1 の switchWorkspace）に呼ぶ
        loadTargets
        refreshIndexingState
        loadIndexTree
        # 検索対象のツリーを読み込んだので、［検索］の可否を決め直す
        updateSearchButton
        checkFastSearchAvailable
        refreshIndexSummary
    }

    function ensureNetworkDriveCache {
        # インデックスの一覧・設定にネットワークのパスがあるときだけ、ドライブの割り当て（CIM）をネットワークを調べる列で
        # 1 回照会し、画面のスレッドのキャッシュに入れる（画面のスレッドで CIM を照会しないようにする。方針 5）。
        # ローカルだけの利用者には、列も CIM の照会も増えない
        $paths = @($script:targetItems | ForEach-Object { [string]$_.Path }) + @(readIndexSources | ForEach-Object { [string]$_.Path })
        if ((getWorkspaceJobQueue $paths) -ne "network") {
            return
        }
        startJob {
            getDriveTargets
        } @() {
            param ($output, $errorText)
            if (!$errorText -and $output -and $output.Count -gt 0) {
                setDriveTargets $output[0]
            }
        } (getWorkspaceJobQueue $paths)
    }

    function loadStartupData {
        try {
            loadWorkspaceViews
            # 前の版のインデックス（index\）が見つかれば、その知らせを覚える（ネットワークの場所は裏で調べ、分かったらステータスに出す）
            refreshLegacyIndexMessage
            ensureNetworkDriveCache
        } finally {
            $script:startupLoaded = $true
        }
        # 起動時に出した知らせ（既定のワークスペースが使えない・前の版のインデックスがある）は、読み込みが終わっても消さない
        setStatus $(if ($script:workspaceBlock) { $script:workspaceBlock } elseif ($script:legacyIndexMessage) { $script:legacyIndexMessage } else { "" })
        # 前回のインデックス作成が起動したまま残った Office があれば、終了するか確認する（記録の読み取りは裏で行う）
        startLeftoverCheck
        # ［新規で開く］のために作ったコピー（open_copy）のうち、1 日より古いものを裏で片付ける（起動時の 1 回だけ。開いているコピーは残る）
        startJob {
            param ($copyDir, $tmpRoot)
            [void](clearOldOpenCopies $copyDir $tmpRoot)
        } @((getOpenCopyDir $workspace), $workspace.TmpRoot) {
            param ($output, $errorText)
        } (getWorkspaceJobQueue @($workspace.Dir, (getOpenCopyDir $workspace)))
    }

    # ---- 起動 ----

    # 版・コミットの表示は起動時に 1 回だけ組み立てる（VERSION.txt は配布物にだけあり、開発中は無いので「開発版」になる）
    $versionInfo = readVersionFile (Join-Path ${rootDir} "VERSION.txt")
    $script:aboutView = getAboutView $versionInfo
    if ($null -eq $versionInfo) {
        # 開発版は、.git のファイルから分かるタグ・コミットを添える。ファイルを読むので、裏で調べて、分かったら表示を差し替える
        startJob {
            param ($toolDir)
            readDevVersion $toolDir
        } @(${rootDir}) {
            param ($output, $errorText)
            if (!$errorText -and $null -ne $output -and @($output).Count -gt 0 -and $null -ne $output[0]) {
                $script:aboutView = getAboutView $null $output[0]
            }
        }
    }

    updateSettingsView
    setSearchOptionToUi (readSearchOption)
    setOpenMode (readOpenMode)
    # 検索ワードの注意と［検索］の可否（検索ワードが空なので押せない）。画面を出したときに押せる色で出ないよう、先に決める
    updateWordNotice
    # 一覧を読み込むまで（loadStartupData）は、「インデックスがありません」の案内を出さない
    $ui.IndexGridPlaceholder.Visibility = "Collapsed"

    # 起動時の画面：インデックス作成が中断中、またはインデックスが無ければ［インデックス管理］、それ以外は［検索］
    # （ネットワークのワークスペースは、画面のスレッドで調べず、［検索］を開く）
    $openIndexTab = ($script:indexingState -and $script:indexingState.Pending -gt 0) -or !(testStartupIndexExists $workspace.Dir)
    selectScreen $(if ($openIndexTab) { "IndexTab" } else { "SearchTab" })
    # 既定のワークスペースにほかのファイルが置いてあれば、［設定］を開いて別のフォルダを選んでもらう（画面を出した後に知らせる）
    $script:workspaceBlock = getWorkspaceBlockMessage
    updateWorkspaceBanner
    if ($script:workspaceBlock) {
        selectScreen "SettingsTab"
    }
    setStatus "読み込んでいます…"
    stepSplash 95

# startGui の一部: 多重起動した 2 つ目の合図で、この画面を前面に出す見張り（activateTimer）。startGui の中で読み込む。

    # 多重起動したとき（2つ目のプロセスが $activateEvent を合図）に、この画面を前面へ出す。
    # 画面のスレッドで一定間隔にイベントを確認する（P/Invoke を使わず、WPF の Activate で前面化する）。
    # ※以前は C# の SingleInstance（AttachThreadInput 等の P/Invoke）で行っていたが、
    #   実行時コンパイル（csc.exe）を無くすため、DispatcherTimer＋Window.Activate に置き換えた。
    $activateTimer = New-Object System.Windows.Threading.DispatcherTimer
    $activateTimer.Interval = [TimeSpan]::FromMilliseconds(300)
    $activateTimer.Add_Tick({
        if ($activateEvent.WaitOne(0)) {
            if ($window.WindowState -eq [System.Windows.WindowState]::Minimized) {
                $window.WindowState = [System.Windows.WindowState]::Normal
            }
            [void]$window.Activate()
            # ほかのプロセスが前面のときは Activate が無視されることがあるため、最前面を一瞬立ててから戻す
            $window.Topmost = $true
            $window.Topmost = $false
        }
    })
    $activateTimer.Start()


    try {
        [void]$window.ShowDialog()
    } finally {
        # インデックス作成のスレッド、検索の司令のスレッドと照合のプール、画面の裏の仕事のスレッドを片づける
        # （docs/design/structure/closing.md「閉じるときの順番」）。片づける順番はそのまま変えない。
        # 画面の裏の仕事（$script:backgroundQueue・$script:networkQueue）だけ、止まった仕事（届かない共有の
        # Test-Path など、OS の呼び出しで戻らないもの）を待たずに戻る Abandon（前は Close）を使う
        $script:closeTimer.Stop()
        $script:indexingTimer.Stop()
        try { closeIndexingWait } catch { }
        if ($script:indexingSession) {
            $script:indexingSession.Close()
        }
        $script:searchService.Close()
        $script:jobTimer.Stop()
        $script:backgroundQueue.Abandon()
        if ($script:networkQueue) {
            $script:networkQueue.Abandon()
        }
        $activateTimer.Stop()
        $activateEvent.Close()
        $mutex.ReleaseMutex()
        $mutex.Dispose()
    }
    # 画面のスレッドの Dispatcher を止める。止めずに戻ると、PowerShell が終わるときの片づけで、まれに終了コード 5 で終わることがある
    # （docs/design/structure/closing.md「閉じるときの順番」）。例外で抜けるときは通らない
    # （起動の失敗を知らせる画面（reportStartupFailure）が、この Dispatcher を使うため）
    [System.Windows.Threading.Dispatcher]::CurrentDispatcher.InvokeShutdown()
}

    startGui -TebunkoDir ${tebunkoRoot}
} catch {
    exit (reportStartupFailure $_)
}
'@
${tebunkoSource} = ${tebunkoBody}
if (${tebunkoProbe}.Trim() -ne [string][char]0x30A2) {
    # Read with a wrong code page: read this file again as UTF-8 and take the body out of it.
    if (!${tebunkoPath}) {
        throw 'tebunko: cannot read this script as UTF-8 (no file path). Run it from a file saved as UTF-8.'
    }
    ${tebunkoRaw} = [System.IO.File]::ReadAllText(${tebunkoPath}, (New-Object System.Text.UTF8Encoding($false)))
    ${tebunkoMatch} = [regex]::Match(${tebunkoRaw}, '(?s)\$\{tebunkoBody\} = @''\r?\n(.*?)\r?\n''@')
    ${tebunkoProbeMatch} = [regex]::Match(${tebunkoRaw}, '(?s)\$\{tebunkoProbe\} = @''\r?\n(.*?)\r?\n''@')
    if (!${tebunkoMatch}.Success -or !${tebunkoProbeMatch}.Success -or ${tebunkoProbeMatch}.Groups[1].Value.Trim() -ne [string][char]0x30A2) {
        throw 'tebunko: cannot read this script as UTF-8. Save it as UTF-8 (with BOM) and run it again.'
    }
    ${tebunkoSource} = ${tebunkoMatch}.Groups[1].Value
}
${tebunkoSource} = [regex]::Replace(${tebunkoSource}, '(?m)^@@''@', '''@')
${tebunkoSource} = ("`r`n" * 19) + ${tebunkoSource}
. ([scriptblock]::Create(${tebunkoSource})) @PSBoundParameters
